#define MAX_PART_ATTEMPTS 600  /* scelte di parti provate in tutto per un'affermazione (28k) */
#define MAX_WITNESSES 8      /* testimoni di un'equipotenza provati, dal più corto, uno per tentativo (28q) */
#define MAX_BIJ 512          /* termini della grammatica dei testimoni costruiti per un'equipotenza (28q) */
#define MAX_BRANCHES 16      /* rami uno dentro l'altro: casi, scelte di parti e prove (28k, 28l) */
#define MAX_PROBES 8         /* disgiunzioni provate per trovarne una con un caso che si chiude subito (28l) */
#define MAX_CONGRUENCES 32   /* condizioni "m divide P" in un enunciato deciso sui resti (18r) */
#define MAX_PERIOD 100000    /* il multiplo comune dei moduli, al più */
#define MAX_RESIDUE_CASES 200000  /* assegnazioni di resti provate per un enunciato */
#define MAX_CLASSES 16       /* classi di resto elencate in un insieme di soluzioni */
#define MAX_QPOLY 24         /* grado massimo dei polinomi di una funzione razionale da integrare (30d) */
#define MAX_PRIMITIVE_DEPTH 4  /* metodi uno dentro l'altro nella ricerca di una primitiva (30c) */
#define MAX_PRIMITIVE_CALLS 600  /* chiamate alla ricerca di una primitiva, per un enunciato (30c) */
#define MAX_INNER 24         /* funzioni interne provate come nuova variabile (30g) */
#define MAX_EXP_TERMS 160    /* termini x^m e^{(a + i b) x} di una primitiva (30e) */
#define ANSWER_BYTES 4096    /* lunghezza di una primitiva o di un valore scritti */
#define RIEMANN_PIECES 256   /* intervalli in cui si divide [a, b] all'inizio (30i) */
#define RIEMANN_SPLITS 10    /* dimezzamenti di un intervallo in cui il calcolo non riesce (30i) */
#define MAX_PIECES 8         /* parti in cui un valore assoluto divide un integrale definito (30i-2) */

/* Valore di Token.ch per le graffe scritte \{ e \} e per l'a capo \\: 256 più
 * il carattere, per distinguerle dalle graffe di raggruppamento di LaTeX. */
#define ESCAPED 256
#define MAX_PARTS 24         /* fattori distinti nella scomposizione di un polinomio */
#define MAX_UNIVARIATE 16    /* grado massimo di un polinomio in n da scomporre */
#define MAX_DIVISORS 2048    /* divisori di un intero provati come radici razionali */

/* Nomi interni di variabili, fuori dall'intervallo dei caratteri: \pi, e una
 * lettera ausiliaria che vale zero o più (vedi body_is_positive()). */
#define VAR_PI 256
#define VAR_SLACK 257
#define VAR_ITERATE 258  /* il valore corrente mentre si calcola un'iterata f^{m}(a) con i numeri (17s) */

/* Nomi interni dei termini precedenti di una successione dichiarata
 * dall'enunciato, mentre la sua regola viene calcolata con i numeri
 * (capitolo 26): VAR_TERM, VAR_TERM + 1, ..., fino a MAX_ORDER. */
#define VAR_TERM 300

/* I razionali tengono numeratore e denominatore sotto 2^62, così il prodotto
 * di due di essi e la somma di due prodotti stanno sempre in un __int128. */
#define COEF_LIMIT ((__int128)1 << 62)

/* =============================================================================
 * 2. ERRORI E MEMORIA
 * ============================================================================
 *
 * Errori. Un conto può uscire dai limiti in molti punti (overflow, divisione
 * per zero, notazione senza regola). Invece di propagare un codice attraverso
 * ogni chiamata, la prima causa viene annotata in `failure` e il conto
 * prosegue producendo valori senza significato: chi lo ha avviato controlla
 * `failure` alla fine e scarta tutto.
 *
 * Memoria. Polinomi e nodi dell'albero vivono in un'unica zona ("arena") da
 * cui si prende spazio in fila e che si svuota tutta insieme tra un enunciato
 * e il successivo. Non c'è free(): i valori intermedi sono tanti e piccoli, e
 * la loro vita finisce comunque con l'enunciato.
 *
 * Pila. Le funzioni che visitano un albero sono ricorsive, e la pila non
 * cresce: un enunciato lungo, che può avere alberi profondi, si legge
 * tenendo il conto di quanta ne chiederà (in fondo al capitolo).
 */

/* Motivo del primo errore del conto in corso, in italiano; NULL se va bene. */
static const char *failure;
/* Una crescita fallita delle strutture dinamiche non puo essere cancellata
 * da un tentativo euristico: il punto d'ingresso scarta comunque l'esito. */
static int work_allocation_failed;

/* Annota reason come causa del fallimento, se è la prima. */
static void fail(const char *reason) { if (!failure) failure = reason; }

/* 1 se il conto in corso è fallito perché un'espressione non è definita nel
 * punto in cui la si calcolava: divisione per zero, logaritmo di un numero non
 * positivo, radice di un numero negativo. Serve a distinguere questo caso dai
 * limiti del programma, come i numeri troppo grandi. Chi vuole la distinzione
 * lo azzera prima del conto, insieme a `failure`. */
static int undefined;

/* Come fail(), per i casi in cui un'espressione non è definita. */
static void fail_undefined(const char *reason) {
    if (!failure) undefined = 1;
    fail(reason);
}

/* Il messaggio dell'arena piena. Ha un nome perché una ricerca che la
 * riempie (capitolo 19) lo riconosce: lì vuol dire "troppi tentativi", non
 * un enunciato fuori portata. */
static const char *const OUT_OF_MEMORY = "memoria di lavoro esaurita";

/* L'arena: arena_used è il numero di byte già assegnati. */
static _Alignas(16) char arena[ARENA_BYTES];
static size_t arena_used;

/* Arrotonda bytes al multiplo di 16 successivo, l'unità di assegnazione. */
static size_t arena_round(size_t bytes) { return (bytes + 15) & ~(size_t)15; }

/* Ritorna un blocco di bytes byte, allineato a 16 e non inizializzato, oppure
 * NULL (con fail()) se l'arena è piena. */
static void *arena_alloc(size_t bytes) {
    bytes = arena_round(bytes);
    if (bytes > ARENA_BYTES - arena_used) { fail(OUT_OF_MEMORY); return NULL; }
    void *block = arena + arena_used;
    arena_used += bytes;
    return block;
}

/* Allarga un vettore di lavoro posseduto dal chiamante. capacity conta
 * elementi di unit byte; i dati esistenti restano validi per indice, ma
 * gli indirizzi possono cambiare. Le celle nuove sono azzerate. Overflow
 * e memoria esaurita annotano failure e lasciano intatto il vecchio blocco. */
static int work_reserve(void **data, size_t *capacity, size_t need, size_t unit) {
    if (need <= *capacity) return 1;
    size_t cap = *capacity ? *capacity : 16;
    while (cap < need) {
        if (cap > (size_t)-1 / 2) { cap = need; break; }
        cap *= 2;
    }
    if (unit && cap > (size_t)-1 / unit) { work_allocation_failed = 1; fail(OUT_OF_MEMORY); return 0; }
    void *next = realloc(*data, cap * unit);
    if (!next) { work_allocation_failed = 1; fail(OUT_OF_MEMORY); return 0; }
    memset((unsigned char *)next + *capacity * unit, 0, (cap - *capacity) * unit);
    *data = next; *capacity = cap;
    return 1;
}

/* Alloca metadati nell'arena, controllando dimensione e fallimento. Per
 * questi dati un ripiego non puo cancellare l'errore: maschere o snapshot
 * incompleti cambierebbero il significato di una deduzione. Zero elementi
 * non richiedono un blocco; unit deve essere positivo. */
static void *work_arena_array(size_t count, size_t unit) {
    if (!count) return NULL;
    if (!unit || count > ARENA_BYTES / unit) {
        work_allocation_failed = 1; fail(OUT_OF_MEMORY); return NULL;
    }
    void *data = arena_alloc(count * unit);
    if (!data) work_allocation_failed = 1;
    return data;
}

/* LA PILA DI LAVORO
 *
 * Quasi ogni funzione che visita un albero è ricorsiva: scende di un livello
 * di pila per ogni livello dell'albero. A differenza dell'arena e dei vettori
 * di lavoro la pila non cresce, e oltre il suo fondo il programma non dà un
 * esito: si ferma. Finché un enunciato stava in MAX_FORMULA caratteri i suoi
 * alberi non potevano essere abbastanza profondi; da quando il linguaggio
 * degli insiemi qualsiasi (17o-17w) legge enunciati di lunghezza qualsiasi
 * (gli altri linguaggi no: prove_core()) possono esserlo, e 20.000 negazioni
 * una dentro l'altra fermavano il programma. Ora la lettura di un enunciato
 * lungo tiene il conto della pila che i suoi alberi chiederanno, e si ferma
 * prima, con l'esito "pila di lavoro esaurita".
 *
 * Due cose rendono profondo un albero.
 *
 *   - L'annidamento vero: parentesi, negazioni, f(f(f(x))). Lo legge una
 *     discesa ricorsiva, che usa lei stessa la pila: quanta, lo dice la
 *     distanza tra l'indirizzo di una variabile locale e quello preso
 *     all'avvio (stack_used()). Si misura, e non si contano i livelli, perché
 *     il costo di un livello cambia di venti volte tra una compilazione
 *     ottimizzata e una con i sanitizer.
 *   - Le catene e gli elenchi: "a \iff b \iff c", o le lettere di
 *     "\forall x, y, z", si leggono con un ciclo, che non usa pila, ma danno
 *     un albero a pettine, con un livello per anello o per lettera. Chi li
 *     legge conta i livelli in stack_chain_levels (chain_link() in
 *     parser.c), e ognuno vale CHAIN_LEVEL_BYTES. Le catene di \land e di
 *     \lor, le sole che in un enunciato possono essere lunghe quanto si
 *     vuole (le ipotesi), in un enunciato lungo non sono a pettine: il
 *     lettore le unisce a metà (abstract_chain() in parser.c).
 *
 * La lettura conta il doppio: chi visiterà l'albero può usare, per livello,
 * più pila di chi lo ha letto. Sono misure fatte (novembre 2026, pila di
 * 8 MB, compilazione ottimizzata): la lettura usa da 600 a 1400 byte per
 * livello di annidamento e le visite meno; un anello di catena costa alle
 * visite da 140 a 210 byte. stack_budget, di default, è metà di quella pila.
 *
 * Non è un tetto alla grandezza dei modelli né al numero delle ipotesi: è
 * il budget di una risorsa che il programma non può allargare, e chi lo
 * esaurisce riceve un NON DIMOSTRATO che lo dice, come per la memoria. */
#define CHAIN_LEVEL_BYTES 256  /* byte di pila che un anello di una catena a pettine costa a chi la visita */

/* Byte di pila concessi agli alberi di un enunciato lungo (--stack-budget):
 * la metà di una pila di 8 MB, quella consueta. Chi lavora con una pila più
 * piccola (ulimit -s) deve abbassarlo, perché in C standard il programma non
 * può sapere quanta ne ha: con 2 MB di pila e il budget di default 2000
 * parentesi annidate lo fermano ancora. */
static size_t stack_budget = (size_t)4 << 20;

/* L'esito di chi esaurisce il budget della pila. Ha un nome perché prove()
 * lo mette nel verdetto al posto di ciò che i lettori, fermati a metà,
 * hanno detto. */
static const char *const STACK_EXHAUSTED = "pila di lavoro esaurita: l'enunciato è troppo annidato";

static uintptr_t stack_origin;     /* Indirizzo di una variabile locale di engine_init(): il punto da cui si misura. */
static size_t stack_chain_levels;  /* Anelli delle catene a pettine lette nell'enunciato in corso. */
static int stack_guard;            /* 1 mentre si lavora a un enunciato lungo: solo allora si misura. */
/* 1 se il budget è finito lavorando all'enunciato in corso. Come
 * work_allocation_failed, non lo cancella un tentativo successivo: lo
 * azzera e lo legge solo prove(). */
static int stack_exhausted;

/* Ritorna i byte di pila tra il punto di avvio e chi chiama. La differenza
 * si fa tra interi e in valore assoluto, perché il verso in cui la pila
 * cresce dipende dalla macchina. */
static size_t stack_used(void) {
    char here;
    uintptr_t now = (uintptr_t)(void *)&here;
    return (size_t)(now > stack_origin ? now - stack_origin : stack_origin - now);
}

/* Ritorna 1 se gli alberi dell'enunciato in corso stanno ancora nel budget
 * della pila: il doppio di quella in uso, più quella delle catene lette.
 * Altrimenti annota stack_exhausted e ritorna 0, e così a ogni chiamata
 * successiva: nessun lettore deve proseguire. Per un enunciato corto
 * ritorna sempre 1, senza misurare. */
static int stack_room(void) {
    if (!stack_guard) return 1;
    size_t reading = 2 * stack_used();
    if (reading > stack_budget || stack_chain_levels > (stack_budget - reading) / CHAIN_LEVEL_BYTES) stack_exhausted = 1;
    return !stack_exhausted;
}

/* Una parola del bitset, zero oltre la sua fine. L'indice i corrisponde
 * alla parola i/W e al bit i%W: nessuno shift puo raggiungere W. */
static inline unsigned long long slot_set_word(SlotSet set, size_t word) {
    if (word < 2) return set.low[word];
    return word - 2 < set.extra ? set.high[word - 2] : 0;
}

/* Ritorna 1 se la variabile slot appartiene all'insieme. */
static inline int slot_set_contains(SlotSet set, int slot) {
    size_t i = (size_t)slot;
    return (int)(slot_set_word(set, i / SLOT_WORD_BITS) >> (i % SLOT_WORD_BITS) & 1);
}

/* Aggiunge slot (non negativo). Le due parole comuni si copiano nel
 * valore; la coda cresce nell'arena senza cambiare i valori condivisi. */
static inline SlotSet slot_set_with(SlotSet set, int slot) {
    size_t i = (size_t)slot, word = i / SLOT_WORD_BITS;
    unsigned long long bit = 1ULL << (i % SLOT_WORD_BITS);
    if (slot_set_word(set, word) & bit) return set;
    if (word < 2) { set.low[word] |= bit; return set; }
    size_t count = word - 1 > set.extra ? word - 1 : set.extra;
    unsigned long long *tail = work_arena_array(count, sizeof *tail);
    if (!tail) return SLOT_EMPTY;
    if (set.extra) memcpy(tail, set.high, set.extra * sizeof *tail);
    memset(tail + set.extra, 0, (count - set.extra) * sizeof *tail);
    tail[word - 2] |= bit;
    set.high = tail; set.extra = count;
    return set;
}

/* L'insieme contenente soltanto slot, con la stessa regola di crescita. */
static inline SlotSet slot_set_single(int slot) { return slot_set_with(SLOT_EMPTY, slot); }

/* Unione: OR di ogni parola. Si riusa una coda gia immutabile quando
 * l'altro insieme non ne ha una, o quando entrambe sono la stessa. */
static inline SlotSet slot_set_union(SlotSet a, SlotSet b) {
    SlotSet result = a;
    result.low[0] |= b.low[0]; result.low[1] |= b.low[1];
    if (!b.extra) return result;
    if (!a.extra || (a.high == b.high && a.extra == b.extra)) {
        result.high = b.high; result.extra = b.extra; return result;
    }
    size_t count = a.extra > b.extra ? a.extra : b.extra;
    unsigned long long *tail = work_arena_array(count, sizeof *tail);
    if (!tail) return SLOT_EMPTY;
    for (size_t i = 0; i < count; i++) tail[i] = slot_set_word(a, i + 2) | slot_set_word(b, i + 2);
    result.high = tail; result.extra = count;
    return result;
}

/* Ritorna 1 se set contiene tutti i bit di wanted, anche oltre le prime
 * due parole. Un bit mancante basta a smentire l'inclusione. */
static inline int slot_set_includes(SlotSet set, SlotSet wanted) {
    for (size_t i = 0; i < 2 + wanted.extra; i++)
        if (slot_set_word(wanted, i) & ~slot_set_word(set, i)) return 0;
    return 1;
}

/* Ritorna 1 se i due insiemi condividono almeno una variabile. */
static inline int slot_set_intersects(SlotSet a, SlotSet b) {
    size_t count = a.extra < b.extra ? a.extra : b.extra;
    for (size_t i = 0; i < 2 + count; i++)
        if (slot_set_word(a, i) & slot_set_word(b, i)) return 1;
    return 0;
}

/* =============================================================================
 * 3. NUMERI ESATTI: RAZIONALI E RAZIONALI COMPLESSI
 * ============================================================================
 *
 * Nessun numero in virgola mobile: un errore di arrotondamento farebbe
 * sembrare diverso da zero un valore nullo, e la dimostrazione crollerebbe.
 *
 * I coefficienti dei polinomi sono numeri a + b i con a e b razionali. La
 * parte immaginaria serve solo alla trigonometria (capitolo 11): negli
 * enunciati senza seni e coseni resta sempre zero.
 */

/* Un numero razionale num/den. Invariante: den > 0 e la frazione è ridotta ai
 * minimi termini, quindi due Frac uguali hanno campi uguali. Lo stesso tipo
 * rappresenta gli esponenti dei monomi (capitolo 4). */
typedef struct { long long num, den; } Frac;

/* Massimo comun divisore di |a| e |b| con l'algoritmo di Euclide:
 * gcd(a, b) = gcd(b, a mod b), finché il resto è zero. */
static __int128 gcd128(__int128 a, __int128 b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) { __int128 t = a % b; a = b; b = t; }
    return a;
}

/* Ritorna num/den ridotta ai minimi termini. Fallisce se den è zero o se il
 * risultato esce da COEF_LIMIT. */
static Frac frac_make(__int128 num, __int128 den) {
    if (den == 0) { fail_undefined("divisione per zero"); return (Frac){0, 1}; }
    if (den < 0) { num = -num; den = -den; }
    __int128 g = gcd128(num, den);
    if (g > 1) { num /= g; den /= g; }
    if (num >= COEF_LIMIT || num <= -COEF_LIMIT || den >= COEF_LIMIT) {
        fail("numeri troppo grandi per il calcolo esatto");
        return (Frac){0, 1};
    }
    return (Frac){(long long)num, (long long)den};
}

/* Operazioni elementari sui razionali. */
static Frac frac_int(long long v) { return (Frac){v, 1}; }
static Frac frac_neg(Frac a) { return (Frac){-a.num, a.den}; }
static Frac frac_add(Frac a, Frac b) {
    return frac_make((__int128)a.num * b.den + (__int128)b.num * a.den, (__int128)a.den * b.den);
}
static Frac frac_mul(Frac a, Frac b) {
    return frac_make((__int128)a.num * b.num, (__int128)a.den * b.den);
}
static Frac frac_div(Frac a, Frac b) {
    return frac_make((__int128)a.num * b.den, (__int128)a.den * b.num);
}

/* Confronto: negativo, zero o positivo secondo che a sia minore, uguale o
 * maggiore di b. */
static int frac_cmp(Frac a, Frac b) {
    __int128 left = (__int128)a.num * b.den, right = (__int128)b.num * a.den;
    return (left > right) - (left < right);
}

/* Parte intera inferiore di a: il più grande intero non maggiore di a. La
 * divisione del C tronca verso zero, quindi i negativi vanno corretti. */
static long long frac_floor(Frac a) {
    long long q = a.num / a.den;
    return (a.num % a.den < 0) ? q - 1 : q;
}

/* Un numero complesso re + im i a coordinate razionali: il coefficiente di un
 * termine di polinomio. */
typedef struct { Frac re, im; } Num;

static Num num_int(long long v) { return (Num){frac_int(v), frac_int(0)}; }
static Num num_frac(Frac v) { return (Num){v, frac_int(0)}; }
static int num_is_zero(Num a) { return a.re.num == 0 && a.im.num == 0; }
static int num_equal(Num a, Num b) { return frac_cmp(a.re, b.re) == 0 && frac_cmp(a.im, b.im) == 0; }
static Num num_neg(Num a) { return (Num){frac_neg(a.re), frac_neg(a.im)}; }
static Num num_add(Num a, Num b) { return (Num){frac_add(a.re, b.re), frac_add(a.im, b.im)}; }

/* (a + b i)(c + d i) = (ac - bd) + (ad + bc) i. */
static Num num_mul(Num a, Num b) {
    return (Num){frac_add(frac_mul(a.re, b.re), frac_neg(frac_mul(a.im, b.im))),
                 frac_add(frac_mul(a.re, b.im), frac_mul(a.im, b.re))};
}

/* 1 / (a + b i) = (a - b i) / (a^2 + b^2): si moltiplica sopra e sotto per il
 * coniugato. Fallisce se a + b i è zero.
 *
 * Un numero reale si inverte da solo, senza passare per a^2: quel quadrato
 * usciva dai limiti del calcolo esatto già per 1 / 11^9, e una radice cubica
 * di 11^9 non veniva calcolata. */
static Num num_inv(Num a) {
    if (a.im.num == 0) return (Num){frac_div(frac_int(1), a.re), frac_int(0)};
    Frac norm = frac_add(frac_mul(a.re, a.re), frac_mul(a.im, a.im));
    return (Num){frac_div(a.re, norm), frac_neg(frac_div(a.im, norm))};
}

/* =============================================================================
 * 4. MONOMI E ATOMI
 * ============================================================================
 *
 * Un ATOMO è una quantità che l'algebra tratta come una lettera indivisibile.
 * Ce ne sono sei tipi (le etichette da 4f a 4h sono più sotto, in
 * term_reduce()):
 *
 *   4a. VAR: una variabile dell'enunciato: n, oppure un parametro come x.
 *   4b. BIGOP: una somma o un prodotto con estremo superiore a n + c, per
 *       esempio la somma di f(k) per k da 1 a n.
 *   4c. REC: un termine X(a n + j) di una successione definita da una
 *       ricorrenza lineare, per esempio il numero di Fibonacci F(n).
 *   4d. POW: una potenza base^M, dove M è un monomio. Con M non banale è una
 *       potenza a esponente simbolico: 2^n, a^n, (n+1)^n, e^{i n x}. Con
 *       M = 1 è la base stessa presa come lettera, e serve per le radici:
 *       la radice quadrata di n + 1 è l'atomo "(n+1)" elevato a 1/2.
 *   4e. LN: il logaritmo naturale del valore assoluto di una base.
 *   4i. ATAN: l'arcotangente di un'espressione reale.
 *
 * Un MONOMIO è un prodotto di atomi elevati a esponenti razionali, anche
 * negativi: 1/2^n è il monomio (2^n)^{-1}, e^{i x/2} è (e^{i x})^{1/2}.
 *
 * Perché gli atomi si possono trattare come lettere indipendenti. Il test "è
 * zero?" cancella solo termini con lo stesso monomio. Se due monomi diversi
 * rappresentassero in realtà la stessa quantità, il test potrebbe non
 * accorgersi di uno zero (e rispondere NON DIMOSTRATO), ma non dichiarerà mai
 * nullo qualcosa che non lo è: ogni cancellazione è un'uguaglianza vera. Per
 * perdere il meno possibile, il capitolo 6 crea gli atomi in forma canonica:
 * 4^n diventa (2^n)^2, non un atomo a sé.
 */

/* Un atomo elevato a un esponente razionale non nullo. */
typedef struct {
    int atom;  /* indice nella tabella `atoms` */
    Frac exp;  /* esponente, mai zero */
} Factor;

/* Un monomio: il prodotto dei suoi fattori. Invariante: i fattori sono in
 * ordine crescente di atomo e senza ripetizioni, così due monomi uguali hanno
 * la stessa rappresentazione. count == 0 è il monomio 1. */
typedef struct {
    int count;                   /* fattori validi in `factor` */
    Factor factor[MAX_FACTORS];
} Mono;

/* Un termine di polinomio: coefficiente per monomio. */
typedef struct {
    Num coef;
    Mono mono;
} Term;

typedef struct Node Node;  /* nodo dell'albero sintattico, capitolo 8 */

/* I tipi di atomo descritti sopra. */
typedef enum { ATOM_VAR, ATOM_BIGOP, ATOM_REC, ATOM_POW, ATOM_LN, ATOM_ATAN } AtomKind;

/* Cosa fa da base in un atomo POW o LN:
 *   BASE_EI:    la base è e^i, cioè l'atomo vale e^{i M} (trigonometria);
 *   BASE_PRIME: un numero primo;
 *   BASE_ATOM:  un altro atomo (un parametro, o n stesso);
 *   BASE_POLY:  un polinomio non riducibile a monomio, per esempio n + 1. */
typedef enum { BASE_EI, BASE_PRIME, BASE_ATOM, BASE_POLY } BaseKind;

/* Come un atomo e^{i M} si semplifica quando M contiene pi greco:
 *   PI_NONE:    nessuna regola;
 *   PI_CONST:   M = pi, l'atomo è il numero e^{i pi} = -1;
 *   PI_INTEGER: M = pi per una potenza di n: l'atomo vale 1 al quadrato. */
typedef enum { PI_NONE, PI_CONST, PI_INTEGER } PiMode;

/* Un atomo. I campi usati dipendono da kind:
 *
 *   VAR:   id = nome della variabile.
 *   BIGOP: node = il nodo somma/prodotto che lo definisce, dilation = a,
 *          offset = c: l'atomo vale la somma (o il prodotto) del corpo di
 *          node per l'indice dall'estremo inferiore fino ad a n + c.
 *   REC:   id = posizione nel vocabolario, dilation = a, offset = j:
 *          l'atomo vale X(a n + j).
 *   POW:   base e id dicono la base (id è il primo, l'atomo o la posizione in
 *          `base_polys`), exponent è il monomio M.
 *   LN:    base e id dicono la base, come per POW.
 *   ATAN:  id = posizione dell'argomento in `atan_args` (capitolo 11).
 *
 * pi e depends_on_n sono calcolati alla creazione. */
typedef struct {
    AtomKind kind;
    long long id;
    const Node *node;
    long long dilation, offset;
    BaseKind base;
    Mono exponent;
    PiMode pi;
    int depends_on_n;  /* 1 se il valore cambia al variare di n */
    int positive;      /* BIGOP: 1 se è un prodotto di fattori tutti positivi */
} Atom;

/* Tabella degli atomi dell'enunciato in corso. */
static Atom atoms[MAX_ATOMS];
static int atom_count;

/* Nome della variabile su cui si fa induzione nell'enunciato in corso. */
static int induction_var = 'n';

/* Ritorna il monomio atom^exp. */
static Mono mono_atom(int atom, Frac exp) {
    Mono m;
    m.count = 1;
    m.factor[0] = (Factor){atom, exp};
    return m;
}

/* Ritorna a * b: i fattori si fondono mantenendo l'ordine, e gli esponenti
 * dello stesso atomo si sommano (x^p * x^q = x^{p+q}). Un esponente che
 * diventa zero fa sparire il fattore. */
static Mono mono_mul(const Mono *a, const Mono *b) {
    Mono r;
    r.count = 0;
    int i = 0, j = 0;
    while (i < a->count || j < b->count) {
        Factor f;
        if (j == b->count || (i < a->count && a->factor[i].atom < b->factor[j].atom)) {
            f = a->factor[i++];
        } else if (i == a->count || b->factor[j].atom < a->factor[i].atom) {
            f = b->factor[j++];
        } else {
            f = a->factor[i++];
            f.exp = frac_add(f.exp, b->factor[j++].exp);
            if (f.exp.num == 0) continue;
        }
        if (r.count == MAX_FACTORS) { fail("monomio con troppi fattori"); break; }
        r.factor[r.count++] = f;
    }
    return r;
}

/* Ritorna m^q: ogni esponente viene moltiplicato per q. */
static Mono mono_pow(const Mono *m, Frac q) {
    Mono r;
    r.count = 0;
    if (q.num == 0) return r;
    for (int i = 0; i < m->count; i++)
        r.factor[r.count++] = (Factor){m->factor[i].atom, frac_mul(m->factor[i].exp, q)};
    return r;
}

/* Ordine totale sui monomi, usato per tenere i polinomi ordinati: confronto
 * fattore per fattore, prima per atomo e poi per esponente; a parità vince il
 * più corto. Ritorna negativo, zero o positivo. */
static int mono_cmp(const Mono *a, const Mono *b) {
    for (int i = 0; i < a->count && i < b->count; i++) {
        if (a->factor[i].atom != b->factor[i].atom) return a->factor[i].atom - b->factor[i].atom;
        int c = frac_cmp(a->factor[i].exp, b->factor[i].exp);
        if (c) return c;
    }
    return a->count - b->count;
}

/* Ritorna 1 se il monomio contiene un atomo che dipende da n. */
static int mono_depends_on_n(const Mono *m) {
    for (int i = 0; i < m->count; i++)
        if (atoms[m->factor[i].atom].depends_on_n) return 1;
    return 0;
}

/* Ritorna l'esponente con cui atom compare nel monomio m, zero se manca. */
static Frac mono_exponent(const Mono *m, int atom) {
    for (int i = 0; i < m->count; i++)
        if (m->factor[i].atom == atom) return m->factor[i].exp;
    return frac_int(0);
}

/* Ritorna m con l'esponente di atom sostituito da exp (zero lo toglie). */
static Mono mono_with_exponent(const Mono *m, int atom, Frac exp) {
    Mono rest;
    rest.count = 0;
    for (int i = 0; i < m->count; i++)
        if (m->factor[i].atom != atom) rest.factor[rest.count++] = m->factor[i];
    if (exp.num == 0) return rest;
    Mono factor = mono_atom(atom, exp);
    return mono_mul(&rest, &factor);
}

/* Applica al termine t le identità che legano un atomo a un numero,
 * modificandolo sul posto. Dopo la chiamata gli esponenti interessati sono in
 * forma canonica, così monomi uguali restano riconoscibili.
 *
 * 4f. Un atomo E = e^{i pi} elevato a r:
 *       - E^2 = 1, quindi r si riduce modulo 2 all'intervallo [0, 2);
 *       - E^1 = -1, quindi da r >= 1 si toglie 1 cambiando segno al
 *         coefficiente;
 *       - E^{1/2} = e^{i pi/2} = i, quindi da r >= 1/2 si toglie 1/2
 *         moltiplicando il coefficiente per i.
 *     Resta r in [0, 1/2).
 *
 * 4g. Un atomo E = e^{i pi n} (o e^{i pi n^2}, ...): vale solo la prima
 *     regola, E^2 = e^{2 pi i n} = 1 perché n è intero. E^1 = (-1)^n resta
 *     un atomo.
 *
 * 4h. Un atomo "primo p preso come lettera" elevato a r (nasce dalle radici:
 *     la radice di 2 è p^{1/2}): la parte intera k di r è un numero vero,
 *     p^k, che passa nel coefficiente. Resta r in [0, 1). */
static void term_reduce(Term *t) {
    for (int i = 0; i < t->mono.count; i++) {
        Factor *f = &t->mono.factor[i];
        const Atom *atom = &atoms[f->atom];
        Frac r = f->exp;

        if (atom->pi != PI_NONE) {
            /* 4f, 4g. Riduzione modulo 2. */
            r = frac_add(r, frac_int(-2 * frac_floor(frac_div(r, frac_int(2)))));

            /* 4f. Estrazione di -1 e di i, solo per la costante e^{i pi}. */
            if (atom->pi == PI_CONST) {
                if (frac_cmp(r, frac_int(1)) >= 0) {
                    t->coef = num_neg(t->coef);
                    r = frac_add(r, frac_int(-1));
                }
                if (frac_cmp(r, (Frac){1, 2}) >= 0) {
                    t->coef = num_mul(t->coef, (Num){frac_int(0), frac_int(1)});
                    r = frac_add(r, (Frac){-1, 2});
                }
            }
        } else if (atom->kind == ATOM_POW && atom->base == BASE_PRIME && atom->exponent.count == 0) {
            /* 4h. Parte intera dell'esponente di un primo. */
            long long whole = frac_floor(r);
            if (whole > MAX_POWER || whole < -MAX_POWER) { fail("esponente costante troppo grande"); return; }
            Num step = num_frac(whole > 0 ? frac_int(atom->id) : (Frac){1, atom->id});
            for (long long k = (whole > 0 ? whole : -whole); k > 0 && !failure; k--) t->coef = num_mul(t->coef, step);
            r = frac_add(r, frac_int(-whole));
        } else {
            continue;
        }

        /* Il fattore sparisce se l'esponente è diventato zero. */
        f->exp = r;
        if (r.num == 0) {
            for (int j = i + 1; j < t->mono.count; j++) t->mono.factor[j - 1] = t->mono.factor[j];
            t->mono.count--;
            i--;
        }
    }
}

/* =============================================================================
 * 5. POLINOMI NEGLI ATOMI
 * ============================================================================
 *
 * Un polinomio è una somma di termini. La forma è canonica: termini ordinati
 * per monomio, monomi tutti diversi, nessun coefficiente nullo. Ne segue il
 * test su cui si regge tutto il programma: un polinomio è zero se e solo se
 * non ha termini.
 *
 * I polinomi sono valori immutabili: ogni operazione ne costruisce uno nuovo
 * nell'arena e non tocca gli operandi.
 */

/* Un polinomio in forma canonica. `term` punta a `count` termini nell'arena
 * (NULL se count == 0); la memoria è dell'arena, non del polinomio. */
typedef struct {
    int count;
    Term *term;
} Poly;

/* Confronto tra termini per qsort: ordine dei monomi. */
static int term_cmp(const void *a, const void *b) {
    return mono_cmp(&((const Term *)a)->mono, &((const Term *)b)->mono);
}

/* Ritorna spazio per capacity termini, o NULL se l'arena è piena. */
static Term *terms_alloc(long long capacity) {
    if (capacity > MAX_PRODUCT) { fail("espressione troppo grande"); return NULL; }
    return arena_alloc((size_t)capacity * sizeof(Term));
}

/* Porta in forma canonica i primi `used` termini di buffer, che era stato
 * chiesto con terms_alloc(capacity), e ritorna il polinomio risultante. */
static Poly poly_finish(Term *buffer, long long capacity, int used) {
    /* Ordina, poi somma i coefficienti dei termini con lo stesso monomio. */
    qsort(buffer, (size_t)used, sizeof(Term), term_cmp);
    int merged = 0;
    for (int i = 0; i < used; i++) {
        if (merged > 0 && mono_cmp(&buffer[merged - 1].mono, &buffer[i].mono) == 0)
            buffer[merged - 1].coef = num_add(buffer[merged - 1].coef, buffer[i].coef);
        else
            buffer[merged++] = buffer[i];
    }

    /* Elimina i termini che la somma ha annullato. */
    int count = 0;
    for (int i = 0; i < merged; i++)
        if (!num_is_zero(buffer[i].coef)) buffer[count++] = buffer[i];

    /* Restituisce all'arena lo spazio non usato. Si può fare solo se il buffer
     * è l'ultimo blocco assegnato, ed è il caso normale: il prodotto di due
     * polinomi chiede spazio per tutti i prodotti parziali, quasi tutti poi
     * fusi tra loro. Senza questo passo l'arena si riempirebbe di vuoti. */
    size_t old_bytes = arena_round((size_t)capacity * sizeof(Term));
    size_t new_bytes = arena_round((size_t)count * sizeof(Term));
    if ((char *)buffer + old_bytes == arena + arena_used) arena_used -= old_bytes - new_bytes;

    return (Poly){count, count ? buffer : NULL};
}

/* Ritorna il polinomio formato dal solo termine t (o zero se il coefficiente è
 * nullo), dopo aver applicato le identità di term_reduce(). */
static Poly poly_term(Term t) {
    term_reduce(&t);
    Term *buffer = terms_alloc(1);
    if (!buffer) return (Poly){0, NULL};
    buffer[0] = t;
    return poly_finish(buffer, 1, 1);
}

/* Ritorna il polinomio costante c. */
static Poly poly_const(Num c) {
    Term t;
    t.coef = c;
    t.mono.count = 0;
    return poly_term(t);
}

/* Ritorna a + b, oppure a - b se subtract è diverso da zero. */
static Poly poly_add(Poly a, Poly b, int subtract) {
    long long capacity = (long long)a.count + b.count;
    Term *buffer = terms_alloc(capacity);
    if (!buffer) return (Poly){0, NULL};
    for (int i = 0; i < a.count; i++) buffer[i] = a.term[i];
    for (int i = 0; i < b.count; i++) {
        buffer[a.count + i] = b.term[i];
        if (subtract) buffer[a.count + i].coef = num_neg(b.term[i].coef);
    }
    return poly_finish(buffer, capacity, (int)capacity);
}

/* Ritorna a * b: ogni termine di a per ogni termine di b. */
static Poly poly_mul(Poly a, Poly b) {
    long long capacity = (long long)a.count * b.count;
    Term *buffer = terms_alloc(capacity);
    if (!buffer) return (Poly){0, NULL};
    int used = 0;
    for (int i = 0; i < a.count; i++)
        for (int j = 0; j < b.count; j++) {
            Term t;
            t.coef = num_mul(a.term[i].coef, b.term[j].coef);
            t.mono = mono_mul(&a.term[i].mono, &b.term[j].mono);
            term_reduce(&t);
            buffer[used++] = t;
        }
    return poly_finish(buffer, capacity, used);
}

/* Ritorna 1 se p è il polinomio costante 1. */
static int poly_is_one(Poly p) {
    return p.count == 1 && p.term[0].mono.count == 0 && num_equal(p.term[0].coef, num_int(1));
}

/* Ritorna 1 se a e b sono lo stesso polinomio. Grazie alla forma canonica
 * basta il confronto termine per termine. */
static int poly_equal(Poly a, Poly b) {
    if (a.count != b.count) return 0;
    for (int i = 0; i < a.count; i++)
        if (mono_cmp(&a.term[i].mono, &b.term[i].mono) != 0 || !num_equal(a.term[i].coef, b.term[i].coef))
            return 0;
    return 1;
}

/* Ritorna 1 se a = lambda * b per una costante lambda non nulla. */
static int poly_proportional(Poly a, Poly b) {
    if (a.count != b.count || a.count == 0) return 0;
    Num ratio = num_mul(a.term[0].coef, num_inv(b.term[0].coef));
    for (int i = 0; i < a.count; i++)
        if (mono_cmp(&a.term[i].mono, &b.term[i].mono) != 0 ||
            !num_equal(a.term[i].coef, num_mul(ratio, b.term[i].coef)))
            return 0;
    return 1;
}

/* Ritorna 1 se in p compare un atomo che dipende da n. */
static int poly_depends_on_n(Poly p) {
    for (int i = 0; i < p.count; i++)
        if (mono_depends_on_n(&p.term[i].mono)) return 1;
    return 0;
}

/* Scompone p secondo le potenze dell'atomo x: p = part[0] + part[1] x + ... +
 * part[d] x^d, con le part[j] prive di x. Ritorna il grado d (0 se x non
 * compare), oppure -1 se x compare con esponente negativo, frazionario o
 * maggiore di max_degree. part deve avere max_degree + 1 posti. */
static int poly_split(Poly p, int x, Poly *part, int max_degree) {
    int degree = 0;
    for (int j = 0; j <= max_degree; j++) {
        Term *buffer = terms_alloc(p.count);
        if (!buffer && p.count) return -1;
        int used = 0;
        for (int i = 0; i < p.count; i++) {
            /* Il termine va in part[j] se x vi compare alla j, senza x. */
            Term t = p.term[i];
            Frac e = mono_exponent(&t.mono, x);
            if (e.den != 1 || e.num < 0 || e.num > max_degree) return -1;
            if (e.num != j) continue;
            t.mono = mono_with_exponent(&t.mono, x, frac_int(0));
            buffer[used++] = t;
            if (j > degree) degree = j;
        }
        part[j] = poly_finish(buffer, p.count, used);
    }
    return degree;
}

/* Legge p come polinomio nel solo atomo x, a coefficienti razionali.
 *
 * Se p ha questa forma, con grado al più MAX_UNIVARIATE, mette in *scale il
 * più piccolo intero positivo che moltiplicato per p dà coefficienti interi,
 * in c[0..MAX_UNIVARIATE] quei coefficienti (zero dove mancano) e ritorna il
 * grado, 0 per il polinomio nullo. Altrimenti ritorna -1: quando compare un
 * altro atomo, un esponente negativo o non intero, un coefficiente complesso,
 * oppure un numero oltre il miliardo. Quest'ultimo tetto tiene lontani
 * dall'overflow i conti di chi poi usa i coefficienti. */
static int poly_coefficients(Poly p, int x, long long *c, long long *scale) {
    const long long cap = 1000000000;
    int degree = 0;

    /* Il moltiplicatore: il minimo comune multiplo dei denominatori. */
    *scale = 1;
    for (int i = 0; i < p.count; i++) {
        long long den = p.term[i].coef.re.den;
        __int128 multiple = (__int128)*scale / gcd128(*scale, den) * den;
        if (multiple > cap) return -1;
        *scale = (long long)multiple;
    }

    /* I coefficienti, ciascuno al posto del suo esponente. */
    for (int j = 0; j <= MAX_UNIVARIATE; j++) c[j] = 0;
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        Frac e = frac_int(0);
        if (t->mono.count == 1 && t->mono.factor[0].atom == x) e = t->mono.factor[0].exp;
        else if (t->mono.count != 0) return -1;
        if (t->coef.im.num != 0 || e.den != 1 || e.num < 0 || e.num > MAX_UNIVARIATE) return -1;
        __int128 value = (__int128)t->coef.re.num * (*scale / t->coef.re.den);
        if (value > cap || value < -cap) return -1;
        c[e.num] = (long long)value;
        if (e.num > degree) degree = (int)e.num;
    }
    return degree;
}

/* =============================================================================
 * 6. CREAZIONE DEGLI ATOMI
 * ============================================================================
 *
 * Ogni atomo è registrato una volta sola: chiedere due volte "2^n" restituisce
 * lo stesso indice. È questo a far sì che due occorrenze della stessa quantità
 * si riconoscano e si cancellino.
 */

/* Polinomi che fanno da base a un atomo POW con BASE_POLY, ciascuno una volta. */
static Poly base_polys[MAX_ATOMS];
static int base_poly_count;

/* Prototipo in avanti necessario: il confronto tra due somme guarda dentro i
 * nodi dell'albero, che sono definiti nel capitolo 8. */
static int bigop_same(const Node *a, const Node *b);

/* Cerca nella tabella un atomo uguale a proto e ne ritorna l'indice;
 * se non c'è lo aggiunge. Due atomi sono uguali se coincidono in tutti i campi
 * che li identificano; per i BIGOP l'offset non conta (vedi atom_bigop()), e
 * le somme si confrontano per come sono scritte, con bigop_same(). */
static int atom_intern(const Atom *proto) {
    for (int i = 0; i < atom_count; i++) {
        const Atom *a = &atoms[i];
        if (a->kind != proto->kind || a->id != proto->id || a->dilation != proto->dilation || a->base != proto->base)
            continue;
        if (a->kind == ATOM_BIGOP && !bigop_same(a->node, proto->node)) continue;
        if (a->kind == ATOM_REC && a->offset != proto->offset) continue;
        if (a->kind == ATOM_POW && mono_cmp(&a->exponent, &proto->exponent) != 0) continue;
        return i;
    }
    if (atom_count == MAX_ATOMS) { fail("troppe quantità distinte nell'enunciato"); return 0; }
    atoms[atom_count] = *proto;
    return atom_count++;
}

/* Ritorna l'atomo della variabile name. */
static int atom_var(int name) {
    Atom a = {0};
    a.kind = ATOM_VAR;
    a.id = name;
    a.depends_on_n = (name == induction_var);
    return atom_intern(&a);
}

/* Ritorna l'atomo della somma (o prodotto) definita da node con estremo
 * superiore dilation * n + offset.
 *
 * L'offset vale solo alla prima richiesta: fissa quale somma l'atomo
 * rappresenta, e le richieste successive con la stessa somma e la stessa
 * dilation ritornano quell'atomo anche con un offset diverso. Sta al chiamante
 * aggiungere o togliere i termini di differenza (vedi eval_bigop()).
 *
 * "La stessa somma" vuol dire scritta allo stesso modo, non lo stesso nodo:
 * due copie della somma dei k da 1 a n nello stesso enunciato sono un atomo
 * solo. Prima erano due lettere indipendenti, e il programma non riusciva a
 * dimostrare nemmeno che 2 diviso un prodotto è uguale a se stesso: dove le
 * due copie erano moltiplicate o divise per qualcosa, l'ipotesi induttiva non
 * bastava a legarle. */
static int atom_bigop(const Node *node, long long dilation, long long offset) {
    Atom a = {0};
    a.kind = ATOM_BIGOP;
    a.node = node;
    a.dilation = dilation;
    a.offset = offset;
    a.depends_on_n = 1;
    return atom_intern(&a);
}

/* Ritorna l'atomo X(dilation * n + offset) della successione del vocabolario
 * in posizione sequence. */
static int atom_rec(int sequence, long long dilation, long long offset) {
    Atom a = {0};
    a.kind = ATOM_REC;
    a.id = sequence;
    a.dilation = dilation;
    a.offset = offset;
    a.depends_on_n = 1;
    return atom_intern(&a);
}

/* Ritorna l'atomo base^exponent, con la base descritta da base e id. */
static int atom_pow(BaseKind base, long long id, const Mono *exponent) {
    Atom a = {0};
    a.kind = ATOM_POW;
    a.base = base;
    a.id = id;
    a.exponent = *exponent;

    /* Dipende da n se ne dipende l'esponente oppure la base. */
    a.depends_on_n = mono_depends_on_n(exponent) ||
                     (base == BASE_ATOM && atoms[id].depends_on_n) ||
                     (base == BASE_POLY && poly_depends_on_n(base_polys[id]));

    /* Riconosce e^{i pi} ed e^{i pi n^j}, a cui si applicano le identità di
     * term_reduce(): l'esponente deve essere pi per (eventualmente) una
     * potenza intera positiva di n, e nient'altro. */
    if (base == BASE_EI) {
        int has_pi = 0, has_n = 0, other = 0;
        for (int i = 0; i < exponent->count; i++) {
            const Atom *f = &atoms[exponent->factor[i].atom];
            Frac e = exponent->factor[i].exp;
            if (f->kind == ATOM_VAR && f->id == VAR_PI && e.num == 1 && e.den == 1) has_pi = 1;
            else if (f->kind == ATOM_VAR && f->id == induction_var && e.den == 1 && e.num > 0) has_n = 1;
            else other = 1;
        }
        if (has_pi && !other) a.pi = has_n ? PI_INTEGER : PI_CONST;
    }
    return atom_intern(&a);
}

/* Ritorna l'atomo ln|base|, con la base descritta da base e id. */
static int atom_ln(BaseKind base, long long id) {
    Atom a = {0};
    a.kind = ATOM_LN;
    a.base = base;
    a.id = id;
    a.depends_on_n = (base == BASE_ATOM && atoms[id].depends_on_n) ||
                     (base == BASE_POLY && poly_depends_on_n(base_polys[id]));
    return atom_intern(&a);
}

/* Ritorna la posizione di p in base_polys, aggiungendolo se manca. */
static int base_poly_intern(Poly p) {
    for (int i = 0; i < base_poly_count; i++)
        if (poly_equal(base_polys[i], p)) return i;
    if (base_poly_count == MAX_ATOMS) { fail("troppe basi distinte nell'enunciato"); return 0; }
    base_polys[base_poly_count] = p;
    return base_poly_count++;
}

/* =============================================================================
 * 7. FRAZIONI DI POLINOMI
 * ============================================================================
 *
 * Il valore di un'espressione è una frazione num/den di polinomi negli atomi,
 * con le regole delle frazioni di scuola:
 *
 *     a1/b1 + a2/b2 = (a1 b2 + a2 b1) / (b1 b2)
 *     a1/b1 * a2/b2 = (a1 a2) / (b1 b2)
 *     a1/b1 : a2/b2 = (a1 b2) / (b1 a2)
 *
 * Le frazioni non vengono ridotte ai minimi termini (il perché è nel commento
 * di design), con un'eccezione che non costa nulla: se il denominatore è un
 * solo termine lo si porta al numeratore cambiando segno agli esponenti. Così
 * 1/2^n diventa (2^n)^{-1} e i denominatori restano piccoli.
 *
 * Invariante: senza errori den non è mai il polinomio nullo. Per questo "la
 * frazione è zero" equivale a "num non ha termini".
 */

/* La frazione num/den. */
typedef struct { Poly num, den; } Rat;

/* Ritorna num/den, applicando la semplificazione del denominatore monomio.
 * Fallisce se den è zero. */
static Rat rat_make(Poly num, Poly den) {
    Rat r = {num, den};
    if (den.count == 0) {
        fail_undefined("divisione per zero");
        r.den = poly_const(num_int(1));
    } else if (den.count == 1 && !poly_is_one(den)) {
        Term inverse;
        inverse.coef = num_inv(den.term[0].coef);
        inverse.mono = mono_pow(&den.term[0].mono, frac_int(-1));
        r.num = poly_mul(num, poly_term(inverse));
        r.den = poly_const(num_int(1));
    }
    return r;
}

/* Frazioni elementari: l'intero v, il razionale v e l'atomo `atom`. */
static Rat rat_int(long long v) { return (Rat){poly_const(num_int(v)), poly_const(num_int(1))}; }
static Rat rat_frac(Frac v) { return (Rat){poly_const(num_frac(v)), poly_const(num_int(1))}; }
static Rat rat_atom(int atom) {
    Term t;
    t.coef = num_int(1);
    t.mono = mono_atom(atom, frac_int(1));
    return (Rat){poly_term(t), poly_const(num_int(1))};
}

/* Ritorna a + b, oppure a - b se subtract è diverso da zero. Se i denominatori
 * coincidono si sommano solo i numeratori: capita spesso, e tiene piccole le
 * frazioni. */
static Rat rat_add(Rat a, Rat b, int subtract) {
    if (poly_equal(a.den, b.den)) return rat_make(poly_add(a.num, b.num, subtract), a.den);
    return rat_make(poly_add(poly_mul(a.num, b.den), poly_mul(b.num, a.den), subtract),
                    poly_mul(a.den, b.den));
}

/* Ritorna a * b. */
static Rat rat_mul(Rat a, Rat b) { return rat_make(poly_mul(a.num, b.num), poly_mul(a.den, b.den)); }

/* CONDIZIONI DI ESISTENZA
 *
 * Una divisione, un logaritmo, una radice hanno senso solo se ciò su cui
 * operano rispetta una condizione: diverso da zero, positivo, non negativo.
 * Quando il valore è un numero la condizione si controlla sul momento (vedi
 * fail_undefined()). Quando è un'espressione in n non si può: vale per certi
 * n e non per altri. Allora la si annota in questo elenco, e chi ha chiesto
 * il conto decide poi se vale per ogni n (capitolo 13, 13c).
 *
 * L'elenco si riempie solo mentre conditions_on è diverso da zero: durante la
 * dimostrazione resta spento, perché lì le condizioni sono ipotesi
 * dell'enunciato ("vale dove i due membri sono definiti"). */

/* Cosa si chiede a un'espressione perché un'operazione sia definita. */
typedef enum { NEVER_ZERO, ALWAYS_POSITIVE, NEVER_NEGATIVE } Requirement;

/* Una condizione di esistenza: il prodotto dei `count` polinomi di factor[]
 * deve rispettare `kind` per ogni n ammesso. Quasi sempre il fattore è uno
 * solo; sono di più quando chi pone la condizione conosce l'espressione già
 * divisa in fattori, e conviene non perderli moltiplicandoli (vedi
 * require_positive() nel capitolo 11). `why` dice che cosa succede se la
 * condizione non vale, con le stesse parole di fail_undefined(). I termini
 * dei polinomi stanno nell'arena: la condizione vale finché l'arena non viene
 * svuotata. */
typedef struct {
    Requirement kind;
    int count;                      /* fattori validi in factor: almeno 1 */
    Poly factor[MAX_SIGN_FACTORS];
    const char *why;
} Condition;

static Condition conditions[MAX_CONDITIONS];
static int condition_count;
static int conditions_on;    /* 1 mentre le condizioni vanno annotate */
static int conditions_lost;  /* 1 se l'elenco non è bastato a contenerle */

/* Il perché di una divisione che non è scritta nell'enunciato: la fa il
 * conto, quando riscrive un prodotto fino a n - 1 come il prodotto fino a n
 * diviso per l'ultimo fattore (vedi eval_bigop()). `rewriting` è diverso da
 * zero mentre il conto fa una divisione di questo tipo. */
static const char *const REWRITTEN = "la dimostrazione divide un prodotto per un suo fattore, che lì vale zero";
static int rewriting;

/* Annota che il prodotto dei `count` polinomi di factor[] deve rispettare
 * kind, se l'elenco è acceso. Una condizione già presente non viene ripetuta.
 * Dividere per un numero diverso da zero non pone condizioni, e lo zero è già
 * stato rifiutato da chi divide. */
static void require_product(Requirement kind, const Poly *factor, int count, const char *why) {
    if (!conditions_on || failure) return;
    if (kind == NEVER_ZERO && count == 1 && factor[0].count == 1 && factor[0].term[0].mono.count == 0) return;
    for (int i = 0; i < condition_count; i++) {
        int same = conditions[i].kind == kind && conditions[i].count == count;
        for (int f = 0; f < count && same; f++) same = poly_equal(conditions[i].factor[f], factor[f]);
        if (same) return;
    }
    if (condition_count == MAX_CONDITIONS || count > MAX_SIGN_FACTORS) { conditions_lost = 1; return; }
    Condition *c = &conditions[condition_count++];
    c->kind = kind;
    c->count = count;
    c->why = why;
    for (int f = 0; f < count; f++) c->factor[f] = factor[f];
}

/* Annota che value deve rispettare kind. */
static void require(Requirement kind, Poly value, const char *why) { require_product(kind, &value, 1, why); }

/* Ritorna a / b. Fallisce se b è la frazione nulla, e annota che b non deve
 * annullarsi (il suo denominatore è già stato annotato quando b è nata da
 * un'altra divisione). */
static Rat rat_div(Rat a, Rat b) {
    require(NEVER_ZERO, b.num, rewriting ? REWRITTEN : "divisione per zero");
    return rat_make(poly_mul(a.num, b.den), poly_mul(a.den, b.num));
}

/* Ritorna a^e per e intero, anche negativo, con a^0 = 1. Moltiplicazioni
 * ripetute: gli esponenti costanti degli enunciati sono piccoli. */
static Rat rat_pow_int(Rat a, long long e) {
    if (e < -MAX_POWER || e > MAX_POWER) { fail("esponente costante troppo grande"); return rat_int(0); }
    if (e < 0) { a = rat_div(rat_int(1), a); e = -e; }
    Rat r = rat_int(1);
    for (long long i = 0; i < e && !failure; i++) r = rat_mul(r, a);
    return r;
}

/* Ritorna p con l'atomo x sostituito da value. In p l'atomo deve comparire
 * con esponenti interi tra 0 e MAX_UNIVARIATE, altrimenti fallisce.
 *
 * Schema di Horner: p = c0 + c1 x + ... + cd x^d si calcola come
 * (...(cd x + c(d-1)) x + ...) x + c0, con d moltiplicazioni. */
static Rat poly_substitute(Poly p, int x, Rat value) {
    Poly part[MAX_UNIVARIATE + 1], one = poly_const(num_int(1));
    int degree = poly_split(p, x, part, MAX_UNIVARIATE);
    if (degree < 0) { fail("polinomio di grado troppo alto in una variabile da sostituire"); return rat_int(0); }
    Rat result = {part[degree], one};
    for (int j = degree - 1; j >= 0; j--) result = rat_add(rat_mul(result, value), (Rat){part[j], one}, 0);
    return result;
}

/* Se r è un numero (nessun atomo) lo mette in *value e ritorna 1. */
static int rat_number(Rat r, Num *value) {
    if (!poly_is_one(r.den)) return 0;
    if (r.num.count == 0) { *value = num_int(0); return 1; }
    if (r.num.count != 1 || r.num.term[0].mono.count != 0) return 0;
    *value = r.num.term[0].coef;
    return 1;
}

/* Se r è un numero intero lo mette in *value e ritorna 1. */
static int rat_integer(Rat r, long long *value) {
    Num v;
    if (!rat_number(r, &v) || v.im.num != 0 || v.re.den != 1) return 0;
    *value = v.re.num;
    return 1;
}

/* Se r ha la forma a * n + c con a e c interi (n è la variabile di induzione)
 * mette i due numeri in *a e *c e ritorna 1. Un intero è il caso a = 0. */
static int rat_affine(Rat r, long long *a, long long *c) {
    int n = atom_var(induction_var);
    *a = *c = 0;
    if (!poly_is_one(r.den)) return 0;
    for (int i = 0; i < r.num.count; i++) {
        const Term *t = &r.num.term[i];
        if (t->coef.im.num != 0 || t->coef.re.den != 1) return 0;
        if (t->mono.count == 0) *c = t->coef.re.num;
        else if (t->mono.count == 1 && t->mono.factor[0].atom == n &&
                 t->mono.factor[0].exp.num == 1 && t->mono.factor[0].exp.den == 1)
            *a = t->coef.re.num;
        else return 0;
    }
    return 1;
}

/* Se e = alpha x + beta, con x l'atomo della variabile e alpha diverso da
 * zero, mette i due razionali in *alpha e *beta e ritorna 1. */
static int rat_affine_in(Rat e, int x, Frac *alpha, Frac *beta) {
    *alpha = *beta = frac_int(0);
    if (failure || e.den.count != 1 || e.den.term[0].mono.count != 0 || e.den.term[0].coef.im.num != 0) return 0;
    for (int i = 0; i < e.num.count; i++) {
        const Term *t = &e.num.term[i];
        if (t->coef.im.num != 0) return 0;
        if (t->mono.count == 0) *beta = t->coef.re;
        else if (t->mono.count == 1 && t->mono.factor[0].atom == x && frac_cmp(t->mono.factor[0].exp, frac_int(1)) == 0) *alpha = t->coef.re;
        else return 0;
    }
    *alpha = frac_div(*alpha, e.den.term[0].coef.re);
    *beta = frac_div(*beta, e.den.term[0].coef.re);
    return alpha->num != 0 && !failure;
}

/* I capitoli 8, 9, 14, 17 e 21, cioè tutta la lettura del LaTeX, stanno in
 * parser.c: gli alberi (delle espressioni, degli enunciati sugli insiemi,
 * degli enunciati con quantificatori), i tre lettori che li costruiscono e la
 * lettura degli \item di un file .tex. Va incluso qui, dopo le frazioni di
 * polinomi che i suoi alberi nominano e prima del motore che li usa. */
#include "parser.c"

/* Il segno di derivata dentro un'espressione (9d) arriva dal lettore come un
 * nodo N_DERIV, che nessun conto sa trattare: lo sostituisce con la derivata
 * il capitolo 27 (27j), con le regole di derive() e il loro controllo con i
 * numeri. Chi legge un enunciato fatto di espressioni (capitoli 13, 18, 25)
 * chiama queste funzioni subito dopo il parsing, prima di ogni conto, ma sta
 * più in alto del capitolo 27, che a sua volta usa la valutazione, gli
 * intervalli e la tabella dei segni: per questo i prototipi sono qui.
 *
 * derivatives_expanded() ritorna l'albero con le derivate al posto dei
 * segni, oppure annota in `failure` perché un segno non si espande;
 * formula_derivatives_expanded() fa lo stesso su ogni confronto di un
 * enunciato con quantificatori. derivative_signs conta i segni espansi
 * dall'ultima volta che qualcuno l'ha azzerato. derivative_doubt() dice se
 * un enunciato deciso dalla tabella dei segni dipende da punti in cui una
 * funzione è definita ma le regole non ne danno la derivata (27l): NULL se
 * no, altrimenti il motivo. */
static Node *derivatives_expanded(Node *tree);
static void formula_derivatives_expanded(Formula *f);
static const char *derivative_doubt(const Formula *thesis);
static int derivative_signs;

/* 1 se derivative_doubt() ha trovato un estremo del dominio di una funzione
 * in cui la derivata (da tutte e due le parti) non esiste: il verdetto lo
 * dice, perché chi conta la derivata da una parte sola leggerebbe in un
 * altro modo la risposta. */
static int derivative_edges;
static const char *const DERIVATIVE_EDGES = "negli estremi del dominio la derivata, che chiede la funzione definita da tutte e due le parti, non c'è";

/* =============================================================================
 * 10. VOCABOLARIO: LE SUCCESSIONI NOTE, COME DATI
 * ============================================================================
 *
 * Il motore non sa cosa sia un fattoriale o un numero di Fibonacci: lo legge
 * da questa tabella. Una successione si può definire in due modi.
 *
 *   10a. Con una formula nell'indice m, scritta nello stesso LaTeX degli
 *        enunciati. Il fattoriale è un prodotto, il numero armonico una
 *        somma: il motore li tratta come ogni altra somma o prodotto.
 *
 *   10b. Con una ricorrenza lineare a coefficienti costanti di ordine d:
 *        X(m+d) = coef[0] X(m+d-1) + ... + coef[d-1] X(m), con i valori
 *        iniziali X(0), ..., X(d-1). Fibonacci è d = 2, coefficienti 1 e 1.
 *
 * Per aggiungere una successione basta una riga qui (per esempio i numeri di
 * Lucas: {'L', NULL, 2, {1, 1}, {2, 1}, NULL}).
 */

/* Una successione del vocabolario. */
typedef struct {
    int name;                   /* lettera con cui compare (pedice), o '!' */
    const char *definition;     /* 10a: formula in m; NULL nel caso 10b */
    int order;                  /* 10b: ordine d della ricorrenza */
    long long coef[MAX_ORDER];  /* 10b: coefficienti, dal termine più recente */
    long long init[MAX_ORDER];  /* 10b: X(0), ..., X(d-1) */
    Node *tree;                 /* 10a: la definizione già analizzata */
} Sequence;

static Sequence library[] = {
    {'!', "\\prod_{j=1}^{m} j", 0, {0}, {0}, NULL},
    {'H', "\\sum_{j=1}^{m} \\frac{1}{j}", 0, {0}, {0}, NULL},
    {'F', NULL, 2, {1, 1}, {0, 1}, NULL},
};
#define LIBRARY_COUNT ((int)(sizeof library / sizeof *library))

/* Quanto dell'arena è occupato dal vocabolario: da non svuotare mai. */
static size_t arena_keep;

/* Prepara il motore: analizza le definizioni del vocabolario. Va chiamata una
 * volta prima di ogni altra funzione dei capitoli successivi. */
static void engine_init(void) {
    /* Il punto da cui si misura la pila (stack_used()): chi chiama questa
     * funzione è in cima al programma, o quasi. */
    char here;
    stack_origin = (uintptr_t)(void *)&here;
    arena_used = 0;
    for (int i = 0; i < LIBRARY_COUNT; i++)
        if (library[i].definition) library[i].tree = parse_expression(library[i].definition);
    arena_keep = arena_used;
}

/* =============================================================================
 * 11. VALUTAZIONE: DALL'ALBERO ALLA FRAZIONE
 * ============================================================================
 *
 * eval() calcola il valore di un nodo come frazione di polinomi negli atomi.
 * Le variabili possono essere "legate" a un valore: l'indice di una somma
 * durante il calcolo del corpo, e soprattutto n, che l'induzione lega di volta
 * in volta a un numero, a se stessa o a n + 1. Una variabile non legata è un
 * parametro dell'enunciato e diventa un atomo.
 *
 * Il punto delicato è riportare ogni risultato agli stessi atomi "in n",
 * qualunque sia il valore legato a n:
 *
 *   - somme e prodotti: eval_bigop(); quelle con n nel coefficiente
 *     binomiale hanno una forma chiusa, che dà il teorema del binomio:
 *     binomial_sum() (11n);
 *   - successioni per ricorrenza: eval_recurrence();
 *   - potenze con esponente simbolico: power() e symbolic_power();
 *   - radici e logaritmi: fractional_power() e logarithm(), che si appoggiano
 *     alla scomposizione in fattori di factorize();
 *   - seni e coseni: exp_i().
 *
 * Nel conto di un'uguaglianza che vale "dove i due membri sono definiti" la
 * scomposizione usa anche i fatti del dominio (11q): i segni che in tutti
 * quei punti, e solo lì, sono certi.
 */

/* Un legame numerico: name e il nome della variabile, value la frazione
 * negli atomi che la sostituisce. I polinomi di value sono posseduti
 * dall'arena della valutazione; la cella del legame non li libera. */
typedef struct {
    int name;
    Rat value;
} Binding;

/* Le variabili legate in questo momento: l'ultima aggiunta nasconde le
 * precedenti con lo stesso nome. */
/* I blocchi mantengono stabili gli indirizzi restituiti da env_lookup(),
 * anche se una valutazione ricorsiva aggiunge altri legami. 64 e soltanto
 * la granularita di allocazione, non un massimo: cresce l'indice di blocchi. */
#define ENV_BLOCK_BINDINGS 64
static Binding **env_block;
static size_t env_block_capacity, env_blocks;
static int env_count;

/* La cella del legame index, gia allocata: nessuna ricerca o allocazione. */
static Binding *env_at(int index) {
    return &env_block[(size_t)index / ENV_BLOCK_BINDINGS][(size_t)index % ENV_BLOCK_BINDINGS];
}

/* Più di zero mentre si valuta una definizione del vocabolario. */
static int library_depth;

/* Il più piccolo n per cui tutte le somme e i prodotti scritti nell'enunciato
 * hanno almeno un termine. È il caso base quando l'enunciato non ne indica
 * uno; eval_bigop() lo alza. */
static long long default_base;

/* Un valore sotto il quale n non scende mai nell'enunciato in corso. Serve a
 * stabilire il segno di espressioni come n - 1 (vedi factorize()). */
static long long domain_floor;

/* I valori dati ai parametri dell'enunciato quando lo si calcola in un punto
 * preciso: il parametro point_name[i] vale point_value[i]. Durante la
 * dimostrazione l'elenco è vuoto e i parametri restano lettere; lo riempie
 * solo la verifica numerica (13e), che lega questi valori per primi: sono
 * quindi i primi point_count posti di `env` (vedi difference()). */
static int point_name[MAX_POINT];
static Frac point_value[MAX_POINT];
static int point_count;

/* I fatti del dominio (11q, più sotto): mentre domain_on è diverso da zero si
 * sta calcolando un'uguaglianza che vale "dove i due membri sono definiti", e
 * ogni domain_fact[i] è un polinomio negli atomi che in tutti quei punti è
 * >= 0. Li accende e li spegne solo vanishes_where_defined() (12d).
 *
 * Warning: un conto ausiliario fatto durante la valutazione, che non calcola
 * una parte dell'enunciato ma una prova con la lettera ausiliaria (come
 * body_is_positive() e binomial_sum()), deve spegnere domain_on finché dura e
 * poi rimetterlo com'era: i fatti valgono per i valori dell'enunciato, non per
 * quella lettera. */
static Poly domain_fact[MAX_DOMAIN_FACTS];
static int domain_fact_count;
static int domain_on;

/* Lega name a value, senza spostare le celle gia visibili. Un fallimento
 * annota anche work_allocation_failed: eventuali tentativi che ripuliscono
 * failure non possono consegnare un risultato basato su una pila incompleta. */
static int env_push(int name, Rat value) {
    size_t block = (size_t)env_count / ENV_BLOCK_BINDINGS;
    if (!work_reserve((void **)&env_block, &env_block_capacity, block + 1, sizeof *env_block)) return 0;
    if (block == env_blocks) {
        env_block[block] = calloc(ENV_BLOCK_BINDINGS, sizeof **env_block);
        if (!env_block[block]) { work_allocation_failed = 1; fail(OUT_OF_MEMORY); return 0; }
        env_blocks++;
    }
    *env_at(env_count++) = (Binding){name, value};
    return 1;
}

/* Scioglie l'ultima variabile legata. */
static void env_pop(void) { if (env_count > 0) env_count--; }

/* Ritorna il valore legato a name, o NULL se name è un parametro libero. */
static const Rat *env_lookup(int name) {
    for (int i = env_count - 1; i >= 0; i--)
        if (env_at(i)->name == name) return &env_at(i)->value;
    return NULL;
}

/* Ritorna 1 se name è legata a un valore che cambia durante il conto: n, o
 * l'indice di una somma. I parametri a cui la verifica numerica ha dato un
 * valore sono legati anche loro, ma a una costante, e non contano. */
static int env_varies(int name) {
    for (int i = env_count - 1; i >= point_count; i--)
        if (env_at(i)->name == name) return 1;
    return 0;
}

static Rat eval(const Node *node);

/* Un indice che nasconde una variabile dell'ambiente dentro una somma.
 * name e il nome locale, outer il contesto esterno preso in prestito.
 * La cella vive nel frame ricorsivo che la possiede: una cella per indice,
 * senza copiare un vettore sempre piu lungo a ogni livello. */
typedef struct NameScope NameScope;
struct NameScope { int name; const NameScope *outer; };

/* Ritorna 1 se name e nascosto da uno degli indici interni attivi. */
static int name_shadowed(const NameScope *scope, int name) {
    for (; scope; scope = scope->outer) if (scope->name == name) return 1;
    return 0;
}

/* Ritorna 1 se nel sotto-albero node compare, libera, una variabile che in
 * questo momento è legata a un valore che cambia (vedi env_varies()). shadow collega gli indici di somme interne
 * gia incontrati: sono legati dalla loro somma, non dall'ambiente. */
static int uses_bound_variable(const Node *node, const NameScope *shadow) {
    if (!node) return 0;
    if (node->kind == N_VAR) return !name_shadowed(shadow, node->name) && env_varies(node->name);
    if (node->kind == N_BIGOP) {
        if (uses_bound_variable(node->a, shadow) || uses_bound_variable(node->b, shadow)) return 1;
        NameScope inner = {node->name, shadow};
        return uses_bound_variable(node->c, &inner);
    }
    return uses_bound_variable(node->a, shadow) || uses_bound_variable(node->b, shadow) ||
           uses_bound_variable(node->c, shadow);
}

/* Valuta il corpo della somma o prodotto node con l'indice legato a index. */
static Rat eval_body(const Node *node, Rat index) {
    env_push(node->name, index);
    Rat value = eval(node->c);
    env_pop();
    return value;
}

/* Ritorna 1 se l'atomo è non negativo per ogni n ammesso: n stesso, quando
 * parte da zero o più; la lettera ausiliaria; le potenze di un numero primo;
 * i prodotti di fattori positivi. */
static int atom_is_nonnegative(int atom) {
    const Atom *a = &atoms[atom];
    if (a->kind == ATOM_VAR) return a->id == VAR_SLACK || (a->id == induction_var && domain_floor >= 0);
    if (a->kind == ATOM_BIGOP) return a->positive;
    return a->kind == ATOM_POW && a->base == BASE_PRIME;
}

static int poly_is_real(Poly p);

/* Ritorna 1 se l'atomo ha certamente valore reale. Le variabili sono numeri
 * reali per convenzione; non lo sono gli atomi e^{i M}, e per prudenza nemmeno
 * somme e prodotti, il cui termine potrebbe contenerne. */
static int atom_is_real(int atom) {
    const Atom *a = &atoms[atom];
    if (a->kind == ATOM_BIGOP) return 0;
    if (a->kind != ATOM_POW) return 1;
    if (a->base == BASE_EI) return 0;
    if (a->base == BASE_ATOM) return atom_is_real((int)a->id);
    return a->base == BASE_PRIME || poly_is_real(base_polys[a->id]);
}

/* Ritorna 1 se p ha certamente valore reale: coefficienti reali e atomi
 * reali. */
static int poly_is_real(Poly p) {
    for (int i = 0; i < p.count; i++) {
        if (p.term[i].coef.im.num != 0) return 0;
        for (int f = 0; f < p.term[i].mono.count; f++)
            if (!atom_is_real(p.term[i].mono.factor[f].atom)) return 0;
    }
    return 1;
}

/* Ritorna 1 se p è evidentemente positivo: una somma di termini non negativi
 * con coefficiente positivo, uno dei quali è una costante. Un termine è non
 * negativo se ogni suo fattore è un atomo non negativo oppure una potenza pari
 * di un atomo reale, come x^2.
 *
 * È una condizione sufficiente, non necessaria: n^2 - n + 1 è positivo ma non
 * la soddisfa. */
static int poly_is_positive(Poly p) {
    int constant = 0;
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        if (t->coef.im.num != 0 || t->coef.re.num <= 0) return 0;
        for (int f = 0; f < t->mono.count; f++) {
            const Factor *factor = &t->mono.factor[f];
            int even = factor->exp.den == 1 && factor->exp.num % 2 == 0;
            if (!atom_is_nonnegative(factor->atom) && !(even && atom_is_real(factor->atom))) return 0;
        }
        if (t->mono.count == 0) constant = 1;
    }
    return constant;
}

/* Ritorna 1 se il corpo di node è positivo per ogni indice da lower in su.
 *
 * Il corpo viene valutato nell'indice lower + t, dove t è una lettera
 * ausiliaria che vale zero o più: se numeratore e denominatore del risultato
 * sono evidentemente positivi, il corpo lo è per ogni t. Per il fattoriale il
 * corpo è l'indice stesso, e in 1 + t dà 1 + t: positivo.
 *
 * Un errore durante questa prova non riguarda l'enunciato e viene scartato. */
static int body_is_positive(const Node *node, long long lower) {
    const char *saved = failure;
    int recording = conditions_on, domain = domain_on;

    /* È una prova fatta con una lettera ausiliaria, non un conto
     * dell'enunciato: le sue divisioni non pongono condizioni, e i fatti del
     * dominio (11q) non la riguardano. Il risultato resta nell'atomo anche
     * dopo il conto in cui è nato: per questo non deve dipendere da loro. */
    conditions_on = domain_on = 0;
    Rat value = eval_body(node, rat_add(rat_int(lower), rat_atom(atom_var(VAR_SLACK)), 0));
    int positive = failure == saved && poly_is_positive(value.num) && poly_is_positive(value.den);
    failure = saved;
    conditions_on = recording;
    domain_on = domain;
    return positive;
}

/* Lo stato della regola 11n, il teorema del binomio (binomial_sum(), più
 * sotto). binomial_ok dice che la regola si può usare: lo decide chi poi la
 * dichiara nella dimostrazione scritta (induct(), capitolo 13), e
 * binomial_used gli dice se è stata usata. binomial_skip è il coefficiente
 * binomiale che la regola sta trattando come 1 mentre calcola il resto del
 * termine, o NULL; binomial_live dice che in quel conto la lettera
 * ausiliaria sta al posto dell'indice della somma, che è un intero. */
static int binomial_ok, binomial_used, binomial_live;
static const Node *binomial_skip;

/* Prototipo in avanti necessario: la regola valuta il termine della somma
 * (eval()) e ne eleva dei pezzi a potenza (power()), e la valutazione di una
 * somma la chiama. */
static int binomial_sum(const Node *node, long long lower, Rat upper, Rat *out);

/* Valuta una somma o un prodotto.
 *
 * Sia lower l'estremo inferiore (un intero) e a n + c il valore dell'estremo
 * superiore con le variabili legate attuali. Tre casi.
 *
 * 11a. a = 0: gli estremi sono numeri. Si svolge: il corpo viene valutato per
 *      ogni indice da lower a c e i risultati sommati (o moltiplicati). Se
 *      c = lower - 1 non ci sono termini e il risultato è 0 (o 1).
 *
 * 11b. a > 0: l'estremo dipende da n. Il risultato è un atomo, che rappresenta
 *      la somma fino a un estremo di riferimento a n + r, corretto con i
 *      termini di differenza:
 *
 *          somma fino ad a n + c  =  atomo + corpo(a n + r + 1) + ... + corpo(a n + c)
 *
 *      se c > r, e con i termini da c + 1 a r sottratti se c < r. Per i
 *      prodotti si moltiplica e si divide. È il cuore dell'induzione: con n+1
 *      al posto di n, la somma fino a n diventa "atomo più ultimo termine".
 *
 *      Il riferimento r è l'estremo con cui l'atomo viene chiesto la prima
 *      volta, cioè quello scritto nell'enunciato (la prima valutazione è con n
 *      legato a se stesso). Scegliere invece sempre r = 0 sarebbe sbagliato:
 *      per una somma da 5 a n + 10 l'atomo "somma da 5 a n" non avrebbe
 *      termini per n piccolo.
 *
 *      Il caso richiede che il corpo dipenda solo dal proprio indice e da
 *      parametri: se dipendesse da n, passando a n+1 cambierebbero tutti i
 *      termini e non basterebbe aggiungere l'ultimo; se dipendesse dall'indice
 *      di una somma esterna, lo stesso atomo indicherebbe somme diverse.
 *
 * 11n. Il termine dipende da n attraverso un coefficiente binomiale: la
 *      somma ha una forma chiusa, che dà il teorema del binomio
 *      (binomial_sum()). */
static Rat eval_bigop(const Node *node) {
    int product = node->op;
    long long lower, a, c;
    Rat upper = eval(node->b);
    if (!rat_integer(eval(node->a), &lower)) { fail("estremo inferiore di somma o prodotto non costante"); return rat_int(0); }
    if (!rat_affine(upper, &a, &c)) { fail("estremo superiore non della forma a n + c"); return rat_int(0); }

    /* 11a. Estremi numerici: si svolge. */
    if (a == 0) {
        if (c < lower - 1) { fail("somma o prodotto con estremo superiore troppo piccolo"); return rat_int(0); }
        if (c - lower >= MAX_UNROLL) { fail("somma o prodotto con troppi termini da svolgere"); return rat_int(0); }
        Rat total = rat_int(product ? 1 : 0);
        for (long long k = lower; k <= c && !failure; k++) {
            Rat value = eval_body(node, rat_int(k));
            total = product ? rat_mul(total, value) : rat_add(total, value, 0);
        }
        return total;
    }

    /* 11b. Estremo che dipende da n: atomo più termini di differenza. */
    if (a < 0) { fail("estremo superiore decrescente in n"); return rat_int(0); }
    NameScope index_scope = {node->name, NULL};
    if (uses_bound_variable(node->a, NULL) || uses_bound_variable(node->c, &index_scope)) {
        /* 11n. */
        Rat closed;
        if (!product && binomial_ok && binomial_sum(node, lower, upper, &closed)) {
            /* Come in 11b: la somma deve avere almeno un termine, e N = a n + c
             * deve essere un naturale. */
            long long need = lower - c;
            need = (need > 0) ? (need + a - 1) / a : -((-need) / a);
            if (library_depth == 0 && need > default_base) default_base = need;
            binomial_used = 1;
            return closed;
        }
        fail("somma o prodotto il cui termine dipende da n: aggiungere l'ultimo termine non basta");
        return rat_int(0);
    }
    int known = atom_count;
    int atom = atom_bigop(node, a, c);
    long long reference = atoms[atom].offset;

    /* Alla nascita di un atomo prodotto si stabilisce se è positivo: lo usano
     * radici e logaritmi (vedi factorize()). */
    if (atom_count > known && product) atoms[atom].positive = body_is_positive(node, lower);
    if (c - reference > MAX_UNROLL || reference - c > MAX_UNROLL) { fail("troppi termini di differenza"); return rat_int(0); }

    /* Solo le somme scritte nell'enunciato decidono il caso base: devono avere
     * almeno un termine, cioè a n + c >= lower. */
    if (library_depth == 0) {
        long long need = lower - c;
        need = (need > 0) ? (need + a - 1) / a : -((-need) / a);
        if (need > default_base) default_base = need;
    }

    Rat total = rat_atom(atom);
    Rat an = rat_mul(rat_int(a), rat_atom(atom_var(induction_var)));
    for (long long j = reference + 1; j <= c && !failure; j++) {
        Rat value = eval_body(node, rat_add(an, rat_int(j), 0));
        total = product ? rat_mul(total, value) : rat_add(total, value, 0);
    }
    for (long long j = c + 1; j <= reference && !failure; j++) {
        Rat value = eval_body(node, rat_add(an, rat_int(j), 0));
        rewriting = product;
        total = product ? rat_div(total, value) : rat_add(total, value, 1);
        rewriting = 0;
    }
    return total;
}

/* Valuta X(index) per la successione s del vocabolario definita per ricorrenza
 * (caso 10b), con index = a n + c.
 *
 * Si tiene una finestra di d valori consecutivi X(t), ..., X(t+d-1) e la si fa
 * scorrere di un posto alla volta:
 *
 *   avanti:   X(t+d) = coef[0] X(t+d-1) + ... + coef[d-1] X(t)
 *   indietro: X(t-1) = (X(t+d-1) - coef[0] X(t+d-2) - ... - coef[d-2] X(t)) / coef[d-1]
 *
 * La seconda è la prima risolta rispetto al termine più vecchio.
 *
 * Se a = 0 la finestra parte dai valori iniziali X(0), ..., X(d-1), che sono
 * numeri, e dopo c passi contiene il numero X(c). Se a > 0 parte dagli atomi
 * X(a n), ..., X(a n + d - 1), e dopo c passi esprime X(a n + c) come loro
 * combinazione: per Fibonacci, F(n+2) = F(n) + F(n+1). */
static Rat eval_recurrence(int sequence, Rat index) {
    const Sequence *s = &library[sequence];
    int d = s->order;
    long long a, c;
    if (!rat_affine(index, &a, &c) || a < 0) { fail("indice di successione non della forma a n + c"); return rat_int(0); }
    if (c > MAX_UNROLL || c < -MAX_UNROLL) { fail("indice di successione troppo lontano"); return rat_int(0); }

    /* Finestra iniziale. */
    Rat window[MAX_ORDER];
    for (int j = 0; j < d; j++)
        window[j] = (a == 0) ? rat_int(s->init[j]) : rat_atom(atom_rec(sequence, a, j));

    /* Passi in avanti. */
    for (long long step = 0; step < c && !failure; step++) {
        Rat next = rat_int(0);
        for (int i = 0; i < d; i++) next = rat_add(next, rat_mul(rat_int(s->coef[i]), window[d - 1 - i]), 0);
        for (int j = 0; j + 1 < d; j++) window[j] = window[j + 1];
        window[d - 1] = next;
    }

    /* Passi all'indietro. */
    for (long long step = 0; step < -c && !failure; step++) {
        Rat previous = window[d - 1];
        for (int i = 0; i + 1 < d; i++)
            previous = rat_add(previous, rat_mul(rat_int(s->coef[i]), window[d - 2 - i]), 1);
        previous = rat_div(previous, rat_int(s->coef[d - 1]));
        for (int j = d - 1; j > 0; j--) window[j] = window[j - 1];
        window[0] = previous;
    }
    return window[0];
}

/* Valuta il termine di indice index della successione chiamata name. */
static Rat eval_sequence(int name, Rat index) {
    for (int i = 0; i < LIBRARY_COUNT; i++) {
        if (library[i].name != name) continue;
        if (!library[i].definition) return eval_recurrence(i, index);

        /* 10a: si valuta la formula con m legato all'indice. */
        env_push('m', index);
        library_depth++;
        Rat value = eval(library[i].tree);
        library_depth--;
        env_pop();
        return value;
    }
    fail("successione con pedice non presente nel vocabolario");
    return rat_int(0);
}

/* Moltiplica il monomio di out per atom^exp; con exp nullo non fa nulla. */
static void term_times(Term *out, int atom, Frac exp) {
    if (exp.num == 0) return;
    Mono factor = mono_atom(atom, exp);
    out->mono = mono_mul(&out->mono, &factor);
}

/* Toglie da *value il suo più piccolo fattore primo: mette il primo in *prime
 * e quante volte divide in *times. Ritorna 0, senza fare nulla, quando *value
 * è 1 o meno. Chiamata ripetutamente elenca la scomposizione in fattori primi.
 *
 * Si prova a dividere per 2, 3, 4, ...: il primo divisore trovato è per forza
 * primo, e se nessuno fino alla radice quadrata divide, il numero stesso è
 * primo. *value non deve superare 10^12, o il ciclo sarebbe troppo lungo. */
static int pop_prime(long long *value, long long *prime, long long *times) {
    if (*value <= 1) return 0;
    long long p = 2;
    while (p * p <= *value && *value % p != 0) p++;
    if (p * p > *value) p = *value;
    *prime = p;
    *times = 0;
    while (*value % p == 0) { *value /= p; (*times)++; }
    return 1;
}

/* Ritorna il monomio comune a tutti i termini di p, che non deve essere nullo:
 * per ogni atomo il minimo esponente tra i termini, contando zero dove manca.
 * Con esponenti negativi anche x^{-1} può essere comune:
 * x + 1/x = x^{-1} (x^2 + 1). */
static Mono poly_common(Poly p) {
    Mono common = p.term[0].mono;
    for (int i = 1; i < p.count; i++) {
        const Mono *other = &p.term[i].mono;
        Mono low;
        low.count = 0;
        int x = 0, y = 0;
        while (x < common.count || y < other->count) {
            Factor f;
            if (y == other->count || (x < common.count && common.factor[x].atom < other->factor[y].atom)) {
                /* Atomo assente nell'altro termine: conta zero, quindi resta
                 * comune solo un esponente negativo. */
                f = common.factor[x++];
                if (f.exp.num > 0) continue;
            } else if (x == common.count || other->factor[y].atom < common.factor[x].atom) {
                f = other->factor[y++];
                if (f.exp.num > 0) continue;
            } else {
                f = common.factor[x++];
                if (frac_cmp(other->factor[y].exp, f.exp) < 0) f.exp = other->factor[y].exp;
                y++;
            }
            low.factor[low.count++] = f;
        }
        common = low;
    }
    return common;
}

/* Ritorna l'atomo che rappresenta (atom)^m, con m un monomio. Se atom è già
 * una potenza b^{m'} il risultato è b^{m' m}, per la regola (b^p)^q = b^{pq}:
 * così (e^{i x})^n ed e^{i n x} sono lo stesso atomo. */
static int atom_raised(int atom, const Mono *m) {
    if (atoms[atom].kind != ATOM_POW) return atom_pow(BASE_ATOM, atom, m);
    Mono merged = mono_mul(&atoms[atom].exponent, m);
    return atom_pow(atoms[atom].base, atoms[atom].id, &merged);
}

/* Ritorna 1 se il monomio vale un numero intero per ogni n ammesso: è un
 * prodotto di potenze, a esponente intero positivo, di n e di atomi come 2^n.
 * Mentre la regola 11n calcola il termine di una somma conta come intero
 * anche la lettera ausiliaria, che lì sta al posto dell'indice. */
static int mono_is_integer(const Mono *m) {
    for (int i = 0; i < m->count; i++) {
        const Atom *a = &atoms[m->factor[i].atom];
        Frac e = m->factor[i].exp;
        if (e.den != 1 || e.num < 0) return 0;
        if (a->kind == ATOM_VAR && (a->id == induction_var || (a->id == VAR_SLACK && binomial_live))) continue;
        if (a->kind == ATOM_POW && a->base == BASE_PRIME && domain_floor >= 0 && mono_is_integer(&a->exponent)) continue;
        return 0;
    }
    return 1;
}

/* Ritorna p^{q m}, dove p è un polinomio non nullo, m un monomio non banale
 * (l'esponente simbolico, per esempio n) e q un razionale.
 *
 * Per riconoscere la stessa potenza scritta in modi diversi, p viene scomposto
 * in fattori di cui si eleva ciascuno separatamente, usando (u v)^e = u^e v^e:
 *
 *     p = (segno o unità immaginaria) * (numero razionale positivo)
 *         * (monomio comune a tutti i termini) * (polinomio primitivo)
 *
 *   11c. Il segno: (-1)^{q m} = e^{i pi q m}. L'unità immaginaria i, che
 *        compare con i seni, è e^{i pi/2}, quindi dà e^{i pi q m / 2}.
 *   11d. Il numero: si scompone in fattori primi, ognuno con il suo atomo.
 *        Così 4^n = (2^n)^2 e 6^n = 2^n 3^n.
 *   11e. Il monomio comune: ogni suo atomo viene elevato con atom_raised().
 *   11f. Il polinomio primitivo, cioè ciò che resta: ha coefficienti interi
 *        senza divisori comuni e primo coefficiente positivo, quindi è lo
 *        stesso per tutti i multipli di p. Se non è 1 diventa la base di un
 *        atomo.
 *
 * La regola (u v)^e = u^e v^e vale per e intero ma non in generale: con basi
 * negative ed esponente non intero può fallire. Per questo la scomposizione si
 * fa solo quando l'esponente q m è un intero per ogni n (11b'); altrimenti la
 * base resta un blocco unico e diventa un atomo così com'è. */
/* Prototipi in avanti inevitabili: le potenze che fanno da lettere sono
 * della ricerca del capitolo 18 (18x), che conosce le variabili generiche;
 * qui servono solo a fondere gli esponenti, (x^{n})^{m} = x^{n m}, che per
 * una base positiva e esponenti interi è vero. Fuori dalla ricerca
 * power_letter() ritorna sempre 0. */
static int power_letter(int atom);
static int power_exponent(const Mono *m);

static Rat symbolic_power(Poly p, const Mono *m, Frac q) {
    Term out;
    out.coef = num_int(1);
    out.mono.count = 0;
    if (p.count == 0) { fail("zero elevato a un esponente simbolico"); return rat_int(0); }

    /* 11b'. Esponente non intero: nessuna scomposizione. Se la base è un solo
     * atomo lo si eleva direttamente, e una potenza di un primo, che è
     * positiva, può ancora fondere gli esponenti: (2^n)^x = 2^{n x}. */
    if (q.den != 1 || !mono_is_integer(m)) {
        const Term *only = &p.term[0];
        int single = p.count == 1 && only->mono.count == 1 && num_equal(only->coef, num_int(1)) &&
                     only->mono.factor[0].exp.num == 1 && only->mono.factor[0].exp.den == 1;
        int atom = single ? only->mono.factor[0].atom : 0;
        if (single && atoms[atom].kind == ATOM_POW && (atoms[atom].base == BASE_PRIME || (q.den == 1 && power_letter(atom) && power_exponent(m))))
            term_times(&out, atom_raised(atom, m), q);
        else if (single) term_times(&out, atom_pow(BASE_ATOM, atom, m), q);
        else term_times(&out, atom_pow(BASE_POLY, base_poly_intern(p), m), q);
        return (Rat){poly_term(out), poly_const(num_int(1))};
    }

    /* Monomio comune, e ciò che resta dopo averlo raccolto. */
    Mono common = poly_common(p);
    Term divisor;
    divisor.coef = num_int(1);
    divisor.mono = mono_pow(&common, frac_int(-1));
    Poly rest = poly_mul(p, poly_term(divisor));
    if (failure || rest.count == 0) return rat_int(0);

    /* Contenuto numerico. Se tutti i coefficienti sono immaginari puri si
     * raccoglie i; se sono misti non si raccoglie nulla. */
    int imaginary = 1, real = 1;
    for (int i = 0; i < rest.count; i++) {
        if (rest.term[i].coef.re.num != 0) imaginary = 0;
        if (rest.term[i].coef.im.num != 0) real = 0;
    }
    Frac content = frac_int(1);
    if (real || imaginary) {
        /* Massimo comun divisore dei numeratori diviso minimo comune multiplo
         * dei denominatori, con il segno del primo coefficiente. */
        __int128 g = 0, l = 1;
        for (int i = 0; i < rest.count; i++) {
            Frac v = imaginary ? rest.term[i].coef.im : rest.term[i].coef.re;
            g = gcd128(g, v.num);
            l = l / gcd128(l, v.den) * v.den;
            if (l >= COEF_LIMIT) { fail("numeri troppo grandi per il calcolo esatto"); return rat_int(0); }
        }
        Frac first = imaginary ? rest.term[0].coef.im : rest.term[0].coef.re;
        content = frac_make(first.num < 0 ? -g : g, l);
        divisor.coef = num_inv(imaginary ? (Num){frac_int(0), content} : num_frac(content));
        divisor.mono.count = 0;
        rest = poly_mul(rest, poly_term(divisor));
    }

    /* 11c. Segno e unità immaginaria. */
    if (content.num < 0 || imaginary) {
        Mono pi = mono_atom(atom_var(VAR_PI), frac_int(1));
        Mono turn = mono_mul(m, &pi);
        int e = atom_pow(BASE_EI, 0, &turn);
        if (content.num < 0) term_times(&out, e, q);
        if (imaginary) term_times(&out, e, frac_div(q, frac_int(2)));
    }

    /* 11d. Fattori primi di numeratore e denominatore del contenuto. */
    for (int side = 0; side < 2; side++) {
        long long value = side ? content.den : (content.num < 0 ? -content.num : content.num);
        long long prime, times;
        if (value > 1000000000000LL) { fail("numero troppo grande da scomporre in fattori primi"); return rat_int(0); }
        while (pop_prime(&value, &prime, &times))
            term_times(&out, atom_pow(BASE_PRIME, prime, m), frac_mul(frac_int(side ? -times : times), q));
    }

    /* 11e. Monomio comune. */
    for (int i = 0; i < common.count; i++)
        term_times(&out, atom_raised(common.factor[i].atom, m), frac_mul(common.factor[i].exp, q));

    /* 11f. Polinomio primitivo. */
    if (!poly_is_one(rest)) term_times(&out, atom_pow(BASE_POLY, base_poly_intern(rest), m), q);

    return (Rat){poly_term(out), poly_const(num_int(1))};
}

/* Un fattore di una scomposizione: base elevata a power. La base è descritta
 * come negli atomi POW: un primo, un atomo, o un polinomio di `base_polys`. */
typedef struct {
    BaseKind kind;
    long long id;
    Frac power;
} Part;

/* La scomposizione di un polinomio p in fattori di cui è noto il segno:
 * p = (prodotto delle part) * rest. Ogni part ha base non negativa per tutti
 * gli n ammessi; rest raccoglie ciò di cui il segno non è noto, compreso il
 * segno stesso di p, e vale 1 quando non resta nulla. */
typedef struct {
    int count;             /* part valide */
    Part part[MAX_PARTS];
    Poly rest;
} Factorization;

/* Aggiunge alla scomposizione il fattore base^power, sommando l'esponente se
 * la base è già presente. */
static void part_add(Factorization *f, BaseKind kind, long long id, Frac power) {
    for (int i = 0; i < f->count; i++)
        if (f->part[i].kind == kind && f->part[i].id == id) {
            f->part[i].power = frac_add(f->part[i].power, power);
            return;
        }
    if (f->count == MAX_PARTS) { fail("troppi fattori in un radicando o nell'argomento di un logaritmo"); return; }
    f->part[f->count++] = (Part){kind, id, power};
}

/* Ritorna il polinomio c[0] + c[1] n + ... + c[degree] n^degree. */
static Poly poly_univariate(const long long *c, int degree) {
    int n = atom_var(induction_var);
    Term *buffer = terms_alloc(degree + 1);
    if (!buffer) return (Poly){0, NULL};
    int used = 0;
    for (int i = 0; i <= degree; i++) {
        if (c[i] == 0) continue;
        Term t;
        t.coef = num_int(c[i]);
        t.mono.count = 0;
        if (i > 0) t.mono = mono_atom(n, frac_int(i));
        buffer[used++] = t;
    }
    return poly_finish(buffer, degree + 1, used);
}

/* Mette in out i divisori positivi di value (positivo) e ne ritorna il numero,
 * oppure 0 se sono più di MAX_DIVISORS. I divisori vanno a coppie d e
 * value/d, quindi basta cercare d fino alla radice quadrata. */
static int divisors(long long value, long long *out) {
    int count = 0;
    for (long long d = 1; d * d <= value; d++) {
        if (value % d != 0) continue;
        if (count + 2 > MAX_DIVISORS) return 0;
        out[count++] = d;
        if (d != value / d) out[count++] = value / d;
    }
    return count;
}

/* Dice se a n + b divide il polinomio di coefficienti c[0..degree], cioè se
 * -b/a ne è una radice: ritorna 1 se lo è, 0 se non lo è, -1 se i numeri
 * escono dall'aritmetica esatta e non si può dire. Si calcola
 * a^degree * p(-b/a), che è l'intero somma dei c[i] (-b)^i a^{degree-i}, con
 * lo schema di Horner partendo dal coefficiente di grado più alto.
 *
 * Il terzo esito va tenuto distinto dal "no": chi conclude che un polinomio
 * non ha radici (capitolo 18) non può contare su una risposta data per
 * mancanza di cifre. */
static int is_root(const long long *c, int degree, long long a, long long b) {
    __int128 value = 0, a_power = 1;
    for (int i = degree; i >= 0; i--) {
        __int128 scaled, term;
        if (__builtin_mul_overflow(value, (__int128)-b, &scaled) ||
            __builtin_mul_overflow((__int128)c[i], a_power, &term) ||
            __builtin_add_overflow(scaled, term, &value))
            return -1;
        if (i > 0 && __builtin_mul_overflow(a_power, (__int128)a, &a_power)) return -1;
    }
    return value == 0;
}

/* Divide sul posto il polinomio c[0..degree] per a n + b. Ritorna 1 se la
 * divisione è esatta a coefficienti interi, lasciando in c[0..degree-1] il
 * quoziente; altrimenti ritorna 0 e c resta com'era.
 *
 * Se c = (a n + b) q, confrontando i coefficienti: c[degree] = a q[degree-1],
 * c[i] = a q[i-1] + b q[i], c[0] = b q[0]. Si ricavano i q dall'alto. */
static int deflate(long long *c, int degree, long long a, long long b) {
    long long q[MAX_UNIVARIATE + 1];
    if (c[degree] % a != 0) return 0;
    q[degree - 1] = c[degree] / a;
    for (int i = degree - 1; i >= 1; i--) {
        long long rest = c[i] - b * q[i];
        if (rest % a != 0) return 0;
        q[i - 1] = rest / a;
    }
    if (c[0] != b * q[0]) return 0;
    for (int i = 0; i < degree; i++) c[i] = q[i];
    c[degree] = 0;
    return 1;
}

/* Trova le radici razionali del polinomio c[0] + c[1] x + ... + c[degree]
 * x^degree, a coefficienti interi con c[degree] diverso da zero. Le mette,
 * distinte, in root[] (che deve avere degree + 1 posti) e ne ritorna il
 * numero; ritorna -1 se non riesce a stabilirle con certezza.
 *
 * Teorema delle radici razionali. Sia u/v una radice, con u e v interi senza
 * divisori comuni e v > 0. Sostituendo e moltiplicando per v^degree:
 *
 *     c[0] v^d + c[1] u v^{d-1} + ... + c[d] u^d = 0.
 *
 * Tutti i termini tranne il primo contengono u, quindi u divide c[0] v^d; non
 * avendo fattori in comune con v, divide c[0]. Allo stesso modo v divide
 * c[d]. Se c[0] non è zero i candidati sono dunque in numero finito, e
 * provandoli tutti si trovano tutte le radici razionali. Se c[0] è zero, lo
 * zero è una radice: si divide per x e si ricomincia. */
static int rational_roots(const long long *c, int degree, Frac *root) {
    int count = 0;

    /* Le potenze di x che dividono il polinomio danno la radice zero. */
    while (degree >= 1 && c[0] == 0) {
        if (!count) root[count++] = frac_int(0);
        c++;
        degree--;
    }
    if (degree < 1) return count;

    /* I candidati: -b/a con a divisore di c[degree] e b di c[0], primi tra
     * loro, con i due segni. is_root(c, degree, a, b) prova la radice -b/a. */
    long long lead[MAX_DIVISORS], tail[MAX_DIVISORS];
    int leads = divisors(llabs(c[degree]), lead), tails = divisors(llabs(c[0]), tail);
    if (!leads || !tails) return -1;
    for (int i = 0; i < leads; i++)
        for (int j = 0; j < tails; j++) {
            if (gcd128(lead[i], tail[j]) != 1) continue;
            for (int sign = -1; sign <= 1; sign += 2) {
                int found = is_root(c, degree, lead[i], sign * tail[j]);
                if (found < 0) return -1;
                if (found) root[count++] = frac_make(-sign * tail[j], lead[i]);
            }
        }
    return count;
}

/* Stacca da p i fattori di primo grado a n + b che sono non negativi per ogni
 * n ammesso: li aggiunge a f e ritorna il quoziente. Se p non è un polinomio
 * nella sola n a coefficienti interi lo ritorna com'è.
 *
 * Teorema delle radici razionali: se una frazione ridotta -b/a è radice di un
 * polinomio a coefficienti interi, allora a divide il coefficiente di grado
 * massimo e b divide il termine noto. I candidati sono quindi in numero
 * finito e si provano tutti. Ciò che resta dopo aver tolto i fattori di primo
 * grado (per esempio n^2 + n + 1) non viene scomposto oltre.
 *
 * a n + b è non negativo per n >= domain_floor quando a > 0 e lo è nel punto
 * più basso, n = domain_floor. */
static Poly split_linear_factors(Poly p, Factorization *f) {
    long long c[MAX_UNIVARIATE + 1], scale;

    /* Coefficienti di p, se è della forma richiesta: devono essere già interi,
     * perché il quoziente va restituito senza cambiarlo di un fattore. */
    int degree = poly_coefficients(p, atom_var(induction_var), c, &scale);
    if (degree < 0 || scale != 1) return p;

    /* Finché si trova una radice si stacca il fattore e si ricomincia: così
     * una radice multipla viene tolta più volte. */
    int found = 1, changed = 0;
    while (found && degree >= 1 && c[0] != 0) {
        long long lead[MAX_DIVISORS], tail[MAX_DIVISORS];
        int leads = divisors(llabs(c[degree]), lead), tails = divisors(llabs(c[0]), tail);
        found = 0;
        for (int x = 0; x < leads && !found; x++)
            for (int y = 0; y < tails && !found; y++)
                for (int sign = -1; sign <= 1 && !found; sign += 2) {
                    long long a = lead[x], b = sign * tail[y];
                    if (a * domain_floor + b < 0) continue;
                    if (is_root(c, degree, a, b) != 1 || !deflate(c, degree, a, b)) continue;
                    long long linear[2] = {b, a};
                    part_add(f, BASE_POLY, base_poly_intern(poly_univariate(linear, 1)), frac_int(1));
                    degree--;
                    found = changed = 1;
                }
    }
    return changed ? poly_univariate(c, degree) : p;
}

/* 11q. I FATTI DEL DOMINIO
 *
 * A che cosa servono. Molte uguaglianze tra espressioni in x si affermano
 * "dove i due membri sono definiti": che F' = f (30a), che la derivata di f
 * è g (27a). In ognuno di quei punti ogni radice di indice pari scritta in
 * un membro ha il radicando >= 0, ogni logaritmo scritto senza valore
 * assoluto ha l'argomento > 0, ogni potenza a esponente costante non intero
 * ha la base >= 0 (come u^{1/3}, 11o). Chi dimostra l'uguaglianza a mano li
 * usa: "dove \sqrt{x} è definita x >= 0, e lì \sqrt[3]{x} = (\sqrt[6]{x})^2".
 * Senza di loro il conto esatto non può: per x < 0 la radice cubica reale di
 * x è definita (11o) e la radice sesta no, e due atomi diversi restano
 * diversi.
 *
 * Che cosa sono. Un fatto è un polinomio negli atomi che vale >= 0 in ogni
 * punto in cui i due membri sono definiti. Si annota (domain_note()) nel
 * punto in cui la valutazione incontra l'operazione che lo chiede: il
 * radicando in fractional_power() con la lettura non negativa (odd = 0),
 * l'argomento in logarithm_of_positive(); e, nei casi dei valori assoluti di
 * derivative_identity() (27a), il segno scelto per ogni |u|. Vengono dai due
 * membri e da un'espressione che è definita dove l'uguaglianza si afferma:
 * la funzione di cui un membro è la derivata, la primitiva (vedi 12d). Si
 * usano in quattro modi:
 *
 *   11q-1. Un atomo reale x con il fatto x >= 0 è un fattore di segno noto
 *          per factorize(): la radice cubica di x diventa x^{1/3}, come il
 *          quadrato della radice sesta, invece di prendere due strade (11o
 *          per la prima, la base "x presa come lettera" per la seconda).
 *   11q-2. Un resto di segno non noto che è c w o c w^2, con w un fatto e c
 *          un razionale positivo, diventa un fattore di segno noto: così
 *          \sqrt{w^2} = w, come \sqrt{\cos^2 x} = \cos x dove \cos x >= 0;
 *          \sqrt{u v} = \sqrt{u} \sqrt{v} quando u >= 0 e v >= 0 sono fatti;
 *          la radice di una frazione i cui due termini sono fatti.
 *   11q-3. |u| = u se u >= 0 è un fatto, |u| = -u se lo è -u.
 *   11q-4. Un radicando perde le potenze intere delle radici che contiene:
 *          (\sqrt{u})^2 = u dove \sqrt{u} è definita. Così il radicando di
 *          \sqrt{1 - (\sqrt{1 - 2x})^2} è 2x, e la radice è \sqrt{2} \sqrt{x}.
 *
 * Perché è giusto. Sia D l'insieme dei punti in cui l'uguaglianza si
 * afferma: quelli in cui i due membri sono definiti (e la funzione derivata,
 * o la primitiva, lo è). Un fatto vale in ogni punto di D: è il valore, in
 * quel punto, di un radicando o di un argomento scritto in un'espressione
 * definita in D, calcolato con regole che in D sono identità, comprese
 * quelle che usano i fatti annotati prima (ognuno vero in D, per lo stesso
 * motivo: si ragiona sull'ordine in cui sono stati annotati). Ogni
 * riscrittura che usa un fatto sostituisce un'espressione con un'altra che
 * ha lo stesso valore in ogni punto di D. Quindi se L - R si riduce a zero,
 * L = R in ogni punto di D, che è proprio ciò che si afferma. In un caso dei
 * valori assoluti tutto questo vale nei punti di D in cui valgono i segni di
 * quel caso, e i casi insieme coprono D. Che D non sia vuoto non lo dice il
 * conto: lo dicono i numeri, perché DIMOSTRATO chiede almeno un punto di
 * prova in cui i due membri sono definiti e uguali (27h, 30b).
 *
 * Una riserva, che c'era già prima dei fatti: dove un fattore di segno noto
 * di un radicando si annulla, la scomposizione può chiedere più di quanto
 * l'espressione scritta chieda (\sqrt{x (x - 1)}, con x >= 0, diventa
 * \sqrt{x} \sqrt{x - 1}, che in x = 0 non è definita). Sono punti in cui il
 * fattore è zero, isolati se non lo è su un intervallo, e non interni a D;
 * le derivate e le primitive si affermano sugli intervalli aperti, dove il
 * conto copre ogni punto.
 *
 * Perché solo lì. Un fatto è vero in D e non fuori: x >= 0, che viene da
 * \sqrt{x}, è falso in x = -1, e con lui \sqrt{x^2} = x. Per questo i fatti
 * non devono entrare in nessuna decisione che parli di altri punti: un
 * FALSO (che dice qualcosa di un punto, e lo decidono i numeri, mai il test
 * di annullamento), un "esiste", la tabella dei segni (che dà il segno in
 * ogni punto di un intervallo, anche dove i fatti non valgono), le
 * condizioni di esistenza di 13c (da controllare, non da supporre), un
 * enunciato con \forall x \in \mathbb{R}, che parla anche dei punti in cui
 * un membro non è definito. domain_on lo accende solo vanishes_where_defined()
 * (12d), che chiamano solo i test di annullamento delle uguaglianze "dove i
 * due membri sono definiti", e lo spegne prima di tornare. Ciò che il conto
 * lascia dopo di sé, gli atomi e le loro basi, non dipende dai fatti: un
 * atomo è una quantità con un significato fisso, e i fatti scelgono solo
 * quali atomi scrivere. L'unica eccezione, il segno di un prodotto \prod
 * deciso quando il suo atomo nasce, è calcolata con i fatti spenti
 * (body_is_positive()). Oggi quel conto, come quello di binomial_sum(), nei
 * due test non avviene: lì n è legata a un numero, e le somme e i prodotti
 * si svolgono (11a). Spegnere i fatti costa una riga e tiene vera la
 * garanzia anche se un giorno avverrà.
 *
 * Che cosa manca. Dividere un resto per un fatto (\sqrt{w^2 v} con v non
 * costante resta un atomo); i fatti che non vengono da ciò che il conto
 * calcola, come |u| <= 1 per l'arcoseno o 1 - \cos x >= 0, che chiede
 * \sqrt{\frac{1 + \cos x}{1 - \cos x}} = \frac{|\sin x|}{1 - \cos x}
 * (vedi tests/derivatives/book_derivatives_beyond_about.tex). */

/* Ritorna 1 se r = c w per un razionale c > 0, che mette in *c. */
static int positive_multiple(Poly r, Poly w, Frac *c) {
    if (!poly_proportional(r, w)) return 0;
    Num ratio = num_mul(r.term[0].coef, num_inv(w.term[0].coef));
    *c = ratio.re;
    return ratio.im.num == 0 && ratio.re.num > 0;
}

/* Annota il fatto r >= 0, se è acceso il conto di un'uguaglianza dove i due
 * membri sono definiti. Il fatto è il polinomio num * den, che ha il segno
 * della frazione dove questa è definita. Una costante non dice nulla, e un
 * multiplo positivo di un fatto già annotato non si ripete. Oltre
 * MAX_DOMAIN_FACTS il fatto si perde: ne segue solo un conto meno
 * semplificato. */
static void domain_note(Rat r) {
    Frac c;
    if (!domain_on || failure) return;
    Poly p = poly_mul(r.num, r.den);
    if (p.count == 0 || (p.count == 1 && p.term[0].mono.count == 0)) return;
    for (int i = 0; i < domain_fact_count; i++)
        if (positive_multiple(p, domain_fact[i], &c)) return;
    if (domain_fact_count < MAX_DOMAIN_FACTS) domain_fact[domain_fact_count++] = p;
}

/* Ritorna 1 se un fatto dice che r >= 0 dove i due membri sono definiti,
 * cioè se num * den è un suo multiplo positivo; -1 se lo dice di -r; 0 se i
 * fatti non lo dicono, e sempre a fatti spenti. */
static int domain_sign(Rat r) {
    Frac c;
    if (!domain_on || failure || r.num.count == 0) return 0;
    Poly p = poly_mul(r.num, r.den), minus = poly_add(poly_const(num_int(0)), p, 1);
    for (int i = 0; i < domain_fact_count; i++) {
        if (positive_multiple(p, domain_fact[i], &c)) return 1;
        if (positive_multiple(minus, domain_fact[i], &c)) return -1;
    }
    return 0;
}

/* 11q-1. Ritorna 1 se l'atomo è reale e un fatto dice che è >= 0. */
static int domain_nonnegative(int atom) {
    return domain_on && atom_is_real(atom) && domain_sign(rat_atom(atom)) > 0;
}

/* 11q-2. Se rest, di segno non noto, è c w^k con w un fatto, k = 1 o 2 e c
 * un razionale positivo, aggiunge a f i fattori primi di c e la base w con
 * esponente k, e ritorna il polinomio 1, ciò che resta; altrimenti ritorna
 * rest. La base w è >= 0 per il fatto stesso, quindi è un fattore come gli
 * altri della scomposizione (vedi Factorization).
 *
 * I quadrati si cercano per primi: il radicando di \sqrt{1 - \sin^2 x} è
 * a sua volta un fatto, e riconoscerlo come tale (k = 1) non direbbe nulla
 * di nuovo, mentre come quadrato di \cos x, quando \cos x >= 0 è un fatto,
 * la radice si estrae. */
static Poly domain_split(Poly rest, Factorization *f) {
    for (int k = 2; k >= 1; k--)
        for (int i = 0; domain_on && !failure && i < domain_fact_count; i++) {
            Frac c;
            Poly power = k == 2 ? poly_mul(domain_fact[i], domain_fact[i]) : domain_fact[i];
            if (!positive_multiple(rest, power, &c)) continue;
            if (c.num > 1000000000000LL || c.den > 1000000000000LL) return rest;
            for (int side = 0; side < 2; side++) {
                long long value = side ? c.den : c.num, prime, times;
                while (pop_prime(&value, &prime, &times)) part_add(f, BASE_PRIME, prime, frac_int(side ? -times : times));
            }
            part_add(f, BASE_POLY, base_poly_intern(domain_fact[i]), frac_int(k));
            return poly_const(num_int(1));
        }
    return rest;
}

/* Scompone il polinomio non nullo p in fattori di segno noto (vedi
 * Factorization). Serve a radici e logaritmi, che si distribuiscono sui
 * fattori solo quando questi sono non negativi:
 *
 *     radice(u v) = radice(u) radice(v),    ln(u v) = ln(u) + ln(v).
 *
 * Tre passi, ognuno dei quali stacca fattori dal polinomio:
 *
 *   11k. Il monomio comune ai termini. I suoi atomi non negativi diventano
 *        fattori; gli altri finiscono in rest.
 *   11l. Il contenuto numerico: il massimo comun divisore dei coefficienti,
 *        scomposto in fattori primi. Il segno resta in rest.
 *   11m. I fattori di primo grado in n, con split_linear_factors().
 *
 * Se i coefficienti non sono tutti reali (succede con seni e coseni) si fa
 * solo il passo 11k. Nel conto di un'uguaglianza dove i due membri sono
 * definiti contano anche i fatti del dominio: un atomo >= 0 per un fatto è
 * di segno noto in 11k (11q-1), e il resto viene confrontato con i fatti
 * (11q-2). */
static Factorization factorize(Poly p) {
    Factorization f;
    f.count = 0;

    /* 11k. Monomio comune. */
    Mono common = poly_common(p);
    Term unknown;
    unknown.coef = num_int(1);
    unknown.mono.count = 0;
    for (int i = 0; i < common.count; i++) {
        int atom = common.factor[i].atom;
        if (atom_is_nonnegative(atom) || domain_nonnegative(atom)) part_add(&f, BASE_ATOM, atom, common.factor[i].exp);
        else term_times(&unknown, atom, common.factor[i].exp);
    }
    Term divisor;
    divisor.coef = num_int(1);
    divisor.mono = mono_pow(&common, frac_int(-1));
    Poly rest = poly_mul(p, poly_term(divisor));

    int real = 1;
    for (int i = 0; i < rest.count; i++)
        if (rest.term[i].coef.im.num != 0) real = 0;
    if (real && !failure) {
        /* 11l. Contenuto: massimo comun divisore dei numeratori diviso minimo
         * comune multiplo dei denominatori. */
        __int128 g = 0, l = 1;
        for (int i = 0; i < rest.count; i++) {
            g = gcd128(g, rest.term[i].coef.re.num);
            l = l / gcd128(l, rest.term[i].coef.re.den) * rest.term[i].coef.re.den;
            if (l >= COEF_LIMIT) { fail("numeri troppo grandi per il calcolo esatto"); break; }
        }
        Frac content = failure ? frac_int(1) : frac_make(g, l);
        if (content.num > 1000000000000LL || content.den > 1000000000000LL) fail("numero troppo grande da scomporre in fattori primi");
        for (int side = 0; side < 2 && !failure; side++) {
            long long value = side ? content.den : content.num, prime, times;
            while (pop_prime(&value, &prime, &times)) part_add(&f, BASE_PRIME, prime, frac_int(side ? -times : times));
        }
        divisor.coef = num_inv(num_frac(content));
        divisor.mono.count = 0;
        rest = poly_mul(rest, poly_term(divisor));

        /* 11m. Fattori di primo grado. */
        if (!failure) rest = split_linear_factors(rest, &f);
    }

    /* 11q-2. Il resto, se è un fatto o il quadrato di un fatto. */
    f.rest = domain_split(poly_mul(rest, poly_term(unknown)), &f);
    return f;
}

/* Ritorna base^q con q razionale non intero: una radice, o una sua potenza.
 *
 * Numeratore e denominatore della base vengono scomposti con factorize() e
 * ogni fattore u diventa l'atomo "u preso come lettera" elevato a q volte il
 * suo esponente: radice(12) = 2 radice(3) nasce così, da 12 = 2^2 * 3.
 *
 * Può restare una parte di segno non noto, per esempio n + a con a parametro.
 * Se resta in uno solo tra numeratore e denominatore la si tratta come gli
 * altri fattori: la base è non negativa per ipotesi (altrimenti la radice non
 * sarebbe definita) e tutti gli altri fattori lo sono, quindi lo è anche lei.
 * Se resta in entrambi non si può dire nulla dei due segni presi da soli, e si
 * rinuncia.
 *
 * 11o. Le radici di indice dispari. Con odd diverso da zero q ha il
 * denominatore dispari m, e la radice è quella reale, definita anche per una
 * base negativa: la radice cubica di -8 è -2. È la lettura di \sqrt[3]{u}
 * nei libri; u^{1/3} scritto come potenza resta invece definito solo per
 * u >= 0, come e^{(1/3) ln u}. La radice reale di indice dispari rispetta i
 * prodotti senza condizioni sui segni, (u v)^{1/m} = u^{1/m} v^{1/m} per
 * ogni u e v reali, perché t -> t^m è una funzione crescente da R in R che
 * rispetta i prodotti, e quindi lo fa anche la sua inversa; e (-1)^{1/m} =
 * -1. Così la parte di segno non noto si distribuisce come le altre: ogni
 * atomo del suo monomio comune riceve il suo esponente (la radice cubica di
 * x^5 è x^{5/3}), il segno esce come (-1)^p con q = p/m, e il polinomio che
 * resta diventa un atomo. Nessuna condizione da annotare.
 *
 * Nel conto di un'uguaglianza dove i due membri sono definiti (11q) la base
 * perde prima le potenze intere delle radici che contiene (11q-4), e con la
 * lettura non negativa (odd = 0) diventa un fatto: base >= 0 lì dove la
 * radice è definita. Una radice dispari non dà fatti, perché è definita per
 * ogni base; ma se un fatto dice che la base è >= 0, factorize() la
 * scompone tutta in fattori di segno noto, e la radice dispari prende la
 * strada di quella pari: per una base >= 0 le due letture coincidono.
 *
 * Prototipo in avanti necessario: 11q-4 usa la regola 12a, che sta nel
 * capitolo del test di annullamento. */
static Poly poly_reduce_radicals(Poly p, int keep_value);
static Rat fractional_power(Rat base, Frac q, int odd) {
    Term out;
    Mono none;
    out.coef = num_int(1);
    out.mono.count = none.count = 0;

    /* 11q-4. (\sqrt{u})^2 = u dove \sqrt{u} è definita: il conto non cambia
     * valore in nessun punto in cui i due membri lo sono. Un denominatore
     * che diventa zero vuol dire che in quei punti la base non è mai
     * definita: il conto si ferma, senza dire di più (fail() e non
     * fail_undefined(), che direbbe qualcosa di un punto preciso). */
    if (domain_on) {
        base.num = poly_reduce_radicals(base.num, 1);
        base.den = poly_reduce_radicals(base.den, 1);
        if (base.den.count == 0) { fail("una radice con un denominatore che dove i due membri sono definiti vale zero"); return rat_int(0); }
        if (!odd) domain_note(base);
    }

    /* Zero: 0^q = 0 per q positivo. */
    if (base.num.count == 0) {
        if (q.num < 0) fail_undefined("zero elevato a un esponente negativo");
        return rat_int(0);
    }

    /* Con esponente negativo la base sta a denominatore. */
    if (q.num < 0) require(NEVER_ZERO, base.num, "zero elevato a un esponente negativo");

    Factorization side[2] = {factorize(base.num), factorize(base.den)};
    if (failure) return rat_int(0);
    int loose[2] = {!poly_is_one(side[0].rest), !poly_is_one(side[1].rest)};
    if (loose[0] && loose[1] && !odd) { fail("radice di una frazione in cui non si conosce il segno dei due termini"); return rat_int(0); }
    for (int s = 0; s < 2; s++) {
        Frac direction = frac_int(s ? -1 : 1);

        /* Fattori di segno noto. */
        for (int i = 0; i < side[s].count; i++) {
            const Part *part = &side[s].part[i];
            Frac e = frac_mul(frac_mul(part->power, q), direction);
            term_times(&out, part->kind == BASE_ATOM ? (int)part->id : atom_pow(part->kind, part->id, &none), e);
        }

        /* 11o. La parte di segno non noto, con una radice di indice
         * dispari: il monomio comune, il segno, il polinomio che resta. */
        if (loose[s] && odd) {
            Poly rest = side[s].rest;
            Mono common = poly_common(rest);
            for (int i = 0; i < common.count; i++) term_times(&out, common.factor[i].atom, frac_mul(frac_mul(common.factor[i].exp, q), direction));
            rest = poly_mul(rest, poly_term((Term){num_int(1), mono_pow(&common, frac_int(-1))}));
            if (rest.term[0].coef.im.num == 0 && rest.term[0].coef.re.num < 0) {
                rest = poly_add(poly_const(num_int(0)), rest, 1);
                if (q.num % 2) out.coef = num_neg(out.coef);
            }
            if (rest.count == 1 && rest.term[0].mono.count == 0 && !poly_is_one(rest)) { fail("radice di un numero complesso"); return rat_int(0); }
            if (!poly_is_one(rest)) term_times(&out, atom_pow(BASE_POLY, base_poly_intern(rest), &none), frac_mul(q, direction));
            continue;
        }

        /* Parte di segno non noto. Se è una costante è -1 (o un numero
         * complesso): la base è negativa e la radice non è definita. */
        if (!loose[s]) continue;
        if (side[s].rest.count == 1 && side[s].rest.term[0].mono.count == 0) { fail_undefined("radice di un numero negativo"); return rat_int(0); }

        /* Gli altri fattori sono non negativi: la base lo è se lo è questo. */
        require(NEVER_NEGATIVE, side[s].rest, "radice di un numero negativo");
        term_times(&out, atom_pow(BASE_POLY, base_poly_intern(side[s].rest), &none), frac_mul(q, direction));
    }
    return (Rat){poly_term(out), poly_const(num_int(1))};
}

/* Ritorna ln|x| come combinazione di atomi LN.
 *
 * Il logaritmo del valore assoluto trasforma prodotti in somme senza
 * condizioni sui segni: ln|u v| = ln|u| + ln|v| e ln|u^e| = e ln|u| per ogni
 * u e v non nulli. Si scompongono quindi numeratore e denominatore con
 * factorize() e si sommano i logaritmi dei fattori, ognuno con il suo
 * esponente. Dove l'enunciato scrive ln(x) con x positivo, ln|x| è lo stesso
 * numero.
 *
 * Una potenza p^M di un primo dà M ln(p), così ln(2^n) = n ln 2. */
static Rat logarithm(Rat x) {
    if (x.num.count == 0) { fail_undefined("logaritmo di zero"); return rat_int(0); }
    require(NEVER_ZERO, x.num, "logaritmo di zero");
    Rat total = rat_int(0);
    for (int s = 0; s < 2 && !failure; s++) {
        Factorization f = factorize(s ? x.den : x.num);

        /* Fattori di segno noto. */
        for (int i = 0; i < f.count && !failure; i++) {
            const Part *part = &f.part[i];
            Term t;
            t.coef = num_frac(part->power);
            t.mono.count = 0;
            if (part->kind == BASE_ATOM && atoms[part->id].kind == ATOM_POW && atoms[part->id].base == BASE_PRIME) {
                t.mono = atoms[part->id].exponent;
                term_times(&t, atom_ln(BASE_PRIME, atoms[part->id].id), frac_int(1));
            } else {
                term_times(&t, atom_ln(part->kind, part->id), frac_int(1));
            }
            total = rat_add(total, (Rat){poly_term(t), poly_const(num_int(1))}, s);
        }

        /* Parte di segno non noto. Una costante qui è -1, e ln|-1| = 0; un
         * polinomio dà un atomo, con il segno scelto in modo che p e -p, che
         * hanno lo stesso valore assoluto, diano lo stesso atomo. */
        Poly rest = f.rest;
        if (rest.count == 1 && rest.term[0].mono.count == 0) {
            if (rest.term[0].coef.im.num != 0) fail("logaritmo di un numero complesso");
            continue;
        }
        if (rest.count > 0 && rest.term[0].coef.im.num == 0 && rest.term[0].coef.re.num < 0)
            rest = poly_add(poly_const(num_int(0)), rest, 1);
        total = rat_add(total, rat_atom(atom_ln(BASE_POLY, base_poly_intern(rest))), s);
    }
    return total;
}

/* Ritorna ln(x) per un argomento scritto senza valore assoluto, che quindi
 * deve essere positivo. In generale è un'ipotesi dell'enunciato; quando x è un
 * numero la si controlla, e un argomento non positivo è un errore. Quando non
 * lo è, la condizione la annota chi chiama, che conosce l'argomento com'è
 * scritto (vedi require_positive()). Nel conto di un'uguaglianza dove i due
 * membri sono definiti, x > 0 è un fatto del dominio (11q). */
static Rat logarithm_of_positive(Rat x) {
    Num value;
    if (rat_number(x, &value) && (value.im.num != 0 || value.re.num <= 0)) {
        fail_undefined("logaritmo di un numero non positivo");
        return rat_int(0);
    }

    domain_note(x);
    return logarithm(x);
}

/* Argomenti degli atomi ATAN dell'enunciato in corso, ciascuno una volta:
 * l'atomo di id k vale l'arcotangente di atan_args[k]. */
static Rat atan_args[MAX_ATOMS];
static int atan_count;

/* Ritorna arctan(x) come combinazione di atomi.
 *
 * L'argomento deve essere reale. Tre regole portano arcotangenti uguali allo
 * stesso atomo:
 *
 *   - arctan(0) = 0;
 *   - l'arcotangente è dispari, arctan(-u) = -arctan(u): si tiene l'argomento
 *     con numeratore e denominatore di primo coefficiente positivo, e il segno
 *     esce fuori;
 *   - arctan(1) = pi/4, perché tan(pi/4) = 1. Tra gli argomenti razionali è
 *     l'unico valore, con 0, che sia un multiplo razionale di pi greco. */
static Rat arctangent(Rat x) {
    if (!poly_is_real(x.num) || !poly_is_real(x.den)) { fail("arcotangente di un'espressione che non è certamente reale"); return rat_int(0); }
    if (x.num.count == 0) return rat_int(0);

    /* Segno: lo si porta fuori. */
    int negative = 0;
    if (x.num.term[0].coef.re.num < 0) { x.num = poly_add(poly_const(num_int(0)), x.num, 1); negative = !negative; }
    if (x.den.term[0].coef.re.num < 0) { x.den = poly_add(poly_const(num_int(0)), x.den, 1); negative = !negative; }

    Rat value;
    if (poly_equal(x.num, x.den)) {
        value = rat_div(rat_atom(atom_var(VAR_PI)), rat_int(4));
    } else {
        /* Cerca un atomo con lo stesso argomento: p1/q1 = p2/q2 quando
         * p1 q2 = p2 q1. */
        int index = 0;
        while (index < atan_count &&
               !poly_equal(poly_mul(x.num, atan_args[index].den), poly_mul(atan_args[index].num, x.den)))
            index++;
        if (index == MAX_ATOMS) { fail("troppe arcotangenti distinte nell'enunciato"); return rat_int(0); }
        if (index == atan_count) atan_args[atan_count++] = x;

        Atom atom = {0};
        atom.kind = ATOM_ATAN;
        atom.id = index;
        atom.depends_on_n = poly_depends_on_n(x.num) || poly_depends_on_n(x.den);
        value = rat_atom(atom_intern(&atom));
    }
    return negative ? rat_add(rat_int(0), value, 1) : value;
}

/* Ritorna base^exponent.
 *
 * 11g. Esponente intero costante: moltiplicazioni ripetute.
 *
 * 11h. Altrimenti l'esponente deve essere un polinomio, cioè una somma di
 *      termini q M con q razionale e M monomio; poiché b^{u+v} = b^u b^v, si
 *      eleva un termine alla volta. Il termine costante (M = 1) è una potenza
 *      intera oppure, se q non è intero, una radice: fractional_power(). Gli
 *      altri passano da symbolic_power(), separatamente per numeratore e
 *      denominatore della base. Così 2^{n+1} diventa 2 * 2^n. */
static Rat power(Rat base, Rat exponent) {
    /* 11g. */
    long long e;
    if (rat_integer(exponent, &e)) return rat_pow_int(base, e);

    /* 11h. */
    if (!poly_is_one(exponent.den)) { fail("esponente con un denominatore che non è un monomio"); return rat_int(0); }
    Rat result = rat_int(1);
    for (int i = 0; i < exponent.num.count && !failure; i++) {
        const Term *t = &exponent.num.term[i];
        Frac q = t->coef.re;
        if (t->coef.im.num != 0) { fail("esponente complesso"); break; }
        if (t->mono.count == 0) {
            result = rat_mul(result, q.den == 1 ? rat_pow_int(base, q.num) : fractional_power(base, q, 0));
        } else {
            /* Un esponente simbolico negativo porta la base a denominatore;
             * uno che non è sempre intero vuole una base non negativa. */
            Mono m = t->mono;
            if (q.num < 0) require(NEVER_ZERO, base.num, "zero elevato a un esponente negativo");
            if (conditions_on && (q.den != 1 || !mono_is_integer(&m)))
                require(NEVER_NEGATIVE, poly_mul(base.num, base.den), "potenza a esponente non intero di un numero negativo");

            /* 1 elevato a qualunque esponente è 1: senza questo passo il
             * denominatore 1 di 2^{x} diventava un atomo (1)^{x}, e le
             * dimostrazioni di 18x lo scrivevano. */
            Rat top = poly_is_one(base.num) ? rat_int(1) : symbolic_power(base.num, &m, q);
            Rat bottom = poly_is_one(base.den) ? rat_int(1) : symbolic_power(base.den, &m, q);
            result = rat_mul(result, rat_div(top, bottom));
        }
    }
    return result;
}

/* 11n. IL TEOREMA DEL BINOMIO
 *
 * Una somma come \sum_{k=0}^{n} \binom{n}{k} \cos(kx) non si tratta
 * aggiungendo l'ultimo termine (11b): passando da n a n + 1 cambiano tutti i
 * termini, perché n sta nel coefficiente binomiale. Ha però una forma
 * chiusa. Per ogni naturale N e ogni numero y, anche complesso,
 *
 *     \sum_{k=0}^{N} \binom{N}{k} y^k = (1 + y)^N:
 *
 * è lo sviluppo del prodotto di N fattori (1 + y), in cui y^k si ottiene
 * scegliendo y da k fattori, e i modi di sceglierli sono \binom{N}{k}.
 * Sommando o sottraendo lo stesso sviluppo scritto per -y restano i termini
 * con k pari, o quelli con k dispari:
 *
 *     \sum_k \binom{N}{2k}   y^{2k}   = ((1 + y)^N + (1 - y)^N) / 2,
 *     \sum_k \binom{N}{2k+1} y^{2k+1} = ((1 + y)^N - (1 - y)^N) / 2,
 *
 * e qui k può arrivare fino a N, perché \binom{N}{m} è zero quando m > N.
 *
 * Come si applica. Il termine della somma deve essere il coefficiente
 * binomiale, che ha sopra l'estremo superiore N e sotto k, 2k oppure 2k + 1,
 * moltiplicato per un'espressione g(k). Si calcola g mettendo al posto
 * dell'indice la lettera ausiliaria t: se ogni termine del risultato
 * contiene t solo all'esponente di potenze b^{t M}, allora quel termine è
 * c y^t, con y il prodotto delle potenze b^M, e c e y senza t. Con
 * \cos(kx) = (e^{ikx} + e^{-ikx}) / 2 i termini sono due, con y = e^{ix} e
 * y = e^{-ix}. A ognuno si applica una delle tre formule; per 2k e 2k + 1,
 * dove g(k) = c r^k, serve un y con y^2 = r, che si ottiene dimezzando gli
 * esponenti (i due valori possibili, y e -y, danno lo stesso risultato).
 *
 * Che cosa resta fuori: g(k) con l'indice fuori dagli esponenti (k \binom{n}{k}),
 * due coefficienti binomiali nello stesso termine, un coefficiente con sotto
 * 3k o k + 1, una radice quadrata che non si sa scrivere, una base 1 + y
 * nulla quando N può essere zero. In tutti questi casi la regola non si
 * applica, e la somma resta non trattata.
 *
 * Che la forma chiusa sia quella giusta lo ricontrolla la verifica del
 * capitolo 13: con un numero al posto di n la somma viene svolta termine per
 * termine (11a), senza passare di qui.
 */

/* Ritorna il coefficiente binomiale per cui è moltiplicata l'espressione
 * node: lo si raggiunge scendendo solo per prodotti, segni meno e numeratori
 * di frazioni. NULL se non c'è. */
static const Node *binomial_factor(const Node *node) {
    if (node->kind == N_CALL && node->op == FN_BINOM) return node;
    if (node->kind == N_MUL) {
        const Node *found = binomial_factor(node->a);
        return found ? found : binomial_factor(node->b);
    }
    return node->kind == N_NEG || node->kind == N_DIV ? binomial_factor(node->a) : NULL;
}

/* Prototipo in avanti necessario: la base di un atomo è un polinomio, fatto
 * di atomi. */
static int poly_has_slack(Poly p);

/* Ritorna 1 se nell'atomo compare, a qualunque livello, la lettera
 * ausiliaria. */
static int atom_has_slack(int atom) {
    const Atom *a = &atoms[atom];
    if (a->kind == ATOM_VAR) return a->id == VAR_SLACK;
    if (a->kind == ATOM_ATAN) return poly_has_slack(atan_args[a->id].num) || poly_has_slack(atan_args[a->id].den);
    if (a->kind != ATOM_POW && a->kind != ATOM_LN) return 0;
    for (int i = 0; a->kind == ATOM_POW && i < a->exponent.count; i++)
        if (atom_has_slack(a->exponent.factor[i].atom)) return 1;
    if (a->base == BASE_ATOM) return atom_has_slack((int)a->id);
    return a->base == BASE_POLY && poly_has_slack(base_polys[a->id]);
}

/* Ritorna 1 se in p compare la lettera ausiliaria. */
static int poly_has_slack(Poly p) {
    for (int i = 0; i < p.count; i++)
        for (int f = 0; f < p.term[i].mono.count; f++)
            if (atom_has_slack(p.term[i].mono.factor[f].atom)) return 1;
    return 0;
}

/* Se il fattore `atom` elevato a e di un termine di g(t) è una potenza
 * b^{t M} (vedi 11n), moltiplica *y per ciò che diventa con 1 al posto di t,
 * elevato a e / halves: (b^M)^{e / halves}; halves è 1, oppure 2 quando serve
 * la radice quadrata. Ritorna 1 se ci riesce; 0 se t compare in un altro
 * modo, o se la potenza chiesta non si sa scrivere.
 *
 * Un esponente non intero si accetta solo dove non c'è da scegliere un ramo
 * della radice: sugli atomi e^{i M}, per cui (e^{i M})^q vuol dire e^{i q M},
 * e sui numeri: un primo ha il suo atomo "radice", e di un razionale che è
 * un quadrato, o il suo opposto, la radice è un razionale, per i se serve. */
static int binomial_ratio(int atom, Frac e, int halves, Rat *y) {
    const Atom *a = &atoms[atom];
    int slack = atom_var(VAR_SLACK);
    Frac inside = mono_exponent(&a->exponent, slack), q = frac_div(e, frac_int(halves));
    Mono rest = mono_with_exponent(&a->exponent, slack, frac_int(0)), none = {0};
    Num number;
    if (frac_cmp(inside, frac_int(1)) != 0) return 0;
    for (int i = 0; i < rest.count; i++)
        if (atom_has_slack(rest.factor[i].atom)) return 0;
    if ((a->base == BASE_ATOM && atom_has_slack((int)a->id)) || (a->base == BASE_POLY && poly_has_slack(base_polys[a->id]))) return 0;

    /* b^M: un atomo, oppure, con M = 1, la base stessa. Di un atomo e^{i M}
     * o p^M, e di un primo, si prende qualunque potenza razionale. */
    int letter = -1;
    Rat value;
    if (a->base == BASE_EI || rest.count > 0) letter = atom_pow(a->base, a->id, &rest);
    else if (a->base == BASE_PRIME) letter = atom_pow(BASE_PRIME, a->id, &none);
    if (a->base == BASE_PRIME && rest.count == 0) value = rat_int(a->id);
    else if (letter >= 0) value = rat_atom(letter);
    else if (a->base == BASE_ATOM) value = rat_atom((int)a->id);
    else value = (Rat){base_polys[a->id], poly_const(num_int(1))};
    if (q.den == 1) { *y = rat_mul(*y, rat_pow_int(value, q.num)); return !failure; }
    if (letter >= 0 && (a->base == BASE_EI || a->base == BASE_PRIME)) {
        Term power = {num_int(1), mono_atom(letter, q)};
        *y = rat_mul(*y, (Rat){poly_term(power), poly_const(num_int(1))});
        return !failure;
    }

    /* La radice quadrata di un numero: +-(u/v)^2. */
    if (q.den != 2 || !rat_number(value, &number) || number.im.num != 0 || number.re.num == 0) return 0;
    long long top = number.re.num < 0 ? -number.re.num : number.re.num, bottom = number.re.den, u = 0, v = 0;
    if (top > 1000000000000LL || bottom > 1000000000000LL) return 0;
    while (u * u < top) u++;
    while (v * v < bottom) v++;
    if (u * u != top || v * v != bottom) return 0;
    Rat root = {poly_const(number.re.num < 0 ? (Num){frac_int(0), (Frac){u, v}} : num_frac((Frac){u, v})), poly_const(num_int(1))};
    *y = rat_mul(*y, rat_pow_int(root, q.num));
    return !failure;
}

/* Ritorna base^upper per la regola 11n, dove upper = a n + c è l'estremo
 * superiore di una somma. È power(), tranne che per la base zero, che lì è
 * un errore: 0^N vale 0 quando N è almeno 1, cioè quando lo è per il più
 * piccolo n ammesso; se N può essere zero, dove 0^0 = 1, non c'è un valore
 * solo e resta un errore. Capita con y = -1: la somma a segni alterni dei
 * coefficienti binomiali è (1 - 1)^N. */
static Rat binomial_power(Rat base, Rat upper) {
    long long a, c;
    if (base.num.count == 0 && rat_affine(upper, &a, &c) && a > 0 && a * domain_floor + c >= 1) return rat_int(0);
    return power(base, upper);
}

/* 11n. Se la somma node, da lower a upper, ha per termine un coefficiente
 * binomiale per una somma di termini c y^k, come descritto sopra, mette in
 * *out la sua forma chiusa e ritorna 1. Ritorna 0, senza lasciare errori, se
 * la regola non si applica. upper è il valore dell'estremo superiore, a n + c
 * con a > 0. */
static int binomial_sum(const Node *node, long long lower, Rat upper, Rat *out) {
    const Node *binomial = binomial_factor(node->c);
    const char *saved = failure;
    int slack = atom_var(VAR_SLACK), listed = conditions_on, step = 0, shift = 0, fits = binomial && !failure && lower >= 0 && lower <= MAX_UNROLL;
    int domain = domain_on;
    Rat total = rat_int(0), one = rat_int(1), g = one;

    /* Il termine con t al posto dell'indice: sopra il coefficiente deve
     * esserci l'estremo superiore, sotto step t + shift; g è il resto. I
     * fatti del dominio (11q) valgono per i valori dell'enunciato, non per
     * la lettera t: la regola li spegne finché lavora. */
    domain_on = 0;
    if (fits) {
        env_push(node->name, rat_atom(slack));
        binomial_live = 1;
        Rat top = eval(binomial->a), bottom = eval(binomial->b);
        fits = !failure && rat_add(top, upper, 1).num.count == 0 && poly_is_one(bottom.den);
        for (int i = 0; fits && i < bottom.num.count; i++) {
            const Term *t = &bottom.num.term[i];
            int constant = t->mono.count == 0, linear = t->mono.count == 1 && t->mono.factor[0].atom == slack && frac_cmp(t->mono.factor[0].exp, frac_int(1)) == 0;
            if (t->coef.im.num != 0 || t->coef.re.den != 1 || (!constant && !linear)) fits = 0;
            else if (constant) shift = (int)t->coef.re.num;
            else step = (int)t->coef.re.num;
        }
        fits = fits && ((step == 1 && shift == 0) || (step == 2 && (shift == 0 || shift == 1)));
        if (fits) {
            binomial_skip = binomial;
            g = eval(node->c);
            binomial_skip = NULL;
        }
        binomial_live = 0;
        env_pop();
    }

    /* Un denominatore di un solo termine si porta nei termini del
     * numeratore; altrimenti non deve contenere t, e divide tutta la somma.
     * Da qui in poi i conti non sono dell'enunciato ma della regola, e le
     * loro divisioni non pongono condizioni. */
    conditions_on = 0;
    Poly pieces = g.num, below = poly_const(num_int(1));
    if (fits && !failure && g.den.count == 1) {
        Term inverse = {num_inv(g.den.term[0].coef), mono_pow(&g.den.term[0].mono, frac_int(-1))};
        pieces = poly_mul(g.num, poly_term(inverse));
    } else if (fits && !failure) {
        below = g.den;
        fits = !poly_has_slack(below);
    }

    /* Un termine alla volta: c, y e la sua forma chiusa. */
    for (int j = 0; fits && !failure && j < pieces.count; j++) {
        Term constant = {pieces.term[j].coef, {0}};
        Rat y = one;
        for (int f = 0; fits && f < pieces.term[j].mono.count; f++) {
            Factor factor = pieces.term[j].mono.factor[f];
            const Atom *a = &atoms[factor.atom];
            if (a->kind == ATOM_POW && mono_exponent(&a->exponent, slack).num != 0) fits = binomial_ratio(factor.atom, factor.exp, step, &y);
            else if (atom_has_slack(factor.atom)) fits = 0;
            else constant.mono = mono_mul(&constant.mono, &(Mono){1, {factor}});
        }
        if (!fits || failure) break;
        Rat c = {poly_term(constant), poly_const(num_int(1))}, plus = binomial_power(rat_add(one, y, 0), upper), closed = plus;
        if (step == 2) {
            /* y qui è la radice: y^2 è il rapporto tra due termini. */
            Rat minus = binomial_power(rat_add(one, y, 1), upper);
            if (y.num.count == 0) { fits = 0; break; }
            closed = rat_div(rat_add(plus, minus, shift), rat_mul(rat_int(2), rat_pow_int(y, shift)));
        }
        total = rat_add(total, rat_mul(c, closed), 0);
    }
    if (fits && !failure) total = rat_div(total, (Rat){below, poly_const(num_int(1))});
    conditions_on = listed;

    /* I termini prima di lower, che la formula conta e la somma no. */
    for (long long k = 0; fits && !failure && k < lower; k++) total = rat_add(total, eval_body(node, rat_int(k)), 1);
    domain_on = domain;
    if (!fits || failure) { failure = saved; return 0; }
    *out = total;
    return 1;
}

/* Ritorna e^{i sign theta}, con sign uguale a +1 o -1.
 *
 * L'angolo theta deve essere un polinomio: una somma di termini q M con q
 * razionale. Poiché e^{i (u + v)} = e^{i u} e^{i v}, il risultato è il
 * prodotto degli atomi e^{i M} elevati a q. Per esempio, con theta = (n+1) x/2
 * = n x/2 + x/2 si ottiene (e^{i n x})^{1/2} (e^{i x})^{1/2}: le formule di
 * addizione di seno e coseno sono già qui dentro. */
static Rat exp_i(Rat theta, int sign) {
    Term out;
    out.coef = num_int(1);
    out.mono.count = 0;
    if (!poly_is_one(theta.den)) { fail("angolo con un denominatore che non è un monomio"); return rat_int(0); }
    for (int i = 0; i < theta.num.count; i++) {
        const Term *t = &theta.num.term[i];
        if (t->coef.im.num != 0) { fail("angolo complesso"); return rat_int(0); }
        term_times(&out, atom_pow(BASE_EI, 0, &t->mono), frac_mul(t->coef.re, frac_int(sign)));
    }
    return (Rat){poly_term(out), poly_const(num_int(1))};
}

/* Raccoglie in factor[] i fattori in cui è scritta l'espressione del nodo, e
 * ne aggiorna il numero in *count. Un prodotto o un quoziente danno i fattori
 * dei due operandi; un segno meno dà il fattore -1; una potenza a esponente
 * dispari dà quelli della base. Tutto il resto è un fattore solo, il suo
 * valore: numeratore e denominatore.
 *
 * Una potenza a esponente pari non cambia il segno del prodotto, ma lo
 * annulla dove si annulla la base: se `positive` è diverso da zero si annota
 * a parte che la base non deve essere zero. Con troppi fattori ritorna 0. */
static int sign_factors(const Node *node, Poly *factor, int *count, int positive) {
    if (failure) return 0;
    if (node->kind == N_MUL || node->kind == N_DIV)
        return sign_factors(node->a, factor, count, positive) && sign_factors(node->b, factor, count, positive);
    if (node->kind == N_POW && node->b->kind == N_NUM && node->b->value % 2 == 0) {
        if (positive) require(NEVER_ZERO, eval(node->a).num, "logaritmo di zero");
        return 1;
    }
    if (node->kind == N_POW && node->b->kind == N_NUM) return sign_factors(node->a, factor, count, positive);

    /* Un segno meno, e poi ciò che nega; oppure un fattore così com'è. */
    Rat value = node->kind == N_NEG ? rat_int(-1) : eval(node);
    Poly piece[2] = {value.num, value.den};
    for (int i = 0; i < 2; i++) {
        if (poly_is_one(piece[i])) continue;
        if (*count == MAX_SIGN_FACTORS) return 0;
        factor[(*count)++] = piece[i];
    }
    return node->kind == N_NEG ? sign_factors(node->a, factor, count, positive) : 1;
}

/* Annota che l'argomento di un logaritmo, il nodo `argument` di valore x,
 * deve essere positivo. Il segno di un prodotto si decide meglio fattore per
 * fattore che sul prodotto svolto: di sin(a) cos(b) si sa dire il segno dei
 * due fattori, della somma di quattro esponenziali a cui si riduce no. Per
 * questo la condizione porta i fattori dell'argomento com'è scritto; se sono
 * troppi porta il prodotto di numeratore e denominatore del valore, che ha
 * lo stesso segno. */
static void require_positive(const Node *argument, Rat x) {
    const char *why = "logaritmo di un numero non positivo";
    Poly factor[MAX_SIGN_FACTORS];
    int count = 0;
    if (!conditions_on || failure) return;
    if (sign_factors(argument, factor, &count, 1) && count > 0) require_product(ALWAYS_POSITIVE, factor, count, why);
    else if (!failure) require(ALWAYS_POSITIVE, poly_mul(x.num, x.den), why);
}

/* I valori assoluti del confronto che la tabella dei segni (18p) sta
 * preparando: abs_node[i] è il nodo del valore assoluto numero i, e il bit i
 * di abs_pattern dice se in questo conto il suo argomento va preso con il
 * segno cambiato. Fuori da quei conti abs_count è zero. */
static const Node *abs_node[MAX_ABS];
static int abs_count;
static unsigned abs_pattern;

/* Le radici quadrate del confronto che la tabella dei segni (18p-7) sta
 * preparando: surd_node[i] è un nodo con il radicando numero i (radici con
 * lo stesso radicando scritto sono una sola), surd_letter[i] l'atomo che la
 * rappresenta, surd_inside[i] il radicando come frazione, e surd_value[i]
 * ciò che nei conti prende il posto della radice: la sua lettera, oppure un
 * prodotto di altre lettere quando la radice si ricava da quelle
 * (surd_relate()). Le più interne vengono prima, così un radicando contiene
 * solo le lettere delle radici precedenti. Fuori da quei conti surd_count è
 * zero. */
static const Node *surd_node[MAX_SURDS];
static int surd_letter[MAX_SURDS];
static Rat surd_inside[MAX_SURDS], surd_value[MAX_SURDS];
static int surd_count;

/* Il segno di un numero che può contenere radici quadrate di interi. È
 * definita nel capitolo 18.12 (18p), dopo il test di annullamento che le
 * serve; qui la usa il valore assoluto di un numero. */
static int number_sign(Rat r, int *side);

/* Gli esponenziali e i logaritmi nella tabella dei segni (18p-8): mentre la
 * tabella prepara un confronto, una potenza con la variabile all'esponente e
 * un logaritmo con la variabile nell'argomento diventano lettere, e sono
 * queste due funzioni a dirlo. Ritornano 1 e mettono in *out ciò che prende
 * il posto del nodo, oppure 0 se il nodo va calcolato come sempre. Sono
 * definite nel capitolo 18.9, con le altre lettere della tabella. */
static int exp_letters(const Node *node, Rat *out);
static int log_letter(const Node *node, Rat *out);

/* La radice di un prodotto di esponenziali (18p-8): se il radicando r di una
 * radice di indice index è un tale prodotto e la radice si estrae, la mette
 * in *out e ritorna 1. */
static int exp_root(Rat r, long long index, Rat *out);

/* Le funzioni goniometriche nella tabella dei segni (18p-11): mentre la
 * tabella prepara un confronto di un enunciato periodico, seno, coseno,
 * tangente e cotangente di a x + b pi diventano frazioni nella lettera
 * t = tan(g x / 2). trig_value() ritorna 1 e mette in *out ciò che prende
 * il posto del nodo, il cui argomento vale argument; 0 se il nodo va
 * calcolato come sempre. È definita nel capitolo 18.9. */
static int trig_value(const Node *node, Rat argument, Rat *out);

/* Valuta una chiamata di funzione. */
static Rat eval_call(const Node *node) {
    /* Il logaritmo di un valore assoluto è esattamente ciò che logarithm()
     * calcola, quindi lì il valore assoluto si attraversa. Altrove non c'è
     * ancora una regola per trattarlo. */
    const Node *argument = node->a;
    if ((node->op == FN_LN || node->op == FN_LOG) && argument->kind == N_CALL && argument->op == FN_ABS)
        argument = argument->a;
    int absolute = (argument != node->a);
    Rat letter;

    Rat x = eval(argument);
    switch ((Function)node->op) {
    case FN_FACT:
        return eval_sequence('!', x);

    case FN_BINOM: {
        /* Coefficiente binomiale "x su r".
         *
         * 11i. r intero costante: il prodotto di (x - r + j) / j per j da 1 a
         *      r, cioè x (x-1) ... (x-r+1) / r!. È un polinomio in x e vale
         *      anche quando x < r, dove dà correttamente zero.
         * 11j. r simbolico: x! / (r! (x-r)!), valida per 0 <= r <= x. */
        if (node == binomial_skip) return rat_int(1);  /* 11n: il resto del termine */
        Rat r = eval(node->b);
        long long count;
        if (rat_integer(r, &count)) {
            if (count < 0 || count > MAX_UNROLL) { fail("coefficiente binomiale con indice inferiore non valido"); return rat_int(0); }
            Rat result = rat_int(1);
            for (long long j = 1; j <= count && !failure; j++)
                result = rat_div(rat_mul(result, rat_add(x, rat_int(count - j), 1)), rat_int(j));
            return result;
        }
        Rat below = rat_mul(eval_sequence('!', r), eval_sequence('!', rat_add(x, r, 1)));
        return rat_div(eval_sequence('!', x), below);
    }

    case FN_SIN: case FN_COS: case FN_TAN: case FN_COT: {
        if (trig_value(node, x, &letter)) return letter;

        /* Formule di Eulero: con E = e^{i x},
         *     cos x = (E + 1/E) / 2,    sin x = (E - 1/E) / (2 i).
         * Dividere per 2 i equivale a moltiplicare per -i/2. */
        Rat forward = exp_i(x, 1), backward = exp_i(x, -1);
        Rat half = rat_div(rat_int(1), rat_int(2));
        Rat minus_half_i = {poly_const((Num){frac_int(0), (Frac){-1, 2}}), poly_const(num_int(1))};
        Rat cosine = rat_mul(rat_add(forward, backward, 0), half);
        Rat sine = rat_mul(rat_add(forward, backward, 1), minus_half_i);
        if (node->op == FN_SIN) return sine;
        if (node->op == FN_COS) return cosine;
        return node->op == FN_TAN ? rat_div(sine, cosine) : rat_div(cosine, sine);
    }

    case FN_ROOT: {
        /* La radice di indice r è la potenza 1/r. */
        long long index;
        if (!rat_integer(eval(node->b), &index) || index < 2) { fail("indice di radice non intero o minore di 2"); return rat_int(0); }

        /* Nella tabella dei segni una radice quadrata resta un simbolo. Lì la
         * variabile è un numero reale qualsiasi, e le semplificazioni di
         * fractional_power(), pensate per quantità positive, non valgono: la
         * radice di x^2 non è x. */
        if (exp_root(x, index, &letter)) return letter;
        for (int i = 0; i < surd_count && index == 2; i++)
            if (node_equal(surd_node[i]->a, node->a)) return surd_value[i];

        /* 11p. La radice m-esima di una potenza w^k scritta così: con m
         * dispari è w^{k/m} per ogni w reale (11o); con m pari e k dispari
         * è definita dove w^k >= 0, cioè dove w >= 0, e lì vale w^{k/m}. Con
         * m e k pari no: la radice quadrata di w^2 è |w|, non w, e resta la
         * regola di sempre. Serve perché la radice cubica di (x^3 + 1)^2 e
         * il quadrato di quella di x^3 + 1 siano lo stesso numero anche per
         * il conto: svolta la potenza, i due radicandi non si riconoscono. */
        const Node *power_node = node->a;
        if (power_node->kind == N_POW && power_node->b->kind == N_NUM && power_node->b->value >= 1 && power_node->b->value <= MAX_POWER &&
            (index % 2 || power_node->b->value % 2)) {
            Frac q = frac_make(power_node->b->value, index);
            Rat w = eval(power_node->a);
            return q.den == 1 ? rat_pow_int(w, q.num) : fractional_power(w, q, index % 2);
        }
        return fractional_power(x, (Frac){1, index}, index % 2);
    }

    case FN_LN:
        if (log_letter(node, &letter)) return letter;
        if (!absolute) require_positive(argument, x);
        return absolute ? logarithm(x) : logarithm_of_positive(x);

    case FN_LOG: {
        /* Cambio di base: il logaritmo di x in base b è ln x / ln b. */
        if (!node->b) { fail("logaritmo senza base: scrivere \\ln oppure \\log_{b}"); return rat_int(0); }
        if (log_letter(node, &letter)) return letter;
        if (!absolute) require_positive(argument, x);
        Rat above = absolute ? logarithm(x) : logarithm_of_positive(x);
        Rat below = eval(node->b);
        require_positive(node->b, below);
        return rat_div(above, logarithm_of_positive(below));
    }

    case FN_ARCTAN:
        return arctangent(x);

    case FN_ARCCOT:
        /* Con l'arcocotangente a valori in (0, pi), come nei libri di
         * scuola, arccot u = pi/2 - arctan u per ogni u reale: i due membri
         * sono continui, hanno la stessa cotangente, e stanno tutti e due
         * in (0, pi), dove la cotangente è iniettiva. */
        return rat_add(rat_div(rat_atom(atom_var(VAR_PI)), rat_int(2)), arctangent(x), 1);

    case FN_ARCSIN: case FN_ARCCOS:
        /* Non c'è una forma esatta che valga in tutto [-1, 1]: arcsin u =
         * arctan(u / sqrt(1 - u^2)) perde i due estremi, e un'espressione
         * che risultasse non definita dove lo è sbaglierebbe la tabella dei
         * segni. Di queste funzioni si calcolano le derivate (27f), che non
         * le contengono, e i valori con gli intervalli (capitolo 24). */
        fail("arcoseno e arcocoseno non hanno una forma per i conti esatti");
        return rat_int(0);

    case FN_ABS: {
        /* Di un numero reale il valore assoluto si calcola. Di un'espressione
         * no, perché |x| non è una funzione razionale di x: vale x oppure -x
         * secondo il segno. La tabella dei segni (18p) fa il conto una volta
         * per ogni scelta, e dice quale con abs_pattern. */
        Num value;
        int side;
        if (rat_number(x, &value) && value.im.num == 0) return value.re.num < 0 ? rat_add(rat_int(0), x, 1) : x;

        /* Il caso scelto per questo valore assoluto. Nel conto di
         * un'uguaglianza dove i due membri sono definiti (11q), il valore
         * scelto, x oppure -x, è >= 0 nei punti di quel caso: un fatto. */
        for (int i = 0; i < abs_count; i++)
            if (abs_node[i] == node || node_equal(abs_node[i], node)) {
                Rat chosen = (abs_pattern >> i & 1) ? rat_add(rat_int(0), x, 1) : x;
                domain_note(chosen);
                return chosen;
            }

        /* 11q-3. Un segno che dicono i fatti del dominio. */
        int known = domain_sign(x);
        if (known) return known < 0 ? rat_add(rat_int(0), x, 1) : x;

        /* Un numero con radici quadrate: il segno si trova stringendolo tra
         * due razionali (number_sign(), 18p). */
        if (number_sign(x, &side)) return side < 0 ? rat_add(rat_int(0), x, 1) : x;
        if (!failure) fail("valore assoluto non ancora supportato");
        return rat_int(0);
    }
    }
    return rat_int(0);
}

/* Ritorna 1 se il numero u divide il numero v, cioè se v è u per un numero
 * intero (17n): zero divide solo zero, e un altro numero divide v quando il
 * quoziente è intero. Vale per i razionali come è scritta: 1/2 divide 3. */
static int number_divides(Num u, Num v) {
    if (u.im.num != 0 || v.im.num != 0) return 0;
    if (u.re.num == 0) return v.re.num == 0;
    return frac_div(v.re, u.re).den == 1;
}

/* 11v. LE APPLICAZIONI DEFINITE PER CASI: QUALE CASO VALE
 *
 * f(t), con f definita per casi (17s), vale il valore del caso la cui
 * condizione vale in t. Quando t è un numero il caso si trova calcolando le
 * condizioni, e si prende il primo che vale: che i casi che valgono insieme
 * diano lo stesso numero lo ha dimostrato la regola 18v-6, prima di ogni
 * altra cosa, e lo ricontrolla map_holds_on_sample() (capitolo 19).
 *
 * Quando t contiene le variabili generiche di una dimostrazione, calcolare
 * non basta: il caso va dimostrato, per tutti i loro valori. Lo fa la regola
 * 18v-1, che annota la sua scelta in case_choice[]; qui la si legge
 * soltanto. Se manca, il conto fallisce con CASE_UNDECIDED, e
 * l'applicazione resta annotata in undecided_*: chi cerca una dimostrazione
 * ne ricava che cosa distinguere (18v-2) o quali casi provare (18v-3).
 */

/* Una scelta di caso per un'applicazione definita per casi: f(t) vale il
 * caso piece. La fa la dimostrazione dopo aver dimostrato la condizione del
 * caso (18v-1), oppure la impone per tentativo chi cerca un valore e poi
 * ricontrolla tutto (18v-3). Vale solo per quel nodo e per quel valore di t,
 * che cambia con le variabili legate. */
typedef struct {
    const Node *node;  /* l'applicazione f(t), nell'albero dell'enunciato */
    Rat argument;      /* il valore di t quando il caso è stato scelto */
    int piece;         /* il caso: un indice di piece[] nell'applicazione */
} CaseChoice;

/* Le scelte valide in questo momento, dalla più vecchia. Chi le aggiunge le
 * toglie quando ha finito, riportando il contatore dov'era. */
static CaseChoice case_choice[MAX_CASE_CHOICES];
static int case_choice_count;

/* Il motivo del fallimento di un conto che ha incontrato un'applicazione
 * definita per casi senza un caso scelto. Ha un nome perché chi cerca una
 * dimostrazione lo riconosce: non è un errore dell'enunciato. */
static const char *const CASE_UNDECIDED = "un'applicazione definita per casi è calcolata in un punto in cui il caso non è stabilito";

/* L'ultima applicazione che ha fatto fallire un conto con CASE_UNDECIDED: la
 * sua definizione, il suo nodo e il valore dell'argomento. */
static const Map *undecided_map;
static const Node *undecided_node;
static Rat undecided_argument;

/* Ritorna 1 se a e b sono scritte allo stesso modo, termine per termine. */
static int rat_same(Rat a, Rat b) { return poly_equal(a.num, b.num) && poly_equal(a.den, b.den); }

/* Calcola con i numeri la condizione c di un caso, in cui ogni variabile ha
 * un numero per valore: ritorna 1 se è vera, 0 se è falsa, -1 se un membro
 * non è un numero reale o il conto non riesce. */
static int condition_computed(const Formula *c) {
    Num u, v;
    if (c->kind == F_NOT) {
        int inner = condition_computed(c->a);
        return inner < 0 ? -1 : !inner;
    }
    if (c->kind == F_AND || c->kind == F_OR) {
        int x = condition_computed(c->a), y = condition_computed(c->b);
        if (x < 0 || y < 0) return -1;
        return c->kind == F_AND ? x && y : x || y;
    }
    int numbers = rat_number(eval(c->left), &u) && u.im.num == 0;
    if (c->kind != F_IN) numbers = numbers && rat_number(eval(c->right), &v) && v.im.num == 0;
    if (failure || !numbers) return -1;
    switch (c->kind) {
    case F_EQUAL:    return frac_cmp(u.re, v.re) == 0;
    case F_DISTINCT: return frac_cmp(u.re, v.re) != 0;
    case F_LESS:     return frac_cmp(u.re, v.re) < 0;
    case F_LESS_EQ:  return frac_cmp(u.re, v.re) <= 0;
    case F_DIVIDES:  return number_divides(u, v) != c->swapped;
    case F_IN:       return numbers_contain(&c->numbers, u.re) != c->swapped;
    default:         return -1;
    }
}

/* Calcola con i numeri quale caso di map vale nel punto argument: ritorna il
 * primo che vale, -1 se nessuno vale, -2 se il punto non è un numero o una
 * condizione non si calcola, perché nomina anche una variabile generica,
 * come un parametro (17s). */
static int case_computed(const Map *map, Rat argument) {
    Num t;
    if (!rat_number(argument, &t) || t.im.num != 0) return -2;
    for (int i = 0; i < map->cases && !failure; i++) {
        env_push(map->parameter, argument);
        int holds = condition_computed(map->piece[i].when);
        env_pop();
        if (holds) return holds > 0 ? i : -2;
    }
    return failure ? -2 : -1;
}

/* Ritorna il caso di map che vale per l'applicazione node, il cui argomento
 * vale argument, come descritto in testa al paragrafo; -1, con fail(), se
 * non lo si sa. */
static int case_of(const Map *map, const Node *node, Rat argument) {
    int computed = case_computed(map, argument);
    if (failure) return -1;
    if (computed >= 0) return computed;
    if (computed == -1) {
        fail_undefined("nessun caso della definizione vale in questo punto");
        return -1;
    }
    for (int i = case_choice_count - 1; i >= 0; i--)
        if (case_choice[i].node == node && rat_same(case_choice[i].argument, argument)) return case_choice[i].piece;
    undecided_map = map;
    undecided_node = node;
    undecided_argument = argument;
    fail(CASE_UNDECIDED);
    return -1;
}

/* Ritorna il valore del nodo con le variabili legate attuali. In caso di
 * errore `failure` è impostato e il valore non ha significato. */
static Rat eval(const Node *node) {
    /* Dopo un errore il risultato verrà scartato: ci si ferma subito, anche
     * per non svolgere somme con estremi privi di senso. */
    if (failure) return rat_int(0);

    switch (node->kind) {
    case N_NUM:
        return rat_int(node->value);
    case N_VAR: {
        const Rat *bound = env_lookup(node->name);
        return bound ? *bound : rat_atom(atom_var(node->name));
    }
    case N_SEQ:
        return eval_sequence(node->name, eval(node->a));
    case N_NEG:
        return rat_add(rat_int(0), eval(node->a), 1);
    case N_BIGOP:
        return eval_bigop(node);
    case N_CALL:
        return eval_call(node);
    case N_APPLY: {
        /* f(a) è la regola di f calcolata con la sua variabile legata ad a.
         * La regola non contiene altre lettere (lo controlla il capitolo 17),
         * quindi le variabili legate in questo momento non la toccano. */
        const Map *map = map_find(node->name);
        if (!map || (!map->body && !map->cases)) { fail("applicazione senza la regola che la definisce"); return rat_int(0); }

        /* Gli argomenti si calcolano prima di legare le variabili della
         * regola: in (a \ast b) \ast c, con la regola scritta in a e b,
         * la a dell'argomento è quella dell'enunciato. Per una definizione
         * per casi la regola è il valore del caso che vale (11v). */
        Rat first = eval(node->a);

        /* 17s. L'iterata f^{m}(a): con f^{c} = f, è f applicata m - c + 1
         * volte. Si calcola solo con m un numero; con m una lettera la
         * dimostra il capitolo 26 (26c), come una successione. */
        if (node->c) {
            long long m;
            if (!rat_integer(eval(node->c), &m)) { fail("un'iterata con l'esponente che non è un numero si dimostra solo per induzione"); return rat_int(0); }
            if (map->iterates != 3 || map->iterate_from != map->step_from || map->binary || m < map->iterate_from ||
                m - map->iterate_from >= MAX_UNROLL) {
                fail("un'iterata fuori dagli indici per cui le ipotesi la definiscono");
                return rat_int(0);
            }
            Node once = *node;
            once.c = NULL;
            for (long long k = map->iterate_from; k <= m && !failure; k++) {
                env_push(VAR_ITERATE, first);
                Node at = {N_VAR, 0, VAR_ITERATE, 0, NULL, NULL, NULL};
                once.a = &at;
                first = eval(&once);
                env_pop();
            }
            return first;
        }
        const Node *body = map->body;
        if (map->cases) {
            int piece = case_of(map, node, first);
            if (piece < 0) return rat_int(0);
            body = map->piece[piece].value;
        }
        if (map->binary) {
            Rat second = eval(node->b);
            env_push(map->parameter, first);
            env_push(map->parameter2, second);
        } else {
            env_push(map->parameter, first);
        }
        Rat value = eval(body);
        if (map->binary) env_pop();
        env_pop();
        return value;
    }
    case N_DERIV:
        /* Un segno di derivata che nessuno ha espanso (27j): non ha un
         * valore, e non va letto come nient'altro. */
        fail("un segno di derivata dentro un'espressione che il programma non ha calcolato");
        return rat_int(0);
    default:
        break;
    }

    /* Nella tabella dei segni una potenza con la variabile all'esponente è
     * un prodotto di lettere (18p-8). */
    Rat letters;
    if (node->kind == N_POW && exp_letters(node, &letters)) return letters;

    /* Operatori binari. I due operandi vanno valutati in istruzioni separate:
     * come argomenti della stessa chiamata il C non ne fisserebbe l'ordine, e
     * l'ordine decide con quale estremo nasce un atomo (vedi eval_bigop()). */
    Rat a = eval(node->a);
    Rat b = eval(node->b);
    switch (node->kind) {
    case N_ADD: return rat_add(a, b, 0);
    case N_SUB: return rat_add(a, b, 1);
    case N_MUL: return rat_mul(a, b);
    case N_DIV: return rat_div(a, b);
    default:    return power(a, b);
    }
}

/* =============================================================================
 * 12. TEST DI ANNULLAMENTO
 * ============================================================================
 *
 * "Questo polinomio è zero?" è la domanda a cui si riduce ogni dimostrazione.
 * Per quasi tutti gli atomi la risposta è nella forma canonica: è zero se non
 * ha termini. Due famiglie di atomi però soddisfano identità che la forma
 * canonica non vede, e vanno applicate qui.
 *
 *   12a. Radici. L'atomo "u preso come lettera", con u un polinomio, compare
 *        con esponenti frazionari: la radice quadrata di u è u^{1/2}. Ma
 *        u^1 non è una lettera nuova: è il polinomio u. Quindi di ogni
 *        esponente si separa la parte intera, che torna a essere il polinomio.
 *
 *   12b. Logaritmi. Una combinazione c1 ln|u1| + ... + ck ln|uk| con
 *        coefficienti interi è il logaritmo di |u1^c1 ... uk^ck|, quindi è
 *        zero quando quel prodotto vale 1 oppure -1. E quest'ultima è
 *        un'uguaglianza tra frazioni, senza più logaritmi.
 *
 *   12c. Arcotangenti. Per u reale, arctan(u) è l'argomento, cioè l'angolo,
 *        del numero complesso 1 + i u. Gli argomenti di un prodotto si
 *        sommano, quindi c1 arctan(u1) + ... + ck arctan(uk), con coefficienti
 *        interi, è l'argomento di Z = (1 + i u1)^c1 ... (1 + i uk)^ck, a meno
 *        di multipli di 2 pi. Se Z è un numero reale positivo il suo
 *        argomento è zero, e la combinazione è un multiplo di 2 pi; se
 *        inoltre è piccola in valore assoluto, quel multiplo è zero.
 *
 * Le tre regole sono vere identità, quindi un "sì" resta una dimostrazione.
 * Non sono complete: uno zero che dipende da altre identità (per esempio tra
 * radici di polinomi non scomposti) riceve un "no", e l'enunciato resta NON
 * DIMOSTRATO.
 *
 *   12d. Dove i due membri sono definiti. Il test di sempre, su L - R
 *        calcolata con i fatti del dominio (11q): vanishes_where_defined().
 *        Un "sì" vuol dire L = R in ogni punto in cui i due membri sono
 *        definiti, e non altrove: lo usano solo le uguaglianze che
 *        affermano questo, le derivate (27a) e le primitive (30a).
 */

/* Ritorna un polinomio che è zero se e solo se lo è p, in cui ogni atomo
 * "polinomio u preso come lettera" compare con esponente in [0, 1) (12a).
 *
 * Per un atomo x di base u: se k è il più piccolo tra le parti intere degli
 * esponenti di x (contando zero dove x manca), si moltiplica tutto p per
 * x^{-k}, che non cambia l'essere zero, e poi in ogni termine si sostituisce
 * la parte intera j dell'esponente con il polinomio u^j. I termini con la
 * stessa parte intera si raccolgono, e le potenze di u si moltiplicano con lo
 * schema di Horner: ((P_top u + P_{top-1}) u + ...) + P_k.
 *
 * Si procede dall'atomo creato per ultimo al primo: la base di un atomo
 * contiene solo atomi creati prima di lui, quindi sostituirla può far
 * comparire solo esponenti ancora da sistemare, mai già sistemati.
 *
 * Con keep_value diverso da zero il risultato deve avere anche lo stesso
 * valore di p, non solo lo stesso essere zero (serve a 11q-4): un atomo con
 * una parte intera negativa, che chiederebbe di moltiplicare per x^{-k}, si
 * lascia com'è. Con k = 0 la moltiplicazione non c'è, e la sostituzione di
 * u^j al posto di x^j è un'identità dove la radice è definita. */
static Poly poly_reduce_radicals(Poly p, int keep_value) {
    for (int x = atom_count - 1; x >= 0 && !failure; x--) {
        const Atom *atom = &atoms[x];
        if (atom->kind != ATOM_POW || atom->base != BASE_POLY || atom->exponent.count != 0) continue;

        /* Intervallo delle parti intere degli esponenti di x. */
        long long low = 0, high = 0;
        for (int i = 0; i < p.count; i++) {
            long long whole = frac_floor(mono_exponent(&p.term[i].mono, x));
            if (whole < low) low = whole;
            if (whole > high) high = whole;
        }
        if ((low == 0 && high == 0) || (keep_value && low < 0)) continue;
        if (high - low > MAX_POWER) { fail("esponente di una radice troppo grande"); break; }

        /* Horner, dalla parte intera più alta alla più bassa. */
        Poly result = poly_const(num_int(0));
        for (long long whole = high; whole >= low; whole--) {
            Term *buffer = terms_alloc(p.count);
            if (!buffer && p.count) return p;
            int used = 0;
            for (int i = 0; i < p.count; i++) {
                Term t = p.term[i];
                Frac e = mono_exponent(&t.mono, x);
                if (frac_floor(e) != whole) continue;
                t.mono = mono_with_exponent(&t.mono, x, frac_add(e, frac_int(-whole)));
                buffer[used++] = t;
            }
            Poly same = poly_finish(buffer, p.count, used);
            result = poly_add(poly_mul(result, base_polys[atom->id]), same, 0);
        }
        p = result;
    }
    return p;
}

/* Ritorna, come frazione, la base u dell'atomo ln|u| di indice atom. */
static Rat ln_base(int atom) {
    const Atom *a = &atoms[atom];
    if (a->base == BASE_PRIME) return rat_int(a->id);
    if (a->base == BASE_ATOM) return rat_atom((int)a->id);
    return (Rat){base_polys[a->id], poly_const(num_int(1))};
}

/* Ritorna 1 se p, non nullo, è una combinazione di logaritmi che vale zero
 * per la regola 12b.
 *
 * Ogni termine deve contenere un solo atomo LN, al primo grado. Il resto del
 * monomio è il suo "cofattore": i termini con lo stesso cofattore M formano un
 * gruppo M (c1 ln|u1| + ... + ck ln|uk|), e p è zero se lo è ogni gruppo.
 * I coefficienti razionali si rendono interi moltiplicando il gruppo per il
 * minimo comune multiplo dei denominatori. */
static int log_combination_vanishes(Poly p) {
    int *log_atom = arena_alloc((size_t)p.count * sizeof(int));
    Mono *cofactor = arena_alloc((size_t)p.count * sizeof(Mono));
    if (!log_atom || !cofactor) return 0;

    /* Separa in ogni termine l'atomo LN dal cofattore. */
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        log_atom[i] = -1;
        for (int f = 0; f < t->mono.count; f++) {
            if (atoms[t->mono.factor[f].atom].kind != ATOM_LN) continue;
            if (log_atom[i] >= 0 || t->mono.factor[f].exp.num != 1 || t->mono.factor[f].exp.den != 1) return 0;
            log_atom[i] = t->mono.factor[f].atom;
        }
        if (log_atom[i] < 0 || t->coef.im.num != 0) return 0;
        cofactor[i] = mono_with_exponent(&t->mono, log_atom[i], frac_int(0));
    }

    /* Un gruppo alla volta: il primo termine non ancora trattato e tutti
     * quelli con il suo stesso cofattore. log_atom[j] = -1 segna i trattati. */
    for (int i = 0; i < p.count; i++) {
        if (log_atom[i] < 0) continue;

        /* Minimo comune multiplo dei denominatori dei coefficienti. */
        long long scale = 1;
        for (int j = i; j < p.count; j++) {
            if (log_atom[j] < 0 || mono_cmp(&cofactor[j], &cofactor[i]) != 0) continue;
            long long den = p.term[j].coef.re.den;
            scale = scale / (long long)gcd128(scale, den) * den;
            if (scale > MAX_POWER) return 0;
        }

        /* Il prodotto delle basi, ognuna elevata al proprio coefficiente. */
        Rat product = rat_int(1);
        for (int j = p.count - 1; j >= i; j--) {
            if (log_atom[j] < 0 || mono_cmp(&cofactor[j], &cofactor[i]) != 0) continue;
            long long e = p.term[j].coef.re.num * (scale / p.term[j].coef.re.den);
            product = rat_mul(product, rat_pow_int(ln_base(log_atom[j]), e));
            log_atom[j] = -1;
        }
        if (failure) return 0;

        /* Il gruppo è zero se il prodotto vale 1 oppure -1. */
        if (poly_reduce_radicals(poly_add(product.num, product.den, 1), 0).count != 0 &&
            poly_reduce_radicals(poly_add(product.num, product.den, 0), 0).count != 0)
            return 0;
    }
    return 1;
}

/* Ritorna 1 se p, non nullo, è una combinazione di arcotangenti che vale zero
 * per la regola 12c.
 *
 * Come per i logaritmi, ogni termine deve contenere un solo "angolo" al primo
 * grado, e i termini si raggruppano per cofattore. Un angolo è un atomo ATAN
 * oppure pi greco, che si riscrive come 4 arctan(1).
 *
 * Per un gruppo c1 arctan(u1) + ... + ck arctan(uk), con i coefficienti resi
 * interi e uj = pj/qj:
 *
 *   - Il segno di Z. Invece di dividere, si moltiplica per i coniugati:
 *     Z è un reale positivo esattamente quando lo è
 *
 *         W = prodotto dei (1 + i sj uj)^|cj|,   sj = segno di cj,
 *
 *     perché W è Z per il quadrato del modulo dei fattori a esponente
 *     negativo. Scrivendo 1 + i sj uj = (qj + i sj pj)/qj, W è la frazione
 *     V/Q con V = prodotto dei (qj + i sj pj)^|cj| e Q = prodotto dei
 *     qj^|cj|. Si chiede che V non abbia parte immaginaria e che V Q sia
 *     evidentemente positivo: V e Q hanno allora lo stesso segno.
 *
 *   - La grandezza. Ogni arcotangente è minore di pi/2 in valore assoluto, e
 *     arctan(1) vale esattamente pi/4. Contando 2 per ogni arcotangente e 1
 *     per ogni arctan(1), se il totale pesato con |cj| non supera 8 la
 *     combinazione è minore di 8 * pi/4 = 2 pi in valore assoluto: l'unico
 *     multiplo di 2 pi possibile è zero. Serve almeno un'arcotangente diversa
 *     da arctan(1), altrimenti la disuguaglianza non sarebbe stretta. */
static int arctan_combination_vanishes(Poly p) {
    int pi = atom_var(VAR_PI);
    int *angle = arena_alloc((size_t)p.count * sizeof(int));
    Mono *cofactor = arena_alloc((size_t)p.count * sizeof(Mono));
    if (!angle || !cofactor) return 0;

    /* Separa in ogni termine l'angolo dal cofattore. */
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        angle[i] = -1;
        for (int f = 0; f < t->mono.count; f++) {
            int atom = t->mono.factor[f].atom;
            if (atoms[atom].kind != ATOM_ATAN && atom != pi) continue;
            if (angle[i] >= 0 || t->mono.factor[f].exp.num != 1 || t->mono.factor[f].exp.den != 1) return 0;
            angle[i] = atom;
        }
        if (angle[i] < 0 || t->coef.im.num != 0) return 0;
        cofactor[i] = mono_with_exponent(&t->mono, angle[i], frac_int(0));
    }

    /* Un gruppo alla volta, come in log_combination_vanishes(). */
    for (int i = 0; i < p.count; i++) {
        if (angle[i] < 0) continue;

        /* Coefficienti interi: minimo comune multiplo dei denominatori, dopo
         * aver contato pi greco come 4 arctan(1). */
        long long scale = 1;
        for (int j = i; j < p.count; j++) {
            if (angle[j] < 0 || mono_cmp(&cofactor[j], &cofactor[i]) != 0) continue;
            Frac c = frac_mul(p.term[j].coef.re, frac_int(angle[j] == pi ? 4 : 1));
            scale = scale / (long long)gcd128(scale, c.den) * c.den;
            if (scale > 8) return 0;
        }

        /* V, Q e il controllo sulla grandezza. */
        Poly v = poly_const(num_int(1)), q = poly_const(num_int(1));
        long long weight = 0;
        int proper = 0;
        for (int j = p.count - 1; j >= i; j--) {
            if (angle[j] < 0 || mono_cmp(&cofactor[j], &cofactor[i]) != 0) continue;
            int unit = (angle[j] == pi);
            Frac c = frac_mul(p.term[j].coef.re, frac_int(unit ? 4 * scale : scale));
            long long times = c.num < 0 ? -c.num : c.num;
            Rat u = unit ? rat_int(1) : atan_args[atoms[angle[j]].id];
            angle[j] = -1;
            weight += times * (unit ? 1 : 2);
            if (!unit) proper = 1;
            if (weight > 8) return 0;

            /* Il fattore q + i s p, moltiplicato |c| volte. */
            Num turn = {frac_int(0), frac_int(c.num < 0 ? -1 : 1)};
            Poly factor = poly_add(u.den, poly_mul(poly_const(turn), u.num), 0);
            for (long long k = 0; k < times; k++) {
                v = poly_mul(v, factor);
                q = poly_mul(q, u.den);
            }
        }
        if (failure || !proper) return 0;

        /* V reale, e V Q positivo. */
        for (int k = 0; k < v.count; k++)
            if (v.term[k].coef.im.num != 0) return 0;
        if (!poly_is_positive(poly_mul(v, q))) return 0;
    }
    return 1;
}

/* Ritorna 1 se p è zero, tenendo conto delle identità 12a, 12b e 12c. Un
 * errore durante il conto (in `failure`) vale come "no". */
static int poly_vanishes(Poly p) {
    p = poly_reduce_radicals(p, 0);
    if (failure) return 0;
    return p.count == 0 || log_combination_vanishes(p) || arctan_combination_vanishes(p);
}

/* Ritorna L - R per l'enunciato, con la variabile di induzione legata a n e i
 * parametri legati ai valori del punto in uso, se ce n'è uno. */
static Rat difference(const Statement *statement, Rat n) {
    env_count = 0;
    library_depth = 0;

    /* I parametri vanno legati per primi: env_varies() li riconosce dal posto. */
    for (int i = 0; i < point_count; i++) env_push(point_name[i], rat_frac(point_value[i]));
    env_push(induction_var, n);
    Rat left = eval(statement->lhs);
    Rat right = eval(statement->rhs);
    env_count = 0;
    return rat_add(left, right, 1);
}

/* 12d. IL TEST DOVE I DUE MEMBRI SONO DEFINITI
 *
 * Ritorna 1 se L - R, calcolata come in difference(), si riduce a zero con i
 * fatti del dominio (11q): allora L = R in ogni punto in cui i due membri
 * sono definiti (e, in un caso dei valori assoluti di 27a, valgono i segni
 * del caso). È il test di annullamento delle uguaglianze che si affermano
 * così, e solo di quelle (vedi "Perché solo lì", in 11q): lo chiamano 27a,
 * con la rilettura della derivata calcolata (27k), e 30a.
 *
 * source, se non è NULL, è un'espressione definita in ogni punto in cui
 * l'uguaglianza si afferma, anche se non ne è un membro: la funzione di cui
 * L è la derivata (27a), che deve essere definita dove è derivabile; la
 * primitiva F di cui L è F' (30a), che l'enunciato considera solo dove è
 * definita. Le sue radici e i suoi logaritmi danno fatti come quelli dei
 * membri, ed è lei a darli quando le regole li perdono: la derivata di
 * \ln(x + 3) è \frac{1}{x + 3}, definita anche per x < -3. Si calcola una
 * volta, per prima, solo per i fatti: un errore nel suo conto (un arcoseno,
 * che il conto esatto non ha) non riguarda l'uguaglianza, e i fatti trovati
 * prima dell'errore valgono lo stesso.
 *
 * I fatti si annotano mentre si calcola, e uno trovato in un membro può
 * servire a un'espressione calcolata prima: per questo il conto si rifà,
 * ogni volta con tutti i fatti trovati nelle volte precedenti, finché ne
 * compaiono di nuovi e la differenza non si è ridotta a zero, al più
 * DOMAIN_PASSES volte. Un conto che fallisce (la radice di una frazione i
 * cui termini non hanno segno noto, per esempio) si ferma al primo membro, e
 * i fatti dell'altro non arrivano: per questo le volte dispari calcolano
 * R - L, con il secondo membro per primo, che si annulla quando si annulla
 * L - R. Dopo un conto riuscito senza fatti nuovi rifarlo non cambierebbe
 * nulla; dopo uno fallito si prova almeno l'altro ordine. Se fallisce anche
 * l'ultima volta, `failure` resta impostato. All'uscita i fatti sono spenti
 * e dimenticati: non arrivano a nessun altro conto.
 *
 * Le condizioni di esistenza (capitolo 7) restano spente per tutto il test:
 * sono ciò che 13c deve controllare, e i fatti, che le suppongono vere,
 * cambierebbero quelle annotate. */
static int vanishes_where_defined(const Statement *statement, const Node *source, Rat n) {
    const char *was = failure;
    Statement turned = {statement->rhs, statement->lhs, statement->relation};
    int vanishes = 0, listed = conditions_on;
    conditions_on = 0;
    domain_on = 1;
    domain_fact_count = 0;
    if (source) {
        Statement facts_only = {(Node *)source, node_num(0), REL_EQ};
        difference(&facts_only, n);
    }
    for (int pass = 0; pass < DOMAIN_PASSES && !vanishes; pass++) {
        int known = domain_fact_count;
        failure = was;
        Rat gap = difference(pass % 2 ? &turned : statement, n);
        vanishes = !failure && poly_vanishes(gap.num);
        if (domain_fact_count == known && (pass > 0 || !failure)) break;
    }
    domain_on = 0;
    domain_fact_count = 0;
    conditions_on = listed;
    return vanishes;
}

/* =============================================================================
 * 13. INDUZIONE: CASO BASE, PASSO, VERDETTO
 * ============================================================================
 *
 * Sia D(n) = L(n) - R(n) la differenza dei due membri. L'enunciato dice che
 * D(n) = 0 per ogni n >= n0. Il principio di induzione chiede due cose:
 *
 *   13a. Caso base: D(n0) = 0. Con n = n0 ogni somma e prodotto si svolge e
 *        D(n0) è un'espressione senza n: deve annullarsi.
 *
 *   13b. Passo: per ogni n >= n0, da D(n) = 0 segue D(n+1) = 0.
 *        Si scrivono D(n) e D(n+1) con gli stessi atomi. L'ipotesi induttiva
 *        D(n) = 0 è un'equazione tra gli atomi: se un atomo X (di solito la
 *        somma dell'enunciato) vi compare al primo grado, numeratore
 *        A X + B = 0, se ne ricava X = -B/A. Sostituendo nel numeratore di
 *        D(n+1), che è un polinomio C0 + C1 X + ... + Cd X^d, e moltiplicando
 *        per A^d si ottiene
 *
 *            C0 A^d + C1 (-B) A^{d-1} + ... + Cd (-B)^d
 *
 *        che non contiene più X: se è il polinomio nullo il passo è
 *        dimostrato. È ciò che si fa a mano: "per ipotesi induttiva la somma
 *        fino a n vale R(n), quindi la somma fino a n+1 vale R(n) + f(n+1), e
 *        resta da controllare che sia R(n+1)".
 *
 * Quando l'ipotesi si può usare. Ricavare X = -B/A richiede A diverso da zero
 * per ogni n >= n0. Senza questa cautela si "dimostrerebbero" enunciati falsi:
 * in (n-1) S(n) = (n-1) g(n) il caso base n = 1 dice 0 = 0 qualunque sia g.
 * Il programma accetta due situazioni in cui la condizione è garantita:
 *
 *   - A è proporzionale al denominatore di D: allora X compare in D con un
 *     coefficiente costante (il caso "somma = formula"), e A non si annulla
 *     dove l'enunciato è definito;
 *   - A non dipende da n: dipende solo dai parametri, e un'uguaglianza tra
 *     funzioni razionali dei parametri, vera dove A non è zero, è vera ovunque
 *     sia definita.
 *
 * Negli altri casi servirebbe dimostrare che A non ha zeri interi: il
 * programma non lo sa fare e risponde NON DIMOSTRATO.
 *
 * Se l'induzione non riesce si cerca un controesempio: D valutata in pochi n
 * successivi. Un valore che è un numero diverso da zero prova che l'enunciato
 * è falso.
 *
 * Se l'induzione riesce, il verdetto non è ancora dato:
 *
 *   13c. si decide se i due membri sono definiti per ogni n, con un valore
 *        fisso dei parametri;
 *   13d. oppure, se un valore fisso non c'è, per tutti i valori dei parametri
 *        abbastanza grandi;
 *   13e. la dimostrazione viene ricontrollata con i numeri (verify_instances());
 *   13f. si scrive la dimostrazione, con i suoi passaggi;
 *   13g. ogni formula scritta viene riletta e ricontrollata;
 *   13h. si scrive il certificato dell'induzione e lo si dà al verificatore
 *        indipendente, checker.c.
 */

/* Esito di un tentativo di dimostrazione. */
typedef enum { PROVED, REFUTED, NOT_PROVED, UNSUPPORTED, SOLVED } Outcome;

/* Il verdetto su un enunciato, di qualunque tipo.
 *
 * I campi variable, base e witness riguardano le dimostrazioni per induzione;
 * per gli altri enunciati variable vale 0, method dice come sono stati
 * dimostrati e il controesempio, se c'è, è il testo in detail. Le stringhe
 * puntate non appartengono al verdetto: method e note sono costanti; reason,
 * detail, proof e certificate restano valide fino al verdetto successivo. */
typedef struct {
    Outcome outcome;
    int variable;        /* variabile di induzione, o 0 */
    long long base;      /* PROVED per induzione: il caso base n0 */
    long long witness;   /* REFUTED per induzione: un n in cui non vale */
    const char *reason;  /* NOT_PROVED, UNSUPPORTED: perché, in italiano;
                            PROVED per induzione o con la tabella dei
                            segni, REFUTED e SOLVED con la tabella dei
                            segni, senza certificato: perché il certificato
                            manca; altrimenti NULL */
    const char *detail;  /* REFUTED senza induzione: il controesempio, o NULL;
                            SOLVED: le soluzioni, come condizione in LaTeX */
    const char *proof;   /* dimostrazione scritta in LaTeX, o NULL */
    const char *method;  /* PROVED senza induzione, SOLVED: come, in italiano */
    const char *note;    /* PROVED, REFUTED: avvertenza su come è stato letto
                            l'enunciato, o NULL;
                            SOLVED: che cosa indicano i nomi usati nelle
                            soluzioni, o dove vale una derivata, o NULL */
    const char *certificate;  /* PROVED: il certificato che il verificatore
                                 indipendente ha accettato (13h, 18p-15), o NULL;
                                 REFUTED su insiemi qualsiasi: il controesempio,
                                 come certificato accettato (28f); REFUTED e
                                 SOLVED con la tabella dei segni: la tabella,
                                 come certificato accettato (18p-15) */
} Verdict;

/* Il testo della dimostrazione dell'enunciato in corso: LaTeX, in inglese come
 * gli altri testi destinati a un documento. proof_reset() lo svuota,
 * proof_add() vi aggiunge un pezzo con la sintassi di printf. Un testo più
 * lungo di PROOF_BYTES viene rifiutato, salvo i modelli che crescono sullo heap. */
static char proof_initial[PROOF_BYTES];
static char *proof_text = proof_initial;
static size_t proof_length, proof_capacity = PROOF_BYTES;
static int proof_growable, proof_broken;

/* Allarga un testo sullo heap entro il budget richiesto. Il deposito
 * iniziale resta statico per i domini che usano testi di lunghezza nota;
 * nessun puntatore al testo va conservato durante una crescita. */
static int text_reserve(char **text, size_t *capacity, char *initial, size_t need) {
    if (need <= *capacity) return 1;
    size_t cap = *capacity;
    while (cap < need) {
        if (cap > (size_t)-1 / 2) { cap = need; break; }
        cap *= 2;
    }
    if (cap > model_memory_limit) return 0;
    char *p = *text == initial ? malloc(cap) : realloc(*text, cap);
    if (!p) return 0;
    if (*text == initial) memcpy(p, initial, *capacity);
    *text = p; *capacity = cap;
    return 1;
}

/* Quanti passi di una dimostrazione scritta non hanno superato il controllo
 * indipendente, dall'avvio del programma. Le dimostrazioni sugli insiemi e
 * quelle con quantificatori ricontrollano ogni fatto che stanno per scrivere
 * con un metodo diverso da quello che lo ha ricavato (16h e 16i, e i
 * controlli del capitolo 18); quelle per induzione rileggono ogni formula
 * scritta e la ricalcolano con i numeri (13g). Se un passo non regge, la
 * dimostrazione viene abbandonata e il contatore sale. Sale anche quando il
 * verificatore indipendente respinge un certificato: di un'induzione (13h),
 * di un enunciato sugli insiemi, di uno su insiemi qualsiasi (28f).
 * Deve restare a zero: un valore diverso vuol dire che una regola ha
 * sbagliato, e i test lo controllano. */
static int unjustified_steps;

/* Svuota il documento e restituisce il deposito iniziale; i risultati
 * della chiamata precedente, come per l'arena, non sono piu validi. */
static void proof_reset(void) {
    if (proof_text != proof_initial) free(proof_text);
    proof_text = proof_initial; proof_capacity = PROOF_BYTES;
    proof_length = 0; proof_growable = proof_broken = 0;
    proof_text[0] = 0;
}

/* Aggiunge LaTeX. Solo la stampa di un modello abilita la crescita: gli
 * altri domini conservano i propri controlli di lunghezza. Un testo che
 * non entra resta marcato come incompleto, mai consegnato come modello. */
static void proof_add(const char *format, ...) {
    if (proof_broken) return;
    va_list arguments;
    va_start(arguments, format);
    va_list retry; va_copy(retry, arguments);
    int written = vsnprintf(proof_text + proof_length, proof_capacity - proof_length, format, arguments);
    if (written < 0 || (size_t)written > (size_t)-1 - proof_length - 1) proof_broken = 1;
    else {
        size_t need = proof_length + (size_t)written + 1;
        if (need > proof_capacity) {
            if (!proof_growable || !text_reserve(&proof_text, &proof_capacity, proof_initial, need)) {
                /* I vecchi chiamanti riconoscono il troncamento dalla lunghezza. */
                proof_length = proof_capacity - 1; proof_broken = 1;
            } else vsnprintf(proof_text + proof_length, proof_capacity - proof_length, format, retry);
        }
        if (!proof_broken) proof_length += (size_t)written;
    }
    va_end(retry);
    va_end(arguments);
}

/* Passo induttivo (13b): d è D(n), d1 è D(n+1), scritte con gli stessi atomi.
 * Ritorna 1 se da D(n) = 0 segue D(n+1) = 0, e allora mette in *used l'atomo
 * ricavato dall'ipotesi, oppure -1 se l'ipotesi non è servita. */
static int step_holds(Rat d, Rat d1, int *used) {
    /* D(n+1) è già zero: non serve nemmeno l'ipotesi. */
    *used = -1;
    if (poly_vanishes(d1.num)) return 1;

    /* Si prova a ricavare dall'ipotesi ogni somma o prodotto, uno alla volta. */
    for (int x = 0; x < atom_count && !failure; x++) {
        if (atoms[x].kind != ATOM_BIGOP) continue;

        /* Ipotesi: A x + B = 0, con A che non si annulla. */
        Poly hypothesis[2], part[MAX_DEGREE + 1];
        if (poly_split(d.num, x, hypothesis, 1) != 1) continue;
        Poly a = hypothesis[1], b = hypothesis[0];
        if (!poly_proportional(a, d.den) && poly_depends_on_n(a)) continue;

        /* Tesi: C0 + C1 x + ... + Cd x^d = 0. */
        int degree = poly_split(d1.num, x, part, MAX_DEGREE);
        if (degree < 0) continue;

        /* Sostituzione x = -B/A, moltiplicata per A^d. Le potenze di -B e di A
         * si accumulano mentre j cresce e d - j decresce. */
        Poly minus_b = poly_add(poly_const(num_int(0)), b, 1);
        Poly b_power = poly_const(num_int(1));
        Poly sum = poly_const(num_int(0));
        for (int j = 0; j <= degree; j++) {
            Poly piece = poly_mul(part[j], b_power);
            for (int k = j; k < degree; k++) piece = poly_mul(piece, a);
            sum = poly_add(sum, piece, 0);
            b_power = poly_mul(b_power, minus_b);
        }
        if (!failure && poly_vanishes(sum)) { *used = x; return 1; }
    }
    return 0;
}

/* 13c. DEFINITO PER OGNI n
 *
 * L'induzione è algebra sulle lettere: prova che i due membri sono uguali
 * "dove sono definiti". Perché il verdetto "per ogni n >= n0" sia vero serve
 * anche che lo siano per ogni n >= n0. In
 *
 *     (n - 50) / (n - 50) = 1
 *
 * l'algebra non trova nulla da ridire, e i primi n nemmeno, ma per n = 50 il
 * membro sinistro non esiste. Lo stesso vale per le divisioni che fa il conto
 * stesso: scrivere un prodotto fino a n - 1 come "prodotto fino a n diviso
 * l'ultimo fattore" (vedi eval_bigop()) è lecito solo dove quel fattore non è
 * zero.
 *
 * Le condizioni di esistenza (capitolo 7) vengono raccolte calcolando D(n) e
 * D(n+1) con n lettera e i parametri legati a numeri: sono polinomi negli
 * atomi, e condition_holds() decide ciascuna per ogni intero n >= n0. Bastano
 * queste due valutazioni: il caso n = n0 è già stato calcolato con i numeri,
 * D(n+1) contiene tutto ciò che compare passando da n a n + 1 (i due membri
 * in n + 1 e i termini nuovi di ogni somma), e D(n) le divisioni fatte per
 * scrivere l'ipotesi.
 *
 * La decisione ha tre risposte: vale (1), non vale (0, con un n in cui
 * fallisce), non so (-1). Le regole, nell'ordine in cui si provano (nel file
 * stanno nell'ordine in cui una ha bisogno dell'altra):
 *
 *   13c-1. Un seno o un coseno, eventualmente per un fattore positivo: il
 *          segno viene dal quadrante in cui cade l'angolo (trig_sign()).
 *   13c-2. Si raccoglie il monomio comune ai termini. I suoi atomi devono
 *          essere mai nulli (per "diverso da zero") o positivi (per i segni):
 *          n da 1 in su, le potenze di un primo, i prodotti di fattori
 *          positivi, le potenze di una base che a sua volta lo è.
 *   13c-3. Ciò che resta è un polinomio in una sola quantità che cresce con
 *          n, la "variabile principale": n stessa, o una potenza come 2^n.
 *          Il segno si decide con il limite di Cauchy (sign_holds()).
 *   13c-4. Ciò che resta contiene la variabile principale e radici di numeri
 *          primi, come la radice di 2: gli zeri si trovano con le radici
 *          razionali (zero_free()).
 *   13c-5. Altrimenti si guarda se il segno è evidente: coefficienti tutti
 *          dello stesso segno e fattori non negativi (evident_sign()).
 *   13c-6. Un'espressione che non decresce ed è positiva per n = n0, o che
 *          non cresce ed è negativa (monotone_sign()).
 *   13c-7. Un'espressione in n e in potenze come 2^n e 3^n, che crescono a
 *          velocità diverse: il segno per differenze (difference_rule()).
 *   13c-8. Per "diverso da zero", con seni e coseni: esponenziali complessi
 *          che non possono cancellarsi (exponentials_never_cancel()).
 *
 * Ogni regola conclude solo ciò che è certo. In particolare nessuna prende
 * per "diverso da zero" un'espressione solo perché non è il polinomio nullo:
 * tra gli atomi ci sono identità che la forma canonica non vede. Quando
 * nessuna regola decide, la risposta è "non so", e il verdetto sarà
 * NON DIMOSTRATO: di n! - 5 il programma non sa dire che non si annulla. */

/* Ritorna il segno, -1, 0 o 1, di c[0] + c[1] x + ... + c[degree] x^degree
 * nell'intero x, con lo schema di Horner. Se i numeri escono dall'aritmetica
 * esatta mette 0 in *known, che chi chiama ha messo a 1. */
static int univariate_sign(const long long *c, int degree, long long x, int *known) {
    __int128 value = 0;
    for (int i = degree; i >= 0; i--)
        if (__builtin_mul_overflow(value, (__int128)x, &value) || __builtin_add_overflow(value, (__int128)c[i], &value)) {
            *known = 0;
            return 0;
        }
    return (value > 0) - (value < 0);
}

/* Ritorna +1 se il monomio, per n >= base, è positivo e non decresce al
 * crescere di n; -1 se è positivo e non cresce; 0 se non si sa, o se non ha
 * fattori. I mattoni sono n (da 1 in su) e le potenze p^M di un primo, che
 * seguono l'andamento dell'esponente M perché p > 1; un esponente negativo
 * rovescia l'andamento. Un prodotto di quantità positive che vanno tutte
 * nello stesso verso va in quel verso. */
static int mono_trend(const Mono *m, long long base) {
    int trend = 0;
    for (int i = 0; i < m->count; i++) {
        const Atom *a = &atoms[m->factor[i].atom];
        int own;
        if (a->kind == ATOM_VAR && a->id == induction_var && base >= 1) own = 1;
        else if (a->kind == ATOM_POW && a->base == BASE_PRIME) own = mono_trend(&a->exponent, base);
        else return 0;
        if (m->factor[i].exp.num < 0) own = -own;
        if (own == 0 || (trend && own != trend)) return 0;
        trend = own;
    }
    return trend;
}

/* Mette in *value il valore del monomio per n = base e ritorna 1, se è un
 * razionale che si calcola con potenze intere di n e di numeri primi;
 * altrimenti ritorna 0. Numeri troppo grandi lasciano l'errore in `failure`. */
static int mono_at(const Mono *m, long long base, Frac *value) {
    *value = frac_int(1);
    for (int i = 0; i < m->count && !failure; i++) {
        const Atom *a = &atoms[m->factor[i].atom];
        Frac e = m->factor[i].exp, v, power;
        if (e.den != 1 || e.num > 62 || e.num < -62) return 0;
        if (a->kind == ATOM_VAR && a->id == induction_var) {
            v = frac_int(base);
        } else if (a->kind == ATOM_POW && a->base == BASE_PRIME) {
            if (!mono_at(&a->exponent, base, &power) || power.den != 1 || power.num > 62 || power.num < -62) return 0;
            v = frac_int(1);
            for (long long k = llabs(power.num); k > 0 && !failure; k--)
                v = power.num > 0 ? frac_mul(v, frac_int(a->id)) : frac_div(v, frac_int(a->id));
        } else {
            return 0;
        }
        if (v.num == 0 && e.num < 0) return 0;
        for (long long k = llabs(e.num); k > 0 && !failure; k--) *value = e.num > 0 ? frac_mul(*value, v) : frac_div(*value, v);
    }
    return !failure;
}

/* LA VARIABILE PRINCIPALE
 *
 * Le regole 13c-3 e 13c-4 decidono un polinomio in una sola quantità che
 * cresce con n prendendo valori interi: n stessa, oppure una potenza come
 * 2^n. Di 2 A^2 - 3 A + 1 con A = 2^n si trovano le radici intere in A, e poi
 * si guarda se 2^n le raggiunge. Così la stessa regola che per n - 50 trova
 * n = 50 trova per 2^n - 4096 il valore n = 12. */

/* Ritorna l'atomo che fa da variabile principale di q per n >= base: l'unico
 * atomo di q che dipende da n, se è n oppure una potenza p^M di un primo con
 * M intero e crescente. Se q non dipende da n ritorna n. Ritorna -1 se gli
 * atomi che dipendono da n sono più d'uno, o di un altro tipo. */
static int main_atom(Poly q, long long base) {
    int found = -1;
    for (int i = 0; i < q.count; i++)
        for (int f = 0; f < q.term[i].mono.count; f++) {
            int atom = q.term[i].mono.factor[f].atom;
            if (!atoms[atom].depends_on_n) continue;
            if (found >= 0 && atom != found) return -1;
            found = atom;
        }
    if (found < 0) return atom_var(induction_var);
    const Atom *a = &atoms[found];
    if (a->kind == ATOM_VAR) return found;
    int power = a->kind == ATOM_POW && a->base == BASE_PRIME && mono_is_integer(&a->exponent);
    return power && mono_trend(&a->exponent, base) == 1 ? found : -1;
}

/* Mette in *value il valore intero della variabile principale `atom` per
 * n = at, e ritorna 1; ritorna 0 se non è un intero che si sa calcolare. */
static int main_at(int atom, long long at, long long *value) {
    Mono single = mono_atom(atom, frac_int(1));
    Frac v;
    if (!mono_at(&single, at, &v) || v.den != 1) return 0;
    *value = v.num;
    return 1;
}

/* 13c-3. Decide se il polinomio a coefficienti interi c[0..degree] nella
 * variabile principale `atom`, con c[degree] diverso da zero, è positivo
 * (strict) o non negativo per ogni intero n >= base. Ritorna 1, oppure 0 con
 * il primo n in cui fallisce in *where, oppure -1 se i valori da provare sono
 * troppi o troppo grandi.
 *
 * Limite di Cauchy: ogni radice reale r del polinomio soddisfa
 * |r| < 1 + M, dove M è il più grande |c[i]| / |c[degree]| con i < degree.
 * Infatti se |x| >= 1 + M la somma dei termini di grado più basso vale al più
 * M |c[degree]| (|x|^degree - 1) / (|x| - 1) <= |c[degree]| (|x|^degree - 1),
 * meno del termine di grado massimo: il polinomio non può annullarsi.
 *
 * Oltre il limite il segno quindi non cambia più. La variabile principale
 * cresce con n: si provano i suoi valori uno dopo l'altro finché non
 * superano il limite. Se nessuno fallisce, nemmeno l'ultimo, il segno resta
 * quello buono per sempre. */
static int sign_holds(const long long *c, int degree, int strict, int atom, long long base, long long *where) {
    long long largest = 0, x;
    for (int i = 0; i < degree; i++)
        if (llabs(c[i]) > largest) largest = llabs(c[i]);
    long long bound = largest / llabs(c[degree]) + 2;
    for (long long at = base; at - base <= MAX_SCAN; at++) {
        int known = 1;
        if (!main_at(atom, at, &x)) return -1;
        int sign = univariate_sign(c, degree, x, &known);
        if (!known) return -1;
        if (sign < 0 || (strict && sign == 0)) { *where = at; return 0; }
        if (degree == 0 || x >= bound) return 1;
    }
    return -1;
}

/* 13c-4. Decide se q è diverso da zero per ogni intero n >= base, quando la
 * variabile principale `atom` vi compare solo con potenze intere e gli altri
 * atomi sono radici di numeri primi. Ritorna 1, oppure 0 con il più piccolo n in cui
 * si annulla in *where, oppure -1 se q non ha questa forma o un conto non
 * riesce.
 *
 * Detta A la variabile principale, q è una somma c_1(A) m_1 + ... +
 * c_r(A) m_r, dove gli m_j sono monomi distinti negli atomi costanti e i c_j
 * polinomi a coefficienti razionali. Se gli m_j sono linearmente
 * indipendenti sui razionali, q si annulla dove A vale r solo se tutti i c_j
 * si annullano in r. I valori interi di A in cui q si annulla sono allora
 * tra le radici intere di uno qualunque dei c_j, che il teorema delle radici
 * razionali elenca tutte (rational_roots()). Di ognuna si guarda se A la
 * raggiunge per qualche n >= base, e se annulla tutto q.
 *
 * L'indipendenza va garantita, non supposta: qui un legame nascosto tra gli
 * m_j farebbe perdere uno zero, cioè accettare una divisione per zero. Per
 * questo gli atomi costanti ammessi sono solo le radici di numeri primi,
 * come la radice di 2 e la radice cubica di 5: i loro prodotti distinti sono
 * linearmente indipendenti sui razionali (teorema di Besicovitch; il caso
 * più noto è che 1, radice di 2, radice di 3 e radice di 6 lo sono). Altri
 * atomi costanti soddisfano identità: arctan(1/2) + arctan(1/3) = pi/4, e
 * 2 cos(pi/3) = 1 tra le potenze di e^{i pi}. */
static int zero_free(Poly q, int atom, long long base, long long *where) {
    const long long cap = 1000000000;
    int answer = 1;
    Poly part[MAX_UNIVARIATE + 1];
    Frac coefficient[MAX_UNIVARIATE + 1], root[MAX_UNIVARIATE + 1];
    long long c[MAX_UNIVARIATE + 1];

    /* q = part[0] + part[1] A + ... + part[degree] A^degree. */
    int degree = poly_split(q, atom, part, MAX_UNIVARIATE);
    if (degree < 0) return -1;
    for (int j = 0; j <= degree; j++)
        for (int i = 0; i < part[j].count; i++)
            for (int f = 0; f < part[j].term[i].mono.count; f++) {
                const Atom *a = &atoms[part[j].term[i].mono.factor[f].atom];
                if (a->kind != ATOM_POW || a->base != BASE_PRIME || a->exponent.count != 0) return -1;
            }

    /* Il polinomio c(A) che moltiplica uno dei monomi costanti: quello del
     * primo termine della parte di grado massimo. Di un coefficiente
     * complesso si guarda la parte reale, o quella immaginaria se la reale
     * manca: c(r) = 0 le annulla entrambe. */
    const Term *chosen = &part[degree].term[0];
    int imaginary = chosen->coef.re.num == 0;
    __int128 scale = 1;
    for (int j = 0; j <= degree; j++) {
        coefficient[j] = frac_int(0);
        for (int i = 0; i < part[j].count; i++)
            if (mono_cmp(&part[j].term[i].mono, &chosen->mono) == 0)
                coefficient[j] = imaginary ? part[j].term[i].coef.im : part[j].term[i].coef.re;
        scale = scale / gcd128(scale, coefficient[j].den) * coefficient[j].den;
        if (scale > cap) return -1;
    }
    for (int j = 0; j <= degree; j++) {
        __int128 value = (__int128)coefficient[j].num * (scale / coefficient[j].den);
        if (value > cap || value < -cap) return -1;
        c[j] = (long long)value;
    }

    /* Le radici intere di c(A). */
    int roots = degree >= 1 ? rational_roots(c, degree, root) : 0;
    if (roots < 0) return -1;
    for (int k = 0; k < roots; k++) {
        if (root[k].den != 1) continue;

        /* A cresce: raggiunge la radice per un solo n, o la salta. */
        long long at = base, x = 0;
        while (at - base <= MAX_SCAN && main_at(atom, at, &x) && x < root[k].num) at++;
        if (failure || at - base > MAX_SCAN) return -1;
        if (x != root[k].num) continue;

        /* La radice annulla tutto q? Schema di Horner sui polinomi. */
        Poly value = part[degree], r = poly_const(num_int(root[k].num));
        for (int j = degree - 1; j >= 0; j--) value = poly_add(poly_mul(value, r), part[j], 0);
        if (failure) return -1;
        if (poly_vanishes(value) && (answer == 1 || at < *where)) { answer = 0; *where = at; }
    }
    return answer;
}

static int condition_holds(Requirement kind, Poly p, long long base, long long *where);

/* Ritorna 1 se l'atomo è certamente positivo per ogni n >= base: n da 1 in
 * su, pi greco, le potenze di un primo, i prodotti di fattori positivi, le
 * potenze di una base positiva (una radice di n + 1 è l'atomo "n + 1" elevato
 * a 1/2), il logaritmo di un primo, l'arcotangente di un argomento positivo.
 * Zero vuol dire "non si sa". */
static int atom_is_positive(int atom, long long base) {
    const Atom *a = &atoms[atom];
    long long where;
    if (a->kind == ATOM_VAR) return a->id == VAR_PI || (a->id == induction_var && base >= 1);
    if (a->kind == ATOM_BIGOP) return a->positive;
    if (a->kind == ATOM_ATAN) {
        Rat u = atan_args[a->id];
        return condition_holds(ALWAYS_POSITIVE, poly_mul(u.num, u.den), base, &where) == 1;
    }
    if (a->kind == ATOM_LN) return a->base == BASE_PRIME;
    if (a->kind != ATOM_POW || a->base == BASE_EI) return 0;
    if (a->base == BASE_PRIME) return 1;
    if (a->base == BASE_ATOM) return atom_is_positive((int)a->id, base);
    return condition_holds(ALWAYS_POSITIVE, base_polys[a->id], base, &where) == 1;
}

/* Decide se l'atomo è diverso da zero per ogni n >= base: 1, 0 (con lo zero
 * in *where) o -1. Una potenza si annulla solo se si annulla la base; e^{i M}
 * mai; un'arcotangente solo se si annulla l'argomento. */
static int atom_never_zero(int atom, long long base, long long *where) {
    const Atom *a = &atoms[atom];
    if (a->kind == ATOM_VAR && a->id == induction_var) {
        *where = 0;
        return base >= 1;
    }
    if (a->kind == ATOM_VAR) return a->id == VAR_PI ? 1 : -1;
    if (a->kind == ATOM_BIGOP) return a->positive ? 1 : -1;
    if (a->kind == ATOM_ATAN) return condition_holds(NEVER_ZERO, atan_args[a->id].num, base, where);
    if (a->kind == ATOM_REC) return -1;
    if (a->base == BASE_PRIME || (a->kind == ATOM_POW && a->base == BASE_EI)) return 1;
    Poly inner = a->base == BASE_ATOM ? rat_atom((int)a->id).num : base_polys[a->id];
    if (a->kind == ATOM_POW) return condition_holds(NEVER_ZERO, inner, base, where);

    /* Un logaritmo ln|u| vale zero solo dove u = 1 oppure u = -1. */
    int below = condition_holds(NEVER_ZERO, poly_add(inner, poly_const(num_int(1)), 1), base, where);
    return below == 1 ? condition_holds(NEVER_ZERO, poly_add(inner, poly_const(num_int(1)), 0), base, where) : below;
}

/* 13c-5. Ritorna 1 se q è evidentemente positivo per ogni n >= base, -1 se
 * evidentemente negativo, 0 se non si vede. Evidente vuol dire: coefficienti
 * tutti dello stesso segno; ogni fattore positivo, oppure non negativo con
 * esponente positivo, oppure potenza pari di un atomo reale; e almeno un
 * termine fatto solo di fattori positivi, che tiene la somma lontana da
 * zero. */
static int evident_sign(Poly q, long long base) {
    int sign = 0, strict = 0;
    for (int i = 0; i < q.count; i++) {
        const Term *t = &q.term[i];
        int positive = 1, own = t->coef.re.num > 0 ? 1 : -1;
        if (t->coef.im.num != 0 || (sign && own != sign)) return 0;
        sign = own;
        for (int f = 0; f < t->mono.count; f++) {
            const Factor *factor = &t->mono.factor[f];
            if (atom_is_positive(factor->atom, base)) continue;
            int even = factor->exp.den == 1 && factor->exp.num % 2 == 0;
            if (factor->exp.num < 0 || !(atom_is_nonnegative(factor->atom) || (even && atom_is_real(factor->atom)))) return 0;
            positive = 0;
        }
        if (positive) strict = 1;
    }
    return strict ? sign : 0;
}

/* 13c-6. Ritorna 1 se q è positivo per ogni n >= base, -1 se è negativo, 0
 * se questa regola non lo stabilisce.
 *
 * Se ogni termine che dipende da n non decresce al crescere di n (un
 * monomio che non decresce con coefficiente positivo, o uno che non cresce
 * con coefficiente negativo), q non decresce: se è positivo per n = base lo
 * è per sempre. Allo stesso modo, se nessun termine cresce e q è negativo in
 * base, resta negativo. Così 2^{2^n} - 1 è positivo da n = 1 in poi, mentre
 * di 2^n - 4096, che in n = 1 è negativo e cresce, non si conclude nulla (e
 * infatti si annulla per n = 12). */
static int monotone_sign(Poly q, long long base) {
    int direction = 0;
    Frac total = frac_int(0), v;
    for (int i = 0; i < q.count; i++) {
        const Term *t = &q.term[i];
        if (t->coef.im.num != 0 || !mono_at(&t->mono, base, &v)) return 0;
        total = frac_add(total, frac_mul(t->coef.re, v));
        if (t->mono.count == 0) continue;
        int own = mono_trend(&t->mono, base);
        if (t->coef.re.num < 0) own = -own;
        if (own == 0 || (direction && own != direction)) return 0;
        direction = own;
    }
    if (failure) return 0;
    if (direction >= 0 && total.num > 0) return 1;
    if (direction <= 0 && total.num < 0) return -1;
    return 0;
}

/* Divide il monomio m in esponenziali complessi e resto. Mette in *wave i
 * fattori e^{i M} di m e in *angle l'angolo complessivo, cioè la somma degli
 * esponenti: il prodotto dei fattori di *wave vale e^{i angle}. Ritorna 1 se
 * ci riesce; 0 se tra gli esponenziali ce n'è uno a cui si applicano le
 * identità con pi greco (4f, 4g), che qui non si sanno trattare. */
static int split_wave(const Mono *m, Mono *wave, Poly *angle) {
    wave->count = 0;
    *angle = poly_const(num_int(0));
    for (int f = 0; f < m->count; f++) {
        const Atom *a = &atoms[m->factor[f].atom];
        if (a->kind != ATOM_POW || a->base != BASE_EI) continue;
        if (a->pi != PI_NONE) return 0;
        Term t;
        t.coef = num_frac(m->factor[f].exp);
        t.mono = a->exponent;
        *angle = poly_add(*angle, poly_term(t), 0);
        wave->factor[wave->count++] = m->factor[f];
    }
    return 1;
}

/* Ritorna il termine t privato dei fattori di wave. */
static Term term_without(Term t, const Mono *wave) {
    for (int f = 0; f < wave->count; f++) t.mono = mono_with_exponent(&t.mono, wave->factor[f].atom, frac_int(0));
    return t;
}

/* Ritorna 1 se l'atomo vale un numero algebrico per ogni n intero: n, i
 * termini delle successioni per ricorrenza, e le potenze con base algebrica
 * ed esponente razionale, come 2^n o la radice di n + 1. Non lo sono, o non
 * si sa, pi greco, i logaritmi, le arcotangenti, le somme, i parametri.
 * Serve alla regola 13c-8. */
static int poly_is_algebraic(Poly p);
static int atom_is_algebraic(int atom) {
    const Atom *a = &atoms[atom];
    if (a->kind == ATOM_VAR) return a->id == induction_var;
    if (a->kind == ATOM_REC) return 1;
    if (a->kind != ATOM_POW || a->base == BASE_EI || !mono_is_integer(&a->exponent)) return 0;
    if (a->base == BASE_ATOM) return atom_is_algebraic((int)a->id);
    return a->base == BASE_PRIME || poly_is_algebraic(base_polys[a->id]);
}

/* Ritorna 1 se ogni atomo del monomio vale un numero algebrico. */
static int mono_is_algebraic(const Mono *m) {
    for (int i = 0; i < m->count; i++)
        if (!atom_is_algebraic(m->factor[i].atom)) return 0;
    return 1;
}

/* Ritorna 1 se ogni atomo di p vale un numero algebrico. */
static int poly_is_algebraic(Poly p) {
    for (int i = 0; i < p.count; i++)
        if (!mono_is_algebraic(&p.term[i].mono)) return 0;
    return 1;
}

/* 13c-8. Ritorna 1 se q, che contiene esponenziali complessi e^{i M}, è
 * certamente diverso da zero per ogni intero n >= base; -1 se non lo sa
 * stabilire. È il caso dei denominatori con seni e coseni, come sin(n x) con
 * x legato a un numero razionale.
 *
 * Teorema di Lindemann-Weierstrass: se t_1, ..., t_r sono numeri algebrici
 * distinti, allora e^{t_1}, ..., e^{t_r} sono linearmente indipendenti sui
 * numeri algebrici: una loro combinazione a coefficienti algebrici vale zero
 * solo se tutti i coefficienti sono zero. (Ne segue, per esempio, che sin(1)
 * non è zero, cioè che pi greco non è razionale.)
 *
 * Si scrive q = g_1 e^{i t_1} + ... + g_r e^{i t_r}, raccogliendo i termini
 * con gli stessi esponenziali: ogni t_j è la somma degli esponenti, un
 * polinomio negli atomi, e ogni g_j è il polinomio che resta. Se tutti gli
 * atomi coinvolti sono algebrici, per ogni n intero i t_j e i g_j sono numeri
 * algebrici. Basta allora un indice j tale che, per ogni n >= base, g_j non
 * sia zero e t_j sia diverso da tutti gli altri t_k: anche se altri
 * esponenti coincidono tra loro, e^{i t_j} resta con il suo coefficiente non
 * nullo, e la somma non può annullarsi. Le due richieste sono a loro volta
 * condizioni "mai zero", decise da condition_holds(). */
static int exponentials_never_cancel(Poly q, long long base) {
    enum { MOST = 24 };
    Mono wave[MOST];   /* gli esponenziali di ogni termine */
    Poly angle[MOST];  /* il loro esponente complessivo t */
    long long where;
    if (q.count > MOST) return -1;

    /* Ogni termine si divide in esponenziali e resto, tutti algebrici. */
    int waves = 0;
    for (int i = 0; i < q.count; i++) {
        if (!split_wave(&q.term[i].mono, &wave[i], &angle[i])) return -1;
        Term rest = term_without(q.term[i], &wave[i]);
        if (!mono_is_algebraic(&rest.mono) || !poly_is_algebraic(angle[i])) return -1;
        waves += wave[i].count;
    }
    if (!waves || failure) return -1;

    /* Si cerca il termine j che non può essere cancellato. */
    for (int j = 0; j < q.count; j++) {
        int alone = 1, repeated = 0;
        Poly g = poly_const(num_int(0));
        for (int k = 0; k < j; k++)
            if (mono_cmp(&wave[k], &wave[j]) == 0) repeated = 1;
        if (repeated) continue;

        /* Il coefficiente g_j, e gli esponenti degli altri gruppi. */
        for (int k = 0; k < q.count && alone; k++) {
            if (mono_cmp(&wave[k], &wave[j]) == 0) {
                g = poly_add(g, poly_term(term_without(q.term[k], &wave[k])), 0);
            } else {
                alone = condition_holds(NEVER_ZERO, poly_add(angle[j], angle[k], 1), base, &where) == 1;
            }
        }
        if (failure) return -1;
        if (alone && condition_holds(NEVER_ZERO, g, base, &where) == 1) return 1;
    }
    return -1;
}

/* 13c-1. IL SEGNO DI UN SENO O DI UN COSENO
 *
 * Seni e coseni sono calcolati come esponenziali complessi (capitolo 11), e
 * in quella forma il segno non si vede. Lo si ritrova riconoscendo le due
 * forme più semplici:
 *
 *     c e^{i t} + c e^{-i t}      = 2 c cos t
 *     -i c e^{i t} + i c e^{-i t} = 2 c sin t
 *
 * eventualmente moltiplicate per un fattore positivo, come 2^n. Il segno di
 * cos t e di sin t dipende dal quadrante: dall'intero m per cui
 *
 *     m pi/2 < t < (m + 1) pi/2.
 *
 * Con m = 0 sono positivi entrambi, con m = 1 solo il seno, con m = 2
 * nessuno dei due, con m = 3 solo il coseno, e poi si ricomincia.
 *
 * Quando l'angolo dipende da n il quadrante deve essere lo stesso per ogni
 * n: le due disuguaglianze sono a loro volta condizioni "positivo per ogni
 * n", decise da condition_holds(). Se l'angolo è un multiplo di pi greco,
 * t = pi r, si chiede m < 2 r < m + 1, senza approssimazioni. Altrimenti
 * servono dei numeri razionali tra cui stia pi greco, e si usano quelli di
 * Archimede, 223/71 < pi < 22/7: per m positivo basta t > m (22/7)/2 da una
 * parte e t < (m + 1) (223/71)/2 dall'altra, e per m negativo i due limiti
 * si scambiano. Sono condizioni un po' più strette del necessario: un angolo
 * molto vicino a un multiplo di pi/2 resta senza risposta. */

/* Cerca il quadrante dell'angolo `angle` per ogni n >= base: ritorna 1 e
 * mette in *quadrant l'intero m descritto sopra, se lo trova tra -8 e 8;
 * altrimenti ritorna 0. Se in_pi è diverso da zero l'angolo vero è pi greco
 * per `angle`. */
static int angle_quadrant(Poly angle, int in_pi, long long base, int *quadrant) {
    const Frac below = {223, 71}, above = {22, 7};
    long long where;
    for (int step = 0; step <= 16 && !failure; step++) {
        /* I candidati nell'ordine 0, 1, -1, 2, -2, ... */
        int m = step % 2 ? (step + 1) / 2 : -(step / 2);
        Frac low = frac_int(m), high = frac_int(m + 1);
        if (!in_pi) {
            low = frac_mul(low, frac_div(m >= 0 ? above : below, frac_int(2)));
            high = frac_mul(high, frac_div(m + 1 > 0 ? below : above, frac_int(2)));
        }

        /* scaled è 2 r per un multiplo di pi greco, l'angolo stesso altrimenti. */
        Poly scaled = in_pi ? poly_mul(angle, poly_const(num_int(2))) : angle;
        if (condition_holds(ALWAYS_POSITIVE, poly_add(scaled, poly_const(num_frac(low)), 1), base, &where) != 1) continue;
        if (condition_holds(ALWAYS_POSITIVE, poly_add(poly_const(num_frac(high)), scaled, 1), base, &where) != 1) continue;
        *quadrant = m;
        return 1;
    }
    return 0;
}

/* Ritorna il segno di p per ogni n >= base, +1 o -1, quando p è una delle
 * forme descritte sopra; 0 se non lo è o se il quadrante non si trova. Mette
 * in *strict 1 se il segno è stretto, 0 se p può anche valere zero.
 *
 * Oltre alle due forme con seno e coseno ne riconosce una terza, con un
 * termine costante: c0 + c e^{i t} + (coniugato di c) e^{-i t}, che vale
 * c0 + 2 Re(c e^{i t}) e sta quindi tra c0 - 2|c| e c0 + 2|c|. Se |c0| supera
 * 2|c| ha il segno di c0; se lo uguaglia lo ha in senso largo. È il caso di
 * cos^2 t = 1/2 + (e^{2 i t} + e^{-2 i t})/4, che nasce come denominatore di
 * una tangente al quadrato. */
static int trig_sign(Poly p, long long base, int *strict) {
    Mono wave[3];
    Poly angle[3];
    Term rest[3];
    int still = -1, first = -1, second = -1, quadrant;
    if (p.count < 2 || p.count > 3) return 0;

    /* Due termini con esponenziali opposti, e al più uno senza. */
    for (int i = 0; i < p.count; i++) {
        if (!split_wave(&p.term[i].mono, &wave[i], &angle[i])) return 0;
        rest[i] = term_without(p.term[i], &wave[i]);
        if (wave[i].count == 0 && still < 0) still = i;
        else if (first < 0) first = i;
        else second = i;
    }
    if (second < 0 || wave[first].count == 0 || wave[second].count == 0 || (p.count == 3 && still < 0)) return 0;
    if (mono_mul(&wave[first], &wave[second]).count != 0) return 0;

    /* Lo stesso fattore reale in tutti i termini, positivo; i coefficienti
     * dei due esponenziali coniugati tra loro. */
    Num c = rest[first].coef, d = rest[second].coef;
    if (mono_cmp(&rest[first].mono, &rest[second].mono) != 0 || frac_cmp(c.re, d.re) != 0 || frac_cmp(c.im, frac_neg(d.im)) != 0) return 0;
    for (int f = 0; f < rest[first].mono.count; f++)
        if (!atom_is_positive(rest[first].mono.factor[f].atom, base)) return 0;

    /* Con il termine costante: il confronto tra c0^2 e 4 |c|^2. */
    if (p.count == 3) {
        Num c0 = rest[still].coef;
        if (mono_cmp(&rest[still].mono, &rest[first].mono) != 0 || c0.im.num != 0) return 0;
        Frac size = frac_mul(frac_int(4), frac_add(frac_mul(c.re, c.re), frac_mul(c.im, c.im)));
        int compare = frac_cmp(frac_mul(c0.re, c0.re), size);
        if (failure || compare < 0) return 0;
        *strict = compare > 0;
        return c0.re.num > 0 ? 1 : -1;
    }

    /* L'angolo è un multiplo di pi greco se pi compare, alla prima potenza,
     * in tutti i suoi termini; se compare solo in alcuni si rinuncia. */
    int pi = atom_var(VAR_PI), with = 0;
    Poly turn = angle[first];
    for (int i = 0; i < turn.count; i++) with += frac_cmp(mono_exponent(&turn.term[i].mono, pi), frac_int(1)) == 0;
    if (with != 0 && with != turn.count) return 0;
    if (with) {
        Term divisor;
        divisor.coef = num_int(1);
        divisor.mono = mono_atom(pi, frac_int(-1));
        turn = poly_mul(turn, poly_term(divisor));
    }
    if (failure || !angle_quadrant(turn, with != 0, base, &quadrant)) return 0;

    /* Coefficiente reale: coseno. Immaginario: seno, con il segno di -Im c,
     * perché -i c' e^{i t} + i c' e^{-i t} = 2 c' sin t. */
    int q = ((quadrant % 4) + 4) % 4;
    *strict = 1;
    if (c.im.num == 0) return (c.re.num > 0 ? 1 : -1) * (q == 0 || q == 3 ? 1 : -1);
    if (c.re.num == 0) return (c.im.num < 0 ? 1 : -1) * (q == 0 || q == 1 ? 1 : -1);
    return 0;
}

/* 13c-7. IL SEGNO PER DIFFERENZE
 *
 * Per le espressioni fatte di n e di potenze come 2^n e 3^n, dove più
 * quantità crescono a velocità diverse: 2^n - n, 3^n - 2^n - n.
 *
 * Lemma. Sia b > 0. Se q(N) > 0 e q(n+1) - b q(n) >= 0 per ogni n >= N,
 * allora q(n) > 0 per ogni n >= N: per induzione, q(n+1) >= b q(n) > 0. Lo
 * stesso vale con >= al posto di >.
 *
 * La differenza q(n+1) - b q(n) è un'espressione dello stesso tipo, e più
 * semplice: se b è la più piccola delle basi che compaiono in q (1 per i
 * termini che sono polinomi in n), i termini con quella base perdono un
 * grado, perché b^{n+1} (n+1)^d - b b^n n^d = b^{n+1} ((n+1)^d - n^d), e
 * dopo abbastanza passi spariscono. Si ripete finché resta un'espressione di
 * segno evidente. Per 2^n - n: la differenza con b = 1 è 2^n - 1, la
 * successiva 2^n, che è positiva; e i valori in n = 1 sono 1 e 1, positivi.
 *
 * Il lemma chiede che ogni differenza parta bene in N. Se non succede per
 * N = base si prova più avanti, controllando uno per uno i valori saltati:
 * così 2^n - 100 n - 1000, negativo all'inizio e poi sempre positivo, risulta
 * mai nullo, e di 2^n - n^2 si trova che vale zero per n = 2. */

/* Ritorna 1 se q è fatto solo di n e di potenze p^n di numeri primi, con
 * esponenti interi non negativi e coefficienti reali. */
static int in_growth_class(Poly q) {
    for (int i = 0; i < q.count; i++) {
        if (q.term[i].coef.im.num != 0) return 0;
        for (int f = 0; f < q.term[i].mono.count; f++) {
            const Factor *factor = &q.term[i].mono.factor[f];
            const Atom *a = &atoms[factor->atom];
            int power = a->kind == ATOM_POW && a->base == BASE_PRIME && a->exponent.count == 1 &&
                        a->exponent.factor[0].atom == atom_var(induction_var) && frac_cmp(a->exponent.factor[0].exp, frac_int(1)) == 0;
            int letter = a->kind == ATOM_VAR && a->id == induction_var;
            if ((!power && !letter) || factor->exp.den != 1 || factor->exp.num < 0 || factor->exp.num > MAX_UNIVARIATE) return 0;
        }
    }
    return 1;
}

/* Ritorna q(n+1) scritto con gli stessi atomi, per q della classe di
 * in_growth_class(): n diventa n + 1 e ogni p^n diventa p p^n. */
static Poly poly_shift(Poly q) {
    int n = atom_var(induction_var);
    Poly out = poly_substitute(q, n, rat_add(rat_atom(n), rat_int(1), 0)).num;
    for (int x = 0; x < atom_count && !failure; x++) {
        if (atoms[x].kind != ATOM_POW || atoms[x].base != BASE_PRIME || atoms[x].exponent.count == 0) continue;
        out = poly_substitute(out, x, rat_mul(rat_int(atoms[x].id), rat_atom(x))).num;
    }
    return out;
}

/* Mette in *value il valore di q per n = at, e ritorna 1; ritorna 0 se non è
 * un razionale che si sa calcolare (vedi mono_at()). */
static int poly_at(Poly q, long long at, Frac *value) {
    Frac v;
    *value = frac_int(0);
    for (int i = 0; i < q.count; i++) {
        if (q.term[i].coef.im.num != 0 || !mono_at(&q.term[i].mono, at, &v)) return 0;
        *value = frac_add(*value, frac_mul(q.term[i].coef.re, v));
    }
    return !failure;
}

/* Ritorna 1 se il lemma qui sopra dimostra che q(n) > 0 (strict) o q(n) >= 0
 * per ogni n >= from; 0 se non ci riesce. depth limita il numero di
 * differenze successive. */
static int grows_positive(Poly q, long long from, int strict, int depth) {
    Frac value;
    if (q.count == 0) return !strict;
    if (!poly_at(q, from, &value) || value.num < 0 || (strict && value.num == 0)) return 0;
    int evident = evident_sign(q, from);
    if (evident || depth == 0) return evident > 0;

    /* La base più piccola tra i termini: il prodotto dei primi di ciascuno. */
    long long smallest = 0;
    for (int i = 0; i < q.count; i++) {
        long long own = 1;
        for (int f = 0; f < q.term[i].mono.count; f++) {
            const Atom *a = &atoms[q.term[i].mono.factor[f].atom];
            for (long long e = a->kind == ATOM_POW ? q.term[i].mono.factor[f].exp.num : 0; e > 0; e--)
                if (__builtin_mul_overflow(own, a->id, &own)) return 0;
        }
        if (!smallest || own < smallest) smallest = own;
    }
    Poly next = poly_add(poly_shift(q), poly_mul(q, poly_const(num_int(smallest))), 1);
    return !failure && grows_positive(next, from, 0, depth - 1);
}

/* Decide con il lemma se q, della classe di in_growth_class(), rispetta kind
 * per ogni n >= base: 1, 0 (con il primo n in cui fallisce in *where) o -1. */
static int difference_rule(Requirement kind, Poly q, long long base, long long *where) {
    Poly minus = poly_add(poly_const(num_int(0)), q, 1);
    if (!in_growth_class(q)) return -1;
    for (long long from = base; from <= base + 64; from++) {
        /* Il valore in `from`, calcolato: i precedenti sono già stati visti. */
        Frac value;
        if (!poly_at(q, from, &value)) return -1;
        if (kind == NEVER_ZERO ? value.num == 0 : kind == ALWAYS_POSITIVE ? value.num <= 0 : value.num < 0) {
            *where = from;
            return 0;
        }

        /* Da qui in poi il segno non cambia più? */
        if (grows_positive(q, from, kind != NEVER_NEGATIVE, 40)) return 1;
        if (kind == NEVER_ZERO && grows_positive(minus, from, 1, 40)) return 1;
        if (failure) return -1;
    }
    return -1;
}

/* Decide se il polinomio negli atomi p rispetta kind per ogni intero
 * n >= base: ritorna 1 se sì, 0 se no (e mette in *where un n in cui
 * fallisce), -1 se non lo sa stabilire. Le regole sono descritte in testa al
 * paragrafo 13c. */
static int condition_holds(Requirement kind, Poly p, long long base, long long *where) {
    long long c[MAX_UNIVARIATE + 1], scale;
    *where = base;

    /* Lo zero, anche quando lo è per un'identità che solo il test di
     * annullamento riconosce: dividere per arctan(1/2) + arctan(1/3) - pi/4
     * è dividere per zero. */
    if (poly_vanishes(p)) return kind == NEVER_NEGATIVE;
    if (failure) return -1;

    /* 13c-1. Un seno o un coseno: il segno viene dal quadrante. Un segno in
     * senso largo basta per "non negativo"; per "positivo" bisogna anche che
     * p non si annulli, e lo dicono le altre regole. */
    int strict = 0, trig = trig_sign(p, base, &strict);
    if (failure) return -1;
    *where = base;
    if (trig && strict) return kind == NEVER_ZERO || trig > 0;
    if (trig > 0 && kind == NEVER_NEGATIVE) return 1;
    if (trig > 0 && kind == ALWAYS_POSITIVE) return condition_holds(NEVER_ZERO, p, base, where) == 1 ? 1 : -1;
    if (trig < 0 && kind == ALWAYS_POSITIVE) return 0;

    /* 13c-2. Il monomio comune. */
    Mono common = poly_common(p);
    for (int i = 0; i < common.count; i++) {
        int atom = common.factor[i].atom;
        int fine = kind == NEVER_ZERO ? atom_never_zero(atom, base, where) : (atom_is_positive(atom, base) ? 1 : -1);
        if (fine != 1) return fine;
    }
    Term divisor;
    divisor.coef = num_int(1);
    divisor.mono = mono_pow(&common, frac_int(-1));
    Poly q = poly_mul(p, poly_term(divisor));
    if (failure) return -1;
    *where = base;

    /* 13c-3. Un polinomio nella sola variabile principale: il segno si
     * decide. */
    int atom = main_atom(q, base);
    int degree = atom >= 0 ? poly_coefficients(q, atom, c, &scale) : -1;
    if (degree >= 0 && kind != NEVER_ZERO) {
        int holds = sign_holds(c, degree, kind == ALWAYS_POSITIVE, atom, base, where);
        if (holds >= 0) return holds;
    }

    /* 13c-4. La variabile principale e radici di primi: gli zeri si trovano. */
    if (atom >= 0 && kind == NEVER_ZERO) {
        int free = zero_free(q, atom, base, where);
        if (free >= 0) return free;
    }
    if (failure) return -1;
    *where = base;

    /* 13c-5, 13c-6. Un segno evidente, o garantito dall'andamento. Una
     * espressione sempre negativa non si annulla, ma non è né positiva né
     * non negativa, già per n = base. */
    int sign = evident_sign(q, base);
    if (!sign) sign = monotone_sign(q, base);
    if (failure) return -1;
    if (sign > 0) return 1;
    if (sign < 0) return kind == NEVER_ZERO;

    /* 13c-7. n e potenze come 2^n: il segno per differenze. */
    int grown = difference_rule(kind, q, base, where);
    if (grown >= 0) return grown;
    if (failure) return -1;
    *where = base;

    /* 13c-8. Esponenziali complessi che non si cancellano. */
    return kind == NEVER_ZERO ? exponentials_never_cancel(q, base) : -1;
}

/* Decide una condizione dell'elenco per ogni n >= base: 1, 0 (con un n in cui
 * fallisce in *where) o -1. Prima sul prodotto dei suoi fattori; se così non
 * si decide, e i fattori sono più d'uno, sul segno di ciascuno: il prodotto
 * di fattori che hanno ognuno un segno fisso ha un segno fisso. */
static int condition_decided(const Condition *c, long long base, long long *where) {
    Poly product = c->factor[0];
    for (int f = 1; f < c->count; f++) product = poly_mul(product, c->factor[f]);
    int holds = failure ? -1 : condition_holds(c->kind, product, base, where);
    if (holds >= 0 || c->count == 1 || c->kind == NEVER_ZERO || failure) return holds;

    int sign = 1;
    for (int f = 0; f < c->count; f++) {
        Poly minus = poly_add(poly_const(num_int(0)), c->factor[f], 1);
        if (condition_holds(ALWAYS_POSITIVE, c->factor[f], base, where) == 1) continue;
        if (failure || condition_holds(ALWAYS_POSITIVE, minus, base, where) != 1) return -1;
        sign = -sign;
    }
    *where = base;
    return sign > 0;
}

/* Decide se l'enunciato, con i parametri legati ai valori del punto in uso, è
 * definito per ogni n >= base: ritorna 1 se sì, 0 se no (con un n in cui non
 * lo è in *where e il perché in *why), -1 se non lo sa stabilire. Vedi il
 * paragrafo 13c.
 *
 * Le valutazioni sono tre, e dicono a quale n si riferisce una condizione
 * che fallisce: quelle nate dal calcolo di D(n) a quell'n, quelle nate solo
 * da D(n+1) al successivo, quelle nate solo da D(base) al caso base. La
 * terza serve perché il calcolo con i numeri non controlla tutto: un
 * logaritmo di cos(1) non è un numero, e il suo segno lo decide solo
 * condition_holds(). */
static int defined_for_every(const Statement *statement, long long base, long long *where, const char **why) {
    Rat n = rat_atom(atom_var(induction_var));
    int answer = 1, broken = 0;

    /* Le tre valutazioni, con l'elenco delle condizioni acceso. */
    condition_count = conditions_lost = 0;
    conditions_on = 1;
    difference(statement, n);
    int first = condition_count;
    difference(statement, rat_add(n, rat_int(1), 0));
    int second = condition_count;
    difference(statement, rat_int(base));
    conditions_on = 0;
    if (failure || conditions_lost) answer = -1;
    failure = NULL;

    /* Ogni condizione va decisa. Una che fallisce chiude la questione, ma si
     * guardano tutte, per riferire il più piccolo n in cui qualcosa manca. */
    for (int i = 0; i < condition_count; i++) {
        long long at;
        int holds = condition_decided(&conditions[i], base, &at);
        if (failure) holds = -1;
        failure = NULL;
        if (holds < 0) answer = -1;
        if (holds != 0) continue;
        at = i >= second ? base : at + (i >= first);
        if (!broken || at < *where) { *where = at; *why = conditions[i].why; }
        broken = 1;
    }
    return broken ? 0 : answer;
}

/* Ritorna la posizione nel vocabolario della successione di cui l'atomo BIGOP
 * `atom` è la definizione, o -1 se è una somma scritta nell'enunciato. */
static int bigop_library(int atom) {
    for (int i = 0; i < LIBRARY_COUNT; i++)
        if (library[i].tree == atoms[atom].node) return i;
    return -1;
}

/* 13d. DEFINITO PER PARAMETRI ABBASTANZA GRANDI
 *
 * Il paragrafo 13c cerca un valore dei parametri che vada bene per ogni n.
 * Non sempre esiste: la somma dei ln(x - k) per k da 1 a n è definita per
 * x > n, e nessun x supera tutti gli n. Eppure per ogni n i valori buoni ci
 * sono: tutti quelli abbastanza grandi. È ciò che serve perché l'enunciato
 * non sia vuoto per nessun n, e qui lo si dimostra così.
 *
 * Un polinomio in x, per x abbastanza grande, ha il segno del suo
 * coefficiente di grado massimo (oltre il limite di Cauchy non ha più
 * radici). Una condizione di esistenza che è un polinomio in x con
 * coefficienti in n vale quindi "da un certo x in poi" se il coefficiente di
 * grado massimo ha il segno giusto: e questo, non contenendo più x, è una
 * condizione in n che condition_holds() sa decidere per ogni n.
 *
 * Le condizioni sono in numero finito per ogni n: i due membri in n e in
 * n + 1, e i termini delle somme, uno per ogni indice fino a n + 1. Ognuna
 * vale oltre una sua soglia, quindi tutte insieme oltre la più grande. Per i
 * termini delle somme la condizione si scrive una volta sola, con l'indice
 * generico "estremo inferiore + t" e t >= 0, come fa body_is_positive().
 *
 * Con più parametri si mandano all'infinito uno dopo l'altro: il primo
 * dell'elenco molto più in fretta del secondo, e così via. Conta allora il
 * coefficiente di grado massimo nel primo parametro, poi in quello il
 * coefficiente di grado massimo nel secondo. Si provano i due ordini
 * estremi, e i due versi: tutti verso più infinito, tutti verso meno
 * infinito (dove una potenza dispari cambia segno). */

/* I parametri mandati all'infinito, dal più veloce al più lento, e il verso:
 * +1 verso più infinito, -1 verso meno infinito. Vuoto fuori da
 * defined_eventually(). */
static int far_name[MAX_POINT];
static int far_count;
static int far_sign;

/* Ritorna 1 se la lettera name è uno dei parametri mandati all'infinito. */
static int is_far(long long name) {
    for (int i = 0; i < far_count; i++)
        if (far_name[i] == name) return 1;
    return 0;
}

/* Ritorna 1 se nel sotto-albero node compare, libero, uno di quei parametri.
 * shadow elenca gli indici di somma che nascondono una lettera con lo stesso
 * nome, come in uses_bound_variable(). */
static int node_has_parameter(const Node *node, const NameScope *shadow) {
    if (!node) return 0;
    if (node->kind == N_VAR) return !name_shadowed(shadow, node->name) && is_far(node->name);
    if (node->kind == N_BIGOP) {
        if (node_has_parameter(node->a, shadow) || node_has_parameter(node->b, shadow)) return 1;
        NameScope inner = {node->name, shadow};
        return node_has_parameter(node->c, &inner);
    }
    return node_has_parameter(node->a, shadow) || node_has_parameter(node->b, shadow) ||
           node_has_parameter(node->c, shadow);
}

static int poly_has_parameter(Poly p);

/* Ritorna 1 se il valore dell'atomo dipende da uno dei parametri mandati
 * all'infinito, anche di nascosto: nel termine di una somma, nella base di
 * una potenza o di un logaritmo, nell'argomento di un'arcotangente. */
static int atom_has_parameter(int atom) {
    const Atom *a = &atoms[atom];
    if (a->kind == ATOM_VAR) return is_far(a->id);
    if (a->kind == ATOM_REC) return 0;
    if (a->kind == ATOM_BIGOP) return bigop_library(atom) < 0 && node_has_parameter(a->node, NULL);
    if (a->kind == ATOM_ATAN) return poly_has_parameter(atan_args[a->id].num) || poly_has_parameter(atan_args[a->id].den);
    for (int f = 0; f < a->exponent.count; f++)
        if (atom_has_parameter(a->exponent.factor[f].atom)) return 1;
    if (a->base == BASE_ATOM) return atom_has_parameter((int)a->id);
    return a->base == BASE_POLY && poly_has_parameter(base_polys[a->id]);
}

/* Ritorna 1 se p contiene un atomo che dipende da uno di quei parametri. */
static int poly_has_parameter(Poly p) {
    for (int i = 0; i < p.count; i++)
        for (int f = 0; f < p.term[i].mono.count; f++)
            if (atom_has_parameter(p.term[i].mono.factor[f].atom)) return 1;
    return 0;
}

static int eventual_sign(Poly p, long long base);

/* Ritorna 1 se il prodotto dell'atomo BIGOP `atom` ha tutti i fattori
 * positivi per parametri abbastanza grandi: il corpo, valutato nell'indice
 * generico, ha numeratore e denominatore dello stesso segno. Allora per ogni
 * n il prodotto, che ha un numero finito di fattori, è positivo da un certo
 * punto in poi. Un errore durante la prova non riguarda l'enunciato. */
static int product_far_positive(int atom, long long base) {
    const Node *node = atoms[atom].node;
    const char *saved = failure;
    long long lower;
    int positive = 0;
    env_count = 0;
    library_depth = 0;
    if (node->op && rat_integer(eval(node->a), &lower)) {
        Rat value = eval_body(node, rat_add(rat_int(lower), rat_atom(atom_var(VAR_SLACK)), 0));
        int above = failure ? 0 : eventual_sign(value.num, base), below = failure ? 0 : eventual_sign(value.den, base);
        positive = above * below == 1;
    }
    failure = saved;
    return positive;
}

/* Ritorna il segno che p finisce per avere, per ogni n >= base, quando i
 * parametri sono abbastanza grandi nel verso e nell'ordine in uso: +1 o -1;
 * 2 se si sa solo che non si annulla; 0 se non si sa dire nulla.
 *
 * p si scrive come monomio comune per il resto. Nel monomio comune ogni
 * atomo deve avere un segno noto: i parametri stessi, gli atomi senza
 * parametri di cui 13c conosce il segno, i prodotti di fattori positivi, le
 * potenze di una base positiva. Il resto deve essere un polinomio nei
 * parametri: conta il suo coefficiente di grado massimo, che non li contiene
 * più. */
static int eventual_sign(Poly p, long long base) {
    long long where;
    if (p.count == 0) return 0;

    /* Senza parametri: una condizione in n, da decidere per ogni n. */
    if (!poly_has_parameter(p)) {
        if (condition_holds(ALWAYS_POSITIVE, p, base, &where) == 1) return 1;
        if (condition_holds(ALWAYS_POSITIVE, poly_add(poly_const(num_int(0)), p, 1), base, &where) == 1) return -1;
        return condition_holds(NEVER_ZERO, p, base, &where) == 1 ? 2 : 0;
    }

    /* Il monomio comune. */
    int sign = 1, known = 1;
    Mono common = poly_common(p);
    for (int i = 0; i < common.count; i++) {
        int atom = common.factor[i].atom;
        const Atom *a = &atoms[atom];
        Frac e = common.factor[i].exp;
        if (a->kind == ATOM_VAR && is_far(a->id)) {
            if (far_sign < 0 && e.den != 1) return 0;
            if (far_sign < 0 && e.num % 2) sign = -sign;
        } else if (!atom_has_parameter(atom)) {
            if (atom_is_positive(atom, base)) continue;
            if (atom_never_zero(atom, base, &where) != 1) return 0;
            known = 0;
        } else if (a->kind == ATOM_POW && a->base == BASE_EI) {
            known = 0;
        } else if (a->kind == ATOM_BIGOP) {
            if (!product_far_positive(atom, base)) return 0;
        } else if (a->kind != ATOM_POW || a->base != BASE_POLY || eventual_sign(base_polys[a->id], base) != 1) {
            return 0;
        }
    }
    Term divisor;
    divisor.coef = num_int(1);
    divisor.mono = mono_pow(&common, frac_int(-1));
    Poly lead = poly_mul(p, poly_term(divisor));

    /* Il coefficiente di grado massimo, un parametro dopo l'altro. */
    for (int i = 0; i < far_count && !failure; i++) {
        Poly part[MAX_UNIVARIATE + 1];
        int degree = poly_split(lead, atom_var(far_name[i]), part, MAX_UNIVARIATE);
        if (degree < 0) return 0;
        if (far_sign < 0 && degree % 2) sign = -sign;
        lead = part[degree];
    }
    if (failure || poly_has_parameter(lead)) return 0;
    int tail = eventual_sign(lead, base);
    if (tail == 0) return 0;
    return tail == 2 || !known ? 2 : sign * tail;
}

/* Ritorna 1 se per ogni n >= base l'enunciato è definito per tutti i valori
 * dei parametri abbastanza grandi, in uno dei versi e degli ordini provati;
 * -1 se non riesce a stabilirlo. I parametri sono quelli di point_name[].
 * Vedi il paragrafo 13d. */
static int defined_eventually(const Statement *statement, long long base) {
    Rat n = rat_atom(atom_var(induction_var));
    int count = point_count, known = atom_count, found = 0;

    /* Le condizioni, con i parametri come lettere: i due membri in n e in
     * n + 1, e il termine generico di ogni somma e prodotto. */
    point_count = 0;
    condition_count = conditions_lost = 0;
    conditions_on = 1;
    failure = NULL;
    difference(statement, n);
    difference(statement, rat_add(n, rat_int(1), 0));
    for (int x = 0; x < known && !failure; x++) {
        long long lower;
        if (atoms[x].kind != ATOM_BIGOP) continue;
        env_count = 0;
        library_depth = 0;
        if (!rat_integer(eval(atoms[x].node->a), &lower)) { conditions_lost = 1; break; }
        eval_body(atoms[x].node, rat_add(rat_int(lower), rat_atom(atom_var(VAR_SLACK)), 0));
    }
    conditions_on = 0;
    point_count = count;
    int lost = failure || conditions_lost;
    failure = NULL;

    /* I due ordini e i due versi. Ogni condizione chiede il segno del
     * prodotto dei suoi fattori. */
    far_count = count;
    for (int attempt = 0; attempt < (count > 1 ? 4 : 2) && !found && !lost; attempt++) {
        far_sign = attempt % 2 ? -1 : 1;
        for (int i = 0; i < count; i++) far_name[i] = point_name[attempt < 2 ? i : count - 1 - i];
        found = 1;
        for (int i = 0; i < condition_count && found; i++) {
            const Condition *c = &conditions[i];
            int sign = 1;
            for (int f = 0; f < c->count && found; f++) {
                int own = eventual_sign(c->factor[f], base);
                if (failure || own == 0 || (own == 2 && c->kind != NEVER_ZERO)) found = 0;
                if (own == -1) sign = -sign;
                failure = NULL;
            }
            if (c->kind != NEVER_ZERO && sign < 0) found = 0;
        }
    }
    far_count = 0;
    return found ? 1 : -1;
}

/* I numeri semplici che la verifica numerica dà ai parametri: positivi e
 * negativi, interi e frazioni, grandi e piccoli. */
static const Frac point_samples[] = {{2, 1}, {3, 1}, {1, 2}, {5, 1}, {1, 3}, {-2, 1}, {3, 2}, {7, 1},
                                     {-1, 2}, {4, 1}, {-3, 1}, {1000, 1}, {1, 1000}};
enum { POINT_SAMPLES = sizeof point_samples / sizeof *point_samples };

/* Ciò che un conto di prova lascia dietro di sé e che va tolto quando il
 * conto non serve più: gli atomi, le basi e le arcotangenti nati durante il
 * conto, e la memoria presa dall'arena. */
typedef struct {
    int atoms, polys, atans;  /* quanti ce n'erano prima del conto */
    size_t arena;             /* byte dell'arena occupati prima del conto */
} Scratch;

/* Ritorna lo stato di adesso, da ridare a scratch_drop() dopo il conto. */
static Scratch scratch_mark(void) { return (Scratch){atom_count, base_poly_count, atan_count, arena_used}; }

/* Toglie tutto ciò che è nato dopo mark. */
static void scratch_drop(Scratch mark) {
    atom_count = mark.atoms;
    base_poly_count = mark.polys;
    atan_count = mark.atans;
    arena_used = mark.arena;
}

/* I VALORI DEI PARAMETRI SCELTI GUARDANDO LE CONDIZIONI
 *
 * La verifica numerica (13e) prova per i parametri pochi numeri semplici. Un
 * enunciato definito solo per valori particolari, come la radice di
 * x - 5000, non ne incontrerebbe mai uno buono. Quando i numeri semplici non
 * bastano si guarda che cosa l'enunciato chiede: le condizioni di esistenza
 * raccolte con i parametri lasciati come lettere sono, nei casi comuni,
 * polinomi nei parametri. Per ogni parametro, uno alla volta, le condizioni
 * che contengono solo lui dividono la retta in intervalli, separati dalle
 * radici reali dei polinomi: il segno di ogni polinomio è costante dentro un
 * intervallo, quindi basta provare un punto per intervallo.
 *
 * Le radici si cercano in virgola mobile, il solo punto del programma in cui
 * non si usa l'aritmetica esatta. Non è un rischio: servono solo a proporre
 * dei candidati. Ogni candidato viene poi controllato con conti esatti, qui
 * e nella verifica vera e propria. Un errore di arrotondamento può far
 * perdere un candidato buono, mai farne accettare uno cattivo. */

/* Mette in root[], in ordine crescente, le radici reali del polinomio
 * c[0] + c[1] x + ... + c[degree] x^degree, approssimate, e ne ritorna il
 * numero. root deve avere almeno max(degree, 1) posti.
 *
 * Tra due zeri consecutivi della derivata il polinomio è monotono, quindi ha
 * al più una radice, e c'è esattamente quando il segno agli estremi è
 * diverso: la si trova per bisezione. Gli zeri della derivata, che ha un
 * grado in meno, si trovano allo stesso modo, fino al grado 1. Agli estremi
 * della retta fa da confine il limite di Cauchy (vedi sign_holds()). */
static int real_roots(const double *c, int degree, double *root) {
    double derivative[MAX_UNIVARIATE + 1], turn[MAX_UNIVARIATE + 1], bound = 0;
    while (degree > 0 && c[degree] == 0) degree--;
    if (degree < 1) return 0;
    if (degree == 1) { root[0] = -c[0] / c[1]; return 1; }
    for (int i = 0; i < degree; i++) {
        double ratio = c[i] / c[degree];
        if (ratio < 0) ratio = -ratio;
        if (ratio > bound) bound = ratio;
        derivative[i] = (i + 1) * c[i + 1];
    }
    bound += 1;
    int turns = real_roots(derivative, degree - 1, turn), count = 0;

    /* Gli intervalli di monotonia: da -bound al primo zero della derivata, e
     * così via fino a bound. */
    double left = -bound;
    for (int k = 0; k <= turns; k++) {
        double right = k < turns ? turn[k] : bound, at[2] = {left, right}, value[2];
        for (int s = 0; s < 2; s++) {
            value[s] = 0;
            for (int i = degree; i >= 0; i--) value[s] = value[s] * at[s] + c[i];
        }
        if (value[1] == 0) {
            root[count++] = right;
        } else if (value[0] != 0 && (value[0] < 0) != (value[1] < 0)) {
            /* Bisezione: il segno in `low` resta quello di value[0]. */
            double low = left, high = right;
            for (int step = 0; step < 200; step++) {
                double middle = (low + high) / 2, v = 0;
                for (int i = degree; i >= 0; i--) v = v * middle + c[i];
                if ((v < 0) == (value[0] < 0)) low = middle; else high = middle;
            }
            root[count++] = (low + high) / 2;
        }
        left = right;
    }
    return count;
}

/* Ritorna il segno, -1, 0 o 1, del polinomio p nel punto in cui l'atomo
 * `atom` vale y^root, con y razionale: un termine c atom^{a/b} vi vale
 * c y^{a root / b}. Chi chiama garantisce che in p compare solo quell'atomo,
 * con esponenti non negativi il cui denominatore divide root. Il conto è
 * esatto, su interi a 128 bit; se non bastano mette 0 in *known, che chi
 * chiama ha messo a 1.
 *
 * Con y = u/v e K il più grande degli esponenti interi, moltiplicando per
 * v^K e per il minimo comune multiplo L dei denominatori dei coefficienti
 * ogni termine diventa un intero, e il segno non cambia perché v e L sono
 * positivi. */
static int power_sum_sign(Poly p, int atom, long long root, Frac y, int *known) {
    long long top = 0;
    __int128 scale = 1, total = 0;
    for (int i = 0; i < p.count; i++) {
        Frac e = mono_exponent(&p.term[i].mono, atom);
        long long den = p.term[i].coef.re.den;
        if (e.num * (root / e.den) > top) top = e.num * (root / e.den);
        scale = scale / gcd128(scale, den) * den;
        if (scale > COEF_LIMIT) { *known = 0; return 0; }
    }
    for (int i = 0; i < p.count; i++) {
        Frac e = mono_exponent(&p.term[i].mono, atom);
        long long power = e.num * (root / e.den);
        __int128 term = (__int128)p.term[i].coef.re.num * (scale / p.term[i].coef.re.den);
        for (long long k = 0; k < top; k++)
            if (__builtin_mul_overflow(term, (__int128)(k < power ? y.num : y.den), &term)) { *known = 0; return 0; }
        if (__builtin_add_overflow(total, term, &total)) { *known = 0; return 0; }
    }
    return (total > 0) - (total < 0);
}

/* Sceglie per i parametri dell'enunciato dei valori che rispettano le sue
 * condizioni di esistenza, e li mette in point_value[]. Ritorna 1 se ci
 * riesce, 0 se non trova nulla da proporre. Chi chiama deve poi verificare
 * il punto: qui si guardano solo le condizioni che si sanno leggere,
 * calcolate nel primo e nell'ultimo n della verifica numerica.
 *
 * I parametri si fissano uno alla volta. Fissato un valore, lo si sostituisce
 * nelle condizioni, così quelle che legano due parametri diventano
 * condizioni sul secondo.
 *
 * Per il parametro x si sanno leggere le condizioni che sono polinomi in una
 * sola quantità T, anche con esponenti frazionari. Di solito T è x stesso.
 * Ma se l'enunciato contiene la radice di un'espressione di primo grado,
 * come x - 5000, T è quell'espressione: la condizione
 * "radice(x - 5000) > 100" si legge "T^{1/2} > 100". Con gli esponenti
 * frazionari si pone T = y^d, dove d è il minimo comune multiplo dei loro
 * denominatori: le condizioni diventano polinomi in y, e scegliendo y
 * razionale le radici di T sono numeri esatti, che la verifica sa calcolare.
 * Da y si risale a T e poi a x. */
static int choose_point(const Statement *statement, long long base) {
    int count = point_count, useful = 0;

    /* Le condizioni, con i parametri come lettere. Un errore ferma solo la
     * raccolta: si usa ciò che è stato annotato fino a lì. Di una condizione
     * su più fattori conta il prodotto. */
    point_count = 0;
    condition_count = conditions_lost = 0;
    conditions_on = 1;
    failure = NULL;
    difference(statement, rat_int(base));
    failure = NULL;
    difference(statement, rat_int(base + SEARCH_SPAN));
    conditions_on = 0;
    undefined = 0;
    point_count = count;
    for (int i = 0; i < condition_count; i++) {
        for (int f = 1; f < conditions[i].count; f++) conditions[i].factor[0] = poly_mul(conditions[i].factor[0], conditions[i].factor[f]);
        conditions[i].count = 1;
    }
    if (failure) condition_count = 0;
    failure = NULL;

    for (int j = 0; j < count; j++) {
        int x = atom_var(point_name[j]), carrier = x, roots = 0, candidates = 0, chosen = -1;
        long long c[MAX_UNIVARIATE + 1], scale, root = 1;
        Frac slope = frac_int(1), shift = frac_int(0);
        Poly view[MAX_CONDITIONS];
        int usable[MAX_CONDITIONS];
        double real[MAX_CONDITIONS * MAX_UNIVARIATE];
        Frac candidate[POINT_SAMPLES + MAX_CONDITIONS * MAX_UNIVARIATE + 1];

        /* La quantità T: la base di una radice, se è di primo grado in x. */
        for (int i = 0; i < condition_count && carrier == x; i++)
            for (int t = 0; t < conditions[i].factor[0].count && carrier == x; t++)
                for (int f = 0; f < conditions[i].factor[0].term[t].mono.count; f++) {
                    int atom = conditions[i].factor[0].term[t].mono.factor[f].atom;
                    const Atom *a = &atoms[atom];
                    if (a->kind != ATOM_POW || a->base != BASE_POLY || a->exponent.count != 0) continue;
                    if (poly_coefficients(base_polys[a->id], x, c, &scale) != 1) continue;
                    carrier = atom;
                    slope = frac_make(c[1], scale);
                    shift = frac_make(c[0], scale);
                    break;
                }

        /* Le condizioni scritte in T, e quelle che vi si sanno leggere: solo
         * T, con esponenti non negativi. d è il loro denominatore comune. */
        for (int i = 0; i < condition_count; i++) {
            Rat back = rat_div(rat_add(rat_atom(carrier), rat_frac(shift), 1), rat_frac(slope));
            view[i] = carrier == x ? conditions[i].factor[0] : poly_substitute(conditions[i].factor[0], x, back).num;
            usable[i] = !failure;
            failure = NULL;
            for (int t = 0; t < view[i].count && usable[i]; t++) {
                const Term *term = &view[i].term[t];
                Frac e = mono_exponent(&term->mono, carrier);
                usable[i] = term->coef.im.num == 0 && term->mono.count == (e.num != 0) && e.num >= 0 && e.den <= 12;
            }
            for (int t = 0; t < view[i].count && usable[i]; t++) {
                long long den = mono_exponent(&view[i].term[t].mono, carrier).den;
                root = root / (long long)gcd128(root, den) * den;
            }
        }

        /* Le radici reali, in y, dei polinomi a cui si riducono. */
        for (int i = 0; i < condition_count; i++) {
            double coefficient[MAX_UNIVARIATE + 1] = {0};
            int degree = 0;
            for (int t = 0; t < view[i].count && usable[i]; t++) {
                Frac e = mono_exponent(&view[i].term[t].mono, carrier), value = view[i].term[t].coef.re;
                long long power = e.num * (root / e.den);
                if (power > MAX_UNIVARIATE) { usable[i] = 0; break; }
                coefficient[power] += (double)value.num / (double)value.den;
                if (power > degree) degree = (int)power;
            }
            if (usable[i] && degree >= 1) {
                roots += real_roots(coefficient, degree, real + roots);
                useful = 1;
            }
        }

        /* In ordine crescente, con un inserimento alla volta. */
        for (int a = 1; a < roots; a++)
            for (int b = a; b > 0 && real[b - 1] > real[b]; b--) {
                double swap = real[b];
                real[b] = real[b - 1];
                real[b - 1] = swap;
            }

        /* I candidati per y: prima i numeri semplici, poi un numero per ogni
         * intervallo tra due radici (il più semplice: un intero se c'è, se
         * no un multiplo di 1/2, di 1/4, ...) e uno oltre ciascun estremo. */
        for (int k = 0; k < POINT_SAMPLES; k++) candidate[candidates++] = point_samples[k];
        for (int k = 0; k <= roots && roots > 0; k++) {
            double low = k > 0 ? real[k - 1] : real[0] - 2, high = k < roots ? real[k] : real[roots - 1] + 2;
            if (low < -1e12 || high > 1e12) continue;
            for (long long den = 1; den <= 1048576; den *= 2) {
                long long num = (long long)(low * (double)den);
                while ((double)num <= low * (double)den) num++;
                if ((double)num < high * (double)den) { candidate[candidates++] = frac_make(num, den); break; }
            }
        }

        /* Il primo candidato che rispetta, con un conto esatto, tutte le
         * condizioni lette. Con T = y^d e d > 1, y è una radice: positivo. */
        for (int k = 0; k < candidates && chosen < 0; k++) {
            int fine = root == 1 || candidate[k].num > 0;
            for (int i = 0; i < condition_count && fine; i++) {
                int known = 1, sign = usable[i] ? power_sum_sign(view[i], carrier, root, candidate[k], &known) : 1;
                Requirement kind = conditions[i].kind;
                fine = known && (kind == NEVER_ZERO ? sign != 0 : kind == ALWAYS_POSITIVE ? sign > 0 : sign >= 0);
            }
            if (fine) chosen = k;
        }
        if (chosen < 0) return 0;

        /* Da y a T = y^d, e da T a x. */
        Frac value = frac_int(1);
        for (long long k = 0; k < root && !failure; k++) value = frac_mul(value, candidate[chosen]);
        point_value[j] = frac_div(frac_add(value, frac_neg(shift)), slope);

        /* Il valore scelto entra nelle condizioni che restano; quelle in cui
         * non si riesce a sostituirlo non contano più. */
        for (int i = 0; i < condition_count && !failure; i++) {
            Poly next = poly_substitute(conditions[i].factor[0], x, rat_frac(point_value[j])).num;
            if (failure) { conditions[i].kind = NEVER_ZERO; next = poly_const(num_int(1)); }
            failure = NULL;
            conditions[i].factor[0] = next;
        }
        if (failure) { failure = NULL; return 0; }
    }
    return useful;
}

/* Il punto in cui l'ultima verify_instances() ha stabilito che l'enunciato
 * è definito per ogni n (13c): i primi fixed_count parametri, con i loro
 * valori. fixed_count vale -1 se non c'è, perché l'ha stabilito in altro
 * modo (13d). Le chiamate con `every` a zero non lo toccano. Lo usa il
 * certificato (13h), che lo consegna al verificatore perché lo ricontrolli. */
static int fixed_count = -1;
static int fixed_name[MAX_POINT];
static Frac fixed_value[MAX_POINT];

/* 13e. Verifica indipendente di un enunciato già dimostrato, a partire dal
 * caso base `base`. Ritorna NULL se conferma la dimostrazione, altrimenti il
 * motivo, in italiano, per cui il verdetto non va emesso.
 *
 * La dimostrazione è algebra sulle lettere: vale "dove i due membri sono
 * definiti", e non dice se quel dove esiste. ln(-x) = ln(x) passa, perché i
 * logaritmi sono trattati come ln|x|, ma non c'è un solo x in cui tutti e due
 * i membri abbiano senso. Qui si fa ciò che l'algebra non fa: si danno ai
 * parametri dei valori numerici e si calcolano davvero i due membri per
 * n = base, base + 1, ..., base + SEARCH_SPAN. Con i numeri al posto delle
 * lettere i controlli della valutazione (capitolo 11) scattano: logaritmo di
 * un numero non positivo, radice di un numero negativo, divisione per zero.
 * Poi, se `every` è diverso da zero, si decide se nello stesso punto i due
 * membri sono definiti anche per tutti gli n successivi (13c); e se non lo
 * sono, se per ogni n lo sono per tutti i valori dei parametri abbastanza
 * grandi (13d).
 *
 * Serve un punto in cui tutto è definito per ogni n. I valori provati per i
 * parametri sono pochi numeri semplici, positivi e negativi, grandi e
 * piccoli, combinati in modi diversi a ogni tentativo; se nessuno va bene,
 * un ultimo tentativo usa valori scelti guardando le condizioni di esistenza
 * (choose_point()). Si rinuncia, e il verdetto diventa NON DIMOSTRATO, in
 * quattro casi:
 *
 *   - in nessun punto provato il caso base è definito: l'enunciato sembra
 *     vuoto;
 *   - in ogni punto provato c'è un n in cui un'espressione non è definita:
 *     l'enunciato non può valere "per ogni n";
 *   - c'è un punto che i numeri non smentiscono, ma non si sa stabilire che
 *     regga per tutti gli n, o i numeri sono troppo grandi per calcolarlo;
 *   - in un punto i due membri sono numeri diversi: sarebbe un errore del
 *     programma, e la dimostrazione non va creduta.
 *
 * Un conto che si ferma per un limite del programma, come i numeri troppo
 * grandi, non dice nulla: da lì in poi quel punto non viene più calcolato,
 * senza obiezioni. Ma se si ferma già al primo valore il punto non ha
 * confermato niente, e non conta.
 *
 * `every` è zero quando si ricontrolla una formula scritta in una
 * dimostrazione (13g): lì conta solo che i numeri tornino.
 *
 * I conti fatti qui non servono dopo: atomi e memoria tornano com'erano. */
static const char *verify_instances(const Statement *statement, long long base, int every) {
    static char text[200];
    if (every) fixed_count = -1;
    Scratch mark = scratch_mark();
    const char *problem = NULL;
    long long reached = base - 1;  /* l'ultimo n fin dove un tentativo è arrivato */
    const char *why = NULL;        /* che cosa non è definito in quell'n */
    int undecided = 0;             /* 1 se un punto non è smentito, ma nemmeno confermato per ogni n */
    int far = 0;                   /* esito di defined_eventually(), 0 finché non è stato chiesto */

    /* I parametri: le lettere dell'enunciato diverse dalla variabile di
     * induzione. Pi greco è un numero, non un parametro. */
    point_count = 0;
    for (int i = 0; i < mark.atoms && point_count < MAX_POINT; i++)
        if (atoms[i].kind == ATOM_VAR && atoms[i].id != induction_var && atoms[i].id != VAR_PI && atoms[i].id != VAR_SLACK)
            point_name[point_count++] = (int)atoms[i].id;

    /* Senza parametri c'è un solo punto da provare. Con i parametri, dopo i
     * tentativi con i numeri semplici ce n'è uno con valori scelti apposta. */
    int attempts = point_count ? 4 * POINT_SAMPLES : 1, confirmed = 0;
    for (int attempt = 0; attempt <= attempts && !confirmed && !problem; attempt++) {
        if (attempt == attempts) {
            int chosen = point_count && choose_point(statement, base);
            scratch_drop(mark);
            if (!chosen) break;
        } else {
            /* Valori diversi per parametri diversi, e combinazioni diverse a
             * ogni giro dell'elenco. */
            for (int j = 0; j < point_count; j++)
                point_value[j] = point_samples[(attempt * (2 * j + 1) + (attempt / POINT_SAMPLES) * j + j) % POINT_SAMPLES];
        }

        confirmed = 1;
        for (long long c = base; c <= base + SEARCH_SPAN && confirmed && !problem; c++) {
            Num value;
            failure = NULL;
            undefined = 0;
            Rat d = difference(statement, rat_int(c));
            int limit = failure && !undefined;
            if (failure && undefined) {
                confirmed = 0;
                if (c > reached) { reached = c; why = failure; }
            } else if (limit && c == base) {
                /* Nemmeno il primo valore si è potuto calcolare: questo punto
                 * non ha confermato nulla. Prenderlo per buono farebbe
                 * passare x^100 + ln(-x) = x^100 + ln(x), dove i numeri
                 * diventano troppo grandi prima di arrivare al logaritmo. */
                confirmed = 0;
                undecided = 1;
            } else if (!failure && rat_number(d, &value) && !num_is_zero(value)) {
                snprintf(text, sizeof text, "la verifica numerica non conferma la dimostrazione: per %c = %lld i due membri sono diversi",
                         induction_var, c);
                problem = text;
            }
            scratch_drop(mark);
            if (limit) break;
        }

        /* 13c. Il punto regge per i primi n: regge per tutti? */
        if (confirmed && every && !problem) {
            long long where = base;
            const char *broken = NULL;
            failure = NULL;
            int answer = defined_for_every(statement, base, &where, &broken);
            scratch_drop(mark);
            if (answer == 1) {
                fixed_count = point_count;
                memcpy(fixed_name, point_name, sizeof fixed_name);
                memcpy(fixed_value, point_value, sizeof fixed_value);
            }

            /* 13d. Questo valore non va bene per ogni n: ma forse per ogni n
             * vanno bene tutti i valori abbastanza grandi. Lo si chiede una
             * volta sola, perché non dipende dal punto. */
            if (answer != 1 && point_count && !far) {
                far = defined_eventually(statement, base);
                scratch_drop(mark);
            }
            if (answer != 1 && far != 1) confirmed = 0;
            if (answer < 0) undecided = 1;
            if (answer == 0 && where > reached) { reached = where; why = broken; }
        }
    }
    if (!confirmed && !problem) {
        if (undecided) {
            snprintf(text, sizeof text, "non riesco a stabilire che le espressioni dell'enunciato siano definite per ogni %c", induction_var);
            problem = text;
        } else if (reached <= base && point_count) {
            problem = "non trovo valori dei parametri per cui tutte le espressioni dell'enunciato sono definite";
        } else if (why == REWRITTEN) {
            snprintf(text, sizeof text, "per %c = %lld %s", induction_var, reached, why);
            problem = text;
        } else {
            snprintf(text, sizeof text, "per %c = %lld l'enunciato non è definito: %s", induction_var, reached, why);
            problem = text;
        }
    }
    failure = NULL;
    undefined = 0;
    point_count = 0;
    return problem;
}

/* 13f. LA DIMOSTRAZIONE SCRITTA
 *
 * Il testo ripercorre ciò che il programma ha fatto, con le espressioni vere:
 *
 *   - caso base: i due membri con il numero al posto di n, e il loro valore;
 *   - ipotesi induttiva: l'enunciato per n;
 *   - passo: l'enunciato per n + 1; per ogni somma o prodotto, i termini che
 *     si aggiungono passando da n a n + 1; il valore che l'ipotesi dà alla
 *     somma ricavata; e ciò che i due membri diventano dopo la sostituzione.
 *
 * Servono due modi di scrivere un'espressione. put_node() riscrive un albero
 * com'è nell'enunciato, eventualmente con una variabile sostituita: serve per
 * "il membro sinistro per n + 1" e per "il termine con k = n + 1". put_rat()
 * scrive invece una frazione di polinomi negli atomi, cioè la forma a cui la
 * valutazione riduce ogni espressione: serve per i valori e per i risultati
 * dei conti. Un'espressione troppo lunga non viene scritta, e il testo dice
 * solo che il conto è stato fatto. */

/* Scrive il numero v in LaTeX. */
static void put_frac(Frac v) {
    if (v.den == 1) proof_add("%lld", v.num);
    else proof_add("%s\\frac{%lld}{%lld}", v.num < 0 ? "-" : "", llabs(v.num), v.den);
}

/* La sostituzione in corso mentre put_node() scrive: la variabile shown_name
 * va scritta come l'espressione shown_value. Con shown_value NULL non si
 * sostituisce nulla. */
static int shown_name;
static const Node *shown_value;

/* Ritorna quanto strettamente il nodo tiene insieme i suoi operandi, per
 * decidere le parentesi: 1 somme e differenze, 2 somme e prodotti scritti con
 * \sum e \prod, 3 prodotti, 4 potenze e fattoriali, 5 ciò che è già un blocco
 * unico.
 *
 * Il livello 2 esiste perché un \sum prende come corpo tutto il prodotto che
 * lo segue (capitolo 9): come addendo non vuole parentesi, come fattore sì,
 * altrimenti inghiottirebbe i fattori scritti dopo. */
static int node_precedence(const Node *n) {
    switch (n->kind) {
    case N_ADD: case N_SUB: case N_NEG: return 1;
    case N_BIGOP: return 2;
    case N_MUL: return 3;
    case N_POW: return 4;
    case N_CALL: return n->op == FN_FACT ? 4 : 5;
    case N_NUM: return n->value < 0 ? 1 : 5;
    default: return 5;
    }
}

/* Scrive in LaTeX l'espressione dell'albero n, applicando la sostituzione in
 * corso. need è la precedenza minima che il contesto accetta senza
 * parentesi: un nodo che lega meno viene messo tra parentesi.
 *
 * Warning: se aggiungi un tipo di nodo o una funzione, aggiungine il caso
 * anche qui; ciò che questa funzione scrive deve rileggersi, con il parser
 * del capitolo 9, come l'espressione di partenza. */
static void put_node(const Node *n, int need) {
    static const char *const call_name[] = {[FN_SIN] = "sin", [FN_COS] = "cos", [FN_TAN] = "tan", [FN_COT] = "cot",
                                            [FN_ARCTAN] = "arctan", [FN_LN] = "ln", [FN_ARCSIN] = "arcsin",
                                            [FN_ARCCOS] = "arccos", [FN_ARCCOT] = "arccot"};

    /* La variabile sostituita. Dentro l'espressione che la sostituisce non
     * si sostituisce di nuovo. */
    if (n->kind == N_VAR && shown_value && n->name == shown_name) {
        const Node *value = shown_value;
        shown_value = NULL;
        put_node(value, need);
        shown_value = value;
        return;
    }

    int wrap = node_precedence(n) < need;
    if (wrap) proof_add("\\left(");
    switch (n->kind) {
    case N_NUM:
        proof_add("%lld", n->value);
        break;
    case N_VAR:
        if (n->name == VAR_PI) proof_add("\\pi"); else proof_add("%c", n->name);
        break;
    case N_SEQ:
        proof_add("%c_{", n->name);
        put_node(n->a, 0);
        proof_add("}");
        break;
    case N_NEG:
        proof_add("-");
        put_node(n->a, 3);
        break;
    case N_ADD: case N_SUB:
        put_node(n->a, 1);
        proof_add(n->kind == N_ADD ? " + " : " - ");
        put_node(n->b, 2);
        break;
    case N_MUL: {
        /* Un numero davanti a una lettera si scrive accostato, 2n; ma non se
         * al posto della lettera va scritto un numero, perché 2 e 1
         * accostati si leggerebbero 21. */
        int replaced = shown_value && n->b->kind == N_VAR && n->b->name == shown_name;
        int juxtaposed = n->a->kind == N_NUM && n->b->kind == N_VAR && !(replaced && shown_value->kind == N_NUM);
        put_node(n->a, 3);
        if (!juxtaposed) proof_add(" \\cdot ");
        put_node(n->b, 4);
        break;
    }
    case N_DIV:
        proof_add("\\frac{");
        put_node(n->a, 0);
        proof_add("}{");
        put_node(n->b, 0);
        proof_add("}");
        break;
    case N_POW:
        /* La potenza di una funzione si scrive \cos^{2}(x), come la legge il
         * parser. */
        if (n->a->kind == N_CALL && n->a->op >= FN_SIN && n->a->op <= FN_LN) {
            proof_add("\\%s^{", call_name[n->a->op]);
            put_node(n->b, 0);
            proof_add("}\\left(");
            put_node(n->a->a, 0);
            proof_add("\\right)");
            break;
        }
        /* Una frazione come base va tra parentesi: \frac{1}{x}^{2} si
         * rilegge bene, ma a occhio sembra il quadrato del solo x. */
        if (n->a->kind == N_DIV) proof_add("\\left(");
        put_node(n->a, 5);
        if (n->a->kind == N_DIV) proof_add("\\right)");
        proof_add("^{");
        put_node(n->b, 0);
        proof_add("}");
        break;
    case N_BIGOP: {
        /* L'indice nasconde, nel corpo, una variabile con lo stesso nome. */
        const Node *kept = shown_value;
        proof_add("\\%s_{%c=", n->op ? "prod" : "sum", n->name);
        put_node(n->a, 0);
        proof_add("}^{");
        put_node(n->b, 0);
        proof_add("} ");
        if (n->name == shown_name) shown_value = NULL;
        put_node(n->c, 3);
        shown_value = kept;
        break;
    }
    case N_CALL:
        if (n->op == FN_FACT) {
            put_node(n->a, 5);
            proof_add("!");
        } else if (n->op == FN_BINOM) {
            proof_add("\\binom{");
            put_node(n->a, 0);
            proof_add("}{");
            put_node(n->b, 0);
            proof_add("}");
        } else if (n->op == FN_ROOT) {
            proof_add("\\sqrt");
            if (n->b->kind != N_NUM || n->b->value != 2) { proof_add("["); put_node(n->b, 0); proof_add("]"); }
            proof_add("{");
            put_node(n->a, 0);
            proof_add("}");
        } else if (n->op == FN_ABS) {
            proof_add("\\left|");
            put_node(n->a, 0);
            proof_add("\\right|");
        } else {
            if (n->op == FN_LOG) { proof_add("\\log_{"); put_node(n->b, 0); proof_add("}"); }
            else proof_add("\\%s", call_name[n->op]);
            proof_add("\\left(");
            put_node(n->a, 0);
            proof_add("\\right)");
        }
        break;
    case N_APPLY:
        /* Un'operazione dichiarata (9g) si scrive tra i suoi due argomenti,
         * e sempre tra parentesi, come la grammatica la vuole. */
        if (n->name >= OPERATION_NAMES) {
            proof_add("\\left(");
            put_node(n->a, 5);
            proof_add(" \\%s ", operation_symbols[n->name - OPERATION_NAMES]);
            put_node(n->b, 5);
            proof_add("\\right)");
            break;
        }
        proof_add("%c\\left(", n->name);
        put_node(n->a, 0);
        proof_add("\\right)");
        break;
    case N_DERIV:
        /* Il segno deriva tutto il term che lo segue (9d): tra parentesi,
         * non si prende i fattori scritti dopo. */
        proof_add("\\left(\\frac{d^{%lld}}{d%c^{%lld}}\\left(", n->value, n->name, n->value);
        put_node(n->a, 0);
        proof_add("\\right)\\right)");
        break;
    }
    if (wrap) proof_add("\\right)");
}

/* Ritorna l'albero dell'espressione a * variable + c, con a positivo, scritta
 * nel modo più breve: n, n + 1, 2 n - 1. */
static Node *node_affine(long long a, int variable, long long c) {
    Node *n = node_new(N_VAR, NULL, NULL);
    n->name = variable;
    if (a != 1) n = node_new(N_MUL, node_num(a), n);
    if (c > 0) return node_new(N_ADD, n, node_num(c));
    if (c < 0) return node_new(N_SUB, n, node_num(-c));
    return n;
}

/* Prototipi in avanti necessari: un atomo può contenere una frazione (le
 * arcotangenti), un polinomio (le basi) o un monomio (gli esponenti), e
 * questi sono fatti di atomi. */
static void put_rat(Rat r);
static void put_terms(Poly p);
static void put_mono(const Mono *m);

/* Diventa 1 quando put_rat() incontra una quantità che il LaTeX degli
 * enunciati non sa dire: un numero immaginario, o una potenza di e^i che non
 * sia una potenza di -1. Seni e coseni sono calcolati con gli esponenziali
 * complessi, ma in quella forma non si possono né scrivere in modo leggibile
 * né rileggere: chi chiama rinuncia a scrivere l'espressione. */
static int unwritable;

/* Scrive la somma o il prodotto dell'atomo BIGOP `atom` con `shift` termini
 * in più: l'estremo superiore è dilation * n + offset + shift. Le successioni
 * del vocabolario si scrivono con il loro nome: n!, H_{n}. Un atomo è una
 * funzione di n così com'è: la sostituzione in corso non lo riguarda. */
static void put_bigop(int atom, long long shift) {
    const Atom *a = &atoms[atom];
    const Node *upper = node_affine(a->dilation, induction_var, a->offset + shift), *kept = shown_value;
    int named = bigop_library(atom);
    shown_value = NULL;
    if (named >= 0 && library[named].name == '!') {
        put_node(upper, 5);
        proof_add("!");
    } else if (named >= 0) {
        proof_add("%c_{", library[named].name);
        put_node(upper, 0);
        proof_add("}");
    } else {
        proof_add("\\%s_{%c=", a->node->op ? "prod" : "sum", a->node->name);
        put_node(a->node->a, 0);
        proof_add("}^{");
        put_node(upper, 0);
        proof_add("} ");
        put_node(a->node->c, 3);
    }
    shown_value = kept;
}

/* Scrive l'atomo elevato a exp, diverso da zero. Ogni tipo di atomo si scrive
 * come la quantità che rappresenta (vedi il capitolo 4), nel LaTeX che il
 * parser del capitolo 9 sa rileggere:
 *
 *   VAR    la lettera;
 *   BIGOP  la somma o il prodotto, tra parentesi, o il nome nel vocabolario;
 *   REC    il termine della successione, come F_{n + 1};
 *   POW    base^{esponente}: l'esponente dell'atomo e exp si moltiplicano;
 *          l'esponente 1/2 su una base presa come lettera è una radice;
 *          e^{i pi M} con M intero è (-1)^M (vedi 4g);
 *   LN     \ln del valore assoluto della base;
 *   ATAN   \arctan dell'argomento.
 *
 * Warning: se aggiungi un tipo di atomo, aggiungine il caso qui. */
static void put_atom(int atom, Frac exp) {
    const Atom *a = &atoms[atom];
    int one = exp.num == 1 && exp.den == 1;
    switch (a->kind) {
    case ATOM_VAR:
        if (a->id == VAR_SLACK) unwritable = 1;
        else if (a->id == VAR_PI) proof_add("\\pi");
        else proof_add("%c", (int)a->id);
        break;
    case ATOM_REC:
        proof_add("%c_{", library[a->id].name);
        put_node(node_affine(a->dilation, induction_var, a->offset), 0);
        proof_add("}");
        break;
    case ATOM_BIGOP: {
        int named = bigop_library(atom) >= 0;
        if (!named) proof_add("\\left(");
        put_bigop(atom, 0);
        if (!named) proof_add("\\right)");
        break;
    }
    case ATOM_POW: {
        /* Le potenze di e^i: si scrive solo (-1)^M, togliendo il pi greco
         * dall'esponente. */
        if (a->base == BASE_EI) {
            if (a->pi != PI_INTEGER || !one) { unwritable = 1; return; }
            proof_add("\\left(-1\\right)^{");
            for (int i = 0, written = 0; i < a->exponent.count; i++) {
                const Factor *f = &a->exponent.factor[i];
                if (atoms[f->atom].kind == ATOM_VAR && atoms[f->atom].id == VAR_PI) continue;
                if (written++) proof_add("\\,");
                put_atom(f->atom, f->exp);
            }
            proof_add("}");
            return;
        }

        /* La base: un numero o una lettera da soli, altrimenti tra parentesi;
         * sotto radice le parentesi non servono. */
        int root = a->exponent.count == 0 && exp.num == 1 && exp.den == 2;
        const Poly *poly = a->base == BASE_POLY ? &base_polys[a->id] : NULL;
        int whole = poly && poly->count == 1 && poly->term[0].mono.count == 0 && poly->term[0].coef.im.num == 0 &&
                    poly->term[0].coef.re.den == 1 && poly->term[0].coef.re.num > 0;
        int simple = a->base == BASE_PRIME || (a->base == BASE_ATOM && atoms[a->id].kind == ATOM_VAR) || whole;
        proof_add(root ? "\\sqrt{" : simple ? "" : "\\left(");
        if (a->base == BASE_PRIME) proof_add("%lld", a->id);
        else if (a->base == BASE_ATOM) put_atom((int)a->id, frac_int(1));
        else put_terms(base_polys[a->id]);
        proof_add(root ? "}" : simple ? "" : "\\right)");
        if (root || (a->exponent.count == 0 && one)) return;

        /* L'esponente: exp per il monomio dell'atomo. */
        proof_add("^{");
        if (a->exponent.count == 0) {
            put_frac(exp);
        } else {
            if (exp.num == -1 && exp.den == 1) proof_add("-");
            else if (!one) { put_frac(exp); proof_add("\\,"); }
            put_mono(&a->exponent);
        }
        proof_add("}");
        return;
    }
    case ATOM_LN:
        /* Anche l'argomento numerico va chiuso: in un monomio \ln 3\,e^x
         * si rileggerebbe come ln(3 e^x), non ln(3) per e^x. Le parentesi
         * esterne, quando exp non e 1, separano invece (ln 3)^exp da
         * ln(3^exp). Nessuno dei due confini puo essere lasciato implicito. */
        proof_add(one ? "\\ln " : "\\left(\\ln ");
        if (a->base == BASE_PRIME) {
            proof_add("\\left(%lld\\right)", a->id);
        } else {
            proof_add("\\left|");
            if (a->base == BASE_ATOM) put_atom((int)a->id, frac_int(1)); else put_terms(base_polys[a->id]);
            proof_add("\\right|");
        }
        if (!one) proof_add("\\right)");
        break;
    case ATOM_ATAN:
        proof_add("\\arctan\\left(");
        put_rat(atan_args[a->id]);
        proof_add("\\right)");
        break;
    }
    if (!one) { proof_add("^{"); put_frac(exp); proof_add("}"); }
}

/* Diverso da zero mentre le potenze con esponente k/2 vanno scritte come
 * potenze intere di una radice quadrata, \sqrt{u}^{k}, invece che u^{k/2}. Le
 * due scritture valgono lo stesso numero, perché u, base di una radice, non
 * è negativo. Serve al capitolo 25: la tabella dei segni (18p) legge le
 * radici quadrate ma non gli esponenti frazionari. */
static int surd_powers;

/* Scrive il monomio m: i suoi fattori, separati da uno spazio sottile. */
static void put_mono(const Mono *m) {
    for (int i = 0; i < m->count; i++) {
        const Atom *a = &atoms[m->factor[i].atom];
        Frac e = m->factor[i].exp;
        if (i) proof_add("\\,");

        /* Le potenze di e^i non sono radici di numeri reali: restano a
         * put_atom(), che le dichiara non scrivibili. */
        if (!surd_powers || e.den != 2 || (a->kind == ATOM_POW && a->base == BASE_EI)) {
            put_atom(m->factor[i].atom, e);
            continue;
        }

        /* Di una base presa come lettera put_atom() sa già scrivere la
         * radice; degli altri atomi la si scrive qui. */
        if (a->kind == ATOM_POW && a->exponent.count == 0) {
            put_atom(m->factor[i].atom, (Frac){1, 2});
        } else {
            proof_add("\\sqrt{");
            put_atom(m->factor[i].atom, frac_int(1));
            proof_add("}");
        }
        if (e.num != 1) proof_add("^{%lld}", e.num);
    }
}

/* Scrive il polinomio negli atomi p, un termine dopo l'altro: segno, valore
 * assoluto del coefficiente (taciuto se è 1 davanti a degli atomi), atomi. */
static void put_terms(Poly p) {
    if (p.count == 0) { proof_add("0"); return; }
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        if (t->coef.im.num != 0) { unwritable = 1; return; }
        Frac size = t->coef.re;
        int negative = size.num < 0, bare = t->mono.count == 0, unit;
        if (negative) size = frac_neg(size);
        unit = size.num == 1 && size.den == 1;
        proof_add("%s", i ? (negative ? " - " : " + ") : (negative ? "-" : ""));
        if (!unit || bare) put_frac(size);
        if (bare) continue;

        /* Tra il coefficiente e una potenza di un numero ci vuole il punto:
         * 2 e 3^n accostati si leggerebbero 23^n. */
        const Factor *first = &t->mono.factor[0];
        const Atom *a = &atoms[first->atom];
        int root = a->exponent.count == 0 && first->exp.num == 1 && first->exp.den == 2;
        int digit = a->kind == ATOM_POW && a->base == BASE_PRIME && !root;
        if (!unit) proof_add(digit ? " \\cdot " : "\\,");
        put_mono(&t->mono);
    }
}

/* Scrive la frazione di polinomi r; solo il numeratore se il denominatore è
 * 1. Come per put_bigop(), la sostituzione in corso non riguarda gli atomi. */
static void put_rat(Rat r) {
    const Node *kept = shown_value;
    shown_value = NULL;
    if (poly_is_one(r.den)) {
        put_terms(r.num);
    } else {
        proof_add("\\frac{");
        put_terms(r.num);
        proof_add("}{");
        put_terms(r.den);
        proof_add("}");
    }
    shown_value = kept;
}

/* Un pezzo del testo della dimostrazione in corso: i caratteri [from, to) di
 * proof_text. È una formula appena scritta, che si vuole poter rileggere. */
typedef struct {
    size_t from, to;
} Span;

/* Toglie dal testo della dimostrazione ciò che segue i primi length
 * caratteri. */
static void proof_cut(size_t length) {
    proof_length = length;
    proof_text[length] = 0;
}

/* Scrive il membro `side` dell'enunciato con la variabile di induzione
 * sostituita da value (NULL: così com'è) e ritorna il pezzo scritto. */
static Span put_side(const Node *side, const Node *value) {
    Span span = {proof_length, 0};
    shown_name = induction_var;
    shown_value = value;
    put_node(side, 0);
    shown_value = NULL;
    span.to = proof_length;
    return span;
}

/* Scrive prefix e poi il valore r, e ritorna 1 con il pezzo del valore in
 * *span. Se r non si può scrivere, perché troppo lungo, o non reale, o
 * perché un conto è fallito, non scrive nulla e ritorna 0. */
static int put_value(const char *prefix, Rat r, Span *span) {
    size_t start = proof_length;
    if (failure || r.num.count + r.den.count > 14) return 0;
    proof_add("%s", prefix);
    span->from = proof_length;
    unwritable = 0;
    put_rat(r);
    span->to = proof_length;
    if (!unwritable) return 1;
    proof_cut(start);
    return 0;
}

/* 13g. IL CONTROLLO DELLE FORMULE SCRITTE
 *
 * Ritorna 1 se l'uguaglianza tra le due formule scritte nei pezzi a e b della
 * dimostrazione è confermata per un'altra strada: le due formule vengono
 * rilette dal testo con il parser degli enunciati, come se le avesse scritte
 * l'utente, e l'uguaglianza passa per la verifica numerica 13e a partire da
 * n = base.
 *
 * Chi scrive la formula e chi la controlla non hanno nulla in comune: la
 * scrittura parte dagli alberi e dai polinomi negli atomi, il controllo dai
 * caratteri del testo e dai numeri. Un errore nel modo di scrivere (una
 * parentesi mancante, una sostituzione fatta male, un segno) cambia il valore
 * di ciò che si rilegge, e qui si vede. */
static int reread_equal(Span a, Span b, long long base) {
    char text[MAX_FORMULA];
    Statement statement;
    size_t kept = arena_used;
    int length = snprintf(text, sizeof text, "%.*s = %.*s", (int)(a.to - a.from), proof_text + a.from,
                          (int)(b.to - b.from), proof_text + b.from);
    int holds = length > 0 && (size_t)length < sizeof text && parse_statement(text, &statement) && !failure &&
                verify_instances(&statement, base, 0) == NULL;
    arena_used = kept;
    failure = NULL;
    return holds;
}

/* Ritorna 1 se i due pezzi del testo contengono gli stessi caratteri. */
static int span_same(Span a, Span b) {
    return a.to - a.from == b.to - b.from && memcmp(proof_text + a.from, proof_text + b.from, a.to - a.from) == 0;
}

/* Ritorna il valore del membro `side` dell'enunciato con la variabile di
 * induzione legata a n. */
static Rat side_value(const Node *side, Rat n) {
    env_count = 0;
    library_depth = 0;
    env_push(induction_var, n);
    Rat value = eval(side);
    env_count = 0;
    return value;
}

/* Scrive, un \item per ciascuno, i termini che ogni somma o prodotto
 * dell'enunciato guadagna passando da n a n + 1: gli indici da
 * dilation * n + offset + 1 a dilation * (n + 1) + offset. Ogni uguaglianza
 * scritta viene riletta (13g) a partire da n = base: ritorna 1 se reggono
 * tutte. */
static int put_new_terms(long long base) {
    int sound = 1;
    for (int x = 0; x < atom_count; x++) {
        const Atom *a = &atoms[x];
        if (a->kind != ATOM_BIGOP) continue;
        Span longer = {proof_length + strlen("\\item $"), 0}, split;
        proof_add("\\item $");
        put_bigop(x, a->dilation);
        longer.to = proof_length;
        proof_add(" = ");
        split.from = proof_length;

        /* Un \prod prende come corpo tutti i fattori che lo seguono
         * (capitolo 9): senza parentesi inghiottirebbe quelli nuovi. */
        int wrap = a->node->op && bigop_library(x) < 0;
        if (wrap) proof_add("\\left(");
        put_bigop(x, 0);
        if (wrap) proof_add("\\right)");
        for (long long j = 1; j <= a->dilation; j++) {
            proof_add(a->node->op ? " \\cdot " : " + ");
            shown_name = a->node->name;
            shown_value = node_affine(a->dilation, induction_var, a->offset + j);
            put_node(a->node->c, a->node->op ? 4 : 2);
            shown_value = NULL;
        }
        split.to = proof_length;
        proof_add("$.\n");
        sound &= reread_equal(longer, split, base);
    }
    return sound;
}

/* Scrive la dimostrazione per induzione dell'enunciato, già verificata: caso
 * base `base`, d = D(n), e `used` l'atomo ricavato dall'ipotesi nel passo
 * (-1 se non è servita), come li ha lasciati step_holds().
 *
 * Ogni formula scritta viene riletta e ricontrollata con reread_equal(). Se
 * anche una sola non regge, tutto il testo è sostituito da uno schema senza
 * formule e unjustified_steps sale: il verdetto resta, perché non dipende dal
 * testo, ma un passaggio non confermato non va stampato.
 *
 * I conti rifatti qui servono solo a mostrare le espressioni: un loro errore,
 * come un'espressione fuori dai limiti, toglie una frase dal testo ma non
 * tocca il verdetto, quindi `failure` torna com'era.
 *
 * Il testo si aggiunge a quello già scritto. Con nested diverso da zero è un
 * passo di una dimostrazione più grande (regola 18n): un \item con i suoi
 * sotto-passi, senza l'intestazione e senza il quadratino finale. */
static void put_induction_proof(const Statement *statement, long long base, Rat d, int used, int nested) {
    int variable = induction_var, sound = 1, valued = 1;
    const char *saved = failure;
    size_t opening = proof_length;
    const Node *side[2] = {statement->lhs, statement->rhs}, *successor = node_affine(1, variable, 1);
    Rat next = rat_add(rat_atom(atom_var(variable)), rat_int(1), 0);
    Span text[2], value[2];

    /* Caso base: i due membri con il numero al posto di n, e il loro valore.
     * Un membro che è già un numero non ha bisogno di "= valore". */
    proof_add(nested ? "\\item By induction on $%c$.\n" : "\\textbf{Proof.} By induction on $%c$.\n", variable);
    proof_add("\\begin{itemize}\n\\item \\emph{Base case}, $%c = %lld$. ", variable, base);
    for (int s = 0; s < 2; s++) {
        Rat low = side_value(side[s], rat_int(base));
        proof_add(s ? " and the right-hand side is $" : "The left-hand side is $");
        text[s] = put_side(side[s], node_num(base));
        if (side[s]->kind == N_NUM || (side[s]->kind == N_VAR && side[s]->name == variable)) value[s] = text[s];
        else if (put_value(" = ", low, &value[s])) sound &= reread_equal(text[s], value[s], base);
        else valued = 0;
        proof_add("$");
    }
    sound &= reread_equal(text[0], text[1], base);
    proof_add(valued && span_same(value[0], value[1]) ? ": the two values are equal.\n"
                  : ": the two sides are equal, because their difference reduces to $0$ by exact algebra.\n");

    /* 11n. La regola con cui sono state calcolate le somme che hanno n nel
     * coefficiente binomiale: va detta, perché da lì in poi quelle somme
     * compaiono solo con la loro forma chiusa. */
    if (binomial_used)
        proof_add("\\item \\emph{Binomial theorem}. For a general $%c$ a sum whose term is $\\binom{N}{k}$ times powers with $k$ in the exponent "
                  "is computed in closed form: its term is written as a sum of terms $c\\,y^{k}$, with $c$ and $y$ free of $k$, and "
                  "$\\sum_{k=0}^{N}\\binom{N}{k}y^{k} = (1 + y)^{N}$; when only the even or the odd $k$ appear, "
                  "$\\sum_{k}\\binom{N}{2k}y^{2k} = \\frac{(1 + y)^{N} + (1 - y)^{N}}{2}$ and "
                  "$\\sum_{k}\\binom{N}{2k+1}y^{2k+1} = \\frac{(1 + y)^{N} - (1 - y)^{N}}{2}$. "
                  "In the base case the sum is written out term by term instead.\n", variable);

    /* I due membri per n + 1, come li ha calcolati il passo induttivo. */
    Rat up[2] = {side_value(side[0], next), side_value(side[1], next)};

    if (used < 0) {
        /* Nessuna somma da ricavare: i due membri coincidono per ogni n. */
        proof_add("\\item \\emph{Inductive step}. Here the inductive hypothesis is not needed. For $%c + 1$ the statement is $", variable);
        text[0] = put_side(side[0], successor);
        proof_add(" = ");
        text[1] = put_side(side[1], successor);
        proof_add("$");
        sound &= reread_equal(text[0], text[1], base);
        if (!failure && rat_add(up[0], up[1], 1).num.count == 0 && put_value(", and written out both sides are $", up[0], &value[0])) {
            proof_add("$.\n");
            sound &= reread_equal(text[0], value[0], base) & reread_equal(text[1], value[0], base);
        } else {
            proof_add(", and the difference of the two sides reduces to $0$ by exact algebra.\n");
        }
    } else {
        /* L'ipotesi, e ciò che va dimostrato. */
        proof_add("\\item \\emph{Inductive hypothesis}. Assume the statement for some $%c \\ge %lld$: $", variable, base);
        put_side(side[0], NULL);
        proof_add(" = ");
        put_side(side[1], NULL);
        proof_add("$.\n\\item \\emph{Inductive step}. We prove the statement for $%c + 1$: $", variable);
        text[0] = put_side(side[0], successor);
        proof_add(" = ");
        text[1] = put_side(side[1], successor);
        proof_add("$.\n\\begin{itemize}\n");
        sound &= reread_equal(text[0], text[1], base);

        /* Seni e coseni sono calcolati come esponenziali complessi (capitolo
         * 11): il testo lo dice, perché in quella forma i risultati dei conti
         * non vengono scritti. */
        for (int x = 0, told = 0; x < atom_count && !told; x++)
            if (atoms[x].kind == ATOM_POW && atoms[x].base == BASE_EI && atoms[x].pi == PI_NONE) {
                proof_add("\\item Sines and cosines are computed as complex exponentials, $\\cos\\theta = \\frac{e^{i\\theta} + "
                          "e^{-i\\theta}}{2}$ and $\\sin\\theta = \\frac{e^{i\\theta} - e^{-i\\theta}}{2i}$; expressions in "
                          "that form are not written out below.\n");
                told = 1;
            }

        /* I termini che ogni somma o prodotto guadagna passando a n + 1. */
        sound &= put_new_terms(base);

        /* Il valore che l'ipotesi dà all'atomo ricavato: da A x + B = 0. */
        Poly hypothesis[2];
        Rat solved = rat_int(0);
        int split = poly_split(d.num, used, hypothesis, 1) == 1;
        if (split) solved = rat_make(poly_add(poly_const(num_int(0)), hypothesis[0], 1), hypothesis[1]);
        Span atom = {proof_length + strlen("\\item By the inductive hypothesis, $"), 0};
        size_t start = proof_length;
        proof_add("\\item By the inductive hypothesis, $");
        put_bigop(used, 0);
        atom.to = proof_length;
        if (split && put_value(" = ", solved, &value[0])) {
            proof_add("$.\n");
            sound &= reread_equal(atom, value[0], base);
        } else {
            proof_cut(start);
            proof_add("\\item The inductive hypothesis gives the value of $");
            put_bigop(used, 0);
            proof_add("$.\n");
        }

        /* Ciò che i due membri diventano con quel valore al posto dell'atomo. */
        for (int s = 0; s < 2 && split && !failure; s++)
            up[s] = rat_div(poly_substitute(up[s].num, used, solved), poly_substitute(up[s].den, used, solved));
        char opening[112];
        snprintf(opening, sizeof opening, "\\item With these replacements, the left-hand side for $%c + 1$ becomes $", variable);
        start = proof_length;
        int shown = split && put_value(opening, up[0], &value[0]) && put_value("$ and the right-hand side becomes $", up[1], &value[1]);
        if (shown && span_same(value[0], value[1])) {
            /* Lo stesso testo due volte: lo si dice una volta sola. */
            proof_cut(start);
            snprintf(opening, sizeof opening, "\\item With these replacements, both sides of the statement for $%c + 1$ become $", variable);
            put_value(opening, up[0], &value[0]);
            proof_add("$.\n");
            sound &= reread_equal(text[0], value[0], base) & reread_equal(text[1], value[0], base);
        } else if (shown) {
            proof_add("$. They are equal: their difference, written as one fraction, has numerator $0$.\n");
            sound &= reread_equal(text[0], value[0], base) & reread_equal(text[1], value[1], base);
        } else {
            proof_cut(start);
            proof_add("\\item With these replacements, the difference of the two sides for $%c + 1$ reduces to $0$ by exact algebra.\n", variable);
        }
        proof_add("\\end{itemize}\n");
    }
    proof_add(nested ? "\\end{itemize}\n" : "\\end{itemize}\n$\\Box$");

    /* Un passaggio non confermato: resta solo lo schema, senza formule. */
    if (!sound || proof_length >= PROOF_BYTES - 1) {
        if (!sound) unjustified_steps++;
        proof_cut(opening);
        proof_add(nested ? "\\item " : "\\textbf{Proof.} ");
        proof_add("By induction on $%c$: the base case $%c = %lld$ and the inductive step were both "
                  "checked by exact algebra on the difference of the two sides.%s", variable, variable, base, nested ? "\n" : " $\\Box$");
    }
    failure = saved;
}

/* 13h. IL CERTIFICATO
 *
 * I controlli fatti fin qui sono tutti del motore: stessa aritmetica, stesso
 * modo di leggere le formule. L'ultimo è di un altro programma. Il motore
 * scrive un certificato, cioè l'enunciato, il caso base e un "fattore" W per
 * cui D(n+1) = W D(n), e checker.c lo ricontrolla con i suoi polinomi. Che
 * cosa dimostra un certificato accettato è scritto in testa a checker.c:
 * che i due membri sono uguali dove sono definiti e, se il verificatore sa
 * ricontrollarlo, che lo sono per ogni n (vedi "La definizione", più sotto).
 *
 * Il fattore. L'ipotesi induttiva è A X + B = 0, e il numeratore di D(n+1) è
 * un polinomio in X, P(X) = C0 + C1 X + ... + Cd X^d. Il passo induttivo
 * (13b) ha controllato che A^d P(-B/A) = 0. Per il teorema del resto vuol
 * dire che A X + B divide A^d P(X):
 *
 *     A^d P(X) = Q(X) (A X + B).
 *
 * Q si trova con la regola di Ruffini. Con Y = A X, A^d P(X) è il polinomio
 * in Y di coefficienti c_j = C_j A^{d-j}, da dividere per Y + B:
 *
 *     s_{d-1} = c_d,    s_{j-1} = c_j - B s_j,    Q = s_0 + s_1 Y + ... + s_{d-1} Y^{d-1},
 *
 * e ciò che avanza, c_0 - B s_0, è proprio la quantità che 13b ha trovato
 * nulla. Con D(n) = (A X + B)/D0 e D(n+1) = P(X)/D1 si ottiene
 *
 *     D(n+1) = W D(n),    W = Q D0 / (A^d D1).
 *
 * Se D(n+1) è zero senza bisogno dell'ipotesi, W = 0.
 *
 * Un divisore di W che non è un divisore dell'enunciato. Quando A dipende
 * solo dai parametri (il secondo caso di 13b) può restare a denominatore di
 * W. Il verificatore allora respinge, a meno che il certificato dichiari A
 * tra le espressioni "generic": il teorema certificato vale dove A non è
 * zero, e l'estensione agli altri valori dei parametri resta l'argomento di
 * 13b, che il certificato non copre. Si prova prima senza.
 *
 * La definizione. 13c ha stabilito che in un certo punto dei parametri
 * l'enunciato è definito per ogni n; verify_instances() lascia quel punto in
 * fixed_name[] e fixed_value[]. Il certificato lo porta al verificatore con
 * la voce "defined", e il verificatore ricontrolla con le sue regole che
 * nessun divisore si annulli (capitolo 9 di checker.c). Le risposte sono tre
 * e contano tutte: accettato, e allora il certificato dice anche questo;
 * respinto, cioè c'è un n in cui l'enunciato non è definito e 13c ha
 * sbagliato; non controllabile, e allora si torna al certificato della sola
 * uguaglianza.
 *
 * I logaritmi. Il motore li calcola scomponendo l'argomento in fattori
 * (capitolo 11), e ogni fattore è la base di un atomo LN. Il verificatore fa
 * lo stesso conto per conto suo, ma non cerca i fattori: glieli suggerisce
 * il certificato, con una voce "brick" per ogni base, e lui li prova con una
 * divisione. Un suggerimento sbagliato non divide nulla, quindi non può far
 * accettare il falso.
 *
 * La notazione dei certificati ha meno parole di quella degli enunciati:
 * niente radici, seni, arcotangenti. Quando l'enunciato o il fattore
 * contengono qualcosa che non sa dire, il certificato non c'è, e il verdetto
 * lo dichiara.
 */

/* Il certificato dell'enunciato in corso, nella notazione di checker.c. */
static char certificate_initial[CERTIFICATE_BYTES];
static char *certificate_text = certificate_initial;
static size_t certificate_length, certificate_capacity = CERTIFICATE_BYTES;

/* Diventa 1 quando il certificato in corso non si può scrivere: una quantità
 * che la notazione non ha, o memoria insufficiente per il testo dinamico. */
static int certificate_broken;

/* Le successioni del vocabolario nominate nel certificato in corso: il bit i
 * è la riga i di library[]. Vanno definite nel certificato stesso. */
static unsigned certificate_sequences;
_Static_assert(LIBRARY_COUNT <= 32, "certificate_sequences ha un bit per ogni riga del vocabolario");

/* Perché l'ultimo certificato chiesto a certify() non c'è o non vale, in
 * italiano. Resta valido fino alla chiamata successiva. */
static char certificate_problem[256];

/* 1 mentre si scrive il certificato di una tabella dei segni (18p-15): solo
 * allora il valore assoluto e la radice quadrata hanno una parola, (abs a) e
 * (sqrt a), che il verificatore conosce nel suo capitolo 12. In un
 * certificato di induzione resterebbero parole sconosciute: lì il
 * certificato manca, e il verdetto dice perché. */
static int cert_signs;

/* Diverso da zero mentre si scrive il certificato di una derivata, di una
 * primitiva o di un integrale (27m, 30cert): è il nome della variabile reale, e
 * allora hanno una parola le funzioni che il verificatore conosce nel suo
 * capitolo 13: (exp a) per e^a, (sin a), (cos a), (atan a), (root m a),
 * (pi). La lettera e, se non è la variabile, è il numero di Nepero, (exp 1),
 * come nel capitolo 27. */
static int cert_real;

/* Aggiunge un pezzo al certificato, con la sintassi di printf. */
static void cert_add(const char *format, ...) {
    if (certificate_broken) return;
    va_list arguments;
    va_start(arguments, format);
    va_list retry; va_copy(retry, arguments);
    int written = vsnprintf(certificate_text + certificate_length, certificate_capacity - certificate_length, format, arguments);
    if (written < 0 || (size_t)written > (size_t)-1 - certificate_length - 1) certificate_broken = 1;
    else {
        size_t need = certificate_length + (size_t)written + 1;
        if (need > certificate_capacity) {
            if (!text_reserve(&certificate_text, &certificate_capacity, certificate_initial, need)) certificate_broken = 1;
            else vsnprintf(certificate_text + certificate_length, certificate_capacity - certificate_length, format, retry);
        }
        if (!certificate_broken) certificate_length += (size_t)written;
    }
    va_end(retry);
    va_end(arguments);
}

/* Scrive una lettera dell'enunciato. \pi e la lettera ausiliaria di
 * body_is_positive() non sono parametri: la notazione non li ha. */
static void cert_letter(long long name) {
    if (name < 128 && isalpha((int)name)) cert_add("%c", (int)name);
    else certificate_broken = 1;
}

static void cert_node(const Node *n);

/* Scrive "(word a)" oppure, se b non è NULL, "(word a b)". */
static void cert_call(const char *word, const Node *a, const Node *b) {
    cert_add("(%s ", word);
    cert_node(a);
    if (b) {
        cert_add(" ");
        cert_node(b);
    }
    cert_add(")");
}

/* Scrive il termine di indice index della riga `entry` del vocabolario. Il
 * fattoriale è una parola della notazione; le altre successioni si nominano,
 * e certify() ne aggiunge la definizione.
 *
 * Warning: "(fact a)" è per il verificatore il prodotto degli interi da 1 ad
 * a. Se cambi la riga '!' del vocabolario, il certificato non dice più ciò
 * che il motore ha dimostrato: va cambiato anche qui. */
static void cert_term(int entry, const Node *index) {
    if (library[entry].name == '!') {
        cert_call("fact", index, NULL);
        return;
    }
    certificate_sequences |= 1u << entry;
    cert_add("(seq %c ", library[entry].name);
    cert_node(index);
    cert_add(")");
}

/* Scrive la somma o il prodotto del nodo node, con upper al posto del suo
 * estremo superiore. */
static void cert_bigop(const Node *node, const Node *upper) {
    cert_add("(%s ", node->op ? "prod" : "sum");
    cert_letter(node->name);
    cert_add(" ");
    cert_node(node->a);
    cert_add(" ");
    cert_node(upper);
    cert_add(" ");
    cert_node(node->c);
    cert_add(")");
}

/* Scrive l'albero n nella notazione dei certificati: l'operatore davanti, e
 * tutte le parentesi.
 *
 * Warning: se aggiungi un tipo di nodo o una funzione, decidi qui se la
 * notazione dei certificati lo sa dire; altrimenti resta senza certificato. */
static void cert_node(const Node *n) {
    static const char *const binary[] = {[N_ADD] = "+", [N_SUB] = "-", [N_MUL] = "*", [N_DIV] = "/", [N_POW] = "^"};
    switch (n->kind) {
    case N_NUM:
        cert_add("%lld", n->value);
        return;
    case N_VAR:
        if (cert_real && n->name == VAR_PI) cert_add("(pi)");
        else if (cert_real && n->name == 'e' && cert_real != 'e') cert_add("(exp 1)");
        else cert_letter(n->name);
        return;
    case N_SEQ:
        for (int i = 0; i < LIBRARY_COUNT; i++)
            if (library[i].name == n->name) { cert_term(i, n->a); return; }
        certificate_broken = 1;
        return;
    case N_NEG:
        cert_call("neg", n->a, NULL);
        return;
    case N_BIGOP:
        cert_bigop(n, n->b);
        return;
    case N_CALL:
        if (n->op == FN_FACT) {
            cert_call("fact", n->a, NULL);
        } else if (n->op == FN_BINOM) {
            cert_call("binom", n->a, n->b);
        } else if ((cert_signs || cert_real) && n->op == FN_ABS) {
            /* Nel capitolo 13 di checker.c il valore assoluto si calcola solo
             * dentro l'argomento di un logaritmo. */
            cert_call("abs", n->a, NULL);
        } else if (cert_signs && n->op == FN_ROOT && n->b->kind == N_NUM && n->b->value == 2) {
            cert_call("sqrt", n->a, NULL);
        } else if (cert_real && n->op == FN_ROOT && n->b->kind == N_NUM && n->b->value >= 2) {
            cert_add("(root %lld ", n->b->value);
            cert_node(n->a);
            cert_add(")");
        } else if (cert_real && (n->op == FN_SIN || n->op == FN_COS || n->op == FN_ARCTAN)) {
            cert_call(n->op == FN_SIN ? "sin" : n->op == FN_COS ? "cos" : "atan", n->a, NULL);
        } else if (cert_real && (n->op == FN_TAN || n->op == FN_COT)) {
            /* tan u = sin u / cos u, cot u = cos u / sin u: definite dove lo
             * sono loro, dove il denominatore non è zero. */
            cert_add("(/ ");
            cert_call(n->op == FN_TAN ? "sin" : "cos", n->a, NULL);
            cert_add(" ");
            cert_call(n->op == FN_TAN ? "cos" : "sin", n->a, NULL);
            cert_add(")");
        } else if (cert_real && n->op == FN_ARCCOT) {
            /* L'arcocotangente a valori in (0, pi) è pi/2 - arctan u. */
            cert_add("(- (/ (pi) 2) ");
            cert_call("atan", n->a, NULL);
            cert_add(")");
        } else if (n->op == FN_LN || (n->op == FN_LOG && n->b)) {
            /* Il logaritmo di un valore assoluto ha una parola sua, perché
             * è definito anche dove l'argomento è negativo (vedi
             * eval_call()). Il logaritmo in base b è ln a / ln b. */
            int absolute = n->a->kind == N_CALL && n->a->op == FN_ABS;
            if (n->op == FN_LOG) cert_add("(/ ");
            cert_call(absolute ? "lnabs" : "ln", absolute ? n->a->a : n->a, NULL);
            if (n->op == FN_LOG) {
                cert_add(" ");
                cert_call("ln", n->b, NULL);
                cert_add(")");
            }
        } else {
            certificate_broken = 1;
        }
        return;
    case N_APPLY: case N_DERIV:
        certificate_broken = 1;
        return;
    default:
        if (cert_real && n->kind == N_POW && n->a->kind == N_VAR && n->a->name == 'e' && cert_real != 'e') cert_call("exp", n->b, NULL);
        else cert_call(binary[n->kind], n->a, n->b);
    }
}

static void cert_poly(Poly p);

static void cert_atom(int atom);

/* Scrive la base di un atomo POW o LN che non sia e^i: un numero primo, un
 * altro atomo, o un polinomio. */
static void cert_base(const Atom *a) {
    if (a->base == BASE_PRIME) cert_add("%lld", a->id);
    else if (a->base == BASE_ATOM) cert_atom((int)a->id);
    else cert_poly(base_polys[a->id]);
}

/* Scrive l'atomo `atom` come la quantità che rappresenta (capitolo 4).
 *
 *   VAR    la lettera;
 *   BIGOP  la somma o il prodotto fino al suo estremo, o il termine della
 *          successione del vocabolario di cui è la definizione;
 *   REC    il termine della successione;
 *   POW    base^M; e^{i pi M} con M intero è (-1)^M (vedi 4g);
 *   LN     il logaritmo del valore assoluto della base.
 *
 * Arcotangenti e le altre potenze di e^i (seni e coseni) non hanno una
 * scrittura.
 *
 * Warning: se aggiungi un tipo di atomo, aggiungine il caso qui. */
static void cert_atom(int atom) {
    const Atom *a = &atoms[atom];
    switch (a->kind) {
    case ATOM_VAR:
        cert_letter(a->id);
        return;
    case ATOM_REC:
        cert_term((int)a->id, node_affine(a->dilation, induction_var, a->offset));
        return;
    case ATOM_BIGOP: {
        const Node *upper = node_affine(a->dilation, induction_var, a->offset);
        int named = bigop_library(atom);
        if (named >= 0) cert_term(named, upper); else cert_bigop(a->node, upper);
        return;
    }
    case ATOM_POW: {
        /* L'esponente; per (-1)^M è quello dell'atomo senza il pi greco. */
        Mono exponent = a->exponent;
        if (a->base == BASE_EI) {
            if (a->pi != PI_INTEGER) { certificate_broken = 1; return; }
            exponent = mono_with_exponent(&exponent, atom_var(VAR_PI), frac_int(0));
        }

        /* La base, da sola se l'atomo è la base presa come lettera. */
        if (exponent.count) cert_add("(^ ");
        if (a->base == BASE_EI) cert_add("-1"); else cert_base(a);
        if (!exponent.count) return;
        cert_add(" ");
        cert_poly(poly_term((Term){num_int(1), exponent}));
        cert_add(")");
        return;
    }
    case ATOM_LN:
        cert_add("(lnabs ");
        cert_base(a);
        cert_add(")");
        return;
    default:
        certificate_broken = 1;
    }
}

/* Scrive il numero razionale c. */
static void cert_frac(Frac c) {
    if (c.den == 1) cert_add("%lld", c.num);
    else cert_add("(/ %lld %lld)", c.num, c.den);
}

/* Scrive il polinomio negli atomi p: la somma dei suoi termini, ciascuno il
 * coefficiente per i suoi atomi elevati ai loro esponenti. Un coefficiente
 * immaginario o un esponente non intero (una radice) non hanno scrittura. */
static void cert_poly(Poly p) {
    if (p.count == 0) cert_add("0");
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        Frac c = t->coef.re;
        if (t->coef.im.num != 0) certificate_broken = 1;

        /* Somme e prodotti hanno due operandi: "(+ primo (+ secondo ...))",
         * "(* (* primo secondo) terzo)". Il coefficiente 1 davanti a degli
         * atomi si tace; `shown` conta i fattori già scritti. */
        int shown = c.num != c.den || t->mono.count == 0;
        if (i + 1 < p.count) cert_add("(+ ");
        for (int j = 1; j < shown + t->mono.count; j++) cert_add("(* ");
        if (shown) cert_frac(c);
        for (int j = 0; j < t->mono.count; j++) {
            Frac e = t->mono.factor[j].exp;
            if (e.den != 1) certificate_broken = 1;
            if (shown) cert_add(" ");
            if (e.num != 1) cert_add("(^ ");
            cert_atom(t->mono.factor[j].atom);
            if (e.num != 1) cert_add(" %lld)", e.num);
            if (shown++) cert_add(")");
        }
        if (i + 1 < p.count) cert_add(" ");
    }
    for (int i = 1; i < p.count; i++) cert_add(")");
}

/* Scrive in certificate_text il certificato dell'enunciato statement con
 * caso base `base` e fattore top/bottom. Se generic non è NULL dichiara
 * quell'espressione dei parametri diversa da zero; se defined è diverso da
 * zero aggiunge la voce "defined" con il punto di 13c. Alla fine
 * certificate_broken dice se il testo è da buttare. */
static void write_certificate(const Statement *statement, long long base, Poly top, Poly bottom, const Poly *generic, int defined) {
    /* Le voci: variabile, caso base, enunciato, fattore. */
    certificate_length = 0;
    certificate_broken = 0;
    certificate_sequences = 0;
    cert_add("certificate induction\nvariable %c\nbase %lld\nstatement (= ", induction_var, base);
    cert_node(statement->lhs);
    cert_add(" ");
    cert_node(statement->rhs);
    cert_add(poly_is_one(bottom) ? ")\nfactor " : ")\nfactor (/ ");
    cert_poly(top);
    if (!poly_is_one(bottom)) {
        cert_add(" ");
        cert_poly(bottom);
        cert_add(")");
    }
    if (generic) {
        cert_add("\ngeneric ");
        cert_poly(*generic);
    }

    /* I fattori in cui il motore ha scomposto gli argomenti dei logaritmi:
     * le basi dei suoi atomi LN. Il verificatore li prova con una divisione
     * (vedi 8g in checker.c), quindi uno in più non fa danno. */
    for (int i = 0, written = 0; i < atom_count && written < MAX_BRICKS; i++) {
        if (atoms[i].kind != ATOM_LN || atoms[i].base == BASE_PRIME) continue;
        cert_add("\nbrick ");
        cert_base(&atoms[i]);
        written++;
    }
    if (defined) {
        cert_add("\ndefined");
        for (int i = 0; i < fixed_count; i++) {
            cert_add(" ");
            cert_letter(fixed_name[i]);
            cert_add(" ");
            cert_frac(fixed_value[i]);
        }
    }

    /* Le successioni nominate. Scrivere una definizione può nominarne
     * un'altra: si continua finché ne restano. */
    for (unsigned written = 0, pending; (pending = certificate_sequences & ~written) != 0;) {
        int i = 0;
        while (!(pending >> i & 1)) i++;
        written |= 1u << i;
        if (library[i].definition) {
            cert_add("\ndefine %c m ", library[i].name);
            cert_node(library[i].tree);
            continue;
        }
        cert_add("\nsequence %c %d", library[i].name, library[i].order);
        for (int j = 0; j < library[i].order; j++) cert_add(" %lld", library[i].coef[j]);
        for (int j = 0; j < library[i].order; j++) cert_add(" %lld", library[i].init[j]);
    }
    cert_add("\nend\n");
}

/* Scrive il certificato dell'induzione appena riuscita e lo fa controllare
 * dal verificatore indipendente. statement, base, d, d1 e used sono quelli
 * di induct(): l'enunciato, il caso base, D(n), D(n+1) e l'atomo ricavato
 * dall'ipotesi (o -1).
 *
 * Ritorna la risposta del verificatore, e allora il certificato è in
 * certificate_text; oppure CK_UNSUPPORTED se non si è potuto scrivere. Quando
 * la risposta non è CK_ACCEPTED il motivo è in certificate_problem. */
static CkAnswer certify(const Statement *statement, long long base, Rat d, Rat d1, int used) {
    const char *saved = failure, *why = "", *text;
    Poly a = poly_const(num_int(1)), top = poly_const(num_int(0)), bottom = a;
    CkAnswer answer = CK_UNSUPPORTED;
    int generic = 0;

    /* Il fattore W = top/bottom, con la regola di Ruffini. Le due
     * scomposizioni sono quelle già riuscite in step_holds(): qui possono
     * mancare solo se è finita la memoria. */
    Poly hypothesis[2], part[MAX_DEGREE + 1];
    int degree = used < 0 ? -1 : poly_split(d1.num, used, part, MAX_DEGREE);
    if (used >= 0 && (degree < 0 || poly_split(d.num, used, hypothesis, 1) != 1)) fail(OUT_OF_MEMORY);
    if (used >= 0 && !failure) {
        Poly a_power[MAX_DEGREE + 1], y_power[MAX_DEGREE + 1];
        a = hypothesis[1];

        /* Le potenze di A e di Y = A X. */
        a_power[0] = y_power[0] = poly_const(num_int(1));
        for (int j = 1; j <= degree; j++) {
            a_power[j] = poly_mul(a_power[j - 1], a);
            y_power[j] = poly_mul(y_power[j - 1], poly_mul(a, rat_atom(used).num));
        }

        /* s vale s_j quando entra in Q, poi diventa s_{j-1}. */
        Poly s = part[degree], q = top;
        for (int j = degree - 1; j >= 0; j--) {
            q = poly_add(q, poly_mul(s, y_power[j]), 0);
            s = poly_add(poly_mul(part[j], a_power[degree - j]), poly_mul(hypothesis[0], s), 1);
        }
        top = poly_mul(q, d.den);
        bottom = poly_mul(a_power[degree], d1.den);
    }

    /* Numeratore e denominatore proporzionali: W è un numero. Capita con
     * ogni enunciato "somma = formula", dove W = 1. */
    if (!failure && poly_proportional(top, bottom)) {
        top = poly_const(num_mul(top.term[0].coef, num_inv(bottom.term[0].coef)));
        bottom = poly_const(num_int(1));
    }

    /* L'uguaglianza. Prima senza "generic", poi dichiarando A: dopo un
     * rifiuto si riprova solo se A è un'espressione dei parametri che si può
     * dichiarare diversa da zero. */
    for (; generic < 2 && !failure; generic++) {
        /* 11n. Il verificatore non conosce il teorema del binomio, e una
         * somma con n nel termine non la sa nemmeno leggere come tale: non
         * gli si chiede nulla, e il verdetto dice perché. */
        if (binomial_used) {
            why = "il teorema del binomio non è nella notazione dei certificati";
            break;
        }
        write_certificate(statement, base, top, bottom, generic ? &a : NULL, 0);
        if (certificate_broken) {
            answer = CK_UNSUPPORTED;
            why = "l'enunciato o il passo induttivo usano qualcosa che la notazione dei certificati non ha";
            break;
        }
        text = certificate_text;
        answer = ck_check(&text, &why);
        if (answer != CK_REJECTED || used < 0 || poly_depends_on_n(a)) break;
    }

    /* La definizione. 13c ha stabilito che nel suo punto l'enunciato è
     * definito per ogni n: lo si fa ricontrollare. Se il verificatore non
     * sa decidere resta il certificato della sola uguaglianza; se trova un
     * n in cui l'enunciato non è definito, 13c ha sbagliato. */
    if (answer == CK_ACCEPTED && fixed_count >= 0) {
        const char *doubt = "";
        write_certificate(statement, base, top, bottom, generic ? &a : NULL, 1);
        text = certificate_text;
        CkAnswer full = certificate_broken ? CK_UNSUPPORTED : ck_check(&text, &doubt);
        if (full == CK_REJECTED) {
            answer = CK_REJECTED;
            why = doubt;
        } else if (full == CK_UNSUPPORTED) {
            write_certificate(statement, base, top, bottom, generic ? &a : NULL, 0);
        }
    }

    /* Un errore nei conti del fattore (numeri troppo grandi) non riguarda
     * l'enunciato: vuol dire solo che il certificato non c'è. */
    if (failure) {
        answer = CK_UNSUPPORTED;
        why = failure;
    }
    failure = saved;
    snprintf(certificate_problem, sizeof certificate_problem, "%s%s",
             answer == CK_REJECTED ? "il verificatore indipendente ha respinto il certificato: " : "", why);
    return answer;
}

/* Il motivo con cui induct() rifiuta un enunciato che non è un'uguaglianza.
 * Ha un nome perché prove() (capitolo 20) lo riconosce, e allora passa
 * l'enunciato all'induzione sulle disuguaglianze (capitolo 25). */
static const char *const NOT_AN_EQUALITY = "il passo induttivo del capitolo 13 tratta solo le uguaglianze";

/* Il metodo dell'induzione su un enunciato già analizzato: caso base, passo,
 * verifiche e dimostrazione scritta, come descritto in testa al capitolo.
 *
 * variable è la variabile di induzione; se has_base è diverso da zero il caso
 * base è base, altrimenti lo sceglie il programma: il più piccolo n, almeno 1,
 * per cui le somme e i prodotti dell'enunciato hanno almeno un termine.
 * nested dice come scrivere la dimostrazione (vedi put_induction_proof()).
 *
 * Usa la tabella degli atomi così com'è: chi chiama decide se svuotarla. */
static Verdict induct_equality(const Statement *input, int variable, int has_base, long long base, int nested) {
    Verdict verdict = {UNSUPPORTED, variable, base, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    Statement statement = *input;
    induction_var = variable;
    default_base = 1;
    domain_floor = has_base ? base : 1;
    if (statement.relation != REL_EQ) { verdict.reason = NOT_AN_EQUALITY; return verdict; }

    /* D(n). È la prima valutazione, quindi quella che fa nascere gli atomi con
     * gli estremi scritti nell'enunciato, e che calcola default_base. */
    Rat n = rat_atom(atom_var(variable));
    Rat d = difference(&statement, n);
    if (failure) { verdict.reason = failure; return verdict; }
    if (!has_base) base = default_base;
    verdict.base = base;

    /* 13a. Caso base. */
    Rat d0 = difference(&statement, rat_int(base));
    int base_holds = !failure && poly_vanishes(d0.num);
    if (failure) { verdict.reason = failure; return verdict; }
    if (!base_holds) {
        /* Un numero diverso da zero è una smentita certa. Un'espressione con
         * dei parametri potrebbe invece essere uno zero che l'algebra non sa
         * riconoscere: non si può concludere nulla. */
        Num value;
        if (rat_number(d0, &value)) { verdict.outcome = REFUTED; verdict.witness = base; }
        else { verdict.outcome = NOT_PROVED; verdict.reason = "il caso base non si riduce a zero"; }
        return verdict;
    }

    /* 13b. Passo induttivo. */
    Rat d1 = difference(&statement, rat_add(n, rat_int(1), 0));
    if (failure) { verdict.reason = failure; return verdict; }
    int used;
    int proved = step_holds(d, d1, &used);
    if (failure) { verdict.reason = failure; return verdict; }
    if (proved) {
        /* 13c, 13d, 13e. Verifica indipendente, con i numeri al posto delle lettere. */
        const char *problem = verify_instances(&statement, base, 1);
        if (problem) {
            verdict.outcome = NOT_PROVED;
            verdict.reason = problem;
            return verdict;
        }

        /* 13f, 13g. La dimostrazione scritta, con i suoi passaggi. */
        put_induction_proof(&statement, base, d, used, nested);

        /* 13h. Il certificato. Un rifiuto vuol dire che il motore e il
         * verificatore non sono d'accordo: nel dubbio non è dimostrato, e
         * l'enunciato va guardato come un errore del programma. */
        CkAnswer answer = certify(&statement, base, d, d1, used);
        if (answer == CK_REJECTED) {
            unjustified_steps++;
            verdict.outcome = NOT_PROVED;
            verdict.reason = certificate_problem;
            return verdict;
        }
        if (answer == CK_ACCEPTED) verdict.certificate = certificate_text;
        else verdict.reason = certificate_problem;
        verdict.outcome = PROVED;
        verdict.proof = proof_text;
        return verdict;
    }

    /* Ricerca di un controesempio nei valori successivi al caso base. Un
     * errore qui (per esempio numeri troppo grandi) interrompe solo la
     * ricerca. */
    for (long long c = base + 1; c <= base + SEARCH_SPAN; c++) {
        Num value;
        Rat dc = difference(&statement, rat_int(c));
        if (failure) break;
        if (rat_number(dc, &value) && !num_is_zero(value)) {
            verdict.outcome = REFUTED;
            verdict.witness = c;
            return verdict;
        }
    }
    failure = NULL;
    verdict.outcome = NOT_PROVED;
    verdict.reason = "il passo induttivo non si chiude";
    return verdict;
}

/* Dimostra per induzione l'enunciato input: è induct_equality(), con il
 * teorema del binomio (11n) tra le regole di calcolo. La regola è permessa
 * solo qui perché è qui che la dimostrazione scritta la dichiara
 * (put_induction_proof()) e che il certificato dice di non saperla
 * esprimere (certify()): altrove verrebbe usata in silenzio. */
static Verdict induct(const Statement *input, int variable, int has_base, long long base, int nested) {
    binomial_ok = 1;
    binomial_used = 0;
    Verdict verdict = induct_equality(input, variable, has_base, base, nested);
    binomial_ok = 0;
    return verdict;
}

/* Prova a dimostrare per induzione l'enunciato scritto in formula, con la
 * variabile di induzione e il caso base indicati (vedi induct()).
 *
 * Svuota l'arena e la tabella degli atomi: i risultati di chiamate precedenti
 * non sono più validi. */
static Verdict prove_by_induction(const char *formula, int variable, int has_base, long long base) {
    Verdict verdict = {UNSUPPORTED, variable, base, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    Statement statement;

    /* Ripartenza da zero per il nuovo enunciato, e parsing. */
    proof_reset();
    arena_used = arena_keep;
    atom_count = 0;
    base_poly_count = 0;
    atan_count = 0;
    failure = NULL;
    if (!parse_statement(formula, &statement)) { verdict.reason = syntax_error; return verdict; }

    /* 27j. I segni di derivata dentro le espressioni, prima di ogni conto. */
    derivative_signs = 0;
    statement.lhs = derivatives_expanded(statement.lhs);
    statement.rhs = derivatives_expanded(statement.rhs);
    if (failure) { verdict.reason = failure; return verdict; }
    return induct(&statement, variable, has_base, base, 0);
}

/* =============================================================================
 * 15. INSIEMI: DECISIONE PER REGIONI
 * ============================================================================
 *
 * Come si decide un enunciato che deve valere per ogni scelta degli insiemi.
 *
 * Regioni. Dati k insiemi, ogni elemento sta in esattamente una delle 2^k
 * regioni del diagramma di Venn: una regione è la scelta, per ciascun insieme,
 * tra "ci sta" e "non ci sta". Una regione è il numero i cui bit dicono a
 * quali insiemi appartiene: con S di indice 0 e T di indice 1, la regione 1 è
 * "in S e non in T".
 *
 * Il fatto su cui si regge tutto: se un oggetto appartiene o no a
 * un'espressione dipende solo dalle regioni che tocca.
 *
 *   15a. Un elemento x: da quale regione lo contiene. x sta in A unito B se
 *        sta in A o in B, e così via.
 *   15b. Un insieme X: da quali regioni incontra. X sta nell'insieme delle
 *        parti di A se X è contenuto in A, cioè se ogni regione che X incontra
 *        sta in A; sta in {vuoto} se non ne incontra nessuna.
 *   15c. Una coppia (x, y): dalle regioni di x e di y. Sta in A per B se x sta
 *        in A e y sta in B.
 *
 * Configurazioni. Per insiemi dati, alcune regioni contengono elementi e altre
 * sono vuote: questa è la "configurazione". Un'uguaglianza o un'inclusione tra
 * due espressioni fallisce quando esiste un oggetto che sta in una sola delle
 * due (per l'inclusione: nella prima e non nella seconda), e un tale oggetto
 * esiste quando le regioni che tocca sono tutte non vuote. Quindi ogni
 * relazione ha un elenco di "supporti", insiemi di regioni, e fallisce
 * esattamente nelle configurazioni che contengono per intero un supporto.
 *
 * Decisione. La verità di tutto l'enunciato dipende allora solo dalla
 * configurazione. Le configurazioni sono 2^(2^k), ognuna è realizzata da
 * qualche scelta degli insiemi (un elemento per ogni regione non vuota), e
 * ogni scelta degli insiemi ne realizza una. L'enunciato vale per ogni scelta
 * degli insiemi se e solo se vale in tutte le configurazioni: si provano
 * tutte. Con al più 4 insiemi sono al più 65536.
 *
 * Il metodo decide davvero, in entrambi i sensi: un enunciato che fallisce in
 * una configurazione è falso, e la configurazione dà un controesempio.
 *
 * Il quantificatore "esiste un insieme V". Non si può trattare V come gli
 * altri insiemi, perché V va scelto, non è arbitrario. Due casi:
 *
 *   15d. "Esiste V" è un'ipotesi (sta a sinistra di un'implicazione). Dire
 *        "se esiste V con una certa proprietà allora C" equivale a dire "per
 *        ogni V, se V ha la proprietà allora C": V diventa un insieme
 *        arbitrario come gli altri.
 *   15e. "Esiste V" è una tesi. Si cerca un V esplicito costruito dagli altri
 *        insiemi, cioè un'unione di loro regioni: si provano tutte. Trovarlo
 *        dimostra l'esistenza. Non trovarlo non prova nulla, perché V potrebbe
 *        dover dividere una regione: allora si passa a 15f.
 *   15f. Più quantificatori, o in un'altra posizione, o un V che 15e non
 *        trova. Non basta più sapere quali regioni sono vuote: si contano i
 *        loro elementi, fino a un numero che dipende da quanti quantificatori
 *        stanno uno dentro l'altro. È descritto più sotto, con il suo teorema.
 */

/* Ritorna 1 se l'oggetto descritto da u e v appartiene all'espressione n.
 * Il significato di u e v dipende dal tipo di n (vedi 15a, 15b, 15c):
 *
 *   insieme di elementi:    u è la regione dell'elemento;
 *   collezione di insiemi:  u ha un bit per ogni regione che l'insieme incontra;
 *   insieme di coppie:      u e v sono le regioni delle due componenti. */
static int member(const SetNode *n, unsigned u, unsigned v) {
    switch (n->kind) {
    case SET_VAR:        return (u >> n->var) & 1;
    case SET_ONLY_EMPTY: return u == 0;
    case SET_POWER:
        for (unsigned region = 0; u >> region; region++)
            if (((u >> region) & 1) && !member(n->a, region, 0)) return 0;
        return 1;
    case SET_PRODUCT:    return member(n->a, u, 0) && member(n->b, v, 0);
    case SET_UNION:      return member(n->a, u, v) || member(n->b, u, v);
    case SET_INTER:      return member(n->a, u, v) && member(n->b, u, v);
    case SET_DIFF:       return member(n->a, u, v) && !member(n->b, u, v);
    case SET_SYMDIFF:    return member(n->a, u, v) != member(n->b, u, v);
    default:             return 0;  /* SET_EMPTY */
    }
}

/* Confronto per qsort: prima le configurazioni con meno regioni. */
static int by_size(const void *a, const void *b) {
    return __builtin_popcount(*(const unsigned *)a) - __builtin_popcount(*(const unsigned *)b);
}

/* Riempie support e supports della relazione n con i supporti minimi: gli
 * insiemi di regioni, nessuno contenuto in un altro, tali che la relazione
 * fallisce esattamente quando le regioni di uno di essi sono tutte non vuote.
 *
 * Si esaminano tutti gli oggetti del tipo giusto: le regioni per gli elementi,
 * gli insiemi di regioni per gli insiemi, le coppie di regioni per le coppie.
 * Ogni oggetto che distingue i due membri dà un supporto: le regioni che
 * tocca. Bastano i minimi, perché una configurazione che ne contiene uno più
 * grande contiene anche il più piccolo. */
static void relation_supports(SetNode *n) {
    SetType type = set_join(n->a->type, n->b->type);
    unsigned regions = 1u << set_var_count;
    unsigned long long objects = type == TY_FAMILY ? 1ull << regions
                               : type == TY_PAIRS ? (unsigned long long)regions * regions : regions;
    unsigned *found = arena_alloc((size_t)objects * sizeof(unsigned));
    if (!found) return;

    /* Tutti gli oggetti che distinguono i due membri. */
    int count = 0;
    for (unsigned long long object = 0; object < objects; object++) {
        unsigned u = type == TY_PAIRS ? (unsigned)(object / regions) : (unsigned)object;
        unsigned v = type == TY_PAIRS ? (unsigned)(object % regions) : 0;
        int left = member(n->a, u, v), right = member(n->b, u, v);
        if (n->kind == SET_SUBSET ? !(left && !right) : left == right) continue;
        found[count++] = type == TY_FAMILY ? u : type == TY_PAIRS ? (1u << u) | (1u << v) : 1u << u;
    }

    /* Dal più piccolo al più grande, si tiene un supporto solo se non ne
     * contiene uno già tenuto. */
    qsort(found, (size_t)count, sizeof(unsigned), by_size);
    int kept = 0;
    for (int i = 0; i < count; i++) {
        int redundant = 0;
        for (int j = 0; j < kept && !redundant; j++)
            if ((found[j] & ~found[i]) == 0) redundant = 1;
        if (!redundant) found[kept++] = found[i];
    }
    n->support = found;
    n->supports = kept;
}

/* Calcola i supporti di tutte le relazioni del sotto-albero. */
static void set_prepare(SetNode *n) {
    if (!n) return;
    if (n->kind == SET_EQ || n->kind == SET_SUBSET || n->kind == SET_NEQ) { relation_supports(n); return; }
    set_prepare(n->a);
    set_prepare(n->b);
}

/* Ritorna 1 se la formula n è vera nella configurazione in cui le regioni non
 * vuote sono quelle dei bit di nonempty. Il quantificatore si limita a
 * valutare il proprio corpo: come viene trattato il suo insieme lo decide chi
 * sceglie le configurazioni (vedi 15d e 15e). */
static int set_holds(const SetNode *n, unsigned nonempty) {
    switch (n->kind) {
    case SET_EQ: case SET_SUBSET: case SET_NEQ: {
        int fails = 0;
        for (int i = 0; i < n->supports && !fails; i++)
            if ((n->support[i] & ~nonempty) == 0) fails = 1;
        return n->kind == SET_NEQ ? fails : !fails;
    }
    case SET_AND:     return set_holds(n->a, nonempty) && set_holds(n->b, nonempty);
    case SET_OR:      return set_holds(n->a, nonempty) || set_holds(n->b, nonempty);
    case SET_IMPLIES: return !set_holds(n->a, nonempty) || set_holds(n->b, nonempty);
    case SET_IFF:     return set_holds(n->a, nonempty) == set_holds(n->b, nonempty);
    case SET_NOT:     return !set_holds(n->a, nonempty);
    default:          return set_holds(n->a, nonempty);  /* SET_EXISTS */
    }
}

/* Ritorna 1 se n è vera in ogni configurazione le cui regioni non vuote stanno
 * tra quelle di allowed. Altrimenti ritorna 0 e mette in *failing, tra le
 * configurazioni in cui n è falsa, una con il minor numero di regioni non
 * vuote: darà il controesempio più piccolo. */
static int set_valid(const SetNode *n, unsigned allowed, unsigned *failing) {
    int valid = 1;

    /* Tutti i sottoinsiemi di allowed: (p - 1) & allowed è il successivo in
     * ordine decrescente, e dopo lo zero il giro è finito. */
    for (unsigned p = allowed;; p = (p - 1) & allowed) {
        if (!set_holds(n, p) && (valid || __builtin_popcount(p) < __builtin_popcount(*failing))) {
            valid = 0;
            *failing = p;
        }
        if (p == 0) break;
    }
    return valid;
}

/* Ritorna le regioni compatibili con la scelta, per l'insieme di indice var,
 * di un'unione di regioni degli altri insiemi (caso 15e). mask ha un bit per
 * ogni regione degli altri insiemi: 1 se quella regione fa parte dell'insieme.
 * Una regione di tutti gli insiemi è compatibile se il suo bit var coincide
 * con quanto mask dice della regione che resta togliendo quel bit. */
static unsigned witness_regions(int var, unsigned mask) {
    unsigned allowed = 0;
    for (unsigned region = 0; region < (1u << set_var_count); region++) {
        unsigned low = region & ((1u << var) - 1), high = region >> (var + 1);
        unsigned others = low | (high << var);
        if (((region >> var) & 1) == ((mask >> others) & 1)) allowed |= 1u << region;
    }
    return allowed;
}

/* 15f. Quantificatori in ogni posizione: contare gli elementi delle regioni.
 *
 * "Se S non è vuoto esistono due parti di S, non vuote, senza elementi in
 * comune" è falso: se S ha un elemento solo non si può. Per deciderlo non
 * basta sapere quali regioni sono vuote: conta quanti elementi hanno. Ma non
 * serve contarli tutti.
 *
 * Teorema. Sia P una condizione sugli insiemi con al più q quantificatori
 * "esiste un insieme" uno dentro l'altro. Se due scelte degli insiemi liberi
 * danno a ogni regione lo stesso numero di elementi, oppure tutte e due
 * almeno 2^q, allora P vale per l'una se e solo se vale per l'altra.
 *
 * Dimostrazione, per induzione su q. Con q = 0 la verità di P dipende solo
 * da quali regioni sono vuote (capitolo 15, "Configurazioni"), e 2^0 = 1 è
 * proprio "almeno un elemento". Sia ora P = "esiste X tale che R", con R di
 * profondità q - 1, e X un insieme che funziona per la prima scelta. X
 * divide ogni regione, di c elementi, in due: a dentro X e c - a fuori. La
 * regione corrispondente della seconda scelta ha c' elementi, con c' = c
 * oppure c e c' tutti e due almeno 2^q. La si divide così: se c' = c allo
 * stesso modo; altrimenti, se a < 2^(q-1) si mettono a elementi dentro (ne
 * restano fuori almeno 2^(q-1), come nella prima); se c - a < 2^(q-1) se ne
 * lasciano fuori c - a; se nessuno dei due, almeno 2^(q-1) da ogni parte,
 * che si può perché c' è almeno 2^q. Le regioni nuove hanno allora gli stessi
 * numeri di elementi, o tutte e due almeno 2^(q-1): per ipotesi induttiva R
 * vale anche per la seconda scelta. I connettivi non cambiano nulla.
 *
 * Quindi basta dare a ogni regione degli insiemi liberi un numero di
 * elementi tra 0 e 2^q, dove 2^q vuol dire "almeno", e per ogni "esiste X"
 * provare ogni modo di dividere le regioni: è un conto finito e completo,
 * che decide in tutti e due i sensi.
 *
 * Gli oggetti fuori da tutti gli insiemi. Di oggetti ce n'è quanti se ne
 * vuole, e un insieme quantificato può prenderne; ma nessun insieme li
 * prende tutti: l'insieme di tutti gli oggetti non esiste. Per questo la
 * regione 0, quella degli oggetti che non stanno in nessun insieme, è
 * sempre "almeno" quanto serve, e quando un "esiste X" la divide ne resta
 * fuori sempre altrettanto. Una versione che la trattava come le altre
 * regioni lasciava a X la possibilità di prenderla tutta, e così
 * dimostrava "esiste V tale che ogni W è contenuto in V".
 *
 * Il conto cresce in fretta, e ha un tetto (MAX_COUNT_CASES): oltre, la
 * risposta è NON DIMOSTRATO.
 */

/* Ritorna quanti "esiste un insieme" stanno uno dentro l'altro in n, al più. */
static int set_depth(const SetNode *n) {
    if (!n) return 0;
    int a = set_depth(n->a), b = set_depth(n->b), deepest = a > b ? a : b;
    return n->kind == SET_EXISTS ? deepest + 1 : deepest;
}

/* Ritorna le lettere che in n compaiono libere, un bit per indice; bound sono
 * quelle legate da un quantificatore più esterno. */
static unsigned set_free_letters(const SetNode *n, unsigned bound) {
    if (!n) return 0;
    if (n->kind == SET_VAR) return (1u << n->var) & ~bound;
    if (n->kind == SET_EXISTS) bound |= 1u << n->var;
    return set_free_letters(n->a, bound) | set_free_letters(n->b, bound);
}

/* Quante valutazioni può ancora fare il conto in corso; sotto zero è stato
 * interrotto, e le sue risposte non valgono. */
static long long count_budget;

static int counts_hold(const SetNode *n, const unsigned char *count);

/* 15f, un "esiste X". exists è il nodo, bit la lettera X, cap = 2^d con d
 * la profondità della condizione sotto il quantificatore. count[] sono i
 * numeri di elementi delle regioni scelti finora: quelle prima di `region`
 * sono già divise tra dentro e fuori X, le altre no. Ritorna 1 se c'è un
 * modo di dividere le regioni da `region` in poi che rende vera la
 * condizione.
 *
 * Una regione di m elementi si divide in a dentro e m - a fuori, e dei due
 * numeri conta solo ciò che sta sotto cap: cap vuol dire "almeno cap". Se m
 * è 2 cap, cioè "almeno 2 cap", le divisioni possibili sono tutte le coppie
 * in cui una delle due parti è "almeno cap". */
static int split_holds(const SetNode *exists, unsigned bit, int cap, unsigned char *count, unsigned region) {
    unsigned regions = 1u << set_var_count;
    while (region < regions && (region & bit)) region++;
    if (region == regions) return counts_hold(exists->a, count);

    int whole = count[region], found = 0;
    if (whole < 2 * cap) {
        /* Un numero preciso di elementi: a dentro, gli altri fuori. */
        for (int a = 0; a <= whole && !found && count_budget >= 0; a++) {
            count[region | bit] = (unsigned char)(a < cap ? a : cap);
            count[region] = (unsigned char)(whole - a < cap ? whole - a : cap);
            found = split_holds(exists, bit, cap, count, region + 1);
        }
    } else {
        /* "Almeno 2 cap" elementi. Della regione 0 ne restano fuori sempre
         * "almeno cap": non si esaurisce (vedi sopra). */
        for (int inside = 0; inside <= cap && !found; inside++) {
            for (int outside = inside == cap && region != 0 ? 0 : cap; outside <= cap && !found && count_budget >= 0; outside++) {
                count[region | bit] = (unsigned char)inside;
                count[region] = (unsigned char)outside;
                found = split_holds(exists, bit, cap, count, region + 1);
            }
        }
    }
    count[region] = (unsigned char)whole;
    count[region | bit] = 0;
    return found;
}

/* 15f. Ritorna 1 se la condizione n è vera quando la regione r ha count[r]
 * elementi, dove un numero pari a 2^d o più, con d la profondità di n, vuol
 * dire "almeno 2^d". */
static int counts_hold(const SetNode *n, const unsigned char *count) {
    switch (n->kind) {
    case SET_AND:     return counts_hold(n->a, count) && counts_hold(n->b, count);
    case SET_OR:      return counts_hold(n->a, count) || counts_hold(n->b, count);
    case SET_IMPLIES: return !counts_hold(n->a, count) || counts_hold(n->b, count);
    case SET_IFF:     return counts_hold(n->a, count) == counts_hold(n->b, count);
    case SET_NOT:     return !counts_hold(n->a, count);
    case SET_EXISTS:  break;
    default: {
        /* Una relazione: conta solo quali regioni non sono vuote. */
        unsigned nonempty = 0;
        for (unsigned r = 0; r < (1u << set_var_count); r++)
            if (count[r]) nonempty |= 1u << r;
        if (--count_budget < 0) return 0;
        return set_holds(n, nonempty);
    }
    }

    /* "Esiste X": chi era X fuori da qui non conta più, quindi le regioni
     * tornano intere; poi ognuna viene divisa in tutti i modi. */
    unsigned char inner[1u << MAX_SET_VARS];
    unsigned bit = 1u << n->var;
    int cap = 1 << set_depth(n->a);
    for (unsigned r = 0; r < (1u << set_var_count); r++) {
        int whole = r & bit ? 0 : count[r] + count[r | bit];
        inner[r] = (unsigned char)(whole > 2 * cap || r == 0 ? 2 * cap : whole);
    }
    return split_holds(n, bit, cap, inner, 0);
}

/* 15f. Decide se root vale per ogni scelta degli insiemi liberi, provando
 * per le loro regioni ogni numero di elementi da 0 a 2^q. Ritorna 1 se
 * vale; 0 se no, e allora count[] contiene i numeri di elementi di una
 * scelta in cui non vale; -1 se il conto è stato interrotto. */
static int counts_valid(const SetNode *root, unsigned char *count) {
    unsigned regions = 1u << set_var_count, free_letters = set_free_letters(root, 0);
    int top = 1 << set_depth(root);
    count_budget = MAX_COUNT_CASES;
    memset(count, 0, regions);
    count[0] = (unsigned char)top;
    for (;;) {
        int holds = counts_hold(root, count);
        if (count_budget < 0) return -1;
        if (!holds) return 0;

        /* La scelta successiva, come un contachilometri sulle regioni fatte
         * di soli insiemi liberi. */
        unsigned r = 1;
        for (; r < regions; r++) {
            if (r & ~free_letters) continue;
            if (count[r] < top) { count[r]++; break; }
            count[r] = 0;
        }
        if (r == regions) return 1;
    }
}

/* =============================================================================
 * 16. INSIEMI: VERIFICA INDIPENDENTE E DIMOSTRAZIONE SCRITTA
 * ============================================================================
 *
 * Verifica indipendente. Il capitolo 15 ragiona per regioni. Qui lo stesso
 * enunciato viene ricontrollato in un modo che non ne dipende: si prende un
 * universo piccolo, {1, ..., N}, si assegnano agli insiemi tutti i suoi
 * sottoinsiemi in tutti i modi possibili, e ogni espressione viene calcolata
 * davvero, come insieme. Se i due metodi non sono d'accordo, il verdetto non
 * viene emesso.
 *
 * Non è una seconda dimostrazione: N è piccolo. È un controllo contro gli
 * errori del programma, che è ciò a cui serve.
 *
 * Dimostrazione scritta. Il testo è in LaTeX. La forma preferita è quella
 * discorsiva dei libri: "sia x un elemento del primo insieme; allora... quindi
 * x sta nel secondo; viceversa...". La costruisce chase(), con i passi da 16d
 * a 16g, quando l'enunciato parla di insiemi di elementi o di coppie.
 *
 * Ogni fatto che quel testo afferma viene ricontrollato prima di essere
 * scritto, con un metodo che non usa le regole di chase(): è il controllo
 * 16h.
 *
 * Quando quella forma non si applica (insiemi delle parti, ipotesi "non
 * vuoto", quantificatori) o richiederebbe troppi casi, il testo segue invece
 * il ragionamento per regioni del capitolo 15, in una di tre forme:
 *
 *   16a. Una sola relazione tra insiemi di elementi o di coppie: la tabella di
 *        appartenenza, con una riga per ogni caso.
 *   16b. Un'equivalenza o un'implicazione tra condizioni: per ciascuna, in
 *        quali configurazioni fallisce; il confronto dei due elenchi conclude.
 *   16c. Ogni altro enunciato: per ogni relazione le configurazioni in cui
 *        fallisce, e l'esame di tutte le configurazioni.
 *
 * Anche questi testi affermano dei fatti: le righe di una tabella, gli elenchi
 * di configurazioni, l'insieme scelto per un "esiste". Ognuno viene
 * ricalcolato con gli insiemi veri prima di essere scritto: è il controllo
 * 16i.
 */

/* Ritorna il valore dell'espressione n quando gli insiemi valgono value[],
 * sottoinsiemi di un universo di size elementi. Il risultato è una maschera:
 *
 *   insieme di elementi:    il bit e dice se l'elemento e ne fa parte;
 *   collezione di insiemi:  il bit X dice se l'insieme di maschera X ne fa
 *                           parte;
 *   insieme di coppie:      il bit x * size + y dice se (x, y) ne fa parte.
 *
 * In tutti e tre i casi unione, intersezione e differenza sono le operazioni
 * sui bit. size non deve superare 5, perché le maschere abbiano 32 bit. */
static unsigned concrete(const SetNode *n, unsigned *value, int size) {
    unsigned a = n->a ? concrete(n->a, value, size) : 0, b = n->b ? concrete(n->b, value, size) : 0;
    unsigned result = 0;
    switch (n->kind) {
    case SET_VAR:        return value[n->var];
    case SET_ONLY_EMPTY: return 1u;  /* l'insieme vuoto ha maschera 0 */
    case SET_POWER:
        for (unsigned x = 0; x < (1u << size); x++)
            if ((x & ~a) == 0) result |= 1u << x;
        return result;
    case SET_PRODUCT:
        for (int x = 0; x < size; x++)
            for (int y = 0; y < size; y++)
                if (((a >> x) & 1) && ((b >> y) & 1)) result |= 1u << (x * size + y);
        return result;
    case SET_UNION:      return a | b;
    case SET_INTER:      return a & b;
    case SET_DIFF:       return a & ~b;
    case SET_SYMDIFF:    return a ^ b;
    case SET_APPLY: {
        /* 17r: la regola di f, con la sua lettera che vale a. È il calcolo
         * dell'enunciato com'è scritto, per il controllo dello svolgimento:
         * value[] deve avere MAX_SET_LETTERS posti. */
        const PartRule *rule = &part_rules[n->var];
        unsigned saved = value[rule->param[0]];
        value[rule->param[0]] = a;
        result = concrete(rule->rule, value, size);
        value[rule->param[0]] = saved;
        return result;
    }
    default:             return 0;  /* SET_EMPTY */
    }
}

/* Ritorna 1 se la formula n è vera quando gli insiemi valgono value[],
 * sottoinsiemi di un universo di size elementi. Il quantificatore prova
 * davvero tutti i sottoinsiemi, scrivendo in value[] l'insieme in esame.
 *
 * Per un "esiste X" l'universo ha un elemento in più di quello in cui stanno
 * gli insiemi scelti prima, e così per ogni quantificatore più interno: è
 * il modo di dire, con un universo finito, che fuori da qualunque insieme
 * resta sempre qualche oggetto (vedi 15f). Con un universo fisso l'insieme
 * di tutti gli elementi esisteva, e questo controllo confermava "esiste V
 * tale che ogni W è contenuto in V". */
static int concrete_holds(const SetNode *n, unsigned *value, int size) {
    switch (n->kind) {
    case SET_EQ:      return concrete(n->a, value, size) == concrete(n->b, value, size);
    case SET_NEQ:     return concrete(n->a, value, size) != concrete(n->b, value, size);
    case SET_SUBSET:  return (concrete(n->a, value, size) & ~concrete(n->b, value, size)) == 0;
    case SET_AND:     return concrete_holds(n->a, value, size) && concrete_holds(n->b, value, size);
    case SET_OR:      return concrete_holds(n->a, value, size) || concrete_holds(n->b, value, size);
    case SET_IMPLIES: return !concrete_holds(n->a, value, size) || concrete_holds(n->b, value, size);
    case SET_IFF:     return concrete_holds(n->a, value, size) == concrete_holds(n->b, value, size);
    case SET_NOT:     return !concrete_holds(n->a, value, size);
    case SET_PAIR_IN: {
        /* 17r: A e B sono parti dell'insieme della relazione, e la regola
         * vale con le sue lettere che valgono A e B (vedi SET_APPLY in
         * concrete()). */
        const PartRule *rule = &part_rules[n->var];
        unsigned first = concrete(n->a, value, size), second = concrete(n->b, value, size), base = value[rule->base];
        if ((first & ~base) || (second & ~base)) return 0;
        unsigned saved[2] = {value[rule->param[0]], value[rule->param[1]]};
        value[rule->param[0]] = first;
        value[rule->param[1]] = second;
        int holds = concrete_holds(rule->rule, value, size);
        value[rule->param[0]] = saved[0];
        value[rule->param[1]] = saved[1];
        return holds;
    }
    default:          /* SET_EXISTS */
        for (unsigned candidate = 0; candidate < (1u << (size + 1)); candidate++) {
            value[n->var] = candidate;
            if (concrete_holds(n->a, value, size + 1)) return 1;
        }
        return 0;
    }
}

/* Ritorna 1 se root è vera per ogni assegnazione di sottoinsiemi di un
 * universo di size elementi agli insiemi dell'enunciato. bound è l'indice
 * dell'insieme legato da un quantificatore, o -1: quello non si assegna qui. */
static int concrete_valid(const SetNode *root, int bound, int size) {
    unsigned value[MAX_SET_VARS] = {0};
    for (;;) {
        if (!concrete_holds(root, value, size)) return 0;

        /* Assegnazione successiva, come un contachilometri: si incrementa il
         * primo insieme, e quando ha fatto il giro si passa al seguente. */
        int i = 0;
        for (; i < set_var_count; i++) {
            if (i == bound) continue;
            if (++value[i] < (1u << size)) break;
            value[i] = 0;
        }
        if (i == set_var_count) return 1;
    }
}

/* Costruisce gli insiemi che realizzano la configurazione nonempty, con un
 * elemento per ogni regione non vuota: li mette in value[] come maschere su un
 * universo di *size elementi. */
static void configuration_sets(unsigned nonempty, unsigned *value, int *size) {
    *size = 0;
    for (int i = 0; i < set_var_count; i++) value[i] = 0;
    for (unsigned region = 0; nonempty >> region; region++) {
        if (!((nonempty >> region) & 1)) continue;
        for (int i = 0; i < set_var_count; i++)
            if ((region >> i) & 1) value[i] |= 1u << *size;
        (*size)++;
    }
}

/* 16i. Controllo di un fatto delle forme 16b e 16c: "la condizione n fallisce
 * esattamente nelle configurazioni che contengono una di quelle di list".
 * Gli elenchi nascono dal conto per regioni del capitolo 15; qui, per ogni
 * configurazione contenuta in allowed, si costruiscono gli insiemi veri e si
 * calcola la condizione con concrete_holds(), che delle regioni non sa nulla.
 * Si provano le configurazioni con al più 5 regioni non vuote, perché gli
 * insiemi concreti hanno al più 5 elementi.
 *
 * Con holds diverso da zero il fatto è "vale esattamente", come per una
 * relazione "diverso da". Ritorna 1 se il fatto è confermato; altrimenti
 * annota il passo come non giustificato e ritorna 0. */
static int list_confirmed(const SetNode *n, unsigned allowed, const unsigned *list, int count, int holds) {
    for (unsigned p = allowed;; p = (p - 1) & allowed) {
        if (__builtin_popcount(p) <= 5) {
            unsigned value[MAX_SET_VARS];
            int size, listed = 0;
            for (int i = 0; i < count; i++)
                if ((list[i] & ~p) == 0) listed = 1;
            configuration_sets(p, value, &size);
            if ((concrete_holds(n, value, size) != 0) != (holds ? listed : !listed)) { unjustified_steps++; return 0; }
        }
        if (p == 0) break;
    }
    return 1;
}

/* Aggiunge alla dimostrazione l'espressione o la formula n, in LaTeX. Un
 * operando viene messo tra parentesi quando è a sua volta un'operazione dello
 * stesso livello: tra insiemi sotto un'operazione tra insiemi, tra condizioni
 * sotto un connettivo. */
static void put_set(const SetNode *n) {
    static const char *const symbol[] = {
        [SET_UNION] = "\\cup", [SET_INTER] = "\\cap", [SET_DIFF] = "\\setminus", [SET_SYMDIFF] = "\\triangle",
        [SET_PRODUCT] = "\\times", [SET_EQ] = "=", [SET_SUBSET] = "\\subseteq", [SET_NEQ] = "\\neq",
        [SET_AND] = "\\land", [SET_OR] = "\\lor", [SET_IMPLIES] = "\\implies", [SET_IFF] = "\\iff",
    };
    switch (n->kind) {
    case SET_VAR:        proof_add("%c", set_var_name[n->var]); return;
    case SET_EMPTY:      proof_add("\\emptyset"); return;
    case SET_ONLY_EMPTY: proof_add("\\{\\emptyset\\}"); return;
    case SET_POWER:      proof_add("\\mathcal{P}("); put_set(n->a); proof_add(")"); return;
    case SET_NOT:        proof_add("\\lnot ("); put_set(n->a); proof_add(")"); return;
    case SET_EXISTS:     proof_add("\\exists %c\\,(", set_var_name[n->var]); put_set(n->a); proof_add(")"); return;
    default:             break;
    }

    /* Operatori binari. */
    int logical = n->kind >= SET_AND;
    for (int side = 0; side < 2; side++) {
        const SetNode *operand = side ? n->b : n->a;
        int nested = logical ? operand->kind >= SET_AND && operand->kind != SET_NOT && operand->kind != SET_EXISTS
                             : operand->kind >= SET_UNION && operand->kind <= SET_PRODUCT && n->kind <= SET_PRODUCT;
        if (side) proof_add(" %s ", symbol[n->kind]);
        if (nested) proof_add("(");
        put_set(operand);
        if (nested) proof_add(")");
    }
}

/* Aggiunge alla dimostrazione il nome di una regione, per esempio
 * S \cap T^{c} per "in S e non in T". */
static void put_region(unsigned region) {
    for (int i = 0; i < set_var_count; i++)
        proof_add("%s%c%s", i ? " \\cap " : "", set_var_name[i], ((region >> i) & 1) ? "" : "^{c}");
}

/* Aggiunge alla dimostrazione la descrizione delle configurazioni di list, da
 * leggere dopo "fails exactly": ogni elemento è un insieme di regioni che
 * devono essere tutte non vuote. */
static void put_configurations(const unsigned *list, int count) {
    if (count == 0) { proof_add("in no case"); return; }
    if (list[0] == 0) { proof_add("in every case"); return; }

    /* Il caso più comune: basta una regione non vuota. */
    int single = 1;
    for (int i = 0; i < count; i++)
        if (__builtin_popcount(list[i]) != 1) single = 0;
    if (single && count <= MAX_CONFIGS) {
        proof_add(count == 1 ? "when the region " : "when at least one of the regions ");
        for (int i = 0; i < count; i++) {
            proof_add("%s$", i ? ", " : "");
            put_region((unsigned)__builtin_ctz(list[i]));
            proof_add("$");
        }
        proof_add(" is non-empty");
        return;
    }

    /* In generale: più regioni non vuote insieme. */
    for (int i = 0; i < count && i < MAX_CONFIGS; i++) {
        int size = __builtin_popcount(list[i]), first = 1;
        proof_add("%swhen the region%s ", i ? "; or " : "", size == 1 ? "" : "s");
        for (unsigned region = 0; list[i] >> region; region++) {
            if (!((list[i] >> region) & 1)) continue;
            proof_add("%s$", first ? "" : " and ");
            put_region(region);
            proof_add("$");
            first = 0;
        }
        proof_add(size == 1 ? " is non-empty" : size == 2 ? " are both non-empty" : " are all non-empty");
    }
    if (count > MAX_CONFIGS) proof_add("; or in %d further situations of the same kind", count - MAX_CONFIGS);
}

/* Ritorna 1 se nel sotto-albero c'è una relazione tra oggetti di tipo type. */
static int set_relates(const SetNode *n, SetType type) {
    if (!n) return 0;
    if (n->kind == SET_EQ || n->kind == SET_SUBSET || n->kind == SET_NEQ) {
        SetType operands = set_join(n->a->type, n->b->type);
        return operands == type || (type == TY_SET && operands == TY_ANY);
    }
    return set_relates(n->a, type) || set_relates(n->b, type);
}

/* Aggiunge alla dimostrazione la premessa comune alle forme 16b e 16c: cosa
 * sono le regioni e perché una relazione fallisce in certe configurazioni. Si
 * citano solo i tipi di oggetto presenti nell'enunciato root. */
static void put_regions_preamble(const SetNode *root) {
    proof_add("The sets ");
    for (int i = 0; i < set_var_count; i++) proof_add("%s$%c$", i ? ", " : "", set_var_name[i]);
    proof_add(" divide all elements into regions: a region is fixed by saying, for each of these sets, whether an "
              "element belongs to it. We write $A^{c}$ for ``not in $A$'', so that for instance $");
    put_region(1);
    proof_add("$ is the region of the elements that lie in $%c$ and in none of the other sets. ", set_var_name[0]);
    if (set_relates(root, TY_SET))
        proof_add("Whether an element belongs to a set built from them depends only on its region; so an inclusion "
                  "$A \\subseteq B$ fails exactly when some region contained in $A$ but not in $B$ is non-empty, and "
                  "an equality $A = B$ fails exactly when some region contained in only one of $A$, $B$ is non-empty. ");
    if (set_relates(root, TY_FAMILY))
        proof_add("A set $X$ belongs to $\\mathcal{P}(A)$ exactly when every region that $X$ meets is contained in "
                  "$A$, and to $\\{\\emptyset\\}$ exactly when $X$ meets no region; so whether $X$ belongs to a "
                  "collection of sets depends only on the regions it meets, and two such collections differ exactly "
                  "when some set, with one element in each of certain regions and no other element, lies in only one "
                  "of them. This requires those regions to be all non-empty. ");
    if (set_relates(root, TY_PAIRS))
        proof_add("A pair $(x, y)$ belongs to $A \\times B$ exactly when $x \\in A$ and $y \\in B$; so whether it "
                  "belongs to a set of pairs depends only on the regions of $x$ and of $y$, and two sets of pairs "
                  "differ exactly when some pair lies in only one of them, which requires the regions of its two "
                  "components to be non-empty. ");
    proof_add("\n\n");
}

/* Aggiunge alla dimostrazione un elenco con, per ogni relazione del
 * sotto-albero, le configurazioni in cui fallisce (forma 16c). */
static void put_relation_items(const SetNode *n) {
    if (!n) return;
    if (n->kind == SET_EQ || n->kind == SET_SUBSET || n->kind == SET_NEQ) {
        proof_add("\\item $");
        put_set(n);
        proof_add(n->kind == SET_NEQ ? "$ holds exactly " : "$ fails exactly ");
        put_configurations(n->support, n->supports);
        proof_add(".\n");
        return;
    }
    put_relation_items(n->a);
    put_relation_items(n->b);
}

/* Ritorna 1 se la formula è fatta solo di uguaglianze e inclusioni unite da
 * "e" e "o". Una formula così, se fallisce in una configurazione, fallisce in
 * ogni configurazione con più regioni non vuote: per descriverla bastano le
 * configurazioni minime in cui fallisce. */
static int set_is_monotone(const SetNode *n) {
    if (n->kind == SET_EQ || n->kind == SET_SUBSET) return 1;
    return (n->kind == SET_AND || n->kind == SET_OR) && set_is_monotone(n->a) && set_is_monotone(n->b);
}

/* Mette in out le configurazioni minime, tra quelle contenute in allowed, in
 * cui la formula monotona n fallisce, dalla più piccola alla più grande, e ne
 * ritorna il numero; -1 se sono più di max. Una configurazione è minima se
 * togliendole una qualsiasi regione la formula torna vera. */
static int minimal_failures(const SetNode *n, unsigned allowed, unsigned *out, int max) {
    int count = 0;
    for (unsigned p = allowed;; p = (p - 1) & allowed) {
        int minimal = !set_holds(n, p);
        for (unsigned region = 0; minimal && p >> region; region++)
            if (((p >> region) & 1) && !set_holds(n, p & ~(1u << region))) minimal = 0;
        if (minimal) {
            if (count == max) return -1;
            out[count++] = p;
        }
        if (p == 0) break;
    }
    qsort(out, (size_t)count, sizeof(unsigned), by_size);
    return count;
}

/* Raccoglie in *firsts e *seconds le lettere che nel sotto-albero compaiono
 * nel primo e nel secondo fattore di un prodotto cartesiano: sono quelle a cui
 * possono appartenere le componenti x e y di una coppia. into è il mucchio a
 * cui va la lettera corrente, o NULL fuori da un prodotto. */
static void product_factors(const SetNode *n, unsigned *firsts, unsigned *seconds, unsigned *into) {
    if (!n) return;
    if (n->kind == SET_VAR && into) *into |= 1u << n->var;
    if (n->kind == SET_PRODUCT) {
        product_factors(n->a, firsts, seconds, firsts);
        product_factors(n->b, firsts, seconds, seconds);
        return;
    }
    product_factors(n->a, firsts, seconds, into);
    product_factors(n->b, firsts, seconds, into);
}

/* Forma 16a: se root è una sola relazione tra insiemi di elementi o di coppie
 * scrive la dimostrazione con la tabella di appartenenza e ritorna 1;
 * altrimenti non scrive nulla e ritorna 0.
 *
 * Per gli insiemi di elementi le colonne sono "x appartiene a S" per ogni
 * insieme S. Per le coppie (x, y) sono "x appartiene a S" per gli insiemi che
 * compaiono come primo fattore di un prodotto e "y appartiene a T" per quelli
 * che compaiono come secondo. */
static int put_table_proof(const SetNode *root) {
    if (root->kind != SET_EQ && root->kind != SET_SUBSET) return 0;
    SetType type = set_join(root->a->type, root->b->type);
    unsigned firsts = (1u << set_var_count) - 1, seconds = 0;
    if (type == TY_PAIRS) {
        firsts = 0;
        product_factors(root, &firsts, &seconds, NULL);
    } else if (type != TY_SET && type != TY_ANY) {
        return 0;
    }
    int columns = __builtin_popcount(firsts) + __builtin_popcount(seconds);
    if (columns > 4) return 0;
    size_t start = proof_length;

    /* Premessa. */
    const char *object = type == TY_PAIRS ? "$(x, y)$" : "$x$";
    proof_add("\\textbf{Proof.} Let %s be an arbitrary %s. Each row of the table is one possible combination of the "
              "memberships in its first columns ($1$ = belongs, $0$ = does not belong); the last two columns say, "
              "by the definitions of the operations, whether %s belongs to each side.\n\n",
              object, type == TY_PAIRS ? "pair" : "element", object);

    /* Intestazione. */
    proof_add("\\begin{center}\\begin{tabular}{");
    for (int i = 0; i < columns; i++) proof_add("c");
    proof_add("|cc}\n");
    for (int i = 0; i < set_var_count; i++)
        if ((firsts >> i) & 1) proof_add("$x \\in %c$ & ", set_var_name[i]);
    for (int i = 0; i < set_var_count; i++)
        if ((seconds >> i) & 1) proof_add("$y \\in %c$ & ", set_var_name[i]);
    proof_add("$");
    put_set(root->a);
    proof_add("$ & $");
    put_set(root->b);
    proof_add("$ \\\\ \\hline\n");

    /* Una riga per ogni combinazione: u e v sono le regioni di x e di y. */
    for (unsigned u = 0; u < (1u << set_var_count); u++) {
        if (u & ~firsts) continue;
        for (unsigned v = 0; v < (1u << set_var_count); v++) {
            if (v & ~seconds) continue;
            for (int i = 0; i < set_var_count; i++)
                if ((firsts >> i) & 1) proof_add("%u & ", (u >> i) & 1);
            for (int i = 0; i < set_var_count; i++)
                if ((seconds >> i) & 1) proof_add("%u & ", (v >> i) & 1);
            int left = member(root->a, u, v), right = member(root->b, u, v);
            proof_add("%d & %d \\\\\n", left, right);

            /* 16i. Controllo della riga. Le due colonne si ricalcolano con
             * gli insiemi veri: un universo di due elementi, x (il numero 0)
             * e y (il numero 1), messi negli insiemi che la riga dice. Per
             * gli insiemi di elementi si guarda x, cioè il bit 0; per quelli
             * di coppie la coppia (x, y), cioè il bit 0 * 2 + 1. E la riga
             * deve essere compatibile con ciò che la conclusione dirà di
             * tutte: colonne uguali, oppure la prima non oltre la seconda. */
            unsigned value[MAX_SET_VARS], bit = type == TY_PAIRS ? 2u : 1u;
            for (int i = 0; i < set_var_count; i++) value[i] = ((u >> i) & 1) | (((v >> i) & 1) << 1);
            int agrees = ((concrete(root->a, value, 2) & bit) != 0) == left && ((concrete(root->b, value, 2) & bit) != 0) == right;
            if (!agrees || (root->kind == SET_EQ ? left != right : left && !right)) {
                unjustified_steps++;
                proof_length = start;
                proof_text[start] = 0;
                return 0;
            }
        }
    }
    proof_add("\\end{tabular}\\end{center}\n\n");

    /* Conclusione. */
    if (root->kind == SET_EQ)
        proof_add("The last two columns are equal in every row, so the two sides have the same elements. $\\Box$");
    else
        proof_add("In every row where the first of the last two columns is $1$, the second is $1$ as well, so every "
                  "element of the left-hand side belongs to the right-hand side. $\\Box$");
    return 1;
}

/* Forma 16b: se root è un'equivalenza o un'implicazione tra condizioni
 * monotone, eventualmente sotto ipotesi che sono inclusioni o uguaglianze tra
 * insiemi di elementi, scrive la dimostrazione per confronto delle
 * configurazioni e ritorna 1; altrimenti non scrive nulla e ritorna 0.
 *
 * Le ipotesi di quel tipo dicono solo che certe regioni sono vuote: le si
 * toglie dalle regioni ammesse e si ragiona sulle altre. */
static int put_comparison_proof(const SetNode *root) {
    const SetNode *hypothesis = NULL, *core = root;
    unsigned all = (1u << (1u << set_var_count)) - 1, allowed = all;
    if (set_var_count == 5) return 0;

    /* Ipotesi, se ci sono: la parte sinistra di un'implicazione esterna. */
    if (root->kind == SET_IMPLIES && (root->b->kind == SET_IFF || root->b->kind == SET_IMPLIES)) {
        unsigned empty[MAX_CONFIGS];
        hypothesis = root->a;
        core = root->b;
        if (!set_is_monotone(hypothesis)) return 0;
        int count = minimal_failures(hypothesis, all, empty, MAX_CONFIGS);
        if (count < 0 || !list_confirmed(hypothesis, all, empty, count, 0)) return 0;
        for (int i = 0; i < count; i++) {
            if (__builtin_popcount(empty[i]) != 1) return 0;
            allowed &= ~empty[i];
        }
    }
    if ((core->kind != SET_IFF && core->kind != SET_IMPLIES) || !set_is_monotone(core->a) || !set_is_monotone(core->b))
        return 0;

    /* Le configurazioni minime in cui ciascuna delle due condizioni fallisce. */
    unsigned left[MAX_CONFIGS], right[MAX_CONFIGS];
    int lefts = minimal_failures(core->a, allowed, left, MAX_CONFIGS);
    int rights = minimal_failures(core->b, allowed, right, MAX_CONFIGS);
    if (lefts < 0 || rights < 0) return 0;

    /* 16i. I due elenchi, ricontrollati con gli insiemi veri, e ciò che il
     * testo dirà del loro confronto: ogni configurazione minima in cui la
     * seconda condizione fallisce ne contiene una in cui fallisce la prima
     * e, per un'equivalenza, anche il viceversa. */
    if (!list_confirmed(core->a, allowed, left, lefts, 0) || !list_confirmed(core->b, allowed, right, rights, 0)) return 0;
    for (int way = 0; way < (core->kind == SET_IFF ? 2 : 1); way++) {
        const unsigned *weak = way ? left : right, *strong = way ? right : left;
        int weaks = way ? lefts : rights, strongs = way ? rights : lefts;
        for (int i = 0; i < weaks; i++) {
            int contains = 0;
            for (int j = 0; j < strongs; j++)
                if ((strong[j] & ~weak[i]) == 0) contains = 1;
            if (!contains) { unjustified_steps++; return 0; }
        }
    }

    proof_add("\\textbf{Proof.} ");
    put_regions_preamble(root);
    if (hypothesis) {
        unsigned empty = all & ~allowed;
        proof_add("By the hypothesis $");
        put_set(hypothesis);
        proof_add("$, ");
        if (empty) {
            int first = 1;
            for (unsigned region = 0; empty >> region; region++) {
                if (!((empty >> region) & 1)) continue;
                proof_add("%s$", first ? "the following regions are empty: " : ", ");
                put_region(region);
                proof_add("$");
                first = 0;
            }
            proof_add("; only the remaining regions are considered below. ");
        } else {
            proof_add("no region is forced to be empty. ");
        }
    }

    if (core->kind == SET_IFF) {
        /* Le due condizioni falliscono nelle stesse configurazioni: gli
         * elenchi coincidono, e se ne stampa uno. */
        proof_add("Each of the two conditions $");
        put_set(core->a);
        proof_add("$ and $");
        put_set(core->b);
        proof_add("$ fails exactly ");
        put_configurations(left, lefts);
        proof_add(". Hence one holds if and only if the other does. $\\Box$");
    } else {
        proof_add("The condition $");
        put_set(core->a);
        proof_add("$ fails exactly ");
        put_configurations(left, lefts);
        proof_add("; the condition $");
        put_set(core->b);
        proof_add("$ fails exactly ");
        put_configurations(right, rights);
        proof_add(". Every situation in which the second fails is one in which the first fails as well; hence the "
                  "first implies the second. $\\Box$");
    }
    return 1;
}

/* 16i. Ritorna 1 se per ogni relazione del sotto-albero l'elenco delle
 * configurazioni in cui fallisce (o vale, se è "diverso da"), che la forma
 * 16c sta per scrivere, è confermato da list_confirmed(). */
static int relations_confirmed(const SetNode *n) {
    if (!n) return 1;
    if (n->kind == SET_EQ || n->kind == SET_SUBSET || n->kind == SET_NEQ)
        return list_confirmed(n, (1u << (1u << set_var_count)) - 1, n->support, n->supports, n->kind == SET_NEQ);
    return relations_confirmed(n->a) && relations_confirmed(n->b);
}

/* Forma 16c: scrive la dimostrazione generica di root. witness, se non è
 * NULL, è il quantificatore per cui è stato trovato l'insieme esplicito
 * unione delle regioni di mask (vedi 15e). Ritorna 0, senza scrivere nulla,
 * se un elenco che starebbe per scrivere non supera il controllo 16i. */
static int put_general_proof(const SetNode *root, const SetNode *witness, unsigned mask) {
    int single = root->kind == SET_EQ || root->kind == SET_SUBSET;
    if (!single && !relations_confirmed(root)) return 0;
    proof_add("\\textbf{Proof.} ");
    put_regions_preamble(root);

    /* Una sola relazione, tra collezioni di insiemi o tra insiemi di coppie:
     * non ci sono condizioni da combinare, si confrontano i due membri su
     * tutti gli oggetti possibili. */
    if (single) {
        unsigned regions = 1u << set_var_count;
        if (set_relates(root, TY_FAMILY))
            proof_add("There are $%u$ ways of choosing which regions a set $X$ meets. In each of them, ", 1u << regions);
        else
            proof_add("There are $%u$ ways of choosing the regions of $x$ and of $y$ for a pair $(x, y)$. In each of them, ", regions * regions);
        proof_add(root->kind == SET_EQ ? "it belongs to the left-hand side exactly when it belongs to the right-hand side. "
                                         "Hence the two sides have the same elements. $\\Box$"
                                       : "if it belongs to the left-hand side then it belongs to the right-hand side. "
                                         "Hence the left-hand side is contained in the right-hand side. $\\Box$");
        return 1;
    }
    proof_add("For the conditions in the statement this gives:\n\\begin{itemize}\n");
    put_relation_items(root);
    proof_add("\\end{itemize}\n");

    if (witness) {
        /* L'insieme scelto, scritto come unione di regioni degli altri. */
        proof_add("For the set $%c$ whose existence is claimed we take $%c = ", set_var_name[witness->var], set_var_name[witness->var]);
        int first = 1;
        for (unsigned others = 0; mask >> others; others++) {
            if (!((mask >> others) & 1)) continue;
            unsigned low = others & ((1u << witness->var) - 1), high = others >> witness->var;
            unsigned region = low | (high << (witness->var + 1));
            proof_add("%s(", first ? "" : " \\cup ");
            for (int i = 0, printed = 0; i < set_var_count; i++) {
                if (i == witness->var) continue;
                proof_add("%s%c%s", printed++ ? " \\cap " : "", set_var_name[i], ((region >> i) & 1) ? "" : "^{c}");
            }
            proof_add(")");
            first = 0;
        }
        proof_add("%s$; where $%c$ instead appears in a hypothesis, it is an arbitrary set and counts as one more "
                  "set dividing the elements into regions. ", first ? "\\emptyset" : "", set_var_name[witness->var]);
    }
    proof_add("The statement is a logical combination of these conditions, so its truth depends only on which "
              "regions are empty. It was checked in each of the possible cases, and it holds in all of them. $\\Box$");
    return 1;
}

/* Un fatto su un punto: sta (sign = 1) o non sta (sign = 0) in node. Per un
 * insieme di elementi coord dice di quale componente si parla, 0 per x e 1 per
 * y; per un insieme di coppie il punto è la coppia (x, y) e coord non conta. */
typedef struct {
    const SetNode *node;
    int coord, sign;
} Fact;

/* Lo stato di una dimostrazione "per inseguimento degli elementi": ciò che si
 * sa del punto in esame e ciò che resta da sviluppare.
 *
 * Di ogni lettera si sa se x (indice 0) o y (indice 1) le appartiene: il bit
 * della lettera in known dice se lo si sa, quello in truth cosa si sa.
 * pending sono i fatti affermati ma non ancora scomposti. list_start serve a
 * sapere se l'elenco di passaggi in corso è ancora vuoto. */
typedef struct {
    unsigned known[2], truth[2];
    Fact pending[24];
    int pendings;
    size_t list_start;  /* lunghezza del testo quando è iniziato l'elenco di passaggi in corso */
    unsigned long long alive[4];  /* 16h: i mondi ancora possibili, un bit per mondo */
} Chase;

/* Passi ancora concessi: se si esauriscono la dimostrazione discorsiva viene
 * abbandonata, per non scrivere pagine di casi. Un valore negativo dice che
 * va abbandonata comunque. */
static int chase_budget;

/* Le ipotesi utilizzabili durante un inseguimento, come inclusioni: ogni
 * punto di hypothesis_sub[i] sta in hypothesis_sup[i]. */
static const SetNode *hypothesis_sub[16], *hypothesis_sup[16];
static int hypotheses;

/* Le lettere su cui ha senso distinguere due casi, per x e per y. */
static unsigned chase_letters[2];

/* Quanti casi sono aperti uno dentro l'altro. Ogni caso è un elenco rientrato
 * nel documento, e LaTeX ne ammette quattro annidati: oltre il terzo livello
 * di casi la dimostrazione discorsiva viene abbandonata. */
static int chase_depth;

/* 16h. Controllo di ogni passo.
 *
 * chase() ricava i fatti con le sue regole: scompone, usa le ipotesi, apre
 * casi. Qui gli stessi fatti vengono ricontrollati senza regole, per forza
 * bruta. Un "mondo" è un modo completo di dire a quali insiemi appartengono x
 * e y: due regioni, u per x e v per y. Con al più quattro insiemi i mondi sono
 * al più 16 * 16 = 256, e il mondo (u, v) ha il numero 16 u + v.
 *
 * Ogni ramo della dimostrazione porta con sé l'elenco dei mondi ancora
 * possibili, Chase.alive: all'inizio quelli che rispettano le ipotesi; ogni
 * volta che il testo assume qualcosa ("sia x in ...", "caso x in T") si
 * tolgono i mondi in cui non vale. Allora:
 *
 *   - un fatto che il testo afferma come conseguenza deve valere in tutti i
 *     mondi rimasti;
 *   - "questo caso non può presentarsi" richiede che non ne sia rimasto
 *     nessuno;
 *   - quando si distinguono due casi, ogni mondo rimasto deve stare in uno
 *     dei due.
 *
 * Se un controllo fallisce la dimostrazione discorsiva viene abbandonata,
 * come quando i passi concessi finiscono, e il contatore unjustified_steps
 * sale: il verdetto non cambia, perché è già stato stabilito in altro modo,
 * ma quel testo non viene scritto. */

/* Ritorna 1 se nel mondo (u, v) il fatto è vero. */
static int fact_in_world(Fact fact, unsigned u, unsigned v) {
    int inside = fact.node->type == TY_PAIRS ? member(fact.node, u, v) : member(fact.node, fact.coord ? v : u, 0);
    return inside == fact.sign;
}

/* Ritorna 1 se il mondo numero w è ancora possibile nel ramo c. */
static int world_alive(const Chase *c, unsigned w) { return (c->alive[w / 64] >> (w % 64)) & 1; }

/* Da qui in poi il ramo c assume il fatto: toglie i mondi in cui non vale. */
static void worlds_assume(Chase *c, Fact fact) {
    for (unsigned w = 0; w < 256; w++)
        if (!fact_in_world(fact, w >> 4, w & 15)) c->alive[w / 64] &= ~(1ULL << (w % 64));
}

/* Annota che un passo non ha superato il controllo e fa abbandonare la
 * dimostrazione discorsiva. Ritorna 0, per comodità di chi chiama. */
static int step_unjustified(void) {
    unjustified_steps++;
    chase_budget = -1;
    return 0;
}

/* Ritorna 1 se il fatto vale in tutti i mondi possibili nel ramo c; altrimenti
 * annota il passo come non giustificato e ritorna 0. */
static int worlds_entail(const Chase *c, Fact fact) {
    for (unsigned w = 0; w < 256; w++)
        if (world_alive(c, w) && !fact_in_world(fact, w >> 4, w & 15)) return step_unjustified();
    return 1;
}

/* Ritorna 1 se nel ramo c non è rimasto nessun mondo possibile; altrimenti
 * annota il passo come non giustificato e ritorna 0. */
static int worlds_none(const Chase *c) {
    return (c->alive[0] | c->alive[1] | c->alive[2] | c->alive[3]) == 0 ? 1 : step_unjustified();
}

/* Aggiunge un fatto da sviluppare. */
static void chase_push(Chase *c, const SetNode *node, int coord, int sign) {
    if (c->pendings == (int)(sizeof c->pending / sizeof *c->pending)) { chase_budget = -1; return; }
    c->pending[c->pendings++] = (Fact){node, coord, sign};
}

/* Ritorna 1 se da ciò che si sa segue che il punto sta in n, 0 se segue che
 * non ci sta, -1 se non si può ancora dire. */
static int chase_value(const SetNode *n, int coord, const Chase *c) {
    if (n->kind == SET_VAR) return ((c->known[coord] >> n->var) & 1) ? (int)((c->truth[coord] >> n->var) & 1) : -1;
    if (n->kind == SET_EMPTY) return 0;
    int a = chase_value(n->a, n->kind == SET_PRODUCT ? 0 : coord, c);
    int b = chase_value(n->b, n->kind == SET_PRODUCT ? 1 : coord, c);
    switch (n->kind) {
    case SET_UNION:   return a == 1 || b == 1 ? 1 : a == 0 && b == 0 ? 0 : -1;
    case SET_DIFF:    return a == 0 || b == 1 ? 0 : a == 1 && b == 0 ? 1 : -1;
    case SET_SYMDIFF: return a < 0 || b < 0 ? -1 : a != b;
    default:          return a == 0 || b == 0 ? 0 : a == 1 && b == 1 ? 1 : -1;  /* intersezione, prodotto */
    }
}

/* Aggiunge alla dimostrazione il fatto "il punto sta / non sta in n". */
static void put_fact(const SetNode *n, int coord, int sign) {
    proof_add("$%s %s ", n->type == TY_PAIRS ? "(x, y)" : coord ? "y" : "x", sign ? "\\in" : "\\notin");
    put_set(n);
    proof_add("$");
}

/* Aggiunge alla dimostrazione la giustificazione di ciò che chase_value()
 * dice di n: per ogni operazione, quali fatti sui suoi operandi la decidono,
 * partendo dalle più interne. Per esempio "As x in S and x not in T,
 * x in S \ T". Delle lettere non c'è nulla da giustificare. */
static void chase_explain(const SetNode *n, int coord, const Chase *c) {
    if (n->kind == SET_VAR || n->kind == SET_EMPTY) return;
    int ca = n->kind == SET_PRODUCT ? 0 : coord, cb = n->kind == SET_PRODUCT ? 1 : coord;
    int a = chase_value(n->a, ca, c), b = chase_value(n->b, cb, c), sign = chase_value(n, coord, c);

    /* Quali operandi servono: uno solo quando basta a decidere. */
    int use_a = 1, use_b = 1;
    if (n->kind == SET_UNION && sign) { use_a = a == 1; use_b = !use_a; }
    if ((n->kind == SET_INTER || n->kind == SET_PRODUCT) && !sign) { use_a = a == 0; use_b = !use_a; }
    if (n->kind == SET_DIFF && !sign) { use_a = a == 0; use_b = !use_a; }

    if (use_a) chase_explain(n->a, ca, c);
    if (use_b) chase_explain(n->b, cb, c);

    /* 16h. I fatti citati e quello che se ne ricava devono essere veri in
     * tutti i mondi possibili. */
    if ((use_a && !worlds_entail(c, (Fact){n->a, ca, a})) || (use_b && !worlds_entail(c, (Fact){n->b, cb, b})) ||
        !worlds_entail(c, (Fact){n, coord, sign}))
        return;
    proof_add("\\item As ");
    if (use_a) put_fact(n->a, ca, a);
    if (use_a && use_b) proof_add(" and ");
    if (use_b) put_fact(n->b, cb, b);
    proof_add(", ");
    put_fact(n, coord, sign);
    proof_add(".\n");
}

/* Prosegue la dimostrazione che il punto, di cui si sa quanto è in c, sta in
 * goal, scrivendone il testo. Ritorna 1 se ogni caso si chiude, 0 se la
 * dimostrazione va abbandonata.
 *
 * È il modo in cui queste dimostrazioni si scrivono a mano:
 *
 *   16d. Si scompongono i fatti noti con le definizioni: "x sta in A meno B"
 *        dà "x sta in A" e "x non sta in B". Quando la definizione lascia due
 *        possibilità, come per "x sta in A unito B", si distinguono due casi.
 *   16e. Se ormai si sa che il punto sta in goal, lo si giustifica e il caso è
 *        chiuso.
 *   16f. Altrimenti si usa un'ipotesi A contenuto in B: se il punto sta in A
 *        allora sta in B, e se non sta in B allora non sta in A.
 *   16g. Se nessuna ipotesi dice qualcosa di nuovo, si distinguono due casi
 *        secondo che x stia o no in una lettera di cui non si sa ancora nulla.
 *
 * Un caso si chiude anche quando ciò che si sa è contraddittorio: non può
 * presentarsi. Ogni passo aggiunge un'informazione su un numero finito di
 * lettere, quindi il procedimento termina. */
static int chase(Chase c, const SetNode *goal) {
    if (--chase_budget < 0) return 0;

    /* 16d. Scomposizione dei fatti in attesa. Si prende per primo il fatto
     * più semplice: una lettera, poi un fatto già deciso da ciò che si sa, poi
     * uno che si scompone senza casi. Così i casi si aprono solo quando sono
     * inevitabili, e spesso ciò che si è appreso nel frattempo li rende
     * inutili. */
    while (c.pendings > 0) {
        int pick = 0, best = -1;
        for (int i = 0; i < c.pendings; i++) {
            const SetNode *m = c.pending[i].node;
            int sign = c.pending[i].sign, rank = 0;
            if (m->kind == SET_VAR) rank = 3;
            else if (chase_value(m, c.pending[i].coord, &c) >= 0) rank = 2;
            else if (sign ? m->kind == SET_INTER || m->kind == SET_PRODUCT || m->kind == SET_DIFF : m->kind == SET_UNION) rank = 1;
            if (rank >= best) { best = rank; pick = i; }
        }
        Fact fact = c.pending[pick];
        c.pending[pick] = c.pending[--c.pendings];
        const SetNode *n = fact.node;
        int now = chase_value(n, fact.coord, &c);
        if (now == fact.sign) continue;
        if (now >= 0) {
            /* Ciò che si sa dice il contrario: il caso non può presentarsi. */
            if (!worlds_none(&c)) return 0;
            if (n->kind == SET_EMPTY) {
                proof_add("\\item But no element belongs to $\\emptyset$, so this case cannot occur.\n");
                return 1;
            }
            chase_explain(n, fact.coord, &c);
            proof_add("\\item This contradicts ");
            put_fact(n, fact.coord, fact.sign);
            proof_add(", so this case cannot occur.\n");
            return 1;
        }
        if (n->kind == SET_VAR) {
            c.known[fact.coord] |= 1u << n->var;
            if (fact.sign) c.truth[fact.coord] |= 1u << n->var;
            continue;
        }

        /* Le due possibilità che la definizione lascia aperte, ognuna fatta
         * di uno o due fatti sugli operandi; se è una sola, i suoi fatti
         * valgono insieme. */
        int ca = n->kind == SET_PRODUCT ? 0 : fact.coord, cb = n->kind == SET_PRODUCT ? 1 : fact.coord;
        Fact option[2][2];
        int size[2] = {0, 0}, options = 2;
        if ((fact.sign && (n->kind == SET_INTER || n->kind == SET_PRODUCT || n->kind == SET_DIFF)) ||
            (!fact.sign && n->kind == SET_UNION)) {
            options = 1;
            option[0][size[0]++] = (Fact){n->a, ca, fact.sign};
            option[0][size[0]++] = (Fact){n->b, cb, n->kind == SET_DIFF ? 0 : fact.sign};
        } else if (n->kind == SET_SYMDIFF) {
            option[0][size[0]++] = (Fact){n->a, ca, 1};
            option[0][size[0]++] = (Fact){n->b, cb, !fact.sign};
            option[1][size[1]++] = (Fact){n->a, ca, 0};
            option[1][size[1]++] = (Fact){n->b, cb, fact.sign};
        } else {
            option[0][size[0]++] = (Fact){n->a, ca, fact.sign};
            option[1][size[1]++] = (Fact){n->b, cb, n->kind == SET_DIFF ? 1 : fact.sign};
        }

        /* Una possibilità già smentita da ciò che si sa non va considerata. */
        int open[2] = {0, 0}, opens = 0;
        for (int i = 0; i < options; i++) {
            open[i] = 1;
            for (int j = 0; j < size[i]; j++)
                if (chase_value(option[i][j].node, option[i][j].coord, &c) == !option[i][j].sign) open[i] = 0;
            opens += open[i];
        }
        if (opens == 0) {
            if (!worlds_none(&c)) return 0;
            proof_add("\\item But ");
            put_fact(n, fact.coord, fact.sign);
            proof_add(" is impossible here, so this case cannot occur.\n");
            return 1;
        }
        if (opens == 1) {
            int only = open[0] ? 0 : 1;
            for (int j = 0; j < size[only]; j++)
                if (!worlds_entail(&c, option[only][j])) return 0;
            proof_add("\\item Then ");
            for (int j = 0; j < size[only]; j++) {
                if (j) proof_add(" and ");
                put_fact(option[only][j].node, option[only][j].coord, option[only][j].sign);
                chase_push(&c, option[only][j].node, option[only][j].coord, option[only][j].sign);
            }
            proof_add(".\n");
            continue;
        }

        /* Due casi, ognuno proseguito per conto suo in un elenco rientrato. */
        if (chase_depth == 3) return 0;

        /* 16h. I due casi devono coprire tutti i mondi possibili. */
        for (unsigned w = 0; w < 256; w++) {
            int covered = 0;
            for (int i = 0; i < 2 && !covered; i++) {
                covered = 1;
                for (int j = 0; j < size[i]; j++)
                    if (!fact_in_world(option[i][j], w >> 4, w & 15)) covered = 0;
            }
            if (world_alive(&c, w) && !covered) return step_unjustified();
        }
        proof_add("\\item Two cases are possible.\n");
        for (int i = 0; i < 2; i++) {
            Chase branch = c;
            proof_add("\\item \\emph{Case} ");
            for (int j = 0; j < size[i]; j++) {
                if (j) proof_add(" and ");
                put_fact(option[i][j].node, option[i][j].coord, option[i][j].sign);
                chase_push(&branch, option[i][j].node, option[i][j].coord, option[i][j].sign);
                worlds_assume(&branch, option[i][j]);
            }
            proof_add(":\n\\begin{itemize}\n");
            branch.list_start = proof_length;
            chase_depth++;
            int closed = chase(branch, goal);
            chase_depth--;
            if (!closed) return 0;
            proof_add("\\end{itemize}\n");
        }
        return 1;
    }

    /* 16e. La tesi è raggiunta. Se non c'è nulla da giustificare, perché la
     * tesi è tra i fatti già noti, e l'elenco dei passaggi è ancora vuoto, la
     * si enuncia comunque: in LaTeX un elenco non può restare senza voci. */
    if (chase_value(goal, 0, &c) == 1) {
        chase_explain(goal, 0, &c);
        if (!worlds_entail(&c, (Fact){goal, 0, 1})) return 0;
        if (proof_length == c.list_start) {
            proof_add("\\item So ");
            put_fact(goal, 0, 1);
            proof_add(".\n");
        }
        return 1;
    }

    /* 16f. Un'ipotesi che aggiunge un fatto nuovo. */
    for (int i = 0; i < hypotheses; i++) {
        const SetNode *sub = hypothesis_sub[i], *sup = hypothesis_sup[i];
        int inside = chase_value(sub, 0, &c), above = chase_value(sup, 0, &c);
        int forward = inside == 1 && above != 1, backward = above == 0 && inside != 0;
        if (!forward && !backward) continue;
        chase_explain(forward ? sub : sup, 0, &c);
        if (!worlds_entail(&c, (Fact){forward ? sup : sub, 0, forward})) return 0;
        proof_add("\\item Since $");
        put_set(sub);
        proof_add(" \\subseteq ");
        put_set(sup);
        proof_add("$ by assumption, ");
        put_fact(forward ? sup : sub, 0, forward);
        proof_add(".\n");
        chase_push(&c, forward ? sup : sub, 0, forward);
        return chase(c, goal);
    }

    /* 16g. Due casi su una lettera di cui non si sa ancora nulla. */
    for (int coord = 0; coord < 2; coord++)
        for (int var = 0; var < set_var_count; var++) {
            if (!((chase_letters[coord] >> var) & 1) || ((c.known[coord] >> var) & 1)) continue;
            if (chase_depth == 3) return 0;
            proof_add("\\item Two cases are possible.\n");
            for (int sign = 1; sign >= 0; sign--) {
                Chase branch = c;
                SetNode letter = {SET_VAR, TY_SET, var, NULL, NULL, NULL, 0};
                branch.known[coord] |= 1u << var;
                if (sign) branch.truth[coord] |= 1u << var;
                worlds_assume(&branch, (Fact){&letter, coord, sign});
                proof_add("\\item \\emph{Case} $%s %s %c$:\n\\begin{itemize}\n",
                          coord ? "y" : "x", sign ? "\\in" : "\\notin", set_var_name[var]);
                branch.list_start = proof_length;
                chase_depth++;
                int closed = chase(branch, goal);
                chase_depth--;
                if (!closed) return 0;
                proof_add("\\end{itemize}\n");
            }
            return 1;
        }
    return 0;
}

/* Ritorna le lettere che compaiono nel sotto-albero, un bit per lettera. */
static unsigned set_letters(const SetNode *n) {
    if (!n) return 0;
    return (n->kind == SET_VAR ? 1u << n->var : 0) | set_letters(n->a) | set_letters(n->b);
}

/* Scrive la dimostrazione che ogni punto di sub sta in sup, con le ipotesi
 * correnti. Ritorna 0 se va abbandonata. L'insieme vuoto è contenuto in ogni
 * insieme, e in quel caso non c'è nulla da scrivere. converse diverso da zero
 * fa cominciare il testo con "Conversely": è la seconda metà di
 * un'uguaglianza. */
static int narrate_inclusion(const SetNode *sub, const SetNode *sup, int converse) {
    if (sub->kind == SET_EMPTY) return 1;
    int pairs = sub->type == TY_PAIRS || sup->type == TY_PAIRS;
    Chase start = {0};

    /* Le lettere su cui distinguere i casi: per le coppie quelle dei primi e
     * dei secondi fattori, per gli elementi quelle dei due membri e delle
     * ipotesi. */
    chase_letters[0] = chase_letters[1] = 0;
    if (pairs) {
        product_factors(sub, &chase_letters[0], &chase_letters[1], NULL);
        product_factors(sup, &chase_letters[0], &chase_letters[1], NULL);
    } else {
        chase_letters[0] = set_letters(sub) | set_letters(sup);
        for (int i = 0; i < hypotheses; i++) chase_letters[0] |= set_letters(hypothesis_sub[i]) | set_letters(hypothesis_sup[i]);
    }

    proof_add("%s $%s \\in ", sup->kind == SET_EMPTY ? (converse ? "Conversely, suppose that" : "Suppose that")
                                                       : (converse ? "Conversely, let" : "Let"), pairs ? "(x, y)" : "x");
    put_set(sub);
    proof_add("$.\n\\begin{itemize}\n");
    start.list_start = proof_length;
    chase_push(&start, sub, 0, 1);

    /* 16h. I mondi possibili all'inizio: quelli che rispettano le ipotesi,
     * ristretti poi a quelli in cui il punto sta in sub. */
    unsigned regions = 1u << set_var_count;
    for (unsigned u = 0; u < regions; u++)
        for (unsigned v = 0; v < regions; v++) {
            int possible = 1;
            for (int i = 0; i < hypotheses; i++)
                if (fact_in_world((Fact){hypothesis_sub[i], 0, 1}, u, v) && !fact_in_world((Fact){hypothesis_sup[i], 0, 1}, u, v))
                    possible = 0;
            if (possible) start.alive[(16 * u + v) / 64] |= 1ULL << ((16 * u + v) % 64);
        }
    worlds_assume(&start, (Fact){sub, 0, 1});
    if (!chase(start, sup)) return 0;
    proof_add("\\end{itemize}\n");
    if (sup->kind == SET_EMPTY) {
        proof_add("So there is no such element.\n\n");
    } else {
        proof_add("Hence $");
        put_set(sub);
        proof_add(" \\subseteq ");
        put_set(sup);
        proof_add("$.\n\n");
    }
    return 1;
}

/* Scrive la dimostrazione di tutte le relazioni della congiunzione n: di ogni
 * inclusione direttamente, di ogni uguaglianza con le due inclusioni. */
static int narrate_goals(const SetNode *n) {
    if (n->kind == SET_AND) return narrate_goals(n->a) && narrate_goals(n->b);
    if (!narrate_inclusion(n->a, n->b, 0)) return 0;
    if (n->kind == SET_SUBSET) return 1;
    if (!narrate_inclusion(n->b, n->a, n->a->kind != SET_EMPTY)) return 0;
    proof_add("Therefore $");
    put_set(n);
    proof_add("$.\n\n");
    return 1;
}

/* Aggiunge alle ipotesi le relazioni della congiunzione n: un'inclusione così
 * com'è, un'uguaglianza come due inclusioni. */
static void add_hypotheses(const SetNode *n) {
    if (n->kind == SET_AND) { add_hypotheses(n->a); add_hypotheses(n->b); return; }
    for (int way = 0; way < (n->kind == SET_EQ ? 2 : 1) && hypotheses < 16; way++) {
        hypothesis_sub[hypotheses] = way ? n->b : n->a;
        hypothesis_sup[hypotheses++] = way ? n->a : n->b;
    }
}

/* Ritorna 1 se n è una congiunzione di inclusioni e uguaglianze tra insiemi di
 * elementi; con pairs diverso da zero sono ammessi anche gli insiemi di
 * coppie. */
static int set_is_plain(const SetNode *n, int pairs) {
    if (n->kind == SET_AND) return set_is_plain(n->a, pairs) && set_is_plain(n->b, pairs);
    if (n->kind != SET_EQ && n->kind != SET_SUBSET) return 0;
    SetType type = set_join(n->a->type, n->b->type);
    return type == TY_SET || type == TY_ANY || (pairs && type == TY_PAIRS);
}

/* Forma discorsiva, quella preferita: se root è un'inclusione o
 * un'uguaglianza, oppure un'implicazione o un'equivalenza tra condizioni di
 * quel tipo (anche sotto ipotesi dello stesso tipo), scrive la dimostrazione
 * per inseguimento degli elementi e ritorna 1. Altrimenti, o se i casi da
 * distinguere sono troppi, non lascia nulla e ritorna 0.
 *
 * Con delle ipotesi sono ammessi solo insiemi di elementi: le ipotesi vengono
 * applicate al punto x, non a una coppia. */
static int put_narrative_proof(const SetNode *root) {
    const SetNode *given = NULL, *core = root;
    if (root->kind == SET_IMPLIES) { given = root->a; core = root->b; }
    int equivalence = core->kind == SET_IFF;
    if (given && !set_is_plain(given, 0)) return 0;
    if (equivalence ? !set_is_plain(core->a, 0) || !set_is_plain(core->b, 0) : !set_is_plain(core, !given)) return 0;

    hypotheses = 0;
    chase_budget = 300;
    chase_depth = 0;
    proof_add("\\textbf{Proof.} ");
    if (given) {
        add_hypotheses(given);
        proof_add("Assume $");
        put_set(given);
        proof_add("$.\n\n");
    }
    int complete;
    if (!equivalence) {
        complete = narrate_goals(core);
    } else {
        /* Le due implicazioni, ognuna con il proprio lato come ipotesi. */
        int kept = hypotheses;
        add_hypotheses(core->a);
        proof_add("\\smallskip ($\\Rightarrow$) Assume that $");
        put_set(core->a);
        proof_add("$.\n\n");
        complete = narrate_goals(core->b);
        hypotheses = kept;
        add_hypotheses(core->b);
        proof_add("\\smallskip ($\\Leftarrow$) Conversely, assume that $");
        put_set(core->b);
        proof_add("$.\n\n");
        complete = complete && narrate_goals(core->a);
    }
    if (!complete || chase_budget < 0) { proof_reset(); return 0; }
    proof_add("\\hfill $\\Box$");
    return 1;
}

/* Il controesempio di un enunciato falso, come testo: vale fino al verdetto
 * successivo. */
static char counterexample_text[256];

/* Scrive in counterexample_text gli insiemi value[], sottoinsiemi di un
 * universo di size elementi, per esempio "S = {1, 2}, T = {}". Riporta solo
 * le lettere il cui indice ha il bit in listed. */
static void sets_describe(const unsigned *value, int size, unsigned listed) {
    size_t length = 0;
    counterexample_text[0] = 0;
    for (int i = 0; i < set_var_count; i++) {
        if (!((listed >> i) & 1)) continue;
        length += (size_t)snprintf(counterexample_text + length, sizeof counterexample_text - length,
                                   "%s%c = {", length ? ", " : "", set_var_name[i]);
        for (int e = 0, printed = 0; e < size && length < sizeof counterexample_text; e++)
            if ((value[i] >> e) & 1)
                length += (size_t)snprintf(counterexample_text + length, sizeof counterexample_text - length,
                                           "%s%d", printed++ ? ", " : "", e + 1);
        if (length < sizeof counterexample_text)
            length += (size_t)snprintf(counterexample_text + length, sizeof counterexample_text - length, "}");
    }
}

/* Scrive nella dimostrazione che l'enunciato è falso, con gli stessi insiemi
 * di sets_describe() come controesempio. */
static void put_counterexample(const unsigned *value, int size, unsigned listed) {
    proof_add("The statement is false. Counterexample: $");
    for (int i = 0, printed = 0; i < set_var_count; i++) {
        if (!((listed >> i) & 1)) continue;
        proof_add("%s%c = ", printed++ ? ",\\ " : "", set_var_name[i]);
        if (!value[i]) { proof_add("\\emptyset"); continue; }
        proof_add("\\{");
        for (int e = 0, listed_elements = 0; e < size; e++)
            if ((value[i] >> e) & 1) proof_add("%s%d", listed_elements++ ? ", " : "", e + 1);
        proof_add("\\}");
    }
    proof_add("$.");
}

/* Costruisce con configuration_sets() gli insiemi che realizzano la
 * configurazione nonempty e ne scrive la descrizione in counterexample_text.
 * bound, se non è -1, è l'indice di un insieme da non riportare. */
static void counterexample(unsigned nonempty, int bound, unsigned *value, int *size) {
    configuration_sets(nonempty, value, size);
    sets_describe(value, *size, bound < 0 ? ~0u : ~(1u << bound));
}

/* 16i. Controllo dell'insieme scelto per un "esiste" (15e): l'unione delle
 * regioni di mask, per la lettera del quantificatore exists. Per ogni scelta
 * degli altri insiemi tra i sottoinsiemi di un universo di size elementi si
 * costruisce davvero quell'insieme e si calcola la condizione del
 * quantificatore; se other non è NULL basta che valga quando vale other.
 * Ritorna 1 se regge sempre; altrimenti annota il passo come non giustificato
 * e ritorna 0. */
static int witness_confirmed(const SetNode *exists, const SetNode *other, unsigned mask, int size) {
    unsigned value[MAX_SET_VARS] = {0};
    for (;;) {
        /* Un elemento sta nell'insieme scelto se la sua regione rispetto agli
         * altri insiemi è una di quelle di mask. In quella regione gli altri
         * insiemi occupano i bit in ordine, saltando la lettera di exists. */
        value[exists->var] = 0;
        for (int e = 0; e < size; e++) {
            unsigned region = 0;
            for (int i = 0, place = 0; i < set_var_count; i++)
                if (i != exists->var) region |= ((value[i] >> e) & 1) << place++;
            if ((mask >> region) & 1) value[exists->var] |= 1u << e;
        }
        if ((!other || concrete_holds(other, value, size)) && !concrete_holds(exists->a, value, size)) {
            unjustified_steps++;
            return 0;
        }

        /* Assegnazione successiva degli altri insiemi, come in
         * concrete_valid(). */
        int i = 0;
        for (; i < set_var_count; i++) {
            if (i == exists->var) continue;
            if (++value[i] < (1u << size)) break;
            value[i] = 0;
        }
        if (i == set_var_count) return 1;
    }
}

/* Scrive l'enunciato sugli insiemi n nella notazione dei certificati
 * (capitolo 10 di checker.c): la parola davanti, e tutte le parentesi. Un
 * "esiste un insieme" non ha scrittura.
 *
 * Warning: se aggiungi un tipo di nodo, aggiungi qui la sua parola, e la
 * parola al verificatore; altrimenti l'enunciato resta senza certificato. */
static void cert_set(const SetNode *n) {
    static const char *const word[] = {
        [SET_EMPTY] = "empty", [SET_ONLY_EMPTY] = "onlyempty", [SET_POWER] = "power",
        [SET_UNION] = "union", [SET_INTER] = "inter", [SET_DIFF] = "diff", [SET_SYMDIFF] = "symdiff", [SET_PRODUCT] = "times",
        [SET_EQ] = "=", [SET_SUBSET] = "subset", [SET_NEQ] = "neq",
        [SET_AND] = "and", [SET_OR] = "or", [SET_IMPLIES] = "implies", [SET_IFF] = "iff", [SET_NOT] = "not",
    };
    if (n->kind == SET_VAR) { cert_letter(set_var_name[n->var]); return; }
    if (n->kind == SET_EXISTS) { certificate_broken = 1; return; }
    cert_add("(%s", word[n->kind]);
    if (n->a) { cert_add(" "); cert_set(n->a); }
    if (n->b) { cert_add(" "); cert_set(n->b); }
    cert_add(")");
}

/* Verifica indipendente di 15f. Ritorna 1 se root è vera per ogni scelta
 * degli insiemi liberi, quelli con il bit in free_letters, tra i
 * sottoinsiemi dei primi `inner` elementi di un universo di `size` elementi:
 * ogni espressione viene calcolata davvero, come insieme, e ogni "esiste un
 * insieme" prova tutti i sottoinsiemi di un universo che cresce di un
 * elemento a ogni quantificatore (concrete_holds()). Gli elementi oltre i
 * primi `inner` stanno fuori da ogni insieme libero: sono gli oggetti di cui
 * 15f dice che ce n'è quanti se ne vuole. */
static int concrete_valid_freely(const SetNode *root, unsigned free_letters, int inner, int size) {
    unsigned value[MAX_SET_VARS] = {0};
    for (;;) {
        if (!concrete_holds(root, value, size)) return 0;

        /* Assegnazione successiva dei soli insiemi liberi, come in
         * concrete_valid(). Gli altri li riscrive chi li quantifica. */
        int i = 0;
        for (; i < set_var_count; i++) {
            if (!((free_letters >> i) & 1)) continue;
            if (++value[i] < (1u << inner)) break;
            value[i] = 0;
        }
        if (i == set_var_count) return 1;
    }
}

/* 15f, con la sua verifica e il suo testo: decide l'enunciato root contando
 * gli elementi delle regioni, e completa verdict.
 *
 * Il conto non viene creduto sulla parola. Se dice "vero", l'enunciato deve
 * valere in tutti gli universi piccoli di concrete_valid_freely(); se dice
 * "falso", gli insiemi del controesempio vengono costruiti e l'enunciato
 * calcolato su di loro. Sono controlli parziali, perché l'universo è
 * piccolo: un enunciato vero che ha bisogno di molti oggetti fuori dagli
 * insiemi, o un controesempio con più di qualche elemento, non vengono
 * confermati, e allora il verdetto è NON DIMOSTRATO. */
static Verdict prove_sets_by_counting(const SetNode *root, Verdict verdict) {
    unsigned char count[1u << MAX_SET_VARS];
    unsigned free_letters = set_free_letters(root, 0), value[MAX_SET_VARS] = {0};
    int depth = set_depth(root);
    verdict.outcome = NOT_PROVED;

    /* Con le lettere che si possono riusare i quantificatori uno dentro
     * l'altro non hanno un limite, ma i numeri di elementi (fino a 2^q) e la
     * verifica (32^q casi) sì. */
    int valid = depth <= MAX_SET_VARS ? counts_valid(root, count) : -1;
    if (valid < 0) {
        verdict.reason = "troppi casi da esaminare, contando gli elementi delle regioni";
        return verdict;
    }

    /* Falso: gli insiemi liberi con, in ogni regione, gli elementi contati
     * ("almeno" diventa proprio quel numero), più quanti oggetti esterni
     * stanno in un universo di 5. */
    if (!valid) {
        int size = 0;
        for (unsigned region = 1; region < (1u << set_var_count); region++)
            for (int e = 0; e < count[region] && size <= 5; e++, size++)
                for (int i = 0; i < set_var_count; i++)
                    if ((region >> i) & 1) value[i] |= 1u << size;
        if (size > 5 || concrete_holds(root, value, 5)) {
            verdict.reason = "la verifica indipendente non conferma il controesempio trovato contando gli elementi delle regioni";
            return verdict;
        }
        /* Senza insiemi liberi non c'è una scelta da riportare. */
        sets_describe(value, size, free_letters);
        if (free_letters) put_counterexample(value, size, free_letters);
        else proof_add("The statement is false: no letter is left free, and counting the elements of the regions shows that it fails.");
        verdict.outcome = REFUTED;
        verdict.detail = free_letters ? counterexample_text : NULL;
        verdict.proof = proof_text;
        return verdict;
    }

    /* Vero: verifica indipendente su un universo piccolo, che per il
     * quantificatore più esterno ha cinque elementi (quattro quando i
     * quantificatori annidati sono tre o più, perché i casi crescono in
     * fretta: 32 * 64 * 128 * ...). */
    if (!concrete_valid_freely(root, free_letters, 3, depth <= 2 ? 4 : 3)) {
        verdict.reason = "la verifica indipendente ha trovato un caso in cui l'enunciato non vale";
        return verdict;
    }
    proof_add("\\textbf{Proof.} The statement has quantifiers over sets, at most $%d$ inside one another. Whether it holds for given "
              "sets depends only on the number of elements of each region of their Venn diagram, and only up to $%d$: two "
              "choices of the sets whose regions have the same numbers of elements, or both at least $%d$, cannot be told apart, "
              "because a set that works for one choice divides each region into two parts, and the corresponding region of the "
              "other choice can be divided into parts with the same numbers of elements, or both at least half of $%d$. So each "
              "region is given $0, 1, \\ldots$ or at least $%d$ elements, the part outside all the sets always at least $%d$, and for "
              "each quantified set every way of dividing the regions is tried. The statement holds in all these cases. $\\Box$",
              depth, 1 << depth, 1 << depth, 1 << depth, 1 << depth, 1 << depth);
    verdict.outcome = PROVED;
    verdict.proof = proof_text;
    return verdict;
}

/* Decide l'enunciato sugli insiemi root, già letto e con i tipi controllati
 * (set_check()), e ne ritorna il verdetto, con la dimostrazione scritta o il
 * controesempio. È la seconda metà di prove_sets(), che serve anche a
 * prove_parts() (17r). */
static Verdict prove_set_tree(SetNode *root) {
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, "per ogni scelta degli insiemi", NULL, NULL};
    set_prepare(root);
    if (failure) { verdict.reason = failure; return verdict; }

    /* Il quantificatore, se c'è: uno solo, e solo come enunciato intero o come
     * uno dei due lati di un'equivalenza o di un'implicazione. */
    const SetNode *exists = NULL, *other = NULL;
    int as_hypothesis = 0, as_thesis = 0;
    if (root->kind == SET_EXISTS) {
        exists = root;
        as_thesis = 1;
    } else if (root->kind == SET_IFF || root->kind == SET_IMPLIES) {
        if (root->a->kind == SET_EXISTS) { exists = root->a; other = root->b; as_hypothesis = 1; as_thesis = root->kind == SET_IFF; }
        else if (root->b->kind == SET_EXISTS) { exists = root->b; other = root->a; as_thesis = 1; as_hypothesis = root->kind == SET_IFF; }
    }
    int quantifiers = 0;
    for (const SetNode *stack[64], **top = stack, *n = root; n || top > stack; ) {
        if (!n) { n = *--top; continue; }
        if (n->kind == SET_EXISTS) quantifiers++;
        if (n->b && top < stack + 64) *top++ = n->b;
        n = n->a;
    }
    /* 15f. Più quantificatori, o uno in un'altra posizione: contando gli
     * elementi delle regioni. */
    if (quantifiers > (exists ? 1 : 0)) return prove_sets_by_counting(root, verdict);

    /* Decisione per regioni (capitolo 15). */
    unsigned all = (1u << (1u << set_var_count)) - 1, failing = 0, mask = 0;
    int valid, found = 1;
    if (!exists) {
        valid = set_valid(root, all, &failing);
    } else {
        /* 15d: "esiste V" come ipotesi, con V arbitrario. */
        SetNode to_other = {SET_IMPLIES, TY_FORMULA, 0, (SetNode *)exists, (SetNode *)other, NULL, 0};
        SetNode to_exists = {SET_IMPLIES, TY_FORMULA, 0, (SetNode *)other, (SetNode *)exists, NULL, 0};
        valid = !as_hypothesis || set_valid(&to_other, all, &failing);

        /* 15e: "esiste V" come tesi, cercando V tra le unioni di regioni. */
        if (valid && as_thesis) {
            unsigned ignored = 0, candidates = 1u << (1u << (set_var_count - 1));
            const SetNode *goal = other ? &to_exists : exists;
            found = 0;
            for (mask = 0; mask < candidates && !found; mask++)
                found = set_valid(goal, witness_regions(exists->var, mask), &ignored);
            mask--;
        }
    }
    /* 15f. Nessuna unione di regioni va bene: l'insieme cercato, se c'è,
     * divide una regione, e lo si trova contando. */
    if (valid && !found) return prove_sets_by_counting(root, verdict);

    /* Enunciato falso: il controesempio, ricontrollato calcolando davvero. */
    if (!valid) {
        unsigned value[MAX_SET_VARS];
        int size;
        counterexample(failing, exists ? exists->var : -1, value, &size);
        if (size > 5 || concrete_holds(root, value, size)) {
            verdict.outcome = NOT_PROVED;
            verdict.reason = "la verifica indipendente non conferma il controesempio";
            return verdict;
        }
        put_counterexample(value, size, exists ? ~(1u << exists->var) : ~0u);
        verdict.outcome = REFUTED;
        verdict.detail = counterexample_text;
        verdict.proof = proof_text;
        return verdict;
    }

    /* Enunciato vero: verifica indipendente su un universo piccolo. Con più
     * insiemi l'universo è più piccolo, perché le assegnazioni restino
     * poche migliaia. */
    int free_sets = set_var_count - (exists ? 1 : 0), universe = free_sets >= 4 ? 3 : 4;
    if (!concrete_valid(root, exists ? exists->var : -1, universe)) {
        verdict.outcome = NOT_PROVED;
        verdict.reason = "la verifica indipendente ha trovato un caso in cui l'enunciato non vale";
        return verdict;
    }

    /* Dimostrazione scritta (capitolo 16), con il controllo di ciò che
     * afferma: se nemmeno la forma generale lo supera, non c'è un testo di
     * cui fidarsi e il verdetto non viene emesso. */
    int written = 1;
    if (exists || (!put_narrative_proof(root) && !put_table_proof(root) && !put_comparison_proof(root)))
        written = (!as_thesis || witness_confirmed(exists, other, mask, universe)) &&
                  put_general_proof(root, as_thesis ? exists : NULL, mask);
    if (!written) {
        verdict.outcome = NOT_PROVED;
        verdict.reason = "la dimostrazione scritta non ha superato il controllo dei suoi passi";
        return verdict;
    }

    /* Il certificato: l'enunciato, che il verificatore indipendente decide
     * da capo con il suo conto (capitolo 10 di checker.c). Se lo trova
     * falso, i due programmi non sono d'accordo: nel dubbio non è
     * dimostrato. "Esiste un insieme" il verificatore non lo tratta. */
    certificate_length = 0;
    certificate_broken = exists != NULL;
    cert_add("certificate sets\nstatement ");
    cert_set(root);
    cert_add("\nend\n");
    if (!certificate_broken) {
        const char *text = certificate_text, *why;
        CkAnswer answer = ck_check(&text, &why);
        if (answer == CK_REJECTED) {
            unjustified_steps++;
            snprintf(certificate_problem, sizeof certificate_problem, "il verificatore indipendente ha respinto il certificato: %s", why);
            verdict.outcome = NOT_PROVED;
            verdict.reason = certificate_problem;
            return verdict;
        }
        if (answer == CK_ACCEPTED) verdict.certificate = certificate_text;
    }
    verdict.outcome = PROVED;
    verdict.proof = proof_text;
    return verdict;
}

/* Decide l'enunciato sugli insiemi scritto in formula e ne ritorna il
 * verdetto, con la dimostrazione scritta o il controesempio.
 *
 * Svuota l'arena: i risultati di chiamate precedenti non sono più validi. */
static Verdict prove_sets(const char *formula) {
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, "per ogni scelta degli insiemi", NULL, NULL};

    /* Ripartenza da zero e parsing. */
    proof_reset();
    arena_used = arena_keep;
    failure = NULL;
    set_var_count = 0;
    syntax_error = NULL;
    cursor = formula;
    next_token();
    SetNode *root = set_formula();
    if (token.kind != T_END) syntax("testo inatteso dopo l'enunciato");
    if (syntax_error) { verdict.reason = syntax_error; return verdict; }
    if (failure) { verdict.reason = failure; return verdict; }
    if (set_check(root) != TY_FORMULA) {
        verdict.reason = "enunciato sugli insiemi mal formato: operandi di tipo diverso, o manca una relazione";
        return verdict;
    }
    return prove_set_tree(root);
}

/* 17r. Il controllo dello svolgimento di un enunciato su relazioni e
 * applicazioni tra parti (vedi la testa di 17r in parser.c). written è
 * l'enunciato com'è scritto, con le sue letters lettere; unfolded quello
 * svolto, con le lettere di parts_reindex(), e free_map[] dice l'indice
 * nuovo di ogni lettera libera. Per ogni scelta delle lettere libere tra le
 * parti di un universo piccolo, i due enunciati devono avere lo stesso
 * valore: written calcolato con le regole (concrete_holds() su SET_PAIR_IN e
 * SET_APPLY), unfolded con le regole già sostituite. Ritorna quante scelte
 * ha confrontato, o -1 se in una i due valori sono diversi.
 *
 * Gli universi hanno uno, due e, se i quantificatori uno dentro l'altro
 * sono al più due, tre elementi: ogni quantificatore li fa crescere di uno
 * (concrete_holds()), e le scelte crescono in fretta. */
static long long parts_check(const SetNode *written, int letters, const SetNode *unfolded, const int *free_map) {
    unsigned book[MAX_SET_LETTERS], plain[MAX_SET_LETTERS];
    long long compared = 0;
    int frees = 0, depth = set_depth(unfolded);
    for (int i = 0; i < letters; i++) frees += free_map[i] >= 0;
    for (int size = 1; size <= (depth <= 2 ? 3 : 2); size++) {
        unsigned choices = 1u << (size * frees);
        for (unsigned code = 0; code < choices; code++) {
            /* La scelta code: le parti delle lettere libere, size bit l'una,
             * le stesse nei due enunciati. */
            memset(book, 0, sizeof book);
            memset(plain, 0, sizeof plain);
            for (int i = 0; i < letters; i++) {
                if (free_map[i] < 0) continue;
                book[i] = plain[free_map[i]] = (code >> (size * free_map[i])) & ((1u << size) - 1);
            }
            if (concrete_holds(written, book, size) != concrete_holds(unfolded, plain, size)) return -1;
            compared++;
        }
    }
    return compared;
}

/* 17r. Decide l'enunciato su relazioni e applicazioni tra le parti di un
 * insieme scritto in formula: lo legge con il lettore del capitolo 14 e le
 * scritture di 17r, lo svolge, ricontrolla lo svolgimento (parts_check()) e
 * passa l'enunciato svolto al capitolo 15. Il verdetto è quello del capitolo
 * 15, e la dimostrazione dice in più che cosa è stato svolto e come lo si è
 * ricontrollato.
 *
 * Svuota l'arena: i risultati di chiamate precedenti non sono più validi. */
static Verdict prove_parts(const char *formula) {
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, "per ogni scelta degli insiemi", NULL, NULL};
    int free_map[MAX_SET_LETTERS];

    /* Ripartenza da zero e parsing, con le scritture di 17r. */
    proof_reset();
    arena_used = arena_keep;
    failure = NULL;
    set_var_count = part_rule_count = 0;
    syntax_error = NULL;
    cursor = formula;
    next_token();
    parts_world = 1;
    SetNode *written = set_formula();
    parts_world = 0;
    if (token.kind != T_END) syntax("testo inatteso dopo l'enunciato");
    for (int i = 0; i < part_rule_count && !syntax_error; i++)
        if (!part_rules[i].rule) syntax("un'applicazione tra parti dichiarata va data con la sua regola, \\forall X \\in \\mathcal{P}(S)\\ (f(X) = ...)");
    if (syntax_error || failure) { verdict.reason = syntax_error ? syntax_error : failure; return verdict; }
    if (set_check(written) != TY_FORMULA) {
        verdict.reason = "enunciato sugli insiemi mal formato: operandi di tipo diverso, o manca una relazione";
        return verdict;
    }

    /* Lo svolgimento, le lettere nuove, e il controllo. */
    int letters = set_var_count;
    memset(parts_to, 0, sizeof parts_to);
    SetNode *root = parts_unfold(written);
    if (root == &parts_declared) { verdict.reason = "l'enunciato dichiara delle relazioni o delle applicazioni tra parti, ma non ne dice nulla"; return verdict; }
    if (parts_declaration_left(root)) {
        verdict.reason = "una relazione o un'applicazione tra parti si dichiara solo tra le ipotesi, in cima all'enunciato";
        return verdict;
    }
    parts_reindex(root, free_map);
    if (syntax_error) { verdict.reason = syntax_error; return verdict; }
    if (set_check(root) != TY_FORMULA) {
        verdict.reason = "enunciato sugli insiemi mal formato, una volta svolte le relazioni e le applicazioni tra parti";
        return verdict;
    }
    long long compared = parts_check(written, letters, root, free_map);
    if (compared < 0) {
        unjustified_steps++;
        verdict.outcome = NOT_PROVED;
        verdict.reason = "lo svolgimento delle relazioni e delle applicazioni tra parti, ricalcolato su universi piccoli, non dà lo stesso enunciato";
        return verdict;
    }

    /* La decisione del capitolo 15, e nella dimostrazione ciò che è stato
     * svolto. */
    verdict = prove_set_tree(root);
    if (verdict.outcome == PROVED || verdict.outcome == REFUTED)
        proof_add(" The relations and maps between parts of a set are read as their rules, with the arguments in place of the "
                  "letters of each rule, and (A, B) in a relation as A and B parts of its set that satisfy the rule; the statement "
                  "decided above is the result. The statement as written and that one take the same value for each of the %lld "
                  "choices of the free sets tried in universes of one, two and three elements.", compared);
    return verdict;
}

/* =============================================================================
 * 24. INTERVALLI: NUMERI REALI CON L'ERRORE GARANTITO
 * ============================================================================
 *
 * Quasi tutto il programma fa conti esatti. Ma un numero come log_2 3, la
 * radice quadrata di e, o pi greco diviso 6 non si scrive con una frazione,
 * e per sapere quale di due numeri così viene prima sulla retta non c'è un
 * conto esatto da fare. Qui un numero reale è rappresentato da un
 * intervallo [low, high] che lo contiene di sicuro: se due intervalli non si
 * toccano, l'ordine dei due numeri è certo; se si toccano, la risposta è
 * "non so", mai una risposta sbagliata.
 *
 * Da dove viene la garanzia. I double seguono lo standard IEEE 754: ognuna
 * delle quattro operazioni dà il double più vicino al risultato vero, cioè
 * sbaglia al più di mezza unità sull'ultima cifra. Dopo ogni operazione
 * l'intervallo viene allargato, da tutte e due le parti, di RANGE_EPS volte
 * il suo valore: più dell'errore possibile. Le funzioni (logaritmo,
 * esponenziale, arcotangente, seno, coseno) sono serie di potenze sommate
 * con le stesse operazioni, più un termine che maggiora il resto della
 * serie. math.h non serve, e non si usa.
 *
 * Che cosa non si può fare con gli intervalli: stabilire che due numeri sono
 * uguali. Uno zero esatto va riconosciuto prima, con i conti esatti; qui si
 * arriva solo per confermare che un numero non è zero, e da che parte sta.
 *
 * Un Range con low > high vuol dire "non so" (range_none()): lo danno una
 * divisione per un intervallo che contiene lo zero, un logaritmo di un
 * intervallo che tocca i numeri non positivi, un numero troppo grande. Ogni
 * operazione su un "non so" dà "non so".
 */

/* Un numero reale noto a meno di un errore: sta tra low e high, compresi.
 * Invariante: low <= high, tutti e due finiti; altrimenti vuol dire "non
 * so". */
typedef struct {
    double low, high;
} Range;

#define RANGE_EPS (4 * DBL_EPSILON)  /* allargamento relativo dopo ogni operazione */

/* Ritorna il "non so". */
static Range range_none(void) { return (Range){1, -1}; }

/* Ritorna 1 se r è un intervallo vero, 0 se è un "non so". Un estremo
 * infinito o non numerico, sottratto a se stesso, non dà zero. */
static int range_known(Range r) { return r.low <= r.high && r.low - r.low == 0 && r.high - r.high == 0; }

/* Ritorna l'intervallo [low, high] allargato quanto basta a coprire
 * l'errore dell'operazione che ha prodotto i due estremi. DBL_MIN copre i
 * numeri così piccoli che l'allargamento relativo sparirebbe. */
static Range range_wide(double low, double high) {
    double a = low < 0 ? -low : low, b = high < 0 ? -high : high;
    Range r = {low - a * RANGE_EPS - DBL_MIN, high + b * RANGE_EPS + DBL_MIN};
    return range_known(r) ? r : range_none();
}

/* Ritorna un intervallo che contiene num / den, con den diverso da zero. Le
 * due conversioni in double e la divisione sbagliano ognuna di mezza unità:
 * l'allargamento le copre. */
static Range range_ratio(__int128 num, __int128 den) {
    double q = (double)num / (double)den;
    return range_wide(q, q);
}

/* Ritorna -a: cambiare segno è esatto. */
static Range range_neg(Range a) { return range_known(a) ? (Range){-a.high, -a.low} : range_none(); }

/* Ritorna a + b. */
static Range range_add(Range a, Range b) {
    if (!range_known(a) || !range_known(b)) return range_none();
    return range_wide(a.low + b.low, a.high + b.high);
}

/* Ritorna a * b: il più piccolo e il più grande dei quattro prodotti degli
 * estremi. */
static Range range_mul(Range a, Range b) {
    if (!range_known(a) || !range_known(b)) return range_none();
    double p[4] = {a.low * b.low, a.low * b.high, a.high * b.low, a.high * b.high}, low = p[0], high = p[0];
    for (int i = 1; i < 4; i++) {
        if (p[i] < low) low = p[i];
        if (p[i] > high) high = p[i];
    }
    return range_wide(low, high);
}

/* Ritorna 1 / a; "non so" se a contiene lo zero. */
static Range range_inv(Range a) {
    if (!range_known(a) || (a.low <= 0 && a.high >= 0)) return range_none();
    return range_wide(1 / a.high, 1 / a.low);
}

/* Ritorna a - b e a / b. */
static Range range_sub(Range a, Range b) { return range_add(a, range_neg(b)); }
static Range range_div(Range a, Range b) { return range_mul(a, range_inv(b)); }

/* Ritorna a allargato di margin da tutte e due le parti: per il resto di
 * una serie troncata. */
static Range range_pad(Range a, double margin) {
    return range_known(a) ? range_wide(a.low - margin, a.high + margin) : range_none();
}

/* Ritorna la somma dei primi `terms` termini della serie
 *
 *     y + s y^3 / 3 + s^2 y^5 / 5 + ...        con s = sign (1 oppure -1),
 *
 * che per s = 1 è la tangente iperbolica inversa di y e per s = -1 è
 * l'arcotangente, più il resto. Vale per |y| <= 1/2: il resto dopo n
 * termini è minore di |y|^(2n+1), che con 60 termini è sotto 10^-36. */
static Range range_odd_series(Range y, int sign) {
    Range square = range_mul(y, y), power = y, sum = y;
    for (int j = 1; j < 60; j++) {
        power = range_mul(power, square);
        Range term = range_div(power, range_ratio(2 * j + 1, 1));
        sum = (sign > 0 || j % 2 == 0) ? range_add(sum, term) : range_sub(sum, term);
    }
    return range_pad(sum, 1e-30);
}

/* Ritorna il logaritmo naturale di 2: è 2 atanh(1/3), perché
 * atanh(y) = ln((1 + y) / (1 - y)) / 2. */
static Range range_ln2(void) {
    return range_mul(range_ratio(2, 1), range_odd_series(range_ratio(1, 3), 1));
}

/* Ritorna il logaritmo naturale del double v, che è positivo.
 *
 * Si scrive v = m 2^k con m tra radice di 1/2 e radice di 2: dividere e
 * moltiplicare per 2 un double è esatto. Poi ln v = k ln 2 + ln m, e
 * ln m = 2 atanh((m - 1) / (m + 1)), con un argomento minore di 0,18 in
 * valore assoluto, dove la serie converge in fretta. */
static Range range_ln_at(double v) {
    int k = 0;
    if (!(v > 0) || v - v != 0) return range_none();
    for (; v > 1.4142135623730951; k++) v /= 2;
    for (; v < 0.7071067811865476; k--) v *= 2;
    Range m = {v, v}, one = {1, 1};
    Range inner = range_mul(range_ratio(2, 1), range_odd_series(range_div(range_sub(m, one), range_add(m, one)), 1));
    return range_add(inner, range_mul(range_ratio(k, 1), range_ln2()));
}

/* Ritorna il logaritmo naturale di a, "non so" se a non è tutto positivo. Il
 * logaritmo cresce: bastano i due estremi. */
static Range range_ln(Range a) {
    if (!range_known(a) || !(a.low > 0)) return range_none();
    Range low = range_ln_at(a.low), high = range_ln_at(a.high);
    return range_known(low) && range_known(high) ? (Range){low.low, high.high} : range_none();
}

/* Ritorna e elevato al double v.
 *
 * Si scrive v = k ln 2 + r con r piccolo: allora e^v = 2^k e^r, ed e^r è la
 * somma di r^j / j!. Con |r| < 1/2 il resto dopo 30 termini è sotto 10^-40.
 * Moltiplicare per 2^k è esatto finché il numero resta nei double. */
static Range range_exp_at(double v) {
    if (v - v != 0 || v > 700 || v < -700) return range_none();
    long long k = (long long)(v / 0.6931471805599453 + (v < 0 ? -0.5 : 0.5));
    Range r = range_sub((Range){v, v}, range_mul(range_ratio(k, 1), range_ln2())), term = {1, 1}, sum = {1, 1};
    for (int j = 1; j <= 30; j++) {
        term = range_div(range_mul(term, r), range_ratio(j, 1));
        sum = range_add(sum, term);
    }
    sum = range_pad(sum, 1e-30);
    for (long long i = 0; i < (k < 0 ? -k : k) && range_known(sum); i++) sum = range_wide(k < 0 ? sum.low / 2 : sum.low * 2, k < 0 ? sum.high / 2 : sum.high * 2);
    return sum;
}

/* Ritorna e elevato ad a. L'esponenziale cresce: bastano i due estremi. */
static Range range_exp(Range a) {
    if (!range_known(a)) return range_none();
    Range low = range_exp_at(a.low), high = range_exp_at(a.high);
    return range_known(low) && range_known(high) ? (Range){low.low, high.high} : range_none();
}

/* Ritorna la radice quadrata di a, "non so" se a tocca i negativi.
 *
 * Il metodo di Newton dà un double vicino alla radice, ma non dice quanto;
 * lo si allarga e poi si controlla, elevando al quadrato con gli intervalli,
 * che i due estremi stiano davvero uno sotto e uno sopra. */
static Range range_sqrt(Range a) {
    if (!range_known(a) || a.low < 0) return range_none();
    double bound[2];
    for (int side = 0; side < 2; side++) {
        double v = side ? a.high : a.low, s = v > 1 ? v : 1;
        if (v == 0) { bound[side] = 0; continue; }
        for (int step = 0; step < 200; step++) s = (s + v / s) / 2;
        Range near = range_wide(s * (1 - 16 * DBL_EPSILON), s * (1 + 16 * DBL_EPSILON));
        Range under = range_mul((Range){near.low, near.low}, (Range){near.low, near.low}), over = range_mul((Range){near.high, near.high}, (Range){near.high, near.high});
        if (!range_known(under) || !range_known(over) || under.high > v || over.low < v) return range_none();
        bound[side] = side ? near.high : near.low;
    }
    return (Range){bound[0], bound[1]};
}

/* Ritorna l'arcotangente di a.
 *
 * La serie dell'arcotangente converge bene solo vicino allo zero. Ci si
 * arriva con la formula di bisezione dell'angolo, atan(t) = 2 atan(u) con
 * u = t / (1 + sqrt(1 + t^2)), ripetuta finché |u| <= 1/2: ogni volta
 * l'angolo si dimezza, e bastano tre giri anche per un t enorme. */
static Range range_atan(Range a) {
    Range one = {1, 1};
    int doublings = 0;
    for (; range_known(a) && (a.low < -0.5 || a.high > 0.5) && doublings < 8; doublings++)
        a = range_div(a, range_add(one, range_sqrt(range_add(one, range_mul(a, a)))));
    if (!range_known(a) || a.low < -0.5 || a.high > 0.5) return range_none();
    a = range_odd_series(a, -1);
    for (int i = 0; i < doublings; i++) a = range_add(a, a);
    return a;
}

/* Ritorna pi greco, con la formula di Machin:
 * pi = 16 atan(1/5) - 4 atan(1/239). */
static Range range_pi(void) {
    return range_sub(range_mul(range_ratio(16, 1), range_odd_series(range_ratio(1, 5), -1)), range_mul(range_ratio(4, 1), range_odd_series(range_ratio(1, 239), -1)));
}

/* Ritorna arcsin a; "non so" se a non sta tutto in [-1, 1].
 *
 * L'arcoseno è crescente, quindi l'intervallo va dall'arcoseno di un
 * estremo a quello dell'altro. In un estremo t con |t| < 1 l'angolo y =
 * arcsin t, tra -pi/2 e pi/2, ha sin y = t e cos y = sqrt(1 - t^2) > 0,
 * quindi tan y = t / sqrt(1 - t^2) e y è l'arcotangente di quel numero; in
 * t = 1 e t = -1 vale pi/2 e -pi/2. Ogni passo è un'operazione con gli
 * intervalli, che contiene il risultato vero: la scelta tra i due casi
 * guarda se l'estremo è proprio il numero 1, non decide nulla
 * dell'enunciato. */
static Range range_asin(Range a) {
    Range ends[2], one = {1, 1}, half_pi = range_div(range_pi(), range_ratio(2, 1));
    if (!range_known(a) || a.low < -1 || a.high > 1) return range_none();
    for (int side = 0; side < 2; side++) {
        Range t = side ? (Range){a.high, a.high} : (Range){a.low, a.low};
        if (t.low == 1 || t.low == -1) ends[side] = t.low > 0 ? half_pi : range_neg(half_pi);
        else ends[side] = range_atan(range_div(t, range_sqrt(range_sub(one, range_mul(t, t)))));
        if (!range_known(ends[side])) return range_none();
    }
    return (Range){ends[0].low, ends[1].high};
}

/* Ritorna pi/2 - b: arccos a = pi/2 - arcsin a, arccot a = pi/2 - arctan a
 * (con l'arcocotangente in (0, pi)). */
static Range range_from_half_pi(Range b) { return range_sub(range_div(range_pi(), range_ratio(2, 1)), b); }

/* Mette in *sine e *cosine il seno e il coseno di a.
 *
 * Prima si toglie ad a il multiplo di 2 pi più vicino, che non cambia né
 * l'uno né l'altro; resta un angolo tra -4 e 4, e lì le serie
 *
 *     sin r = r - r^3/3! + r^5/5! - ...      cos r = 1 - r^2/2! + r^4/4! - ...
 *
 * sommate fino al grado 60 hanno un resto sotto 10^-45 (4^61 / 61!). */
static void range_sin_cos(Range a, Range *sine, Range *cosine) {
    *sine = *cosine = range_none();
    if (!range_known(a) || a.low < -1e9 || a.high > 1e9) return;
    Range turn = range_mul(range_ratio(2, 1), range_pi());
    double middle = (a.low + a.high) / 2 / 6.283185307179586;
    Range r = range_sub(a, range_mul(range_ratio((long long)(middle + (middle < 0 ? -0.5 : 0.5)), 1), turn));
    if (!range_known(r) || r.low < -4 || r.high > 4) return;
    Range term = {1, 1}, even = {1, 1}, odd = {0, 0};
    for (int j = 1; j <= 60; j++) {
        /* term è r^j / j!; i gradi dispari vanno al seno, i pari al coseno,
         * con i segni alterni: + per j = 1, 4, 5, 8, 9, ... */
        term = range_div(range_mul(term, r), range_ratio(j, 1));
        Range signed_term = (j % 4 == 2 || j % 4 == 3) ? range_neg(term) : term;
        if (j % 2) odd = range_add(odd, signed_term); else even = range_add(even, signed_term);
    }
    *sine = range_pad(odd, 1e-30);
    *cosine = range_pad(even, 1e-30);
}

/* Se il segno di r è certo lo mette in *side (1 o -1) e ritorna 1; ritorna
 * 0 se r contiene lo zero o è un "non so". */
static int range_side(Range r, int *side) {
    if (!range_known(r) || (r.low <= 0 && r.high >= 0)) return 0;
    *side = r.low > 0 ? 1 : -1;
    return 1;
}

/* Ritorna a elevato all'intero e, con moltiplicazioni ripetute. */
static Range range_power(Range a, long long e) {
    Range result = {1, 1};
    for (long long i = 0; i < (e < 0 ? -e : e) && range_known(result); i++) result = range_mul(result, a);
    return e < 0 ? range_inv(result) : result;
}

/* Ritorna un intervallo che contiene il valore dell'espressione node quando
 * la variabile name sta in x; "non so" se non riesce a calcolarlo. Mette 1
 * in *undefined, che chi chiama ha messo a 0, quando è certo che lì
 * l'espressione non ha un valore: la radice o il logaritmo di un numero
 * sicuramente negativo. La lettera e, quando non è la variabile, è il numero
 * di Nepero.
 *
 * Serve in due posti: a ricontrollare con i numeri una riga della tabella
 * dei segni, dove conta il segno certo di una differenza, e a tracciare le
 * curve di un grafico, dove basta il punto medio. Somme, prodotti estesi e
 * applicazioni dichiarate non li calcola. */
static Range node_range(const Node *node, int name, Range x, int *undefined) {
    Range a, b, sine, cosine;
    switch (node->kind) {
    case N_NUM: return range_ratio(node->value, 1);
    case N_VAR:
        if (node->name == name) return x;
        if (node->name == VAR_PI) return range_pi();
        return node->name == 'e' ? range_exp_at(1) : range_none();
    case N_NEG: return range_neg(node_range(node->a, name, x, undefined));
    case N_ADD: return range_add(node_range(node->a, name, x, undefined), node_range(node->b, name, x, undefined));
    case N_SUB: return range_sub(node_range(node->a, name, x, undefined), node_range(node->b, name, x, undefined));
    case N_MUL: return range_mul(node_range(node->a, name, x, undefined), node_range(node->b, name, x, undefined));
    case N_DIV: return range_div(node_range(node->a, name, x, undefined), node_range(node->b, name, x, undefined));
    case N_POW: {
        /* Un esponente intero scritto come numero: moltiplicazioni. Ogni
         * altro esponente chiede una base positiva: a^b = e^(b ln a). */
        const Node *exponent = node->b->kind == N_NEG ? node->b->a : node->b;
        a = node_range(node->a, name, x, undefined);
        if (exponent->kind == N_NUM && exponent->value <= MAX_UNI) return range_power(a, node->b->kind == N_NEG ? -exponent->value : exponent->value);
        if (range_known(a) && a.high < 0) *undefined = 1;
        return range_exp(range_mul(node_range(node->b, name, x, undefined), range_ln(a)));
    }
    case N_CALL:
        a = node_range(node->a, name, x, undefined);
        if (!range_known(a)) return a;
        switch (node->op) {
        case FN_ABS:
            if (a.low >= 0 || a.high <= 0) return a.low >= 0 ? a : range_neg(a);
            return (Range){0, -a.low > a.high ? -a.low : a.high};
        case FN_ROOT:
            /* La radice quadrata; le altre, per un radicando positivo, come
             * potenze con esponente 1/n; quelle di indice dispari di un
             * radicando negativo come -(-a)^{1/n} (11o). */
            if (node->b->kind != N_NUM || node->b->value < 2) return range_none();
            if (a.high < 0 && node->b->value % 2 == 0) *undefined = 1;
            if (node->b->value == 2) return range_sqrt(a);
            if (a.high < 0 && node->b->value % 2) return range_neg(range_exp(range_div(range_ln(range_neg(a)), range_ratio(node->b->value, 1))));
            return range_exp(range_div(range_ln(a), range_ratio(node->b->value, 1)));
        case FN_LN:
        case FN_LOG:
            if (a.high <= 0) *undefined = 1;
            a = range_ln(a);
            if (node->op == FN_LN) return a;
            if (!node->b) return range_none();
            b = node_range(node->b, name, x, undefined);
            return range_div(a, range_ln(b));
        case FN_SIN: case FN_COS: case FN_TAN: case FN_COT:
            range_sin_cos(a, &sine, &cosine);
            if (node->op == FN_SIN || node->op == FN_COS) return node->op == FN_SIN ? sine : cosine;
            return node->op == FN_TAN ? range_div(sine, cosine) : range_div(cosine, sine);
        case FN_ARCTAN: return range_atan(a);
        case FN_ARCCOT: return range_from_half_pi(range_atan(a));
        case FN_ARCSIN: case FN_ARCCOS:
            /* Fuori da [-1, 1] l'argomento non ha arcoseno. */
            if (a.low > 1 || a.high < -1) *undefined = 1;
            return node->op == FN_ARCSIN ? range_asin(a) : range_from_half_pi(range_asin(a));
        default: return range_none();
        }
    default:
        return range_none();
    }
}

/* Ritorna un intervallo che contiene il numero p, un polinomio negli atomi
 * che sono numeri: un primo elevato a un razionale, il logaritmo di un
 * primo, i numeri e e pi. "Non so" se p contiene altro. */
static Range poly_range(Poly p) {
    Range sum = {0, 0};
    for (int t = 0; t < p.count; t++) {
        const Term *term = &p.term[t];
        if (term->coef.im.num != 0) return range_none();
        Range product = range_ratio(term->coef.re.num, term->coef.re.den);
        for (int f = 0; f < term->mono.count; f++) {
            const Atom *atom = &atoms[term->mono.factor[f].atom];
            Frac e = term->mono.factor[f].exp;
            Range base;
            if (atom->kind == ATOM_VAR && atom->id == 'e') base = range_exp_at(1);
            else if (atom->kind == ATOM_VAR && atom->id == VAR_PI) base = range_pi();
            else if (atom->base != BASE_PRIME || atom->exponent.count != 0) return range_none();
            else if (atom->kind == ATOM_POW) base = range_ratio(atom->id, 1);
            else if (atom->kind == ATOM_LN) base = range_ln(range_ratio(atom->id, 1));
            else return range_none();

            /* base^e: con e intero sono moltiplicazioni, altrimenti
             * e^(e ln base), per una base positiva. */
            product = range_mul(product, e.den == 1 ? range_power(base, e.num) : range_exp(range_mul(range_ratio(e.num, e.den), range_ln(base))));
        }
        sum = range_add(sum, product);
    }
    return sum;
}

/* =============================================================================
 * 18. QUANTIFICATORI: REGOLE DI DIMOSTRAZIONE
 * ============================================================================
 *
 * establish() dimostra una condizione seguendone la struttura. Ogni caso è una
 * regola di deduzione, e ogni regola scrive nella dimostrazione la frase che
 * la giustifica: il testo finale è la traccia di ciò che il programma ha
 * fatto, non un riassunto scritto dopo.
 *
 * Lo stato di una dimostrazione in corso è fatto di due elenchi di variabili.
 *
 *   - Le variabili "generiche", in universal[]: quelle introdotte con "sia x
 *     un elemento di A" per dimostrare un "per ogni". Nell'algebra restano
 *     lettere, cioè atomi, e ciò che si dimostra deve valere per ogni loro
 *     valore nell'insieme.
 *   - Le variabili a cui è stato dato un valore, nell'ambiente di eval()
 *     (capitolo 11): quelle di un "esiste", legate al numero o
 *     all'espressione scelti.
 *
 * Un confronto tra due espressioni diventa così una frazione di polinomi
 * nelle sole variabili generiche, e tutto si riduce a tre domande su un
 * polinomio: è il polinomio nullo? Si annulla da qualche parte, negli insiemi
 * dati? Che segno ha? Le regole sono queste:
 *
 *   18a. Una costante non nulla non si annulla.
 *   18b. Un polinomio in una variabile si annulla solo nelle sue radici, e
 *        quelle razionali si trovano tutte.
 *   18c. Regola dei segni: su una semiretta, un polinomio senza coefficienti
 *        negativi non è negativo.
 *   18d. Un polinomio di grado d che è intero in d + 1 interi consecutivi è
 *        intero in tutti gli interi.
 *   18e. Appartenenza a un insieme numerico: intero, non sotto l'estremo
 *        inferiore, diverso dai punti tolti. Serve alle altre regole, per
 *        il valore scelto per un "esiste", ed è una regola a sé quando
 *        l'enunciato scrive x \in A come condizione (17k).
 *   18f. Ogni divisione scritta ha il divisore diverso da zero.
 *   18g. Un confronto tra numeri, o tra espressioni identiche, si decide
 *        calcolando.
 *   18h. Fattore comune: se p = e q e q non si annulla, p = 0 implica e = 0.
 *   18i. "Esiste x" con un'equazione in x: di primo grado la si risolve; di
 *        grado più alto, con coefficienti numerici, si provano le sue radici
 *        razionali. Se la condizione è una disgiunzione si prova l'equazione
 *        di ciascuna parte: "esiste x con A o B" vale se esiste x con A.
 *   18j. "Esiste x" negli altri casi: si provano i numeri più semplici.
 *   18k. "Per ogni x": si introduce una variabile generica.
 *   18l. Connettivi: una congiunzione chiede tutte le parti, a una
 *        disgiunzione ne basta una.
 *   18m. La regola di un'applicazione la definisce davvero: il valore esiste
 *        e sta nel codominio.
 *   18n. "Per ogni n" in un insieme di interi da un certo punto in su, di
 *        un'uguaglianza: per induzione, con il metodo del capitolo 13.
 *   18o. "Per ogni x" intero: per casi sul resto di x in una divisione.
 *   18p. Una variabile sola, reale o razionale, con relazioni d'ordine: la
 *        tabella dei segni. È una regola a parte: decide da sola, vero o
 *        falso, gli enunciati della sua forma, e trova gli insiemi di
 *        soluzioni; le altre regole non li vedono.
 *   18q. Il grafico di ciò che la tabella dei segni ha deciso.
 *   18s. Più ipotesi insieme: la tesi è una combinazione delle ipotesi, con
 *        dei polinomi per moltiplicatori. È il seguito di 18h, che tratta il
 *        caso di un'ipotesi sola di cui la tesi è un fattore.
 *   18r. Un enunciato fatto solo di congruenze tra interi, con moduli che
 *        sono numeri: si provano tutti i resti. Come la tabella dei segni
 *        decide da sola, vero o falso, e trova gli insiemi di soluzioni.
 *   18t. Due variabili reali, un parametro e una variabile: la retta del
 *        parametro si divide in casi, e in ognuno decide la tabella dei
 *        segni. Anche questa è una regola a parte, e risolve: i valori del
 *        parametro, o le soluzioni per ogni valore del parametro.
 *   18u. Le ipotesi "esiste k", con il loro testimone: una disgiunzione
 *        guardata tutta insieme. Ciò che un'ipotesi dice esistere riceve un
 *        nome, appartenenze e divisibilità si svolgono nella loro
 *        definizione, e il valore di un "esiste" della tesi si cerca tra i
 *        polinomi nelle variabili generiche, con il sistema lineare di 18s.
 *        È il seguito di 18i.
 *   18v. Le applicazioni definite per casi (17s): il caso di f(t) si
 *        dimostra prima di usarlo; quando non si sa, una variabile si divide
 *        nei casi che servono (un resto, un lato di un numero, un punto,
 *        l'essere un intero o un multiplo), e il valore di un "esiste" si
 *        cerca caso per caso. Le stesse distinzioni servono a ogni "esiste"
 *        il cui valore sta nell'insieme solo da un lato di un numero. Prima
 *        di tutto si dimostra che i casi definiscono un'applicazione. E una
 *        disgiunzione di "diversi" vale quando le loro condizioni non
 *        possono mancare insieme: 1 è una combinazione dei polinomi
 *        (18v-7, il seguito di 18s), come per le coppie (x + 1, 2x) \neq
 *        (0, 0). Tra gli interi c + k M non si annulla se le variabili di M
 *        non possono dividere -c/k (18v-10, accanto a 18w e alla regola dei
 *        segni di 18z: vedi divisor_excludes()). Il valore di un "esiste"
 *        che è un parametro più un numero, y = b + 1, lo trovano i testimoni
 *        di primo grado di 18z, che contano anche le lettere scritte nella
 *        regola di un'applicazione (la regola 18v-9 di prima). Tra i reali
 *        le applicazioni si svolgono nella definizione e decide la tabella
 *        dei segni (18v-8), dando dei razionali agli "esiste" in testa a ciò
 *        che resta quando le lettere sono troppe (18v-11): queste due stanno
 *        nel capitolo 19, perché decidono da capo gli enunciati svolti.
 *   18w. Una variabile intera che deve dividere un numero diverso da zero:
 *        i valori che contano sono i divisori di quel numero, finiti, e si
 *        provano tutti. Un "per ogni" diventa un caso per divisore, un
 *        "esiste" cerca tra i divisori.
 *   18x. Le potenze come lettere: 2^{n}, con n una variabile generica
 *        intera, è un numero razionale positivo, e nelle identità tra
 *        polinomi fa da lettera; il valore di un "esiste" che compare solo
 *        negli esponenti si cerca tra le combinazioni degli esponenti delle
 *        ipotesi (a = 2^{n} b, b = 2^{k} c danno a = 2^{n + k} c).
 *   18y. Le variabili reali senza relazioni d'ordine: le regole precedenti
 *        valgono anche per loro, tranne ciò che presuppone variabili
 *        razionali (le radici di 18b oltre il primo grado, "è un numero
 *        razionale" in 18e); un valore positivo che sta in \mathbb{Q} ha il
 *        nome in \mathbb{Q}^{+}, e il valore di un "esiste" si cerca anche
 *        diviso per una variabile che non è zero, come 1/q. Più in generale
 *        il nome di un'ipotesi "esiste" che ne fissa un valore positivo
 *        varia nella parte positiva del suo insieme: da y = a x, con x e y
 *        naturali, a è naturale.
 *   18z. Tre regole per i ragionamenti tra interi: un'ipotesi che dà il
 *        valore di una variabile si sostituisce nel resto (da y = a x e x =
 *        b y segue x (1 - a b) = 0, e con a, b naturali a = b = 1); un
 *        polinomio con un fattore monomio che non si annulla è zero solo
 *        dove lo è l'altro fattore (m (1 - 2a) con m naturale); un "esiste"
 *        prova anche le espressioni di primo grado più semplici nelle
 *        variabili generiche (x = 2m, y = b + 1).
 *
 * I capitoli che seguono, numerati da 18.1 a 18.19, raccolgono queste regole
 * per argomento, nell'ordine in cui un lettore ne ha bisogno: ognuno usa solo
 * ciò che sta nei capitoli prima di lui. Le etichette delle regole restano
 * quelle dell'elenco qui sopra, perché le citano commenti, test e README.
 *
 *   18.1   Lo stato della dimostrazione e la scrittura dei polinomi    18x
 *   18.2   Polinomi nelle variabili generiche              18a-18f, 18v-4, 18v-5,
 *                                                          18v-10, 18y, 18z
 *   18.3   Confronti e disgiunzioni di confronti           18g, 18h, 18s, 18v-7,
 *                                                          18z
 *   18.4   "Per ogni" ed "esiste": induzione, resti,       18n, 18o, 18v,
 *          casi di una definizione, equazioni              18i
 *   18.5   Le ipotesi "esiste", con il loro testimone      18u, 18x, 18y
 *   18.6   establish(): la dimostrazione per struttura     18e, 18j, 18k, 18l,
 *                                                          18m, 18v-6, 18w, 18z
 *   18.7   Sole congruenze: tutti i resti                  18r
 *   18.8   La tabella dei segni: numeri e polinomi         18p-1 ... 18p-6
 *          esatti, i punti
 *   18.9   Le lettere della tabella: esponenziali,         18p-8, 18p-11,
 *          logaritmi, funzioni goniometriche, famiglie     18p-13
 *   18.10  L'albero dei segni                              18p-7, 18p-9, 18p-10
 *   18.11  I confronti preparati, e la loro verità         18p-14, 18p-8, 18p-13
 *          in una riga
 *   18.12  Il controllo con i numeri                       18p-2
 *   18.13  Le righe della tabella e le soluzioni           18p-2
 *   18.14  Le soluzioni di una condizione periodica        18p-12, 18p-14
 *   18.15  Il grafico                                      18q
 *   18.16  Il verdetto della tabella e il certificato      18p, 18p-15
 *   18.17  Un parametro: la proiezione e le celle          18t-a, 18t-b
 *   18.18  Un parametro: le celle decise e scritte         18t-c, 18t-d, 18t-e
 *   18.19  Un parametro: i controlli e il verdetto         18t-f, 18t-g, 18t-h
 *
 * Il verdetto di un enunciato con quantificatori, e la verifica indipendente
 * di ciò che queste regole hanno dimostrato, sono nel capitolo 19.
 *
 * Le espressioni possono contenere anche somme, potenze e funzioni, come
 * nel capitolo 9. Le regole da 18a a 18h lavorano sui polinomi, e davanti a
 * un'espressione che non lo è semplicemente non si applicano: restano
 * l'induzione (18n) e, quando le variabili hanno un valore, il calcolo.
 *
 * Ogni regola è un'implicazione vera, quindi un "sì" è una dimostrazione. Non
 * sono complete: quando nessuna si applica la risposta è "no", e il verdetto
 * sarà NON DIMOSTRATO.
 *
 * Controllo dei passi. Prima di scrivere un fatto ricavato con un conto, la
 * regola lo ricontrolla per un'altra strada: una scomposizione rimoltiplicando
 * i fattori, una sostituzione tornando indietro, un elenco di radici
 * sostituendole una per una e cercandone di dimenticate tra i primi elementi
 * dell'insieme, una copertura con semirette guardando dove cadono quegli
 * elementi. Se il controllo fallisce la regola non si applica, e il contatore
 * unjustified_steps (capitolo 13) lo registra: così ciò che il testo afferma
 * non dipende da un solo calcolo.
 *
 * La negazione non ha regole sue. Dimostrare "non A" è stabilire A con il
 * segno rovesciato: i due quantificatori si scambiano (non per ogni x vale P
 * equivale a esiste x per cui non vale P), e così congiunzione e
 * disgiunzione. Per questo le funzioni prendono, oltre alla condizione, il
 * parametro `negated`.
 */

/* =============================================================================
 * 18.1 LO STATO DELLA DIMOSTRAZIONE E LA SCRITTURA DEI POLINOMI
 * ============================================================================
 *
 * Ciò che tutte le regole condividono. Lo stato della prova in corso: le
 * variabili generiche, i valori scelti per gli "esiste" (in chosen[], per
 * il controesempio, e nei loro nodi, per la verifica: witness_keep()), i
 * tentativi che restano, e il punto (Mark) a cui tornare quando un tentativo
 * fallisce, cancellando il testo e le scelte fatte dopo. Poi il modo di
 * scrivere nella dimostrazione un polinomio nelle variabili dell'enunciato,
 * e di ottenerlo da una frazione negli atomi (rat_polynomials()): le regole
 * che seguono lavorano tutte su polinomi così.
 */

/* Le variabili generiche della dimostrazione in corso, dalla più esterna. */
static Bound *universal;
static size_t universal_capacity;
static int universal_count;

/* Una cella per variabile, invece di una maschera a 32 bit: 1 se e stata
 * nominata da un'ipotesi esistenziale. Il vettore segue quello dei legami. */
static unsigned char *universal_named;
static size_t universal_named_capacity;

/* Introduce una variabile generica, azzerandone la qualifica di testimone.
 * 0 e failure quando uno dei depositi non puo crescere. Gli insiemi restano
 * posseduti dagli alberi, quindi il loro indirizzo non cambia con realloc. */
static int universal_push(Bound bound) {
    size_t need = (size_t)universal_count + 1;
    if (!work_reserve((void **)&universal, &universal_capacity, need, sizeof *universal) ||
        !work_reserve((void **)&universal_named, &universal_named_capacity, need, sizeof *universal_named)) return 0;
    universal_named[universal_count] = 0;
    universal[universal_count++] = bound;
    return 1;
}

/* La dimostrazione per casi sul resto in corso (regola 18o): il modulo m, o 0
 * se non ce n'è una, e il resto r del caso che si sta trattando. split_case
 * dice anche quale dei valori di un "esiste" si sta scegliendo, o
 * ricontrollando (vedi Formula): fuori dai casi vale 0. */
static int split_modulus, split_case;

/* Quante volte establish() può ancora essere chiamata per la prova in corso.
 * Provare un valore dopo l'altro per più "esiste" annidati, o le due letture
 * di una lunga catena di equivalenze, fa crescere i tentativi in modo
 * esponenziale: finiti i passi la ricerca si ferma e il verdetto è NON
 * DIMOSTRATO, invece di esaurire tempo e memoria. */
static int search_left;

/* Mette da parte i tentativi rimasti oltre MAX_SEARCH / 10 e ritorna quanti
 * sono; chi chiama li restituisce, con search_left += ..., quando ha finito.
 * Serve alle regole che provano molte strade (i moduli di 18o, i testimoni
 * di 18u): i loro tentativi si contano a parte, e quando non portano a nulla
 * non consumano la ricerca di chi sta intorno.
 *
 * Perché un decimo. Era un ventesimo, mille passi: la transitività di una
 * relazione tra numeri complessi (17t-4) dà un nome a quattro testimoni e ne
 * cerca altri due, tutto dentro 18u, e la sua dimostrazione chiede quasi
 * duemila passi. */
static int search_set_aside(void) {
    int outside = search_left > MAX_SEARCH / 10 ? search_left - MAX_SEARCH / 10 : 0;
    search_left -= outside;
    return outside;
}

/* Ritorna la posizione in universal[] della variabile il cui atomo è atom, o
 * -1 se atom non è una variabile generica. */
static int universal_index(int atom) {
    for (int i = 0; i < universal_count; i++)
        if (atom_var(universal[i].name) == atom) return i;
    return -1;
}

/* Un valore dato a una variabile per dimostrare un "esiste". */
typedef struct {
    int name;     /* la lettera */
    Frac value;   /* il numero scelto */
} Choice;

/* I numeri scelti finora, dal quantificatore più esterno. Quando la
 * dimostrazione smentisce l'enunciato, sono il controesempio da riportare. */
static Choice *chosen;
static size_t chosen_capacity;
static int chosen_count;

/* 1 se una scelta è stata fatta dentro un caso sul resto (18o), o dentro una
 * distinzione di casi su una variabile (18v-2): allora i numeri scelti
 * cambiano da un caso all'altro, e non formano un controesempio da
 * riportare. */
static int chosen_by_cases;

/* Quante distinzioni di casi su una variabile (18v-2) racchiudono il punto
 * della dimostrazione in cui si è. */
static int region_depth;

/* 18v-4. I fatti "u non divide w" del caso in esame. Nascono da una
 * distinzione di casi (18v-2): nel caso "k \nmid y" la variabile y non si
 * scrive come k s, e il fatto resta scritto qui finché dura il caso. u = 1
 * dice che w non è un intero. Le regole 18v-1 e 18v-4 li usano. */
typedef struct {
    Rat divisor;  /* u: un numero, o un'espressione nelle variabili generiche */
    Poly value;   /* w: un polinomio nelle variabili generiche */
} Exclusion;

static Exclusion *excluded;
static size_t excluded_capacity;
static int excluded_count;

/* Annota che alla variabile name è stato dato il valore value. */
static void choose(int name, Frac value) {
    if (split_modulus || region_depth) chosen_by_cases = 1;
    if (work_reserve((void **)&chosen, &chosen_capacity, (size_t)chosen_count + 1, sizeof *chosen))
        chosen[chosen_count++] = (Choice){name, value};
}

/* Annota nel quantificatore "esiste" f il valore value con cui la sua
 * condizione è stata dimostrata, nel caso split_case (vedi Formula): la
 * verifica del capitolo 19 lo rilegge. witness_drop() lo toglie, quando per
 * lo stesso caso si ricomincia, o il valore non va usato.
 *
 * Dentro una distinzione di casi su una variabile (18v-2) il valore non si
 * annota: cambia da un caso all'altro, e quei casi non hanno un numero come
 * quelli sul resto. La verifica cerca allora da sé un valore che renda vera
 * la condizione, come per un "esiste" che la dimostrazione non ha scelto. */
static void witness_keep(Formula *f, Rat value) {
    if (region_depth) return;
    f->has_witness |= 1u << split_case;
    f->witness[split_case] = value;
}

static void witness_drop(Formula *f) { f->has_witness &= ~(1u << split_case); }

/* Ciò che la regola 18u lascia da ricontrollare alla verifica del capitolo
 * 19: quanti valori trovati da 18u-3 sono annotati in witness_records[] (vedi
 * WitnessRecord, nel capitolo 18.5), e quante ipotesi "esiste" 18u-1 ha
 * preso con il loro testimone. Come le scelte, tornano indietro con un
 * tentativo abbandonato: di quel tentativo non resta nulla da ricontrollare. */
static int record_count, hypotheses_named;

/* Un punto della dimostrazione scritta e dell'elenco delle scelte a cui si
 * può tornare quando un tentativo fallisce. */
typedef struct {
    size_t proof;  /* lunghezza del testo */
    int chosen;    /* numero di scelte */
    int records;   /* valori annotati da 18u-3 */
    int named;     /* ipotesi "esiste" prese da 18u-1 */
} Mark;

/* Ritorna il punto in cui si è adesso. */
static Mark mark_here(void) { return (Mark){proof_length, chosen_count, record_count, hypotheses_named}; }

/* Cancella il testo, le scelte e le annotazioni di 18u aggiunti dopo mark. */
static void rollback(Mark mark) {
    proof_length = mark.proof;
    proof_text[proof_length] = 0;
    chosen_count = mark.chosen;
    record_count = mark.records;
    hypotheses_named = mark.named;
}

/* Lettere da scrivere con un apice, per atomo: la regola dei segni (18c)
 * indica con x' il parametro della semiretta su cui fa variare x. */
static char primed[MAX_ATOMS];

/* Scrive il testo dell'enunciato che corrisponde alla condizione f. */
static void put_source(const Formula *f) { proof_add("%.*s", (int)(f->end - f->start), f->start); }

/* Scrive l'insieme set com'è scritto nell'enunciato. */
static void put_numbers(const NumberSet *set) { proof_add("%.*s", (int)(set->end - set->start), set->start); }

/* Ritorna il grado del monomio: la somma dei suoi esponenti. */
static long long mono_degree(const Mono *m) {
    long long degree = 0;
    for (int i = 0; i < m->count; i++) degree += m->factor[i].exp.num;
    return degree;
}

/* Ritorna il termine di p che put_poly() scrive per primo: il primo, nella
 * forma canonica, tra quelli di grado più alto. p non deve essere nullo. */
static const Term *poly_leading(Poly p) {
    const Term *leading = &p.term[0];
    for (int i = 1; i < p.count; i++)
        if (mono_degree(&p.term[i].mono) > mono_degree(&leading->mono)) leading = &p.term[i];
    return leading;
}

/* Scrive in LaTeX il polinomio p, dai termini di grado più alto. p deve essere
 * un polinomio "vero" nelle variabili dell'enunciato (vedi rat_polynomials()). */
static void put_poly(Poly p) {
    if (p.count == 0) { proof_add("0"); return; }
    int written = 0;
    for (long long degree = mono_degree(&poly_leading(p)->mono); degree >= 0; degree--)
        for (int i = 0; i < p.count; i++) {
            const Term *t = &p.term[i];
            if (mono_degree(&t->mono) != degree) continue;

            /* Segno e valore assoluto del coefficiente. Davanti a delle
             * lettere il coefficiente 1 non si scrive. */
            Frac size = t->coef.re;
            int negative = size.num < 0;
            if (negative) size = frac_neg(size);
            proof_add("%s", written++ ? (negative ? " - " : " + ") : (negative ? "-" : ""));
            if (t->mono.count == 0 || size.num != 1 || size.den != 1) put_frac(size);

            /* Le lettere, con apice ed esponente. Una potenza che fa da
             * lettera (18x) la scrive put_atom(), con l'esponente; dopo un
             * numero ci vuole il punto, perché 2 e 2^{n} accostati si
             * leggerebbero 22^{n}. */
            for (int k = 0; k < t->mono.count; k++) {
                const Factor *f = &t->mono.factor[k];
                if (atoms[f->atom].kind != ATOM_VAR) {
                    if (k == 0 && (size.num != 1 || size.den != 1)) proof_add(" \\cdot ");
                    else if (k) proof_add("\\,");
                    put_atom(f->atom, frac_int(f->exp.num));
                    continue;
                }
                proof_add("%c%s", (int)atoms[f->atom].id, primed[f->atom] ? "'" : "");
                if (f->exp.num != 1) proof_add("^{%lld}", f->exp.num);
            }
        }
}

/* Scrive p come fattore di un prodotto: tra parentesi se ha più termini. */
static void put_factor(Poly p) {
    if (p.count > 1) { proof_add("\\left("); put_poly(p); proof_add("\\right)"); }
    else put_poly(p);
}

/* Ritorna -p. */
static Poly poly_negate(Poly p) { return poly_add(poly_const(num_int(0)), p, 1); }

/* Scrive la frazione num/den, o solo num se den è 1. Se den comincia con un
 * segno meno si cambia segno a entrambi: si legge meglio. */
static void put_ratio(Poly num, Poly den) {
    if (poly_is_one(den)) { put_poly(num); return; }
    if (poly_leading(den)->coef.re.num < 0) { num = poly_negate(num); den = poly_negate(den); }
    proof_add("\\frac{");
    put_poly(num);
    proof_add("}{");
    put_poly(den);
    proof_add("}");
}

/* Ritorna 1 se p è una costante, zero compreso. */
static int poly_is_constant(Poly p) { return p.count == 0 || (p.count == 1 && p.term[0].mono.count == 0); }

/* Ritorna 1 se l'atomo x compare in p. */
static int poly_uses(Poly p, int x) {
    for (int i = 0; i < p.count; i++)
        if (mono_exponent(&p.term[i].mono, x).num != 0) return 1;
    return 0;
}

/* 18x. LE POTENZE COME LETTERE
 *
 * A che cosa serve. "a = 2^{n} b con n intero" è una relazione di
 * equivalenza: con m = -n si ha b = 2^{m} a, e da a = 2^{n} b, b = 2^{k} c
 * segue a = 2^{n + k} c. Sono identità tra polinomi, purché 2^{n} e 2^{k}
 * siano lettere come le altre: (a - 2^{n} b) + 2^{n} (b - 2^{k} c) =
 * a - 2^{n} 2^{k} c. Il conto le scrive già così, perché 2^{n + k} diventa
 * 2^{n} 2^{k} e 2^{-n} l'inverso di 2^{n} (capitolo 11); ma le regole del
 * capitolo 18 lavorano solo con le variabili, e davanti a un atomo che non
 * lo è si fermavano.
 *
 * Una potenza fa da lettera quando l'esponente è un prodotto di variabili
 * generiche intere e la base è positiva e razionale: un numero positivo, o
 * una variabile generica che varia tra i razionali positivi. Allora, per
 * ogni valore delle variabili, la potenza è un numero razionale positivo.
 *
 * Perché è lecito. Un'identità tra polinomi in lettere indipendenti vale
 * per ogni valore delle lettere, quindi anche quando una lettera vale 2^{n}:
 * tutto ciò che le regole ricavano da un'identità resta vero. Le lettere
 * nuove non sono però indipendenti davvero (2^{n} è sempre positivo, e
 * dipende da n), e una regola che ragionasse sul loro insieme sbaglierebbe:
 * per questo ogni regola che guarda gli insiemi lavora soltanto sulle
 * variabili di universal[], e davanti a una potenza non si applica. La
 * regola dei segni e quella delle radici (18b, 18c) guardano
 * universal_index(), e così 18d; 18e dice di una potenza soltanto che è un
 * numero razionale, ed è vero per quanto detto sopra; 18s la usa come
 * moltiplicatore, come una variabile.
 *
 * Solo dentro la ricerca. power_letters vale 1 mentre il capitolo 18 cerca
 * una dimostrazione, e 0 altrove: la regola dei resti (18r) e la verifica del
 * capitolo 19 vogliono polinomi nelle sole variabili, e per loro una potenza
 * resta ciò che era. */
static int power_letters;

/* 18x. Ritorna 1 se il monomio m è fatto di variabili generiche intere con
 * esponenti interi positivi: l'esponente di una potenza che fa da lettera. */
static int power_exponent(const Mono *m) {
    for (int i = 0; i < m->count; i++) {
        int who = universal_index(m->factor[i].atom);
        Frac e = m->factor[i].exp;
        if (who < 0 || !universal[who].numbers->integers || e.den != 1 || e.num < 1) return 0;
    }
    return 1;
}

/* 18x. Ritorna 1 se l'atomo è una potenza che fa da lettera (vedi sopra):
 * esponente fatto di variabili generiche intere, con esponenti interi
 * positivi, e base un numero positivo o una variabile generica dei
 * razionali positivi. Fuori dalla ricerca (power_letters a 0) ritorna 0. */
static int power_letter(int atom) {
    const Atom *a = &atoms[atom];
    if (!power_letters || a->kind != ATOM_POW || a->exponent.count == 0 || !power_exponent(&a->exponent)) return 0;
    if (a->base == BASE_PRIME) return 1;
    if (a->base == BASE_POLY) {
        Poly b = base_polys[a->id];
        return b.count == 1 && b.term[0].mono.count == 0 && b.term[0].coef.im.num == 0 && b.term[0].coef.re.num > 0;
    }
    if (a->base != BASE_ATOM) return 0;
    int who = universal_index((int)a->id);
    const NumberSet *set = who >= 0 ? universal[who].numbers : NULL;
    return set && !set->reals && set->bounded && (set->low > 0 || (set->low == 0 && set->strict));
}

/* Scrive r come frazione di due polinomi "veri": coefficienti razionali, solo
 * atomi che sono variabili (o, durante la ricerca, potenze che fanno da
 * lettere: 18x), esponenti interi non negativi. Mette i due polinomi in *num
 * e *den e ritorna 1; ritorna 0 se r non si può scrivere così.
 *
 * Serve perché rat_make() porta al numeratore un denominatore fatto di un
 * solo termine, lasciando esponenti negativi: 1/x diventa x^{-1}. Qui si fa
 * il passo inverso, moltiplicando sopra e sotto per la potenza di x che
 * manca. Dove r è definita quella potenza non è zero, quindi r si annulla
 * esattamente dove si annulla *num. */
static int rat_polynomials(Rat r, Poly *num, Poly *den) {
    *num = r.num;
    *den = r.den;

    /* Solo variabili, con esponenti interi e coefficienti reali. */
    for (int side = 0; side < 2; side++) {
        Poly p = side ? r.den : r.num;
        for (int i = 0; i < p.count; i++) {
            if (p.term[i].coef.im.num != 0) return 0;
            for (int k = 0; k < p.term[i].mono.count; k++) {
                int atom = p.term[i].mono.factor[k].atom;
                if ((atoms[atom].kind != ATOM_VAR && !power_letter(atom)) || p.term[i].mono.factor[k].exp.den != 1) return 0;
            }
        }
    }

    /* Per ogni variabile, l'esponente più basso con cui compare: se è
     * negativo si moltiplica tutto per la potenza opposta. */
    for (int x = 0; x < atom_count && !failure; x++) {
        Frac lowest = frac_int(0);
        for (int side = 0; side < 2; side++) {
            Poly p = side ? *den : *num;
            for (int i = 0; i < p.count; i++) {
                Frac e = mono_exponent(&p.term[i].mono, x);
                if (frac_cmp(e, lowest) < 0) lowest = e;
            }
        }
        if (lowest.num == 0) continue;
        Term lift;
        lift.coef = num_int(1);
        lift.mono = mono_atom(x, frac_neg(lowest));
        *num = poly_mul(*num, poly_term(lift));
        *den = poly_mul(*den, poly_term(lift));
    }
    return !failure;
}

/* Scrive il valore r come frazione di due polinomi "veri" (vedi
 * rat_polynomials()), o \ldots se non lo è. */
static void put_fraction(Rat r) {
    Poly num, den;
    if (rat_polynomials(r, &num, &den)) put_ratio(num, den);
    else proof_add("\\ldots");
}

/* =============================================================================
 * 18.2 POLINOMI NELLE VARIABILI GENERICHE: ZERI, SEGNI, INTERI, APPARTENENZA
 * ============================================================================
 *
 * Le regole da 18a a 18f: dato un polinomio "vero" nelle variabili generiche
 * (rat_polynomials()), stabilire per ogni loro valore che non si annulla, che
 * ha un segno, che è un intero, che sta in un insieme numerico; e che ogni
 * divisore di un'espressione è diverso da zero. Ognuna scrive il proprio
 * ragionamento, e ricontrolla prima ciò che il testo sta per affermare: le
 * radici sostituendole (roots_confirmed()), le semirette guardando dove
 * cadono i primi elementi dell'insieme, la sostituzione tornando indietro.
 */

/* Controllo di un passo: ciò che la dimostrazione sta per dire delle radici
 * del polinomio p, nella variabile di atomo x che varia in set. Ritorna 1 se
 *
 *   - ognuno dei `roots` numeri di root[] è davvero una radice;
 *   - tra i primi elementi di set non c'è una radice che manca dall'elenco.
 *
 * rational_roots() le ha trovate con un conto su interi; qui si sostituisce
 * ogni numero nel polinomio com'è. Il secondo controllo non può essere
 * completo, ma guarda proprio dove un errore farebbe danno: una radice
 * dimenticata dentro l'insieme renderebbe falso "p non si annulla mai".
 * Se un controllo fallisce annota il passo come non giustificato e ritorna 0. */
static int roots_confirmed(Poly p, int x, const Frac *root, int roots, const NumberSet *set) {
    Frac sample[2 * SAMPLE_SIZE];
    Num value;
    for (int k = 0; k < roots; k++) {
        Rat at = poly_substitute(p, x, rat_frac(root[k]));
        if (failure) return 0;
        if (!rat_number(at, &value) || !num_is_zero(value)) { unjustified_steps++; return 0; }
    }
    numbers_sample(set, sample, 2 * SAMPLE_SIZE);
    for (int i = 0; i < 2 * SAMPLE_SIZE; i++) {
        int listed = 0;
        for (int k = 0; k < roots; k++)
            if (frac_cmp(sample[i], root[k]) == 0) listed = 1;
        if (!listed && rat_number(poly_substitute(p, x, rat_frac(sample[i])), &value) && num_is_zero(value)) { unjustified_steps++; return 0; }
    }
    return 1;
}

/* Una semiretta su cui la regola dei segni fa variare una variabile x:
 * x = origin + direction * t, con t >= 0, oppure t > 0 se strict. */
typedef struct {
    long long origin;  /* il punto di partenza */
    int direction;     /* +1 verso destra, -1 verso sinistra */
    int strict;        /* 1 se il punto di partenza è escluso */
    int used;          /* 1 se x compare nel polinomio in esame */
} Ray;

/* La semiretta in esame per ogni variabile generica, nella stessa posizione
 * di universal[]. Vale durante una chiamata a signs(). */
static Ray *ray;
static size_t ray_capacity;

/* Che cosa signs() deve stabilire di un polinomio. */
typedef enum {
    SIGN_NONNEGATIVE,  /* non è mai negativo */
    SIGN_POSITIVE,     /* è sempre positivo */
    SIGN_NONZERO       /* non è mai zero, oppure lo è solo dove lo è `guard` */
} SignGoal;

/* 18z. Ritorna 1 se il monomio a divide il monomio b: ogni suo atomo
 * compare in b con un esponente almeno uguale. */
static int mono_divides(const Mono *a, const Mono *b) {
    for (int i = 0; i < a->count; i++)
        if (frac_cmp(mono_exponent(b, a->factor[i].atom), a->factor[i].exp) < 0) return 0;
    return 1;
}

/* 18c. Regola dei segni.
 *
 * Stabilisce il segno del polinomio p per tutti i valori delle variabili
 * generiche, secondo goal, e scrive il ragionamento. Ritorna 1 se ci riesce.
 * Va chiamata con index = 0 e shown = p: shown è il polinomio di partenza, da
 * citare nel testo, mentre p cambia a ogni sostituzione.
 *
 * L'idea. Un polinomio in t >= 0 i cui coefficienti non sono negativi è una
 * somma di termini non negativi: non è negativo, ed è positivo se uno dei
 * termini lo è di sicuro (il termine noto, oppure un termine in sole variabili
 * strettamente positive). Per ricondursi a questo caso si copre l'insieme di
 * ogni variabile x con una o due semirette:
 *
 *   - un insieme con estremo inferiore c, come \mathbb{N}: x = c + t;
 *   - tutti gli interi: x = t, oppure x = -1 - t;
 *   - tutti i razionali: x = t, oppure x = -t.
 *
 * e su ciascuna si sostituisce x. Con più variabili si esaminano tutte le
 * combinazioni di semirette: il segno deve risultare in ognuna.
 *
 * Con guard e goal SIGN_NONZERO c'è un caso in più. Una somma di termini non
 * negativi è zero solo se lo è ogni termine; se tra i termini c'è una potenza
 * di una sola variabile, quella variabile deve valere zero. Se ogni termine
 * di guard contiene una variabile così forzata, dove p è zero lo è anche
 * guard. È ciò che serve per a + b con a, b >= 0: è zero solo per
 * a = b = 0, dove a - b è zero. */
static int signs(Poly shown, Poly p, const Poly *guard, int index, SignGoal goal) {
    if (failure || !work_reserve((void **)&ray, &ray_capacity, (size_t)universal_count, sizeof *ray)) return 0;

    /* 18c-1. Una variabile alla volta: le semirette che coprono il suo
     * insieme. Dopo la sostituzione x = origin + direction * x la lettera x
     * indica il parametro t della semiretta. */
    if (index < universal_count) {
        const NumberSet *set = universal[index].numbers;
        int x = atom_var(universal[index].name);
        ray[index].used = poly_uses(p, x) || (guard && poly_uses(*guard, x));
        if (!ray[index].used) return signs(shown, p, guard, index + 1, goal);

        Ray cover[2] = {{set->bounded ? set->low : 0, 1, set->bounded && set->strict, 1},
                        {set->integers ? -1 : 0, -1, 0, 1}};
        int covers = set->bounded ? 1 : 2;

        /* Controllo del passo: ogni elemento dell'insieme deve stare su una
         * delle semirette, altrimenti il ragionamento per casi ne lascerebbe
         * fuori qualcuno. Lo si verifica sui primi elementi dell'insieme: il
         * parametro t = direction * (x - origin) non deve essere negativo. */
        Frac sample[SAMPLE_SIZE];
        numbers_sample(set, sample, SAMPLE_SIZE);
        for (int i = 0; i < SAMPLE_SIZE; i++) {
            int covered = 0;
            for (int k = 0; k < covers; k++) {
                Frac t = frac_mul(frac_int(cover[k].direction), frac_add(sample[i], frac_int(-cover[k].origin)));
                if (t.num > 0 || (t.num == 0 && !cover[k].strict)) covered = 1;
            }
            if (!covered) { unjustified_steps++; return 0; }
        }
        for (int k = 0; k < covers; k++) {
            Rat line = rat_add(rat_int(cover[k].origin), rat_mul(rat_int(cover[k].direction), rat_atom(x)), 0);
            Poly moved = poly_substitute(p, x, line).num, moved_guard = {0, NULL};
            if (guard) moved_guard = poly_substitute(*guard, x, line).num;
            ray[index] = cover[k];
            if (!signs(shown, moved, guard ? &moved_guard : NULL, index + 1, goal)) return 0;
        }
        return 1;
    }

    /* 18c-2. Tutte le variabili sono su una semiretta: si guardano i
     * coefficienti. `certain` dice se c'è un termine sicuramente diverso da
     * zero; forced[i] se un termine è potenza della sola variabile i. */
    int negative = 0, positive = 0, certain = 0, constant = 0, multiples = 0;
    char forced[universal_count ? universal_count : 1];
    memset(forced, 0, sizeof forced);
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        int all_strict = 1;
        if (t->coef.re.num < 0) negative++; else positive++;
        for (int k = 0; k < t->mono.count; k++) {
            int who = universal_index(t->mono.factor[k].atom);
            if (who < 0) return 0;
            if (!ray[who].strict) all_strict = 0;
            if (t->mono.count == 1) forced[who] = 1;
        }
        if (all_strict) certain = 1;
        if (t->mono.count == 0) constant = 1;
    }

    /* 18c-3. Il segno che ne segue. `conclusion` è la parola con cui lo si
     * dirà, oppure NULL nel caso con guard: zero solo dove ogni termine è
     * zero, e lì deve annullarsi anche guard. */
    const char *conclusion = NULL;
    if (goal == SIGN_NONNEGATIVE && !negative) {
        conclusion = "not negative";
    } else if (goal != SIGN_NONNEGATIVE && !negative && certain) {
        conclusion = "positive";
    } else if (goal == SIGN_NONZERO && !positive && certain) {
        conclusion = "negative";
    } else if (goal == SIGN_NONZERO && guard && p.count && !(negative && positive)) {
        /* Un termine di guard si annulla se contiene una variabile forzata
         * a zero, oppure (18z) se è un multiplo di un termine di p: quando
         * ogni termine di p vale zero, vale zero anche il suo monomio, e con
         * lui ogni suo multiplo. Così a (1 - m n) = 0 con m, n naturali e a
         * intero dà a (1 - m) = 0 anche per a = 0, dove nessuna variabile è
         * forzata. */
        for (int i = 0; i < guard->count; i++) {
            int vanishes = 0;
            for (int k = 0; k < guard->term[i].mono.count; k++) {
                int who = universal_index(guard->term[i].mono.factor[k].atom);
                if (who >= 0 && forced[who]) vanishes = 1;
            }
            for (int j = 0; j < p.count && !vanishes; j++)
                if (mono_divides(&p.term[j].mono, &guard->term[i].mono)) vanishes = multiples = 1;
            if (!vanishes) return 0;
        }
    } else {
        return 0;
    }

    /* Controllo del passo: tornando indietro dalle semirette, cioè
     * sostituendo t = direction * (x - origin), si deve ritrovare il
     * polinomio di partenza. È ciò che il testo affermerà scrivendo
     * "p = ..." con le variabili nuove. */
    Rat back = {p, poly_const(num_int(1))};
    for (int i = 0; i < universal_count; i++) {
        if (!ray[i].used) continue;
        int x = atom_var(universal[i].name);
        Rat inverse = rat_mul(rat_int(ray[i].direction), rat_add(rat_atom(x), rat_int(ray[i].origin), 1));
        back = poly_substitute(back.num, x, inverse);
    }
    if (failure) return 0;
    if (!poly_is_one(back.den) || !poly_equal(back.num, shown)) { unjustified_steps++; return 0; }

    /* 18c-4. Il testo: le semirette, poi il polinomio prima e dopo la
     * sostituzione. Una variabile su una semiretta che non parte da zero
     * verso destra viene riscritta, e da lì in poi porta l'apice. */
    int listed = 0, shifted = 0;
    for (int i = 0; i < universal_count; i++) {
        if (!ray[i].used) continue;
        int name = universal[i].name;
        const char *order = ray[i].strict ? ">" : "\\ge";
        proof_add("%s", listed++ ? ", " : " For ");
        if (ray[i].origin == 0 && ray[i].direction > 0) { proof_add("$%c %s 0$", name, order); continue; }
        shifted = 1;
        proof_add("$%c = ", name);
        if (ray[i].origin) proof_add("%lld %c ", ray[i].origin, ray[i].direction > 0 ? '+' : '-');
        else proof_add("-");
        proof_add("%c'$ with $%c' %s 0$", name, name, order);
    }
    proof_add("%s $", listed ? ":" : "");
    put_poly(shown);
    for (int i = 0; i < universal_count; i++)
        primed[atom_var(universal[i].name)] = ray[i].used && (ray[i].origin != 0 || ray[i].direction < 0);
    if (shifted) { proof_add(" = "); put_poly(p); }
    proof_add("$");
    if (conclusion) {
        /* Per "non negativo" bastano i coefficienti; per un segno stretto
         * serve anche il termine sicuramente diverso da zero. */
        proof_add(" has no %s coefficient", negative ? "positive" : "negative");
        if (goal != SIGN_NONNEGATIVE) proof_add(" and %s", constant ? "a constant term" : "a term whose variables are all positive");
        proof_add(", so it is %s.", conclusion);
    } else {
        int written = 0;
        proof_add(" has no %s coefficient, so it is zero only if each of its terms is zero.", negative ? "positive" : "negative");
        for (int i = 0; i < universal_count; i++)
            if (forced[i]) proof_add("%s $%c%s = 0$", written++ ? "," : " That forces", universal[i].name, primed[atom_var(universal[i].name)] ? "'" : "");
        proof_add("%s $", written ? ", and then" : " Then");
        put_poly(*guard);
        proof_add(" = 0$%s.", multiples ? ": each of its terms has a factor forced to zero, or is a multiple of a term that is zero" : "");
    }
    memset(primed, 0, sizeof primed);
    return 1;
}

/* 18y. LE VARIABILI REALI, SENZA RELAZIONI D'ORDINE
 *
 * A che cosa serve. "a b^{-1} \in \mathbb{Q}" tra numeri reali positivi è
 * una relazione di equivalenza: a a^{-1} = 1, il reciproco di un razionale
 * diverso da zero è razionale, e (a b^{-1})(b c^{-1}) = a c^{-1}. Sono conti
 * con = e con l'appartenenza, senza disuguaglianze: la tabella dei segni non
 * li tratta, e le regole del capitolo 18 sì, purché nessuna di loro dia per
 * scontato che una variabile sia razionale. Lo davano per scontato in due:
 *
 *   18y-1. La regola delle radici (18b): un polinomio in una variabile reale
 *          può annullarsi in una radice irrazionale, come x^2 - 2, e le
 *          radici razionali non le dicono tutte. Per una variabile reale la
 *          regola vale solo al primo grado, dove l'unica radice, -r/c, è
 *          razionale.
 *   18y-2. L'appartenenza (18e): "è un numero razionale" vale per
 *          un'espressione razionale nelle variabili razionali e nelle
 *          potenze che fanno da lettere (18x), non in una variabile reale, né
 *          nelle costanti e e \pi. Che lo fosse anche lì era un errore già
 *          presente: "esiste x razionale con x = e" passava le regole, e lo
 *          fermava solo la verifica del capitolo 19.
 *
 * Le altre regole non dipendono dall'insieme in questo modo: la regola dei
 * segni (18c) copre una semiretta di reali come una di razionali, 18d e 18o
 * vogliono interi, 18j prova numeri razionali, che sono anche reali, e le
 * identità tra polinomi valgono per ogni valore delle lettere. Il valore di
 * un "esiste" tra i razionali, cercato da 18u-3, va però scritto con le sole
 * lettere razionali (`need` in combination()), e due passi servono al
 * reciproco di un razionale:
 *
 *   18y-3. Il valore cercato può essere w / v, con v una variabile generica
 *          che non vale zero (in witnesses_solve()): da x = q y segue
 *          y = (1/q) x.
 *   18y-4. Un valore sempre positivo che sta in \mathbb{Q} ha il nome in
 *          \mathbb{Q}^{+} (positive_part()), che non contiene lo zero: così
 *          da x y^{-1} = q, con x e y reali positivi, q non è zero, e si può
 *          dividere per lui. Una potenza con esponente intero negativo, come
 *          y^{-1}, è un'espressione razionale, e la sua base fa da divisore
 *          (negative_power(), term_defined()).
 *
 * Che cosa resta da sapere. La verifica del capitolo 19 prova numeri
 * razionali anche al posto delle variabili reali: su di loro "a b^{-1} \in
 * \mathbb{Q}" vale sempre, e un enunciato vero sui razionali ma falso sui
 * reali non la fermerebbe. Per questi enunciati la correttezza riposa sulle
 * regole, e i test ne contengono di falsi di quel tipo, che non devono
 * risultare dimostrati (false_number_relations.tex). */
/* Ritorna 1 se p ha coefficienti interi e contiene solo variabili generiche
 * intere: allora vale un intero per ogni loro valore. Non scrive nulla. */
static int poly_whole(Poly p) {
    for (int i = 0; i < p.count; i++) {
        if (p.term[i].coef.im.num != 0 || p.term[i].coef.re.den != 1) return 0;
        for (int k = 0; k < p.term[i].mono.count; k++) {
            const Factor *f = &p.term[i].mono.factor[k];
            int who = universal_index(f->atom);
            if (who < 0 || !universal[who].numbers->integers || f->exp.den != 1 || f->exp.num < 0) return 0;
        }
    }
    return 1;
}

/* 18v-4. Dimostra che p non si annulla perché, se fosse zero, una variabile
 * avrebbe il valore che il caso in esame esclude. Scrive il ragionamento e
 * ritorna 1 se ci riesce.
 *
 * Se p = gamma y + delta, con gamma un numero diverso da zero e delta senza y,
 * allora p = 0 vuol dire y = rho = -delta/gamma. Se nel caso in esame vale
 * "u non divide w" (excluded[]) e w, con rho al posto di y, è u per un
 * polinomio a coefficienti interi nelle variabili intere, cioè u per un
 * intero, allora p = 0 porterebbe a "u divide w": falso. È ciò che serve con
 * k \nmid b e k s + k - b, o con b \notin \mathbb{Z} e a + 1 - b. */
static int excluded_root(Poly p) {
    Poly one = poly_const(num_int(1));
    for (int e = 0; e < excluded_count && !failure; e++) {
        for (int i = 0; i < universal_count && !failure; i++) {
            Poly part[2], q, d;
            int y = atom_var(universal[i].name);
            if (!poly_uses(excluded[e].value, y) || poly_split(p, y, part, 1) != 1 || !poly_is_constant(part[1]) || part[1].count == 0) continue;
            Rat root = rat_div((Rat){poly_negate(part[0]), one}, (Rat){part[1], one});
            Rat image = poly_substitute(excluded[e].value, y, root);
            if (failure || !rat_polynomials(rat_div(image, excluded[e].divisor), &q, &d) || !poly_is_one(d) || !poly_whole(q)) continue;

            /* Controllo del passo: u per il quoziente deve ridare w. */
            Rat back = rat_add(rat_mul((Rat){q, one}, excluded[e].divisor), image, 1);
            if (failure) return 0;
            if (back.num.count != 0) { unjustified_steps++; return 0; }

            Num unit;
            int integer = rat_number(excluded[e].divisor, &unit) && num_equal(unit, num_int(1));
            /* Il testo: il valore della variabile, quello di w se w non è
             * la variabile stessa, perché è un multiplo, e il fatto del caso. */
            proof_add(" If it were zero, then $%c = ", universal[i].name);
            put_fraction(root);
            if (!poly_equal(excluded[e].value, rat_atom(y).num)) {
                proof_add("$, and so $");
                put_poly(excluded[e].value);
                proof_add(" = ");
                put_fraction(image);
            }
            if (integer) {
                proof_add("$, an integer (integer coefficients, integer variables); but in this case $");
                put_poly(excluded[e].value);
                proof_add(" \\notin \\mathbb{Z}$.");
            } else {
                proof_add("$, which is $");
                put_fraction(excluded[e].divisor);
                proof_add("$ times the integer $");
                put_poly(q);
                proof_add("$; but in this case $");
                put_fraction(excluded[e].divisor);
                proof_add(" \\nmid ");
                put_poly(excluded[e].value);
                proof_add("$.");
            }
            return 1;
        }
    }
    return 0;
}

/* Controllo del passo di 18v-5 e 18v-10: p, che la regola dichiara mai
 * nullo, non deve annullarsi in nessuna scelta dei primi elementi degli
 * insiemi delle sue variabili, dalla variabile di posto from in su. È un
 * conto diverso dalla regola: sostituisce numeri e guarda il risultato.
 * Ritorna 0 se trova uno zero (o se un conto non riesce). */
static int no_zero_on_sample(Poly p, int from) {
    Num value;
    if (failure) return 0;
    if (from == universal_count) return !rat_number((Rat){p, poly_const(num_int(1))}, &value) || !num_is_zero(value);
    int x = atom_var(universal[from].name);
    if (!poly_uses(p, x)) return no_zero_on_sample(p, from + 1);
    Frac sample[5];
    numbers_sample(universal[from].numbers, sample, 5);
    for (int i = 0; i < 5; i++) {
        Rat moved = poly_substitute(p, x, rat_frac(sample[i]));
        if (failure || !poly_is_one(moved.den) || !no_zero_on_sample(moved.num, from + 1)) return 0;
    }
    return 1;
}

/* 18v-5. Dimostra che p, a coefficienti razionali in variabili generiche
 * intere, non si annulla guardando i resti: scrive il ragionamento e ritorna
 * 1 se ci riesce.
 *
 * Moltiplicato p per il minimo comune multiplo s dei denominatori, s p =
 * g Q + c, dove c è il termine noto, g il massimo comun divisore degli altri
 * coefficienti e Q un polinomio a coefficienti interi: per valori interi
 * delle variabili Q è un intero, e s p = 0 direbbe che g divide c. Se g non
 * divide c, quindi, p non è mai zero. Così 4s - 10t - 5 = 0 non ha soluzioni
 * intere: 4s - 10t è pari, 5 no. */
static int content_excludes(Poly p) {
    long long scale = 1;
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        if (t->coef.im.num != 0) return 0;
        for (int k = 0; k < t->mono.count; k++) {
            int who = universal_index(t->mono.factor[k].atom);
            if (who < 0 || !universal[who].numbers->integers || t->mono.factor[k].exp.den != 1) return 0;
        }
        __int128 multiple = (__int128)scale / gcd128(scale, t->coef.re.den) * t->coef.re.den;
        if (multiple > 1000000000) return 0;
        scale = (long long)multiple;
    }
    __int128 g = 0, c = 0;
    for (int i = 0; i < p.count; i++) {
        __int128 value = (__int128)p.term[i].coef.re.num * (scale / p.term[i].coef.re.den);
        if (p.term[i].mono.count == 0) c = value;
        else g = gcd128(g, value);
    }
    if (g < 2 || c % g == 0) return 0;
    if (!no_zero_on_sample(p, 0)) { if (!failure) unjustified_steps++; return 0; }
    proof_add(" The variables are integers, and every coefficient of $");
    if (scale != 1) proof_add("%lld\\left(", scale);
    put_poly(p);
    if (scale != 1) proof_add("\\right)");
    proof_add("$ except the constant term is a multiple of $%lld$, while the constant term $%lld$ is not: so it is never zero.",
              (long long)g, (long long)c);
    return 1;
}

/* 18v-10. Dimostra che p = c + k M, con c e k numeri, c diverso da zero, e M
 * un prodotto di potenze di variabili generiche intere, non si annulla
 * perché una delle variabili non può dividere il numero che servirebbe.
 * Scrive il ragionamento e ritorna 1 se ci riesce.
 *
 * Se p = 0 allora M = -c/k: questo deve essere un intero N (M lo è), e ogni
 * variabile x di M divide M, cioè N: x è uno dei divisori di N, positivi o
 * negativi, che sono in numero finito perché N non è zero. Se nessuno di
 * loro sta nell'insieme di x, p non si annulla mai. Così a x - 1 non è mai
 * zero con a intero diverso da 1 e da -1: a dovrebbe dividere 1.
 *
 * Le altre due regole sui divisori e sui prodotti che valgono 1. È lo stesso
 * fatto di 18w, che prova uno per uno i divisori di un numero quando la
 * condizione dice "d divide c"; qui la divisibilità non è scritta, e nasce
 * dal polinomio. E un prodotto di naturali che vale 1 ha ogni fattore uguale
 * a 1 lo dice la regola dei segni con la guardia (18c, dopo la sostituzione
 * di 18z): quella dice dove p può annullarsi, a = b = 1 in 1 - a b, questa
 * che non si annulla mai, anche tra gli interi e con -c/k diverso da 1. Le
 * tre restano, perché nessuna fa ciò che fanno le altre; un enunciato che due
 * di loro sanno dimostrare lo dimostra la prima che lo prova. */
static int divisor_excludes(Poly p) {
    if (p.count != 2) return 0;
    const Term *constant = p.term[0].mono.count == 0 ? &p.term[0] : &p.term[1], *product = constant == &p.term[0] ? &p.term[1] : &p.term[0];
    if (constant->mono.count != 0 || product->mono.count == 0 || constant->coef.im.num || product->coef.im.num) return 0;
    Frac needed = frac_neg(frac_div(constant->coef.re, product->coef.re));
    if (failure || needed.den != 1 || needed.num == 0 || llabs(needed.num) > 1000000) return 0;
    for (int k = 0; k < product->mono.count; k++) {
        const Factor *f = &product->mono.factor[k];
        int who = universal_index(f->atom);
        if (who < 0 || !universal[who].numbers->integers || f->exp.den != 1 || f->exp.num < 1) return 0;
    }
    for (int k = 0; k < product->mono.count; k++) {
        int who = universal_index(product->mono.factor[k].atom), inside = 0;
        for (long long d = 1; d * d <= llabs(needed.num) && !inside; d++) {
            if (llabs(needed.num) % d) continue;
            long long pair[4] = {d, -d, llabs(needed.num) / d, -(llabs(needed.num) / d)};
            for (int j = 0; j < 4; j++) inside = inside || numbers_contain(universal[who].numbers, frac_int(pair[j]));
        }
        if (inside) continue;
        if (!no_zero_on_sample(p, 0)) { if (!failure) unjustified_steps++; return 0; }
        proof_add(" If it were zero, then $");
        Term alone = *product;
        alone.coef = num_int(1);
        put_poly(poly_term(alone));
        proof_add(" = %lld$, and $%c$, an integer that divides it, would be one of the divisors of $%lld$; none of them is in $",
                  needed.num, universal[who].name, needed.num);
        put_numbers(universal[who].numbers);
        proof_add("$.");
        return 1;
    }
    return 0;
}

/* 18a, 18b, 18c. Dimostra che il polinomio p non si annulla per nessun valore
 * delle variabili generiche; se guard non è NULL basta meno: che p si annulli
 * solo dove si annulla anche guard. Scrive il ragionamento e ritorna 1 se ci
 * riesce. p deve essere un polinomio "vero" (vedi rat_polynomials()). Le
 * regole 18v-4 e 18v-5, provate prima di 18b e dopo 18c, dimostrano qualcosa
 * di più: che p non si annulla mai. */
static int zero_only_where(Poly p, const Poly *guard) {
    if (failure || p.count == 0) return 0;

    /* 18a. Una costante. */
    if (poly_is_constant(p)) {
        proof_add(" The constant $");
        put_poly(p);
        proof_add("$ is not zero.");
        return 1;
    }

    /* 18v-4. Un fatto "u non divide w" del caso in esame può escludere la
     * radice anche quando sta nell'insieme: va guardato prima di 18b, che
     * altrimenti si fermerebbe lì. C'è solo dentro una distinzione di casi. */
    if (excluded_count && excluded_root(p)) return 1;

    /* 18b. Una sola variabile: si annulla solo nelle radici, e quelle che
     * contano stanno nell'insieme, che è fatto di razionali. */
    for (int i = 0; i < universal_count; i++) {
        long long c[MAX_UNIVARIATE + 1], scale;
        Frac root[MAX_UNIVARIATE + 1];
        const NumberSet *set = universal[i].numbers;
        int x = atom_var(universal[i].name);
        int degree = poly_coefficients(p, x, c, &scale);
        if (degree < 1) continue;

        /* 18y-1. Per una variabile reale le radici razionali sono tutte le
         * radici solo al primo grado. */
        if (set->reals && degree > 1) continue;
        int roots = rational_roots(c, degree, root);
        if (roots < 0) break;
        if (!roots_confirmed(p, x, root, roots, set)) return 0;

        /* Una radice nell'insieme è ammessa solo se lì si annulla guard. */
        int inside = 0;
        for (int k = 0; k < roots; k++) {
            Num value;
            if (!numbers_contain(set, root[k])) continue;
            if (!guard || !rat_number(poly_substitute(*guard, x, rat_frac(root[k])), &value) || !num_is_zero(value)) return 0;
            inside++;
        }

        proof_add(" The polynomial $");
        put_poly(p);
        if (roots == 0) {
            proof_add("$ has no rational root: the rational root theorem leaves finitely many candidates, and none of them is a root.");
            return 1;
        }
        proof_add("$ has the rational root%s $", roots > 1 ? "s" : "");
        for (int k = 0; k < roots; k++) {
            if (k) proof_add(",\\ ");
            put_frac(root[k]);
        }
        proof_add("$ and no other; ");
        if (!inside) {
            proof_add("%s in $", roots > 1 ? "none of them is" : "it is not");
            put_numbers(set);
            proof_add("$.");
        } else {
            proof_add("wherever a root is in $");
            put_numbers(set);
            proof_add("$, also $");
            put_poly(*guard);
            proof_add("$ is zero.");
        }
        return 1;
    }

    /* 18z. Un fattore comune che non si annulla: p = M q, con M un monomio
     * le cui lettere non valgono mai zero (variabili generiche il cui
     * insieme non contiene lo zero, o potenze di 18x, che sono positive).
     * Un prodotto di numeri è zero solo se lo è un fattore, quindi p è zero
     * esattamente dove lo è q, e basta dimostrare di q ciò che si chiede di
     * p. Così m (1 - 2a), con m naturale e a intero, non è mai zero: lo dice
     * 18b di 1 - 2a, la cui radice 1/2 non è intera. Se q non riesce, resta
     * la regola dei segni su p. */
    Mono common = poly_common(p);
    int factor = common.count > 0;
    for (int k = 0; k < common.count && factor; k++) {
        int atom = common.factor[k].atom, who = universal_index(atom);
        factor = power_letter(atom) || (who >= 0 && !numbers_contain(universal[who].numbers, frac_int(0)));
    }
    if (factor) {
        Term inverse = {num_int(1), mono_pow(&common, frac_int(-1))}, whole = {num_int(1), common};
        Poly q = poly_mul(p, poly_term(inverse));
        Mark mark = mark_here();

        /* Controllo del passo: M q deve ridare p. */
        if (failure) return 0;
        if (!poly_equal(poly_mul(q, poly_term(whole)), p)) { unjustified_steps++; return 0; }
        proof_add(" The polynomial $");
        put_poly(p);
        proof_add("$ is $");
        put_poly(poly_term(whole));
        proof_add("$ times $");
        put_factor(q);
        proof_add("$, and the letters of the first factor are never zero.");
        if (zero_only_where(q, guard)) return 1;
        rollback(mark);
    }

    /* 18c. Più variabili, o radici non determinabili: la regola dei segni.
     * Se non basta, il testo che ha scritto si toglie, e restano 18v-5, i
     * resti, e 18v-10, i divisori. Vengono dopo perché dove la regola dei
     * segni basta la dimostrazione resta quella di sempre. */
    size_t before = proof_length;
    if (signs(p, p, guard, 0, SIGN_NONZERO)) return 1;
    if (failure) return 0;
    proof_cut(before);
    return content_excludes(p) || divisor_excludes(p);
}

/* 18d. Dimostra che il polinomio p è un numero intero per ogni valore delle
 * variabili generiche, scrive il ragionamento e ritorna 1 se ci riesce.
 *
 * Due casi. Se le variabili sono intere e i coefficienti pure, è ovvio. Se p
 * ha una sola variabile n e grado d, basta che sia intero per n = 0, 1, ...,
 * d. Infatti (formula di Newton) p(n) è la somma, per k da 0 a d, di
 * D_k * binom(n, k), dove D_k è la differenza k-esima di p in zero: una
 * combinazione a coefficienti interi di p(0), ..., p(k), quindi un intero. E
 * binom(n, k) è intero per ogni n intero, anche negativo. Così (n^2 + n)/2 è
 * sempre intero, pur avendo coefficienti frazionari. */
static int always_integer(Poly p) {
    /* Le variabili devono essere tutte intere. */
    int whole = 1;
    for (int i = 0; i < p.count; i++) {
        if (p.term[i].coef.re.den != 1) whole = 0;
        for (int k = 0; k < p.term[i].mono.count; k++) {
            int who = universal_index(p.term[i].mono.factor[k].atom);
            if (who < 0 || !universal[who].numbers->integers) return 0;
        }
    }
    if (whole) {
        proof_add(" It is an integer, because the coefficients of $");
        put_poly(p);
        proof_add("$ are integers.");
        return 1;
    }

    /* Una sola variabile: i valori in 0, ..., grado. I coefficienti c sono
     * quelli di p moltiplicati per scale, quindi p(k) è intero quando scale
     * divide la somma dei c[j] k^j. Con c fino a un miliardo e k, j fino a
     * 16 la somma sta comodamente in un __int128. */
    for (int i = 0; i < universal_count; i++) {
        long long c[MAX_UNIVARIATE + 1], scale;
        int degree = poly_coefficients(p, atom_var(universal[i].name), c, &scale);
        if (degree < 1) continue;
        for (long long k = 0; k <= degree; k++) {
            __int128 value = 0;
            for (int j = degree; j >= 0; j--) value = value * k + c[j];
            if (value % scale != 0) return 0;
        }
        proof_add(" It is an integer: $");
        put_poly(p);
        proof_add("$ is an integer for $%c = 0, \\ldots, %d$, and a polynomial of degree $%d$ that is an integer at "
                  "$%d$ consecutive integers is an integer at every integer.", universal[i].name, degree, degree, degree + 1);
        return 1;
    }
    return 0;
}

/* 18e. Dimostra che value appartiene a set per ogni valore delle variabili
 * generiche, scrive il ragionamento e ritorna 1 se ci riesce. Le frasi hanno
 * per soggetto "it": chi chiama ha appena nominato il valore. */
static int always_in(Rat value, const NumberSet *set) {
    Poly num, den;
    Num number;
    if (!rat_polynomials(value, &num, &den)) return 0;

    /* Un numero: basta guardarlo. */
    if (rat_number(value, &number)) {
        if (!numbers_contain(set, number.re)) return 0;
        proof_add(" Indeed $");
        put_frac(number.re);
        proof_add("$ is in $");
        put_numbers(set);
        proof_add("$.");
        return 1;
    }

    /* Intero, se l'insieme è di interi; razionale, se è di razionali, e
     * questo lo è solo un'espressione nelle variabili razionali e nelle
     * potenze che fanno da lettere (18y-2). Ogni espressione razionale è un
     * numero reale. */
    if (set->integers) {
        if (!poly_is_one(den) || !always_integer(num)) return 0;
    } else if (set->reals) {
        proof_add(" It is a real number.");
    } else {
        for (int side = 0; side < 2; side++)
            for (int i = 0; i < (side ? den : num).count; i++) {
                const Mono *m = &(side ? den : num).term[i].mono;
                for (int k = 0; k < m->count; k++) {
                    int who = universal_index(m->factor[k].atom);
                    if (!power_letter(m->factor[k].atom) && (who < 0 || universal[who].numbers->reals)) return 0;
                }
            }
        proof_add(" It is a rational number.");
    }

    /* Non sotto l'estremo inferiore: value - low = above/den, e si guarda il
     * segno di above e quello di den. */
    if (set->bounded) {
        Poly above = poly_add(num, poly_mul(poly_const(num_int(set->low)), den), 1);
        if (set->low == 0) {
            proof_add(set->strict ? " It is positive." : " It is not negative.");
        } else {
            proof_add(" It is %s $%lld$, since subtracting $%lld$ leaves $", set->strict ? "greater than" : "at least", set->low, set->low);
            put_ratio(above, den);
            proof_add("$.");
        }
        if (!poly_is_one(den)) proof_add(" We look at the numerator and at the denominator.");
        if (!signs(above, above, NULL, 0, set->strict ? SIGN_POSITIVE : SIGN_NONNEGATIVE)) return 0;
        if (!poly_is_one(den) && !signs(den, den, NULL, 0, SIGN_POSITIVE)) return 0;
    }

    /* Diverso da ogni punto tolto: value = h vorrebbe dire num - h den = 0. */
    for (int i = 0; i < set->holes; i++) {
        Poly gap = poly_add(num, poly_mul(poly_const(num_frac(set->hole[i])), den), 1);
        proof_add(" It is not $");
        put_frac(set->hole[i]);
        proof_add("$: that would mean $");
        put_poly(gap);
        proof_add(" = 0$.");
        if (!zero_only_where(gap, NULL)) return 0;
    }
    return 1;
}

/* 18f. Dimostra che ogni divisione scritta nell'espressione node ha il
 * divisore diverso da zero, per ogni valore delle variabili generiche. Scrive
 * il ragionamento, salvo per i divisori che sono numeri, e ritorna 1 se ci
 * riesce.
 *
 * Non entra nelle regole delle applicazioni: che f(x) sia definita per x nel
 * dominio lo stabilisce una volta per tutte map_defined() (18m), e
 * term_check() garantisce che l'argomento stia nel dominio.
 *
 * Si controllano prima le divisioni più interne: un divisore si può calcolare
 * solo se ciò che contiene è definito. */
/* 18y. Ritorna 1 se node è una potenza con esponente un intero negativo
 * scritto in cifre, come b^{-1}: un'espressione razionale, dove la base non
 * è zero. */
static int negative_power(const Node *node) {
    const Node *e = node->kind == N_POW ? node->b : NULL;
    return e && e->kind == N_NEG && e->a->kind == N_NUM && e->a->value >= 1 && e->a->value <= MAX_POWER;
}

static int term_defined(const Node *node) {
    Poly num, den;
    if (!node || node->kind == N_APPLY) return 1;
    if (!term_defined(node->a) || !term_defined(node->b)) return 0;

    /* 18y. Una potenza con esponente intero negativo, come b^{-1}, è una
     * divisione per una potenza della base: la base fa da divisore. */
    if (node->kind == N_POW && negative_power(node)) {
        if (!rat_polynomials(eval(node->a), &num, &den)) return 0;
        if (poly_is_constant(num)) return num.count != 0;
        proof_add(" The base $");
        put_ratio(num, den);
        proof_add("$ of a negative power is never zero.");
        return zero_only_where(num, NULL);
    }
    if (node->kind != N_DIV) return 1;
    if (!rat_polynomials(eval(node->b), &num, &den)) return 0;
    if (poly_is_constant(num)) return num.count != 0;
    proof_add(" The divisor $");
    put_ratio(num, den);
    proof_add("$ is never zero.");
    return zero_only_where(num, NULL);
}

/* =============================================================================
 * 18.3 CONFRONTI E DISGIUNZIONI DI CONFRONTI
 * ============================================================================
 *
 * Le regole 18g, 18h e 18s, che dimostrano "per ogni valore delle variabili
 * generiche vale almeno uno di questi confronti". Ogni confronto diventa un
 * Literal: il numeratore della differenza dei due membri, calcolato dopo
 * aver controllato i divisori (18f), con ciò che si chiede (uguali o
 * diversi) tenuto conto delle negazioni. Un confronto tra espressioni che
 * non sono razionali si decide solo tra numeri (closed_gap()). Qui stanno
 * anche le leggi di De Morgan (junction()), che servono a ogni regola sui
 * connettivi.
 */

/* Un confronto dentro una disgiunzione da dimostrare. */
typedef struct {
    Formula *source;  /* il confronto com'è scritto nell'enunciato */
    int equation;     /* 1 se si chiede che i due membri siano uguali, 0 se
                         diversi: dipende dal confronto e dalle negazioni */
    int cleared;      /* 1 se value è stato ottenuto togliendo denominatori */
    int computed;     /* 1 se il confronto è stato deciso tra numeri, con
                         closed_gap(): allora value è 0 (uguali) o 1 (diversi) */
    Poly value;       /* il numeratore di membro sinistro - membro destro */
} Literal;

/* Ritorna 1 se ogni variabile dell'espressione node ha in questo momento un
 * numero per valore, cioè se l'espressione si può calcolare. shadow elenca
 * gli indici di somma che nascondono una variabile con lo stesso nome. */
static int term_is_closed(const Node *node, const NameScope *shadow) {
    Num value;
    if (!node) return 1;
    if (node->kind == N_VAR) {
        if (name_shadowed(shadow, node->name)) return 1;
        const Rat *bound = env_lookup(node->name);
        return node->name == VAR_PI || (bound && rat_number(*bound, &value));
    }
    if (node->kind == N_BIGOP) {
        if (!term_is_closed(node->a, shadow) || !term_is_closed(node->b, shadow)) return 0;
        NameScope inner = {node->name, shadow};
        return term_is_closed(node->c, &inner);
    }
    return term_is_closed(node->a, shadow) && term_is_closed(node->b, shadow) && term_is_closed(node->c, shadow);
}

/* 18g, per le espressioni che non sono razionali. Calcola i due membri del
 * confronto source, in cui ogni variabile ha un numero per valore, e decide
 * se sono uguali: ritorna 1 se lo sono, 0 se sono diversi, -1 se non lo sa
 * dire o se un membro non è definito.
 *
 * Qui "definito" non si riduce ai divisori: il conto annota le condizioni di
 * esistenza (capitolo 7) e ognuna deve risultare vera, con le regole del
 * paragrafo 13c. Senza questo passo ln(cos 2) = ln(cos 2) sarebbe "la stessa
 * espressione", e quindi vero, pur non esistendo. Che due valori siano
 * diversi si conclude solo se una di quelle regole prova che la differenza
 * non è zero. Un errore di calcolo vuol dire solo che non si sa. */
static int closed_gap(const Formula *source) {
    long long where;
    if (failure || !term_is_closed(source->left, NULL) || !term_is_closed(source->right, NULL)) return -1;
    condition_count = conditions_lost = 0;
    conditions_on = 1;
    Rat gap = rat_add(eval(source->left), eval(source->right), 1);
    conditions_on = 0;
    int answer = failure || conditions_lost ? -1 : 1;
    for (int i = 0; i < condition_count && answer == 1; i++)
        if (condition_decided(&conditions[i], 1, &where) != 1) answer = -1;
    if (answer == 1 && !poly_vanishes(gap.num)) answer = condition_holds(NEVER_ZERO, gap.num, 1, &where) == 1 ? 0 : -1;
    if (failure) answer = -1;
    failure = NULL;
    return answer;
}

/* Come si legge un connettivo tenuto conto della negazione: una congiunzione
 * o una disgiunzione di due parti, ognuna con il suo segno. */
typedef struct {
    int conjunction;  /* 1 congiunzione, 0 disgiunzione */
    Formula *x, *y;   /* le due parti */
    int nx, ny;       /* 1 se la parte va presa negata */
} Junction;

/* Se f è una congiunzione, una disgiunzione o un'implicazione mette in *j il
 * modo di leggerla, negata se negated, e ritorna 1.
 *
 * Leggi di De Morgan: non (A e B) = (non A) o (non B), e viceversa. Per
 * l'implicazione: A implica B = (non A) o B, quindi la sua negazione è
 * A e (non B). */
static int junction(Formula *f, int negated, Junction *j) {
    if (f->kind != F_AND && f->kind != F_OR && f->kind != F_IMPLIES) return 0;
    j->conjunction = (f->kind == F_AND) != negated;
    j->x = f->a;
    j->y = f->b;
    j->nx = f->kind == F_IMPLIES ? !negated : negated;
    j->ny = negated;
    return 1;
}

/* Se f, negata se negated, è un confronto o una disgiunzione di confronti, li
 * aggiunge a literal[] aggiornando *count e ritorna 1. Altrimenti ritorna 0,
 * e literal[] può contenere confronti raccolti a metà, da ignorare. */
static int gather(Formula *f, int negated, Literal *literal, int *count) {
    Junction j;
    if (f->kind == F_NOT) return gather(f->a, !negated, literal, count);
    if (f->kind == F_EQUAL || f->kind == F_DISTINCT) {
        if (*count == MAX_LITERALS) return 0;
        literal[(*count)++] = (Literal){f, (f->kind == F_EQUAL) != negated, 0, 0, {0, NULL}};
        return 1;
    }
    return junction(f, negated, &j) && !j.conjunction &&
           gather(j.x, j.nx, literal, count) && gather(j.y, j.ny, literal, count);
}

/* Scrive "il confronto vale" oppure "il confronto non vale", secondo che ciò
 * che si chiede (uguali se equation) coincida o no con ciò che è scritto. */
static void put_outcome(const Formula *source, int equation) {
    proof_add(" $");
    put_source(source);
    proof_add("$ %s", (source->kind == F_EQUAL) == equation ? "holds" : "fails");
}

/* 18h, prima parte. Divide *h per e finché la divisione è esatta, lasciando
 * in *h il quoziente, e ritorna quante volte ha diviso. e deve essere di primo
 * grado, con coefficiente costante, in una variabile generica x: e = c x + r.
 *
 * Regola di Ruffini. Sia rho = -r/c la radice di e in x. Scritto h come
 * p_d x^d + ... + p_0, con i p_j senza x, il quoziente per x - rho ha
 * coefficienti q_{d-1} = p_d e q_{j-1} = p_j + rho q_j, e il resto è
 * p_0 + rho q_0. La divisione è esatta quando il resto è il polinomio nullo;
 * allora h = (x - rho) Q = e (Q / c). */
static int divide_out(Poly *h, Poly e) {
    for (int i = 0; i < universal_count; i++) {
        int x = atom_var(universal[i].name), times = 0;
        Poly linear[2];
        if (poly_split(e, x, linear, 1) != 1 || !poly_is_constant(linear[1])) continue;
        Num c = linear[1].term[0].coef;
        Poly rho = poly_mul(linear[0], poly_const(num_neg(num_inv(c))));

        for (;;) {
            Poly piece[MAX_UNIVARIATE + 1];
            int degree = poly_split(*h, x, piece, MAX_UNIVARIATE);
            if (degree < 1) break;

            /* carry vale q_j quando comincia il passo j. */
            Poly quotient = poly_const(num_int(0)), carry = piece[degree];
            for (int j = degree - 1; j >= 0; j--) {
                Term power;
                power.coef = num_int(1);
                power.mono.count = 0;
                if (j > 0) power.mono = mono_atom(x, frac_int(j));
                quotient = poly_add(quotient, poly_mul(carry, poly_term(power)), 0);
                carry = poly_add(piece[j], poly_mul(rho, carry), 0);
            }
            if (failure || carry.count != 0) break;
            *h = poly_mul(quotient, poly_const(num_inv(c)));
            times++;
        }
        return times;
    }
    return 0;
}

/* 18x. Ritorna 1 se r è un polinomio a coefficienti interi nelle variabili
 * generiche intere, con esponenti interi non negativi: un intero, per ogni
 * valore delle variabili. */
static int rat_is_integer_polynomial(Rat r) {
    if (!poly_is_one(r.den)) return 0;
    for (int i = 0; i < r.num.count; i++) {
        const Term *t = &r.num.term[i];
        if (t->coef.im.num != 0 || t->coef.re.den != 1) return 0;
        for (int k = 0; k < t->mono.count; k++) {
            int who = universal_index(t->mono.factor[k].atom);
            Frac e = t->mono.factor[k].exp;
            if (who < 0 || !universal[who].numbers->integers || e.den != 1 || e.num < 0) return 0;
        }
    }
    return 1;
}

/* 18x. Ritorna 1 se l'esponente node vale un intero per ogni valore delle
 * variabili generiche, per come è scritto: numeri interi, variabili
 * generiche intere o legate a un polinomio intero in quelle, somme,
 * differenze, prodotti e opposti. */
static int exponent_is_integer(const Node *node) {
    switch (node->kind) {
    case N_NUM:
        return 1;
    case N_VAR: {
        const Rat *bound = env_lookup(node->name);
        if (bound) return rat_is_integer_polynomial(*bound);
        int who = universal_index(atom_var(node->name));
        return who >= 0 && universal[who].numbers->integers;
    }
    case N_NEG:
        return exponent_is_integer(node->a);
    case N_ADD: case N_SUB: case N_MUL:
        return exponent_is_integer(node->a) && exponent_is_integer(node->b);
    default:
        return 0;
    }
}

/* 18x. Ritorna 1 se la base node è un razionale positivo per ogni valore
 * delle variabili generiche, per come è scritta: un numero positivo, o una
 * variabile generica che varia tra i razionali positivi. */
static int base_is_positive(const Node *node) {
    Num value;
    if (node_is_numeral(node)) return rat_number(eval(node), &value) && value.im.num == 0 && value.re.num > 0;

    /* Una potenza intera, un prodotto o un quoziente di numeri positivi è
     * positivo: (x^{n})^{m} ha una base positiva se ce l'ha x^{n}. */
    if (node->kind == N_POW) return exponent_is_integer(node->b) && base_is_positive(node->a);
    if (node->kind == N_MUL || node->kind == N_DIV) return base_is_positive(node->a) && base_is_positive(node->b);

    /* Una variabile legata a un valore (18z la lega a ciò che un'ipotesi
     * dice): positiva se il valore è un monomio con coefficiente positivo
     * nelle lettere positive, come x^{n} con x naturale. */
    const Rat *bound = node->kind == N_VAR ? env_lookup(node->name) : NULL;
    if (bound) {
        Poly num, den;
        if (!rat_polynomials(*bound, &num, &den) || num.count != 1 || den.count != 1) return 0;
        for (int side = 0; side < 2; side++) {
            const Term *t = side ? &den.term[0] : &num.term[0];
            if (t->coef.im.num != 0 || t->coef.re.num <= 0) return 0;
            for (int k = 0; k < t->mono.count; k++) {
                int atom = t->mono.factor[k].atom, who = universal_index(atom);
                const NumberSet *set = who >= 0 ? universal[who].numbers : NULL;
                if (!power_letter(atom) && !(set && set->bounded && (set->low > 0 || (set->low == 0 && set->strict)))) return 0;
            }
        }
        return 1;
    }
    if (node->kind != N_VAR || env_lookup(node->name)) return 0;
    int who = universal_index(atom_var(node->name));
    const NumberSet *set = who >= 0 ? universal[who].numbers : NULL;
    return set && !set->reals && set->bounded && (set->low > 0 || (set->low == 0 && set->strict));
}

/* Ritorna 1 se l'espressione node è razionale in questo momento: lo è per
 * come è scritta (term_is_rational()), oppure lo diventa perché ogni
 * esponente che è una lettera ha adesso per valore un intero non negativo,
 * come quando si prova e = 1 in a^{e} = a. Allora la potenza è un prodotto
 * ripetuto, e le regole sui polinomi si applicano come a ogni altro. */
static int term_is_rational_now(const Node *node) {
    Num exponent;
    if (!node || term_is_rational(node)) return 1;
    switch (node->kind) {
    case N_NEG: case N_ADD: case N_SUB: case N_MUL: case N_DIV: case N_APPLY:
        return term_is_rational_now(node->a) && term_is_rational_now(node->b);
    case N_POW: {
        /* 18x. Durante la ricerca anche una potenza con un esponente intero
         * scritto con le variabili è un numero razionale, se la base è
         * positiva: il conto ne fa delle lettere, e se non ci riesce
         * rat_polynomials() lo dirà. */
        if (power_letters && exponent_is_integer(node->b) && base_is_positive(node->a)) return 1;

        /* 18y. b^{-1}: razionale dove la base non è zero, cosa che
         * term_defined() controlla. */
        if (negative_power(node)) return term_is_rational_now(node->a);
        const Rat *bound = node->b->kind == N_VAR ? env_lookup(node->b->name) : NULL;
        return bound && rat_number(*bound, &exponent) && exponent.im.num == 0 && exponent.re.den == 1 && exponent.re.num >= 0 &&
               exponent.re.num <= MAX_POWER && term_is_rational_now(node->a);
    }
    default:
        return 0;
    }
}

/* Calcola il polinomio di ognuno dei `count` confronti di literal[], il
 * numeratore della differenza dei due membri, dopo aver controllato le
 * divisioni (18f): riempie value, cleared e computed. Ritorna 0 se un
 * confronto non si può trattare; può aver scritto, nella dimostrazione, le
 * frasi sui divisori. */
static int clause_polynomials(Literal *literal, int count) {
    for (int i = 0; i < count; i++) {
        const Formula *source = literal[i].source;
        Poly den;

        /* Espressioni non razionali: solo tra numeri, con closed_gap(). */
        literal[i].computed = !term_is_rational_now(source->left) || !term_is_rational_now(source->right);
        if (literal[i].computed) {
            int equal = closed_gap(source);
            if (equal < 0) return 0;
            literal[i].value = poly_const(num_int(equal ? 0 : 1));
            continue;
        }
        if (!term_defined(source->left) || !term_defined(source->right)) return 0;
        Rat gap = rat_add(eval(source->left), eval(source->right), 1);
        if (failure || !rat_polynomials(gap, &literal[i].value, &den)) return 0;
        literal[i].cleared = !poly_is_one(den);
    }
    return 1;
}

/* 18s. La tesi come combinazione delle ipotesi.
 *
 * "Se x - y = k e y - z = j allora x - z = k + j" usa due ipotesi insieme: la
 * regola 18h ne sa usare una sola, e solo quando la tesi ne è un fattore. Qui
 * le ipotesi sono uguaglianze H_1 = 0, ..., H_m = 0 tra polinomi, la tesi è
 * T = 0, e si cercano dei polinomi c_1, ..., c_m con
 *
 *     T = c_1 H_1 + ... + c_m H_m.
 *
 * Trovarli è una dimostrazione: è un'identità tra polinomi, quindi vale per
 * ogni valore delle variabili, e dove tutte le H_i sono zero lo è anche T.
 * Non trovarli non dice nulla: T può annullarsi dove si annullano le H_i
 * senza esserne una combinazione (H = x^2, T = x), oppure solo tra gli
 * interi. Allora la regola non si applica.
 *
 * Un fattore che non si annulla. A volte la tesi non è una combinazione
 * delle ipotesi ma lo è un suo multiplo: da d a = d b, con d diverso da
 * zero, segue a = b, eppure a - b non è un multiplo di d a - d b. Per questo
 * si cerca anche g T = c_1 H_1 + ... + c_m H_m con g una variabile generica
 * il cui insieme non contiene lo zero: dove le H_i sono zero lo è g T, e
 * poiché g non è zero lo è T. Che g non si annulli lo dimostra, e lo
 * scrive, la regola 18b.
 *
 * La ricerca. Si fissa l'elenco dei "generatori" m H_i, con m un monomio
 * nelle variabili generiche di grado al più top - grado(H_i), dove top è il
 * grado di ciò che si vuole ottenere: i moltiplicatori cercati sono le
 * combinazioni a coefficienti razionali di questi monomi. Trovare i
 * coefficienti è un sistema lineare, risolto per eliminazione: ogni
 * generatore serve a togliere un monomio dai successivi e da T, e alla fine
 * T deve essere diventato il polinomio nullo.
 *
 * Il controllo. I moltiplicatori trovati sono dati: chi chiama ricalcola
 * c_1 H_1 + ... + c_m H_m con prodotti e somme e lo confronta con T. Un
 * errore nell'eliminazione produce moltiplicatori sbagliati, che quel
 * confronto respinge.
 *
 * La stessa ricerca serve alla regola 18u, che tra i moltiplicatori cerca
 * anche il valore di un "esiste": per lei alcuni dei polinomi dati possono
 * avere per moltiplicatore solo un polinomio nelle variabili intere, o in
 * quelle razionali (vedi `need` in combination()): il valore di un "esiste"
 * tra i razionali, scritto con una variabile reale, non si saprebbe
 * razionale (18y).
 */

/* Ritorna il coefficiente con cui il monomio m compare in p, zero se manca. */
static Frac poly_coefficient(Poly p, const Mono *m) {
    for (int i = 0; i < p.count; i++)
        if (mono_cmp(&p.term[i].mono, m) == 0) return p.term[i].coef.re;
    return frac_int(0);
}

/* Ritorna il grado di p: il più alto tra i gradi dei suoi monomi. */
static long long poly_degree(Poly p) {
    long long degree = 0;
    for (int i = 0; i < p.count; i++)
        if (mono_degree(&p.term[i].mono) > degree) degree = mono_degree(&p.term[i].mono);
    return degree;
}

/* Un generatore di 18s: il monomio `by` per l'ipotesi di posto owner. */
typedef struct {
    int owner;  /* quale ipotesi */
    Mono by;    /* il monomio che la moltiplica */
    Poly left;  /* ciò che ne resta durante l'eliminazione */
} Generator;

/* Che cosa vale sempre una lettera dei moltiplicatori di 18s, e che cosa si
 * chiede a quelle del moltiplicatore di un'ipotesi: un numero qualsiasi, un
 * razionale, un intero. L'ordine conta: una lettera va bene per una
 * richiesta se il suo tipo non è più basso. */
enum { LETTER_REAL, LETTER_RATIONAL, LETTER_INTEGER };

/* Le lettere con cui 18s forma i monomi dei moltiplicatori: le variabili
 * generiche, e poi le potenze che fanno da lettere (18x) che compaiono nei
 * polinomi in esame. letter_kind[i] dice che cosa vale sempre la lettera i:
 * una potenza è razionale ma non intera, perché 2^{-n} non lo è, e una
 * variabile reale (18y) solo reale. Le riempie combination(). */
static int *multiplier_letter, *letter_kind, multiplier_letters;
static size_t multiplier_capacity, letter_kind_capacity;

/* Aggiunge una lettera con il suo dominio numerico; entrambi i vettori
 * sono posseduti dal calcolo della combinazione, e riusati tra chiamate. */
static int multiplier_push(int atom, int kind) {
    size_t need = (size_t)multiplier_letters + 1;
    if (!work_reserve((void **)&multiplier_letter, &multiplier_capacity, need, sizeof *multiplier_letter) ||
        !work_reserve((void **)&letter_kind, &letter_kind_capacity, need, sizeof *letter_kind)) return 0;
    letter_kind[multiplier_letters] = kind;
    multiplier_letter[multiplier_letters++] = atom;
    return 1;
}

/* 18x. Aggiunge a multiplier_letter[] le potenze che fanno da lettere nel
 * polinomio p, ognuna una volta, finché c'è posto. */
static void power_letters_add(Poly p) {
    for (int i = 0; i < p.count; i++)
        for (int k = 0; k < p.term[i].mono.count; k++) {
            int atom = p.term[i].mono.factor[k].atom, seen = 0;
            if (!power_letter(atom)) continue;
            for (int j = 0; j < multiplier_letters && !seen; j++) seen = multiplier_letter[j] == atom;
            if (!seen && !multiplier_push(atom, LETTER_RATIONAL)) return;
        }
}

/* Aggiunge a list[], che ha già *count elementi, i generatori dell'ipotesi
 * hypothesis, di posto owner: uno per ogni monomio di grado esattamente
 * degree nelle lettere di multiplier_letter[] da `from` in poi, moltiplicato
 * per `prefix`. Si usano solo le lettere il cui tipo (letter_kind[]) non è
 * più basso di need. Si ferma quando l'elenco è pieno. */
static void generators_add(Generator *list, int *count, Poly hypothesis, int owner, Mono prefix, int from, long long degree, int need) {
    if (degree == 0) {
        Term by = {num_int(1), prefix};
        if (*count < MAX_GENERATORS) list[(*count)++] = (Generator){owner, prefix, poly_mul(hypothesis, poly_term(by))};
        return;
    }
    for (int v = from; v < multiplier_letters && *count < MAX_GENERATORS; v++) {
        if (letter_kind[v] < need) continue;
        Mono letter = mono_atom(multiplier_letter[v], frac_int(1));
        generators_add(list, count, hypothesis, owner, mono_mul(&prefix, &letter), v, degree - 1, need);
    }
}

/* 18s. Cerca di scrivere thesis come combinazione dei `count` polinomi di
 * hypothesis[]: se ci riesce mette in multiplier[i] il polinomio c_i e
 * ritorna 1. I polinomi devono essere "veri" (vedi rat_polynomials()). Ogni
 * prodotto c_i H_i ha grado al più top. Se need non è NULL, il
 * moltiplicatore dell'ipotesi i contiene solo lettere che valgono sempre un
 * intero se need[i] è LETTER_INTEGER, un razionale se è LETTER_RATIONAL.
 *
 * Ogni chiamata toglie alla ricerca in corso un numero di tentativi
 * proporzionale ai generatori: un sistema grande costa quanto molti passi di
 * establish(), e senza questo conto una ricerca che ne risolve migliaia non
 * si fermerebbe più.
 *
 * L'eliminazione. I generatori si esaminano in fila: il primo monomio di
 * ciò che resta di un generatore fa da perno, e un suo multiplo viene tolto
 * da ogni generatore successivo e dalla tesi, in modo che quel monomio non
 * vi compaia più. remove[j][g] ricorda quante volte il generatore g è stato
 * tolto dal generatore j, share[g] quante volte dalla tesi. Se alla fine
 * della tesi non resta nulla, tesi = somma di share[g] per ciò che restava
 * di g; tornando indietro dall'ultimo generatore al primo, ciò che restava
 * di g è g meno i multipli dei precedenti, e i coefficienti dei generatori
 * veri si ottengono correggendo share[] con remove[][]. */
static int combination(Poly thesis, const Poly *hypothesis, int count, Poly *multiplier, long long top, const int *need) {
    static Generator list[MAX_GENERATORS];
    static Frac remove[MAX_GENERATORS][MAX_GENERATORS], share[MAX_GENERATORS];
    Mono one;
    one.count = 0;

    /* Le lettere dei moltiplicatori: le variabili generiche, poi le potenze
     * che fanno da lettere (18x). */
    multiplier_letters = 0;
    for (int v = 0; v < universal_count; v++) {
        const NumberSet *set = universal[v].numbers;

        /* Solo le variabili che compaiono nella tesi o in un'ipotesi: se
         * c'è una combinazione con una lettera che non compare in nessuno di
         * quei polinomi, mettendo zero al suo posto nei moltiplicatori se ne
         * ottiene un'altra, senza. Con le dieci variabili generiche della
         * transitività di una relazione tra numeri complessi (17t-4), i
         * generatori inutili esaurivano i tentativi. */
        int x = atom_var(universal[v].name), used = poly_uses(thesis, x);
        for (int i = 0; i < count && !used; i++) used = poly_uses(hypothesis[i], x);
        if (!used) continue;
        if (!multiplier_push(atom_var(universal[v].name), set->integers ? LETTER_INTEGER : set->reals ? LETTER_REAL : LETTER_RATIONAL)) return 0;
    }
    power_letters_add(thesis);
    for (int i = 0; i < count; i++) power_letters_add(hypothesis[i]);

    /* I generatori, per grado crescente del monomio: se l'elenco si riempie
     * restano fuori i più grandi. */
    int generators = 0;
    for (long long degree = 0; degree <= top; degree++)
        for (int i = 0; i < count; i++)
            if (poly_degree(hypothesis[i]) + degree <= top)
                generators_add(list, &generators, hypothesis[i], i, one, 0, degree, need ? need[i] : LETTER_REAL);
    search_left -= generators / 16;

    /* L'eliminazione. */
    for (int g = 0; g < generators && !failure; g++) {
        share[g] = frac_int(0);
        for (int j = g + 1; j < generators; j++) remove[j][g] = frac_int(0);
        if (list[g].left.count == 0) continue;
        const Mono *pivot = &list[g].left.term[0].mono;
        Frac lead = list[g].left.term[0].coef.re;
        for (int j = g + 1; j < generators; j++) {
            Frac times = frac_div(poly_coefficient(list[j].left, pivot), lead);
            if (times.num == 0) continue;
            remove[j][g] = times;
            list[j].left = poly_add(list[j].left, poly_mul(list[g].left, poly_const(num_frac(times))), 1);
        }
        share[g] = frac_div(poly_coefficient(thesis, pivot), lead);
        if (share[g].num != 0) thesis = poly_add(thesis, poly_mul(list[g].left, poly_const(num_frac(share[g]))), 1);
    }
    if (failure || thesis.count != 0) return 0;

    /* All'indietro: i coefficienti dei generatori veri, e i moltiplicatori. */
    for (int i = 0; i < count; i++) multiplier[i] = poly_const(num_int(0));
    for (int g = generators - 1; g >= 0; g--) {
        for (int k = 0; k < g; k++) share[k] = frac_add(share[k], frac_neg(frac_mul(share[g], remove[g][k])));
        Term part = {num_frac(share[g]), list[g].by};
        if (share[g].num != 0) multiplier[list[g].owner] = poly_add(multiplier[list[g].owner], poly_term(part), 0);
    }
    return !failure;
}

/* 18s. Dimostra che, per ogni valore delle variabili generiche, vale almeno
 * uno dei `count` confronti di literal[], quando hanno la forma "H_1 diverso
 * da 0, oppure ..., oppure T = 0" e T, o T per una variabile che non può
 * valere zero, è una combinazione delle H_i. Scrive il ragionamento, come
 * seguito di un \item già aperto, e ritorna 1 se ci riesce. I confronti che
 * non valgono mai (costanti) non contano. */
static int prove_combination(Literal *literal, int count) {
    Poly hypothesis[MAX_LITERALS], multiplier[MAX_LITERALS];
    const Literal *assumed[MAX_LITERALS], *thesis = NULL;
    int hypotheses = 0, theses = 0;
    if (!clause_polynomials(literal, count)) return 0;
    for (int i = 0; i < count; i++) {
        if (poly_is_constant(literal[i].value)) continue;
        if (literal[i].equation) { thesis = &literal[i]; theses++; continue; }
        hypothesis[hypotheses] = literal[i].value;
        assumed[hypotheses++] = &literal[i];
    }
    if (theses > 1 || !hypotheses || (!theses && hypotheses < 2)) return 0;

    /* Prima la tesi com'è; poi, una per volta, moltiplicata per una
     * variabile generica che non può valere zero. `factor` è il posto di
     * quella variabile, -1 se non è servita.
     *
     * 18v-7. Senza tesi la disgiunzione dice che le H_i non sono zero tutte
     * insieme: basta trovare 1 = c_1 H_1 + ... + c_m H_m, perché dove le H_i
     * fossero tutte zero sarebbe 1 = 0. I moltiplicatori arrivano al grado
     * delle ipotesi. Serve a confronti tra coppie, (x + 1, 2x) \neq (0, 0):
     * 1 = (x + 1) - \frac{1}{2}(2x). */
    Poly target = thesis ? thesis->value : poly_const(num_int(1));
    long long top = poly_degree(target);
    for (int i = 0; i < hypotheses && !thesis; i++)
        if (poly_degree(hypothesis[i]) > top) top = poly_degree(hypothesis[i]);
    int factor = -1, found = combination(target, hypothesis, hypotheses, multiplier, top, NULL);
    for (int v = 0; v < universal_count && !found && thesis && !failure && search_left > 0; v++) {
        if (numbers_contain(universal[v].numbers, frac_int(0))) continue;
        target = poly_mul(thesis->value, rat_atom(atom_var(universal[v].name)).num);
        found = combination(target, hypothesis, hypotheses, multiplier, poly_degree(target), NULL);
        if (found) factor = v;
    }
    if (!found) return 0;

    /* Controllo del passo: rifatto il conto con prodotti e somme, la
     * combinazione deve dare il polinomio cercato. */
    Poly rebuilt = poly_const(num_int(0));
    for (int i = 0; i < hypotheses; i++) rebuilt = poly_add(rebuilt, poly_mul(multiplier[i], hypothesis[i]), 0);
    if (failure) return 0;
    if (!poly_equal(rebuilt, target)) { unjustified_steps++; return 0; }

    /* Il testo: le ipotesi, l'identità, la conclusione. */
    proof_add(" Suppose that");
    for (int i = 0; i < hypotheses; i++) {
        proof_add("%s $", i ? " and that" : "");
        put_source(assumed[i]->source);
        proof_add("$ %s%s that is $", assumed[i]->source->kind == F_EQUAL ? "holds" : "fails", assumed[i]->cleared ? ", after clearing denominators," : ",");
        put_poly(hypothesis[i]);
        proof_add(" = 0$");
    }
    proof_add(". As polynomials, $");
    if (factor >= 0) proof_add("%c\\left(", universal[factor].name);
    put_poly(target);
    proof_add(factor >= 0 ? "\\right) = " : " = ");
    for (int i = 0, written = 0; i < hypotheses; i++) {
        if (multiplier[i].count == 0) continue;
        proof_add("%s\\left(", written++ ? " + " : "");
        put_poly(multiplier[i]);
        proof_add("\\right)\\left(");
        put_poly(hypothesis[i]);
        proof_add("\\right)");
    }
    proof_add("$: multiplying out gives the same terms. So $");
    if (!thesis) {
        proof_add("1 = 0$, which is impossible: the conditions cannot fail together.");
        return 1;
    }

    /* Il fattore: il prodotto è zero, e il fattore non lo è mai (18b). */
    if (factor >= 0) {
        proof_add("%c\\left(", universal[factor].name);
        put_poly(thesis->value);
        proof_add("\\right) = 0$.");
        if (!zero_only_where(rat_atom(atom_var(universal[factor].name)).num, NULL)) return 0;
        proof_add(" Hence $");
    }
    put_poly(thesis->value);
    proof_add(" = 0$, %s $", thesis->source->kind == F_EQUAL ? "that is" : "so");
    put_source(thesis->source);
    proof_add(thesis->source->kind == F_EQUAL ? "$." : "$ fails.");
    return 1;
}

/* Prototipo in avanti inevitabile: quando il fattore che resta a 18h si
 * annulla in un punto, la regola chiede di distinguere quel punto (18v-2, nel
 * capitolo 18.4, che usa le regole di questo). */
static void split_at_zero(Rat gap);

/* 18g, 18h. Dimostra che, per ogni valore delle variabili generiche, vale
 * almeno uno dei `count` confronti di literal[]. Scrive il ragionamento, come
 * seguito di un \item già aperto, e ritorna 1 se ci riesce.
 *
 * Ogni confronto diventa un polinomio, il numeratore della differenza dei due
 * membri: "uguali" vuol dire polinomio zero, "diversi" polinomio non zero.
 *
 *   18g. Se un confronto vale sempre la disgiunzione è dimostrata: un
 *        "uguali" con polinomio nullo, o un "diversi" con una costante non
 *        nulla. È sempre il caso quando non ci sono variabili generiche,
 *        perché allora i polinomi sono numeri. Un confronto tra espressioni
 *        non razionali si decide solo così, tra numeri, e con le condizioni
 *        di esistenza controllate (closed_gap()).
 *   18h. Tolti i confronti che non valgono mai, la forma trattata è
 *        "p diverso da 0, oppure e = 0", cioè "p = 0 implica e = 0", anche
 *        senza la seconda parte. Si divide p per e finché si può (p = e^k q:
 *        dove e non è zero, p è zero solo se lo è q), poi si chiede a
 *        zero_only_where() che q si annulli al più dove si annulla e.
 *
 * Una disgiunzione di soli "uguali" non identici non può valere per ogni
 * valore: il prodotto dei polinomi non è nullo, e gli insiemi sono infiniti. */
static int prove_clause(Literal *literal, int count) {
    if (!clause_polynomials(literal, count)) return 0;

    /* 18g. Un confronto che vale sempre. Se i due membri sono numeri si
     * riportano, così il lettore può rifare il conto. */
    for (int i = 0; i < count; i++) {
        const Literal *l = &literal[i];
        Num left, right;
        int always = l->equation ? l->value.count == 0 : (poly_is_constant(l->value) && l->value.count != 0);
        if (!always) continue;
        put_outcome(l->source, l->equation);
        if (l->computed) {
            proof_add(l->equation ? ": computed exactly, the two sides are equal." : ": computed exactly, the two sides are different.");
        } else if (rat_number(eval(l->source->left), &left) && rat_number(eval(l->source->right), &right)) {
            proof_add(l->equation ? ": both sides are equal to $" : ": the two sides are $");
            put_frac(left.re);
            if (!l->equation) { proof_add("$ and $"); put_frac(right.re); }
            proof_add("$.");
        } else if (l->equation) {
            proof_add(": written out, the two sides are the same expression.");
        } else {
            proof_add(": the difference of the two sides has the numerator $");
            put_poly(l->value);
            proof_add("$, a constant that is not zero.");
        }
        return 1;
    }

    /* 18h. Restano i confronti che dipendono dalle variabili: le costanti
     * rimaste sono confronti che non valgono mai. */
    const Literal *distinct = NULL, *equal = NULL;
    for (int i = 0; i < count; i++) {
        if (poly_is_constant(literal[i].value)) continue;
        if (!literal[i].equation && !distinct) distinct = &literal[i];
        else if (literal[i].equation && !equal) equal = &literal[i];
        else return 0;
    }
    if (!distinct) return 0;
    Poly h = distinct->value;
    const char *clearing = distinct->cleared ? ", after clearing denominators," : "";

    /* Un solo "diversi": il polinomio non deve annullarsi mai. */
    if (!equal) {
        int written_equal = distinct->source->kind == F_EQUAL;
        proof_add(written_equal ? " The equality $" : " The condition $");
        put_source(distinct->source);
        proof_add(written_equal ? "$%s would mean $" : "$%s means $", clearing);
        put_poly(h);
        proof_add(written_equal ? " = 0$." : " \\neq 0$.");
        if (!zero_only_where(h, NULL)) return 0;
        if (written_equal) proof_add(" So the equality never holds.");
        return 1;
    }

    /* "Diversi oppure uguali": p = 0 deve implicare e = 0. */
    Poly e = equal->value;
    proof_add(" Suppose that $");
    put_source(distinct->source);
    proof_add("$ %s%s that is $", distinct->source->kind == F_EQUAL ? "holds" : "fails", distinct->cleared ? clearing : ",");
    put_poly(h);
    proof_add(" = 0$.");
    int times = divide_out(&h, e);

    /* Controllo del passo: rimoltiplicando i fattori si deve ritrovare il
     * polinomio di partenza. La divisione è fatta con la regola di Ruffini,
     * il controllo con il prodotto. */
    Poly rebuilt = h;
    for (int i = 0; i < times; i++) rebuilt = poly_mul(rebuilt, e);
    if (failure) return 0;
    if (!poly_equal(rebuilt, distinct->value)) { unjustified_steps++; return 0; }
    if (times && !poly_is_one(h)) {
        proof_add(" Now $");
        put_poly(distinct->value);
        proof_add(" = ");
        put_factor(h);

        /* Il fattore e: tra parentesi se ha più termini o un esponente. */
        int brackets = e.count > 1 || times > 1;
        proof_add(brackets ? "\\left(" : " \\cdot ");
        put_poly(e);
        if (brackets) proof_add("\\right)");
        if (times > 1) proof_add("^{%d}", times);
        proof_add("$.");
    }
    if (!poly_is_one(h) && !zero_only_where(h, &e)) {
        split_at_zero((Rat){h, poly_const(num_int(1))});
        return 0;
    }
    proof_add(" Hence $");
    put_poly(e);
    proof_add(" = 0$, ");
    proof_add(equal->source->kind == F_EQUAL ? "that is $" : "so $");
    put_source(equal->source);
    proof_add(equal->source->kind == F_EQUAL ? "$." : "$ fails.");
    return 1;
}

/* 18z. SOSTITUIRE UN'IPOTESI
 *
 * A che cosa serve. "Se y = a x e x = b y allora x = y", con x, y naturali
 * e a, b interi: la tesi non è una combinazione delle ipotesi (18s), perché
 * è vera solo grazie ai segni. Un matematico scrive: "metto a x al posto di
 * y; allora x = b a x, cioè x (1 - a b) = 0". Da lì la regola dei segni con
 * guardia (18c) conclude: con a = 1 + a', b = 1 + b' (18y-4 sa che a e b
 * sono naturali) e x = 1 + x', x - a b x ha tutti i coefficienti negativi e
 * i termini a' e b', quindi si annulla solo se a' = b' = 0, e allora x - a x
 * = 0. La regola dei segni fa da sola la parte "un prodotto di naturali che
 * vale 1 ha tutti i fattori uguali a 1".
 *
 * La regola. Tra i confronti di una disgiunzione da dimostrare, un "diversi"
 * è un'ipotesi H = 0. Se H è di primo grado in una variabile generica v, con
 * un coefficiente c che è un numero, H = c v + R con R senza v, allora dove
 * vale l'ipotesi v = -R/c. Si lega v a quel valore e si dimostrano le altre
 * parti, ricalcolate con v al suo posto, per ogni valore delle variabili che
 * restano: dove l'ipotesi vale, le parti valgono quanto le loro copie
 * ricalcolate, e dove non vale la disgiunzione è già vera. È lecito anche
 * se v ha un insieme: lo si dimentica, e si dimostra di più.
 *
 * Perché il calcolo e non i polinomi. Le altre parti si ricalcolano dalle
 * loro espressioni, con v legata, e non sostituendo nei polinomi: così anche
 * una potenza di v cambia, y^{m} con y = x^{n} diventa x^{n m} (18x), ed è
 * ciò che serve alla transitività di "y è una potenza di x".
 *
 * Il controllo del passo. Anche l'ipotesi si ricalcola con v legata, e deve
 * diventare il polinomio nullo: se v comparisse anche dentro un altro atomo
 * di H, come in y - 2^{y}, il valore -R/c non risolverebbe l'ipotesi, e la
 * regola non si applica. Le sostituzioni una dopo l'altra sono al più
 * MAX_SUBSTITUTIONS. */

/* Quante sostituzioni 18z fa una dopo l'altra, al più. */
#define MAX_SUBSTITUTIONS 2

/* 18z. Dimostra che, per ogni valore delle variabili generiche, vale almeno
 * uno dei `count` confronti di literal[], sostituendo una variabile con il
 * valore che un'ipotesi le dà (vedi la testa del paragrafo) e passando il
 * resto a 18h, a 18s o a un'altra sostituzione, al più `depth`. Scrive il
 * ragionamento, come seguito di un \item già aperto, e ritorna 1 se ci
 * riesce; se ritorna 0 il testo scritto va cancellato da chi chiama. */
static int prove_by_substitution(Literal *literal, int count, int depth) {
    Mark mark = mark_here();
    if (depth <= 0 || count < 2 || failure || !clause_polynomials(literal, count)) return 0;
    rollback(mark);
    for (int i = 0; i < count; i++) {
        if (literal[i].equation || literal[i].computed) continue;
        for (int v = 0; v < universal_count && !failure && search_left > 0; v++) {
            int name = universal[v].name;
            Poly part[2], shown_num, shown_den;
            if (env_lookup(name) || poly_split(literal[i].value, atom_var(name), part, 1) != 1 || !poly_is_constant(part[1])) continue;
            Rat value = rat_make(poly_negate(part[0]), part[1]);
            if (!rat_polynomials(value, &shown_num, &shown_den)) continue;

            /* Il controllo del passo: l'ipotesi, con v al suo valore. */
            Literal again = literal[i];
            env_push(name, value);
            int solved = clause_polynomials(&again, 1) && again.value.count == 0 && !failure;
            rollback(mark);
            if (!solved) { env_pop(); continue; }

            /* Le altre parti, ricalcolate. */
            Literal rest[MAX_LITERALS];
            int left = 0;
            for (int j = 0; j < count; j++)
                if (j != i) rest[left++] = literal[j];
            proof_add(" Suppose that $");
            put_source(literal[i].source);
            proof_add("$ %s: then $%c = ", literal[i].source->kind == F_EQUAL ? "holds" : "fails", name);
            put_ratio(shown_num, shown_den);
            proof_add("$, and we write that in place of $%c$.\n\\item", name);
            Mark inner = mark_here();
            int proved = prove_clause(rest, left);
            if (!proved && !failure) { rollback(inner); proved = prove_combination(rest, left); }

            /* Una disgiunzione vale se ne vale una parte: si prova anche con
             * una sola ipotesi accanto agli "uguali", quando le altre
             * parlano d'altro (le componenti b, d accanto ad a, c). */
            for (int j = 0; j < left && left > 2 && !proved && !failure; j++) {
                Literal some[MAX_LITERALS];
                int kept = 0;
                if (rest[j].equation) continue;
                for (int k = 0; k < left; k++)
                    if (k == j || rest[k].equation) some[kept++] = rest[k];
                rollback(inner);
                proved = prove_clause(some, kept);
            }
            if (!proved && !failure) { rollback(inner); proved = prove_by_substitution(rest, left, depth - 1); }
            env_pop();
            if (proved) return 1;
            rollback(mark);
        }
    }
    return 0;
}

/* =============================================================================
 * 18.4 "PER OGNI" ED "ESISTE": INDUZIONE, CASI, EQUAZIONI
 * ============================================================================
 *
 * Le regole che dimostrano un quantificatore con un metodo proprio, quando
 * introdurre una variabile generica (18k) non basta: "per ogni n" di
 * un'uguaglianza per induzione (18n), "per ogni x" intero per casi sul resto
 * in una divisione (18o), per casi chiesti da ciò che si sta dimostrando
 * (18v: i casi di un'applicazione definita per casi, o i lati di un numero
 * per il valore di un "esiste"), "esiste x" risolvendo un'equazione in x
 * (18i), anche caso per caso (18v-3). L'induzione è il metodo del capitolo
 * 13; le altre dimostrano ciò che resta chiamando establish() (18.6), con la
 * variabile legata al caso in esame o al valore trovato.
 */

/* Prototipo in avanti inevitabile: establish() (18.6) e le regole 18i, 18o e
 * 18u (18.4, 18.5) si chiamano a vicenda. */
static int establish(Formula *f, int negated);

/* Ritorna 1 se la lettera name compare nel sotto-albero node, come variabile,
 * come indice di una somma o come nome di una successione. */
static int node_uses_letter(const Node *node, int name) {
    if (!node) return 0;
    if (node->name == name && (node->kind == N_VAR || node->kind == N_BIGOP || node->kind == N_SEQ || node->kind == N_APPLY)) return 1;
    return node_uses_letter(node->a, name) || node_uses_letter(node->b, name) || node_uses_letter(node->c, name);
}

/* Ritorna 1 se la lettera name compare nella condizione f: quantificata, o
 * dentro un'espressione. */
static int formula_uses_letter(const Formula *f, int name) {
    if (!f) return 0;
    if ((f->kind == F_FORALL || f->kind == F_EXISTS) && f->variable == name) return 1;
    return node_uses_letter(f->left, name) || node_uses_letter(f->right, name) ||
           formula_uses_letter(f->a, name) || formula_uses_letter(f->b, name);
}

/* Ritorna 1 se l'espressione node dipende dalla lettera name: la scrive,
 * oppure la scrive la regola, o uno dei casi, di un'applicazione che node
 * calcola, come il parametro b di f(n) = a n + b (17s). */
static int node_mentions(const Node *node, int name) {
    if (!node) return 0;
    if (node->kind == N_VAR && node->name == name) return 1;
    const Map *map = node->kind == N_APPLY ? map_find(node->name) : NULL;
    if (map && node_uses_letter(map->body, name)) return 1;
    for (int k = 0; map && k < map->cases; k++)
        if (node_uses_letter(map->piece[k].value, name) || formula_uses_letter(map->piece[k].when, name)) return 1;
    return node_mentions(node->a, name) || node_mentions(node->b, name) || node_mentions(node->c, name);
}

/* Come formula_uses_letter(), contando anche le lettere delle regole delle
 * applicazioni calcolate (node_mentions()). */
static int formula_mentions(const Formula *f, int name) {
    if (!f) return 0;
    if ((f->kind == F_FORALL || f->kind == F_EXISTS) && f->variable == name) return 1;
    return node_mentions(f->left, name) || node_mentions(f->right, name) || formula_mentions(f->a, name) || formula_mentions(f->b, name);
}

/* 18n. Dimostra "per ogni n in A vale L = R" per induzione su n, quando A è
 * un insieme di interi da un certo punto in su e non ci sono altre variabili
 * in gioco. all è il nodo del quantificatore ed equation il confronto.
 * Scrive la dimostrazione, con i suoi passaggi, e ritorna 1 se ci riesce.
 *
 * È il metodo del capitolo 13 usato come una regola: lì arriva un enunciato
 * intero, qui un pezzo di un enunciato più grande. Le due espressioni sono
 * già alberi dello stesso tipo, quindi non c'è nulla da rileggere.
 *
 * L'induzione vuole la tabella degli atomi per sé: un atomo ricorda se
 * dipende dalla variabile di induzione, e quelli nati finora sono stati
 * creati senza saperlo. La tabella viene quindi messa da parte e ripristinata
 * alla fine, com'era: i valori scelti per gli "esiste" già dimostrati, che la
 * verifica rileggerà, contengono i numeri d'ordine dei vecchi atomi. */
static int by_induction(const Formula *all, const Formula *equation) {
    static Atom kept_atoms[MAX_ATOMS];
    static Poly kept_polys[MAX_ATOMS];
    static Rat kept_atans[MAX_ATOMS];
    Statement statement = {equation->left, equation->right, REL_EQ};
    int atoms_before = atom_count, polys_before = base_poly_count, atans_before = atan_count, variable_before = induction_var;
    long long default_before = default_base, floor_before = domain_floor;
    size_t arena_before = arena_used, start = proof_length;
    const char *syntax_before = syntax_error;

    /* Via la tabella di prima; l'arena continua da dov'è. */
    memcpy(kept_atoms, atoms, sizeof(Atom) * (size_t)atoms_before);
    memcpy(kept_polys, base_polys, sizeof(Poly) * (size_t)polys_before);
    memcpy(kept_atans, atan_args, sizeof(Rat) * (size_t)atans_before);
    atom_count = base_poly_count = atan_count = 0;

    proof_add("\\item We prove $");
    put_source(equation);
    proof_add("$ for every $%c \\in ", all->variable);
    put_numbers(&all->numbers);
    proof_add("$.\n");
    int proved = induct(&statement, all->variable, 1, all->numbers.low + all->numbers.strict, 1).outcome == PROVED;
    if (!proved) proof_cut(start);

    /* Tutto com'era. Un errore dell'induzione vuol dire solo che questa
     * regola non si applica. */
    memcpy(atoms, kept_atoms, sizeof(Atom) * (size_t)atoms_before);
    memcpy(base_polys, kept_polys, sizeof(Poly) * (size_t)polys_before);
    memcpy(atan_args, kept_atans, sizeof(Rat) * (size_t)atans_before);
    atom_count = atoms_before;
    base_poly_count = polys_before;
    atan_count = atans_before;
    induction_var = variable_before;
    default_base = default_before;
    domain_floor = floor_before;
    arena_used = arena_before;
    syntax_error = syntax_before;
    failure = NULL;
    env_count = 0;
    return proved;
}

/* 18o. Dimostra "per ogni x in A vale P", con A un insieme di interi senza
 * punti tolti, per casi sul resto di x in una divisione. f è il nodo del
 * quantificatore e negated il segno con cui va letta P. Scrive la
 * dimostrazione e ritorna 1 se ci riesce; se ritorna 0 il testo scritto va
 * cancellato da chi chiama.
 *
 * Divisione con resto: fissato m > 0, ogni intero x si scrive in un solo
 * modo come x = m t + r, con t intero e r tra 0 e m - 1. Dimostrare P per
 * ogni x equivale quindi a dimostrarla per x = m t + r, per ogni t, in
 * ognuno degli m casi. In ciascun caso x è legata all'espressione m t + r, e
 * t è una variabile generica nuova: le altre regole lavorano come sempre. È
 * così che "ogni intero è pari o dispari" si riduce a due equazioni di primo
 * grado: con x = 2 t si prende y = t, con x = 2 t + 1 ancora y = t.
 *
 * Il modulo non si conosce in anticipo: si provano m = 2, 3, ... fino a
 * MAX_CASES. Se x deve stare in A = {x >= a}, allora m t + r >= a, cioè t
 * parte dal più piccolo intero non minore di (a - r)/m.
 *
 * Un caso dentro l'altro non si fa: il valore scelto per un "esiste" è
 * ricordato caso per caso (vedi Formula), con un solo numero di caso. */
static int by_remainders(Formula *f, int negated) {
    static char written[48];
    const NumberSet *set = &f->numbers;
    int quotient = 0;
    if (!set->integers || set->holes || split_modulus || failure) return 0;

    /* Una lettera per il quoziente che l'enunciato non usa. */
    for (const char *letter = "tsuvwpqhgedcba"; *letter && !quotient; letter++) {
        int taken = map_find(*letter) != NULL || formula_uses_letter(f, *letter) || env_lookup(*letter) != NULL;
        for (int i = 0; i < universal_count; i++) taken = taken || universal[i].name == *letter;
        if (!taken) quotient = *letter;
    }
    if (!quotient) return 0;

    /* I tentativi di questa regola sono contati a parte: provare cinque
     * moduli non deve consumare la ricerca di chi sta intorno. */
    int outside = search_set_aside();
    for (int m = 2; m <= MAX_CASES && search_left > 0 && !failure; m++) {
        Mark mark = mark_here();
        int holds = 1;
        proof_add("\\item Every integer is $%d%c + r$ for exactly one integer $%c$ and one $r$ among $0", m, quotient, quotient);
        for (int r = 1; r < m; r++) proof_add(", %d", r);
        proof_add("$: division by $%d$ with remainder. So there are $%d$ cases.\n", m, m);
        split_modulus = m;
        for (int r = 0; r < m && holds; r++) {
            /* L'insieme in cui varia il quoziente, e come scriverlo. */
            NumberSet part = {0};
            long long first = set->low + set->strict - r;
            part.integers = 1;
            part.bounded = set->bounded;
            part.low = first >= 0 ? (first + m - 1) / m : -((-first) / m);
            if (!part.bounded) snprintf(written, sizeof written, "\\mathbb{Z}");
            else if (part.low == 0 || part.low == 1) snprintf(written, sizeof written, part.low ? "\\mathbb{N}" : "\\mathbb{N}_{0}");
            else snprintf(written, sizeof written, "\\{%lld, %lld, \\ldots\\}", part.low, part.low + 1);
            part.start = written;
            part.end = written + strlen(written);

            proof_add("\\item \\emph{Case $%c = %d%c", f->variable, m, quotient);
            if (r) proof_add(" + %d", r);
            proof_add("$}, with $%c \\in %s$.\n\\begin{itemize}\n", quotient, written);

            /* x legata a m t + r, e t generica. */
            split_case = r;
            if (!universal_push((Bound){quotient, &part})) return 0;
            env_push(f->variable, rat_add(rat_mul(rat_int(m), rat_atom(atom_var(quotient))), rat_int(r), 0));
            holds = establish(f->a, negated);
            env_pop();
            universal_count--;
            proof_add("\\end{itemize}\n");
        }
        split_modulus = split_case = 0;
        if (holds) {
            f->modulus = m;
            f->quotient = quotient;
            search_left += outside;
            return 1;
        }
        rollback(mark);
    }
    search_left += outside;
    return 0;
}

/* 18v. LE APPLICAZIONI DEFINITE PER CASI, E LE DISTINZIONI DI CASI
 *
 * A che cosa serve. "f(n) = 2n se n è pari, 5n se n è dispari: f è
 * iniettiva." Un matematico distingue i casi, n = 2s e n = 2s + 1, e in
 * ognuno f(n) è un polinomio. Le regole di questo paragrafo fanno lo stesso,
 * in tre passi.
 *
 *   18v-1. Il caso di f(t). Prima di calcolare una condizione in cui compare
 *          f(t), con f definita per casi (17s) e t un'espressione nelle
 *          variabili generiche, si dimostra la condizione di uno dei casi
 *          per tutti i loro valori: allora f(t) è il valore di quel caso.
 *          Lo dice l'ipotesi stessa, "se vale la condizione allora f(t) è
 *          quel valore", e non serve altro. Le condizioni si dimostrano con
 *          le regole di sempre: 18d per "m divide v" (il quoziente è un
 *          intero), 18c per i confronti d'ordine, 18b per "diverso", 18e per
 *          le appartenenze; e "u non divide v" in due modi: v = m q + c con
 *          q intero e c non multiplo del numero m, oppure v = w + u q con q
 *          intero e "u non divide w" noto nel caso in esame (18v-4).
 *   18v-2. Distinguere i casi. Quando nessuna condizione si sa dimostrare,
 *          la regola annota che cosa servirebbe sapere di una variabile
 *          generica y (split_wanted): un resto (y = 2s oppure 2s + 1), un
 *          lato di un numero (y \ge 2 oppure y \le 1), un punto (y = -2
 *          oppure no), l'essere un intero o un multiplo di k. Il "per ogni"
 *          che ha introdotto y (18k) raccoglie la richiesta e ripete la
 *          dimostrazione in ognuno dei casi. È lecito perché i casi coprono
 *          l'insieme di y per come sono fatti: un resto tra 0 e M - 1, un
 *          lato o l'altro di un numero, un punto o il resto, una proprietà
 *          o la sua negazione. La stessa richiesta la fa chi cerca il
 *          valore di un "esiste" (18i) e trova un valore che sta
 *          nell'insieme solo da un lato di un numero (x = 2y + 2 è in
 *          \mathbb{N} solo per y \ge 0), o un coefficiente che si annulla in
 *          un punto.
 *   18v-3. "Esiste x con f(x) = y". Per trovare x si prova ogni caso: la sua
 *          equazione, risolta da 18i, dà un valore, oppure il caso stesso è
 *          un punto (x = -2). Il valore è solo una proposta: con x legata a
 *          lui, 18v-1 dimostra da capo quale caso vale, e l'uguaglianza si
 *          ricontrolla.
 *
 * In un caso nato da 18v-2 la variabile cambia: diventa 2s + 1, o -1 - s con
 * s \ge 0, oppure resta y ma in un insieme più piccolo (y \ge 2, y \neq -2,
 * y intero), oppure le si affianca un fatto "u non divide y" (excluded[]).
 * Così le regole dei capitoli precedenti vedono di nuovo polinomi in
 * variabili generiche, e i fatti del caso stanno nei loro insiemi.
 *
 * Quante distinzioni. Ogni caso può chiederne un'altra, fino a
 * MAX_REGION_DEPTH una dentro l'altra: un'iniettività ne vuole due (una su
 * a, una su b), qualcuna in più quando i casi della definizione si
 * intrecciano con quelli del valore di un "esiste". Poi la ricerca si
 * ferma. Una richiesta che parla di una variabile più esterna passa al "per
 * ogni" che l'ha introdotta; tra più richieste vale la prima.
 *
 * La verifica. Ogni distinzione divide l'insieme in parti che lo coprono, e
 * in ogni parte valgono le regole di sempre. Il capitolo 19 ricontrolla
 * comunque tutto sui numeri: f si calcola con i numeri (11v), i casi della
 * definizione si ricontrollano punto per punto (map_holds_on_sample()), e i
 * valori degli "esiste" scelti dentro una distinzione la verifica li cerca
 * da sé (witness_keep()).
 */

/* Scrive la condizione c di un caso, negata se negated, con i valori del
 * momento: ogni confronto tra $...$, i connettivi a parole. Le
 * disuguaglianze si scrivono nel verso in cui le ha scritte l'enunciato. */
static void put_condition(const Formula *c, int negated) {
    if (c->kind == F_NOT) { put_condition(c->a, !negated); return; }
    if (c->kind == F_AND || c->kind == F_OR) {
        put_condition(c->a, negated);
        proof_add((c->kind == F_AND) != negated ? " and " : " or ");
        put_condition(c->b, negated);
        return;
    }
    Rat u = eval(c->left);
    proof_add("$");
    switch (c->kind) {
    case F_EQUAL: case F_DISTINCT:
        put_fraction(u);
        proof_add((c->kind == F_EQUAL) != negated ? " = " : " \\neq ");
        put_fraction(eval(c->right));
        break;
    case F_LESS: case F_LESS_EQ: {
        /* u < v e u \le v; negate, v \le u e v < u. */
        int strict = (c->kind == F_LESS) != negated;
        Rat v = eval(c->right), low = negated ? v : u, high = negated ? u : v;
        if (c->swapped) { put_fraction(high); proof_add(strict ? " > " : " \\ge "); put_fraction(low); }
        else { put_fraction(low); proof_add(strict ? " < " : " \\le "); put_fraction(high); }
        break;
    }
    case F_DIVIDES:
        put_fraction(u);
        proof_add(c->swapped == negated ? " \\mid " : " \\nmid ");
        put_fraction(eval(c->right));
        break;
    case F_IN:
        put_fraction(u);
        proof_add(c->swapped == negated ? " \\in " : " \\notin ");
        put_numbers(&c->numbers);
        break;
    default:
        break;
    }
    proof_add("$");
}

/* Scrive " + c" oppure " - |c|". */
static void put_added(Frac c) {
    proof_add(c.num < 0 ? " - " : " + ");
    put_frac(c.num < 0 ? frac_neg(c) : c);
}

/* 18v-1. Dimostra che u non divide v per ogni valore delle variabili
 * generiche, in uno dei due modi descritti in testa al paragrafo. Scrive il
 * ragionamento e ritorna 1 se ci riesce; altrimenti il testo va cancellato
 * da chi chiama.
 *
 * Perché basta. Con u = m un numero e v = m q + c, dove q vale sempre un
 * intero: v/m = q + c/m, intero esattamente quando lo è c/m. Con v = w + u q
 * e q intero: v/u = w/u + q, intero esattamente quando lo è w/u. */
static int not_multiple(Rat u, Rat v) {
    Poly num, den, q, d, one = poly_const(num_int(1));
    Num m;
    if (failure) return 0;

    /* v = m q + c, con c il termine noto di v. */
    if (rat_number(u, &m) && m.im.num == 0 && m.re.num != 0 && rat_polynomials(v, &num, &den) && poly_is_one(den)) {
        Num c = num_int(0);
        for (int i = 0; i < num.count; i++)
            if (num.term[i].mono.count == 0) c = num.term[i].coef;
        Rat rest = rat_div(rat_add(v, (Rat){poly_const(c), one}, 1), u);
        if (!failure && c.im.num == 0 && !number_divides(m, c) && rat_polynomials(rest, &q, &d) && poly_is_one(d)) {
            size_t start = proof_length;
            proof_add(" Indeed $");
            put_poly(num);
            proof_add(" = ");
            put_frac(m.re);
            proof_add(" q");
            put_added(c.re);
            proof_add("$ with $q = ");
            put_poly(q);
            proof_add("$.");
            if (always_integer(q)) {
                proof_add(" The number $");
                put_frac(m.re);
                proof_add("$ does not divide $");
                put_frac(c.re);
                proof_add("$.");
                return 1;
            }
            proof_cut(start);
        }
    }

    /* v = w + u q, o v = -w + u q, con "u non divide w" noto nel caso in
     * esame: u divide v esattamente quando divide w, perché divide w
     * quando divide -w. Se v è w stessa, è il fatto del caso. */
    for (int e = 0; e < 2 * excluded_count && !failure; e++) {
        const Exclusion *x = &excluded[e / 2];
        int opposite = e % 2;
        Rat same = rat_add(x->divisor, u, 1);
        if (failure || same.num.count != 0) continue;
        Rat rest = rat_div(rat_add(v, (Rat){x->value, one}, !opposite), u);
        if (failure || !rat_polynomials(rest, &q, &d) || !poly_is_one(d)) continue;
        if (q.count == 0 && !opposite) { proof_add(" It is the fact of this case."); return 1; }
        size_t start = proof_length;
        proof_add(" Indeed $");
        put_fraction(v);
        proof_add(" = %s", opposite ? "-\\left(" : "");
        put_poly(x->value);
        proof_add("%s + ", opposite ? "\\right)" : "");
        put_fraction(u);
        proof_add(" q$ with $q = ");
        put_poly(q);
        proof_add("$.");
        if (always_integer(q)) {
            proof_add(" In this case $");
            if (rat_number(u, &m) && num_equal(m, num_int(1))) {
                put_poly(x->value);
                proof_add(" \\notin \\mathbb{Z}$.");
            } else {
                put_fraction(u);
                proof_add(" \\nmid ");
                put_poly(x->value);
                proof_add("$.");
            }
            return 1;
        }
        proof_cut(start);
    }
    return 0;
}

/* 18v-1. Dimostra la condizione c di un caso, negata se negated, per ogni
 * valore delle variabili generiche; la variabile della regola è già legata
 * al valore dell'argomento. Scrive, per ogni confronto, che vale e perché, e
 * ritorna 1 se ci riesce; altrimenti il testo va cancellato da chi chiama. */
static int case_proved(const Formula *c, int negated) {
    Poly num, den;
    if (failure) return 0;
    if (c->kind == F_NOT) return case_proved(c->a, !negated);
    if (c->kind == F_AND || c->kind == F_OR) {
        if ((c->kind == F_AND) != negated) return case_proved(c->a, negated) && case_proved(c->b, negated);
        size_t start = proof_length;
        if (case_proved(c->a, negated)) return 1;
        proof_cut(start);
        return case_proved(c->b, negated);
    }

    /* Tra numeri si calcola. */
    proof_add(" ");
    put_condition(c, negated);
    proof_add(" holds.");
    int computed = condition_computed(c);
    if (failure) return 0;
    if (computed >= 0) {
        if ((computed == 1) == negated) return 0;
        proof_add(" Computed with the numbers.");
        return 1;
    }

    /* Altrimenti, una regola per ogni tipo di confronto. */
    Rat u = eval(c->left), v = c->kind == F_IN ? rat_int(0) : eval(c->right);
    if (failure) return 0;
    switch (c->kind) {
    case F_EQUAL: case F_DISTINCT:
        /* Uguali: la differenza è il polinomio nullo. Diversi: il suo
         * numeratore non si annulla, e il denominatore nemmeno, perché la
         * differenza esista. */
        if (!rat_polynomials(rat_add(u, v, 1), &num, &den)) return 0;
        if ((c->kind == F_EQUAL) != negated) {
            if (num.count) return 0;
            proof_add(" The two sides are the same expression.");
            return 1;
        }
        if (!poly_is_constant(den)) {
            proof_add(" The difference of the two sides has the denominator $");
            put_poly(den);
            proof_add("$.");
            if (!zero_only_where(den, NULL)) return 0;
        }
        proof_add(" The difference of the two sides has the numerator $");
        put_poly(num);
        proof_add("$.");
        return zero_only_where(num, NULL);
    case F_LESS: case F_LESS_EQ: {
        /* u < v vuol dire v - u > 0; la negazione u - v \ge 0. */
        int strict = (c->kind == F_LESS) != negated;
        Rat gap = negated ? rat_add(u, v, 1) : rat_add(v, u, 1);
        if (!rat_polynomials(gap, &num, &den) || !poly_is_one(den)) return 0;
        return signs(num, num, NULL, 0, strict ? SIGN_POSITIVE : SIGN_NONNEGATIVE);
    }
    case F_DIVIDES:
        if (c->swapped != negated) return not_multiple(u, v);
        if (u.num.count == 0 || !rat_polynomials(rat_div(v, u), &num, &den) || !poly_is_one(den)) return 0;
        proof_add(" The quotient is $");
        put_poly(num);
        proof_add("$.");
        return always_integer(num);
    case F_IN:
        if (c->swapped == negated) return always_in(u, &c->numbers);
        return c->numbers.integers && !c->numbers.bounded && !c->numbers.holes && not_multiple(rat_int(1), u);
    default:
        return 0;
    }
}

/* 18v-2. Che cosa si distingue: vedi Split. */
typedef enum {
    SPLIT_ORDER,    /* un lato o l'altro del numero at */
    SPLIT_POINT,    /* il numero at, o tutti gli altri */
    SPLIT_RESIDUE,  /* il resto nella divisione per modulus */
    SPLIT_MEMBER,   /* alpha y + beta multiplo del numero divisor, o no: per y razionale */
    SPLIT_DIVISOR   /* y multiplo di divisor, o no: per y intero */
} SplitKind;

/* Una distinzione di casi richiesta per una variabile generica y (18v-2):
 * che cosa servirebbe sapere di y per proseguire. */
typedef struct {
    int atom;           /* y, come atomo */
    SplitKind kind;
    Frac at;            /* ORDER, POINT: il numero */
    int upper_closed;   /* ORDER: 1 se at sta con i valori più grandi (y \ge at
                           oppure y < at), 0 se con i più piccoli (y > at
                           oppure y \le at) */
    long long modulus;  /* RESIDUE: il modulo, da 2 a MAX_CASES */
    Rat divisor;        /* MEMBER: un numero; DIVISOR: un'espressione senza y */
    Frac alpha, beta;   /* MEMBER: la condizione è "divisor divide alpha y + beta" */
} Split;

/* La richiesta in attesa, se split_pending: la raccoglie in_regions(). */
static Split split_wanted;
static int split_pending;

/* Annota la richiesta s, se non ce n'è già una: vale la prima. */
static void split_ask(Split s) {
    if (split_pending) return;
    split_wanted = s;
    split_pending = 1;
}

/* Ritorna, per una distinzione ORDER su una variabile intera, il primo
 * intero c del lato di sopra: y \ge at vuol dire y \ge c con c = \lceil at
 * \rceil, y > at vuol dire y \ge \lfloor at \rfloor + 1. */
static long long order_cut(const Split *s) {
    return s->upper_closed ? -frac_floor(frac_neg(s->at)) : frac_floor(s->at) + 1;
}

/* Ritorna il posto in universal[] dell'unica variabile generica di p, o -1
 * se p non ne ha, ne ha più di una o contiene altri atomi. */
static int sole_generic(Poly p) {
    int who = -1;
    for (int i = 0; i < p.count; i++)
        for (int k = 0; k < p.term[i].mono.count; k++) {
            int w = universal_index(p.term[i].mono.factor[k].atom);
            if (w < 0 || (who >= 0 && w != who)) return -1;
            who = w;
        }
    return who;
}

/* Legge il numeratore di gap come alpha y + beta, con y l'unica variabile
 * generica e alpha, beta numeri: mette il posto di y in *who e ritorna 1. */
static int gap_affine(Rat gap, int *who, Frac *alpha, Frac *beta) {
    Poly num, den;
    if (failure || !rat_polynomials(gap, &num, &den) || !poly_is_constant(den) || den.count == 0) return 0;
    *who = sole_generic(num);
    if (*who < 0) return 0;
    return rat_affine_in((Rat){num, poly_const(num_int(1))}, atom_var(universal[*who].name), alpha, beta);
}

/* Chiede di distinguere il punto in cui gap si annulla, se gap è di primo
 * grado in una sola variabile e quel punto sta nel suo insieme. */
static void split_at_zero(Rat gap) {
    Frac alpha, beta;
    int who;
    if (split_pending || !gap_affine(gap, &who, &alpha, &beta)) return;
    Frac at = frac_neg(frac_div(beta, alpha));
    if (failure || !numbers_contain(universal[who].numbers, at)) return;
    split_ask((Split){atom_var(universal[who].name), SPLIT_POINT, at, 0, 0, rat_int(0), frac_int(0), frac_int(0)});
}

/* Chiede di distinguere i due lati del punto in cui gap si annulla, per
 * sapere se gap > 0 (strict) o gap \ge 0: il punto sta dal lato in cui la
 * condizione vale se non è stretta, dall'altro se lo è. Serve che i due lati
 * abbiano elementi dell'insieme: per gli interi, che l'estremo inferiore
 * stia sotto il punto; per i razionali, che non ci sia un estremo. */
static void split_at_sign(Rat gap, int strict) {
    Frac alpha, beta;
    int who;
    if (split_pending || !gap_affine(gap, &who, &alpha, &beta)) return;
    Frac at = frac_neg(frac_div(beta, alpha));
    int upper_closed = (alpha.num > 0) == !strict;
    const NumberSet *set = universal[who].numbers;
    if (failure) return;
    Split s = {atom_var(universal[who].name), SPLIT_ORDER, at, upper_closed, 0, rat_int(0), frac_int(0), frac_int(0)};
    if (set->integers ? set->bounded && order_cut(&s) <= set->low + set->strict : set->bounded) return;
    split_ask(s);
}

/* Chiede di distinguere se u divide v. Con u un intero e v un polinomio in
 * una sola variabile y: per y intera i resti modulo |u| per il minimo comune
 * multiplo dei denominatori di v (con quel periodo v cambia di un multiplo
 * di u); per y razionale, se v è di primo grado, "multiplo o no". Con u
 * un'espressione: se v = y + u q, con q a coefficienti interi in variabili
 * intere e y intera senza estremi, "u divide y o no". */
static void split_at_multiple(Rat u, Rat v) {
    Poly num, den, part[2], q, d, one = poly_const(num_int(1));
    Num m;
    if (split_pending || failure || !rat_polynomials(v, &num, &den) || !poly_is_one(den)) return;
    if (rat_number(u, &m)) {
        int who = sole_generic(num);
        if (who < 0 || m.im.num != 0 || m.re.den != 1 || m.re.num == 0) return;
        const NumberSet *set = universal[who].numbers;
        int y = atom_var(universal[who].name);
        if (set->integers && !set->holes) {
            long long scale = 1;
            for (int i = 0; i < num.count && scale <= MAX_CASES; i++) scale = scale / (long long)gcd128(scale, num.term[i].coef.re.den) * num.term[i].coef.re.den;
            long long modulus = llabs(m.re.num) * scale;
            if (scale > MAX_CASES || modulus < 2 || modulus > MAX_CASES) return;
            split_ask((Split){y, SPLIT_RESIDUE, frac_int(0), 0, modulus, rat_int(0), frac_int(0), frac_int(0)});
        } else if (!set->integers && !set->reals && !set->bounded && !set->holes) {
            Frac alpha, beta;
            if (rat_affine_in((Rat){num, one}, y, &alpha, &beta))
                split_ask((Split){y, SPLIT_MEMBER, frac_int(0), 0, 0, u, alpha, beta});
        }
        return;
    }
    for (int i = 0; i < universal_count && !failure; i++) {
        const NumberSet *set = universal[i].numbers;
        int y = atom_var(universal[i].name);
        if (!set->integers || set->bounded || set->holes || poly_uses(u.num, y) || poly_uses(u.den, y)) continue;
        if (poly_split(num, y, part, 1) != 1 || !poly_is_one(part[1])) continue;
        if (!rat_polynomials(rat_div((Rat){part[0], one}, u), &q, &d) || !poly_is_one(d) || !poly_whole(q)) continue;
        split_ask((Split){y, SPLIT_DIVISOR, frac_int(0), 0, 0, u, frac_int(0), frac_int(0)});
        return;
    }
}

/* Chiede ciò che servirebbe perché value stia in set: non sotto l'estremo,
 * diverso dai punti tolti. */
static void split_for_membership(Rat value, const NumberSet *set) {
    if (set->bounded) split_at_sign(rat_add(value, rat_int(set->low), 1), set->strict);
    for (int i = 0; i < set->holes; i++) split_at_zero(rat_add(value, rat_frac(set->hole[i]), 1));
}

/* Chiede di distinguere ciò che decide la condizione c di un caso, letta con
 * i valori del momento: il primo dei suoi confronti che non si sa già
 * dimostrare né smentire. */
static void split_from_condition(const Formula *c) {
    if (split_pending || failure) return;
    if (c->kind == F_NOT) { split_from_condition(c->a); return; }
    if (c->kind == F_AND || c->kind == F_OR) {
        split_from_condition(c->a);
        split_from_condition(c->b);
        return;
    }

    /* Un confronto che si sa già decidere non va distinto. */
    size_t start = proof_length;
    int decided = case_proved(c, 0);
    proof_cut(start);
    if (!decided && !failure) decided = case_proved(c, 1);
    proof_cut(start);
    if (decided || failure) return;

    Rat u = eval(c->left), v = c->kind == F_IN ? rat_int(0) : eval(c->right);
    if (failure) return;
    switch (c->kind) {
    case F_EQUAL: case F_DISTINCT: split_at_zero(rat_add(u, v, 1)); return;
    case F_LESS:                   split_at_sign(rat_add(v, u, 1), 1); return;
    case F_LESS_EQ:                split_at_sign(rat_add(v, u, 1), 0); return;
    case F_DIVIDES:                split_at_multiple(u, v); return;
    case F_IN:
        if (c->numbers.integers) split_at_multiple(rat_int(1), u);
        split_for_membership(u, &c->numbers);
        return;
    default:
        return;
    }
}

/* Chiede ciò che decide il caso di f(t), con f = map e t = argument. */
static void split_from_cases(const Map *map, Rat argument) {
    env_push(map->parameter, argument);
    for (int i = 0; i < map->cases && !split_pending && !failure; i++) split_from_condition(map->piece[i].when);
    env_pop();
}

/* Che cosa diventa la variabile y in un caso di una distinzione. */
typedef enum {
    REGION_SET,      /* resta y, in un insieme più piccolo */
    REGION_VALUE,    /* y è un'espressione in una variabile generica nuova */
    REGION_POINT,    /* y è un numero */
    REGION_EXCLUDED  /* resta y, con un fatto "u non divide w" in più */
} RegionKind;

/* Uno dei casi di una distinzione (18v-2). */
typedef struct {
    RegionKind kind;
    const NumberSet *set;  /* SET: il nuovo insieme di y; VALUE: quello della variabile nuova */
    int letter;            /* VALUE: la variabile nuova */
    Rat value;             /* VALUE: y come espressione nella variabile nuova; POINT: il numero */
    Exclusion excluded;    /* EXCLUDED: il fatto del caso */
} Region;

/* Ritorna un insieme uguale a set, nell'arena, con il testo che lo scrive.
 * Prima lo riporta all'invariante di NumberSet: un insieme di interi con
 * l'estremo escluso comincia dal successivo, un punto tolto sull'estremo lo
 * sposta (come in parse_numbers()), e restano solo i punti tolti che
 * appartengono all'insieme. Ritorna NULL, con fail(), se l'arena è piena. */
static const NumberSet *numbers_made(NumberSet set) {
    NumberSet *made = arena_alloc(sizeof *made);
    char *text = arena_alloc(192);
    if (!made || !text) return NULL;
    if (set.integers && set.bounded && set.strict) { set.low++; set.strict = 0; }
    for (int i = 0; set.integers && set.bounded && i < set.holes; ) {
        if (frac_cmp(set.hole[i], frac_int(set.low)) != 0) { i++; continue; }
        set.hole[i] = set.hole[--set.holes];
        set.low++;
        i = 0;
    }
    NumberSet plain = set;
    plain.holes = 0;
    int kept = 0;
    for (int i = 0; i < set.holes; i++)
        if (numbers_contain(&plain, set.hole[i])) set.hole[kept++] = set.hole[i];
    set.holes = kept;

    /* Il testo: l'insieme di partenza, poi i punti tolti. */
    const char *field = set.reals ? "\\mathbb{R}" : "\\mathbb{Q}";
    int n;
    if (set.integers && !set.bounded) n = snprintf(text, 192, "\\mathbb{Z}");
    else if (set.integers && set.low == 0) n = snprintf(text, 192, "\\mathbb{N}_{0}");
    else if (set.integers && set.low == 1) n = snprintf(text, 192, "\\mathbb{N}");
    else if (set.integers) n = snprintf(text, 192, "\\{%lld, %lld, \\ldots\\}", set.low, set.low + 1);
    else if (!set.bounded) n = snprintf(text, 192, "%s", field);
    else if (set.low == 0 && set.strict) n = snprintf(text, 192, "%s^{+}", field);
    else n = snprintf(text, 192, "\\{q \\in %s \\mid q %s %lld\\}", field, set.strict ? ">" : "\\ge", set.low);
    for (int i = 0; i < set.holes && n < 150; i++) {
        Frac h = set.hole[i];
        n += snprintf(text + n, 192 - (size_t)n, "%s", i ? ", " : " \\setminus \\{");
        if (h.den == 1) n += snprintf(text + n, 192 - (size_t)n, "%lld", h.num);
        else n += snprintf(text + n, 192 - (size_t)n, "%s\\frac{%lld}{%lld}", h.num < 0 ? "-" : "", llabs(h.num), h.den);
    }
    if (set.holes) snprintf(text + n, 192 - (size_t)n, "\\}");
    *made = set;
    made->start = text;
    made->end = text + strlen(text);
    return made;
}

/* Ritorna una lettera per una variabile nuova: non è usata in body, né tra le
 * variabili generiche, legate o dei parametri, né dalle applicazioni e dalle
 * loro regole. 0 se non ce n'è. */
static int region_letter(const Formula *body) {
    for (const char *letter = "stuvwpqrhgmjz"; *letter; letter++) {
        int taken = map_find(*letter) != NULL || formula_uses_letter(body, *letter) || env_lookup(*letter) != NULL;
        for (int i = 0; i < universal_count; i++) taken = taken || universal[i].name == *letter;
        for (int i = 0; i < map_count; i++) taken = taken || maps[i].parameter == *letter;
        for (int i = 0; i < statement_parameter_count; i++) taken = taken || statement_parameters[i].name == *letter;
        if (!taken) return *letter;
    }
    return 0;
}

/* Mette in out[] i casi della distinzione s per la variabile generica di
 * posto index, e ritorna quanti sono; 0 se la distinzione non si sa fare.
 * body è la condizione da dimostrare in ogni caso, che serve solo a
 * scegliere la lettera di una variabile nuova. Ogni elenco copre l'insieme
 * di y:
 *
 *   - ORDER, y intera, c il primo intero del lato di sopra: y \ge c, e poi
 *     y \le c - 1, cioè gli interi da l'estremo inferiore a c - 1 uno per
 *     uno, oppure y = c - 1 - s con s \in \mathbb{N}_{0} se non c'è un
 *     estremo;
 *   - ORDER, y razionale senza estremo: y = at + s e y = at - s, con s \ge 0
 *     da un lato e s > 0 dall'altro, secondo dove sta at;
 *   - POINT: y = at, e y nel suo insieme senza at;
 *   - RESIDUE: y = M s + r per r da 0 a M - 1, con s dove serve perché
 *     y stia sopra l'estremo inferiore (come in 18o);
 *   - MEMBER: y = P s + o con s intero, dove P = |m / alpha| e o è la
 *     soluzione di alpha y + beta = 0 ridotta tra 0 e P: sono le y per cui
 *     alpha y + beta è un multiplo di m; e le altre, con il loro fatto;
 *   - DIVISOR: y = u s con s intero, e le altre, con il loro fatto. */
static int regions_of(int index, const Split *s, const Formula *body, Region *out) {
    const NumberSet *set = universal[index].numbers;
    int letter = region_letter(body), count = 0;
    Rat fresh = letter ? rat_atom(atom_var(letter)) : rat_int(0);
    NumberSet any = {0}, base = *set;
    any.integers = 1;
    base.holes = 0;
    if (!letter) return 0;
    switch (s->kind) {
    case SPLIT_ORDER:
        if (set->integers) {
            long long c = order_cut(s);
            NumberSet up = *set;
            up.bounded = 1;
            up.low = c;
            up.strict = 0;
            out[count++] = (Region){REGION_SET, numbers_made(up), 0, rat_int(0), {rat_int(0), {0, NULL}}};
            if (set->bounded) {
                for (long long p = set->low + set->strict; p <= c - 1; p++) {
                    if (!numbers_contain(set, frac_int(p))) continue;
                    if (count > MAX_REGION_POINTS) return 0;
                    out[count++] = (Region){REGION_POINT, NULL, 0, rat_int(p), {rat_int(0), {0, NULL}}};
                }
                return count;
            }
            NumberSet down = any;
            down.bounded = 1;
            for (int i = 0; i < set->holes; i++)
                if (frac_cmp(set->hole[i], frac_int(c - 1)) <= 0) down.hole[down.holes++] = frac_add(frac_int(c - 1), frac_neg(set->hole[i]));
            out[count++] = (Region){REGION_VALUE, numbers_made(down), letter, rat_add(rat_int(c - 1), fresh, 1), {rat_int(0), {0, NULL}}};
            return count;
        }
        if (set->bounded) return 0;
        for (int side = 0; side < 2; side++) {
            /* side 0: y = at + s; side 1: y = at - s. at è compreso dal lato
             * upper_closed. */
            NumberSet half = base;
            half.bounded = 1;
            half.low = 0;
            half.strict = side == s->upper_closed;
            for (int i = 0; i < set->holes; i++) {
                Frac moved = frac_add(set->hole[i], frac_neg(s->at));
                if (side) moved = frac_neg(moved);
                if (moved.num >= 0 && half.holes < MAX_HOLES) half.hole[half.holes++] = moved;
            }
            Rat value = rat_add(rat_frac(s->at), fresh, side);
            out[count++] = (Region){REGION_VALUE, numbers_made(half), letter, value, {rat_int(0), {0, NULL}}};
        }
        return count;
    case SPLIT_POINT: {
        NumberSet rest = *set;
        if (rest.holes == MAX_HOLES) return 0;
        rest.hole[rest.holes++] = s->at;
        out[count++] = (Region){REGION_POINT, NULL, 0, rat_frac(s->at), {rat_int(0), {0, NULL}}};
        out[count++] = (Region){REGION_SET, numbers_made(rest), 0, rat_int(0), {rat_int(0), {0, NULL}}};
        return count;
    }
    case SPLIT_RESIDUE:
        for (long long r = 0; r < s->modulus; r++) {
            NumberSet part = any;
            long long first = set->low + set->strict - r, m = s->modulus;
            part.bounded = set->bounded;
            part.low = !set->bounded ? 0 : first >= 0 ? (first + m - 1) / m : -((-first) / m);
            Rat value = rat_add(rat_mul(rat_int(m), fresh), rat_int(r), 0);
            out[count++] = (Region){REGION_VALUE, numbers_made(part), letter, value, {rat_int(0), {0, NULL}}};
        }
        return count;
    case SPLIT_MEMBER: {
        Num m;
        if (!rat_number(s->divisor, &m)) return 0;
        Frac period = frac_div(m.re, s->alpha), offset = frac_neg(frac_div(s->beta, s->alpha));
        if (period.num < 0) period = frac_neg(period);
        offset = frac_add(offset, frac_neg(frac_mul(period, frac_int(frac_floor(frac_div(offset, period))))));
        if (period.num == 1 && period.den == 1 && offset.num == 0) {
            NumberSet whole = base;
            whole.integers = 1;
            out[count++] = (Region){REGION_SET, numbers_made(whole), 0, rat_int(0), {rat_int(0), {0, NULL}}};
        } else {
            Rat value = rat_add(rat_mul(rat_frac(period), fresh), rat_frac(offset), 0);
            out[count++] = (Region){REGION_VALUE, numbers_made(any), letter, value, {rat_int(0), {0, NULL}}};
        }
        /* Il fatto del secondo caso, scritto come "P non divide y - o": dice
         * lo stesso di "m non divide alpha y + beta", e nella forma in cui lo
         * riconosce not_multiple(), che guarda le differenze con y. */
        Rat shifted = rat_add(rat_atom(s->atom), rat_frac(offset), 1);
        out[count++] = (Region){REGION_EXCLUDED, NULL, 0, rat_int(0), {rat_frac(period), shifted.num}};
        return count;
    }
    case SPLIT_DIVISOR:
        out[count++] = (Region){REGION_VALUE, numbers_made(any), letter, rat_mul(s->divisor, fresh), {rat_int(0), {0, NULL}}};
        out[count++] = (Region){REGION_EXCLUDED, NULL, 0, rat_int(0), {s->divisor, rat_atom(s->atom).num}};
        return count;
    }
    return 0;
}

/* Controllo del passo: ogni elemento dell'insieme di y deve stare in uno dei
 * casi, altrimenti la distinzione ne lascerebbe fuori qualcuno. Lo si
 * verifica, come in 18c, sui primi elementi dell'insieme, calcolando: un
 * insieme nuovo lo contiene, un punto è lui, un'espressione a s + b lo dà
 * con s = (y - b)/a nel suo insieme, un fatto "m non divide w" vale con
 * i numeri. La distinzione "u divide y o no", con u un'espressione, è vera
 * per come è fatta, e non ha numeri da calcolare: lì il controllo non c'è.
 * Ritorna 1 se il controllo passa. */
static int regions_cover(int index, const Split *s, const Region *region, int regions) {
    Frac sample[2 * SAMPLE_SIZE], alpha, beta;
    Num w, m;
    if (s->kind == SPLIT_DIVISOR) return 1;
    numbers_sample(universal[index].numbers, sample, 2 * SAMPLE_SIZE);
    for (int i = 0; i < 2 * SAMPLE_SIZE; i++) {
        int covered = 0;
        for (int k = 0; k < regions && !covered && !failure; k++) {
            const Region *r = &region[k];
            if (r->kind == REGION_SET) covered = numbers_contain(r->set, sample[i]);
            else if (r->kind == REGION_POINT) covered = rat_number(r->value, &w) && frac_cmp(w.re, sample[i]) == 0;
            else if (r->kind == REGION_VALUE && rat_affine_in(r->value, atom_var(r->letter), &alpha, &beta))
                covered = numbers_contain(r->set, frac_div(frac_add(sample[i], frac_neg(beta)), alpha));
            else if (r->kind == REGION_EXCLUDED && rat_number(r->excluded.divisor, &m) &&
                     rat_number(poly_substitute(r->excluded.value, s->atom, rat_frac(sample[i])), &w))
                covered = !number_divides(m, w);
        }
        if (failure) return 0;
        if (!covered) return 0;
    }
    return 1;
}

/* Scrive la frase che annuncia la distinzione s sulla variabile name; region
 * sono i suoi casi. */
static void region_intro(int name, const Split *s, const Region *region) {
    Num m;
    switch (s->kind) {
    case SPLIT_ORDER:
        if (region[0].set->integers) {
            long long c = order_cut(s);
            proof_add("\\item Either $%c \\ge %lld$ or $%c \\le %lld$.\n", name, c, name, c - 1);
            return;
        }
        proof_add("\\item Either $%c %s ", name, s->upper_closed ? "\\ge" : ">");
        put_frac(s->at);
        proof_add("$ or $%c %s ", name, s->upper_closed ? "<" : "\\le");
        put_frac(s->at);
        proof_add("$.\n");
        return;
    case SPLIT_POINT:
        proof_add("\\item Either $%c = ", name);
        put_frac(s->at);
        proof_add("$ or $%c \\neq ", name);
        put_frac(s->at);
        proof_add("$.\n");
        return;
    case SPLIT_RESIDUE:
        proof_add("\\item Every integer is $%lld%c + r$ for exactly one integer $%c$ and one $r$ among $0", s->modulus, region[0].letter, region[0].letter);
        for (long long r = 1; r < s->modulus; r++) proof_add(", %lld", r);
        proof_add("$: division by $%lld$ with remainder. So there are $%lld$ cases.\n", s->modulus, s->modulus);
        return;
    case SPLIT_MEMBER: {
        Rat linear = rat_add(rat_mul(rat_frac(s->alpha), rat_atom(s->atom)), rat_frac(s->beta), 0);
        proof_add("\\item Either $");
        put_fraction(linear);
        if (rat_number(s->divisor, &m) && num_equal(m, num_int(1))) {
            proof_add(" \\in \\mathbb{Z}$ or $");
            put_fraction(linear);
            proof_add(" \\notin \\mathbb{Z}$.\n");
        } else {
            proof_add("$ is a multiple of $");
            put_fraction(s->divisor);
            proof_add("$ or it is not.\n");
        }
        return;
    }
    case SPLIT_DIVISOR:
        proof_add("\\item Either $");
        put_fraction(s->divisor);
        proof_add(" \\mid %c$ or $", name);
        put_fraction(s->divisor);
        proof_add(" \\nmid %c$.\n", name);
        return;
    }
}

/* Scrive il titolo del caso r, il numero k della distinzione s sulla
 * variabile name: che cosa vale nel caso e, se y diventa un'espressione in
 * una variabile nuova, quale. */
static void region_heading(int name, const Split *s, const Region *r, int k) {
    Num m;
    proof_add("\\item \\emph{Case $");
    if (r->kind == REGION_POINT) {
        proof_add("%c = ", name);
        put_fraction(r->value);
    } else {
        switch (s->kind) {
        case SPLIT_ORDER:
            if (r->set->integers) proof_add(k == 0 ? "%c \\ge %lld" : "%c \\le %lld", name, order_cut(s) - (k != 0));
            else {
                proof_add("%c %s ", name, k == 0 ? (s->upper_closed ? "\\ge" : ">") : (s->upper_closed ? "<" : "\\le"));
                put_frac(s->at);
            }
            break;
        case SPLIT_POINT:
            proof_add("%c \\neq ", name);
            put_frac(s->at);
            break;
        case SPLIT_RESIDUE:
            proof_add("%c = ", name);
            put_fraction(r->value);
            break;
        case SPLIT_MEMBER: {
            Rat linear = rat_add(rat_mul(rat_frac(s->alpha), rat_atom(s->atom)), rat_frac(s->beta), 0);
            int unit = rat_number(s->divisor, &m) && num_equal(m, num_int(1));
            if (unit) {
                put_fraction(linear);
                proof_add(k == 0 ? " \\in \\mathbb{Z}" : " \\notin \\mathbb{Z}");
            } else {
                put_fraction(s->divisor);
                proof_add(k == 0 ? " \\mid " : " \\nmid ");
                put_fraction(linear);
            }
            break;
        }
        case SPLIT_DIVISOR:
            put_fraction(s->divisor);
            proof_add(k == 0 ? " \\mid %c" : " \\nmid %c", name);
            break;
        }
    }
    proof_add("$}");
    if (r->kind == REGION_VALUE && s->kind != SPLIT_RESIDUE) {
        proof_add(", that is $%c = ", name);
        put_fraction(r->value);
        proof_add("$ with $%c \\in ", r->letter);
        put_numbers(r->set);
        proof_add("$");
    } else if (r->kind == REGION_VALUE) {
        proof_add(", with $%c \\in ", r->letter);
        put_numbers(r->set);
        proof_add("$");
    }
    proof_add(".\n");
}

/* Ciò che va dimostrato in ogni caso di una distinzione: una funzione che lo
 * dimostra, scrivendo, e i suoi dati. Ritorna 1 se ci riesce. */
typedef int (*RegionGoal)(void *data);

/* 18v-2. Dimostra goal, e se non riesce perché manca una distinzione su una
 * delle variabili generiche dal posto from in su, la fa e dimostra goal in
 * ognuno dei casi, che possono chiederne altre fino a MAX_REGION_DEPTH.
 * body serve a scegliere le lettere nuove (regions_of()). Ritorna 1 se ci
 * riesce; se ritorna 0 non lascia testo, e una richiesta su una variabile
 * più esterna resta in attesa per chi l'ha introdotta. */
static int in_regions(RegionGoal prove, void *data, const Formula *body, int from, int depth) {
    Mark mark = mark_here();
    Split older = split_wanted;
    int had = split_pending;
    split_pending = 0;
    int holds = prove(data);
    Split wanted = split_wanted;
    int asked = split_pending;
    split_pending = had;
    split_wanted = older;
    if (failure == CASE_UNDECIDED) failure = NULL;
    if (holds || !asked || failure || search_left <= 0) return holds;

    /* La richiesta è per una variabile più esterna: passa a chi l'ha
     * introdotta, se non ce n'è già una. */
    int index = universal_index(wanted.atom);
    if (index < 0) return 0;
    if (index < from) {
        if (!had) { split_pending = 1; split_wanted = wanted; }
        return 0;
    }
    if (depth >= MAX_REGION_DEPTH) return 0;
    rollback(mark);

    /* I casi, uno per uno. */
    Region region[MAX_CASES + MAX_REGION_POINTS + 2];
    int regions = regions_of(index, &wanted, body, region);
    if (regions < 2 || failure) return 0;
    if (!regions_cover(index, &wanted, region, regions)) {
        if (!failure) unjustified_steps++;
        return 0;
    }
    int name = universal[index].name;
    region_intro(name, &wanted, region);
    region_depth++;
    holds = 1;
    for (int k = 0; k < regions && holds && !failure; k++) {
        const Region *r = &region[k];
        Bound kept = universal[index];
        region_heading(name, &wanted, r, k);
        if (r->kind == REGION_EXCLUDED &&
            !work_reserve((void **)&excluded, &excluded_capacity, (size_t)excluded_count + 1, sizeof *excluded)) { holds = 0; break; }
        if (r->kind == REGION_SET) universal[index].numbers = r->set;
        if (r->kind == REGION_VALUE || r->kind == REGION_POINT) env_push(name, r->value);
        if (r->kind == REGION_VALUE) universal[index] = (Bound){r->letter, r->set};
        if (r->kind == REGION_EXCLUDED) excluded[excluded_count++] = r->excluded;
        proof_add("\\begin{itemize}\n");
        holds = in_regions(prove, data, body, from, depth + 1);
        proof_add("\\end{itemize}\n");
        if (r->kind == REGION_EXCLUDED) excluded_count--;
        if (r->kind == REGION_VALUE || r->kind == REGION_POINT) env_pop();
        universal[index] = kept;
    }
    region_depth--;
    if (!holds) rollback(mark);
    return holds && !failure;
}

/* La condizione da dimostrare in ogni caso di una distinzione chiesta
 * dentro un "per ogni" (18k). */
typedef struct {
    Formula *body;
    int negated;
} Claim;

/* La RegionGoal di un Claim: lo dimostra con establish(). */
static int claim_established(void *data) {
    Claim *claim = data;
    return establish(claim->body, claim->negated);
}

/* 18v-2. Dimostra body, negata se negated, distinguendo i casi che servono
 * sulle variabili generiche dal posto from in su: quelle appena introdotte
 * da un "per ogni". */
static int establish_in_regions(Formula *body, int negated, int from) {
    Claim claim = {body, negated};
    return in_regions(claim_established, &claim, body, from, 0);
}

/* 18v-1. Stabilisce il caso di ogni applicazione definita per casi
 * nell'espressione node, dalle più interne: per ognuna, se l'argomento non è
 * un numero, dimostra la condizione di un caso e annota la scelta in
 * case_choice[], scrivendo il ragionamento. Ritorna 1 se ci riesce; se no
 * chiede una distinzione (18v-2) e ritorna 0, e il testo va cancellato da
 * chi chiama. */
static int cases_decided_in(const Node *node) {
    if (!node) return 1;
    if (failure || !cases_decided_in(node->a) || !cases_decided_in(node->b) || !cases_decided_in(node->c)) return 0;
    const Map *map = node->kind == N_APPLY ? map_find(node->name) : NULL;
    if (!map || !map->cases) return 1;
    Rat t = eval(node->a);
    if (failure) return 0;
    if (case_computed(map, t) >= 0) return 1;
    if (failure) return 0;
    for (int i = case_choice_count - 1; i >= 0; i--)
        if (case_choice[i].node == node && rat_same(case_choice[i].argument, t)) return 1;
    if (case_choice_count == MAX_CASE_CHOICES) return 0;

    /* Il primo caso la cui condizione si dimostra. */
    for (int i = 0; i < map->cases && !failure; i++) {
        size_t start = proof_length;
        env_push(map->parameter, t);
        Rat value = eval(map->piece[i].value);
        proof_add("\\item By the definition of $%c$, $%c(", map->name, map->name);
        put_fraction(t);
        proof_add(") = ");
        put_fraction(value);
        proof_add("$:");
        int holds = !failure && case_proved(map->piece[i].when, 0);
        env_pop();
        if (holds) {
            proof_add("\n");
            case_choice[case_choice_count++] = (CaseChoice){node, t, i};
            return 1;
        }
        proof_cut(start);
        if (failure == OUT_OF_MEMORY) return 0;
        failure = NULL;
    }
    split_from_cases(map, t);
    return 0;
}

/* 18v-1. Stabilisce il caso di ogni applicazione definita per casi nelle
 * espressioni della condizione f, che non contiene quantificatori. */
static int cases_decided(const Formula *f) {
    if (!f) return 1;
    if (f->kind == F_NOT || f->kind == F_AND || f->kind == F_OR || f->kind == F_IMPLIES || f->kind == F_IFF)
        return cases_decided(f->a) && cases_decided(f->b);
    return cases_decided_in(f->left) && cases_decided_in(f->right);
}

/* Elenca in list[], a partire dal posto count, le uguaglianze di f (negata
 * se negated) da cui si può ricavare il valore di una variabile, e ritorna il
 * nuovo numero di elementi; list ha MAX_EQUATIONS posti.
 *
 * In una congiunzione ogni uguaglianza deve valere, quindi il valore cercato
 * la soddisfa: è una condizione necessaria. In una disgiunzione basta che
 * valga una parte, quindi un'uguaglianza di una parte non è necessaria; ma
 * risolverla è un modo di rendere vera la condizione ("esiste y con A o B"
 * vale se esiste y con A). In tutti e due i casi il valore trovato è solo
 * una proposta: chi chiama ricontrolla l'intera condizione.
 *
 * Non entra in un "per ogni y" più interno: lì ogni uguaglianza va letta
 * per tutti gli y, e risolverne una darebbe un valore che cambia con y. In
 * un "esiste y" più interno entra, e ne prende le sole uguaglianze in cui y
 * non compare: "esiste y con A e B(y)" chiede A quanto "A, ed esiste y con
 * B(y)". È ciò che serve per \exists p, q\ (p = a + c \land q = b + d),
 * dove il valore di p sta in un'uguaglianza scritta dopo \exists q. */
static int find_equations(Formula *f, int negated, const Formula **list, int count) {
    Junction j;
    if (f->kind == F_NOT) return find_equations(f->a, !negated, list, count);
    if (f->kind == F_EQUAL || f->kind == F_DISTINCT) {
        if ((f->kind == F_EQUAL) != negated && count < MAX_EQUATIONS) list[count++] = f;
        return count;
    }
    if ((f->kind == F_FORALL || f->kind == F_EXISTS) && (f->kind == F_EXISTS) != negated) {
        int found = find_equations(f->a, negated, list, count), kept = count;
        for (int i = count; i < found; i++)
            if (!node_uses_letter(list[i]->left, f->variable) && !node_uses_letter(list[i]->right, f->variable)) list[kept++] = list[i];
        return kept;
    }
    if (!junction(f, negated, &j)) return count;
    return find_equations(j.y, j.ny, list, find_equations(j.x, j.nx, list, count));
}

/* 18i, secondo caso. L'uguaglianza `equation`, richiesta dalla condizione del
 * quantificatore f, ha per numeratore il polinomio num, che non è di primo
 * grado in x. Se num contiene solo x, con coefficienti numerici, i valori
 * possibili di x sono le sue radici, e quelle razionali si trovano tutte
 * (vedi rational_roots()): si prova ciascuna di quelle che stanno
 * nell'insieme. Scrive il ragionamento e ritorna 1 se una funziona.
 *
 * È ciò che permette di trovare x = 41 per x^2 = 1681, che nessun elenco dei
 * "numeri più semplici" (18j) raggiungerebbe. cleared dice se num è stato
 * ottenuto togliendo denominatori. */
static int solve_by_roots(Formula *f, int negated, const Formula *equation, Poly num, int cleared) {
    long long c[MAX_UNIVARIATE + 1], scale;
    Frac root[MAX_UNIVARIATE + 1];
    int degree = poly_coefficients(num, atom_var(f->variable), c, &scale);
    int roots = degree >= 2 ? rational_roots(c, degree, root) : 0;
    if (roots >= 0 && degree >= 2 && !roots_confirmed(num, atom_var(f->variable), root, roots, &f->numbers)) return 0;
    for (int k = 0; k < roots; k++) {
        Mark mark = mark_here();
        if (!numbers_contain(&f->numbers, root[k])) continue;
        proof_add("\\item We look for $%c$ with $", f->variable);
        put_source(equation);
        proof_add("$. %s this equation is $", cleared ? "After clearing denominators," : "Written out,");
        put_poly(num);
        proof_add(" = 0$, whose rational roots are $");
        for (int j = 0; j < roots; j++) {
            if (j) proof_add(",\\ ");
            put_frac(root[j]);
        }
        proof_add("$. Take $%c = ", f->variable);
        put_frac(root[k]);
        proof_add("$, an element of $");
        put_numbers(&f->numbers);
        proof_add("$.\n");

        /* La condizione, con x legata alla radice. */
        choose(f->variable, root[k]);
        env_push(f->variable, rat_frac(root[k]));
        int holds = establish(f->a, negated);
        env_pop();
        if (holds) { witness_keep(f, rat_frac(root[k])); return 1; }
        rollback(mark);
    }
    return 0;
}

/* Prototipo in avanti inevitabile: 18v-3 risolve la stessa equazione caso
 * per caso, chiamando di nuovo solve_with() con il caso scelto. */
static int solve_through_cases(Formula *f, int negated, const Formula *equation);

/* 18i. Prova a dimostrare "esiste x in A tale che ..." risolvendo
 * l'uguaglianza `equation`, una di quelle di find_equations(). f è il nodo
 * del quantificatore e negated il segno con cui va letta la sua condizione.
 * Scrive il ragionamento e ritorna 1 se ci riesce; se ritorna 0 il testo
 * scritto va cancellato da chi chiama.
 *
 * Se l'uguaglianza, tolti i denominatori, è di grado più alto in x, la si
 * passa a solve_by_roots(). Se è di primo grado, cioè alpha x + beta = 0 con
 * alpha e beta senza x, l'unico valore possibile è x = -beta/alpha. Va
 * controllato tutto ciò che questo sottintende: che alpha non si annulli
 * mai, che il valore stia in A, e infine che con quel valore la condizione
 * valga davvero. Quest'ultimo controllo ricalcola tutto da capo, quindi non
 * si fida dei passaggi fatti per ricavare x. */
static int solve_with(Formula *f, int negated, const Formula *equation) {
    int x = atom_var(f->variable);
    Poly num, den, part[2], shown_num, shown_den;
    Num number;
    if (failure) return 0;

    /* L'equazione come alpha x + beta = 0. Qui x non è legata: è un atomo.
     *
     * È un conto fatto per tentativo, senza aver controllato i divisori: con
     * i valori dati alle altre variabili può capitare una divisione per zero.
     * Vuol dire solo che così non si ricava nulla, quindi l'errore si
     * cancella; all'ingresso `failure` era NULL, e non si perde altro. */
    Rat gap = rat_add(eval(equation->left), eval(equation->right), 1);
    if (failure == CASE_UNDECIDED && poly_uses(undecided_argument.num, x)) {
        failure = NULL;
        return solve_through_cases(f, negated, equation);
    }
    if (failure) { failure = NULL; return 0; }
    if (!rat_polynomials(gap, &num, &den)) return 0;
    if (poly_split(num, x, part, 1) != 1) return solve_by_roots(f, negated, equation, num, !poly_is_one(den));
    Poly alpha = part[1], minus_beta = poly_negate(part[0]);
    Rat solution = rat_make(minus_beta, alpha);
    if (!rat_polynomials(solution, &shown_num, &shown_den)) return 0;

    /* Controllo del passo: alpha x - (-beta) deve ridare il numeratore
     * dell'equazione, che il testo sta per riscrivere in quella forma. */
    Poly linear = poly_add(poly_mul(alpha, rat_atom(x).num), minus_beta, 1);
    if (failure) return 0;
    if (!poly_equal(linear, num)) { unjustified_steps++; return 0; }

    proof_add("\\item We look for $%c$ with $", f->variable);
    put_source(equation);
    proof_add("$. %s this equation is $", poly_is_one(den) ? "Written out," : "After clearing denominators,");
    if (!poly_is_one(alpha)) put_factor(alpha);
    proof_add("%c = ", f->variable);
    put_poly(minus_beta);
    proof_add("$.");

    /* Si può dividere per alpha solo se non si annulla mai. */
    if (!poly_is_constant(alpha)) {
        proof_add(" The coefficient of $%c$ is never zero.", f->variable);
        if (!zero_only_where(alpha, NULL)) {
            split_at_zero((Rat){alpha, poly_const(num_int(1))});
            return 0;
        }
    }

    /* Il valore, e la sua appartenenza ad A. */
    proof_add("\n\\item So take $%c = ", f->variable);
    put_ratio(shown_num, shown_den);
    proof_add("$. It has to be an element of $");
    put_numbers(&f->numbers);
    proof_add("$.");
    if (!always_in(solution, &f->numbers)) {
        split_for_membership(solution, &f->numbers);
        return 0;
    }
    proof_add("\n");

    /* La condizione, con x legata al valore trovato. */
    if (rat_number(solution, &number)) choose(f->variable, number.re);
    env_push(f->variable, solution);
    int holds = establish(f->a, negated);
    env_pop();
    if (holds) witness_keep(f, solution);
    return holds;
}

/* Se il caso piece di map è un punto, "x = c" con x la variabile della regola
 * e c un numero, mette c in *point e ritorna 1. */
static int case_point(const Map *map, int piece, Frac *point) {
    const Formula *c = map->piece[piece].when;
    Num value;
    if (c->kind != F_EQUAL) return 0;
    const Node *other = c->left->kind == N_VAR && c->left->name == map->parameter ? c->right
                      : c->right->kind == N_VAR && c->right->name == map->parameter ? c->left : NULL;
    if (!other || node_uses_letter(other, map->parameter)) return 0;
    int number = rat_number(eval(other), &value) && value.im.num == 0;
    if (failure) { failure = NULL; return 0; }
    if (number) *point = value.re;
    return number;
}

/* 18v-3. L'uguaglianza `equation`, richiesta dalla condizione dell'"esiste"
 * f, contiene un'applicazione definita per casi il cui argomento dipende
 * dalla variabile x: è quella che ha fatto fallire il conto (undecided_*).
 * Si prova un caso alla volta: se il caso è un punto x = c si prova c; se no
 * l'uguaglianza si risolve (18i) con il valore di quel caso. Il caso è solo
 * un tentativo: scelto il valore, la condizione di f si dimostra da capo, e
 * 18v-1 stabilisce il caso con una dimostrazione. Scrive il ragionamento e
 * ritorna 1 se un caso funziona; se ritorna 0 il testo va cancellato. */
static int solve_through_cases(Formula *f, int negated, const Formula *equation) {
    const Map *map = undecided_map;
    const Node *node = undecided_node;
    Rat argument = undecided_argument;
    int x = atom_var(f->variable);
    if (case_choice_count == MAX_CASE_CHOICES) return 0;
    for (int i = 0; i < map->cases && !failure && search_left > 0; i++) {
        Mark mark = mark_here();
        Frac point;
        int holds;
        if (rat_same(argument, rat_atom(x)) && case_point(map, i, &point)) {
            if (!numbers_contain(&f->numbers, point)) continue;
            proof_add("\\item Case %d of the definition of $%c$ is $%c = ", i + 1, map->name, f->variable);
            put_frac(point);
            proof_add("$: take $%c = ", f->variable);
            put_frac(point);
            proof_add("$, an element of $");
            put_numbers(&f->numbers);
            proof_add("$.\n");
            choose(f->variable, point);
            env_push(f->variable, rat_frac(point));
            holds = establish(f->a, negated);
            env_pop();
            if (holds) witness_keep(f, rat_frac(point));
        } else {
            env_push(map->parameter, argument);
            Rat value = eval(map->piece[i].value);
            proof_add("\\item In case %d of the definition of $%c$, where ", i + 1, map->name);
            put_condition(map->piece[i].when, 0);
            proof_add(", $%c(", map->name);
            put_fraction(argument);
            proof_add(") = ");
            put_fraction(value);
            proof_add("$.\n");
            env_pop();
            case_choice[case_choice_count++] = (CaseChoice){node, argument, i};
            holds = !failure && solve_with(f, negated, equation);
            case_choice_count--;
        }
        if (holds) return 1;
        rollback(mark);
        if (failure == CASE_UNDECIDED) failure = NULL;
    }
    return 0;
}

/* 18i. Prova a dimostrare "esiste x in A tale che ..." risolvendo, una dopo
 * l'altra, le uguaglianze da cui x si può ricavare. Ritorna 1 se una
 * funziona; se ritorna 0 non lascia testo né scelte. */
static int solve_for(Formula *f, int negated) {
    const Formula *equation[MAX_EQUATIONS];
    int count = find_equations(f->a, negated, equation, 0);
    for (int i = 0; i < count && !failure && search_left > 0; i++) {
        Mark mark = mark_here();
        if (solve_with(f, negated, equation[i])) return 1;
        rollback(mark);
    }
    return 0;
}

/* =============================================================================
 * 18.5 LE IPOTESI "ESISTE", CON IL LORO TESTIMONE (18u)
 * ============================================================================
 *
 * A che cosa serve. "Se x - y è un intero e y - z è un intero, allora x - z
 * è un intero" si scrive
 *
 *     ((\exists k \in Z (x - y = k)) \land (\exists j \in Z (y - z = j)))
 *         \implies \exists m \in Z (x - z = m).
 *
 * Le regole viste finora dimostrano una disgiunzione una parte per volta, e
 * qui nessuna parte vale da sola: non è vero che l'ipotesi è sempre falsa,
 * né che x - z è sempre intero. Un matematico direbbe: "sia k l'intero che
 * l'ipotesi fornisce, e j l'altro; allora x - z = k + j". Questa regola fa
 * lo stesso, in tre passi, su una disgiunzione di cui si guardano tutte le
 * parti insieme (un'implicazione "A implica B" è la disgiunzione "non A,
 * oppure B": vedi junction()).
 *
 *   18u-1. Dare un nome. Una parte "per ogni v in A vale P(v)" (ed è così
 *          che si legge un'ipotesi "esiste v in A con H(v)", che nella
 *          disgiunzione compare negata: "per ogni v, non H(v)") diventa
 *          P(v) con v variabile generica. È lecito: se per ogni v vale
 *          "P(v) oppure R", e R non contiene v, allora o R è vera, oppure è
 *          falsa e P(v) vale per ogni v. Serve che v non compaia in R: per
 *          questo la lettera non deve essere usata nelle altre parti.
 *   18u-2. Svolgere. Una parte "s appartiene ad A" è "esiste q in A con
 *          s = q", e "u divide v" è "esiste q intero con v = q u" (17n):
 *          sono le definizioni, e sostituirle non cambia nulla. Così
 *          un'ipotesi a \equiv b \pmod{n}, con n una lettera, riceve anche
 *          lei il nome del suo quoziente. La regola 18r non è toccata:
 *          quando i moduli sono numeri decide lei, provando i resti.
 *   18u-3. Trovare il valore. Resta una parte "esiste m in A con E(m)",
 *          accanto a delle ipotesi H_1 = 0, ..., H_r = 0. Se E è di primo
 *          grado in m, cioè alpha m + beta = 0, si cerca m tra i polinomi
 *          nelle variabili generiche: un polinomio w e dei moltiplicatori
 *          c_i con
 *
 *              alpha w + beta = c_1 H_1 + ... + c_r H_r
 *
 *          come polinomi. È lo stesso sistema lineare della regola 18s, con
 *          in più i coefficienti di w tra le incognite: alpha fa da
 *          "ipotesi" il cui moltiplicatore è -w. Trovato w, lo si lega a m
 *          e si dimostra il resto con le regole di sempre: sarà la 18s a
 *          riscrivere l'identità e a ricontrollarla. Più "esiste" di
 *          seguito si cercano insieme: alpha_1 w_1 + alpha_2 w_2 + beta.
 *
 * Perché w va cercato tra i polinomi nelle sole variabili intere, quando A
 * è un insieme di interi: m = x - z soddisfa l'equazione, ma non si può
 * dimostrare che sia intero; m = k + j sì, perché k e j lo sono (18d). Che
 * il valore stia in A va infatti dimostrato per ogni valore delle variabili
 * generiche, senza usare le ipotesi: è più di quanto servirebbe, ed è ciò
 * che always_in() sa fare.
 *
 * Due parti con la stessa lettera. Una variabile è identificata dalla sua
 * lettera, quindi due ipotesi scritte tutte e due con \exists k non possono
 * ricevere tutte e due il nome k: prima di dare il nome, una viene riscritta
 * con una lettera che lì non è usata (quantifier_renamed()).
 *
 * Perché dare un nome è lecito, e che cosa lo garantisce. 18u-1 allarga la
 * portata di una lettera a tutta la disgiunzione, e un errore qui
 * fonderebbe due numeri in uno: da \exists k (x = 2k) e \exists k (y = 2k)
 * seguirebbe x = y. Il passo è corretto a tre condizioni, ognuna con la sua
 * difesa:
 *
 *   - v non compare nelle altre parti, né tra le variabili in vista
 *     (generiche, legate, applicazioni): letter_is_free() lo controlla su
 *     ogni nodo, quantificato o no (formula_uses_letter());
 *   - dentro la parte, v indica sempre lo stesso numero: formula_check()
 *     vieta di quantificare una lettera dentro se stessa, e le copie che
 *     nascono qui, rinominate o svolte, usano lettere che lì non compaiono;
 *   - la copia rinominata dice la stessa cosa dell'originale: nasce
 *     riscrivendo un testo, e formula_renamed() la confronta nodo per nodo
 *     con l'originale (alfa-equivalenza).
 *
 * Un errore che nessuna delle tre vede resta possibile, per esempio un tipo
 * di nodo nuovo con una lettera che formula_uses_letter() non guarda. Lo
 * fermerebbe la verifica del capitolo 19, che ricalcola l'enunciato com'è
 * scritto, con le sue portate, su valori che soddisfano le ipotesi: due
 * numeri fusi per errore danno una tesi che lì fallisce (x = 0, y = 2).
 *
 * Che cosa non fa. Non si applica dentro una dimostrazione per casi sul
 * resto (18o). Il valore cercato e solo un polinomio: un'ipotesi "per
 * ogni" non viene mai usata su un valore particolare.
 *
 * La verifica indipendente. I valori trovati qui sono espressioni nelle
 * lettere a cui è stato dato un nome, e quelle lettere non esistono fuori da
 * questa dimostrazione: la verifica dell'enunciato non potrebbe calcolarli.
 * Perciò, riuscita la dimostrazione, ciò che è stato annotato nei nodi viene
 * dimenticato (forget_choices()), e i controlli sono due, descritti in testa
 * al capitolo 19:
 *
 *   - l'enunciato com'è scritto, su valori che soddisfano le ipotesi per
 *     costruzione: per \exists k (x = k^2 + 7) si sceglie k e si calcola x.
 *     Se le ipotesi non sono mai risultate vere (meno di MIN_SATISFIED
 *     volte), il verdetto non viene emesso;
 *   - il valore scelto qui, annotato prima di dimenticarlo
 *     (record_witnesses()): dove le ipotesi valgono deve stare nel suo
 *     insieme e rendere vera la condizione. Si calcola con i numeri, senza
 *     l'identità tra polinomi con cui 18s ha giustificato il passo, e una
 *     copia del programma che scriveva w con il segno sbagliato, o non
 *     chiedeva che w fosse intero, è stata fermata così.
 */

/* Una parte di una disgiunzione da dimostrare, con il segno con cui va
 * letta: la disgiunzione vale quando vale una delle sue parti. */
typedef struct {
    Formula *source;  /* la condizione */
    int negated;      /* 1 se va presa negata */
} Leaf;

/* Ciò che 18u-3 ha affermato trovando un valore, annotato perché la verifica
 * del capitolo 19 lo ricontrolli con i numeri (record_holds()). Un'istanza
 * dice: per ogni valore delle variabili generiche per cui le parti `leaf`
 * della disgiunzione sono tutte false (cioè le ipotesi valgono), i valori
 * `value` degli "esiste" `quantifier` stanno nei loro insiemi e rendono vera
 * `body`, letta con il segno `sign`.
 *
 * Le espressioni, i nodi e gli insiemi a cui punta stanno nell'arena e negli
 * alberi della dimostrazione in corso: valgono finché questa non riparte. */
typedef struct {
    int generics;                    /* variabili generiche, in generic[] */
    Bound *generic;        /* nell'ordine in cui la verifica dà loro un valore: prima
                                        i testimoni a cui 18u-1 ha dato un nome, poi le altre;
                                        il vettore e posseduto dall'arena della dimostrazione */
    int bindings;                    /* variabili legate a un valore, in binding[] */
    Binding *binding;        /* quelle di env in quel momento: il valore è
                                        un'espressione nelle variabili generiche;
                                        il vettore e posseduto dall'arena */
    int leaves;                      /* parti della disgiunzione, in leaf[] */
    Leaf leaf[MAX_LEAVES];           /* tutte tranne quella dell'"esiste" */
    int names;                       /* "esiste" a cui è stato dato un valore, da 1 a MAX_NAMED */
    Formula *quantifier[MAX_NAMED];  /* i loro nodi, dal più esterno */
    Rat value[MAX_NAMED];            /* i valori: espressioni nelle variabili generiche */
    const Formula *body;             /* la condizione che segue gli "esiste" */
    int sign;                        /* 1 se body va presa negata */
} WitnessRecord;

/* I valori trovati da 18u-3 nella dimostrazione in corso: i primi
 * record_count (vedi Mark). */
static WitnessRecord witness_records[MAX_RECORDS];

/* universal_named e dichiarato con la pila dei legami: la verifica da un
 * valore prima ai testimoni delle ipotesi, poi alle altre variabili. */

/* Prototipo in avanti inevitabile: forget_choices() sta nel capitolo 19, con
 * la verifica a cui serve, e 18u deve chiamarla quando riesce. */
static void forget_choices(Formula *f);

/* Elenca in leaf[], a partire dal posto count, le parti della disgiunzione
 * f (negata se negated): scende nelle negazioni e nei connettivi che, con
 * quel segno, sono disgiunzioni, e si ferma su tutto il resto. Ritorna il
 * nuovo numero di parti, o -1 se sono più di MAX_LEAVES. */
static int leaves_collect(Formula *f, int negated, Leaf *leaf, int count) {
    Junction j;
    if (count < 0) return -1;
    if (f->kind == F_NOT) return leaves_collect(f->a, !negated, leaf, count);
    if (junction(f, negated, &j) && !j.conjunction) return leaves_collect(j.y, j.ny, leaf, leaves_collect(j.x, j.nx, leaf, count));
    if (count == MAX_LEAVES) return -1;
    leaf[count] = (Leaf){f, negated};
    return count + 1;
}

/* Ritorna la condizione f con la sua parte `old` sostituita da `by`. I nodi
 * che stanno tra f e old vengono copiati, così f resta com'era; il segno
 * con cui `by` va letta è quello che aveva old, perché i connettivi intorno
 * sono gli stessi. Se l'arena è piena ritorna f, e l'errore è annotato. */
static Formula *leaf_replaced(Formula *f, const Formula *old, Formula *by) {
    if (f == old) return by;
    if (f->kind != F_NOT && f->kind != F_AND && f->kind != F_OR && f->kind != F_IMPLIES) return f;
    Formula *a = leaf_replaced(f->a, old, by), *b = f->b ? leaf_replaced(f->b, old, by) : NULL;
    if (a == f->a && b == f->b) return f;
    Formula *copy = arena_alloc(sizeof *copy);
    if (!copy) return f;
    *copy = *f;
    copy->a = a;
    copy->b = b;
    return copy;
}

/* Ritorna 1 se la lettera può diventare il nome di una variabile che vale
 * per tutta la disgiunzione leaf[0..count), pur essendo scritta solo nella
 * parte own: non deve essere già una variabile generica o legata, né
 * comparire in un'altra parte. Con own = -1 nessuna parte è esclusa. */
static int letter_is_free(const Leaf *leaf, int count, int own, int letter) {
    if (env_lookup(letter) || map_find(letter)) return 0;
    for (int i = 0; i < universal_count; i++)
        if (universal[i].name == letter) return 0;
    for (int i = 0; i < count; i++)
        if (i != own && formula_uses_letter(leaf[i].source, letter)) return 0;
    return 1;
}

/* 18u-2. Ritorna la definizione svolta della condizione f, che è
 * un'appartenenza a un insieme numerico o una divisibilità:
 *
 *     s \in A     diventa   \exists q \in A\ (s = q)
 *     u \mid v    diventa   \exists q \in \mathbb{Z}\ (v = q \cdot u)
 *
 * preceduta da \lnot se f è scritta con \notin o \nmid. q è `letter`, una
 * lettera che l'enunciato non usa in quel punto. Il testo dei nuovi nodi
 * viene scritto qui, perché l'enunciato non lo contiene; ritorna NULL se
 * l'arena è piena. */
static Formula *membership_unfolded(const Formula *f, int letter) {
    int divides = f->kind == F_DIVIDES;

    /* Il testo, composto nel buffer della dimostrazione e poi tolto da lì:
     * si annota dove cadono l'insieme e l'uguaglianza. */
    size_t from = proof_length;
    if (f->swapped) proof_add("\\lnot ");
    size_t quantifier_at = proof_length - from;
    proof_add("\\exists %c \\in ", letter);
    size_t set_at = proof_length - from;
    if (divides) proof_add("\\mathbb{Z}"); else put_numbers(&f->numbers);
    size_t set_end = proof_length - from;
    proof_add("\\ (");
    size_t equation_at = proof_length - from;
    put_node(divides ? f->right : f->left, 0);
    proof_add(" = %c", letter);
    if (divides) { proof_add(" \\cdot "); put_node(f->left, 4); }
    size_t equation_end = proof_length - from;
    proof_add(")");
    size_t length = proof_length - from;
    char *text = arena_alloc(length + 1);
    if (text) memcpy(text, proof_text + from, length + 1);
    proof_cut(from);
    if (!text) return NULL;

    /* I nodi: l'uguaglianza, il quantificatore, la negazione. */
    Node *name = node_new(N_VAR, NULL, NULL);
    name->name = letter;
    Formula *equation = formula_node(F_EQUAL, NULL, NULL, text + equation_at);
    equation->end = text + equation_end;
    equation->left = divides ? f->right : f->left;
    equation->right = divides ? node_new(N_MUL, name, f->left) : name;
    Formula *exists = formula_node(F_EXISTS, equation, NULL, text + quantifier_at);
    exists->end = text + length;
    exists->variable = letter;
    if (divides) exists->numbers.integers = 1; else exists->numbers = f->numbers;
    exists->numbers.start = text + set_at;
    exists->numbers.end = text + set_end;
    if (!f->swapped) return exists;
    Formula *negation = formula_node(F_NOT, exists, NULL, text);
    negation->end = text + length;
    return negation;
}

/* 18y-4. IL NOME DI UN VALORE POSITIVO
 *
 * Un'ipotesi "esiste q in A con E(q)", dove E fissa il valore di q, dice di
 * più quando quel valore è sempre positivo: allora q sta nella parte
 * positiva di A. È un fatto, non una scelta: se E è alpha q + beta = 0, con
 * alpha che non si annulla mai, l'unico q possibile è -beta/alpha, e se
 * questo numero è positivo per ogni valore delle variabili generiche, ogni q
 * che soddisfa E è positivo. Quindi "esiste q in A con E(q)" ed "esiste q
 * nella parte positiva di A con E(q)" dicono la stessa cosa, in tutti e due i
 * versi, e il nome che 18u-1 dà a q può variare nella parte positiva.
 *
 * A che cosa serve. Due casi, con lo stesso ragionamento:
 *
 *   - x y^{-1} \in \mathbb{Q}, tra reali positivi, è "esiste q razionale con
 *     x y^{-1} = q" (18u-2): q = x/y è positivo, quindi q non è zero, e si
 *     può dividere per lui (18y-3): da x y^{-1} = q segue y x^{-1} = 1/q;
 *   - y = a x con x, y naturali e a intero: a = y/x è positivo, quindi a è
 *     un naturale, a >= 1. È ciò che serve all'antisimmetria della
 *     divisibilità (18z): da y = a x e x = b y segue a b = 1, e tra i naturali
 *     questo vuol dire a = b = 1.
 *
 * Si guardano le uguaglianze che E chiede tutte insieme: E stessa, o le
 * parti di una congiunzione. */

/* 18y-4. Se l'insieme a ha una parte positiva diversa da lui, scritta come
 * un insieme dei libri, la mette in *out e ritorna 1: \mathbb{N} per gli
 * interi che arrivano a 1 o sotto, \mathbb{Q}^{+} e \mathbb{R}^{+} per i
 * razionali e i reali senza estremo. Con dei punti tolti ritorna 0. */
static int positive_part(const NumberSet *a, NumberSet *out) {
    static const char *const written[] = {"\\mathbb{N}", "\\mathbb{Q}^{+}", "\\mathbb{R}^{+}"};
    if (a->holes || (a->bounded && (!a->integers || a->low >= 1))) return 0;
    memset(out, 0, sizeof *out);
    out->integers = a->integers;
    out->reals = a->reals;
    out->bounded = 1;
    out->low = a->integers ? 1 : 0;
    out->strict = !a->integers;
    out->start = written[a->integers ? 0 : a->reals ? 2 : 1];
    out->end = out->start + strlen(out->start);
    return 1;
}

/* 18y-4. Dimostra che l'"esiste" q, un'ipotesi, fissa un valore positivo per
 * la sua lettera, come descritto in testa al paragrafo: una delle
 * uguaglianze che la sua condizione chiede è alpha q + beta = 0, con alpha
 * che non si annulla mai e -beta/alpha positivo. Scrive il ragionamento e
 * ritorna 1 se ci riesce; se ritorna 0 non lascia testo. */
static int witness_positive(const Formula *q) {
    const Formula *equation[MAX_EQUATIONS];
    int count = 0, x = atom_var(q->variable);
    Mark mark = mark_here();

    /* Le uguaglianze chieste tutte insieme: la condizione, o le parti di una
     * congiunzione. */
    const Formula *stack[MAX_EQUATIONS], *g;
    int depth = 0;
    stack[depth++] = q->a;
    while (depth && count < MAX_EQUATIONS) {
        g = stack[--depth];
        if (g->kind == F_AND && depth + 2 <= MAX_EQUATIONS) { stack[depth++] = g->b; stack[depth++] = g->a; }
        else if (g->kind == F_EQUAL) equation[count++] = g;
    }
    for (int i = 0; i < count && !failure; i++) {
        Poly num, den, part[2], top, bottom;
        Rat gap = rat_add(eval(equation[i]->left), eval(equation[i]->right), 1);
        if (failure) { failure = NULL; continue; }
        if (!rat_polynomials(gap, &num, &den) || poly_split(num, x, part, 1) != 1) continue;
        Rat value = rat_make(poly_negate(part[0]), part[1]);
        if (!rat_polynomials(value, &top, &bottom)) continue;
        proof_add("\\item In $");
        put_source(q);
        proof_add("$ the equality $");
        put_source(equation[i]);
        proof_add("$ fixes $%c = ", q->variable);
        put_ratio(top, bottom);
        proof_add("$.");
        if (!poly_is_constant(part[1])) proof_add(" The coefficient of $%c$ is never zero:", q->variable);
        int positive = poly_is_constant(part[1]) || zero_only_where(part[1], NULL);
        if (positive) proof_add(" That value is positive, so $%c$ is too.", q->variable);
        positive = positive && signs(top, top, NULL, 0, SIGN_POSITIVE) && (poly_is_one(bottom) || signs(bottom, bottom, NULL, 0, SIGN_POSITIVE));
        if (positive && !failure) { proof_add("\n"); return 1; }
        failure = NULL;
        rollback(mark);
    }
    return 0;
}

/* La lettera name dopo la sostituzione di ogni from[i] con to[i], per i <
 * count; -1 se name è già una delle to[i], che dovevano essere nuove. */
static int letter_renamed(int name, const int *from, const int *to, int count) {
    for (int i = 0; i < count; i++) {
        if (name == from[i]) return to[i];
        if (name == to[i]) return -1;
    }
    return name;
}

/* Ritorna 1 se l'espressione b è a con ogni lettera from[i] scritta to[i]:
 * stessi nodi, stessi numeri, stesse lettere tranne quelle cambiate. */
static int node_renamed(const Node *a, const Node *b, const int *from, const int *to, int count) {
    if (!a || !b) return a == b;
    return a->kind == b->kind && a->value == b->value && a->op == b->op && letter_renamed(a->name, from, to, count) == b->name &&
           node_renamed(a->a, b->a, from, to, count) && node_renamed(a->b, b->b, from, to, count) && node_renamed(a->c, b->c, from, to, count);
}

/* Come node_renamed(), per due condizioni: b deve essere a con le lettere
 * cambiate, nodo per nodo, con gli stessi insiemi.
 *
 * È il controllo del passo di quantifier_renamed(), scritto a parte: là la
 * copia nasce riscrivendo un testo e rileggendolo, e un errore della
 * riscrittura (una lettera tra le graffe di \mathbb{N} cambiata, come è già
 * successo con le definizioni svolte di 17j) darebbe un'altra condizione.
 * Qui si guarda che la copia sia la stessa condizione con le variabili
 * legate chiamate in un altro modo. Basta, perché ogni to[i] è una lettera
 * che in a non compare (letter_renamed() lo pretende), quindi due lettere
 * diverse restano diverse e una variabile non ne cattura un'altra: è ciò che
 * i logici chiamano alfa-equivalenza, e due condizioni alfa-equivalenti sono
 * vere o false insieme. */
static int formula_renamed(const Formula *a, const Formula *b, const int *from, const int *to, int count) {
    if (!a || !b) return a == b;
    return a->kind == b->kind && a->swapped == b->swapped && letter_renamed(a->variable, from, to, count) == b->variable &&
           numbers_equal(&a->numbers, &b->numbers) && node_renamed(a->left, b->left, from, to, count) &&
           node_renamed(a->right, b->right, from, to, count) && formula_renamed(a->a, b->a, from, to, count) &&
           formula_renamed(a->b, b->b, from, to, count);
}

/* 18u-1, quando la lettera è già usata altrove. Ritorna una copia del
 * quantificatore q, parte di posto own della disgiunzione leaf[0..count),
 * in cui ogni sua lettera che compare anche in un'altra parte è cambiata
 * con una che lì non è usata; ritorna NULL se non c'è nulla da cambiare o
 * se non ci riesce.
 *
 * I libri scrivono spesso due ipotesi con la stessa lettera, \exists k\ (a
 * - b = kn) e \exists k\ (b - c = kn): sono due numeri diversi, e per
 * dare un nome a tutti e due uno va chiamato in un altro modo. Cambiare il
 * nome di una variabile legata non cambia ciò che la condizione dice.
 *
 * La copia si ottiene come le definizioni svolte di 17j: si riscrive il
 * testo del quantificatore con la lettera nuova e lo si rilegge, così ogni
 * nodo ha il testo che gli corrisponde. Più lettere dopo lo stesso
 * quantificatore hanno un testo solo, quindi si cambiano insieme, e q deve
 * essere il nodo della prima. Una copia che non risulta la stessa
 * condizione con le lettere cambiate (formula_renamed()) è un passo non
 * giustificato, e non si usa. */
static Formula *quantifier_renamed(const Formula *q, const Leaf *leaf, int count, int own) {
    size_t binders = 0;
    for (const Formula *g = q; g->kind == q->kind && g->start == q->start && g->end == q->end; g = g->a) binders++;
    if (!binders) return NULL;
    char (*fresh)[2] = arena_alloc(binders * sizeof *fresh);
    const char **to = arena_alloc(binders * sizeof *to), *before = syntax_error;
    int *from = arena_alloc(binders * sizeof *from), *letters = arena_alloc(binders * sizeof *letters), changes = 0;
    if (!fresh || !to || !from || !letters) return NULL;

    /* Le lettere scritte dopo il quantificatore: i nodi con lo stesso
     * testo. Si cambiano quelle usate altrove, purché non siano già
     * variabili in vista: allora il nome nuovo non basterebbe. */
    for (const Formula *g = q; g->kind == q->kind && g->start == q->start && g->end == q->end; g = g->a) {
        int taken = 0, letter = 0;
        for (int i = 0; i < count; i++) taken = taken || (i != own && formula_uses_letter(leaf[i].source, g->variable));
        if (!taken) continue;
        for (const char *c = "hjkqrstuvwpgdcbamn"; *c && !letter; c++) {
            int used = !letter_is_free(leaf, count, -1, *c);
            for (int i = 0; i < changes; i++) used = used || fresh[i][0] == *c;
            if (!used) letter = *c;
        }
        if (!letter || !letter_is_free(leaf, 0, -1, g->variable)) return NULL;
        from[changes] = g->variable;
        fresh[changes][0] = (char)letter;
        fresh[changes][1] = 0;  /* Il deposito non e statico: la parola va terminata. */
        to[changes] = fresh[changes];
        letters[changes] = letter;
        changes++;
    }
    if (!changes) return NULL;

    /* Il testo riscritto, e la sua lettura. Un errore di lettura vuol dire
     * solo che la copia non si può fare; una copia letta che dice un'altra
     * cosa, invece, è un errore della riscrittura. */
    draft_length = 0;
    draft_rewrite(q->start, q->end, from, to, changes);
    Formula *copy = unfold();
    int read = !syntax_error;
    syntax_error = before;
    if (read && !formula_renamed(q, copy, from, letters, changes)) { unjustified_steps++; read = 0; }
    return read ? copy : NULL;
}

/* 18u-3, per una sola uguaglianza. Cerca i valori dei `names` "esiste" di
 * quantifier[] che rendono `equation` una conseguenza delle `hypotheses`
 * ipotesi di given[], e con quelli dimostra la disgiunzione f (negata se
 * negated) in cui body prende il posto di quantifier[0]. given[] deve avere
 * altri `names` posti liberi dopo le ipotesi. Scrive il ragionamento e
 * ritorna 1 se ci riesce; se ritorna 0 il testo scritto va cancellato da chi
 * chiama. */
static int witnesses_solve(Formula *f, int negated, Formula **quantifier, int names, Formula *body,
                           const Formula *equation, Poly *given, int hypotheses) {
    Poly num, den, part[2], alpha[MAX_NAMED], multiplier[MAX_LITERALS + MAX_NAMED];
    int need[MAX_LITERALS + MAX_NAMED] = {0};
    Mark mark = mark_here();

    /* L'equazione con le lettere cercate come atomi. È un conto fatto per
     * tentativo: se non riesce vuol dire solo che da qui non si ricava
     * nulla, come in solve_with(). */
    Rat gap = rat_add(eval(equation->left), eval(equation->right), 1);
    if (failure) { failure = NULL; return 0; }
    if (!rat_polynomials(gap, &num, &den)) return 0;

    /* num = beta + alpha_1 m_1 + ... + alpha_r m_r: di primo grado in ogni
     * lettera cercata, e senza prodotti tra due di loro. */
    Poly beta = num;
    for (int j = 0; j < names; j++) {
        if (poly_split(beta, atom_var(quantifier[j]->variable), part, 1) != 1) return 0;
        alpha[j] = part[1];
        beta = part[0];
    }
    for (int j = 0; j < names; j++)
        for (int k = 0; k < names; k++)
            if (poly_uses(alpha[j], atom_var(quantifier[k]->variable))) return 0;

    /* Prima l'equazione com'è, v = -1; poi, se ci sono ipotesi, moltiplicata
     * per una variabile generica v che non può valere zero (vedi "Un fattore
     * che non si annulla" in testa a 18s).
     *
     * 18y-3. Moltiplicata per v si può anche cercare v m al posto di m, se m
     * varia tra i razionali o i reali: allora m = w / v. Serve dove il
     * valore è un reciproco: da x = q y, con q diverso da zero, y = (1/q) x,
     * e 1/q non è un polinomio. Si cerca w con v beta + alpha w nullo dove
     * valgono le ipotesi; dividendo per v, che non è zero, beta + alpha (w /
     * v) lo è anche lui. */
    int fractions = 1;
    for (int j = 0; j < names; j++) fractions = fractions && !quantifier[j]->numbers.integers;
    for (int v = -1; v < (hypotheses ? universal_count : 0) && !failure && search_left > 0; v++)
        for (int divide = 0; divide <= (v >= 0 && fractions) && !failure && search_left > 0; divide++) {
            Poly scale = poly_const(num_int(1));
            if (v >= 0 && numbers_contain(universal[v].numbers, frac_int(0))) continue;
            if (v >= 0) scale = rat_atom(atom_var(universal[v].name)).num;
            Poly target = poly_mul(scale, beta);
            long long least = poly_degree(target);
            for (int j = 0; j < names; j++) {
                given[hypotheses + j] = divide ? alpha[j] : poly_mul(scale, alpha[j]);
                need[hypotheses + j] = quantifier[j]->numbers.integers ? LETTER_INTEGER : quantifier[j]->numbers.reals ? LETTER_REAL : LETTER_RATIONAL;
                if (poly_degree(given[hypotheses + j]) > least) least = poly_degree(given[hypotheses + j]);
            }

            /* Il grado di ciò che si cerca non è noto: si parte dal più basso
             * possibile e si sale di poco, finché il sistema ha una soluzione. */
            int found = 0;
            for (long long top = least; top <= least + 2 && !found && !failure && search_left > 0; top++)
                found = combination(target, given, hypotheses + names, multiplier, top, need);
            if (!found) continue;

            /* Controllo del passo: rifatto il conto con prodotti e somme,
             * scale (beta + alpha_1 w_1 + ...) deve essere la combinazione delle
             * ipotesi che il sistema ha trovato (scale beta + alpha_1 w_1 + ...
             * se si divide). I w_j sono i moltiplicatori degli alpha_j, cambiati
             * di segno. */
            Poly rebuilt = poly_const(num_int(0));
            for (int i = 0; i < hypotheses + names; i++) rebuilt = poly_add(rebuilt, poly_mul(multiplier[i], given[i]), 0);
            if (failure) return 0;
            if (!poly_equal(rebuilt, target)) { unjustified_steps++; continue; }

            /* I valori, e la loro appartenenza agli insiemi. Dividendo per v,
             * prima che v non è zero. */
            Rat value[MAX_NAMED];
            int inside = 1;
            proof_add("\\item We look for $%c", quantifier[0]->variable);
            for (int j = 1; j < names; j++) proof_add(", %c", quantifier[j]->variable);
            proof_add("$ with $");
            put_source(equation);
            proof_add("$%s.", hypotheses ? ", using what is assumed" : "");
            if (divide) {
                proof_add(" We divide by $%c$, which is not zero.", universal[v].name);
                inside = zero_only_where(scale, NULL);
            }
            for (int j = 0; j < names && inside; j++) {
                Poly shown_num, shown_den;
                value[j] = rat_make(poly_negate(multiplier[hypotheses + j]), divide ? scale : poly_const(num_int(1)));
                proof_add(" Take $%c = ", quantifier[j]->variable);
                if (rat_polynomials(value[j], &shown_num, &shown_den)) put_ratio(shown_num, shown_den); else put_poly(value[j].num);
                proof_add("$. It has to be an element of $");
                put_numbers(&quantifier[j]->numbers);
                proof_add("$.");
                inside = always_in(value[j], &quantifier[j]->numbers);
            }
            proof_add("\n");
            if (!inside) { rollback(mark); continue; }

            /* Il resto, con le lettere legate ai valori trovati. */
            for (int j = 0; j < names; j++) {
                Num number;
                if (rat_number(value[j], &number)) choose(quantifier[j]->variable, number.re);
                env_push(quantifier[j]->variable, value[j]);
            }
            int holds = establish(leaf_replaced(f, quantifier[0], body), negated);
            for (int j = 0; j < names; j++) env_pop();
            if (!holds) { rollback(mark); continue; }
            for (int j = 0; j < names; j++) witness_keep(quantifier[j], value[j]);
            return 1;
        }
    return 0;
}

/* Annota in witness_records[] ciò che 18u-3 ha appena affermato. I `names`
 * "esiste" di quantifier[] cominciano la parte own della disgiunzione
 * leaf[0..count), body è la condizione che li segue, da leggere con il segno
 * sign, e i valori scelti sono nei nodi. Ritorna 0, senza annotare nulla, se
 * l'elenco è pieno: allora il valore non va usato, perché nessuno lo
 * ricontrollerebbe.
 *
 * Si copia lo stato della dimostrazione in quel momento: le variabili
 * generiche, prima quelle a cui 18u-1 ha dato il nome di un testimone, e
 * quelle legate a un valore. I valori nei nodi invece non bastano: 18u-1
 * li dimentica (forget_choices()), perché contengono lettere che fuori dalla
 * dimostrazione non esistono. */
static int record_witnesses(const Leaf *leaf, int count, int own, Formula **quantifier, int names, const Formula *body, int sign) {
    if (record_count == MAX_RECORDS) return 0;
    WitnessRecord *r = &witness_records[record_count++];
    r->generics = 0;
    r->generic = arena_alloc(((size_t)universal_count + 1) * sizeof *r->generic);
    if (!r->generic) { record_count--; return 0; }
    for (int named = 1; named >= 0; named--)
        for (int i = 0; i < universal_count; i++)
            if ((int)universal_named[i] == named) r->generic[r->generics++] = universal[i];
    r->bindings = env_count;
    r->binding = arena_alloc(((size_t)env_count + 1) * sizeof *r->binding);
    if (!r->binding) { record_count--; return 0; }
    for (int i = 0; i < env_count; i++) r->binding[i] = *env_at(i);
    r->leaves = 0;
    for (int i = 0; i < count; i++)
        if (i != own) r->leaf[r->leaves++] = leaf[i];
    r->names = names;
    for (int j = 0; j < names; j++) {
        r->quantifier[j] = quantifier[j];
        r->value[j] = quantifier[j]->witness[split_case];
    }
    r->body = body;
    r->sign = sign;
    return 1;
}

/* 18x. IL VALORE DI UN ESPONENTE
 *
 * "Esiste m intero con b = 2^{m} a", accanto all'ipotesi a = 2^{n} b: m sta
 * in un esponente, e l'equazione non è di primo grado in m, quindi 18u-3 non
 * lo trova. Ma gli esponenti si sommano quando le potenze si moltiplicano, e
 * il valore che serve è di solito una combinazione degli esponenti delle
 * ipotesi: qui m = -n; con a = 2^{n} b e b = 2^{k} c, per a = 2^{m} c, m =
 * n + k. La regola prova come valore di un "esiste" tra gli interi, la cui
 * lettera compare solo negli esponenti, le somme n_1 \pm ... \pm n_j delle
 * variabili generiche intere che compaiono negli esponenti delle altre
 * parti, dalle più corte; con ognuna la disgiunzione viene dimostrata da
 * capo, con le regole di sempre. È una ricerca, come 18j: un valore che non
 * porta a una dimostrazione si scarta, e uno che ci porta è giusto perché
 * la dimostrazione c'è. Il valore trovato si annota come quelli di 18u-3, e
 * la verifica del capitolo 19 lo ricontrolla con i numeri. */

/* 18x. Ritorna 1 se la lettera compare nell'espressione node fuori dagli
 * esponenti: come variabile, o nella base di una potenza. */
static int letter_outside_exponents(const Node *node, int letter) {
    if (!node) return 0;
    if (node->kind == N_POW) return letter_outside_exponents(node->a, letter);
    if (node->name == letter && (node->kind == N_VAR || node->kind == N_BIGOP || node->kind == N_SEQ || node->kind == N_APPLY)) return 1;
    return letter_outside_exponents(node->a, letter) || letter_outside_exponents(node->b, letter) || letter_outside_exponents(node->c, letter);
}

/* 18x. Ritorna 1 se nella condizione f la lettera compare, e solo negli
 * esponenti delle potenze. */
static int letter_only_in_exponents(const Formula *f, int letter) {
    if (!f) return 1;
    if (letter_outside_exponents(f->left, letter) || letter_outside_exponents(f->right, letter)) return 0;
    return letter_only_in_exponents(f->a, letter) && letter_only_in_exponents(f->b, letter);
}

/* 18x. Aggiunge a letters[], che ne ha *count e posto per MAX_NAMED, le
 * variabili generiche intere che compaiono negli esponenti dell'espressione
 * node, ognuna una volta. inside dice se si è già dentro un esponente. */
static void exponent_letters(const Node *node, int inside, int *letters, int *count) {
    if (!node) return;
    if (inside && node->kind == N_VAR && !env_lookup(node->name)) {
        int who = universal_index(atom_var(node->name)), seen = 0;
        for (int i = 0; i < *count; i++) seen = seen || letters[i] == node->name;
        if (who >= 0 && universal[who].numbers->integers && !seen && *count < MAX_NAMED) letters[(*count)++] = node->name;
    }
    exponent_letters(node->a, inside, letters, count);
    exponent_letters(node->b, inside || node->kind == N_POW, letters, count);
    exponent_letters(node->c, inside, letters, count);
}

/* 18x. Come exponent_letters(), per ogni espressione della condizione f. */
static void formula_exponent_letters(const Formula *f, int *letters, int *count) {
    if (!f) return;
    exponent_letters(f->left, 0, letters, count);
    exponent_letters(f->right, 0, letters, count);
    formula_exponent_letters(f->a, letters, count);
    formula_exponent_letters(f->b, letters, count);
}

/* Fin dove arriva, in valore assoluto, la costante che 18x aggiunge alle
 * combinazioni degli esponenti. */
#define EXPONENT_SHIFT 2

/* 18x. Prova il valore value per l'"esiste" q con cui comincia la parte own
 * della disgiunzione f (negata se negated), le cui parti sono
 * leaf[0..count); body è la condizione di q, da leggere con il segno sign.
 * Ritorna 1 se con quel valore la disgiunzione è dimostrata e il valore
 * annotato per la verifica; 0 se no, senza lasciare testo né scelte; -1 se
 * è dimostrata ma l'elenco delle annotazioni è pieno, e allora il valore non
 * si può usare: nessuno lo ricontrollerebbe. */
static int exponent_try(Formula *f, int negated, const Leaf *leaf, int count, int own, Formula *q, Formula *body, int sign, Rat value) {
    Mark mark = mark_here();
    proof_add("\\item The letter $%c$ appears only in exponents, and exponents add up when powers are multiplied: we try $%c = ", q->variable, q->variable);
    put_poly(value.num);
    proof_add("$. It has to be an element of $");
    put_numbers(&q->numbers);
    proof_add("$.");
    if (!always_in(value, &q->numbers)) { rollback(mark); return 0; }
    proof_add("\n");
    env_push(q->variable, value);
    int holds = establish(leaf_replaced(f, q, body), negated);
    env_pop();
    if (!holds) { rollback(mark); return 0; }
    witness_keep(q, value);
    if (record_witnesses(leaf, count, own, &q, 1, body, sign)) return 1;
    witness_drop(q);
    rollback(mark);
    return -1;
}

/* 18x. Dimostra la disgiunzione f (negata se negated), le cui parti sono
 * leaf[0..count), dando all'"esiste" q con cui comincia la parte own, la cui
 * condizione è body da leggere con il segno sign, il valore di una
 * combinazione degli esponenti delle altre parti (vedi la testa del
 * paragrafo). Scrive il ragionamento e ritorna 1 se ci riesce; se ritorna 0
 * non lascia testo né scelte. */
static int exponent_witness(Formula *f, int negated, const Leaf *leaf, int count, int own, Formula *q, Formula *body, int sign) {
    int letters[MAX_NAMED], found = 0;
    if (!power_letters || !q->numbers.integers || !formula_uses_letter(body, q->variable) || !letter_only_in_exponents(body, q->variable)) return 0;
    for (int i = 0; i < count; i++)
        if (i != own) formula_exponent_letters(leaf[i].source, letters, &found);

    /* Tre giri, dai valori più semplici. Prima le combinazioni: per ogni
     * lettera il segno + o -, oppure niente (cifra 0, 1 o 2 in base 3),
     * dalle più corte. Poi i prodotti di due esponenti, con i due segni:
     * (x^{n})^{m} = x^{n m}, e con y = x^{n} e z = y^{m} il valore per
     * z = x^{k} è k = n m. Infine le combinazioni con una costante piccola,
     * perché con a = 2^{n + 1} b il valore per b = 2^{m + 1} a è m = -n - 2.
     * I prodotti vengono prima delle costanti perché ogni valore provato
     * costa una dimostrazione intera, e le costanti sono le più numerose. */
    int combinations = 1;
    for (int i = 0; i < found; i++) combinations *= 3;
    for (int round = 0; round < 3; round++) {
        if (round == 1) {
            for (int i = 0; i < found; i++)
                for (int j = i; j < found; j++)
                    for (int minus = 0; minus < 2 && !failure && search_left > 0; minus++) {
                        Rat value = rat_mul(rat_atom(atom_var(letters[i])), rat_atom(atom_var(letters[j])));
                        if (minus) value = rat_add(rat_int(0), value, 1);
                        int tried = exponent_try(f, negated, leaf, count, own, q, body, sign, value);
                        if (tried) return tried > 0;
                    }
            continue;
        }
        for (int length = 1; length <= found; length++)
            for (int shift = round ? 1 : 0; shift <= (round ? 2 * EXPONENT_SHIFT : 0); shift++)
                for (int code = 1; code < combinations && !failure && search_left > 0; code++) {
                    Rat value = rat_int(shift % 2 ? (shift + 1) / 2 : -(shift / 2));
                    int used = 0;
                    for (int i = 0, c = code; i < found; i++, c /= 3) {
                        if (c % 3 == 0) continue;
                        value = rat_add(value, rat_atom(atom_var(letters[i])), c % 3 == 2);
                        used++;
                    }
                    if (used != length) continue;
                    int tried = exponent_try(f, negated, leaf, count, own, q, body, sign, value);
                    if (tried) return tried > 0;
                }
    }
    return 0;
}

/* 18u-3. Dimostra la disgiunzione f (negata se negated), le cui parti sono
 * leaf[0..count), cercando il valore degli "esiste" con cui comincia la
 * parte own tra i polinomi nelle variabili generiche, come descritto in
 * testa a 18u. Scrive il ragionamento e ritorna 1 se ci riesce; se ritorna
 * 0 non lascia testo né scelte.
 *
 * Il valore trovato è solo una proposta, come in 18i: l'intera disgiunzione
 * viene poi dimostrata da capo con il valore al posto della lettera. */
static int witnesses_from(Formula *f, int negated, const Leaf *leaf, int count, int own) {
    Formula *quantifier[MAX_NAMED], *body = leaf[own].source;
    const Formula *equation[MAX_EQUATIONS];
    Literal assumed[MAX_LITERALS];
    Poly given[MAX_LITERALS + MAX_NAMED];
    Mark mark = mark_here();
    if (failure) return 0;

    /* Gli "esiste" consecutivi con cui comincia la parte own: sign è il
     * segno con cui va letta la condizione che li segue. */
    int sign = leaf[own].negated, longest = 0;
    while (longest < MAX_NAMED && (body->kind == F_FORALL || body->kind == F_EXISTS) && (body->kind == F_EXISTS) != sign &&
           letter_is_free(leaf, count, own, body->variable)) {
        quantifier[longest++] = body;
        body = body->a;
    }
    if (!longest) return 0;

    /* Le ipotesi: le altre parti che sono un confronto da leggere come
     * "diversi", cioè un'uguaglianza che si può supporre. Il loro polinomio
     * lo calcola clause_polynomials(), che controlla anche le divisioni: le
     * frasi che scrive qui non servono, le riscriverà la regola 18s. Un
     * conto che non riesce vuol dire solo che così non si ricava nulla. */
    int hypotheses = 0, kept = 0;
    for (int i = 0; i < count && hypotheses < MAX_LITERALS; i++) {
        Literal literal[MAX_LITERALS];
        int found = 0;
        if (i != own && gather(leaf[i].source, leaf[i].negated, literal, &found) && found == 1 && !literal[0].equation)
            assumed[hypotheses++] = literal[0];
    }
    int usable = clause_polynomials(assumed, hypotheses);
    rollback(mark);
    if (failure || !usable) { failure = NULL; return 0; }
    for (int i = 0; i < hypotheses; i++)
        if (!poly_is_constant(assumed[i].value)) given[kept++] = assumed[i].value;

    /* Si cercano insieme i valori dei primi `names` "esiste": prima di
     * tutti, poi di meno, perché un'uguaglianza li deve contenere tutti.
     * Ogni uguaglianza richiesta da ciò che li segue può darli. */
    for (int names = longest; names > 0; names--) {
        body = quantifier[names - 1]->a;
        int equations = find_equations(body, sign, equation, 0);
        for (int e = 0; e < equations && !failure && search_left > 0; e++) {
            if (witnesses_solve(f, negated, quantifier, names, body, equation[e], given, kept)) {
                if (record_witnesses(leaf, count, own, quantifier, names, body, sign)) return 1;
                for (int j = 0; j < names; j++) witness_drop(quantifier[j]);
                rollback(mark);
                return 0;
            }
            rollback(mark);
        }
    }

    /* 18x. Un "esiste" la cui lettera sta solo negli esponenti: le
     * combinazioni degli esponenti delle altre parti. */
    return exponent_witness(f, negated, leaf, count, own, quantifier[0], quantifier[0]->a, sign);
}

/* 18u. Dimostra la disgiunzione f (negata se negated) guardandone tutte le
 * parti insieme, con i tre passi descritti in testa a 18u: uno per
 * chiamata, e il resto lo fa establish(), che torna qui finché serve.
 * Scrive il ragionamento e ritorna 1 se ci riesce; se ritorna 0 non lascia
 * testo né scelte. */
static int name_witnesses(Formula *f, int negated) {
    Leaf leaf[MAX_LEAVES];
    Mark mark = mark_here();
    int count = leaves_collect(f, negated, leaf, 0);
    if (count < 0 || failure || split_modulus) return 0;

    /* Senza variabili generiche ogni parte è una condizione su numeri, che
     * non dipende dalle altre: la disgiunzione vale solo se ne vale una da
     * sola, e questo è già stato provato da chi chiama. */
    if (!universal_count) return 0;

    /* 18u-1. Una parte che dice "per ogni v": v diventa generica. I due
     * modi di arrivarci si scrivono in modo diverso: un "per ogni" della
     * tesi introduce v, un "esiste" tra le ipotesi le dà un nome. */
    for (int i = 0; i < count; i++) {
        Formula *q = leaf[i].source;
        if ((q->kind != F_FORALL && q->kind != F_EXISTS) || (q->kind == F_FORALL) == leaf[i].negated) continue;

        /* La lettera è usata anche da un'altra parte: prima la si cambia,
         * e il passo successivo darà il nome alla copia. */
        if (!letter_is_free(leaf, count, i, q->variable)) {
            Formula *renamed = quantifier_renamed(q, leaf, count, i);
            if (!renamed) continue;
            proof_add("\\item The letters bound in $");
            put_source(q);
            proof_add("$ are used elsewhere too: we write it $");
            put_source(renamed);
            proof_add("$, which says the same.\n");
            if (establish(leaf_replaced(f, q, renamed), negated)) return 1;
            rollback(mark);
            return 0;
        }
        /* 18y-4. Il nome di un valore che l'ipotesi fissa, e che è sempre
         * positivo, varia nella parte positiva dell'insieme. L'insieme sta
         * nell'arena: la verifica del capitolo 19 lo rilegge dopo. */
        const NumberSet *named = &q->numbers;
        NumberSet positive, *kept;
        if (q->kind == F_EXISTS && positive_part(&q->numbers, &positive) && (kept = arena_alloc(sizeof *kept)) && witness_positive(q)) {
            *kept = positive;
            named = kept;
        }
        if (q->kind == F_FORALL) {
            proof_add("\\item Let $%c \\in ", q->variable);
            put_numbers(&q->numbers);
            proof_add("$.\n");
        } else {
            proof_add("\\item Suppose that $");
            put_source(q);
            proof_add("$ holds, and call $%c$ such an element of $", q->variable);
            put_numbers(named);
            proof_add("$: from here on $%c$ is fixed, and what follows is proved for every $%c \\in ", q->variable, q->variable);
            put_numbers(named);
            proof_add("$.\n");
        }
        int hypothesis = q->kind == F_EXISTS;
        if (!universal_push((Bound){q->variable, named})) return 0;
        universal_named[universal_count - 1] = (unsigned char)hypothesis;
        int holds = establish(leaf_replaced(f, q, q->a), negated);
        universal_count--;
        universal_named[universal_count] = 0;

        /* I valori annotati dentro f possono contenere v, che fuori da qui
         * non esiste: la verifica ricalcolerà f com'è scritta, e quelli
         * trovati da 18u-3 li ricontrollerà a parte (witness_records[]). */
        if (holds) { hypotheses_named += hypothesis; forget_choices(f); return 1; }
        rollback(mark);
        return 0;
    }

    /* 18u-2. Un'appartenenza o una divisibilità: la sua definizione, con
     * una lettera che qui non è usata. */
    for (int i = 0; i < count; i++) {
        Formula *q = leaf[i].source;
        int letter = 0;
        if (q->kind != F_IN && q->kind != F_DIVIDES) continue;
        for (const char *c = "qhkjtsuvwpgdcba"; *c && !letter; c++)
            if (letter_is_free(leaf, count, -1, *c)) letter = *c;

        Formula *unfolded = letter ? membership_unfolded(q, letter) : NULL;
        if (!unfolded) continue;
        proof_add("\\item By definition, $");
        put_source(q);
        proof_add("$ says that $");
        put_source(unfolded);
        proof_add("$.\n");
        if (establish(leaf_replaced(f, q, unfolded), negated)) return 1;
        rollback(mark);
        return 0;
    }

    /* 18u-3. Un "esiste": il suo valore, cercato usando le altre parti. */
    for (int i = 0; i < count && !failure; i++)
        if (witnesses_from(f, negated, leaf, count, i)) return 1;
    return 0;
}

/* =============================================================================
 * 18.6 ESTABLISH(): LA DIMOSTRAZIONE PER STRUTTURA
 * ============================================================================
 *
 * establish() mette insieme le regole dei capitoli precedenti seguendo la
 * forma della condizione: un'appartenenza (18e) o una divisibilità, un
 * confronto o una disgiunzione di confronti (18g, 18h, 18s), i connettivi
 * (18l, 18u), i quantificatori (18w, 18k, 18n, 18o, 18i, 18j), e prima di
 * establish() la regola dei divisori (18w), che le serve. Qui stanno anche
 * ciò che si dimostra di un'applicazione prima di usarla (18m) e la
 * divisione della tesi nelle sue affermazioni (prove_claims()), che sono i
 * punti di ingresso del capitolo 19.
 */

/* 18w. I DIVISORI DI UN NUMERO: UNA RICERCA FINITA
 *
 * A che cosa serve. "Nessun d diverso da 1 divide sia 2 sia 3" si scrive
 * \forall d \in \mathbb{N}\ \lnot (d \neq 1 \land d \mid 2 \land d \mid 3),
 * e parla di infiniti d; ma per tutti quelli che non dividono 2 la
 * condizione vale da sé, perché la sua parte "d divide 2" è falsa. Restano i
 * divisori di 2, che sono pochi: si provano uno per uno.
 *
 * Il teorema. Se d divide un intero c diverso da zero, allora |d| <= |c|.
 * Infatti c = q d con q intero (17n), e q non è zero perché c non lo è;
 * quindi |q| >= 1 e |c| = |q| |d| >= |d|. I divisori di c stanno dunque tra
 * -|c| e |c|, e si trovano tutti provando quei numeri: il conto è finito e
 * completo.
 *
 * La regola, per una lettera d che varia tra gli interi:
 *
 *   18w-1. "Per ogni d vale P(d)", dove P(d), letta come una disgiunzione,
 *          ha tra le sue parti "d non divide c", con c un numero diverso da
 *          zero (una volta date alle altre lettere i loro valori). Per ogni d
 *          che non divide c quella parte è vera, e con lei P(d); resta da
 *          dimostrare P(d) per i divisori di c che stanno nell'insieme di d,
 *          un caso ciascuno. È così che si legge un'ipotesi "d divide c":
 *          "d \mid c \implies Q" è "d non divide c, oppure Q".
 *   18w-2. "Esiste d con P(d)", dove P(d), letta come una congiunzione, ha
 *          tra le sue parti "d divide c": un d che va bene divide c, e si
 *          provano i divisori di c nell'insieme di d, dal più piccolo in
 *          valore assoluto. È la regola 18j con l'elenco completo dei valori
 *          possibili al posto dei numeri più semplici.
 *
 * Il valore di c deve essere un numero: un divisore di una lettera generica
 * non ha un elenco finito. Fuori dai casi di 18w-1 nulla si dimostra: lì la
 * parte "d non divide c" è vera per definizione, e i casi coprono tutti gli
 * altri d dell'insieme.
 *
 * La verifica indipendente (capitolo 19) ricalcola l'enunciato com'è
 * scritto, con d sul campione, senza usare questa regola. I valori scelti
 * per un "esiste" dentro un caso di 18w-1 cambiano da un caso all'altro, e
 * un nodo ne ricorda uno solo: perciò, riuscita la regola, vengono
 * dimenticati, e la verifica ricalcola quegli "esiste" com'è scritto. */

/* Il più grande |c| di cui 18w elenca i divisori provando i numeri da 1 a
 * |c|: oltre, il conto costerebbe troppo e la regola non si applica. */
#define DIVISOR_SCAN 100000

/* 18w. Se la condizione del quantificatore f, letta con il segno di f
 * (negata se negated), obbliga la variabile a dividere un numero diverso da
 * zero, mette quel numero in *c, la parte che lo dice in *part, e ritorna 1;
 * altrimenti ritorna 0. every dice se il quantificatore, con quel segno, è un
 * "per ogni": allora la parte è "d non divide c" di una disgiunzione (18w-1),
 * altrimenti "d divide c" di una congiunzione (18w-2). */
static int divisor_bound(Formula *f, int negated, int every, long long *c, const Formula **part) {
    Leaf leaf[MAX_LEAVES];

    /* Le parti di una congiunzione sono le negazioni delle parti della
     * disgiunzione negata: in tutti e due i casi si cerca una parte che,
     * con il suo segno, dice "d non divide c". */
    int count = leaves_collect(f->a, every ? negated : !negated, leaf, 0);
    for (int i = 0; i < count; i++) {
        const Formula *q = leaf[i].source;
        Num value;
        if (q->kind != F_DIVIDES || q->swapped == leaf[i].negated) continue;
        if (q->left->kind != N_VAR || q->left->name != f->variable || node_uses_letter(q->right, f->variable)) continue;

        /* c deve essere un intero diverso da zero: un conto che non riesce
         * vuol dire solo che questa parte non dà un elenco. */
        Rat r = eval(q->right);
        int number = !failure && rat_number(r, &value) && value.im.num == 0 && value.re.den == 1 && value.re.num != 0 &&
                     value.re.num >= -DIVISOR_SCAN && value.re.num <= DIVISOR_SCAN;
        failure = NULL;
        if (!number) continue;
        *c = value.re.num < 0 ? -value.re.num : value.re.num;
        *part = q;
        return 1;
    }
    return 0;
}

/* 18w. Dimostra il quantificatore f, negato se negated, quando la sua
 * variabile varia tra gli interi e la sua condizione la obbliga a dividere
 * un numero diverso da zero (divisor_bound()), con i casi descritti in testa
 * al paragrafo. Scrive il ragionamento e ritorna 1 se ci riesce; 0 se la
 * regola non si applica; -1 se si applica ma un caso non riesce. Se non
 * ritorna 1 non lascia testo né scelte.
 *
 * Perché il -1. I divisori sono tutti i valori che contano: un "esiste" il
 * cui valore non si trova tra loro non si trova altrove, perché un valore
 * scritto con le variabili generiche che fosse sempre un divisore di c
 * sarebbe un polinomio con un numero finito di valori su insiemi infiniti,
 * cioè una costante, e le costanti sono già state provate. Lo stesso per un
 * "per ogni" con un caso che non riesce. Chi chiama può quindi smettere di
 * cercare: provare le altre regole costava migliaia di passi, e la ricerca
 * di un controesempio a una proprietà transitiva si fermava prima di
 * arrivarci. */
static int by_divisors(Formula *f, int negated) {
    long long c, divisor[2 * MAX_CASES];
    const Formula *part;
    int every = (f->kind == F_FORALL) != negated, count = 0;
    Mark mark = mark_here();
    if (!f->numbers.integers || failure || !divisor_bound(f, negated, every, &c, &part)) return 0;

    /* I divisori di c nell'insieme della variabile, dal più piccolo in
     * valore assoluto, prima il positivo. Il controllo del passo ricalcola
     * che ognuno divida davvero c, con la divisione di number_divides(). */
    for (long long d = 1; d <= c; d++) {
        if (c % d != 0) continue;
        for (long long v = d; v >= -d; v -= 2 * d) {
            if (!numbers_contain(&f->numbers, frac_int(v))) continue;
            if (count == 2 * MAX_CASES) return 0;
            if (!number_divides(num_int(v), num_int(c))) { unjustified_steps++; return 0; }
            divisor[count++] = v;
        }
    }

    /* 18w-2. "Esiste": i divisori, uno dopo l'altro, come in 18j. */
    if (!every) {
        for (int i = 0; i < count && !failure; i++) {
            proof_add("\\item Since $");
            put_source(part);
            proof_add("$ is required, $%c$ is a divisor of $%lld$. Take $%c = %lld$, an element of $", f->variable, c, f->variable, divisor[i]);
            put_numbers(&f->numbers);
            proof_add("$.\n");
            choose(f->variable, frac_int(divisor[i]));
            env_push(f->variable, rat_int(divisor[i]));
            int holds = establish(f->a, negated);
            env_pop();
            if (holds) { witness_keep(f, rat_int(divisor[i])); return 1; }
            rollback(mark);
        }
        return -1;
    }

    /* 18w-1. "Per ogni": fuori dai divisori la parte "d non divide c" vale;
     * poi un caso per divisore. */
    proof_add("\\item Let $%c \\in ", f->variable);
    put_numbers(&f->numbers);
    proof_add("$. If $");
    put_source(part);
    proof_add("$ fails, the condition holds. Otherwise $%c$ divides $%lld$: then $%lld = q %c$ with $q$ a nonzero integer, so "
              "$|%c| \\le %lld$, and the divisors of $%lld$ in $", f->variable, c, c, f->variable, f->variable, c, c);
    put_numbers(&f->numbers);
    proof_add(count ? "$ are " : "$: there are none, so the condition always holds.\n");
    for (int i = 0; i < count; i++) proof_add("%s$%lld$%s", i ? (i + 1 == count ? " and " : ", ") : "", divisor[i], i + 1 == count ? ".\n" : "");
    for (int i = 0; i < count; i++) {
        proof_add("\\item \\emph{Case $%c = %lld$}.\n\\begin{itemize}\n", f->variable, divisor[i]);
        env_push(f->variable, rat_int(divisor[i]));
        int holds = establish(f->a, negated);
        env_pop();
        proof_add("\\end{itemize}\n");
        if (!holds) { rollback(mark); return -1; }
    }

    /* Le scelte fatte dentro i casi cambiano da un caso all'altro: non sono
     * un controesempio da riportare, e i nodi non le ricordano (vedi la
     * testa del paragrafo). */
    if (chosen_count > mark.chosen) chosen_by_cases = 1;
    forget_choices(f->a);
    return 1;
}

/* Il lavoro di establish(), che ne descrive il contratto, una volta
 * stabiliti i casi delle applicazioni definite per casi. */
static int establish_rules(Formula *f, int negated) {
    Mark mark = mark_here();
    Literal literal[MAX_LITERALS];
    Junction j;
    int count = 0;
    if (failure || search_left <= 0) return 0;
    search_left--;
    if (f->kind == F_NOT) return establish(f->a, !negated);

    /* 18e. Appartenenza a un insieme numerico (17k): l'espressione deve
     * avere un valore, e il valore stare nell'insieme. Che non ci stia si sa
     * dire solo di un numero, guardandolo. */
    if (f->kind == F_IN) {
        Num number;
        int inside = f->swapped == negated;
        proof_add("\\item $");
        put_source(f);
        proof_add("$ %s.", negated ? "fails" : "holds");
        int proved = term_defined(f->left);
        Rat value = eval(f->left);
        if (proved && inside) proved = always_in(value, &f->numbers);
        else if (proved) proved = !failure && rat_number(value, &number) && number.im.num == 0 && !numbers_contain(&f->numbers, number.re);
        if (proved && !inside) {
            proof_add(" Indeed $");
            put_frac(number.re);
            proof_add("$ is not in $");
            put_numbers(&f->numbers);
            proof_add("$.");
        }
        if (proved && !failure) { proof_add("\n"); return 1; }
        rollback(mark);
        return 0;
    }

    /* Divisibilità (17n): "u divide v" si dimostra, per ogni valore delle
     * variabili, quando il quoziente v/u è un polinomio che vale sempre un
     * intero (18d): allora v è u per quell'intero, anche dove u è zero. Che
     * u non divida v si sa dire solo di due numeri. */
    if (f->kind == F_DIVIDES) {
        Poly num, den;
        Num divisor, dividend;
        int divides = f->swapped == negated;
        proof_add("\\item $");
        put_source(f);
        proof_add("$ %s.", negated ? "fails" : "holds");
        int proved = term_defined(f->left) && term_defined(f->right);
        Rat u = eval(f->left), v = eval(f->right);
        if (proved && !failure && rat_number(u, &divisor) && rat_number(v, &dividend)) {
            proved = number_divides(divisor, dividend) == divides;
            if (proved) proof_add(" Computed with the two numbers.");
        } else if (proved && !failure && divides && u.num.count != 0) {
            proof_add(" The quotient is $");
            proved = rat_polynomials(rat_div(v, u), &num, &den) && poly_is_one(den);
            if (proved) { put_poly(num); proof_add("$."); proved = always_integer(num); }
        } else {
            proved = 0;
        }
        if (proved && !failure) { proof_add("\n"); return 1; }
        rollback(mark);
        return 0;
    }

    /* 18g, 18h. Un confronto, o una disgiunzione di confronti. */
    if (gather(f, negated, literal, &count)) {
        /* I polinomi che prove_clause() calcola servono solo a lei: resta il
         * testo che ha scritto. La memoria che ha preso si può ridare, a
         * meno che non sia nata la base di una potenza o l'argomento di
         * un'arcotangente, che restano nelle tabelle degli atomi. Senza
         * questo passo una ricerca lunga riempie l'arena molto prima di
         * finire i tentativi. */
        size_t before = arena_used;
        int polys = base_poly_count, atans = atan_count;
        proof_add("\\item");
        int proved = prove_clause(literal, count);

        /* 18s. Dove 18h non arriva: la tesi come combinazione delle
         * ipotesi. Il testo del primo tentativo si cancella. */
        if (!proved && !failure) {
            rollback(mark);
            proof_add("\\item");
            proved = prove_combination(literal, count);
        }

        /* 18z. Dove non arriva nemmeno 18s: un'ipotesi dà il valore di una
         * variabile, che si sostituisce nel resto. */
        if (!proved && !failure) {
            rollback(mark);
            proof_add("\\item");
            proved = prove_by_substitution(literal, count, MAX_SUBSTITUTIONS);
        }
        /* 18v-2. Un confronto che vale tranne in un punto di una variabile:
         * quel punto, e il resto, sono due casi da distinguere. */
        if (!proved && !failure)
            for (int i = 0; i < count && !split_pending; i++) split_at_zero((Rat){literal[i].value, poly_const(num_int(1))});
        if (polys == base_poly_count && atans == atan_count && failure != OUT_OF_MEMORY) arena_used = before;
        if (proved) { proof_add("\n"); return 1; }
        rollback(mark);

        /* Una disgiunzione di più confronti che prove_clause() non sa
         * trattare insieme può ancora valere per una sola delle sue parti:
         * si prosegue con la regola dei connettivi. Serve solo se tra le
         * parti c'è un "diversi": un "uguali" che vale da solo è già stato
         * riconosciuto (18g), e provarli di nuovo uno per uno consumerebbe i
         * tentativi di chi sta intorno, come la regola 18o. */
        int different = 0;
        for (int i = 0; i < count; i++) different += !literal[i].equation;
        if (count < 2 || !different || failure) return 0;
    }

    /* 18l. Congiunzione: tutte e due le parti. Disgiunzione che non è fatta
     * di soli confronti: una parte basta, e si prova prima l'una poi l'altra. */
    if (junction(f, negated, &j)) {
        if (j.conjunction) {
            if (establish(j.x, j.nx) && establish(j.y, j.ny)) return 1;
            rollback(mark);
            return 0;
        }
        for (int side = 0; side < 2; side++) {
            Formula *part = side ? j.y : j.x;
            int sign = side ? j.ny : j.nx;
            proof_add("\\item It is enough to show that $");
            put_source(part);
            proof_add("$ %s.\n", sign ? "fails" : "holds");
            if (establish(part, sign)) return 1;
            rollback(mark);
        }

        /* 18u. Nessuna delle due parti vale da sola: si guardano tutte
         * insieme, dando un nome a ciò che le ipotesi dicono esistere. I
         * tentativi di questa regola sono contati a parte, come quelli di
         * 18o, e sono pochi: quando non porta a nulla non deve consumare la
         * ricerca di chi sta intorno, che può arrivare qui migliaia di
         * volte, una per ogni numero provato da 18j. Prima di questo conto
         * due enunciati falsi, che venivano smentiti, restavano senza
         * risposta; sono nei test. */
        int outside = search_set_aside();
        int named = name_witnesses(f, negated);
        search_left += outside;
        if (named) return 1;

        /* 18l. Altrimenti, se è "A implica B e C"
         * si dimostrano "A implica B" e "A implica C", che insieme dicono lo
         * stesso: così l'ipotesi A resta accanto a ogni pezzo della tesi,
         * dove le regole 18h e 18s la sanno usare. I due nodi provvisori
         * servono solo a passare le due implicazioni a questa funzione. */
        if (f->kind == F_IMPLIES && !negated && f->b->kind == F_AND) {
            Formula first = *f, second = *f;
            first.b = f->b->a;
            second.b = f->b->b;
            if (establish(&first, 0) && establish(&second, 0)) return 1;
            rollback(mark);
        }
        return 0;
    }

    /* 18l. Equivalenza: le due implicazioni. La sua negazione: una delle due
     * implicazioni non vale. I due nodi provvisori servono solo a passare le
     * implicazioni a questa stessa funzione. */
    if (f->kind == F_IFF) {
        Formula forward = *f, backward = *f;
        forward.kind = backward.kind = F_IMPLIES;
        backward.a = f->b;
        backward.b = f->a;
        if (negated) {
            if (establish(&forward, 1) || establish(&backward, 1)) return 1;
        } else {
            proof_add("\\item ($\\Rightarrow$)\n");
            if (establish(&forward, 0)) {
                proof_add("\\item ($\\Leftarrow$)\n");
                if (establish(&backward, 0)) return 1;
            }
        }
        rollback(mark);
        return 0;
    }
    if (f->kind != F_FORALL && f->kind != F_EXISTS) return 0;

    /* 18w. Una variabile intera che deve dividere un numero: i valori che
     * contano sono i divisori, finiti. Si prova prima delle altre regole,
     * perché quando si applica decide in pochi passi ciò che quelle
     * cercherebbero a lungo. Quando si applica e non riesce, le altre non
     * troverebbero di più (vedi by_divisors()). */
    int divisors = by_divisors(f, negated);
    if (divisors) return divisors > 0;

    /* 18k. "Per ogni": variabili generiche. Più quantificatori di seguito
     * sullo stesso insieme si introducono insieme, come in "siano a, b". */
    if ((f->kind == F_FORALL) != negated) {
        Formula *last = f;
        int outer = universal_count;
        f->modulus = 0;

        /* I legami crescono con la dimostrazione, inclusi i testimoni delle
         * ipotesi; non si assume che basti la profondita del testo letto. */
        proof_add("\\item Let $%c", f->variable);
        if (!universal_push((Bound){f->variable, &f->numbers})) return 0;
        while (last->a->kind == f->kind && numbers_equal(&last->a->numbers, &f->numbers)) {
            last = last->a;
            proof_add(", %c", last->variable);
            if (!universal_push((Bound){last->variable, &last->numbers})) { universal_count = outer; return 0; }
        }
        proof_add(" \\in ");
        put_numbers(&f->numbers);
        proof_add("$");

        /* 17t-2. Le componenti di una coppia: si dice di quale. */
        for (const Formula *g = f, *said = NULL; ; g = g->a) {
            if (g->pair) proof_add(g->complex ? "%s$%c = %c + i%c$" : "%s$%c = (%c, %c)$", said ? " and " : ", with ", g->pair, g->variable, g->a->variable);
            if (g->pair) said = g;
            if (g == last) break;
        }
        proof_add(".\n");
        int holds = establish_in_regions(last->a, negated, outer);
        universal_count = outer;
        if (holds) return 1;

        /* Le due regole che seguono valgono per una variabile sola, intera.
         * Il tentativo diretto può essersi fermato su un conto che con una
         * lettera non si fa, come una somma fino a n: non è un errore
         * dell'enunciato. */
        const NumberSet *set = &f->numbers;
        if (last != f || !set->integers || set->holes || search_left <= 0) { rollback(mark); return 0; }
        failure = NULL;

        /* 18n. Per induzione: un'uguaglianza, su una semiretta di interi,
         * senza altre variabili in gioco. */
        const Formula *body = f->a;
        int sign = negated;
        while (body->kind == F_NOT) { body = body->a; sign = !sign; }
        if (set->bounded && outer == 0 && env_count == 0 && (body->kind == F_EQUAL || body->kind == F_DISTINCT) &&
            (body->kind == F_EQUAL) != sign) {
            rollback(mark);
            if (by_induction(f, body)) return 1;
        }

        /* 18o. Per casi sul resto di una divisione. */
        if (by_remainders(f, negated)) return 1;
        failure = NULL;
        rollback(mark);
        return 0;
    }

    /* 18i. "Esiste": prima risolvendo un'equazione. Un valore scelto in un
     * tentativo precedente, per questo stesso caso, non conta più. */
    witness_drop(f);
    if (solve_for(f, negated)) return 1;
    rollback(mark);

    /* 18u-3. Poi cercando il valore tra i polinomi nelle variabili
     * generiche: qui non ci sono ipotesi, e l'equazione deve diventare
     * un'identità. Trova p = m + n per m a + n a = p a, dove 18i si ferma
     * perché dividerebbe per a, che può essere zero. Anche questi tentativi
     * sono contati a parte, come quelli di 18o. */
    Leaf alone = {f, negated};
    int outside = search_set_aside();
    int polynomial = witnesses_from(f, negated, &alone, 1, 0);
    search_left += outside;
    if (polynomial) return 1;

    /* 18j. Poi provando i numeri più semplici dell'insieme. Il valore è un
     * numero fisso anche se ci sono variabili generiche: va bene quando lo
     * stesso numero serve per tutti i loro valori. */
    Frac sample[SAMPLE_SIZE];
    numbers_sample(&f->numbers, sample, SAMPLE_SIZE);
    for (int i = 0; i < SAMPLE_SIZE && !failure; i++) {
        proof_add("\\item Take $%c = ", f->variable);
        put_frac(sample[i]);
        if (f->pair) proof_add(f->complex ? "$ in $%c = %c + i%c" : "$ in $%c = (%c, %c)", f->pair, f->variable, f->a->variable);
        proof_add("$, an element of $");
        put_numbers(&f->numbers);
        proof_add("$.\n");
        choose(f->variable, sample[i]);
        env_push(f->variable, rat_frac(sample[i]));
        int holds = establish(f->a, negated);
        env_pop();
        if (holds) { witness_keep(f, rat_frac(sample[i])); return 1; }
        rollback(mark);
    }

    /* 18z. Poi le espressioni di primo grado più semplici nelle variabili
     * generiche: "per ogni m c'è un x che m non è un multiplo di x" non ha
     * un x fisso, ma x = 2m va bene per ogni m. Il valore va dimostrato
     * nell'insieme e la condizione con quel valore, come ogni altro: chi
     * cerca propone, la dimostrazione decide. Una variabile intera dà valori
     * interi, una razionale razionali. È anche la regola che prima si
     * chiamava 18v-9 (v, v + 1, v - 1), che questo elenco contiene: "esiste
     * y per cui nessun x dà f(x) = y", con f(x) = a x + b e a, b parametri,
     * vuole y = b + 1. */
    static const int line[][2] = {{1, 0}, {1, 1}, {2, 0}, {1, -1}, {2, 1}, {3, 0}};
    const Formula *equation[MAX_EQUATIONS];

    /* Solo quando nessuna uguaglianza dà il valore, e solo con le variabili
     * di cui la condizione parla, anche attraverso la regola di
     * un'applicazione che calcola (b, nella regola di f): dove 18i ha già
     * un'equazione da risolvere questi tentativi non aggiungono nulla, e
     * dentro più "esiste" annidati costavano migliaia di passi. */
    if (find_equations(f->a, negated, equation, 0)) return 0;
    for (int v = 0; v < universal_count && !failure && search_left > 0; v++) {
        if (env_lookup(universal[v].name) || (f->numbers.integers && !universal[v].numbers->integers) ||
            !formula_mentions(f->a, universal[v].name)) continue;
        for (size_t k = 0; k < sizeof line / sizeof *line && !failure && search_left > 0; k++) {
            Rat value = rat_add(rat_mul(rat_int(line[k][0]), rat_atom(atom_var(universal[v].name))), rat_int(line[k][1]), 0);
            proof_add("\\item Take $%c = ", f->variable);
            put_poly(value.num);
            proof_add("$. It has to be an element of $");
            put_numbers(&f->numbers);
            proof_add("$.");
            if (!always_in(value, &f->numbers)) { rollback(mark); continue; }
            proof_add("\n");
            env_push(f->variable, value);
            int holds = establish(f->a, negated);
            env_pop();
            if (holds) { witness_keep(f, value); return 1; }
            rollback(mark);
        }
    }
    return 0;
}

/* Ritorna 1 se la condizione f contiene un quantificatore. */
static int formula_quantifies(const Formula *f) {
    return f && (f->kind == F_FORALL || f->kind == F_EXISTS || f->kind == F_SOLVE || formula_quantifies(f->a) || formula_quantifies(f->b));
}

/* Ritorna 1 se l'enunciato in corso ha un'applicazione definita per casi. */
static int cases_declared(void) {
    for (int i = 0; i < map_count; i++)
        if (maps[i].cases) return 1;
    return 0;
}

/* Dimostra la condizione f, o la sua negazione se negated, per ogni valore
 * delle variabili generiche e con i valori dati alle altre. Scrive il
 * ragionamento come una serie di \item e ritorna 1 se ci riesce; se ritorna 0
 * non lascia testo né scelte. Le regole sono descritte in testa al capitolo
 * 18.
 *
 * Una condizione senza quantificatori in cui compare un'applicazione
 * definita per casi comincia con la scelta dei casi (18v-1), che vale finché
 * la si dimostra: dopo, le scelte si tolgono, perché parlano di quei valori
 * delle variabili. Un conto che si è fermato su un caso non stabilito non è
 * un errore dell'enunciato: lo si dimentica, e la richiesta di distinguere
 * (18v-2) resta a chi la raccoglie. */
static int establish(Formula *f, int negated) {
    Mark mark = mark_here();
    int choices = case_choice_count;
    int holds = (!cases_declared() || formula_quantifies(f) || cases_decided(f)) && establish_rules(f, negated);
    case_choice_count = choices;
    if (failure == CASE_UNDECIDED) failure = NULL;
    if (!holds) rollback(mark);
    return holds;
}

/* 18v-6. Dimostra, in uno dei casi di una distinzione sulla variabile della
 * regola di map (o senza distinzioni), che la definizione per casi dà un
 * solo valore e che sta nel codominio: un caso vale, il suo valore è
 * definito e sta nel codominio, e ognuno degli altri o non vale o dà lo
 * stesso valore. Scrive il ragionamento e ritorna 1 se ci riesce; se un caso
 * non si sa decidere chiede una distinzione (18v-2).
 *
 * Che nessun caso valga in una parte del dominio non si dimostra: i casi
 * allora non coprono il dominio, e la verifica sul campione lo trova. */
static int cases_hold_here(void *data) {
    const Map *map = data;
    const Rat *bound = env_lookup(map->parameter);
    Rat t = bound ? *bound : rat_atom(atom_var(map->parameter));
    int first = -1, holds = 1;
    env_push(map->parameter, t);

    /* Il primo caso che vale, con il suo valore. */
    for (int i = 0; i < map->cases && first < 0 && !failure; i++) {
        size_t start = proof_length;
        proof_add("\\item Case %d of the definition applies:", i + 1);
        if (case_proved(map->piece[i].when, 0)) first = i;
        else proof_cut(start);
        if (failure == CASE_UNDECIDED) failure = NULL;
    }
    if (first < 0) holds = 0;
    Rat value = holds ? eval(map->piece[first].value) : rat_int(0);
    if (holds) {
        proof_add(" So $%c(", map->name);
        put_fraction(t);
        proof_add(") = ");
        put_fraction(value);
        proof_add("$.");
        holds = term_defined(map->piece[first].value) && always_in(value, &map->codomain);
        proof_add("\n");
    }

    /* Gli altri: non valgono, o danno lo stesso valore. */
    for (int j = 0; j < map->cases && holds && !failure; j++) {
        if (j == first) continue;
        Rat other = eval(map->piece[j].value);
        Rat gap = rat_add(other, value, 1);
        if (!failure && gap.num.count == 0) {
            proof_add("\\item Case %d of the definition gives the same value.\n", j + 1);
            continue;
        }
        if (failure) failure = NULL;
        size_t start = proof_length;
        proof_add("\\item Case %d of the definition does not apply:", j + 1);
        if (case_proved(map->piece[j].when, 1)) { proof_add("\n"); continue; }
        proof_cut(start);
        holds = 0;
    }

    /* Un caso che non si sa decidere: si chiede che cosa distinguere. */
    if (!holds && !failure)
        for (int i = 0; i < map->cases && !split_pending; i++) split_from_condition(map->piece[i].when);
    env_pop();
    return holds && !failure;
}

/* 18v-6. Dimostra che la definizione per casi di map definisce
 * un'applicazione dal dominio al codominio: per ogni x del dominio i casi
 * che valgono danno uno stesso valore, definito e nel codominio. Scrive il
 * ragionamento come un \item e ritorna 1 se ci riesce. È il seguito di 18m
 * per le definizioni per casi. */
static int cases_define(const Map *map) {
    int outer = universal_count;
    proof_add("\\item \\emph{The definition by cases defines a map from $");
    put_numbers(&map->domain);
    proof_add("$ to $");
    put_numbers(&map->codomain);
    proof_add("$.} Let $%c \\in ", map->parameter);
    put_numbers(&map->domain);
    proof_add("$.\n\\begin{itemize}\n");
    if (!universal_push((Bound){map->parameter, &map->domain})) return 0;
    int defined = in_regions(cases_hold_here, (void *)map, NULL, outer, 0);
    universal_count = outer;
    proof_add("\\end{itemize}\n");
    return defined && !failure;
}

/* 18m. Dimostra che la regola di map definisce un'applicazione dal dominio al
 * codominio: per ogni x del dominio il valore esiste, perché nessun divisore
 * si annulla, e appartiene al codominio. Scrive il ragionamento come un \item
 * e ritorna 1 se ci riesce.
 *
 * Senza questo passo le ipotesi dell'enunciato potrebbero non essere
 * soddisfatte da nessuna applicazione, e allora qualunque tesi ne seguirebbe:
 * un verdetto FALSO sarebbe sbagliato, e uno DIMOSTRATO non direbbe nulla. */
static int map_defined(const Map *map) {
    Poly num, den;
    if (map->cases) return cases_define(map);
    proof_add("\\item \\emph{The %srule defines %s from $", map->partner ? "first component of the " : map->component ? "second component of the " : "",
              map->binary ? "an operation" : "a map");
    put_numbers(&map->domain);
    if (map->binary) { proof_add(" \\times "); put_numbers(&map->second); }
    proof_add("$ to $");
    put_numbers(&map->codomain);
    proof_add("$.} Let $%c \\in ", map->parameter);
    put_numbers(&map->domain);
    if (map->binary) { proof_add("$ and $%c \\in ", map->parameter2); put_numbers(&map->second); }
    proof_add("$.");

    /* Le variabili della regola sono generiche nel dominio, dopo i
     * parametri dell'enunciato (17s). */
    int outer = universal_count;
    if (!universal_push((Bound){map->parameter, &map->domain})) return 0;
    if (map->binary && !universal_push((Bound){map->parameter2, &map->second})) { universal_count = outer; return 0; }
    int defined = term_defined(map->body);
    Rat value = eval(map->body);
    if (defined && rat_polynomials(value, &num, &den)) {
        proof_add(" The value is $");
        put_ratio(num, den);
        proof_add("$.");
        defined = always_in(value, &map->codomain);
    } else {
        defined = 0;
    }
    universal_count = outer;
    proof_add("\n");
    return defined && !failure;
}

/* Dimostra la tesi f dividendola nelle affermazioni di cui è la congiunzione:
 * ognuna ha il suo titolo, con il testo dell'enunciato, e sotto i suoi passi.
 * Ritorna 1 se le dimostra tutte. */
static int prove_claims(Formula *f) {
    if (f->kind == F_AND) return prove_claims(f->a) && prove_claims(f->b);
    proof_add("\\item \\emph{Claim:} $");
    put_source(f);
    proof_add("$.\n\\begin{itemize}\n");
    int holds = establish_in_regions(f, 0, 0);
    proof_add("\\end{itemize}\n");
    return holds;
}

/* =============================================================================
 * 18.7 SOLE CONGRUENZE: TUTTI I RESTI (18r)
 * ============================================================================
 *
 * "5x è congruo a 8 modulo 36 se e solo se x è congruo a 16 modulo 36" parla
 * di tutti gli interi, ma che un intero x soddisfi una congruenza dipende
 * solo dal resto di x nella divisione per il modulo: i resti sono 36, e si
 * provano tutti. Questa regola decide così, vero o falso, ogni enunciato
 * fatto soltanto di condizioni di questo tipo.
 *
 * Il linguaggio. Un enunciato chiuso costruito con connettivi e
 * quantificatori a partire da condizioni "m divide P", dove m è un numero e P
 * un polinomio a coefficienti razionali nelle variabili dell'enunciato. Le
 * variabili variano in insiemi di interi. La condizione si può scrivere in
 * quattro modi: m \mid P, P \equiv Q \pmod{m}, P \in \mathbb{Z}, oppure
 * \exists k \in \mathbb{Z} (L = R) con un'uguaglianza di primo grado in k,
 * a coefficiente numerico: c k + P = 0 dice che -P/c è un intero
 * (names_a_multiple()). In tutti i casi la condizione è "il polinomio Q è
 * un intero", con Q = P/m, P oppure -P/c; scritto Q = N/D con N a
 * coefficienti interi e D il minimo comune
 * multiplo dei denominatori, è "D divide N". Così anche x/2 \equiv 1
 * \pmod{3}, che ha un coefficiente frazionario, riceve il modulo giusto: 6.
 *
 * Perché basta provare i resti. Sia M un multiplo comune dei moduli D.
 *
 *   1. Se x e x' sono interi con lo stesso resto modulo M, cioè x' = x + M t,
 *      allora N(x') - N(x) è multiplo di M per ogni polinomio N a
 *      coefficienti interi: lo è (x + M t)^j - x^j, per la formula del
 *      binomio, e somme e prodotti per interi lo conservano. Vale lo stesso
 *      con più variabili, cambiandone una alla volta. Quindi "D divide N"
 *      vale per x se e solo se vale per x', perché D divide M.
 *   2. Per induzione sulla struttura, la verità di ogni parte dell'enunciato
 *      dipende solo dai resti modulo M delle variabili libere in quella
 *      parte: i connettivi non aggiungono nulla, e per un quantificatore
 *      basta il punto 3.
 *   3. Un insieme di interi della grammatica (tutti gli interi da un certo
 *      punto in su, o tutti, meno un numero finito di punti) contiene interi
 *      di ogni resto modulo M, perché ogni classe di resto è infinita e non
 *      limitata dall'alto. Quindi "per ogni x in A vale P(x)" equivale a "per
 *      ogni resto r tra 0 e M - 1 vale P(r)", e così "esiste".
 *
 * Il conto è finito e completo: M alla d casi, con d quantificatori uno
 * dentro l'altro. Per questo la regola risponde anche FALSO, e quando la
 * domanda è \{x \in \mathbb{Z} \mid c\} elenca i resti buoni.
 *
 * Ciò che non è di questa forma (un'uguaglianza tra variabili, una variabile
 * razionale, un modulo che è una lettera) non la riguarda: lì la verità non
 * è periodica, e l'enunciato resta alle altre regole.
 *
 * La verifica indipendente è nel capitolo 19: lo stesso enunciato viene
 * ricalcolato sugli interi veri di un periodo, con i conti esatti del
 * capitolo 11 al posto dell'aritmetica dei resti. Lì stanno anche il
 * verdetto e le soluzioni (decide_by_residues(), solve_by_residues()), che
 * di quella verifica hanno bisogno.
 */

/* Una condizione "modulus divide dividend" di un enunciato deciso sui resti. */
typedef struct {
    const Formula *source;  /* il nodo F_DIVIDES o F_IN, oppure l'uguaglianza
                               sotto un "esiste k" che dice la stessa cosa */
    long long modulus;      /* D, positivo */
    Poly dividend;          /* N, a coefficienti interi */
} Congruence;

/* Le condizioni dell'enunciato in corso, e un multiplo comune dei loro
 * moduli: il periodo M. */
static Congruence congruences[MAX_CONGRUENCES];
static int congruence_count;
static long long residue_period;

/* Le variabili intere visibili nel punto dell'enunciato che si sta
 * esaminando, dalla più esterna, e il resto dato a ciascuna. */
static int *residue_name;
static long long *residue_value;
static size_t residue_name_capacity, residue_value_capacity;
static int residue_count;

/* Ritorna 1 se f è un'uguaglianza o una disgiunzione di uguaglianze. */
static int equations_only(const Formula *f) {
    if (f->kind == F_OR) return equations_only(f->a) && equations_only(f->b);
    return f->kind == F_EQUAL;
}

/* Ritorna 1 se f ha la forma "esiste k in Z tale che L = R (oppure L' = R',
 * ...)": è il modo di scrivere "è un multiplo di" senza il simbolo. Che le
 * uguaglianze siano davvero di primo grado in k lo controlla chi le legge. */
static int names_a_multiple(const Formula *f) {
    return f->kind == F_EXISTS && f->numbers.integers && !f->numbers.bounded && !f->numbers.holes && equations_only(f->a);
}

/* Registra in congruences[] la condizione "quotient è un numero intero",
 * scritta dal nodo source. Ritorna 1 se ci riesce: quotient deve essere un
 * polinomio a coefficienti razionali nelle variabili intere in vista.
 *
 * Il modulo è il minimo comune multiplo D dei denominatori dei coefficienti,
 * e il dividendo è D per quotient: vedi "Il linguaggio" in testa a 18r. */
static int congruence_add(const Formula *source, Rat quotient) {
    Poly num, den;
    if (failure || congruence_count == MAX_CONGRUENCES || !rat_polynomials(quotient, &num, &den)) return 0;
    if (!poly_is_constant(den) || den.count == 0) return 0;
    Poly q = poly_mul(num, poly_const(num_inv(den.term[0].coef)));

    /* Il modulo; e ogni lettera deve essere una variabile intera in vista. */
    long long modulus = 1;
    for (int i = 0; i < q.count; i++) {
        const Term *t = &q.term[i];
        __int128 multiple = (__int128)modulus / gcd128(modulus, t->coef.re.den) * t->coef.re.den;
        if (t->coef.im.num != 0 || multiple > MAX_PERIOD) return 0;
        modulus = (long long)multiple;
        for (int k = 0; k < t->mono.count; k++) {
            int known = 0;
            for (int v = 0; v < residue_count; v++) known = known || atom_var(residue_name[v]) == t->mono.factor[k].atom;
            if (!known) return 0;
        }
    }
    congruences[congruence_count++] = (Congruence){source, modulus, poly_mul(q, poly_const(num_int(modulus)))};
    return !failure;
}

/* Registra le uguaglianze di e, che stanno sotto "esiste k in Z" con k di
 * nome name: ognuna deve essere c k + P = 0 con c un numero non nullo, e
 * dice che -P/c è un intero. Ritorna 1 se sono tutte di questa forma. */
static int multiples_read(const Formula *e, int name) {
    Poly num, den, part[2];
    if (e->kind == F_OR) return multiples_read(e->a, name) && multiples_read(e->b, name);
    Rat gap = rat_add(eval(e->left), eval(e->right), 1);
    if (failure || !rat_polynomials(gap, &num, &den) || !poly_is_constant(den)) return 0;
    if (poly_split(num, atom_var(name), part, 1) != 1 || !poly_is_constant(part[1])) return 0;
    return congruence_add(e, rat_make(poly_negate(part[0]), part[1]));
}

/* Ritorna 1 se la condizione f appartiene al linguaggio di 18r, e allora ne
 * registra le condizioni in congruences[]. *deepest, che chi chiama mette a
 * zero, riceve il massimo numero di variabili in vista insieme, cioè quanti
 * quantificatori sui resti stanno uno dentro l'altro. Nessuna variabile deve
 * essere legata: i conti si fanno sulle lettere. */
static int congruences_read(const Formula *f, int *deepest) {
    Num divisor;
    if (failure) return 0;
    switch (f->kind) {
    case F_NOT:
        return congruences_read(f->a, deepest);
    case F_AND: case F_OR: case F_IMPLIES: case F_IFF:
        return congruences_read(f->a, deepest) && congruences_read(f->b, deepest);
    case F_DIVIDES:
        return rat_number(eval(f->left), &divisor) && !num_is_zero(divisor) && congruence_add(f, rat_div(eval(f->right), eval(f->left)));
    case F_IN:
        /* Solo "è un intero": stare in un insieme con un estremo o con dei
         * punti tolti non dipende dal resto. */
        return f->numbers.integers && !f->numbers.bounded && !f->numbers.holes && congruence_add(f, eval(f->left));
    case F_FORALL: case F_EXISTS: case F_SOLVE: {
        if (names_a_multiple(f)) return multiples_read(f->a, f->variable);
        if (!f->numbers.integers ||
            !work_reserve((void **)&residue_name, &residue_name_capacity, (size_t)residue_count + 1, sizeof *residue_name) ||
            !work_reserve((void **)&residue_value, &residue_value_capacity, (size_t)residue_count + 1, sizeof *residue_value)) return 0;
        residue_name[residue_count++] = f->variable;
        if (residue_count > *deepest) *deepest = residue_count;
        int known = congruences_read(f->a, deepest);
        residue_count--;
        return known;
    }
    default:
        return 0;
    }
}

/* Ritorna 1 se, con i resti dati alle variabili in vista, vale la condizione
 * registrata per il nodo source: il dividendo è multiplo del modulo. I conti
 * si fanno modulo il modulo, quindi con numeri piccoli. */
static int congruence_holds(const Formula *source) {
    const Congruence *c = congruences;
    while (c->source != source) c++;
    __int128 total = 0;
    for (int i = 0; i < c->dividend.count; i++) {
        const Term *t = &c->dividend.term[i];
        __int128 product = t->coef.re.num % c->modulus;
        for (int k = 0; k < t->mono.count; k++) {
            long long value = 0;
            for (int v = 0; v < residue_count; v++)
                if (atom_var(residue_name[v]) == t->mono.factor[k].atom) value = residue_value[v] % c->modulus;
            for (long long e = 0; e < t->mono.factor[k].exp.num; e++) product = product * value % c->modulus;
        }
        total = (total + product) % c->modulus;
    }
    return total == 0;
}

/* 18r. Ritorna 1 se la condizione f, che congruences_read() ha accettato, è
 * vera con i resti dati alle variabili in vista. Un quantificatore prova
 * tutti i resti della sua variabile, da 0 a residue_period - 1. */
static int residue_holds(const Formula *f) {
    switch (f->kind) {
    case F_NOT:     return !residue_holds(f->a);
    case F_AND:     return residue_holds(f->a) && residue_holds(f->b);
    case F_OR:      return residue_holds(f->a) || residue_holds(f->b);
    case F_IMPLIES: return !residue_holds(f->a) || residue_holds(f->b);
    case F_IFF:     return residue_holds(f->a) == residue_holds(f->b);
    case F_DIVIDES: case F_IN:
        return congruence_holds(f) != f->swapped;
    case F_EQUAL:   return congruence_holds(f);
    default:        break;
    }

    /* "Esiste k con L = R": una delle uguaglianze, cioè delle condizioni. */
    if (names_a_multiple(f)) return residue_holds(f->a);

    /* Un quantificatore su una variabile intera. */
    int every = f->kind == F_FORALL, holds = every;
    residue_name[residue_count++] = f->variable;
    for (long long r = 0; r < residue_period && holds == every; r++) {
        residue_value[residue_count - 1] = r;
        holds = residue_holds(f->a);
    }
    residue_count--;
    return holds;
}

/* =============================================================================
 * 18.8 LA TABELLA DEI SEGNI (18p): NUMERI E POLINOMI ESATTI, I PUNTI
 * ============================================================================
 *
 * Questo capitolo e i seguenti, fino al 18.16, sono la regola 18p. Qui il
 * metodo e la sua parte esatta: i razionali a 128 bit, i polinomi in una
 * variabile, le catene di Sturm, la base e i punti della tabella. Le lettere
 * per esponenziali, logaritmi e funzioni goniometriche sono nel capitolo 18.9,
 * l'albero dei segni nel 18.10, i confronti preparati nel 18.11, i controlli
 * con i numeri nel 18.12, le righe e le soluzioni nei 18.13 e 18.14, il
 * grafico nel 18.15, il verdetto e il certificato nel 18.16.
 *
 * 18p. UNA SOLA VARIABILE: LA TABELLA DEI SEGNI
 *
 * Gli enunciati di questa regola hanno una variabile sola, che varia nei
 * numeri reali o nei razionali, e confrontano espressioni razionali con =,
 * \neq, <, \le, >, \ge. Sono le equazioni e le disequazioni dei libri di
 * scuola scritte insieme al loro risultato, per esempio
 *
 *     \forall x \in \mathbb{R}\ (\frac{x - 2}{x + 3} \ge 0 \iff (x < -3 \lor x \ge 2))
 *
 * Che cosa vuol dire un confronto dove un'espressione non è definita. In
 * x = -3 la frazione non ha valore. La convenzione è quella dei libri: un
 * confronto vale in x solo se le espressioni che contiene sono definite in
 * x, quindi -3 non è una soluzione della disequazione. È una convenzione
 * diversa da quella del resto del capitolo, dove un'espressione non definita
 * ferma la dimostrazione: qui "per ogni x, A(x) se e solo se B(x)" confronta
 * due insiemi di soluzioni, e la dimostrazione scritta lo ricorda.
 *
 * Il metodo decide ogni enunciato di questa forma: risponde vero o falso,
 * mai "non so", salvo che i numeri escano dall'aritmetica esatta.
 *
 *   18p-1. Ogni confronto si porta alla forma N(x)/D(x) ? 0, con N e D
 *          polinomi a coefficienti interi. Che sia vero in x dipende solo
 *          dal segno di N e di D in x, e dal fatto che i divisori incontrati
 *          nel conto, anch'essi polinomi, lì siano diversi da zero.
 *
 *   18p-2. Un polinomio cambia segno solo passando per una sua radice: è
 *          una funzione continua, e per il teorema degli zeri tra un valore
 *          positivo e uno negativo ne assume uno nullo. Tra due radici
 *          consecutive di tutti i polinomi in gioco ogni segno è dunque
 *          costante, e con i segni lo è la verità dell'enunciato. Basta
 *          guardarla in ogni radice e in un punto qualsiasi di ogni
 *          intervallo tra due radici: è la tabella dei segni.
 *
 *   18p-3. Le radici non serve calcolarle, basta separarle. Teorema di
 *          Sturm: per un polinomio p senza radici multiple si costruisce la
 *          catena p_0 = p, p_1 = p', p_{i+1} = -resto(p_{i-1} : p_i), fino a
 *          una costante. Detto V(x) il numero di cambi di segno nella lista
 *          p_0(x), p_1(x), ... (saltando gli zeri), il numero di radici
 *          reali di p tra a e b, con a < b che non sono radici, è
 *          V(a) - V(b). Dimezzando un intervallo che le contiene tutte si
 *          arriva a intervalli con una radice sola ciascuno.
 *
 *   18p-4. Polinomi diversi possono avere radici in comune, e allora due
 *          intervalli potrebbero nascondere la stessa radice. Lo si evita
 *          lavorando su una "base": polinomi senza radici multiple e a due a
 *          due senza radici comuni, di cui ogni polinomio in gioco è un
 *          prodotto (a meno di esponenti). La si costruisce con il massimo
 *          comun divisore: se g = mcd(a, b) non è costante, al posto di a e
 *          b si mettono a/g, b/g e g. Radici di elementi diversi della base
 *          sono numeri diversi, quindi stringendo gli intervalli prima o poi
 *          si separano.
 *
 *   18p-5. Il segno di un polinomio p in una radice r, isolata in (a, b), di
 *          un elemento q della base. Se q divide p, p(r) = 0. Altrimenti p e
 *          q non hanno radici comuni, p non si annulla in tutto (a, b)
 *          (l'unica radice lì dentro è r) e ha quindi il segno che ha nel
 *          punto medio, che è un numero razionale e si calcola.
 *
 *   18p-6. Un elemento della base di grado quattro o più si prova a
 *          scomporlo in fattori di secondo grado (uni_quadratic_factor()).
 *          Alla decisione non serve: serve a scrivere le radici con i
 *          radicali, come sui libri, invece che con un nome.
 *
 * Le regole che seguono portano alla stessa tabella confronti che non sono
 * tra frazioni di polinomi; ognuna è spiegata dove è scritta.
 *
 *   18p-7.  Radici quadrate e valori assoluti: ogni radice è una lettera, e
 *           il segno di P + Q s viene da quelli di P, Q e P^2 - Q^2 R.
 *   18p-8.  Esponenziali e logaritmi: una lettera per p^(x/L) o per
 *           log_b f(x), con i suoi gradini.
 *   18p-9.  Monomi di potenze di basi diverse.
 *   18p-10. Numeri con logaritmi, e e pi tra i coefficienti e gli estremi.
 *   18p-11. Funzioni goniometriche: la lettera t = tan(u / 2).
 *   18p-12. Le soluzioni di una condizione periodica, scritte con k.
 *   18p-13. Le famiglie x = a + k T di un risultato, dentro un enunciato.
 *   18p-14. Le finestre: una condizione periodica ristretta a un intervallo.
 *
 * E una regola che non decide nulla, ma fa ricontrollare ciò che si è
 * deciso:
 *
 *   18p-15. Il certificato: la tabella, data a checker.c, che la ricontrolla
 *           per conto suo (capitolo 12 di checker.c).
 *
 * Le radici razionali si trovano a parte, con il teorema delle radici
 * razionali, e si tolgono: così ogni punto medio, che è razionale, non è mai
 * una radice, e nei numeri razionali si sa quali punti della tabella contano.
 *
 * Risolvere. La stessa tabella dà l'insieme delle soluzioni di una
 * condizione, \{x \in \mathbb{R} \mid ...\}: le righe consecutive in cui la
 * condizione vale sono un intervallo o un punto, e messe in fila sono la
 * risposta (sign_solution()). Nessuna formula risolutiva per un tipo di
 * equazione: è lo stesso metodo generale, letto in un altro modo.
 *
 * I controlli indipendenti sono due, e nessuno dei due usa polinomi in una
 * variabile o radici. Il primo rifà ogni riga della tabella. Una riga con un
 * valore razionale si rifà sostituendo il numero nell'enunciato, con il
 * calcolo esatto (sign_holds_at()); una riga in una radice irrazionale, in
 * un punto come ln 3, o di un enunciato periodico si rifà con gli intervalli
 * del capitolo 24 (range_truth()), dove un segno è certo oppure non si sa, e
 * un'uguaglianza si può solo trovare compatibile. Ogni intervallo si prova
 * anche in altri punti oltre a quello scelto (row_points()). Una riga
 * smentita è un errore del programma; una riga razionale che non si riesce a
 * rifare lascia l'enunciato non deciso. Il secondo rilegge le soluzioni
 * scritte, con il lettore del programma, e le confronta con la tabella
 * (solution_reread()); per una condizione periodica le confronta con la
 * condizione, calcolata con gli intervalli in molti valori e negli estremi
 * scritti. Ciò che resta scoperto: la rilettura quando una radice non ha
 * una scrittura con i radicali e riceve un nome; il verdetto lo dichiara.
 * Lì il controllo è quello degli script di tools/fuzz/, i cui oracoli fanno
 * i conti per conto loro.
 *
 * Il terzo controllo, dove arriva, è il certificato (18p-15): con frazioni
 * di polinomi e valori assoluti, senza radici, esponenziali, logaritmi e
 * funzioni goniometriche, la tabella intera va al verificatore, che ne
 * ricava da capo i polinomi, ne riconta le radici con le catene di Sturm e
 * ricalcola la verità di ogni riga. DIMOSTRATO, FALSO e RISOLTO valgono
 * allora solo se il verificatore accetta.
 */

/* Un razionale con numeratore e denominatore a 128 bit: i punti in cui si
 * dimezza un intervallo hanno denominatori che crescono in fretta.
 * Invariante: den > 0 e la frazione è ridotta. */
typedef struct {
    __int128 num, den;  /* il numeratore, con il segno, e il denominatore */
} Wide;

/* Il messaggio quando un conto della tabella esce dai 128 bit. */
static const char *const SIGN_LIMIT = "numeri troppo grandi per la tabella dei segni";

/* Ritorna num/den ridotta, con den diverso da zero. */
static Wide wide_make(__int128 num, __int128 den) {
    __int128 g = gcd128(num, den);
    if (den < 0) g = -g;
    return (Wide){num / g, den / g};
}

/* Ritorna il segno di a - b. */
static int wide_cmp(Wide a, Wide b) {
    __int128 left, right;
    if (__builtin_mul_overflow(a.num, b.den, &left) || __builtin_mul_overflow(b.num, a.den, &right)) { fail(SIGN_LIMIT); return 0; }
    return (left > right) - (left < right);
}

/* Ritorna il punto medio tra a e b. */
static Wide wide_mid(Wide a, Wide b) {
    __int128 x, y, den;
    if (__builtin_mul_overflow(a.num, b.den, &x) || __builtin_mul_overflow(b.num, a.den, &y) || __builtin_add_overflow(x, y, &x) ||
        __builtin_mul_overflow(a.den, b.den, &den) || __builtin_mul_overflow(den, (__int128)2, &den)) { fail(SIGN_LIMIT); return a; }
    return wide_make(x, den);
}

/* Ritorna a + b. */
static Wide wide_add(Wide a, Wide b) {
    __int128 x, y, den;
    if (__builtin_mul_overflow(a.num, b.den, &x) || __builtin_mul_overflow(b.num, a.den, &y) || __builtin_add_overflow(x, y, &x) ||
        __builtin_mul_overflow(a.den, b.den, &den)) { fail(SIGN_LIMIT); return a; }
    return wide_make(x, den);
}

/* Ritorna a * b. */
static Wide wide_mul(Wide a, Wide b) {
    __int128 num, den;
    if (__builtin_mul_overflow(a.num, b.num, &num) || __builtin_mul_overflow(a.den, b.den, &den)) { fail(SIGN_LIMIT); return a; }
    return wide_make(num, den);
}

/* Ritorna la parte intera della radice quadrata di v, con 0 <= v < 2^126.
 * Metodo di Newton sugli interi: partendo da una stima per eccesso, la
 * successione r -> (r + v / r) / 2 scende, e si ferma sulla parte intera
 * della radice. */
static __int128 wide_isqrt(__int128 v) {
    if (v < 2) return v;
    __int128 r = (__int128)1 << 63;
    for (;;) {
        __int128 next = (r + v / r) / 2;
        if (next >= r) return r;
        r = next;
    }
}

/* Ritorna un razionale strettamente tra a e b, con a < b: quello con il
 * denominatore più piccolo, se ne esiste uno con denominatore fino a 64,
 * altrimenti il punto medio.
 *
 * Perché non sempre il punto medio: è il valore in cui si calcola una riga
 * della tabella, e il controllo indipendente lo sostituisce nell'enunciato
 * con le frazioni a 64 bit. Un'espressione di grado 9 in -31/16 ne esce, in
 * -7/4 no; e nella dimostrazione scritta "per esempio x = -7/4" si legge
 * meglio. */
static Wide wide_between(Wide a, Wide b) {
    for (__int128 d = 1; d <= 64 && !failure; d++) {
        /* Il più piccolo n con n/d > a è la parte intera di a d, più uno. La
         * divisione del C tronca verso lo zero: per i negativi si corregge. */
        __int128 scaled, n;
        if (__builtin_mul_overflow(a.num, d, &scaled)) break;
        n = scaled / a.den - (scaled % a.den < 0) + 1;

        /* n/d è ridotta: se non lo fosse, un denominatore più piccolo avrebbe
         * già dato lo stesso numero. */
        if (wide_cmp((Wide){n, d}, b) < 0) return (Wide){n, d};
    }
    return wide_mid(a, b);
}

/* Un polinomio in una variabile a coefficienti interi:
 * c[0] + c[1] x + ... + c[degree] x^degree. Invariante: c[degree] non è
 * zero; il polinomio nullo ha degree -1. */
typedef struct {
    int degree;
    __int128 c[MAX_UNI + 1];
} Uni;

/* Ristabilisce l'invariante dopo un conto che può aver annullato i
 * coefficienti più alti. */
static void uni_trim(Uni *p) {
    while (p->degree >= 0 && p->c[p->degree] == 0) p->degree--;
}

/* Divide p per il massimo comun divisore dei suoi coefficienti, che è
 * positivo: non cambia né le radici né i segni, e tiene piccoli i numeri. */
static void uni_primitive(Uni *p) {
    __int128 g = 0;
    for (int i = 0; i <= p->degree; i++) g = gcd128(g, p->c[i]);
    for (int i = 0; g > 1 && i <= p->degree; i++) p->c[i] /= g;
}

/* Cambia segno a p. */
static void uni_negate(Uni *p) {
    for (int i = 0; i <= p->degree; i++) p->c[i] = -p->c[i];
}

/* Ritorna 1 se a e b sono lo stesso polinomio. */
static int uni_equal(const Uni *a, const Uni *b) {
    return a->degree == b->degree && memcmp(a->c, b->c, sizeof a->c[0] * (size_t)(a->degree + 1)) == 0;
}

/* Ritorna la derivata di p. */
static Uni uni_derivative(const Uni *p) {
    Uni d;
    d.degree = p->degree > 0 ? p->degree - 1 : -1;
    for (int i = 1; i <= p->degree; i++)
        if (__builtin_mul_overflow(p->c[i], (__int128)i, &d.c[i - 1])) fail(SIGN_LIMIT);
    return d;
}

/* Ritorna un multiplo positivo del resto della divisione di a per b, che non
 * è il polinomio nullo.
 *
 * Per restare tra gli interi a ogni passo si moltiplica il resto per il
 * coefficiente direttivo di b prima di togliergli il multiplo di b che ne
 * annulla il termine più alto. Se quel coefficiente è negativo il segno si
 * rovescia: `negative` tiene il conto, perché alla catena di Sturm serve il
 * resto vero a meno di un fattore positivo, non a meno del segno. */
static Uni uni_remainder(const Uni *a, const Uni *b) {
    Uni r = *a;
    int negative = 0;
    while (r.degree >= b->degree && !failure) {
        __int128 lead = r.c[r.degree], scale = b->c[b->degree], part;
        int shift = r.degree - b->degree;
        for (int i = 0; i <= r.degree; i++) {
            if (__builtin_mul_overflow(r.c[i], scale, &r.c[i])) fail(SIGN_LIMIT);
            if (i >= shift && (__builtin_mul_overflow(lead, b->c[i - shift], &part) || __builtin_sub_overflow(r.c[i], part, &r.c[i]))) fail(SIGN_LIMIT);
        }
        if (scale < 0) negative = !negative;
        uni_trim(&r);
        uni_primitive(&r);
    }
    if (negative) uni_negate(&r);
    return r;
}

/* Ritorna il massimo comun divisore di a e b, con coefficienti senza
 * divisori comuni e coefficiente direttivo positivo (algoritmo di Euclide:
 * mcd(a, b) = mcd(b, resto)). */
static Uni uni_gcd(Uni a, Uni b) {
    while (b.degree >= 0 && !failure) {
        Uni r = uni_remainder(&a, &b);
        a = b;
        b = r;
    }
    uni_primitive(&a);
    if (a.degree >= 0 && a.c[a.degree] < 0) uni_negate(&a);
    return a;
}

/* Se b divide a mette il quoziente in *q e ritorna 1, altrimenti ritorna 0.
 * b non è nullo e i suoi coefficienti non hanno divisori comuni: allora, per
 * il lemma di Gauss, se divide a il quoziente ha coefficienti interi, e la
 * divisione si fa tra interi. */
static int uni_divide(const Uni *a, const Uni *b, Uni *q) {
    Uni r = *a;
    q->degree = a->degree - b->degree;
    if (a->degree < 0) { q->degree = -1; return 1; }
    if (q->degree < 0) return 0;
    for (int i = q->degree; i >= 0; i--) {
        __int128 lead = r.c[i + b->degree], part;
        if (lead % b->c[b->degree] != 0) return 0;
        q->c[i] = lead / b->c[b->degree];
        for (int j = 0; j <= b->degree; j++)
            if (__builtin_mul_overflow(q->c[i], b->c[j], &part) || __builtin_sub_overflow(r.c[i + j], part, &r.c[i + j])) { fail(SIGN_LIMIT); return 0; }
    }
    for (int i = 0; i < b->degree; i++)
        if (r.c[i] != 0) return 0;
    return 1;
}

/* Ritorna il segno di p nel razionale x. Schema di Horner senza frazioni:
 * con x = n/d si calcola il segno di p(x) d^degree, che è lo stesso perché
 * d è positivo.
 *
 * Per un polinomio di grado alto quel numero può non stare in 128 bit: capita
 * con gli angoli multipli della goniometria, dove sin(7u) è una frazione di
 * grado 14 in t. Allora il segno si prende con gli intervalli del capitolo
 * 24: lo stesso schema di Horner, in cui ogni operazione allarga l'intervallo
 * quanto basta a contenere il risultato vero. Se l'intervallo finale non
 * contiene lo zero il segno è certo. Se lo contiene, p(x) è zero oppure è
 * solo troppo vicino a zero per questi numeri: è zero esattamente quando
 * d t - n divide p, e la divisione è un conto tra interi; altrimenti non si
 * risponde. */
static int uni_sign_at(const Uni *p, Wide x) {
    __int128 value = 0, power = 1, term;
    int exact = 1, side = 0;
    for (int i = p->degree; i >= 0 && exact; i--)
        exact = !(__builtin_mul_overflow(value, x.num, &value) || __builtin_mul_overflow(p->c[i], power, &term) ||
                  __builtin_add_overflow(value, term, &value) || (i > 0 && __builtin_mul_overflow(power, x.den, &power)));
    if (exact) return (value > 0) - (value < 0);
    Range at = range_ratio(x.num, x.den), sum = {0, 0};
    Uni linear = {1, {-x.num, x.den}}, quotient;
    for (int i = p->degree; i >= 0; i--) sum = range_add(range_mul(sum, at), range_ratio(p->c[i], 1));
    if (range_side(sum, &side)) return side;
    if (!failure && !uni_divide(p, &linear, &quotient)) fail(SIGN_LIMIT);
    return 0;
}

/* Legge il polinomio negli atomi p come polinomio nel solo atomo x a
 * coefficienti razionali, moltiplicato per x^*shift se x vi compare con
 * esponenti negativi (un denominatore fatto di sole x): mette in *out il
 * polinomio a coefficienti interi che ha gli stessi segni di p x^*shift.
 * Ritorna 0 se p non ha questa forma: un altro atomo, un esponente non
 * intero, un coefficiente complesso, un grado oltre MAX_UNI. */
static int uni_from_poly(Poly p, int x, Uni *out, int *shift) {
    __int128 scale = 1;
    long long low = 0;
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        Frac e = t->mono.count ? t->mono.factor[0].exp : frac_int(0);
        if (t->mono.count > 1 || (t->mono.count == 1 && t->mono.factor[0].atom != x) || e.den != 1 || t->coef.im.num != 0) return 0;
        if (e.num < low) low = e.num;
        scale = scale / gcd128(scale, t->coef.re.den) * t->coef.re.den;
        if (scale > COEF_LIMIT) { fail(SIGN_LIMIT); return 0; }
    }
    *shift = (int)-low;
    out->degree = -1;
    memset(out->c, 0, sizeof out->c);
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        long long e = (t->mono.count ? t->mono.factor[0].exp.num : 0) - low;
        if (e > MAX_UNI) return 0;
        out->c[e] = (__int128)t->coef.re.num * (scale / t->coef.re.den);
        if (e > out->degree) out->degree = (int)e;
    }
    return 1;
}

/* La catena di Sturm del polinomio di cui si stanno separando le radici
 * (18p-3): sturm_length polinomi, il primo è il polinomio stesso. */
static Uni sturm[MAX_UNI + 2];
static int sturm_length;

/* Costruisce la catena di Sturm di p, che non ha radici multiple. */
static void sturm_build(const Uni *p) {
    sturm[0] = *p;
    sturm[1] = uni_derivative(p);
    sturm_length = 2;
    while (sturm[sturm_length - 1].degree > 0 && !failure) {
        Uni r = uni_remainder(&sturm[sturm_length - 2], &sturm[sturm_length - 1]);
        if (r.degree < 0) break;
        uni_negate(&r);
        sturm[sturm_length++] = r;
    }
}

/* Ritorna V(x): quanti cambi di segno ha la catena di Sturm nel razionale x,
 * saltando gli zeri. */
static int sturm_changes(Wide x) {
    int changes = 0, last = 0;
    for (int i = 0; i < sturm_length; i++) {
        int sign = uni_sign_at(&sturm[i], x);
        if (sign && last && sign != last) changes++;
        if (sign) last = sign;
    }
    return changes;
}

/* I polinomi dell'enunciato in corso: numeratori, denominatori e divisori
 * dei suoi confronti. La tabella dei segni ha una colonna per ognuno. */
static Uni sign_poly[MAX_CRITICAL];
static int sign_polys;

/* La base di 18p-4: polinomi senza radici multiple, a due a due senza radici
 * comuni, coefficienti senza divisori comuni e coefficiente direttivo
 * positivo. Ogni radice di un polinomio di sign_poly[] è radice di uno e un
 * solo elemento. Dopo sign_points() gli elementi di grado almeno 2 non hanno
 * più radici razionali. */
static Uni sign_base[2 * MAX_CRITICAL];
static int sign_bases;

/* Aggiunge al testo text, di size byte, un pezzo con la sintassi di printf.
 * Se non ci sta annota un errore: un testo troncato non si può presentare
 * come risultato. */
static void text_add(char *text, size_t size, const char *format, ...) {
    size_t used = strlen(text);
    va_list args;
    va_start(args, format);
    int wanted = vsnprintf(text + used, size - used, format, args);
    va_end(args);
    if (wanted < 0 || (size_t)wanted >= size - used) fail("risultato troppo lungo da scrivere");
}

/* Aggiunge a text, di size byte, il razionale v in LaTeX: 3, -\frac{5}{2}. */
static void wide_latex(Wide v, char *text, size_t size) {
    if (v.den == 1) text_add(text, size, "%lld", (long long)v.num);
    else text_add(text, size, "%s\\frac{%lld}{%lld}", v.num < 0 ? "-" : "", (long long)(v.num < 0 ? -v.num : v.num), (long long)v.den);
}

/* Scrive nella dimostrazione il razionale v, in LaTeX come wide_latex(): due
 * numeri di 64 bit e la frazione stanno comodamente in text. */
static void put_wide(Wide v) {
    char text[96] = "";
    wide_latex(v, text, sizeof text);
    proof_add("%s", text);
}

/* Scrive in text, di size byte, il razionale v come testo semplice: 3, -5/2. */
static void wide_text(Wide v, char *text, size_t size) {
    if (v.den == 1) snprintf(text, size, "%lld", (long long)v.num);
    else snprintf(text, size, "%lld/%lld", (long long)v.num, (long long)v.den);
}

/* Aggiunge a text, di size byte, il polinomio p nella lettera name, in LaTeX. */
static void uni_latex(const Uni *p, int name, char *text, size_t size) {
    if (p->degree < 0) text_add(text, size, "0");
    for (int i = p->degree, first = 1; i >= 0; i--) {
        __int128 c = p->c[i], magnitude = c < 0 ? -c : c;
        if (c == 0) continue;
        text_add(text, size, "%s", first ? (c < 0 ? "-" : "") : (c < 0 ? " - " : " + "));
        if (magnitude != 1 || i == 0) text_add(text, size, "%lld", (long long)magnitude);
        if (i > 0) text_add(text, size, "%c", name);
        if (i > 1) text_add(text, size, "^{%d}", i);
        first = 0;
    }
}

/* Scrive nella dimostrazione il polinomio p nella lettera name. */
static void put_uni(const Uni *p, int name) {
    char text[512] = "";
    uni_latex(p, name, text, sizeof text);
    proof_add("%s", text);
}

/* Porta fuori dalla radice quadrata di *inside i suoi fattori quadrati, come
 * in sqrt(12) = 2 sqrt(3): lascia in *inside ciò che resta sotto la radice e
 * ritorna il numero che va davanti, così che il radicando di partenza sia
 * quel numero al quadrato per *inside. Si provano i fattori fino a 100000:
 * un quadrato più grande resta dentro, e la scrittura è giusta, solo meno
 * semplice. */
static __int128 square_out(__int128 *inside) {
    __int128 outside = 1;
    for (__int128 f = 2; f * f <= *inside && f < 100000; f++)
        while (*inside % (f * f) == 0) { *inside /= f * f; outside *= f; }
    return outside;
}

/* Aggiunge a text, di size byte, una radice del polinomio di secondo grado
 * q = a x^2 + b x + c, che ha due radici reali irrazionali, scritta con i
 * radicali; smaller dice se è la più piccola delle due. Ritorna 0, senza
 * scrivere nulla, se q non ha grado due o ha coefficienti troppo grandi.
 *
 * Le radici sono (-b - sqrt(D)) / 2a e (-b + sqrt(D)) / 2a con
 * D = b^2 - 4ac, e quella con il segno meno, portato il denominatore a
 * essere positivo, è la più piccola. Da sqrt(D) si portano fuori i
 * quadrati: sqrt(12) = 2 sqrt(3). */
static int quadratic_latex(const Uni *q, int smaller, char *text, size_t size) {
    __int128 limit = (__int128)1 << 30, a = q->c[2], b = q->c[1], c = q->c[0];
    if (q->degree != 2 || a >= limit || a <= -limit || b >= limit || b <= -limit || c >= limit || c <= -limit) return 0;

    /* (top + side * outside * sqrt(inside)) / bottom, con bottom > 0. */
    __int128 inside = b * b - 4 * a * c, top = a < 0 ? b : -b, bottom = a < 0 ? -2 * a : 2 * a;
    __int128 outside = square_out(&inside);
    __int128 g = gcd128(gcd128(top, outside), bottom);
    top /= g; outside /= g; bottom /= g;
    if (bottom != 1 && top == 0 && smaller) text_add(text, size, "-");
    if (bottom != 1) text_add(text, size, "\\frac{");
    if (top != 0) text_add(text, size, "%lld %s ", (long long)top, smaller ? "-" : "+");
    else if (smaller && bottom == 1) text_add(text, size, "-");
    if (outside != 1) text_add(text, size, "%lld", (long long)outside);
    text_add(text, size, "\\sqrt{%lld}", (long long)inside);
    if (bottom != 1) text_add(text, size, "}{%lld}", (long long)bottom);
    return 1;
}

/* Un punto in cui può cambiare la verità dell'enunciato. Se exact è 1 il
 * punto è il razionale low (uguale a high). Altrimenti, se element non è
 * negativo, è la sola radice di sign_base[element] tra low e high, che non
 * sono radici, ed è irrazionale. Altrimenti è il numero kappa[kappa], che
 * non è radice di nessun polinomio (un logaritmo, per esempio): di lui si
 * sa solo che sta tra low e high. */
typedef struct {
    int exact;       /* 1 se il punto è il razionale low */
    Wide low, high;  /* l'intervallo chiuso che contiene il punto */
    int element;     /* il posto in sign_base[] del polinomio di cui è la sola
                        radice tra low e high; -1 per un punto esatto o kappa */
    int kappa;       /* il posto in kappa[]; -1 se il punto è una radice */
} Critical;

/* Un numero reale che non è radice di un polinomio a coefficienti razionali,
 * e che entra nella tabella come punto: log_2 3, e^2. Lo si conosce con un
 * intervallo che lo contiene (capitolo 24) e con il testo che lo scrive. */
typedef struct {
    Range value;
    char text[96];  /* in LaTeX, come va scritto nelle soluzioni */
    int exact;      /* 1 se number è valido */
    Rat number;     /* lo stesso numero come frazione negli atomi che sono
                       numeri (logaritmi di primi, il numero e): serve a
                       riconoscere due scritture dello stesso numero */
} Kappa;

/* I numeri così dell'enunciato in corso: li aggiunge sign_column_kappa(). */
static Kappa kappa[MAX_KAPPAS];
static int kappas;

/* I due tipi di spazio (18p-8). */
typedef enum {
    SPACE_EXP,  /* la lettera è p^(x/L): un esponenziale, sempre positivo */
    SPACE_LOG   /* la lettera è il logaritmo in base b di un'espressione */
} SpaceKind;

/* Un gradino di uno spazio: una radice reale di un polinomio nella lettera
 * dello spazio, cioè un valore in cui un confronto può cambiare. Il valore è
 * il razionale low (exact = 1) oppure la sola radice di element tra low e
 * high. Dire che la lettera sta sopra, sotto o sul gradino è un confronto
 * nella variabile dell'enunciato: lo dà above (il segno di left - right),
 * oppure la colonna kappa quando il confronto è con un numero che non è
 * radice di un polinomio. */
typedef struct {
    int exact;             /* 1 se il gradino è il razionale low */
    Wide low, high;        /* l'intervallo chiuso che lo contiene */
    Uni element;           /* gradino irrazionale: il polinomio di cui è la sola
                              radice tra low e high */
    const Formula *above;  /* NULL se si usa kappa */
    int kappa;             /* posto in sign_poly[], o -1 */
} Step;

/* Uno spazio: una funzione della variabile, crescente, che nei conti della
 * tabella è una lettera sola. I polinomi nella lettera sono colonne con il
 * numero dello spazio in sign_space[]; i gradini, in ordine crescente, sono
 * le loro radici reali. Gli spazi valgono per l'enunciato in corso. */
typedef struct {
    SpaceKind kind;
    long long prime;       /* SPACE_EXP: il primo p; 0 per il numero e */
    long long scale;       /* SPACE_EXP: L, con la lettera uguale a p^(x/L) */
    Frac base;             /* SPACE_LOG: la base b > 1 */
    int natural;           /* SPACE_LOG: 1 se la base è il numero e */
    const Node *argument;  /* SPACE_LOG: l'argomento, com'è scritto */
    int letter;            /* l'atomo che sta per la funzione */
    int steps;             /* quanti gradini, in step[] */
    Step step[MAX_STEPS];  /* i gradini, in ordine crescente (space_process()) */
} Space;

/* Gli spazi dell'enunciato in corso: li crea space_collect(), con
 * space_exp() e space_log(). */
static Space space[MAX_SPACES];
static int spaces;

/* Lo stato della tabella che serve agli agganci di eval(): space_live è 1
 * mentre si prepara un confronto (solo allora potenze e logaritmi diventano
 * lettere); space_seen ha il bit s se nel confronto in corso è comparso il
 * logaritmo dello spazio s; sign_name e sign_x sono la variabile
 * dell'enunciato, come lettera e come atomo. */
static int space_live;
static unsigned space_seen;
static int sign_name, sign_x;

/* I punti dell'enunciato in corso. Dopo sign_points() sono in ordine
 * crescente e i loro intervalli chiusi [low, high] non si toccano. */
static Critical sign_point[MAX_POINTS];
static int sign_points_count;

/* Che cos'è ogni colonna, oltre al suo polinomio. sign_space[i] dice in
 * quale lettera è il polinomio: -1 nella variabile dell'enunciato,
 * altrimenti nella lettera dello spazio con quel numero (18p-8).
 * sign_kappa[i], se non è -1, dice che la colonna non ha un polinomio: è il
 * segno di x - kappa[sign_kappa[i]], che si legge dalla posizione della riga
 * rispetto a quel punto. */
static int sign_space[MAX_CRITICAL], sign_kappa[MAX_CRITICAL];

/* Ritorna il posto in sign_poly[] del polinomio p nella lettera dello spazio
 * `where` (-1: la variabile), aggiungendolo se manca. Lo si conserva senza
 * divisori comuni tra i coefficienti; il segno resta. */
static int sign_column_in(Uni p, int where) {
    uni_primitive(&p);
    for (int i = 0; i < sign_polys; i++)
        if (sign_space[i] == where && sign_kappa[i] < 0 && uni_equal(&sign_poly[i], &p)) return i;
    if (sign_polys == MAX_CRITICAL) { fail("troppi polinomi diversi nella tabella dei segni"); return 0; }
    sign_poly[sign_polys] = p;
    sign_space[sign_polys] = where;
    sign_kappa[sign_polys] = -1;
    return sign_polys++;
}

/* Lo stesso, per un polinomio nella variabile dell'enunciato. */
static int sign_column(Uni p) { return sign_column_in(p, -1); }

/* Ritorna il posto della colonna "x - k", dove k è il numero che sta
 * nell'intervallo value e si scrive text; la aggiunge se manca. number, se
 * non è NULL, è lo stesso numero come frazione esatta. Due numeri sono lo
 * stesso se sono scritti allo stesso modo, o se la differenza delle loro
 * frazioni esatte è la frazione nulla: così log_3 2 e ln 2 / ln 3, che
 * nascono da due parti diverse di un enunciato, sono un punto solo. Senza
 * questo sarebbero due punti impossibili da separare. */
static int sign_column_kappa(Range value, const char *text, const Rat *number) {
    for (int i = 0; i < sign_polys; i++) {
        if (sign_kappa[i] < 0) continue;
        const Kappa *other = &kappa[sign_kappa[i]];
        if (strcmp(other->text, text) == 0 || (number && other->exact && rat_add(*number, other->number, 1).num.count == 0)) return i;
    }
    if (sign_polys == MAX_CRITICAL || kappas == MAX_KAPPAS || strlen(text) >= sizeof kappa[0].text || !range_known(value)) {
        fail("troppi punti con logaritmi nella tabella dei segni, o un punto che non so calcolare");
        return 0;
    }
    kappa[kappas].value = value;
    kappa[kappas].exact = number != NULL;
    if (number) kappa[kappas].number = *number;
    strcpy(kappa[kappas].text, text);
    sign_poly[sign_polys] = (Uni){-1, {0}};
    sign_space[sign_polys] = -1;
    sign_kappa[sign_polys] = kappas++;
    return sign_polys++;
}

/* Aggiunge un elemento alla base, se c'è posto. */
static void base_append(Uni p) {
    if (sign_bases == 2 * MAX_CRITICAL) { fail("troppi polinomi diversi nella tabella dei segni"); return; }
    sign_base[sign_bases++] = p;
}

/* 18p-4. Inserisce nella base le radici di p, che non è costante.
 *
 * Prima si tolgono a p le radici multiple: s = p / mcd(p, p') ha le stesse
 * radici, ognuna una volta sola. Poi s si confronta con ogni elemento b: se
 * hanno un fattore comune g, b diventa b/g, g entra nella base come elemento
 * nuovo e s diventa s/g. I pezzi restano senza radici comuni perché né b né
 * s hanno radici multiple. Ciò che avanza di s è un elemento nuovo. */
static void base_insert(const Uni *p) {
    Uni d = uni_derivative(p), g = uni_gcd(*p, d), s, rest;
    if (failure || !uni_divide(p, &g, &s)) { fail(SIGN_LIMIT); return; }
    uni_primitive(&s);
    if (s.c[s.degree] < 0) uni_negate(&s);
    for (int i = 0; i < sign_bases && s.degree > 0 && !failure; i++) {
        g = uni_gcd(s, sign_base[i]);
        if (g.degree <= 0) continue;
        if (!uni_divide(&sign_base[i], &g, &rest)) { fail(SIGN_LIMIT); return; }
        if (rest.degree > 0) {
            if (rest.c[rest.degree] < 0) uni_negate(&rest);
            sign_base[i] = rest;
            base_append(g);
        }
        if (!uni_divide(&s, &g, &rest)) { fail(SIGN_LIMIT); return; }
        s = rest;
        if (s.degree >= 0 && s.c[s.degree] < 0) uni_negate(&s);
    }
    if (s.degree > 0 && !failure) base_append(s);
}

/* Aggiunge ai punti il razionale value. */
static void point_exact(Wide value) {
    if (sign_points_count == MAX_POINTS) { fail("troppi punti nella tabella dei segni"); return; }
    sign_point[sign_points_count++] = (Critical){1, value, value, -1, -1};
}

/* 18p-3. Aggiunge ai punti le radici di sign_base[element] tra low e high,
 * che sono `roots`, dimezzando l'intervallo finché ne contiene una sola. La
 * catena di Sturm è già quella dell'elemento, che non ha radici razionali:
 * il punto medio non è mai una radice. */
static void point_isolate(int element, Wide low, Wide high, int roots) {
    if (roots <= 0 || failure) return;
    if (roots == 1) {
        if (sign_points_count == MAX_POINTS) { fail("troppi punti nella tabella dei segni"); return; }
        sign_point[sign_points_count++] = (Critical){0, low, high, element, -1};
        return;
    }
    Wide mid = wide_mid(low, high);
    int left = sturm_changes(low) - sturm_changes(mid);
    point_isolate(element, low, mid, left);
    point_isolate(element, mid, high, roots - left);
}

/* Dimezza l'intervallo del punto p, che non è esatto, tenendo la metà che
 * contiene la radice: quella ai cui estremi il polinomio ha segni opposti,
 * perché la radice è semplice. */
static void point_refine(Critical *p) {
    /* Un punto che non è radice di un polinomio non si può stringere. */
    if (p->element < 0) return;
    Wide mid = wide_mid(p->low, p->high);
    const Uni *b = &sign_base[p->element];
    if (uni_sign_at(b, mid) == uni_sign_at(b, p->low)) p->low = mid; else p->high = mid;
}

/* Confronto tra punti per qsort, valido quando gli intervalli non si
 * toccano: decide l'estremo inferiore. */
static int point_order(const void *a, const void *b) {
    return wide_cmp(((const Critical *)a)->low, ((const Critical *)b)->low);
}

/* Ritorna un intero che supera in valore assoluto ogni radice reale di p,
 * che non è costante.
 *
 * Limite di Fujiwara. Sia d il grado, e B tale che per ogni i < d valga
 * |c_i| <= |c_d| (B/2)^{d-i}. Se |x| >= B allora
 *
 *     |c_i x^i| <= |c_d| (B/2)^{d-i} |x|^i <= |c_d| |x|^d / 2^{d-i},
 *
 * e sommando su i < d si resta sotto |c_d x^d| (1/2 + 1/4 + ...): il termine
 * di grado più alto non può essere compensato, quindi x non è una radice.
 * Rispetto al limite di Cauchy, 1 + max |c_i / c_d|, questo tiene conto dei
 * gradi: per x^8 + 10^8 dà 32 invece di cento milioni, e i conti nei punti
 * estremi restano piccoli. Si prova B = 2, 4, 8, ... */
static Wide uni_bound(const Uni *p) {
    __int128 lead = p->c[p->degree] < 0 ? -p->c[p->degree] : p->c[p->degree];
    for (__int128 half = 1; ; half *= 2) {
        int enough = 1;
        for (int i = 0; i < p->degree && enough; i++) {
            /* |c_i| <= lead * half^(d-i)? Se il prodotto esce dai 128 bit è
             * certamente abbastanza grande. */
            __int128 size = p->c[i] < 0 ? -p->c[i] : p->c[i], right = lead;
            for (int k = 0; k < p->degree - i && right < size; k++)
                if (__builtin_mul_overflow(right, half, &right)) right = size;
            enough = right >= size;
        }
        if (enough) return (Wide){2 * half + 1, 1};
        if (half > ((__int128)1 << 100)) { fail(SIGN_LIMIT); return (Wide){1, 1}; }
    }
}

/* Mette in list[], che ha `room` posti, i divisori positivi di value, che
 * non è zero, e ne ritorna il numero; -1 se non ci stanno. */
static int divisors_of(long long value, long long *list, int room) {
    int count = 0;
    if (value < 0) value = -value;
    for (long long d = 1; d <= value; d++) {
        if (value % d) continue;
        if (count == room) return -1;
        list[count++] = d;
    }
    return count;
}

/* 18p-6. Cerca un fattore di secondo grado, a coefficienti interi, di p, che
 * ha coefficienti interi senza divisori comuni e nessuna radice razionale.
 * Se lo trova lo mette in *factor, mette il quoziente in *rest e ritorna 1.
 *
 * A che cosa serve. La base separa le radici di polinomi diversi, ma non
 * scompone un polinomio: (x^2 - 2)(x^2 + 3) resta x^4 + x^2 - 6, e le sue
 * radici reali si potrebbero indicare solo con un nome. Trovato il fattore
 * x^2 - 2 si scrivono come sui libri: -\sqrt{2} e \sqrt{2}.
 *
 * Metodo di Kronecker. Se q, a coefficienti interi senza divisori comuni,
 * divide p, il quoziente ha coefficienti interi (lemma di Gauss); quindi per
 * ogni intero t il numero q(t) divide p(t). Un polinomio di secondo grado
 * A x^2 + B x + C è determinato dai valori in tre punti; con 0, 1 e -1:
 *
 *     q(0) = C,    q(1) = A + B + C,    q(-1) = A - B + C,
 *
 * cioè A = (q(1) + q(-1)) / 2 - C e B = (q(1) - q(-1)) / 2. Si provano tutte
 * le terne di divisori di p(0), p(1) e p(-1), che non sono zero perché p non
 * ha radici razionali, e ogni candidato si controlla con una divisione. Le
 * terne sono in numero finito, quindi la ricerca è completa: se non trova
 * nulla, p non ha fattori di secondo grado. q e -q sono lo stesso fattore:
 * basta C positivo.
 *
 * Con valori oltre KRONECKER_LIMIT, o con più di KRONECKER_DIVISORS divisori,
 * non cerca: non è un errore, le radici avranno un nome. */
static int uni_quadratic_factor(const Uni *p, Uni *factor, Uni *rest) {
    long long at[3] = {0, 0, 0}, list[3][KRONECKER_DIVISORS];
    int count[3];

    /* p(0), p(1) e p(-1), e i loro divisori. */
    for (int i = 0; i <= p->degree; i++) {
        if (p->c[i] > KRONECKER_LIMIT || p->c[i] < -KRONECKER_LIMIT) return 0;
        if (i == 0) at[0] = (long long)p->c[0];
        at[1] += (long long)p->c[i];
        at[2] += i % 2 ? -(long long)p->c[i] : (long long)p->c[i];
    }
    for (int i = 0; i < 3; i++) {
        if (at[i] == 0 || at[i] > KRONECKER_LIMIT || at[i] < -KRONECKER_LIMIT) return 0;
        count[i] = divisors_of(at[i], list[i], KRONECKER_DIVISORS);
        if (count[i] < 0) return 0;
    }

    /* Ogni terna, con i due segni per q(1) e q(-1). */
    for (int i = 0; i < count[0]; i++)
        for (int j = 0; j < 2 * count[1]; j++)
            for (int k = 0; k < 2 * count[2]; k++) {
                long long zero = list[0][i], plus = j % 2 ? -list[1][j / 2] : list[1][j / 2], minus = k % 2 ? -list[2][k / 2] : list[2][k / 2];
                if ((plus + minus) % 2 || (plus + minus) / 2 == zero) continue;
                *factor = (Uni){2, {zero, (plus - minus) / 2, (plus + minus) / 2 - zero}};
                uni_primitive(factor);
                if (uni_divide(p, factor, rest)) return 1;
                if (failure) return 0;
            }
    return 0;
}

/* Trova i punti della tabella: tutte le radici reali dei polinomi di
 * sign_poly[], ognuna una volta, in ordine crescente.
 *
 * Serve sapere con certezza quali radici sono razionali: perché nei numeri
 * razionali contano solo quelle, e perché tolte quelle nessun punto medio
 * può più essere una radice. Quando non si riesce a stabilirlo (coefficienti
 * troppo grandi per elencarne i divisori) annota un errore. */
static void sign_points(int where) {
    sign_bases = sign_points_count = 0;
    for (int i = 0; i < sign_polys && !failure; i++)
        if (sign_space[i] == where && sign_poly[i].degree > 0) base_insert(&sign_poly[i]);

    /* Un elemento alla volta: prima le radici razionali, che si tolgono,
     * poi quelle di ciò che resta, con Sturm. */
    for (int k = 0; k < sign_bases && !failure; k++) {
        Uni *b = &sign_base[k];
        long long c[MAX_UNIVARIATE + 1];
        Frac root[MAX_UNIVARIATE + 2];
        int small = b->degree <= MAX_UNIVARIATE, found = -1;
        if (b->degree == 1) { point_exact(wide_make(-b->c[0], b->c[1])); continue; }

        /* Quante radici reali ha in tutto: se nessuna, come x^2 + 1, non
         * serve altro. Gli estremi stanno oltre ogni radice (uni_bound),
         * quindi non sono radici. */
        Wide bound = uni_bound(b), minus = {-bound.num, 1};
        sturm_build(b);
        if (failure || sturm_changes(minus) - sturm_changes(bound) == 0) continue;

        /* Le radici razionali. */
        for (int i = 0; i <= b->degree && small; i++) {
            if (b->c[i] > LLONG_MAX / 4 || b->c[i] < -(LLONG_MAX / 4)) small = 0;
            else c[i] = (long long)b->c[i];
        }
        if (small) found = rational_roots(c, b->degree, root);
        if (found < 0) { fail("non riesco a stabilire quali radici di un polinomio sono razionali"); return; }
        for (int i = 0; i < found && !failure; i++) {
            Uni linear = {1, {-(__int128)root[i].num, root[i].den}}, rest;
            point_exact((Wide){root[i].num, root[i].den});
            if (!uni_divide(b, &linear, &rest)) { fail(SIGN_LIMIT); return; }
            *b = rest;
        }
        if (b->degree < 1 || failure) continue;

        /* 18p-6. I fattori di secondo grado diventano elementi a sé, in
         * fondo alla base: questo ciclo arriverà anche a loro. Un polinomio
         * di terzo grado senza radici razionali non ne ha. */
        Uni quadratic, rest;
        while (!failure && b->degree >= 4 && uni_quadratic_factor(b, &quadratic, &rest)) {
            base_append(quadratic);
            *b = rest;
        }
        if (failure) return;

        /* Le altre, che sono irrazionali. */
        bound = uni_bound(b);
        minus = (Wide){-bound.num, 1};
        sturm_build(b);
        point_isolate(k, minus, bound, sturm_changes(minus) - sturm_changes(bound));
    }

    /* I punti che non sono radici di polinomi, nella tabella della
     * variabile: ognuno con due razionali che lo chiudono, un passo di
     * griglia più in là dei due estremi del suo intervallo. */
    for (int i = 0; i < sign_polys && where < 0 && !failure; i++) {
        if (sign_kappa[i] < 0) continue;
        Range value = kappa[sign_kappa[i]].value;
        if (sign_points_count == MAX_POINTS || value.low < -1e9 || value.high > 1e9) { fail("troppi punti nella tabella dei segni"); return; }
        __int128 grid = (__int128)1 << 40, low = (__int128)(value.low * (double)grid) - 1, high = (__int128)(value.high * (double)grid) + 1;
        sign_point[sign_points_count++] = (Critical){0, wide_make(low, grid), wide_make(high, grid), -1, sign_kappa[i]};
    }

    /* Finché due intervalli si toccano si dimezza uno dei due che non sia un
     * punto esatto. Le radici sono numeri diversi, quindi finisce; due punti
     * che non sono radici e che non si riesce a separare fermano il conto. */
    for (int again = 1, rounds = 0; again && !failure; rounds++) {
        again = 0;
        if (rounds > 200) { fail(SIGN_LIMIT); return; }
        for (int i = 0; i < sign_points_count && !failure; i++)
            for (int j = i + 1; j < sign_points_count && !failure; j++) {
                Critical *p = &sign_point[i], *q = &sign_point[j];
                if (wide_cmp(p->high, q->low) < 0 || wide_cmp(q->high, p->low) < 0) continue;
                again = 1;
                if (!p->exact) point_refine(p);
                if (!q->exact) point_refine(q);
            }
    }

    /* Gli intervalli che isolano le radici irrazionali si stringono fino a
     * meno di un ottavo: non serve alla decisione, ma "la radice tra 5/4 e
     * 11/8" dice al lettore dov'è, "tra -3 e 3" no. Non di più, perché ogni
     * dimezzamento raddoppia i denominatori dei conti nei punti medi. */
    for (int i = 0; i < sign_points_count && !failure; i++) {
        Critical *p = &sign_point[i];
        __int128 gap, scale;
        while (!failure && !p->exact && p->element >= 0) {
            /* high - low = gap / scale, da confrontare con 1/8. */
            if (__builtin_mul_overflow(p->high.num, p->low.den, &gap) || __builtin_mul_overflow(p->low.num, p->high.den, &scale) ||
                __builtin_sub_overflow(gap, scale, &gap) || __builtin_mul_overflow(gap, (__int128)8, &gap) ||
                __builtin_mul_overflow(p->high.den, p->low.den, &scale)) { fail(SIGN_LIMIT); break; }
            if (gap < scale) break;
            point_refine(p);
        }
    }
    if (!failure) qsort(sign_point, (size_t)sign_points_count, sizeof *sign_point, point_order);
}

/* =============================================================================
 * 18.9 LE LETTERE DELLA TABELLA: ESPONENZIALI, LOGARITMI, FUNZIONI
 *      GONIOMETRICHE, FAMIGLIE
 * ============================================================================
 *
 * Ciò che non è una frazione di polinomi nella variabile lo diventa in
 * un'altra lettera: un esponenziale o un logaritmo (18p-8) è la lettera di
 * uno "spazio", una funzione goniometrica è una frazione in t = tan(u / 2)
 * (18p-11), una famiglia di soluzioni x = a + k T è un angolo (18p-13). Qui
 * si riconoscono queste forme e si registrano le lettere; eval() le usa
 * attraverso gli agganci dichiarati prima di eval_call() (capitolo 11). I
 * segni nelle lettere li calcola l'albero dei segni, nel capitolo 18.10.
 *
 * 18p-8. ESPONENZIALI E LOGARITMI
 *
 * 5^(x+2) - 4 * 5^(1-x) - 30 non è un polinomio in x, ma lo è nella lettera
 * t = 5^x: 25 t - 20 / t - 30. E il segno di un polinomio in t dipende solo
 * da dove sta t rispetto alle sue radici. Qui sta tutto il metodo: la
 * funzione t = 5^x cresce, quindi "t è sopra la radice r" vuol dire
 * "x è sopra log_5 r", che è un confronto nella x.
 *
 *   - Uno "spazio" è una funzione crescente della variabile trattata come
 *     lettera: p^(x/L) per un primo p (una potenza b^(a x + c) è un prodotto
 *     di potenze intere di queste lettere, per un numero), oppure log_b f(x)
 *     con b > 1 (un logaritmo in base minore di 1 è l'opposto di uno in base
 *     maggiore).
 *   - I "gradini" dello spazio sono le radici reali dei polinomi nella sua
 *     lettera, trovate come nella tabella (18p-3, 18p-4), in ordine.
 *   - Per ogni gradino r, il confronto "lettera - r" nella variabile:
 *       p^(x/L) - r   ha il segno di   x - L log_p r   (r > 0; se r <= 0
 *                                       l'esponenziale gli sta sempre sopra);
 *       log_b f - r   ha il segno di   f(x) - b^r.
 *     Se log_p r è un intero, o b^r un razionale o una radice quadrata, è un
 *     confronto che la tabella tratta già. Altrimenti x - L log_p r si
 *     annulla in un numero che non è radice di nessun polinomio a
 *     coefficienti razionali: entra nella tabella come punto a sé (Kappa), e
 *     il suo posto tra gli altri punti lo decidono gli intervalli del
 *     capitolo 24.
 *   - In una riga della tabella, contando i gradini che la lettera ha sotto
 *     di sé si sa in quale tratto si trova, e il segno di ogni polinomio su
 *     quel tratto si calcola in un punto razionale del tratto.
 *
 * Due casi si risolvono senza gradini. Una somma di logaritmi nella stessa
 * base con coefficienti razionali, più un numero, ha il segno di un
 * prodotto di potenze degli argomenti meno una potenza della base
 * (sign_log_linear()): è la regola "la somma dei logaritmi è il logaritmo
 * del prodotto", che vale dove gli argomenti sono positivi, cioè dove il
 * confronto ha un valore. E un polinomio in più lettere che è un prodotto
 * di polinomi in lettere diverse, come (2^x - 1)(5^x - 1), ha il segno del
 * prodotto dei segni (sign_ground()).
 *
 * Altre tre regole portano a queste forme ciò che è scritto in un altro
 * modo. La radice di un prodotto di esponenziali si estrae (exp_root()):
 * \sqrt[3]{11^{9x}} è 11^{3x}. Il logaritmo di una potenza, accanto al
 * logaritmo della base nello stesso confronto, è un suo multiplo
 * (alias_collect()). E un polinomio i cui termini sono potenze di uno
 * stesso rapporto di esponenziali, come 2 \cdot 4^x - 5 \cdot 6^x + 3 \cdot 9^x,
 * è un polinomio in quel rapporto (sign_one_ratio()).
 *
 * Che cosa resta fuori: la variabile sia all'esponente sia fuori senza che
 * il polinomio si spezzi (x + 2^x), esponenti non di primo grado, un
 * logaritmo o un rapporto di esponenziali uguale a un numero irrazionale
 * che non so scrivere, somme di logaritmi in basi diverse. Il programma lo
 * dice.
 */

/* Ritorna lo spazio dell'esponenziale di base il primo prime (0: il numero
 * e), creandolo se create non è zero; NULL se non c'è, o non c'è più posto. */
static Space *space_exp(long long prime, int create) {
    for (int s = 0; s < spaces; s++)
        if (space[s].kind == SPACE_EXP && space[s].prime == prime) return &space[s];
    if (!create || spaces == MAX_SPACES) return NULL;
    Space *sp = &space[spaces];
    memset(sp, 0, sizeof *sp);
    sp->kind = SPACE_EXP;
    sp->prime = prime;
    sp->scale = 1;
    sp->letter = atom_var(SURD_NAMES + MAX_SURDS + spaces++);
    return sp;
}

/* Ritorna il numero dello spazio del logaritmo in base base (o in base e,
 * se natural) dell'espressione argument, creandolo se create non è zero; -1
 * se non c'è, o non c'è più posto. Due logaritmi sono lo stesso spazio se
 * hanno la stessa base e l'argomento scritto allo stesso modo. */
static int space_log(Frac base, int natural, const Node *argument, int create) {
    for (int s = 0; s < spaces; s++)
        if (space[s].kind == SPACE_LOG && space[s].natural == natural && (natural || frac_cmp(space[s].base, base) == 0) && node_equal(space[s].argument, argument)) return s;
    if (!create || spaces == MAX_SPACES) return -1;
    Space *sp = &space[spaces];
    memset(sp, 0, sizeof *sp);
    sp->kind = SPACE_LOG;
    sp->base = base;
    sp->natural = natural;
    sp->argument = argument;
    sp->letter = atom_var(SURD_NAMES + MAX_SURDS + spaces);
    return spaces++;
}

/* Ritorna il numero dello spazio di cui l'atomo è la lettera, oppure
 * `spaces` se non è la lettera di nessuno spazio. */
static int space_of(int atom) {
    int s = 0;
    while (s < spaces && space[s].letter != atom) s++;
    return s;
}

/* Legge la base di una potenza o di un logaritmo. Ritorna 1 se node è il
 * numero e (*euler = 1), oppure un razionale positivo diverso da 1, che
 * mette in *value. La lettera e è il numero di Nepero quando non è la
 * variabile dell'enunciato né una variabile con un valore. */
static int constant_base(const Node *node, Frac *value, int *euler) {
    Num number;
    *euler = node->kind == N_VAR && node->name == 'e' && sign_name != 'e' && !env_lookup('e');
    if (*euler) return 1;
    if (node_uses_letter(node, sign_name)) return 0;
    Rat base = eval(node);
    if (failure || !rat_number(base, &number) || number.im.num != 0 || number.re.num <= 0 || number.re.num == number.re.den) return 0;
    *value = number.re;
    return 1;
}

/* Ritorna la radice m-esima intera di v > 0, o 0 se v non è una potenza
 * m-esima esatta. */
static long long exact_root(long long v, int m) {
    long long low = 1, high = v;
    while (low < high) {
        long long middle = low + (high - low) / 2, power = 1;
        for (int i = 0; i < m && power <= v; i++) power = power > v / middle ? v + 1 : power * middle;
        if (power < v) low = middle + 1; else high = middle;
    }
    long long power = 1;
    for (int i = 0; i < m; i++) power = power > v / low ? v + 1 : power * low;
    return power == v ? low : 0;
}

/* Legge la base del logaritmo node (FN_LN o FN_LOG) e la porta a una forma
 * sola: maggiore di 1, e non potenza di un altro razionale. Mette in *value
 * la base così ridotta e in *factor il numero per cui va moltiplicato il
 * logaritmo nella base ridotta per avere quello scritto:
 *
 *     log_(1/b) f = -log_b f,        log_(b^m) f = (log_b f) / m.
 *
 * Così log_9, log_3 e log_(1/3) dello stesso argomento sono multipli della
 * stessa lettera. Per il logaritmo naturale *euler = 1 e il fattore è 1. */
static int log_base(const Node *node, Frac *value, int *euler, Frac *factor) {
    *factor = frac_int(1);
    *euler = node->op == FN_LN;
    if (*euler) return 1;
    if (!node->b || !constant_base(node->b, value, euler)) return 0;
    if (*euler) return 1;
    if (value->num < value->den) {
        *value = (Frac){value->den, value->num};
        *factor = frac_int(-1);
    }
    for (int m = 40; m >= 2; m--) {
        long long top = exact_root(value->num, m), bottom = exact_root(value->den, m);
        if (!top || !bottom) continue;
        *value = (Frac){top, bottom};
        *factor = frac_div(*factor, frac_int(m));
        break;
    }
    return 1;
}

/* Il più piccolo multiplo comune di due interi positivi. */
static long long lcm_small(long long a, long long b) { return a / (long long)gcd128(a, b) * b; }

/* Registra gli spazi che servono all'espressione node: uno per ogni primo
 * della base di una potenza con la variabile all'esponente, uno per ogni
 * logaritmo con la variabile nell'argomento. Per gli esponenziali fissa
 * anche L, il più piccolo intero per cui ogni potenza è una potenza intera
 * di p^(x/L). Ciò che non ha la forma attesa viene lasciato stare: sarà il
 * conto vero a dire che non è trattato. */
static void space_collect(const Node *node) {
    Frac base, alpha, beta, factor;
    int euler;
    long long prime, times;
    if (!node || failure) return;
    space_collect(node->a);
    space_collect(node->b);
    space_collect(node->c);
    if (node->kind == N_POW && node_uses_letter(node->b, sign_name) && constant_base(node->a, &base, &euler) &&
        rat_affine_in(eval(node->b), sign_x, &alpha, &beta)) {
        Space *sp = euler ? space_exp(0, 1) : NULL;
        if (sp) sp->scale = lcm_small(sp->scale, alpha.den);
        for (int side = 0; side < 2 && !euler; side++) {
            long long value = side ? base.den : base.num;
            while (pop_prime(&value, &prime, &times)) {
                sp = space_exp(prime, 1);
                if (sp) sp->scale = lcm_small(sp->scale, frac_mul(alpha, frac_int(times)).den);
            }
        }
    }
    if (node->kind == N_CALL && (node->op == FN_LN || node->op == FN_LOG) && node_uses_letter(node->a, sign_name) && log_base(node, &base, &euler, &factor))
        space_log(base, euler, node->a, 1);
}

/* Dopo space_collect(): per ogni radice di node il cui radicando è un
 * prodotto di potenze di lettere di esponenziali, allarga L quanto basta
 * perché ogni esponente sia un multiplo dell'indice, così che la radice si
 * possa estrarre (exp_root()): con \sqrt{2^{x}} la lettera diventa
 * 2^(x/2). Lo si fa solo per queste radici, e dalle più interne: allargare
 * L per una radice come \sqrt{e^{x} - 6} renderebbe irrazionale, senza
 * motivo, il gradino e^x = 6. */
static void root_scales(const Node *node) {
    if (!node) return;
    root_scales(node->a);
    root_scales(node->b);
    root_scales(node->c);
    if (node->kind != N_CALL || node->op != FN_ROOT || !node->b || node->b->kind != N_NUM || node->b->value < 2 || node->b->value > 40) return;
    Rat r = eval(node->a);
    int plain = !failure && r.num.count == 1 && r.den.count == 1;
    failure = NULL;
    for (int side = 0; side < 2 && plain; side++) {
        const Term *term = side ? &r.den.term[0] : &r.num.term[0];
        for (int f = 0; f < term->mono.count; f++) {
            Frac e = term->mono.factor[f].exp;
            int s = space_of(term->mono.factor[f].atom);
            if (s == spaces || space[s].kind != SPACE_EXP || e.den != 1) return;
        }
    }
    for (int side = 0; side < 2 && plain; side++) {
        const Term *term = side ? &r.den.term[0] : &r.num.term[0];
        for (int f = 0; f < term->mono.count; f++) {
            long long e = term->mono.factor[f].exp.num, index = node->b->value;
            space[space_of(term->mono.factor[f].atom)].scale *= index / (long long)gcd128(e < 0 ? -e : e, index);
        }
    }
}

/* Chiama visit sui due membri di ogni confronto della condizione f. */
static void formula_sides(const Formula *f, void (*visit)(const Node *)) {
    if (!f) return;
    if (f->kind == F_EQUAL || f->kind == F_DISTINCT || f->kind == F_LESS || f->kind == F_LESS_EQ) {
        visit(f->left);
        visit(f->right);
        return;
    }
    formula_sides(f->a, visit);
    formula_sides(f->b, visit);
}

/* Registra gli spazi di tutti i confronti della condizione f; poi allarga
 * quelli che servono alle radici di prodotti di esponenziali. */
static void formula_spaces(const Formula *f) {
    formula_sides(f, space_collect);
    formula_sides(f, root_scales);
}

/* 18p-8. Se node, una potenza, ha la variabile all'esponente, una base
 * numerica positiva e l'esponente di primo grado a x + c con c intero, mette
 * in *out il suo valore nelle lettere degli spazi e ritorna 1:
 *
 *     b^(a x + c) = b^c * prodotto sui primi p di b di (p^(x/L))^(e_p a L),
 *
 * dove e_p è l'esponente di p nella scomposizione di b. Le divisioni di
 * questo conto non pongono condizioni: una potenza di un numero positivo non
 * è mai zero. */
static int exp_letters(const Node *node, Rat *out) {
    Frac base, alpha, beta;
    int euler, done = 1, listed = conditions_on;
    long long prime, times;
    if (!space_live || !node_uses_letter(node->b, sign_name) || !constant_base(node->a, &base, &euler)) return 0;
    if (!rat_affine_in(eval(node->b), sign_x, &alpha, &beta) || beta.den != 1 || (euler && beta.num != 0)) return 0;
    conditions_on = 0;
    if (euler) {
        /* La base e: una lettera sola, e nessun numero davanti. */
        Space *sp = space_exp(0, 0);
        Frac power = sp ? frac_mul(alpha, frac_int(sp->scale)) : frac_int(0);
        done = sp && power.den == 1;
        if (done) *out = rat_pow_int(rat_atom(sp->letter), power.num);
    } else {
        *out = rat_pow_int(rat_frac(base), beta.num);
    }
    for (int side = 0; side < 2 && done && !euler; side++) {
        long long value = side ? base.den : base.num;
        while (done && pop_prime(&value, &prime, &times)) {
            Space *sp = space_exp(prime, 0);
            Frac power = sp ? frac_mul(frac_mul(alpha, frac_int(side ? -times : times)), frac_int(sp->scale)) : frac_int(0);
            if (!sp || power.den != 1) done = 0;
            else *out = rat_mul(*out, rat_pow_int(rat_atom(sp->letter), power.num));
        }
    }
    conditions_on = listed;
    return done && !failure;
}

/* 18p-8. Vedi la dichiarazione prima di eval_call(). r deve essere un
 * razionale positivo per un prodotto di potenze, anche negative, di lettere
 * di esponenziali; la radice si estrae se il razionale è una potenza
 * index-esima esatta e ogni esponente è un multiplo di index. Le lettere
 * sono positive: la radice n-esima di c g^(n a) è la radice di c per g^a,
 * senza valori assoluti e senza condizioni. È così che \sqrt[3]{11^{9x}}
 * diventa 11^{3x}. Un numero senza lettere resta alla regola di sempre. */
static int exp_root(Rat r, long long index, Rat *out) {
    int letters = 0;
    if (!space_live || spaces == 0 || failure || index > 40 || r.num.count != 1 || r.den.count != 1) return 0;
    const Term *top = &r.num.term[0], *bottom = &r.den.term[0];
    if (top->coef.im.num != 0 || bottom->coef.im.num != 0) return 0;
    Frac coefficient = frac_div(top->coef.re, bottom->coef.re);
    long long up = coefficient.num > 0 ? exact_root(coefficient.num, (int)index) : 0, down = exact_root(coefficient.den, (int)index);
    if (failure || !up || !down) return 0;
    *out = rat_frac((Frac){up, down});
    for (int side = 0; side < 2; side++) {
        const Term *term = side ? bottom : top;
        for (int f = 0; f < term->mono.count; f++) {
            Frac e = term->mono.factor[f].exp;
            int s = space_of(term->mono.factor[f].atom);
            if (s == spaces || space[s].kind != SPACE_EXP || e.den != 1 || e.num % index != 0) return 0;
            *out = rat_mul(*out, rat_pow_int(rat_atom(space[s].letter), (side ? -e.num : e.num) / index));
            letters++;
        }
    }
    return letters > 0 && !failure;
}

/* 18p-8. Il logaritmo di una potenza accanto al logaritmo della base.
 *
 * log_b(B^n) = n log_b(B) vale dove B è positivo. Dove B è negativo e n è
 * pari il primo membro ha un valore e il secondo no: per questo \log x^{2}
 * e \log x sono due lettere diverse. Ma un confronto in cui compare anche
 * log_b(B) ha un valore solo dove B è positivo, e lì i due logaritmi sono
 * legati: dentro quel confronto log_b(B^n) si scrive n volte la lettera di
 * log_b(B). È ciò che serve a (\log x^{2})^{2} + 4\log x = 0, che così è un
 * polinomio in una lettera sola. Senza log_b(B) nello stesso confronto la
 * regola non si applica.
 *
 * alias_node[i] è un logaritmo di una potenza del confronto che si sta
 * preparando, alias_space[i] lo spazio del logaritmo della base e
 * alias_power[i] l'esponente n. Li riempie alias_collect(), li usa
 * log_letter(), e sign_prepare() li azzera alla fine del confronto. */
#define MAX_LOG_ALIAS 8
static const Node *alias_node[MAX_LOG_ALIAS];
static int alias_space[MAX_LOG_ALIAS], aliases;
static long long alias_power[MAX_LOG_ALIAS];

/* Ritorna 1 se in node compare un logaritmo con la base ridotta base (o in
 * base e, se natural) e l'argomento scritto come argument. */
static int log_present(const Node *node, Frac base, int natural, const Node *argument) {
    Frac found, factor;
    int euler;
    if (!node) return 0;
    if (node->kind == N_CALL && (node->op == FN_LN || node->op == FN_LOG) && node_equal(node->a, argument) && log_base(node, &found, &euler, &factor) &&
        euler == natural && (natural || frac_cmp(found, base) == 0)) return 1;
    return log_present(node->a, base, natural, argument) || log_present(node->b, base, natural, argument) || log_present(node->c, base, natural, argument);
}

/* Registra in alias_node[] i logaritmi di potenze di node, un pezzo del
 * confronto f, che in f stanno accanto al logaritmo della loro base. */
static void alias_collect(const Node *node, const Formula *f) {
    Frac base, factor;
    int euler;
    if (!node) return;
    alias_collect(node->a, f);
    alias_collect(node->b, f);
    alias_collect(node->c, f);
    if (node->kind != N_CALL || (node->op != FN_LN && node->op != FN_LOG) || node->a->kind != N_POW || node->a->b->kind != N_NUM || node->a->b->value < 2) return;
    if (aliases == MAX_LOG_ALIAS || !node_uses_letter(node->a->a, sign_name) || !log_base(node, &base, &euler, &factor)) return;
    int s = space_log(base, euler, node->a->a, 0);
    if (s < 0 || (!log_present(f->left, base, euler, node->a->a) && !log_present(f->right, base, euler, node->a->a))) return;
    alias_node[aliases] = node;
    alias_space[aliases] = s;
    alias_power[aliases++] = node->a->b->value;
}

/* 18p-8. Se node, un logaritmo, ha la variabile nell'argomento e uno spazio
 * registrato, mette in *out la lettera dello spazio, moltiplicata per il
 * fattore che porta dalla base ridotta a quella scritta (log_base()), e
 * ritorna 1. Annota in space_seen che il confronto in corso contiene quel
 * logaritmo: l'argomento dovrà essere positivo. */
static int log_letter(const Node *node, Rat *out) {
    Frac base, factor;
    int euler;
    if (!space_live || !node_uses_letter(node->a, sign_name) || !log_base(node, &base, &euler, &factor)) return 0;
    int s = space_log(base, euler, node->a, 0);
    for (int i = 0; i < aliases; i++) {
        if (alias_node[i] != node) continue;
        s = alias_space[i];
        factor = frac_mul(factor, frac_int(alias_power[i]));
    }
    if (s < 0) return 0;
    space_seen |= 1u << s;
    *out = rat_mul(rat_frac(factor), rat_atom(space[s].letter));
    return 1;
}

/* 18p-11. FUNZIONI GONIOMETRICHE
 *
 * 2 \sin x \cos x > \frac{1}{2} non è un confronto tra frazioni in x. Lo
 * diventa con la sostituzione della tangente dell'angolo metà:
 *
 *     t = tan(u / 2),     sin u = 2t / (1 + t^2),     cos u = (1 - t^2) / (1 + t^2).
 *
 * Le due formule sono identità (si verificano scrivendo seno e coseno di
 * u = 2 (u/2) con le formule di duplicazione e dividendo per
 * cos^2(u/2) + sin^2(u/2) = 1). Quando u percorre un giro, da -pi a pi
 * esclusi, t percorre tutta la retta reale una volta sola, crescendo: la
 * tabella dei segni nella lettera t descrive quindi tutto un periodo. Resta
 * fuori un punto solo, u = pi, dove t non ha un valore: lì seno e coseno
 * valgono 0 e -1, e l'enunciato si calcola a parte.
 *
 * Gli argomenti. Ogni funzione goniometrica dell'enunciato deve avere
 * l'argomento a x + b pi, con a e b razionali. Si prende u = g x, dove g è
 * il più grande razionale di cui tutti gli a sono multipli interi: allora
 * a x + b pi = n u + b pi con n intero, e
 *
 *   - cos(n u) + i sin(n u) = (cos u + i sin u)^n (formula di De Moivre):
 *     n moltiplicazioni tra numeri complessi danno cos(n u) e sin(n u) come
 *     frazioni in t;
 *   - cos(b pi) e sin(b pi) sono numeri noti quando b pi è un multiplo di
 *     15 gradi: si scrivono con le radici di 2 e di 3 (trig_constant());
 *   - le formule di addizione mettono insieme le due cose.
 *
 * Tangente e cotangente sono i due quozienti, e dove il denominatore è zero
 * non hanno un valore: lo dice la divisione, come sempre.
 *
 * Che cosa resta fuori: la variabile anche fuori dalle funzioni
 * goniometriche (x + sin x), salvo che in un confronto con un multiplo di pi
 * che restringe la condizione a un intervallo (18p-14); argomenti non di
 * primo grado; angoli costanti che non sono multipli di 15 gradi; angoli
 * multipli così alti che i polinomi in t escono dall'aritmetica esatta
 * della tabella (cos x + cos 3x = 2 sin 6x cos x).
 */

/* Lo stato dell'enunciato periodico in corso. trig_on dice che lo è;
 * trig_live che si sta preparando un suo confronto (solo allora le funzioni
 * diventano frazioni in t); trig_at_pi che le si vuole nel punto u = pi
 * invece che in t; trig_x e trig_letter sono gli atomi della variabile e di
 * t; trig_scale è g; trig_bad dice che una funzione ha un argomento non
 * trattato. trig_root[] sono i nodi di radice di 2 e di radice di 3, che
 * servono a scrivere seni e coseni dei multipli di 15 gradi. */
static int trig_on, trig_live, trig_at_pi, trig_bad;
static int trig_x, trig_letter;
static Frac trig_scale;
static Node *trig_root[2];

/* Le finestre dell'enunciato periodico in corso (18p-14): quante sono, il
 * più basso e il più alto dei giri in cui cade un loro estremo, il primo e
 * l'ultimo giro da leggere, e il giro che si sta leggendo. Senza finestre
 * si legge un giro solo, il numero 0. */
static int windows;
static long long window_low, window_high, window_first, window_last, window_turn;

/* Se e = a x + b pi, con x la variabile dell'enunciato periodico, mette a
 * in *slope e b in *turn e ritorna 1. */
static int trig_affine(Rat e, Frac *slope, Frac *turn) {
    int pi = atom_var(VAR_PI);
    *slope = *turn = frac_int(0);
    if (failure || e.den.count != 1 || e.den.term[0].mono.count != 0 || e.den.term[0].coef.im.num != 0) return 0;
    for (int i = 0; i < e.num.count; i++) {
        const Term *t = &e.num.term[i];
        if (t->coef.im.num != 0 || t->mono.count != 1 || frac_cmp(t->mono.factor[0].exp, frac_int(1)) != 0) return 0;
        if (t->mono.factor[0].atom == trig_x) *slope = t->coef.re;
        else if (t->mono.factor[0].atom == pi) *turn = t->coef.re;
        else return 0;
    }
    *slope = frac_div(*slope, e.den.term[0].coef.re);
    *turn = frac_div(*turn, e.den.term[0].coef.re);
    return !failure;
}

/* 18p-13. LE FAMIGLIE x = a + k T
 *
 * Le soluzioni di una condizione periodica si scrivono con un intero k:
 * x = \frac{\pi}{6} + 2k\pi, oppure \frac{\pi}{6} + 2k\pi < x < \frac{5}{6}\pi + 2k\pi.
 * In un enunciato compaiono dentro un "esiste k intero", e dire che un
 * risultato così è giusto vuol dire confrontarlo con la condizione. Lo si
 * fa riportando anche lui a funzioni goniometriche di x. Si guarda l'angolo
 *
 *     A = 2 pi (x - a) / T,
 *
 * che fa un giro intero ogni volta che x avanza di un periodo T: tutta la
 * famiglia è descritta dal punto di angolo A sulla circonferenza.
 *
 *   - x = a + k T per qualche k esattamente quando A è un multiplo di 2 pi,
 *     cioè quando il punto è (1, 0): sin A = 0 e cos A > 0.
 *
 *   - a + k T <= x <= b + k T per qualche k, con 0 < b - a < T, esattamente
 *     quando il punto sta sull'arco che va dall'angolo 0 all'angolo
 *     D = 2 pi (b - a) / T. Con B = D - A = 2 pi (b - x) / T, l'angolo che
 *     manca alla fine dell'arco:
 *       - se l'arco è al più mezzo giro (D <= pi) i suoi punti interni sono
 *         quelli con sin A > 0 e sin B > 0: stanno nel semipiano a sinistra
 *         del raggio di partenza e in quello a destra del raggio di arrivo;
 *       - se è più di mezzo giro (D > pi) sono quelli con sin A > 0 oppure
 *         sin B > 0: il primo mezzo giro dopo la partenza e l'ultimo prima
 *         dell'arrivo, che insieme coprono l'arco perché si sovrappongono;
 *       - gli estremi sono i punti con A, o B, multiplo di 2 pi, come sopra,
 *         e contano se l'estremo è compreso.
 *
 * Una versione precedente usava l'angolo metà, sin(pi (x - a) / T): bastava
 * un seno per estremo, ma per una famiglia come \frac{\pi}{4} + 2k\pi
 * chiedeva il seno di pi/8, che non si scrive con le radici di 2 e di 3.
 * Con l'angolo intero servono i seni e i coseni di 2 pi a / T, e nei
 * risultati dei libri a è quasi sempre una frazione semplice del periodo.
 *
 * T deve essere un multiplo razionale di pi; a e b possono contenere, oltre
 * a multipli di pi, arcotangenti di razionali con coefficiente intero: dei
 * seni e dei coseni serve solo il segno, e cos(arctan m) e sin(arctan m)
 * stanno come 1 sta a m.
 */

/* Una famiglia: un pezzo di una condizione "esiste k intero". È un punto
 * per ogni k (single), x = low, oppure un intervallo per ogni k, da low a
 * high, con gli estremi compresi o no, a cui possono essere tolti i punti
 * x = hole[i]. low, high e hole[] sono espressioni in k. */
typedef struct {
    const Node *low, *high;               /* gli estremi; lo stesso nodo per un punto */
    int low_closed, high_closed, single;  /* 1 se l'estremo è compreso; 1 per un punto */
    const Node *hole[MAX_LATTICE_HOLES];  /* i punti tolti */
    int holes;                            /* quanti, in hole[] */
    int k;                                /* la lettera dell'intero */
} Family;

/* Legge il pezzo d di una condizione in name e nell'intero k, che deve
 * essere un confronto tra name e un'espressione, o una congiunzione di
 * confronti così: al più un estremo da ogni parte e alcuni punti tolti.
 * Aggiorna *out, che chi chiama ha azzerato, e ritorna 0 se d ha un'altra
 * forma. */
static int family_part(const Formula *d, int name, Family *out) {
    if (d->kind == F_AND) return family_part(d->a, name, out) && family_part(d->b, name, out);
    if (d->kind != F_EQUAL && d->kind != F_DISTINCT && d->kind != F_LESS && d->kind != F_LESS_EQ) return 0;
    int at_left = d->left->kind == N_VAR && d->left->name == name, at_right = d->right->kind == N_VAR && d->right->name == name;
    if (at_left == at_right) return 0;
    const Node *other = at_left ? d->right : d->left;
    if (d->kind == F_DISTINCT) {
        if (out->holes == MAX_LATTICE_HOLES) return 0;
        out->hole[out->holes++] = other;
    } else if (d->kind == F_EQUAL) {
        if (out->low || out->high) return 0;
        out->low = out->high = other;
        out->low_closed = out->high_closed = out->single = 1;
    } else if (at_right) {
        /* other < name: un estremo inferiore. */
        if (out->low) return 0;
        out->low = other;
        out->low_closed = d->kind == F_LESS_EQ;
    } else {
        if (out->high) return 0;
        out->high = other;
        out->high_closed = d->kind == F_LESS_EQ;
    }
    return 1;
}

/* Legge una famiglia dal pezzo d, come family_part(), e controlla che sia
 * completa: un punto, un intervallo con i suoi due estremi, oppure, quando
 * alone non è zero, un solo punto tolto (è il caso di "per ogni k,
 * x \neq ..."), che viene messo in low come se fosse un punto. */
static int family_read(const Formula *d, int name, int k, int alone, Family *out) {
    memset(out, 0, sizeof *out);
    out->k = k;
    if (!family_part(d, name, out)) return 0;
    if (alone) {
        if (out->low || out->high || out->holes != 1) return 0;
        out->low = out->high = out->hole[0];
        out->low_closed = out->high_closed = out->single = 1;
        out->holes = 0;
        return 1;
    }
    return out->low && out->high && (!out->single || out->holes == 0);
}

/* Se e = alpha + k tau pi, con k la lettera dell'intero e tau un razionale
 * diverso da zero, mette tau in *tau e alpha, che non contiene k, in *alpha,
 * e ritorna 1. */
static int family_period(const Node *e, int k, Frac *tau, Rat *alpha) {
    int letter = atom_var(k), pi = atom_var(VAR_PI);
    Rat value = eval(e);
    Poly rest = poly_const(num_int(0));
    *tau = frac_int(0);
    if (failure || value.den.count != 1 || value.den.term[0].mono.count != 0 || value.den.term[0].coef.im.num != 0) return 0;
    for (int i = 0; i < value.num.count; i++) {
        const Term *t = &value.num.term[i];
        Frac power = mono_exponent(&t->mono, letter);
        if (power.num == 0) { rest = poly_add(rest, poly_term(*t), 0); continue; }
        if (t->coef.im.num != 0 || t->mono.count != 2 || frac_cmp(power, frac_int(1)) != 0 || frac_cmp(mono_exponent(&t->mono, pi), frac_int(1)) != 0) return 0;
        *tau = frac_add(*tau, t->coef.re);
    }
    *tau = frac_div(*tau, value.den.term[0].coef.re);
    *alpha = (Rat){rest, value.den};
    return tau->num != 0 && !failure;
}

/* Ritorna 1 se f è un quantificatore su un intero che la tabella tratta
 * come una foglia: "esiste k in Z" o "per ogni k in Z", su tutti gli
 * interi. */
static int family_owner(const Formula *f) {
    return (f->kind == F_EXISTS || f->kind == F_FORALL) && f->numbers.integers && !f->numbers.bounded && f->numbers.holes == 0;
}

/* Chiama visit(d, context) per ogni pezzo della condizione f di un
 * quantificatore su un intero: i termini di una disgiunzione per "esiste",
 * quelli di una congiunzione per "per ogni". */
static void family_each(const Formula *owner, const Formula *f, void (*visit)(const Formula *, const Formula *, void *), void *context) {
    if (f->kind == (owner->kind == F_EXISTS ? F_OR : F_AND)) {
        family_each(owner, f->a, visit, context);
        family_each(owner, f->b, visit, context);
        return;
    }
    visit(owner, f, context);
}

/* Aggiorna trig_scale con la pendenza positiva slope di un angolo
 * dell'enunciato: trig_scale diventa il più grande razionale di cui sono
 * multipli interi tutte le pendenze viste, cioè il loro massimo comun
 * divisore (quello di due frazioni p/q e r/s è mcd(p s, r q) / (q s)). La
 * prima pendenza, con trig_scale ancora zero, è il valore di partenza. */
static void trig_scale_include(Frac slope) {
    if (trig_scale.num == 0) trig_scale = slope;
    else trig_scale = frac_make(gcd128((__int128)trig_scale.num * slope.den, (__int128)slope.num * trig_scale.den), (__int128)trig_scale.den * slope.den);
}

/* Per formula_trig(): aggiorna trig_scale con il periodo del pezzo d, o
 * mette 1 in trig_bad se il pezzo non è una famiglia trattata. Ogni
 * espressione della famiglia deve avere lo stesso tau, e la pendenza
 * 2 pi / T = 2 / tau dell'angolo A entra nel conto come quella di un
 * argomento. */
static void family_scale(const Formula *owner, const Formula *d, void *context) {
    Family family;
    Frac tau, other;
    Rat alpha;
    (void)context;
    if (!family_read(d, sign_name, owner->variable, owner->kind == F_FORALL, &family) || !family_period(family.low, family.k, &tau, &alpha)) { trig_bad = 1; return; }
    if (tau.num < 0) tau.num = -tau.num;
    const Node *more[1 + MAX_LATTICE_HOLES] = {family.high, family.hole[0], family.hole[1]};
    for (int i = 0; i < 1 + family.holes; i++) {
        if (!family_period(more[i], family.k, &other, &alpha)) { trig_bad = 1; return; }
        if (other.num < 0) other.num = -other.num;
        if (frac_cmp(other, tau) != 0) { trig_bad = 1; return; }
    }
    trig_scale_include(frac_div(frac_int(2), tau));
}

/* Registra le funzioni goniometriche dell'espressione node che contengono la
 * variabile: aggiorna trig_scale con le pendenze dei loro argomenti
 * (trig_scale_include()), e mette 1 in trig_bad se un argomento non è
 * a x + b pi. */
static void trig_collect(const Node *node) {
    Frac slope, turn;
    if (!node || failure) return;
    trig_collect(node->a);
    trig_collect(node->b);
    trig_collect(node->c);
    if (node->kind != N_CALL || node->op < FN_SIN || node->op > FN_COT || !node_uses_letter(node->a, sign_name)) return;
    if (!trig_affine(eval(node->a), &slope, &turn) || slope.num == 0) { trig_bad = 1; return; }
    if (slope.num < 0) slope.num = -slope.num;
    trig_scale_include(slope);
}

/* Registra le funzioni goniometriche di tutti i confronti della condizione f. */
static void formula_trig(const Formula *f) {
    if (!f) return;
    if (family_owner(f)) { family_each(f, f->a, family_scale, NULL); return; }
    if (f->kind == F_EQUAL || f->kind == F_DISTINCT || f->kind == F_LESS || f->kind == F_LESS_EQ) {
        trig_collect(f->left);
        trig_collect(f->right);
        return;
    }
    formula_trig(f->a);
    formula_trig(f->b);
}

/* Mette in *cosine e *sine il coseno e il seno di turn * pi, e ritorna 1;
 * 0 se l'angolo non è un multiplo di 15 gradi.
 *
 * L'angolo è k quarti di giro più r volte 15 gradi, con r da 0 a 5. Per il
 * resto valgono
 *
 *     cos 15 = (sqrt6 + sqrt2) / 4     sin 15 = (sqrt6 - sqrt2) / 4
 *     cos 30 = sqrt3 / 2               sin 30 = 1 / 2
 *     cos 45 = sin 45 = sqrt2 / 2,
 *
 * e 60 e 75 gradi sono i complementari di 30 e 15 (seno e coseno si
 * scambiano). Ogni quarto di giro in più manda (cos, sin) in (-sin, cos). */
static int trig_constant(Frac turn, Rat *cosine, Rat *sine) {
    Frac twelfths = frac_mul(turn, frac_int(12));
    if (twelfths.den != 1) return 0;
    long long steps = ((twelfths.num % 24) + 24) % 24, rest = steps % 6;
    Rat two = eval(trig_root[0]), three = eval(trig_root[1]), half = rat_frac((Frac){1, 2}), quarter = rat_frac((Frac){1, 4});
    Rat small = rat_mul(quarter, rat_add(rat_mul(two, three), two, 1)), large = rat_mul(quarter, rat_add(rat_mul(two, three), two, 0));
    Rat c[6] = {rat_int(1), large, rat_mul(half, three), rat_mul(half, two), half, small};
    Rat s[6] = {rat_int(0), small, half, rat_mul(half, two), rat_mul(half, three), large};
    *cosine = c[rest];
    *sine = s[rest];
    for (long long quarter_turns = steps / 6; quarter_turns > 0; quarter_turns--) {
        Rat was = *cosine;
        *cosine = rat_add(rat_int(0), *sine, 1);
        *sine = was;
    }
    return !failure;
}

/* Mette in *cosine e *sine il coseno e il seno di n u, con u l'angolo
 * dell'enunciato: nel punto u = pi, se trig_at_pi, altrimenti come frazioni
 * nella lettera t. Formula di De Moivre: n moltiplicazioni di
 * cos u + i sin u per se stesso; n negativo cambia segno al seno. */
static void trig_multiple(long long n, Rat *cosine, Rat *sine) {
    Rat t = rat_atom(trig_letter), square = rat_mul(t, t), one = rat_int(1);
    Rat c = trig_at_pi ? rat_int(-1) : rat_div(rat_add(one, square, 1), rat_add(one, square, 0));
    Rat s = trig_at_pi ? rat_int(0) : rat_div(rat_add(t, t, 0), rat_add(one, square, 0));
    *cosine = one;
    *sine = rat_int(0);
    for (long long i = 0; i < (n < 0 ? -n : n) && !failure; i++) {
        Rat real = rat_add(rat_mul(*cosine, c), rat_mul(*sine, s), 1);
        *sine = rat_add(rat_mul(*cosine, s), rat_mul(*sine, c), 0);
        *cosine = real;
    }
    if (n < 0) *sine = rat_add(rat_int(0), *sine, 1);
}

/* 18p-11. Vedi la dichiarazione prima di eval_call(). L'argomento del nodo
 * deve valere n u + b pi con n intero, dove u = g x è l'angolo
 * dell'enunciato. */
static int trig_value(const Node *node, Rat argument, Rat *out) {
    Frac slope, turn;
    if (!trig_live || !trig_affine(argument, &slope, &turn)) return 0;
    Frac multiple = frac_div(slope, trig_scale);
    if (multiple.den != 1) return 0;

    Rat cn, sn, cb, sb;
    trig_multiple(multiple.num, &cn, &sn);
    if (!trig_constant(turn, &cb, &sb)) return 0;

    /* Formule di addizione. */
    Rat sine = rat_add(rat_mul(sn, cb), rat_mul(cn, sb), 0), cosine = rat_add(rat_mul(cn, cb), rat_mul(sn, sb), 1);
    *out = node->op == FN_SIN ? sine : node->op == FN_COS ? cosine : node->op == FN_TAN ? rat_div(sine, cosine) : rat_div(cosine, sine);
    return !failure;
}

/* =============================================================================
 * 18.10 L'ALBERO DEI SEGNI
 * ============================================================================
 *
 * Il segno di un confronto in un punto, calcolato dai segni dei polinomi
 * della tabella. La differenza dei due membri diventa un albero (SignNode):
 * foglie che sono frazioni di polinomi in una lettera, la variabile o quella
 * di uno spazio, e nodi per il prodotto, il quoziente e a + b sqrt(r). Lo
 * costruiscono sign_build() per le radici quadrate (18p-7), sign_ground()
 * per le lettere degli spazi (18p-8), sign_number_linear() per i confronti
 * con un numero come ln 6 (18p-10), powers_difference() per due monomi di
 * potenze (18p-9); sign_fraction() fa il conto e annota le condizioni di
 * esistenza, e sign_value() legge il segno in una riga.
 *
 * 18p-7. LE RADICI QUADRATE
 *
 * Un confronto può contenere radici quadrate, di numeri e di espressioni
 * nella variabile: x < 1 - \sqrt{2}, \sqrt{x + 3} = \sqrt{x + 12} - \sqrt{3 - x}.
 * La differenza dei due membri non è più una frazione di polinomi, ma il suo
 * segno si ricava ancora, in modo esatto, dai segni di polinomi.
 *
 * Ogni radice diventa una lettera s, con s^2 = R (il radicando) e s >= 0.
 * Un'espressione nelle lettere si scrive, raccogliendo le potenze pari di s,
 * come P + Q s, dove P e Q non contengono s. Dove R >= 0:
 *
 *   - se Q = 0, oppure R = 0, il segno è quello di P;
 *   - se P = 0, oppure P e Q hanno lo stesso segno, il segno è quello di Q;
 *   - se P e Q hanno segni opposti vince il più grande in valore assoluto
 *     tra P e Q s, cioè, confrontando i quadrati, il segno è quello di P
 *     moltiplicato per il segno di P^2 - Q^2 R.
 *
 * P, Q, R e P^2 - Q^2 R contengono una radice in meno: ripetendo si arriva a
 * frazioni di polinomi, le foglie, i cui segni sono le colonne della
 * tabella. Tra le colonne entrano così anche i polinomi P^2 - Q^2 R, ed è
 * giusto: le soluzioni di un'equazione con radici sono tra le radici del
 * polinomio che si ottiene elevando al quadrato, e la tabella, guardando i
 * segni di P e di Q, scarta da sola quelle che non lo sono.
 *
 * Un'espressione con radici ha un valore solo dove ogni radicando è
 * definito e non negativo: è una condizione di esistenza come un divisore
 * diverso da zero, e va posta per ogni radice anche se nei conti la lettera
 * è sparita, come in (\sqrt{x})^2.
 */

/* Il messaggio per un confronto che la tabella dei segni non tratta. */
static const char *const SIGN_SHAPE =
    "la tabella dei segni tratta solo espressioni razionali e radici quadrate nella variabile: niente logaritmi, funzioni goniometriche o altre lettere";

/* I tipi di nodo di un albero dei segni. */
typedef enum {
    SIGN_LEAF,   /* una frazione di polinomi in una lettera sola */
    SIGN_RATIO,  /* a / b */
    SIGN_TIMES,  /* a * b */
    SIGN_SURD    /* a + b sqrt(r) */
} SignKind;

/* Un nodo di un albero dei segni: un'espressione di cui si sa calcolare il
 * segno a partire dai segni dei polinomi di sign_poly[]. I nodi stanno in
 * sign_node[] e valgono per l'enunciato in corso. */
typedef struct SignNode SignNode;
struct SignNode {
    SignKind kind;
    int top, bottom, power, letter;  /* SIGN_LEAF: vale top / (bottom x^power),
                                        con top, bottom e letter posti in
                                        sign_poly[]; letter è il posto del
                                        polinomio x, o -1 se x non compare da
                                        sola a denominatore: così lo zero
                                        entra tra i punti solo quando serve */
    int space;                       /* SIGN_LEAF: -1 se la lettera x è la
                                        variabile dell'enunciato, altrimenti
                                        lo spazio di cui è la lettera (18p-8) */
    const SignNode *a, *b;           /* SIGN_RATIO, SIGN_TIMES e SIGN_SURD: gli operandi */
    const SignNode *r, *n;           /* SIGN_SURD: il radicando, e a^2 - b^2 r */
};

static SignNode sign_node[MAX_SIGN_NODES];
static int sign_nodes;

/* Una condizione di esistenza di un confronto: il nodo deve essere definito
 * e non negativo (strict = 0, un radicando), diverso da zero (strict = 1,
 * un divisore) oppure positivo (strict = 2, l'argomento di un logaritmo). */
typedef struct {
    const SignNode *node;
    int strict;
} SignNeed;

/* Le condizioni di esistenza dei confronti dell'enunciato in corso, a pezzi
 * consecutivi: ogni SignCase indica il suo. */
static SignNeed sign_need[MAX_SIGN_NEEDS];
static int sign_needs;

/* Un'espressione preparata per la tabella (18p-1): il suo albero dei segni e
 * le sue condizioni di esistenza, che sono `needs` voci di sign_need[] a
 * partire da first. */
typedef struct {
    const SignNode *value;
    int first, needs;
} SignCase;

/* Un confronto dell'enunciato, preparato per la tabella.
 *
 * Senza valori assoluti è un'espressione sola, la differenza dei due membri:
 * by_pattern[0]. Con k valori assoluti ce n'è una per ogni scelta dei segni
 * dei loro argomenti: nella scelta di numero p il valore assoluto i vale
 * l'argomento cambiato di segno se il bit i di p è 1. Quale scelta sia
 * quella vera in un punto lo dicono i segni degli argomenti:
 * inner[i][p] è l'argomento del valore assoluto i nella scelta p (conta solo
 * per i valori assoluti che stanno dentro il suo argomento, che hanno un
 * numero più basso). */
typedef struct {
    const Formula *source;  /* il confronto com'è nell'enunciato */
    int inner_count;        /* quanti valori assoluti, cioè le righe usate di inner[] */
    int identity;  /* 0 non ancora chiesto; 1 se i due membri sono la stessa
                      funzione, -1 se non risulta (formula_identity()) */
    int window;    /* 1 se il confronto è una finestra di un enunciato periodico
                      (18p-14): allora by_pattern[0] è il segno di u - gamma nel
                      giro numero home, e direction, 1 o -1, il segno per cui
                      moltiplicarlo per avere quello di left - right */
    int direction;
    long long home;
    SignCase inner[MAX_ABS][1 << MAX_ABS];
    SignCase by_pattern[1 << MAX_ABS];
} SignAtom;

/* I confronti dell'enunciato in corso, nell'ordine in cui sign_prepare() li
 * incontra; sign_compare() li ritrova dal nodo source. */
static SignAtom sign_atom[MAX_SIGN_ATOMS];
static int sign_atoms;

/* Mette in abs_node[] i valori assoluti dell'espressione node, quelli più
 * interni per primi, una volta ciascuno: due valori assoluti scritti allo
 * stesso modo, come il |u| di una funzione che ricompare nella sua derivata
 * (27f), hanno sempre lo stesso segno dell'argomento, e sono un valore
 * assoluto solo, con una sola scelta del segno (eval_call() li riconosce
 * allo stesso modo). */
static void abs_collect(const Node *node) {
    if (!node || failure) return;
    abs_collect(node->a);
    abs_collect(node->b);
    abs_collect(node->c);
    if (node->kind != N_CALL || node->op != FN_ABS) return;
    for (int i = 0; i < abs_count; i++)
        if (abs_node[i] == node || node_equal(abs_node[i], node)) return;
    if (abs_count == MAX_ABS) { fail("troppi valori assoluti in un confronto"); return; }
    abs_node[abs_count++] = node;
}

/* Mette in surd_node[] le radici quadrate dell'espressione node, quelle più
 * interne per prime e una sola per radicando, e crea le loro lettere. */
static void surd_collect(const Node *node) {
    if (!node || failure) return;
    surd_collect(node->a);
    surd_collect(node->b);
    surd_collect(node->c);
    if (node->kind != N_CALL || node->op != FN_ROOT || node->b->kind != N_NUM || node->b->value != 2) return;
    for (int i = 0; i < surd_count; i++)
        if (node_equal(surd_node[i]->a, node->a)) return;
    if (surd_count == MAX_SURDS) { fail("troppe radici quadrate diverse in un confronto"); return; }
    surd_letter[surd_count] = atom_var(SURD_NAMES + surd_count);
    surd_node[surd_count++] = node;
}

/* Ritorna un nodo nuovo del tipo kind; se non c'è più posto annota un
 * errore e ritorna il primo, che non verrà usato. */
static SignNode *sign_node_new(SignKind kind) {
    if (sign_nodes == MAX_SIGN_NODES) { fail("espressione troppo complessa per la tabella dei segni"); return &sign_node[0]; }
    SignNode *node = &sign_node[sign_nodes++];
    memset(node, 0, sizeof *node);
    node->kind = kind;
    node->space = -1;
    return node;
}

/* Scrive il polinomio p come A + B s, dove s è la lettera della radice
 * numero i: mette A in *plain e B in *with, frazioni senza s. Una potenza
 * s^e con e = 2 j + r, r = 0 o 1, vale R^j s^r; con j negativo è una
 * divisione per R, lecita perché dove si divide per s il confronto chiede
 * già che s non sia zero. */
static void surd_split(Poly p, int i, Rat *plain, Rat *with) {
    *plain = *with = rat_int(0);
    for (int t = 0; t < p.count && !failure; t++) {
        Term term = p.term[t];
        Frac e = mono_exponent(&term.mono, surd_letter[i]);
        if (e.den != 1) { fail(SIGN_SHAPE); return; }
        long long half = frac_floor(frac_make(e.num, 2));
        term.mono = mono_with_exponent(&term.mono, surd_letter[i], frac_int(0));
        Rat piece = rat_mul((Rat){poly_term(term), poly_const(num_int(1))}, rat_pow_int(surd_inside[i], half));
        if (e.num - 2 * half) *with = rat_add(*with, piece, 0);
        else *plain = rat_add(*plain, piece, 0);
    }
}

/* Cerca tra le radici quelle che si ricavano dalle altre, e mette in
 * surd_value[] il loro valore: se il radicando R_j è q^2 R_a R_b, con q
 * razionale, allora sqrt(R_j) = q sqrt(R_a) sqrt(R_b). Vale anche con una
 * sola radice (R_j = q^2 R_a) e con nessuna (R_j = q^2, un quadrato).
 *
 * L'uguaglianza chiede che R_a e R_b non siano negativi, ma il confronto lo
 * chiede già, perché quelle radici vi compaiono: dove ha un valore,
 * l'uguaglianza vale. Serve a tenere bassa la torre: tre radici di cui una è
 * il prodotto delle altre due, come sqrt(4x + 5), sqrt(x - 1) e
 * sqrt(4x^2 + x - 5), sono due lettere e non tre, e i polinomi che ne
 * nascono hanno gradi e coefficienti molto più piccoli. */
static void surd_relate(void) {
    int derived[MAX_SURDS] = {0};
    for (int j = 0; j < surd_count && !failure; j++)
        for (int a = -1; a < surd_count && !derived[j]; a++)
            for (int b = a < 0 ? -1 : a + 1; b <= surd_count && !derived[j] && !failure; b++) {
                /* a e b scorrono sulle altre radici non ricavate; -1 per a,
                 * e surd_count per b, vogliono dire "nessuna". */
                int second = b < surd_count ? b : -1;
                if (a == j || second == j || (a >= 0 && derived[a]) || (second >= 0 && derived[second])) continue;
                if (a < 0 && second >= 0) continue;
                Rat product = rat_int(1);
                if (a >= 0) product = rat_mul(product, surd_inside[a]);
                if (second >= 0) product = rat_mul(product, surd_inside[second]);
                if (product.num.count == 0) continue;

                /* R_j deve essere c R_a R_b con c il quadrato di un razionale
                 * positivo. Si confrontano i prodotti in croce, che sono
                 * polinomi: se sono proporzionali il rapporto c è quello dei
                 * loro primi coefficienti, perché i termini sono in ordine. */
                Poly left = poly_mul(surd_inside[j].num, product.den), right = poly_mul(surd_inside[j].den, product.num);
                if (left.count == 0 || left.count != right.count || left.term[0].coef.im.num != 0 || right.term[0].coef.im.num != 0) continue;
                Frac ratio = frac_div(left.term[0].coef.re, right.term[0].coef.re);
                if (failure || ratio.num <= 0 || !poly_equal(left, poly_mul(right, poly_const(num_frac(ratio))))) continue;
                long long top = (long long)wide_isqrt(ratio.num), bottom = (long long)wide_isqrt(ratio.den);
                if (top * top != ratio.num || bottom * bottom != ratio.den) continue;
                surd_value[j] = rat_frac((Frac){top, bottom});
                if (a >= 0) surd_value[j] = rat_mul(surd_value[j], rat_atom(surd_letter[a]));
                if (second >= 0) surd_value[j] = rat_mul(surd_value[j], rat_atom(surd_letter[second]));
                derived[j] = 1;
            }
}

/* Prototipo in avanti inevitabile: sign_build() costruisce i suoi alberi con
 * sign_ground() e sign_surd(), che per i pezzi chiedono a loro volta un
 * albero a sign_build(), anche attraverso sign_constant(). */
static const SignNode *sign_build(Rat e, int level, int x);

/* Ritorna quale lettera di spazio compare nel polinomio p: -1 se nessuna,
 * il numero dello spazio se una sola, -2 se più d'una. */
static int poly_space(Poly p) {
    int found = -1;
    for (int t = 0; t < p.count; t++)
        for (int f = 0; f < p.term[t].mono.count; f++)
            for (int s = 0; s < spaces; s++) {
                if (p.term[t].mono.factor[f].atom != space[s].letter) continue;
                if (found >= 0 && found != s) return -2;
                found = s;
            }
    return found;
}

/* Ritorna 1 se l'atomo è un numero: il logaritmo di un primo, una potenza
 * di un primo con esponente razionale, il numero pi, o il numero e (la
 * lettera e, quando non è la variabile dell'enunciato). */
static int atom_is_number(int atom) {
    const Atom *a = &atoms[atom];
    if (a->kind == ATOM_VAR) return a->id == VAR_PI || (a->id == 'e' && sign_name != 'e');
    return (a->kind == ATOM_LN || a->kind == ATOM_POW) && a->base == BASE_PRIME && a->exponent.count == 0;
}

/* Ritorna 1 se p è un numero: tutti i suoi atomi lo sono. */
static int poly_is_number(Poly p) {
    for (int t = 0; t < p.count; t++)
        for (int f = 0; f < p.term[t].mono.count; f++)
            if (!atom_is_number(p.term[t].mono.factor[f].atom)) return 0;
    return 1;
}

/* Mette in *side il segno del numero p (vedi poly_is_number()) e ritorna 1;
 * annota un errore e ritorna 0 se non riesce a stabilirlo. Prima il conto
 * esatto, che riconosce lo zero; poi gli intervalli. */
static int number_side(Poly p, int *side) {
    Rat number = {p, poly_const(num_int(1))};
    if (number_sign(number, side) || range_side(poly_range(p), side)) { failure = NULL; return 1; }
    failure = NULL;
    fail("non riesco a stabilire il segno di una costante dell'enunciato");
    return 0;
}

/* Aggiunge a text, di size byte, i fattori del termine term il cui
 * esponente ha il segno di side (1: positivi, -1: negativi), scritti con
 * l'esponente in valore assoluto; ritorna quanti ne ha scritti. */
static int term_number_latex(const Term *term, int side, char *text, size_t size) {
    int written = 0;
    for (int f = 0; f < term->mono.count; f++) {
        const Atom *atom = &atoms[term->mono.factor[f].atom];
        Frac e = term->mono.factor[f].exp;
        char power[48] = "";
        if ((e.num > 0) != (side > 0)) continue;
        if (e.num < 0) e.num = -e.num;
        if (e.den != 1) snprintf(power, sizeof power, "^{\\frac{%lld}{%lld}}", e.num, e.den);
        else if (e.num != 1) snprintf(power, sizeof power, "^{%lld}", e.num);
        if (atom->kind == ATOM_VAR) text_add(text, size, "%s%s", atom->id == VAR_PI ? "\\pi" : "e", power);
        else if (atom->kind == ATOM_LN) text_add(text, size, "%s\\ln%s %lld", written ? " " : "", power, atom->id);
        else if (e.num == 1 && e.den == 2) text_add(text, size, "\\sqrt{%lld}", atom->id);
        else text_add(text, size, " %lld%s", atom->id, power);
        written++;
    }
    return written;
}

/* Aggiunge a text, di size byte, il numero p in LaTeX (vedi
 * poly_is_number()): una somma di termini, ognuno un razionale per un
 * prodotto di \ln p, di potenze di primi e di potenze di e, con i fattori
 * di esponente negativo a denominatore. Ciò che scrive si rilegge, con il
 * parser, come lo stesso numero. */
static void poly_number_latex(Poly p, char *text, size_t size) {
    if (p.count == 0) text_add(text, size, "0");
    for (int t = 0; t < p.count; t++) {
        const Term *term = &p.term[t];
        Frac c = term->coef.re;
        long long top = c.num < 0 ? -c.num : c.num;
        int above = 0, below = c.den != 1;
        for (int f = 0; f < term->mono.count; f++)
            if (term->mono.factor[f].exp.num > 0) above = 1; else below = 1;
        text_add(text, size, "%s", t == 0 ? (c.num < 0 ? "-" : "") : (c.num < 0 ? " - " : " + "));
        if (below) text_add(text, size, "\\frac{");
        if (top != 1 || !above) text_add(text, size, "%lld", top);
        term_number_latex(term, 1, text, size);
        if (!below) continue;
        text_add(text, size, "}{");
        if (c.den != 1) text_add(text, size, "%lld", c.den);
        term_number_latex(term, -1, text, size);
        text_add(text, size, "}");
    }
}

/* Aggiunge a text, di size byte, il numero r in LaTeX: il numeratore, o una
 * frazione se il denominatore non è 1. */
static void number_latex(Rat r, char *text, size_t size) {
    if (poly_is_one(r.den)) { poly_number_latex(r.num, text, size); return; }
    text_add(text, size, "\\frac{");
    poly_number_latex(r.num, text, size);
    text_add(text, size, "}{");
    poly_number_latex(r.den, text, size);
    text_add(text, size, "}");
}

/* Ritorna l'albero dei segni della costante di segno side (-1, 0 o 1). */
static const SignNode *sign_constant(int side, int x) { return sign_build(rat_int(side), 0, x); }

/* Ritorna l'albero dei segni del prodotto di a e b. */
static const SignNode *sign_times(const SignNode *a, const SignNode *b) {
    SignNode *node = sign_node_new(SIGN_TIMES);
    node->a = a;
    node->b = b;
    return node;
}

/* 18p-10. Se p = A x + B, con A e B numeri (vedi poly_is_number()) e non
 * tutti e due razionali, mette in *out l'albero dei segni di p e ritorna 1.
 *
 * È il caso di un confronto della variabile con una costante che contiene
 * logaritmi o il numero e: x < \ln 6, x \neq \frac{\ln 3}{\ln 5}. Se A è zero
 * p è una costante, e ha il suo segno. Altrimenti p si annulla in
 * k = -B / A e ha il segno di A per quello di x - k. Se k risulta razionale
 * (ln 8 / ln 2 = 3, che il conto esatto semplifica) è un punto qualsiasi
 * della tabella; se no è un numero che non è radice di un polinomio, e
 * prende un posto suo (Kappa). */
static int sign_number_linear(Poly p, int x, const SignNode **out) {
    Poly part[2], one = poly_const(num_int(1));
    Num plain;
    int side = 0, degree = poly_split(p, x, part, 1);
    if (degree < 0 || !poly_is_number(part[0]) || (degree == 1 && !poly_is_number(part[1]))) return 0;
    if (degree == 0) {
        if (number_side(part[0], &side)) *out = sign_constant(side, x);
        return 1;
    }
    if (!number_side(part[1], &side)) return 1;
    Rat root = rat_div(rat_add(rat_int(0), (Rat){part[0], one}, 1), (Rat){part[1], one});
    if (failure) return 1;

    /* Il conto esatto semplifica i monomi, non i polinomi: (2 ln 2 - ln 3) /
     * (2 ln 3 - 4 ln 2) resta scritto così, ed è -1/2. Lo si riconosce
     * perché numeratore e denominatore sono proporzionali. E si scrive la
     * frazione con il primo coefficiente del denominatore positivo. */
    if (root.num.count == 0)
        root = rat_int(0);
    else if (poly_proportional(root.num, root.den) && root.num.term[0].coef.im.num == 0 && root.den.term[0].coef.im.num == 0)
        root = rat_frac(frac_div(root.num.term[0].coef.re, root.den.term[0].coef.re));
    else if (root.den.count > 0 && root.den.term[0].coef.re.num < 0)
        root = (Rat){poly_add(poly_const(num_int(0)), root.num, 1), poly_add(poly_const(num_int(0)), root.den, 1)};
    if (rat_number(root, &plain) && plain.im.num == 0) {
        *out = sign_times(sign_constant(side, x), sign_build(rat_add(rat_atom(x), rat_frac(plain.re), 1), 0, x));
        return 1;
    }
    char text[96] = "";
    number_latex(root, text, sizeof text);
    SignNode *leaf = sign_node_new(SIGN_LEAF);
    leaf->top = sign_column_kappa(range_div(range_neg(poly_range(part[0])), poly_range(part[1])), text, &root);
    leaf->bottom = sign_column((Uni){0, {1}});
    leaf->letter = -1;
    *out = sign_times(sign_constant(side, x), leaf);
    return 1;
}

/* 18p-8. Se p è una somma di logaritmi nella stessa base b, con
 * coefficienti razionali, più una costante,
 *
 *     K (w_1 log_b f_1 + ... + w_k log_b f_k + c),
 *
 * mette in *out un albero dei segni con lo stesso segno e ritorna 1. La
 * costante c può essere un razionale, oppure contenere logaritmi di numeri:
 * serve solo che c ln b sia una somma u_2 ln 2 + u_3 ln 3 + ..., cioè il
 * logaritmo naturale del razionale q = 2^(u_2) 3^(u_3) ... Allora, con D un
 * intero positivo che rende interi tutti gli esponenti,
 *
 *     segno della somma = segno di  q^D f_1^(D w_1) ... f_k^(D w_k) - 1,
 *
 * perché moltiplicare per D non cambia il segno, la somma dei logaritmi è
 * il logaritmo del prodotto, e un logaritmo in base b > 1 è positivo
 * esattamente quando l'argomento supera 1. Vale dove gli f_i sono positivi,
 * cioè dove il confronto ha un valore. Il fattore K davanti, un numero,
 * porta il suo segno.
 *
 * Ritorna 0, senza fare nulla, se p non ha questa forma. */
static int sign_log_linear(Poly p, int x, const SignNode **out) {
    Poly part[MAX_SPACES], rest = poly_const(num_int(0)), one = poly_const(num_int(1));
    Frac weight[MAX_SPACES];
    int first = -1, side = 1;
    for (int s = 0; s < spaces; s++) part[s] = rest;

    /* I coefficienti dei logaritmi, e ciò che non ne contiene. */
    for (int t = 0; t < p.count; t++) {
        Term bare = p.term[t];
        int where = -1;
        for (int f = 0; f < p.term[t].mono.count; f++) {
            int atom = p.term[t].mono.factor[f].atom, s = space_of(atom);
            if (s == spaces && atom_is_number(atom)) continue;
            if (s == spaces || space[s].kind != SPACE_LOG || where >= 0 || frac_cmp(p.term[t].mono.factor[f].exp, frac_int(1)) != 0) return 0;
            where = s;
            bare.mono = mono_with_exponent(&bare.mono, atom, frac_int(0));
        }
        if (where < 0) { rest = poly_add(rest, poly_term(bare), 0); continue; }
        if (first >= 0 && (space[where].natural != space[first].natural || (!space[where].natural && frac_cmp(space[where].base, space[first].base) != 0))) return 0;
        if (first < 0) first = where;
        part[where] = poly_add(part[where], poly_term(bare), 0);
    }
    if (first < 0) return 0;

    /* I pesi: ogni coefficiente è un multiplo razionale del primo. */
    long long common = 1;
    for (int s = 0; s < spaces; s++) {
        weight[s] = frac_int(s == first);
        if (s == first || part[s].count == 0) continue;
        if (!poly_proportional(part[s], part[first]) || part[s].term[0].coef.im.num != 0 || part[first].term[0].coef.im.num != 0) return 0;
        weight[s] = frac_div(part[s].term[0].coef.re, part[first].term[0].coef.re);
        common = lcm_small(common, weight[s].den);
    }

    /* c ln b = (rest / K) ln b, come somma di logaritmi di primi. Se K è
     * un razionale, rest deve esserlo; se K è un multiplo di ln b (capita
     * quando il confronto contiene il logaritmo di un numero, che porta
     * ln b a denominatore), rest / K per ln b è rest diviso quel multiplo. */
    Poly base_log = space[first].natural ? one : logarithm_of_positive(rat_frac(space[first].base)).num, sum;
    Frac ratio;
    if (failure) return 0;
    if (part[first].count == 1 && part[first].term[0].mono.count == 0) {
        ratio = part[first].term[0].coef.re;
        sum = poly_mul(rest, base_log);
    } else if (!space[first].natural && poly_proportional(part[first], base_log)) {
        ratio = frac_div(part[first].term[0].coef.re, base_log.term[0].coef.re);
        sum = rest;
    } else {
        return 0;
    }
    if (failure || !number_side(part[first], &side)) return 0;

    /* I primi e i loro esponenti u_p = coefficiente / K; poi il prodotto. */
    for (int pass = 0; pass < 2; pass++) {
        Rat product = rat_int(1);
        for (int t = 0; t < sum.count; t++) {
            const Term *term = &sum.term[t];
            const Atom *atom = term->mono.count == 1 ? &atoms[term->mono.factor[0].atom] : NULL;
            if (!atom || atom->kind != ATOM_LN || atom->base != BASE_PRIME || frac_cmp(term->mono.factor[0].exp, frac_int(1)) != 0 || term->coef.im.num != 0) return 0;
            Frac power = frac_div(term->coef.re, ratio);
            if (pass == 0) common = lcm_small(common, power.den);
            else product = rat_mul(product, rat_pow_int(rat_int(atom->id), power.num * (common / power.den)));
        }
        if (pass == 0) continue;
        for (int s = 0; s < spaces && !failure; s++)
            if (weight[s].num != 0) product = rat_mul(product, rat_pow_int(eval(space[s].argument), weight[s].num * (common / weight[s].den)));
        *out = sign_times(sign_constant(side, x), sign_build(rat_add(product, rat_int(1), 1), surd_count, x));
    }
    return 1;
}

/* Prototipo in avanti inevitabile: sign_ground() passa a sign_one_ratio() i
 * polinomi in un rapporto di esponenziali, e sign_one_ratio() le ridà i
 * fattori di due termini. */
static const SignNode *sign_ground(Poly p, int x);

/* 18p-8, regola e di sign_ground(). Se i termini di p sono tutti un numero
 * razionale per un prodotto di potenze di lettere di esponenziali, e quei
 * prodotti sono tutti potenze di uno stesso monomio m per un monomio comune,
 * mette in *out l'albero dei segni di p e ritorna 1; ritorna 0 se p non ha
 * questa forma, o se non la si sa trattare.
 *
 * È l'equazione "omogenea" dei libri: in 2 \cdot 4^x - 5 \cdot 6^x + 3 \cdot 9^x,
 * con le lettere a = 2^x e b = 3^x, i termini sono 2a^2, -5ab, 3b^2, cioè
 * b^2 per un polinomio in m = a / b: 2m^2 - 5m + 3. In generale
 * p = M Q(m), con M un monomio, che è positivo, e Q un polinomio in una
 * variabile; m è un esponenziale, positivo anche lui. Q si scompone: per
 * ogni radice razionale positiva r/s il fattore s m - r, il cui segno è
 * quello di s M+ - r M- (m = M+ / M-), un polinomio di due termini che
 * tratta la regola d; un fattore con la radice negativa o nulla è positivo;
 * ciò che resta, se non ha radici positive (lo dice il teorema di Sturm), ha
 * sugli m positivi il segno che ha in m = 1. Se resta una radice positiva
 * irrazionale il confronto non è trattato: servirebbe il logaritmo di un
 * numero che non è razionale. */
static int sign_one_ratio(Poly p, int x, const SignNode **out) {
    long long exponent[MAX_UNIVARIATE + 1][MAX_SPACES], step[MAX_SPACES], power[MAX_UNIVARIATE + 1], c[MAX_UNIVARIATE + 1] = {0};
    long long common = 0, scale = 1, lowest = 0, highest = 0;
    Frac root[MAX_UNIVARIATE + 2];
    if (p.count < 2 || p.count > MAX_UNIVARIATE + 1) return 0;

    /* Gli esponenti delle lettere in ogni termine. */
    for (int t = 0; t < p.count; t++) {
        const Term *term = &p.term[t];
        if (term->coef.im.num != 0) return 0;
        for (int i = 0; i < spaces; i++) exponent[t][i] = 0;
        for (int f = 0; f < term->mono.count; f++) {
            int i = space_of(term->mono.factor[f].atom);
            if (i == spaces || space[i].kind != SPACE_EXP || term->mono.factor[f].exp.den != 1) return 0;
            exponent[t][i] = term->mono.factor[f].exp.num;
        }
        scale = lcm_small(scale, term->coef.re.den);
        if (scale > 1000000) return 0;
    }

    /* Il monomio m: la differenza tra due termini, ridotta ai minimi termini
     * e con il primo esponente positivo. */
    for (int i = 0; i < spaces; i++) common = (long long)gcd128(common, exponent[1][i] - exponent[0][i]);
    if (common == 0) return 0;
    for (int i = 0, seen = 0; i < spaces; i++) {
        step[i] = (exponent[1][i] - exponent[0][i]) / common;
        if (!seen && step[i] < 0) common = -common, step[i] = -step[i];
        seen |= step[i] != 0;
    }

    /* Ogni termine è il primo per una potenza intera di m. */
    for (int t = 0; t < p.count; t++) {
        int lead = 0;
        while (step[lead] == 0) lead++;
        power[t] = (exponent[t][lead] - exponent[0][lead]) / step[lead];
        for (int i = 0; i < spaces; i++)
            if (exponent[t][i] - exponent[0][i] != power[t] * step[i]) return 0;
        if (power[t] < lowest) lowest = power[t];
        if (power[t] > highest) highest = power[t];
    }
    int degree = (int)(highest - lowest);
    if (highest - lowest > MAX_UNIVARIATE) return 0;
    for (int t = 0; t < p.count; t++) {
        Frac value = frac_mul(p.term[t].coef.re, frac_int(scale));
        if (failure || value.num > LLONG_MAX / 4 || value.num < -(LLONG_MAX / 4)) return 0;
        c[power[t] - lowest] = value.num;
    }

    /* Q e le sue radici razionali; M+ e M-. */
    Uni rest = {degree, {0}}, quotient;
    Mono plus = {0}, minus = {0};
    const SignNode *tree = NULL;
    int roots = rational_roots(c, degree, root);
    if (roots < 0) return 0;
    for (int i = 0; i <= degree; i++) rest.c[i] = c[i];
    for (int i = 0; i < spaces; i++) {
        if (step[i] > 0) plus = mono_with_exponent(&plus, space[i].letter, frac_int(step[i]));
        if (step[i] < 0) minus = mono_with_exponent(&minus, space[i].letter, frac_int(-step[i]));
    }
    for (int r = 0; r < roots && !failure; r++) {
        Uni linear = {1, {-(__int128)root[r].num, root[r].den}};
        const SignNode *factor = root[r].num > 0 ? sign_ground(poly_add(poly_term((Term){num_int(root[r].den), plus}), poly_term((Term){num_int(root[r].num), minus}), 1), x) : NULL;

        /* Una radice multipla dà lo stesso fattore più volte. */
        while (!failure && uni_divide(&rest, &linear, &quotient)) {
            rest = quotient;
            if (factor) tree = tree ? sign_times(tree, factor) : factor;
        }
    }
    if (failure) return 0;

    /* Ciò che resta non deve annullarsi per m positivo. */
    if (rest.degree >= 1) {
        Wide bound = uni_bound(&rest);
        sturm_build(&rest);
        if (failure || sturm_changes((Wide){0, 1}) - sturm_changes(bound) != 0) return 0;
    }
    const SignNode *sign = sign_constant(uni_sign_at(&rest, (Wide){1, 1}), x);
    *out = tree ? sign_times(sign, tree) : sign;
    return !failure;
}

/* 18p-8. Ritorna l'albero dei segni del polinomio p, che non contiene
 * radici ma può contenere la variabile (atomo x), lettere di spazi e numeri
 * come ln 2.
 *
 *   a. Una somma di logaritmi: sign_log_linear().
 *   b. Una lettera sola, la variabile o quella di uno spazio, con
 *      coefficienti razionali: una foglia. Con la variabile e coefficienti
 *      che sono numeri non razionali: sign_number_linear().
 *   c. Più lettere. Una lettera di spazio che divide tutti i termini si
 *      raccoglie. Poi si sceglie una lettera g e si scrive p come polinomio
 *      in g, con i coefficienti nelle altre lettere: se sono tutti multipli
 *      razionali di uno stesso polinomio U, allora p = U V(g), e il segno è
 *      il prodotto dei due segni.
 *   d. Due termini soli, ognuno un numero per un prodotto di potenze di
 *      esponenziali: c_1 M_1 + c_2 M_2. Se c_1 e c_2 hanno lo stesso segno
 *      è il loro. Altrimenti il segno è quello del logaritmo del rapporto
 *      |c_1| M_1 / (|c_2| M_2), che è A x + B con A e B numeri fatti di
 *      logaritmi: di nuovo sign_number_linear(). È così che si risolve
 *      2^x = 3^(x+1).
 *   e. Più di due termini, tutti potenze di uno stesso monomio di
 *      esponenziali per un monomio comune: un polinomio in quel monomio
 *      (sign_one_ratio()).
 *
 * In ogni altro caso le lettere sono davvero mescolate, e il confronto non
 * è trattato. */
static const SignNode *sign_ground(Poly p, int x) {
    const SignNode *found = &sign_node[0];
    int s = poly_space(p);
    if (failure) return found;
    if (s != -1 && sign_log_linear(p, x, &found)) return found;

    /* b. */
    if (s == -1 || (s >= 0 && !poly_uses(p, x))) {
        Uni top;
        int up;
        if (!uni_from_poly(p, s < 0 ? x : space[s].letter, &top, &up)) {
            if (failure || s != -1 || !sign_number_linear(p, x, &found)) fail(SIGN_SHAPE);
            return found;
        }
        SignNode *leaf = sign_node_new(SIGN_LEAF);
        leaf->space = s;
        leaf->top = sign_column_in(top, s);
        leaf->bottom = sign_column_in((Uni){0, {1}}, s);
        leaf->power = up;
        leaf->letter = up ? sign_column_in((Uni){1, {0, 1}}, s) : -1;
        return leaf;
    }

    /* c. La lettera g: quella dell'ultimo spazio che compare. lowest è il
     * suo esponente più basso tra tutti i termini. */
    int g = spaces - 1;
    while (g > 0 && !poly_uses(p, space[g].letter)) g--;

    /* Una lettera che divide tutti i termini si raccoglie, qualunque sia:
     * L_1^2 - L_1 L_2 è L_1 (L_1 - L_2) anche se la lettera scelta è L_2. */
    for (int h = g; h >= 0; h--) {
        long long lowest = LLONG_MAX;
        for (int t = 0; t < p.count; t++) {
            Frac e = mono_exponent(&p.term[t].mono, space[h].letter);
            if (e.den != 1) { fail(SIGN_SHAPE); return found; }
            if (e.num < lowest) lowest = e.num;
        }
        if (lowest == 0) continue;

        /* p = h^lowest per un polinomio senza h a fattor comune. Con lowest
         * negativo h sta a denominatore, e il segno di h^lowest è quello di
         * h^(-lowest): dove h è zero il confronto non ha un valore. */
        Poly factor = poly_term((Term){num_int(1), mono_atom(space[h].letter, frac_int(lowest < 0 ? -lowest : lowest))});
        return sign_times(sign_ground(factor, x), sign_ground(poly_mul(p, poly_term((Term){num_int(1), mono_atom(space[h].letter, frac_int(-lowest))})), x));
    }
    Poly part[MAX_UNI + 1];
    int degree = poly_split(p, space[g].letter, part, MAX_UNI), lead = 0, apart = degree >= 0;
    while (apart && part[lead].count == 0) lead++;

    /* I coefficienti devono essere multipli di part[lead]: i rapporti sono
     * i coefficienti di V. */
    Poly other = poly_const(num_int(0));
    for (int j = lead; j <= degree && apart; j++) {
        if (part[j].count == 0) continue;
        if (!poly_proportional(part[j], part[lead])) { apart = 0; break; }
        Num ratio = num_mul(part[j].term[0].coef, num_inv(part[lead].term[0].coef));
        other = poly_add(other, poly_term((Term){ratio, j ? mono_atom(space[g].letter, frac_int(j)) : (Mono){0}}), 0);
    }
    if (apart) return sign_times(sign_ground(part[lead], x), sign_ground(other, x));

    /* e. Più di due termini: potenze di uno stesso monomio di
     * esponenziali (sign_one_ratio()). */
    if (p.count > 2) {
        if (!sign_one_ratio(p, x, &found) && !failure) fail(SIGN_SHAPE);
        return found;
    }

    /* d. Il logaritmo del rapporto dei due termini: per ogni lettera
     * p^(x/L) con esponente k nel rapporto, (k / L) x ln p (ln e = 1). */
    if (p.count != 2 || p.term[0].coef.im.num != 0 || p.term[1].coef.im.num != 0) { fail(SIGN_SHAPE); return found; }

    /* I due termini devono essere fatti solo di lettere di esponenziali,
     * che sono positive: lo si controlla prima di ogni altra cosa. Una
     * versione che guardava i segni dei coefficienti senza questo controllo
     * dava per positivo x + 2^x, cioè risolveva x + 2^x > 0 con "ogni x". */
    for (int side = 0; side < 2; side++)
        for (int f = 0; f < p.term[side].mono.count; f++) {
            int space_number = space_of(p.term[side].mono.factor[f].atom);
            if (space_number == spaces || space[space_number].kind != SPACE_EXP || p.term[side].mono.factor[f].exp.den != 1) { fail(SIGN_SHAPE); return found; }
        }
    Frac first = p.term[0].coef.re, second = p.term[1].coef.re;
    if ((first.num > 0) == (second.num > 0)) return sign_constant(first.num > 0 ? 1 : -1, x);
    Rat log_ratio = logarithm_of_positive(rat_frac(frac_div(first.num < 0 ? frac_neg(first) : first, second.num < 0 ? frac_neg(second) : second)));
    for (int side = 0; side < 2 && !failure; side++)
        for (int f = 0; f < p.term[side].mono.count && !failure; f++) {
            Frac e = p.term[side].mono.factor[f].exp;
            const Space *sp = &space[space_of(p.term[side].mono.factor[f].atom)];
            Rat slope = rat_mul(rat_frac(frac_make(side ? -e.num : e.num, sp->scale)), sp->prime ? logarithm_of_positive(rat_int(sp->prime)) : rat_int(1));
            log_ratio = rat_add(log_ratio, rat_mul(slope, rat_atom(x)), 0);
        }
    if (failure) return found;

    /* p ha il segno del suo primo coefficiente dove il rapporto supera 1. */
    SignNode *ratio = sign_node_new(SIGN_RATIO);
    ratio->a = sign_ground(log_ratio.num, x);
    ratio->b = sign_ground(log_ratio.den, x);
    return sign_times(sign_constant(first.num > 0 ? 1 : -1, x), ratio);
}

/* Ritorna l'albero dei segni di a + b s, dove s è la radice numero i e a e
 * b contengono solo le radici precedenti. */
static const SignNode *sign_surd(Rat a, Rat b, int i, int x) {
    if (b.num.count == 0) return sign_build(a, i, x);
    SignNode *node = sign_node_new(SIGN_SURD);
    Rat norm = rat_add(rat_mul(a, a), rat_mul(rat_mul(b, b), surd_inside[i]), 1);
    node->a = sign_build(a, i, x);
    node->b = sign_build(b, i, x);
    node->r = sign_build(surd_inside[i], i, x);
    node->n = sign_build(norm, i, x);
    return node;
}

/* 18p-7. Ritorna l'albero dei segni della frazione e, che può contenere la
 * variabile di atomo x e le lettere delle prime `level` radici. Annota un
 * errore se contiene altro. */
static const SignNode *sign_build(Rat e, int level, int x) {
    if (failure) return &sign_node[0];

    /* Le radici che non compaiono non contano; senza radici e senza lettere
     * di spazi è una foglia, con numeratore e denominatore tra le colonne
     * della tabella e le potenze di x a denominatore tenute a parte. Con le
     * lettere degli spazi, numeratore e denominatore vanno ognuno per conto
     * suo (18p-8). */
    while (level > 0 && !poly_uses(e.num, surd_letter[level - 1]) && !poly_uses(e.den, surd_letter[level - 1])) level--;
    Uni top, bottom;
    int up, down;
    if (level == 0 && (poly_space(e.num) != -1 || poly_space(e.den) != -1 || !uni_from_poly(e.num, x, &top, &up) || !uni_from_poly(e.den, x, &bottom, &down))) {
        SignNode *node = sign_node_new(SIGN_RATIO);
        node->a = sign_ground(e.num, x);
        node->b = sign_ground(e.den, x);
        return node;
    }
    if (level == 0) {
        SignNode *leaf = sign_node_new(SIGN_LEAF);
        leaf->top = sign_column(top);
        leaf->bottom = sign_column(bottom);
        leaf->power = up - down;
        leaf->letter = up || down ? sign_column((Uni){1, {0, 1}}) : -1;
        return leaf;
    }

    /* Numeratore e denominatore, ognuno come P + Q s nell'ultima radice. */
    Rat a, b, c, d;
    surd_split(e.num, level - 1, &a, &b);
    surd_split(e.den, level - 1, &c, &d);
    if (failure) return &sign_node[0];
    SignNode *node = sign_node_new(SIGN_RATIO);
    node->a = sign_surd(a, b, level - 1, x);
    node->b = sign_surd(c, d, level - 1, x);
    return node;
}

/* Prototipo in avanti inevitabile: il tratto in cui sta la lettera di uno
 * spazio (space_row()) si legge dai confronti dei suoi gradini, cioè da
 * sign_compare(), che a sua volta legge i segni delle foglie negli spazi
 * attraverso space_row(). sign_compare() sta nel capitolo 18.11, con i
 * confronti preparati. */
static int sign_compare(const Formula *f, const int *sign, int *defined);

/* Ritorna in quale tratto del suo spazio sta la lettera dello spazio s,
 * nella riga della tabella in cui i polinomi hanno i segni di sign[]: con k
 * gradini sotto di sé sta nel tratto 2k, e se è proprio su un gradino, che
 * allora è il gradino numero k, nel tratto 2k + 1. I gradini sono in ordine
 * crescente, quindi quelli sotto sono i primi. */
static int space_row(int s, const int *sign, int *defined) {
    int below = 0, on = 0;
    for (int j = 0; j < space[s].steps; j++) {
        const Step *step = &space[s].step[j];
        int side = step->above ? sign_compare(step->above, sign, defined) : sign[step->kappa];
        if (side > 0) below++;
        else if (side == 0) on = 1;
    }
    return 2 * below + on;
}

/* Ritorna il segno del polinomio della colonna column, che è nella lettera
 * dello spazio s, quando la lettera sta nel tratto row (vedi space_row()).
 * Su un gradino è zero se il polinomio del gradino lo divide (18p-5); in un
 * tratto aperto lo si calcola in un razionale del tratto. Per un
 * esponenziale il primo tratto va da zero, escluso, al primo gradino. */
static int space_sign(int s, int row, int column) {
    const Space *sp = &space[s];
    const Uni *p = &sign_poly[column];
    int k = row / 2;
    Uni rest;
    if (row % 2) {
        const Step *step = &sp->step[k];
        if (step->exact) return uni_sign_at(p, step->low);
        return uni_divide(p, &step->element, &rest) ? 0 : uni_sign_at(p, wide_mid(step->low, step->high));
    }
    if (sp->steps == 0) return uni_sign_at(p, (Wide){1, 1});
    if (k == sp->steps) return uni_sign_at(p, (Wide){sp->step[k - 1].high.num / sp->step[k - 1].high.den + 2, 1});
    if (k > 0) return uni_sign_at(p, wide_between(sp->step[k - 1].high, sp->step[k].low));
    return uni_sign_at(p, sp->kind == SPACE_EXP ? wide_between((Wide){0, 1}, sp->step[0].low) : (Wide){sp->step[0].low.num / sp->step[0].low.den - 2, 1});
}

/* Ritorna il segno del nodo dove i polinomi hanno i segni di sign[]; mette 0
 * in *defined, che chi chiama ha messo a 1, se lì non ha valore. Le regole
 * per SIGN_SURD sono quelle in testa a 18p-7. */
static int sign_value(const SignNode *node, const int *sign, int *defined) {
    if (node->kind == SIGN_LEAF && node->space < 0) {
        if (sign[node->bottom] == 0 || (node->letter >= 0 && sign[node->letter] == 0)) *defined = 0;
        return sign[node->top] * sign[node->bottom] * (node->power % 2 ? sign[node->letter] : 1);
    }
    if (node->kind == SIGN_LEAF) {
        /* Una foglia in uno spazio: gli stessi tre segni, letti nel tratto
         * in cui sta la lettera. */
        int row = space_row(node->space, sign, defined);
        int below = space_sign(node->space, row, node->bottom), letter = node->letter >= 0 ? space_sign(node->space, row, node->letter) : 1;
        if (below == 0 || letter == 0) *defined = 0;
        return space_sign(node->space, row, node->top) * below * (node->power % 2 ? letter : 1);
    }
    int plain = sign_value(node->a, sign, defined), with = sign_value(node->b, sign, defined);
    if (node->kind == SIGN_TIMES) return plain * with;
    if (node->kind == SIGN_RATIO) {
        if (with == 0) *defined = 0;
        return plain * with;
    }
    int inside = sign_value(node->r, sign, defined), norm = sign_value(node->n, sign, defined);
    if (inside < 0) *defined = 0;
    if (with == 0 || inside == 0) return plain;
    if (plain == 0 || plain == with) return with;
    return plain * norm;
}

/* Aggiunge alle condizioni di esistenza di *out che la frazione e sia non
 * negativa (strict = 0), diversa da zero (1) o positiva (2). */
static void sign_require(SignCase *out, Rat e, int level, int strict, int x) {
    if (failure) return;
    if (sign_needs == MAX_SIGN_NEEDS) { fail("troppe condizioni di esistenza in un enunciato"); return; }
    sign_need[sign_needs++] = (SignNeed){sign_build(e, level, x), strict};
    out->needs++;
}

/* 18p-9. MONOMI DI POTENZE
 *
 * 2^(x+5) 3^(x+2) <= 8 * 6^((3x-1)/x) ha la variabile in esponenti che non
 * sono di primo grado, e le lettere di 18p-8 non bastano. Ma i due membri
 * sono monomi: prodotti di potenze di numeri positivi. Un monomio così è
 *
 *     prodotto sui primi p di p^(H_p(x)),      con gli H_p frazioni in x,
 *
 * e il segno della differenza di due monomi positivi è il segno della
 * differenza dei loro logaritmi, cioè di una somma di H_p(x) ln p. Se gli
 * H_p sono tutti multipli razionali di uno stesso H, H_p = w_p H, la somma è
 * H(x) ln W con W = prodotto dei p^(w_p), un razionale: il segno è quello
 * di H(x) se W > 1, il suo opposto se W < 1. Resta un confronto tra frazioni
 * in x. Nell'esempio, portato tutto a sinistra, H_2 = H_3 = x - 1 + 1/x.
 *
 * Se gli H_p non sono proporzionali, come in 2^x = 3^(x+1), il confronto
 * non è di questo tipo.
 */

/* Un monomio di potenze in costruzione: per ogni primo l'esponente, una
 * frazione nella variabile. */
typedef struct {
    int count;                     /* quanti primi, in prime[] */
    long long prime[MAX_FACTORS];  /* i primi, ognuno una volta */
    Rat power[MAX_FACTORS];        /* l'esponente di prime[i], una frazione in x */
} Powers;

/* Moltiplica il monomio *m per prime elevato a power. Ritorna 0 se i primi
 * sono troppi. */
static int powers_times(Powers *m, long long prime, Rat power) {
    int i = 0;
    while (i < m->count && m->prime[i] != prime) i++;
    if (i == MAX_FACTORS) return 0;
    if (i == m->count) { m->prime[m->count++] = prime; m->power[i] = rat_int(0); }
    m->power[i] = rat_add(m->power[i], power, 0);
    return 1;
}

/* Moltiplica *m per il monomio dell'espressione node elevato a scale, e
 * ritorna 1; ritorna 0 se node non è un monomio di potenze: un numero
 * positivo, un prodotto, un quoziente, una potenza o una radice di monomi.
 * Gli esponenti e gli indici delle radici sono espressioni qualsiasi. */
static int powers_read(const Node *node, Rat scale, Powers *m) {
    long long prime, times;
    if (failure) return 0;
    switch (node->kind) {
    case N_NUM: {
        long long value = node->value;
        if (value <= 0) return 0;
        while (pop_prime(&value, &prime, &times))
            if (!powers_times(m, prime, rat_mul(scale, rat_int(times)))) return 0;
        return 1;
    }
    case N_MUL: return powers_read(node->a, scale, m) && powers_read(node->b, scale, m);
    case N_DIV: return powers_read(node->a, scale, m) && powers_read(node->b, rat_add(rat_int(0), scale, 1), m);
    case N_POW: return powers_read(node->a, rat_mul(scale, eval(node->b)), m);
    case N_CALL:
        if (node->op != FN_ROOT) return 0;
        return powers_read(node->a, rat_div(scale, eval(node->b)), m);
    default: return 0;
    }
}

/* 18p-9. Se left e right sono monomi di potenze con la variabile in qualche
 * esponente, e gli esponenti dei primi nel loro rapporto sono proporzionali,
 * mette in *out una frazione nella variabile che ha il segno di
 * left - right e ritorna 1. Le condizioni di esistenza degli esponenti
 * restano annotate in conditions[]. Altrimenti ritorna 0. */
static int powers_difference(const Node *left, const Node *right, Rat *out) {
    Powers m = {0};
    int lead = -1;
    Frac weight[MAX_FACTORS];
    if (!node_uses_letter(left, sign_name) && !node_uses_letter(right, sign_name)) return 0;

    /* "A - B confrontato con 0" è "A confrontato con B". */
    if (left->kind == N_SUB && right->kind == N_NUM && right->value == 0) {
        right = left->b;
        left = left->a;
    }
    if (!powers_read(left, rat_int(1), &m) || !powers_read(right, rat_int(-1), &m) || failure) return 0;

    /* Gli esponenti, tutti multipli di quello del primo che ne ha uno non
     * nullo: si confrontano i prodotti in croce, come in surd_relate(). */
    for (int i = 0; i < m.count; i++) {
        weight[i] = frac_int(0);
        if (m.power[i].num.count == 0) continue;
        if (lead < 0) { lead = i; weight[i] = frac_int(1); continue; }
        Poly a = poly_mul(m.power[i].num, m.power[lead].den), b = poly_mul(m.power[i].den, m.power[lead].num);
        if (a.count != b.count || a.term[0].coef.im.num != 0 || b.term[0].coef.im.num != 0) return 0;
        weight[i] = frac_div(a.term[0].coef.re, b.term[0].coef.re);
        if (failure || !poly_equal(a, poly_mul(b, poly_const(num_frac(weight[i]))))) return 0;
    }
    if (lead < 0) { *out = rat_int(0); return 1; }

    /* Il segno di ln W = somma dei w_p ln p: con D il minimo comune multiplo
     * dei denominatori, è il segno di prodotto dei p^(D w_p) meno 1, cioè
     * del confronto tra i primi con esponente positivo e quelli con
     * esponente negativo. */
    long long common = 1;
    Wide above = {1, 1}, below = {1, 1};
    for (int i = 0; i < m.count; i++) common = lcm_small(common, weight[i].den);
    for (int i = 0; i < m.count && !failure; i++) {
        long long whole = weight[i].num * (common / weight[i].den);
        for (long long k = 0; k < (whole < 0 ? -whole : whole) && !failure; k++)
            if (whole > 0) above = wide_mul(above, (Wide){m.prime[i], 1}); else below = wide_mul(below, (Wide){m.prime[i], 1});
    }
    if (failure) return 0;
    int side = wide_cmp(above, below);
    *out = side < 0 ? rat_add(rat_int(0), m.power[lead], 1) : side > 0 ? m.power[lead] : rat_int(0);
    return 1;
}

/* Calcola left - right (solo left se right è NULL) con i valori assoluti
 * presi secondo `pattern`, e ne prepara in *out l'albero dei segni nella
 * variabile di atomo x, con le condizioni di esistenza. Annota un errore se
 * non è fatta di espressioni razionali e radici quadrate. */
static void sign_fraction(const Node *left, const Node *right, unsigned pattern, int x, SignCase *out) {
    Rat one = rat_int(1);
    out->first = sign_needs;
    out->needs = 0;

    /* Il conto, annotando i divisori incontrati: prima i radicandi, dal più
     * interno, poi la differenza. */
    condition_count = conditions_lost = undefined = 0;
    conditions_on = 1;
    abs_pattern = pattern;
    env_count = 0;
    space_seen = 0;
    for (int i = 0; i < surd_count; i++) surd_value[i] = rat_atom(surd_letter[i]);

    /* 18p-9. Due monomi di potenze: la differenza degli esponenti ha lo
     * stesso segno della differenza dei membri, e non servono lettere. */
    Rat exponent;
    if (right && powers_difference(left, right, &exponent)) {
        conditions_on = 0;
        if (failure) return;
        if (conditions_lost) { fail("troppe condizioni di esistenza in un confronto"); return; }
        out->value = sign_build(exponent, 0, x);
        for (int i = 0; i < condition_count && !failure; i++)
            for (int j = 0; j < conditions[i].count; j++) sign_require(out, (Rat){conditions[i].factor[j], one.num}, 0, 1, x);
        return;
    }
    condition_count = conditions_lost = undefined = 0;
    failure = NULL;
    for (int i = 0; i < surd_count; i++) surd_inside[i] = eval(surd_node[i]->a);

    /* Per l'argomento di un valore assoluto (right è NULL) le condizioni
     * incontrate nei radicandi non contano: i radicandi sono quelli di tutto
     * il confronto, non dell'argomento, e possono contenere proprio il
     * valore assoluto di cui si sta cercando il ramo. Contare l'argomento
     * positivo di un logaritmo sotto radice faceva risultare non definita
     * la radice di log |x| per x negativo. */
    if (!right) {
        condition_count = conditions_lost = 0;
        space_seen = 0;
    }

    /* Le relazioni tra le radici si cercano con l'elenco spento: le
     * divisioni di quel conto non sono dell'enunciato. */
    conditions_on = 0;
    if (!failure) surd_relate();
    conditions_on = 1;
    Rat d = eval(left);
    if (right) d = rat_add(d, eval(right), 1);
    conditions_on = 0;

    /* Una divisione per un'espressione che è zero ovunque: con questa scelta
     * dei segni il confronto non è definito in nessun punto. Capita con
     * |x + |x||, che dove x è negativo vale zero. Lo dice una condizione che
     * non vale mai: lo zero deve essere diverso da zero. */
    if (failure && undefined) {
        failure = NULL;
        undefined = 0;
        out->value = sign_build(rat_int(0), 0, x);
        sign_require(out, rat_int(0), 0, 1, x);
        return;
    }
    if (failure) return;
    if (conditions_lost) { fail("troppe condizioni di esistenza in un confronto"); return; }
    out->value = sign_build(d, surd_count, x);

    /* Le condizioni di esistenza annotate nel conto. Un divisore diverso da
     * zero: ogni suo fattore. Le altre due, che nascono dai logaritmi e
     * dalle potenze che il conto non ha trasformato in lettere (quelli di
     * un numero, per esempio), riguardano il prodotto dei fattori: positivo,
     * oppure non negativo. */
    for (int i = 0; i < condition_count && !failure; i++) {
        Rat product = one;
        for (int j = 0; j < conditions[i].count; j++) {
            if (conditions[i].kind == NEVER_ZERO) sign_require(out, (Rat){conditions[i].factor[j], one.num}, surd_count, 1, x);
            else product = rat_mul(product, (Rat){conditions[i].factor[j], one.num});
        }
        if (conditions[i].kind != NEVER_ZERO) sign_require(out, product, surd_count, conditions[i].kind == ALWAYS_POSITIVE ? 2 : 0, x);
    }
    /* I radicandi non negativi si chiedono al confronto intero (right non è
     * NULL), non all'argomento di un valore assoluto. L'argomento serve a
     * scegliere il ramo del valore assoluto, e lo si calcola prima di sapere
     * quale ramo vale: un radicando che contiene quel valore assoluto, lì, è
     * ancora quello del ramo sbagliato. Chiederlo faceva risultare non
     * definita la radice di |e^x - 2| - 1 dove e^x < 1, che invece lo è. Il
     * confronto intero, nel ramo giusto, chiede comunque tutti i radicandi. */
    for (int i = 0; i < surd_count && right; i++) sign_require(out, surd_inside[i], i, 0, x);

    /* Gli argomenti dei logaritmi comparsi nel conto: positivi. */
    unsigned seen = space_seen;
    for (int s = 0; s < spaces; s++)
        if (seen >> s & 1) sign_require(out, eval(space[s].argument), surd_count, 2, x);
}

/* =============================================================================
 * 18.11 I CONFRONTI PREPARATI, E LA LORO VERITÀ IN UNA RIGA
 * ============================================================================
 *
 * sign_prepare() percorre l'enunciato e prepara ogni confronto per la
 * tabella (SignAtom): un albero dei segni per ogni scelta dei segni dei
 * valori assoluti, una finestra in un enunciato periodico (18p-14), una
 * famiglia di soluzioni sotto un "esiste k" (18p-13). Poi i gradini di ogni
 * spazio diventano confronti nella variabile (18p-8, space_process()).
 * Preparato tutto, sign_truth() dice se l'enunciato vale in una riga della
 * tabella, cioè dati i segni di tutti i polinomi.
 */

/* Mette tra le radici in corso quelle di 2 e di 3, con le loro lettere: i
 * seni e i coseni degli angoli costanti di un enunciato periodico si
 * scrivono con quelle (18p-11). Serve a chi prepara un albero dei segni che
 * non viene da un confronto scritto nell'enunciato. */
static void trig_roots_open(void) {
    abs_count = surd_count = 0;
    for (int i = 0; i < 2; i++) surd_collect(trig_root[i]);
    for (int i = 0; i < surd_count; i++) {
        surd_value[i] = rat_atom(surd_letter[i]);
        surd_inside[i] = eval(surd_node[i]->a);
    }
}

/* I segni del seno e del coseno di un angolo, come alberi dei segni: dicono
 * in quale quarto di giro sta l'angolo, e se è un multiplo di 2 pi. */
typedef struct {
    SignCase sine, cosine;
} FamilyAngle;

/* Una famiglia preparata per la tabella (18p-13): gli angoli che dicono se
 * la variabile sta in uno dei suoi punti o intervalli. below è l'angolo
 * A = 2 pi (x - low) / T, above è B = 2 pi (high - x) / T (non usato per un
 * punto), hole[i] è 2 pi (x - hole[i]) / T. wide dice che l'intervallo è più
 * lungo di mezzo periodo, full che è lungo proprio un periodo (allora copre
 * tutto, tranne al più il punto in cui comincia e finisce); hole_counts[i]
 * che quel punto tolto sta nell'intervallo dello stesso k, il solo caso in
 * cui toglie qualcosa. */
typedef struct {
    const Formula *owner;  /* il quantificatore di cui la famiglia è un pezzo */
    Family family;
    FamilyAngle below, above, hole[MAX_LATTICE_HOLES];
    int wide, full;
    int hole_counts[MAX_LATTICE_HOLES];
} FamilyLeaf;

/* Le famiglie dell'enunciato in corso, di tutti i suoi quantificatori su un
 * intero: family_truth() prende quelle del suo (owner). */
static FamilyLeaf family_leaf[MAX_LATTICE];
static int family_leaves;

/* Prepara in *out i segni del seno e del coseno di
 * direction 2 pi (x - e) / T, dove e = alpha + k T è un'espressione della
 * famiglia e direction è 1 o -1.
 *
 * L'angolo è n u + psi con u = g x l'angolo dell'enunciato, n intero e
 * psi = -direction 2 pi alpha / T un angolo costante. Di psi serve la
 * direzione (cos psi, sin psi) a meno di un fattore positivo: la parte che
 * è un multiplo di pi la dà trig_constant(); ogni arcotangente di un
 * razionale m, con coefficiente intero p, la ruota di (1 + i m)^p, perché
 * cos(arctan m) + i sin(arctan m) è 1 + i m diviso per un numero positivo. */
static void family_angle(const Node *e, int k, int direction, int x, FamilyAngle *out) {
    Frac tau, turn = frac_int(0);
    Rat alpha, real = rat_int(1), imaginary = rat_int(0), cb, sb, cn, sn;
    int pi = atom_var(VAR_PI);
    out->sine.first = out->cosine.first = sign_needs;
    out->sine.needs = out->cosine.needs = 0;
    if (!family_period(e, k, &tau, &alpha)) { if (!failure) fail(SIGN_SHAPE); return; }
    if (tau.num < 0) tau.num = -tau.num;
    Frac multiple = frac_div(frac_div(frac_int(2 * direction), tau), trig_scale), scale = frac_div(frac_int(-2 * direction), tau);
    if (multiple.den != 1) { fail(SIGN_SHAPE); return; }

    /* psi, un termine di alpha alla volta. */
    Frac den = alpha.den.term[0].coef.re;
    for (int i = 0; i < alpha.num.count && !failure; i++) {
        const Term *t = &alpha.num.term[i];
        const Atom *atom = t->mono.count == 1 ? &atoms[t->mono.factor[0].atom] : NULL;
        Frac weight = frac_mul(frac_div(t->coef.re, den), scale);
        Num slope;
        if (!atom || t->coef.im.num != 0 || frac_cmp(t->mono.factor[0].exp, frac_int(1)) != 0) { fail(SIGN_SHAPE); return; }
        if (t->mono.factor[0].atom == pi) { turn = frac_add(turn, weight); continue; }
        if (atom->kind != ATOM_ATAN || weight.den != 1 || !rat_number(atan_args[atom->id], &slope) || slope.im.num != 0) { fail(SIGN_SHAPE); return; }
        Rat m = rat_frac(weight.num < 0 ? frac_neg(slope.re) : slope.re);
        for (long long step = 0; step < (weight.num < 0 ? -weight.num : weight.num); step++) {
            Rat was = real;
            real = rat_add(real, rat_mul(imaginary, m), 1);
            imaginary = rat_add(imaginary, rat_mul(was, m), 0);
        }
    }
    if (failure || !trig_constant(turn, &cb, &sb)) { if (!failure) fail("una famiglia di soluzioni con un angolo che non è un multiplo di 15 gradi"); return; }

    /* sin(n u + psi) e cos(n u + psi), con le formule di addizione. */
    Rat cosine = rat_add(rat_mul(cb, real), rat_mul(sb, imaginary), 1), sine = rat_add(rat_mul(sb, real), rat_mul(cb, imaginary), 0);
    trig_multiple(multiple.num, &cn, &sn);
    out->sine.value = sign_build(rat_add(rat_mul(sn, cosine), rat_mul(cn, sine), 0), surd_count, x);
    out->cosine.value = sign_build(rat_add(rat_mul(cn, cosine), rat_mul(sn, sine), 1), surd_count, x);
}

/* Per sign_prepare: prepara il pezzo d del quantificatore owner. context
 * punta all'atomo della lettera della tabella. La lunghezza dell'intervallo
 * rispetto al periodo, e se un punto tolto sta nell'intervallo dello stesso
 * k, si decidono con i numeri, per k = 0 e k = 1: dove non è certo, il pezzo
 * non è trattato. */
static void family_prepare(const Formula *owner, const Formula *d, void *context) {
    int x = *(const int *)context, none = 0, side = 0;
    Range zero = {0, 0}, one = {1, 1};
    if (failure) return;
    if (family_leaves == MAX_LATTICE) { fail("troppe famiglie di soluzioni in un enunciato"); return; }
    FamilyLeaf *leaf = &family_leaf[family_leaves++];
    const Family *family = &leaf->family;
    leaf->owner = owner;
    if (!family_read(d, sign_name, owner->variable, owner->kind == F_FORALL, &leaf->family)) { fail(SIGN_SHAPE); return; }

    /* Le radici di 2 e di 3 servono ai seni e ai coseni degli angoli
     * costanti, come in ogni confronto di un enunciato periodico. */
    trig_roots_open();
    trig_live = 1;
    family_angle(family->low, family->k, 1, x, &leaf->below);
    if (!family->single && !failure) {
        /* L'intervallo deve stare in un periodo; wide se supera la metà. Un
         * intervallo lungo proprio mezzo periodo va bene in tutti e due i
         * modi (i due seni sono uguali), e uno lungo proprio un periodo è
         * un caso a sé (full); ma con i numeri un'uguaglianza non la si
         * vede mai: lì decide il conto esatto, quando gli estremi sono
         * multipli di pi. */
        Frac tau, slope, turns = frac_int(0);
        Rat low_part, high_part;
        Range low = node_range(family->low, family->k, zero, &none), width = range_sub(node_range(family->high, family->k, zero, &none), low);
        Range period = range_sub(node_range(family->low, family->k, one, &none), low);
        if (range_side(period, &side) && side < 0) period = range_neg(period);
        int positive = range_side(width, &side) && side > 0, inside = range_side(range_sub(period, width), &side) && side > 0;
        int exact = family_period(family->low, family->k, &tau, &low_part) && family_period(family->high, family->k, &tau, &high_part) &&
                    trig_affine(rat_add(high_part, low_part, 1), &slope, &turns) && slope.num == 0;
        if (tau.num < 0) tau.num = -tau.num;
        int half = exact && frac_cmp(frac_add(turns, turns), tau) == 0;
        leaf->full = exact && frac_cmp(turns, tau) == 0;
        leaf->wide = 0;
        if (!leaf->full && !half) {
            if (!positive || !inside) fail("un intervallo di una famiglia di soluzioni non può essere più lungo del periodo");
            else if (!range_side(range_sub(range_add(width, width), period), &side)) fail("non so dire se un intervallo di una famiglia di soluzioni supera mezzo periodo");
            else leaf->wide = side > 0;
        }
        family_angle(family->high, family->k, -1, x, &leaf->above);
    }
    for (int i = 0; i < family->holes && !failure; i++) {
        Range hole = node_range(family->hole[i], family->k, zero, &none);
        int after = range_side(range_sub(hole, node_range(family->low, family->k, zero, &none)), &side) ? side : 0;
        int before = range_side(range_sub(node_range(family->high, family->k, zero, &none), hole), &side) ? side : 0;
        if (after == 0 || before == 0) { fail("un punto tolto proprio sull'estremo di un intervallo: non so dire se conta"); break; }
        leaf->hole_counts[i] = after > 0 && before > 0;
        family_angle(family->hole[i], family->k, 1, x, &leaf->hole[i]);
    }
    trig_live = 0;
    surd_count = 0;
}

/* Ritorna 1 se in node compare una funzione goniometrica della variabile. */
static int node_has_trig(const Node *node) {
    if (!node) return 0;
    if (node->kind == N_CALL && node->op >= FN_SIN && node->op <= FN_COT && node_uses_letter(node->a, sign_name)) return 1;
    return node_has_trig(node->a) || node_has_trig(node->b) || node_has_trig(node->c);
}

/* 18p-14. LE FINESTRE: UNA CONDIZIONE PERIODICA RISTRETTA A UN INTERVALLO
 *
 * In 0 \le x \le 2\pi \land \sin x > \frac{1}{2} la variabile compare anche
 * fuori dalle funzioni goniometriche. Un confronto così, tra la variabile e
 * un multiplo di pi, qui si chiama finestra. Non è periodico, e la lettera
 * t = tan(u / 2) non lo vede: t è la stessa in u e in u + 2 pi. Ma la
 * tabella in t descrive bene ogni giro; da un giro all'altro cambia solo la
 * finestra. Quindi la tabella si legge un giro alla volta: nel giro numero
 * j l'angolo è u = u_0 + 2 pi j, con u_0 tra -pi (escluso) e pi (compreso).
 *
 * Una finestra x <= rho pi è u <= gamma, con gamma = g rho pi. Si scrive
 * gamma = gamma_0 + 2 pi h, con gamma_0 tra -pi (escluso) e pi (compreso):
 * h è il giro in cui cade l'estremo. Allora:
 *
 *   - in un giro j < h tutti gli angoli stanno sotto gamma, in un giro
 *     j > h tutti sopra;
 *   - nel giro h, u - gamma = u_0 - gamma_0. Sull'intervallo da -pi a pi la
 *     tangente dell'angolo metà cresce, quindi u_0 - gamma_0 ha il segno di
 *     t - tan(gamma_0 / 2); e tan(gamma_0 / 2) = sin gamma_0 / (1 + cos gamma_0)
 *     (formule di bisezione), con 1 + cos gamma_0 positivo: è il segno di
 *     t (1 + cos gamma_0) - sin gamma_0, un polinomio di primo grado in t;
 *   - se gamma_0 = pi, su ogni riga della tabella u_0 è più piccolo, e nel
 *     punto u_0 = pi, quello calcolato a parte, i due sono uguali.
 *
 * I giri da leggere vanno da quello prima del più basso h a quello dopo il
 * più alto: più in là le finestre non cambiano più, e il primo e l'ultimo
 * giro letti valgono per tutti quelli prima e per tutti quelli dopo. Un
 * insieme di soluzioni che non è vuoto in uno di questi due giri si ripete
 * all'infinito da una parte sola: non è né limitato né periodico, e il
 * programma dice che non lo sa scrivere.
 *
 * Che cosa resta fuori: un estremo che non è un multiplo razionale di pi
 * (x < 1 chiederebbe la tangente di 1/2), o lo è ma non di 15 gradi.
 */

/* Prepara la finestra f, un confronto senza funzioni goniometriche in cui
 * compare la variabile di un enunciato periodico, nel posto atom di
 * sign_atom[]. x è l'atomo della lettera t. Annota un errore se la
 * differenza dei due membri non è a x + b pi con a diverso da zero. */
static void window_prepare(const Formula *f, SignAtom *atom, int x) {
    Frac slope, turn;
    Rat cosine, sine, difference = rat_add(eval(f->left), eval(f->right), 1);
    if (failure || !trig_affine(difference, &slope, &turn) || slope.num == 0) { if (!failure) fail(SIGN_SHAPE); return; }

    /* gamma in giri di pi: whole = rest + 2 home, con rest tra -1 (escluso)
     * e 1 (compreso). home è la parte intera superiore di (whole - 1) / 2. */
    Frac whole = frac_mul(frac_neg(frac_div(turn, slope)), trig_scale);
    if (failure || whole.num > 1000000 || whole.num < -1000000 || whole.den > 1000000) { fail("una finestra con un estremo troppo grande"); return; }
    long long top = whole.num - whole.den, bottom = 2 * whole.den;
    atom->home = top >= 0 ? (top + bottom - 1) / bottom : -((-top) / bottom);
    Frac rest = frac_add(whole, frac_int(-2 * atom->home));
    int at_end = rest.num == rest.den;
    atom->window = 1;
    atom->direction = slope.num > 0 ? 1 : -1;
    atom->inner_count = 0;
    if (!windows || atom->home < window_low) window_low = atom->home;
    if (!windows || atom->home > window_high) window_high = atom->home;
    windows++;

    /* Il segno di u_0 - gamma_0: nel punto u_0 = pi, oppure sulle righe. */
    SignCase *edge = &atom->by_pattern[0];
    trig_roots_open();
    edge->first = sign_needs;
    edge->needs = 0;
    if (trig_at_pi) edge->value = sign_constant(at_end ? 0 : 1, x);
    else if (at_end) edge->value = sign_constant(-1, x);
    else if (!trig_constant(rest, &cosine, &sine)) { if (!failure) fail("una finestra con un estremo che non è un multiplo di 15 gradi"); }
    else edge->value = sign_build(rat_add(rat_mul(rat_atom(trig_letter), rat_add(rat_int(1), cosine, 0)), sine, 1), surd_count, x);
    surd_count = 0;
}

/* Prepara i confronti dell'enunciato f nella variabile di atomo x: riempie
 * sign_atom[] e sign_poly[]. Un quantificatore su un intero è una foglia: le
 * sue famiglie si preparano con family_prepare() (18p-13). In un enunciato
 * periodico un confronto senza funzioni goniometriche della variabile è una
 * finestra (18p-14). Annota un errore se un confronto non è tra espressioni
 * che la tabella tratta. */
static void sign_prepare(const Formula *f, int x) {
    if (failure) return;
    if (family_owner(f)) { family_each(f, f->a, family_prepare, &x); return; }
    if (f->kind != F_EQUAL && f->kind != F_DISTINCT && f->kind != F_LESS && f->kind != F_LESS_EQ) {
        sign_prepare(f->a, x);
        if (f->b) sign_prepare(f->b, x);
        return;
    }
    if (sign_atoms == MAX_SIGN_ATOMS) { fail("troppi confronti in un enunciato per la tabella dei segni"); return; }
    SignAtom *atom = &sign_atom[sign_atoms++];
    atom->source = f;
    atom->identity = atom->window = 0;
    if (trig_on && !node_has_trig(f->left) && !node_has_trig(f->right) && (node_uses_letter(f->left, sign_name) || node_uses_letter(f->right, sign_name))) {
        window_prepare(f, atom, x);
        return;
    }

    /* I valori assoluti e le radici; poi, per ogni scelta dei segni dei
     * valori assoluti, il confronto e i loro argomenti. */
    abs_count = surd_count = 0;
    abs_collect(f->left);
    abs_collect(f->right);

    /* In un enunciato periodico servono le radici di 2 e di 3, per i seni e
     * i coseni degli angoli costanti (18p-11). */
    for (int i = 0; i < 2 && trig_on; i++) surd_collect(trig_root[i]);
    surd_collect(f->left);
    surd_collect(f->right);
    atom->inner_count = abs_count;
    alias_collect(f->left, f);
    alias_collect(f->right, f);
    space_live = 1;
    trig_live = trig_on;
    for (unsigned pattern = 0; pattern < 1u << abs_count && !failure; pattern++) {
        sign_fraction(f->left, f->right, pattern, x, &atom->by_pattern[pattern]);
        for (int i = 0; i < abs_count && !failure; i++) sign_fraction(abs_node[i]->a, NULL, pattern, x, &atom->inner[i][pattern]);
    }
    abs_count = surd_count = space_live = trig_live = aliases = 0;
}

/* Aggiunge all'enunciato il confronto tra left e right, lo prepara per la
 * tabella e lo ritorna: serve ai gradini degli spazi, il cui confronto con
 * la lettera è un confronto nella variabile (18p-8). Del confronto si usa
 * solo il segno di left - right. */
static const Formula *sign_threshold(Node *left, Node *right, int x) {
    Formula *f = formula_node(F_EQUAL, NULL, NULL, "");
    f->left = left;
    f->right = right;
    sign_prepare(f, x);
    return f;
}

/* Ritorna un nodo che vale base elevato a power, con base razionale
 * positivo e power intero; NULL se i numeri sono troppo grandi. */
static Node *node_power(Frac base, long long power) {
    __int128 top = 1, bottom = 1;
    for (long long i = 0; i < (power < 0 ? -power : power); i++)
        if (__builtin_mul_overflow(top, (__int128)(power < 0 ? base.den : base.num), &top) || __builtin_mul_overflow(bottom, (__int128)(power < 0 ? base.num : base.den), &bottom) ||
            top > LLONG_MAX / 4 || bottom > LLONG_MAX / 4) return NULL;
    return bottom == 1 ? node_num((long long)top) : node_new(N_DIV, node_num((long long)top), node_num((long long)bottom));
}

/* Ritorna un intervallo che contiene la sola radice del polinomio element
 * tra low e high, stretta per bisezione. A ogni passo il segno del polinomio
 * nel punto medio si calcola con gli intervalli (schema di Horner): finché è
 * certo si sa da che parte sta la radice, e quando non lo è più ci si
 * ferma, con un intervallo che la contiene ancora. */
static Range root_range(const Uni *element, Wide low_end, Wide high_end) {
    double low = range_ratio(low_end.num, low_end.den).low, high = range_ratio(high_end.num, high_end.den).high;
    int at_low = uni_sign_at(element, low_end), side = 0;
    for (int round = 0; round < 80; round++) {
        double middle = (low + high) / 2;
        Range value = {0, 0}, point = {middle, middle};
        for (int i = element->degree; i >= 0; i--) value = range_add(range_mul(value, point), range_ratio(element->c[i], 1));
        if (!range_side(value, &side)) break;
        if (side == at_low) low = middle; else high = middle;
    }
    return range_wide(low, high);
}

/* Ritorna un intervallo che contiene il gradino step. */
static Range step_range(const Step *step) {
    return step->exact ? range_ratio(step->low.num, step->low.den) : root_range(&step->element, step->low, step->high);
}

/* Se r = p^k con k intero mette k in *power e ritorna 1. Per p = 0, che
 * sta per il numero e, lo è solo r = 1. */
static int power_of_prime(Wide r, long long p, long long *power) {
    __int128 rest = r.num == 1 ? r.den : r.num;
    *power = 0;
    if (r.num != 1 && r.den != 1) return 0;
    if (p == 0) return rest == 1;
    for (; rest % p == 0; rest /= p) *power += r.num == 1 ? -1 : 1;
    return rest == 1;
}

/* Se il gradino step, che non è razionale, è la radice n-esima positiva di
 * un razionale positivo q, cioè se il suo polinomio è a x^n - b, mette q in
 * *under e ritorna n; altrimenti ritorna 0. */
static long long step_pure(const Step *step, Wide *under) {
    const Uni *q = &step->element;
    for (int i = 1; i < q->degree; i++)
        if (q->c[i] != 0) return 0;
    if (q->degree < 2 || step->high.num <= 0) return 0;
    *under = wide_make(-q->c[0], q->c[q->degree]);
    return under->num > 0 ? q->degree : 0;
}

/* Scrive in text, di size byte, il gradino step in LaTeX: il razionale, o
 * la radice con i radicali se il suo polinomio ha grado due. smaller dice
 * se delle due radici è la più piccola. Annota un errore se il gradino è
 * una radice senza scrittura. */
static void step_latex(const Step *step, int smaller, char *text, size_t size) {
    text[0] = '\0';
    if (step->exact) wide_latex(step->low, text, size);
    else if (!quadratic_latex(&step->element, smaller, text, size)) fail("un esponenziale o un logaritmo uguale a un numero che non so scrivere");
}

/* 18p-8. Trova i gradini dello spazio s, le radici reali dei polinomi nella
 * sua lettera, e per ognuno prepara il confronto nella variabile che dice
 * se la lettera gli sta sopra. name e x sono la variabile, come lettera e
 * come atomo. Usa le tabelle dei punti (sign_base[], sign_point[]), che poi
 * restano libere per lo spazio successivo. */
static void space_process(int s, int name, int x) {
    Space *sp = &space[s];
    sign_points(s);
    sp->steps = 0;
    for (int i = 0; i < sign_points_count && !failure; i++) {
        Critical *point = &sign_point[i];

        /* Un esponenziale è positivo: i gradini da zero in giù non lo
         * riguardano. Una radice irrazionale va stretta finché non si sa da
         * che parte dello zero sta. */
        if (sp->kind == SPACE_EXP) {
            while (!failure && !point->exact && point->low.num <= 0 && point->high.num >= 0) point_refine(point);
            if (point->high.num <= 0) continue;
        }
        if (sp->steps == MAX_STEPS) { fail("troppe radici di un polinomio in un esponenziale o in un logaritmo"); return; }
        Step *step = &sp->step[sp->steps++];
        *step = (Step){point->exact, point->low, point->high, {0, {0}}, NULL, -1};
        if (!point->exact) step->element = sign_base[point->element];
    }

    /* I confronti, dopo aver copiato tutti i gradini: prepararli riusa le
     * tabelle dei punti. */
    for (int j = 0; j < sp->steps && !failure; j++) {
        Step *step = &sp->step[j];
        char value[64], text[96];
        long long power;
        Wide pure;
        int smaller = j + 1 < sp->steps && !step->exact && !sp->step[j + 1].exact && uni_equal(&step->element, &sp->step[j + 1].element);
        Node *variable = node_new(N_VAR, NULL, NULL);
        variable->name = name;

        long long index = step->exact ? 1 : step_pure(step, &pure);
        if (sp->kind == SPACE_EXP && index && power_of_prime(step->exact ? step->low : pure, sp->prime, &power)) {
            /* p^(x/L) = p^(k/n): x = L k / n, un razionale. Capita con n > 1
             * quando il gradino è la radice n-esima di una potenza di p. */
            Frac at = frac_make((__int128)sp->scale * power, index);
            step->above = sign_threshold(variable, at.den == 1 ? node_num(at.num) : node_new(N_DIV, node_num(at.num), node_num(at.den)), x);
        } else if (sp->kind == SPACE_EXP) {
            /* x = L log_p r, un numero che non è radice di un polinomio. */
            Range number = range_mul(range_ratio(sp->scale, 1), range_ln(step_range(step)));
            if (sp->prime) number = range_div(number, range_ln(range_ratio(sp->prime, 1)));
            step_latex(step, smaller, value, sizeof value);
            /* L'argomento di una funzione senza parentesi è un solo fattore
             * (capitolo 9): \log_{5} 2\sqrt{15} si rileggerebbe come
             * (\log_{5} 2) \sqrt{15}. Senza parentesi resta solo un intero. */
            int wrap = value[strspn(value, "0123456789")] != '\0';
            if (sp->prime) snprintf(text, sizeof text, "%.0lld\\log_{%lld} %s%s%s", sp->scale == 1 ? 0 : sp->scale, sp->prime, wrap ? "\\left(" : "", value, wrap ? "\\right)" : "");
            else snprintf(text, sizeof text, "%.0lld\\ln %s%s%s", sp->scale == 1 ? 0 : sp->scale, wrap ? "\\left(" : "", value, wrap ? "\\right)" : "");

            /* Lo stesso numero come frazione esatta, quando il gradino è un
             * razionale: L ln r / ln p. */
            Rat exact = rat_int(0);
            int plain = step->exact && step->low.num < LLONG_MAX / 4 && step->low.den < LLONG_MAX / 4 && !failure;
            if (plain) {
                exact = rat_mul(rat_int(sp->scale), logarithm_of_positive(rat_frac((Frac){(long long)step->low.num, (long long)step->low.den})));
                if (sp->prime) exact = rat_div(exact, logarithm_of_positive(rat_int(sp->prime)));
            }
            if (!failure) step->kappa = sign_column_kappa(number, text, plain ? &exact : NULL);
        } else if (!step->exact || (!sp->natural && (step->low.den > 2 || (step->low.den == 2 && sp->base.den != 1)))) {
            fail("un logaritmo uguale a un numero irrazionale, o una potenza della base che non so scrivere");
        } else if (sp->natural && step->low.num != 0) {
            /* ln f = r con r diverso da zero: f = e^r, che non è radice di un
             * polinomio. Lo si tratta quando f = a x + c con a positivo:
             * allora x = (e^r - c) / a è un punto della tabella. */
            Frac slope, shift;
            space_live = 1;
            int affine = rat_affine_in(eval(sp->argument), x, &slope, &shift) && slope.num > 0;
            space_live = 0;
            if (!affine) { fail("un logaritmo naturale uguale a un numero diverso da zero è trattato solo per un argomento di primo grado, crescente"); return; }
            char power_text[48] = "e", top[96];
            if (step->low.den != 1) snprintf(power_text, sizeof power_text, "e^{%s\\frac{%lld}{%lld}}", step->low.num < 0 ? "-" : "", (long long)(step->low.num < 0 ? -step->low.num : step->low.num), (long long)step->low.den);
            else if (step->low.num != 1) snprintf(power_text, sizeof power_text, "e^{%lld}", (long long)step->low.num);
            if (shift.num == 0) snprintf(top, sizeof top, "%s", power_text);
            else if (shift.den == 1) snprintf(top, sizeof top, "%s %c %lld", power_text, shift.num < 0 ? '+' : '-', (long long)(shift.num < 0 ? -shift.num : shift.num));
            else snprintf(top, sizeof top, "%s %c \\frac{%lld}{%lld}", power_text, shift.num < 0 ? '+' : '-', (long long)(shift.num < 0 ? -shift.num : shift.num), (long long)shift.den);
            if (slope.num == slope.den) snprintf(text, sizeof text, "%s", top);
            else if (slope.den == 1) snprintf(text, sizeof text, "\\frac{%s}{%lld}", top, (long long)slope.num);
            else snprintf(text, sizeof text, "\\frac{%lld\\left(%s\\right)}{%lld}", (long long)slope.den, top, (long long)slope.num);
            Range number = range_div(range_sub(range_exp(range_ratio(step->low.num, step->low.den)), range_ratio(shift.num, shift.den)), range_ratio(slope.num, slope.den));

            /* Come frazione esatta: (e^r - c) / a, con e un atomo. */
            Rat exact = rat_div(rat_add((Rat){poly_term((Term){num_int(1), mono_atom(atom_var('e'), (Frac){(long long)step->low.num, (long long)step->low.den})}), poly_const(num_int(1))}, rat_frac(shift), 1), rat_frac(slope));
            step->kappa = sign_column_kappa(number, text, &exact);
        } else {
            /* log_b f = k / m: f = b^(k/m), con m = 1 oppure 2. Con m = 2 è
             * b^((k - 1)/2) per la radice di b. */
            long long k = (long long)step->low.num, half = step->low.den == 2 ? (k - 1) / 2 - ((k - 1) % 2 < 0) : k;
            Node *constant = sp->natural ? node_num(1) : node_power(sp->base, half);
            if (!constant) { fail(SIGN_LIMIT); return; }
            if (step->low.den == 2) constant = node_new(N_MUL, constant, node_call(FN_ROOT, node_num(sp->base.num), node_num(2)));
            step->above = sign_threshold((Node *)sp->argument, constant, x);
        }
    }
}

/* Ritorna il segno dell'espressione c dove i polinomi hanno i segni di
 * sign[]; mette 0 in *defined, che chi chiama ha messo a 1, se lì non è
 * definita. */
static int sign_of_case(const SignCase *c, const int *sign, int *defined) {
    for (int i = 0; i < c->needs; i++) {
        int value = sign_value(sign_need[c->first + i].node, sign, defined), strict = sign_need[c->first + i].strict;
        if (strict == 1 ? value == 0 : strict == 2 ? value <= 0 : value < 0) *defined = 0;
    }
    return sign_value(c->value, sign, defined);
}

/* Ritorna 1 se l'angolo angle è un multiplo di 2 pi dove i polinomi hanno i
 * segni di sign[]: il seno è zero e il coseno positivo. */
static int family_at_zero(const FamilyAngle *angle, const int *sign) {
    int defined = 1;
    return sign_of_case(&angle->sine, sign, &defined) == 0 && sign_of_case(&angle->cosine, sign, &defined) > 0;
}

/* Ritorna 1 se il quantificatore su un intero f è vero dove i polinomi
 * hanno i segni di sign[]: per "esiste" se la variabile sta in una delle
 * sue famiglie, per "per ogni k, x diverso da ..." se non sta in nessuna.
 * Le regole sono quelle scritte in testa a 18p-13. */
static int family_truth(const Formula *f, const int *sign) {
    int any = 0;
    for (int i = 0; i < family_leaves; i++) {
        const FamilyLeaf *leaf = &family_leaf[i];
        int defined = 1, in = family_at_zero(&leaf->below, sign);
        if (leaf->owner != f) continue;
        if (!leaf->family.single) {
            int low = sign_of_case(&leaf->below.sine, sign, &defined), high = sign_of_case(&leaf->above.sine, sign, &defined);
            if (leaf->full) in = !in || leaf->family.low_closed || leaf->family.high_closed;
            else in = (in && leaf->family.low_closed) || (family_at_zero(&leaf->above, sign) && leaf->family.high_closed) ||
                      (leaf->wide ? low > 0 || high > 0 : low > 0 && high > 0);
            for (int h = 0; h < leaf->family.holes; h++)
                if (leaf->hole_counts[h] && family_at_zero(&leaf->hole[h], sign)) in = 0;
        }
        any |= in;
    }
    return f->kind == F_EXISTS ? any : !any;
}

/* Ritorna il segno di left - right per il confronto f dove i polinomi di
 * sign_poly[] hanno i segni di sign[]; mette 0 in *defined, che chi chiama ha
 * messo a 1, se lì uno dei due membri non è definito.
 *
 * Prima la scelta dei segni dei valori assoluti, da quelli più interni: uno
 * ha il segno cambiato dove il suo argomento è negativo. Poi il segno della
 * differenza in quella scelta. */
static int sign_compare(const Formula *f, const int *sign, int *defined) {
    const SignAtom *atom = NULL;
    unsigned pattern = 0;
    for (int i = 0; i < sign_atoms; i++)
        if (sign_atom[i].source == f) atom = &sign_atom[i];
    if (!atom) { *defined = 0; return 0; }

    /* 18p-14. Una finestra: sotto o sopra il suo estremo in tutti i giri
     * tranne quello in cui l'estremo cade. */
    if (atom->window) {
        int side = window_turn < atom->home ? -1 : window_turn > atom->home ? 1 : sign_of_case(&atom->by_pattern[0], sign, defined);
        return side * atom->direction;
    }
    for (int i = 0; i < atom->inner_count; i++)
        if (sign_of_case(&atom->inner[i][pattern], sign, defined) < 0) pattern |= 1u << i;
    return sign_of_case(&atom->by_pattern[pattern], sign, defined);
}

/* Ritorna 1 se l'enunciato f, senza quantificatori, è vero dove i polinomi
 * di sign_poly[] hanno i segni di sign[] (-1, 0 o 1), altrimenti 0. */
static int sign_truth(const Formula *f, const int *sign) {
    if (family_owner(f)) return family_truth(f, sign);
    switch (f->kind) {
    case F_AND:     return sign_truth(f->a, sign) && sign_truth(f->b, sign);
    case F_OR:      return sign_truth(f->a, sign) || sign_truth(f->b, sign);
    case F_IMPLIES: return !sign_truth(f->a, sign) || sign_truth(f->b, sign);
    case F_IFF:     return sign_truth(f->a, sign) == sign_truth(f->b, sign);
    case F_NOT:     return !sign_truth(f->a, sign);
    default:        break;
    }

    /* Un confronto: definito, e con il segno giusto. */
    int defined = 1, value = sign_compare(f, sign, &defined);
    if (!defined) return 0;
    switch (f->kind) {
    case F_EQUAL:    return value == 0;
    case F_DISTINCT: return value != 0;
    case F_LESS:     return value < 0;
    default:         return value <= 0;
    }
}

/* =============================================================================
 * 18.12 IL CONTROLLO CON I NUMERI
 * ============================================================================
 *
 * Il controllo indipendente delle righe della tabella (18p-2), fatto senza
 * polinomi in una variabile e senza radici: il valore di una riga si
 * sostituisce nell'enunciato e si calcola, con il conto esatto quando è
 * razionale (sign_holds_at()), con gli intervalli del capitolo 24 quando non
 * lo è o l'enunciato è periodico (range_truth()). Ciò che dicono i due conti
 * è solo "vale", "non vale" o "non so": il segno di un numero con radici si
 * stringe tra due razionali (number_sign()), un'uguaglianza vista con gli
 * intervalli si può solo trovare compatibile, a meno che i due membri siano
 * la stessa funzione (formula_identity()). Chi ricontrolla usa
 * table_agrees().
 */

/* Mette in *low e *high due razionali tra cui sta il valore di p, che deve
 * essere un numero fatto di razionali e di radici quadrate di interi: una
 * somma di termini q sqrt(m). Ogni radice è presa tra k / 2^bits e
 * (k + 1) / 2^bits, con k la parte intera di sqrt(m) 2^bits. Ritorna 0 se p
 * non ha questa forma o se i numeri escono dai limiti. */
static int number_bounds(Poly p, int bits, Wide *low, Wide *high) {
    *low = *high = (Wide){0, 1};
    for (int t = 0; t < p.count && !failure; t++) {
        const Term *term = &p.term[t];
        if (term->coef.im.num != 0) return 0;

        /* Il termine: un razionale per la radice di un intero. Un primo con
         * esponente e = w + 1/2 dà p^w fuori dalla radice e p dentro. */
        Wide rational = {term->coef.re.num, term->coef.re.den};
        __int128 under = 1;
        for (int f = 0; f < term->mono.count && !failure; f++) {
            const Atom *atom = &atoms[term->mono.factor[f].atom];
            Frac e = term->mono.factor[f].exp;
            if (atom->kind != ATOM_POW || atom->base != BASE_PRIME || atom->exponent.count != 0 || e.den > 2) return 0;
            long long whole = frac_floor(e);
            for (long long i = 0; i < (whole < 0 ? -whole : whole) && !failure; i++)
                rational = wide_mul(rational, whole < 0 ? (Wide){1, atom->id} : (Wide){atom->id, 1});
            if (e.den == 2) under *= atom->id;
            if (under >= (__int128)1 << 40) return 0;
        }
        if (failure) return 0;

        /* La radice tra due razionali vicini; se è esatta, i due coincidono.
         * Con un razionale negativo davanti i due limiti si scambiano. */
        __int128 scaled = under << (2 * bits), root = wide_isqrt(scaled), unit = (__int128)1 << bits;
        Wide below = wide_mul(rational, wide_make(root, unit)), above = wide_mul(rational, wide_make(root + (root * root != scaled), unit));
        *low = wide_add(*low, rational.num < 0 ? above : below);
        *high = wide_add(*high, rational.num < 0 ? below : above);
    }
    return !failure;
}

/* Mette in *side il segno del numero r e ritorna 1; ritorna 0 se non riesce
 * a stabilirlo. r può contenere radici quadrate di interi.
 *
 * Il segno di un numero con radici si trova stringendolo tra due razionali:
 * prima o poi i due hanno lo stesso segno, a meno che il numero sia zero. Lo
 * zero va quindi riconosciuto prima, con il test del capitolo 12, che per le
 * radici di interi è esatto. La precisione cresce fino a 40 cifre binarie;
 * se non basta, la risposta è "non so". È un conto diverso da quello della
 * tabella dei segni, che non approssima mai: per questo vale come controllo. */
static int number_sign(Rat r, int *side) {
    Num value;

    /* Un numeratore senza termini è zero, qualunque cosa ci sia sotto: è
     * così che si riconosce lo zero di un'espressione con logaritmi, dove il
     * denominatore non si semplifica. */
    if (r.num.count == 0) { *side = 0; return 1; }
    if (rat_number(r, &value)) {
        *side = (value.re.num > 0) - (value.re.num < 0);
        return value.im.num == 0;
    }
    for (int bits = 8; bits <= 40 && !failure; bits += 8) {
        Wide low[2], high[2];
        if (!number_bounds(r.num, bits, &low[0], &high[0]) || !number_bounds(r.den, bits, &low[1], &high[1])) return 0;
        int above = low[0].num > 0 ? 1 : high[0].num < 0 ? -1 : 0, below = low[1].num > 0 ? 1 : high[1].num < 0 ? -1 : 0;
        if (above && below) { *side = above * below; return 1; }

        /* Dopo il primo giro si sa che r è un numero di questa forma, e si
         * può chiedere se è zero. */
        if (bits == 8 && poly_vanishes(r.num)) { *side = 0; return 1; }
    }
    return 0;
}

/* Ritorna 1 se le condizioni di esistenza annotate in conditions[] valgono
 * tutte di sicuro; 0 se una di sicuro non vale, e allora mette 1 in
 * *broken; 0 anche se di una non si riesce a dire. Ogni condizione riguarda
 * un prodotto di numeri: il segno di ogni fattore lo dà number_sign(),
 * esatto, oppure il suo intervallo. */
static int conditions_hold(int *broken) {
    for (int i = 0; i < condition_count; i++) {
        int product = 1;
        for (int j = 0; j < conditions[i].count; j++) {
            int side = 0;
            Rat factor = {conditions[i].factor[j], poly_const(num_int(1))};
            if (!number_sign(factor, &side) && !range_side(poly_range(factor.num), &side)) { failure = NULL; return 0; }
            product *= side;
        }
        failure = NULL;
        if (conditions[i].kind == NEVER_ZERO ? product == 0 : conditions[i].kind == ALWAYS_POSITIVE ? product <= 0 : product < 0) { *broken = 1; return 0; }
    }
    return 1;
}

/* Ritorna 1 se la condizione f, senza quantificatori, vale quando la
 * variabile di nome name è il razionale value, calcolando ogni confronto
 * direttamente con i numeri: un confronto in cui un'espressione non è
 * definita non vale. È il controllo indipendente della tabella dei segni:
 * non usa né polinomi in una variabile né radici.
 *
 * Chi chiama azzera `failure` prima. Se un conto si ferma a un limite del
 * programma (numeri troppo grandi, un segno che non si riesce a stabilire)
 * l'errore resta annotato e la risposta non vuol dire nulla: chi chiama lo
 * deve guardare. */
static int sign_holds_at(const Formula *f, int name, Frac value) {
    /* Un errore già annotato va lasciato dov'è. Prima ogni confronto lo
     * azzerava: se il primo membro di un "se e solo se" usciva dai limiti e
     * il secondo no, l'errore spariva e la riga, invece che non controllata,
     * risultava in disaccordo con la tabella. */
    if (failure) return 0;
    switch (f->kind) {
    case F_AND:     return sign_holds_at(f->a, name, value) && sign_holds_at(f->b, name, value);
    case F_OR:      return sign_holds_at(f->a, name, value) || sign_holds_at(f->b, name, value);
    case F_IMPLIES: return !sign_holds_at(f->a, name, value) || sign_holds_at(f->b, name, value);
    case F_IFF:     return sign_holds_at(f->a, name, value) == sign_holds_at(f->b, name, value);
    case F_NOT:     return !sign_holds_at(f->a, name, value);
    default:        break;
    }
    /* Prima con gli intervalli (capitolo 24), che dicono due cose certe:
     * se un membro lì non ha un valore, e allora il confronto non vale; e
     * se tutti e due ce l'hanno. */
    int nowhere = 0, side = 0;
    Range point = range_ratio(value.num, value.den);
    Range left = node_range(f->left, name, point, &nowhere), right = node_range(f->right, name, point, &nowhere);
    if (nowhere) return 0;
    int certain = range_known(left) && range_known(right);

    /* Poi il conto esatto, che riconosce l'uguaglianza. Con i soli numeri
     * razionali e le loro radici dice da sé quando un'espressione non è
     * definita. Con logaritmi e potenze no: annota le condizioni invece di
     * controllarle. Gli si crede se gli intervalli hanno già stabilito che i
     * due membri hanno un valore, oppure se le condizioni annotate, che sono
     * numeri, risultano tutte vere (conditions_hold()). */
    Scratch mark = scratch_mark();
    undefined = 0;
    env_count = 0;
    env_push(name, rat_frac(value));
    condition_count = conditions_lost = 0;
    conditions_on = 1;
    Rat d = rat_add(eval(f->left), eval(f->right), 1);
    conditions_on = 0;
    env_count = 0;
    int absent = failure && undefined, broken = 0;
    int trusted = !failure && !conditions_lost && (certain || conditions_hold(&broken));
    int known = trusted && number_sign(d, &side);
    scratch_drop(mark);
    if (absent || broken) { failure = NULL; return 0; }

    /* Se il conto esatto non decide, il segno certo della differenza; e due
     * membri scritti allo stesso modo, che hanno un valore, sono uguali. Se
     * nemmeno così si decide resta un errore, che chi chiama controlla. */
    if (!known) {
        failure = NULL;
        if (certain && range_side(range_sub(left, right), &side)) known = 1;
        else if (certain && node_equal(f->left, f->right)) known = 1, side = 0;
        else fail("non riesco a stabilire il segno di un numero dell'enunciato");
    }
    if (!known) return 0;
    return f->kind == F_EQUAL ? side == 0 : f->kind == F_DISTINCT ? side != 0 : f->kind == F_LESS ? side < 0 : side <= 0;
}

/* Ritorna 1 se i due membri del confronto f sono la stessa funzione: se la
 * loro differenza, calcolata con la variabile come lettera e con il conto
 * esatto del motore (per seni e coseni le formule di Eulero, capitolo 11), è
 * zero per il test di annullamento del capitolo 12. Un "sì" è una
 * dimostrazione dell'identità, fatta per una strada che non passa dalla
 * tabella dei segni: per questo vale come suo controllo. Il risultato si
 * ricorda nel confronto preparato, se c'è. */
static int formula_identity(const Formula *f) {
    SignAtom *atom = NULL;
    for (int i = 0; i < sign_atoms; i++)
        if (sign_atom[i].source == f) atom = &sign_atom[i];
    if (atom && atom->identity) return atom->identity > 0;
    Scratch mark = scratch_mark();
    const char *was = failure;
    int live = trig_live, listed = conditions_on, bound = env_count;
    failure = NULL;
    trig_live = conditions_on = env_count = 0;
    Rat gap = rat_add(eval(f->left), eval(f->right), 1);
    int same = !failure && (gap.num.count == 0 || poly_vanishes(gap.num));
    failure = was;
    trig_live = live;
    conditions_on = listed;
    env_count = bound;
    scratch_drop(mark);
    if (atom) atom->identity = same ? 1 : -1;
    return same;
}

/* Ciò che serve a provare con i numeri le famiglie di un quantificatore su
 * un intero: la variabile, il suo valore, se un'uguaglianza quasi certa si
 * può prendere per buona, e il risultato che si accumula: 1 se la variabile
 * sta di sicuro in una famiglia, -1 se di una non si sa, 0 altrimenti. */
typedef struct {
    int name;
    Range x;
    int tolerant;
    int seen;
} FamilyCheck;

/* Ritorna la distanza di v dall'intero più vicino, come intervallo. */
static Range range_from_integer(Range v) {
    double middle = (v.low + v.high) / 2, nearest = (double)(long long)(middle + (middle < 0 ? -0.5 : 0.5));
    return range_known(v) && middle < 1e15 && middle > -1e15 ? range_sub(v, (Range){nearest, nearest}) : range_none();
}

/* Per range_truth: prova con i numeri se la variabile sta nella famiglia
 * del pezzo d, e aggiorna il risultato in context (un FamilyCheck). Il
 * periodo T e gli estremi per k = 0 si calcolano dalle espressioni; poi si
 * cerca il k giusto tra i tre più vicini a (x - low) / T. */
static void family_range(const Formula *owner, const Formula *d, void *context) {
    FamilyCheck *check = context;
    Family family;
    Range zero = {0, 0}, one = {1, 1};
    int none = 0, side = 0, found = 0;
    if (check->seen == 1) return;
    if (!family_read(d, check->name, owner->variable, owner->kind == F_FORALL, &family)) { check->seen = -1; return; }
    Range low = node_range(family.low, family.k, zero, &none), period = range_sub(node_range(family.low, family.k, one, &none), low);
    if (!range_side(period, &side)) { check->seen = -1; return; }
    if (side < 0) period = range_neg(period);
    Range turns = range_div(range_sub(check->x, low), period);
    if (!range_known(turns)) { check->seen = -1; return; }

    /* Un punto per ogni k: (x - low) / T deve essere un intero. */
    if (family.single) {
        Range gap = range_from_integer(turns);
        if (range_side(gap, &side)) return;
        check->seen = check->tolerant && range_known(gap) && gap.high - gap.low < 1e-6 ? 1 : -1;
        return;
    }

    /* Un intervallo per ogni k. */
    Range high = node_range(family.high, family.k, zero, &none);
    double middle = (turns.low + turns.high) / 2, base = (double)(long long)middle - (middle < 0);
    for (int step = -1; step <= 1 && !found; step++) {
        Range shift = range_mul((Range){base + step, base + step}, period);
        Range left = range_sub(check->x, range_add(low, shift)), right = range_sub(range_add(high, shift), check->x);
        int left_side = 0, right_side = 0, left_known = range_side(left, &left_side), right_known = range_side(right, &right_side);
        if ((left_known && left_side < 0) || (right_known && right_side < 0)) continue;
        if (!range_known(left) || !range_known(right)) { check->seen = -1; return; }

        /* Dentro, oppure su un estremo: lì conta se l'estremo è compreso, e
         * lo si può dire solo se è permesso prendere per zero una
         * differenza stretta attorno allo zero. */
        if ((!left_known || !right_known) && (!check->tolerant || left.high - left.low > 1e-6 || right.high - right.low > 1e-6)) { check->seen = -1; return; }

        /* Su un estremo escluso il valore non sta in questo intervallo, ma
         * può stare nel successivo: capita quando l'intervallo è lungo un
         * periodo intero, e l'estremo di uno è anche quello dell'altro. Una
         * versione che qui si fermava dava per escluso un punto compreso. */
        found = (left_known || family.low_closed) && (right_known || family.high_closed);
    }
    if (!found) return;

    /* I punti tolti: x - hole non deve essere un multiplo di T, per i punti
     * tolti che stanno nell'intervallo dello stesso k. */
    for (int h = 0; h < family.holes; h++) {
        Range hole = node_range(family.hole[h], family.k, zero, &none);
        int after = range_side(range_sub(hole, low), &side) ? side : 0, before = range_side(range_sub(high, hole), &side) ? side : 0;
        if (after == 0 || before == 0) { check->seen = -1; return; }
        if (after < 0 || before < 0) continue;
        Range gap = range_from_integer(range_div(range_sub(check->x, hole), period));
        if (range_side(gap, &side)) continue;
        if (!check->tolerant || !range_known(gap) || gap.high - gap.low > 1e-6) { check->seen = -1; return; }
        return;
    }
    check->seen = 1;
}

/* La logica a tre valori di Kleene, con 1 vero, 0 falso e -1 "non si sa":
 * ritorna il valore del connettivo kind (F_NOT, F_AND, F_OR, F_IMPLIES o
 * F_IFF) sulle parti a e b, e b non conta per F_NOT. Un "non so" pesa solo
 * dove potrebbe cambiare il risultato: "falso e non so" è falso, "vero o
 * non so" è vero, "vero e non so" è non so. L'implicazione è "non a, oppure
 * b"; l'equivalenza si sa solo se si sanno tutte e due le parti. È la logica
 * giusta per un conto che a volte non sa rispondere: ciò che dice di sicuro
 * resta sicuro, qualunque sia la risposta che manca. */
static int truth_join(FormulaKind kind, int a, int b) {
    if (kind == F_NOT) return a < 0 ? -1 : !a;
    if (kind == F_IMPLIES && a >= 0) a = !a;
    if (kind == F_AND) return a == 0 || b == 0 ? 0 : a < 0 || b < 0 ? -1 : 1;
    if (kind == F_IFF) return a < 0 || b < 0 ? -1 : a == b;
    return a == 1 || b == 1 ? 1 : a < 0 || b < 0 ? -1 : 0;
}

/* Ritorna 1 se la condizione f, senza quantificatori, vale di sicuro quando
 * la variabile name sta nell'intervallo x, 0 se di sicuro non vale, -1 se
 * gli intervalli non bastano a dirlo (capitolo 24). I connettivi seguono la
 * logica a tre valori (truth_join()): "falso e non so" è falso, "vero e non
 * so" è non so.
 *
 * Un confronto è falso di sicuro dove un suo membro di sicuro non ha un
 * valore; è deciso quando la differenza dei membri ha un segno certo. Se la
 * differenza contiene lo zero di solito non si sa. Con tolerant diverso da
 * zero, e una differenza stretta attorno allo zero, la si prende per zero:
 * serve nei punti in cui la tabella afferma un'uguaglianza, che con gli
 * intervalli si può trovare compatibile ma non dimostrare. */
static int range_truth(const Formula *f, int name, Range x, int tolerant) {
    int nowhere = 0, side = 0;
    if (family_owner(f)) {
        FamilyCheck check = {name, x, tolerant, 0};
        family_each(f, f->a, family_range, &check);
        return check.seen < 0 ? -1 : f->kind == F_EXISTS ? check.seen : !check.seen;
    }
    if (f->kind == F_AND || f->kind == F_OR || f->kind == F_IMPLIES || f->kind == F_IFF || f->kind == F_NOT) {
        int a = range_truth(f->a, name, x, tolerant), b = f->kind == F_NOT ? -1 : range_truth(f->b, name, x, tolerant);
        return truth_join(f->kind, a, b);
    }
    Range left = node_range(f->left, name, x, &nowhere), right = node_range(f->right, name, x, &nowhere), gap = range_sub(left, right);
    if (nowhere) return 0;
    if (!range_known(gap)) return -1;

    /* Una differenza che contiene lo zero: è zero di sicuro se i due membri
     * sono la stessa funzione, cosa che per le identità goniometriche il
     * conto esatto con le formule di Eulero sa riconoscere
     * (formula_identity()); altrimenti la si prende per zero solo se è
     * permesso, ed è stretta. */
    if (!range_side(gap, &side) && !formula_identity(f) && (!tolerant || gap.high - gap.low > 1e-6)) return -1;
    return f->kind == F_EQUAL ? side == 0 : f->kind == F_DISTINCT ? side != 0 : f->kind == F_LESS ? side < 0 : side <= 0;
}

/* Il controllo indipendente della tabella in un valore della sua lettera:
 * ritorna 1 se il conto con i numeri dà per la condizione body la stessa
 * verità truth della tabella, 0 se ne dà una diversa, -1 se non riesce a
 * dirlo. Il valore è il razionale at; oppure, se point non è NULL, il punto
 * point, che può non essere razionale.
 *
 * Tre casi. In un enunciato periodico la lettera è t, e la variabile vale
 * (2 / g) arctan t: un numero non razionale, che si conosce con un
 * intervallo. Un punto non razionale si conosce anche lui con un
 * intervallo. Negli altri casi il valore si sostituisce esattamente
 * (sign_holds_at()). */
static int table_agrees(const Formula *body, int name, Wide at, const Critical *point, int truth) {
    if (!trig_on && !point) {
        if (at.num >= COEF_LIMIT || at.num <= -COEF_LIMIT || at.den >= COEF_LIMIT) return -1;
        failure = NULL;
        int direct = sign_holds_at(body, name, (Frac){(long long)at.num, (long long)at.den});
        int known = failure == NULL;
        failure = NULL;
        return known ? direct == truth : -1;
    }
    Range value = range_ratio(at.num, at.den);
    if (point && point->kappa >= 0) value = kappa[point->kappa].value;
    else if (point && !point->exact) value = root_range(&sign_base[point->element], point->low, point->high);
    /* In un enunciato periodico il valore della variabile nel giro in corso:
     * (2 arctan t + 2 pi j) / g. */
    if (trig_on) value = range_div(range_add(range_mul(range_ratio(2, 1), range_atan(value)), range_mul(range_ratio(2 * window_turn, 1), range_pi())), range_ratio(trig_scale.num, trig_scale.den));
    /* In un enunciato periodico un'identità che il conto esatto non
     * riconosce (formula_identity()) si può solo trovare compatibile: lì la
     * conferma è una verifica con i numeri, non una seconda dimostrazione. */
    int seen = range_truth(body, name, value, point != NULL || trig_on);
    return seen < 0 ? -1 : seen == truth;
}

/* =============================================================================
 * 18.13 LE RIGHE DELLA TABELLA E LE SOLUZIONI
 * ============================================================================
 *
 * Con i punti in ordine (18.8) e i confronti preparati (18.11), la tabella:
 * una riga per ogni punto e per ogni intervallo tra due punti, con i segni
 * di tutti i polinomi in un valore della riga, ricontrollata con i numeri
 * (18.12) prima di essere creduta (sign_table()). Poi ciò che se ne legge e
 * si scrive: le righe nella dimostrazione (put_row()), e le soluzioni di una
 * condizione, i tratti di righe consecutive in cui vale (sign_solution()),
 * rilette dal testo prima di essere consegnate (solution_reread()).
 */

/* Una riga della tabella dei segni (18p-2): un punto, oppure l'intervallo tra
 * due punti consecutivi. La riga 2 i è l'intervallo prima del punto i, la
 * riga 2 i + 1 il punto i; l'ultima è l'intervallo dopo l'ultimo punto. */
typedef struct {
    Wide sample;             /* il valore della variabile in cui si calcolano i
                                segni: il punto, o un razionale dell'intervallo;
                                per una radice irrazionale il punto medio
                                dell'intervallo che la isola (18p-5) */
    int sign[MAX_CRITICAL];  /* il segno (-1, 0, 1) di ogni polinomio di sign_poly[] */
    int inside;              /* 1 se la riga sta nell'insieme su cui varia la variabile */
    int rational;            /* 1 se sample è proprio il valore della riga: è 0
                                solo nelle radici irrazionali */
    int must;                /* 1 se la riga va confermata perché l'enunciato si
                                possa decidere: le righe con un valore razionale,
                                e in un enunciato periodico gli intervalli */
    int confirmed;           /* 1 se il conto con i numeri in sample ha dato la
                                stessa verità della tabella */
} SignRow;

/* Le righe della tabella appena riempita da sign_table(): valgono fino alla
 * tabella successiva, e le leggono la dimostrazione, le soluzioni, il
 * grafico, il certificato e lo studio di funzione (capitolo 27). */
static SignRow sign_row[2 * MAX_POINTS + 1];
static int sign_rows;

/* Mette in out[], che ha 8 posti, altri valori della riga row, che è un
 * intervallo, oltre a quello scelto in sign_row[row].sample; ritorna quanti.
 *
 * Un punto solo conferma che la riga è giusta lì, non che l'intervallo sia
 * tutto di un segno: se alla tabella mancasse un punto, perché una regola ha
 * dato per costante un segno che non lo è, nel punto scelto potrebbe non
 * vedersi. È successo con x + 2^x, dato per positivo ovunque e confermato in
 * x = 0. Per questo chi ricontrolla una riga la prova anche in due punti tra
 * il valore scelto e ogni estremo, e dalla parte in cui l'estremo non c'è
 * in quattro punti via via più lontani. */
static int row_points(int row, Wide *out) {
    static const long long reach[4] = {1, 3, 10, 40};
    const Critical *before = row >= 2 ? &sign_point[row / 2 - 1] : NULL, *after = row / 2 < sign_points_count ? &sign_point[row / 2] : NULL;
    Wide sample = sign_row[row].sample;
    int count = 0;
    for (int side = 0; side < 2; side++) {
        const Critical *end = side ? after : before;
        if (end) {
            Wide edge = side ? end->low : end->high, near = side ? wide_between(sample, edge) : wide_between(edge, sample);
            out[count++] = near;
            out[count++] = side ? wide_between(near, edge) : wide_between(edge, near);
        } else {
            for (int i = 0; i < 4; i++) out[count++] = wide_add(sample, (Wide){side ? reach[i] : -reach[i], 1});
        }
    }
    if (failure) { failure = NULL; return 0; }
    return count;
}

/* Ritorna il razionale in cui si calcola una riga che è un intervallo, tra
 * i punti before e after che la chiudono (NULL se da quella parte non c'è un
 * punto): un razionale semplice tra i due (wide_between()), oppure l'intero
 * che sta due unità oltre l'unico punto che c'è, oppure 0 se non ce n'è
 * nessuno. Lo stesso valore sceglie la regola 18t per le celle della retta
 * del parametro, che sono righe di una tabella nella sua lettera. */
static Wide interval_sample(const Critical *before, const Critical *after) {
    if (before && after) return wide_between(before->high, after->low);
    if (after) return (Wide){after->low.num / after->low.den - 2, 1};
    if (before) return (Wide){before->high.num / before->high.den + 2, 1};
    return (Wide){0, 1};
}

/* Mette tra le colonne della tabella i polinomi x - a che delimitano set,
 * cioè il suo estremo inferiore e i suoi punti tolti, e ritorna il posto in
 * sign_poly[] del primo (-1 se set non ha un estremo); i posti dei punti
 * tolti vanno in hole_column[]. Una colonna che c'è già si ritrova
 * (sign_column()): così il certificato (18p-15) usa le colonne della tabella
 * che ha deciso. */
static int set_columns(const NumberSet *set, int *hole_column) {
    int floor_column = set->bounded ? sign_column((Uni){1, {-(__int128)set->low, 1}}) : -1;
    for (int i = 0; i < set->holes; i++) hole_column[i] = sign_column((Uni){1, {-(__int128)set->hole[i].num, set->hole[i].den}});
    return floor_column;
}

/* Ritorna 1 se i segni sign[] di una riga dicono che la riga non sta sotto
 * l'estremo inferiore di set, né su un suo punto tolto: le colonne di quei
 * polinomi sono quelle di set_columns(). */
static int row_in_set(const int *sign, const NumberSet *set, int floor_column, const int *hole_column) {
    if (floor_column >= 0 && (sign[floor_column] < 0 || (sign[floor_column] == 0 && set->strict))) return 0;
    for (int i = 0; i < set->holes; i++)
        if (sign[hole_column[i]] == 0) return 0;
    return 1;
}

/* 18p-2. Riempie sign_row[]: per ogni riga il valore, i segni dei polinomi,
 * se sta in set, e l'esito del controllo indipendente della condizione body
 * nella variabile name. floor_column e hole_column[] sono i posti, in
 * sign_poly[], dei polinomi x - a che delimitano set: il suo estremo
 * inferiore (-1 se non c'è) e i punti tolti.
 *
 * Il controllo indipendente si fa dove il valore è un razionale: lo si
 * sostituisce nell'enunciato e si fa il conto con i numeri. Se il conto esce
 * dai limiti la riga resta non confermata. Un intervallo viene poi provato
 * in altri punti, per accorgersi di un punto che alla tabella mancasse.
 * Nelle radici irrazionali il controllo non si può fare: lì la tabella
 * poggia solo su 18p-5.
 *
 * Ritorna 0 se in una riga il conto con i numeri smentisce la tabella: è un
 * errore del programma, e nessuna riga va più creduta. */
static int sign_table(const Formula *body, int name, const NumberSet *set, int floor_column, const int *hole_column) {
    int sound = 1;
    sign_rows = 2 * sign_points_count + 1;
    for (int row = 0; row < sign_rows && !failure; row++) {
        SignRow *r = &sign_row[row];
        const Critical *point = row % 2 ? &sign_point[row / 2] : NULL;
        const Critical *before = row >= 2 ? &sign_point[row / 2 - 1] : NULL, *after = row / 2 < sign_points_count ? &sign_point[row / 2] : NULL;

        /* Il valore in cui si calcolano i segni. */
        r->sample = !point ? interval_sample(before, after) : point->exact ? point->low : wide_mid(point->low, point->high);
        r->rational = !point || point->exact;
        for (int i = 0; i < sign_polys && !failure; i++) {
            Uni rest;
            if (sign_kappa[i] >= 0) {
                /* x - k: dipende solo da dove sta la riga rispetto al punto k. */
                int place = 0;
                while (sign_point[place].kappa != sign_kappa[i]) place++;
                r->sign[i] = (row > 2 * place + 1) - (row < 2 * place + 1);
            } else if (sign_space[i] >= 0) {
                r->sign[i] = 0;  /* un polinomio in un'altra lettera: non è un segno di questa tabella */
            } else {
                r->sign[i] = (!r->rational && point->element >= 0 && uni_divide(&sign_poly[i], &sign_base[point->element], &rest)) ? 0 : uni_sign_at(&sign_poly[i], r->sample);
            }
        }
        if (failure) break;

        /* La riga conta solo se sta nell'insieme su cui varia la variabile:
         * tra i razionali, solo un punto razionale o un intervallo. */
        r->inside = (set->reals || r->rational) && row_in_set(r->sign, set, floor_column, hole_column);

        /* Il controllo indipendente (table_agrees()). Una riga con un
         * valore razionale si rifà con il conto esatto, e deve riuscire. Una
         * radice irrazionale, e ogni riga di un enunciato periodico, si
         * rifà con gli intervalli: lì un'uguaglianza si può solo trovare
         * compatibile, non dimostrare, ma un segno sbagliato si vede. */
        int exact = r->rational && !trig_on;
        r->confirmed = 0;
        r->must = trig_on ? !point : r->rational;
        if (!r->inside) continue;

        /* Con le finestre (18p-14) la riga dice una cosa diversa in ogni
         * giro, e si ricontrolla in ognuno; altrimenti il giro è uno solo. */
        Wide more[8];
        int count = point ? 0 : row_points(row, more), every = 1;
        for (window_turn = window_first; window_turn <= window_last && sound; window_turn++) {
            int truth = sign_truth(body, r->sign), agreed = table_agrees(body, name, r->sample, exact ? NULL : point, truth);
            if (agreed == 0) sound = 0;
            if (agreed != 1) every = 0;

            /* Un intervallo si ricontrolla anche in altri punti (row_points()). */
            for (int extra = 0; extra < count && sound; extra++)
                if (table_agrees(body, name, more[extra], NULL, truth) == 0) sound = 0;
        }
        window_turn = 0;
        r->confirmed = every;
    }
    return sound;
}

/* Scrive nella dimostrazione il punto numero k della tabella: il razionale,
 * il numero con il suo logaritmo, oppure, per una radice non razionale, il
 * nome r con il suo posto tra i punti, lo stesso che ha nella sua riga. */
static void put_point(int k) {
    const Critical *point = &sign_point[k];
    if (point->kappa >= 0) proof_add("%s", kappa[point->kappa].text);
    else if (point->exact) put_wide(point->low);
    else proof_add("r_{%d}", k + 1);
}

/* Scrive nella dimostrazione di quale riga della tabella si parla: il punto,
 * la radice con l'intervallo che la isola, o l'intervallo con il valore
 * scelto al suo interno. name è la variabile. */
static void put_row(int row, int name) {
    const Critical *point = row % 2 ? &sign_point[row / 2] : NULL;
    if (point && point->element >= 0) {
        proof_add("$%c = r_{%d}$, the root of $", name, row / 2 + 1);
        put_uni(&sign_base[point->element], name);
        proof_add("$ between $");
        put_wide(point->low);
        proof_add("$ and $");
        put_wide(point->high);
        proof_add("$");
        return;
    }
    if (point) { proof_add("$%c = ", name); put_point(row / 2); proof_add("$"); return; }

    /* Un intervallo: i due punti che lo chiudono, se ci sono, e il valore
     * scelto al suo interno. */
    proof_add("$");
    if (row >= 2) { put_point(row / 2 - 1); proof_add(" < "); }
    proof_add("%c", name);
    if (row / 2 < sign_points_count) { proof_add(" < "); put_point(row / 2); }
    proof_add("$ (for instance $%c = ", name);
    put_wide(sign_row[row].sample);
    proof_add("$)");
}

/* Le soluzioni trovate da sign_solution(), come condizione in LaTeX, e ciò
 * che va detto per leggerle: se hanno estremi irrazionali, e che cosa
 * indicano i nomi r_{k}. Valgono fino alla tabella successiva. */
static char solution_text[1024], solution_note[512];

/* Ritorna 1 se il punto numero k della tabella, una radice irrazionale, è il
 * primo dei punti che sono radici del suo elemento della base: per un
 * elemento di secondo grado, la più piccola delle due radici, perché i punti
 * sono in ordine. */
static int point_is_first_root(int k) {
    for (int i = 0; i < k; i++)
        if (!sign_point[i].exact && sign_point[i].element == sign_point[k].element) return 0;
    return 1;
}

/* Aggiunge a text, di size byte, il punto numero k della tabella, scritto
 * come estremo di una soluzione: un razionale, oppure una radice.
 *
 * Una radice irrazionale ha una scrittura con i radicali quando l'elemento
 * della base che la annulla ha grado 2 (quadratic_latex()). Negli altri
 * casi la radice prende il nome r_{k+1}, quello che ha nella dimostrazione, e
 * solution_note dice quale numero è. */
static void point_latex(int k, int name, char *text, size_t size) {
    const Critical *point = &sign_point[k];
    if (point->kappa >= 0) { text_add(text, size, "%s", kappa[point->kappa].text); return; }
    if (point->exact) { wide_latex(point->low, text, size); return; }

    /* La più piccola delle due radici è il primo dei due punti di questo
     * elemento. */
    const Uni *q = &sign_base[point->element];
    if (quadratic_latex(q, point_is_first_root(k), text, size)) return;

    /* Una radice senza scrittura: il nome, e nella nota di quale numero si
     * tratta, una volta sola. */
    char label[24], low[48], high[48];
    snprintf(label, sizeof label, "r_{%d}", k + 1);
    text_add(text, size, "%s", label);
    if (strstr(solution_note, label)) return;
    wide_text(point->low, low, sizeof low);
    wide_text(point->high, high, sizeof high);
    text_add(solution_note, sizeof solution_note, "; %s è la radice di ", label);
    uni_latex(q, name, solution_note, sizeof solution_note);
    text_add(solution_note, sizeof solution_note, " tra %s e %s", low, high);
}

/* Un pezzo dell'insieme in cui una condizione vale: righe consecutive della
 * tabella in cui è vera, cioè un punto solo oppure un intervallo. */
typedef struct {
    int first, last;              /* la prima e l'ultima riga */
    int low, high;                /* i punti che lo delimitano; -1 se da quella
                                     parte non ha limite. Per un punto solo
                                     sono lo stesso punto */
    int low_closed, high_closed;  /* 1 se l'estremo fa parte del pezzo */
} Piece;

/* Cerca il primo pezzo, dalla riga from in poi, in cui vale la condizione f
 * secondo le righe di sign_row[]. Ritorna 0 se non ce ne sono più.
 *
 * Un pezzo che comincia su una riga dispari, cioè su un punto, comprende
 * quel punto; se comincia su un intervallo, il punto che lo precede resta
 * fuori. Lo stesso alla fine. */
static int sign_piece(const Formula *f, int from, Piece *piece) {
    int first = from;
    while (first < sign_rows && !(sign_row[first].inside && sign_truth(f, sign_row[first].sign))) first++;
    if (first >= sign_rows) return 0;
    int last = first;
    while (last + 1 < sign_rows && sign_row[last + 1].inside && sign_truth(f, sign_row[last + 1].sign)) last++;
    *piece = (Piece){first, last, first == 0 ? -1 : first % 2 ? first / 2 : first / 2 - 1, last == sign_rows - 1 ? -1 : last / 2, first % 2, last % 2};
    return 1;
}

/* Scrive in solution_text i valori della variabile name per cui vale la
 * condizione f, secondo le righe di sign_row[]: una condizione in LaTeX
 * com'è scritta nei libri, per esempio x < -3 \lor x \ge 2, con un pezzo
 * per ogni intervallo o punto (sign_piece()).
 *
 * Ritorna 1 se il testo si può rileggere e ricontrollare; 0 se usa un nome
 * per una radice che non ha una scrittura, o se è una delle due frasi senza
 * estremi ("nessun x", "ogni x"). */
static int sign_solution(const Formula *f, int name) {
    int pieces = 0, plain = 1;
    Piece piece;
    solution_text[0] = solution_note[0] = '\0';
    for (int from = 0; !failure && sign_piece(f, from, &piece); from = piece.last + 1) {
        int low = piece.low, high = piece.high, low_closed = piece.low_closed, high_closed = piece.high_closed;
        if (pieces++) text_add(solution_text, sizeof solution_text, " \\lor ");
        if (low < 0 && high < 0) {
            text_add(solution_text, sizeof solution_text, "\\forall %c \\in \\mathbb{R}", name);
            plain = 0;
        } else if (piece.first == piece.last && low_closed) {
            text_add(solution_text, sizeof solution_text, "%c = ", name);
            point_latex(low, name, solution_text, sizeof solution_text);
        } else if (low < 0 || high < 0) {
            text_add(solution_text, sizeof solution_text, "%c %s ", name, low < 0 ? (high_closed ? "\\le" : "<") : (low_closed ? "\\ge" : ">"));
            point_latex(low < 0 ? high : low, name, solution_text, sizeof solution_text);
        } else {
            point_latex(low, name, solution_text, sizeof solution_text);
            text_add(solution_text, sizeof solution_text, " %s %c %s ", low_closed ? "\\le" : "<", name, high_closed ? "\\le" : "<");
            point_latex(high, name, solution_text, sizeof solution_text);
        }
    }
    if (!pieces) {
        text_add(solution_text, sizeof solution_text, "\\nexists %c \\in \\mathbb{R}", name);
        plain = 0;
    }
    return plain && !solution_note[0];
}

/* Rilegge come una condizione, con il lettore degli enunciati (capitolo 17),
 * il testo text che il programma ha appena scritto. Ritorna l'albero, oppure
 * NULL se il testo non si rilegge tutto: un errore di sintassi, o qualcosa
 * dopo la condizione. In ogni caso syntax_error resta NULL. È il primo passo
 * di ogni controllo di ciò che si consegna (18p, 18t-f): il controllo
 * guarda ciò che il testo dice, non ciò che il motore pensava di scrivere. */
static Formula *condition_reread(const char *text) {
    syntax_error = NULL;
    cursor = text;
    next_token();
    Formula *written = logic_formula();
    if (syntax_error || token.kind != T_END) { syntax_error = NULL; return NULL; }
    return written;
}

/* Rilegge le soluzioni scritte in solution_text e controlla che dicano ciò
 * che dice la tabella: in ogni riga razionale la condizione riletta, con il
 * valore della riga al posto della variabile name, deve valere esattamente
 * quando vale f. È il controllo di ciò che si consegna, cioè del testo: un
 * < scritto al posto di un \le, o un estremo con il segno sbagliato, qui si
 * vede. Ritorna 1 se tutte le righe concordano. */
static int solution_reread(const Formula *f, int name) {
    const Formula *written = condition_reread(solution_text);
    if (!written) return 0;
    for (int row = 0; row < sign_rows; row++) {
        const SignRow *r = &sign_row[row];
        Wide at[9];
        if (!r->inside || !r->rational) continue;

        /* Il valore della riga, che deve riuscire; e per un intervallo gli
         * altri suoi punti, dove un estremo scritto male si vede anche se
         * il valore scelto sta dalla parte giusta di tutti e due. */
        int count = row % 2 ? 0 : row_points(row, at + 1);
        at[0] = r->sample;
        for (int i = 0; i <= count; i++) {
            if (at[i].num >= COEF_LIMIT || at[i].num <= -COEF_LIMIT || at[i].den >= COEF_LIMIT) { if (i == 0) return 0; continue; }
            failure = NULL;
            int direct = sign_holds_at(written, name, (Frac){(long long)at[i].num, (long long)at[i].den});
            if (failure && i > 0) { failure = NULL; continue; }
            if (failure || direct != sign_truth(f, r->sign)) { failure = NULL; return 0; }
        }
    }
    return 1;
}

/* =============================================================================
 * 18.14 LE SOLUZIONI DI UNA CONDIZIONE PERIODICA (18p-12, 18p-14)
 * ============================================================================
 *
 * La tabella di un enunciato periodico è nella lettera t = tan(u / 2), con
 * u = g x. Per scrivere le soluzioni in x bisogna tornare indietro:
 *
 *   - un punto t_0 della tabella è l'angolo u_0 = 2 arctan t_0, tra -pi e
 *     pi; un tratto di righe consecutive in cui la condizione vale è un
 *     arco della circonferenza; il punto u = pi, calcolato a parte, chiude
 *     il giro e può unire l'ultimo arco al primo;
 *   - le soluzioni in u si ripetono ogni 2 pi, quindi in x ogni 2 pi / g; ma
 *     l'insieme può avere un periodo più piccolo (le soluzioni di
 *     tan x = 1 si ripetono ogni pi), e si cerca il più piccolo tra i
 *     sottomultipli;
 *   - gli estremi si scrivono, quando si può, come multipli razionali di
 *     pi. Che u_0 sia proprio p pi / q, e non un numero vicino, si
 *     stabilisce con un conto esatto: vedi angle_of_point().
 */

/* Un angolo, in giri di pi: vale turns * pi più una parte fissa che dipende
 * da kind. Due angoli dello stesso tipo, con la stessa parte fissa, sono
 * uguali quando hanno lo stesso turns: è così che gli angoli si confrontano
 * senza errori. near è il suo valore approssimato diviso pi, che serve solo
 * a metterli in ordine. */
typedef struct {
    int kind;      /* 0: nessuna parte fissa, l'angolo è un multiplo razionale di
                      pi; 1: la parte fissa è arctan(slope); 2: è
                      2 arctan(t), con t il punto numero point della tabella */
    Frac turns;    /* il multiplo razionale di pi che si aggiunge alla parte fissa */
    Frac slope;    /* kind 1 */
    int point;     /* kind 2 */
    double near;   /* il valore approssimato diviso pi: solo per l'ordine */
} Angle;

/* Un arco dell'insieme delle soluzioni, da from a to nel verso in cui gli
 * angoli crescono; un punto solo se single. period è ogni quanto si ripete,
 * in giri di pi di u: lo usa solo la scrittura delle famiglie (18p-12). */
typedef struct {
    Angle from, to;
    int from_closed, to_closed, single;
    Frac period;
} Arc;

/* Ritorna il polinomio S_q(t), la parte immaginaria di (1 + i t)^q: la somma
 * sui j dispari di (-1)^((j-1)/2) C(q, j) t^j. */
static Uni half_angle_poly(int q) {
    Uni p = {0, {0}};
    __int128 binomial = 1;
    for (int j = 0; j <= q; j++) {
        if (j % 2) p.c[j] = (j / 2) % 2 ? -binomial : binomial;
        binomial = binomial * (q - j) / (j + 1);
    }
    p.degree = q;
    uni_trim(&p);
    return p;
}

/* Ritorna l'angolo u_0 = 2 arctan t_0 del punto numero k della tabella.
 *
 * Quando u_0 è un multiplo razionale di pi lo si riconosce così. Il numero
 * 1 + i t_0 ha per argomento arctan t_0 = u_0 / 2; quindi (1 + i t_0)^q ha
 * per argomento q u_0 / 2, ed è un numero reale esattamente quando q u_0 è
 * un multiplo di 2 pi, cioè quando la sua parte immaginaria S_q(t_0) è
 * zero. Che t_0 annulli S_q è un fatto esatto: per un razionale è un conto;
 * per una radice irrazionale di un elemento e della base, vuol dire che il
 * massimo comun divisore di e e di S_q ha una radice nell'intervallo che
 * isola t_0, e le radici in un intervallo le conta il teorema di Sturm.
 * Saputo che q u_0 è un multiplo di 2 pi, quale multiplo lo dice il valore
 * approssimato, perché i multipli distano 2 pi / q l'uno dall'altro. Si
 * provano i q dei libri, dai più piccoli: con q = 12 si riconosce pi/6, con
 * 24 pi/12, con 16 pi/8, con 20 pi/10.
 *
 * Altrimenti, se tan u_0 = 2 t_0 / (1 - t_0^2) è un razionale m, l'angolo è
 * arctan m, più o meno pi. Lo è per un t_0 razionale, e per una radice di
 * a t^2 + b t - a, dove vale 2a / b perché a (1 - t^2) = b t. Negli altri
 * casi l'angolo resta scritto come 2 arctan t_0. */
static Angle angle_of_point(int k) {
    static const int tries[] = {1, 2, 3, 4, 6, 12, 8, 5, 10, 24, 16, 20};
    const Critical *point = &sign_point[k];
    Range value = point->exact ? range_ratio(point->low.num, point->low.den) : root_range(&sign_base[point->element], point->low, point->high);
    Range turn = range_div(range_mul(range_ratio(2, 1), range_atan(value)), range_pi());
    Angle angle = {2, frac_int(0), frac_int(0), k, (turn.low + turn.high) / 2};

    /* Un multiplo razionale di pi. */
    for (size_t i = 0; i < sizeof tries / sizeof *tries && !failure; i++) {
        int q = tries[i];
        /* q u_0 deve essere un multiplo di 2 pi: near q / 2 un intero. */
        double scaled = angle.near * q / 2, nearest = (double)(long long)(scaled + (scaled < 0 ? -0.5 : 0.5));
        if (scaled - nearest > 1e-9 || nearest - scaled > 1e-9) continue;
        Uni imaginary = half_angle_poly(q);
        int zero;
        if (point->exact) {
            zero = uni_sign_at(&imaginary, point->low) == 0;
        } else {
            Uni common = uni_gcd(sign_base[point->element], imaginary);
            zero = common.degree >= 1;
            if (zero) {
                sturm_build(&common);
                zero = sturm_changes(point->low) - sturm_changes(point->high) == 1;
            }
        }
        if (failure || !zero) continue;
        angle.kind = 0;
        angle.turns = frac_make(2 * (long long)nearest, q);
        return angle;
    }

    /* arctan di un razionale, più o meno pi. */
    Frac slope = frac_int(0);
    int rational = 0;
    if (point->exact && point->low.num < 1000000 && point->low.num > -1000000 && point->low.den < 1000000) {
        Frac t = {(long long)point->low.num, (long long)point->low.den}, below = frac_add(frac_int(1), frac_neg(frac_mul(t, t)));
        rational = below.num != 0;
        if (rational) slope = frac_div(frac_add(t, t), below);
    } else if (!point->exact) {
        const Uni *e = &sign_base[point->element];
        rational = e->degree == 2 && e->c[0] == -e->c[2] && e->c[1] != 0 && e->c[2] < 1000000 && e->c[2] > -1000000 && e->c[1] < 1000000 && e->c[1] > -1000000;
        if (rational) slope = frac_make(2 * e->c[2], e->c[1]);
    }
    if (rational && !failure) {
        Range base = range_div(range_atan(range_ratio(slope.num, slope.den)), range_pi());
        double shift = angle.near - (base.low + base.high) / 2;
        angle.kind = 1;
        angle.slope = slope;
        angle.turns = frac_int((long long)(shift + (shift < 0 ? -0.5 : 0.5)));
    }
    failure = NULL;
    return angle;
}

/* Ritorna l'angolo a ruotato di turns giri di pi. */
static Angle angle_turn(Angle a, Frac turns) {
    a.turns = frac_add(a.turns, turns);
    a.near += (double)turns.num / (double)turns.den;
    return a;
}

/* Ritorna 1 se a e b sono lo stesso angolo a meno di multipli di modulus
 * (in giri di pi: 2 per i giri interi). */
static int angle_same(Angle a, Angle b, Frac modulus) {
    Frac gap = frac_div(frac_add(a.turns, frac_neg(b.turns)), modulus);
    if (a.kind != b.kind || gap.den != 1) return 0;
    return a.kind == 0 || (a.kind == 1 ? frac_cmp(a.slope, b.slope) == 0 : a.point == b.point);
}

/* Ritorna 1 se gli archi a e b sono lo stesso arco a meno di multipli di
 * modulus. */
static int arc_same(const Arc *a, const Arc *b, Frac modulus) {
    Frac gap = frac_add(a->from.turns, frac_neg(b->from.turns));
    return a->single == b->single && a->from_closed == b->from_closed && a->to_closed == b->to_closed &&
           angle_same(a->from, b->from, modulus) && angle_same(a->to, angle_turn(b->to, gap), modulus) && frac_cmp(a->to.turns, frac_add(b->to.turns, gap)) == 0;
}

/* Riporta l'arco *arc, che si ripete ogni period giri di pi, alla sua copia
 * di riferimento, quella che scrivono i libri: comincia tra 0 e il periodo,
 * come \frac{7}{6}\pi + 2k\pi < x < \frac{11}{6}\pi + 2k\pi; ma un intervallo
 * che così scavalcherebbe la fine del periodo si scrive attorno allo zero,
 * -\frac{\pi}{6} + 2k\pi \le x \le \frac{\pi}{3} + 2k\pi, e un punto scritto
 * con un'arcotangente resta, quando il periodo lo permette, senza multipli
 * di pi accanto: x = \arctan 2 + k\pi. */
static void arc_home(Arc *arc, Frac period) {
    double length = (double)period.num / (double)period.den, from = arc->from.near;
    long long steps = (long long)(from / length);
    Frac whole = frac_div(arc->from.turns, period);
    if (from < 0) steps--;
    if (from - steps * length > length - 1e-9) steps++;
    if (from - steps * length < -1e-9) steps--;
    if (!arc->single && arc->to.near - steps * length > length + 1e-9) steps++;
    if (arc->single && arc->from.kind != 0 && whole.den == 1) steps = whole.num;
    Frac back = frac_mul(frac_int(-steps), period);
    arc->from = angle_turn(arc->from, back);
    arc->to = angle_turn(arc->to, back);
    arc->period = period;
}

/* Aggiunge a text, di size byte, l'angolo a diviso per g = trig_scale, cioè
 * il valore della variabile, più il multiplo del periodo period (in giri di
 * pi, già diviso per g) se with_period non è zero: \frac{\pi}{6} + 2k\pi. */
static void angle_latex(Angle a, Frac period, int with_period, char *text, size_t size) {
    Frac turns = frac_div(a.turns, trig_scale), factor = frac_div(frac_int(a.kind == 2 ? 2 : 1), trig_scale);
    int written = 0;

    /* La parte fissa: un'arcotangente, con il suo fattore. */
    if (a.kind != 0) {
        char inside[96] = "";
        Frac size_of = a.slope;
        int minus = a.kind == 1 && a.slope.num < 0;
        if (minus) size_of.num = -size_of.num;
        if (a.kind == 1) wide_latex((Wide){size_of.num, size_of.den}, inside, sizeof inside); else point_latex(a.point, 't', inside, sizeof inside);
        if (minus) text_add(text, size, "-");
        if (factor.den != 1) text_add(text, size, "\\frac{%lld}{%lld}", factor.num, factor.den);
        else if (factor.num != 1) text_add(text, size, "%lld", factor.num);
        if (a.kind == 1 && size_of.den == 1) text_add(text, size, "\\arctan %s", inside); else text_add(text, size, "\\arctan\\left(%s\\right)", inside);
        written = 1;
    }

    /* Il multiplo di pi. */
    if (turns.num != 0) {
        long long top = turns.num < 0 ? -turns.num : turns.num;
        text_add(text, size, "%s", written ? (turns.num < 0 ? " - " : " + ") : (turns.num < 0 ? "-" : ""));
        if (turns.den == 1 && top == 1) text_add(text, size, "\\pi");
        else if (turns.den == 1) text_add(text, size, "%lld\\pi", top);
        else if (top == 1) text_add(text, size, "\\frac{\\pi}{%lld}", turns.den);
        else text_add(text, size, "\\frac{%lld}{%lld}\\pi", top, turns.den);
        written = 1;
    }

    /* Il periodo. */
    if (with_period) {
        text_add(text, size, "%s", written ? " + " : "");
        if (period.den == 1 && period.num == 1) text_add(text, size, "k\\pi");
        else if (period.den == 1) text_add(text, size, "%lldk\\pi", period.num);
        else if (period.num == 1) text_add(text, size, "\\frac{k\\pi}{%lld}", period.den);
        else text_add(text, size, "\\frac{%lldk\\pi}{%lld}", period.num, period.den);
    } else if (!written) {
        text_add(text, size, "0");
    }
}

/* Gli archi delle soluzioni dell'enunciato periodico in corso, e il periodo
 * dell'insieme in giri di pi di u. Li riempie trig_solution(), che li riduce
 * a un periodo e dà a ognuno il periodo della sua famiglia; oppure
 * window_solution() (18p-14), con gli intervalli così come sono, senza
 * periodo. */
static Arc trig_arc[MAX_ARCS];
static int trig_arcs;
static Frac trig_period;

/* 18p-12. Scrive in solution_text le soluzioni, nella variabile name, della
 * condizione periodica f, dalle righe della tabella in t e dal valore
 * at_pi che la condizione ha nel punto u = pi; riempie trig_arc[].
 * Ritorna 0, dopo aver annotato un errore, se gli archi sono troppi. */
static int trig_solution(const Formula *f, int name, int at_pi) {
    static const int parts[] = {24, 12, 8, 6, 5, 4, 3, 2, 1};
    Piece piece;
    Angle start = {0, frac_int(-1), frac_int(0), 0, -1}, end = {0, frac_int(1), frac_int(0), 0, 1};
    int first = -1, last = -1, whole = 0;
    trig_arcs = 0;
    solution_text[0] = solution_note[0] = '\0';

    /* Gli archi in un giro di u, da -pi a pi. Il primo può cominciare in
     * -pi e l'ultimo finire in pi: sono lo stesso punto della
     * circonferenza. */
    for (int from = 0; !failure && sign_piece(f, from, &piece); from = piece.last + 1) {
        if (trig_arcs == MAX_ARCS - 1) { fail("troppi archi nelle soluzioni di una condizione periodica"); return 0; }
        Arc *arc = &trig_arc[trig_arcs];
        arc->single = piece.first == piece.last && piece.first % 2;
        arc->from = piece.low < 0 ? start : angle_of_point(piece.low);
        arc->to = piece.high < 0 ? end : angle_of_point(piece.high);
        arc->from_closed = piece.low >= 0 && piece.low_closed;
        arc->to_closed = piece.high >= 0 && piece.high_closed;
        if (piece.low < 0) first = trig_arcs;
        if (piece.high < 0) last = trig_arcs;
        if (piece.low < 0 && piece.high < 0) whole = 1;
        trig_arcs++;
    }
    if (failure) return 0;

    /* Il punto u = pi. Se la condizione lì vale: unisce l'ultimo arco al
     * primo, o chiude quello dei due che c'è, o è una soluzione isolata. Se
     * non vale, i due archi restano aperti da quella parte. */
    if (whole && at_pi) {
        text_add(solution_text, sizeof solution_text, "\\forall %c \\in \\mathbb{R}", name);
        trig_arcs = 1;
        trig_period = frac_int(2);
        trig_arc[0] = (Arc){start, end, 1, 1, 0, frac_int(2)};
        return 1;
    }
    if (at_pi && first >= 0 && last >= 0) {
        trig_arc[last].to = angle_turn(trig_arc[first].to, frac_int(2));
        trig_arc[last].to_closed = trig_arc[first].to_closed;
        trig_arc[first] = trig_arc[--trig_arcs];
    } else if (at_pi && last >= 0) {
        trig_arc[last].to_closed = 1;
    } else if (at_pi && first >= 0) {
        trig_arc[first].from_closed = 1;
    } else if (at_pi) {
        trig_arc[trig_arcs++] = (Arc){end, end, 1, 1, 1, frac_int(2)};
    }
    if (trig_arcs == 0) {
        text_add(solution_text, sizeof solution_text, "\\nexists %c \\in \\mathbb{R}", name);
        trig_period = frac_int(2);
        return 1;
    }

    /* Il periodo più piccolo: il più grande m per cui ruotando ogni arco di
     * 2 pi / m si ritrova un arco dell'insieme. Gli archi sono massimali e
     * staccati, quindi l'insieme ruotato coincide con l'insieme quando
     * coincidono gli archi. */
    int m = 1;
    for (size_t i = 0; i < sizeof parts / sizeof *parts && m == 1; i++) {
        int same = 1;
        for (int a = 0; a < trig_arcs && same; a++) {
            Arc turned = trig_arc[a];
            int found = 0;
            turned.from = angle_turn(turned.from, frac_make(2, parts[i]));
            turned.to = angle_turn(turned.to, frac_make(2, parts[i]));
            for (int b = 0; b < trig_arcs && !found; b++) found = arc_same(&turned, &trig_arc[b], frac_int(2));
            same = found;
        }
        if (same) m = parts[i];
    }
    trig_period = frac_make(2, m);

    /* Un arco per ogni classe: gli altri sono le sue copie ruotate di un
     * periodo. */
    int kept = 0;
    for (int a = 0; a < trig_arcs; a++) {
        Arc arc = trig_arc[a];
        int copy = 0;
        arc_home(&arc, trig_period);
        for (int b = 0; b < kept && !copy; b++) copy = arc_same(&arc, &trig_arc[b], trig_period);
        if (!copy) trig_arc[kept++] = arc;
    }
    trig_arcs = kept;

    /* Le famiglie. Dentro il periodo dell'insieme alcuni archi possono
     * ripetersi più spesso: le soluzioni di sin(4x) = sin(2x) sono
     * x = k pi/2 e x = pi/6 + k pi/3, e solo insieme hanno periodo pi. Per
     * ogni divisore r, dai più grandi, un arco che ruotato di 1/r, 2/r, ...
     * del periodo ritrova altri archi dell'insieme li rappresenta tutti,
     * con il periodo diviso per r. Ogni famiglia così scritta è fatta di
     * archi dell'insieme, e ogni arco finisce in una famiglia: l'insieme
     * non cambia, cambia solo come lo si scrive. */
    int state[MAX_ARCS] = {0};  /* 1: rappresenta una famiglia; 2: è in quella di un altro */
    for (size_t i = 0; i < sizeof parts / sizeof *parts && parts[i] > 1; i++) {
        Frac step = frac_div(trig_period, frac_int(parts[i]));
        for (int a = 0; a < trig_arcs; a++) {
            int member[24], found = !state[a];
            for (int j = 1; j < parts[i] && found; j++) {
                Arc turned = trig_arc[a];
                turned.from = angle_turn(turned.from, frac_mul(step, frac_int(j)));
                turned.to = angle_turn(turned.to, frac_mul(step, frac_int(j)));
                found = 0;
                for (int b = 0; b < trig_arcs && !found; b++)
                    if (b != a && !state[b] && arc_same(&turned, &trig_arc[b], trig_period)) { member[j] = b; found = 1; }
            }
            if (!found) continue;
            state[a] = 1;
            for (int j = 1; j < parts[i]; j++) state[member[j]] = 2;
            arc_home(&trig_arc[a], step);
        }
    }
    kept = 0;
    for (int a = 0; a < trig_arcs; a++)
        if (state[a] != 2) trig_arc[kept++] = trig_arc[a];
    trig_arcs = kept;

    /* In ordine, e scritti nella variabile: gli angoli divisi per g. */
    for (int a = 0; a < trig_arcs; a++)
        for (int b = a + 1; b < trig_arcs; b++)
            if (trig_arc[b].from.near < trig_arc[a].from.near) { Arc swap = trig_arc[a]; trig_arc[a] = trig_arc[b]; trig_arc[b] = swap; }
    for (int a = 0; a < trig_arcs && !failure; a++) {
        const Arc *arc = &trig_arc[a];
        Frac shown = frac_div(arc->period, trig_scale);
        if (a) text_add(solution_text, sizeof solution_text, " \\lor ");
        if (arc->single) {
            text_add(solution_text, sizeof solution_text, "%c = ", name);
            angle_latex(arc->from, shown, 1, solution_text, sizeof solution_text);
            continue;
        }
        angle_latex(arc->from, shown, 1, solution_text, sizeof solution_text);
        text_add(solution_text, sizeof solution_text, " %s %c %s ", arc->from_closed ? "\\le" : "<", name, arc->to_closed ? "\\le" : "<");
        angle_latex(arc->to, shown, 1, solution_text, sizeof solution_text);
    }
    return !failure;
}

/* 18p-14. Scrive in solution_text le soluzioni, nella variabile name, della
 * condizione periodica f ristretta da finestre, e riempie trig_arc[] con i
 * loro intervalli, questa volta non ridotti a un periodo. La tabella si
 * legge un giro alla volta, dal giro window_first al giro window_last;
 * pi_truth[j][0] dice se la condizione vale nel punto u = pi del giro
 * window_first + j, che è dove quel giro finisce e il successivo comincia:
 * se vale, unisce l'ultimo intervallo di un giro al primo del successivo.
 * Ritorna 0, dopo aver annotato un errore, se le soluzioni non stanno in un
 * intervallo limitato o se gli intervalli sono troppi. */
static int window_solution(const Formula *f, int name, int pi_truth[][3]) {
    static const char unbounded[] = "le soluzioni di una condizione periodica ristretta dalla variabile non stanno in un intervallo limitato: non le so scrivere";
    Piece piece;
    int carry = -1;  /* l'intervallo che arriva alla fine del giro precedente, punto compreso */
    trig_arcs = 0;
    solution_text[0] = solution_note[0] = '\0';
    for (window_turn = window_first; window_turn <= window_last && !failure; window_turn++) {
        Frac shift = frac_int(2 * window_turn);
        Angle start = {0, frac_int(2 * window_turn - 1), frac_int(0), 0, (double)(2 * window_turn - 1)};
        Angle end = {0, frac_int(2 * window_turn + 1), frac_int(0), 0, (double)(2 * window_turn + 1)};
        int reaches = -1, at_end = pi_truth[window_turn - window_first][0], outer = window_turn == window_first || window_turn == window_last;

        /* Gli intervalli di questo giro. Il primo può continuare quello che
         * il giro precedente ha lasciato aperto. */
        for (int from = 0; !failure && sign_piece(f, from, &piece); from = piece.last + 1) {
            Arc *arc = piece.low < 0 && carry >= 0 ? &trig_arc[carry] : NULL;
            if (outer) { fail(unbounded); break; }
            if (!arc && trig_arcs == MAX_ARCS) { fail("troppi archi nelle soluzioni di una condizione periodica"); break; }
            if (!arc) {
                arc = &trig_arc[trig_arcs++];
                arc->from = piece.low < 0 ? start : angle_turn(angle_of_point(piece.low), shift);
                arc->from_closed = piece.low >= 0 && piece.low_closed;
            }
            arc->single = arc->from_closed && piece.first == piece.last && piece.first % 2 && piece.low >= 0;
            arc->to = piece.high < 0 ? end : angle_turn(angle_of_point(piece.high), shift);
            arc->to_closed = piece.high >= 0 && piece.high_closed;
            carry = -1;
            reaches = piece.high < 0 ? (int)(arc - trig_arc) : -1;
        }
        if (failure) break;

        /* Il punto in cui il giro finisce. */
        if (!at_end) { carry = -1; continue; }
        if (outer) { fail(unbounded); break; }
        if (reaches < 0 && trig_arcs == MAX_ARCS) { fail("troppi archi nelle soluzioni di una condizione periodica"); break; }
        if (reaches < 0) trig_arc[trig_arcs] = (Arc){end, end, 1, 1, 1, frac_int(0)};
        carry = reaches >= 0 ? reaches : trig_arcs++;
        trig_arc[carry].to_closed = 1;
    }
    window_turn = 0;
    if (failure) return 0;

    /* Il testo: gli intervalli sono già in ordine. */
    if (trig_arcs == 0) text_add(solution_text, sizeof solution_text, "\\nexists %c \\in \\mathbb{R}", name);
    for (int a = 0; a < trig_arcs && !failure; a++) {
        const Arc *arc = &trig_arc[a];
        if (a) text_add(solution_text, sizeof solution_text, " \\lor ");
        if (arc->single) {
            text_add(solution_text, sizeof solution_text, "%c = ", name);
            angle_latex(arc->from, frac_int(0), 0, solution_text, sizeof solution_text);
            continue;
        }
        angle_latex(arc->from, frac_int(0), 0, solution_text, sizeof solution_text);
        text_add(solution_text, sizeof solution_text, " %s %c %s ", arc->from_closed ? "\\le" : "<", name, arc->to_closed ? "\\le" : "<");
        angle_latex(arc->to, frac_int(0), 0, solution_text, sizeof solution_text);
    }
    return !failure;
}

/* Ritorna un intervallo che contiene il valore della variabile nell'angolo
 * a, cioè l'angolo diviso per g = trig_scale. */
static Range angle_range(Angle a) {
    Range value = range_mul(range_ratio(a.turns.num, a.turns.den), range_pi());
    if (a.kind == 1) value = range_add(value, range_atan(range_ratio(a.slope.num, a.slope.den)));
    if (a.kind == 2) {
        const Critical *point = &sign_point[a.point];
        Range t = point->exact ? range_ratio(point->low.num, point->low.den) : root_range(&sign_base[point->element], point->low, point->high);
        value = range_add(value, range_mul(range_ratio(2, 1), range_atan(t)));
    }
    return range_div(value, range_ratio(trig_scale.num, trig_scale.den));
}

/* =============================================================================
 * 18.15 IL GRAFICO DELLA TABELLA DEI SEGNI (18q)
 * ============================================================================
 *
 * Di un enunciato deciso con la tabella dei segni si può fare il disegno: è
 * la figura che sui libri accompagna la soluzione di una disequazione. Qui
 * si decide che cosa disegnare; a disegnare e a scrivere il PDF pensa
 * plot.c, che non sa nulla di enunciati.
 *
 *   - Un pannello per ogni confronto della condizione, con le curve dei due
 *     membri (una sola, e l'asse, se l'altro membro è 0).
 *   - In ogni pannello, le fasce verdi dove quel confronto è verificato; e
 *     il campo di esistenza: una fascia grigia dove un membro non ha un
 *     valore, una retta tratteggiata sul suo bordo o su un punto isolato in
 *     cui non lo ha.
 *   - In fondo la retta dei numeri con le soluzioni di tutta la condizione:
 *     un tratto spesso per ogni intervallo, un punto pieno per un estremo
 *     che è una soluzione e uno vuoto per uno che non lo è.
 *
 * Fasce, rette ed estremi vengono dalle righe di sign_row[], cioè dai conti
 * esatti della tabella. I numeri in virgola mobile servono solo a tracciare
 * le curve e a mettere i punti sull'asse: un errore di arrotondamento sposta
 * una linea di un capello, non cambia che cosa è vero. Per questo qui, e
 * solo qui, il motore usa i double.
 */

/* Il grafico dell'ultimo enunciato deciso con la tabella dei segni, o NULL
 * se non ne ha uno. Appartiene al motore, che lo libera quando comincia
 * l'enunciato successivo (prove()); chi scrive il documento lo legge prima.
 * figures_wanted dice se i grafici servono: finché nessuno li mette in un
 * documento non vengono costruiti. */
static PlFigure *figure;
static int figures_wanted;

/* Ritorna il valore, in virgola mobile, dell'espressione node quando la
 * variabile name vale x: il punto medio dell'intervallo che lo contiene
 * (capitolo 24). Mette 0 in *ok, che chi chiama ha messo a 1, se lì non ha
 * un valore o non lo si sa calcolare. */
static double node_value(const Node *node, int name, double x, int *ok) {
    int undefined = 0;
    Range value = node_range(node, name, (Range){x, x}, &undefined);
    if (undefined || !range_known(value)) { *ok = 0; return 0; }
    return (value.low + value.high) / 2;
}

/* Ritorna il valore della variabile, in virgola mobile, là dove la lettera
 * della tabella vale t: t stesso, oppure, in un enunciato periodico,
 * (2 arctan t) / g, il punto del giro che va da -pi / g a pi / g. */
static double figure_place(double t) {
    if (!trig_on) return t;
    Range angle = range_atan((Range){t, t});
    return (angle.low + angle.high) * (double)trig_scale.den / (double)trig_scale.num;
}

/* Ritorna il valore approssimato della variabile nel punto numero k della
 * tabella, per metterlo su un asse. Una radice irrazionale si avvicina per
 * bisezione sull'elemento della base che la annulla: agli estremi
 * dell'intervallo che la isola il polinomio ha segni opposti, perché la
 * radice è semplice. */
static double point_approx(int k) {
    const Critical *point = &sign_point[k];
    double low = (double)point->low.num / (double)point->low.den, high = (double)point->high.num / (double)point->high.den;
    if (point->exact) return figure_place(low);
    if (point->kappa >= 0) return (low + high) / 2;
    const Uni *q = &sign_base[point->element];
    int negative = 0;
    for (int step = 0; step <= 60; step++) {
        /* Il valore del polinomio nel punto da provare, con la regola di
         * Horner; al passo 0 il punto è l'estremo inferiore. */
        double x = step ? (low + high) / 2 : low, value = 0;
        for (int i = q->degree; i >= 0; i--) value = value * x + (double)q->c[i];
        if (!step) negative = value < 0;
        else if ((value < 0) == negative) low = x;
        else high = x;
    }
    return figure_place((low + high) / 2);
}

/* Mette in list[], che ha MAX_PANELS + 1 posti, i confronti della
 * condizione f nell'ordine in cui sono scritti, e ne aggiorna il numero
 * *count; oltre MAX_PANELS + 1 smette di contare. */
static void comparisons_collect(const Formula *f, const Formula **list, int *count) {
    if (!f || *count > MAX_PANELS) return;
    if (f->kind == F_EQUAL || f->kind == F_DISTINCT || f->kind == F_LESS || f->kind == F_LESS_EQ) { list[(*count)++] = f; return; }
    comparisons_collect(f->a, list, count);
    comparisons_collect(f->b, list, count);
}

/* Confronto tra double per qsort. */
static int double_order(const void *a, const void *b) {
    double x = *(const double *)a, y = *(const double *)b;
    return (x > y) - (x < y);
}

/* Ritorna 1 se nella riga row della tabella il confronto f ha un valore. */
static int row_defined(const Formula *f, int row) {
    int defined = 1;
    sign_compare(f, sign_row[row].sign, &defined);
    return defined;
}

/* Ritorna 1 se il punto numero k della tabella è un bordo del campo di
 * esistenza del confronto f: da una parte il confronto ha un valore e
 * dall'altra no, oppure non lo ha solo nel punto. */
static int point_edge(const Formula *f, int k) {
    int before = row_defined(f, 2 * k), here = row_defined(f, 2 * k + 1), after = row_defined(f, 2 * k + 2);
    return before != after || (!here && before);
}

/* Disegna in axes, tra low e high, il pannello del confronto f nella
 * variabile name: le due curve, le fasce verdi dove vale, quelle grigie e
 * le rette tratteggiate dove non ha un valore. title è il titolo del
 * pannello. */
static void figure_panel(PlAxes *axes, const Formula *f, int name, double low, double high, const char *title) {
    static double xs[FIGURE_SAMPLES + MAX_POINTS], left[FIGURE_SAMPLES + MAX_POINTS], right[FIGURE_SAMPLES + MAX_POINTS], seen[2 * FIGURE_SAMPLES];
    volatile double zero = 0;
    double hole = zero / zero;  /* "non un numero": dove plot.c spezza una linea */

    /* I due membri come sono scritti: il lettore scambia quelli di > e \ge. */
    const Node *first = f->swapped ? f->right : f->left, *second = f->swapped ? f->left : f->right;
    int count = 0, values = 0, next = 0, flat = second->kind == N_NUM && second->value == 0;

    /* I campioni, da sinistra. Passando su un punto in cui il confronto non
     * è definito si mette un buco e una retta tratteggiata: senza il buco la
     * linea unirebbe i due rami di un asintoto. */
    for (int i = 0; i < FIGURE_SAMPLES; i++) {
        double x = low + (high - low) * i / (FIGURE_SAMPLES - 1);
        for (; next < sign_points_count && point_approx(next) <= x; next++) {
            if (point_edge(f, next)) pl_axvline(axes, point_approx(next), PL_GRAY, 0.8, 1);
            if (row_defined(f, 2 * next + 1)) continue;
            xs[count] = point_approx(next);
            left[count] = right[count] = hole;
            count++;
        }
        int ok = 1;
        double l = node_value(first, name, x, &ok), r = node_value(second, name, x, &ok);

        /* Un valore fuori dai double (infinito, o "non un numero") vale come
         * un buco: sottratto a se stesso non dà zero. */
        if (l - l != 0 || r - r != 0) ok = 0;
        xs[count] = x;
        left[count] = ok ? l : hole;
        right[count] = ok ? r : hole;
        count++;
        /* Per l'asse y contano i campioni della parte centrale: ai lati
         * c'è solo il margine, dove un polinomio è già cresciuto molto. */
        if (!ok || 8 * i < FIGURE_SAMPLES || 8 * i > 7 * FIGURE_SAMPLES) continue;
        seen[values++] = l;
        if (!flat) seen[values++] = r;
    }

    /* L'asse y: i valori centrali delle curve, più un margine. Vicino a un
     * asintoto i valori crescono senza limite, e prendendoli tutti il resto
     * del grafico si schiaccerebbe sull'asse: si tengono quelli tra il primo
     * e l'ultimo decimo, e la cornice taglia il resto. */
    double bottom = -1, top = 1;
    if (values > 0) {
        qsort(seen, (size_t)values, sizeof *seen, double_order);
        bottom = seen[values / 10];
        top = seen[values - 1 - values / 10];
        if (flat && bottom > 0) bottom = 0;
        if (flat && top < 0) top = 0;
        double margin = (top - bottom) / 2;
        if (margin < 0.5) margin = 0.5;
        bottom -= margin;
        top += margin;
    }
    pl_set_title(axes, title);
    pl_set_xlim(axes, low, high);
    pl_set_ylim(axes, bottom, top);

    /* Dove il confronto non ha valore: una fascia grigia per ogni tratto di
     * righe consecutive in cui non è definito. Un punto solo, come uno zero
     * del denominatore, ha già la sua retta tratteggiata. */
    for (int row = 0; row < sign_rows; row++) {
        int last = row;
        if (row_defined(f, row)) continue;
        while (last + 1 < sign_rows && !row_defined(f, last + 1)) last++;
        /* La riga r comincia nel punto (r - 1) / 2 e finisce nel punto
         * r / 2, che per una riga dispari sono lo stesso punto; la prima e
         * l'ultima arrivano ai bordi dell'asse. */
        if (last > row || row % 2 == 0)
            pl_axvspan(axes, row == 0 ? low : point_approx((row - 1) / 2), last == sign_rows - 1 ? high : point_approx(last / 2), PL_GRAY);
        row = last;
    }

    /* Dove il confronto vale: una fascia per ogni intervallo, un punto sulla
     * curva per una soluzione isolata. */
    Piece piece;
    for (int from = 0; sign_piece(f, from, &piece); from = piece.last + 1) {
        double a = piece.low < 0 ? low : point_approx(piece.low), b = piece.high < 0 ? high : point_approx(piece.high);
        int ok = 1;
        if (piece.first == piece.last && piece.first % 2) pl_marker(axes, a, node_value(first, name, a, &ok), PL_GREEN, 1);
        else pl_axvspan(axes, a, b, PL_GREEN);
    }

    /* Le curve: i due membri, o un membro e l'asse se l'altro è 0. */
    if (flat) pl_axhline(axes, 0, PL_BLACK, 0.8, 0);
    pl_plot(axes, xs, left, count, PL_BLUE, 1.5, "left side");
    if (!flat) pl_plot(axes, xs, right, count, PL_ORANGE, 1.5, "right side");
    pl_legend(axes);
}

/* Disegna in axes, tra low e high, la retta dei numeri con le soluzioni
 * della condizione f: un tratto spesso per ogni intervallo, e ai suoi
 * estremi un punto pieno se l'estremo è una soluzione, vuoto se non lo è.
 * Sulle tacche stanno gli estremi: i razionali esatti, gli altri con tre
 * decimali. */
static void figure_solutions(PlAxes *axes, const Formula *f, double low, double high) {
    static double at[MAX_POINTS];
    static char text[MAX_POINTS][32];
    static const char *label[MAX_POINTS];
    int ticks = 0, written = -1;  /* written: l'ultima tacca con la scritta */
    Piece piece;
    pl_set_title(axes, "solutions (full dot: included, empty dot: excluded)");
    pl_set_xlim(axes, low, high);
    pl_set_ylim(axes, -1, 1);
    pl_set_yticks(axes, NULL, NULL, 0);
    pl_axhline(axes, 0, PL_GRAY, 0.8, 0);
    for (int from = 0; sign_piece(f, from, &piece); from = piece.last + 1) {
        double ends[2] = {piece.low < 0 ? low : point_approx(piece.low), piece.high < 0 ? high : point_approx(piece.high)}, level[2] = {0, 0};
        int single = piece.first == piece.last && piece.first % 2;
        if (!single) pl_plot(axes, ends, level, 2, PL_GREEN, 4, NULL);

        /* Gli estremi: i punti, con la loro tacca. Un punto solo è l'estremo
         * di se stesso, e si disegna una volta. */
        for (int side = 0; side < (single ? 1 : 2); side++) {
            int k = side ? piece.high : piece.low;
            if (k < 0) continue;
            pl_marker(axes, ends[side], 0, PL_GREEN, side ? piece.high_closed : piece.low_closed);
            if (ticks > 0 && at[ticks - 1] == ends[side]) continue;
            /* In un enunciato periodico il punto esatto è il valore di t,
             * non quello della variabile: lì la scritta è sempre il
             * decimale. */
            if (sign_point[k].exact && !trig_on) wide_text(sign_point[k].low, text[ticks], sizeof text[ticks]);
            else snprintf(text[ticks], sizeof text[ticks], "%.3f", ends[side]);

            /* Due estremi vicini avrebbero le scritte una sull'altra: il
             * secondo resta con la sola tacca, e il suo valore si legge
             * nelle soluzioni scritte. È una stima: un carattere è largo
             * circa 0,08 pollici e l'asse circa 5, la misura vera la conosce
             * solo plot.c. */
            if (written >= 0 && (ends[side] - at[written]) / (high - low) * 5 < 0.04 * (double)(strlen(text[written]) + strlen(text[ticks])) + 0.1) text[ticks][0] = '\0';
            else written = ticks;
            at[ticks] = ends[side];
            label[ticks] = text[ticks];
            ticks++;
        }
    }
    pl_set_xticks(axes, at, label, ticks);
}

/* Ritorna 1 se nel punto numero k della tabella la condizione f cambia: se
 * lì vale e subito prima o subito dopo no, o il contrario. */
static int point_matters(const Formula *f, int k) {
    int truth[3];
    for (int i = 0; i < 3; i++) truth[i] = sign_row[2 * k + i].inside && sign_truth(f, sign_row[2 * k + i].sign);
    return truth[0] != truth[1] || truth[1] != truth[2];
}

/* 18q. Costruisce in `figure` il grafico della condizione f nella variabile
 * name, dalla tabella dei segni appena riempita. Se la condizione ha più di
 * MAX_PANELS confronti, o manca la memoria, non lo costruisce. */
static void sign_figure(const Formula *f, int name) {
    const Formula *panel[MAX_PANELS + 1];
    int panels = 0;
    comparisons_collect(f, panel, &panels);
    if (panels == 0 || panels > MAX_PANELS) return;

    /* L'asse x: dal primo all'ultimo punto in cui cambia qualcosa, con un
     * margine; se non ce ne sono, un intervallo attorno allo zero. Non tutti
     * i punti della tabella contano: con i valori assoluti ci sono anche le
     * radici delle scelte di segno che in quel punto non valgono, e
     * comprenderle allargherebbe l'asse fino a schiacciare ciò che si vuole
     * vedere. */
    double low = -5, high = 5;
    int seen = 0;
    for (int k = 0; k < sign_points_count && !trig_on; k++) {
        int matters = point_matters(f, k);
        for (int i = 0; i < panels && !matters; i++) matters = point_edge(panel[i], k) || point_matters(panel[i], k);
        if (!matters) continue;
        if (!seen++) low = point_approx(k);
        high = point_approx(k);
    }
    if (seen) {
        double margin = (high - low) / 2;
        if (margin < 2) margin = 2;
        low -= margin;
        high += margin;
    }

    /* Di un enunciato periodico si disegna un periodo: il giro della
     * tabella, da -pi / g a pi / g, dove t percorre tutta la retta. */
    if (trig_on) {
        Range pi = range_pi();
        high = (pi.low + pi.high) / 2 * (double)trig_scale.den / (double)trig_scale.num;
        low = -high;
    }

    /* I pannelli dei confronti, poi la retta delle soluzioni. */
    figure = pl_figure(6.4, 1.2 + 1.9 * panels);
    if (!figure) return;
    for (int k = 0; k <= panels; k++) {
        char title[64];
        PlAxes *axes = pl_add_axes(figure, k < panels ? 1 : 0.3);
        if (!axes) { pl_close(figure); figure = NULL; return; }
        if (k == panels) { figure_solutions(axes, f, low, high); break; }
        snprintf(title, sizeof title, panels > 1 ? "comparison %d (green: where it holds)" : "green: where the comparison holds", k + 1);
        figure_panel(axes, panel[k], name, low, high, title);
    }
}

/* =============================================================================
 * 18.16 IL VERDETTO DELLA TABELLA E IL SUO CERTIFICATO (18p, 18p-15)
 * ============================================================================
 *
 * Il punto di ingresso della regola 18p. Quali enunciati le spettano
 * (formula_needs_signs(), che usa il capitolo 19 per scegliere la regola) e
 * quali sa trattare; poi decide_by_signs(), che mette in fila i capitoli
 * precedenti: prepara i confronti, trova i punti, riempie e ricontrolla la
 * tabella, scrive la dimostrazione una riga alla volta, e ne trae il
 * verdetto o le soluzioni. Infine la tabella diventa un certificato, che
 * checker.c ricontrolla per conto suo (sign_certify()).
 */

/* Ritorna 1 se nell'enunciato f compare una relazione d'ordine o un
 * quantificatore sui numeri reali, o se f chiede un insieme di soluzioni:
 * ciò che solo la tabella dei segni tratta. */
static int formula_needs_signs(const Formula *f) {
    if (!f) return 0;
    if (f->kind == F_LESS || f->kind == F_LESS_EQ || f->kind == F_SOLVE) return 1;
    if ((f->kind == F_FORALL || f->kind == F_EXISTS) && f->numbers.reals) return 1;
    return formula_needs_signs(f->a) || formula_needs_signs(f->b);
}

/* Ritorna 1 se in f compare un quantificatore. */
static int formula_has_quantifier(const Formula *f) {
    if (!f) return 0;
    return f->kind == F_FORALL || f->kind == F_EXISTS || formula_has_quantifier(f->a) || formula_has_quantifier(f->b);
}

/* Ritorna 1 se in f compare un quantificatore che la tabella dei segni non
 * tratta: ogni quantificatore tranne quelli su un intero, senza altri
 * quantificatori dentro, che descrivono famiglie di soluzioni (18p-13). */
static int formula_bad_quantifier(const Formula *f) {
    if (!f) return 0;
    if (family_owner(f)) return formula_has_quantifier(f->a);
    return f->kind == F_FORALL || f->kind == F_EXISTS || formula_bad_quantifier(f->a) || formula_bad_quantifier(f->b);
}

/* Comincia una tabella dei segni nella variabile di nome name: svuota le
 * colonne, i confronti preparati, gli alberi, gli spazi, le famiglie e le
 * finestre della tabella precedente, e spegne le funzioni goniometriche. Chi
 * chiama sceglie poi la lettera della tabella (sign_x) e, per un enunciato
 * periodico, accende trig_on. La usano decide_by_signs() e la regola del
 * parametro (18t), che prepara una tabella nella lettera del parametro: lo
 * stato da cui partono è così lo stesso. */
static void sign_reset(int name) {
    sign_atoms = sign_polys = sign_nodes = sign_needs = kappas = spaces = family_leaves = windows = 0;
    window_first = window_last = window_turn = 0;
    sign_name = name;
    trig_on = 0;
}

/* Ritorna l'enunciato f senza le negazioni che lo precedono, e mette in
 * *negated 1 se erano in numero dispari: allora f afferma il contrario di
 * ciò che resta. */
static const Formula *without_negations(const Formula *f, int *negated) {
    *negated = 0;
    while (f->kind == F_NOT) { f = f->a; *negated = !*negated; }
    return f;
}

/* Chiude la dimostrazione di un "per ogni" o di un "esiste" deciso da una
 * tabella dei segni, riga per riga, o dalle celle di un parametro: holds
 * dice se è vero ciò che resta dell'enunciato tolte le negazioni
 * (without_negations()), negated se le negazioni erano dispari. Riempie
 * l'esito di *verdict, con il controesempio where se l'enunciato è falso e
 * una riga, o una cella, lo ha mostrato (altrimenti where è NULL). */
static void claim_verdict(Verdict *verdict, int holds, int negated, const char *where) {
    if (negated) proof_add(" The statement is the negation of this claim.");
    proof_add(holds != negated ? " $\\Box$" : " So the statement is false.");
    verdict->outcome = holds != negated ? PROVED : REFUTED;
    verdict->detail = verdict->outcome == REFUTED ? where : NULL;
    verdict->proof = proof_text;
}

/* Scrive in where, di size byte, il valore della variabile name nella riga
 * row della tabella, quella che ha deciso l'enunciato: è il controesempio, o
 * l'esempio, che il verdetto riporta. shown è la lettera della tabella (t in
 * un enunciato periodico) e turn_text il giro in cui si legge la riga
 * (18p-14), come testo da aggiungere al valore; vuoto per il giro 0. */
static void row_where(int row, int name, int shown, const char *turn_text, char *where, size_t size) {
    const SignRow *r = &sign_row[row];
    if (trig_on) {
        /* Il valore della variabile: (2 / g) arctan t. */
        char value[96] = "", factor[48] = "";
        Frac twice = frac_div(frac_int(2), trig_scale);
        if (twice.den != 1) snprintf(factor, sizeof factor, "\\frac{%lld}{%lld}", twice.num, twice.den);
        else if (twice.num != 1) snprintf(factor, sizeof factor, "%lld", twice.num);
        solution_note[0] = '\0';

        /* Un punto della tabella che è un angolo riconosciuto (18p-12) si
         * scrive come tale: x = \frac{\pi}{3}, non 4\arctan(2 - \sqrt{3}). */
        Angle angle = row % 2 ? angle_of_point(row / 2) : (Angle){2, frac_int(0), frac_int(0), 0, 0};
        if (angle.kind != 2) {
            snprintf(where, size, "%c = ", name);
            angle_latex(angle_turn(angle, frac_int(2 * window_turn)), frac_int(0), 0, where, size);
            return;
        }
        if (row % 2) point_latex(row / 2, shown, value, sizeof value); else wide_latex(r->sample, value, sizeof value);
        if (failure || solution_note[0]) snprintf(where, size, "%c = %s\\arctan t%s, con t una radice irrazionale di un polinomio della tabella", name, factor, turn_text);
        else if (strcmp(value, "0") == 0) snprintf(where, size, "%c = %s", name, turn_text[0] ? turn_text + (window_turn < 0 ? 1 : 3) : "0");
        else snprintf(where, size, "%c = %s\\arctan\\left(%s\\right)%s", name, factor, value, turn_text);
        failure = NULL;
    } else if (!r->rational) {
        /* Una radice irrazionale: con i radicali, se ha una scrittura. */
        char low[48], high[48], value[96] = "";
        wide_text(sign_point[row / 2].low, low, sizeof low);
        wide_text(sign_point[row / 2].high, high, sizeof high);
        solution_note[0] = '\0';
        point_latex(row / 2, name, value, sizeof value);
        if (!failure && !solution_note[0]) snprintf(where, size, "%c = %s", name, value);
        else snprintf(where, size, "%c = il numero irrazionale tra %s e %s che annulla un polinomio dell'enunciato", name, low, high);
        failure = NULL;
    } else {
        char value[48];
        wide_text(r->sample, value, sizeof value);
        snprintf(where, size, "%c = %s", name, value);
    }
}

/* 18p-12. Le soluzioni della condizione periodica body nella variabile name,
 * dalla tabella appena riempita, e il loro controllo; pi_truth[] è la verità
 * della condizione nel punto u = pi di ogni giro letto (vedi
 * window_solution()), opening il punto della dimostrazione da cui comincia
 * la tabella, da cancellare se il controllo non riesce. Riempie *verdict.
 *
 * Ciò che si è scritto lo si rilegge, con il lettore del programma, come
 * "esiste k intero tale che ..."; poi in molti valori della variabile,
 * sparsi su più periodi, il testo riletto e la condizione, calcolati con i
 * numeri, devono dire la stessa cosa. È il controllo di tutto il ritorno da
 * t a x: angoli riconosciuti, periodo, estremi compresi o no, e la
 * scrittura. */
static void periodic_solutions(const Formula *body, int name, int pi_truth[][3], size_t opening, Verdict *verdict) {
    if (!(windows ? window_solution(body, name, pi_truth) : trig_solution(body, name, pi_truth[0][0]))) { verdict->reason = failure; failure = NULL; proof_cut(opening); return; }
    static char wrapped[sizeof solution_text + 64];
    const Formula *written = NULL;
    int checked = 0, family = strstr(solution_text, "k\\pi") != NULL, plain = (family || (windows && trig_arcs > 0)) && !solution_note[0];
    if (plain) {
        snprintf(wrapped, sizeof wrapped, family ? "\\exists k \\in \\mathbb{Z}\\ \\left(%s\\right)" : "%s", solution_text);
        written = condition_reread(wrapped);
    }

    /* I valori di prova, in giri di pi di u: sparsi su quasi quattro
     * periodi, oppure, con le finestre, su tutti i giri letti. Poi gli
     * estremi scritti, dove si vede un < al posto di un \le: lì i due conti
     * possono solo dire "uguale, a quanto si vede", e devono dirlo tutti e
     * due. */
    long long first = 2 * window_first - 1, span = 2 * (window_last - window_first) + 2;
    for (int i = 0; i < 97 + 2 * trig_arcs && plain; i++) {
        Range value;
        int edge = i >= 97;
        if (edge) value = angle_range((i - 97) % 2 ? trig_arc[(i - 97) / 2].to : trig_arc[(i - 97) / 2].from);
        else if (windows) value = range_div(range_mul(range_ratio(first * 97000 + span * (1000 * i + 371), 97000), range_pi()), range_ratio(trig_scale.num, trig_scale.den));
        else value = range_div(range_mul(range_ratio(-3700000 + 82291 * i, 1000000), range_pi()), range_ratio(trig_scale.num, trig_scale.den));
        int member = written ? range_truth(written, name, value, edge) : -1, seen = range_truth(body, name, value, edge);
        if (member < 0 || seen < 0) continue;
        checked += !edge;
        if (member == seen) continue;
        unjustified_steps++;
        proof_cut(opening);
        verdict->outcome = NOT_PROVED;
        verdict->reason = "le soluzioni scritte non coincidono con la condizione, calcolata con i numeri";
        return;
    }
    if (plain && checked < 40) { proof_cut(opening); verdict->reason = "non riesco a ricontrollare con i numeri le soluzioni di una condizione periodica"; return; }
    proof_add("Going back to $%c$, the condition holds exactly for $%s$%s. $\\Box$", name, solution_text, family ? ", with $k$ any integer" : "");
    verdict->outcome = SOLVED;
    verdict->detail = solution_text;
    verdict->note = family ? "k intero" : NULL;
    if (solution_note[0]) {
        static char note[sizeof solution_note + 128];
        snprintf(note, sizeof note, "%sradici senza una scrittura con i radicali: le soluzioni scritte non sono state rilette%s", family ? "k intero; " : "", solution_note);
        verdict->note = note;
    }
    verdict->proof = proof_text;
}

/* Le soluzioni della condizione body, non periodica, nella variabile name,
 * dalla tabella appena riempita: sign_solution() le scrive, e
 * solution_reread() le rilegge e le confronta con la tabella. opening è il
 * punto della dimostrazione da cui comincia la tabella, da cancellare se il
 * controllo non riesce. Riempie *verdict. */
static void table_solutions(const Formula *body, int name, size_t opening, Verdict *verdict) {
    int plain = sign_solution(body, name);
    if (failure) { verdict->reason = failure; failure = NULL; proof_cut(opening); return; }
    if (plain && !solution_reread(body, name)) {
        unjustified_steps++;
        proof_cut(opening);
        verdict->outcome = NOT_PROVED;
        verdict->reason = "le soluzioni scritte, rilette, non coincidono con la tabella dei segni";
        return;
    }
    proof_add("Hence the condition holds exactly for $%s$. $\\Box$", solution_text);
    verdict->outcome = SOLVED;
    verdict->detail = solution_text;
    if (solution_note[0]) {
        static char note[sizeof solution_note + 96];
        snprintf(note, sizeof note, "radici senza una scrittura con i radicali: le soluzioni scritte non sono state rilette%s", solution_note);
        verdict->note = note;
    }
    verdict->proof = proof_text;
}

/* 18p. Decide con la tabella dei segni l'enunciato thesis, che deve avere la
 * forma: eventuali negazioni, un quantificatore su una variabile che varia
 * nei reali o nei razionali, una condizione senza altri quantificatori;
 * oppure essere l'insieme delle soluzioni di una condizione così, nei reali.
 * Riempie *verdict, con la dimostrazione scritta e il controesempio o le
 * soluzioni. */
static void decide_by_signs(const Formula *thesis, Verdict *verdict) {
    static char where[160];
    int negated;
    const Formula *q = without_negations(thesis, &negated);
    if ((q->kind != F_FORALL && q->kind != F_EXISTS && q->kind != F_SOLVE) || formula_bad_quantifier(q->a) || q->numbers.integers) {
        verdict->reason = "le relazioni d'ordine e i numeri reali sono trattati solo con una variabile, sui reali o sui razionali";
        return;
    }
    if (q->kind == F_SOLVE && !q->numbers.reals) { verdict->reason = "un insieme di soluzioni si cerca solo nei numeri reali"; return; }
    const Formula *body = q->a;
    const NumberSet *set = &q->numbers;
    int every = q->kind == F_FORALL, solving = q->kind == F_SOLVE, name = q->variable, x = atom_var(name), shown = name;
    static int pi_truth[MAX_TURNS][3];
    char pi_text[64] = "";

    /* 18p-11. Un enunciato con funzioni goniometriche della variabile è
     * periodico: la tabella si fa nella lettera t = tan(g x / 2), che da qui
     * in poi prende il posto della variabile, e il punto g x = pi, dove t
     * non ha un valore, si calcola subito, a parte: lì ogni funzione è un
     * numero, e l'enunciato è vero o falso senza tabella. */
    sign_reset(name);
    trig_bad = 0;
    trig_scale = frac_int(0);
    trig_x = x;
    formula_trig(body);
    failure = NULL;
    if (trig_scale.num != 0) {
        if (trig_bad || !set->reals || set->bounded || set->holes) {
            verdict->reason = "le funzioni goniometriche sono trattate su tutti i numeri reali, con argomenti a x + b \\pi";
            return;
        }
        int constant[MAX_CRITICAL];
        trig_on = 1;
        trig_letter = atom_var(SURD_NAMES + MAX_SURDS + MAX_SPACES);
        trig_root[0] = node_call(FN_ROOT, node_num(2), node_num(2));
        trig_root[1] = node_call(FN_ROOT, node_num(3), node_num(2));
        x = sign_x = trig_letter;
        shown = 't';
        trig_at_pi = 1;
        sign_prepare(body, x);
        trig_at_pi = 0;
        for (int i = 0; i < sign_polys && !failure; i++) {
            if (sign_poly[i].degree > 0) fail(SIGN_SHAPE);
            constant[i] = uni_sign_at(&sign_poly[i], (Wide){0, 1});
        }
        /* 18p-14. Con le finestre i giri da leggere sono più d'uno, e il
         * punto u = pi va calcolato in ognuno. */
        if (windows) { window_first = window_low - 1; window_last = window_high + 1; }
        if (!failure && window_last - window_first >= MAX_TURNS) fail("una condizione periodica ristretta a un intervallo che copre troppi periodi");
        if (failure) { verdict->reason = failure; failure = NULL; trig_on = 0; return; }
        for (window_turn = window_first; window_turn <= window_last; window_turn++) {
            int *at_pi = pi_truth[window_turn - window_first];
            at_pi[0] = sign_truth(body, constant);
            at_pi[1] = body->kind == F_IFF && sign_truth(body->a, constant);
            at_pi[2] = body->kind == F_IFF && sign_truth(body->b, constant);

            /* Il controllo con i numeri, nel punto x = (2j + 1) pi / g. */
            Range pi_point = range_div(range_mul(range_ratio(2 * window_turn + 1, 1), range_pi()), range_ratio(trig_scale.num, trig_scale.den));
            int seen = range_truth(body, name, pi_point, 1);
            if (seen < 0 || seen == at_pi[0]) continue;
            unjustified_steps++;
            trig_on = 0;
            window_turn = 0;
            verdict->outcome = NOT_PROVED;
            verdict->reason = "la verifica indipendente, con i numeri, non conferma il conto nel punto in cui la tangente non è definita";
            return;
        }
        window_turn = 0;
        sign_atoms = sign_polys = sign_nodes = sign_needs = family_leaves = windows = 0;
    } else if (formula_has_quantifier(body)) {
        verdict->reason = "un intero k dentro l'enunciato è trattato solo per scrivere le soluzioni di una condizione periodica, come x = a + k T";
        return;
    }

    /* 18p-1. I confronti; poi i punti che delimitano l'insieme: il suo
     * estremo inferiore e i punti tolti. */
    sign_x = x;

    /* 18p-8. Gli spazi: prima si registrano, guardando tutti i confronti;
     * un errore in questa lettura non conta, lo ridirà il conto vero. In un
     * enunciato periodico non se ne registrano: esponenziali e logaritmi
     * della variabile lì non sono trattati. */
    space_live = !trig_on;
    if (!trig_on) formula_spaces(body);
    space_live = 0;
    failure = NULL;
    sign_prepare(body, x);

    /* I gradini degli spazi, dall'ultimo al primo: i confronti che ne
     * nascono possono contenere solo le lettere degli spazi precedenti, più
     * interni, che così vengono dopo e li trovano già tra le colonne. */
    for (int s = spaces - 1; s >= 0 && !failure; s--) space_process(s, name, x);
    int hole_column[MAX_HOLES], floor_column = failure ? -1 : set_columns(set, hole_column);

    /* 18p-2, 18p-3, 18p-4. I punti, poi la tabella. */
    if (!failure) sign_points(-1);
    int sound = failure ? 1 : sign_table(body, name, set, floor_column, hole_column);
    if (failure) { verdict->reason = failure; failure = NULL; return; }
    if (!sound) {
        unjustified_steps++;
        verdict->outcome = NOT_PROVED;
        verdict->reason = "la verifica indipendente, con i numeri, non conferma la tabella dei segni";
        return;
    }

    /* La dimostrazione scritta: una riga alla volta, da sinistra, finché una
     * decide. Una riga decide quando smentisce un "per ogni" o conferma un
     * "esiste"; per un insieme di soluzioni servono tutte. */
    size_t opening = proof_length;
    int decided = -1, rechecked = 1;
    if (trig_on) {
        /* La sostituzione, detta al lettore: da qui la tabella è in t. */
        char angle[48] = "x";
        if (trig_scale.den != 1) snprintf(angle, sizeof angle, "\\frac{%lld}{%lld} %c", trig_scale.num, trig_scale.den, name);
        else if (trig_scale.num != 1) snprintf(angle, sizeof angle, "%lld %c", trig_scale.num, name);
        else snprintf(angle, sizeof angle, "%c", name);
        proof_add("\\textbf{Substitution.} Put $u = %s$ and $t = \\tan\\frac{u}{2}$: then $\\sin u = \\frac{2t}{1 + t^{2}}$ and "
                  "$\\cos u = \\frac{1 - t^{2}}{1 + t^{2}}$, and every comparison becomes one between expressions in $t$. As $u$ runs "
                  "over one turn, from $-\\pi$ to $\\pi$, $t$ runs once over the whole real line; the point $u = \\pi$, where $t$ has no "
                  "value, is checked apart. The statement has period $2\\pi$ in $u$.\n\n", angle);
    }
    proof_add("\\textbf{Sign table.} Each comparison counts as false where one of its sides has no value. "
              "Its truth can change only where one of these expressions in $%c$ is zero: ", shown);
    for (int i = 0, written = 0; i < sign_polys; i++) {
        /* Solo le colonne di questa tabella: i polinomi nella variabile, e
         * le differenze x - k. */
        if (sign_space[i] >= 0 || (sign_kappa[i] < 0 && sign_poly[i].degree <= 0)) continue;
        proof_add("%s$", written++ ? ", " : "");
        if (sign_kappa[i] >= 0) proof_add("%c - %s", shown, kappa[sign_kappa[i]].text); else put_uni(&sign_poly[i], shown);
        proof_add("$");
    }
    proof_add(". At each of these points and on every interval between two consecutive ones the signs are constant, so one value of $%c$ decides each.\n\\begin{itemize}\n", shown);
    /* Un giro alla volta (18p-14): senza finestre il giro è uno solo. */
    for (window_turn = window_first; window_turn <= window_last && decided < 0; window_turn++) {
        const int *at_pi = pi_truth[window_turn - window_first];
        char turn_text[64] = "";
        if (window_turn) {
            /* Il giro, come multiplo di pi da aggiungere al valore di x. */
            snprintf(turn_text, sizeof turn_text, window_turn < 0 ? " - " : " + ");
            angle_latex((Angle){0, frac_int(window_turn < 0 ? -2 * window_turn : 2 * window_turn), frac_int(0), 0, 0}, frac_int(0), 0, turn_text, sizeof turn_text);
        }
        if (windows)
            proof_add("\\item[] With $u$ from $%lld\\pi$ to $%lld\\pi$%s:\n", 2 * window_turn - 1, 2 * window_turn + 1,
                      window_turn == window_first ? ", and in the same way on every turn before" : window_turn == window_last ? ", and in the same way on every turn after" : "");
        for (int row = 0; row < sign_rows && decided < 0; row++) {
            const SignRow *r = &sign_row[row];
            if (!r->inside) continue;
            int truth = sign_truth(body, r->sign);
            proof_add("\\item ");
            put_row(row, shown);
            if (body->kind == F_IFF)
                proof_add(": the left side is %s, the right side is %s.\n", sign_truth(body->a, r->sign) ? "true" : "false", sign_truth(body->b, r->sign) ? "true" : "false");
            else
                proof_add(": the condition %s.\n", truth ? "holds" : "fails");

            /* Una riga razionale che il conto con i numeri non ha potuto
             * confermare lascia l'enunciato non deciso: un risultato non
             * verificato non è un risultato. */
            if (r->must && !r->confirmed) rechecked = 0;
            if (solving || truth == every) continue;
            decided = row;
            row_where(row, name, shown, turn_text, where, sizeof where);
        }

        /* In un enunciato periodico, il punto lasciato fuori dalla tabella. */
        if (trig_on && decided < 0) {
            pi_text[0] = '\0';
            angle_latex((Angle){0, frac_int(2 * window_turn + 1), frac_int(0), 0, 0}, frac_int(0), 0, pi_text, sizeof pi_text);
            proof_add("\\item $%c = %s$, where $t$ has no value", name, pi_text);
            if (body->kind == F_IFF) proof_add(": the left side is %s, the right side is %s.\n", at_pi[1] ? "true" : "false", at_pi[2] ? "true" : "false");
            else proof_add(": the condition %s.\n", at_pi[0] ? "holds" : "fails");
            if (!solving && at_pi[0] != every) {
                decided = sign_rows;
                snprintf(where, sizeof where, "%c = %s", name, pi_text);
            }
        }
    }
    window_turn = 0;
    proof_add("\\end{itemize}\n");
    if (!rechecked) {
        proof_cut(opening);
        verdict->reason = "non riesco a ricontrollare con i numeri una riga della tabella dei segni: numeri troppo grandi, o una radice dentro un'altra";
        return;
    }
    verdict->method = "con la tabella dei segni";

    /* Il grafico, se serve: della condizione, o del primo membro quando
     * l'enunciato la confronta con il suo risultato. Si fa solo se il conto
     * con i numeri ha confermato ogni riga che deve confermare (must), anche
     * quelle dopo la riga che ha deciso. Di una condizione periodica si
     * disegna un periodo; di una ristretta a un intervallo (18p-14), che si
     * legge un giro alla volta, il grafico non c'è ancora. */
    int drawable = figures_wanted && !windows;
    for (int row = 0; row < sign_rows; row++)
        if (sign_row[row].inside && sign_row[row].must && !sign_row[row].confirmed) drawable = 0;
    if (drawable) sign_figure(body->kind == F_IFF && !solving ? body->a : body, name);

    /* Un insieme di soluzioni: lo si legge dalla tabella, e ciò che si è
     * scritto lo si rilegge. Se una radice non ha una scrittura con i
     * radicali la rilettura non si può fare, e il verdetto lo dice. */
    if (solving && trig_on) { periodic_solutions(body, name, pi_truth, opening, verdict); return; }
    if (solving) { table_solutions(body, name, opening, verdict); return; }

    /* Il verdetto. "Per ogni" è vero se nessuna riga lo smentisce, "esiste"
     * se una lo conferma; una negazione davanti li rovescia. */
    int holds = every ? decided < 0 : decided >= 0;
    if (decided >= 0) proof_add("At this value the condition %s.", every ? "fails" : "holds");
    else proof_add("The condition %s on every row, hence for every value of $%c$ in the set.", every ? "holds" : "fails", shown);
    claim_verdict(verdict, holds, negated, decided >= 0 ? where : NULL);
}

/* 18p-15. IL CERTIFICATO DELLA TABELLA
 *
 * La tabella appena usata da decide_by_signs() diventa un certificato per
 * checker.c (capitolo 12 di checker.c): la condizione, ciò che si afferma, i
 * polinomi che fanno da fattori, e le righe con la verità che la tabella vi
 * ha trovato. Il verificatore non si fida di nulla di questo: ricava da capo
 * i polinomi della condizione e controlla che siano prodotti dei fattori,
 * riconta con Sturm le radici di ogni fattore, ricalcola la verità di ogni
 * riga e ne trae il verdetto.
 *
 * Che cosa si scrive.
 *
 *   - La condizione, con dentro l'insieme su cui varia la variabile quando
 *     non è tutto R o tutto Q: "per ogni x > 0, C" è "per ogni x, x > 0
 *     implica C"; "esiste x > 0 con C" e le soluzioni in R \setminus \{1\}
 *     sono "x > 0 e C", "x \neq 1 e C". Restano due insiemi, reals e
 *     rationals, ed è ciò che il verificatore conosce.
 *   - Ciò che si afferma: per ogni e esiste con la verità dell'enunciato
 *     senza le negazioni davanti, oppure le soluzioni, rilette dal testo
 *     scritto con il lettore del programma: il certificato dice ciò che il
 *     testo dice, non ciò che il motore pensava di scrivere.
 *   - I fattori: x - r per ogni punto razionale, e ogni elemento della base
 *     (18p-4) di grado almeno due, anche senza radici reali. Ogni polinomio
 *     della tabella ne è un prodotto (base_insert()).
 *   - Le righe, con il campione di ogni intervallo, il punto razionale o
 *     l'intervallo che isola una radice, e la verità della condizione.
 *
 * Le risposte. Accettato: il verdetto porta il certificato. Respinto: il
 * motore e il verificatore non sono d'accordo, quindi nel dubbio non è
 * dimostrato, e il passo conta tra quelli che non hanno superato il
 * controllo. Non controllabile, o un enunciato che la notazione non sa dire
 * (radici, esponenziali, logaritmi, funzioni goniometriche, soluzioni con
 * una radice che ha solo un nome): il verdetto resta, e dice perché il
 * certificato manca. */

/* Ritorna 1 se l'espressione node si scrive nella notazione delle tabelle
 * dei segni di checker.c: interi, la variabile name, + - * /, il meno,
 * potenze con un intero scritto all'esponente e valori assoluti. */
static int sign_node_plain(const Node *node, int name) {
    switch (node->kind) {
    case N_NUM: return 1;
    case N_VAR: return node->name == name;
    case N_NEG: return sign_node_plain(node->a, name);
    case N_ADD: case N_SUB: case N_MUL: case N_DIV:
        return sign_node_plain(node->a, name) && sign_node_plain(node->b, name);
    case N_POW:
        return (node->b->kind == N_NUM || (node->b->kind == N_NEG && node->b->a->kind == N_NUM)) && sign_node_plain(node->a, name);
    case N_CALL:
        return node->op == FN_ABS && sign_node_plain(node->a, name);
    default:
        return 0;
    }
}

/* Ritorna 1 se la condizione f, senza quantificatori, è fatta di confronti
 * che sign_node_plain() accetta. */
static int sign_formula_plain(const Formula *f, int name) {
    switch (f->kind) {
    case F_EQUAL: case F_DISTINCT: case F_LESS: case F_LESS_EQ:
        return sign_node_plain(f->left, name) && sign_node_plain(f->right, name);
    case F_AND: case F_OR: case F_IMPLIES: case F_IFF:
        return sign_formula_plain(f->a, name) && sign_formula_plain(f->b, name);
    case F_NOT:
        return sign_formula_plain(f->a, name);
    default:
        return 0;
    }
}

/* Scrive la condizione f, senza quantificatori, nella notazione dei
 * certificati. > e \ge sono già < e \le con i membri scambiati.
 *
 * Warning: si appoggia all'ordine di FormulaKind (parser.c): prima i quattro
 * confronti, da F_EQUAL a F_LESS_EQ, poi i connettivi fino a F_NOT. Se
 * cambia, cambia anche qui. */
static void cert_formula(const Formula *f) {
    static const char *const words[] = {[F_EQUAL] = "=", [F_DISTINCT] = "neq", [F_LESS] = "<", [F_LESS_EQ] = "<=",
                                        [F_AND] = "and", [F_OR] = "or", [F_IMPLIES] = "implies", [F_IFF] = "iff", [F_NOT] = "not"};
    if (f->kind > F_NOT) { certificate_broken = 1; return; }
    cert_add("(%s ", words[f->kind]);
    if (f->kind <= F_LESS_EQ) {
        cert_node(f->left);
        cert_add(" ");
        cert_node(f->right);
    } else {
        cert_formula(f->a);
        if (f->b) {
            cert_add(" ");
            cert_formula(f->b);
        }
    }
    cert_add(")");
}

/* Scrive il razionale v; uno che non sta in 64 bit non ha scrittura. */
static void cert_wide(Wide v) {
    if (v.num > LLONG_MAX || v.num < -LLONG_MAX || v.den > LLONG_MAX) certificate_broken = 1;
    else if (v.den == 1) cert_add("%lld", (long long)v.num);
    else cert_add("(/ %lld %lld)", (long long)v.num, (long long)v.den);
}

/* Scrive il polinomio p, che non è nullo, nella lettera name: la somma dei
 * termini dal grado più alto, "(+ primo (+ secondo ...))". */
static void cert_uni(const Uni *p, int name) {
    int terms = 0, written = 0;
    for (int i = 0; i <= p->degree; i++) terms += p->c[i] != 0;
    for (int i = p->degree; i >= 0; i--) {
        __int128 c = p->c[i];
        if (c == 0) continue;
        if (c > LLONG_MAX || c < -LLONG_MAX) certificate_broken = 1;
        if (++written < terms) cert_add("(+ ");
        if (i > 0 && c != 1) cert_add("(* %lld ", (long long)c);
        if (i == 0) cert_add("%lld", (long long)c);
        if (i > 1) cert_add("(^ ");
        if (i > 0) cert_letter(name);
        if (i > 1) cert_add(" %d)", i);
        if (i > 0 && c != 1) cert_add(")");
        if (written < terms) cert_add(" ");
    }
    for (int i = 1; i < terms; i++) cert_add(")");
}

/* Scrive in certificate_text il certificato della tabella con cui
 * decide_by_signs() ha deciso thesis, con il verdetto *verdict; ritorna
 * NULL, oppure il motivo per cui il certificato non c'è. */
static const char *sign_certificate(const Formula *thesis, const Verdict *verdict) {
    int negated;
    const Formula *q = without_negations(thesis, &negated);
    const Formula *body = q->a, *written = NULL;
    const NumberSet *set = &q->numbers;
    int name = q->variable, every = q->kind == F_FORALL, solving = q->kind == F_SOLVE;
    if (!sign_formula_plain(body, name))
        return "la notazione dei certificati della tabella dei segni ha solo frazioni di polinomi e valori assoluti, "
               "non radici, esponenziali, logaritmi o funzioni goniometriche";

    /* Le soluzioni, rilette dal testo; i due testi senza estremi sono le
     * parole all e none. */
    int all = solving && strncmp(solution_text, "\\forall", 7) == 0, none = solving && strncmp(solution_text, "\\nexists", 8) == 0;
    if (solving && solution_note[0]) return "le soluzioni scritte nominano una radice che non ha una scrittura con i radicali";
    if (solving && !all && !none) {
        written = condition_reread(solution_text);
        if (!written) return "le soluzioni scritte non si rileggono";
    }

    /* I posti, in sign_poly[], dei polinomi x - a dell'insieme: già nella
     * tabella, set_columns() li ritrova. */
    int hole_column[MAX_HOLES], floor_column = set_columns(set, hole_column);

    /* La variabile, l'insieme, la condizione con dentro l'insieme. */
    int terms = set->bounded + set->holes;
    certificate_length = 0;
    certificate_broken = 0;
    cert_signs = 1;
    cert_add("certificate signs\nvariable ");
    cert_letter(name);
    cert_add("\ndomain %s\ncondition ", set->reals ? "reals" : "rationals");
    if (terms) cert_add(every ? "(implies " : "(and ");
    for (int i = 0; i < terms; i++) {
        if (i + 1 < terms) cert_add("(and ");
        if (i == 0 && set->bounded) {
            cert_add(set->strict ? "(< %lld " : "(<= %lld ", set->low);
            cert_letter(name);
        } else {
            cert_add("(neq ");
            cert_letter(name);
            cert_add(" ");
            cert_frac(set->hole[i - set->bounded]);
        }
        cert_add(i + 1 < terms ? ") " : ")");
    }
    for (int i = 1; i < terms; i++) cert_add(")");
    if (terms) cert_add(" ");
    cert_formula(body);
    if (terms) cert_add(")");

    /* Ciò che si afferma: la verità dell'enunciato senza le negazioni, o le
     * soluzioni. */
    if (!solving) cert_add("\nclaim %s %s", every ? "forall" : "exists", (verdict->outcome == PROVED) != negated ? "true" : "false");
    else if (written) { cert_add("\nclaim solve\nsolution "); cert_formula(written); }
    else cert_add("\nclaim solve\nsolution %s", all ? "all" : "none");

    /* I fattori: prima x - r per i punti razionali, poi gli elementi della
     * base di grado almeno due; place[k] è il numero dell'elemento k. */
    int place[2 * MAX_CRITICAL], factors = 0;
    for (int k = 0; k < sign_points_count; k++) {
        if (!sign_point[k].exact) continue;
        Uni linear = {1, {-sign_point[k].low.num, sign_point[k].low.den}};
        cert_add("\nfactor ");
        cert_uni(&linear, name);
        factors++;
    }
    for (int k = 0; k < sign_bases; k++) {
        place[k] = 0;
        if (sign_base[k].degree < 2) continue;
        cert_add("\nfactor ");
        cert_uni(&sign_base[k], name);
        place[k] = ++factors;
    }

    /* Le righe, con la verità della condizione: quella del corpo, e
     * l'insieme come è scritto nella condizione. */
    for (int row = 0; row < sign_rows; row++) {
        const SignRow *r = &sign_row[row];
        const Critical *point = &sign_point[row / 2];
        int member = row_in_set(r->sign, set, floor_column, hole_column), truth = sign_truth(body, r->sign);
        if (row % 2 == 0) { cert_add("\ninterval "); cert_wide(r->sample); }
        else if (point->exact) { cert_add("\npoint "); cert_wide(point->low); }
        else {
            /* Una radice irrazionale è di un elemento senza radici
             * razionali, quindi di grado almeno due: ha il suo posto. */
            if (!place[point->element]) certificate_broken = 1;
            cert_add("\nroot %d ", place[point->element]);
            cert_wide(point->low);
            cert_add(" ");
            cert_wide(point->high);
        }
        cert_add(" %s", (every ? !member || truth : member && truth) ? "true" : "false");
    }
    cert_add("\nend\n");
    cert_signs = 0;
    return certificate_broken ? "la tabella ha numeri troppo grandi per la notazione dei certificati, o è troppo lunga" : NULL;
}

/* 18p-15. Fa ricontrollare a checker.c il verdetto *verdict che
 * decide_by_signs() ha dato su thesis, e lo aggiorna con la risposta: vedi
 * "Le risposte" in testa a 18p-15. */
static void sign_certify(const Formula *thesis, Verdict *verdict) {
    static char problem[512];
    if (verdict->outcome != PROVED && verdict->outcome != REFUTED && verdict->outcome != SOLVED) return;
    const char *why = sign_certificate(thesis, verdict), *text = certificate_text;
    if (!why) {
        CkAnswer answer = ck_check(&text, &why);
        if (answer == CK_ACCEPTED) { verdict->certificate = certificate_text; return; }

        /* Respinto: nel dubbio non è dimostrato, e il grafico, che illustra
         * la tabella, non si mostra. */
        if (answer == CK_REJECTED) {
            unjustified_steps++;
            snprintf(problem, sizeof problem, "il verificatore indipendente ha respinto il certificato della tabella dei segni: %s", why);
            *verdict = (Verdict){NOT_PROVED, 0, 0, 0, problem, NULL, NULL, NULL, NULL, NULL};
            if (figure) { pl_close(figure); figure = NULL; }
            return;
        }
        snprintf(problem, sizeof problem, "il verificatore non sa controllarlo, %s", why);
        why = problem;
    }

    /* Il motivo si scrive nella riga del verdetto, e per un insieme di
     * soluzioni sta prima del ": " dopo il quale vengono le soluzioni: chi
     * le legge (gli script di tools/fuzz/) le cerca lì. Per questo nel
     * motivo i due punti diventano virgole. */
    if (why != problem) snprintf(problem, sizeof problem, "%s", why);
    for (char *colon = problem; (colon = strchr(colon, ':')) != NULL;) *colon = ',';
    verdict->reason = problem;
}

/* =============================================================================
 * 18.17 UN PARAMETRO (18t): LA PROIEZIONE E LE CELLE
 * ============================================================================
 *
 * Questo capitolo e i due che seguono sono la regola 18t. Qui il metodo e la
 * sua prima metà: i polinomi nelle due lettere, la proiezione (18t-a) e le
 * celle della retta del parametro (18t-b). Il capitolo 18.18 decide ogni
 * cella e ne scrive le soluzioni (18t-c, 18t-d, 18t-e), il 18.19 ricontrolla
 * ciò che si consegna (18t-f, 18t-g, 18t-h) e dà il verdetto.
 *
 * 18t. DUE VARIABILI REALI: UN PARAMETRO
 *
 * A che cosa serve. Sono gli esercizi "con il parametro" dei libri di scuola:
 *
 *     \forall a \in \mathbb{R}\ \{x \in \mathbb{R} \mid x^{2} - 4ax \le 0\}
 *
 * chiede di risolvere la disequazione in x per ogni valore di a, e la
 * risposta è un elenco di casi: per a < 0 le soluzioni sono 4a \le x \le 0,
 * per a = 0 la sola x = 0, per a > 0 sono 0 \le x \le 4a. Le forme trattate
 * sono tre:
 *
 *   - una verifica: un quantificatore sul parametro e, dentro, una
 *     combinazione di confronti nel solo parametro e di enunciati "per ogni
 *     x" o "esiste x"; per esempio \forall a\ \forall x\ (...), oppure
 *     \forall k\ ((\forall x\ (x^{2} - 2kx + 7 > 0)) \iff -\sqrt{7} < k < \sqrt{7});
 *   - i valori del parametro: \{k \in \mathbb{R} \mid \forall x\ (...)\};
 *   - le soluzioni con il parametro, come nell'esempio qui sopra.
 *
 * L'idea. Fissato il parametro a un numero resta un enunciato in una
 * variabile, e quello lo decide la tabella dei segni (18p). I numeri sono
 * infiniti, ma basta provarne pochi: la retta del parametro si divide in
 * "celle", punti e intervalli aperti, e dentro una cella la risposta non
 * cambia. È come guardare una parabola che si sposta al variare di a: finché
 * non cambia verso, e le sue intersezioni con l'asse non nascono, non
 * spariscono e non si scavalcano, la disequazione ha "le stesse" soluzioni,
 * solo spostate. È la scomposizione cilindrica di Collins, con una sola
 * lettera da eliminare.
 *
 *   18t-a. La proiezione: quali valori del parametro separano le celle. Ogni
 *          confronto che contiene x è una frazione di polinomi nelle due
 *          lettere; numeratori, denominatori e divisori si leggono come
 *          polinomi in x i cui coefficienti sono polinomi nel parametro. I
 *          valori critici sono le radici reali di:
 *            a1. il coefficiente direttivo di ognuno;
 *            a2. per ogni f, il primo psc_k(f, f') che non è il polinomio
 *                nullo, con k = 0, 1, ... (f' è la derivata rispetto a x);
 *            a3. per ogni coppia f, g, il primo psc_k(f, g) che non è il
 *                polinomio nullo;
 *            a4. i polinomi dei confronti nel solo parametro, preparati
 *                come per una tabella dei segni nella lettera del parametro
 *                (18p-1, 18p-7).
 *          psc_k è il coefficiente principale del sottorisultante numero k
 *          (subresultant_lead()); psc_0 è il risultante, e psc_0(f, f') è, a
 *          meno del coefficiente direttivo, il discriminante.
 *
 *          Perché bastano. Su un intervallo aperto del parametro in cui
 *          nessuno di quei polinomi si annulla:
 *            - ogni f ha sempre lo stesso grado in x (a1);
 *            - il massimo comun divisore di f e f' ha sempre lo stesso
 *              grado, il primo k con psc_k diverso da zero (a2): quindi f ha
 *              sempre lo stesso numero di radici complesse distinte. Le
 *              radici di un polinomio di grado costante dipendono con
 *              continuità dai coefficienti; se il loro numero non cambia non
 *              possono fondersi né separarsi, e una radice reale non può
 *              diventare complessa, perché prima dovrebbe coincidere con la
 *              sua coniugata. Le radici reali di f sono dunque funzioni
 *              continue del parametro, sempre le stesse e nello stesso
 *              ordine;
 *            - il massimo comun divisore di f e g ha sempre lo stesso grado
 *              (a3): una radice di f e una di g che coincidono in un punto
 *              coincidono in tutto l'intervallo, e due diverse restano
 *              diverse.
 *          Le radici reali di tutti i polinomi sono quindi curve continue
 *          che non si toccano: tagliano la striscia sopra l'intervallo in
 *          fasce, e in ogni fascia e su ogni curva ogni polinomio ha un
 *          segno costante. I segni che x incontra sono gli stessi per ogni
 *          valore del parametro nell'intervallo, e con loro la verità di
 *          "per ogni x" e di "esiste x" (G. E. Collins, Quantifier
 *          elimination for real closed fields by cylindrical algebraic
 *          decomposition, 1975, teoremi 4 e 5). I valori critici non hanno
 *          bisogno di teoria: ognuno è una cella di un punto solo.
 *
 *   18t-b. Le celle: i valori critici in ordine, trovati come i punti di una
 *          tabella dei segni nella lettera del parametro (sign_points()), e
 *          gli intervalli tra due consecutivi, ognuno con un razionale
 *          scelto al suo interno.
 *
 *   18t-c. Una cella, una decisione. Al posto del parametro si scrive il
 *          valore della cella: il razionale scelto, oppure il valore
 *          critico. Uno irrazionale si scrive con la formula risolutiva, se
 *          è radice di un polinomio di secondo grado; altrimenti la regola
 *          rinuncia. Ciò che resta è un enunciato in una variabile, e lo
 *          decide 18p.
 *
 *   18t-d. Il verdetto. "Per ogni a" è vero se lo è in ogni cella, "esiste
 *          a" se lo è in una; i valori del parametro richiesti sono le celle
 *          in cui la condizione vale, scritte come le soluzioni di 18p.
 *
 *   18t-e. Le soluzioni con il parametro. In ogni cella si risolve in x con
 *          il valore della cella. In una cella che è un punto il parametro è
 *          un numero, e gli estremi delle soluzioni anche. In un intervallo
 *          gli estremi vanno scritti in funzione del parametro: sono radici
 *          dei polinomi di 18t-a, e quelle di un polinomio di primo o di
 *          secondo grado in x hanno una formula (i "candidati",
 *          candidates_build()). Ogni estremo trovato con il valore scelto si
 *          riconosce nel solo candidato che lì ha quel valore: il confronto
 *          è esatto, e in un intervallo due candidati diversi non coincidono
 *          mai, per a2 e a3. Le celle vicine con le stesse soluzioni si
 *          scrivono insieme.
 *
 * I controlli indipendenti, oltre a quelli che ogni decisione di 18p porta
 * con sé, sono tre.
 *
 *   18t-f. Ciò che si consegna si rilegge. Il testo delle soluzioni viene
 *          riletto dal lettore del programma come una condizione W. Nel
 *          valore di ogni cella, e in altri due razionali di ogni
 *          intervallo, la tabella dei segni deve dimostrare che la
 *          condizione di partenza e W hanno le stesse soluzioni in x; per i
 *          valori del parametro, W deve valere esattamente nelle celle
 *          trovate. Un estremo riconosciuto male, o un < al posto di un
 *          \le, qui si vedono.
 *
 *   18t-g. La griglia. Le celle poggiano sulla teoria di 18t-a: se alla
 *          proiezione mancasse un valore critico, dentro una cella la verità
 *          potrebbe cambiare senza che il valore scelto lo mostri. Per
 *          questo l'enunciato si guarda anche in valori del parametro presi
 *          senza guardare le celle: tutti i quarti da -PARAM_REACH / 4 a
 *          PARAM_REACH / 4, e i PARAM_GRID razionali più semplici, che vi
 *          aggiungono i terzi. E lo si guarda in due modi. Con la tabella
 *          dei segni, che per quel valore del parametro decide per ogni x:
 *          è lo stesso metodo delle celle, ma in valori che la proiezione
 *          non ha scelto. E con il conto diretto sui numeri
 *          (sign_holds_at()) in PARAM_GRID valori di x, che non usa né la
 *          proiezione né la tabella. Un valore della griglia che smentisce
 *          la cella in cui cade ferma il verdetto. Non è una seconda
 *          dimostrazione, perché la griglia è finita: è un controllo contro
 *          gli errori del programma. Non vede un errore della proiezione che
 *          si mostra solo in un valore del parametro isolato, irrazionale, o
 *          oltre PARAM_REACH / 4: quello lo cerca 18t-h.
 *
 *   18t-h. La proiezione, ricontrollata con un altro conto. È il controllo
 *          su cui poggiano i verdetti che dipendono da tutte le celle (un
 *          "per ogni a" dimostrato, un "esiste a" smentito, ogni RISOLTO):
 *          param_project() registra ogni polinomio che calcola, con la sua
 *          provenienza (ProjectionItem), compresi i psc_k trovati nulli
 *          prima del primo che non lo è, e projection_sound() controlla:
 *            h1. i pezzi: le parti in x di ogni polinomio di param_poly[],
 *                rimoltiplicate per le potenze di x, lo ricompongono; da
 *                loro, e non dall'elenco della proiezione, si ricava quali
 *                polinomi a1, a2 e a3 servono, con il grado in x letto da
 *                capo;
 *            h2. i valori: ogni polinomio che serve si calcola in D + 1
 *                valori razionali del parametro, dove D limita il suo grado,
 *                con un altro algoritmo (il determinante dei numeri, con
 *                l'eliminazione di Bareiss, invece dello sviluppo di Laplace
 *                sui polinomi); il registrato deve esserne un multiplo per
 *                una costante positiva, e un psc_k dichiarato nullo deve
 *                annullarsi in tutti i D + 1. Due polinomi di grado al più D
 *                che coincidono in D + 1 punti sono lo stesso polinomio;
 *            h3. il contenimento: le radici reali distinte di ogni polinomio
 *                che serve, contate con Sturm, sono tante quante i valori
 *                critici che lo annullano, decisi con un conto esatto: tutte
 *                sono quindi valori critici;
 *            h4. le celle: i valori critici sono in ordine e separati; uno
 *                irrazionale è la sola radice del suo polinomio di secondo
 *                grado nel suo intervallo, ed è la radice che il valore della
 *                cella scrive; il razionale di ogni intervallo vi sta dentro.
 *          Con h1-h4 il ragionamento di 18t-a vale per le celle trovate: in
 *          ogni intervallo nessun polinomio della proiezione si annulla, e
 *          il valore scelto decide per tutto l'intervallo. Una discordanza è
 *          un errore del motore: il verdetto non c'è, e unjustified_steps
 *          sale. Un conto che esce dai 128 bit, o un grado oltre
 *          PROJECTION_POINTS - 1, lascia l'enunciato non dimostrato, con il
 *          suo motivo. Che cosa non copre: un polinomio che param_collect()
 *          non ha messo nell'elenco, o che eval() ha calcolato male, perché
 *          h1 parte da param_poly[]; i polinomi a4 dei confronti nel solo
 *          parametro, che prepara sign_prepare() come in una tabella in una
 *          lettera sola; la decisione in ogni cella, che è di 18p con i suoi
 *          controlli; la teoria di 18t-a. E h3 e h4 contano le radici con la
 *          catena di Sturm di 18p-3 (sturm_build()), la stessa che ha
 *          trovato i valori critici: un errore lì sarebbe comune ai due
 *          conti. Ai verdetti che poggiano su una cella sola (un
 *          controesempio, un "esiste a" con il suo valore) non serve, e non
 *          li ferma.
 *
 * Che cosa resta fuori, e il verdetto lo dice: più di due lettere reali una
 * dentro l'altra; insiemi diversi da \mathbb{R}; radici, valori assoluti,
 * logaritmi, potenze e funzioni goniometriche in un confronto che contiene
 * la variabile; gradi in x oltre MAX_PARAM_DEGREE; valori critici
 * irrazionali che non sono radici di un polinomio di secondo grado;
 * soluzioni i cui estremi non sono radici di polinomi di primo o di secondo
 * grado in x. Un enunciato con il parametro non ha grafico: il disegno di
 * 18q è quello di una variabile sola.
 *
 * Il limite su radici e valori assoluti vale anche per una radice o un valore
 * assoluto del solo parametro, quando sta in un confronto con la variabile:
 * la regola scrive soluzioni come 2 - \sqrt{4 - k^{2}} < x, e sa rileggerle
 * un valore del parametro alla volta, ma lo stesso testo dentro un enunciato
 * da verificare non lo tratta. Per trattarlo la proiezione dovrebbe ricevere,
 * di ogni confronto P + Q \sqrt{R} con R nel solo parametro, i polinomi P, Q
 * e P^2 - Q^2 R, come 18p-7 fa in una variabile, e R tra le colonne del
 * parametro; e di un valore assoluto i due polinomi che nascono dai due
 * segni del suo argomento. Andrebbe in param_collect().
 */

/* I limiti di questa regola. Stanno qui, e non nel capitolo 1 con gli altri,
 * perché la regola resti tutta in un blocco.
 *
 * Warning: MAX_MINOR è il doppio di MAX_PARAM_DEGREE, le righe del risultante
 * di due polinomi di quel grado: se alzi il grado alza anche MAX_MINOR, e
 * guarda quanto costa lo sviluppo di minor_determinant(). */
#define MAX_PARAM_POLYS 24   /* polinomi nelle due lettere di un enunciato con il parametro */
#define MAX_PARAM_DEGREE 4   /* il loro grado massimo nella variabile */
#define MAX_MINOR 8          /* righe del determinante più grande: quello di due polinomi di grado 4 */
#define MAX_PARAM_POINTS 48  /* valori critici del parametro */
#define MAX_CANDIDATES 16    /* estremi scritti in funzione del parametro (18t-e) */
#define PARAM_REACH 32       /* la griglia del parametro (18t-g): i quarti da -PARAM_REACH / 4 a PARAM_REACH / 4 */
#define PARAM_GRID 24        /* i razionali più semplici, aggiunti alla griglia del parametro e dati alla variabile nel conto diretto (18t-g) */
#define CELL_TEXT 512        /* lunghezza delle soluzioni di una cella */
#define PARAM_TEXT 4096      /* lunghezza delle soluzioni scritte */
#define PROJECTION_POINTS 64 /* valori del parametro in cui 18t-h calcola un polinomio della proiezione: il suo grado più uno, al più */

/* Quanti polinomi della proiezione si registrano, al più (18t-h): per ogni
 * polinomio il coefficiente direttivo e fino a MAX_PARAM_DEGREE - 1 psc_k con
 * la derivata, per ogni coppia fino a MAX_PARAM_DEGREE psc_k. Sono al più
 * MAX_PARAM_DEGREE per ognuno dei P polinomi e delle P (P - 1) / 2 coppie. */
#define MAX_PROJECTION (MAX_PARAM_DEGREE * MAX_PARAM_POLYS * (MAX_PARAM_POLYS + 1) / 2)

/* I messaggi per ciò che la regola non tratta. */
static const char *const PARAM_FORM =
    "con due lettere reali sono trattati un parametro e una variabile, ognuno su tutto \\mathbb{R}: non tre lettere una dentro l'altra, né altri insiemi";
static const char *const PARAM_SHAPE =
    "con un parametro i confronti che contengono la variabile devono essere tra espressioni razionali nelle due lettere: niente radici, valori assoluti, logaritmi, potenze o funzioni goniometriche";
static const char *const PARAM_DEGREE = "con un parametro i polinomi nella variabile sono trattati fino al quarto grado, e con coefficienti non troppo grandi";
static const char *const PARAM_ROOT = "un valore critico del parametro è un numero irrazionale che non so scrivere con una radice quadrata";
static const char *const PARAM_WRITE = "non so scrivere le soluzioni in funzione del parametro";
static const char *const PARAM_INNER = "la tabella dei segni non decide l'enunciato in un valore del parametro";

/* Ritorna 1 se set è tutto \mathbb{R}, senza estremi né punti tolti. */
static int numbers_all_reals(const NumberSet *set) { return set->reals && !set->bounded && set->holes == 0; }

/* Ritorna il nodo dell'intero v, anche negativo. Il lettore non produce mai
 * un N_NUM negativo, e chi legge gli alberi ci conta: -3 è N_NEG di 3. */
static Node *node_integer(long long v) { return v < 0 ? node_new(N_NEG, node_num(-v), NULL) : node_num(v); }

/* Ritorna il nodo del razionale v. Annota un errore se v non sta nei 64 bit
 * dei numeri di un albero. */
static Node *node_rational(Wide v) {
    if (v.num >= COEF_LIMIT || v.num <= -COEF_LIMIT || v.den >= COEF_LIMIT) { fail(SIGN_LIMIT); return node_num(0); }
    Node *top = node_integer((long long)v.num);
    return v.den == 1 ? top : node_new(N_DIV, top, node_num((long long)v.den));
}

/* 18t-c. Ritorna una copia della condizione f in cui la variabile name è
 * sostituita dall'espressione value, che viene condivisa e non copiata. È
 * formula_substitute() del lettore (capitolo 17) con una lettera sola. name
 * non è legata dentro f: lo garantisce formula_check(), che non ammette due
 * significati per una lettera. */
static Formula *formula_with(const Formula *f, int name, Node *value) {
    const Node *const to[1] = {value};
    return formula_substitute(f, &name, to, 1);
}

/* I polinomi nelle due lettere dell'enunciato in corso (18t-a): numeratori,
 * denominatori e divisori dei confronti che contengono la variabile.
 * param_var[i] è l'atomo della variabile del polinomio i: quella del
 * quantificatore interno in cui sta il suo confronto. param_part[i] sono i
 * suoi coefficienti come polinomio in quella variabile, dal termine noto a
 * quello di grado param_degree[i]; li riempie param_project(). */
static Poly param_poly[MAX_PARAM_POLYS], param_part[MAX_PARAM_POLYS][MAX_PARAM_DEGREE + 1];
static int param_var[MAX_PARAM_POLYS], param_degree[MAX_PARAM_POLYS];
static int param_polys;

/* Aggiunge all'elenco il polinomio p, che viene dal conto di un confronto
 * razionale nel parametro (atomo a) e nella variabile (atomo x). Annota un
 * errore se p contiene altro: un'altra lettera, un esponente non intero, un
 * coefficiente complesso.
 *
 * p può avere esponenti negativi, perché rat_make() porta al numeratore un
 * denominatore di un solo termine: 3/a diventa 3 a^{-1}. Allora lo si
 * moltiplica per la potenza che li toglie, e la lettera che stava a
 * denominatore entra nell'elenco come polinomio a sé: dove si annulla il
 * confronto non ha valore. Un numero non ha radici e non entra; un polinomio
 * già presente, anche a meno di un fattore costante, non si ripete. */
static void param_add(Poly p, int a, int x) {
    const int letter[2] = {a, x};
    long long lowest[2] = {0, 0};
    for (int t = 0; t < p.count; t++) {
        const Term *term = &p.term[t];
        if (term->coef.im.num != 0) { fail(PARAM_SHAPE); return; }
        for (int f = 0; f < term->mono.count; f++) {
            const Factor *factor = &term->mono.factor[f];
            int which = factor->atom == a ? 0 : 1;
            if ((factor->atom != a && factor->atom != x) || factor->exp.den != 1) { fail(PARAM_SHAPE); return; }
            if (factor->exp.num < lowest[which]) lowest[which] = factor->exp.num;
        }
    }
    for (int i = 0; i < 2 && !failure; i++) {
        if (lowest[i] == 0) continue;
        Term power;
        power.coef = num_int(1);
        power.mono = mono_atom(letter[i], frac_int(-lowest[i]));
        p = poly_mul(p, poly_term(power));
        param_add(rat_atom(letter[i]).num, a, x);
    }
    if (failure || poly_is_constant(p)) return;
    for (int i = 0; i < param_polys; i++)
        if (param_var[i] == x && poly_proportional(p, param_poly[i])) return;
    if (param_polys == MAX_PARAM_POLYS) { fail("troppi polinomi diversi in un enunciato con il parametro"); return; }
    param_poly[param_polys] = p;
    param_var[param_polys++] = x;
}

/* 18t-a. Legge i confronti della condizione f, che sta sotto il
 * quantificatore sul parametro di nome a_name. x_name è la lettera del
 * quantificatore interno in cui f si trova, 0 se f sta fuori da tutti.
 *
 * Un confronto senza la variabile va tra quelli della tabella nella lettera
 * del parametro (a4): lo prepara sign_prepare(), con tutto ciò che 18p sa
 * trattare in una lettera sola. Di un confronto con la variabile entrano
 * nell'elenco numeratore, denominatore e divisori della differenza dei due
 * membri. Annota un errore per un quantificatore dentro un altro, per un
 * insieme che non è \mathbb{R}, e per un confronto con la variabile che non
 * è razionale. */
static void param_collect(const Formula *f, int a_name, int x_name) {
    if (failure) return;
    if (f->kind == F_FORALL || f->kind == F_EXISTS || f->kind == F_SOLVE) {
        if (x_name || !numbers_all_reals(&f->numbers)) { fail(PARAM_FORM); return; }
        param_collect(f->a, a_name, f->variable);
        return;
    }
    if (f->kind != F_EQUAL && f->kind != F_DISTINCT && f->kind != F_LESS && f->kind != F_LESS_EQ) {
        param_collect(f->a, a_name, x_name);
        if (f->b) param_collect(f->b, a_name, x_name);
        return;
    }
    int a = atom_var(a_name);
    if (!x_name || (!node_uses_letter(f->left, x_name) && !node_uses_letter(f->right, x_name))) { sign_prepare(f, a); return; }
    if (!term_is_rational(f->left) || !term_is_rational(f->right)) { fail(PARAM_SHAPE); return; }

    /* Il conto, con le due lettere libere e l'elenco dei divisori acceso. */
    int x = atom_var(x_name);
    condition_count = conditions_lost = undefined = 0;
    env_count = 0;
    conditions_on = 1;
    Rat d = rat_add(eval(f->left), eval(f->right), 1);
    conditions_on = 0;

    /* Una divisione per un'espressione che è zero ovunque: il confronto non
     * ha valore per nessuna coppia di numeri, quindi è sempre falso e non
     * ha polinomi da dare. */
    if (failure && undefined) { failure = NULL; undefined = 0; return; }
    if (conditions_lost) fail("troppe condizioni di esistenza in un confronto");
    if (failure) return;
    param_add(d.num, a, x);
    param_add(d.den, a, x);
    for (int i = 0; i < condition_count && !failure; i++)
        for (int j = 0; j < conditions[i].count; j++) param_add(conditions[i].factor[j], a, x);
}

/* La matrice di cui subresultant_lead() calcola il determinante: minor_size
 * righe e colonne di polinomi nel parametro. */
static Poly minor_entry[MAX_MINOR][MAX_MINOR];
static int minor_size;

/* Ritorna il determinante della matrice fatta dalle righe di minor_entry[]
 * da `row` in giù e dalle colonne non ancora usate, quelle con il bit a zero
 * in `used`.
 *
 * Sviluppo di Laplace lungo la prima riga: la somma, sulle colonne libere c,
 * dell'elemento della riga in c per il determinante di ciò che resta tolte
 * la riga e la colonna, con il segno più se c è la prima, la terza, ...
 * delle colonne libere e meno altrimenti. Gli elementi nulli si saltano: le
 * matrici di subresultant_lead() sono quasi vuote, e così i prodotti da
 * calcolare sono pochi anche con otto righe. */
static Poly minor_determinant(int row, unsigned used) {
    if (row == minor_size) return poly_const(num_int(1));
    Poly sum = {0, NULL};
    for (int c = 0, place = 0; c < minor_size && !failure; c++) {
        if (used >> c & 1) continue;
        if (minor_entry[row][c].count) sum = poly_add(sum, poly_mul(minor_entry[row][c], minor_determinant(row + 1, used | 1u << c)), place % 2);
        place++;
    }
    return sum;
}

/* Ritorna psc_k(f, g), il coefficiente principale del sottorisultante numero
 * k di f e g: polinomi nella variabile di grado m e n, con i coefficienti
 * f[0..m] e g[0..n] che sono polinomi nel parametro, e 0 <= k <= min(m, n).
 * Annota un errore se la matrice ha più di MAX_MINOR righe.
 *
 * Che cos'è. Si scrivono in righe i coefficienti, dalla potenza più alta
 * x^(m+n-k-1) in giù, dei polinomi
 *
 *     x^(n-k-1) f, ..., x f, f, x^(m-k-1) g, ..., x g, g:
 *
 * sono m + n - 2k righe. psc_k è il determinante delle prime m + n - 2k
 * colonne. Con k = 0 è la matrice di Sylvester, e psc_0 il risultante.
 *
 * A che cosa serve. Dove i coefficienti direttivi di f e di g non sono zero,
 * il grado del massimo comun divisore di f e g è il più piccolo k per cui
 * psc_k non è zero. Per k = 0 è il fatto noto che il risultante si annulla
 * esattamente quando f e g hanno una radice in comune: una combinazione
 * u f + v g = 0 con u di grado minore di n e v di grado minore di m è una
 * relazione tra le righe. Per k qualsiasi la stessa matrice dice se esistono
 * u e v, di gradi minori di n - k e m - k, con u f + v g di grado minore di
 * k: succede esattamente quando il massimo comun divisore ha grado più di k
 * (teorema fondamentale dei sottorisultanti; Collins 1975, teorema 2). */
static Poly subresultant_lead(const Poly *f, int m, const Poly *g, int n, int k) {
    minor_size = m + n - 2 * k;
    if (minor_size > MAX_MINOR) { fail(PARAM_DEGREE); return (Poly){0, NULL}; }
    for (int r = 0; r < minor_size; r++) {
        /* Le prime n - k righe sono x^s f con s = n - k - 1, ..., 0; le
         * altre x^s g con s = m - k - 1, ..., 0. */
        int upper = r < n - k, shift = upper ? n - k - 1 - r : m - k - 1 - (r - (n - k));
        for (int c = 0; c < minor_size; c++) {
            /* La colonna c è la potenza x^(m+n-k-1-c), e il suo coefficiente
             * in x^s f è quello di x^(m+n-k-1-c-s) in f. */
            int power = m + n - k - 1 - c - shift;
            minor_entry[r][c] = power < 0 || power > (upper ? m : n) ? (Poly){0, NULL} : upper ? f[power] : g[power];
        }
    }
    return minor_determinant(0, 0);
}

/* Un polinomio della proiezione (18t-a) con la sua provenienza, come
 * param_project() lo ha calcolato: è il dato che 18t-h ricontrolla con un
 * altro conto. Gli elementi si registrano nell'ordine in cui si calcolano,
 * anche quelli che sono un numero o il polinomio nullo. */
typedef struct {
    int kind;    /* 1: il coefficiente direttivo di f (a1); 2: psc_k(f, f')
                    (a2); 3: psc_k(f, g) (a3) */
    int first;   /* il posto di f in param_poly[] */
    int second;  /* a3: il posto di g in param_poly[]; -1 altrimenti */
    int k;       /* a2, a3: il numero del sottorisultante; 0 per a1 */
    Uni value;   /* il polinomio nel parametro, moltiplicato per un intero
                    positivo (uni_from_poly()): ha le stesse radici. Il
                    polinomio nullo se param_first() lo ha trovato nullo */
} ProjectionItem;

/* I polinomi della proiezione dell'enunciato in corso, registrati da
 * param_column(). */
static ProjectionItem param_item[MAX_PROJECTION];
static int param_items;

/* Registra il polinomio p, che è nel solo parametro (atomo a), con la sua
 * provenienza (kind, first, second, k: come in ProjectionItem), e lo mette
 * tra le colonne della tabella nella lettera del parametro: le sue radici
 * sono valori critici. Un numero non ne ha, e tra le colonne non entra; ma
 * si registra, come il polinomio nullo, perché 18t-h veda tutto ciò che la
 * proiezione ha calcolato. */
static void param_column(Poly p, int a, int kind, int first, int second, int k) {
    Uni column;
    int shift;
    if (failure) return;
    if (!uni_from_poly(p, a, &column, &shift) || shift) { fail(PARAM_DEGREE); return; }
    if (param_items == MAX_PROJECTION) { fail("troppi polinomi nella proiezione del parametro"); return; }
    param_item[param_items++] = (ProjectionItem){kind, first, second, k, column};
    if (column.degree > 0) sign_column(column);
}

/* 18t-a2, 18t-a3. Mette tra le colonne il primo psc_k(f, g), k = 0, 1, ...,
 * che non è il polinomio nullo, e registra con lui quelli nulli che lo
 * precedono; kind, first e second dicono da dove vengono f e g, come in
 * ProjectionItem. Se sono tutti nulli fino a min(m, n) - 1, il massimo comun
 * divisore ha grado min(m, n) dovunque i coefficienti direttivi non si
 * annullano, e non c'è nulla da aggiungere. La memoria di ogni determinante
 * torna all'arena appena il polinomio è tra le colonne e tra i registrati,
 * che ne tengono una copia. */
static void param_first(const Poly *f, int m, const Poly *g, int n, int a, int kind, int first, int second) {
    for (int k = 0; k < (m < n ? m : n) && !failure; k++) {
        size_t before = arena_used;
        Poly lead = subresultant_lead(f, m, g, n, k);
        int zero = lead.count == 0;
        param_column(lead, a, kind, first, second, k);
        arena_used = before;
        if (!zero) return;
    }
}

/* 18t-a. La proiezione dei polinomi di param_poly[]: riempie param_part[] e
 * param_degree[], e mette tra le colonne della tabella nella lettera del
 * parametro (atomo a) i polinomi a1, a2 e a3, registrandoli in param_item[].
 * Le coppie si fanno solo tra polinomi nella stessa variabile: radici in
 * variabili diverse non hanno un ordine da conservare.
 *
 * Warning: projection_sound() (18t-h) ricava da sé quali polinomi la
 * proiezione deve contenere, con le stesse regole a1, a2 e a3. Se cambi le
 * regole qui, cambiale anche lì, o il ricontrollo fermerà ogni verdetto (un
 * polinomio che manca) oppure non vedrà ciò che hai aggiunto. */
static void param_project(int a) {
    for (int i = 0; i < param_polys && !failure; i++) {
        param_degree[i] = poly_split(param_poly[i], param_var[i], param_part[i], MAX_PARAM_DEGREE);
        if (param_degree[i] < 0) fail(PARAM_DEGREE);
    }
    for (int i = 0; i < param_polys && !failure; i++) {
        const Poly *f = param_part[i];
        Poly derivative[MAX_PARAM_DEGREE + 1];
        int m = param_degree[i];
        param_column(f[m], a, 1, i, -1, 0);
        for (int j = 1; j <= m; j++) derivative[j - 1] = poly_mul(f[j], poly_const(num_int(j)));
        param_first(f, m, derivative, m - 1, a, 2, i, -1);
        for (int j = i + 1; j < param_polys; j++)
            if (param_var[j] == param_var[i]) param_first(f, m, param_part[j], param_degree[j], a, 3, i, j);
    }
}

/* Un valore critico del parametro: la copia di un punto della tabella dei
 * segni nella lettera del parametro, fatta prima che le decisioni sulle
 * celle riusino quella tabella. */
typedef struct {
    Critical at;    /* il punto: il razionale at.low, oppure la sola radice di
                       `element` tra at.low e at.high (at.element non vale più) */
    Uni element;    /* punto irrazionale: il polinomio di secondo grado, senza
                       radici razionali, di cui è radice */
    int smaller;    /* punto irrazionale: 1 se è la più piccola delle due radici */
    char text[96];  /* com'è scritto, in LaTeX */
} ParamPoint;

/* Una cella della retta del parametro (18t-b). La cella 2 i è l'intervallo
 * prima del valore critico i, la cella 2 i + 1 quel valore; l'ultima è
 * l'intervallo dopo l'ultimo valore critico: come le righe di una tabella
 * dei segni. */
typedef struct {
    Wide sample;           /* il razionale in cui si decide la cella: il punto,
                              o un valore dell'intervallo. Non vale per un
                              punto irrazionale */
    Node *value;           /* il valore della cella come espressione, da
                              scrivere al posto del parametro; sta nell'arena */
    int truth;             /* verifiche e valori del parametro: 1 se nella cella
                              la condizione vale */
    int kind;              /* soluzioni con il parametro: 0 se nella cella non
                              ci sono soluzioni, 2 se lo è ogni x, 1 se sono
                              quelle scritte in text */
    char text[CELL_TEXT];  /* kind == 1: le soluzioni nella variabile, in LaTeX */
} ParamCell;

/* I valori critici e le celle dell'enunciato in corso, riempiti da
 * param_cells_build(). */
static ParamPoint param_point[MAX_PARAM_POINTS];
static int param_points;
static ParamCell param_cell[2 * MAX_PARAM_POINTS + 1];
static int param_cells;

/* Ritorna, come espressione, una radice del polinomio di secondo grado q,
 * che ha due radici reali irrazionali e coefficienti sotto 2^30 (lo ha già
 * controllato quadratic_latex()): la più piccola se smaller è 1. È la
 * formula risolutiva, (-b -+ sqrt(b^2 - 4ac)) / 2a, con il denominatore reso
 * positivo come in quadratic_latex(): così il segno meno dà la più piccola. */
static Node *quadratic_node(const Uni *q, int smaller) {
    long long a = (long long)q->c[2], b = (long long)q->c[1], c = (long long)q->c[0];
    Node *root = node_call(FN_ROOT, node_num(b * b - 4 * a * c), node_num(2));
    return node_new(N_DIV, node_new(smaller ? N_SUB : N_ADD, node_integer(a < 0 ? b : -b), root), node_num(a < 0 ? -2 * a : 2 * a));
}

/* 18t-b. Trova i valori critici del parametro di nome name, dalle colonne
 * già preparate, e riempie param_point[] e param_cell[]. Annota un errore
 * se sono troppi, o se uno è irrazionale e non ha una scrittura con una
 * radice quadrata: lì la cella non si saprebbe decidere. */
static void param_cells_build(int name) {
    sign_points(-1);
    if (!failure && sign_points_count > MAX_PARAM_POINTS) fail("troppi valori critici del parametro");
    if (failure) return;
    param_points = sign_points_count;
    param_cells = 2 * param_points + 1;
    for (int k = 0; k < param_points; k++) {
        ParamPoint *p = &param_point[k];
        p->at = sign_point[k];
        p->text[0] = solution_note[0] = '\0';
        point_latex(k, name, p->text, sizeof p->text);
        if (failure || p->at.exact) continue;
        if (p->at.element < 0 || solution_note[0]) { fail(PARAM_ROOT); return; }

        /* La più piccola delle due radici è il primo dei due punti di
         * questo elemento, come in point_latex(). */
        p->element = sign_base[p->at.element];
        p->smaller = point_is_first_root(k);
    }

    /* Il valore di ogni cella. Per un intervallo è scelto come in
     * sign_table() (interval_sample()): tra i due punti che lo chiudono,
     * oppure un intero oltre l'unico che c'è. */
    for (int c = 0; c < param_cells && !failure; c++) {
        ParamCell *cell = &param_cell[c];
        const ParamPoint *point = c % 2 ? &param_point[c / 2] : NULL;
        const ParamPoint *before = c >= 2 ? &param_point[c / 2 - 1] : NULL, *after = c / 2 < param_points ? &param_point[c / 2] : NULL;
        cell->sample = (Wide){0, 1};
        if (point && !point->at.exact) { cell->value = quadratic_node(&point->element, point->smaller); continue; }
        cell->sample = point ? point->at.low : interval_sample(before ? &before->at : NULL, after ? &after->at : NULL);
        cell->value = node_rational(cell->sample);
    }
}

/* Ritorna il numero della cella in cui cade il razionale v. Rispetto a un
 * valore critico irrazionale, v sta a sinistra se non supera l'estremo
 * inferiore dell'intervallo che lo isola, a destra se non sta sotto quello
 * superiore; dentro l'intervallo lo dice il segno del polinomio, che lì ha
 * quella sola radice, semplice: a sinistra della radice ha il segno che ha
 * nell'estremo inferiore. */
static int param_cell_of(Wide v) {
    for (int k = 0; k < param_points; k++) {
        const ParamPoint *p = &param_point[k];
        int side;
        if (p->at.exact) side = wide_cmp(v, p->at.low);
        else if (wide_cmp(v, p->at.low) <= 0) side = -1;
        else if (wide_cmp(v, p->at.high) >= 0) side = 1;
        else side = uni_sign_at(&p->element, v) == uni_sign_at(&p->element, p->at.low) ? -1 : 1;
        if (side <= 0) return side < 0 ? 2 * k : 2 * k + 1;
    }
    return 2 * param_points;
}

/* Ritorna un altro razionale dell'intervallo che è la cella c, oltre a
 * quello scelto: a destra del valore scelto se right è 1, a sinistra
 * altrimenti (18t-f). */
static Wide cell_beside(int c, int right) {
    const ParamPoint *before = c >= 2 ? &param_point[c / 2 - 1] : NULL, *after = c / 2 < param_points ? &param_point[c / 2] : NULL;
    Wide sample = param_cell[c].sample;
    if (right) return after ? wide_between(sample, after->at.low) : wide_add(sample, (Wide){1, 1});
    return before ? wide_between(before->at.high, sample) : wide_add(sample, (Wide){-1, 1});
}

/* =============================================================================
 * 18.18 UN PARAMETRO: LE CELLE DECISE E SCRITTE
 * ============================================================================
 *
 * Una cella alla volta: con il suo valore al posto del parametro l'enunciato
 * ha una variabile sola, e lo decide la tabella dei segni (18t-c,
 * table_truth(), closed_truth()). Poi ciò che si scrive: le condizioni sul
 * parametro che dicono "in queste celle" (18t-d), e le soluzioni in x con
 * gli estremi in funzione del parametro, riconosciuti tra i candidati che
 * danno le formule di primo e di secondo grado (18t-e).
 */

/* Il controesempio dell'ultimo enunciato che table_truth() ha trovato falso,
 * com'è scritto da decide_by_signs(); vuoto se non ne ha dato uno. */
static char param_inner[160];

/* Decide con la tabella dei segni (18p) l'enunciato q: un quantificatore su
 * una variabile reale, con una condizione senza altri quantificatori.
 * Ritorna 1 se è vero, 0 se è falso; -1 se la tabella non lo decide, e
 * allora mette in *verdict il suo esito e il suo motivo, che non è mai
 * NULL. Lascia in param_inner il controesempio, se ce n'è uno.
 *
 * Il testo che decide_by_signs() aggiunge alla dimostrazione viene tolto:
 * la dimostrazione di questa regola dice che cosa succede in ogni cella,
 * non come 18p lo ha trovato. */
static int table_truth(const Formula *q, Verdict *verdict) {
    Verdict inner = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    size_t opening = proof_length;
    param_inner[0] = '\0';

    /* Un errore già annotato, come la memoria finita mentre si copiava
     * l'enunciato, va guardato qui: decide_by_signs() riparte da capo, lo
     * cancellerebbe e deciderebbe un enunciato copiato a metà. */
    if (failure) {
        verdict->outcome = UNSUPPORTED;
        verdict->reason = failure;
        failure = NULL;
        return -1;
    }
    decide_by_signs(q, &inner);
    proof_cut(opening);
    if (inner.outcome == REFUTED && inner.detail) snprintf(param_inner, sizeof param_inner, "%s", inner.detail);
    if (inner.outcome == PROVED || inner.outcome == REFUTED) return inner.outcome == PROVED;
    verdict->outcome = inner.outcome;
    verdict->reason = inner.reason ? inner.reason : PARAM_INNER;
    return -1;
}

/* Decide il confronto tra numeri f, come table_truth(): lo mette sotto un
 * "per ogni" di comodo, la cui lettera è quella del parametro, name, che
 * dopo la sostituzione non compare più. Il "controesempio" di un confronto
 * tra numeri non dice nulla, e non resta in param_inner. */
static int number_truth(Formula *f, int name, Verdict *verdict) {
    Formula all;
    memset(&all, 0, sizeof all);
    all.kind = F_FORALL;
    all.a = f;
    all.variable = name;
    all.numbers.reals = 1;
    int truth = table_truth(&all, verdict);
    param_inner[0] = '\0';
    return truth;
}

/* Le due condizioni costanti di closed_reduce(): la falsa e la vera. Si
 * riconoscono dall'indirizzo e non hanno contenuto: non arrivano mai a una
 * tabella dei segni. */
static Formula closed_constant[2];

/* Ritorna la negazione della condizione f, che può essere una delle due
 * costanti. */
static Formula *closed_not(Formula *f) {
    if (f == &closed_constant[0] || f == &closed_constant[1]) return &closed_constant[f == &closed_constant[0]];
    return formula_node(F_NOT, f, NULL, f->start);
}

/* Semplifica la condizione f, senza quantificatori, in cui il parametro di
 * nome name è già sostituito da un numero e la sola lettera rimasta è la
 * variabile x_name: ogni confronto senza la variabile è un confronto tra
 * numeri, lo si decide subito (number_truth()) e lo si toglie, con le
 * regole dei connettivi ("falso e A" è falso, "vero e A" è A, ...). Ritorna
 * la condizione che resta, in cui ogni confronto contiene la variabile,
 * oppure una delle due costanti; NULL se un confronto tra numeri non si
 * riesce a decidere, con l'esito e il motivo in *verdict.
 *
 * A che cosa serve. Un elenco di casi sul parametro, come quello che questa
 * regola scrive, è fatto per lo più di confronti nel solo parametro: con il
 * parametro uguale a un numero resta in piedi un caso solo. Senza questo
 * passo la tabella dei segni li riceverebbe tutti, e un elenco di sette
 * casi supera da solo il numero di confronti che una tabella tiene
 * (MAX_SIGN_ATOMS): è successo, e le soluzioni giuste di una richiesta con
 * due condizioni non si lasciavano rileggere. */
static Formula *closed_reduce(Formula *f, int x_name, int name, Verdict *verdict) {
    Formula *no = &closed_constant[0], *yes = &closed_constant[1];
    if (f->kind == F_EQUAL || f->kind == F_DISTINCT || f->kind == F_LESS || f->kind == F_LESS_EQ) {
        if (node_uses_letter(f->left, x_name) || node_uses_letter(f->right, x_name)) return f;
        int truth = number_truth(f, name, verdict);
        return truth < 0 ? NULL : truth ? yes : no;
    }
    Formula *a = closed_reduce(f->a, x_name, name, verdict), *b = a && f->b ? closed_reduce(f->b, x_name, name, verdict) : NULL;
    if (!a || (f->b && !b)) return NULL;
    switch (f->kind) {
    case F_NOT:
        return a == f->a ? f : closed_not(a);
    case F_AND:
        if (a == no || b == no) return no;
        if (a == yes || b == yes) return a == yes ? b : a;
        break;
    case F_OR:
        if (a == yes || b == yes) return yes;
        if (a == no || b == no) return a == no ? b : a;
        break;
    case F_IMPLIES:
        if (a == no || b == yes) return yes;
        if (a == yes) return b;
        if (b == no) return closed_not(a);
        break;
    default:
        /* "Se e solo se": con un lato vero è l'altro, con un lato falso la
         * sua negazione. */
        if (a == yes || b == yes) return a == yes ? b : a;
        if (a == no || b == no) return closed_not(a == no ? b : a);
        break;
    }
    return a == f->a && b == f->b ? f : formula_node(f->kind, a, b, f->start);
}

/* 18t-c. Decide l'enunciato f, in cui il parametro di nome name è già
 * sostituito da un numero: una combinazione di confronti tra numeri e di
 * enunciati "per ogni x" o "esiste x". Ritorna 1 se è vero, 0 se è falso;
 * -1 se la tabella dei segni non lo decide, e allora mette in *verdict il
 * suo esito e il suo motivo.
 *
 * I connettivi si calcolano dalle parti. Un confronto tra numeri e un
 * quantificatore li decide 18p; della condizione di un quantificatore si
 * tolgono prima i confronti tra numeri (closed_reduce()), e se non resta
 * altro la sua verità è quella della costante rimasta, perché la variabile
 * varia su un insieme che non è vuoto. */
static int closed_truth(Formula *f, int name, Verdict *verdict) {
    if (f->kind == F_NOT) {
        int inner = closed_truth(f->a, name, verdict);
        return inner < 0 ? -1 : !inner;
    }
    if (f->kind == F_AND || f->kind == F_OR || f->kind == F_IMPLIES || f->kind == F_IFF) {
        int a = closed_truth(f->a, name, verdict), b = a < 0 ? -1 : closed_truth(f->b, name, verdict);
        if (b < 0) return -1;
        return f->kind == F_AND ? a && b : f->kind == F_OR ? a || b : f->kind == F_IMPLIES ? !a || b : a == b;
    }
    if (f->kind != F_FORALL && f->kind != F_EXISTS) return number_truth(f, name, verdict);
    Formula reduced = *f;
    reduced.a = closed_reduce(f->a, f->variable, name, verdict);
    if (!reduced.a) return -1;
    if (reduced.a == &closed_constant[0] || reduced.a == &closed_constant[1]) {
        param_inner[0] = '\0';
        return reduced.a == &closed_constant[1];
    }
    return table_truth(&reduced, verdict);
}

/* Aggiunge a text, di size byte, un pezzo di un insieme di numeri nella
 * lettera name, con le convenzioni di sign_solution(): un intervallo tra gli
 * estremi scritti in low e high, una semiretta se uno dei due è NULL, un
 * punto solo se low e high sono lo stesso puntatore. low_closed e
 * high_closed dicono se l'estremo è compreso. I due non sono mai NULL
 * insieme: "ogni numero" non è un pezzo, e chi chiama lo scrive da sé. */
static void piece_latex(char *text, size_t size, int name, const char *low, int low_closed, const char *high, int high_closed) {
    if (low == high) text_add(text, size, "%c = %s", name, low);
    else if (!low) text_add(text, size, "%c %s %s", name, high_closed ? "\\le" : "<", high);
    else if (!high) text_add(text, size, "%c %s %s", name, low_closed ? "\\ge" : ">", low);
    else text_add(text, size, "%s %s %c %s %s", low, low_closed ? "\\le" : "<", name, high_closed ? "\\le" : "<", high);
}

/* 18t-d. Aggiunge a text, di size byte, la condizione sul parametro di nome
 * name che dice "in una delle celle da first a last", che sono consecutive
 * e non sono tutte. Una cella dispari è un punto, quindi un tratto che
 * comincia o finisce lì lo comprende; se comincia o finisce su un
 * intervallo, il punto accanto resta fuori. */
static void cells_latex(int first, int last, int name, char *text, size_t size) {
    const char *low = first == 0 ? NULL : param_point[first % 2 ? first / 2 : first / 2 - 1].text;
    const char *high = last == param_cells - 1 ? NULL : param_point[last / 2].text;
    piece_latex(text, size, name, low, first % 2, high, last % 2);
}

/* Scrive nella dimostrazione di quale cella si parla: il valore critico,
 * oppure l'intervallo con il razionale scelto al suo interno. */
static void put_cell(int c, int name) {
    if (c % 2) { proof_add("$%c = %s$", name, param_point[c / 2].text); return; }
    proof_add("$");
    if (c >= 2) proof_add("%s < ", param_point[c / 2 - 1].text);
    proof_add("%c", name);
    if (c / 2 < param_points) proof_add(" < %s", param_point[c / 2].text);
    proof_add("$ (for instance $%c = ", name);
    put_wide(param_cell[c].sample);
    proof_add("$)");
}

/* Un estremo delle soluzioni scritto in funzione del parametro (18t-e): vale
 *
 *     (top + sigma * outside * sqrt(radicand)) / bottom,
 *
 * dove top, radicand e bottom sono polinomi nel parametro a coefficienti
 * interi. Invariante: bottom non è il polinomio nullo e ha il coefficiente
 * direttivo positivo; se sigma è 0 la radice non c'è, e outside e radicand
 * non contano; altrimenti outside è positivo. */
typedef struct {
    Uni top, bottom, radicand;
    int sigma;          /* 0, oppure il segno davanti alla radice: 1 o -1 */
    long long outside;  /* il numero intero davanti alla radice */
} Candidate;

/* I candidati dell'enunciato in corso, riempiti da candidates_build(). */
static Candidate param_candidate[MAX_CANDIDATES];
static int param_candidates;

/* Ritorna p moltiplicato per l'intero k. */
static Uni uni_scaled(const Uni *p, __int128 k) {
    Uni out = *p;
    for (int i = 0; i <= out.degree; i++)
        if (__builtin_mul_overflow(out.c[i], k, &out.c[i])) fail(SIGN_LIMIT);
    uni_trim(&out);
    return out;
}

/* Ritorna il valore di p nel razionale x: lo schema di Horner, con le
 * frazioni a 128 bit. */
static Wide uni_value(const Uni *p, Wide x) {
    Wide value = {0, 1};
    for (int i = p->degree; i >= 0 && !failure; i--) value = wide_add(wide_mul(value, x), (Wide){p->c[i], 1});
    return value;
}

/* Scrive il polinomio p, che è nel solo atomo a con coefficienti razionali,
 * come content per *out: *out a coefficienti interi senza divisori comuni e
 * con il coefficiente direttivo positivo, content razionale. Il polinomio
 * nullo dà *out nullo e content zero. Ritorna 0, annotando un errore, se p
 * non ha questa forma o se i numeri sono troppo grandi.
 *
 * uni_from_poly() dà già un multiplo intero di p; il rapporto tra p e *out
 * si legge poi su un coefficiente solo, quello di grado più alto. */
static int uni_exact(Poly p, int a, Uni *out, Wide *content) {
    int shift;
    *content = (Wide){0, 1};
    if (!uni_from_poly(p, a, out, &shift) || shift) { fail(PARAM_DEGREE); return 0; }
    if (out->degree < 0) return 1;
    uni_primitive(out);
    if (out->c[out->degree] < 0) uni_negate(out);
    for (int t = 0; t < p.count; t++) {
        const Term *term = &p.term[t];
        __int128 below;
        if ((term->mono.count ? term->mono.factor[0].exp.num : 0) != out->degree) continue;
        if (__builtin_mul_overflow(out->c[out->degree], (__int128)term->coef.re.den, &below)) { fail(SIGN_LIMIT); return 0; }
        *content = wide_make(term->coef.re.num, below);
    }
    return 1;
}

/* Ritorna il polinomio scale per u nell'atomo a. */
static Poly poly_from_uni(const Uni *u, int a, Frac scale) {
    Poly p = {0, NULL};
    for (int i = 0; i <= u->degree && !failure; i++) {
        Term term;
        if (u->c[i] == 0) continue;
        term.coef = num_frac(frac_mul(scale, frac_make(u->c[i], 1)));
        term.mono.count = 0;
        if (i > 0) term.mono = mono_atom(a, frac_int(i));
        p = poly_add(p, poly_term(term), 0);
    }
    return p;
}

/* Cerca il polinomio a coefficienti interi di cui p è il quadrato: se i
 * conti tornano lo mette in *root, con il coefficiente direttivo positivo, e
 * ritorna 1. Il polinomio nullo è il quadrato di se stesso.
 *
 * Se p = r^2 con r di grado e, il coefficiente di grado e + i di p è
 *
 *     2 r_e r_i + (la somma degli r_j r_{e+i-j} con i < j < e),
 *
 * in cui oltre a r_i compaiono solo coefficienti di r più alti. Quindi r_e è
 * la radice del coefficiente direttivo, e scendendo ogni r_i si ricava con
 * una divisione, che deve essere esatta. I coefficienti di p sotto il grado
 * e qui non vengono guardati: un "sì" va confermato da chi chiama,
 * moltiplicando. */
static int uni_square_root(const Uni *p, Uni *root) {
    int e = p->degree / 2;
    root->degree = p->degree < 0 ? -1 : e;
    memset(root->c, 0, sizeof root->c);
    if (p->degree < 0) return 1;
    if (p->degree % 2 || p->c[p->degree] < 0 || p->c[p->degree] >= (__int128)1 << 126) return 0;
    root->c[e] = wide_isqrt(p->c[p->degree]);
    if (root->c[e] * root->c[e] != p->c[p->degree]) return 0;
    for (int i = e - 1; i >= 0; i--) {
        __int128 rest = p->c[e + i], part;
        for (int j = i + 1; j < e; j++)
            if (__builtin_mul_overflow(root->c[j], root->c[e + i - j], &part) || __builtin_sub_overflow(rest, part, &rest)) return 0;
        if (rest % (2 * root->c[e]) != 0) return 0;
        root->c[i] = rest / (2 * root->c[e]);
    }
    return 1;
}

/* Aggiunge c ai candidati, se non c'è già: due polinomi diversi possono
 * avere una radice in comune, e allora la stessa formula nasce due volte. */
static void candidate_add(const Candidate *c) {
    for (int i = 0; i < param_candidates; i++) {
        const Candidate *other = &param_candidate[i];
        if (other->sigma != c->sigma || !uni_equal(&other->top, &c->top) || !uni_equal(&other->bottom, &c->bottom)) continue;
        if (!c->sigma || (other->outside == c->outside && uni_equal(&other->radicand, &c->radicand))) return;
    }
    if (param_candidates == MAX_CANDIDATES) { fail(PARAM_WRITE); return; }
    param_candidate[param_candidates++] = *c;
}

/* Aggiunge ai candidati la frazione num / den di polinomi nel parametro
 * (atomo a), ridotta ai minimi termini: così due scritture della stessa
 * funzione sono lo stesso candidato, e (4a + 4a) / 2 si legge 4a. den non è
 * il polinomio nullo. */
static void candidate_ratio(Poly num, Poly den, int a) {
    Candidate c;
    Uni top, bottom, common, rest;
    Wide above, below;
    memset(&c, 0, sizeof c);
    c.radicand.degree = -1;
    if (!uni_exact(num, a, &top, &above) || !uni_exact(den, a, &bottom, &below)) return;
    if (top.degree < 0) {
        /* Zero, qualunque sia il denominatore. */
        c.top = top;
        c.bottom = (Uni){0, {1}};
    } else {
        common = uni_gcd(top, bottom);
        if (failure || !uni_divide(&top, &common, &rest)) { fail(SIGN_LIMIT); return; }
        top = rest;
        if (!uni_divide(&bottom, &common, &rest)) { fail(SIGN_LIMIT); return; }

        /* Il numero che resta davanti, above / below, va sopra con il suo
         * numeratore e sotto con il suo denominatore, che è positivo. */
        Wide ratio = wide_mul(above, wide_make(below.den, below.num));
        c.top = uni_scaled(&top, ratio.num);
        c.bottom = uni_scaled(&rest, ratio.den);
    }
    if (!failure) candidate_add(&c);
}

/* Aggiunge ai candidati (minus_b + sigma sqrt(D)) / two_a, una radice di un
 * polinomio di secondo grado in x il cui discriminante D = content per
 * *primitive non è il quadrato di un polinomio. minus_b e two_a sono
 * polinomi nel parametro (atomo a), e two_a non è nullo.
 *
 * Perché la scrittura sia quella dei libri, 2 - \sqrt{4 - k^{2}} e non
 * \frac{4 - \sqrt{16 - 4k^{2}}}{2}, da sotto la radice si porta fuori ciò
 * che si può del numero content, e i tre numeri che restano davanti a
 * minus_b, alla radice e a two_a si riducono a interi senza divisori
 * comuni. */
static void candidate_radical(Poly minus_b, Poly two_a, const Uni *primitive, Wide content, int sigma, int a) {
    Candidate c;
    Uni top, bottom;
    Wide above, below;
    if (!uni_exact(minus_b, a, &top, &above) || !uni_exact(two_a, a, &bottom, &below)) return;

    /* sqrt(|content|) = outside sqrt(inside) / q, dove |content| = p / q:
     * infatti p / q = p q / q^2, e da p q si portano fuori i quadrati. */
    __int128 inside;
    if (__builtin_mul_overflow(content.num < 0 ? -content.num : content.num, content.den, &inside)) { fail(SIGN_LIMIT); return; }
    __int128 outside = square_out(&inside);

    /* I tre numeri, moltiplicati per il prodotto dei loro denominatori. */
    Wide scale = wide_mul(wide_mul((Wide){above.den, 1}, (Wide){below.den, 1}), (Wide){content.den, 1});
    __int128 over = wide_mul(above, scale).num, beside = wide_mul(wide_make(outside, content.den), scale).num, under = wide_mul(below, scale).num;
    if (failure) return;
    __int128 common = gcd128(gcd128(over, beside), under);
    if (under < 0) { over = -over; under = -under; sigma = -sigma; }
    if (beside / common >= COEF_LIMIT) { fail(SIGN_LIMIT); return; }
    c.top = uni_scaled(&top, over / common);
    c.bottom = uni_scaled(&bottom, under / common);
    c.radicand = uni_scaled(primitive, content.num < 0 ? -inside : inside);
    c.sigma = sigma;
    c.outside = (long long)(beside / common);
    if (!failure) candidate_add(&c);
}

/* 18t-e. Riempie param_candidate[] con le radici, scritte in funzione del
 * parametro (atomo a), dei polinomi di param_poly[] di primo e di secondo
 * grado nella variabile di atomo x. Va chiamata dopo param_project().
 *
 *   - c_1 x + c_0 ha la radice -c_0 / c_1.
 *   - A x^2 + B x + C ha le radici (-B +- sqrt(D)) / 2A, con D = B^2 - 4AC.
 *     Se D è il quadrato di un polinomio E le radici sono (-B +- E) / 2A,
 *     senza radicali: è il caso di quasi tutti gli esercizi, dove il
 *     trinomio è un prodotto come (x - a)(a x + 3). Che D sia E^2 si
 *     controlla moltiplicando.
 *
 * Le radici dei polinomi di grado più alto non hanno candidati: se un
 * estremo delle soluzioni è una di loro, la regola rinuncia. */
static void candidates_build(int x, int a) {
    for (int i = 0; i < param_polys && !failure; i++) {
        const Poly *part = param_part[i];
        if (param_var[i] != x) continue;
        if (param_degree[i] == 1) candidate_ratio(poly_negate(part[0]), part[1], a);
        if (param_degree[i] != 2) continue;
        Poly minus_b = poly_negate(part[1]), two_a = poly_mul(part[2], poly_const(num_int(2)));
        Poly d = poly_add(poly_mul(part[1], part[1]), poly_mul(poly_mul(part[2], part[0]), poly_const(num_int(4))), 1);
        Uni primitive, root;
        Wide content;
        if (!uni_exact(d, a, &primitive, &content)) return;

        /* D = content per primitive è un quadrato se lo sono tutti e due:
         * il numero, cioè numeratore e denominatore, e il polinomio. */
        __int128 p = 0, q = 0;
        if (content.num >= 0 && content.num < (__int128)1 << 126 && content.den < (__int128)1 << 62) {
            p = wide_isqrt(content.num);
            q = wide_isqrt(content.den);
        }
        if (p * p == content.num && q * q == content.den && uni_square_root(&primitive, &root)) {
            Poly e = poly_from_uni(&root, a, frac_make(p, q));
            if (!failure && poly_equal(poly_mul(e, e), d)) {
                candidate_ratio(poly_add(minus_b, e, 1), two_a, a);
                candidate_ratio(poly_add(minus_b, e, 0), two_a, a);
                continue;
            }
        }
        candidate_radical(minus_b, two_a, &primitive, content, -1, a);
        candidate_radical(minus_b, two_a, &primitive, content, 1, a);
    }
}

/* Ritorna 1 se il candidato c, quando il parametro vale il razionale at, è
 * il punto `point` di una tabella dei segni nella variabile: il razionale
 * point->low, oppure la sola radice di *element tra point->low e
 * point->high (element è NULL per un punto razionale). Il confronto è
 * esatto.
 *
 * Con il parametro uguale a un numero il candidato vale (t + s sqrt(r)) / b,
 * con t, r, b razionali e s = sigma * outside. Se r è il quadrato di un
 * razionale è un razionale, e si confronta con un punto razionale. Se non lo
 * è, è irrazionale: è una delle due radici di
 *
 *     q(x) = (b x - t)^2 - s^2 r,
 *
 * che non ha radici razionali, la più grande se s e b hanno lo stesso segno.
 * È una radice di *element solo se q lo divide, perché q è il polinomio di
 * grado più basso che la annulla; e allora la radice di q nell'intervallo
 * del punto, se c'è, è il punto. C'è se q cambia segno tra i due estremi, ed
 * è la più piccola delle due se nell'estremo inferiore q è positivo: il suo
 * coefficiente direttivo b^2 lo è, e q è positivo prima della radice più
 * piccola. */
static int candidate_is(const Candidate *c, Wide at, const Critical *point, const Uni *element) {
    Wide top = uni_value(&c->top, at), bottom = uni_value(&c->bottom, at), inside = {0, 1};
    if (c->sigma) inside = uni_value(&c->radicand, at);
    if (failure || bottom.num == 0 || inside.num < 0) return 0;
    if (inside.num >= (__int128)1 << 126 || inside.den >= (__int128)1 << 126) { fail(SIGN_LIMIT); return 0; }
    __int128 p = wide_isqrt(inside.num), q = wide_isqrt(inside.den);
    Wide beside = {c->sigma * c->outside, 1};
    if (p * p == inside.num && q * q == inside.den) {
        Wide value = wide_mul(wide_add(top, wide_mul(beside, (Wide){p, q})), wide_make(bottom.den, bottom.num));
        return point->exact && !failure && wide_cmp(value, point->low) == 0;
    }
    if (point->exact) return 0;

    /* I coefficienti di q, portati a interi con il prodotto dei loro
     * denominatori. */
    Wide two = wide_mul(bottom, bottom), one = wide_mul((Wide){-2, 1}, wide_mul(top, bottom));
    Wide zero = wide_add(wide_mul(top, top), wide_mul((Wide){-1, 1}, wide_mul(wide_mul(beside, beside), inside)));
    Wide scale = wide_mul(wide_mul((Wide){two.den, 1}, (Wide){one.den, 1}), (Wide){zero.den, 1});
    Uni quadratic = {2, {wide_mul(zero, scale).num, wide_mul(one, scale).num, wide_mul(two, scale).num}}, rest;
    if (failure) return 0;
    uni_primitive(&quadratic);
    if (!uni_divide(element, &quadratic, &rest)) return 0;
    int low = uni_sign_at(&quadratic, point->low), high = uni_sign_at(&quadratic, point->high);
    if (failure || low * high >= 0) return 0;
    int larger = (c->sigma > 0) == (bottom.num > 0);
    return (low > 0) != larger;
}

/* Aggiunge a text, di size byte, il polinomio p nella lettera name: come
 * uni_latex(), ma dal termine noto in su quando così non comincia con un
 * segno meno. È la scrittura dei libri: 4 - k^{2}, non -k^{2} + 4. */
static void param_poly_latex(const Uni *p, int name, char *text, size_t size) {
    if (p->degree < 1 || p->c[p->degree] > 0 || p->c[0] <= 0) { uni_latex(p, name, text, size); return; }
    for (int i = 0; i <= p->degree; i++) {
        __int128 c = p->c[i], magnitude = c < 0 ? -c : c;
        if (c == 0) continue;
        text_add(text, size, "%s", i == 0 ? "" : c < 0 ? " - " : " + ");
        if (magnitude != 1 || i == 0) text_add(text, size, "%lld", (long long)magnitude);
        if (i > 0) text_add(text, size, "%c", name);
        if (i > 1) text_add(text, size, "^{%d}", i);
    }
}

/* Aggiunge a text, di size byte, il candidato c, in LaTeX, con il parametro
 * di nome name: 4a, -\frac{3}{a}, \frac{a - 1}{2}, 2 - \sqrt{4 - k^{2}}. */
static void candidate_latex(const Candidate *c, int name, char *text, size_t size) {
    char above[256] = "";
    Uni top = c->top;
    int fraction = c->bottom.degree > 0 || c->bottom.c[0] != 1, terms = 0;
    for (int i = 0; i <= top.degree; i++) terms += top.c[i] != 0;

    /* Il segno meno di un numeratore di un solo termine va davanti alla
     * frazione. */
    int minus = fraction && !c->sigma && terms == 1 && top.c[top.degree] < 0;
    if (minus) uni_negate(&top);
    if (terms > 0 || !c->sigma) param_poly_latex(&top, name, above, sizeof above);
    if (c->sigma) {
        text_add(above, sizeof above, "%s", terms > 0 ? (c->sigma > 0 ? " + " : " - ") : c->sigma > 0 ? "" : "-");
        if (c->outside != 1) text_add(above, sizeof above, "%lld", c->outside);
        text_add(above, sizeof above, "\\sqrt{");
        param_poly_latex(&c->radicand, name, above, sizeof above);
        text_add(above, sizeof above, "}");
    }
    if (!fraction) { text_add(text, size, "%s", above); return; }
    text_add(text, size, "%s\\frac{%s}{", minus ? "-" : "", above);
    param_poly_latex(&c->bottom, name, text, size);
    text_add(text, size, "}");
}

/* Aggiunge a text, di size byte, il punto numero k della tabella dei segni
 * nella variabile x_name appena riempita per la cella cell, scritto come
 * estremo delle soluzioni. Ritorna 0 se non lo sa scrivere.
 *
 * In una cella che è un punto (point = 1) il parametro è un numero e
 * l'estremo anche: lo scrive point_latex(). In un intervallo l'estremo è il
 * solo candidato che nel valore scelto coincide con lui: nessuno, o più
 * d'uno, e la regola rinuncia. */
static int endpoint_latex(int k, const ParamCell *cell, int point, int a_name, int x_name, char *text, size_t size) {
    const Critical *end = &sign_point[k];
    int found = -1;
    if (point) {
        solution_note[0] = '\0';
        point_latex(k, x_name, text, size);
        return !solution_note[0];
    }
    if (!end->exact && end->element < 0) return 0;
    for (int i = 0; i < param_candidates && !failure; i++) {
        if (!candidate_is(&param_candidate[i], cell->sample, end, end->exact ? NULL : &sign_base[end->element])) continue;
        if (found >= 0) return 0;
        found = i;
    }
    if (found < 0 || failure) return 0;
    candidate_latex(&param_candidate[found], a_name, text, size);
    return 1;
}

/* 18t-e. Scrive in cell->text e cell->kind le soluzioni nella variabile
 * x_name della condizione body, che ha già il valore della cella al posto
 * del parametro a_name e di cui decide_by_signs() ha appena riempito la
 * tabella. I pezzi sono quelli di sign_solution(); cambia come si scrivono
 * gli estremi (endpoint_latex()). Ritorna 0 se un estremo non si sa
 * scrivere. */
static int cell_solutions(ParamCell *cell, int point, const Formula *body, int a_name, int x_name) {
    Piece piece;
    int pieces = 0;
    cell->text[0] = '\0';
    cell->kind = 1;
    for (int from = 0; !failure && sign_piece(body, from, &piece); from = piece.last + 1) {
        char low[200] = "", high[200] = "";
        int single = piece.first == piece.last && piece.low_closed;
        if (piece.low < 0 && piece.high < 0) { cell->kind = 2; return 1; }
        if (piece.low >= 0 && !endpoint_latex(piece.low, cell, point, a_name, x_name, low, sizeof low)) return 0;
        if (piece.high >= 0 && !single && !endpoint_latex(piece.high, cell, point, a_name, x_name, high, sizeof high)) return 0;
        if (pieces++) text_add(cell->text, sizeof cell->text, " \\lor ");
        piece_latex(cell->text, sizeof cell->text, x_name, piece.low < 0 ? NULL : low, piece.low_closed, single ? low : piece.high < 0 ? NULL : high, piece.high_closed);
    }
    if (!pieces) cell->kind = 0;
    return !failure;
}

/* Ritorna 1 se le celle a e b hanno le stesse soluzioni, scritte allo stesso
 * modo. */
static int cell_same(const ParamCell *a, const ParamCell *b) {
    return a->kind == b->kind && (a->kind != 1 || strcmp(a->text, b->text) == 0);
}

/* 18t-e. Scrive in text, di size byte, le soluzioni con il parametro: un
 * caso per ogni tratto di celle consecutive con le stesse soluzioni, nella
 * forma (condizione sul parametro \land soluzioni in x). Un tratto senza
 * soluzioni non si scrive; di uno in cui ogni x è soluzione si scrive la
 * sola condizione sul parametro; se il tratto sono tutte le celle la
 * condizione sul parametro non serve. Ritorna 1 se il testo è una
 * condizione che si può rileggere, 0 se è una delle due frasi "ogni x" e
 * "nessun x". */
static int param_cases(int a_name, int x_name, char *text, size_t size) {
    int written = 0, total = 0, plain = 1;
    text[0] = '\0';

    /* Quanti casi si scriveranno: uno solo non vuole parentesi. */
    for (int c = 0; c < param_cells; c++)
        total += param_cell[c].kind != 0 && (c == 0 || !cell_same(&param_cell[c], &param_cell[c - 1]));
    for (int first = 0, last; first < param_cells; first = last + 1) {
        const ParamCell *cell = &param_cell[first];
        int whole;
        for (last = first; last + 1 < param_cells && cell_same(&param_cell[last + 1], cell); last++) continue;
        if (cell->kind == 0) continue;
        whole = first == 0 && last == param_cells - 1;
        if (written++) text_add(text, size, " \\lor ");
        if (whole && cell->kind == 2) {
            text_add(text, size, "\\forall %c \\in \\mathbb{R}", x_name);
            plain = 0;
        } else if (whole) {
            text_add(text, size, "%s", cell->text);
        } else if (cell->kind == 2) {
            cells_latex(first, last, a_name, text, size);
        } else {
            int nested = strstr(cell->text, "\\lor") != NULL;
            text_add(text, size, "%s", total > 1 ? "(" : "");
            cells_latex(first, last, a_name, text, size);
            text_add(text, size, " \\land %s%s%s%s", nested ? "(" : "", cell->text, nested ? ")" : "", total > 1 ? ")" : "");
        }
    }
    if (!written) {
        text_add(text, size, "\\nexists %c \\in \\mathbb{R}", x_name);
        plain = 0;
    }
    return plain;
}

/* 18t-d. Scrive in text, di size byte, i valori del parametro di nome name
 * per cui la condizione vale: i tratti di celle consecutive con truth a 1,
 * come sign_solution() scrive i pezzi di una tabella. Ritorna 1 se il testo
 * è una condizione che si può rileggere, 0 se è una delle due frasi "ogni
 * valore" e "nessun valore". */
static int param_values(int name, char *text, size_t size) {
    int pieces = 0;
    text[0] = '\0';
    for (int first = 0, last; first < param_cells; first = last + 1) {
        for (last = first; param_cell[first].truth && last + 1 < param_cells && param_cell[last + 1].truth; last++) continue;
        if (!param_cell[first].truth) continue;
        if (first == 0 && last == param_cells - 1) { text_add(text, size, "\\forall %c \\in \\mathbb{R}", name); return 0; }
        if (pieces++) text_add(text, size, " \\lor ");
        cells_latex(first, last, name, text, size);
    }
    if (!pieces) text_add(text, size, "\\nexists %c \\in \\mathbb{R}", name);
    return pieces > 0;
}

/* =============================================================================
 * 18.19 UN PARAMETRO: I CONTROLLI E IL VERDETTO
 * ============================================================================
 *
 * I tre controlli indipendenti descritti in testa al capitolo 18.17: le
 * soluzioni rilette e riprovate in ogni cella (18t-f), la griglia di valori
 * del parametro scelti senza guardare le celle (18t-g), la proiezione
 * ricalcolata con un altro algoritmo (18t-h). Poi il punto di ingresso della
 * regola, param_decide(), che mette tutto in fila.
 */

/* 18t-f. Controlla che la condizione written dica, del parametro di nome
 * name, ciò che dicono le celle: nel valore di ogni cella, e in altri due
 * razionali di ogni intervallo, written con il numero al posto del parametro
 * deve risultare vera esattamente quando la cella ha truth a 1 (by_cell = 1),
 * oppure vera e basta (by_cell = 0). La decide closed_truth(), cioè la
 * tabella dei segni. Ritorna 1 se tutto concorda; altrimenti 0, con l'esito
 * NOT_PROVED e il motivo in *verdict. */
static int param_reread(const Formula *written, int name, int by_cell, Verdict *verdict) {
    static char reason[400];
    for (int c = 0; c < param_cells; c++)
        for (int i = 0; i < (c % 2 ? 1 : 3); i++) {
            Scratch mark = scratch_mark();
            Formula *closed = formula_with(written, name, i == 0 ? param_cell[c].value : node_rational(cell_beside(c, i == 2)));
            int truth = -1;
            if (failure) { verdict->reason = failure; failure = NULL; }
            else truth = closed_truth(closed, name, verdict);
            scratch_drop(mark);
            if (truth == (by_cell ? param_cell[c].truth : 1)) continue;
            if (truth < 0) {
                snprintf(reason, sizeof reason, "non riesco a rileggere le soluzioni scritte: %s", verdict->reason);
                verdict->reason = reason;
            } else {
                unjustified_steps++;
                verdict->reason = "le soluzioni scritte, rilette, non coincidono con la condizione in un valore del parametro";
            }
            verdict->outcome = NOT_PROVED;
            return 0;
        }
    return 1;
}

/* 18t-g. Ritorna la verità della condizione f quando il parametro di nome
 * name vale il razionale at, per quanto la si può stabilire con il solo
 * conto diretto sui numeri: 1 vera, 0 falsa, -1 non si sa.
 *
 * Un confronto nel solo parametro si calcola (sign_holds_at()). Di un
 * quantificatore interno si provano PARAM_GRID valori della sua variabile:
 * un valore in cui la condizione non vale smentisce un "per ogni", uno in
 * cui vale conferma un "esiste"; il contrario non si può dire, perché i
 * valori provati sono pochi. I connettivi si calcolano dalle parti, con la
 * logica a tre valori (truth_join()), e danno una risposta anche quando una
 * parte non la dà: "falso e qualcosa" è falso. */
static int grid_truth(const Formula *f, int name, Frac at) {
    if (f->kind == F_NOT || f->kind == F_AND || f->kind == F_OR || f->kind == F_IMPLIES || f->kind == F_IFF) {
        int a = grid_truth(f->a, name, at), b = f->kind == F_NOT ? -1 : grid_truth(f->b, name, at);
        return truth_join(f->kind, a, b);
    }
    if (f->kind == F_FORALL || f->kind == F_EXISTS) {
        Frac value[PARAM_GRID];
        Scratch mark = scratch_mark();
        Formula *body = formula_with(f->a, name, node_rational((Wide){at.num, at.den}));
        int every = f->kind == F_FORALL, found = -1;
        numbers_sample(&f->numbers, value, PARAM_GRID);
        for (int i = 0; i < PARAM_GRID && found < 0; i++) {
            failure = NULL;
            int holds = sign_holds_at(body, f->variable, value[i]);
            if (!failure && holds != every) found = !every;
        }
        failure = NULL;
        scratch_drop(mark);
        return found;
    }
    failure = NULL;
    int holds = sign_holds_at(f, name, at);
    if (failure) holds = -1;
    failure = NULL;
    return holds;
}

/* 18t-g. Ritorna 0 se in uno dei valori della griglia del parametro di nome
 * name, che varia in set, le celle sono smentite: se la condizione f, con
 * quel valore al posto del parametro, risulta falsa dove dovrebbe essere
 * vera, o il contrario. Dovrebbe essere vera nelle celle con truth a 1
 * (by_cell = 1), oppure dappertutto (by_cell = 0). La si guarda nei due modi
 * di 18t-g: con la tabella dei segni (closed_truth()) e con il conto diretto
 * (grid_truth()). Dove un modo non sa rispondere, lì non dice nulla. */
static int grid_agrees(const Formula *f, int name, const NumberSet *set, int by_cell) {
    Frac simple[PARAM_GRID];
    numbers_sample(set, simple, PARAM_GRID);
    for (int i = 0; i < 2 * PARAM_REACH + 1 + PARAM_GRID; i++) {
        /* Prima i quarti, poi i razionali più semplici: qualcuno si ripete,
         * e non fa danno. */
        Wide at = i <= 2 * PARAM_REACH ? wide_make(i - PARAM_REACH, 4) : (Wide){simple[i - 2 * PARAM_REACH - 1].num, simple[i - 2 * PARAM_REACH - 1].den};
        Verdict unused = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
        Scratch mark = scratch_mark();
        Formula *closed = formula_with(f, name, node_rational(at));
        int decided = failure ? -1 : closed_truth(closed, name, &unused);
        int seen = grid_truth(f, name, (Frac){(long long)at.num, (long long)at.den});
        scratch_drop(mark);
        failure = NULL;
        int cell = param_cell_of(at), expected = by_cell ? param_cell[cell].truth : 1;
        if (failure) { failure = NULL; continue; }
        if ((decided >= 0 && decided != expected) || (seen >= 0 && seen != expected)) return 0;
    }
    return 1;
}

/* 18t-h1. Legge i coefficienti f[0..MAX_PARAM_DEGREE] di un polinomio in x,
 * che devono essere polinomi nel solo parametro (atomo a) a coefficienti
 * razionali, e mette in out[j] il coefficiente di x^j moltiplicato per L, lo
 * stesso intero positivo per tutti: il minimo comune multiplo dei
 * denominatori. Mette in *degree il grado in x, il più grande j con f[j] non
 * nullo (-1 se sono tutti nulli). Ritorna 0 se un coefficiente ha un'altra
 * forma (un'altra lettera, un esponente negativo, frazionario o oltre
 * MAX_UNI, un numero complesso); se L esce da COEF_LIMIT annota un errore.
 *
 * Perché lo stesso L per tutti: in un determinante di 18t-h2 ogni riga è
 * fatta di coefficienti di f, quindi resta moltiplicata per L, e il
 * determinante per una potenza di L, che è un fattore costante e non cambia
 * le radici. È un conto a parte da uni_from_poly(), che di ogni polinomio
 * prende il suo multiplo. */
static int projection_integers(const Poly *f, int a, Uni *out, int *degree) {
    __int128 scale = 1;
    for (int j = 0; j <= MAX_PARAM_DEGREE; j++)
        for (int t = 0; t < f[j].count; t++) {
            const Term *term = &f[j].term[t];
            Frac e = term->mono.count ? term->mono.factor[0].exp : frac_int(0);
            if (term->mono.count > 1 || (term->mono.count == 1 && term->mono.factor[0].atom != a) || e.den != 1 || e.num < 0 || e.num > MAX_UNI ||
                term->coef.im.num != 0) return 0;
            scale = scale / gcd128(scale, term->coef.re.den) * term->coef.re.den;
            if (scale > COEF_LIMIT) { fail(SIGN_LIMIT); return 0; }
        }
    *degree = -1;
    for (int j = 0; j <= MAX_PARAM_DEGREE; j++) {
        memset(&out[j], 0, sizeof out[j]);
        out[j].degree = -1;
        for (int t = 0; t < f[j].count; t++) {
            const Term *term = &f[j].term[t];
            int e = term->mono.count ? (int)term->mono.factor[0].exp.num : 0;
            out[j].c[e] = (__int128)term->coef.re.num * (scale / term->coef.re.den);
            if (e > out[j].degree) out[j].degree = e;
        }
        if (out[j].degree >= 0) *degree = j;
    }
    return 1;
}

/* 18t-h2. Ritorna q^d p(n / q) = c_0 q^d + c_1 n q^(d-1) + ... + c_d n^d, con
 * at = n / q, il numero p(at) moltiplicato per q^d: un intero, senza
 * frazioni. d non è meno del grado di p. Annota un errore se un conto esce
 * dai 128 bit.
 *
 * Due polinomi di grado al più d calcolati così nello stesso punto hanno lo
 * stesso rapporto dei loro valori veri: il fattore q^d è lo stesso. */
static __int128 uni_homogeneous(const Uni *p, int d, Frac at) {
    __int128 sum = 0, power = 1, term;
    for (int i = d; i >= 0; i--) {
        /* sum: c_d n^(d-i) + ... + c_(i+1) n q^(d-i-1); power: q^(d-i). */
        if (__builtin_mul_overflow(sum, (__int128)at.num, &sum) || __builtin_mul_overflow(i <= p->degree ? p->c[i] : 0, power, &term) ||
            __builtin_add_overflow(sum, term, &sum) || (i > 0 && __builtin_mul_overflow(power, (__int128)at.den, &power))) {
            fail(SIGN_LIMIT);
            return 0;
        }
    }
    return sum;
}

/* 18t-h2. Ritorna il determinante della matrice di interi m, di size righe e
 * colonne, che il conto rovina. Annota un errore se un conto esce dai 128
 * bit.
 *
 * Eliminazione di Bareiss (E. H. Bareiss, Sylvester's identity and
 * multistep integer-preserving Gaussian elimination, Math. Comp. 22, 1968).
 * È l'eliminazione di Gauss senza frazioni: al passo k ogni elemento sotto
 * e a destra del perno diventa
 *
 *     m[i][j] = (m[k][k] m[i][j] - m[i][k] m[k][j]) / p,
 *
 * dove p è il perno del passo prima (1 al primo). La divisione è esatta,
 * perché dopo il passo k l'elemento m[i][j] è il determinante della
 * sottomatrice di partenza fatta dalle righe 0..k, i e dalle colonne 0..k, j
 * (identità di Sylvester): un intero. Dopo l'ultimo passo m[size-1][size-1]
 * è il determinante. Un perno nullo si scambia con una riga sotto, che
 * cambia il segno; se sono nulli tutti, la colonna sotto la diagonale è
 * nulla e il determinante è zero. È un altro algoritmo dallo sviluppo di
 * Laplace di minor_determinant(), e lavora sui numeri, non sui polinomi. */
static __int128 bareiss(__int128 m[MAX_MINOR][MAX_MINOR], int size) {
    __int128 previous = 1;
    int sign = 1;
    for (int k = 0; k + 1 < size; k++) {
        if (m[k][k] == 0) {
            int r = k + 1;
            while (r < size && m[r][k] == 0) r++;
            if (r == size) return 0;
            for (int j = 0; j < size; j++) {
                __int128 swap = m[k][j];
                m[k][j] = m[r][j];
                m[r][j] = swap;
            }
            sign = -sign;
        }
        for (int i = k + 1; i < size; i++)
            for (int j = k + 1; j < size; j++) {
                __int128 x, y;
                if (__builtin_mul_overflow(m[k][k], m[i][j], &x) || __builtin_mul_overflow(m[i][k], m[k][j], &y) || __builtin_sub_overflow(x, y, &x)) {
                    fail(SIGN_LIMIT);
                    return 0;
                }
                m[i][j] = x / previous;
            }
        previous = m[k][k];
    }
    return sign * m[size - 1][size - 1];
}

/* 18t-h3. Ritorna 1 se ogni radice reale di p, polinomio nel parametro che
 * non è il polinomio nullo, è uno dei valori critici param_point[]; 0 se
 * no. Annota un errore se i numeri sono troppo grandi.
 *
 * Il conto. Sia s la parte senza quadrati di p, p / mcd(p, p'): ha le stesse
 * radici, ognuna una volta. Il teorema di Sturm conta le sue radici reali
 * distinte, N, tra -B e B, dove B le supera tutte (uni_bound()). Poi si
 * contano i valori critici che sono radici di s, C: uno razionale lo è se s
 * lì vale zero; uno irrazionale è la sola radice del suo polinomio E tra due
 * razionali, e lo è se mcd(E, s), che ha per radici le radici comuni, ne ha
 * una tra quei due, cioè proprio lui. I valori critici sono numeri diversi
 * (18t-h4), quindi C <= N, e C = N vuol dire che ogni radice reale di s è un
 * valore critico. */
static int roots_are_critical(const Uni *p) {
    if (p->degree <= 0) return 1;
    Uni derivative = uni_derivative(p), common = uni_gcd(*p, derivative), s;
    if (failure || !uni_divide(p, &common, &s)) { fail(SIGN_LIMIT); return 0; }
    Wide bound = uni_bound(&s), minus = {-bound.num, 1};
    sturm_build(&s);
    int roots = sturm_changes(minus) - sturm_changes(bound), found = 0;
    for (int k = 0; k < param_points && !failure; k++) {
        const ParamPoint *point = &param_point[k];
        if (point->at.exact) {
            found += uni_sign_at(&s, point->at.low) == 0;
            continue;
        }
        common = uni_gcd(point->element, s);
        if (common.degree < 1) continue;
        sturm_build(&common);
        found += sturm_changes(point->at.low) - sturm_changes(point->at.high) > 0;
    }
    return found == roots;
}

/* 18t-h2, 18t-h3. Ricontrolla il polinomio della proiezione con provenienza
 * kind, first, second e k (come in ProjectionItem), dai coefficienti in x
 * già interi f[0..m] e g[0..n] (g è NULL per a1, che è f[m]): cerca tra
 * param_item[] quello che param_project() ha registrato per lui, e lo
 * confronta con i valori calcolati qui. Ritorna 2 se i due coincidono e sono
 * il polinomio nullo; 1 se coincidono, non lo sono, e ogni radice reale è
 * un valore critico; 0 se qualcosa non torna. Annota un errore se i numeri
 * sono troppo grandi.
 *
 * Perché D + 1 valori bastano. Un polinomio di grado al più D che non è il
 * polinomio nullo ha al più D radici: se si annulla in D + 1 numeri diversi
 * è il polinomio nullo. Quindi due polinomi di grado al più D sono uno c
 * volte l'altro se lo sono in D + 1 numeri: la differenza si annulla in
 * tutti. Qui D limita il grado di psc_k: ogni termine del determinante
 * prende un elemento da ogni riga, n - k righe di coefficienti di f, di grado
 * al più dF nel parametro, e m - k di g, di grado al più dG, quindi
 * D = (n - k) dF + (m - k) dG.
 *
 * Perché il determinante si calcola sui numeri. Calcolare un polinomio nel
 * parametro in un numero a0 rispetta somme e prodotti, e il determinante è
 * fatto di somme e prodotti degli elementi: il valore in a0 del determinante
 * è il determinante della matrice dei valori in a0. La matrice resta quella
 * dei gradi formali m e n anche dove a0 annulla un coefficiente direttivo:
 * psc_k è definito così, e così lo calcola subresultant_lead(). I valori si
 * prendono nei razionali più semplici, 0, 1, -1, 2, -2, 1/2, ...
 * (numbers_sample()), che tengono piccoli i numeri, e moltiplicati per
 * q^d (uni_homogeneous()); il determinante risulta moltiplicato per q^D, e
 * così il polinomio registrato, calcolato con lo stesso D. */
static int projection_item(int kind, int first, int second, int k, const Uni *f, int m, const Uni *g, int n) {
    const ProjectionItem *item = NULL;
    for (int i = 0; i < param_items && !item; i++)
        if (param_item[i].kind == kind && param_item[i].first == first && param_item[i].second == second && param_item[i].k == k) item = &param_item[i];
    if (!item) return 0;

    /* I gradi nel parametro, e D. */
    int df = 0, dg = 0, size = g ? m + n - 2 * k : 1;
    for (int j = 0; j <= m; j++) df = f[j].degree > df ? f[j].degree : df;
    for (int j = 0; g && j <= n; j++) dg = g[j].degree > dg ? g[j].degree : dg;
    int d = g ? (n - k) * df + (m - k) * dg : f[m].degree;
    if (d + 1 > PROJECTION_POINTS || size > MAX_MINOR) { fail(SIGN_LIMIT); return 0; }
    if (item->value.degree > d) return 0;

    /* 18t-h2. I valori nei D + 1 razionali: il coefficiente direttivo, o il
     * determinante. Le prime n - k righe sono x^(n-k-1) f, ..., f, le altre
     * x^(m-k-1) g, ..., g, scritte dalla potenza x^(m+n-k-1) in giù: nella
     * riga r di f la colonna c ha il coefficiente di x^(m-c+r), nella riga
     * r' = r - (n - k) di g quello di x^(n-c+r'). Delle m + n - k colonne si
     * tengono le prime m + n - 2k. */
    NumberSet reals;
    Frac point[PROJECTION_POINTS];
    __int128 value[PROJECTION_POINTS], matrix[MAX_MINOR][MAX_MINOR];
    memset(&reals, 0, sizeof reals);
    reals.reals = 1;
    numbers_sample(&reals, point, d + 1);
    for (int t = 0; t <= d && !failure; t++) {
        if (!g) { value[t] = uni_homogeneous(&f[m], d, point[t]); continue; }
        for (int r = 0; r < size; r++)
            for (int c = 0; c < size; c++) {
                int upper = r < n - k, power = upper ? m - c + r : n - c + r - (n - k);
                matrix[r][c] = power < 0 || power > (upper ? m : n) ? 0 : uni_homogeneous(upper ? &f[power] : &g[power], upper ? df : dg, point[t]);
            }
        value[t] = bareiss(matrix, size);
    }
    if (failure) return 0;

    /* Il confronto: il registrato è c volte il polinomio vero se in ogni
     * punto il rapporto dei due valori è c, quello del primo punto in cui il
     * valore vero non è zero. Il rapporto si confronta ridotto ai minimi
     * termini, senza moltiplicare: così non esce dai 128 bit. E c deve essere
     * positivo: tutti e due i conti moltiplicano psc_k solo per numeri
     * positivi (i denominatori tolti, q^D, j nella derivata), con le righe
     * nello stesso ordine. Se il valore vero è zero dappertutto, il polinomio
     * vero è il polinomio nullo, e tale deve essere il registrato. */
    int t0 = 0;
    while (t0 <= d && value[t0] == 0) t0++;
    if (t0 > d) return item->value.degree < 0 ? 2 : 0;
    if (item->value.degree < 0) return 0;
    Wide ratio = wide_make(uni_homogeneous(&item->value, d, point[t0]), value[t0]);
    if (ratio.num <= 0) return 0;
    for (int t = 0; t <= d && !failure; t++) {
        __int128 recorded = uni_homogeneous(&item->value, d, point[t]);
        if (value[t] == 0) {
            if (recorded != 0) return 0;
            continue;
        }
        Wide here = wide_make(recorded, value[t]);
        if (here.num != ratio.num || here.den != ratio.den) return 0;
    }
    if (failure) return 0;

    /* 18t-h3. Il contenimento. */
    return roots_are_critical(&item->value);
}

/* 18t-h2, 18t-h3. Ricontrolla i psc_k(f, g) con provenienza kind, first e
 * second per k = 0, 1, ..., fino al primo che non è il polinomio nullo: sono
 * quelli che 18t-a chiede. Ritorna 1 se tornano tutti, 0 se no. */
static int projection_first(int kind, int first, int second, const Uni *f, int m, const Uni *g, int n) {
    for (int k = 0; k < (m < n ? m : n); k++) {
        int found = projection_item(kind, first, second, k, f, m, g, n);
        if (found != 2) return found;
    }
    return 1;
}

/* 18t-h4. Ritorna 1 se i valori critici e le celle sono ciò che le decisioni
 * presumono; 0 se no. Annota un errore se i numeri sono troppo grandi.
 *
 *   - I valori critici sono in ordine e i loro intervalli non si toccano:
 *     sono numeri diversi, come vuole 18t-h3.
 *   - Uno irrazionale è la sola radice del suo polinomio E, di secondo grado,
 *     tra i due estremi del suo intervallo, che non sono radici (teorema di
 *     Sturm): così è un numero ben definito. Ed è la più piccola delle due
 *     radici di E esattamente se l'altra sta sopra l'intervallo: è ciò che
 *     dice smaller, con cui quadratic_node() sceglie il segno davanti alla
 *     radice quadrata nel valore della cella.
 *   - Il razionale di una cella che è un intervallo sta tra i due valori
 *     critici che la chiudono; quello di un punto razionale è il punto. */
static int cells_are_sound(void) {
    for (int k = 0; k < param_points && !failure; k++) {
        const ParamPoint *p = &param_point[k];
        if (k + 1 < param_points && wide_cmp(p->at.high, param_point[k + 1].at.low) >= 0) return 0;
        if (p->at.exact) continue;
        Uni e = p->element;
        if (e.degree != 2 || uni_sign_at(&e, p->at.low) == 0 || uni_sign_at(&e, p->at.high) == 0) return 0;
        Wide bound = uni_bound(&e);
        sturm_build(&e);
        if (sturm_changes(p->at.low) - sturm_changes(p->at.high) != 1) return 0;
        if (p->smaller != (sturm_changes(p->at.high) - sturm_changes(bound) == 1)) return 0;
    }
    for (int c = 0; c < param_cells && !failure; c++) {
        Wide sample = param_cell[c].sample;
        if (c % 2) {
            if (param_point[c / 2].at.exact && wide_cmp(sample, param_point[c / 2].at.low) != 0) return 0;
            continue;
        }
        if (c >= 2 && wide_cmp(sample, param_point[c / 2 - 1].at.high) <= 0) return 0;
        if (c / 2 < param_points && wide_cmp(sample, param_point[c / 2].at.low) >= 0) return 0;
    }
    return 1;
}

/* 18t-h. Ricontrolla la proiezione registrata in param_item[] e le celle
 * costruite da lei, con il parametro di atomo a. Va chiamata dopo
 * param_cells_build(), anche dopo le decisioni sulle celle: usa solo
 * param_poly[], param_part[], param_var[], param_item[], param_point[] e
 * param_cell[], che le decisioni non toccano. Ritorna 1 se tutto torna; 0
 * se qualcosa non torna, che è un errore del motore; -1 se un conto esce dai
 * numeri che il controllo sa trattare, e anche se un errore era già
 * annotato prima: allora non conferma nulla. */
static int projection_sound(int a) {
    static Uni part[MAX_PARAM_POLYS][MAX_PARAM_DEGREE + 1];
    int degree[MAX_PARAM_POLYS], sound = 1;

    /* 18t-h1. Ogni polinomio: le sue parti in x, rimoltiplicate per le
     * potenze di x, lo ricompongono, e i coefficienti interi e il grado in x
     * che ne legge projection_integers() sono il punto di partenza di ciò
     * che segue. Non si usa param_degree[]. */
    for (int i = 0; i < param_polys && sound && !failure; i++) {
        size_t before = arena_used;
        Poly sum = {0, NULL};
        for (int j = 0; j <= MAX_PARAM_DEGREE; j++) {
            Poly power = poly_const(num_int(1));
            if (j > 0) power = poly_term((Term){num_int(1), mono_atom(param_var[i], frac_int(j))});
            sum = poly_add(sum, poly_mul(param_part[i][j], power), 0);
        }
        sound = !failure && poly_equal(sum, param_poly[i]) && projection_integers(param_part[i], a, part[i], &degree[i]) && degree[i] >= 0;
        arena_used = before;
    }

    /* 18t-h4, poi 18t-h2 e 18t-h3: gli elementi che la proiezione deve
     * contenere si ricavano qui da part[]. Per ogni polinomio il coefficiente
     * direttivo e i psc_k con la derivata, che si calcola qui; per ogni
     * coppia nella stessa variabile i psc_k. */
    sound = sound && cells_are_sound();
    for (int i = 0; i < param_polys && sound && !failure; i++) {
        Uni derivative[MAX_PARAM_DEGREE + 1];
        int m = degree[i];
        sound = projection_item(1, i, -1, 0, part[i], m, NULL, 0) != 0;
        for (int j = 1; j <= m; j++) derivative[j - 1] = uni_scaled(&part[i][j], j);
        sound = sound && projection_first(2, i, -1, part[i], m, derivative, m - 1);
        for (int j = i + 1; j < param_polys && sound; j++)
            if (param_var[j] == param_var[i]) sound = projection_first(3, i, j, part[i], m, part[j], degree[j]);
    }
    if (failure) {
        failure = NULL;
        return -1;
    }
    return sound;
}

/* 18t-h. Ritorna 1 se projection_sound() conferma la proiezione del
 * parametro di atomo a; altrimenti mette in *verdict l'esito NOT_PROVED con
 * il motivo e ritorna 0. Una discordanza è un errore del motore, e conta in
 * unjustified_steps; un conto troppo grande no. */
static int projection_confirmed(int a, Verdict *verdict) {
    int sound = projection_sound(a);
    if (sound > 0) return 1;
    verdict->outcome = NOT_PROVED;
    if (sound < 0) {
        verdict->reason = "non riesco a ricontrollare la proiezione che dà i valori critici del parametro: i conti escono dai limiti del calcolo esatto";
        return 0;
    }
    unjustified_steps++;
    verdict->reason = "la verifica indipendente della proiezione non conferma i valori critici del parametro";
    return 0;
}

/* Ritorna 1 se in f compare un quantificatore sui numeri reali, o una
 * richiesta di soluzioni. */
static int formula_has_real_letter(const Formula *f) {
    if (!f) return 0;
    if (f->kind == F_SOLVE || ((f->kind == F_FORALL || f->kind == F_EXISTS) && f->numbers.reals)) return 1;
    return formula_has_real_letter(f->a) || formula_has_real_letter(f->b);
}

/* Ritorna 1 se l'enunciato thesis è di quelli di questa regola: eventuali
 * negazioni, poi un quantificatore su un numero reale, o una richiesta di
 * soluzioni nei reali, con un'altra lettera reale all'interno. Gli altri
 * enunciati con relazioni d'ordine restano a decide_by_signs().
 *
 * Una richiesta di soluzioni sotto un quantificatore arriva qui qualunque
 * sia l'insieme del quantificatore: decide_by_signs() non conosce quella
 * forma, e leggerebbe la richiesta come una condizione sempre falsa. Qui
 * riceve la risposta giusta: se l'insieme non è \mathbb{R}, che non è
 * trattata. */
static int has_parameter(const Formula *thesis) {
    while (thesis->kind == F_NOT) thesis = thesis->a;
    if (thesis->kind == F_FORALL && thesis->a->kind == F_SOLVE) return 1;
    return (thesis->kind == F_FORALL || thesis->kind == F_EXISTS || thesis->kind == F_SOLVE) && thesis->numbers.reals && formula_has_real_letter(thesis->a);
}

/* Il lavoro di decide_with_parameter(), che ne descrive il contratto. */
static void param_decide(const Formula *thesis, Verdict *verdict) {
    static char text[PARAM_TEXT], where[320];
    int negated;
    const Formula *q = without_negations(thesis, &negated);

    /* Le tre forme: una richiesta di soluzioni sotto il "per ogni" del
     * parametro (request), i valori del parametro (solving), una verifica. */
    const Formula *request = q->kind == F_FORALL && q->a->kind == F_SOLVE ? q->a : NULL;
    int solving = q->kind == F_SOLVE, every = q->kind == F_FORALL, name = q->variable, a = atom_var(name);
    if (!numbers_all_reals(&q->numbers)) { verdict->reason = PARAM_FORM; return; }

    /* 18t-a, 18t-b. La tabella nella lettera del parametro: prima le sue
     * colonne, poi i suoi punti, che sono i valori critici. Lo stato che
     * sign_prepare() si aspetta è quello di una tabella nuova (sign_reset()),
     * senza funzioni goniometriche né esponenziali. */
    sign_reset(name);
    sign_x = a;
    param_polys = param_candidates = param_items = 0;
    failure = NULL;
    param_collect(q->a, name, 0);
    param_project(a);
    if (request && !failure) candidates_build(atom_var(request->variable), a);
    if (!failure) param_cells_build(name);
    if (failure) { verdict->reason = failure; failure = NULL; return; }

    /* La dimostrazione scritta comincia dai valori critici: vanno detti
     * adesso, perché le colonne non sopravvivono alla prima cella. */
    size_t opening = proof_length;
    proof_add("\\textbf{Cases on $%c$.} Each comparison counts as false where one of its sides has no value. "
              "For a fixed value of $%c$ what is left is a statement in one variable, decided by a sign table. "
              "Read as polynomials in that variable, the expressions of the statement keep the same real roots, in the same order, "
              "as $%c$ moves without crossing a real root of one of these: ", name, name, name);
    int listed = 0;
    for (int i = 0; i < sign_polys; i++) {
        if (sign_poly[i].degree <= 0) continue;
        proof_add("%s$", listed++ ? ", " : "");
        put_uni(&sign_poly[i], name);
        proof_add("$");
    }
    proof_add("%s (the leading coefficients, the discriminants and the resultants of those polynomials, and the comparisons in $%c$ alone). "
              "So one value of $%c$ decides for each of these roots and for each interval between two consecutive ones.\n\\begin{itemize}\n",
              listed ? "" : "none", name, name);

    /* 18t-c. Una cella alla volta. Una verifica si ferma alla prima cella
     * che decide: quella che smentisce un "per ogni" o conferma un
     * "esiste". Ciò che ogni decisione lascia nell'arena e tra gli atomi
     * viene tolto subito. */
    int decided = -1;
    for (int c = 0; c < param_cells && decided < 0; c++) {
        ParamCell *cell = &param_cell[c];
        Scratch mark = scratch_mark();
        Formula *closed = formula_with(request ? request->a : q->a, name, cell->value);
        const char *problem = failure;
        proof_add("\\item ");
        put_cell(c, name);
        if (problem) {
            /* La copia non è riuscita: non c'è un enunciato da decidere. */
        } else if (request) {
            /* 18t-e. La richiesta, con il valore della cella: tolti i
             * confronti tra numeri, o non resta nulla da risolvere, oppure
             * la risolve 18p, e dalla sua tabella si leggono le soluzioni. */
            Verdict inner = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
            Formula solve = *request;
            size_t before = proof_length;
            solve.a = closed_reduce(closed, request->variable, name, verdict);
            if (!solve.a) {
                problem = verdict->reason;
            } else if (solve.a == &closed_constant[0] || solve.a == &closed_constant[1]) {
                cell->kind = solve.a == &closed_constant[1] ? 2 : 0;
            } else {
                decide_by_signs(&solve, &inner);
                proof_cut(before);
                if (inner.outcome != SOLVED) {
                    verdict->outcome = inner.outcome;
                    problem = inner.reason ? inner.reason : PARAM_INNER;
                } else if (!cell_solutions(cell, c % 2, solve.a, name, request->variable)) {
                    problem = failure ? failure : PARAM_WRITE;
                }
            }
            if (!problem && cell->kind == 1) proof_add(": the solutions are $%s$.\n", cell->text);
            else if (!problem) proof_add(": %s $%c$ is a solution.\n", cell->kind ? "every" : "no", request->variable);
        } else {
            cell->truth = closed_truth(closed, name, verdict);
            if (cell->truth < 0) problem = verdict->reason;
            else proof_add(": the condition %s.\n", cell->truth ? "holds" : "fails");
            if (!solving && cell->truth >= 0 && cell->truth != every) {
                /* Il valore che decide, per il verdetto: con l'x che
                 * smentisce, se la condizione è un "per ogni x". */
                char value[96];
                decided = c;
                if (c % 2 && !param_point[c / 2].at.exact) snprintf(value, sizeof value, "%s", param_point[c / 2].text);
                else wide_text(cell->sample, value, sizeof value);
                int inner = (q->a->kind == F_FORALL || q->a->kind == F_EXISTS) && param_inner[0];
                snprintf(where, sizeof where, "%c = %s%s%s", name, value, inner ? ", " : "", inner ? param_inner : "");
            }
        }
        scratch_drop(mark);
        failure = NULL;
        if (!problem) continue;
        proof_cut(opening);
        verdict->reason = problem;
        return;
    }
    proof_add("\\end{itemize}\n");
    verdict->method = "con la tabella dei segni, per casi sul parametro";

    /* 18t-d. Una verifica. "Per ogni" è vero se nessuna cella lo smentisce,
     * "esiste" se una lo conferma; una negazione davanti li rovescia. Quando
     * hanno deciso tutte le celle insieme, e non una sola, prima del
     * verdetto si ricontrolla la proiezione (18t-h) e si guarda la griglia
     * (18t-g). */
    if (!solving && !request) {
        int holds = every ? decided < 0 : decided >= 0;
        if (decided < 0 && !projection_confirmed(a, verdict)) {
            proof_cut(opening);
            return;
        }
        if (decided < 0 && !grid_agrees(q->a, name, &q->numbers, 1)) {
            unjustified_steps++;
            proof_cut(opening);
            verdict->outcome = NOT_PROVED;
            verdict->reason = "la verifica indipendente, su una griglia di numeri, non conferma i casi sul parametro";
            return;
        }
        if (decided >= 0) proof_add("At this value the condition %s.", every ? "fails" : "holds");
        else proof_add("The condition %s in every case, hence for every value of $%c$.", every ? "holds" : "fails", name);
        claim_verdict(verdict, holds, negated, decided >= 0 ? where : NULL);
        return;
    }

    /* 18t-d, 18t-e. Le soluzioni scritte; poi 18t-h, 18t-f e 18t-g, che le
     * ricontrollano. Le soluzioni poggiano su tutte le celle, quindi la
     * proiezione va ricontrollata sempre. Per i valori del parametro si
     * rilegge il testo e lo si confronta con le celle. Per le soluzioni con
     * il parametro si controlla l'enunciato "per ogni x, la condizione vale
     * se e solo se valgono le soluzioni scritte"; se le soluzioni sono "ogni
     * x" o "nessun x", che non sono condizioni da rileggere, l'enunciato è
     * la condizione stessa, o la sua negazione. */
    int plain = request ? param_cases(name, request->variable, text, sizeof text) : param_values(name, text, sizeof text);
    if (failure) { verdict->reason = failure; failure = NULL; proof_cut(opening); return; }
    if (!projection_confirmed(a, verdict)) {
        proof_cut(opening);
        return;
    }
    Formula *written = plain ? condition_reread(text) : NULL, *claim = NULL;
    if (plain && !written) {
        unjustified_steps++;
        proof_cut(opening);
        verdict->outcome = NOT_PROVED;
        verdict->reason = "le soluzioni scritte non si lasciano rileggere";
        return;
    }
    if (request) {
        Formula *body = request->a;
        claim = formula_node(F_FORALL, plain ? formula_node(F_IFF, body, written, "") : param_cell[0].kind ? body : formula_node(F_NOT, body, NULL, ""), NULL, "");
        claim->variable = request->variable;
        claim->numbers = request->numbers;
    }
    if ((claim || written) && !param_reread(claim ? claim : written, name, !claim, verdict)) { proof_cut(opening); return; }
    if (!grid_agrees(claim ? claim : q->a, name, &q->numbers, !claim)) {
        unjustified_steps++;
        proof_cut(opening);
        verdict->outcome = NOT_PROVED;
        verdict->reason = "la verifica indipendente, su una griglia di numeri, non conferma le soluzioni scritte";
        return;
    }
    proof_add("Hence the condition holds exactly for $%s$. $\\Box$", text);
    verdict->outcome = SOLVED;
    verdict->detail = text;
    verdict->proof = proof_text;
}

/* 18t. Decide con i casi sul parametro l'enunciato thesis, che è di quelli
 * riconosciuti da has_parameter(): una verifica, i valori del parametro, o
 * le soluzioni con il parametro. Riempie *verdict, con la dimostrazione
 * scritta e il controesempio o le soluzioni; ciò che la regola non tratta
 * resta NON SUPPORTATO, con il motivo.
 *
 * Mentre lavora, i grafici sono spenti: ogni cella passa da
 * decide_by_signs(), che altrimenti ne costruirebbe uno per volta, e il
 * disegno di una cella non è il disegno dell'enunciato. */
static void decide_with_parameter(const Formula *thesis, Verdict *verdict) {
    int wanted = figures_wanted;
    figures_wanted = 0;
    param_decide(thesis, verdict);
    figures_wanted = wanted;
}

/* =============================================================================
 * 19. QUANTIFICATORI: VERIFICA INDIPENDENTE E VERDETTO
 * ============================================================================
 *
 * Verifica indipendente. Il capitolo 18 ragiona con i polinomi: scompone,
 * risolve, studia segni. Qui lo stesso enunciato viene ricontrollato senza
 * algebra, calcolando con i numeri: ogni "per ogni" si prova sui primi
 * elementi dell'insieme, ogni "esiste" con il valore scelto dalla
 * dimostrazione (quello del caso giusto, se la dimostrazione è per casi sul
 * resto), e ogni confronto è un confronto tra due numeri. Se la
 * dimostrazione dice x = (y + 1)/(y - 1), per ogni y del campione si calcola
 * quel numero, si guarda se sta nell'insieme e se soddisfa la condizione.
 *
 * Come per gli insiemi (capitolo 16) non è una seconda dimostrazione, perché
 * il campione è finito: è un controllo contro gli errori del programma. Se
 * non conferma la dimostrazione, il verdetto non viene emesso.
 *
 * I valori da provare. I primi elementi di un insieme non bastano quando
 * l'enunciato chiede qualcosa di raro. In "per ogni x, se esiste k con x =
 * k^2 + 7 allora ..." nessuno dei primi interi soddisfa l'ipotesi, e
 * un'implicazione con l'ipotesi falsa è vera qualunque cosa dica la tesi:
 * una verifica così sarebbe una prova su strada fatta solo nei giorni di
 * sole. Perciò ogni quantificatore prova anche i valori che le condizioni
 * gli impongono (sample_equations(), sample_candidates()): da alpha x +
 * beta = 0 il valore -beta/alpha; e se l'uguaglianza contiene la lettera k
 * di un "esiste" più interno, per ogni k del campione il valore di x che la
 * rende vera. Così x = k^2 + 7 dà x = 7, 8, 11, 16, ..., e l'ipotesi vale
 * per costruzione. Divisibilità e appartenenza si leggono con la loro
 * definizione: n | a - b dice a - b = q n con q intero, e q si sceglie. E
 * tra i valori di una variabile razionale ce n'è sempre uno che non è
 * intero (check_sample()), anche quando le variabili sono tante e i valori
 * pochi.
 *
 * I valori scelti da 18u. Riuscita la regola 18u, i valori annotati nei
 * nodi vengono dimenticati (vedi 18u): la verifica dell'enunciato ricalcola
 * ogni "esiste" com'è scritto, e del valore scelto dalla dimostrazione non
 * direbbe nulla. Lo ricontrolla record_holds(), con ciò che 18u-3 ha
 * annotato in witness_records[]: dove le ipotesi valgono, il valore deve
 * stare nel suo insieme e rendere vera la condizione. Le variabili generiche
 * si scelgono anche lì in modo che le ipotesi valgano: prima un numero per
 * ogni testimone nominato da 18u-1, poi le altre ricavate dalle ipotesi.
 * È un conto con i numeri, indipendente dall'identità tra polinomi con cui
 * 18s ha giustificato il passo.
 *
 * Quante prove servono. Una verifica che non ha mai trovato vere le ipotesi
 * non ha controllato nulla. Se la dimostrazione ha preso un'ipotesi "esiste"
 * con il suo testimone (18u-1), la verifica dell'enunciato deve aver trovato
 * vera la tesi di un'implicazione, con l'ipotesi vera, almeno MIN_SATISFIED
 * volte; e ogni valore annotato da 18u-3 deve essere stato provato su almeno
 * MIN_SATISFIED scelte che soddisfano le ipotesi. Altrimenti il verdetto è
 * NON DIMOSTRATO, e il motivo lo dice. Così resta senza verdetto anche un
 * enunciato vero perché le sue ipotesi non valgono mai, come "se x^2 = 2k^2
 * + 3 allora ...": nessuno ha controllato che non valgano, e un'ipotesi che
 * la verifica non sa soddisfare non è per questo impossibile.
 *
 * Perché ne basta una. Una soglia più alta sembrerebbe più prudente, ma ci
 * sono ipotesi che valgono in un punto solo: una relazione che contiene solo
 * le coppie (1, v) è antisimmetrica, e "(x, y) e (y, x) nella relazione"
 * vale solo per x = y = 1. Lì una prova è tutta la verifica possibile, e
 * una soglia di quattro ha tolto il verdetto a tre enunciati di questo tipo
 * generati da fuzz_relations.py, uno dimostrato e due smentiti, tutti e tre
 * giustamente. Dove le soluzioni sono tante, le
 * prove sono tante anche loro, perché i valori si ricavano dalle ipotesi
 * (vedi "I valori da provare").
 */

/* Mette in *out il valore r con ogni variabile legata in questo momento
 * sostituita dal suo valore, una per volta. Ritorna 0 se un conto non
 * riesce. */
static int substituted(Rat r, Rat *out) {
    for (int i = 0; i < env_count && !failure; i++) {
        Poly num, den;
        int x = atom_var(env_at(i)->name);
        if (!rat_polynomials(r, &num, &den)) return 0;
        r = rat_div(poly_substitute(num, x, env_at(i)->value), poly_substitute(den, x, env_at(i)->value));
    }
    *out = r;
    return !failure;
}

/* Calcola un valore scelto dalla dimostrazione, chosen, ora che le variabili
 * da cui dipende sono legate a numeri. Mette il numero in *value e ritorna
 * 1; ritorna 0 se non ne esce un numero razionale. */
static int value_now(Rat chosen, Frac *value) {
    Num number;
    if (!substituted(chosen, &chosen) || !rat_number(chosen, &number) || number.im.num != 0) return 0;
    *value = number.re;
    return 1;
}

/* Quanti elementi di ogni insieme prova la verifica: SAMPLE_SIZE, oppure meno
 * quando i quantificatori annidati sono tanti. Lo fissa decide_quantified(). */
static int sample_width;

/* Mette in out i valori che la verifica prova per una variabile di set, e
 * ritorna quanti sono: i primi width elementi (numbers_sample()), più il
 * primo che non è intero se tra quelli non ce n'è nessuno e set non è fatto
 * di interi. out deve avere posto per width + 1 valori.
 *
 * Perché. In ordine di altezza i primi razionali sono 0, 1, -1, 2, -2: con
 * cinque o più variabili annidate la larghezza scende a cinque o meno, e la
 * verifica di un enunciato sui razionali provava soltanto interi. Una copia
 * del programma rotta apposta, che non chiedeva che il valore di un
 * "esiste" fosse intero, "dimostrava" così che per x, y, z, w razionali con
 * x - y e z - w interi anche xz - yw è intero, e la verifica confermava: la
 * tesi fallisce solo fuori dagli interi (x = 0, y = 1, z = w = 1/2).
 * L'enunciato è in false_rare_witnesses.tex. Il valore si aggiunge e non ne
 * sostituisce un altro, perché un "esiste" che si confermava con -2 deve
 * continuare a trovarlo. */
static int check_sample(const NumberSet *set, Frac *out, int width) {
    Frac first[SAMPLE_SIZE];
    numbers_sample(set, out, width);
    if (set->integers) return width;
    for (int i = 0; i < width; i++)
        if (out[i].den != 1) return width;
    numbers_sample(set, first, SAMPLE_SIZE);
    for (int i = width; i < SAMPLE_SIZE; i++)
        if (first[i].den != 1) { out[width] = first[i]; return width + 1; }
    return width;
}

/* Quante volte la verifica ha trovato vera la tesi di un'implicazione dopo
 * averne trovata vera l'ipotesi: le prove che hanno controllato qualcosa
 * (vedi "Quante prove servono", in testa al capitolo). */
static long sample_theses;

/* Ritorna holds, la tesi di un'implicazione calcolata sul campione con
 * l'ipotesi vera, e la conta se è vera. */
static int thesis_counted(int holds) {
    sample_theses += holds;
    return holds;
}

/* Una condizione da rendere vera da cui la verifica ricava dei valori da
 * provare (sample_candidates()): un'uguaglianza, con al più un numero
 * ancora da scegliere, il testimone, che varia in `set`.
 *
 *   - source è F_EQUAL o F_DISTINCT: left = right. witness è la lettera di
 *     un "esiste" più interno che vi compare, o 0 se non ce n'è.
 *   - source è F_DIVIDES, "u divide v": per definizione v = q u con q
 *     intero (17n); il testimone è q, set sono gli interi, witness è 0.
 *   - source è F_IN, "s appartiene ad A": s = q con q in A; set è A. */
typedef struct {
    const Formula *source;
    int witness;
    const NumberSet *set;  /* NULL se non c'è un testimone */
} Wanted;

/* Gli interi: l'insieme del quoziente di una divisibilità. */
static const NumberSet all_integers = {.integers = 1};

/* Un quantificatore gia visitato dal verificatore numerico: formula e il
 * nodo originale, outer il contesto esterno preso in prestito. Ogni cella
 * vive nel proprio frame ricorsivo; i risultati conservano solo Formula*. */
typedef struct SampleBinder SampleBinder;
struct SampleBinder { const Formula *formula; const SampleBinder *outer; };

/* Elenca in list[], dal posto count, le condizioni da rendere vere perché
 * valga f, negata se negated, e ritorna il nuovo numero, al più
 * MAX_EQUATIONS. outer collega gli "esiste" esterni gia incontrati:
 * le loro lettere sono testimoni, senza limite sulla profondita della pila.
 *
 * Fa per la verifica ciò che find_equations() fa per la dimostrazione, ed è
 * scritta a parte perché chi controlla non usi il codice di chi cerca. In una
 * congiunzione prende ciò che serve, in una disgiunzione ciò che basta: in
 * tutti e due i casi è solo un valore da provare, e il conto lo ricontrolla.
 * Non entra in un "per ogni" più interno, dove un'uguaglianza vale per ogni
 * valore della sua lettera e risolverla non dà nulla. Entra in un "esiste",
 * e ne tiene anche le uguaglianze con la sua lettera: sono le ipotesi
 * "esiste k" di 18u, che si soddisfano scegliendo k. Un'uguaglianza con due
 * testimoni si salta, e così una divisibilità o un'appartenenza che ne usa
 * già uno: i valori da scegliere sarebbero due. */
static int sample_equations(const Formula *f, int negated, const SampleBinder *outer, Wanted *list, int count) {
    if (count == MAX_EQUATIONS) return count;
    switch (f->kind) {
    case F_NOT:
        return sample_equations(f->a, !negated, outer, list, count);
    case F_EQUAL: case F_DISTINCT: case F_DIVIDES: case F_IN: {
        /* I testimoni che vi compaiono, e da che parte va letta. */
        const Formula *binder = NULL;
        int witnesses = 0, plain = f->kind == F_EQUAL || f->kind == F_DISTINCT;
        for (const SampleBinder *p = outer; p; p = p->outer)
            if (formula_uses_letter(f, p->formula->variable)) { binder = p->formula; witnesses++; }
        if (plain ? (f->kind == F_EQUAL) == negated || witnesses > 1 : f->swapped != negated || witnesses) return count;
        if (plain) list[count] = binder ? (Wanted){f, binder->variable, &binder->numbers} : (Wanted){f, 0, NULL};
        else list[count] = (Wanted){f, 0, f->kind == F_IN ? &f->numbers : &all_integers};
        return count + 1;
    }
    case F_FORALL: case F_EXISTS: {
        if ((f->kind == F_EXISTS) == negated) return count;
        SampleBinder inner = {f, outer};
        return sample_equations(f->a, negated, &inner, list, count);
    }
    case F_AND: case F_OR:
        count = sample_equations(f->a, negated, outer, list, count);
        return sample_equations(f->b, negated, outer, list, count);
    case F_IMPLIES:
        count = sample_equations(f->a, !negated, outer, list, count);
        return sample_equations(f->b, negated, outer, list, count);
    default:
        return count;
    }
}

/* Fin dove la verifica prova gli interi, in valore assoluto, per una lettera
 * che compare solo negli esponenti (sample_exponent()). */
#define EXPONENT_SCAN 40

/* 18x, per la verifica. Il valore intero della variabile name che rende vera
 * l'uguaglianza w quando il suo testimone vale q, se name vi compare solo
 * negli esponenti: a = 2^{m} c non è di primo grado in m, ma con a e c
 * numeri il valore di m, se c'è, si trova provando gli interi da 0 verso
 * l'esterno, fino a EXPONENT_SCAN. Lo mette in *value e ritorna 1 se lo
 * trova. È un conto con i numeri, come il resto della verifica: senza, la
 * verifica di "a = 2^{n} b e b = 2^{k} c implicano a = 2^{m} c" provava per
 * m solo i primi interi, e non trovava m = -7 per a = 1, c = 128. */
static int sample_exponent(int name, const Wanted *w, Frac q, Frac *value) {
    const Formula *f = w->source;
    if (!formula_uses_letter(f, name)) return 0;
    for (int i = 0; i <= 2 * EXPONENT_SCAN; i++) {
        long long m = i % 2 ? (i + 1) / 2 : -(i / 2);
        size_t mark = arena_used;
        Num gap;
        if (w->witness) env_push(w->witness, rat_frac(q));
        env_push(name, rat_int(m));
        int zero = rat_number(rat_add(eval(f->left), eval(f->right), 1), &gap) && num_is_zero(gap) && !failure;
        env_pop();
        if (w->witness) env_pop();
        failure = NULL;
        arena_used = mark;
        if (zero) { *value = frac_int(m); return 1; }
    }
    return 0;
}

/* Il numeratore e il denominatore della condizione w, scritta come
 * polinomio uguale a zero, quando il suo testimone vale q. */
static Rat sample_gap(const Wanted *w, Frac q) {
    const Formula *f = w->source;
    if (f->kind == F_DIVIDES) return rat_add(eval(f->right), rat_mul(rat_frac(q), eval(f->left)), 1);
    if (f->kind == F_IN) return rat_add(eval(f->left), rat_frac(q), 1);
    if (w->witness) env_push(w->witness, rat_frac(q));
    Rat gap = rat_add(eval(f->left), eval(f->right), 1);
    if (w->witness) env_pop();
    return gap;
}

/* Il valore della variabile name che rende vera la condizione w quando il
 * suo testimone vale q, con tutte le altre variabili legate a numeri. Lo
 * mette in *value e ritorna 1 se la condizione, scritta come polinomio
 * uguale a zero, è di primo grado in name con coefficienti numerici, e se in
 * quel valore il denominatore non si annulla; oppure, se name compare solo
 * negli esponenti, se sample_exponent() lo trova. Un conto che non riesce
 * vuol dire solo che da qui non viene un valore.
 *
 * Se la condizione contiene un'applicazione definita per casi il cui
 * argomento dipende da name (11v), in *pieces va il numero dei suoi casi, e
 * si usa il caso piece: il valore del caso nell'equazione, oppure il punto
 * stesso, se il caso è "x = c". Con piece fuori dai casi non c'è un valore.
 * È solo un valore da provare: chi chiama lo ricontrolla calcolando con i
 * numeri, dove il caso si decide da sé. */
static int sample_solution(int name, const Wanted *w, Frac q, int piece, int *pieces, Frac *value) {
    const Formula *f = w->source;
    size_t mark = arena_used;
    Poly num, den, part[2];
    Num zero;
    int x = atom_var(name), forced = 0;
    *pieces = 0;
    Rat gap = sample_gap(w, q);
    if (failure == CASE_UNDECIDED && poly_uses(undecided_argument.num, x)) {
        const Map *map = undecided_map;
        Rat argument = undecided_argument;
        failure = NULL;
        *pieces = map->cases;
        if (piece < 0 || piece >= map->cases || case_choice_count == MAX_CASE_CHOICES) { arena_used = mark; return 0; }
        if (rat_same(argument, rat_atom(x)) && case_point(map, piece, value)) { arena_used = mark; return 1; }
        case_choice[case_choice_count++] = (CaseChoice){undecided_node, argument, piece};
        forced = 1;
        gap = sample_gap(w, q);
    }
    int solved = !failure && rat_polynomials(gap, &num, &den) && poly_split(num, x, part, 1) == 1 &&
                 poly_is_constant(part[0]) && poly_is_constant(part[1]) && part[1].term[0].coef.im.num == 0 &&
                 (part[0].count == 0 || part[0].term[0].coef.im.num == 0);
    if (solved) *value = frac_neg(frac_div(part[0].count ? part[0].term[0].coef.re : frac_int(0), part[1].term[0].coef.re));
    solved = solved && !(rat_number(poly_substitute(den, x, rat_frac(*value)), &zero) && num_is_zero(zero)) && !failure;
    if (forced) case_choice_count--;
    failure = NULL;
    arena_used = mark;
    if (!solved && (f->kind == F_EQUAL || f->kind == F_DISTINCT) && letter_only_in_exponents(f, name))
        solved = sample_exponent(name, w, q, value);
    return solved;
}

/* Mette in value[] i valori di name, al più SAMPLE_SIZE, che rendono vera
 * una delle condizioni list[0..wanted) e che stanno in set, escludendo quelli
 * già in known[0..knowns); ritorna quanti sono. Prima le condizioni senza
 * testimone, che danno un valore ciascuna; poi quelle con un testimone, che
 * prende i valori di check_sample() con larghezza width.
 *
 * Tra quei valori c'è anche quello che la verifica proverà per un "esiste"
 * k scritto nell'enunciato (sample_holds() prova gli stessi), quindi
 * l'ipotesi "esiste k con x = k^2" risulta vera per ogni x così ottenuto. */
static int sample_candidates(int name, const NumberSet *set, const Wanted *list, int wanted, int width, const Frac *known,
                             int knowns, Frac *value) {
    int count = 0;
    for (int witnessed = 0; witnessed < 2; witnessed++) {
        for (int e = 0; e < wanted && count < SAMPLE_SIZE; e++) {
            Frac q[SAMPLE_SIZE + 1];
            if ((list[e].set != NULL) != witnessed) continue;
            int tries = witnessed ? check_sample(list[e].set, q, width) : 1;
            for (int t = 0; t < tries && count < SAMPLE_SIZE; t++) {
                /* Con un'applicazione definita per casi, un valore per
                 * ogni caso (sample_solution()). */
                for (int piece = -1, pieces = 0; piece < pieces && count < SAMPLE_SIZE; piece++) {
                    Frac x;
                    if (!sample_solution(name, &list[e], witnessed ? q[t] : frac_int(0), piece, &pieces, &x) || !numbers_contain(set, x)) continue;
                    int seen = 0;
                    for (int i = 0; i < knowns && !seen; i++) seen = frac_cmp(known[i], x) == 0;
                    for (int i = 0; i < count && !seen; i++) seen = frac_cmp(value[i], x) == 0;
                    if (!seen) value[count++] = x;
                }
            }
        }
    }
    return count;
}

/* Il campione puo avere molti quantificatori: la larghezza suggerita
 * limita le combinazioni usuali, ma due valori per 40 lettere sono gia
 * oltre un trilione. Ogni visita reale ha quindi un budget separato,
 * configurabile; esaurirlo e mancata verifica, mai conferma parziale. */
static unsigned long long verification_left;
static int verification_limited;
static const char verification_problem[] = "budget di lavoro della verifica indipendente esaurito";

/* Conta una visita del verificatore numerico, senza traboccare il contatore. */
static int verification_step(void) {
    if (verification_limited || !verification_left) {
        verification_limited = 1; fail(verification_problem); return 0;
    }
    verification_left--;
    return 1;
}

/* Prototipo in avanti inevitabile: sample_holds() e sample_at() si chiamano
 * a vicenda. */
static int sample_holds(const Formula *f, int negated);

/* Calcola sul campione la condizione del quantificatore f, negata se
 * negated, con la sua variabile uguale a value; ritorna 1 se risulta vera.
 * Se il "per ogni" f è stato dimostrato per casi sul resto (18o), il numero
 * dice in quale caso si è, e quanto vale il quoziente che la dimostrazione
 * ha usato. */
static int sample_at(const Formula *f, int negated, Frac value) {
    int every = (f->kind == F_FORALL) != negated;
    int cases = every && f->modulus && value.den == 1, outer = split_case;
    env_push(f->variable, rat_frac(value));
    if (cases) {
        long long r = ((value.num % f->modulus) + f->modulus) % f->modulus;
        env_push(f->quotient, rat_int((value.num - r) / f->modulus));
        split_case = (int)r;
    }
    int holds = sample_holds(f->a, negated);
    if (cases) env_pop();
    split_case = outer;
    env_pop();
    return holds;
}

/* Ritorna 1 se la condizione f, negata se negated, risulta vera calcolando
 * con i numeri sul campione, come descritto in testa al capitolo. Tutte le
 * variabili visibili in f devono essere legate a numeri.
 *
 * I conti non lasciano nulla che serva dopo, solo un sì o un no: ogni volta
 * la memoria usata viene restituita all'arena riportando arena_used dov'era.
 * Senza questo passo, le migliaia di confronti di un enunciato con molte
 * variabili riempivano l'arena, e un enunciato vero restava non confermato. */
static int sample_holds(const Formula *f, int negated) {
    if (!verification_step()) return 0;
    Frac sample[SAMPLE_SIZE + 1], value;
    Num left, right;
    size_t mark = arena_used;
    if (failure) return 0;

    switch (f->kind) {
    case F_NOT:
        return sample_holds(f->a, !negated);
    case F_MAP:
        return !negated;
    case F_IN: {
        /* Il valore è un numero: basta guardare se sta nell'insieme. */
        int numbers = rat_number(eval(f->left), &left) && left.im.num == 0;
        arena_used = mark;
        return numbers && (numbers_contain(&f->numbers, left.re) != f->swapped) != negated;
    }
    case F_DIVIDES: {
        /* Due numeri: basta dividere. */
        int numbers = rat_number(eval(f->left), &left) && rat_number(eval(f->right), &right);
        arena_used = mark;
        return numbers && (number_divides(left, right) != f->swapped) != negated;
    }
    case F_LESS: case F_LESS_EQ: case F_SOLVE:
        /* Gli enunciati con una relazione d'ordine e gli insiemi di
         * soluzioni li decide e li ricontrolla la tabella dei segni (18p):
         * qui non arrivano. */
        return 0;
    case F_EQUAL: case F_DISTINCT: {
        /* Espressioni non razionali: come nella dimostrazione, il confronto
         * conta solo se i due membri esistono (closed_gap()). Gli atomi nati
         * dal conto, come la radice di 2, vanno tolti insieme alla memoria:
         * le loro basi vi abitano. */
        if (!term_is_rational(f->left) || !term_is_rational(f->right)) {
            Scratch before = scratch_mark();
            int equal = closed_gap(f);
            scratch_drop(before);
            return equal >= 0 && (equal == (f->kind == F_EQUAL)) != negated;
        }
        int numbers = rat_number(eval(f->left), &left) && rat_number(eval(f->right), &right);
        arena_used = mark;
        return numbers && (num_equal(left, right) == (f->kind == F_EQUAL)) != negated;
    }
    case F_AND:
        return negated ? sample_holds(f->a, 1) || sample_holds(f->b, 1) : sample_holds(f->a, 0) && sample_holds(f->b, 0);
    case F_OR:
        return negated ? sample_holds(f->a, 1) && sample_holds(f->b, 1) : sample_holds(f->a, 0) || sample_holds(f->b, 0);
    case F_IMPLIES:
        return negated ? sample_holds(f->a, 0) && sample_holds(f->b, 1) : sample_holds(f->a, 1) || thesis_counted(sample_holds(f->b, 0));
    case F_IFF: {
        /* Le due implicazioni, come in establish(). */
        if (negated) return (sample_holds(f->a, 0) && sample_holds(f->b, 1)) || (sample_holds(f->b, 0) && sample_holds(f->a, 1));
        int forward = sample_holds(f->a, 1) || thesis_counted(sample_holds(f->b, 0));
        return forward && (sample_holds(f->b, 1) || thesis_counted(sample_holds(f->a, 0)));
    }
    case F_FORALL: case F_EXISTS:
        break;
    }

    /* "Esiste": il valore scelto dalla dimostrazione, e solo quello. Deve
     * essere un numero dell'insieme e soddisfare la condizione.
     *
     * Se non regge non se ne cerca un altro: la dimostrazione ha affermato
     * qualcosa di quel valore, ed è quello che va controllato. Prima la
     * verifica ripiegava sugli elementi del campione, e una dimostrazione
     * sbagliata ("nessun x dà y = -2") veniva confermata trovando un altro y
     * la cui controimmagine era semplicemente fuori dal campione. */
    int every = (f->kind == F_FORALL) != negated;
    if (!every && (f->has_witness >> split_case & 1)) {
        int holds = value_now(f->witness[split_case], &value) && numbers_contain(&f->numbers, value);
        arena_used = mark;
        if (holds) {
            env_push(f->variable, rat_frac(value));
            holds = sample_holds(f->a, negated);
            env_pop();
            arena_used = mark;
        }
        return holds;
    }

    /* "Per ogni": tutti gli elementi del campione. "Esiste" per cui la
     * dimostrazione non ha scelto un valore, perché non le è servito: almeno
     * uno. */
    int samples = check_sample(&f->numbers, sample, sample_width);
    for (int i = 0; i < samples; i++) {
        int holds = sample_at(f, negated, sample[i]);
        arena_used = mark;
        if (holds != every) return holds;
    }

    /* Oltre ai primi elementi dell'insieme, i valori che le condizioni
     * impongono (vedi "I valori da provare", in testa al capitolo): per
     * smentire un "per ogni", o confermare un "esiste", serve un valore che
     * renda vera una condizione. Senza questo passo l'ipotesi \exists k \in
     * \mathbb{Z}\ (a - b = 7k) risultava falsa per a = 50 e b = 1, perché k
     * = 7 non è tra i primi interi; e x = k^2 + 7 non era vera per nessuno
     * dei primi x. Un'implicazione con l'ipotesi falsa conferma qualsiasi
     * dimostrazione. */
    Wanted wanted[MAX_EQUATIONS];
    Frac candidate[SAMPLE_SIZE];
    int conditions = sample_equations(f->a, every ? !negated : negated, NULL, wanted, 0);
    int candidates = sample_candidates(f->variable, &f->numbers, wanted, conditions, sample_width, sample, samples, candidate);
    for (int i = 0; i < candidates; i++) {
        int holds = sample_at(f, negated, candidate[i]);
        arena_used = mark;
        if (holds != every) return holds;
    }
    return every;
}

/* Dimentica ciò che una dimostrazione ha annotato nei nodi di f: i valori
 * scelti e i casi sul resto. Va chiamata prima di riusare la memoria in cui
 * quei valori stanno. */
static void forget_choices(Formula *f) {
    if (!f) return;
    f->has_witness = 0;
    f->modulus = 0;
    forget_choices(f->a);
    forget_choices(f->b);
}

/* Quanti valori provare per ogni variabile quando le variabili da combinare
 * sono depth: le combinazioni sono larghezza^depth, e si scende da
 * SAMPLE_SIZE finché non stanno in MAX_CHECKS. Mai meno di due valori. */
static int width_for(int depth) {
    int width = SAMPLE_SIZE;
    for (;;) {
        long long combinations = 1;
        for (int i = 0; i < depth && combinations <= MAX_CHECKS; i++) {
            if (combinations > MAX_CHECKS / width) { combinations = MAX_CHECKS + 1; break; }
            combinations *= width;
        }
        if (combinations <= MAX_CHECKS || width == 2) return width;
        width--;
    }
}

/* Lega, sopra le variabili generiche già legate a numeri, le variabili che
 * nella dimostrazione annotata in r avevano un valore, con quel valore
 * calcolato in quei numeri: un numero, o un'espressione nelle generiche non
 * ancora legate. Ritorna quante ne ha legate, o -1, senza legarne nessuna,
 * se un conto non riesce o se env non ha abbastanza posti. */
static int bindings_push(const WitnessRecord *r) {
    int saved = env_count;
    for (int i = 0; i < r->bindings; i++) {
        Rat value;
        if (!substituted(r->binding[i].value, &value)) {
            while (i-- > 0) env_pop();
            return -1;
        }
        if (!env_push(r->binding[i].name, value)) { env_count = saved; return -1; }
    }
    return r->bindings;
}

/* Ritorna 1 se ciò che r afferma regge quando le prime `level` variabili
 * generiche di r sono legate a numeri e le altre li prendono come descritto
 * in testa al capitolo: ognuna i valori che le ipotesi le impongono, se ce
 * ne sono, altrimenti i valori di check_sample() con larghezza width.
 * Aggiunge a *satisfied le scelte in cui le ipotesi valgono.
 *
 * Un'ipotesi che in quei numeri non è definita (una divisione per zero) lì
 * non vale, e la scelta non conta. Ogni altro conto che non riesce, nelle
 * ipotesi, nei valori scelti o nella condizione, vuol dire che ciò che r
 * afferma non è confermato. */
static int record_holds(const WitnessRecord *r, int level, int width, long *satisfied) {
    if (!verification_step()) return 0;
    size_t mark = arena_used;
    if (failure) return 0;
    int pushed = bindings_push(r);
    if (pushed < 0) return 0;

    /* Tutte le generiche hanno un numero: prima le ipotesi, poi i valori
     * scelti, il loro insieme e la condizione. */
    if (level == r->generics) {
        int met = 1, holds = 1, named = 0;
        for (int i = 0; i < r->leaves && met && !failure; i++) {
            undefined = 0;
            met = sample_holds(r->leaf[i].source, !r->leaf[i].negated);
            if (failure && undefined) failure = NULL;
        }
        if (met) {
            (*satisfied)++;
            for (int j = 0; j < r->names && holds; j++) {
                Frac w;
                holds = value_now(r->value[j], &w) && numbers_contain(&r->quantifier[j]->numbers, w);
                if (holds) { env_push(r->quantifier[j]->variable, rat_frac(w)); named++; }
            }
            holds = holds && sample_holds(r->body, r->sign);
        }
        while (named-- > 0) env_pop();
        while (pushed-- > 0) env_pop();
        arena_used = mark;
        return holds && !failure;
    }

    /* La variabile di questo livello: i valori che le ipotesi le impongono,
     * calcolati con le variabili già legate, o quelli di check_sample(). */
    const Bound *g = &r->generic[level];
    Wanted wanted[MAX_EQUATIONS];
    Frac value[SAMPLE_SIZE + 1];
    int conditions = 0;
    for (int i = 0; i < r->leaves; i++)
        conditions = sample_equations(r->leaf[i].source, !r->leaf[i].negated, NULL, wanted, conditions);
    int values = sample_candidates(g->name, g->numbers, wanted, conditions, width, NULL, 0, value);
    while (pushed-- > 0) env_pop();
    arena_used = mark;
    if (!values) values = check_sample(g->numbers, value, width);
    for (int i = 0; i < values; i++) {
        env_push(g->name, rat_frac(value[i]));
        int holds = record_holds(r, level + 1, width, satisfied);
        env_pop();
        arena_used = mark;
        if (!holds) return 0;
    }
    return 1;
}

/* La verifica dei valori annotati da 18u-3 (record_holds()). Ritorna NULL se
 * reggono tutti, ognuno su abbastanza scelte che soddisfano le ipotesi (vedi
 * "Quante prove servono", in testa al capitolo); altrimenti il motivo per cui
 * il verdetto non va emesso. */
static const char *records_doubt(void) {
    for (int k = 0; k < record_count; k++) {
        const WitnessRecord *r = &witness_records[k];
        long satisfied = 0;
        verification_left = verification_work_limit; verification_limited = 0;
        int holds = record_holds(r, 0, width_for(r->generics), &satisfied);
        failure = NULL;
        if (verification_limited) return verification_problem;
        if (!holds) return "la verifica indipendente, sui numeri, non conferma un valore scelto dalla dimostrazione per un \"esiste\"";
        if (satisfied < MIN_SATISFIED)
            return "la verifica indipendente non ha trovato valori che soddisfano le ipotesi con cui ricontrollare un valore scelto dalla dimostrazione";
    }
    return NULL;
}

/* Calcola con i numeri l'immagine dell'elemento value del dominio di map,
 * un'applicazione definita per casi (17s), senza fidarsi del primo caso che
 * vale: tutti i casi che valgono devono dare lo stesso numero, e almeno uno
 * deve valere. Se la regola com'è scritta c'è (i casi vengono dai suoi
 * valori assoluti), anche lei deve dare quel numero: è il controllo della
 * lettura per casi. Mette il numero in *image e ritorna 1 se tutto torna. */
static int cases_image(const Map *map, Rat value, Num *image) {
    int found = 0;
    Num other;
    env_push(map->parameter, value);
    for (int i = 0; i < map->cases && !failure; i++) {
        int holds = condition_computed(map->piece[i].when);
        if (holds < 0) found = -1;
        if (holds != 1 || found < 0) continue;
        if (!rat_number(eval(map->piece[i].value), &other)) found = -1;
        else if (found && !num_equal(other, *image)) found = -1;
        else { *image = other; found = 1; }
    }
    if (found > 0 && map->body && (!rat_number(eval(map->body), &other) || !num_equal(other, *image))) found = -1;
    env_pop();
    return found > 0 && !failure;
}

/* Ritorna 1 se, sul campione del dominio, la regola di map dà sempre un
 * numero che sta nel codominio. Per una definizione per casi, lo dà nel
 * modo di cases_image(). */
static int map_holds_on_sample(const Map *map) {
    Frac sample[SAMPLE_SIZE], other[SAMPLE_SIZE];
    numbers_sample(&map->domain, sample, SAMPLE_SIZE);

    /* Per un'operazione, ogni coppia del campione dei due insiemi. */
    int seconds = map->binary ? SAMPLE_SIZE : 1;
    if (map->binary) numbers_sample(&map->second, other, SAMPLE_SIZE);
    for (int i = 0; i < SAMPLE_SIZE; i++) {
        for (int j = 0; j < seconds; j++) {
            Num value;
            if (map->cases) {
                if (!cases_image(map, rat_frac(sample[i]), &value)) return 0;
            } else {
                env_push(map->parameter, rat_frac(sample[i]));
                if (map->binary) env_push(map->parameter2, rat_frac(other[j]));
                Rat image = eval(map->body);
                if (map->binary) env_pop();
                env_pop();
                if (failure || !rat_number(image, &value)) return 0;
            }
            if (value.im.num != 0 || !numbers_contain(&map->codomain, value.re)) return 0;
        }
    }
    return 1;
}

/* Ritorna, per un'applicazione definita per casi i cui casi non si sono
 * dimostrati una definizione (18v-6), che cosa trova il campione del
 * dominio: un punto in cui nessun caso vale, due casi che valgono insieme e
 * danno valori diversi, o un valore fuori dal codominio. Il motivo sta in un
 * testo che vale fino alla chiamata successiva; NULL se il campione non trova
 * nulla, o se le condizioni non si calcolano con i numeri, perché nominano
 * un parametro (17s). */
static const char *cases_fault(const Map *map) {
    static char reason[160];
    Frac sample[2 * SAMPLE_SIZE];
    Num value, other;
    numbers_sample(&map->domain, sample, 2 * SAMPLE_SIZE);
    for (int i = 0; i < 2 * SAMPLE_SIZE && !failure; i++) {
        int applies = 0, clash = 0;
        env_push(map->parameter, rat_frac(sample[i]));
        for (int k = 0; k < map->cases && !failure; k++) {
            int holds = condition_computed(map->piece[k].when);
            if (holds < 0) { env_pop(); failure = NULL; return NULL; }
            if (!holds || !rat_number(eval(map->piece[k].value), &other)) continue;
            if (applies++ && !num_equal(other, value)) clash = 1;
            value = other;
        }
        env_pop();
        if (failure) break;
        const char *what = !applies ? "nessun caso della definizione vale" : clash ? "due casi della definizione valgono e danno valori diversi"
                         : value.im.num || !numbers_contain(&map->codomain, value.re) ? "il valore cade fuori dal codominio" : NULL;
        if (!what) continue;
        int n = snprintf(reason, sizeof reason, "la definizione per casi non definisce un'applicazione: in %c = ", map->parameter);
        if (sample[i].den == 1) snprintf(reason + n, sizeof reason - (size_t)n, "%lld %s", sample[i].num, what);
        else snprintf(reason + n, sizeof reason - (size_t)n, "%lld/%lld %s", sample[i].num, sample[i].den, what);
        return reason;
    }
    failure = NULL;
    return NULL;
}

/* La verifica dell'enunciato e delle sue applicazioni, con i parametri
 * (17s) dal posto level in su legati, uno per volta, ai valori di
 * check_sample(): ciò che la dimostrazione ha stabilito per ogni valore dei
 * parametri deve reggere in ognuno. Con thesis NULL si guardano solo le
 * applicazioni. Ritorna 1 se tutto regge. */
static int sample_with_parameters(const Formula *thesis, int negated, int level) {
    if (level < statement_parameter_count && env_lookup(statement_parameters[level].name))
        return sample_with_parameters(thesis, negated, level + 1);
    if (level == statement_parameter_count) {
        int holds = !thesis || sample_holds(thesis, negated);
        for (int i = 0; i < map_count; i++) holds = holds && map_holds_on_sample(&maps[i]);
        return holds;
    }
    Frac value[SAMPLE_SIZE + 1];
    int values = check_sample(statement_parameters[level].numbers, value, sample_width);
    for (int i = 0; i < values; i++) {
        env_push(statement_parameters[level].name, rat_frac(value[i]));
        int holds = sample_with_parameters(thesis, negated, level + 1);
        env_pop();
        if (!holds) return 0;
    }
    return 1;
}

/* Il testo delle scelte fatte, per esempio "a = 0, b = 3". */
static char *choice_text;
static size_t choice_capacity;

/* Scrive in choice_text i numeri scelti dalla dimostrazione e ne ritorna
 * l'indirizzo, oppure NULL se non ce ne sono. */
static const char *describe_choices(void) {
    size_t length = 0;
    if (!chosen_count || chosen_by_cases) return NULL;
    /* 128 byte per numero bastano a segni, due interi a 64 bit e notazione
     * di coppie/complessi. Il numero dei legami decide la memoria, non un
     * testo fisso che potrebbe omettere parte del controesempio. */
    if ((size_t)chosen_count > ((size_t)-1 - 1) / 128 ||
        !work_reserve((void **)&choice_text, &choice_capacity, (size_t)chosen_count * 128 + 1, 1)) return NULL;
    for (int i = 0; i < chosen_count; i++) {
        /* 17t-2. Le due componenti di una coppia, scelte una dopo l'altra, si
         * scrivono come la coppia: x = (0, 1), o x = 0 + 1i per un numero
         * complesso (17t-4). */
        int pair = 0, complex = 0;
        for (int k = 0; k < pairs_seen_count && !pair && i + 1 < chosen_count; k++)
            if (pairs_seen[k].part[0] == chosen[i].name && pairs_seen[k].part[1] == chosen[i + 1].name) {
                pair = pairs_seen[k].letter;
                complex = pairs_seen[k].complex;
            }
        if (length < choice_capacity && pair)
            length += (size_t)snprintf(choice_text + length, choice_capacity - length, complex ? "%s%c = " : "%s%c = (", i ? ", " : "", pair);
        for (int j = i; j <= i + (pair != 0); j++) {
            Frac v = chosen[j].value;
            const char *between = j == i ? "" : complex ? (v.num < 0 ? " - " : " + ") : ", ";
            if (complex && j > i && v.num < 0) v.num = -v.num;
            if (length < choice_capacity && !pair)
                length += (size_t)snprintf(choice_text + length, choice_capacity - length, "%s%c = ", i ? ", " : "", chosen[j].name);
            if (length < choice_capacity)
                length += (size_t)snprintf(choice_text + length, choice_capacity - length, "%s%lld", between, v.num);
            if (v.den != 1 && length < choice_capacity)
                length += (size_t)snprintf(choice_text + length, choice_capacity - length, "/%lld", v.den);
        }
        if (length < choice_capacity && pair) length += (size_t)snprintf(choice_text + length, choice_capacity - length, complex ? "i" : ")");
        if (pair) i++;
    }
    return choice_text;
}

/* Verifica indipendente della regola 18r, e il suo verdetto.
 *
 * La regola calcola con i resti: polinomi ridotti modulo un numero, sulle
 * condizioni che ha messo in tabella. Qui lo stesso enunciato viene
 * ricalcolato com'è scritto, senza tabella e senza resti: ogni variabile
 * prende per valore gli interi veri di un periodo, residue_period elementi
 * consecutivi del suo insieme (non i numeri da 0 a M - 1 usati dalla regola,
 * ma quelli da cui l'insieme comincia, o a cavallo dello zero), e ogni
 * condizione è una divisione tra due numeri esatti del capitolo 11. Per il
 * teorema in testa a 18r anche questo è un conto completo: se i due non
 * danno la stessa risposta uno dei due è sbagliato, e il verdetto non viene
 * emesso. */

/* Ritorna il k-esimo, per k da 0 a residue_period - 1, di una fila di
 * elementi di set con resti tutti diversi modulo residue_period: interi
 * consecutivi, e al posto di uno che manca da set il primo dopo di lui con lo
 * stesso resto. */
static long long period_member(const NumberSet *set, long long k) {
    long long x = (set->bounded ? set->low + set->strict : -(residue_period / 2)) + k;
    while (!numbers_contain(set, frac_int(x))) x += residue_period;
    return x;
}

/* Ritorna 1 se esiste un intero k, la variabile di nome name, che soddisfa
 * una delle uguaglianze di e; ogni altra variabile ha un numero per valore.
 * Un'uguaglianza di primo grado in k ha una sola soluzione, e si guarda se è
 * intera; una in cui k non compare vale o non vale per ogni k. */
static int multiple_exists(const Formula *e, int name) {
    Poly num, den, part[2];
    Num slope = num_int(0), constant;
    size_t mark = arena_used;
    if (e->kind == F_OR) return multiple_exists(e->a, name) || multiple_exists(e->b, name);
    Rat gap = rat_add(eval(e->left), eval(e->right), 1);
    int degree = !failure && rat_polynomials(gap, &num, &den) ? poly_split(num, atom_var(name), part, 1) : -1;
    Poly one = poly_const(num_int(1));
    int numbers = degree >= 0 && rat_number((Rat){part[0], one}, &constant) && (degree == 0 || rat_number((Rat){part[1], one}, &slope));
    arena_used = mark;
    if (!numbers) { fail("la verifica sugli interi non sa leggere un'uguaglianza"); return 0; }
    return degree == 0 ? num_is_zero(constant) : number_divides(slope, constant);
}

/* Ritorna 1 se la condizione f, del linguaggio di 18r, è vera calcolando con
 * gli interi: ogni variabile visibile in f deve essere legata a un numero.
 * Un quantificatore prova gli interi di un periodo del suo insieme. Se un
 * conto non riesce annota l'errore: chi chiama non deve fidarsi della
 * risposta. */
static int period_holds(const Formula *f) {
    Num left, right;
    size_t mark = arena_used;
    if (failure) return 0;
    switch (f->kind) {
    case F_NOT:     return !period_holds(f->a);
    case F_AND:     return period_holds(f->a) && period_holds(f->b);
    case F_OR:      return period_holds(f->a) || period_holds(f->b);
    case F_IMPLIES: return !period_holds(f->a) || period_holds(f->b);
    case F_IFF:     return period_holds(f->a) == period_holds(f->b);
    case F_DIVIDES: {
        int numbers = rat_number(eval(f->left), &left) && rat_number(eval(f->right), &right);
        arena_used = mark;
        if (!numbers) fail("la verifica sugli interi non sa calcolare una condizione");
        return numbers && number_divides(left, right) != f->swapped;
    }
    case F_IN: {
        int numbers = rat_number(eval(f->left), &left) && left.im.num == 0;
        arena_used = mark;
        if (!numbers) fail("la verifica sugli interi non sa calcolare una condizione");
        return numbers && numbers_contain(&f->numbers, left.re) != f->swapped;
    }
    case F_FORALL: case F_EXISTS:
        break;
    default:
        fail("la verifica sugli interi ha trovato una condizione che non conosce");
        return 0;
    }
    if (names_a_multiple(f)) return multiple_exists(f->a, f->variable);

    int every = f->kind == F_FORALL, holds = every;
    for (long long k = 0; k < residue_period && holds == every && !failure; k++) {
        env_push(f->variable, rat_int(period_member(&f->numbers, k)));
        holds = period_holds(f->a);
        env_pop();
    }
    return holds;
}

/* Cerca dei resti per le variabili dei "per ogni" in testa a f con cui ciò
 * che segue è falso. Se li trova ritorna 1 e li lascia in residue_name[] e
 * residue_value[], con residue_count variabili. */
static int residue_failure(const Formula *f) {
    if (f->kind != F_FORALL) return !residue_holds(f);
    residue_name[residue_count++] = f->variable;
    for (long long r = 0; r < residue_period; r++) {
        residue_value[residue_count - 1] = r;
        if (residue_failure(f->a)) return 1;
    }
    residue_count--;
    return 0;
}

/* Il testo di ciò che decide_by_residues() ha da riportare: un controesempio
 * come "x = 5, y = 0", oppure le soluzioni come condizione in LaTeX. */
static char residue_text[64 * MAX_CLASSES];

/* 18r, per \{x \in A \mid c\}: l'insieme delle soluzioni di una condizione c
 * del linguaggio di 18r, con A un insieme di interi. solve è il nodo F_SOLVE,
 * già accettato da congruences_read(); riempie *verdict.
 *
 * Le soluzioni sono gli x il cui resto modulo M è uno di quelli "buoni", che
 * si trovano provandoli tutti. Per scriverle come sui libri si cerca il
 * periodo più piccolo d che divide M: se i resti buoni si ripetono ogni d,
 * basta elencare quelli tra 0 e d - 1.
 *
 * Tre controlli, come per le soluzioni della tabella dei segni: i resti
 * buoni devono essere gli stessi calcolando con gli interi veri
 * (period_holds()); e le soluzioni scritte vengono rilette dal lettore del
 * programma e calcolate, sugli stessi interi, come una condizione qualsiasi. */
static void solve_by_residues(const Formula *solve, Verdict *verdict) {
    static char good[MAX_PERIOD];
    const NumberSet *set = &solve->numbers;
    long long period = residue_period, shortest = period, classes = 0;
    int name = solve->variable, length = 0, confirmed = 1;

    /* I resti buoni, con la regola; e la conferma sugli interi. */
    residue_name[0] = name;
    residue_count = 1;
    for (long long r = 0; r < period; r++) {
        residue_value[0] = r;
        good[r] = (char)residue_holds(solve->a);
    }
    residue_count = 0;
    for (long long k = 0; k < period && confirmed; k++) {
        long long x = period_member(set, k);
        env_push(name, rat_int(x));
        confirmed = period_holds(solve->a) == good[((x % period) + period) % period] && !failure;
        env_pop();
    }

    /* Il periodo più piccolo, e quanti resti buoni contiene. */
    for (long long d = 1; d < period && shortest == period; d++) {
        int repeats = period % d == 0;
        for (long long r = d; r < period && repeats; r++) repeats = good[r] == good[r - d];
        if (repeats) shortest = d;
    }
    for (long long r = 0; r < shortest; r++) classes += good[r];
    if (confirmed && classes > MAX_CLASSES && classes < shortest) {
        verdict->outcome = NOT_PROVED;
        verdict->reason = "le soluzioni sono troppe classi di resto per elencarle";
        return;
    }

    /* Le soluzioni scritte: nessuna, tutte, oppure le classi di resto. */
    int listed = classes > 0 && classes < shortest;
    if (!listed) length = snprintf(residue_text, sizeof residue_text, "%s %c \\in %.*s", classes ? "\\forall" : "\\nexists", name, (int)(set->end - set->start), set->start);
    for (long long r = 0; r < shortest && listed; r++)
        if (good[r]) length += snprintf(residue_text + length, sizeof residue_text - (size_t)length, "%s%c \\equiv %lld \\pmod{%lld}", length ? " \\lor " : "", name, r, shortest);

    /* Rilettura: ciò che è scritto, letto come una condizione, deve valere
     * esattamente dove vale la condizione di partenza. */
    if (listed && confirmed) {
        syntax_error = NULL;
        cursor = residue_text;
        next_token();
        const Formula *written = logic_formula();
        confirmed = !syntax_error && token.kind == T_END;
        for (long long k = 0; k < period && confirmed; k++) {
            long long x = period_member(set, k);
            env_push(name, rat_int(x));
            confirmed = period_holds(written) == good[((x % period) + period) % period] && !failure;
            env_pop();
        }
    }
    if (!confirmed) {
        failure = syntax_error = NULL;
        unjustified_steps++;
        verdict->outcome = NOT_PROVED;
        verdict->reason = "la verifica indipendente, sugli interi di un periodo, non conferma i resti trovati o le soluzioni scritte";
        return;
    }

    proof_add("Whether $%c$ satisfies the condition depends only on its remainder modulo $%lld$: each part of the condition says that "
              "a polynomial with integer coefficients is a multiple of a number that divides $%lld$. Trying the remainders "
              "$0, \\ldots, %lld$ one by one, the condition holds exactly for $%s$. $\\Box$", name, period, period, period - 1, residue_text);
    verdict->outcome = SOLVED;
    verdict->method = "provando tutti i resti";
    verdict->detail = residue_text;
    verdict->proof = proof_text;
}

/* 18r. Se l'enunciato thesis è fatto solo di congruenze tra interi lo decide
 * provando tutti i resti, riempie *verdict e ritorna 1; altrimenti ritorna 0
 * e non tocca nulla. Nessuna variabile deve essere legata, e la tabella degli
 * atomi deve essere quella dell'enunciato.
 *
 * Il verdetto è DIMOSTRATO o FALSO solo se il conto sui resti e quello sugli
 * interi di un periodo danno la stessa risposta; per un insieme di soluzioni
 * è RISOLTO (solve_by_residues()). */
static int decide_by_residues(const Formula *thesis, Verdict *verdict) {
    /* È del linguaggio? Un conto che non riesce vuol dire solo di no. */
    int deepest = 0;
    congruence_count = residue_count = 0;
    if (!congruences_read(thesis, &deepest) || failure) { failure = NULL; return 0; }

    /* Il periodo, e il numero di casi: devono restare trattabili. */
    long long cases = 1;
    residue_period = 1;
    for (int i = 0; i < congruence_count; i++) {
        __int128 multiple = (__int128)residue_period / gcd128(residue_period, congruences[i].modulus) * congruences[i].modulus;
        if (multiple > MAX_PERIOD) return 0;
        residue_period = (long long)multiple;
    }
    for (int i = 0; i < deepest; i++) {
        if (cases > MAX_RESIDUE_CASES / residue_period) return 0;
        cases *= residue_period;
    }
    proof_reset();
    if (thesis->kind == F_SOLVE) { solve_by_residues(thesis, verdict); return 1; }

    /* La regola, e la verifica indipendente. */
    int holds = residue_holds(thesis);
    int confirmed = period_holds(thesis) == holds && !failure;

    /* Un enunciato falso che comincia con dei "per ogni" ha un controesempio
     * da riportare: i resti trovati, portati dentro gli insiemi. Anche
     * questi numeri vengono ricontrollati, calcolando su di loro ciò che
     * segue i quantificatori. */
    const char *counterexample = NULL;
    if (confirmed && !holds && thesis->kind == F_FORALL && residue_failure(thesis)) {
        const Formula *body = thesis;
        int length = 0;
        for (int i = 0; i < residue_count; i++, body = body->a) {
            long long x = residue_value[i];
            while (!numbers_contain(&body->numbers, frac_int(x))) x += residue_period;
            env_push(body->variable, rat_int(x));
            length += snprintf(residue_text + length, sizeof residue_text - (size_t)length, "%s%c = %lld", i ? ", " : "", body->variable, x);
        }
        confirmed = !period_holds(body) && !failure;
        env_count = residue_count = 0;
        counterexample = residue_text;
    }
    if (!confirmed) {
        failure = NULL;
        unjustified_steps++;
        verdict->outcome = NOT_PROVED;
        verdict->reason = "la verifica indipendente, sugli interi di un periodo, non conferma il conto sui resti";
        return 1;
    }

    /* La dimostrazione scritta: le condizioni, il periodo, l'esito. */
    proof_add(holds ? "\\textbf{Proof.} " : "\\textbf{The statement is false.} ");
    proof_add("Written out, each condition of the statement says that a polynomial with integer coefficients is a multiple of a number: ");
    for (int i = 0; i < congruence_count; i++) {
        proof_add("%s$%lld$ divides $", i ? ", " : "", congruences[i].modulus);
        put_poly(congruences[i].dividend);
        proof_add("$");
    }
    proof_add(". Let $M = %lld$, a common multiple of these numbers. If a letter changes by a multiple of $M$, each polynomial "
              "changes by a multiple of $M$, so no condition changes; and each set of the statement contains integers with every "
              "remainder modulo $M$. It is therefore enough to give each letter the remainders $0, \\ldots, %lld$: %lld case%s. ",
              residue_period, residue_period - 1, cases, cases == 1 ? "" : "s");
    if (holds) proof_add("The statement holds in each of them. $\\Box$");
    else if (counterexample) proof_add("The statement fails for $%s$.", counterexample);
    else proof_add("Computing them shows that the statement is false.");
    verdict->outcome = holds ? PROVED : REFUTED;
    verdict->method = "provando tutti i resti";
    verdict->detail = counterexample;
    verdict->proof = proof_text;
    return 1;
}

/* Ritorna 1 se nella condizione f compare un nodo di tipo kind. */
static int formula_has_kind(const Formula *f, FormulaKind kind) {
    return f && (f->kind == kind || formula_has_kind(f->a, kind) || formula_has_kind(f->b, kind));
}

/* 18y. Ritorna 1 se nella condizione f compare una relazione d'ordine, o un
 * insieme di soluzioni: ciò che decide soltanto la tabella dei segni. */
static int formula_has_order(const Formula *f) {
    return formula_has_kind(f, F_LESS) || formula_has_kind(f, F_LESS_EQ) || formula_has_kind(f, F_SOLVE);
}

/* Prototipo in avanti inevitabile: le iterate di un'applicazione (17s) si
 * dimostrano come una successione definita per ricorrenza, con il metodo
 * del capitolo 26, che viene dopo (26c). */
static Verdict decide_iterates(const Formula *thesis);

/* Prototipi in avanti inevitabili: un enunciato con applicazioni tra reali si
 * decide svolgendo le definizioni (18v-8), e ciò che si ottiene è di nuovo un
 * enunciato con quantificatori, che decide questa stessa funzione. */
static int real_maps_unfoldable(void);
static Verdict decide_real_maps(const Formula *thesis);

/* Ritorna 1 se l'enunciato in corso definisce le iterate di
 * un'applicazione (17s). */
static int iterates_declared(void) {
    for (int i = 0; i < map_count; i++)
        if (maps[i].iterates) return 1;
    return 0;
}

/* Il lavoro di prove_quantified(), che ne descrive il contratto. Al ritorno
 * la tabella `maps` contiene ancora le applicazioni dell'enunciato. */
static Verdict decide_quantified(const char *formula) {
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, "con le regole sui quantificatori", NULL, NULL};

    /* Ripartenza da zero e parsing. */
    proof_reset();
    arena_used = arena_keep;

    /* Con la memoria ripartono anche le tabelle che vi puntano: gli atomi,
     * le basi che sono polinomi e gli argomenti delle arcotangenti. Le
     * ultime due una volta si azzeravano solo più avanti, dove comincia la
     * ricerca con le regole sui quantificatori: un enunciato deciso prima,
     * dalla tabella dei segni, lasciava ad atan_args[] un puntatore a
     * memoria già riusata, e l'enunciato successivo con un'arcotangente
     * leggeva dati a caso. */
    atom_count = base_poly_count = atan_count = 0;
    failure = NULL;
    env_count = 0;
    map_count = statement_parameter_count = 0;
    syntax_error = NULL;
    cursor = formula;
    next_token();
    Formula *thesis = logic_statement();
    if (token.kind != T_END) syntax("testo inatteso dopo l'enunciato");

    /* Come si sono lette le lettere di coppie (17t-2), per il verdetto:
     * subito, prima che una rilettura ne aggiunga altre. */
    pairs_note_write();

    /* 27j. I segni di derivata dentro le espressioni diventano derivate,
     * prima di ogni altro conto. */
    derivative_signs = 0;
    if (!syntax_error) formula_derivatives_expanded(thesis);

    /* Ipotesi e tesi, poi i controlli che la grammatica non fa. */
    if (!syntax_error && !failure) {
        if ((map_count > 0 || pair_set_count > 0) && thesis->kind == F_IMPLIES) {
            read_definitions(thesis->a);
            thesis = thesis->b;
        }
        for (int i = 0; i < map_count; i++)
            if (!maps[i].body && !maps[i].cases) fail("un'applicazione è dichiarata senza la regola che la definisce");
        pair_sets_check();

        /* I parametri (17s) sono visibili in tutta la tesi, salvo dove una
         * lettera legata li nasconde, e contano tra le variabili a cui la
         * verifica dà un valore. */
        unshadowed_note[0] = 0;
        if (statement_parameter_count && !failure) parameters_unshadowed(thesis);
        scope_parameters();
        quantifier_depth = statement_parameter_count;
        if (!failure) formula_check(thesis);
        scope_count = 0;
    }

    /* 26c. Le iterate di un'applicazione: una successione per ricorrenza. */
    if (!syntax_error && !failure && iterates_declared()) return decide_iterates(thesis);

    /* 27l. Un enunciato con segni di derivata lo decide solo la tabella dei
     * segni, in una variabile reale, e solo se le derivate espanse dicono
     * la derivata in ogni punto che conta. Le altre regole lavorano sui
     * razionali, dove una derivata non ha senso. */
    if (derivative_signs && !syntax_error && !failure) {
        const char *doubt = NULL;
        derivative_edges = 0;
        if (!formula_needs_signs(thesis) || map_count || pair_set_count || has_parameter(thesis) || formula_has_kind(thesis, F_IN) ||
            formula_has_kind(thesis, F_DIVIDES) || (thesis->kind == F_SOLVE && thesis->numbers.integers))
            verdict.reason = "il segno di derivata è trattato negli enunciati su una sola variabile reale, decisi dalla tabella dei segni";
        else if ((doubt = derivative_doubt(thesis))) {
            verdict.outcome = NOT_PROVED;
            verdict.reason = doubt;
        } else {
            decide_by_signs(thesis, &verdict);
            if (derivative_edges && !verdict.note) verdict.note = DERIVATIVE_EDGES;
        }
        return verdict;
    }

    /* 18r. Un insieme di soluzioni tra gli interi: la regola dei resti, se
     * la condizione è fatta di congruenze. */
    if (!syntax_error && !failure && thesis->kind == F_SOLVE && thesis->numbers.integers && !map_count && decide_by_residues(thesis, &verdict))
        return verdict;

    /* 18p. Relazioni d'ordine e numeri reali: li tratta solo la tabella dei
     * segni, che decide da sola. Le altre regole lavorano sui razionali e
     * con = e \neq. Con due lettere reali, un parametro e una variabile, la
     * tabella si fa per casi sul parametro (18t).
     *
     * 18y. Fa eccezione un enunciato sui numeri reali senza relazioni
     * d'ordine che parla di appartenenza o di divisibilità, come "a b^{-1}
     * \in \mathbb{Q}" tra reali positivi: la tabella dei segni non lo
     * tratta, e le regole del capitolo 18 sì, perché quelle che
     * presuppongono variabili razionali lo controllano (vedi 18y, in testa a
     * always_in()). */
    int real_membership = !map_count && !formula_has_order(thesis) &&
                          (formula_has_kind(thesis, F_IN) || formula_has_kind(thesis, F_DIVIDES));
    if (!syntax_error && !failure && formula_needs_signs(thesis) && !real_membership) {
        int reals = 0;
        for (int i = 0; i < map_count; i++) reals = reals || maps[i].domain.reals || maps[i].codomain.reals;
        if (reals && real_maps_unfoldable()) return decide_real_maps(thesis);
        if (reals)
            verdict.reason = "le applicazioni tra numeri reali si decidono svolgendo la definizione solo se regole e condizioni sono "
                             "polinomi, divisi al più per dei numeri, senza parametri né iterate, e con due argomenti solo se vengono "
                             "da \\mathbb{C}, senza casi";
        else if (map_count > 0) verdict.reason = "le relazioni d'ordine e i numeri reali non sono ancora trattati insieme alle applicazioni";
        else if (formula_has_kind(thesis, F_IN) || formula_has_kind(thesis, F_DIVIDES))
            verdict.reason = "le relazioni d'ordine e i numeri reali non sono ancora trattati insieme all'appartenenza a un insieme numerico e alla divisibilità";
        else if (has_parameter(thesis)) decide_with_parameter(thesis, &verdict);
        else {
            decide_by_signs(thesis, &verdict);
            sign_certify(thesis, &verdict);
        }
        return verdict;
    }

    /* Quanti valori provare per ogni variabile nella verifica: dipende da
     * quanti quantificatori stanno uno dentro l'altro. */
    sample_width = width_for(quantifier_depth);

    /* Prima la tesi, poi la sua negazione. Il testo si riscrive da capo ogni
     * volta, perché comincia in modo diverso nei due casi. Anche la memoria
     * riparte da dov'era dopo il parsing: un primo tentativo che la riempie
     * non deve togliere al secondo la possibilità di riuscire.
     *
     * Con dei parametri (17s) la tesi e la negazione si cercano per ogni
     * valore dei parametri, che restano variabili generiche. Una tesi falsa
     * solo per qualche valore si smentisce però con quel valore: dopo i due
     * tentativi soliti, la negazione si cerca con i parametri legati, uno
     * dopo l'altro, ai primi PARAMETER_TRIES elementi del loro insieme. È
     * lecito perché ciò che l'enunciato afferma vale per ogni valore dei
     * parametri: basta che fallisca per uno, in cui le ipotesi valgono (le
     * regole definiscono un'applicazione, 18m), per smentirlo. */
    int stopped = 0, instances = 0;
    size_t parsed = arena_used;
    if (statement_parameter_count) instances = 1;
    for (int i = 0; i < statement_parameter_count; i++) instances *= PARAMETER_TRIES;
    for (int attempt = 0; attempt < 2 + instances && !syntax_error && !failure; attempt++) {
        int negated = attempt > 0, instance = attempt - 2;
        proof_reset();
        forget_choices(thesis);
        arena_used = parsed;
        atom_count = base_poly_count = atan_count = 0;
        chosen_count = 0;
        chosen_by_cases = 0;
        record_count = hypotheses_named = 0;
        if (universal_named) memset(universal_named, 0, universal_named_capacity);
        excluded_count = case_choice_count = region_depth = split_pending = 0;

        /* I parametri (17s) sono variabili generiche dall'inizio, oppure, in
         * uno degli ultimi tentativi, numeri. */
        env_count = 0;
        universal_count = 0;
        if (instance < 0)
            for (int i = 0; i < statement_parameter_count; i++) if (!universal_push(statement_parameters[i])) break;
        split_modulus = split_case = 0;
        search_left = MAX_SEARCH;
        proof_add("\\textbf{%s}\n\\begin{itemize}\n", negated ? "The statement is false." : "Proof.");
        for (int i = 0, rest = instance; i < statement_parameter_count && instance >= 0; i++, rest /= PARAMETER_TRIES) {
            Frac value[PARAMETER_TRIES];
            numbers_sample(statement_parameters[i].numbers, value, PARAMETER_TRIES);
            proof_add("\\item Take $%c = ", statement_parameters[i].name);
            put_frac(value[rest % PARAMETER_TRIES]);
            proof_add("$, an element of $");
            put_numbers(statement_parameters[i].numbers);
            proof_add("$.\n");
            choose(statement_parameters[i].name, value[rest % PARAMETER_TRIES]);
            env_push(statement_parameters[i].name, rat_frac(value[rest % PARAMETER_TRIES]));
        }

        /* 18m. Le regole definiscono davvero delle applicazioni? Se no, si
         * guarda sul campione se la regola è sbagliata o se è solo il
         * programma a non saperlo dimostrare. Il conto sul campione può
         * incontrare una divisione per zero, che qui è una risposta e non
         * un errore: per questo `failure` viene azzerato. */
        int defined = 1;
        for (int i = 0; i < map_count && defined; i++) {
            if (map_defined(&maps[i])) continue;

            /* Con i parametri legati a dei numeri le ipotesi possono non
             * valere per quei numeri: si passa ai successivi. */
            if (instance >= 0) { failure = NULL; defined = 0; continue; }
            int plausible = !failure && sample_with_parameters(NULL, 0, 0);
            failure = NULL;
            const char *fault = maps[i].cases && !plausible && !statement_parameter_count ? cases_fault(&maps[i]) : NULL;
            verdict.outcome = NOT_PROVED;
            verdict.reason = fault ? fault
                           : plausible ? "non riesco a dimostrare che la regola dà sempre un valore nel codominio"
                                       : "la regola non definisce un'applicazione: per qualche elemento del dominio il valore manca o cade fuori dal codominio";
            return verdict;
        }
        if (!defined) continue;

        /* Le regole del capitolo 18, con le potenze che fanno da lettere
         * (18x) solo finché cercano. */
        int found;
        power_letters = 1;
        if (negated) {
            proof_add("\\item \\emph{The conclusion fails.}\n\\begin{itemize}\n");
            found = establish_in_regions(thesis, 1, 0);
            proof_add("\\end{itemize}\n");
        } else {
            found = prove_claims(thesis);
        }
        power_letters = 0;
        /* Una ricerca che finisce i tentativi, o la memoria, è una ricerca
         * interrotta: non dice nulla sull'enunciato. */
        if (search_left <= 0 || failure == OUT_OF_MEMORY) stopped = 1;
        if (failure == OUT_OF_MEMORY) failure = NULL;
        else if (!found || failure) continue;
        if (!found) continue;
        proof_add("\\end{itemize}\n$\\Box$");

        /* Verifica indipendente: l'enunciato com'è scritto, quante prove
         * hanno trovato vere le ipotesi, i valori scelti da 18u-3 (vedi la
         * testa del capitolo 19). Come sopra, un errore di calcolo qui è una
         * mancata conferma. */
        sample_theses = 0;
        verification_left = verification_work_limit; verification_limited = 0;
        int confirmed = sample_with_parameters(thesis, negated, 0);
        const char *doubt = NULL;
        if (verification_limited) doubt = verification_problem;
        else if (failure || !confirmed) doubt = "la verifica indipendente, su un campione di numeri, non conferma la dimostrazione";
        else if (hypotheses_named && sample_theses < MIN_SATISFIED)
            doubt = "la verifica indipendente non ha trovato valori del campione che soddisfano le ipotesi, e quindi non ha controllato la tesi";
        else doubt = records_doubt();
        if (doubt) {
            failure = NULL;
            verdict.outcome = NOT_PROVED;
            verdict.reason = doubt;
        } else {
            verdict.outcome = negated ? REFUTED : PROVED;
            verdict.detail = negated ? describe_choices() : NULL;
            verdict.proof = proof_text;
            /* Le lettere di coppie le dicono già la dimostrazione e il
             * controesempio (17t-2); una lettera rinominata no. */
            if (unshadowed_note[0]) verdict.note = unshadowed_note;
        }
        return verdict;
    }

    /* 18r. Le regole che seguono la struttura non hanno deciso: se
     * l'enunciato è fatto solo di congruenze tra interi lo decide il conto
     * su tutti i resti. Viene dopo le altre perché, dove bastano, quelle
     * scrivono la dimostrazione passo per passo; e riparte da zero, perché
     * un loro conto uscito dai limiti non riguarda questo. */
    if (!syntax_error && !map_count) {
        const char *before = failure;
        failure = NULL;
        arena_used = parsed;
        atom_count = base_poly_count = atan_count = 0;
        env_count = universal_count = 0;
        if (decide_by_residues(thesis, &verdict)) return verdict;
        failure = before;
    }

    /* Notazione o conto fuori portata, oppure nessuna delle due prove
     * riuscita. */
    if (syntax_error || failure) {
        verdict.reason = syntax_error ? syntax_error : failure;
        return verdict;
    }
    verdict.outcome = NOT_PROVED;
    verdict.reason = stopped ? "la ricerca è stata interrotta: troppi tentativi senza arrivare a una dimostrazione"
                             : "le regole disponibili non bastano né a dimostrare né a smentire la tesi";
    return verdict;
}

/* Decide l'enunciato con quantificatori scritto in formula e ne ritorna il
 * verdetto, con la dimostrazione scritta.
 *
 * Se l'enunciato dichiara delle applicazioni deve avere la forma "ipotesi
 * implica tesi", con le dichiarazioni e le regole come ipotesi; altrimenti è
 * tutto tesi. Si prova a dimostrare la tesi e, se non riesce, la sua
 * negazione: nel primo caso il verdetto è DIMOSTRATO, nel secondo FALSO.
 *
 * Svuota l'arena e la tabella degli atomi: i risultati di chiamate precedenti
 * non sono più validi. */
static Verdict prove_quantified(const char *formula) {
    Verdict verdict = decide_quantified(formula);

    /* Le applicazioni dichiarate valgono solo per questo enunciato: il parser
     * delle espressioni, che serve anche agli altri metodi, non deve più
     * vederle (vedi `maps`, capitolo 8). Lo stesso per i parametri (17s). */
    map_count = statement_parameter_count = 0;
    return verdict;
}

/* 18v-8. LE APPLICAZIONI TRA NUMERI REALI: LA DEFINIZIONE SVOLTA
 *
 * A che cosa serve. "f(x) = x^{2} per x \ge 0, x(3 - x) per x < 0: f è
 * suriettiva su \mathbb{R}." Le regole 18a-18v lavorano sui razionali: tra i
 * reali la controimmagine di y è \sqrt{y}, che come valore di un "esiste" non
 * si scrive con un polinomio. Ma tra i reali c'è un'altra strada: tolta
 * l'applicazione, ciò che resta è un enunciato con confronti tra polinomi in
 * lettere reali, che la tabella dei segni decide da sola, con una lettera
 * (18p) o con due, una per parametro (18t, che proietta, divide la retta del
 * parametro in celle e ricontrolla la proiezione con un altro conto, 18t-h).
 * "Per ogni y esiste x con f(x) = y" diventa
 *
 *     \forall y\ \exists x\ ((x \ge 0 \land x^{2} = y) \lor (x < 0 \land x(3 - x) = y))
 *
 * e 18t trova, caso per caso su y, se l'insieme degli x è vuoto.
 *
 * Svolgere la definizione. Una condizione P in cui compare f(t), con f data
 * dai casi (c_i, e_i), vale esattamente quando vale una delle c_i(t) \land
 * P(e_i(t)): se i casi coprono il dominio, uno vale in t, e dove vale c_i è
 * f(t) = e_i(t) (lo dice l'ipotesi); viceversa, se valgono c_i(t) e P(e_i(t)),
 * è f(t) = e_i(t), quindi P(f(t)). Con una regola sola, f(t) è e(t). Si
 * svolge prima l'applicazione più interna, il cui argomento non ne contiene
 * altre. Le ipotesi su cui poggia lo svolgimento (i casi coprono il dominio,
 * dove si sovrappongono danno lo stesso valore, i valori stanno nel
 * codominio) sono anch'esse enunciati tra reali senza applicazioni, e le
 * decide prima la tabella dei segni.
 *
 * Il testo. Lo svolgimento si fa sugli alberi, e il risultato si scrive in
 * LaTeX (put_formula()) e si rilegge da capo, come ogni enunciato: è la via
 * di 17j, e la dimostrazione scritta cita ciò che è stato davvero dimostrato.
 * La tesi si divide nelle sue affermazioni, una congiunzione alla volta,
 * perché 18t vuole un parametro solo per enunciato.
 *
 * Che cosa si chiede. Applicazioni tra insiemi di reali, con regole e
 * condizioni che sono polinomi, o divise soltanto per numeri: dove
 * l'applicazione è definita, il valore svolto lo è sempre, e la tabella dei
 * segni non deve occuparsi di punti in cui un membro non esiste. Nessun
 * parametro, nessuna iterata. Le applicazioni a valori in coppie arrivano
 * già divise nelle loro componenti (17s). Di due argomenti ci sono solo
 * quelle di \mathbb{C}, che il lettore ha scritto come applicazioni di due
 * reali, la parte reale e la parte immaginaria (17s): con una regola sola,
 * senza casi, e il codominio senza estremi né punti tolti, perché le due
 * componenti del valore non hanno condizioni proprie.
 *
 * Gli "esiste" tra i reali (18v-11). Svolta la definizione, una parte può
 * avere più lettere di quante la tabella dei segni ne decida: per f di
 * \mathbb{C}, "f non è iniettiva" diventa "esistono a, A, b, B reali con ...",
 * quattro lettere. Se la parte comincia con degli "esiste" su tutto
 * \mathbb{R} (un "non per ogni" è un "esiste"), si danno loro i primi
 * razionali, e ciò che resta, con i numeri al posto delle lettere, è un
 * enunciato nuovo da decidere da capo: se è dimostrato, quei numeri sono i
 * valori degli "esiste", perché un razionale è un reale. È la regola 18j
 * portata tra i reali: prova degli esempi, e quando nessuno va bene la parte
 * resta non dimostrata, mai smentita, perché un esempio che manca tra i
 * primi razionali non dice nulla degli altri reali.
 *
 * Il certificato. Ogni enunciato svolto porta il suo, quando la tabella dei
 * segni lo scrive; l'enunciato con l'applicazione no, perché il passaggio
 * dall'uno agli altri, lo svolgimento, non è nella notazione dei
 * certificati: il verdetto lo dice.
 */

/* Ritorna 1 se in node ogni divisione è per un numero, senza lettere. */
static int divisions_by_numbers(const Node *node) {
    if (!node) return 1;
    if (node->kind == N_DIV && !node_is_numeral(node->b)) return 0;
    return divisions_by_numbers(node->a) && divisions_by_numbers(node->b) && divisions_by_numbers(node->c);
}

/* Ritorna un'applicazione di node il cui argomento non ne contiene altre, o
 * NULL se node non ne ha. */
static const Node *application_innermost(const Node *node) {
    if (!node) return NULL;
    const Node *inside = application_innermost(node->a);
    if (!inside) inside = application_innermost(node->b);
    if (!inside) inside = application_innermost(node->c);
    return inside ? inside : node->kind == N_APPLY ? node : NULL;
}

/* Ritorna una copia di f nell'arena, con le stesse componenti. */
static Formula *formula_copy(const Formula *f) {
    Formula *copy = formula_node(f->kind, NULL, NULL, f->start);
    *copy = *f;
    return copy;
}

/* Ritorna la congiunzione di a e b, o b se a è NULL. */
static Formula *conjoined(Formula *a, Formula *b) {
    if (!a) return b;
    Formula *both = formula_node(F_AND, a, b, NULL);
    both->start = both->end = NULL;
    return both;
}

/* 18v-8. Ritorna la condizione f con ogni applicazione svolta come descritto
 * in testa al paragrafo: un albero nuovo, nell'arena; NULL, con fail(), se
 * un'applicazione non si svolge: un'iterata, o una di due argomenti con dei
 * casi o scritta con un argomento solo. */
static Formula *applications_unfolded(const Formula *f) {
    if (!f || failure) return NULL;
    Formula *copy = formula_copy(f);
    if (f->a) copy->a = applications_unfolded(f->a);
    if (f->b) copy->b = applications_unfolded(f->b);

    /* Un confronto, un'appartenenza o una divisibilità: l'applicazione più
     * interna, poi di nuovo. */
    const Node *apply = application_innermost(f->left);
    if (!apply) apply = application_innermost(f->right);
    if (!apply) return copy;
    const Map *map = map_find(apply->name);
    if (!map || apply->c || (!map->body && !map->cases) || (map->binary && (map->cases || !apply->b))) {
        fail("un'applicazione che lo svolgimento non tratta");
        return NULL;
    }
    const Node *const argument[2] = {apply->a, apply->b};
    const int parameter[2] = {map->parameter, map->parameter2};
    int cases = map->cases ? map->cases : 1, arity = map->binary ? 2 : 1;
    Formula *any = NULL;
    for (int i = 0; i < cases && !failure; i++) {
        Node *value = node_substitute(map->cases ? map->piece[i].value : map->body, parameter, argument, arity);
        Formula *atom = formula_copy(f);
        atom->left = node_replaced(f->left, apply, value);
        atom->right = node_replaced(f->right, apply, value);
        Formula *piece = applications_unfolded(atom);
        if (map->cases) piece = conjoined(formula_substitute(map->piece[i].when, &map->parameter, argument, 1), piece);
        if (!any) { any = piece; continue; }
        Formula *either = formula_node(F_OR, any, piece, NULL);
        either->start = either->end = NULL;
        any = either;
    }
    return any;
}

/* Scrive la condizione f in LaTeX, dall'albero, con una parentesi intorno a
 * ogni parte: il testo si rilegge con la grammatica del capitolo 17. */
static void put_formula(const Formula *f) {
    static const char *const joint[] = {[F_AND] = "\\land", [F_OR] = "\\lor", [F_IMPLIES] = "\\implies", [F_IFF] = "\\iff"};
    switch (f->kind) {
    case F_EQUAL: case F_DISTINCT: case F_LESS: case F_LESS_EQ:
        put_node(f->left, 0);
        proof_add(f->kind == F_EQUAL ? " = " : f->kind == F_DISTINCT ? " \\neq " : f->kind == F_LESS ? " < " : " \\le ");
        put_node(f->right, 0);
        return;
    case F_IN:
        put_node(f->left, 0);
        proof_add(f->swapped ? " \\notin " : " \\in ");
        put_numbers(&f->numbers);
        return;
    case F_DIVIDES:
        put_node(f->left, 0);
        proof_add(f->swapped ? " \\nmid " : " \\mid ");
        put_node(f->right, 0);
        return;
    case F_NOT:
        proof_add("\\lnot (");
        put_formula(f->a);
        proof_add(")");
        return;
    case F_AND: case F_OR: case F_IMPLIES: case F_IFF:
        proof_add("(");
        put_formula(f->a);
        proof_add(") %s (", joint[f->kind]);
        put_formula(f->b);
        proof_add(")");
        return;
    case F_FORALL: case F_EXISTS: case F_SOLVE: {
        /* Una parte dei reali, con un estremo o dei punti tolti, diventa
         * \mathbb{R} con la condizione di appartenenza scritta con dei
         * confronti: "per ogni y in A vale P" è "per ogni reale y, y in A
         * implica P", "esiste" vuole y in A e P. La tabella dei segni, che
         * con due lettere le vuole su tutta la retta, le riceve così. */
        const NumberSet *set = &f->numbers;
        int part = set->reals && (set->bounded || set->holes);
        if (f->kind == F_SOLVE) proof_add("\\{%c \\in ", f->variable);
        else proof_add("%s %c \\in ", f->kind == F_FORALL ? "\\forall" : "\\exists", f->variable);
        if (part) proof_add("\\mathbb{R}");
        else put_numbers(set);
        proof_add(f->kind == F_SOLVE ? " \\mid " : "\\ (");
        if (part) {
            proof_add("(");
            if (set->bounded) proof_add("%c %s %lld", f->variable, set->strict ? ">" : "\\ge", set->low);
            for (int i = 0; i < set->holes; i++) {
                proof_add("%s%c \\neq ", set->bounded || i ? " \\land " : "", f->variable);
                put_frac(set->hole[i]);
            }
            proof_add(f->kind == F_FORALL ? ") \\implies (" : ") \\land (");
        }
        put_formula(f->a);
        if (part) proof_add(")");
        proof_add(f->kind == F_SOLVE ? "\\}" : ")");
        return;
    }
    default:
        fail("una condizione che lo svolgimento non sa scrivere");
    }
}

/* Mette in out, di size byte, il testo di f scritto da put_formula(), e
 * ritorna 1; 0 se non ci sta o se la scrittura non riesce. Il testo nasce
 * nella dimostrazione, che resta com'era. */
static int formula_text(const Formula *f, char *out, size_t size) {
    size_t start = proof_length;
    put_formula(f);
    size_t length = proof_length - start;
    int fits = length + 1 < size && !failure && proof_length + 1 < PROOF_BYTES;
    if (fits) {
        memcpy(out, proof_text + start, length);
        out[length] = 0;
    }
    proof_cut(start);
    return fits;
}

/* Ritorna 1 se l'espressione node è un polinomio, o una sua divisione per
 * numeri: un'espressione razionale definita ovunque. */
static int node_everywhere(const Node *node) { return term_is_rational(node) && divisions_by_numbers(node); }

/* Ritorna 1 se ogni condizione atomica di f confronta espressioni definite
 * ovunque. */
static int formula_everywhere(const Formula *f) {
    if (!f) return 1;
    return node_everywhere(f->left) && node_everywhere(f->right) && formula_everywhere(f->a) && formula_everywhere(f->b);
}

/* Ritorna 1 se le applicazioni dell'enunciato in corso sono di quelle che
 * 18v-8 svolge: tra insiemi di reali, con regole e condizioni definite
 * ovunque, senza parametri né iterate; di due argomenti solo quelle di
 * \mathbb{C} (non un'operazione scritta con un simbolo), senza casi e con il
 * codominio intero. */
static int real_maps_unfoldable(void) {
    if (!map_count || statement_parameter_count) return 0;
    for (int i = 0; i < map_count; i++) {
        const Map *map = &maps[i];
        if (map->iterates || !map->domain.reals || !map->codomain.reals) return 0;
        if (map->binary && (map->cases || map->codomain.bounded || map->codomain.holes || !map->second.reals || (map->name >= OPERATION_NAMES && map->name < GREEK_NAMES))) return 0;
        if (!map->cases && !node_everywhere(map->body)) return 0;
        for (int k = 0; k < map->cases; k++)
            if (!node_everywhere(map->piece[k].value) || !formula_everywhere(map->piece[k].when)) return 0;
    }
    return 1;
}

/* Il nodo del numero razionale v. */
static Node *node_of_frac(Frac v) {
    Node *size = v.den == 1 ? node_num(llabs(v.num)) : node_new(N_DIV, node_num(llabs(v.num)), node_num(v.den));
    return v.num < 0 ? node_new(N_NEG, size, NULL) : size;
}

/* Ritorna "\forall x \in A\ (body)", con x e A la variabile e il dominio di
 * map. */
static Formula *over_domain(const Map *map, Formula *body) {
    Formula *all = formula_node(F_FORALL, body, NULL, NULL);
    all->start = all->end = NULL;
    all->variable = map->parameter;
    all->numbers = map->domain;
    return all;
}

/* Le affermazioni di 18v-8, in testo: le ipotesi su cui poggia lo
 * svolgimento, e le parti della tesi svolte. */
typedef struct {
    int count;                        /* quante, in text[] */
    int definitions;                  /* le prime: le ipotesi sulle definizioni */
    char text[MAX_UNFOLDINGS][MAX_FORMULA];
    const char *source[MAX_UNFOLDINGS];  /* le parti della tesi come sono scritte; per un'ipotesi, che cosa dice */
    size_t length[MAX_UNFOLDINGS];
    int letters[MAX_UNFOLDINGS];         /* 18v-11: le lettere degli "esiste" in testa alla parte, in letter[] */
    int letter[MAX_UNFOLDINGS][MAX_WITNESS_LETTERS];
    char rest[MAX_UNFOLDINGS][MAX_FORMULA];  /* e ciò che segue, con le negazioni portate dentro */
} Unfolded;

/* Aggiunge f, scritta, alle affermazioni u; ritorna 0 se non c'è posto. */
static int unfolded_add(Unfolded *u, const Formula *f, const char *source, size_t length) {
    if (u->count == (int)(sizeof u->text / sizeof *u->text) || !formula_text(f, u->text[u->count], MAX_FORMULA)) return 0;
    u->source[u->count] = source;
    u->length[u->count++] = length;
    return 1;
}

/* 18v-11. Mette in u, per l'ultima parte aggiunta, le lettere degli
 * "esiste" su tutto \mathbb{R} con cui comincia f (letta negata se negated:
 * un "non per ogni" è un "esiste"), al più MAX_WITNESS_LETTERS, e il testo di
 * ciò che segue, con la negazione portata davanti. */
static int witness_prefix(Unfolded *u, const Formula *f, int negated) {
    int k = u->count - 1, count = 0;
    for (;;) {
        if (f->kind == F_NOT) { negated = !negated; f = f->a; continue; }
        int exists = (f->kind == F_EXISTS) != negated && (f->kind == F_EXISTS || f->kind == F_FORALL);
        if (!exists || !f->numbers.reals || f->numbers.bounded || f->numbers.holes || count == MAX_WITNESS_LETTERS) break;
        u->letter[k][count++] = f->variable;
        f = f->a;
    }
    u->letters[k] = count;
    if (!count) return 1;
    char *rest = u->rest[k];
    size_t used = 0;
    if (negated) { strcpy(rest, "\\lnot ("); used = strlen(rest); }
    if (!formula_text(f, rest + used, MAX_FORMULA - used - 2)) return 0;
    if (negated) strcat(rest, ")");
    return 1;
}

/* Aggiunge a u le parti della congiunzione f, svolte. */
static int claims_unfolded(Unfolded *u, const Formula *f) {
    if (f->kind == F_AND) return claims_unfolded(u, f->a) && claims_unfolded(u, f->b);
    Formula *plain = applications_unfolded(f);
    return plain && unfolded_add(u, plain, f->start, (size_t)(f->end - f->start)) && witness_prefix(u, plain, 0);
}

/* 18v-11. Prova a dimostrare la parte k di u, che comincia con degli
 * "esiste" tra i reali, dando a ognuno un razionale: i primi elementi di
 * \mathbb{Q}, tanti quanti le lettere permettono. Ciò che segue, con i numeri
 * al posto delle lettere, si riscrive (draft_rewrite()) e si decide da capo:
 * se è dimostrato, quei numeri sono i valori degli "esiste", e la parte è
 * dimostrata, perché un razionale è un reale. Ritorna il verdetto della
 * prima scelta dimostrata, o uno con outcome NOT_PROVED; in *values le
 * scelte, scritte. */
static Verdict witnesses_tried(const Unfolded *u, int k, char *values, size_t size) {
    Verdict none = {NOT_PROVED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    int letters = u->letters[k], width = letters <= 2 ? 5 : 3;
    Frac sample[5];
    numbers_sample(&(NumberSet){.reals = 0}, sample, width);
    long long combinations = 1;
    for (int i = 0; i < letters; i++) combinations *= width;
    for (long long c = 0; c < combinations; c++) {
        char number[MAX_WITNESS_LETTERS][48];
        const char *to[MAX_WITNESS_LETTERS];
        size_t written = 0;
        for (long long i = 0, rest = c; i < letters; i++, rest /= width) {
            Frac v = sample[rest % width];
            if (v.den == 1) snprintf(number[i], sizeof number[i], "(%lld)", v.num);
            else snprintf(number[i], sizeof number[i], "(%s\\frac{%lld}{%lld})", v.num < 0 ? "-" : "", llabs(v.num), v.den);
            to[i] = number[i];
            written += (size_t)snprintf(values + written, size > written ? size - written : 0, "%s%c = %s", i ? ", " : "", u->letter[k][i], number[i]);
        }

        /* Il testo con i numeri: nasce nella bozza del lettore. */
        static char closed[MAX_FORMULA];
        syntax_error = NULL;
        draft_length = 0;
        draft_rewrite(u->rest[k], u->rest[k] + strlen(u->rest[k]), u->letter[k], to, letters);
        if (syntax_error || draft_length >= sizeof closed) { syntax_error = NULL; continue; }
        memcpy(closed, draft, draft_length);
        closed[draft_length] = 0;
        Verdict tried = prove_quantified(closed);
        if (tried.outcome == PROVED) return tried;
    }
    return none;
}

/* Aggiunge a u, per ogni applicazione, gli enunciati tra reali che dicono
 * che la sua definizione dà un valore, uno solo, nel codominio: i casi
 * coprono il dominio, dove due valgono insieme i valori coincidono, e ogni
 * valore sta sopra l'estremo del codominio e lontano dai suoi punti tolti. */
static int definitions_unfolded(Unfolded *u) {
    for (int i = 0; i < map_count; i++) {
        const Map *map = &maps[i];
        const NumberSet *to = &map->codomain;
        int cases = map->cases ? map->cases : 1;
        if (map->cases) {
            Formula *cover = NULL;
            for (int k = 0; k < map->cases; k++) {
                if (!cover) { cover = (Formula *)map->piece[k].when; continue; }
                Formula *either = formula_node(F_OR, cover, (Formula *)map->piece[k].when, NULL);
                either->start = either->end = NULL;
                cover = either;
            }
            if (!unfolded_add(u, over_domain(map, cover), "The cases cover the domain", 0)) return 0;
            for (int j = 0; j < map->cases; j++)
                for (int k = j + 1; k < map->cases; k++) {
                    Formula *same = formula_node(F_EQUAL, NULL, NULL, NULL), *both = conjoined((Formula *)map->piece[j].when, (Formula *)map->piece[k].when);
                    same->start = same->end = NULL;
                    same->left = map->piece[j].value;
                    same->right = map->piece[k].value;
                    Formula *agree = formula_node(F_IMPLIES, both, same, NULL);
                    agree->start = agree->end = NULL;
                    if (!unfolded_add(u, over_domain(map, agree), "Where two cases hold together, they give the same value", 0)) return 0;
                }
        }
        if (!to->bounded && !to->holes) continue;
        for (int k = 0; k < cases; k++) {
            Node *value = map->cases ? map->piece[k].value : map->body;
            Formula *inside = NULL;
            if (to->bounded) {
                inside = formula_node(to->strict ? F_LESS : F_LESS_EQ, NULL, NULL, NULL);
                inside->left = node_num(to->low);
                inside->right = value;
            }
            for (int h = 0; h < to->holes; h++) {
                Formula *away = formula_node(F_DISTINCT, NULL, NULL, NULL);
                away->left = value;
                away->right = node_of_frac(to->hole[h]);
                inside = conjoined(inside, away);
            }
            if (map->cases) {
                inside = formula_node(F_IMPLIES, (Formula *)map->piece[k].when, inside, NULL);
            }
            if (!unfolded_add(u, over_domain(map, inside), "The values lie in the codomain", 0)) return 0;
        }
    }
    u->definitions = u->count;
    return 1;
}

/* 18v-8. Decide la tesi thesis, di un enunciato con applicazioni tra reali
 * che real_maps_unfoldable() accetta, svolgendo le definizioni come
 * descritto in testa al paragrafo, e ne ritorna il verdetto. Ogni enunciato
 * svolto si decide da capo con prove_quantified(): al ritorno le
 * applicazioni e gli alberi dell'enunciato non valgono più. */
static Verdict decide_real_maps(const Formula *thesis) {
    static Unfolded u;
    static char composed[PROOF_BYTES], counterexample[400];
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, "con la tabella dei segni, sulla definizione svolta", NULL, NULL};
    verdict.reason = "la definizione svolta non si scrive: troppo lunga, o con applicazioni che lo svolgimento non tratta";

    /* I testi, tutti prima di decidere il primo: ogni decisione riparte da
     * zero, e gli alberi non varrebbero più. Il controesempio di un
     * enunciato precedente non vale per questo: prima restava, e un
     * enunciato falso per un'altra ragione lo riportava (fuzz_cases.py). */
    static char reading[200];
    u.count = u.definitions = 0;
    counterexample[0] = 0;
    snprintf(reading, sizeof reading, "%s", pairs_note);
    if (!definitions_unfolded(&u) || !claims_unfolded(&u, thesis) || failure) { failure = NULL; return verdict; }

    /* Le ipotesi della definizione devono valere; le parti della tesi tutte
     * valere, o una fallire. */
    size_t length = 0;
    int refuted = -1;
    for (int k = 0; k < u.count && refuted < 0; k++) {
        static char values[400];
        Verdict part = prove_quantified(u.text[k]);
        int definition = k < u.definitions, witnessed = 0;
        if (!definition && part.outcome != PROVED && part.outcome != REFUTED && u.letters[k]) {
            Verdict tried = witnesses_tried(&u, k, values, sizeof values);
            if (tried.outcome == PROVED) { part = tried; witnessed = 1; }
        }
        if (part.outcome == REFUTED && !definition) {
            refuted = k;
            if (part.detail) snprintf(counterexample, sizeof counterexample, "%s", part.detail);
        } else if (part.outcome != PROVED) {
            verdict.outcome = part.outcome == UNSUPPORTED ? UNSUPPORTED : NOT_PROVED;
            verdict.reason = definition ? (part.outcome == REFUTED ? "la definizione per casi non definisce un'applicazione: la tabella dei segni lo smentisce"
                                                                    : "non riesco a dimostrare che la definizione dà un valore, uno solo, nel codominio")
                                        : part.reason;
            return verdict;
        }

        /* La sua dimostrazione, dopo il titolo, nel testo che si compone. */
        if (!part.proof) continue;
        int n = 0;
        if (definition) n = snprintf(composed + length, sizeof composed - length, "\\item \\emph{%s:} $%s$.\n\n%s\n", u.source[k], u.text[k], part.proof);
        else if (witnessed)
            n = snprintf(composed + length, sizeof composed - length, "\\item \\emph{Claim:} $%.*s$, that is, with the definition unfolded, $%s$. "
                         "It holds with the rational values $%s$, which are real numbers: with them in place of the letters,\n\n%s\n",
                         (int)u.length[k], u.source[k], u.text[k], values, part.proof);
        else n = snprintf(composed + length, sizeof composed - length, "\\item \\emph{Claim:} $%.*s$, that is, with the definition unfolded, $%s$.\n\n%s\n",
                          (int)u.length[k], u.source[k], u.text[k], part.proof);
        if (n < 0 || (size_t)n >= sizeof composed - length) { verdict.reason = "dimostrazione troppo lunga"; return verdict; }
        length += (size_t)n;
    }

    /* Il verdetto, e la dimostrazione: le parti, dentro un elenco. */
    proof_reset();
    proof_add(refuted >= 0 ? "\\textbf{The statement is false.} " : "\\textbf{Proof.} ");
    proof_add("Each value $f(t)$ is replaced by its definition: by the value of the case that holds in $t$, joined to its condition. "
              "The statements without the map are decided by the sign table.\n\\begin{itemize}\n");
    if (proof_length + length + 64 >= PROOF_BYTES) { verdict.reason = "dimostrazione troppo lunga"; return verdict; }
    proof_add("%s\\end{itemize}\n%s", composed, refuted >= 0 ? "" : "$\\Box$");
    verdict.outcome = refuted >= 0 ? REFUTED : PROVED;
    verdict.reason = "lo svolgimento della definizione non è nella notazione dei certificati";
    verdict.detail = refuted >= 0 && counterexample[0] ? counterexample : NULL;
    verdict.proof = proof_text;
    verdict.note = reading[0] ? reading : NULL;
    return verdict;
}

/* =============================================================================
 * 25. INDUZIONE SU UNA DISUGUAGLIANZA
 * ============================================================================
 *
 * A che cosa serve. "La somma degli 1/sqrt(k), per k da 1 a n, è almeno
 * sqrt(n)"; "2^n >= n^3 da n = 10 in poi". Per un'uguaglianza l'ipotesi
 * induttiva dà il valore della somma, e basta sostituirlo (capitolo 13). Per
 * una disuguaglianza dà solo una stima: si può usare in un verso solo, e ciò
 * che resta da controllare non è più "questo polinomio è zero" ma "questa
 * espressione in n non è mai negativa". La prima domanda è algebra; la
 * seconda la sa decidere la tabella dei segni (18p), per ogni n reale.
 *
 * IL TEOREMA
 *
 * Sia D(n) il membro che l'enunciato dice maggiore meno l'altro, così che
 * l'enunciato sia "D(n) >= 0 per ogni intero n >= n0" (oppure "> 0").
 * Supponiamo che per un intero n1 >= n0:
 *
 *   25a. D(n) >= 0 per n = n0, ..., n1;
 *   25b. per ogni intero n >= n1 valga
 *
 *            U(n) D(n+1) = V(n) D(n) + P(n) T(n),
 *
 *        con U(n) diverso da zero, V(n)/U(n) >= 0, P(n)/U(n) >= 0 e
 *        T(n) > 0.
 *
 * Allora D(n) >= 0 per ogni intero n >= n0. Infatti fino a n1 lo dice 25a; e
 * se D(n) >= 0 per un n >= n1, dividendo l'identità per U(n) si ha
 * D(n+1) = (V/U) D(n) + (P/U) T, somma di due numeri non negativi.
 *
 * Con il segno stretto: se in 25a vale D(n) > 0 e in 25b vale V(n)/U(n) > 0,
 * allora D(n+1) > 0, perché il primo addendo è positivo. Quando V è il
 * polinomio nullo l'ipotesi non serve: D(n+1) = (P/U) T, e allora si chiede
 * P(n)/U(n) > 0.
 *
 * Le ipotesi contano tutte. Senza V/U >= 0 la stima D(n) >= 0 verrebbe
 * moltiplicata per un numero negativo e si rovescerebbe. Senza T > 0 il
 * segno di P/U non direbbe nulla del prodotto. Senza U diverso da zero
 * l'identità, in quell'n, non dice nulla di D(n+1): è 0 = 0.
 *
 * DA DOVE VIENE L'IDENTITÀ
 *
 * D(n) e D(n+1) si scrivono con gli stessi atomi (capitolo 13). Alcuni
 * atomi sono funzioni di n che hanno senso anche per n reale: n stesso, la
 * radice di n + 1. Altri no, e sono quelli che l'induzione deve far sparire:
 * una somma fino a n, n!, 2^n. Li chiamiamo discreti. Raccogliendo i monomi
 * discreti, i due numeratori sono
 *
 *     N  = c M + r        (D(n)   = N / Q)
 *     N' = c' M + r'      (D(n+1) = N' / Q')
 *
 * dove M è un monomio discreto, c e c' non contengono atomi discreti, e r,
 * r' sono ciò che resta. Allora, senza nessuna divisione,
 *
 *     c N' - c' N = c r' - c' r,    cioè    (c Q') D(n+1) = (c' Q) D(n) + (c r' - c' r).
 *
 * È l'identità del teorema, con U = c Q', V = c' Q, e P T = c r' - c' r,
 * purché quest'ultimo sia un polinomio senza atomi discreti (P) per un solo
 * monomio discreto (T), fatto di atomi positivi. Tre esempi:
 *
 *   - somma >= R(n): M è la somma, c = c' = 1, e P = (termine nuovo) -
 *     (R(n+1) - R(n)): "il termine che si aggiunge è almeno quanto cresce
 *     il secondo membro";
 *   - 2^n >= n^3: M = 2^n, c = 1, c' = 2, P = 2 n^3 - (n+1)^3: "raddoppiare
 *     n^3 dà più di (n+1)^3", vero da n = 4 in poi;
 *   - n! >= 2^n: M = n!, c = 1, c' = n + 1, T = 2^n, P = n - 1: è il
 *     confronto tra i due rapporti (n+1)!/n! e 2^{n+1}/2^n.
 *
 * Se D non contiene atomi discreti l'ipotesi non serve: U = Q', V = 0,
 * P = N', e l'enunciato in n + 1 è già una disuguaglianza nella sola n.
 *
 * Perché non si divide. Ricavare M dall'ipotesi, come fa il capitolo 13 per
 * le uguaglianze, vorrebbe dire dividere per c, e una frazione di polinomi
 * negli atomi semplifica n/n senza chiedersi se n è zero. Qui c resta al
 * suo posto, dentro U, e che U non si annulli lo dimostra la tabella dei
 * segni insieme al resto: per lei un confronto non vale dove un'espressione
 * non ha un valore.
 *
 * CHI DECIDE I SEGNI
 *
 *   - Di D(n) per n = n0, ..., n1: un conto esatto sui numeri (constant_side()).
 *   - Di V/U e di P/U per ogni n >= n1: la tabella dei segni, a cui si dà
 *     l'enunciato "per ogni n reale, n >= n1 implica V/U >= 0 e P/U >= 0".
 *     Vale per ogni reale, quindi per ogni intero. Il contrario no: se la
 *     tabella lo smentisce in un n non intero, qui non si conclude nulla.
 *   - Di T: atom_is_positive() (13c) per ognuno dei suoi atomi.
 *   - n1: il primo n da cui le due condizioni risultano vere nei valori
 *     calcolati. È solo una proposta, che la tabella poi dimostra o no.
 *
 * CHE COSA SI CONTROLLA, E CHE COSA NO
 *
 *   - L'enunciato deve essere definito per ogni n >= n0 (13c). Qui non ci
 *     sono parametri: una lettera diversa da n farebbe del passo una
 *     disuguaglianza in due variabili, che la tabella non tratta. La
 *     lettera e è il numero di Nepero, come nella tabella.
 *   - Verifica indipendente: D(n) viene calcolato davvero, con i numeri,
 *     per n = n0, ..., n0 + SEARCH_SPAN, senza passare né dall'identità né
 *     dalla tabella. Un valore del segno sbagliato è un controesempio, e il
 *     verdetto è FALSO.
 *   - L'identità scritta nella dimostrazione viene riletta dal testo e
 *     ricalcolata (come in 13g), a partire dai due membri dell'enunciato: i
 *     testi di U, V e P dati alla tabella sono quegli stessi caratteri.
 *   - Non c'è un certificato: la notazione di checker.c non ha né le
 *     disuguaglianze né le radici, e la tabella dei segni non ne emette. Il
 *     verdetto lo dice.
 *
 * Che cosa resta fuori: le disuguaglianze con parametri (Bernoulli con una
 * lettera), quelle in cui la somma compare al quadrato o sotto radice,
 * quelle il cui passo contiene un logaritmo di n insieme a una frazione,
 * quelle con tre o più monomi discreti (2^n + 3^n >= n). La risposta è NON
 * DIMOSTRATO o NON SUPPORTATO.
 */

/* Prototipo in avanti necessario: la base di un atomo è un polinomio, fatto
 * di atomi. */
static int poly_is_discrete(Poly p);

/* Ritorna 1 se l'atomo è discreto: una quantità che dipende da n e che ha
 * senso solo per n intero, o che comunque non è una funzione algebrica di n.
 * Sono le somme e i prodotti fino a n, i termini delle successioni per
 * ricorrenza, le potenze con n all'esponente, e le potenze e i logaritmi che
 * hanno per base una di queste. Non lo sono n, le radici di polinomi in n e
 * i numeri. */
static int atom_is_discrete(int atom) {
    const Atom *a = &atoms[atom];
    if (a->kind == ATOM_BIGOP || a->kind == ATOM_REC) return 1;
    if (a->kind != ATOM_POW && a->kind != ATOM_LN) return 0;
    if (a->kind == ATOM_POW && mono_depends_on_n(&a->exponent)) return 1;
    if (a->base == BASE_ATOM) return atom_is_discrete((int)a->id);
    return a->base == BASE_POLY && poly_is_discrete(base_polys[a->id]);
}

/* Ritorna la parte discreta del monomio m: il prodotto dei suoi fattori che
 * sono atomi discreti, ognuno con il suo esponente. */
static Mono mono_discrete(const Mono *m) {
    Mono part;
    part.count = 0;
    for (int i = 0; i < m->count; i++)
        if (atom_is_discrete(m->factor[i].atom)) part.factor[part.count++] = m->factor[i];
    return part;
}

/* Ritorna 1 se in p compare un atomo discreto. */
static int poly_is_discrete(Poly p) {
    for (int i = 0; i < p.count; i++)
        if (mono_discrete(&p.term[i].mono).count > 0) return 1;
    return 0;
}

/* Ritorna il coefficiente del monomio discreto `which` in p: la somma dei
 * termini di p la cui parte discreta è proprio which, divisi per which. Non
 * contiene atomi discreti. Con which = 1 è la parte di p senza atomi
 * discreti. */
static Poly discrete_coefficient(Poly p, const Mono *which) {
    Mono inverse = mono_pow(which, frac_int(-1));
    Term *buffer = terms_alloc(p.count);
    int used = 0;
    if (!buffer) return (Poly){0, NULL};
    for (int i = 0; i < p.count; i++) {
        Mono own = mono_discrete(&p.term[i].mono);
        if (mono_cmp(&own, which) != 0) continue;
        buffer[used] = p.term[i];
        buffer[used++].mono = mono_mul(&p.term[i].mono, &inverse);
    }
    return poly_finish(buffer, p.count, used);
}

/* Toglie gli atomi discreti dal denominatore di *r, se sono un monomio M
 * comune a tutti i suoi termini: numeratore e denominatore vengono divisi
 * per M, che finisce nel numeratore con gli esponenti cambiati di segno.
 * Così (2n+2)! / ((n+1)^2 n!^2) ha per denominatore il solo (n+1)^2. Il
 * valore non cambia dove M non è zero, cioè dove r è definita. Ritorna 0,
 * senza toccare *r, se il denominatore contiene atomi discreti in un altro
 * modo. */
static int rat_clear_discrete(Rat *r) {
    Mono common = mono_discrete(&r->den.term[0].mono);
    for (int i = 1; i < r->den.count; i++) {
        Mono own = mono_discrete(&r->den.term[i].mono);
        if (mono_cmp(&own, &common) != 0) return 0;
    }
    Term inverse;
    inverse.coef = num_int(1);
    inverse.mono = mono_pow(&common, frac_int(-1));
    r->num = poly_mul(r->num, poly_term(inverse));
    r->den = poly_mul(r->den, poly_term(inverse));
    return 1;
}

/* Mette in *side il segno del numero r e ritorna 1; ritorna 0 se non riesce
 * a stabilirlo. r è il valore di un'espressione senza lettere.
 *
 * Tre strade, dalla più precisa: il conto esatto di number_sign() (18p), che
 * tratta i razionali e le radici quadrate di interi e riconosce lo zero; il
 * test di annullamento del capitolo 12, per uno zero scritto con altri
 * atomi; gli intervalli del capitolo 24, che danno un segno certo quando il
 * numero non è zero. Un errore di questi conti (numeri troppo grandi) vuol
 * dire solo "non so". */
static int constant_side(Rat r, int *side) {
    const char *saved = failure;
    int above = 0, below = 0, known = number_sign(r, side);
    if (!known) {
        failure = saved;
        *side = 0;
        known = poly_vanishes(r.num);
        if (!known && range_side(poly_range(r.num), &above) && range_side(poly_range(r.den), &below)) {
            *side = above * below;
            known = 1;
        }
    }
    known = known && failure == saved;
    failure = saved;
    return known;
}

/* Ritorna D(n) per la disuguaglianza statement: il membro che l'enunciato
 * dice maggiore meno l'altro, con la variabile di induzione legata a n. */
static Rat inequality_gap(const Statement *statement, Rat n) {
    Rat gap = difference(statement, n);
    int upward = statement->relation == REL_GE || statement->relation == REL_GT;
    return upward ? gap : rat_add(rat_int(0), gap, 1);
}

/* L'identità del passo induttivo di una disuguaglianza (25b):
 * u D(n+1) = v D(n) + p t. I polinomi stanno nell'arena.
 * Invariante: u, v e p non contengono atomi discreti; ogni atomo di t è
 * discreto e positivo per ogni n dal caso base in su. */
typedef struct {
    Poly u, v, p;
    Mono t;        /* il monomio T; count == 0 vuol dire T = 1 */
} InequalityStep;

/* Cerca l'identità di 25b che elimina il monomio discreto `which` da
 * d = D(n) e d1 = D(n+1); con which NULL, quella che non usa l'ipotesi.
 * Ritorna 1 e riempie *step se l'identità ha la forma richiesta; 0 se which
 * non compare in D(n), o se ciò che resta non è un polinomio senza atomi
 * discreti per un monomio di atomi positivi da n = base in su. */
static int inequality_step(Rat d, Rat d1, const Mono *which, long long base, InequalityStep *step) {
    Poly rest = d1.num;
    step->u = d1.den;
    step->v = poly_const(num_int(0));
    if (which) {
        /* c N' - c' N: i termini con M si cancellano da soli. */
        Poly c = discrete_coefficient(d.num, which), c1 = discrete_coefficient(d1.num, which);
        if (c.count == 0) return 0;
        rest = poly_add(poly_mul(c, d1.num), poly_mul(c1, d.num), 1);
        step->u = poly_mul(c, d1.den);
        step->v = poly_mul(c1, d.den);
    }

    /* Un prodotto di polinomi non nulli può essere nullo, per le identità
     * tra atomi di term_reduce(): con U = 0 l'identità non dice nulla. */
    if (failure || step->u.count == 0) return 0;

    /* Ciò che resta: P per un solo monomio discreto T, positivo. */
    step->t.count = 0;
    if (rest.count > 0) step->t = mono_discrete(&rest.term[0].mono);
    for (int i = 1; i < rest.count; i++) {
        Mono own = mono_discrete(&rest.term[i].mono);
        if (mono_cmp(&own, &step->t) != 0) return 0;
    }
    for (int f = 0; f < step->t.count; f++)
        if (!atom_is_positive(step->t.factor[f].atom, base)) return 0;
    step->p = discrete_coefficient(rest, &step->t);

    /* La stessa identità con i segni cambiati, se serve perché U cominci con
     * un coefficiente positivo: si legge meglio, e non cambia né V/U né P/U. */
    if (step->u.term[0].coef.re.num < 0) {
        Poly zero = poly_const(num_int(0));
        step->u = poly_add(zero, step->u, 1);
        step->v = poly_add(zero, step->v, 1);
        step->p = poly_add(zero, step->p, 1);
    }
    return !failure;
}

/* Scrive il polinomio p nella dimostrazione e ritorna il pezzo scritto. */
static Span put_terms_span(Poly p) {
    Span span = {proof_length, 0};
    put_terms(p);
    span.to = proof_length;
    return span;
}

/* Mette in *side il segno che l'espressione tree prende quando la variabile
 * di induzione vale l'intero c, e ritorna 1; 0 se lì non è definita o se il
 * segno non si stabilisce. Gli atomi e la memoria del conto vengono tolti. */
static int tree_side(const Node *tree, long long c, int *side) {
    Scratch mark = scratch_mark();
    const char *saved = failure;
    env_count = 0;
    env_push(induction_var, rat_int(c));
    Rat value = eval(tree);
    env_count = 0;
    int known = failure == saved && constant_side(value, side);
    failure = saved;
    scratch_drop(mark);
    return known;
}

/* Prepara la domanda per la tabella dei segni: le condizioni di 25b
 * sull'identità step, da n = *start in su, con *start almeno `from`.
 *
 * Scrive i testi di U, V, P e T, li rilegge e controlla due cose. La prima:
 * che l'identità U D(n+1) = V D(n) + P T, con D scritto a partire dai due
 * membri dell'enunciato, riletta dal testo sia vera (il suo numeratore si
 * annulla). La seconda: da quale n, a partire da `from`, le condizioni
 * valgono nei valori già calcolati, cioè fino a `reached`; quell'n va in
 * *start. Poi mette in claim
 * le condizioni, in LaTeX: "V/U >= 0 e P/U >= 0", oppure le loro varianti
 * con il segno stretto (vedi il teorema). I testi sono scritti in fondo
 * alla dimostrazione in corso solo per poterli rileggere, e poi tolti.
 *
 * Ritorna NULL se riesce, altrimenti il motivo, in italiano. */
static const char *inequality_claim(const Statement *statement, const InequalityStep *step, int strict, long long from,
                                    long long reached, long long *start, char *claim, size_t size) {
    int upward = statement->relation == REL_GE || statement->relation == REL_GT, variable = induction_var;
    const Node *greater = upward ? statement->lhs : statement->rhs, *smaller = upward ? statement->rhs : statement->lhs;
    const Node *successor = node_affine(1, variable, 1);
    size_t opening = proof_length;
    char text[3][MAX_FORMULA], check[MAX_FORMULA];
    const char *problem = NULL;

    /* I testi: U, V, P, T, e i due membri in n + 1 e in n. */
    unwritable = 0;
    Span u = put_terms_span(step->u), v = put_terms_span(step->v), p = put_terms_span(step->p), t = {proof_length, 0};
    put_mono(&step->t);
    t.to = proof_length;
    Span side[4] = {put_side(greater, successor), put_side(smaller, successor), put_side(greater, NULL), put_side(smaller, NULL)};
    if (unwritable || failure || proof_length >= PROOF_BYTES - 1) problem = "il passo induttivo non si lascia scrivere come disuguaglianza nella sola variabile di induzione";

    /* L'identità, riletta. */
    int length = problem ? 0 : snprintf(check, sizeof check,
        "\\left(%.*s\\right) \\cdot \\left(\\left(%.*s\\right) - \\left(%.*s\\right)\\right) = "
        "\\left(%.*s\\right) \\cdot \\left(\\left(%.*s\\right) - \\left(%.*s\\right)\\right) + \\left(%.*s\\right)%s%.*s",
        (int)(u.to - u.from), proof_text + u.from, (int)(side[0].to - side[0].from), proof_text + side[0].from,
        (int)(side[1].to - side[1].from), proof_text + side[1].from, (int)(v.to - v.from), proof_text + v.from,
        (int)(side[2].to - side[2].from), proof_text + side[2].from, (int)(side[3].to - side[3].from), proof_text + side[3].from,
        (int)(p.to - p.from), proof_text + p.from, step->t.count ? " \\cdot " : "", (int)(t.to - t.from), proof_text + t.from);
    Statement identity;
    if (!problem && (length <= 0 || (size_t)length >= sizeof check)) problem = "il passo induttivo è troppo lungo da scrivere";
    if (!problem && !(parse_statement(check, &identity) && !failure &&
                      poly_vanishes(difference(&identity, rat_atom(atom_var(variable))).num) && !failure)) {
        unjustified_steps++;
        problem = "l'identità del passo induttivo, riletta dal testo, non è confermata";
    }

    /* I tre polinomi come espressioni, per calcolarli nei primi n. */
    Node *tree[3] = {NULL, NULL, NULL};
    const Span part[3] = {u, v, p};
    for (int i = 0; i < 3 && !problem; i++) {
        snprintf(text[i], sizeof text[i], "%.*s", (int)(part[i].to - part[i].from), proof_text + part[i].from);
        tree[i] = parse_expression(text[i]);
        if (syntax_error || failure) problem = "il passo induttivo, riletto dal testo, non è un'espressione";
    }
    proof_cut(opening);
    failure = NULL;
    if (problem) return problem;

    /* Da dove valgono le condizioni, nei valori calcolati. */
    int plain = step->v.count == 0;
    *start = from;
    for (long long c = from; c <= reached; c++) {
        int su = 0, sv = 0, sp = 0;
        int holds = tree_side(tree[0], c, &su) && tree_side(tree[1], c, &sv) && tree_side(tree[2], c, &sp) && su != 0 &&
                    (plain ? sp * su >= strict : sv * su >= strict && sp * su >= 0);
        if (!holds) *start = c + 1;
    }
    if (*start > reached) return "il passo induttivo non regge nei primi valori calcolati";

    /* Le condizioni. Con U = 1 le frazioni non servono, e con U = V = 1,
     * il caso di una somma, la prima condizione è 1 > 0 e si tace. */
    char ratio[2][MAX_FORMULA];
    for (int i = 0; i < 2; i++) {
        if (poly_is_one(step->u)) snprintf(ratio[i], sizeof ratio[i], "%s", text[i + 1]);
        else snprintf(ratio[i], sizeof ratio[i], "\\frac{%s}{%s}", text[i + 1], text[0]);
    }
    if (plain) length = snprintf(claim, size, "%s %s 0", ratio[1], strict ? ">" : "\\ge");
    else if (poly_is_one(step->u) && poly_is_one(step->v)) length = snprintf(claim, size, "%s \\ge 0", ratio[1]);
    else length = snprintf(claim, size, "%s %s 0 \\land %s \\ge 0", ratio[0], strict ? ">" : "\\ge", ratio[1]);
    return length > 0 && (size_t)length < size ? NULL : "il passo induttivo è troppo lungo da scrivere";
}

/* Scrive nella dimostrazione il caso n = c di una disuguaglianza: i due
 * membri con il numero al posto di n, i loro valori e quello di D(c). Con
 * first diverso da zero è il caso base, altrimenti uno dei casi successivi
 * controllati uno per uno. Ritorna 1 se ogni formula scritta, riletta (13g),
 * è confermata. */
static int put_inequality_case(const Statement *statement, long long c, int first) {
    const Node *side[2] = {statement->lhs, statement->rhs};
    int variable = induction_var, sound = 1, sign = 0;
    char prefix[64];
    Span text, value;
    proof_add(first ? "\\item \\emph{Base case}, $%c = %lld$. " : "\\item \\emph{Case} $%c = %lld$, checked directly. ", variable, c);
    for (int s = 0; s < 2; s++) {
        Rat low = side_value(side[s], rat_int(c));
        proof_add(s ? " and the right-hand side is $" : "The left-hand side is $");
        text = put_side(side[s], node_num(c));
        int bare = side[s]->kind == N_NUM || (side[s]->kind == N_VAR && side[s]->name == variable);
        if (!bare && put_value(" = ", low, &value)) sound &= reread_equal(text, value, c);
        proof_add("$");
    }

    /* D(c): il valore se si lascia scrivere, e un numero decimale vicino
     * quando il valore contiene radici o logaritmi. */
    Rat gap = inequality_gap(statement, rat_int(c));
    Num number;
    snprintf(prefix, sizeof prefix, ", so $D_{%lld} = ", c);
    constant_side(gap, &sign);
    if (put_value(prefix, gap, &value)) {
        Range near = range_div(poly_range(gap.num), poly_range(gap.den));
        double middle = (near.low + near.high) / 2;
        if (!rat_number(gap, &number) && range_known(near) && middle < 1e6 && middle > -1e6) proof_add(" \\approx %.4f", middle);
        proof_add(sign ? "$, a positive number.\n" : "$.\n");
    } else {
        proof_add(", and their difference $D_{%lld}$ is %s.\n", c, sign ? "positive" : "zero");
    }
    return sound;
}

/* Il lavoro di prove_inequality() che non riguarda la tabella dei segni,
 * sull'enunciato già analizzato: i primi valori (25a e la verifica
 * indipendente), "definito per ogni n", l'identità del passo (25b) e la
 * dimostrazione scritta, a cui manca solo la tabella.
 *
 * variable, has_base e base come per induct(). Se tutto riesce il verdetto è
 * PROVED, con la condizione che la tabella deve ancora dimostrare: la mette
 * in question, lunga al più size, come enunciato "per ogni n reale", e in
 * *start mette l'n da cui parte il passo (n1 nel teorema), che non è mai
 * minore di floor. Ogni altro verdetto è già quello definitivo. */
static Verdict inequality_plan(const Statement *statement, int variable, int has_base, long long base, long long floor,
                               long long *start, char *question, size_t size) {
    static char text[256];
    Verdict verdict = {UNSUPPORTED, variable, base, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    int strict = statement->relation == REL_GT || statement->relation == REL_LT;
    const char *relation = statement->relation == REL_GE ? "\\ge" : statement->relation == REL_LE ? "\\le" :
                           statement->relation == REL_GT ? ">" : "<";
    const char *sign = strict ? ">" : "\\ge";
    induction_var = variable;
    default_base = 1;
    domain_floor = has_base ? base : 1;

    /* D(n) e D(n+1), con gli stessi atomi. La prima valutazione fa nascere
     * gli atomi e calcola default_base, come in induct(). */
    Rat n = rat_atom(atom_var(variable));
    Rat d = inequality_gap(statement, n);
    if (failure) { verdict.reason = failure; return verdict; }
    if (!has_base) base = default_base;
    verdict.base = base;
    Rat d1 = inequality_gap(statement, rat_add(n, rat_int(1), 0));
    if (failure) { verdict.reason = failure; return verdict; }

    /* Nessun parametro: solo n, pi greco e il numero e. La lettera
     * ausiliaria non è dell'enunciato (vedi body_is_positive()). */
    for (int i = 0; i < atom_count; i++)
        if (atoms[i].kind == ATOM_VAR && atoms[i].id != variable && atoms[i].id != VAR_PI && atoms[i].id != VAR_SLACK && atoms[i].id != 'e') {
            verdict.reason = "le disuguaglianze con altre lettere oltre alla variabile di induzione non sono ancora supportate";
            return verdict;
        }

    /* 25a, e la verifica indipendente: il segno di D(c) nei primi valori. Un
     * conto che si ferma a un limite del programma chiude l'elenco dei
     * valori noti; un segno sbagliato è un controesempio. */
    Scratch mark = scratch_mark();
    long long reached = base - 1;
    verdict.outcome = NOT_PROVED;
    for (long long c = base; c <= base + SEARCH_SPAN; c++) {
        int side = 0;
        failure = NULL;
        undefined = 0;
        Rat gap = inequality_gap(statement, rat_int(c));
        if (failure && undefined) {
            snprintf(text, sizeof text, "per %c = %lld l'enunciato non è definito: %s", variable, c, failure);
            failure = NULL;
            verdict.reason = text;
            return verdict;
        }
        int known = !failure && constant_side(gap, &side);
        scratch_drop(mark);
        if (!known) break;
        if (side < 0 || (strict && side == 0)) {
            verdict.outcome = REFUTED;
            verdict.witness = c;
            return verdict;
        }
        reached = c;
    }
    failure = NULL;
    if (reached < base) { verdict.reason = "non riesco a stabilire il segno della differenza dei due membri nel caso base"; return verdict; }

    /* 13c. Definito per ogni n. */
    long long where = base;
    const char *why = NULL;
    int defined = defined_for_every(statement, base, &where, &why);
    scratch_drop(mark);
    if (defined != 1) {
        if (defined < 0) snprintf(text, sizeof text, "non riesco a stabilire che le espressioni dell'enunciato siano definite per ogni %c", variable);
        else snprintf(text, sizeof text, why == REWRITTEN ? "per %c = %lld %s" : "per %c = %lld l'enunciato non è definito: %s", variable, where, why);
        verdict.reason = text;
        return verdict;
    }

    /* 25b. I monomi discreti dei due numeratori. I denominatori non ne
     * devono avere. Tolto un monomio deve restarne al più uno: di solito
     * quindi sono due, ma possono essere di più se gli altri si cancellano,
     * come nella somma degli 1/2^k confrontata con 2 - 1/2^n. */
    enum { MAX_DISCRETE = 4 };
    Mono list[MAX_DISCRETE];
    int count = 0, many = !rat_clear_discrete(&d) || !rat_clear_discrete(&d1);
    const Poly numerator[2] = {d.num, d1.num};
    for (int s = 0; s < 2 && !many; s++)
        for (int i = 0; i < numerator[s].count && !many; i++) {
            Mono own = mono_discrete(&numerator[s].term[i].mono);
            int k = 0;
            while (k < count && mono_cmp(&list[k], &own) != 0) k++;
            if (own.count == 0 || k < count) continue;
            if (count == MAX_DISCRETE) many = 1; else list[count++] = own;
        }

    /* Si prova a eliminare ciascun monomio; senza monomi, l'identità che non
     * usa l'ipotesi. La prima che ha la forma giusta e regge nei primi
     * valori è quella che si scrive. */
    InequalityStep step;
    char claim[MAX_FORMULA];
    const char *problem = "il passo induttivo non si riduce a una disuguaglianza nella sola variabile di induzione";
    int found = 0;
    surd_powers = 1;
    for (int k = 0; k < (count ? count : 1) && !many && !found; k++) {
        failure = NULL;
        if (!inequality_step(d, d1, count ? &list[k] : NULL, base, &step)) continue;
        problem = inequality_claim(statement, &step, strict, base > floor ? base : floor, reached, start, claim, sizeof claim);
        found = !problem;
    }
    failure = NULL;
    int length = found ? snprintf(question, size, "\\forall %c \\in \\mathbb{R}\\ (%c \\ge %lld \\implies (%s))", variable, variable, *start, claim) : 0;
    if (!found || length <= 0 || (size_t)length >= size) {
        verdict.reason = found ? "il passo induttivo è troppo lungo da scrivere" : problem;
        return verdict;
    }

    /* La dimostrazione scritta: i casi da base a start, uno per uno. */
    int sound = 1, plain = step.v.count == 0, upward = statement->relation == REL_GE || statement->relation == REL_GT;
    const Node *successor = node_affine(1, variable, 1);
    proof_add("\\textbf{Proof.} By induction on $%c$. Let $D_{%c}$ be the %s-hand side minus the %s-hand side: the statement says "
              "that $D_{%c} %s 0$ for every integer $%c \\ge %lld$.\n\\begin{itemize}\n",
              variable, variable, upward ? "left" : "right", upward ? "right" : "left", variable, sign, variable, base);
    for (long long c = base; c <= *start; c++) sound &= put_inequality_case(statement, c, c == base);

    /* L'ipotesi, se serve, e ciò che va dimostrato. */
    if (plain) {
        proof_add("\\item \\emph{Inductive step}. Here the inductive hypothesis is not needed. For every $%c \\ge %lld$ we prove the statement for $%c + 1$: $",
                  variable, *start, variable);
    } else {
        proof_add("\\item \\emph{Inductive hypothesis}. Assume the statement for some $%c \\ge %lld$: $", variable, *start);
        put_side(statement->lhs, NULL);
        proof_add(" %s ", relation);
        put_side(statement->rhs, NULL);
        proof_add("$, that is $D_{%c} %s 0$.\n\\item \\emph{Inductive step}. We prove the statement for $%c + 1$: $", variable, sign, variable);
    }
    put_side(statement->lhs, successor);
    proof_add(" %s ", relation);
    put_side(statement->rhs, successor);
    proof_add("$, that is $D_{%c + 1} %s 0$.\n\\begin{itemize}\n", variable, sign);
    sound &= put_new_terms(base);

    /* L'identità: i fattori uguali a 1 e gli addendi nulli si tacciono. */
    proof_add("\\item Written with the same quantities, $D_{%c}$ and $D_{%c + 1}$ satisfy, by exact algebra, $", variable, variable);
    if (!poly_is_one(step.u)) { proof_add("\\left("); put_terms(step.u); proof_add("\\right) \\cdot "); }
    proof_add("D_{%c + 1} = ", variable);
    if (!plain && !poly_is_one(step.v)) { proof_add("\\left("); put_terms(step.v); proof_add("\\right) \\cdot "); }
    if (!plain) proof_add("D_{%c}", variable);
    if (step.p.count > 0 || plain) {
        proof_add(plain ? "\\left(" : " + \\left(");
        put_terms(step.p);
        proof_add(step.t.count ? "\\right) \\cdot " : "\\right)");
        put_mono(&step.t);
    }
    proof_add("$.\n");
    if (step.t.count > 0 && step.p.count > 0) {
        proof_add("\\item The factor $");
        put_mono(&step.t);
        proof_add("$ is positive: it is made of powers of positive numbers and of products of positive factors.\n");
    }

    /* La conclusione, che poggia sulla tabella dei segni scritta dopo. */
    proof_add("\\item The sign table below shows that $%s$ for every real number $%c \\ge %lld$. ", claim, variable, *start);
    if (!poly_is_one(step.u)) proof_add("There a comparison holds only where its sides have a value, so the factor of $D_{%c + 1}$ is not zero. ", variable);
    if (plain) proof_add("Hence $D_{%c + 1} %s 0$.\n", variable, sign);
    else proof_add("Since $D_{%c} %s 0$ by the inductive hypothesis, the identity gives $D_{%c + 1} %s 0$.\n", variable, sign, variable, sign);
    proof_add("\\end{itemize}\n\\item \\emph{The inequality of the inductive step}, for every real number $%c \\ge %lld$. ", variable, *start);
    if (!sound || proof_length >= PROOF_BYTES - 1) {
        if (!sound) unjustified_steps++;
        verdict.reason = "una formula della dimostrazione, riletta dal testo, non è confermata";
        return verdict;
    }
    verdict.outcome = PROVED;
    return verdict;
}

/* Chiede al metodo method l'enunciato question, scritto in LaTeX come lo
 * scriverebbe un utente, e ne ritorna il verdetto. È così che un capitolo ne
 * usa un altro che riparte da zero: i capitoli 25 e 26 la tabella dei segni
 * (ask_sign_table()), il capitolo 30 la tabella e i limiti del capitolo 29.
 *
 * Il metodo svuota l'arena, la tabella degli atomi e il testo della
 * dimostrazione. Chi chiama deve quindi aver finito con alberi e polinomi;
 * il testo già scritto invece viene messo da parte qui e, se il metodo
 * dimostra o risolve l'enunciato, ricomposto: prima quel testo, poi la
 * dimostrazione del metodo senza il quadratino con cui la chiude. Se insieme
 * non stanno nel testo, del metodo resta solo la frase short. Se il metodo
 * non dimostra e non risolve, il testo è quello che il metodo ha lasciato,
 * oppure, con keep, quello di prima. Il grafico non viene costruito:
 * sarebbe quello di un passo, non dell'enunciato. */
static Verdict ask_method(Verdict (*method)(const char *), const char *question, const char *short_text, int keep) {
    static char written[PROOF_BYTES];
    static const char box[] = " $\\Box$";
    size_t length = proof_length, closing = sizeof box - 1;
    int wanted = figures_wanted;
    memcpy(written, proof_text, length + 1);
    figures_wanted = 0;
    Verdict answer = method(question);
    figures_wanted = wanted;
    if (answer.outcome != PROVED && answer.outcome != SOLVED) {
        if (keep) {
            memcpy(proof_text, written, length + 1);
            proof_length = length;
        }
        return answer;
    }

    size_t tail = proof_length;
    if (tail >= closing && strcmp(proof_text + tail - closing, box) == 0) proof_cut(tail -= closing);
    if (length + tail + 64 >= PROOF_BYTES) {
        proof_reset();
        proof_add("%s%s", written, short_text);
    } else {
        memmove(proof_text + length, proof_text, tail + 1);
        memcpy(proof_text, written, length);
        proof_length = length + tail;
    }
    return answer;
}

/* Chiede alla tabella dei segni (18p) l'enunciato question, "per ogni x
 * reale ...", con ask_method(). */
static Verdict ask_sign_table(const char *question) {
    return ask_method(prove_quantified, question, "The sign table, too long to be written here, shows that the condition holds on every row.", 0);
}

/* Prova a dimostrare per induzione la disuguaglianza scritta in formula, con
 * il metodo descritto in testa al capitolo. variable, has_base e base come
 * per prove_by_induction().
 *
 * Il verdetto DIMOSTRATO è senza certificato, e lo dice in reason. Svuota
 * l'arena e la tabella degli atomi: i risultati di chiamate precedenti non
 * sono più validi. */
static Verdict prove_inequality(const char *formula, int variable, int has_base, long long base) {
    static char reason[400];
    Verdict verdict = {UNSUPPORTED, variable, base, 0, NULL, NULL, NULL, NULL, NULL, NULL}, refusal = verdict;
    long long start = 0;
    int asked = 0;

    /* Un tentativo per ogni n da cui far partire il passo: il primo lo
     * propone inequality_plan(); se la tabella smentisce il passo, che per
     * lei riguarda ogni numero reale, si riprova da un n più avanti, finché
     * ci sono casi già calcolati da mettere prima. Così 3^n >= 2 n^2 + 1 da
     * n = 0, il cui passo non vale tra 0 e 1, si dimostra con il passo da
     * n = 1. */
    for (long long floor = LLONG_MIN;; floor = start + 1) {
        Statement statement;
        char question[MAX_FORMULA];

        /* Ripartenza da zero per il nuovo enunciato, e parsing. */
        proof_reset();
        arena_used = arena_keep;
        atom_count = 0;
        base_poly_count = 0;
        atan_count = 0;
        failure = NULL;
        if (!parse_statement(formula, &statement)) { verdict.reason = syntax_error; return verdict; }

        /* 27j. I segni di derivata dentro le espressioni, prima di ogni conto. */
        derivative_signs = 0;
        statement.lhs = derivatives_expanded(statement.lhs);
        statement.rhs = derivatives_expanded(statement.rhs);
        if (failure) { verdict.reason = failure; return verdict; }
        verdict = inequality_plan(&statement, variable, has_base, base, floor, &start, question, sizeof question);
        surd_powers = 0;
        if (verdict.outcome != PROVED) return asked ? refusal : verdict;

        /* La tabella dei segni decide il passo. */
        Verdict table = ask_sign_table(question);
        asked = 1;
        if (table.outcome == PROVED) {
            proof_add("\n\\end{itemize}\n$\\Box$");
            verdict.reason = "il passo induttivo è deciso dalla tabella dei segni, e le disuguaglianze non hanno ancora una notazione nei certificati";
            verdict.proof = proof_text;
            return verdict;
        }

        /* Smentito in un numero reale: per gli interi non si conclude nulla,
         * e si riprova più avanti. Non deciso: ci si ferma. */
        if (table.outcome == REFUTED)
            snprintf(reason, sizeof reason, "il passo induttivo non vale per ogni %c reale da %lld in su: la tabella dei segni lo smentisce%s%s",
                     variable, start, table.detail ? " in " : "", table.detail ? table.detail : "");
        else
            snprintf(reason, sizeof reason, "la tabella dei segni non decide il passo induttivo, da %c = %lld in su: %s", variable, start, table.reason);
        refusal.outcome = table.outcome == UNSUPPORTED ? UNSUPPORTED : NOT_PROVED;
        refusal.base = verdict.base;
        refusal.reason = reason;
        if (table.outcome != REFUTED) return refusal;
    }
}

/* =============================================================================
 * 26. SUCCESSIONI DEFINITE PER RICORRENZA
 * ============================================================================
 *
 * A che cosa serve. "Sia a_0 = 0, a_1 = sin x e a_{n+1} = 2 cos x a_n -
 * a_{n-1}. Allora a_n = sin(n x)." La successione non è nel vocabolario
 * (capitolo 10): la definisce l'enunciato, con i primi valori e una regola
 * che dà ogni termine dai precedenti. L'enunciato arriva nella notazione di
 * parse_sequence_statement(): ipotesi, \implies, tesi. Le tesi trattate sono
 * di due tipi, ognuno con il suo teorema. Ci arrivano anche le iterate f^{n}
 * di un'applicazione di un enunciato con quantificatori (17s): fissato x, i
 * numeri f^{n}(x) sono una successione definita per ricorrenza (26c).
 *
 * LA SUCCESSIONE DICHIARATA
 *
 * Le ipotesi devono essere: d valori iniziali s_{i0}, ..., s_{i0+d-1}, e una
 * regola s_{n+r} = Phi, dove in Phi compaiono solo termini s_{n+j} con
 * r - d <= j < r (e n, e i parametri). d è l'ordine. La regola vale per ogni
 * n >= m0 = i0 - (r - d): il primo termine che definisce è s_{i0+d}, quello
 * dopo i valori iniziali. Se l'enunciato dice da quale n vale, deve dire
 * proprio m0. Ogni altra forma (valori iniziali mancanti o di troppo, un
 * termine come s_{2n}) è NON SUPPORTATO: non si indovina che cosa
 * l'enunciato intendesse.
 *
 * 26a. LA FORMULA CHIUSA: "allora s_n = C(n)"
 *
 * Teorema (una ricorrenza determina la successione). Se una successione c
 * ha gli stessi d valori iniziali di s e soddisfa la stessa regola per ogni
 * n >= m0, allora c_n = s_n per ogni n >= i0. Dimostrazione, per induzione
 * su N: i termini fino a i0+d-1 sono uguali per ipotesi; se sono uguali
 * tutti i termini prima di N = n + r, allora s_N = Phi(s_{N-1}, ...) =
 * Phi(c_{N-1}, ...) = c_N, perché Phi è la stessa espressione calcolata
 * negli stessi numeri.
 *
 * Con c_n = C(n) restano quindi da dimostrare due cose, nessuna delle quali
 * contiene più la successione:
 *
 *   - C(i0 + j) è il valore iniziale numero j, per j < d: un'uguaglianza tra
 *     espressioni senza n, che il test di annullamento decide;
 *   - C(n + r) = Phi con C(n + j) al posto di s_{n+j}, per ogni n >= m0:
 *     un'identità in n, dimostrata dall'induzione del capitolo 13 con tutti
 *     i suoi controlli (13c: definita per ogni n; 13e: i numeri).
 *
 * Il verdetto ha la riserva di ogni induzione del capitolo 13: vale per i
 * valori dei parametri in cui la formula chiusa è definita per ogni n.
 *
 * Verifica indipendente, e smentita. I termini s_{i0+d}, s_{i0+d+1}, ...
 * vengono calcolati uno dopo l'altro dalla regola, a partire dai valori
 * iniziali, e confrontati con C: un conto che non passa né dall'identità in
 * n né dall'induzione. Due numeri diversi sono un controesempio, e il
 * verdetto è FALSO con quell'n: così cade una formula sbagliata che
 * coincide con quella giusta nei primi valori.
 *
 * 26b. UNA STIMA: "allora s_n < 3 e s_n < s_{n+1}"
 *
 * Qui la regola deve essere s_{n+1} = Phi(s_n), senza n e senza parametri,
 * e le tesi confronti in cui compaiono solo s_n e s_{n+1}.
 *
 * Teorema (invariante). Sia I(a) una condizione sul numero reale a tale che
 *
 *   - I(s_{i0}) è vera;
 *   - per ogni reale a, se I(a) allora Phi(a) è definita, I(Phi(a)) è vera,
 *     e sono vere le tesi con a al posto di s_n e Phi(a) al posto di
 *     s_{n+1}.
 *
 * Allora per ogni n >= i0 il termine s_n esiste, I(s_n) è vera e le tesi
 * valgono. Dimostrazione: per induzione su n, I(s_n) è vera; quindi
 * s_{n+1} = Phi(s_n) è definita e soddisfa I, e le tesi in n sono il
 * secondo punto con a = s_n.
 *
 * L'invariante. Si prova prima con le tesi che parlano del solo s_n: se
 * s_n < 3 è una tesi, deve comunque essere dimostrata. Di solito non basta:
 * da a < 3 non segue che la radice di 6 + a esista. Allora si aggiunge ciò
 * che è vero del primo termine e che molte successioni conservano:
 * a >= s_{i0} (una successione crescente), poi a <= s_{i0}, poi "a ha il
 * segno di s_{i0}". Sono tentativi, ma l'invariante trovato non va creduto:
 * il secondo punto del teorema, che è un enunciato "per ogni a reale" in
 * una variabile, lo decide la tabella dei segni (18p), e il primo un conto
 * esatto.
 *
 * Verifica indipendente, e smentita. I primi termini vengono calcolati con
 * gli intervalli del capitolo 24, sostituendo la regola in se stessa, e le
 * tesi confrontate lì: un confronto certamente falso è un controesempio.
 *
 * Nessuno dei due teoremi ha una notazione nei certificati: il verdetto
 * DIMOSTRATO lo dice.
 *
 * Che cosa resta fuori: le tesi che non sono né una formula chiusa né una
 * stima (ln a_n = 2^n ln a_0, "è un intero pari"), le ricorrenze senza un
 * valore iniziale, e le formule chiuse la cui identità il capitolo 13 non
 * sa dimostrare, come quelle con una radice di cui serve il segno.
 */

/* Il motivo per cui un termine di una successione non si lascia sostituire:
 * il suo indice non è tra quelli attesi. Ha un nome perché chi prova una
 * sostituzione per vedere se riesce lo riconosce. */
static const char *const FOREIGN_TERM = "un termine della successione ha un indice che la ricorrenza non tratta";

/* Ritorna una copia di tree in cui la variabile name, dove è libera, è
 * sostituita dall'albero value, che non viene copiato. L'indice di una somma
 * nasconde, nel corpo, una variabile con lo stesso nome.
 *
 * Warning: value non deve contenere lettere che in tree sono indici di
 * somme, o verrebbero catturate. Qui value è un numero, n + j, oppure
 * un'espressione nella lettera di una successione. */
static Node *node_replace(const Node *tree, int name, Node *value) {
    if (!tree) return NULL;
    if (tree->kind == N_VAR && tree->name == name) return value;
    Node *copy = node_new(tree->kind, node_replace(tree->a, name, value), node_replace(tree->b, name, value));
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    copy->c = tree->kind == N_BIGOP && tree->name == name ? tree->c : node_replace(tree->c, name, value);
    return copy;
}

/* Ritorna una copia di tree in cui ogni termine s_{n + j} della successione
 * di nome name è sostituito da term[j - low], per j da low a low + count - 1;
 * n è la variabile di induzione. Se un termine ha un altro indice (s_0,
 * s_{2n}, s_{n + j} con j fuori dall'intervallo) fallisce con FOREIGN_TERM.
 * Gli alberi di term[] non vengono copiati. */
static Node *unfold_terms(const Node *tree, int name, long long low, int count, Node *const *term) {
    if (!tree || failure) return NULL;
    if (tree->kind == N_SEQ && tree->name == name) {
        long long a, c;
        if (!rat_affine(eval(tree->a), &a, &c) || a != 1 || c < low || c >= low + count) { fail(FOREIGN_TERM); return NULL; }
        return term[c - low];
    }
    Node *copy = node_new(tree->kind, unfold_terms(tree->a, name, low, count, term), unfold_terms(tree->b, name, low, count, term));
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    copy->c = unfold_terms(tree->c, name, low, count, term);
    return copy;
}

/* Una successione dichiarata da un enunciato (vedi "La successione
 * dichiarata" in testa al capitolo): i valori iniziali e la regola, già
 * controllati. Gli alberi sono quelli dell'enunciato, nell'arena.
 * Invariante: 1 <= order <= MAX_ORDER, e in step compaiono solo termini
 * s_{n + j} con shift - order <= j < shift. */
typedef struct {
    int name;                    /* la lettera s */
    int order;                   /* d: quanti termini precedenti usa la regola */
    long long first;             /* i0: l'indice del primo valore iniziale */
    long long shift;             /* r: la regola dà s_{n + r} */
    long long since;             /* m0 = i0 - (r - d): il primo n in cui la regola vale */
    Node *initial[MAX_ORDER];    /* i valori di s_{i0}, ..., s_{i0 + d - 1} */
    Node *step;                  /* Phi: il valore di s_{n + r} */
} Declared;

/* Aggiorna *low e *high con il più piccolo e il più grande j dei termini
 * s_{n + j} della successione name che compaiono in tree; *found dice se ce
 * ne sono. Ritorna 0 se un termine ha un indice di un'altra forma. */
static int term_span(const Node *tree, int name, long long *low, long long *high, int *found) {
    if (!tree) return 1;
    if (tree->kind == N_SEQ && tree->name == name) {
        long long a, c;
        if (!rat_affine(eval(tree->a), &a, &c) || a != 1 || failure) return 0;
        if (!*found || c < *low) *low = c;
        if (!*found || c > *high) *high = c;
        *found = 1;
        return 1;
    }
    return term_span(tree->a, name, low, high, found) && term_span(tree->b, name, low, high, found) && term_span(tree->c, name, low, high, found);
}

/* Legge le ipotesi di statement come dichiarazione di una successione, con
 * `variable` variabile di induzione, e riempie *seq. Ritorna NULL se hanno
 * la forma richiesta (vedi la testa del capitolo), altrimenti il motivo, in
 * italiano. */
static const char *declared_read(const SequenceStatement *statement, int variable, Declared *seq) {
    long long index[MAX_GIVEN], low = 0, high = 0;
    Node *value[MAX_GIVEN];
    int values = 0, found = 0;
    memset(seq, 0, sizeof *seq);

    /* Ogni ipotesi: un valore iniziale s_{numero} = ..., o la regola
     * s_{n + r} = ..., una sola. */
    for (int i = 0; i < statement->givens; i++) {
        const Statement *given = &statement->given[i];
        long long a, c;
        if (given->lhs->kind != N_SEQ || (i > 0 && given->lhs->name != seq->name)) return "ogni ipotesi deve dare un termine della stessa successione, come a_{0} = 1 oppure a_{n + 1} = 2 a_{n}";
        seq->name = given->lhs->name;
        if (!rat_affine(eval(given->lhs->a), &a, &c) || failure || a < 0 || a > 1 || (a == 1 && seq->step)) return "le ipotesi devono essere i valori iniziali e una sola regola per il termine di indice n + r";
        if (a == 1) { seq->shift = c; seq->step = given->rhs; continue; }
        index[values] = c;
        value[values++] = given->rhs;
    }
    if (!seq->step) return "tra le ipotesi manca la regola che dà un termine dai precedenti";

    /* I termini che la regola usa: tutti prima di quello che definisce. */
    if (!term_span(seq->step, seq->name, &low, &high, &found) || !found || high >= seq->shift || seq->shift - low > MAX_ORDER)
        return "la regola deve dare il termine di indice n + r da quelli che lo precedono, al più quattro";
    seq->order = (int)(seq->shift - low);

    /* I valori iniziali: tanti quanti l'ordine, di indici consecutivi, e
     * senza termini della successione dentro. */
    if (values != seq->order) return "i valori iniziali devono essere tanti quanti i termini precedenti che la regola usa";
    seq->first = index[0];
    for (int i = 1; i < values; i++)
        if (index[i] < seq->first) seq->first = index[i];
    for (int i = 0; i < values; i++) {
        long long place = index[i] - seq->first;
        if (place >= values || seq->initial[place] || node_uses_letter(value[i], seq->name) || node_uses_letter(value[i], variable))
            return "i valori iniziali devono avere indici consecutivi, e non contenere né la lettera della successione né la variabile di induzione";
        seq->initial[place] = value[i];
    }

    /* Da dove vale la regola: se l'enunciato lo dice, deve dire questo. */
    seq->since = seq->first - (seq->shift - seq->order);
    if (statement->has_since && (statement->since_name != variable || statement->since != seq->since))
        return "la regola è data da un n diverso da quello che serve perché definisca tutti i termini dopo i valori iniziali";
    return NULL;
}

/* Ritorna 1 se in tree compare la variabile name, non come indice di una
 * somma né come nome di una successione. */
static int node_has_variable(const Node *tree, int name) {
    if (!tree) return 0;
    if (tree->kind == N_VAR && tree->name == name) return 1;
    return node_has_variable(tree->a, name) || node_has_variable(tree->b, name) || node_has_variable(tree->c, name);
}

/* Ritorna 1 se un confronto con la relazione rel è vero quando la differenza
 * tra il primo e il secondo membro ha il segno side (-1, 0 o 1). */
static int relation_holds(Relation rel, int side) {
    switch (rel) {
    case REL_EQ: return side == 0;
    case REL_GE: return side >= 0;
    case REL_LE: return side <= 0;
    case REL_GT: return side > 0;
    default:     return side < 0;
    }
}

/* Scrive nella dimostrazione il confronto lhs rel rhs, in LaTeX, e ritorna
 * il pezzo scritto. */
static Span put_comparison(const Node *lhs, Relation rel, const Node *rhs) {
    static const char *const sign[] = {[REL_EQ] = "=", [REL_GE] = "\\ge", [REL_LE] = "\\le", [REL_GT] = ">", [REL_LT] = "<"};
    Span span = {proof_length, 0};
    put_node(lhs, 0);
    proof_add(" %s ", sign[rel]);
    put_node(rhs, 0);
    span.to = proof_length;
    return span;
}

/* 26a. Dimostra la tesi "s_n = closed" per la successione seq, con il
 * teorema della formula chiusa (vedi la testa del capitolo): i valori
 * iniziali, i primi termini calcolati dalla regola, e la regola stessa per
 * induzione. Ritorna il verdetto, con la dimostrazione scritta; base è il
 * caso base da riportare.
 *
 * Azzera la tabella degli atomi prima dell'induzione, che la vuole per sé:
 * dopo questa chiamata i polinomi calcolati prima non valgono più. */
static Verdict prove_closed_form(const Declared *seq, Node *closed, int variable, long long base) {
    static char text[320];
    Verdict verdict = {NOT_PROVED, variable, base, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    long long low = seq->shift - seq->order;
    int sound = 1;
    const char *plural = seq->order > 1 ? "s" : "";

    proof_add("\\textbf{Proof.} A sequence is determined by its first value%s and by the rule that gives each term from the previous "
              "ones: two sequences with the same first value%s and the same rule are equal, by induction on the index. So it is "
              "enough to show that the formula $", plural, plural);
    put_node(closed, 0);
    proof_add("$ has the first value%s of $%c$ and satisfies its rule.\n\\begin{itemize}\n", plural, seq->name);

    /* I valori iniziali: un'uguaglianza senza n per ciascuno. */
    Rat window[MAX_ORDER];
    for (int j = 0; j < seq->order; j++) {
        long long at = seq->first + j;
        Num number;
        window[j] = side_value(seq->initial[j], rat_int(at));
        Rat gap = rat_add(side_value(closed, rat_int(at)), window[j], 1);
        if (failure) { verdict.outcome = UNSUPPORTED; verdict.reason = failure; return verdict; }
        if (!poly_vanishes(gap.num)) {
            /* Due numeri diversi smentiscono la tesi solo se è affermata
             * anche per questo indice. */
            if (rat_number(gap, &number) && at >= base) { verdict.outcome = REFUTED; verdict.witness = at; return verdict; }
            snprintf(text, sizeof text, "per %c = %lld la formula non si riduce al valore iniziale", variable, at);
            verdict.reason = text;
            return verdict;
        }
        proof_add("\\item \\emph{First value}, $%c = %lld$. The formula gives $", variable, at);
        Span formula = put_side(closed, node_num(at));
        proof_add("$, and $%c_{%lld} = ", seq->name, at);
        Span value = {proof_length, 0};
        put_node(seq->initial[j], 0);
        value.to = proof_length;
        proof_add("$: the two are equal.\n");
        sound &= reread_equal(formula, value, at);
    }

    /* Verifica indipendente, e smentita: i termini successivi, calcolati
     * uno dopo l'altro dalla regola con i termini precedenti legati a
     * variabili interne, e confrontati con la formula. Un conto che esce
     * dai limiti del programma ferma il confronto senza obiezioni. */
    Node *previous[MAX_ORDER];
    for (int j = 0; j < seq->order; j++) {
        previous[j] = node_new(N_VAR, NULL, NULL);
        previous[j]->name = VAR_TERM + j;
    }
    Node *rule = unfold_terms(seq->step, seq->name, low, seq->order, previous);
    long long last = seq->first + seq->order - 1;
    for (long long at = last + 1; at <= seq->first + seq->order + SEARCH_SPAN / 2 && !failure; at++) {
        Num number;
        undefined = 0;
        env_count = 0;
        env_push(variable, rat_int(at - seq->shift));
        for (int j = 0; j < seq->order; j++) env_push(VAR_TERM + j, window[j]);
        Rat term = eval(rule);
        env_count = 0;
        Rat gap = rat_add(term, side_value(closed, rat_int(at)), 1);
        if (failure && undefined) {
            snprintf(text, sizeof text, "per %c = %lld la regola o la formula non sono definite: %s", variable, at, failure);
            failure = NULL;
            verdict.reason = text;
            return verdict;
        }
        if (failure) break;
        if (!poly_vanishes(gap.num)) {
            if (rat_number(gap, &number) && at >= base) { verdict.outcome = REFUTED; verdict.witness = at; return verdict; }
            snprintf(text, sizeof text, "il termine di indice %lld, calcolato dalla regola, non si riduce alla formula", at);
            verdict.reason = text;
            return verdict;
        }
        for (int j = 0; j + 1 < seq->order; j++) window[j] = window[j + 1];
        window[seq->order - 1] = term;
        last = at;
    }
    failure = NULL;
    if (last < seq->first + seq->order) { verdict.reason = "non riesco a calcolare dalla regola nemmeno il primo termine dopo i valori iniziali"; return verdict; }
    proof_add("\\item \\emph{Check on the next terms}. The terms from $%c_{%lld}$ to $%c_{%lld}$, computed one after the other from the "
              "rule, coincide with the formula.\n", seq->name, seq->first + seq->order, seq->name, last);

    /* La regola, con la formula al posto dei termini: un'identità in n. */
    Node *term[MAX_ORDER];
    for (int j = 0; j < seq->order; j++) term[j] = node_replace(closed, variable, node_affine(1, variable, low + j));
    Statement identity = {node_replace(closed, variable, node_affine(1, variable, seq->shift)),
                          unfold_terms(seq->step, seq->name, low, seq->order, term), REL_EQ};
    if (failure) { verdict.outcome = UNSUPPORTED; verdict.reason = failure; return verdict; }
    proof_add("\\item \\emph{The rule}. With the formula in place of the terms of $%c$, the rule becomes $", seq->name);
    put_comparison(identity.lhs, REL_EQ, identity.rhs);
    proof_add("$, to be proved for every $%c \\ge %lld$.\n", variable, seq->since);
    atom_count = base_poly_count = atan_count = 0;
    Verdict inner = induct(&identity, variable, 1, seq->since, 1);
    if (inner.outcome != PROVED) {
        if (inner.outcome == REFUTED) snprintf(text, sizeof text, "la formula non soddisfa la regola: per %c = %lld i due membri sono diversi", variable, inner.witness);
        else snprintf(text, sizeof text, "non riesco a dimostrare che la formula soddisfa la regola: %s", inner.reason);
        verdict.reason = text;
        return verdict;
    }
    proof_add("\\end{itemize}\n$\\Box$");
    if (!sound) {
        unjustified_steps++;
        verdict.reason = "una formula della dimostrazione, riletta dal testo, non è confermata";
        return verdict;
    }
    verdict.outcome = PROVED;
    verdict.reason = "il teorema che una ricorrenza determina la successione non è nella notazione dei certificati";
    verdict.proof = proof_text;
    return verdict;
}

/* Quanti termini di una successione la regola 26b calcola con gli intervalli
 * per confrontarli con le tesi. Sono pochi perché l'albero di un termine
 * contiene quello del precedente tante volte quante la regola lo nomina. */
#define BOUND_TERMS 6

/* Quanti invarianti prova la regola 26b, uno per tentativo (vedi
 * bound_plan()). */
#define INVARIANTS 4

/* 26b. Prepara la dimostrazione delle tesi di statement, stime sui termini
 * della successione seq, con il teorema dell'invariante (vedi la testa del
 * capitolo). attempt, da 0 a INVARIANTS - 1, dice che cosa aggiungere alle
 * tesi per avere l'invariante: 0 niente, 1 "a >= primo termine", 2 "a <=
 * primo termine", 3 "a ha il segno del primo termine".
 *
 * Fa tutto tranne interrogare la tabella dei segni: il caso base, i primi
 * termini calcolati con gli intervalli, la dimostrazione scritta. Se riesce
 * il verdetto è PROVED e in question, lunga al più size, c'è l'enunciato
 * "per ogni a reale" che la tabella deve ancora dimostrare; ogni altro
 * verdetto è già quello definitivo. */
static Verdict bound_plan(const SequenceStatement *statement, const Declared *seq, int variable, long long base, int attempt,
                          char *question, size_t size) {
    static char text[320];
    Verdict verdict = {UNSUPPORTED, variable, base, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    const char *shape = "una stima sui termini si dimostra solo per una regola a_{n + 1} = f(a_n) in cui n non compare";
    int letter = seq->name;
    if (seq->order != 1 || seq->shift != 1) { verdict.reason = shape; return verdict; }

    /* Le espressioni nella lettera a: a stessa per s_n, Phi(a) per s_{n+1},
     * e il primo termine. In Phi(a) la variabile n non deve restare. */
    Node *now = node_new(N_VAR, NULL, NULL), *start = seq->initial[0];
    now->name = letter;
    Node *pair[2] = {now, unfold_terms(seq->step, letter, 0, 1, &now)}, *later[2] = {pair[1], NULL};
    if (failure || node_uses_letter(pair[1], variable)) { verdict.reason = failure ? failure : shape; return verdict; }

    /* La lettera della successione fa da variabile reale: se nell'enunciato
     * fosse anche un parametro, come in a_{n+1} = a a_n, dopo la
     * sostituzione i due non si distinguerebbero più. */
    int clash = node_has_variable(seq->step, letter);
    for (int i = 0; i < statement->claims; i++) clash |= node_has_variable(statement->claim[i].lhs, letter) || node_has_variable(statement->claim[i].rhs, letter);
    if (clash) { verdict.reason = "la lettera della successione compare anche come parametro"; return verdict; }

    /* Ogni tesi, in tre scritture: con a (solo se parla del solo s_n, e
     * allora entra nell'invariante), con Phi(a) al posto di a (l'invariante
     * dopo un passo), con a e Phi(a) (la tesi che nomina anche s_{n+1}). */
    Statement kept[MAX_CLAIMS + 1], next[MAX_CLAIMS + 1];
    int keeps = 0, nexts = 0, bound = 0;
    for (int i = 0; i < statement->claims && !failure; i++) {
        const Statement *claim = &statement->claim[i];
        Statement alone = {unfold_terms(claim->lhs, letter, 0, 1, pair), unfold_terms(claim->rhs, letter, 0, 1, pair), claim->relation};
        if (failure == FOREIGN_TERM) {
            failure = NULL;
            next[nexts++] = (Statement){unfold_terms(claim->lhs, letter, 0, 2, pair), unfold_terms(claim->rhs, letter, 0, 2, pair), claim->relation};
        } else {
            kept[keeps++] = alone;
            next[nexts++] = (Statement){unfold_terms(claim->lhs, letter, 0, 1, later), unfold_terms(claim->rhs, letter, 0, 1, later), claim->relation};
        }

        /* Tolti i termini, n non deve più comparire: una tesi come
         * s_n < n non è una condizione sul solo numero s_n. */
        bound |= !failure && (node_uses_letter(next[nexts - 1].lhs, variable) || node_uses_letter(next[nexts - 1].rhs, variable));
    }
    if (failure || bound) {
        verdict.reason = failure ? failure : "una stima sui termini si dimostra solo se n compare soltanto negli indici dei termini";
        return verdict;
    }
    if (attempt) {
        /* Ciò che si aggiunge: un confronto con il primo termine, o con
         * zero dalla parte in cui sta il primo termine. */
        int sign = 0;
        Node *bound = attempt < 3 ? start : node_num(0);
        Relation side = attempt == 1 ? REL_GE : attempt == 2 ? REL_LE : REL_GT;
        if (attempt == 3 && (!constant_side(side_value(start, rat_int(seq->first)), &sign) || sign == 0)) {
            verdict.outcome = NOT_PROVED;
            verdict.reason = "non trovo un invariante";
            return verdict;
        }
        if (sign < 0) side = REL_LT;
        kept[keeps++] = (Statement){now, bound, side};
        next[nexts++] = (Statement){pair[1], bound, side};
    }

    /* Il caso base, esatto: il primo termine soddisfa l'invariante. */
    verdict.outcome = NOT_PROVED;
    for (int i = 0; i < keeps; i++) {
        int side = 0;
        Rat gap = rat_add(side_value(node_replace(kept[i].lhs, letter, start), rat_int(seq->first)),
                          side_value(node_replace(kept[i].rhs, letter, start), rat_int(seq->first)), 1);
        if (failure || !constant_side(gap, &side)) {
            verdict.reason = failure ? failure : "non riesco a stabilire se il primo termine soddisfa le tesi";
            failure = NULL;
            return verdict;
        }
        if (!relation_holds(kept[i].relation, side)) {
            /* Un controesempio, se la tesi è affermata anche per il primo
             * termine; altrimenti l'invariante non parte, e basta. */
            if (seq->first >= base) { verdict.outcome = REFUTED; verdict.witness = seq->first; }
            else verdict.reason = "il primo termine non soddisfa le tesi, che sono affermate solo da un indice successivo";
            return verdict;
        }
    }

    /* Verifica indipendente, e smentita: i primi termini con gli intervalli
     * (capitolo 24), ognuno come albero in cui la regola è sostituita in se
     * stessa. Conta solo un confronto certamente falso. */
    Node *term = start;
    for (long long at = seq->first; at < seq->first + BOUND_TERMS; at++) {
        Node *both[2] = {term, unfold_terms(seq->step, letter, 0, 1, &term)};
        for (int i = 0; i < statement->claims; i++) {
            const Statement *claim = &statement->claim[i];
            int nowhere = 0, side = 0;
            Range gap = range_sub(node_range(unfold_terms(claim->lhs, letter, 0, 2, both), 0, range_none(), &nowhere),
                                  node_range(unfold_terms(claim->rhs, letter, 0, 2, both), 0, range_none(), &nowhere));
            if (failure || nowhere) {
                snprintf(text, sizeof text, "per %c = %lld un termine o una tesi non sono definiti", variable, at);
                failure = NULL;
                verdict.reason = text;
                return verdict;
            }
            if (at >= base && range_side(gap, &side) && !relation_holds(claim->relation, side)) {
                verdict.outcome = REFUTED;
                verdict.witness = at;
                return verdict;
            }
        }
        term = both[1];
    }

    /* I testi per la tabella: l'invariante, e ciò che ne deve seguire. */
    char hypothesis[MAX_FORMULA] = "", thesis[MAX_FORMULA] = "";
    size_t opening = proof_length;
    int fits = 1;
    for (int i = 0; i < keeps + nexts; i++) {
        const Statement *part = i < keeps ? &kept[i] : &next[i - keeps];
        char *into = i < keeps ? hypothesis : thesis;
        size_t used = strlen(into);
        Span span = put_comparison(part->lhs, part->relation, part->rhs);
        int written = snprintf(into + used, MAX_FORMULA - used, "%s%.*s", used ? " \\land " : "", (int)(span.to - span.from), proof_text + span.from);
        fits &= written > 0 && (size_t)written < MAX_FORMULA - used;
    }
    proof_cut(opening);
    int length = keeps ? snprintf(question, size, "\\forall %c \\in \\mathbb{R}\\ ((%s) \\implies (%s))", letter, hypothesis, thesis)
                       : snprintf(question, size, "\\forall %c \\in \\mathbb{R}\\ (%s)", letter, thesis);
    if (!fits || length <= 0 || (size_t)length >= size) { verdict.reason = "il passo induttivo è troppo lungo da scrivere"; return verdict; }

    /* La dimostrazione scritta, a cui manca solo la tabella. */
    proof_add("\\textbf{Proof.} By induction on $%c$, with an invariant: a condition $I(%c)$ on a real number $%c$ that the first term "
              "satisfies and that the rule preserves. ", variable, letter, letter);
    if (keeps) proof_add("Here $I(%c)$ is $%s$.\n\\begin{itemize}\n\\item \\emph{Base case}, $%c = %lld$. The first term is $%c_{%lld} = ",
                         letter, hypothesis, variable, seq->first, letter, seq->first);
    else proof_add("Here no condition is needed: $I(%c)$ is always true.\n\\begin{itemize}\n\\item \\emph{Base case}, $%c = %lld$. The first term is $%c_{%lld} = ",
                   letter, variable, seq->first, letter, seq->first);
    put_node(start, 0);
    proof_add(keeps ? "$, and it satisfies $I$: the comparisons are between numbers.\n" : "$.\n");
    proof_add("\\item \\emph{Inductive step}. Assume that $%c_{%c}$ exists and satisfies $I$ for some $%c \\ge %lld$, and write $%c$ for it: "
              "the next term is $%c_{%c + 1} = ", letter, variable, variable, seq->first, letter, letter, variable);
    put_node(pair[1], 0);
    proof_add("$. The sign table below shows that for every real number $%c$ %s $%s$. A comparison holds only where its sides have a "
              "value: so $%c_{%c + 1}$ exists, it satisfies $I$, and the claims hold for this $%c$.\n",
              letter, keeps ? "that satisfies $I$:" : ":", thesis, letter, variable, variable);
    proof_add("\\item \\emph{Check on the first terms}. The terms from $%c_{%lld}$ to $%c_{%lld}$, computed with guaranteed error bounds, "
              "do not contradict the claims.\n\\item \\emph{The condition of the inductive step}, for every real number $%c$. ",
              letter, seq->first, letter, seq->first + BOUND_TERMS - 1, letter);
    verdict.outcome = PROVED;
    return verdict;
}

/* Prova a dimostrare l'enunciato su una successione definita per ricorrenza
 * scritto in formula, nella notazione di parse_sequence_statement(), con i
 * teoremi 26a e 26b. variable, has_base e base come per
 * prove_by_induction(): la tesi è affermata per ogni n dal caso base in su,
 * che in sua assenza è l'indice del primo valore iniziale.
 *
 * Il verdetto DIMOSTRATO è senza certificato, e dice perché in reason.
 * Svuota l'arena e la tabella degli atomi: i risultati di chiamate
 * precedenti non sono più validi. */
static Verdict prove_sequence(const char *formula, int variable, int has_base, long long base) {
    static char reason[400];
    Verdict verdict = {UNSUPPORTED, variable, base, 0, NULL, NULL, NULL, NULL, NULL, NULL}, refusal = verdict;

    /* Per una stima, un tentativo per ogni invariante (26b): la tabella dei
     * segni riparte da zero, quindi ogni volta si rilegge l'enunciato. Per
     * una formula chiusa (26a) basta il primo giro. */
    for (int attempt = 0;; attempt++) {
        SequenceStatement statement;
        Declared seq;
        char question[MAX_FORMULA];

        /* Ripartenza da zero per il nuovo enunciato, e parsing. */
        proof_reset();
        arena_used = arena_keep;
        atom_count = base_poly_count = atan_count = 0;
        failure = NULL;
        induction_var = variable;
        default_base = domain_floor = 1;
        if (!parse_sequence_statement(formula, &statement)) { verdict.reason = syntax_error; return verdict; }
        const char *problem = failure ? failure : declared_read(&statement, variable, &seq);
        if (!problem && has_base && base < seq.first) problem = "la tesi parte da un indice che viene prima dei valori iniziali";
        if (problem) { verdict.reason = problem; return verdict; }
        if (!has_base) base = seq.first;

        /* 26a. Una sola tesi, "s_n = formula" o "formula = s_n", con la
         * formula senza termini della successione. */
        const Statement *claim = &statement.claim[0];
        for (int side = 0; side < 2 && statement.claims == 1 && claim->relation == REL_EQ; side++) {
            Node *term = side ? claim->rhs : claim->lhs, *closed = side ? claim->lhs : claim->rhs;
            long long a, c;
            if (term->kind == N_SEQ && term->name == seq.name && rat_affine(eval(term->a), &a, &c) && a == 1 && c == 0 &&
                !node_uses_letter(closed, seq.name))
                return prove_closed_form(&seq, closed, variable, base);
        }

        /* 26b. Stime: l'invariante, poi la tabella dei segni. */
        verdict = bound_plan(&statement, &seq, variable, base, attempt, question, sizeof question);
        if (verdict.outcome != PROVED) return verdict.outcome == REFUTED || !attempt ? verdict : refusal;
        Verdict table = ask_sign_table(question);
        if (table.outcome == PROVED) {
            proof_add("\n\\end{itemize}\n$\\Box$");
            verdict.reason = "il passo induttivo è deciso dalla tabella dei segni, e le successioni dichiarate non hanno una notazione nei certificati";
            verdict.proof = proof_text;
            return verdict;
        }

        /* Smentito: l'invariante provato non si conserva, e se ne prova un
         * altro. Non deciso: ci si ferma. */
        if (table.outcome == REFUTED)
            snprintf(reason, sizeof reason, "nessun invariante tra quelli provati si conserva: la tabella dei segni smentisce l'ultimo%s%s",
                     table.detail ? " in " : "", table.detail ? table.detail : "");
        else
            snprintf(reason, sizeof reason, "la tabella dei segni non decide il passo induttivo: %s", table.reason);
        refusal.outcome = table.outcome == UNSUPPORTED ? UNSUPPORTED : NOT_PROVED;
        refusal.base = base;
        refusal.reason = reason;
        if (table.outcome != REFUTED || attempt == INVARIANTS - 1) return refusal;
    }
}

/* 26c. LE ITERATE DI UN'APPLICAZIONE
 *
 * A che cosa serve. "f(x) = 2 + 3x, f^{1} = f e f^{n+1} = f \circ f^{n}:
 * allora f^{n}(x) = (3^{n} - 1) + 3^{n} x per ogni n e ogni x." Fissato x,
 * i numeri s_n = f^{n}(x) sono una successione definita per ricorrenza: s_c =
 * f(x), e s_{n+1} = f^{n+1}(x) = f(f^{n}(x)) = f(s_n), cioè la regola di f
 * con s_n al posto della sua variabile. È ciò che dicono le due ipotesi, e
 * niente di più: l'enunciato sulle iterate è quello sulla successione, e lo
 * dimostra 26a, con x come parametro.
 *
 * Perché il passaggio è lecito, e che cosa serve:
 *
 *   - la regola di f deve valere in s_n: s_n è un valore di f, quindi sta
 *     nel codominio, e il codominio deve stare nel dominio (numbers_subset());
 *     che i valori di f stiano nel codominio lo dimostra 18m;
 *   - la tesi deve essere per ogni n da c in su e per ogni x di una parte del
 *     dominio, f^{n}(x) = E, con E senza iterate;
 *   - 26a vale per i valori del parametro in cui la formula è definita per
 *     ogni n: con le divisioni di E e della regola soltanto per numeri non
 *     c'è riserva, e così si chiede. Per lo stesso motivo una smentita di
 *     26a vale anche qui: per un n fissato E - f^{n}(x) è un polinomio in x
 *     non nullo, che si annulla in un numero finito di punti, e l'insieme di
 *     x è infinito.
 *
 * La successione si scrive nella notazione di parse_sequence_statement(),
 * con una lettera nuova, e la si passa a prove_sequence(): da lì in poi è un
 * enunciato del capitolo 26 come gli altri, con i suoi controlli. */

/* Ritorna 1 se in node compare un'iterata di un'applicazione. */
static int node_iterates(const Node *node) {
    return node && ((node->kind == N_APPLY && node->c) || node_iterates(node->a) || node_iterates(node->b) || node_iterates(node->c));
}

/* 26c. Decide la tesi thesis di un enunciato che definisce le iterate di
 * un'applicazione, come descritto in testa al paragrafo, e ne ritorna il
 * verdetto. Svuota l'arena, come prove_sequence(): al ritorno le applicazioni
 * e la tesi non valgono più. */
static Verdict decide_iterates(const Formula *thesis) {
    static char sequence[MAX_FORMULA], prefix[PROOF_BYTES / 4], shown[3][MAX_FORMULA / 3];
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, "per induzione, sulle iterate come successione", NULL, NULL};
    verdict.reason = "le iterate f^{n} si dimostrano in un'uguaglianza f^{n}(x) = E, per ogni n dal primo indice e per ogni x, "
                     "con f data da una regola sola che manda il codominio nel dominio";

    /* La forma: due "per ogni", n e x, e un'uguaglianza con f^{n}(x) da una
     * parte. */
    const Formula *outer = thesis, *inner = thesis->kind == F_FORALL ? thesis->a : NULL;
    const Formula *equation = inner && inner->kind == F_FORALL ? inner->a : NULL;
    if (!equation || equation->kind != F_EQUAL) return verdict;
    const Node *term = equation->left, *closed = equation->right;
    if (!(term->kind == N_APPLY && term->c)) { term = equation->right; closed = equation->left; }
    if (term->kind != N_APPLY || !term->c || term->c->kind != N_VAR || term->a->kind != N_VAR || node_iterates(closed)) return verdict;
    const Formula *index = outer->variable == term->c->name ? outer : inner, *point = index == outer ? inner : outer;
    if (index->variable != term->c->name || point->variable != term->a->name) return verdict;
    const Map *map = map_find(term->name);
    if (!map || !map->body || map->cases || map->binary || map->partner || statement_parameter_count ||
        map->iterate_from != map->step_from || !index->numbers.integers || !index->numbers.bounded || index->numbers.holes ||
        index->numbers.low + index->numbers.strict != map->iterate_from || !numbers_subset(&map->codomain, &map->domain) ||
        !numbers_subset(&point->numbers, &map->domain) || !divisions_by_numbers(closed) || !divisions_by_numbers(map->body))
        return verdict;
    int n = index->variable, x = point->variable, letter = 0;
    for (const char *c = "satubvw"; *c && !letter; c++)
        if (*c != n && *c != x && !map_find(*c) && !node_uses_letter(closed, *c) && !node_uses_letter(map->body, *c)) letter = *c;
    if (!letter) return verdict;

    /* Che la regola definisca un'applicazione (18m): i valori stanno nel
     * codominio, e quindi nel dominio. */
    proof_reset();
    universal_count = 0;
    proof_add("\\textbf{Proof.} First the iterates are written as a sequence, then the claim is proved for it.\n\\begin{itemize}\n");
    if (!map_defined(map) || failure) {
        failure = NULL;
        verdict.outcome = NOT_PROVED;
        verdict.reason = "non riesco a dimostrare che la regola dà sempre un valore nel codominio";
        return verdict;
    }

    /* La successione, scritta con put_node(): il primo valore f(x), la
     * regola f(s_n), la tesi. Il testo nasce nella dimostrazione e da lì si
     * copia. */
    Node at = {N_SEQ, 0, letter, 0, NULL, NULL, NULL}, variable = {N_VAR, 0, x, 0, NULL, NULL, NULL}, now = {N_VAR, 0, n, 0, NULL, NULL, NULL};
    at.a = &now;
    const Node *value[3] = {&variable, &at, NULL};
    for (int part = 0; part < 3; part++) {
        size_t start = proof_length;
        shown_name = map->parameter;
        shown_value = value[part];
        put_node(part < 2 ? map->body : closed, 0);
        shown_value = NULL;
        size_t length = proof_length - start;
        if (length >= sizeof shown[part] || failure) return verdict;
        memcpy(shown[part], proof_text + start, length);
        shown[part][length] = 0;
        proof_cut(start);
    }
    snprintf(sequence, sizeof sequence, "%c_{%lld} = %s, %c_{%c + 1} = %s, %c \\ge %lld \\implies %c_{%c} = %s", letter,
             map->iterate_from, shown[0], letter, n, shown[1], n, map->iterate_from, letter, n, shown[2]);
    proof_add("\\item \\emph{The iterates as a sequence.} Fix $%c \\in ", x);
    put_numbers(&point->numbers);
    proof_add("$ and let $%c_{%c} = %c^{%c}(%c)$ for $%c \\ge %lld$. By the hypotheses $%c_{%lld} = %c(%c)$ and $%c_{%c + 1} = "
              "%c(%c_{%c})$: the rule of $%c$ applies to $%c_{%c}$, which is a value of $%c$, because the codomain is part of the "
              "domain. So $%c_{%lld} = %s$ and $%c_{%c + 1} = %s$ for $%c \\ge %lld$, and the claim is $%c_{%c} = %s$.\n\\end{itemize}\n",
              letter, n, map->name, n, x, n, map->iterate_from, letter, map->iterate_from, map->name, x, letter, n, map->name,
              letter, n, map->name, letter, n, map->name, letter, map->iterate_from, shown[0], letter, n, shown[1], n,
              map->iterate_from, letter, n, shown[2]);
    if (proof_length >= sizeof prefix) return verdict;
    memcpy(prefix, proof_text, proof_length + 1);

    /* Il capitolo 26, e la dimostrazione con il suo inizio davanti. */
    map_count = 0;
    Verdict decided = prove_sequence(sequence, n, 1, map->iterate_from);
    if (decided.outcome != PROVED || !decided.proof) return decided;
    const char *heading = "\\textbf{Proof.} ";
    if (strncmp(decided.proof, heading, strlen(heading)) == 0) decided.proof += strlen(heading);
    size_t ahead = strlen(prefix), rest = strlen(decided.proof);
    if (ahead + rest + 1 > PROOF_BYTES) { decided.proof = NULL; decided.outcome = NOT_PROVED; decided.reason = "dimostrazione troppo lunga"; return decided; }
    memmove(proof_text + ahead, decided.proof, rest + 1);
    memcpy(proof_text, prefix, ahead);
    proof_length = ahead + rest;
    decided.proof = proof_text;
    return decided;
}

/* =============================================================================
 * 27. DERIVATE: DIMOSTRARLE, CALCOLARLE, USARLE NEGLI STUDI DI FUNZIONE
 * ============================================================================
 *
 * A che cosa serve. "La derivata n-esima di sin x è sin(x + n pi/2)"; "la
 * derivata n-esima di ln x è (-1)^{n-1} (n-1)! / x^n, per n >= 1"; "la
 * derivata di x^2 tan x è x (sin 2x + x) / cos^2 x". L'enunciato arriva
 * nella notazione di parse_derivative_statement(): il segno di derivata, la
 * funzione f, il segno di uguale, una formula g(n, x). Lo stesso segno serve
 * in altri due modi, ognuno nel suo paragrafo:
 *
 *   27j. dentro un'espressione, per gli studi di funzione: il segno diventa
 *        la derivata, e la tabella dei segni (18p) decide l'enunciato;
 *   27k. senza il segno di uguale, come richiesta: la derivata si calcola,
 *        si scrive e si rilegge;
 *   27l. negli studi, i punti in cui la funzione è definita ma le regole
 *        non ne danno la derivata.
 *
 * E il certificato, 27m, che le derivate dimostrate o calcolate portano a
 * checker.c, e che il capitolo 30 usa per le primitive e gli integrali.
 *
 * IL TEOREMA
 *
 * Sia n0 >= 0. Se
 *
 *   27a. la derivata di ordine n0 di f è g(n0, x);
 *   27b. per ogni intero n >= n0 la derivata rispetto a x di g(n, x) è
 *        g(n + 1, x);
 *
 * allora la derivata di ordine n di f è g(n, x) per ogni n >= n0. È
 * un'induzione su n: la derivata di ordine n + 1 è la derivata di quella di
 * ordine n, che per ipotesi è g(n, x), e 27b dice quanto vale. Come ogni
 * verdetto del capitolo 13, vale dove le espressioni sono definite.
 *
 * COME SI DERIVA
 *
 * derive() applica le regole di derivazione all'albero di un'espressione, un
 * nodo alla volta, senza cercare nulla. u e v dipendono da x, c no:
 *
 *   27c. c' = 0, x' = 1, (u + v)' = u' + v', (-u)' = -u';
 *   27d. (u v)' = u' v + u v',   (u / v)' = (u' v - u v') / v^2;
 *   27e. (u^c)' = c u^{c-1} u' con c intero, e c u^c u' / u con ogni
 *        altro c; (c^u)' = c^u ln(c) u', con ln(e) = 1; con x nella base e
 *        nell'esponente u^v = e^{v ln u}, e quindi
 *        (u^v)' = u^v (v' ln u + v u' / u), dove u > 0;
 *   27f. la regola della catena, f(u)' = f'(u) u', con sin' = cos,
 *        cos' = -sin, tan' = 1/cos^2, cot' = -1/sin^2, ln' = 1/u,
 *        arctan' = 1/(1 + u^2), arccot' = -1/(1 + u^2),
 *        arcsin' = 1/sqrt(1 - u^2), arccos' = -1/sqrt(1 - u^2), per la
 *        radice m-esima r di u r' = r u' / (m u), per il valore assoluto
 *        |u|' = u' u / |u| e (ln|u|)' = u'/u, e log_b u = ln u / ln b
 *        anche con x nella base b;
 *   27g. la derivata di una somma con \sum è la somma delle derivate.
 *
 * La lettera e è il numero di Nepero: senza questo e^x non avrebbe per
 * derivata se stessa. Ciò che non rientra (x nell'indice di una radice, un
 * prodotto con \prod, un fattoriale di x) è NON SUPPORTATO.
 *
 * Dove valgono le formule. Ogni regola dà una formula che ha un valore solo
 * dove la funzione è derivabile, e lì vale la derivata: è ciò che permette
 * di usare le derivate dentro un'espressione (27j). Per questo alcune sono
 * scritte in un modo che sembra più lungo del necessario:
 *
 *   - c u^c u' / u, e non c u^{c-1} u', quando c non è intero: u^{3/2} è
 *     definita in u = 0 e lì c u^{c-1} = 0, ma u^{3/2} non è definita per
 *     u < 0, quindi in u = 0 la derivata (da tutte e due le parti) non
 *     esiste; la divisione per u la toglie. È lo stesso motivo della
 *     divisione per m u nella radice;
 *   - u' u / |u| non ha valore dove u = 0, dove |u| di solito non è
 *     derivabile (a volte lo è, come |x^3|: di questi punti si occupa
 *     27l); 1/sqrt(1 - u^2) non ce l'ha dove u = 1 o u = -1, gli estremi
 *     del dominio dell'arcoseno;
 *   - (u^v)' contiene ln u, che chiede u > 0: è la convenzione dei libri,
 *     u^v = e^{v ln u}, e il verdetto la dice.
 *
 * Fatte le derivate, 27a e 27b non contengono più il segno di derivata:
 * sono un'uguaglianza tra due espressioni in x, e un'identità in n e x che
 * l'induzione del capitolo 13 dimostra con tutti i suoi controlli.
 *
 * I CONTROLLI INDIPENDENTI
 *
 * Le regole di derivazione sono scritte una volta sola, in derive(): una
 * regola sbagliata darebbe una dimostrazione con tutti i passi in ordine e
 * la conclusione falsa. Per questo ogni derivata che derive() calcola viene
 * ricontrollata con un metodo che non usa le sue regole, in sei punti x0 e
 * con dei numeri al posto delle altre lettere, attraverso gli intervalli
 * del capitolo 24:
 *
 *   27h. La serie di Taylor della funzione in x0, calcolata con gli
 *        intervalli dall'albero della funzione stessa (vedi "Le derivate con
 *        i numeri", più sotto), dà un intervallo che contiene di sicuro la
 *        derivata k-esima vera in x0. Lo si confronta con il valore in x0
 *        della derivata k-esima calcolata da derive(). Se i due intervalli
 *        non si toccano, una regola è sbagliata: è un errore del programma,
 *        unjustified_steps sale e il verdetto non è né DIMOSTRATO né FALSO.
 *        Se i due numeri distano di sicuro meno di AGREEMENT, la derivata è
 *        confermata in quel punto; altrimenti, lì, non si sa. Ogni derivata
 *        fino all'ordine del caso base deve essere confermata in almeno un
 *        punto, e così la derivata della formula, nel passo 27b, per
 *        n = n0 e n = n0 + 1.
 *   27i. Le derivate di f di ordine n0, n0 + 1, ... vengono confrontate con
 *        la formula: è la strada che non passa dall'induzione. Il verdetto è
 *        FALSO con quell'n solo se in un punto x0 la derivata delle regole è
 *        confermata (27h) e la formula è di sicuro diversa sia da lei sia
 *        da quella della serie di Taylor. Così un FALSO non poggia su una
 *        regola che nessuno ha controllato in quel punto: per dire il falso
 *        dovrebbero sbagliare allo stesso modo, nello stesso punto, due
 *        conti scritti in modo diverso. Se la formula è di sicuro diversa da
 *        uno solo dei due, il verdetto è NON DIMOSTRATO. DIMOSTRATO chiede
 *        che in nessun punto la formula sia smentita, e che in almeno un
 *        punto, per almeno un ordine, la formula e la serie di Taylor
 *        coincidano.
 *
 * Che cosa questi controlli non danno: una prova che le regole sono giuste
 * dappertutto. Due funzioni diverse possono coincidere in sei punti. Ma una
 * regola sbagliata dà una derivata diversa da quella vera quasi ovunque (le
 * funzioni trattate sono analitiche dove sono definite e derivabili, e due
 * funzioni analitiche diverse su un intervallo coincidono lì solo in punti
 * isolati), e sei punti scelti senza guardare le regole bastano a vederla,
 * salvo coincidenze. Un FALSO dice invece una cosa precisa, che gli
 * intervalli garantiscono se le ricorrenze di 27h sono scritte giuste (ed è
 * per questo che vi devono concordare anche le regole): in quel punto, con
 * quei valori delle altre lettere, la derivata vera non è la formula.
 *
 * IL CERTIFICATO (27m)
 *
 * Il verdetto DIMOSTRATO, o RISOLTO per una richiesta, porta un certificato
 * per checker.c (capitolo 13), che deriva la funzione da sé, con regole sue
 * scritte un'altra volta, e decide con la sua algebra esatta che la
 * differenza dalla formula è zero. Il verificatore conosce funzioni
 * razionali, esponenziali, logaritmi, seni, coseni, arcotangenti, radici e
 * valori assoluti, non arcoseno e arcocoseno: dove non arriva il verdetto
 * dice perché il certificato manca. Gli studi di funzione (27j), decisi con
 * la tabella dei segni, non hanno ancora un certificato: servirebbe insieme
 * quello della tabella e quello di ogni derivata espansa.
 */

/* Il motivo con cui prove_derivative() rifiuta ciò che non è scritto come una
 * derivata. Ha un nome perché prove() (capitolo 20) lo riconosce e lo
 * sostituisce con il motivo più preciso del lettore, se c'è. */
static const char *const NOT_A_DERIVATIVE = "l'enunciato non comincia con il segno di derivata";

/* Ritorna tree con i figli a, b e c al posto dei suoi: tree stesso se sono
 * gli stessi, altrimenti una copia con gli altri campi uguali. Non copiare
 * ciò che non cambia conta: la tabella dei segni riconosce come uno solo un
 * valore assoluto che un albero raggiunge per due strade, dal suo indirizzo
 * (abs_collect()). */
static Node *node_rebuilt(const Node *tree, Node *a, Node *b, Node *c) {
    if (a == tree->a && b == tree->b && c == tree->c) return (Node *)tree;
    Node *copy = node_new(tree->kind, a, b);
    copy->c = c;
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    return copy;
}

/* Ritorna tree con ogni sotto-albero senza lettere che vale un numero
 * intero sostituito da quel numero: (3 - 1)! diventa 2, (-1)^{3 - 1}
 * diventa 1. Serve prima di calcolare con gli intervalli, che non conoscono
 * i fattoriali e leggono un esponente solo se è un numero scritto, e alla
 * regola delle potenze (27e), che deve sapere se un esponente è un intero.
 * I nodi che non cambiano restano gli stessi (node_rebuilt()). Mette 0 in
 * *closed, che chi chiama ha messo a 1, se tree contiene lettere. Un conto
 * che fallisce lascia l'albero com'è. */
static Node *node_fold(const Node *tree, int *closed) {
    if (!tree) return NULL;
    if (tree->kind == N_NUM) return (Node *)tree;
    if (tree->kind == N_VAR || tree->kind == N_SEQ || tree->kind == N_BIGOP || tree->kind == N_APPLY || tree->kind == N_DERIV) { *closed = 0; return (Node *)tree; }
    int inside = 1;
    Node *a = node_fold(tree->a, &inside), *b = node_fold(tree->b, &inside);
    Node *copy = node_rebuilt(tree, a, b, tree->c);
    if (!inside) { *closed = 0; return copy; }

    /* Senza lettere: il valore, se è un intero. */
    const char *saved = failure;
    Scratch mark = scratch_mark();
    long long value;
    env_count = 0;
    int whole = rat_integer(eval(copy), &value) && failure == saved;
    failure = saved;
    scratch_drop(mark);
    return whole ? node_num(value) : copy;
}

/* Ritorna outer per la derivata di inner rispetto a x: la regola della
 * catena. Se inner è x stessa il fattore è 1 e non si scrive. */
static Node *derive(const Node *f, int x);
static Node *chain(Node *outer, const Node *inner, int x) {
    if (inner->kind == N_VAR && inner->name == x) return outer;
    return node_new(N_MUL, outer, derive(inner, x));
}

/* Ritorna l'albero della derivata di f rispetto alla variabile x, con le
 * regole da 27c a 27g. Se f contiene qualcosa che non sa derivare fallisce,
 * e il valore ritornato non ha significato. La formula ha un valore solo
 * dove f è derivabile (vedi "Dove valgono le formule", in testa al
 * capitolo).
 *
 * Le semplificazioni sono solo quelle che evitano di scrivere zeri e
 * fattori 1: un fattore costante resta fuori dalla derivata, e la catena
 * tace la derivata di x. Il resto lo fa la valutazione. */
static Node *derive(const Node *f, int x) {
    Node *u = f->a, *v = f->b;
    if (failure) return node_num(0);

    /* 27c. Costanti, la variabile, somme. */
    if (!node_has_variable(f, x)) return node_num(0);
    switch (f->kind) {
    case N_VAR: return node_num(1);
    case N_NEG: return node_new(N_NEG, derive(u, x), NULL);
    case N_ADD: case N_SUB:
        if (!node_has_variable(u, x)) return f->kind == N_ADD ? derive(v, x) : node_new(N_NEG, derive(v, x), NULL);
        if (!node_has_variable(v, x)) return derive(u, x);
        return node_new(f->kind, derive(u, x), derive(v, x));

    /* 27d. Prodotti e quozienti. */
    case N_MUL:
        if (!node_has_variable(u, x)) return node_new(N_MUL, u, derive(v, x));
        if (!node_has_variable(v, x)) return node_new(N_MUL, derive(u, x), v);
        return node_new(N_ADD, node_new(N_MUL, derive(u, x), v), node_new(N_MUL, u, derive(v, x)));
    case N_DIV:
        if (!node_has_variable(v, x)) return node_new(N_DIV, derive(u, x), v);
        if (!node_has_variable(u, x)) return node_new(N_NEG, node_new(N_DIV, node_new(N_MUL, u, derive(v, x)), node_new(N_POW, v, node_num(2))), NULL);
        return node_new(N_DIV, node_new(N_SUB, node_new(N_MUL, derive(u, x), v), node_new(N_MUL, u, derive(v, x))),
                        node_new(N_POW, v, node_num(2)));

    /* 27e. Potenze. Con la variabile solo nella base: c u^{c-1} u' se
     * l'esponente è un intero scritto come numero, altrimenti c u^c u' / u
     * (vedi la testa del capitolo). Con la variabile solo nell'esponente:
     * c^u ln(c) u'. Con la variabile in tutti e due: u^v = e^{v ln u}, la
     * regola della catena e quella del prodotto danno
     * u^v (v' ln u + v u' / u). */
    case N_POW: {
        /* L'esponente c - 1 si scrive già calcolato: gli intervalli (capitolo
         * 24), con cui la tabella dei segni ricontrolla le sue righe, leggono
         * come intero solo un esponente scritto come numero, e u^{3 - 1}
         * per loro non avrebbe valore dove u < 0. */
        int closed = 1;
        Node *whole = node_has_variable(v, x) ? NULL : node_fold(v, &closed);
        if (whole && whole->kind == N_NUM) return chain(node_new(N_MUL, whole, node_new(N_POW, u, node_num(whole->value - 1))), u, x);
        if (whole) return node_new(N_DIV, node_new(N_MUL, node_new(N_MUL, v, (Node *)f), derive(u, x)), u);
        if (!node_has_variable(u, x)) {
            if (u->kind == N_VAR && u->name == 'e') return chain((Node *)f, v, x);
            return chain(node_new(N_MUL, (Node *)f, node_call(FN_LN, u, NULL)), v, x);
        }
        return node_new(N_MUL, (Node *)f, node_new(N_ADD, node_new(N_MUL, derive(v, x), node_call(FN_LN, u, NULL)),
                                                  node_new(N_DIV, node_new(N_MUL, v, derive(u, x)), u)));
    }

    /* 27f. Funzioni: la regola della catena. */
    case N_CALL:
        switch ((Function)f->op) {
        case FN_SIN: return chain(node_call(FN_COS, u, NULL), u, x);
        case FN_COS: return chain(node_new(N_NEG, node_call(FN_SIN, u, NULL), NULL), u, x);
        case FN_TAN: return node_new(N_DIV, derive(u, x), node_new(N_POW, node_call(FN_COS, u, NULL), node_num(2)));
        case FN_COT: return node_new(N_NEG, node_new(N_DIV, derive(u, x), node_new(N_POW, node_call(FN_SIN, u, NULL), node_num(2))), NULL);
        case FN_LN:
            /* (ln|w|)' = w'/w dove w non è zero: dove w > 0 è (ln w)', dove
             * w < 0 è (ln(-w))' = -w'/(-w). È la regola che serve a
             * ricontrollare le primitive con ln|w|. */
            if (u->kind == N_CALL && u->op == FN_ABS) u = u->a;
            return node_new(N_DIV, derive(u, x), u);
        case FN_LOG:
            /* log_b u = ln u / ln b, dove b > 0 e b diverso da 1: con b
             * costante si divide per ln b (e con b = e non si divide), con x
             * nella base si deriva il quoziente. */
            if (!v) break;
            if (node_has_variable(v, x)) return derive(node_new(N_DIV, node_call(FN_LN, u, NULL), node_call(FN_LN, v, NULL)), x);
            if (v->kind == N_VAR && v->name == 'e') return derive(node_call(FN_LN, u, NULL), x);
            return node_new(N_DIV, derive(node_call(FN_LN, u, NULL), x), node_call(FN_LN, v, NULL));
        case FN_ARCTAN: return node_new(N_DIV, derive(u, x), node_new(N_ADD, node_num(1), node_new(N_POW, u, node_num(2))));
        case FN_ARCCOT: return node_new(N_NEG, node_new(N_DIV, derive(u, x), node_new(N_ADD, node_num(1), node_new(N_POW, u, node_num(2)))), NULL);
        case FN_ARCSIN: case FN_ARCCOS: {
            /* sin y = u con y in [-pi/2, pi/2] dà cos(y) y' = u', e lì
             * cos y = sqrt(1 - u^2); per l'arcocoseno, cos y = u con y in
             * [0, pi], -sin(y) y' = u' e sin y = sqrt(1 - u^2). */
            Node *slope = node_new(N_DIV, derive(u, x), node_call(FN_ROOT, node_new(N_SUB, node_num(1), node_new(N_POW, u, node_num(2))), node_num(2)));
            return f->op == FN_ARCSIN ? slope : node_new(N_NEG, slope, NULL);
        }
        case FN_ROOT:
            if (node_has_variable(v, x)) break;
            return node_new(N_DIV, node_new(N_MUL, (Node *)f, derive(u, x)), node_new(N_MUL, v, u));
        case FN_ABS:
            /* |u| vale u dove u > 0 e -u dove u < 0: la derivata è u' o -u',
             * cioè u' per il segno di u, che è u / |u|. */
            return node_new(N_DIV, node_new(N_MUL, derive(u, x), u), (Node *)f);
        default: break;
        }
        break;

    /* 27g. Una somma finita, con gli estremi che non dipendono da x. */
    case N_BIGOP: {
        if (f->op || f->name == x || node_has_variable(u, x) || node_has_variable(v, x)) break;
        Node *sum = node_new(N_BIGOP, u, v);
        sum->name = f->name;
        sum->c = derive(f->c, x);
        return sum;
    }
    default:
        break;
    }
    fail("derivata di un'espressione che le regole di derivazione del programma non trattano");
    return node_num(0);
}

/* I punti in cui le derivate vengono controllate con i numeri. Sono scelti
 * perché le funzioni degli esercizi vi siano definite: positivi e negativi,
 * uno minore di 1/2, e alcuni più lontani dall'origine, per le funzioni
 * definite solo oltre un numero (ln(x - 2), una radice di x + 2), che un
 * segno di derivata dentro un'espressione (27j) deve poter confermare. */
static const Frac derivative_points[] = {{3, 10}, {7, 5}, {-9, 10}, {13, 5}, {-11, 5}, {23, 4}};
enum { DERIVATIVE_POINTS = sizeof derivative_points / sizeof *derivative_points };

/* Ritorna una copia di tree pronta per essere calcolata con i numeri nella
 * sola variabile x: la lettera order vale l'intero at, ogni altra lettera
 * (tranne e, che è un numero) un razionale fisso, diverso da lettera a
 * lettera, e i sotto-alberi interi sono già calcolati (node_fold()). */
static Node *sample_tree(const Node *tree, int x, int order, long long at) {
    Node *copy = node_replace(tree, order, node_num(at));
    for (int letter = 'A'; letter <= 'z'; letter++) {
        if (!isalpha(letter) || letter == x || letter == 'e' || !node_has_variable(copy, letter)) continue;
        copy = node_replace(copy, letter, node_new(N_DIV, node_num(3 + letter % 7), node_num(2 + letter % 5)));
    }
    return node_fold(copy, &(int){1});
}

/* Quante derivate di f, oltre quella del caso base, vengono calcolate una
 * dopo l'altra per confrontarle con la formula; il più grande caso base
 * ammesso, perché ogni derivata allunga l'albero; la lunghezza oltre la
 * quale si smette di derivare; e quindi l'ordine più alto di una derivata
 * controllata con i numeri. */
#define DIRECT_ORDERS 3
#define MAX_DERIVATIVE_BASE 4
#define MAX_DERIVATIVE_NODES 20000
#define MAX_JET (MAX_DERIVATIVE_BASE + DIRECT_ORDERS)

/* LE DERIVATE CON I NUMERI: LA SERIE DI TAYLOR TRONCATA (27h)
 *
 * Il problema. Per controllare derive() serve la derivata di f in un punto
 * x0 calcolata senza le sue regole. Il rapporto incrementale
 * (f(x0 + h) - f(x0 - h)) / (2h) non va bene: sbaglia di circa h^2, e con h
 * piccolo perde cifre sottraendo due numeri quasi uguali. Dire "la derivata
 * delle regole è sbagliata" chiederebbe allora una tolleranza scelta a
 * occhio tra due double, cioè proprio un confronto in virgola mobile che
 * decide. Qui la derivata si calcola invece esatta, con i numeri.
 *
 * L'idea: i numeri duali. Si calcola f non su un numero ma su una coppia
 * a + a' eps, con la sola regola eps^2 = 0:
 *
 *     (a + a' eps) + (b + b' eps) = (a + b) + (a' + b') eps,
 *     (a + a' eps) (b + b' eps)   = a b + (a' b + a b') eps.
 *
 * La seconda componente segue da sé la regola della somma e quella del
 * prodotto. Partendo da x0 + 1 eps, alla fine del conto si ha
 * f(x0) + f'(x0) eps: la derivata esatta, senza errore di troncamento,
 * perché non si è approssimato nulla, si è solo portato un numero in più in
 * ogni conto. È la differenziazione automatica "in avanti".
 *
 * Con eps^{K+1} = 0 al posto di eps^2 = 0 la coppia diventa un polinomio in
 * eps di grado K: i primi termini della serie di Taylor di f in x0,
 *
 *     f(x0 + eps) = c_0 + c_1 eps + ... + c_K eps^K + (termini di grado > K),
 *     con c_k = f^(k)(x0) / k!,
 *
 * da cui si leggono tutte le derivate fino alla K-esima in un colpo solo.
 * Somma e prodotto sono quelli dei polinomi, buttando i gradi oltre K: un
 * termine buttato non contribuisce mai ai gradi più bassi, quindi c_0, ...,
 * c_K restano esatti. Per una funzione di u si usa l'equazione
 * differenziale che la funzione soddisfa, e confrontando i coefficienti di
 * eps^{k-1} se ne ricava una ricorrenza. Per e = exp(u), che ha e' = u' e:
 *
 *     k e_k = sum_{i=1..k} i u_i e_{k-i}.
 *
 * Le altre, con u = u_0 + u_1 eps + ...:
 *
 *   27h-1. q = a / b, da b q = a:  q_k = (a_k - sum_{i=1..k} b_i q_{k-i}) / b_0;
 *   27h-2. s = sin u e c = cos u, da s' = c u' e c' = -s u':
 *            k s_k = sum_{i=1..k} i u_i c_{k-i},  k c_k = -sum_{i=1..k} i u_i s_{k-i};
 *          tan u = s / c e cot u = c / s, con 27h-1;
 *   27h-3. y con y_0 dato e w y' = u':
 *            y_k = (k u_k - sum_{j=1..k-1} (k - j) w_j y_{k-j}) / (k w_0);
 *          è ln u con w = u, ed è arctan u con w = 1 + u^2; arccot u è
 *          pi/2 - arctan u. Per y = arcsin u, che ha sin y = u, è
 *          cos(y) y' = u': w = cos y dipende da y, ma per y_k servono solo
 *          w_0, ..., w_{k-1}, che le ricorrenze di 27h-2 danno da y_1, ...,
 *          y_{k-1}, già calcolati; così anche arccos u, con cos y = u e
 *          w = -sin y. La radice di 1 - u^2 della regola di derive() qui
 *          non compare;
 *   27h-4. u^v = exp(v ln u), per u_0 > 0; con v intero scritto come
 *          numero, prodotti ripetuti, per ogni u_0. La radice m-esima è
 *          exp(ln(u) / m), log_b u è ln u / ln b;
 *   27h-5. una somma \sum, o un prodotto \prod, con gli estremi numeri si
 *          svolge, termine per termine.
 *
 * (Riferimenti: A. Griewank, A. Walther, Evaluating Derivatives, SIAM 2008,
 * capitolo 13; R. E. Moore, Methods and Applications of Interval Analysis,
 * SIAM 1979, per le serie di Taylor con gli intervalli.)
 *
 * Perché ci si può credere. Il punto x0 è un intervallo minuscolo che lo
 * contiene, e ogni coefficiente è calcolato con le operazioni del capitolo
 * 24, ognuna delle quali dà un intervallo che contiene il risultato vero
 * per ogni scelta dei dati nei loro intervalli: quindi l'intervallo finale
 * contiene il vero c_k. E ogni operazione si fa solo dove la funzione è
 * analitica: se b_0 può essere zero, o se sotto un logaritmo u_0 può non
 * essere positivo, il coefficiente c_0 è "non so", e allora si dichiara
 * "non so" la serie intera (lì f non è derivabile, o non si sa). Questo
 * conta: le ricorrenze del logaritmo, per esempio, darebbero c_1 = u_1 / u_0
 * anche con u_0 < 0, dove ln u non esiste.
 *
 * Perché è indipendente da derive(). La serie si costruisce dall'albero
 * della funzione di partenza, non da quello delle derivate, e le regole
 * sono scritte qui una seconda volta in un'altra forma: la tangente come
 * quoziente di serie e non come 1 / cos^2, le radici e le potenze attraverso
 * exp e ln, il logaritmo e l'arcotangente con 27h-3. Un errore di derive()
 * non si ripete uguale qui. */

/* Una funzione vicino a x0, data dai primi coefficienti della sua serie di
 * Taylor: c[k] contiene f^(k)(x0) / k!. Invariante, per le serie che
 * jet_eval() ritorna: se c[0] è "non so" lo sono tutti, e la serie dice "non
 * so". */
typedef struct {
    int order;             /* K: il grado più alto tenuto, da 0 a MAX_JET */
    Range c[MAX_JET + 1];  /* i coefficienti da 0 a order; gli altri non contano */
} Jet;

/* Ritorna la costante value come serie di ordine order. */
static Jet jet_constant(Range value, int order) {
    Jet jet = {order, {{0, 0}}};
    jet.c[0] = value;
    return jet;
}

/* Ritorna a + sign b, con sign uguale a 1 oppure a -1. */
static Jet jet_add(Jet a, Jet b, int sign) {
    for (int k = 0; k <= a.order; k++) a.c[k] = sign > 0 ? range_add(a.c[k], b.c[k]) : range_sub(a.c[k], b.c[k]);
    return a;
}

/* Ritorna a b: il prodotto dei due polinomi, senza i gradi oltre order. */
static Jet jet_mul(Jet a, Jet b) {
    Jet product = jet_constant((Range){0, 0}, a.order);
    for (int k = 0; k <= a.order; k++)
        for (int i = 0; i <= k; i++) product.c[k] = range_add(product.c[k], range_mul(a.c[i], b.c[k - i]));
    return product;
}

/* Ritorna a / b (27h-1). Quando si calcola q_k, i q_{k-i} sono già finiti. */
static Jet jet_div(Jet a, Jet b) {
    Jet q = a;
    for (int k = 0; k <= a.order; k++) {
        for (int i = 1; i <= k; i++) q.c[k] = range_sub(q.c[k], range_mul(b.c[i], q.c[k - i]));
        q.c[k] = range_div(q.c[k], b.c[0]);
    }
    return q;
}

/* Ritorna a elevato all'intero e, con prodotti ripetuti (27h-4). */
static Jet jet_power(Jet a, long long e) {
    Jet one = jet_constant((Range){1, 1}, a.order), power = one;
    for (long long i = 0; i < (e < 0 ? -e : e); i++) power = jet_mul(power, a);
    return e < 0 ? jet_div(one, power) : power;
}

/* Ritorna exp(u), con la ricorrenza della testa di questa parte. */
static Jet jet_exp(Jet u) {
    Jet e = jet_constant(range_exp(u.c[0]), u.order);
    for (int k = 1; k <= u.order; k++) {
        for (int i = 1; i <= k; i++) e.c[k] = range_add(e.c[k], range_mul(range_mul(range_ratio(i, 1), u.c[i]), e.c[k - i]));
        e.c[k] = range_div(e.c[k], range_ratio(k, 1));
    }
    return e;
}

/* Ritorna la serie y con y_0 = start e w y' = u' (27h-3). */
static Jet jet_solve(Range start, Jet u, Jet w) {
    Jet y = jet_constant(start, u.order);
    for (int k = 1; k <= u.order; k++) {
        Range sum = range_mul(range_ratio(k, 1), u.c[k]);
        for (int j = 1; j < k; j++) sum = range_sub(sum, range_mul(range_mul(range_ratio(k - j, 1), w.c[j]), y.c[k - j]));
        y.c[k] = range_div(sum, range_mul(range_ratio(k, 1), w.c[0]));
    }
    return y;
}

/* Ritorna ln u: 27h-3 con w = u. */
static Jet jet_ln(Jet u) { return jet_solve(range_ln(u.c[0]), u, u); }

/* Ritorna arctan u: 27h-3 con w = 1 + u^2. */
static Jet jet_atan(Jet u) { return jet_solve(range_atan(u.c[0]), u, jet_add(jet_constant((Range){1, 1}, u.order), jet_mul(u, u), 1)); }

/* Mette in *sine e *cosine sin u e cos u (27h-2). Le due ricorrenze si
 * intrecciano: s_k usa i c_j con j < k, e viceversa, già finiti. */
static void jet_sin_cos(Jet u, Jet *sine, Jet *cosine) {
    Jet s = jet_constant(range_none(), u.order), c = s;
    range_sin_cos(u.c[0], &s.c[0], &c.c[0]);
    for (int k = 1; k <= u.order; k++) {
        for (int i = 1; i <= k; i++) {
            Range step = range_mul(range_ratio(i, 1), u.c[i]);
            s.c[k] = range_add(s.c[k], range_mul(step, c.c[k - i]));
            c.c[k] = range_sub(c.c[k], range_mul(step, s.c[k - i]));
        }
        s.c[k] = range_div(s.c[k], range_ratio(k, 1));
        c.c[k] = range_div(c.c[k], range_ratio(k, 1));
    }
    *sine = s;
    *cosine = c;
}

/* Ritorna arcsin u (sine = 1) o arccos u (sine = 0), con 27h-3: y_k viene
 * da w y' = u', con w = cos y per l'arcoseno e w = -sin y per l'arcocoseno,
 * e insieme a y si costruiscono, un grado alla volta, le serie di sin y e
 * cos y (27h-2). Il valore y_0 lo dà range_asin(). Dove |u_0| non è di
 * sicuro minore di 1, w_0 può essere zero e la divisione dà "non so": lì la
 * funzione non è derivabile, o non si sa. */
static Jet jet_arc(Jet u, int sine) {
    Range start = sine ? range_asin(u.c[0]) : range_from_half_pi(range_asin(u.c[0]));
    Jet y = jet_constant(start, u.order), s = y, c = y;
    range_sin_cos(start, &s.c[0], &c.c[0]);
    for (int k = 1; k <= u.order; k++) {
        /* y_k, con i w_j per j < k già noti. */
        Range sum = range_mul(range_ratio(k, 1), u.c[k]);
        for (int j = 1; j < k; j++) sum = range_sub(sum, range_mul(range_mul(range_ratio(k - j, 1), sine ? c.c[j] : range_neg(s.c[j])), y.c[k - j]));
        y.c[k] = range_div(sum, range_mul(range_ratio(k, 1), sine ? c.c[0] : range_neg(s.c[0])));

        /* s_k e c_k, che chiedono y_1, ..., y_k. */
        s.c[k] = c.c[k] = (Range){0, 0};
        for (int i = 1; i <= k; i++) {
            Range step = range_mul(range_ratio(i, 1), y.c[i]);
            s.c[k] = range_add(s.c[k], range_mul(step, c.c[k - i]));
            c.c[k] = range_sub(c.c[k], range_mul(step, s.c[k - i]));
        }
        s.c[k] = range_div(s.c[k], range_ratio(k, 1));
        c.c[k] = range_div(c.c[k], range_ratio(k, 1));
    }
    return y;
}

/* Ritorna la serie di Taylor di ordine order, nel punto at, dell'espressione
 * node, già passata da sample_tree(): x è la variabile, e le sole altre
 * lettere ammesse sono e e pi greco. La serie è "non so" dove il calcolo non
 * riesce, o dove node non è definita o non è derivabile; anche per ciò che
 * qui non si calcola (un fattoriale di x, un'applicazione). Con order = 0 è
 * il valore di node in at.
 *
 * Sfrutta node_fold() e node_replace() per svolgere somme e prodotti: i nodi
 * che crea per un termine li toglie dall'arena appena calcolato il termine. */
static Jet jet_eval(const Node *node, int x, Range at, int order) {
    Jet a, sine, cosine, result = jet_constant(range_none(), order);
    switch (node->kind) {
    case N_NUM: result = jet_constant(range_ratio(node->value, 1), order); break;
    case N_VAR:
        /* x è x0 + eps; la lettera e è il numero di Nepero. */
        if (node->name == x) {
            result = jet_constant(at, order);
            if (order > 0) result.c[1] = (Range){1, 1};
        } else if (node->name == VAR_PI) result = jet_constant(range_pi(), order);
        else if (node->name == 'e') result = jet_constant(range_exp_at(1), order);
        break;
    case N_NEG: result = jet_add(jet_constant((Range){0, 0}, order), jet_eval(node->a, x, at, order), -1); break;
    case N_ADD: case N_SUB:
        result = jet_add(jet_eval(node->a, x, at, order), jet_eval(node->b, x, at, order), node->kind == N_ADD ? 1 : -1);
        break;
    case N_MUL: result = jet_mul(jet_eval(node->a, x, at, order), jet_eval(node->b, x, at, order)); break;
    case N_DIV: result = jet_div(jet_eval(node->a, x, at, order), jet_eval(node->b, x, at, order)); break;
    case N_POW: {
        /* 27h-4. L'esponente intero, scritto come numero (dopo node_fold()
         * anche negativo), con i prodotti; ogni altro con exp(v ln u). Il
         * limite sull'esponente è quello di node_range(). */
        const Node *exponent = node->b->kind == N_NEG ? node->b->a : node->b;
        long long e = exponent->kind != N_NUM ? MAX_UNI + 1 : node->b->kind == N_NEG ? -exponent->value : exponent->value;
        a = jet_eval(node->a, x, at, order);
        result = e >= -MAX_UNI && e <= MAX_UNI ? jet_power(a, e) : jet_exp(jet_mul(jet_eval(node->b, x, at, order), jet_ln(a)));
        break;
    }
    case N_CALL:
        a = jet_eval(node->a, x, at, order);
        switch (node->op) {
        case FN_SIN: case FN_COS: case FN_TAN: case FN_COT:
            jet_sin_cos(a, &sine, &cosine);
            if (node->op == FN_SIN || node->op == FN_COS) result = node->op == FN_SIN ? sine : cosine;
            else result = node->op == FN_TAN ? jet_div(sine, cosine) : jet_div(cosine, sine);
            break;
        case FN_LN: result = jet_ln(a); break;
        case FN_LOG:
            if (node->b) result = jet_div(jet_ln(a), jet_ln(jet_eval(node->b, x, at, order)));
            break;
        case FN_ARCTAN: result = jet_atan(a); break;
        case FN_ARCCOT: result = jet_add(jet_constant(range_from_half_pi((Range){0, 0}), order), jet_atan(a), -1); break;
        case FN_ARCSIN: case FN_ARCCOS: result = jet_arc(a, node->op == FN_ARCSIN); break;
        case FN_ROOT: {
            /* La radice m-esima è exp(ln(u) / m); con m dispari e u_0 < 0 è
             * la radice reale, -exp(ln(-u) / m) (11o). */
            int side, negative = node->b->kind == N_NUM && node->b->value % 2 && range_side(a.c[0], &side) && side < 0;
            Jet zero = jet_constant((Range){0, 0}, order), inside = negative ? jet_add(zero, a, -1) : a;
            if (node->b->kind == N_NUM && node->b->value >= 2) result = jet_exp(jet_div(jet_ln(inside), jet_constant(range_ratio(node->b->value, 1), order)));
            if (negative) result = jet_add(zero, result, -1);
            break;
        }
        case FN_ABS: {
            /* |u| è u oppure -u dove il segno di u è certo, e lì è derivabile. */
            int side;
            if (range_side(a.c[0], &side)) result = side > 0 ? a : jet_add(jet_constant((Range){0, 0}, order), a, -1);
            break;
        }
        default: break;
        }
        break;
    case N_BIGOP: {
        /* 27h-5. Una somma, o un prodotto, con gli estremi che, calcolati,
         * sono numeri. Come in 11a, l'estremo superiore può essere
         * l'inferiore meno 1, la somma (o il prodotto) vuota, ma non più
         * piccolo. */
        int closed = 1;
        const Node *low = node_fold(node->a, &closed), *high = node_fold(node->b, &closed);
        if (low->kind != N_NUM || high->kind != N_NUM) break;
        __int128 terms = (__int128)high->value - low->value + 1;
        if (terms < 0 || terms > MAX_UNROLL) break;
        result = jet_constant((Range){node->op ? 1 : 0, node->op ? 1 : 0}, order);
        for (long long i = 0; i < (long long)terms && !failure; i++) {
            Scratch mark = scratch_mark();
            Jet term = jet_eval(node_fold(node_replace(node->c, node->name, node_num(low->value + i)), &closed), x, at, order);
            result = node->op ? jet_mul(result, term) : jet_add(result, term, 1);
            scratch_drop(mark);
        }
        break;
    }
    default: break;
    }

    /* L'invariante: senza il valore, nessun coefficiente vale (vedi "Perché
     * ci si può credere"). Un'arena esaurita lascia alberi di riserva, che non
     * dicono nulla. */
    if (!range_known(result.c[0]) || failure)
        for (int k = 0; k <= order; k++) result.c[k] = range_none();
    return result;
}

/* Ritorna un intervallo che contiene il valore di tree, già passato da
 * sample_tree(), in at; "non so" se non si calcola o non è definito. */
static Range sample_value(const Node *tree, int x, Range at) { return jet_eval(tree, x, at, 0).c[0]; }

/* Quanto devono essere vicini due valori dello stesso numero, calcolati in
 * due modi, per dire che coincidono: in rapporto alla grandezza del numero,
 * più 1. È molto più largo dell'errore degli intervalli, e molto più stretto
 * dello scarto che dà una regola sbagliata. */
#define AGREEMENT 1e-9

/* Confronta due intervalli a e b che dovrebbero contenere lo stesso numero.
 * Ritorna -1 se i due numeri sono di sicuro diversi (gli intervalli non si
 * toccano); 1 se la loro distanza è di sicuro al più AGREEMENT (1 + |a|);
 * 0 se non si sa dire né l'una né l'altra cosa: un "non so", o intervalli
 * troppo larghi.
 *
 * Perché non è un confronto tra double che decide: la differenza vera sta
 * di sicuro in gap, quindi gap dentro [-room, room] è una disuguaglianza
 * garantita sulla differenza vera, ricavata da un intervallo come al
 * capitolo 24. E la risposta 1 non dimostra nulla: dice solo che il
 * controllo non ha trovato errori. */
static int numbers_agree(Range a, Range b) {
    Range gap = range_sub(a, b);
    int side;
    if (range_side(gap, &side)) return -1;
    if (!range_known(gap)) return 0;
    double size = a.high > -a.low ? a.high : -a.low, room = AGREEMENT * (1 + size);
    return gap.low >= -room && gap.high <= room;
}

/* Il confronto, punto per punto, tra le derivate calcolate con le regole e
 * quelle lette dalla serie di Taylor (27h), per le derivate di ordine da 0
 * a order di una funzione. */
typedef struct {
    Range taylor[MAX_JET + 1][DERIVATIVE_POINTS];  /* [k][p]: la derivata k-esima vera in x_p */
    Range rules[MAX_JET + 1][DERIVATIVE_POINTS];   /* [k][p]: la derivata k-esima delle regole, calcolata in x_p */
    int agree[MAX_JET + 1];  /* [k]: il bit p è acceso se in x_p le due coincidono (numbers_agree() = 1) */
    int wrong;               /* 1 se, per qualche k e qualche p, sono di sicuro diverse */
} DerivativeCheck;

/* Riempie *check per una funzione, derived[0], e le sue derivate derived[1],
 * ..., derived[order] calcolate con le regole: tutti gli alberi sono già
 * passati da sample_tree(). In ogni punto di prova la serie di Taylor della
 * funzione si calcola una volta sola, fino all'ordine order, e la derivata
 * k-esima è k! per il coefficiente c_k. Per k = 0 il confronto è tra due
 * calcoli del valore della funzione: non controlla una regola, ma lo
 * stesso un FALSO con n = 0 vi si appoggia (27i). */
static void derivatives_check(DerivativeCheck *check, Node *const *derived, int order, int x) {
    memset(check, 0, sizeof *check);
    for (int p = 0; p < DERIVATIVE_POINTS; p++) {
        Range at = range_ratio(derivative_points[p].num, derivative_points[p].den), factorial = {1, 1};
        Jet taylor = jet_eval(derived[0], x, at, order);
        for (int k = 0; k <= order; k++) {
            if (k > 0) factorial = range_mul(factorial, range_ratio(k, 1));
            check->taylor[k][p] = range_mul(factorial, taylor.c[k]);
            check->rules[k][p] = sample_value(derived[k], x, at);
            int agreement = numbers_agree(check->rules[k][p], check->taylor[k][p]);
            if (agreement < 0) check->wrong = 1;
            if (agreement > 0) check->agree[k] |= 1 << p;
        }
    }
}

/* Ritorna il numero di nodi di tree, contando una volta per ogni strada i
 * sotto-alberi condivisi: è il costo di un conto sull'albero. */
static long long node_count(const Node *tree) {
    return tree ? 1 + node_count(tree->a) + node_count(tree->b) + node_count(tree->c) : 0;
}

/* Riempie direct[1], ..., direct[order] con le derivate di direct[0]
 * rispetto a x, con le regole, e *check con il loro confronto con la serie
 * di Taylor (27h). Ritorna 1 se nessuna è smentita in nessun punto e
 * ognuna coincide con la serie in almeno un punto. Altrimenti il motivo è
 * in `failure`, e ritorna 0 se le regole non si applicano (la funzione
 * contiene qualcosa che non sanno derivare, o la derivata è troppo lunga),
 * -1 se la derivata non è confermata. Una smentita, che è l'errore di una
 * regola, conta tra i passi scartati. */
static int derivatives_confirmed(Node **direct, int order, int x, DerivativeCheck *check) {
    Node *sampled[MAX_JET + 1];
    for (int k = 1; k <= order && !failure; k++) {
        direct[k] = derive(direct[k - 1], x);
        if (!failure && node_count(direct[k]) > MAX_DERIVATIVE_NODES) fail("la derivata calcolata con le regole è troppo lunga");
    }
    for (int k = 0; k <= order && !failure; k++) sampled[k] = sample_tree(direct[k], x, 0, 0);
    if (failure) return 0;
    derivatives_check(check, sampled, order, x);
    if (failure) return -1;
    if (check->wrong) {
        unjustified_steps++;
        fail("una derivata calcolata con le regole di derivazione è smentita dalla serie di Taylor della funzione");
        return -1;
    }
    for (int k = 1; k <= order; k++)
        if (!check->agree[k]) { fail("non riesco a confermare con i numeri una derivata calcolata con le regole di derivazione: nei punti di prova la funzione non è definita, o i numeri non bastano"); return -1; }
    return 1;
}

/* Ritorna 1 se tree è un nodo che node_domain() sostituisce: un arcoseno,
 * un arcocoseno, il logaritmo di un valore assoluto. */
static int node_special(const Node *tree) {
    if (tree->kind != N_CALL) return 0;
    if (tree->op == FN_ARCSIN || tree->op == FN_ARCCOS) return 1;
    return (tree->op == FN_LN || tree->op == FN_LOG) && tree->a->kind == N_CALL && tree->a->op == FN_ABS;
}

/* Ritorna 1 se in tree compare un nodo che node_domain() sostituisce. */
static int node_has_special(const Node *tree) {
    return tree && (node_special(tree) || node_has_special(tree->a) || node_has_special(tree->b) || node_has_special(tree->c));
}

/* Ritorna un'espressione che ha un valore esattamente dove lo ha f, fatta di
 * ciò che la valutazione e la tabella dei segni sanno calcolare: f stessa,
 * con ogni arcoseno e arcocoseno di u sostituito da u + 0 sqrt(1 - u^2), che
 * come loro è definito dove u lo è e |u| <= 1, e ogni ln|u| (log_b |u|) da
 * 1 / u (1 / (u ln b)), definito come lui dove u non è zero (e b > 0 e
 * diverso da 1). Il valore è un altro: conta solo dove c'è. Un nodo così
 * dentro l'argomento di un altro resta com'è, perché lì servirebbe proprio
 * il suo valore, e la valutazione lo rifiuterà. */
static Node *node_domain(const Node *f) {
    if (!f || !node_has_special(f)) return (Node *)f;
    if (node_special(f) && f->op == FN_LN && !node_has_special(f->a->a)) return node_new(N_DIV, node_num(1), f->a->a);
    if (node_special(f) && f->op == FN_LOG && !node_has_special(f->a->a) && !node_has_special(f->b))
        return node_new(N_DIV, node_num(1), node_new(N_MUL, f->a->a, node_call(FN_LN, f->b, NULL)));
    if (node_special(f) && f->op != FN_LN && f->op != FN_LOG && !node_has_special(f->a)) {
        Node *radicand = node_new(N_SUB, node_num(1), node_new(N_POW, f->a, node_num(2)));
        return node_new(N_ADD, f->a, node_new(N_MUL, node_num(0), node_call(FN_ROOT, radicand, node_num(2))));
    }
    return node_rebuilt(f, node_domain(f->a), node_domain(f->b), node_domain(f->c));
}

/* 27j. IL SEGNO DI DERIVATA DENTRO UN'ESPRESSIONE
 *
 * A che cosa serve. Lo studio di una funzione si scrive con la sua
 * derivata: f cresce dove f' > 0, è convessa dove f'' > 0. Così
 *
 *     \{x \in \mathbb{R} \mid \frac{d}{dx}\left( x e^{x} \right) > 0\}
 *
 * chiede dove x e^x cresce, e la risposta la dà la tabella dei segni (18p),
 * con il suo metodo e i suoi controlli, se al posto del segno di derivata
 * c'è la derivata. Il lettore fa del segno un nodo N_DERIV (9d); qui, subito
 * dopo il parsing e prima di ogni conto, ogni nodo così diventa la sua
 * derivata. Chi non ci riesce lascia l'errore, e l'enunciato è NON
 * SUPPORTATO: un segno di derivata non si legge mai come altro.
 *
 * Che cosa prende il posto del segno. Siano d_1, ..., d_k le derivate di g
 * date dalle regole (27c-27g), e G un'espressione definita dove g lo è
 * (node_domain(): g stessa, salvo arcoseni, arcocoseni e ln|u|, che la
 * valutazione o la tabella dei segni non sanno calcolare). Il segno
 * \frac{d^k}{dx^k}(g) diventa
 *
 *     d_k + 0 (G + d_1 + ... + d_{k-1}).
 *
 * Vale d_k, ma ha un valore solo nell'insieme E dei punti in cui g, d_1,
 * ..., d_k ce l'hanno tutte: la valutazione annota le condizioni di
 * esistenza (denominatori, radicandi, argomenti dei logaritmi) di ogni
 * pezzo, anche di quello moltiplicato per zero, e gli intervalli lì non
 * danno un valore. È così che un punto in cui g non è definita non entra
 * nella risposta anche se d_k vi ha un valore: in \{x \mid (\ln x)' < 0\} la
 * derivata 1/x è negativa per x < 0, ma lì ln x non c'è, e la risposta è
 * vuota.
 *
 * Perché in E la derivata k-esima esiste e vale d_k. Per k = 1: ogni regola
 * dà una formula che ha un valore solo dove la funzione che deriva è
 * derivabile (vedi "Dove valgono le formule", in testa al capitolo), e lì
 * vale la sua derivata, per la regola della catena e quelle del prodotto e
 * del quoziente. Inoltre E è aperto: le condizioni di g che non sono strette
 * (un radicando non negativo, |u| <= 1 sotto un arcoseno) in d_1 diventano
 * strette, perché la derivata divide per il radicando, o per sqrt(1 - u^2).
 * Allora intorno a ogni punto di E la derivata prima esiste ed è d_1, e la
 * derivata di d_1 in quel punto è la seconda: lo stesso ragionamento, ordine
 * dopo ordine.
 *
 * Che cosa resta da controllare. Il contrario non vale: in un punto fuori
 * da E, dove però g è definita, la derivata può esistere. x|x| ha derivata
 * 2|x|, anche in 0, ma la regola del valore assoluto dà x^2/|x| + |x|, che in
 * 0 non ha valore. Lì l'espansione non dice nulla, e la tabella dei segni,
 * che conta come falso un confronto senza valore, direbbe il falso: se ne
 * occupa 27l.
 *
 * Il controllo indipendente. Le derivate d_1, ..., d_k di ogni segno vengono
 * confrontate con la serie di Taylor di g nei punti di prova, come in 27h
 * (derivatives_confirmed()): una smentita è un errore del programma, e ogni
 * ordine deve essere confermato in almeno un punto.
 */

/* Le espansioni dell'enunciato in corso, per il controllo di 27l: per ogni
 * segno, l'espressione definita dove lo è la funzione (G) e ciò che ha
 * preso il posto del segno. Valgono finché l'arena non viene svuotata. */
#define MAX_EXPANDED 8
static const Node *expanded_function[MAX_EXPANDED], *expanded_value[MAX_EXPANDED];

/* Vedi la dichiarazione dopo l'inclusione di parser.c. I segni annidati,
 * \frac{d}{dx}(\frac{d}{dx}(g)), si espandono dal più interno: la funzione
 * del più esterno è già un'espansione, con le sue condizioni. */
static Node *derivatives_expanded(Node *tree) {
    if (!tree || failure) return tree;
    Node *a = derivatives_expanded(tree->a), *b = derivatives_expanded(tree->b), *c = derivatives_expanded(tree->c);
    if (failure || tree->kind != N_DERIV) return failure ? tree : node_rebuilt(tree, a, b, c);
    int x = tree->name, order = (int)tree->value;
    if (order > MAX_DERIVATIVE_BASE) { fail("l'ordine di una derivata dentro un'espressione deve essere al più 4"); return tree; }
    if (derivative_signs == MAX_EXPANDED) { fail("troppi segni di derivata in un enunciato"); return tree; }

    /* Le derivate, confermate con i numeri (27h). */
    Node *direct[MAX_JET + 1] = {a};
    DerivativeCheck check;
    if (derivatives_confirmed(direct, order, x, &check) < 1) return tree;

    /* La derivata, con le condizioni di esistenza della funzione e delle
     * derivate prima di lei. */
    Node *domain = node_domain(a), *guard = domain;
    int closed = 1;
    for (int k = 1; k < order; k++) guard = node_new(N_ADD, guard, direct[k]);
    Node *value = node_fold(node_new(N_ADD, direct[order], node_new(N_MUL, node_num(0), guard)), &closed);
    expanded_function[derivative_signs] = domain;
    expanded_value[derivative_signs++] = value;
    return value;
}

/* Vedi la dichiarazione dopo l'inclusione di parser.c. */
static void formula_derivatives_expanded(Formula *f) {
    if (!f || failure) return;
    f->left = derivatives_expanded(f->left);
    f->right = derivatives_expanded(f->right);
    formula_derivatives_expanded(f->a);
    formula_derivatives_expanded(f->b);
}

/* Ritorna tree con le scritture del numero e che la valutazione non
 * riconosce sostituite dal loro valore: ln e = 1, log_b e = 1 / ln b,
 * log_e u = ln u. Sono identità dove i due membri sono definiti (b > 0 e
 * diverso da 1, u > 0), e in questo capitolo la lettera e è il numero di
 * Nepero; la valutazione, che serve anche agli enunciati in cui e è una
 * lettera qualsiasi, non le applica da sé. I libri scrivono così le
 * derivate dei logaritmi: (\log_{\frac{2}{3}} x)' = \frac{\log_{\frac{2}{3}} e}{x}. */
static Node *node_euler(const Node *tree) {
    if (!tree) return NULL;
    Node *a = node_euler(tree->a), *b = node_euler(tree->b);
    int euler_a = a && a->kind == N_VAR && a->name == 'e', euler_b = b && b->kind == N_VAR && b->name == 'e';
    if (tree->kind == N_CALL && tree->op == FN_LN && euler_a) return node_num(1);
    if (tree->kind == N_CALL && tree->op == FN_LOG && euler_b) return node_call(FN_LN, a, NULL);
    if (tree->kind == N_CALL && tree->op == FN_LOG && euler_a) return node_new(N_DIV, node_num(1), node_call(FN_LN, b, NULL));
    return node_rebuilt(tree, a, b, node_euler(tree->c));
}

/* 27a, il conto. Ritorna 1 se left - right si riduce a zero con l'algebra
 * esatta, con la lettera order (0 se non c'è) uguale a base, dove i due
 * membri sono definiti; x è la variabile, che se è la lettera e non è il
 * numero di Nepero. left è una derivata della funzione function, che non
 * entra nel conto ma ne dà i fatti del dominio (12d): dove la derivata
 * esiste, la funzione è definita.
 *
 * I valori assoluti. La valutazione non sa calcolare |u| di
 * un'espressione: |u| vale u dove u >= 0 e -u dove u <= 0. Si fa allora il
 * conto per ogni scelta dei segni (u oppure -u per ogni valore assoluto),
 * con lo stesso meccanismo della tabella dei segni (abs_pattern), e si
 * chiede che la differenza si riduca a zero in ognuna. Basta: in ogni punto
 * x ogni |u| vale u(x) oppure -u(x), quindi la differenza in x è quella di
 * una delle scelte, che è zero. Due valori assoluti scritti allo stesso modo
 * sono uno solo (abs_collect()); con argomenti diversi si provano tutte le
 * combinazioni, anche quelle che in nessun punto si verificano: si dimostra
 * qualcosa in meno, mai di più. Dentro una scelta il conto riguarda solo i
 * punti in cui ogni u ha il segno scelto, e quel segno è un fatto (11q): con
 * \cos x >= 0, \sqrt{1 - \sin^2 x} = \cos x.
 *
 * Il dominio. Il test è quello dove i due membri sono definiti (12d): i
 * radicandi delle radici di indice pari e gli argomenti dei logaritmi sono
 * fatti, e \sqrt[3]{x} accanto a \sqrt{x} è x^{1/3} come (\sqrt[6]{x})^2. Si
 * può perché la derivata si afferma solo lì, e che lì ci sia almeno un punto
 * lo dicono i controlli con i numeri, che chi chiama ha già fatto.
 *
 * Le potenze che la valutazione non sa calcolare. e^{\sin x} non ha una
 * forma esatta: il seno è scritto con gli esponenziali complessi, e
 * l'esponente risulta complesso. Ma se la stessa potenza T, con x
 * all'esponente, compare in tutti e due i membri, al suo posto si può
 * mettere una lettera nuova t: se la differenza si riduce a zero per ogni
 * valore di t, si riduce a zero anche per t = T(x). Si dimostra di più di
 * quanto serve, quindi niente di falso. Lo si fa solo con le potenze che
 * il conto non sa fare: delle altre si perderebbero le relazioni con il
 * resto, come e^{2x} = (e^{x})^2. */
static Node *node_swapped(const Node *tree, const Node *pattern, int letter) {
    if (!tree) return NULL;
    if (node_equal(tree, pattern)) {
        Node *variable = node_new(N_VAR, NULL, NULL);
        variable->name = letter;
        return variable;
    }
    return node_rebuilt(tree, node_swapped(tree->a, pattern, letter), node_swapped(tree->b, pattern, letter), node_swapped(tree->c, pattern, letter));
}

/* Ritorna 1 se in tree compare un sotto-albero scritto come pattern. */
static int node_occurs(const Node *tree, const Node *pattern) {
    return tree && (node_equal(tree, pattern) || node_occurs(tree->a, pattern) || node_occurs(tree->b, pattern) || node_occurs(tree->c, pattern));
}

/* Ritorna una potenza con x all'esponente che compare in tree e in other, e
 * che la valutazione non sa calcolare; NULL se non ce n'è. */
static const Node *shared_power(const Node *tree, const Node *other, int x) {
    if (!tree) return NULL;
    if (tree->kind == N_POW && node_has_variable(tree->b, x) && node_occurs(other, tree)) {
        const char *was = failure;
        Scratch mark = scratch_mark();
        failure = NULL;
        eval(tree);
        int unknown = failure != NULL;
        failure = was;
        scratch_drop(mark);
        if (unknown) return tree;
    }
    const Node *found = shared_power(tree->a, other, x);
    if (!found) found = shared_power(tree->b, other, x);
    return found ? found : shared_power(tree->c, other, x);
}

static int derivative_identity(const Node *left, const Node *right, const Node *function, int order, long long base, int x) {
    Statement s = {(Node *)left, (Node *)right, REL_EQ};
    const Node *source = function;
    int holds = 1, kept = induction_var;
    if (x != 'e') { s.lhs = node_euler(left); s.rhs = node_euler(right); source = node_euler(function); }

    /* Le potenze in comune che il conto non sa fare, una lettera nuova
     * per ognuna: le lettere maiuscole, che qui non nominano nulla. La
     * funzione, che dà solo i fatti del dominio, cambia allo stesso modo, e
     * nemmeno lei deve usare la lettera: due quantità diverse con lo stesso
     * nome darebbero un fatto falso. */
    for (int letter = 'A', tries = 0; letter <= 'Z' && tries < 4; letter++) {
        if (node_uses_letter(s.lhs, letter) || node_uses_letter(s.rhs, letter) || node_uses_letter(source, letter)) continue;
        const Node *power = shared_power(s.lhs, s.rhs, x);
        if (!power) break;
        s.lhs = node_swapped(s.lhs, power, letter);
        s.rhs = node_swapped(s.rhs, power, letter);
        source = node_swapped(source, power, letter);
        tries++;
    }
    abs_count = 0;
    abs_collect(s.lhs);
    abs_collect(s.rhs);
    int count = abs_count, points = point_count;
    induction_var = order;

    /* Nessun parametro con un valore (13e): l'identità deve valere per ogni
     * valore delle altre lettere, non per quelli di un conto precedente. Il
     * test di annullamento è quello dove i due membri sono definiti (12d):
     * l'uguaglianza si afferma solo lì, e in ogni caso dei valori assoluti
     * il segno scelto per ognuno è un fatto (11q). */
    point_count = 0;
    for (abs_pattern = 0; holds && !failure && abs_pattern < 1u << count; abs_pattern++) {
        abs_count = count;
        holds = vanishes_where_defined(&s, source, rat_int(base));
    }
    abs_count = 0;
    abs_pattern = 0;
    induction_var = kept;
    point_count = points;
    return holds && !failure;
}

/* 27a, la rilettura con i numeri. Ritorna 1 se le formule scritte nei pezzi
 * a e b della dimostrazione, rilette dal testo con il lettore del programma,
 * hanno lo stesso valore, con gli intervalli (27h), in almeno uno dei punti
 * di prova, e non sono di sicuro diverse in nessuno. È la rilettura di
 * riserva per ciò che 13g non sa calcolare con i numeri esatti: e^{\sin x}
 * in un punto razionale non è un numero che il conto esatto sappia
 * scrivere. Come in 13g, chi scrive e chi rilegge non hanno nulla in
 * comune: la scrittura parte dagli alberi, il controllo dai caratteri. */
static int reread_numbers(Span a, Span b, int x) {
    char text[2][MAX_FORMULA];
    Node *tree[2];
    size_t kept = arena_used;
    int agreed = 0, sound = 1;
    for (int i = 0; i < 2 && sound; i++) {
        Span piece = i ? b : a;
        size_t length = piece.to - piece.from;
        sound = length < MAX_FORMULA;
        if (!sound) break;
        memcpy(text[i], proof_text + piece.from, length);
        text[i][length] = '\0';
        tree[i] = parse_expression(text[i]);
        sound = !syntax_error && !failure;
        if (sound) tree[i] = sample_tree(tree[i], x, 0, 0);
    }
    for (int p = 0; p < DERIVATIVE_POINTS && sound && !failure; p++) {
        Range at = range_ratio(derivative_points[p].num, derivative_points[p].den);
        int agreement = numbers_agree(sample_value(tree[0], x, at), sample_value(tree[1], x, at));
        if (agreement < 0) sound = 0;
        agreed += agreement > 0;
    }
    sound = sound && !failure && agreed > 0;
    syntax_error = failure = NULL;
    arena_used = kept;
    return sound;
}

/* Ritorna 1 se in tree compare una potenza con x sia nella base sia
 * nell'esponente: il verdetto deve dire che la si intende e^{v ln u}. */
static int node_has_tower(const Node *tree, int x) {
    if (!tree) return 0;
    if (tree->kind == N_POW && node_has_variable(tree->a, x) && node_has_variable(tree->b, x)) return 1;
    return node_has_tower(tree->a, x) || node_has_tower(tree->b, x) || node_has_tower(tree->c, x);
}

/* 27m. IL CERTIFICATO DI UNA DERIVATA (E DI UNA PRIMITIVA)
 *
 * A che cosa serve. Le regole di derivazione sono scritte una volta sola, in
 * derive(), e i controlli di 27h e 27i sono con i numeri, in pochi punti. Il
 * certificato porta a checker.c (capitolo 13) la funzione e la derivata
 * affermata, e il verificatore deriva da sé, con regole sue, e decide con la
 * sua algebra esatta se la differenza è zero. Lo stesso per una primitiva
 * (la sua derivata deve essere la funzione integranda) e per un integrale
 * definito (capitolo 30, 30cert). Sta qui, prima di 27k, perché 27k e
 * prove_derivative() lo usano.
 *
 * Che cosa si scrive. Il tipo, la variabile, l'ordine ("order 2", oppure
 * "order n base 1" per una derivata n-esima), le espressioni come sono negli
 * alberi dell'enunciato (o della risposta riletta dal testo, per una
 * richiesta), con le parole di cert_real; per un integrale anche gli estremi
 * e il valore. Poi, come suggerimenti, i fattori in cui il motore ha
 * scomposto gli argomenti dei logaritmi (le basi degli atomi LN dell'ultimo
 * conto), quelli che la notazione sa scrivere: un suggerimento sbagliato non
 * divide nulla e non ha effetto.
 *
 * Che cosa non si scrive: arcoseno e arcocoseno e le successioni del
 * vocabolario. Allora il certificato manca, e il verdetto dice perché.
 *
 * Le risposte. Accettato: il verdetto porta il certificato, che dimostra il
 * teorema in testa al capitolo 13 di checker.c: la derivata vale dove la
 * funzione è regolare (definita, con i radicandi e gli argomenti dei valori
 * assoluti diversi da zero) e la formula è definita. Se la funzione ha radici, potenze con un esponente
 * non intero o valori assoluti, il verdetto lo dice in una nota: nei punti in
 * cui un radicando, o l'argomento di un valore assoluto, vale zero il
 * certificato non dice nulla. Respinto: il motore e il
 * verificatore non sono d'accordo, quindi nel dubbio non è dimostrato, e il
 * passo conta tra quelli che non hanno superato il controllo. Non
 * controllabile: il verdetto resta, e dice perché il certificato manca. */

/* Ritorna 1 se in tree compare una radice, una potenza con l'esponente senza
 * x che non è un intero scritto, o un valore assoluto che non è tutto
 * l'argomento di un logaritmo: nei punti in cui la loro base, o il loro
 * argomento, vale zero il certificato non dice nulla (vedi sopra). */
static int node_has_root(const Node *tree, int x) {
    if (!tree) return 0;
    if (tree->kind == N_CALL && (tree->op == FN_ROOT || tree->op == FN_ABS)) return 1;
    if (tree->kind == N_CALL && (tree->op == FN_LN || tree->op == FN_LOG) && tree->a->kind == N_CALL && tree->a->op == FN_ABS)
        return node_has_root(tree->a->a, x) || node_has_root(tree->b, x);
    if (tree->kind == N_POW && !node_has_variable(tree->b, x) && tree->b->kind != N_NUM && !(tree->b->kind == N_NEG && tree->b->a->kind == N_NUM)) return 1;
    return node_has_root(tree->a, x) || node_has_root(tree->b, x) || node_has_root(tree->c, x);
}

/* Scrive in certificate_text il certificato di tipo kind ("derivative",
 * "antiderivative" o "integral") nella variabile x: order è il testo della
 * voce order (solo per una derivata, altrimenti NULL), function la funzione
 * da derivare o la primitiva, claim la derivata affermata o la funzione
 * integranda, lower, upper e value gli estremi e il valore di un integrale
 * (NULL altrimenti). Ritorna NULL, oppure il motivo per cui il certificato
 * non c'è. */
static const char *calculus_certificate(const char *kind, int x, const char *order, const Node *function, const Node *claim,
                                        const Node *lower, const Node *upper, const Node *value) {
    certificate_length = 0;
    certificate_broken = 0;
    certificate_sequences = 0;
    if (x >= 128 || !isalpha(x)) return "la variabile non è una lettera";
    cert_real = x;
    cert_add("certificate %s\nvariable %c", kind, x);
    if (order) cert_add("\norder %s", order);
    if (lower) {
        cert_add("\nlower ");
        cert_node(lower);
        cert_add("\nupper ");
        cert_node(upper);
    }
    cert_add(order ? "\nfunction " : "\nintegrand ");
    cert_node(order ? function : claim);
    cert_add(order ? "\nderivative " : "\nprimitive ");
    cert_node(order ? claim : function);
    if (value) {
        cert_add("\nvalue ");
        cert_node(value);
    }
    const char *why = certificate_broken || certificate_sequences
                          ? "la notazione dei certificati delle derivate non ha arcoseno, arcocoseno e le successioni, o il testo è troppo lungo"
                          : NULL;

    /* I suggerimenti per i logaritmi: un fattore che non si sa scrivere si
     * toglie, e con lui il guasto che ha segnato. */
    for (int i = 0, written = 0; i < atom_count && written < MAX_BRICKS && !why; i++) {
        size_t before = certificate_length;
        if (atoms[i].kind != ATOM_LN || atoms[i].base == BASE_PRIME) continue;
        cert_add("\nbrick ");
        cert_base(&atoms[i]);
        if (certificate_broken) {
            certificate_length = before;
            certificate_text[before] = '\0';
            certificate_broken = 0;
        } else {
            written++;
        }
    }
    cert_add("\nend\n");
    cert_real = 0;
    if (!why && certificate_broken) why = "il certificato è troppo lungo";
    return why;
}

/* Fa ricontrollare a checker.c il certificato appena scritto da
 * calculus_certificate(), che ha risposto why, e aggiorna *verdict, un
 * verdetto DIMOSTRATO o RISOLTO: vedi le risposte in testa a 27m. Se il
 * certificato è accettato e la funzione function (nella variabile x) ha
 * radici o valori assoluti, la nota del verdetto lo dice, dopo quella che
 * c'era già. Nel motivo i
 * due punti diventano virgole: in una riga RISOLTO dopo il primo ": " viene
 * la risposta, e gli script di tools/fuzz/ la cercano lì. */
static void calculus_certify(Verdict *verdict, const char *why, const Node *function, int x) {
    static char problem[512], note[512];
    const char *text = certificate_text;
    if (!why) {
        CkAnswer answer = ck_check(&text, &why);
        if (answer == CK_ACCEPTED) {
            verdict->certificate = certificate_text;
            verdict->reason = NULL;
            if (node_has_root(function, x)) {
                snprintf(note, sizeof note, "%s%sil certificato non copre i punti in cui la base di una radice o di una potenza con l'esponente non "
                         "intero, o l'argomento di un valore assoluto, vale zero", verdict->note ? verdict->note : "", verdict->note ? "; " : "");
                verdict->note = note;
            }
            return;
        }
        if (answer == CK_REJECTED) {
            unjustified_steps++;
            snprintf(problem, sizeof problem, "il verificatore indipendente ha respinto il certificato, %s", why);
            *verdict = (Verdict){NOT_PROVED, 0, 0, 0, problem, NULL, NULL, NULL, NULL, NULL};
            return;
        }
        snprintf(problem, sizeof problem, "il verificatore non sa controllarlo, %s", why);
    } else {
        snprintf(problem, sizeof problem, "%s", why);
    }
    for (char *colon = problem; (colon = strchr(colon, ':')) != NULL;) *colon = ',';
    verdict->reason = problem;
}

/* 27k. CALCOLARE UNA DERIVATA
 *
 * \frac{d}{dx}\left( x^{2} \tan x \right), senza il segno di uguale, chiede
 * la derivata. La risposta è RISOLTO, con la derivata scritta:
 *
 *   27k-1. la derivata di ordine k, con le regole, confermata con la serie
 *          di Taylor in almeno un punto per ogni ordine (27h);
 *   27k-2. l'albero delle regole scritto come lo scriverebbe chi le ha
 *          appena applicate: senza fattori 1, addendi 0, esponenti 1 e segni
 *          doppi, con i conti tra interi fatti e il numero davanti al
 *          prodotto (node_tidy()): 2x \tan x + \frac{x^{2}}{\cos^{2} x};
 *   27k-3. il testo scritto si rilegge con il lettore del programma, come
 *          se l'avesse scritto l'utente, e il riletto deve avere lo stesso
 *          valore della derivata delle regole per due strade: con l'algebra
 *          esatta, dove sono definite (27a), e con i numeri, contro la
 *          derivata letta dalla serie di Taylor della funzione in tutti i
 *          punti di prova in cui le due si calcolano, almeno uno. Se non è
 *          così la risposta non si consegna.
 *
 * Perché basta una semplificazione leggera. La risposta deve essere giusta
 * e leggibile, non nella forma del libro: forme equivalenti sono infinite,
 * e confrontarle è compito di chi controlla (27a), non di chi scrive. Un
 * semplificatore completo (fattori comuni, identità goniometriche, forme
 * canoniche) sarebbe molto codice, che sbaglia in modi suoi e andrebbe
 * comunque ricontrollato; quello leggero fa solo passi che si vedono a
 * occhio, e ognuno lascia l'espressione definita esattamente dove lo era.
 *
 * Dove vale la risposta. Dove la funzione, la formula scritta e, per un
 * ordine più alto, le derivate prima di lei sono definite (27j): la nota
 * del verdetto lo dice, e per u^v aggiunge che la base deve essere
 * positiva. Dove la formula non ha valore la risposta non dice nulla, nemmeno
 * che la derivata non esiste (27l).
 */

/* Ritorna 1 e mette in *value il numero, se tree è un numero intero scritto. */
static int node_is_number(const Node *tree, long long *value) {
    if (tree->kind != N_NUM) return 0;
    *value = tree->value;
    return 1;
}

/* Se tree è un intero, o un prodotto il cui primo fattore da sinistra è un
 * intero, mette l'intero in *number e il resto del prodotto in *rest (NULL
 * se tree è solo il numero) e ritorna 1. I prodotti scritti da node_tidy()
 * hanno le parentesi a sinistra: (2 u) v. */
static int node_coefficient(Node *tree, long long *number, Node **rest) {
    Node *inner;
    if (node_is_number(tree, number)) { *rest = NULL; return 1; }
    if (tree->kind != N_MUL || !node_coefficient(tree->a, number, &inner)) return 0;
    *rest = inner ? node_new(N_MUL, inner, tree->b) : tree->b;
    return 1;
}

/* Ritorna 1 se tree ha un valore per ogni valore reale delle sue lettere:
 * numeri, lettere, somme, prodotti, potenze con esponente naturale scritto
 * come numero, seno, coseno, arcotangente, arcocotangente e valore assoluto
 * di espressioni così. È ciò che permette a node_tidy() di scrivere 0 al
 * posto di 0 u senza cambiare dove l'espressione è definita. Le potenze di
 * e non ci sono: se e fosse la variabile, e^{1/2} non sarebbe definita
 * ovunque. */
static int node_total(const Node *tree) {
    switch (tree->kind) {
    case N_NUM: case N_VAR: return 1;
    case N_NEG: return node_total(tree->a);
    case N_ADD: case N_SUB: case N_MUL: return node_total(tree->a) && node_total(tree->b);
    case N_POW:
        return tree->b->kind == N_NUM && tree->b->value >= 0 && node_total(tree->a);
    case N_CALL:
        return (tree->op == FN_SIN || tree->op == FN_COS || tree->op == FN_ARCTAN || tree->op == FN_ARCCOT || tree->op == FN_ABS) && node_total(tree->a);
    default: return 0;
    }
}

/* Ritorna il prodotto di number per rest (rest NULL: il solo numero). */
static Node *node_scaled(long long number, Node *rest) {
    if (!rest) return node_num(number);
    return number == 1 ? rest : node_new(N_MUL, node_num(number), rest);
}

/* 27k-2. Ritorna una copia di tree senza ciò che un libro non scriverebbe
 * (vedi sopra). Ogni passo conserva le condizioni di esistenza: per questo
 * 0 u diventa 0 solo se u ha un valore ovunque (node_total()), e a / (b / c)
 * resta com'è, perché a c / b perderebbe la condizione c diverso da zero. Le
 * altre riscritture spostano divisioni, segni e parentesi senza togliere
 * nessun denominatore: (a / b) c = a c / b, (a / b) / c = a / (b c),
 * a (b c) = (a b) c, -(-a) = a, a - (b + c) = a - b - c, e un numero in
 * comune tra numeratore e denominatore si semplifica, (6 u) / (4 v) =
 * (3 u) / (2 v). */
static Node *node_tidy(const Node *tree) {
    long long p, q, product, top, bottom;
    Node *above, *below;
    int closed = 1;
    if (!tree || tree->kind == N_NUM || tree->kind == N_VAR) return (Node *)tree;
    Node *folded = node_fold(tree, &closed);
    if (folded->kind == N_NUM) return folded;
    Node *a = node_tidy(folded->a), *b = node_tidy(folded->b);
    int a_number = a && node_is_number(a, &p), b_number = b && node_is_number(b, &q);
    switch (folded->kind) {
    case N_NEG:
        if (a->kind == N_NEG) return a->a;
        if (a_number) return node_num(-p);
        break;
    case N_ADD: case N_SUB: {
        NodeKind other = folded->kind == N_ADD ? N_SUB : N_ADD;
        if (b_number && q == 0) return a;
        if (a_number && p == 0) return folded->kind == N_ADD ? b : node_tidy(node_new(N_NEG, b, NULL));
        if (b->kind == N_NEG) return node_new(other, a, b->a);
        if (b_number && q < 0) return node_new(other, a, node_num(-q));
        if (folded->kind == N_SUB && (b->kind == N_ADD || b->kind == N_SUB))
            return node_tidy(node_new(b->kind == N_ADD ? N_SUB : N_ADD, node_new(N_SUB, a, b->a), b->b));
        break;
    }
    case N_MUL:
        if (a_number && p == 1) return b;
        if (b_number && q == 1) return a;
        if ((a_number && p == 0 && node_total(b)) || (b_number && q == 0 && node_total(a))) return node_num(0);
        if (b_number && !a_number) return node_tidy(node_new(N_MUL, b, a));
        if (a_number && p < 0) return node_new(N_NEG, node_tidy(node_new(N_MUL, node_num(-p), b)), NULL);
        if (a->kind == N_NEG) return node_new(N_NEG, node_tidy(node_new(N_MUL, a->a, b)), NULL);
        if (b->kind == N_NEG) return node_new(N_NEG, node_tidy(node_new(N_MUL, a, b->a)), NULL);
        if (a_number && b->kind == N_MUL && node_is_number(b->a, &q) && !__builtin_mul_overflow(p, q, &product))
            return node_tidy(node_new(N_MUL, node_num(product), b->b));
        if (b->kind == N_DIV) return node_tidy(node_new(N_DIV, node_new(N_MUL, a, b->a), b->b));
        if (a->kind == N_DIV) return node_tidy(node_new(N_DIV, node_new(N_MUL, a->a, b), a->b));
        if (b->kind == N_MUL) return node_tidy(node_new(N_MUL, node_new(N_MUL, a, b->a), b->b));
        break;
    case N_DIV:
        if (b_number && q == 1) return a;
        if (a->kind == N_NEG) return node_new(N_NEG, node_tidy(node_new(N_DIV, a->a, b)), NULL);
        if (b->kind == N_NEG) return node_new(N_NEG, node_tidy(node_new(N_DIV, a, b->a)), NULL);
        if (a->kind == N_DIV) return node_tidy(node_new(N_DIV, a->a, node_new(N_MUL, a->b, b)));
        if (node_coefficient(a, &top, &above) && node_coefficient(b, &bottom, &below) && top && bottom) {
            long long common = (long long)gcd128(top, bottom);
            if (bottom < 0) common = -common;
            if (common != 1) return node_tidy(node_new(N_DIV, node_scaled(top / common, above), node_scaled(bottom / common, below)));
        }
        break;
    case N_POW:
        if (b_number && q == 1) return a;
        break;
    default:
        break;
    }
    return node_rebuilt(folded, a, b, folded->c);
}

/* 27k. Risolve la richiesta di calcolare la derivata di ordine order di f
 * rispetto a x, come descritto sopra, e ne ritorna il verdetto: verdict è
 * quello che prove_derivative() ha già preparato. */
static Verdict solve_derivative(Node *f, int x, int order, Verdict verdict) {
    static char answer[MAX_FORMULA], note[200];
    Node *direct[MAX_JET + 1] = {f};
    DerivativeCheck check;
    verdict.variable = 0;

    /* 27k-1. */
    int confirmed = derivatives_confirmed(direct, order, x, &check);
    if (confirmed < 1) {
        verdict.outcome = confirmed ? NOT_PROVED : UNSUPPORTED;
        verdict.reason = failure;
        return verdict;
    }

    /* 27k-2: la derivata scritta, nella dimostrazione e nella risposta. */
    proof_add("\\textbf{Solution.} By the rules of differentiation, the derivative of order $%d$ with respect to $%c$ is $", order, x);
    size_t from = proof_length;
    put_node(node_tidy(direct[order]), 0);
    size_t length = proof_length - from;
    proof_add("$.\n\n");
    if (failure || length >= sizeof answer || proof_length >= PROOF_BYTES - 1) {
        verdict.outcome = NOT_PROVED;
        verdict.reason = failure ? failure : "la derivata è troppo lunga per essere scritta e riletta";
        return verdict;
    }
    memcpy(answer, proof_text + from, length);
    answer[length] = '\0';

    /* 27k-3: la rilettura, e i due controlli. Una smentita dei numeri è un
     * errore del programma, nello scrivere o nel rileggere; un conto che non
     * riesce lascia solo la risposta senza conferma. */
    Node *reread = parse_expression(answer);
    int agreed = 0, contradicted = 0, readable = !syntax_error && !failure;
    Node *sampled = readable ? sample_tree(reread, x, 0, 0) : NULL;
    for (int p = 0; p < DERIVATIVE_POINTS && readable; p++) {
        Range claimed = sample_value(sampled, x, range_ratio(derivative_points[p].num, derivative_points[p].den));
        int agreement = numbers_agree(claimed, check.taylor[order][p]);
        contradicted |= agreement < 0;
        agreed += agreement > 0;
    }
    int sound = readable && !contradicted && agreed && !failure && derivative_identity(direct[order], reread, f, 0, 0, x);
    if (!sound) {
        if (contradicted || !readable) unjustified_steps++;
        failure = syntax_error = NULL;
        verdict.outcome = NOT_PROVED;
        verdict.reason = !readable      ? "la derivata scritta non si rilegge con il lettore del programma"
                         : contradicted ? "la derivata scritta, riletta dal testo, è smentita dalla serie di Taylor della funzione"
                                        : "non riesco a confermare la derivata scritta, riletta dal testo, con l'algebra esatta e con la serie di Taylor";
        return verdict;
    }
    proof_add("\\textbf{Check.} This formula, read back as text, has the value of the derivative given by the rules, by exact algebra "
              "where both are defined, and of the derivative read from the Taylor series of the function, computed with interval "
              "arithmetic at %d of the sample points. $\\Box$", agreed);

    /* Il verdetto, con la nota su dove vale. */
    snprintf(note, sizeof note, "%s%s", order == 1 ? "dove la funzione e la derivata sono definite" : "dove la funzione e le derivate fino a questa sono definite",
             node_has_tower(f, x) ? "; u^v con la variabile nella base e nell'esponente è e^{v \\ln u}, con u > 0" : "");
    verdict.outcome = SOLVED;
    verdict.method = "con le regole di derivazione";
    verdict.detail = answer;
    verdict.note = note;
    verdict.proof = proof_text;

    /* 27m. Il certificato dice ciò che dice il testo scritto, riletto. */
    char order_text[24];
    snprintf(order_text, sizeof order_text, "%d", order);
    calculus_certify(&verdict, calculus_certificate("derivative", x, order_text, f, reread, NULL, NULL, NULL), f, x);
    return verdict;
}

/* Prova a dimostrare l'enunciato su una derivata scritto in formula, con il
 * teorema in testa al capitolo. variable, has_base e base come per
 * prove_by_induction(); senza caso base una derivata n-esima parte da
 * n = 0, la funzione stessa. Se l'ordine è scritto come numero non c'è
 * induzione: basta 27a in quell'ordine, e il verdetto non ha una variabile
 * di induzione. Se formula non è scritta come una derivata il verdetto è
 * NON SUPPORTATO con il motivo NOT_A_DERIVATIVE.
 *
 * Il verdetto DIMOSTRATO porta il certificato di 27m, se il verificatore lo
 * accetta; altrimenti dice perché manca, in reason, e se il verificatore lo
 * respinge il verdetto è NON DIMOSTRATO. Svuota l'arena e la tabella degli
 * atomi: i risultati di chiamate precedenti non sono più validi. */
static Verdict prove_derivative(const char *formula, int variable, int has_base, long long base) {
    static char text[320];
    Verdict verdict = {UNSUPPORTED, variable, has_base ? base : 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    DerivativeStatement statement;

    /* Ripartenza da zero per il nuovo enunciato, e parsing. */
    proof_reset();
    arena_used = arena_keep;
    atom_count = base_poly_count = atan_count = 0;
    failure = NULL;
    if (!parse_derivative_statement(formula, &statement)) { verdict.reason = NOT_A_DERIVATIVE; return verdict; }
    int x = statement.variable, fixed = !statement.order;
    Node *f = statement.function, *g = statement.formula;
    if (failure) { verdict.reason = failure; return verdict; }

    /* 27j. I segni di derivata dentro la funzione o la formula. */
    derivative_signs = 0;
    f = derivatives_expanded(f);
    g = derivatives_expanded(g);
    if (failure) { verdict.reason = failure; return verdict; }

    /* 27k. Senza la formula è una richiesta: calcolare la derivata. */
    if (!g) {
        if (!fixed) verdict.reason = "si calcola una derivata il cui ordine è scritto come numero; una formula per la derivata n-esima va scritta dopo il segno di uguale";
        else if (statement.times > MAX_DERIVATIVE_BASE) verdict.reason = "l'ordine di una derivata da calcolare deve essere al più 4";
        else return solve_derivative(f, x, (int)statement.times, verdict);
        return verdict;
    }

    /* L'ordine: la variabile di induzione, da base in su, oppure un numero. */
    if (fixed) {
        base = statement.times;
        verdict.variable = 0;
        verdict.method = "con le regole di derivazione";
    } else if (!has_base) {
        base = 0;
    }
    if (x == variable || (!fixed && (statement.order != variable || node_uses_letter(f, variable)))) {
        verdict.reason = "l'ordine di derivazione deve essere la variabile di induzione, e la funzione da derivare non deve contenerla";
        return verdict;
    }
    if (base < 0 || base > MAX_DERIVATIVE_BASE) { verdict.reason = "l'ordine di una derivata, o il caso base di una derivata n-esima, deve essere al più 4"; return verdict; }
    induction_var = variable;
    default_base = 1;
    domain_floor = base;

    /* Le derivate di f, una dopo l'altra, con le regole. Servono fino
     * all'ordine del caso base; quelle dopo sono per la verifica, e si
     * smette se diventano lunghe o se le regole non le sanno fare. */
    Node *direct[MAX_JET + 1] = {f}, *sampled[MAX_JET + 1];
    int orders = 0, wanted = (int)base + (fixed ? 0 : DIRECT_ORDERS);
    verdict.outcome = NOT_PROVED;
    while (orders < wanted && (orders < base || node_count(direct[orders]) < MAX_DERIVATIVE_NODES)) {
        Node *next = derive(direct[orders], x);
        if (failure && orders >= base) break;
        if (failure) {
            verdict.outcome = UNSUPPORTED;
            verdict.reason = failure;
            return verdict;
        }
        direct[++orders] = next;
    }
    failure = NULL;

    /* 27h. Ogni derivata delle regole contro la serie di Taylor di f, in
     * ogni punto di prova. Una smentita è un errore del programma; fino al
     * caso base ognuna deve essere confermata almeno in un punto. */
    DerivativeCheck check;
    for (int k = 0; k <= orders; k++) sampled[k] = sample_tree(direct[k], x, 0, 0);
    derivatives_check(&check, sampled, orders, x);
    if (failure) { verdict.reason = failure; return verdict; }
    if (check.wrong) {
        unjustified_steps++;
        verdict.reason = "una derivata calcolata con le regole di derivazione è smentita dalla serie di Taylor della funzione";
        return verdict;
    }
    for (int k = 1; k <= base; k++)
        if (!check.agree[k]) { verdict.reason = "non riesco a confermare con i numeri una derivata calcolata con le regole di derivazione"; return verdict; }

    /* 27i. Verifica indipendente, e smentita: la formula contro le derivate
     * delle regole e contro quelle della serie, in ogni punto di prova. Con
     * l'ordine fisso la lettera n, se c'è, è un parametro come gli altri. */
    int compared = 0, contradicted = 0;
    for (int k = (int)base; k <= orders; k++) {
        Node *right = sample_tree(g, x, fixed ? 0 : variable, k);
        for (int p = 0; p < DERIVATIVE_POINTS; p++) {
            Frac at = derivative_points[p];
            Range claimed = sample_value(right, x, range_ratio(at.num, at.den));
            int side, by_rules = range_side(range_sub(check.rules[k][p], claimed), &side);
            int by_series = range_side(range_sub(check.taylor[k][p], claimed), &side);
            if ((check.agree[k] >> p & 1) && by_rules && by_series) {
                snprintf(text, sizeof text, "%c = %lld/%lld", x, at.num, at.den);
                verdict.outcome = REFUTED;
                verdict.witness = k;
                verdict.detail = text;
                return verdict;
            }
            contradicted |= by_rules || by_series;
            if (numbers_agree(check.taylor[k][p], claimed) > 0) compared = 1;
        }
    }
    if (failure) { verdict.reason = failure; return verdict; }

    /* Una smentita da uno solo dei due conti non basta per il FALSO, ma
     * basta per non dire DIMOSTRATO: o la formula è sbagliata, o uno dei due
     * conti, e in nessuno dei due casi la dimostrazione va consegnata. */
    if (contradicted) {
        verdict.reason = "in un punto di prova la formula è di sicuro diversa da una derivata calcolata, ma le regole e la serie di Taylor non vi concordano abbastanza per dire FALSO";
        return verdict;
    }
    if (!compared) { verdict.reason = "non riesco a confermare con i numeri la formula, in nessuno dei punti di prova"; return verdict; }

    /* 27a. Il caso base: un'uguaglianza tra espressioni, senza n. */
    if (!derivative_identity(direct[base], fixed ? g : node_replace(g, variable, node_num(base)), f, variable, base, x)) {
        snprintf(text, sizeof text, "la derivata di ordine %lld, calcolata con le regole, non si riduce alla formula%s%s", base,
                 failure ? ": " : "", failure ? failure : "");
        failure = NULL;
        verdict.reason = text;
        return verdict;
    }
    if (fixed) proof_add("\\textbf{Proof.} By the rules of differentiation.\n\\begin{itemize}\n\\item ");
    else proof_add("\\textbf{Proof.} By induction on $%c$: it is enough that the formula is right for $%c = %lld$ and that its derivative with "
                   "respect to $%c$ is the formula for $%c + 1$.\n\\begin{itemize}\n\\item \\emph{Base case}, $%c = %lld$. ",
                   variable, variable, base, x, variable, variable, base);
    size_t opening = proof_length;
    if (base == 0) proof_add("The derivative of order $0$ is the function itself, $");
    else proof_add("Differentiating $%lld$ time%s with respect to $%c$ gives $", base, base > 1 ? "s" : "", x);
    Span left = {proof_length, 0};
    put_node(direct[base], 0);
    left.to = proof_length;
    proof_add("$, and the formula is $");
    Span right = put_side(g, fixed ? NULL : node_num(base));
    proof_add("$: the two are equal, because their difference reduces to $0$ by exact algebra.\n");

    /* Le derivate non si semplificano, e quella di ordine 4 può avere
     * migliaia di simboli: oltre MAX_FORMULA caratteri reread_equal() non la
     * rilegge e risponde "non confermata", che conterebbe come un passo
     * sbagliato (lo ha mostrato fuzz_derivatives.py con 1/(x/2 - 2)^2). Una
     * formula che non si può rileggere non si scrive: resta la frase, come
     * in 13g quando un valore è troppo lungo. */
    int sound = 1;
    if (left.to - left.from + right.to - right.from + 4 < MAX_FORMULA && proof_length < PROOF_BYTES - 1)
        sound = reread_equal(left, right, base) || reread_numbers(left, right, x);
    else {
        proof_cut(opening);
        proof_add("The derivative of order $%lld$ given by the rules of differentiation is too long to write here; its difference "
                  "from the formula reduces to $0$ by exact algebra.\n", base);
    }

    /* 27b. Il passo: la derivata della formula, confrontata anche lei con la
     * serie di Taylor per i primi due n (27h), e poi l'identità in n. */
    if (!fixed) {
        Node *slope = derive(g, x);
        if (failure) { verdict.outcome = UNSUPPORTED; verdict.reason = failure; return verdict; }
        for (long long k = base; k <= base + 1; k++) {
            Node *pair[2] = {sample_tree(g, x, variable, k), sample_tree(slope, x, variable, k)};
            derivatives_check(&check, pair, 1, x);
            if (failure) { verdict.reason = failure; return verdict; }
            if (check.wrong) {
                unjustified_steps++;
                verdict.reason = "la derivata della formula, calcolata con le regole di derivazione, è smentita dalla sua serie di Taylor";
                return verdict;
            }
            if (!check.agree[1]) { verdict.reason = "non riesco a confermare con i numeri la derivata della formula"; return verdict; }
        }
        Statement step = {slope, node_replace(g, variable, node_affine(1, variable, 1)), REL_EQ};
        proof_add("\\item \\emph{Inductive step}. Assume the statement for some $%c \\ge %lld$. The derivative of order $%c + 1$ is then the "
                  "derivative of the formula for $%c$, which the rules of differentiation give as $", variable, base, variable, variable);
        put_node(slope, 0);
        proof_add("$. It remains to prove that this is the formula for $%c + 1$: $", variable);
        put_comparison(step.lhs, REL_EQ, step.rhs);
        proof_add("$ for every $%c \\ge %lld$.\n", variable, base);
        atom_count = base_poly_count = atan_count = 0;
        Verdict inner = induct(&step, variable, 1, base, 1);
        if (inner.outcome != PROVED) {
            if (inner.outcome == REFUTED) snprintf(text, sizeof text, "la derivata della formula non è la formula per %c + 1: per %c = %lld sono diverse", variable, variable, inner.witness);
            else snprintf(text, sizeof text, "non riesco a dimostrare che la derivata della formula è la formula per %c + 1: %s", variable, inner.reason);
            verdict.reason = text;
            return verdict;
        }
    }
    proof_add("\\item \\emph{Check with numbers}. The derivative%s computed here agree%s with the formula at the sample points, and with "
              "the derivatives read from the Taylor series of the function, computed there with interval arithmetic.\n\\end{itemize}\n$\\Box$",
              orders > base ? "s" : "", orders > base ? "" : "s");
    if (!sound) {
        unjustified_steps++;
        verdict.reason = "una formula della dimostrazione, riletta dal testo, non è confermata";
        return verdict;
    }
    if (proof_length >= PROOF_BYTES - 1) { verdict.reason = "la dimostrazione è troppo lunga per essere scritta per intero"; return verdict; }
    verdict.outcome = PROVED;
    verdict.note = node_has_tower(f, x) ? "u^v con la variabile nella base e nell'esponente è inteso come e^{v ln u}, dove u > 0" : NULL;
    verdict.proof = proof_text;

    /* 27m. Il certificato: l'ordine è un numero, o la lettera dell'induzione
     * con il suo caso base. */
    char order_text[48];
    if (fixed) snprintf(order_text, sizeof order_text, "%lld", base);
    else snprintf(order_text, sizeof order_text, "%c base %lld", variable, base);
    calculus_certify(&verdict, calculus_certificate("derivative", x, order_text, f, g, NULL, NULL, NULL), f, x);
    return verdict;
}

/* 27l. I PUNTI IN CUI LE REGOLE NON DANNO LA DERIVATA
 *
 * Un segno espanso (27j) ha un valore nell'insieme E in cui la funzione g e
 * le sue derivate date dalle regole hanno tutte un valore, e lì vale la
 * derivata. Fuori da E, nei punti in cui g è definita, la derivata può
 * esistere o no: |x| non è derivabile in 0, x|x| sì, e le regole non danno
 * la derivata né all'una né all'altra. La tabella dei segni conta come
 * falso un confronto senza valore: nel secondo caso \forall x\ ((x|x|)' =
 * 2|x|) risulterebbe falso in x = 0, ed è vero.
 *
 * Il controllo. Per ogni segno si cerca, con la tabella dei segni, l'insieme
 * D dei punti in cui g ha un valore e l'espansione no. L'enunciato si decide
 * solo se ogni punto di D è un punto isolato con, accanto, un intervallo in
 * cui g non è definita: per esempio 0 per la radice di x. Lì la derivata
 * non esiste, perché chiede g definita in tutto un intorno del punto (la
 * derivata da una parte sola, che i libri chiamano destra o sinistra, è
 * un'altra cosa), e l'espansione, che lì non ha valore, dice il vero. Ogni
 * altro punto di D lascia l'enunciato non deciso, e il verdetto dice quali.
 * In un enunciato periodico basta un punto di D per non decidere: la sua
 * tabella è nella lettera t = tan(u/2), e il punto u = pi sta a parte.
 *
 * Perché la tabella qui è affidabile: è la stessa con i suoi controlli
 * indipendenti, e la condizione che le si chiede di risolvere è scritta con
 * le stesse espressioni dell'enunciato; se non sa risolverla, non sa
 * nemmeno decidere l'enunciato. */

/* Vedi la dichiarazione dopo l'inclusione di parser.c. thesis è
 * l'enunciato, già controllato, di cui si sono espansi derivative_signs
 * segni. Lascia il testo della dimostrazione com'era. */
static const char *derivative_doubt(const Formula *thesis) {
    static char reason[sizeof solution_text + 200];
    const Formula *q = thesis;
    while (q->kind == F_NOT) q = q->a;
    if (q->kind != F_FORALL && q->kind != F_EXISTS && q->kind != F_SOLVE)
        return "il segno di derivata è trattato negli enunciati con un quantificatore su una variabile reale, o in un insieme di soluzioni";
    size_t length = proof_length;
    int wanted = figures_wanted;
    const char *doubt = NULL;
    figures_wanted = 0;
    for (int i = 0; i < derivative_signs && !doubt; i++) {
        /* D: "g = g" vale dove g ha un valore, "non (e = e)" dove
         * l'espansione e non ce l'ha. */
        Formula *defined = formula_node(F_EQUAL, NULL, NULL, ""), *derived = formula_node(F_EQUAL, NULL, NULL, "");
        defined->left = defined->right = (Node *)expanded_function[i];
        derived->left = derived->right = (Node *)expanded_value[i];
        /* Nell'insieme dell'enunciato, con i suoi estremi e i punti tolti,
         * preso tra i reali anche se è di razionali: si guarda di più, non
         * di meno. */
        Formula *solve = formula_node(F_SOLVE, formula_node(F_AND, defined, formula_node(F_NOT, derived, NULL, ""), ""), NULL, "");
        solve->variable = q->variable;
        solve->numbers = q->numbers;
        solve->numbers.reals = 1;
        solve->numbers.integers = 0;
        Verdict inner = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
        decide_by_signs(solve, &inner);
        failure = NULL;
        if (inner.outcome != SOLVED) {
            snprintf(reason, sizeof reason, "non riesco a stabilire dove le regole di derivazione danno la derivata: %s", inner.reason ? inner.reason : "la tabella dei segni non decide");
            doubt = reason;
            break;
        }
        if (strncmp(inner.detail, "\\nexists", 8) == 0) continue;

        /* Ogni pezzo di D deve essere un punto, e accanto, da una parte,
         * g non deve avere un valore. */
        int isolated = !trig_on;
        Piece piece;
        for (int from = 0; isolated && sign_piece(solve->a, from, &piece); from = piece.last + 1) {
            int row = piece.first;
            isolated = piece.first == piece.last && row % 2 &&
                       (!sign_row[row - 1].inside || !sign_truth(defined, sign_row[row - 1].sign) ||
                        !sign_row[row + 1].inside || !sign_truth(defined, sign_row[row + 1].sign));
        }
        if (isolated) { derivative_edges = 1; continue; }
        snprintf(reason, sizeof reason, "la funzione è definita per %s, ma lì le regole di derivazione non ne danno la derivata: non so se vi è derivabile", inner.detail);
        doubt = reason;
    }
    figures_wanted = wanted;
    proof_cut(length);
    return doubt;
}

/* =============================================================================
 * 28. INSIEMI QUALSIASI: MODELLI FINITI, ISTANZE, UGUALI AL POSTO DI UGUALI
 * ============================================================================
 *
 * A che cosa serve. "In un insieme con un'operazione, un elemento neutro a
 * sinistra e uno a destra coincidono" non parla di numeri: l'insieme è
 * qualsiasi, e dell'operazione si sa solo ciò che dicono le ipotesi. Non
 * c'è una regola da sostituire né un conto da fare, e le regole del capitolo
 * 18, che lavorano con i polinomi, non hanno presa. Il linguaggio di questi
 * enunciati è nel paragrafo 17o di parser.c; qui c'è il modo di deciderli,
 * che è fatto di due metà molto diverse.
 *
 * SMENTIRE: I MODELLI FINITI (28a, 28t)
 *
 * L'enunciato afferma qualcosa di ogni insieme e di ogni operazione. Per
 * smentirlo basta un esempio in cui le ipotesi valgono e la tesi no, e un
 * esempio si può cercare tra gli insiemi con uno, due, tre elementi: lì
 * un'operazione è una tabella, le tabelle sono in numero finito, e che un
 * enunciato valga in una tabella si controlla con un conto finito e
 * completo. Un esempio trovato così è un controesempio vero: il verdetto è
 * FALSO, con le tabelle stampate.
 * Quando le tabelle da enumerare sono troppe, 28t traduce la frase in
 * clausole proposizionali e cerca con un piccolo risolutore SAT scritto
 * qui. Le cardinalita crescono senza tetto compilato nel programma, entro
 * budget espliciti di lavoro e memoria. Ogni tabella estratta viene
 * ricalcolata senza usare la traduzione SAT e verificata dal checker.
 *
 * Non trovarne non dimostra nulla. "Ogni applicazione iniettiva di un
 * insieme in sé è suriettiva" vale in ogni insieme finito, e quindi in ogni
 * tabella che si possa provare, ma è falso: n -> n + 1 sui naturali è
 * iniettiva e non raggiunge lo zero. Per questo la ricerca dei modelli fa
 * due sole cose: smentisce, e fa da controllo indipendente di ciò che
 * l'altra metà dimostra. Un enunciato è dichiarato DIMOSTRATO solo se ha
 * una dimostrazione scritta, ricontrollata passo per passo, nessun modello
 * piccolo lo contraddice, e il verificatore indipendente ne accetta il
 * certificato (28f).
 *
 * Il prefisso esaustivo di 28a usa insiemi non vuoti; 28t include anche gli
 * insiemi vuoti. Il verificatore delle dimostrazioni controlla da se tutti
 * i possibili insiemi vuoti, come spiegato sotto.
 *
 * Fa eccezione l'enunciato che chiede un esempio, \exists S\ \exists R
 * \subseteq S \times S\ (...): lì un modello in cui la condizione vale è
 * proprio ciò che si chiede, e trovarlo è una dimostrazione.
 *
 * DIMOSTRARE: ISTANZE E UGUALI AL POSTO DI UGUALI (28b-28e, 28g)
 *
 * Si ragiona per assurdo, come si fa a mano: si suppongono le ipotesi e la
 * negazione della tesi, e si cerca una contraddizione. Tutto ciò che si sa
 * è un elenco di condizioni vere (Known), che cresce con cinque mosse,
 * ognuna una regola di deduzione valida:
 *
 *   28-1. Una parte. Da "A e B" seguono A e B; da "A oppure B", saputo che
 *         A è falsa, segue B.
 *   28-2. Un nome. Da "esiste x in S con P(x)" si prende un tale elemento e
 *         gli si dà un nome nuovo, c: vale P(c). È l'unico modo in cui
 *         nasce un elemento, insieme all'applicare un simbolo a elementi
 *         che ci sono già: per questo ciò che si dimostra vale anche se
 *         qualche insieme è vuoto, e il verificatore lo ricontrolla (28f).
 *   28-3. Un'istanza. Da "per ogni x in S vale P(x)", e da un elemento t di
 *         S, segue P(t).
 *   28-4. Uguali al posto di uguali. Le uguaglianze note s = t dividono gli
 *         elementi in classi; se a = a' e b = b' allora f(a, b) = f(a', b')
 *         (chiusura per congruenza). Vale anche per le parti e le
 *         relazioni: se x sta in X e x = y, allora y sta in X.
 *   28-5. Due casi. Se di "A oppure B" non si sa quale valga, si prova che
 *         la contraddizione arriva in tutti e due i casi.
 *
 * 28-2 e 28-3 valgono anche per le parti (17u di parser.c): da "esiste una
 * parte X di S con P(X)" nasce una parte con un nome nuovo, e da "per ogni
 * parte X di S vale P(X)" segue P(D) per ogni parte D di S che si sa
 * nominare, anche una definita da una regola, "D = \{x \in S \mid c(x)\}"
 * (28j). Quali parti provare, e come, lo dice 28k.
 *
 * La contraddizione è un'uguaglianza che dovrebbe essere falsa (si sa
 * s diverso da t, e s e t sono finiti nella stessa classe), oppure una
 * disgiunzione di cui tutte le parti sono false.
 *
 * Quali istanze. Le regole dicono che cosa è lecito, non che cosa conviene:
 * le istanze possibili sono infinite. Se ne provano di quattro tipi, per un
 * numero fisso di giri:
 *
 *   - sugli elementi che hanno un nome (quelli dichiarati, quelli della
 *     tesi, quelli nati da 28-2), tutte;
 *   - quelle che riscrivono un elemento presente: un termine della
 *     condizione che contiene tutte le sue variabili corrisponde a un
 *     elemento che c'è già. È ciò che fa chi applica l'associatività a
 *     (a b) c perché ce l'ha davanti;
 *   - sugli altri elementi presenti, solo quelle che non introducono
 *     elementi nuovi e contengono un confronto già deciso: sono quelle da
 *     cui 28-1 può trarre subito qualcosa;
 *   - per un "per ogni t" con t = f(u) nel corpo, sugli elementi presenti
 *     scritti come f(u): è "f(x) sta in f(X)" (28l).
 *
 * La definizione di una parte (28j) non si prova su tutti gli elementi con
 * un nome, ma dove la parte compare: "c \in D" chiede che si svolga.
 *
 * Quando le istanze scelte dalla forma non bastano, l'affermazione si
 * riprova con quelle scelte dal significato (28r): dagli elementi di cui si
 * parla si costruisce un modello candidato, il più piccolo che ciò che si
 * sa permette, e di ogni "per ogni" si prova l'istanza che vi è falsa. È la
 * "model-based quantifier instantiation" dei dimostratori SMT.
 *
 * Quali casi. Prima di distinguere i casi della prima disgiunzione in
 * attesa (28-5), si cerca tra le disgiunzioni in attesa una con un caso che
 * si chiude con i soli giri di istanze: allora l'altro caso segue, e la
 * distinzione non conta tra quelle una dentro l'altra (28l). È il lemma che
 * si dimostra per assurdo a metà di una dimostrazione.
 *
 * Non trovare la contraddizione vuol dire NON DIMOSTRATO, mai FALSO: la
 * ricerca non è completa.
 *
 * LA DIMOSTRAZIONE SCRITTA E IL SUO CONTROLLO (28e)
 *
 * Trovata la contraddizione, si risale da lì a ciò che è servito, e solo
 * quello viene scritto, un passo per riga. Ogni passo scritto viene
 * ricontrollato con un metodo diverso da quello che l'ha trovato:
 *
 *   - una catena di uguaglianze s = u = ... = t viene riletta anello per
 *     anello: ogni termine deve ottenersi dal precedente sostituendo, in un
 *     solo punto, un membro di un'uguaglianza già scritta con l'altro
 *     (rewrites()). La ricerca usa classi e rappresentanti; questo
 *     controllo guarda solo come sono scritti i termini.
 *   - un passo "da (p), poiché A vale e B no, segue C" viene ricontrollato
 *     con una tabella di verità: in ogni modo di dare vero o falso alle
 *     condizioni elementari di (p), se (p) è vera e A e B hanno il valore
 *     detto, allora C è vera (follows()).
 *
 * Poi, a dimostrazione finita, che i casi scritti siano tutti: le foglie,
 * con i loro casi, devono coprire ogni distinzione che fanno (28p). Se un
 * controllo fallisce la dimostrazione non viene emessa, e unjustified_steps
 * lo registra.
 *
 * IL CERTIFICATO (28f)
 *
 * Il controllo di 28e legge le tabelle della ricerca: due testimoni che
 * leggono lo stesso giornale. Per questo ogni verdetto del capitolo va anche
 * a checker.c, che non usa nulla di questo file (capitolo 11 di checker.c):
 *
 *   - un modello trovato da 28a, controesempio o esempio, va con le sue
 *     tabelle, e il verificatore vi ricalcola l'enunciato con il suo
 *     valutatore;
 *   - una dimostrazione va con i soli dati che la ricerca ha trovato: per
 *     ogni affermazione un caso, con i nomi (28-2), le istanze (28-3) e le
 *     parti definite (28j) che servono alle contraddizioni dei suoi rami.
 *     Le parti, le uguaglianze e
 *     i casi (28-1, 28-4, 28-5) il verificatore li ritrova da sé, provando
 *     tutti i valori delle condizioni elementari con la sua chiusura per
 *     congruenza, e lo rifà per ogni scelta degli insiemi vuoti: così che la
 *     dimostrazione valga anche se un insieme è vuoto diventa un conto, e non
 *     resta un argomento ("non inventa elementi").
 *
 * DIMOSTRATO e FALSO vogliono il certificato accettato: uno respinto è un
 * errore del programma, conta in unjustified_steps, e il verdetto diventa
 * NON DIMOSTRATO. Se il verificatore non sa controllare una dimostrazione
 * (troppe condizioni elementari) il verdetto resta, e dice perché il
 * certificato manca. Un modello invece è un conto per intero, che il motore
 * ha già fatto con limiti più stretti: se il verificatore non lo sa rifare,
 * il verdetto non c'è.
 *
 * LA NOTAZIONE DEI LIBRI (28h)
 *
 * Gli enunciati scritti con gli insiemi, f(X) = f(Y), R = \{(x, x) \mid x
 * \in S\}, arrivano qui già svolti nelle condizioni sugli elementi (17p,
 * 17q in parser.c): il capitolo non conosce altro linguaggio. Lo svolgimento
 * è una riscrittura, e prima di tutto si ricontrolla: 28h calcola su molti
 * modelli finiti l'enunciato com'è scritto, senza sostituire nulla, e quello
 * svolto, e vuole lo stesso valore. Il certificato è dell'enunciato svolto:
 * il verificatore non legge la notazione dei libri, come non legge il
 * LaTeX.
 *
 * LE PARTI E LE APPLICAZIONI COME OGGETTI (28m, 28n, 28o)
 *
 * Con \mathcal{P}(S) e T^{S} come insiemi di oggetti (17v in parser.c)
 * cambiano tre cose. I modelli finiti danno a questi insiemi le parti e le
 * applicazioni vere, con la loro tabella (28m): un controesempio è ancora un
 * controesempio vero. Le dimostrazioni hanno in più, tra le ipotesi, le
 * leggi delle parti, l'estensionalità e alcune comprensioni (28n), e il
 * verificatore controlla da sé che lo siano. E poiché qui le istanze
 * crescono in fretta, quando la ricerca di sempre non basta la si ripete
 * guardando avanti prima di distinguere i casi e scegliendo le istanze con
 * più cura, e un'affermazione che non segue tutta insieme si prova a pezzi
 * (28o); se non basta ancora, le istanze le sceglie il modello candidato
 * (28r). Tutto questo cambia solo quali dimostrazioni si trovano: ogni passo
 * scritto è ricontrollato come sempre, e il certificato pure.
 *
 * Un enunciato che parla solo dei numeri che scrive, con relazioni date
 * dall'elenco delle loro coppie (17v), ha un solo modello, con i numeri
 * tutti diversi: lì il calcolo decide, come per un esempio, e il verdetto
 * DIMOSTRATO viene da quel conto, con il certificato del modello.
 *
 * L'EQUIPOTENZA (28q)
 *
 * A \sim B (17w in parser.c) vuol dire che c'è una biiezione da A a B: è un
 * "esiste" su due applicazioni, una l'inversa dell'altra, e il capitolo lo
 * usa con le sue due regole. Vera, dà un nome alla biiezione e alla sua
 * inversa, come 28-2. Falsa, ha per istanza due applicazioni costruite,
 * come 28-3: un testimone, fatto da una grammatica piccola e limitata con le
 * biiezioni con un nome e la forma degli insiemi (l'immagine delle parti, f
 * \mapsto \beta \circ f \circ \alpha^{-1} sulle applicazioni, le componenti di
 * un prodotto, scambiate o no), con una definizione per ogni applicazione
 * nuova; che siano una l'inversa dell'altra lo deve mostrare la
 * dimostrazione, con le definizioni e l'estensionalità (28n). Il numero
 * degli elementi non entra mai in una dimostrazione: solo nei modelli
 * finiti, dove A \sim B è "tanti elementi quanti". Il certificato porta i
 * nomi, le definizioni e il testimone, e il verificatore controlla da sé la
 * forma di ogni definizione (11j di checker.c).
 *
 * CHE COSA NON C'È
 *
 * Applicazioni da costruire (\exists f \in S^{S} dentro l'enunciato) fuori
 * da un'equipotenza, ipotesi su tutte le applicazioni quando T^{S} non è un
 * insieme di oggetti dell'enunciato, applicazioni definite per casi o come
 * inverse (servirebbero comprensioni di applicazioni più larghe di quella con
 * due valori di 28s: le definizioni di 28q nascono solo per un testimone), il
 * quoziente (\exists T\ \exists f), potenze x^{n} con n numero: il lettore le
 * respinge, dicendo quale. Le parti costruite con più di un passo, come
 * f(f^{-1}(\{c\})) o \{a, b\}, non vengono provate (28k): un enunciato che
 * ne ha bisogno resta NON DIMOSTRATO. Dell'equipotenza (28q)
 * mancano le biiezioni che la grammatica non costruisce (\mathcal{P}(S) \sim
 * \{0, 1\}^{S}, l'associatività dei prodotti), i passi w3 e w4 uno dentro
 * l'altro, come \mathcal{P}(\mathcal{P}(S)) \sim \mathcal{P}(\mathcal{P}(T)),
 * le cui identità chiederebbero un lemma con l'estensionalità a metà della
 * dimostrazione, che la ricerca non fa; e nel lettore gli esponenti che sono
 * un prodotto o un'unione, S^{T \times V} e S^{T \cup V} (17w), e i lati di
 * tre componenti. Il numero degli elementi, |S|, non c'è (capitolo 20).
 *
 * Il modello candidato di 28r sceglie le istanze, non i casi: le
 * distinzioni restano quelle di refute(), sulla prima disgiunzione in
 * attesa, e una dimostrazione che ne chiede molte, una dentro l'altra, non
 * si trova. Le sue dimostrazioni sono lunghe: ogni caso riscrive le righe
 * da cui parte, e il certificato porta insieme le istanze di tutti i casi,
 * che il verificatore deve ridistinguere da sé. Una delle sue dimostrazioni
 * (la transitività dell'ordine f(S) \subsetneq g(S) di order_relations.tex)
 * ha più casi di quanti il verificatore sappia provare entro il suo limite:
 * il verdetto resta, e dice che il certificato manca. Si potrebbe dare al
 * verificatore la struttura dei casi, come voci del certificato.
 *
 * I modelli finiti dimostrano solo un esempio; un enunciato "per ogni" lo
 * dimostrano le istanze. Una dimostrazione dai soli modelli sarebbe lecita
 * nella classe di Bernays, Schönfinkel e Ramsey (gli "esiste" della
 * negazione, messa in forma prenessa, tutti prima dei "per ogni", e nessuna
 * applicazione che riporti un insieme in un insieme da cui si parte, così
 * che i termini chiusi siano finiti): lì un controesempio, se c'è, ne ha uno
 * con al più tanti elementi quanti sono gli "esiste". Non è usata: andrebbe
 * riconosciuta la classe, scritto il limite, e certificato il conto su tutti
 * i modelli fino a quel limite, che il verificatore oggi non fa; le
 * dimostrazioni per istanze hanno già il loro certificato. Fuori da quella
 * classe è proprio dove i modelli ingannano: "un'applicazione iniettiva di
 * un insieme in sé è suriettiva" vale in ogni modello finito ed è falso.
 */

/* 28a. I MODELLI FINITI */

/* Una coordinata della ricerca dei modelli: la grandezza di un insieme.
 * Si contano elementi; minimum non è mai una grandezza massima. */
typedef struct {
    size_t size;     /* Quanti elementi ha l'insieme nel modello in corso. */
    size_t minimum;  /* Quanti ne deve avere almeno, per la formula e per i tipi (model_minimums()). */
    size_t extra;    /* Stato dell'enumeratore: size = minimum + extra, dove è indirizzabile. */
} ModelDimension;

/* Un'interpretazione finita dell'enunciato in corso: quanti elementi ha
 * ogni insieme, e la tabella di ogni simbolo dichiarato. Gli elementi
 * dell'insieme di posto i sono i numeri da 0 a dimension[i].size - 1.
 *
 * La tabella di un simbolo dà il suo valore per ogni scelta degli
 * argomenti: alla cella a + b * (elementi del primo insieme) c'è il valore
 * in (a, b), che è un elemento del codominio, oppure 0 o 1 per una parte o
 * una relazione. Un elemento con un nome ha la sola cella 0. Le tabelle dei
 * simboli di struttura degli insiemi di parti e di applicazioni non si
 * scelgono: le fissa model_structure() (28m).
 *
 * Il modello possiede coordinate e tabelle. Gli indici di insieme e di
 * simbolo sono quelli del problema corrente; la pulizia usa soltanto le
 * capacità e le lunghezze possedute, non i contatori del parser. */
typedef struct {
    ModelDimension *dimension;      /* Coordinate possedute, indicizzate per insieme. */
    size_t dimension_capacity;      /* Celle allocate nel vettore dimension. */
    size_t **table;                 /* Tabelle possedute, una per simbolo, NULL senza celle. */
    unsigned char **part;           /* Contesti temporanei presi in prestito dai quantificatori su parti. */
    size_t symbols;                 /* Numero di celle allocate in table e part, indipendente dal parser. */
    size_t bytes;                    /* Byte di coordinate, puntatori e tabelle posseduti. */
    int limited;                     /* Ultima allocazione interrotta per risorse, non per dominio vuoto. */
} Model;

/* Libera solo le tabelle; le coordinate restano valide per il tentativo
 * successivo della stessa enumerazione. Anche la loro memoria e contata. */
static void model_tables_clear(Model *m) {
    if (m->table) for (size_t i = 0; i < m->symbols; i++) free(m->table[i]);
    free(m->table); free(m->part); m->table = NULL; m->part = NULL; m->symbols = 0;
    m->bytes = m->dimension_capacity*sizeof *m->dimension;
}

/* Dimensiona le coordinate entro il budget dei modelli. Una crescita
 * conserva le cardinalita, azzera le celle nuove e non pubblica memoria
 * parziale. Risorse finite fermano questa ricerca, non altre dimostrazioni. */
static int model_dimensions(Model *m) {
    size_t need=(size_t)sort_count,unit=sizeof *m->dimension;
    if (m->bytes>model_memory_limit || need>model_memory_limit/unit) { m->limited=1;return 0; }
    if (need<=m->dimension_capacity) return 1;
    size_t cap=m->dimension_capacity?m->dimension_capacity:16;
    while (cap<need) {
        if (cap>(size_t)-1/2) { cap=need;break; }
        cap*=2;
    }
    size_t other=m->bytes-m->dimension_capacity*unit;
    if (cap>(model_memory_limit-other)/unit) cap=need;
    if (cap>(model_memory_limit-other)/unit) { m->limited=1;return 0; }
    ModelDimension *data=realloc(m->dimension,cap*unit);
    if (!data) { m->limited=1;return 0; }
    memset(data+m->dimension_capacity,0,(cap-m->dimension_capacity)*unit);
    m->dimension=data;m->dimension_capacity=cap;m->bytes=other+cap*unit;
    return 1;
}

/* Libera tutto cio che il modello possiede, senza dipendere dai contatori
 * del parser che possono gia appartenere all'enunciato successivo. */
static void model_clear(Model *m) {
    model_tables_clear(m);
    free(m->dimension);m->dimension=NULL;m->dimension_capacity=0;m->bytes=0;
}

/* Moltiplica dimensioni solo se il risultato e indirizzabile. */
static int model_product(size_t a, size_t b, size_t *out) {
    if (a && b > (size_t)-1 / a) return 0;
    *out = a * b;
    return 1;
}

/* 28i. LE PARTI LEGATE NEI MODELLI
 *
 * (Sta qui, dentro 28a, perché i modelli la usano; la lettera è venuta dopo
 * le altre.)
 *
 * Un quantificatore su parti (17u), "per ogni parte X di S", in un modello
 * finito si calcola come uno su elementi: le parti di un insieme di n
 * elementi sono 2^n, e si provano tutte. Una parte e un vettore di n byte, con
 * il byte x acceso se l'elemento x sta nella parte. La parte legata non ha una
 * tabella sua (model_cells() le dà zero celle, così la ricerca dei
 * modelli non la sceglie): il suo valore è in Model.part, come quello di
 * una variabile in value[]. */

/* Ritorna il valore della cella (a, b) della tabella del simbolo symbol nel
 * modello m (b conta solo con due argomenti): per una parte legata, 1 se a
 * sta nella parte che le dà Model.part. */
static size_t model_cell(const Model *m, int symbol, size_t a, size_t b) {
    if (symbol_bound[symbol]) return m->part[symbol][a];
    size_t cell = symbols[symbol].arity ? a : 0;
    if (symbols[symbol].arity == 2) cell += b * m->dimension[symbols[symbol].domain[0]].size;
    return m->table[symbol][cell];
}

/* Ritorna il valore dell'elemento e nel modello m, con ogni variabile al
 * valore che ha in value[]; per una parte o una relazione applicata, 1 se
 * vale. */
static size_t model_element(const Model *m, const Elem *e, const size_t *value) {
    if (e->symbol < 0) return value[e->slot];
    size_t a = e->arg[0] ? model_element(m, e->arg[0], value) : 0, b = e->arg[1] ? model_element(m, e->arg[1], value) : 0;
    return model_cell(m, e->symbol, a, b);
}

/* Quanti elementi i quantificatori hanno provato da quando model_search()
 * ha cominciato. Con molti quantificatori uno dentro l'altro il conto su un
 * solo modello cresce come una potenza: venti "per ogni" su tre elementi
 * sono miliardi di prove. Oltre model_step_limit model_holds() smette di
 * calcolare, e chi la chiama deve buttare via la sua risposta. */
static long long model_steps;

/* Ritorna 1 se il conto sui modelli in corso è arrivato in fondo. Dopo un
 * conto interrotto il valore ritornato da model_holds() o da book_holds()
 * non vuol dire nulla, nemmeno quando è "vero": una negazione rovescia lo
 * zero di un quantificatore interrotto. Chi usa quel valore lo chiede qui. */
static int model_steps_complete(void) { return model_steps <= model_step_limit; }

/* Il motivo, se la ricerca SAT ha trovato un modello che poi non si è
 * potuto ricalcolare entro model_step_limit; altrimenti NULL. Un modello
 * così non è un controesempio, ma il verdetto deve dire che cosa è mancato:
 * non la ricerca, il budget del ricalcolo. Lo azzera prove_abstract(). */
static const char *model_unconfirmed;

/* 28i. Il calcolo di una condizione in un modello: model_holds() per le
 * condizioni svolte, book_holds() (28h) per quelle scritte come nei libri. */
typedef int (*ModelHolds)(const Model *m, const Sentence *s, size_t *value);

/* 28i. Ritorna 1 se il quantificatore su parti s (S_FORALL_PART o
 * S_EXISTS_PART) vale nel modello m, con le variabili ai valori di value[],
 * calcolando la sua condizione con holds. Prova le parti dalla vuota,
 * contandole in model_steps, e rimette Model.part com'era. Lo stesso
 * simbolo può essere legato da due quantificatori uno dentro l'altro (le
 * copie di 17q): per questo il valore di fuori si salva e si rimette. */
static int model_part_quantifier(const Model *m, const Sentence *s, size_t *value, ModelHolds holds) {
    int every = s->kind == S_FORALL_PART, result = every;
    size_t n = m->dimension[symbols[s->part].domain[0]].size;
    if (n > model_memory_limit) { model_steps = model_step_limit + 1LL; return 0; }
    unsigned char *saved = m->part[s->part], *bits = calloc(n ? n : 1, 1);
    if (!bits) { model_steps = model_step_limit + 1LL; return 0; }
    m->part[s->part] = bits;
    for (;;) {
        if (++model_steps > model_step_limit) break;
        if (holds(m, s->a, value) != every) { result = !every; break; }
        size_t bit = 0;
        while (bit < n && bits[bit]) bits[bit++] = 0;
        if (bit == n) break;
        bits[bit] = 1;
    }
    m->part[s->part] = saved;
    free(bits);
    return result;
}

/* 17w. Ritorna 1 se i due lati dell'equipotenza s hanno nel modello m lo
 * stesso numero di elementi: un lato è un insieme o il prodotto di due, e ne
 * ha il prodotto delle grandezze.
 *
 * Perché basta contare. Tra due insiemi finiti c'è una biiezione se e solo
 * se hanno lo stesso numero di elementi: se ne hanno n tutti e due, li si
 * numera da 0 a n - 1, e l'elemento numero i dell'uno va nell'elemento
 * numero i dell'altro; se c'è una biiezione, ogni elemento dell'uno ne ha
 * uno solo dell'altro e viceversa, quindi sono tanti quanti (è il principio
 * dei cassetti, letto nei due versi). È un fatto sugli insiemi finiti dei
 * modelli: le dimostrazioni non lo usano mai (28q). */
static int model_equipotent(const Model *m, const Sentence *s) {
    size_t size[2] = {1, 1};
    for (int k = 0; k < 2; k++)
        for (int i = 0; i < s->sides[k]; i++)
            if (!model_product(size[k], m->dimension[slot_data[s->side_slot[k][i]].sort].size, &size[k])) {
                model_steps = model_step_limit + 1LL;
                return 0;
            }
    return size[0] == size[1];
}

/* Ritorna 1 se la condizione s vale nel modello m, con le variabili libere
 * ai valori di value[]. È un conto finito e completo: ogni quantificatore
 * prova tutti gli elementi del suo insieme. value[] viene usato anche per
 * le variabili che s lega. Se model_steps supera model_step_limit la
 * risposta non vuol dire nulla. */
static int model_holds(const Model *m, const Sentence *s, size_t *value) {
    switch (s->kind) {
    case S_TRUE:
        return 1;
    case S_EQUIPOTENT:
        return model_equipotent(m, s);
    case S_EQUAL:
        return model_element(m, s->left, value) == model_element(m, s->right, value);
    case S_HOLDS:
        return model_element(m, s->left, value);
    case S_NOT:
        return !model_holds(m, s->a, value);
    case S_AND:
        return model_holds(m, s->a, value) && model_holds(m, s->b, value);
    case S_OR:
        return model_holds(m, s->a, value) || model_holds(m, s->b, value);
    case S_IMPLIES:
        return !model_holds(m, s->a, value) || model_holds(m, s->b, value);
    case S_IFF:
        return model_holds(m, s->a, value) == model_holds(m, s->b, value);
    case S_FORALL_PART: case S_EXISTS_PART:
        return model_part_quantifier(m, s, value, model_holds);
    case S_FORALL: case S_EXISTS:
        break;
    case S_MEMBER: case S_INCLUDED: case S_SAME: case S_UNIQUE:
        /* La notazione dei libri non arriva qui: lo svolgimento (17q) la
         * toglie, e book_holds() (28h) la calcola a parte. */
        return 0;
    }
    int every = s->kind == S_FORALL;
    for (size_t x = 0; x < m->dimension[slot_data[s->slot].sort].size; x++) {
        if (++model_steps > model_step_limit) return 0;
        value[s->slot] = x;
        if (model_holds(m, s->a, value) != every) return !every;
    }
    return every;
}

/* Ritorna quanti valori può prendere una cella della tabella del simbolo
 * symbol nel modello m, e mette in *cells quante celle ha la tabella. Una
 * parte legata (28i) ha zero celle: nessuno ne sceglie la tabella. */
static size_t model_cells(const Model *m, int symbol, size_t *cells) {
    const Symbol *s = &symbols[symbol];
    *cells = 1;
    for (int i = 0; i < s->arity; i++)
        if (!model_product(*cells, m->dimension[s->domain[i]].size, cells)) { *cells = (size_t)-1; return 0; }
    if (symbol_bound[symbol]) { *cells = 0; return 1; }
    return s->range == TRUTH ? 2 : m->dimension[s->range].size;
}

/* Alloca tabelle azzerate delle cardinalita correnti. Celle e valori non
 * hanno un tetto prefissato; overflow, budget o malloc fallita danno 0.
 * Una funzione con dominio non vuoto e codominio vuoto non esiste. */
static int model_allocate(Model *m) {
    model_tables_clear(m);
    m->limited = 0;
    if (!model_dimensions(m)) return 0;
    size_t pointers;
    if (!model_product((size_t)symbol_count, sizeof *m->table + sizeof *m->part, &pointers) || pointers > model_memory_limit-m->bytes) {
        m->limited = 1; return 0;
    }
    if (symbol_count) {
        m->symbols = (size_t)symbol_count;
        m->table = calloc(m->symbols, sizeof *m->table);
        m->part = calloc(m->symbols, sizeof *m->part);
        if (!m->table || !m->part) { m->limited = 1; model_tables_clear(m); return 0; }
    }
    m->bytes += pointers;
    for (int s = 0; s < symbol_count; s++) {
        size_t cells, bytes, values = model_cells(m, s, &cells);
        if (cells && !values && cells != (size_t)-1) { model_tables_clear(m); return 0; }
        if (!model_product(cells, sizeof(size_t), &bytes) || bytes > model_memory_limit - m->bytes) {
            m->limited = 1; model_tables_clear(m); return 0;
        }
        if (bytes) m->table[s] = calloc(bytes, 1);
        if (bytes && !m->table[s]) { m->limited = 1; model_tables_clear(m); return 0; }
        m->bytes += bytes;
    }
    return 1;
}

/* 28m. GLI INSIEMI DI PARTI E DI APPLICAZIONI NEI MODELLI
 *
 * (Sta qui, dopo 28a, perché ne completa i modelli; la lettera è venuta
 * dopo le altre.)
 *
 * Un enunciato che prende \mathcal{P}(S) o T^{S} come insieme di oggetti
 * (17v in parser.c) parla delle parti e delle applicazioni vere: un suo
 * modello non può dare a \mathcal{P}(S) elementi qualsiasi, perché un
 * controesempio in cui \mathcal{P}(S) non contiene tutte le parti di S non
 * smentirebbe nulla. Per questo in un modello la grandezza di questi insiemi
 * e la tabella del loro simbolo di struttura non si scelgono, si calcolano:
 *
 *   - \mathcal{P}(S), con S di n elementi, ha 2^n elementi: l'elemento k è
 *     la parte degli i con il bit i di k uguale a 1. Ogni parte di S ha un
 *     solo k, quindi questo è proprio l'insieme delle parti.
 *   - T^{S}, con S di n elementi e T di m, ha m^n elementi: l'elemento k è
 *     l'applicazione che manda i nella cifra i di k scritto in base m (la
 *     cifra 0 è quella delle unità). Ogni applicazione ha un solo k.
 *
 * È la stessa numerazione del verificatore (ck_derived_sort() in
 * checker.c), che la rifà da sé: le tabelle degli altri simboli nominano gli
 * elementi con quei numeri. Il prefisso esaustivo usa MAX_MODEL_SIZE,
 * MAX_MODEL_OBJECTS e MAX_MODEL_CELLS per restare breve; la ricerca SAT
 * successiva non li usa. Entrambe hanno le stesse tabelle dinamiche. */

/* Ritorna 1 se la tabella del simbolo di posto s è fissata dalla struttura
 * di un insieme, e non va scelta: il simbolo di struttura di un insieme di
 * parti o di applicazioni, o un numero scritto come elemento (17v). */
static int symbol_fixed(int s) { return symbol_structure(s) >= 0 || symbols[s].name >= NUMERAL_NAMES; }

/* 17v. Ritorna quale dei numeri dell'insieme di posto sort è il simbolo s:
 * 0 per il primo nell'elenco dei simboli, 1 per il secondo, e così via. È
 * l'elemento che lo rappresenta nei modelli, dove i numeri sono gli
 * elementi 0, 1, ... del loro insieme. */
static int numeral_position(int sort, int s) {
    int position = 0;
    for (int i = 0; i < s; i++) position += symbols[i].name >= NUMERAL_NAMES && symbols[i].range == sort;
    return position;
}

/* Completa le cardinalita degli insiemi derivati. Le potenze sono quelle
 * della definizione: si fermano se non sono indirizzabili, senza enumerare
 * una potenza enorme. model_allocate controlla poi il budget di memoria. */
static int model_derived_sizes(Model *m) {
    for (int i = 0; i < sort_count; i++) {
        if (sort_data[i].kind == SORT_PLAIN) continue;
        if (sort_data[i].kind == SORT_NUMBERS) {
            m->dimension[i].size = 0;
            for (int s = 0; s < symbol_count; s++) m->dimension[i].size += symbols[s].name >= NUMERAL_NAMES && symbols[s].range == i;
            continue;
        }
        size_t values = sort_data[i].kind == SORT_PARTS ? 2 : m->dimension[sort_data[i].target].size, size = 1;
        size_t power = m->dimension[sort_data[i].base].size;
        /* L'esponenziazione binaria evita un ciclo lungo anche per 0^n e 1^n. */
        for (; power; power /= 2) {
            if ((power & 1) && !model_product(size, values, &size)) return 0;
            if (power > 1 && !model_product(values, values, &values)) return 0;
        }
        m->dimension[i].size = size;
    }
    return 1;
}

/* Le cifre in base base scelgono solo le grandezze degli insiemi arbitrari
 * del prefisso esaustivo; gli altri non consumano cifre. Ritorna la somma,
 * o -2 fuori dal prefisso. I limiti non riguardano il successivo SAT. */
static int model_sizes_at(Model *m, int code, int base) {
    if (!model_dimensions(m)) return -2;
    int sum = 0;
    for (int i = 0; i < sort_count; i++) {
        if (sort_data[i].kind == SORT_PLAIN) {
            sum += (int)(m->dimension[i].size=1+code%base);code/=base;
        }
    }
    if (!model_derived_sizes(m)) return -2;
    for (int i = 0; i < sort_count; i++)
        if (sort_data[i].kind != SORT_PLAIN && m->dimension[i].size > MAX_MODEL_OBJECTS) return -2;
    for (int s = 0; s < symbol_count; s++) {
        size_t cells;
        model_cells(m, s, &cells);
        if (cells > MAX_MODEL_CELLS) return -2;
    }
    return sum;
}

/* Le grandezze della ricerca esaustiva (28a), nella sua base usuale. La
 * ricerca SAT sceglie direttamente le cardinalita, senza una base fissa. */
static int model_sizes(Model *m, int code) {
    return model_sizes_at(m, code, MAX_MODEL_SIZE);
}

/* Riempie in m le tabelle dei simboli di struttura, con la numerazione
 * descritta in testa al paragrafo. Le grandezze devono essere già date
 * (model_sizes()). */
static void model_structure(Model *m) {
    /* 17v. Ogni numero scritto è un elemento diverso del suo insieme. */
    for (int s = 0; s < symbol_count; s++)
        if (symbols[s].name >= NUMERAL_NAMES) m->table[s][0] = (size_t)numeral_position(symbols[s].range, s);
    for (int i = 0; i < sort_count; i++) {
        if (sort_data[i].kind == SORT_PLAIN || sort_data[i].kind == SORT_NUMBERS) continue;
        size_t *cell = m->table[sort_data[i].symbol];
        size_t base = m->dimension[sort_data[i].base].size;
        for (size_t x = 0; x < m->dimension[i].size; x++)
            for (size_t a = 0, rest = x; a < base; a++) {
                /* Le parti: la cella di (a, x) dice se a sta nella parte x.
                 * Le applicazioni: quella di (x, a) è il valore di x in a. */
                if (sort_data[i].kind == SORT_PARTS) { cell[a + x * base] = (size_t)(x >> a & 1); continue; }
                cell[x + a * m->dimension[i].size] = (rest % m->dimension[sort_data[i].target].size);
                rest /= m->dimension[sort_data[i].target].size;
            }
    }
}

/* Quanti insiemi qualsiasi ha l'enunciato in corso: gli altri sono insiemi
 * di parti o di applicazioni, la cui grandezza non si sceglie. */
static int plain_sorts(void) {
    int count = 0;
    for (int i = 0; i < sort_count; i++) count += sort_data[i].kind == SORT_PLAIN;
    return count;
}

/* Prima composizione di total negli insiemi arbitrari: tutto nell'ultima
 * coordinata, zero nelle altre. Non usa una pila proporzionale ai tipi. */
static int model_composition_start(Model *m,size_t total) {
    int last=-1;
    for (int i=0;i<sort_count;i++) if (sort_data[i].kind==SORT_PLAIN) {
        m->dimension[i].extra=0;last=i;
    }
    if (last>=0) m->dimension[last].extra=total;
    return last>=0 || !total;
}

/* Composizione successiva, in ordine lessicografico. La coda non nulla
 * cede un elemento alla coordinata precedente; quelle attraversate sono
 * azzerate. La somma resta total, quindi l'incremento non puo traboccare.
 * Ogni composizione appare una volta, senza codificare base^sort_count. */
static int model_composition_next(Model *m) {
    int last=sort_count-1;
    while (last>=0 && sort_data[last].kind!=SORT_PLAIN) last--;
    if (last<0) return 0;
    size_t tail=m->dimension[last].extra;
    for (int i=last-1;i>=0;i--) if (sort_data[i].kind==SORT_PLAIN) {
        if (tail) {
            m->dimension[i].extra++;m->dimension[last].extra=tail-1;return 1;
        }
        tail=m->dimension[i].extra;m->dimension[i].extra=0;
    }
    return 0;
}

/* Materializza i valori della composizione e le cardinalita derivate.
 * maximum>0 delimita soltanto il campione indipendente dei libri: ripete
 * i vincoli del prefisso esaustivo. SAT chiama con zero e non li usa. */
static int model_composition_values(Model *m,size_t maximum) {
    for (int i=0;i<sort_count;i++) if (sort_data[i].kind==SORT_PLAIN) {
        ModelDimension *d=&m->dimension[i];
        if (d->extra>(size_t)-1-d->minimum) return 0;
        d->size=d->minimum+d->extra;
        if (maximum && d->size>maximum) return 0;
    }
    if (!model_derived_sizes(m)) return 0;
    for (int i=0;i<sort_count;i++) {
        if (m->dimension[i].size<m->dimension[i].minimum) return 0;
        if (maximum && sort_data[i].kind!=SORT_PLAIN && m->dimension[i].size>MAX_MODEL_OBJECTS) return 0;
    }
    if (maximum) for (int f=0;f<symbol_count;f++) {
        size_t cells;model_cells(m,f,&cells);
        if (cells>MAX_MODEL_CELLS) return 0;
    }
    return 1;
}

/* Ambiente riutilizzabile dei valutatori finiti. Il vettore possiede le
 * celle e cresce con gli slot della formula, non con la cardinalita degli
 * insiemi. Le valutazioni sono sequenziali e non creano slot: il puntatore
 * resta valido fino alla prossima chiamata a model_variables(). */
static size_t *model_values;
static size_t model_values_capacity;

/* Prepara valori iniziali zero per tutti gli slot correnti. Un errore di
 * allocazione non puo essere ignorato da una strategia successiva. */
static size_t *model_variables(void) {
    if (!work_reserve((void **)&model_values, &model_values_capacity, (size_t)slot_count, sizeof *model_values)) return NULL;
    if (slot_count) memset(model_values, 0, (size_t)slot_count * sizeof *model_values);
    return model_values;
}

/* Cerca un modello in cui la condizione root vale (wanted = 1) o non vale
 * (wanted = 0), tra quelli in cui ogni insieme ha da 1 a MAX_MODEL_SIZE
 * elementi, dai più piccoli. Se lo trova lo lascia in *m e ritorna 1.
 *
 * Non sempre li prova tutti: una scelta delle grandezze con più di
 * MAX_MODELS tabelle viene saltata, e dopo MAX_MODEL_WORK tabelle in tutto,
 * o model_step_limit elementi provati dai quantificatori, la ricerca si
 * ferma. In *tried mette quante tabelle ha provato, e in
 * *bound il più grande k per cui ha provato tutti i modelli con insiemi di
 * al più k elementi: è ciò che il verdetto può dire di aver controllato. */
static int model_search(const Sentence *root, int wanted, Model *m, long long *tried, int *bound) {
    size_t *value = model_variables();
    int codes = 1, complete[MAX_MODEL_CODES] = {0}, plain = plain_sorts();
    *tried = 0;
    *bound = 0;
    if (work_allocation_failed) return 0;
    model_steps = 0;
    if (!model_dimensions(m)) return 0;
    /* Questa strategia deve completare tutte le configurazioni per
     * certificare bound. Quando non entrano nella sua quota, passa a SAT;
     * non tronca un prodotto e non inventa un prefisso completato. */
    for (int i=0;i<plain;i++) {
        if (codes>MAX_MODEL_CODES/MAX_MODEL_SIZE) return 0;
        codes*=MAX_MODEL_SIZE;
    }

    /* Le grandezze, per numero totale di elementi degli insiemi qualsiasi:
     * code le elenca tutte, e a ogni giro si tengono quelle con quel totale.
     * Gli insiemi di parti e di applicazioni hanno la grandezza che segue
     * (28m). */
    for (int total = plain; sort_count && total <= plain * MAX_MODEL_SIZE && *tried < MAX_MODEL_WORK; total++) {
        for (int code = 0; code < codes && *tried < MAX_MODEL_WORK; code++) {
            if (model_sizes(m, code) != total) continue;

            /* Quante tabelle: il prodotto, su tutte le celle, dei valori
             * possibili. */
            double count = 1;
            for (int s = 0; s < symbol_count && count <= MAX_MODELS; s++) {
                size_t cells, values = model_cells(m, s, &cells);
                for (size_t c = 0; c < cells && count <= MAX_MODELS && !symbol_fixed(s); c++) count *= values;
            }
            if (count > MAX_MODELS) continue;

            /* Tutte le tabelle, come un contachilometri: si parte da tutte
             * le celle a zero e si aumenta la prima che può crescere,
             * azzerando quelle prima di lei. Quelle fissate dalla struttura
             * non cambiano. */
            if (!model_allocate(m)) continue;
            model_structure(m);
            for (int more = 1; more && *tried < MAX_MODEL_WORK; ) {
                /* Una risposta ottenuta a conto interrotto non conta, e la
                 * ricerca finisce lì: *tried è già oltre il suo limite. */
                int holds = model_holds(m, root, value);
                if (!model_steps_complete()) { *tried = MAX_MODEL_WORK; break; }
                ++*tried;
                if (holds == wanted) return 1;
                more = 0;
                for (int s = 0; s < symbol_count && !more; s++) {
                    if (symbol_fixed(s)) continue;
                    size_t cells, values = model_cells(m, s, &cells);
                    for (size_t c = 0; c < cells && !more; c++) {
                        if (++m->table[s][c] < values) more = 1; else m->table[s][c] = 0;
                    }
                }
                if (!more) complete[code] = 1;
            }
        }
    }

    /* Il piu grande k con tutte le grandezze fino a k provate per intero.
     * Ogni codice indica una scelta degli insiemi arbitrari: anche una
     * costruzione derivata troppo grande resta una scelta non completata. */
    for (int k = 1; k <= MAX_MODEL_SIZE; k++) {
        int all = 1;
        for (int code = 0; code < codes; code++) {
            int inside=1,rest=code;
            for (int i=0;i<sort_count;i++) if (sort_data[i].kind==SORT_PLAIN) {
                inside=inside && 1+rest%MAX_MODEL_SIZE<=k;rest/=MAX_MODEL_SIZE;
            }
            if (inside && !complete[code]) all = 0;
        }
        if (!all) break;
        *bound = k;
    }
    return 0;
}

/* 28t. MODELLI FINITI CON SAT
 *
 * Una casella f(a,b)=c e una variabile booleana. Una clausola impone che
 * ogni casella abbia almeno un valore, e le clausole a coppie che non ne
 * abbia due. Un termine composto ha un vettore di valori con lo stesso
 * vincolo; se i suoi argomenti valgono a,b, prende il valore della casella
 * (a,b). I quantificatori diventano congiunzioni o disgiunzioni finite.
 * Per i connettivi si introduce un nome con clausole equivalenti (Tseitin),
 * evitando di distribuire le disgiunzioni sulle congiunzioni.
 *
 * E la riduzione MACE a SAT: Claessen e Sorensson, "New techniques that
 * improve MACE-style finite model finding" (2003), e Reger, Suda e
 * Voronkov, "Finding finite models in multi-sorted first-order logic"
 * (2016), https://arxiv.org/abs/1604.08040. Qui si riscrive l'idea, non il
 * codice. Il piccolo risolutore usa clausole osservate, propagazione unitaria
 * e apprendimento del primo punto di implicazione unico (CDCL): risolve i
 * conflitti con le ragioni delle assegnazioni fino a una sola assegnazione
 * del livello corrente. La clausola cosi ottenuta segue dalle precedenti.
 *
 * SAT cerca soltanto. Anche una risposta sbagliata del risolutore non e una
 * dimostrazione: si estraggono le tabelle, model_holds() ricalcola la frase,
 * e 28f consegna il modello al verificatore indipendente. UNSAT e i limiti
 * di risorse non dimostrano mai un enunciato universale. Dopo il prefisso
 * esaustivo, le cardinalita crescono senza tetto; depositi, tabelle e testo
 * crescono sullo heap entro budget espliciti. Anche il checker usa indici
 * size_t e tabelle dinamiche, non un limite equivalente nascosto.
 */

/* Un letterale SAT e un indice con segno; la memoria necessaria per una
 * variabile esaurisce lo spazio indirizzabile prima dell'indice stesso. */
typedef ptrdiff_t SatLiteral;

/* Una clausola: first/count individuano i letterali nel deposito; next
 * collega i due osservatori nelle liste watch. Zero termina ogni lista. */
typedef struct {
    size_t first, count, next[2];
} SatClause;

/* Una variabile proposizionale: value e phase valgono -1,0,1; depth e il
 * livello di assegnazione, reason la clausola+1 (zero per una decisione).
 * seen serve all'analisi del conflitto, activity guida soltanto la ricerca. */
typedef struct {
    signed char value, phase;
    unsigned char seen;
    size_t depth, reason;
    unsigned long long activity;
} SatVariable;

/* Un valore finito: literal[v] significa "vale v". known=(size_t)-1
 * indica un vettore variabile, altrimenti il valore costante, rappresentato
 * senza allocare un vettore. symbol/arg/next condividono applicazioni e
 * costanti nella hash; symbol=-1 esclude una voce dalla condivisione.
 * literal e posseduto dalla voce, gli argomenti sono indici di altre voci. */
typedef struct {
    size_t size, known, arg[2], next;
    int symbol;
    SatLiteral *literal;
} SatTerm;

/* Metadati SAT di un insieme. named conta le costanti dichiarate, seen
 * quelle gia codificate; ordered_map e la sola mappa S->S ordinata per
 * simmetria, -1 se assente. Le celle sono possedute dallo stato SAT. */
typedef struct { size_t named,seen;int ordered_map; } SatSort;

/* Una ricerca possiede tutti i depositi, ognuno con capacita dinamica.
 * I contatori indicano le voci valide; i suffissi _cap le celle allocate.
 * var e term partono da 1; la variabile 1 e vera. trail contiene le
 * assegnazioni, limit[d] l'inizio del livello d, qhead la prima da propagare.
 * watch contiene 2*clausola+osservatore+1; hash contiene indici di term.
 * table associa ogni cella del modello al suo vettore; slots tiene gli
 * elementi legati. broken significa risorse finite, inconsistent conflitto.
 * bytes comprende le tabelle del modello e tutte le allocazioni SAT;
 * budget/work limitano il lavoro, mai la cardinalita di un insieme.
 * memory_limit, se non nullo, permette alla saturazione di condividere il
 * proprio budget con il SAT; zero conserva quello dei modelli finiti. */
typedef struct {
    size_t variables, clauses, literals, terms, level, assigned, qhead;
    int broken, inconsistent, memory_limited;
    unsigned long long work, budget;
    size_t bytes, memory_limit;
    SatVariable *var;
    SatClause *clause;
    SatLiteral *literal, *trail, *learned;
    size_t *watch, *limit, *hash;
    SatTerm *term;
    size_t var_cap, clause_cap, literal_cap, trail_cap, learned_cap;
    size_t watch_cap, limit_cap, term_cap, hash_cap;
    size_t **table, *slots;
    size_t table_cap, slots_cap;
    SatSort *sort;
    size_t sort_cap;
} SatState;

/* Registra lavoro prima di eseguirlo; un budget esaurito non e UNSAT. */
static int sat_spend(SatState *s, unsigned long long count) {
    unsigned long long budget = s->budget ? s->budget : model_work_limit;
    if (s->broken || s->work > budget || count > budget - s->work) { s->broken = 1; return 0; }
    s->work += count;
    return 1;
}

/* Riserva un deposito geometrico, conservando dati e proprieta anche se
 * realloc fallisce. Le celle nuove sono azzerate; nessuna capacita massima
 * e compilata nel programma. bytes contabilizza solo allocazioni riuscite. */
static int sat_reserve(SatState *s, void **data, size_t *capacity, size_t need, size_t unit) {
    if (s->broken) return 0;
    if (need <= *capacity) return 1;
    size_t cap = *capacity ? *capacity : 16, bytes, old;
    while (cap < need) {
        if (cap > (size_t)-1 / 2) { cap = need; break; }
        cap *= 2;
    }
    size_t limit = s->memory_limit ? s->memory_limit : model_memory_limit;
    if (!model_product(cap, unit, &bytes) || !model_product(*capacity, unit, &old) ||
        s->bytes > limit || bytes - old > limit - s->bytes) {
        s->broken = s->memory_limited = 1; return 0;
    }
    void *p = realloc(*data, bytes);
    if (!p) { s->broken = s->memory_limited = 1; return 0; }
    memset((unsigned char *)p + old, 0, bytes - old);
    *data = p; *capacity = cap; s->bytes += bytes - old;
    return 1;
}

/* Libera ogni deposito della ricerca, comprese le tabelle di indici e i
 * vettori di valori posseduti dai termini. Puo seguire una crescita fallita. */
static void sat_clear(SatState *s) {
    for (size_t i = 1; i <= s->terms; i++) free(s->term[i].literal);
    for (size_t i = 0; i < s->table_cap; i++) free(s->table[i]);
    free(s->table);
    free(s->sort);
    free(s->var); free(s->clause); free(s->literal); free(s->trail);
    free(s->learned); free(s->watch); free(s->limit); free(s->hash); free(s->term); free(s->slots);
    memset(s, 0, sizeof *s);
}

/* Valore assoluto di un letterale prodotto dal risolutore, mai PTRDIFF_MIN. */
static size_t sat_index(SatLiteral l) { return (size_t)(l > 0 ? l : -l); }

/* Il posto nella lista osservata del letterale non nullo l. */
static size_t sat_watch_index(SatLiteral l) { return 2 * (sat_index(l) - 1) + (l < 0); }

/* Il valore del letterale l: 1 vero, -1 falso, 0 non assegnato. */
static int sat_value(const SatState *s, SatLiteral l) { return l > 0 ? s->var[l].value : -s->var[-l].value; }

/* Crea una variabile e riserva insieme i depositi indicizzati da essa.
 * In caso di risorse finite ritorna la costante vera e pone broken: nessun
 * chiamante puo usare quel valore come un modello accettato. */
static SatLiteral sat_variable(SatState *s) {
    size_t v = s->variables + 1;
    if (!sat_spend(s, 1) || v > (size_t)PTRDIFF_MAX || v > ((size_t)-1 - 2) / 2 ||
        !sat_reserve(s, (void **)&s->var, &s->var_cap, v + 2, sizeof *s->var) ||
        !sat_reserve(s, (void **)&s->watch, &s->watch_cap, 2 * v, sizeof *s->watch) ||
        !sat_reserve(s, (void **)&s->trail, &s->trail_cap, v + 2, sizeof *s->trail) ||
        !sat_reserve(s, (void **)&s->learned, &s->learned_cap, v + 2, sizeof *s->learned) ||
        !sat_reserve(s, (void **)&s->limit, &s->limit_cap, v + 2, sizeof *s->limit)) {
        s->broken = 1; return 1;
    }
    s->variables = v;
    s->var[v].phase = -1;
    return (SatLiteral)v;
}

/* Assegna l con la ragione data (zero: decisione), se non era gia falso.
 * Non alloca memoria: propagazione e analisi possono conservare puntatori. */
static int sat_assign(SatState *s, SatLiteral l, size_t reason) {
    if (s->broken) return 0;
    if (sat_value(s, l)) return sat_value(s, l) > 0;
    size_t v = sat_index(l);
    s->var[v].value = s->var[v].phase = l > 0 ? 1 : -1;
    s->var[v].depth = s->level;
    s->var[v].reason = reason;
    s->trail[s->assigned++] = l;
    return 1;
}

/* Aggiunge una clausola togliendo duplicati e falso; una tautologia non
 * serve. Ritorna clausola+1, o zero se non scrive. Le unitarie si assegnano
 * subito; le altre osservano i primi due posti. Il deposito dei letterali
 * puo spostarsi, quindi l'input non deve puntarvi dentro. */
static size_t sat_clause(SatState *s, const SatLiteral *literal, size_t count) {
    if (s->broken || s->inconsistent) return 0;
    if (!sat_spend(s, count + 1)) return 0;
    if (!count) { s->inconsistent = 1; return 0; }
    if (count > (size_t)-1 - s->literals || s->clauses > ((size_t)-1 - 2) / 2 ||
        !sat_reserve(s, (void **)&s->literal, &s->literal_cap, s->literals + count, sizeof *s->literal) ||
        !sat_reserve(s, (void **)&s->clause, &s->clause_cap, s->clauses + 1, sizeof *s->clause)) {
        s->broken = 1; return 0;
    }
    size_t first = s->literals, used = 0;
    for (size_t i = 0; i < count; i++) {
        SatLiteral l = literal[i];
        int repeated = 0;
        if (l == 1) return 0;
        if (l == -1) continue;
        for (size_t j = 0; j < used; j++) {
            if (!sat_spend(s, 1)) return 0;
            if (s->literal[first + j] == -l) return 0;
            repeated |= s->literal[first + j] == l;
        }
        if (!repeated) s->literal[first + used++] = l;
    }
    if (!used) { s->inconsistent = 1; return 0; }
    size_t c = s->clauses++;
    s->clause[c] = (SatClause){first, used, {0, 0}};
    s->literals += used;
    for (size_t i = 0; i < used; i++) s->var[sat_index(s->literal[first + i])].activity++;
    if (used == 1) {
        if (!sat_assign(s, s->literal[first], c + 1)) s->inconsistent = 1;
    } else for (size_t w = 0; w < 2; w++) {
        size_t at = sat_watch_index(s->literal[first + w]);
        s->clause[c].next[w] = s->watch[at];
        s->watch[at] = 2 * c + w + 1;
    }
    return c + 1;
}

/* Propaga solo gli osservatori diventati falsi: un sostituto evita di
 * esaminare la clausola alle altre assegnazioni. Senza sostituto, l'altro
 * osservato e obbligato. Ritorna clausola+1 per un conflitto, zero altrimenti. */
static size_t sat_propagate(SatState *s) {
    while (s->qhead < s->assigned && !s->broken) {
        SatLiteral false_literal = -s->trail[s->qhead++];
        size_t *link = &s->watch[sat_watch_index(false_literal)];
        while (*link) {
            if (!sat_spend(s, 1)) return 0;
            size_t edge = *link - 1, c = edge / 2, w = edge % 2;
            SatClause *clause = &s->clause[c];
            SatLiteral *v = s->literal + clause->first, other = v[1 - w];
            if (sat_value(s, other) > 0) { link = &clause->next[w]; continue; }
            size_t k = 2;
            while (k < clause->count && sat_value(s, v[k]) < 0) {
                if (!sat_spend(s, 1)) return 0;
                k++;
            }
            if (k < clause->count) {
                SatLiteral replacement = v[k];
                size_t at = sat_watch_index(replacement);
                v[k] = v[w]; v[w] = replacement;
                *link = clause->next[w]; clause->next[w] = s->watch[at]; s->watch[at] = edge + 1;
                continue;
            }
            if (!sat_assign(s, other, c + 1)) return c + 1;
            link = &clause->next[w];
        }
    }
    return 0;
}

/* Cancella le assegnazioni dopo il livello indicato; conserva fasi e
 * propagazioni precedenti, che non dipendono dalle decisioni cancellate. */
static void sat_backtrack(SatState *s, size_t level) {
    size_t keep = s->limit[level + 1];
    while (s->assigned > keep) s->var[sat_index(s->trail[--s->assigned])].value = 0;
    s->qhead = s->assigned; s->level = level;
}

/* Decide la CNF: 1 SAT, -1 UNSAT, 0 risorse finite. Risolve un conflitto
 * all'indietro con le sue ragioni fino al primo punto di implicazione unico
 * (un solo letterale al livello corrente). La clausola cosi ottenuta segue
 * dalle precedenti e diventa unitaria al livello degli altri letterali. */
static int sat_solve(SatState *s) {
    unsigned long long bump = 32, conflicts = 0;
    if (s->broken) return 0;
    if (s->inconsistent) return -1;
    for (;;) {
        size_t conflict = sat_propagate(s);
        if (s->broken) return 0;
        if (conflict) {
            if (!s->level) return -1;
            size_t count = 1, pending = 0, at = s->assigned;
            SatLiteral pivot = 0;
            do {
                SatClause *clause = &s->clause[conflict - 1];
                for (size_t i = 0; i < clause->count; i++) {
                    if (!sat_spend(s, 1)) return 0;
                    SatLiteral l = s->literal[clause->first + i];
                    size_t v = sat_index(l);
                    if (v == sat_index(pivot) || s->var[v].seen || !s->var[v].depth) continue;
                    s->var[v].seen = 1; s->var[v].activity += bump;
                    if (s->var[v].depth == s->level) pending++;
                    else s->learned[count++] = l;
                }
                do { pivot = s->trail[--at]; } while (!s->var[sat_index(pivot)].seen);
                s->var[sat_index(pivot)].seen = 0; pending--;
                conflict = s->var[sat_index(pivot)].reason;
            } while (pending && conflict);
            if (pending) { s->broken = 1; return 0; }
            s->learned[0] = -pivot;
            size_t level = 0;
            for (size_t i = 1; i < count; i++) {
                size_t v = sat_index(s->learned[i]);
                s->var[v].seen = 0;
                if (s->var[v].depth > level) level = s->var[v].depth;
            }
            sat_backtrack(s, level);
            size_t reason = sat_clause(s, s->learned, count);
            if (s->broken) return 0;
            if (s->inconsistent || !sat_assign(s, s->learned[0], reason)) return -1;
            if (++conflicts % 128 == 0) {
                bump *= 2;
                if (bump > (1ULL << 40)) {
                    for (size_t v = 2; v <= s->variables; v++) s->var[v].activity /= 2;
                    bump /= 2;
                }
            }
            continue;
        }
        size_t choose = 0;
        for (size_t v = 2; v <= s->variables; v++) {
            if (!sat_spend(s, 1)) return 0;
            if (!s->var[v].value && (!choose || s->var[v].activity > s->var[choose].activity)) choose = v;
        }
        if (!choose) return 1;
        s->limit[++s->level] = s->assigned;
        sat_assign(s, s->var[choose].phase > 0 ? (SatLiteral)choose : -(SatLiteral)choose, 0);
    }
}

/* Nome equivalente ad a e b; le clausole sono q=>a, q=>b, (a e b)=>q. */
static SatLiteral sat_and(SatState *s, SatLiteral a, SatLiteral b) {
    if (s->broken) return -1;
    if (a == b || b == 1) return a;
    if (a == 1) return b;
    if (a == -1 || b == -1 || a == -b) return -1;
    SatLiteral q = sat_variable(s);
    sat_clause(s, (SatLiteral[]){-q, a}, 2);
    sat_clause(s, (SatLiteral[]){-q, b}, 2);
    sat_clause(s, (SatLiteral[]){q, -a, -b}, 3);
    return q;
}

/* La disgiunzione, con De Morgan. */
static SatLiteral sat_or(SatState *s, SatLiteral a, SatLiteral b) { return -sat_and(s, -a, -b); }

/* Hash di una costante o applicazione: l'overflow unsigned e intenzionale
 * e cambia soltanto il contenitore, mai l'identita controllata dei termini. */
static size_t sat_term_hash(int symbol, size_t a, size_t b) {
    return (size_t)(unsigned)(symbol + 2) * 1009u + a * 9176u + b * 6361u;
}

/* Aggiunge un termine vuoto e allarga la hash. I puntatori a term possono
 * spostarsi: chi chiama conserva indici, non indirizzi, durante una crescita. */
static size_t sat_term(SatState *s, size_t size, size_t known) {
    if (!sat_spend(s, 1) || !size || s->terms > ((size_t)-1 - 4) / 2 ||
        !sat_reserve(s, (void **)&s->term, &s->term_cap, s->terms + 2, sizeof *s->term)) {
        s->broken = 1; return 0;
    }
    size_t old = s->hash_cap;
    if (!sat_reserve(s, (void **)&s->hash, &s->hash_cap, 2 * (s->terms + 2), sizeof *s->hash)) return 0;
    if (old != s->hash_cap) {
        memset(s->hash, 0, s->hash_cap * sizeof *s->hash);
        for (size_t i = 1; i <= s->terms; i++) if (s->term[i].symbol != -1) {
            SatTerm *t = &s->term[i];
            size_t at = sat_term_hash(t->symbol, t->arg[0], t->arg[1]) % s->hash_cap;
            t->next = s->hash[at]; s->hash[at] = i;
        }
    }
    size_t id = ++s->terms;
    s->term[id] = (SatTerm){.size=size, .known=known, .symbol=-1};
    return id;
}

/* Legge un letterale di valore, anche dalle costanti senza vettore. */
static SatLiteral sat_at(const SatState *s, size_t id, size_t value) {
    const SatTerm *t = &s->term[id];
    return t->known != (size_t)-1 ? (t->known == value ? 1 : -1) : t->literal[value];
}

/* Crea un vettore one-hot. Il vincolo "al piu uno" usa una catena di
 * prefissi: p_i significa che un valore precedente e vero; p_i e v_i non
 * possono essere veri insieme. Costo lineare, senza le coppie quadratiche.
 * L'ultima clausola impone almeno un valore; due valori usano un solo bit. */
static size_t sat_vector(SatState *s, size_t size) {
    size_t id = sat_term(s, size, size == 1 ? 0 : (size_t)-1);
    if (!id || size == 1) return id;
    size_t cap = 0;
    if (!sat_reserve(s, (void **)&s->term[id].literal, &cap, size, sizeof(SatLiteral))) return id;
    SatLiteral *literal = s->term[id].literal;
    if (size == 2) { literal[1] = sat_variable(s); literal[0] = -literal[1]; return id; }
    for (size_t v = 0; v < size && !s->broken; v++) literal[v] = sat_variable(s);
    sat_clause(s, literal, size);
    SatLiteral prefix = literal[0];
    for (size_t v = 1; v < size && !s->broken; v++) {
        sat_clause(s, (SatLiteral[]){-prefix, -literal[v]}, 2);
        if (v + 1 < size) prefix = sat_or(s, prefix, literal[v]);
    }
    return id;
}

/* Condivide il valore costante (size,value), senza allocare size letterali. */
static size_t sat_constant(SatState *s, size_t size, size_t value) {
    if (s->broken) return 0;
    if (!size || value >= size) { s->broken = 1; return 0; }
    if (s->hash_cap) {
        size_t at = sat_term_hash(-2, size, value) % s->hash_cap;
        for (size_t i = s->hash[at]; i; i = s->term[i].next)
            if (s->term[i].symbol == -2 && s->term[i].arg[0] == size && s->term[i].arg[1] == value) return i;
    }
    size_t id = sat_term(s, size, value);
    if (!id) return 0;
    SatTerm *t = &s->term[id]; t->symbol = -2; t->arg[0] = size; t->arg[1] = value;
    size_t at = sat_term_hash(-2, size, value) % s->hash_cap;
    t->next = s->hash[at]; s->hash[at] = id;
    return id;
}

/* Il vettore booleano equivalente al letterale, senza nuove variabili. */
static size_t sat_boolean(SatState *s, SatLiteral literal) {
    if (literal == 1 || literal == -1) return sat_constant(s, 2, literal == 1);
    size_t id = sat_term(s, 2, (size_t)-1), cap = 0;
    if (!id || !sat_reserve(s, (void **)&s->term[id].literal, &cap, 2, sizeof(SatLiteral))) return 0;
    s->term[id].literal[0] = -literal; s->term[id].literal[1] = literal;
    return id;
}

/* Traduce un'applicazione. Argomenti fissati selezionano una cella;
 * altrimenti ogni combinazione implica il valore di quella cella. La hash
 * condivide i termini composti. Le parti legate hanno vettori separati. */
static size_t sat_application(SatState *s, const Model *m, int symbol, size_t a, size_t b) {
    if (s->broken) return 0;
    const Symbol *f = &symbols[symbol];
    if (symbol_bound[symbol]) {
        SatLiteral truth = -1;
        for (size_t v = 0; v < m->dimension[f->domain[0]].size && !s->broken; v++)
            if (m->part[symbol][v]) truth = sat_or(s, truth, sat_at(s, a, v));
        return sat_boolean(s, truth);
    }
    size_t av = a ? s->term[a].known : 0, bv = b ? s->term[b].known : 0;
    if (av != (size_t)-1 && bv != (size_t)-1) return s->table[symbol][av + bv * (a ? m->dimension[f->domain[0]].size : 1)];
    size_t at = sat_term_hash(symbol, a, b) % s->hash_cap;
    for (size_t i = s->hash[at]; i; i = s->term[i].next)
        if (s->term[i].symbol == symbol && s->term[i].arg[0] == a && s->term[i].arg[1] == b) return i;
    size_t size = f->range == TRUTH ? 2 : m->dimension[f->range].size, id = sat_vector(s, size);
    if (s->broken) return 0;
    /* sat_vector puo aver spostato sia term sia hash. */
    SatTerm *out = &s->term[id];
    at = sat_term_hash(symbol, a, b) % s->hash_cap;
    out->symbol = symbol; out->arg[0] = a; out->arg[1] = b; out->next = s->hash[at]; s->hash[at] = id;
    size_t na = a ? m->dimension[f->domain[0]].size : 1, nb = b ? m->dimension[f->domain[1]].size : 1;
    for (size_t y = 0; y < nb && !s->broken; y++)
        for (size_t x = 0; x < na && !s->broken; x++) {
            SatLiteral la = a ? sat_at(s, a, x) : 1, lb = b ? sat_at(s, b, y) : 1;
            if (la == -1 || lb == -1) continue;
            size_t cell = s->table[symbol][x + y * na];
            for (size_t v = 0; v < size && !s->broken; v++)
                sat_clause(s, (SatLiteral[]){-la, -lb, -sat_at(s, cell, v), sat_at(s, id, v)}, 4);
        }
    return id;
}

/* Il vettore di un termine con i legami correnti. */
static size_t sat_element(SatState *s, const Model *m, const Elem *e) {
    if (s->broken) return 0;
    if (e->symbol < 0) return sat_constant(s, m->dimension[slot_data[e->slot].sort].size, s->slots[e->slot]);
    size_t a = e->arg[0] ? sat_element(s, m, e->arg[0]) : 0;
    size_t b = e->arg[1] ? sat_element(s, m, e->arg[1]) : 0;
    return sat_application(s, m, e->symbol, a, b);
}

/* Due vettori one-hot sono uguali se hanno lo stesso valore. Con un lato
 * costante basta un letterale; altrimenti ogni valore impone l'equivalenza. */
static SatLiteral sat_equal(SatState *s, size_t a, size_t b) {
    if (s->broken) return -1;
    if (a == b) return 1;
    size_t x = s->term[a].known, y = s->term[b].known;
    if (x != (size_t)-1) return sat_at(s, b, x);
    if (y != (size_t)-1) return sat_at(s, a, y);
    SatLiteral q = sat_variable(s);
    for (size_t v = 0; v < s->term[a].size && !s->broken; v++) {
        sat_clause(s, (SatLiteral[]){-q, -sat_at(s, a, v), sat_at(s, b, v)}, 3);
        sat_clause(s, (SatLiteral[]){q, -sat_at(s, a, v), -sat_at(s, b, v)}, 3);
    }
    return q;
}

/* Traduce i connettivi con Tseitin e i quantificatori con congiunzioni o
 * disgiunzioni finite. Gli insiemi vuoti danno le identita vere/falso; le
 * parti si enumerano con un vettore binario, senza shift di lunghezza n. */
static SatLiteral sat_sentence(SatState *s, const Model *m, const Sentence *f) {
    if (!sat_spend(s, 1)) return -1;
    SatLiteral a, b;
    switch (f->kind) {
    case S_TRUE: return 1;
    case S_EQUIPOTENT: {
        int equal = model_equipotent(m, f);
        if (!model_steps_complete()) s->broken = 1;
        return equal ? 1 : -1;
    }
    case S_EQUAL: {
        size_t left = sat_element(s, m, f->left), right = sat_element(s, m, f->right);
        return sat_equal(s, left, right);
    }
    case S_HOLDS: {
        size_t id = sat_element(s, m, f->left);
        return s->broken ? -1 : sat_at(s, id, 1);
    }
    case S_NOT: return -sat_sentence(s, m, f->a);
    case S_AND: case S_OR: case S_IMPLIES: case S_IFF:
        a = sat_sentence(s, m, f->a); b = sat_sentence(s, m, f->b);
        if (f->kind == S_AND) return sat_and(s, a, b);
        if (f->kind == S_OR) return sat_or(s, a, b);
        if (f->kind == S_IMPLIES) return sat_or(s, -a, b);
        return sat_or(s, sat_and(s, a, b), sat_and(s, -a, -b));
    case S_FORALL: case S_EXISTS: {
        int every = f->kind == S_FORALL;
        SatLiteral result = every ? 1 : -1;
        size_t saved = s->slots[f->slot];
        for (size_t x = 0; x < m->dimension[slot_data[f->slot].sort].size && !s->broken; x++) {
            s->slots[f->slot] = x; a = sat_sentence(s, m, f->a);
            result = every ? sat_and(s, result, a) : sat_or(s, result, a);
        }
        s->slots[f->slot] = saved;
        return result;
    }
    case S_FORALL_PART: case S_EXISTS_PART: {
        int every = f->kind == S_FORALL_PART;
        SatLiteral result = every ? 1 : -1;
        size_t n = m->dimension[symbols[f->part].domain[0]].size, cap = 0;
        unsigned char *saved = m->part[f->part], *bits = NULL;
        if (!sat_reserve(s, (void **)&bits, &cap, n ? n : 1, 1)) return -1;
        m->part[f->part] = bits;
        for (;;) {
            a = sat_sentence(s, m, f->a);
            result = every ? sat_and(s, result, a) : sat_or(s, result, a);
            if (s->broken || result == (every ? -1 : 1)) break;
            size_t bit = 0;
            while (bit < n && bits[bit]) bits[bit++] = 0;
            if (bit == n) break;
            bits[bit] = 1;
        }
        m->part[f->part] = saved; free(bits); s->bytes -= cap;
        return result;
    }
    case S_MEMBER: case S_INCLUDED: case S_SAME: case S_UNIQUE:
        s->broken = 1; return -1;
    }
    s->broken = 1; return -1;
}

/* Cerca un modello delle dimensioni correnti, spendendo il budget rimasto.
 * I dati estratti sono ricalcolati per intero, prima del successivo controllo
 * indipendente nel certificato. UNSAT e risorse finite ritornano entrambi 0. */
static int model_sat(const Sentence *root, int wanted, Model *m, unsigned long long *work) {
    if (*work >= model_work_limit) return 0;
    ++*work;
    if (!model_allocate(m)) { if (m->limited) *work = model_work_limit; return 0; }
    SatState s = {.bytes=m->bytes, .budget=model_work_limit - *work};
    if (!s.budget) return 0;
    sat_reserve(&s, (void **)&s.slots, &s.slots_cap, (size_t)slot_count, sizeof *s.slots);
    sat_variable(&s); sat_assign(&s, 1, 0);
    model_steps = 0;
    model_structure(m);
    sat_reserve(&s,(void **)&s.sort,&s.sort_cap,(size_t)sort_count,sizeof *s.sort);
    for (int i=0;i<sort_count && !s.broken;i++) s.sort[i].ordered_map=-1;
    for (int f = 0; f < symbol_count && !s.broken; f++) {
        int sort = symbols[f].range;
        if (sort < 0 || sort >= sort_count || sort_data[sort].kind != SORT_PLAIN || symbol_fixed(f) || symbol_bound[f]) continue;
        if (!symbols[f].arity) s.sort[sort].named++;
        if (symbols[f].arity == 1 && symbols[f].domain[0] == sort && s.sort[sort].ordered_map < 0) s.sort[sort].ordered_map = f;
    }
    sat_reserve(&s, (void **)&s.table, &s.table_cap, (size_t)symbol_count, sizeof *s.table);
    for (int f = 0; f < symbol_count && !s.broken; f++) {
        if (symbol_bound[f]) continue;
        size_t cells, values = model_cells(m, f, &cells), cap = 0;
        if (!sat_reserve(&s, (void **)&s.table[f], &cap, cells ? cells : 1, sizeof(size_t))) break;
        for (size_t c = 0; c < cells && !s.broken; c++) {
            size_t id = symbol_fixed(f) ? sat_constant(&s, values, m->table[f][c]) : sat_vector(&s, values);
            if (s.broken) break;
            s.table[f][c] = id;
            if (s.term[id].known == (size_t)-1)
                for (size_t v = 0; v < values; v++) s.var[sat_index(sat_at(&s, id, v))].phase = 1;
        }
        /* Rottura generale delle simmetrie. Numera prima gli elementi con
         * un nome, nell'ordine in cui appaiono: il j-esimo nome vale al piu
         * j, anche se due nomi coincidono. Poi visita una sola mappa S->S,
         * in ordine di argomento, dando a ogni elemento nuovo il prossimo
         * numero libero. Dopo i nomi e i argomenti, f(i) vale al piu k+i,
         * con k=max(1,numero dei nomi). Se non ci sono nomi si parte da un
         * elemento arbitrario. Ogni modello ammette questa rinumerazione;
         * non si ordina una seconda mappa, che potrebbe contraddirla. */
        int sort = symbols[f].range;
        if (!s.broken && sort >= 0 && sort < sort_count && sort_data[sort].kind == SORT_PLAIN) {
            if (!symbols[f].arity) {
                size_t last = s.sort[sort].seen++;
                for (size_t v = last + 1; v < values && !s.broken; v++) {
                    SatLiteral excluded = -sat_at(&s, s.table[f][0], v);
                    sat_clause(&s, &excluded, 1);
                }
            } else if (s.sort[sort].ordered_map == f) {
                size_t seed = s.sort[sort].named ? s.sort[sort].named : 1;
                for (size_t c = 0; c < cells && c < values && seed < values - c && !s.broken; c++)
                    for (size_t v = seed + c + 1; v < values && !s.broken; v++) {
                        SatLiteral excluded = -sat_at(&s, s.table[f][c], v);
                        sat_clause(&s, &excluded, 1);
                    }
            }
        }
    }
    SatLiteral truth = sat_sentence(&s, m, root);
    sat_clause(&s, (SatLiteral[]){wanted ? truth : -truth}, 1);
    int found = sat_solve(&s) == 1;
    if (found) {
        for (int f = 0; f < symbol_count && found; f++) {
            if (symbol_fixed(f) || symbol_bound[f]) continue;
            size_t cells; model_cells(m, f, &cells);
            for (size_t c = 0; c < cells; c++) {
                size_t id = s.table[f][c], value = 0;
                while (value < s.term[id].size && sat_value(&s, sat_at(&s, id, value)) <= 0) value++;
                if (value == s.term[id].size) { found = 0; break; }
                m->table[f][c] = value;
            }
        }
        size_t *value = s.slots;
        model_steps = 0;
        int confirmed = found && model_holds(m, root, value) == wanted;
        if (!confirmed && model_steps_complete()) unjustified_steps++;
        if (found && !model_steps_complete())
            model_unconfirmed = "trovato un modello candidato, ma ricalcolarvi l'enunciato supera il budget dei passi (--model-steps): non conta come controesempio";
        found = confirmed && model_steps_complete();
    }
    *work += s.work;

    /* Anche un modello che non si riesce a ricalcolare ferma la ricerca: i
     * modelli più grandi costerebbero di più, e il budget che manca è
     * quello dei passi, non quello della ricerca. */
    if (s.memory_limited || (!found && model_unconfirmed)) *work = model_work_limit;
    sat_clear(&s);
    return found;
}

/* Consuma visite delle coordinate e dei tipi senza overflow del contatore.
 * Un budget esaurito non e una risposta di UNSAT. */
static int model_visit(unsigned long long *work,unsigned long long count) {
    if (*work>model_work_limit || count>model_work_limit-*work) { *work=model_work_limit;return 0; }
    *work+=count;return 1;
}

/* Se la polarita richiede un testimone ordinario, il suo insieme non e
 * vuoto. Congiunzioni vere e disgiunzioni false obbligano entrambi i lati;
 * un'implicazione falsa obbliga premessa vera e conclusione falsa. Le altre
 * alternative non sono assunte. Un testimone di una parte non obbliga il
 * suo insieme base: anche l'insieme vuoto ha una parte. */
static int model_required_sorts(Model *m,const Sentence *s,int wanted,unsigned long long *work) {
    if (!s || !model_visit(work,1)) return s==NULL;
    if (s->kind==S_NOT) return model_required_sorts(m,s->a,!wanted,work);
    if ((s->kind==S_AND && wanted) || (s->kind==S_OR && !wanted))
        return model_required_sorts(m,s->a,wanted,work) && model_required_sorts(m,s->b,wanted,work);
    if (s->kind==S_IMPLIES && !wanted)
        return model_required_sorts(m,s->a,1,work) && model_required_sorts(m,s->b,0,work);
    if ((s->kind==S_EXISTS && wanted) || (s->kind==S_FORALL && !wanted)) {
        m->dimension[slot_data[s->slot].sort].minimum=1;
        return model_required_sorts(m,s->a,wanted,work);
    }
    if ((s->kind==S_EXISTS_PART && wanted) || (s->kind==S_FORALL_PART && !wanted))
        return model_required_sorts(m,s->a,wanted,work);
    return 1;
}

/* Limiti inferiori logicamente necessari, non scelte euristiche. Una
 * costante esige un valore; una funzione con argomenti in insiemi non
 * vuoti esige un codominio non vuoto. Il punto fisso propaga solo queste
 * implicazioni. Saltare cardinalita inferiori non perde alcun modello. */
static int model_minimums(Model *m,const Sentence *root,int wanted,unsigned long long *work) {
    if (!model_dimensions(m)) return 0;
    for (int i=0;i<sort_count;i++) {
        if (!model_visit(work,1)) return 0;
        m->dimension[i].minimum=sort_data[i].kind==SORT_PARTS || sort_data[i].kind==SORT_NUMBERS;
    }
    if (!model_required_sorts(m,root,wanted,work)) return 0;
    for (int changed=1;changed;) {
        changed=0;
        for (int f=0;f<symbol_count;f++) {
            if (!model_visit(work,1)) return 0;
            const Symbol *symbol=&symbols[f];
            if (symbol->range==TRUTH || m->dimension[symbol->range].minimum) continue;
            int nonempty=1;
            for (int a=0;a<symbol->arity;a++) nonempty &= m->dimension[symbol->domain[a]].minimum>0;
            if (nonempty) { m->dimension[symbol->range].minimum=1;changed=1; }
        }
    }
    return 1;
}

/* Enumera le composizioni dell'eccesso total oltre i limiti inferiori.
 * Per ogni totale sono finitissime, e ogni vettore ammissibile viene
 * raggiunto. Visite, modelli scartati e coordinata finale consumano lavoro;
 * nessuna ricorsione o potenza codifica il numero degli insiemi. */
static int model_sat_total(const Sentence *root,int wanted,Model *m,size_t total,
                           unsigned long long *work,int bound) {
    if (!model_dimensions(m) || !model_composition_start(m,total)) return 0;
    do {
        if (!model_visit(work,(unsigned long long)sort_count+1)) return 0;
        if (!model_composition_values(m,0)) continue;
        int small=bound>0;
        for (int i=0;i<sort_count;i++)
            if (sort_data[i].kind==SORT_PLAIN && (!m->dimension[i].size || m->dimension[i].size>(size_t)bound)) small=0;
        if (!small && model_sat(root,wanted,m,work)) return 1;
    } while (*work<model_work_limit && model_composition_next(m));
    return 0;
}

/* Prosegue dopo il prefisso esaustivo, senza una cardinalita o un numero
 * di tentativi massimi. Il budget totale di lavoro/memoria e esplicito e
 * configurabile; esaurirlo non autorizza un verdetto matematico positivo. */
static int model_sat_search(const Sentence *root, int wanted, Model *m, long long *tried, int bound) {
    unsigned long long work = 0;
    if (!model_minimums(m,root,wanted,&work)) return 0;
    for (size_t total = 0; work < model_work_limit; total++) {
        if (model_sat_total(root, wanted, m, total, &work, bound)) { ++*tried; return 1; }
        if (!plain_sorts() || total == (size_t)-1) break;
    }
    return 0;
}

/* Ritorna il numero che il pedice index scrive: index stesso, o 0 per
 * ZERO_INDEX (17v). */
static int index_digits(int index) { return index == ZERO_INDEX ? 0 : index; }

/* Scrive il nome del simbolo di posto symbol: la lettera, o il comando
 * LaTeX, con il pedice se c'è. */
static void put_symbol(int symbol) {
    const Symbol *s = &symbols[symbol];
    if (s->name >= NUMERAL_NAMES) { proof_add("%d", s->name - NUMERAL_NAMES); return; }
    if (s->name < 0) { proof_add(sort_data[symbol_structure(symbol)].kind == SORT_PARTS ? "\\in" : "\\operatorname{ev}"); return; }
    if (s->name >= RELATION_NAMES) proof_add("\\%s", relation_commands[s->name - RELATION_NAMES]);
    else if (s->name >= GREEK_NAMES) proof_add("\\%s", greek_letters[s->name - GREEK_NAMES]);
    else if (s->name >= OPERATION_NAMES) proof_add("\\%s", operation_symbols[s->name - OPERATION_NAMES]);
    else proof_add("%c", s->name);
    if (s->index <= LETTER_INDEX) proof_add("_{%c}", LETTER_INDEX - s->index);
    else if (s->index) proof_add("_{%d}", index_digits(s->index));
}

/* Scrive il nome dell'insieme di posto sort: la lettera, o (17v)
 * \mathcal{P}(S) e T^{S}. */
static void put_sort(int sort) {
    if (sort_data[sort].kind == SORT_PLAIN) {
        proof_add("%c", sort_data[sort].name);
        if (sort_data[sort].index) proof_add("_{%d}", sort_data[sort].index);  /* 17w */
        return;
    }
    if (sort_data[sort].kind == SORT_NUMBERS) {
        /* 17v. I numeri che l'enunciato scrive. */
        proof_add("\\{");
        for (int s = 0, written = 0; s < symbol_count; s++)
            if (symbols[s].name >= NUMERAL_NAMES && symbols[s].range == sort) { if (written++) proof_add(", "); put_symbol(s); }
        proof_add("\\}");
        return;
    }
    if (sort_data[sort].kind == SORT_PARTS) { proof_add("\\mathcal{P}("); put_sort(sort_data[sort].base); proof_add(")"); return; }
    put_sort(sort_data[sort].target);
    proof_add("^{");
    put_sort(sort_data[sort].base);
    proof_add("}");
}

/* Scrive l'elemento numero x dell'insieme di posto sort in un modello: la
 * minuscola della lettera dell'insieme, con il numero per pedice. Così gli
 * elementi di due insiemi diversi non si confondono. Un elemento di un
 * insieme di parti si scrive come la parte che è, \{s_{0}, s_{2}\}; uno di
 * un insieme di applicazioni con i suoi valori, (s_{0} \mapsto t_{1}, ...),
 * con la numerazione di 28m. */
static void put_model_element(const Model *m, int sort, size_t x) {
    if (sort_data[sort].kind == SORT_PLAIN && sort_data[sort].index) { proof_add("%c_{%d,%zu}", tolower(sort_data[sort].name), sort_data[sort].index, x); return; }  /* 17w */
    if (sort_data[sort].kind == SORT_PLAIN) { proof_add("%c_{%zu}", tolower(sort_data[sort].name), x); return; }
    if (sort_data[sort].kind == SORT_NUMBERS) {
        /* 17v. Il numero che l'elemento x rappresenta. */
        for (int s = 0; s < symbol_count; s++)
            if (symbols[s].name >= NUMERAL_NAMES && symbols[s].range == sort && (size_t)numeral_position(sort, s) == x) put_symbol(s);
        return;
    }
    proof_add(sort_data[sort].kind == SORT_PARTS ? "\\{" : "(");
    for (size_t a = 0, written = 0, rest = x; a < m->dimension[sort_data[sort].base].size; a++) {
        if (sort_data[sort].kind == SORT_PARTS && !(x >> a & 1)) continue;
        if (written++) proof_add(", ");
        put_model_element(m, sort_data[sort].base, a);
        if (sort_data[sort].kind == SORT_PARTS) continue;
        proof_add(" \\mapsto ");
        put_model_element(m, sort_data[sort].target, rest % m->dimension[sort_data[sort].target].size);
        rest /= m->dimension[sort_data[sort].target].size;
    }
    proof_add(sort_data[sort].kind == SORT_PARTS ? "\\}" : ")");
}

/* Scrive il modello m: gli insiemi, poi ogni simbolo dichiarato con la sua
 * tabella. Una parte e una relazione si scrivono come l'insieme degli
 * elementi, o delle coppie, per cui valgono. Gli insiemi di parti e di
 * applicazioni (17v) sono quelli veri: non si elencano, e il loro simbolo
 * di struttura non ha una tabella da dire. */
static void put_model(const Model *m) {
    for (int i = 0, written = 0; i < sort_count; i++) {
        /* 17v. I numeri scritti sono i soli elementi del loro insieme. */
        if (sort_data[i].kind == SORT_NUMBERS) { proof_add("%s$", written++ ? ", " : ""); put_sort(i); proof_add("$"); }
        if (sort_data[i].kind != SORT_PLAIN) continue;
        proof_add("%s$", written++ ? ", " : "");
        put_sort(i);
        proof_add(" = \\{");
        for (size_t x = 0; x < m->dimension[i].size; x++) { if (x) proof_add(", "); put_model_element(m, i, x); }
        proof_add("\\}$");
    }
    for (int s = 0; s < symbol_count; s++) {
        if (symbol_fixed(s)) continue;
        const Symbol *symbol = &symbols[s];
        size_t cells, first = m->dimension[symbol->arity ? symbol->domain[0] : 0].size, written = 0;
        if (symbol_bound[s]) continue;  /* una parte legata (28i) non ha tabella */
        model_cells(m, s, &cells);
        proof_add("; $");
        /* Una funzione con dominio vuoto e il grafico vuoto: la sua
         * dichiarazione va mostrata anche quando non ci sono celle. */
        if (!cells && symbol->range != TRUTH) { put_symbol(s); proof_add(" = \\emptyset$"); continue; }
        if (symbol->range == TRUTH) { put_symbol(s); proof_add(" = \\{"); }
        for (size_t c = 0; c < cells; c++) {
            if (symbol->range == TRUTH && !m->table[s][c]) continue;
            if (written++) proof_add(", ");

            /* Gli argomenti, come li si scrive nell'enunciato. */
            int infix = symbol->name >= OPERATION_NAMES && symbol->name < GREEK_NAMES;
            if (symbol->range != TRUTH && !infix) put_symbol(s);
            if (symbol->arity && !infix) proof_add(symbol->arity == 2 || symbol->range != TRUTH ? "(" : "");
            if (symbol->arity) put_model_element(m, symbol->domain[0], c % first);
            if (infix) { proof_add(" "); put_symbol(s); proof_add(" "); }
            else if (symbol->arity == 2) proof_add(", ");
            if (symbol->arity == 2) put_model_element(m, symbol->domain[1], c / first);
            if (symbol->arity && !infix) proof_add(symbol->arity == 2 || symbol->range != TRUTH ? ")" : "");
            if (symbol->range != TRUTH) { proof_add(" = "); put_model_element(m, symbol->range, m->table[s][c]); }
        }
        if (symbol->range == TRUTH) proof_add(written ? "\\}" : "\\} = \\emptyset");
        proof_add("$");
    }
}

/* 28h. LA NOTAZIONE DEI LIBRI, RICONTROLLATA SUI MODELLI
 *
 * (Sta qui, subito dopo 28a, perché usa i suoi modelli; la lettera è venuta
 * dopo le altre.)
 *
 * Il paragrafo 17q svolge la notazione dei libri sostituendo, sull'albero:
 * f(X) = f(Y) diventa "per ogni t, esiste u in X con f(u) = t se e solo se
 * ...". Un errore lì farebbe dimostrare un altro enunciato, e ogni controllo
 * successivo, compreso il certificato, lo confermerebbe, perché tutti
 * guardano l'enunciato svolto. Per questo l'enunciato com'è scritto si
 * calcola anche per un'altra strada, su molti modelli finiti, e deve dare
 * lo stesso valore di quello svolto.
 *
 * L'altra strada non sostituisce nulla. Per sapere se il membro t sta in
 * \{(x, y) \mid c\} prova ogni valore di x e di y e guarda se uno dà proprio
 * t e rende vera c, come dice la definizione ("esiste (x, y) uguale a t per
 * cui vale c"); per un'immagine prova ogni elemento del dominio; per
 * un'uguaglianza tra insiemi prova ogni membro possibile; per "esiste un
 * solo x" conta. Le lettere legate prendono i loro valori in value[], come
 * quelle dei quantificatori: è un ambiente, e una lettera non può prendere
 * il posto di un'altra. Le due strade hanno in comune solo l'albero letto e
 * le tabelle dei simboli.
 *
 * I modelli sono quelli di 28a: per ogni scelta delle grandezze degli
 * insiemi, dalla più piccola, tutte le tabelle se sono poche, altrimenti un
 * campione preso a caso con un seme fisso, fino a MAX_CHECK_MODELS modelli o
 * al limite di model_step_limit. Non dimostra che le due strade coincidano
 * sempre, e non serve: è il controllo contro gli errori dello svolgimento,
 * e un errore di sostituzione cambia l'enunciato quasi sempre già in un
 * modello di due o tre elementi.
 */

static int book_holds(const Model *m, const Sentence *s, size_t *value);

/* Ritorna 1 se il membro t[], di set->arity componenti già calcolate, sta
 * nell'insieme set del modello m, con le variabili libere ai valori di
 * value[]. Calcola dalla definizione, senza sostituire nulla (vedi la testa
 * del paragrafo); value[] viene usato anche per le lettere che set lega, e
 * rimesso com'era. */
static int book_member(const Model *m, const size_t *t, const SetTerm *set, size_t *value) {
    int found = 0;
    size_t saved[MAX_ARITY], arg;
    switch (set->kind) {
    case ST_SYMBOL:
        return model_cell(m, set->symbol, t[0], set->arity == 2 ? t[1] : 0);
    case ST_SECTION:
        return model_cell(m, set->symbol, t[0], model_element(m, set->item[0], value));
    case ST_SORT:
        return 1;
    case ST_EMPTY:
        return 0;
    case ST_LIST:
        for (int i = 0; i < set->items && !found; i++) found = t[0] == model_element(m, set->item[i], value);
        return found;
    case ST_BUILDER: {
        /* Ogni valore delle lettere dello schema, come un contachilometri:
         * t sta nell'insieme se uno di loro dà t e rende vera la condizione. */
        int possible = 1;
        for (int i = 0; i < set->bounds; i++) {
            saved[i] = value[set->bound[i]]; value[set->bound[i]] = 0;
            possible = possible && m->dimension[slot_data[set->bound[i]].sort].size != 0;
        }
        for (int more = possible; more && !found; ) {
            if (++model_steps > model_step_limit) break;
            int same = 1;
            for (int i = 0; i < set->arity && same; i++) same = value[set->item[i]->slot] == t[i];
            found = same && book_holds(m, set->condition, value);
            more = 0;
            for (int i = 0; i < set->bounds && !more; i++) {
                if (++value[set->bound[i]] < m->dimension[slot_data[set->bound[i]].sort].size) more = 1; else value[set->bound[i]] = 0;
            }
        }
        for (int i = 0; i < set->bounds; i++) value[set->bound[i]] = saved[i];
        return found;
    }
    case ST_IMAGE: case ST_PREIMAGE: {
        /* f(x) è la cella di x; per un elemento di T^{S} (17v), la cella di
         * (f, x) del simbolo di struttura. */
        size_t map = set->items ? model_element(m, set->item[0], value) : 0;
        int sort = symbols[set->symbol].domain[set->items];
        if (set->kind == ST_PREIMAGE) {
            arg = set->items ? model_cell(m, set->symbol, map, t[0]) : model_cell(m, set->symbol, t[0], 0);
            return book_member(m, &arg, set->a, value);
        }
        for (arg = 0; arg < m->dimension[sort].size && !found; arg++)
            found = (set->items ? model_cell(m, set->symbol, map, arg) : model_cell(m, set->symbol, arg, 0)) == t[0] && book_member(m, &arg, set->a, value);
        return found;
    }
    case ST_PART:
        /* 17v. La cella di (t, X) dell'appartenenza. */
        return model_cell(m, set->symbol, t[0], model_element(m, set->item[0], value));
    case ST_TUPLES:
        /* 17v. Uno dei membri dell'elenco, componente per componente. */
        for (int k = 0; k < set->items && !found; k++) {
            found = 1;
            for (int i = 0; i < set->arity && found; i++) found = model_element(m, set->tuple[k * set->arity + i], value) == t[i];
        }
        return found;
    case ST_REPLACE: {
        /* 17v. Ogni valore delle lettere nuove, come un contachilometri: t
         * sta nell'insieme se uno di loro rende vera la condizione e dà t,
         * come elemento o come la parte con gli stessi elementi di a. */
        int possible = 1;
        for (int i = 0; i < set->bounds; i++) {
            saved[i] = value[set->bound[i]]; value[set->bound[i]] = 0;
            possible = possible && m->dimension[slot_data[set->bound[i]].sort].size != 0;
        }
        for (int more = possible; more && !found; ) {
            if (++model_steps > model_step_limit) break;
            if (book_holds(m, set->condition, value)) {
                if (set->items) {
                    found = model_element(m, set->item[0], value) == t[0];
                } else {
                    found = 1;
                    for (arg = 0; arg < m->dimension[sort_data[set->sort[0]].base].size && found; arg++)
                        found = (int)model_cell(m, set->symbol, arg, t[0]) == book_member(m, &arg, set->a, value);
                }
            }
            more = 0;
            for (int i = 0; i < set->bounds && !more; i++) {
                if (++value[set->bound[i]] < m->dimension[slot_data[set->bound[i]].sort].size) more = 1; else value[set->bound[i]] = 0;
            }
        }
        for (int i = 0; i < set->bounds; i++) value[set->bound[i]] = saved[i];
        return found;
    }
    case ST_DESCRIBE: {
        /* 17v. Ogni parte Z con gli stessi elementi dell'insieme a (nei
         * modelli ce n'è una sola, 28m) dà t \in b. */
        int z = set->bound[0], sort = slot_data[z].sort, result = 1;
        saved[0] = value[z];
        for (size_t x = 0; x < m->dimension[sort].size && result; x++) {
            int same = 1;
            for (arg = 0; arg < m->dimension[sort_data[sort].base].size && same; arg++)
                same = (int)model_cell(m, sort_data[sort].symbol, arg, x) == book_member(m, &arg, set->a, value);
            if (!same) continue;
            value[z] = x;
            result = book_member(m, t, set->b, value);
        }
        value[z] = saved[0];
        return result;
    }
    case ST_POWERSET:
        /* 17v. Ogni elemento della parte t sta in a. */
        for (arg = 0; arg < m->dimension[sort_data[set->sort[0]].base].size; arg++)
            if (model_cell(m, set->symbol, arg, t[0]) && !book_member(m, &arg, set->a, value)) return 0;
        return 1;
    case ST_UNION:
        return book_member(m, t, set->a, value) || book_member(m, t, set->b, value);
    case ST_INTER:
        return book_member(m, t, set->a, value) && book_member(m, t, set->b, value);
    case ST_DIFF:
        return book_member(m, t, set->a, value) && !book_member(m, t, set->b, value);
    case ST_SYMDIFF:
        return book_member(m, t, set->a, value) != book_member(m, t, set->b, value);
    case ST_BIG_UNION: case ST_BIG_INTER: {
        /* Ogni valore dell'indice, nel suo insieme o nella sua parte. */
        int index = set->bound[0], every = set->kind == ST_BIG_INTER, result = every;
        saved[0] = value[index];
        for (size_t i = 0; i < m->dimension[slot_data[index].sort].size && result == every; i++) {
            if (set->symbol >= 0 && !model_cell(m, set->symbol, i, 0)) continue;
            if (set->b && !book_member(m, &i, set->b, value)) continue;
            value[index] = i;
            if (book_member(m, t, set->a, value) != every) result = !every;
        }
        value[index] = saved[0];
        return result;
    }
    }
    return 0;
}

/* Ritorna 1 se, per ogni membro possibile t (ogni scelta delle componenti
 * nei loro insiemi), "t sta in set" e "t sta in other" valgono come chiede
 * how: 0 per "il primo implica il secondo", 1 per "hanno lo stesso valore".
 * Con how = 2 ritorna 1 se c'è un t che sta in other e non in set. */
static int book_compare(const Model *m, const SetTerm *set, const SetTerm *other, int how, size_t *value) {
    size_t t[MAX_ARITY] = {0};
    for (int i = 0; i < set->arity; i++) if (!m->dimension[set->sort[i]].size) return how != 2;
    for (;;) {
        if (++model_steps > model_step_limit) return 0;
        int in_set = book_member(m, t, set, value), in_other = book_member(m, t, other, value);
        if (how == 0 && in_set && !in_other) return 0;
        if (how == 1 && in_set != in_other) return 0;
        if (how == 2 && in_other && !in_set) return 1;
        int i = 0;
        for (; i < set->arity; i++) {
            if (++t[i] < m->dimension[set->sort[i]].size) break;
            t[i] = 0;
        }
        if (i == set->arity) return how != 2;
    }
}

/* Ritorna 1 se la condizione s, scritta come nei libri (17p), vale nel
 * modello m, con le variabili libere ai valori di value[]. È model_holds()
 * per le condizioni di 17o, con in più i nodi di 17p calcolati dalla loro
 * definizione. Se model_steps supera model_step_limit la risposta non vuol
 * dire nulla. */
static int book_holds(const Model *m, const Sentence *s, size_t *value) {
    size_t t[MAX_ARITY];
    int count = 0, every;
    switch (s->kind) {
    case S_TRUE:    return 1;
    case S_EQUIPOTENT: return model_equipotent(m, s);
    case S_EQUAL:   return model_element(m, s->left, value) == model_element(m, s->right, value);
    case S_HOLDS:   return model_element(m, s->left, value);
    case S_NOT:     return !book_holds(m, s->a, value);
    case S_AND:     return book_holds(m, s->a, value) && book_holds(m, s->b, value);
    case S_OR:      return book_holds(m, s->a, value) || book_holds(m, s->b, value);
    case S_IMPLIES: return !book_holds(m, s->a, value) || book_holds(m, s->b, value);
    case S_IFF:     return book_holds(m, s->a, value) == book_holds(m, s->b, value);
    case S_MEMBER:
        for (int i = 0; i < s->items; i++) t[i] = model_element(m, s->item[i], value);
        return book_member(m, t, s->set, value);
    case S_INCLUDED:
        return book_compare(m, s->set, s->other, 0, value) && (!s->proper || book_compare(m, s->set, s->other, 2, value));
    case S_SAME:
        return book_compare(m, s->set, s->other, 1, value);
    case S_FORALL_PART: case S_EXISTS_PART:
        return model_part_quantifier(m, s, value, book_holds);
    case S_UNIQUE:
        /* Si contano gli elementi per cui vale. */
        for (size_t x = 0; x < m->dimension[slot_data[s->slot].sort].size && count < 2; x++) {
            if (++model_steps > model_step_limit) return 0;
            value[s->slot] = x;
            count += book_holds(m, s->a, value);
        }
        return count == 1;
    case S_FORALL: case S_EXISTS:
        break;
    }
    every = s->kind == S_FORALL;
    for (size_t x = 0; x < m->dimension[slot_data[s->slot].sort].size; x++) {
        if (++model_steps > model_step_limit) return 0;
        value[s->slot] = x;
        if (book_holds(m, s->a, value) != every) return !every;
    }
    return every;
}

/* Dà alle tabelle di m valori presi a caso, con il generatore che parte da
 * *state: lo stesso seme dà gli stessi modelli, quindi lo stesso verdetto. */
static void book_random_tables(Model *m, unsigned *state) {
    for (int s = 0; s < symbol_count; s++) {
        if (symbol_fixed(s)) continue;
        size_t cells, values = model_cells(m, s, &cells);
        for (size_t c = 0; c < cells; c++) {
            *state ^= *state << 13;
            *state ^= *state >> 17;
            *state ^= *state << 5;
            m->table[s][c] = (*state % values);
        }
    }
}

/* Confronta l'enunciato com'è scritto, written, calcolato da book_holds(),
 * con quello svolto, unfolded, calcolato da model_holds(), sui modelli
 * descritti in testa al paragrafo. Ritorna quanti modelli ha confrontato, o
 * -1 se in uno i due valori sono diversi. */
static long long book_check(const Sentence *written, const Sentence *unfolded) {
    Model m={0};
    size_t *value=model_variables();
    if (work_allocation_failed || !model_dimensions(&m)) { model_clear(&m);return 0; }
    for (int i=0;i<sort_count;i++) m.dimension[i].minimum=sort_data[i].kind==SORT_PLAIN;
    unsigned state=2463534242u;
    unsigned long long visits=0,cost=(unsigned long long)sort_count+1;
    long long compared=0;
    model_steps=0;

    /* Le composizioni visitano direttamente i totali possibili: non
     * calcolano 4^sort_count e non attraversano codici di insiemi derivati.
     * La quota conta anche configurazioni scartate e scansioni dei tipi. */
    size_t last;
    if (!model_product((size_t)plain_sorts(),MAX_MODEL_SIZE-1,&last)) goto finished;
    for (size_t total=0;total<=last;total++) {
        model_composition_start(&m,total);
        do {
            if (cost>MAX_MODEL_WORK-visits) goto finished;
            visits+=cost;
            if (!model_composition_values(&m,MAX_MODEL_SIZE)) continue;

            /* Tutte le tabelle se sono al piu 256, altrimenti 256 a caso.
             * I simboli di struttura non si scelgono. La valutazione del
             * testo scritto resta indipendente da quella dello svolto. */
            double count=1;
            for (int f=0;f<symbol_count && count<=256;f++) {
                size_t cells,values=model_cells(&m,f,&cells);
                for (size_t c=0;c<cells && count<=256 && !symbol_fixed(f);c++) count*=values;
            }
            if (!model_allocate(&m)) continue;
            model_structure(&m);
            for (int tried=0,more=1;more;tried++) {
                if (count>256) book_random_tables(&m,&state);
                int book=book_holds(&m,written,value),plain=model_holds(&m,unfolded,value);
                if (!model_steps_complete()) goto finished;
                if (book!=plain) { model_clear(&m);return -1; }
                if (++compared>=MAX_CHECK_MODELS) goto finished;
                more=0;
                if (count>256) { more=tried+1<256;continue; }
                for (int f=0;f<symbol_count && !more;f++) {
                    if (symbol_fixed(f)) continue;
                    size_t cells,values=model_cells(&m,f,&cells);
                    for (size_t c=0;c<cells && !more;c++) {
                        if (++m.table[f][c]<values) more=1;else m.table[f][c]=0;
                    }
                }
            }
            model_tables_clear(&m);
        } while (model_composition_next(&m));
    }
finished:
    model_clear(&m);
    return compared;
}

/* Scrive nella dimostrazione che la notazione degli insiemi è stata svolta,
 * e su quanti modelli lo svolgimento è stato ricontrollato: compared, che è
 * 0 se non c'era nulla da svolgere, e allora non scrive nulla. */
static void put_unfolding_note(long long compared) {
    if (!compared) return;
    proof_add(" The notation of sets (sets of elements or of pairs given by a rule, images and preimages, equalities and "
              "inclusions between sets) is read as the conditions on elements it stands for, and that is the statement "
              "written above; the statement as written and that one take the same value in each of the %lld finite models "
              "tried.", compared);
}

/* 28b. GLI ELEMENTI DI CUI SI PARLA */

/* Un elemento nominato in una dimostrazione: un simbolo applicato ad altri
 * elementi, già in tabella. Due scritture uguali sono lo stesso posto della
 * tabella, quindi "scritti allo stesso modo" si controlla confrontando due
 * numeri. Il posto 0 è riservato a "vero", il valore di una parte o di una
 * relazione che vale: così x \in X è l'uguaglianza X(x) = vero, e le regole
 * sulle uguaglianze servono anche per le appartenenze. */
typedef struct {
    int symbol;    /* posto in symbols[]; -1 per "vero", senza troncamenti a 16 bit */
    short arg[2];  /* gli argomenti, posti in questa tabella; -1 dove mancano */
} Ground;

/* La tabella degli elementi. È una sola per tutti i rami della ricerca: un
 * ramo ne usa i primi now->grounds posti, e chi torna a un ramo precedente
 * riusa i posti dopo. */
static Ground ground[MAX_GROUND];

/* Una sostituzione finita delle variabili astratte con elementi presenti.
 * count e il numero di celle possedute nell'arena, data i valori (indici
 * di ground, oppure -1 per una variabile non sostituita). Le celle oltre
 * count valgono sempre -1: gli assiomi possono creare slot dopo una copia.
 * I Known conservano copie immutabili; solo i vettori temporanei di una
 * ricerca vengono modificati. La durata e quella dell'arena della prova. */
typedef struct { int count; short *data; } SlotValues;

/* La sostituzione vuota vale per qualsiasi numero di variabili. */
#define SLOT_VALUES_EMPTY ((SlotValues){0})

/* Legge una sostituzione, compresi i posti creati dopo il suo snapshot. */
static inline int slot_values_get(SlotValues values, int slot) {
    return slot >= 0 && slot < values.count ? values.data[slot] : -1;
}

/* Copia source in un vettore temporaneo gia dimensionato per tutti gli
 * slot correnti. Il suffisso non presente nello snapshot resta non legato;
 * nessuna cella del Known da cui proviene la copia viene modificata. */
static void slot_values_load(SlotValues target, SlotValues source) {
    if (target.count < source.count) {
        work_allocation_failed = 1; fail(OUT_OF_MEMORY); return;
    }
    if (source.count) memcpy(target.data, source.data, (size_t)source.count * sizeof *source.data);
    for (int i = source.count; i < target.count; i++) target.data[i] = -1;
}

/* Crea una copia indipendente con spazio per tutti gli slot correnti.
 * La copia vuota non alloca. Ogni chiamante controlla il fallimento prima
 * di scrivere: un vettore parziale non puo diventare una deduzione. */
static SlotValues slot_values_copy(SlotValues source) {
    int count = slot_count > source.count ? slot_count : source.count;
    if (!count) return SLOT_VALUES_EMPTY;
    short *data = work_arena_array((size_t)count, sizeof *data);
    if (!data) return SLOT_VALUES_EMPTY;
    SlotValues copy = {count, data};
    slot_values_load(copy, source);
    return copy;
}

/* Ciò che si sa in un ramo: una condizione dell'enunciato, con il segno con
 * cui è vera e con un elemento al posto di ogni variabile libera. Come ci
 * si è arrivati lo dicono origin e parent: serve a scrivere la
 * dimostrazione e a ricontrollarla. */
typedef enum {
    K_GIVEN,     /* un'ipotesi dell'enunciato */
    K_DENIED,    /* la tesi, supposta falsa */
    K_PART,      /* 28-1: segue da parent, date le condizioni già decise */
    K_INSTANCE,  /* 28-3: parent, un "per ogni", su degli elementi */
    K_NAMED,     /* 28-2: parent, un "esiste", su un elemento con un nome nuovo */
    K_CASE,      /* 28-5: uno dei due casi lasciati aperti da parent */
    K_DEFINED,   /* 28j: la definizione di una parte nuova, data da una regola */
    K_BIJECTION, /* 28q: parent è un'equipotenza; vera, le identità di una
                    biiezione nuova e della sua inversa (28q-1); falsa, la
                    loro negazione per due applicazioni costruite (28q-2) */
    K_MAPDEF     /* 28q: la definizione di un'applicazione nuova (d1-d3) */
} Origin;

/* A che punto è una condizione nota. */
typedef enum {
    K_NEW,      /* appena aggiunta: va ancora guardata */
    K_DONE,     /* usata: è un fatto, oppure le sue conseguenze sono in elenco */
    K_WAITING,  /* una disgiunzione di cui non si sa ancora quale parte valga */
    K_RULE      /* un "per ogni": dà un'istanza per ogni elemento */
} Stage;

/* Una condizione nota (vedi Origin). Se è un confronto tra due elementi è un
 * "fatto", e left e right dicono quali: uguali se negated è 0, diversi se è
 * 1. Per un'appartenenza right è 0, "vero".
 *
 * Invariante: source non è una negazione (le negazioni sono nel segno), e
 * parent, quando c'è, viene prima nell'elenco. Sostituzioni e parti sono
 * snapshot nell'arena: copiarli in un ramo non introduce memoria mutabile
 * condivisa, e nessun prefisso di quantificatori viene troncato. */
typedef struct {
    const Sentence *source;  /* la condizione, com'è nell'enunciato */
    signed char negated;     /* 1 se è vera la sua negazione */
    signed char origin;      /* un Origin */
    signed char stage;       /* uno Stage */
    short parent;            /* da quale condizione viene; -1 se da nessuna */
    short left, right;       /* fatto: i due elementi; -1 altrimenti */
    int stamp;               /* numero d'ordine: vedi Branch.clock */
    SlotValues value;       /* snapshot immutabile delle sostituzioni */
    int parts;              /* numero di simboli nella copia immutabile part */
    const int *part;      /* 28j: per un'istanza di un "per ogni parte", la
                                parte al posto di ogni parte legata, dalla più
                                esterna; per un nome dato a una parte (K_NAMED)
                                o per una definizione (K_DEFINED), in part[0]
                                la parte nuova. 28q: per K_BIJECTION le
                                applicazioni delle identità, prima le
                                componenti di quella da A a B, poi quelle
                                dell'inversa; per K_MAPDEF, in part[0]
                                l'applicazione definita. Posti in symbols[];
                                nell'arena della prova; NULL se parts = 0 */
} Known;

/* Un ramo della ricerca: tutto ciò che si sa dopo certe scelte di casi.
 *
 * Le uguaglianze note sono tenute in due modi. rep[] dà per ogni elemento
 * il rappresentante della sua classe: due elementi sono uguali, per ciò che
 * si sa, quando hanno lo stesso rappresentante. up[] e why[] ricordano
 * perché: formano una foresta in cui ogni arco t - up[t] è un'uguaglianza
 * tra i due elementi, nota come fatto (why = il suo posto in known[])
 * oppure ottenuta sostituendo uguali negli argomenti (why = CONGRUENT). Due
 * elementi della stessa classe sono collegati da un solo cammino, che non
 * cambia più: gli archi si aggiungono solo tra classi diverse. Quel cammino
 * è la catena di uguaglianze da scrivere.
 *
 * clock numera le condizioni nell'ordine in cui vengono aggiunte: un passo
 * della dimostrazione può usare solo ciò che ha un numero più basso del
 * suo. */
typedef struct {
    Known known[MAX_KNOWN];
    int knowns;
    short rep[MAX_GROUND], up[MAX_GROUND], why[MAX_GROUND];
    short different[MAX_DIFFERENT];  /* i fatti "diversi", posti in known[] */
    int differents;
    int grounds;                     /* elementi in uso nella tabella */
    int symbols;                     /* simboli in uso, compresi i nomi nuovi */
    int clock;
} Branch;

/* Valore di Branch.why per un arco che non è un fatto: i due elementi sono
 * uguali perché hanno lo stesso simbolo e argomenti uguali (28-4). */
#define CONGRUENT (-1)

/* I rami, uno per profondità (una distinzione di casi, una scelta di parti
 * di 28k o un caso provato da 28l ne aggiungono uno), e quello in cui si sta
 * lavorando. */
static Branch branch[MAX_BRANCHES];
static Branch *now;

/* 1 se la ricerca si è fermata perché una tabella è piena: allora non aver
 * trovato una dimostrazione non dice nulla. */
static int exhausted;

/* Come si è chiuso l'ultimo ramo: il fatto "diversi" i cui due elementi sono
 * risultati uguali, oppure la disgiunzione di cui ogni parte è falsa. Uno
 * solo dei due non è -1. */
static int clash_fact, clash_choice;

/* Tabelle per ritrovare un elemento senza scorrere tutto l'elenco: per
 * scrittura (exact) e, tra una chiusura e l'altra, per classi degli
 * argomenti (classes). Contengono posti di ground[], o -1. */
static short exact[4 * MAX_GROUND], classes[4 * MAX_GROUND];

/* Ritorna il posto da cui cominciare a cercare, in una delle due tabelle,
 * il simbolo symbol applicato ad a e b. */
static unsigned ground_hash(int symbol, int a, int b) {
    return ((unsigned)symbol * 31u + (unsigned)(a + 1)) * 2053u + (unsigned)(b + 1);
}

/* Modi di cercare un elemento (vedi ground_lookup()). */
typedef enum { G_EXACT, G_CREATE, G_CLASS } Lookup;

/* Ritorna il posto dell'elemento "symbol applicato ad a e b", o -1.
 *
 *   G_EXACT:  quello scritto proprio così, se è in tabella;
 *   G_CREATE: come sopra, e se manca lo aggiunge (se la tabella è piena
 *             annota exhausted e ritorna -1);
 *   G_CLASS:  uno qualsiasi in tabella i cui argomenti siano uguali ad a e
 *             b per ciò che si sa. Vale solo subito dopo closure(). */
static int ground_lookup(int symbol, int a, int b, Lookup mode) {
    unsigned size = sizeof exact / sizeof *exact;
    if (mode == G_CLASS && a >= 0) {
        int ra = now->rep[a], rb = b >= 0 ? now->rep[b] : -1;
        for (unsigned h = ground_hash(symbol, ra, rb) % size; classes[h] >= 0; h = (h + 1) % size) {
            const Ground *g = &ground[classes[h]];
            if (g->symbol == symbol && now->rep[g->arg[0]] == ra && (g->arg[1] >= 0 ? now->rep[g->arg[1]] : -1) == rb) return classes[h];
        }
        return -1;
    }
    unsigned h = ground_hash(symbol, a, b) % size;
    for (; exact[h] >= 0; h = (h + 1) % size) {
        const Ground *g = &ground[exact[h]];
        if (g->symbol == symbol && g->arg[0] == a && g->arg[1] == b) return exact[h];
    }
    if (mode != G_CREATE) return -1;
    if (now->grounds == MAX_GROUND) { exhausted = 1; return -1; }

    /* Un elemento nuovo: da solo nella sua classe. */
    int id = now->grounds++;
    ground[id] = (Ground){symbol, {(short)a, (short)b}};
    now->rep[id] = (short)id;
    now->up[id] = -1;
    exact[h] = (short)id;
    return id;
}

/* Rifà la tabella exact per gli elementi del ramo corrente: va chiamata
 * quando si cambia ramo, perché i posti dopo now->grounds non valgono più. */
static void ground_reindex(void) {
    unsigned size = sizeof exact / sizeof *exact;
    memset(exact, -1, sizeof exact);
    for (int id = 0; id < now->grounds; id++) {
        unsigned h = ground_hash(ground[id].symbol, ground[id].arg[0], ground[id].arg[1]) % size;
        while (exact[h] >= 0) h = (h + 1) % size;
        exact[h] = (short)id;
    }
}

/* Ritorna il posto dell'elemento che e indica quando ogni variabile vale
 * l'elemento di value[]; -1 se manca dalla tabella, -2 se e contiene una
 * variabile non ancora sostituita. mode è G_EXACT o G_CREATE, come in
 * ground_lookup(). */
static int elem_ground(const Elem *e, SlotValues value, Lookup mode) {
    int arg[2] = {-1, -1};
    if (e->symbol < 0) return slot_values_get(value, e->slot) >= 0 ? slot_values_get(value, e->slot) : -2;
    for (int i = 0; i < 2 && e->arg[i]; i++) {
        arg[i] = elem_ground(e->arg[i], value, mode);
        if (arg[i] < 0) return arg[i];
    }

    return ground_lookup(e->symbol, arg[0], arg[1], mode);
}

/* Scrive l'elemento di posto id. tight chiede le parentesi intorno a
 * un'operazione scritta tra i suoi operandi. */
static void put_ground(int id, int tight) {
    const Ground *g = &ground[id];
    if (g->symbol < 0) { proof_add("\\top"); return; }
    int name = symbols[g->symbol].name;
    if (symbol_structure(g->symbol) >= 0) {
        /* 17v. L'applicazione di un elemento di T^{S}, f(x). */
        put_ground(g->arg[0], 1);
        proof_add("\\left(");
        put_ground(g->arg[1], 0);
        proof_add("\\right)");
        return;
    }
    if (name >= OPERATION_NAMES && name < GREEK_NAMES) {
        if (tight) proof_add("\\left(");
        put_ground(g->arg[0], 1);
        proof_add(" ");
        put_symbol(g->symbol);
        proof_add(" ");
        put_ground(g->arg[1], 1);
        if (tight) proof_add("\\right)");
        return;
    }
    put_symbol(g->symbol);
    if (g->arg[0] < 0) return;
    proof_add("\\left(");
    put_ground(g->arg[0], 0);
    if (g->arg[1] >= 0) { proof_add(", "); put_ground(g->arg[1], 0); }
    proof_add("\\right)");
}

/* Scrive il nome della variabile di posto slot: la lettera, con il pedice se
 * c'è. */
static void put_slot(int slot) {
    proof_add("%c", slot_data[slot].letter);
    if (slot_data[slot].index) proof_add("_{%d}", index_digits(slot_data[slot].index));
}

/* Scrive l'elemento e, con gli elementi di value[] al posto delle variabili
 * sostituite e la lettera per le altre. */
static void put_elem(const Elem *e, SlotValues value, int tight) {
    if (e->symbol < 0) {
        if (slot_values_get(value, e->slot) >= 0) put_ground(slot_values_get(value, e->slot), tight); else put_slot(e->slot);
        return;
    }
    int name = symbols[e->symbol].name;
    if (symbol_structure(e->symbol) >= 0) {
        /* 17v. L'applicazione di un elemento di T^{S}, f(x). */
        put_elem(e->arg[0], value, 1);
        proof_add("\\left(");
        put_elem(e->arg[1], value, 0);
        proof_add("\\right)");
        return;
    }
    if (name >= OPERATION_NAMES && name < GREEK_NAMES) {
        if (tight) proof_add("\\left(");
        put_elem(e->arg[0], value, 1);
        proof_add(" ");
        put_symbol(e->symbol);
        proof_add(" ");
        put_elem(e->arg[1], value, 1);
        if (tight) proof_add("\\right)");
        return;
    }
    put_symbol(e->symbol);
    if (!e->arg[0]) return;
    proof_add("\\left(");
    put_elem(e->arg[0], value, 0);
    if (e->arg[1]) { proof_add(", "); put_elem(e->arg[1], value, 0); }
    proof_add("\\right)");
}

/* 17w. Scrive il lato k dell'equipotenza s: un insieme, o il prodotto di
 * due. */
static void put_equipotent_side(const Sentence *s, int k) {
    for (int i = 0; i < s->sides[k]; i++) {
        if (i) proof_add(" \\times ");
        put_sort(slot_data[s->side_slot[k][i]].sort);
    }
}

/* Scrive la condizione s, negata se negated, con gli elementi di value[] al
 * posto delle variabili sostituite. tight chiede le parentesi intorno a ciò
 * che non è un confronto. */
static void put_sentence(const Sentence *s, int negated, SlotValues value, int tight) {
    static const char *const connective[] = {[S_AND] = "\\land", [S_OR] = "\\lor", [S_IMPLIES] = "\\implies", [S_IFF] = "\\iff"};
    switch (s->kind) {
    case S_TRUE:
        proof_add(negated ? "\\bot" : "\\top");
        return;
    case S_EQUIPOTENT:
        put_equipotent_side(s, 0);
        proof_add(negated ? " \\not\\sim " : " \\sim ");
        put_equipotent_side(s, 1);
        return;
    case S_NOT:
        put_sentence(s->a, !negated, value, tight);
        return;
    case S_EQUAL:
        put_elem(s->left, value, 0);
        proof_add(negated ? " \\neq " : " = ");
        put_elem(s->right, value, 0);
        return;
    case S_HOLDS:
        /* Una parte: x \in X. Una relazione: (x, y) \in R. Una famiglia di
         * parti (17p): x \in X_{i}. */
        if (symbols[s->left->symbol].family) {
            put_elem(s->left->arg[0], value, 0);
            proof_add(negated ? " \\notin " : " \\in ");
            put_symbol(s->left->symbol);
            proof_add("_{");
            put_elem(s->left->arg[1], value, 0);
            proof_add("}");
            return;
        }
        if (symbol_structure(s->left->symbol) >= 0) {
            /* 17v. L'appartenenza a un elemento di \mathcal{P}(S): t \in X. */
            put_elem(s->left->arg[0], value, 0);
            proof_add(negated ? " \\notin " : " \\in ");
            put_elem(s->left->arg[1], value, 0);
            return;
        }
        if (symbols[s->left->symbol].name >= RELATION_NAMES) {
            /* 17v. Una relazione scritta con un comando: x \le y. */
            if (negated) proof_add("\\lnot (");
            put_elem(s->left->arg[0], value, 0);
            proof_add(" ");
            put_symbol(s->left->symbol);
            proof_add(" ");
            put_elem(s->left->arg[1], value, 0);
            if (negated) proof_add(")");
            return;
        }
        if (s->left->arg[1]) proof_add("(");
        put_elem(s->left->arg[0], value, 0);
        if (s->left->arg[1]) { proof_add(", "); put_elem(s->left->arg[1], value, 0); proof_add(")"); }
        proof_add(negated ? " \\notin " : " \\in ");
        put_symbol(s->left->symbol);
        return;
    case S_AND: case S_OR: case S_IMPLIES: case S_IFF:
        if (negated) proof_add("\\lnot ");
        if (negated || tight) proof_add("(");
        put_sentence(s->a, 0, value, 1);
        proof_add(" %s ", connective[s->kind]);
        put_sentence(s->b, 0, value, 1);
        if (negated || tight) proof_add(")");
        return;
    case S_FORALL: case S_EXISTS:
        proof_add("%s\\%s ", negated ? "\\lnot " : "", s->kind == S_FORALL ? "forall" : "exists");
        put_slot(s->slot);
        proof_add(" \\in ");
        put_sort(slot_data[s->slot].sort);
        proof_add("\\ (");
        put_sentence(s->a, 0, value, 0);
        proof_add(")");
        return;
    case S_FORALL_PART: case S_EXISTS_PART:
        proof_add("%s\\%s ", negated ? "\\lnot " : "", s->kind == S_FORALL_PART ? "forall" : "exists");
        put_symbol(s->part);
        proof_add(" \\subseteq ");
        put_sort(symbols[s->part].domain[0]);
        proof_add("\\ (");
        put_sentence(s->a, 0, value, 0);
        proof_add(")");
        return;
    case S_MEMBER: case S_INCLUDED: case S_SAME: case S_UNIQUE:
        /* Non arrivano qui: lo svolgimento (17q) li toglie. */
        return;
    }
}

/* 28c. CIÒ CHE SI SA: UGUAGLIANZE, CLASSI, CATENE */

/* 28-4. Annota che gli elementi a e b, di classi diverse, sono uguali, per
 * la ragione reason: un fatto, o CONGRUENT. Le due classi diventano una, e
 * nella foresta nasce l'arco a - b.
 *
 * Perché l'arco possa partire da a, a deve essere la radice del suo albero:
 * prima si rovesciano gli archi da a alla vecchia radice, che restano le
 * stesse uguaglianze lette nell'altro verso. */
static void classes_join(int a, int b, int reason) {
    int node = a, above = now->up[a], why = now->why[a];
    while (above >= 0) {
        int next = now->up[above], next_why = now->why[above];
        now->up[above] = (short)node;
        now->why[above] = (short)why;
        node = above;
        above = next;
        why = next_why;
    }
    now->up[a] = (short)b;
    now->why[a] = (short)reason;
    for (int from = now->rep[a], to = now->rep[b], id = 0; id < now->grounds; id++)
        if (now->rep[id] == from) now->rep[id] = (short)to;
}

/* 28-4. Chiusura per congruenza: finché due elementi hanno lo stesso
 * simbolo e argomenti uguali per ciò che si sa, ma stanno in classi
 * diverse, li unisce. Al ritorno la tabella `classes` è aggiornata.
 *
 * A ogni giro la tabella viene rifatta: ogni elemento vi entra con la
 * "firma" data dal simbolo e dalle classi degli argomenti, e se la firma
 * c'è già i due elementi sono uguali. Un'unione cambia le classi, quindi le
 * firme, e il giro ricomincia. */
static void closure(void) {
    unsigned size = sizeof classes / sizeof *classes;
    for (int changed = 1; changed; ) {
        changed = 0;
        memset(classes, -1, sizeof classes);
        for (int id = 1; id < now->grounds && !changed; id++) {
            const Ground *g = &ground[id];
            if (g->arg[0] < 0) continue;
            int found = ground_lookup(g->symbol, g->arg[0], g->arg[1], G_CLASS);
            if (found >= 0 && now->rep[found] != now->rep[id]) { classes_join(id, found, CONGRUENT); changed = 1; }
            if (found >= 0) continue;
            unsigned h = ground_hash(g->symbol, now->rep[g->arg[0]], g->arg[1] >= 0 ? now->rep[g->arg[1]] : -1) % size;
            while (classes[h] >= 0) h = (h + 1) % size;
            classes[h] = (short)id;
        }
    }
}

/* Ritorna il posto in known[] di un fatto "diversi" tra la classe di a e
 * quella di b, o -1 se non se ne conosce nessuno. */
static int different_fact(int a, int b) {
    for (int i = 0; i < now->differents; i++) {
        const Known *k = &now->known[now->different[i]];
        int l = now->rep[k->left], r = now->rep[k->right];
        if ((l == now->rep[a] && r == now->rep[b]) || (l == now->rep[b] && r == now->rep[a])) return now->different[i];
    }
    return -1;
}

/* Mette in node[] il cammino nella foresta dall'elemento a all'elemento b,
 * estremi compresi, e ritorna quanti archi ha; -1 se a e b non sono
 * collegati o se il cammino ha più di max archi.
 *
 * Si sale da a fino alla radice, poi da b finché si incontra il cammino di
 * a: quello è il punto in cui i due si congiungono. */
static int forest_path(int a, int b, short *node, int max) {
    short from_a[MAX_GROUND], from_b[MAX_CHAIN + 1];
    int count_a = 0, count_b = 0, meet = -1;
    for (int t = a; t >= 0; t = now->up[t]) from_a[count_a++] = (short)t;
    for (int t = b; t >= 0 && meet < 0; t = now->up[t]) {
        for (int i = 0; i < count_a && meet < 0; i++)
            if (from_a[i] == t) meet = i;
        if (meet < 0) { if (count_b == max) return -1; from_b[count_b++] = (short)t; }
    }
    if (meet < 0 || meet + count_b > max) return -1;
    for (int i = 0; i <= meet; i++) node[i] = from_a[i];
    for (int i = 0; i < count_b; i++) node[meet + 1 + i] = from_b[count_b - 1 - i];
    return meet + count_b;
}

/* Una catena di uguaglianze t_0 = t_1 = ... = t_n: ogni anello cambia un
 * solo punto del termine, usando un fatto. */
typedef struct {
    int links;                  /* n */
    short term[MAX_CHAIN + 1];  /* t_0, ..., t_n: posti in ground[] */
    short fact[MAX_CHAIN];      /* fact[i] giustifica t_i = t_{i+1}: posto in known[] */
} Chain;

/* Allunga la catena c, che finisce con l'elemento a, fino all'elemento b,
 * seguendo il cammino della foresta. Ritorna 0 se a e b non sono collegati
 * o se la catena diventa troppo lunga.
 *
 * Un arco che è un fatto è un anello. Un arco di congruenza, tra f(a1, a2)
 * e f(b1, b2), si svolge: prima la catena da a1 a b1 dentro f(_, a2), poi
 * quella da a2 a b2 dentro f(b1, _). I termini intermedi possono non
 * essere in tabella, e vengono aggiunti: servono solo a essere scritti. */
static int chain_extend(Chain *c, int a, int b) {
    short node[MAX_CHAIN + 1];
    int edges = forest_path(a, b, node, MAX_CHAIN);
    if (edges < 0) return 0;
    for (int i = 0; i < edges; i++) {
        int low = now->up[node[i]] == node[i + 1] ? node[i] : node[i + 1], reason = now->why[low];
        if (reason != CONGRUENT) {
            if (c->links == MAX_CHAIN) return 0;
            c->fact[c->links++] = (short)reason;
            c->term[c->links] = node[i + 1];
            continue;
        }

        /* Un argomento per volta: inner è la catena tra i due argomenti,
         * e ogni suo anello diventa un anello tra due applicazioni. */
        const Ground from = ground[node[i]], to = ground[node[i + 1]];
        for (int side = 0; side < 2 && from.arg[side] >= 0; side++) {
            Chain inner = {0, {from.arg[side]}, {0}};
            if (!chain_extend(&inner, from.arg[side], to.arg[side])) return 0;
            for (int j = 0; j < inner.links; j++) {
                int step = side ? ground_lookup(from.symbol, to.arg[0], inner.term[j + 1], G_CREATE)
                                : ground_lookup(from.symbol, inner.term[j + 1], from.arg[1], G_CREATE);
                if (step < 0 || c->links == MAX_CHAIN) return 0;
                c->fact[c->links++] = inner.fact[j];
                c->term[c->links] = (short)step;
            }
        }
    }
    return 1;
}

/* Controllo di un anello, indipendente dalle classi: ritorna 1 se
 * l'elemento v si ottiene dall'elemento u sostituendo, in un solo punto, l
 * con r oppure r con l. Guarda solo come i due elementi sono scritti: o
 * sono proprio l e r, oppure hanno lo stesso simbolo, un argomento identico
 * e l'altro che si ottiene allo stesso modo. */
static int rewrites(int u, int v, int l, int r) {
    if ((u == l && v == r) || (u == r && v == l)) return 1;
    const Ground *a = &ground[u], *b = &ground[v];
    if (a->symbol != b->symbol || a->arg[0] < 0) return 0;
    int first = a->arg[0] == b->arg[0], second = a->arg[1] == b->arg[1];
    if (first == second) return 0;
    return first ? rewrites(a->arg[1], b->arg[1], l, r) : rewrites(a->arg[0], b->arg[0], l, r);
}

/* Mette in *c la catena di uguaglianze dall'elemento a all'elemento b
 * fatta solo di fatti con numero d'ordine minore di stamp, e la
 * ricontrolla anello per anello con rewrites(). Ritorna 1 se la catena
 * esiste e supera il controllo; 0 se a e b non risultavano uguali a quel
 * punto. Un anello che non supera il controllo è un errore del programma:
 * lo registra unjustified_steps. */
static int chain_between(Chain *c, int a, int b, int stamp) {
    c->links = 0;
    c->term[0] = (short)a;
    if (now->rep[a] != now->rep[b] || !chain_extend(c, a, b)) return 0;
    for (int i = 0; i < c->links; i++) {
        const Known *fact = &now->known[c->fact[i]];
        if (fact->stamp >= stamp) return 0;
        if (fact->negated || fact->left < 0 || !rewrites(c->term[i], c->term[i + 1], fact->left, fact->right)) { unjustified_steps++; return 0; }
    }
    return 1;
}

/* 28d. LA RICERCA */

/* Aggiunge all'elenco del ramo la condizione source, vera con il segno
 * negated e con gli elementi di value[] al posto delle variabili, arrivata
 * da parent nel modo origin. Ritorna il suo posto, o -1 se l'elenco è
 * pieno. Le negazioni in testa passano nel segno. */
static int known_add(const Sentence *source, int negated, SlotValues value, Origin origin, int parent) {
    if (work_allocation_failed) { exhausted = 1; return -1; }
    while (source->kind == S_NOT) { source = source->a; negated = !negated; }
    if (now->knowns == MAX_KNOWN) { exhausted = 1; return -1; }
    Known *k = &now->known[now->knowns];
    k->source = source;
    k->negated = (signed char)negated;
    k->origin = (signed char)origin;
    k->stage = K_NEW;
    k->parent = (short)parent;
    k->left = k->right = -1;
    k->stamp = now->clock++;
    k->value = slot_values_copy(value);
    if (work_allocation_failed) { exhausted = 1; return -1; }
    k->parts = 0;
    k->part = NULL;
    return now->knowns++;
}

/* Conserva nel passo at una copia immutabile dei count simboli scelti.
 * at indica un Known valido e count e non negativo.
 * I rami possono condividere la copia: un tentativo nuovo non la modifica.
 * Ritorna zero e interrompe la ricerca se manca la memoria per la copia. */
static int known_parts(int at, const int *part, int count) {
    int *copy = work_arena_array((size_t)count, sizeof *copy);
    if (count && !copy) { exhausted = 1; return 0; }
    if (count) memcpy(copy, part, (size_t)count * sizeof *copy);
    now->known[at].parts = count;
    now->known[at].part = copy;
    return 1;
}

/* Come si legge un connettivo tenuto conto del segno: le due parti con il
 * loro segno, e se insieme fanno una congiunzione o una disgiunzione. Sono
 * le stesse leggi di junction() (capitolo 18), per quest'altro albero. */
typedef struct {
    int conjunction;       /* 1 congiunzione, 0 disgiunzione */
    const Sentence *x, *y; /* le due parti */
    int nx, ny;            /* 1 se la parte va presa negata */
} Parts;

/* Se s è una congiunzione, una disgiunzione o un'implicazione mette in *p
 * il modo di leggerla, negata se negated, e ritorna 1. */
static int sentence_parts(const Sentence *s, int negated, Parts *p) {
    if (s->kind != S_AND && s->kind != S_OR && s->kind != S_IMPLIES) return 0;
    *p = (Parts){(s->kind == S_AND) != negated, s->a, s->b, s->kind == S_IMPLIES ? !negated : negated, negated};
    return 1;
}

/* Mette in tabella gli elementi nominati dai confronti di s che non stanno
 * sotto un quantificatore: così truth() li trova, e la chiusura per
 * congruenza li confronta con gli altri. */
static void sentence_ground(const Sentence *s, SlotValues value) {
    if (s->kind == S_FORALL || s->kind == S_EXISTS || s->kind == S_FORALL_PART || s->kind == S_EXISTS_PART || s->kind == S_TRUE ||
        s->kind == S_EQUIPOTENT)
        return;
    if (s->kind == S_EQUAL || s->kind == S_HOLDS) {
        elem_ground(s->left, value, G_CREATE);
        if (s->right) elem_ground(s->right, value, G_CREATE);
        return;
    }
    sentence_ground(s->a, value);
    if (s->b) sentence_ground(s->b, value);
}

/* Ritorna ciò che si sa della condizione s, negata se negated, con gli
 * elementi di value[] al posto delle variabili: 1 se è vera, 0 se è falsa,
 * -1 se non si sa. Un confronto è vero se i due elementi sono nella stessa
 * classe, falso se si sa che sono diversi; i connettivi seguono le tavole
 * di verità, dove "non si sa" resta tale a meno che l'altra parte decida;
 * di un quantificatore non si sa mai nulla. Va chiamata dopo closure(). */
static int truth(const Sentence *s, int negated, SlotValues value) {
    int a, b, known = -1;
    switch (s->kind) {
    case S_TRUE:
        known = 1;
        break;
    case S_NOT:
        return truth(s->a, !negated, value);
    case S_EQUAL: case S_HOLDS:
        a = elem_ground(s->left, value, G_EXACT);
        b = s->kind == S_EQUAL ? elem_ground(s->right, value, G_EXACT) : 0;
        if (a >= 0 && b >= 0) known = now->rep[a] == now->rep[b] ? 1 : different_fact(a, b) >= 0 ? 0 : -1;
        break;
    case S_AND:
        a = truth(s->a, 0, value);
        b = truth(s->b, 0, value);
        known = (a == 0 || b == 0) ? 0 : (a == 1 && b == 1) ? 1 : -1;
        break;
    case S_OR: case S_IMPLIES:
        a = truth(s->a, s->kind == S_IMPLIES, value);
        b = truth(s->b, 0, value);
        known = (a == 1 || b == 1) ? 1 : (a == 0 && b == 0) ? 0 : -1;
        break;
    case S_IFF:
        a = truth(s->a, 0, value);
        b = truth(s->b, 0, value);
        if (a >= 0 && b >= 0) known = a == b;
        break;
    case S_FORALL: case S_EXISTS: case S_FORALL_PART: case S_EXISTS_PART: case S_EQUIPOTENT:
    case S_MEMBER: case S_INCLUDED: case S_SAME: case S_UNIQUE:  /* questi non arrivano qui (17q) */
        break;
    }
    return known < 0 ? -1 : known != negated;
}

/* I nomi dati da 28-2, per il certificato (28f). Il posto di un nome in
 * symbols[] si riusa da un ramo all'altro, quindi il nome si riconosce dal
 * suo numero d'ordine, name_serial[], che non si ripete nella dimostrazione
 * di un'affermazione: names_given ne conta i nomi. name_known[] è il posto
 * in known[] della condizione K_NAMED che il nome ha aperto. */
static int *name_serial, *name_known;
static size_t name_serial_capacity, name_known_capacity;
static int names_given;

/* 28r-3. La generazione di ogni simbolo: 0 per quelli dichiarati e per i
 * nomi che l'enunciato dà senza istanze, 1 più la più alta degli elementi
 * dell'istanza per un nome nato dentro un'istanza. Si scrive quando il nome
 * nasce, e vale per quel nome solo (il posto si riusa da un ramo all'altro:
 * lo si riscrive). */
static unsigned char *symbol_generation;
static size_t symbol_generation_capacity;

/* 28r-3. Ritorna la generazione dell'elemento presente id: la più alta dei
 * simboli che lo scrivono. */
static int ground_generation(int id) {
    const Ground *g = &ground[id];
    int generation = g->symbol >= 0 ? symbol_generation[g->symbol] : 0;
    for (int i = 0; i < 2 && g->arg[i] >= 0; i++) {
        int inner = ground_generation(g->arg[i]);
        if (inner > generation) generation = inner;
    }
    return generation;
}

/* 28r-3. Ritorna la generazione del nome che nasce dalla condizione nota k,
 * un "esiste": la più alta degli elementi al posto delle sue variabili, più
 * 1 se k viene, attraverso le sue parti, da un'istanza; al più 255. */
static int known_generation(const Known *k) {
    int generation = 0, instance = 0;
    for (int v = 0; v < k->value.count; v++) {
        int inner = slot_values_get(k->value, v) > 0 ? ground_generation(slot_values_get(k->value, v)) : 0;
        if (inner > generation) generation = inner;
    }
    for (const Known *p = k; !instance && p; p = p->parent >= 0 ? &now->known[p->parent] : NULL) instance = p->origin == K_INSTANCE;
    generation += instance;
    return generation > 255 ? 255 : generation;
}

/* 28n. Da quale legge delle parti viene una condizione nota (known_law()):
 * da nessuna, dall'estensionalità o da una comprensione. */
typedef enum { LAW_NONE, LAW_EXTENSIONALITY, LAW_COMPREHENSION } Law;
static int known_law(int i);

/* 28n. symbol_law[s] è 1 se il nome di posto s è nato da una legge delle
 * parti: una parte data da una comprensione, o un elemento che distingue
 * due parti. */
static unsigned char *symbol_law;
static size_t symbol_law_capacity;
/* Quanti simboli ha letto l'enunciato: gli altri sono nomi dati dalla
 * dimostrazione (28-2, e le parti di 28j). */
static int declared_symbols;

/* Dimensiona i metadati dei simboli della ricerca. Il parser possiede le
 * dichiarazioni, il motore questi dati delle dimostrazioni: nessuno dei
 * due conosce i vettori dell'altro. Tutti i riferimenti restano indici.
 * Una crescita parziale conserva i dati e segnala soltanto risorse finite. */
static int proof_symbols_reserve(size_t need) {
    if (!work_reserve((void **)&name_serial, &name_serial_capacity, need, sizeof *name_serial) ||
        !work_reserve((void **)&name_known, &name_known_capacity, need, sizeof *name_known) ||
        !work_reserve((void **)&symbol_generation, &symbol_generation_capacity, need, sizeof *symbol_generation) ||
        !work_reserve((void **)&symbol_law, &symbol_law_capacity, need, sizeof *symbol_law)) {
        exhausted = 1; return 0;
    }
    return 1;
}

/* Registra un nome del motore dopo aver riservato anche i suoi metadati.
 * Ritorna l'indice nuovo, o -1 senza pubblicare un nome incompleto. */
static int proof_symbol_append(Symbol symbol) {
    if (!proof_symbols_reserve((size_t)symbol_count + 1)) return -1;
    int id = symbol_append(symbol);
    if (id < 0) exhausted = 1;
    return id;
}

/* 28j. LE PARTI NELLA RICERCA: NOMI, COPIE, DEFINIZIONI
 *
 * (Sta qui, dentro 28d, perché known_open() la usa; la lettera è venuta
 * dopo le altre.)
 *
 * Un quantificatore su parti (17u) si usa come uno su elementi, con una
 * parte al posto di un elemento:
 *
 *   - 28-2 per le parti. Da "esiste una parte X di S con P(X)" si prende una
 *     tale parte e le si dà un nome nuovo, X_1: vale P(X_1).
 *   - 28-3 per le parti. Da "per ogni parte X di S vale P(X)", e da una
 *     parte D di S, segue P(D). Quali D provare lo dice 28k.
 *
 * Una parte D si sa nominare quando è un simbolo: una parte dichiarata, una
 * nata da 28-2, oppure una DEFINITA da una regola, "sia D = \{x \in S \mid
 * c(x)\}", con c fatta di ciò che c'è già. Una definizione è un passo
 * valido: per l'assioma di separazione, per ogni insieme S e ogni condizione
 * c c'è la parte degli x di S per cui c vale (vuota, se non vale per
 * nessuno; e se S è vuoto c'è comunque, ed è vuota). D è un nome nuovo, e di
 * lei si sa solo "per ogni x di S, x \in D se e solo se c(x)" (K_DEFINED):
 * nulla di ciò che si sapeva prima cambia. Anche una parte di un insieme
 * vuoto esiste, quindi una parte, nominata o definita, non chiede mai che
 * un insieme abbia elementi; è c che può nominarne uno, come \{a\}, e allora
 * la definizione vale solo dove a c'è (lo controlla il verificatore, 11g).
 *
 * P(D) è P(X) con D al posto di X: una copia dell'albero (sentence_rename()),
 * nell'arena come l'enunciato. Da lì in poi una condizione nota che viene da
 * una copia è come le altre: si apre, si istanzia, si scrive e si
 * ricontrolla allo stesso modo. Il controllo di 28e rilegge ogni copia con
 * sentence_renamed(), che confronta i due alberi nodo per nodo senza
 * ricostruirli: un controllo diverso da chi ha fatto la copia. */

/* Ritorna 1 se s è un quantificatore su parti. */
static int part_quantifier(const Sentence *s) { return s->kind == S_FORALL_PART || s->kind == S_EXISTS_PART; }

/* Ritorna l'elemento e con il simbolo to al posto di from; dove nulla
 * cambia, e stesso. */
static Elem *elem_rename(Elem *e, int from, int to) {
    if (e->symbol < 0) return e;
    Elem *a = e->arg[0] ? elem_rename(e->arg[0], from, to) : NULL, *b = e->arg[1] ? elem_rename(e->arg[1], from, to) : NULL;
    if (e->symbol != from && a == e->arg[0] && b == e->arg[1]) return e;
    return elem_new(e->symbol == from ? to : e->symbol, 0, a, b);
}

/* Ritorna la condizione s con la parte to al posto della parte legata
 * from: ogni from applicato a qualcosa diventa to applicato alla stessa
 * cosa. Un quantificatore interno che lega di nuovo from (le copie di 17q
 * possono farlo) la nasconde, e lì non cambia nulla. Dove nulla cambia si
 * riusa s; se l'arena è piena annota exhausted.
 *
 * Perché i cast: i nodi sono nell'arena, scrivibili, e l'albero letto non
 * cambia mai; una copia ne condivide i pezzi che restano uguali. */
static const Sentence *sentence_rename(const Sentence *s, int from, int to) {
    if (part_quantifier(s) && s->part == from) return s;
    Elem *left = s->left ? elem_rename(s->left, from, to) : NULL, *right = s->right ? elem_rename(s->right, from, to) : NULL;
    const Sentence *a = s->a ? sentence_rename(s->a, from, to) : NULL, *b = s->b ? sentence_rename(s->b, from, to) : NULL;
    if (left == s->left && right == s->right && a == s->a && b == s->b) return s;
    Sentence *copy = arena_alloc(sizeof *copy);
    if (!copy) { exhausted = 1; return s; }
    *copy = *s;
    copy->left = left;
    copy->right = right;
    copy->a = (Sentence *)a;
    copy->b = (Sentence *)b;
    return copy;
}

/* Il simbolo che deve stare in una copia al posto di symbol: to[i] se
 * symbol è from[i], per qualche i < count; altrimenti lui stesso. */
static int renamed_symbol(int symbol, const int *from, const int *to, int count) {
    for (int i = 0; i < count; i++)
        if (from[i] == symbol) return to[i];
    return symbol;
}

/* Ritorna 1 se l'elemento e è scritto come original con to[i] al posto di
 * from[i], per ogni i < count (con count = 0: scritto allo stesso modo). */
static int elem_renamed(const Elem *e, const Elem *original, const int *from, const int *to, int count) {
    if (!e || !original) return e == original;
    if (e->symbol < 0 || original->symbol < 0) return e->symbol == original->symbol && e->slot == original->slot;
    return e->symbol == renamed_symbol(original->symbol, from, to, count) && elem_renamed(e->arg[0], original->arg[0], from, to, count) &&
           elem_renamed(e->arg[1], original->arg[1], from, to, count);
}

/* Ritorna 1 se la condizione s è scritta come original con to[i] al posto
 * della parte legata from[i], per ogni i < count: il controllo di una copia
 * fatta da sentence_rename(), che guarda solo come sono scritti i due
 * alberi. Sotto un quantificatore che lega di nuovo from[i], from[i] resta
 * com'è. Con count = 0 dice se i due alberi sono scritti allo stesso modo.
 * Una copia temporanea fallita segnala failure e ritorna zero. */
static int sentence_renamed(const Sentence *s, const Sentence *original, const int *from, const int *to, int count) {
    if (!s || !original) return s == original;
    if (s->kind != original->kind || s->slot != original->slot || s->part != original->part) return 0;
    if (!elem_renamed(s->left, original->left, from, to, count) || !elem_renamed(s->right, original->right, from, to, count)) return 0;

    /* Solo un quantificatore che nasconde un nome richiede una mappa nuova.
     * Negli altri nodi si condividono i vettori del chiamante, senza copie. */
    int hidden = 0;
    if (part_quantifier(original))
        for (int i = 0; i < count; i++) hidden |= original->part == from[i];
    if (!hidden)
        return sentence_renamed(s->a, original->a, from, to, count) && sentence_renamed(s->b, original->b, from, to, count);
    int *inner = NULL; size_t capacity = 0;
    if (!work_reserve((void **)&inner, &capacity, 2 * (size_t)count, sizeof *inner)) return 0;
    int used = 0;
    for (int i = 0; i < count; i++) if (original->part != from[i]) {
        inner[used] = from[i]; inner[count + used++] = to[i];
    }
    int same = sentence_renamed(s->a, original->a, inner, inner + count, used) &&
               sentence_renamed(s->b, original->b, inner, inner + count, used);
    free(inner);
    return same;
}

/* Ritorna 1 se il simbolo symbol compare nell'elemento e. */
static int elem_mentions(const Elem *e, int symbol) {
    return e && (e->symbol == symbol || elem_mentions(e->arg[0], symbol) || elem_mentions(e->arg[1], symbol));
}

/* Ritorna 1 se il simbolo symbol compare nella condizione s. */
static int sentence_mentions(const Sentence *s, int symbol) {
    return s && (elem_mentions(s->left, symbol) || elem_mentions(s->right, symbol) || sentence_mentions(s->a, symbol) ||
                 sentence_mentions(s->b, symbol));
}

/* Ritorna 1 se il simbolo di posto symbol è una parte che si può mettere al
 * posto di una parte legata di sort: una parte dell'insieme sort, non
 * legata, non una famiglia. */
static int part_of(int symbol, int sort) {
    if (symbol < 0 || symbol >= symbol_count) return 0;
    const Symbol *s = &symbols[symbol];
    return !symbol_bound[symbol] && s->arity == 1 && s->range == TRUTH && !s->family && s->domain[0] == sort;
}

/* Registra una parte nuova dell'insieme sort, che si chiama con la lettera
 * letter e il primo pedice da first in su che nessun simbolo abbia, e le dà
 * il numero d'ordine dei nomi (28f). Ritorna il suo posto in symbols[], o -1
 * se non c'è più posto (e annota exhausted). */
static int part_symbol_new(int letter, int sort, int first) {
    Symbol part = {letter, first, 1, {sort, 0}, TRUTH, 0, 0};
    while (symbol_find(part.name, part.index) >= 0) {
        if (part.index == INT_MAX) { exhausted = 1; return -1; }
        part.index++;
    }
    int id = proof_symbol_append(part);
    if (id < 0) return -1;
    symbol_law[id] = 0;
    symbol_generation[id] = 1;
    name_serial[id] = ++names_given;
    name_known[id] = -1;
    return id;
}

/* 28-2 per una parte: dalla condizione nota di posto i, "esiste una parte X
 * di S con P(X)" (o "non per ogni parte X di S vale P(X)"), dà alla parte un
 * nome nuovo, la lettera di X con il primo pedice libero, e aggiunge P del
 * nome con il segno della condizione. */
static void part_name(int i) {
    const Sentence *s = now->known[i].source;
    int part = part_symbol_new(symbols[s->part].name, symbols[s->part].domain[0], 0);
    if (part < 0) return;
    int named = known_add(sentence_rename(s->a, s->part, part), now->known[i].negated, now->known[i].value, K_NAMED, i);
    if (named < 0) return;
    int chosen = part;
    if (!known_parts(named, &chosen, 1)) return;
    name_known[part] = named;
}

/* 28q. L'EQUIPOTENZA: BIIEZIONI CON UN NOME, BIIEZIONI COSTRUITE
 *
 * (Sta qui, dentro 28d, perché known_open() e instantiate() la usano; la
 * lettera è venuta dopo le altre. La seconda metà, la grammatica dei
 * testimoni, sta più avanti, accanto alle istanze.)
 *
 * A \sim B (17w di parser.c) vuol dire che c'è una biiezione da A a B. Il
 * capitolo la usa nella forma "ci sono \varphi \colon A \to B e \psi \colon
 * B \to A, una l'inversa dell'altra":
 *
 *     D(\varphi, \psi) =  \forall x \in A\ (\psi(\varphi(x)) = x)
 *                         \land \forall y \in B\ (\varphi(\psi(y)) = y).
 *
 * Le due forme sono equivalenti, e senza l'assioma della scelta. Se \varphi è
 * una biiezione, per ogni y di B c'è uno e un solo x con \varphi(x) = y (uno
 * perché \varphi è suriettiva, uno solo perché è iniettiva): \psi(y) è quel
 * x, una descrizione e non una scelta, e D vale. Viceversa da D: se
 * \varphi(a) = \varphi(b) allora a = \psi(\varphi(a)) = \psi(\varphi(b)) = b,
 * e ogni y è \varphi(\psi(y)). Con un lato prodotto, A = A_{1} \times A_{2},
 * x è una coppia e \psi(\varphi(x)) = x vale componente per componente; una
 * applicazione verso un prodotto sono le sue due componenti, ognuna di due
 * argomenti se parte da un prodotto (17w).
 *
 * L'equipotenza è dunque un "esiste" su due applicazioni, e il capitolo la
 * usa con le due regole di sempre:
 *
 *   28q-1. Un nome. Da A \sim B vera nel ramo nascono due applicazioni nuove,
 *          \varphi_{k} e \psi_{k}, e vale D(\varphi_{k}, \psi_{k}): è 28-2 per
 *          una biiezione. I nomi sono nuovi, quindi nulla di ciò che si
 *          sapeva cambia.
 *   28q-2. Un'istanza. Da A \sim B falsa, cioè "per ogni \varphi e \psi, non
 *          D(\varphi, \psi)", segue \lnot D(\gamma, \delta) per due
 *          applicazioni \gamma e \delta che ci sono: è 28-3. Le si costruisce
 *          con la grammatica dei testimoni (più avanti), dando un nome a
 *          ognuna con la sua DEFINIZIONE (K_MAPDEF), in una di tre forme:
 *
 *     d1. \gamma(x) = t, con t un termine in cui \gamma non compare;
 *     d2. \gamma(X) parte di C: \forall y \in C\ (y \in \gamma(X) \iff c), con c
 *         una condizione in cui \gamma non compare;
 *     d3. \gamma(f) applicazione da E: \forall y \in E, e per \gamma(f)(y) una
 *         delle tre forme, ricorsivamente.
 *
 * Una definizione è un passo valido. Per ogni valore degli argomenti c'è
 * uno e un solo oggetto che la soddisfa: il valore di t; la parte \{y \in C
 * \mid c\}, che sta in \mathcal{P}(C) perché lì ci sono tutte le parti; la
 * applicazione che a ogni y dà l'oggetto della forma interna, che sta in
 * C^{E} perché lì ci sono tutte le applicazioni. Uno solo, perché due parti
 * con gli stessi elementi, e due applicazioni con gli stessi valori, sono la
 * stessa (28n). Quindi l'applicazione \gamma esiste, senza scegliere nulla,
 * e il suo nome è nuovo: come per le parti definite (28j), darglielo non
 * cambia nulla di ciò che si sapeva. Il verificatore controlla da sé la forma
 * di ogni definizione (11j di checker.c).
 *
 * Che \gamma e \delta siano una l'inversa dell'altra non lo si suppone mai: è
 * ciò che la dimostrazione deve ottenere, per assurdo, dalle definizioni,
 * dalle identità delle biiezioni con un nome e dall'estensionalità (28n),
 * con le istanze di sempre. Le istanze di una definizione si prendono dove
 * l'applicazione definita compare (instance_mapdef()), come per le parti di
 * 28j. Il numero degli elementi non entra mai: nessuna regola dice che
 * equipotenti vuol dire "con tanti elementi quanti"; lo dicono solo i
 * modelli finiti, dove è un conto (model_equipotent()).
 *
 * Le variabili delle identità sono quelle del nodo (17w); quelle delle
 * definizioni, due per insieme, nascono una volta per enunciato
 * (bijection_prepare()): una definizione è una condizione chiusa, e due
 * condizioni chiuse possono legare la stessa variabile senza confondersi. */

/* 28q. Ritorna il quantificatore kind sulla variabile di posto slot davanti a
 * body. I nodi costruiti qui e dalle leggi delle parti (28n) non hanno
 * testo nell'enunciato: start ed end sono vuoti, e non si stampano mai come
 * testo. */
static Sentence *axiom_bind(SentenceKind kind, int slot, Sentence *body) {
    Sentence *s = sentence_new(kind, body, NULL, "");
    s->end = s->start;
    s->slot = slot;
    return s;
}

/* 28q. Ritorna la condizione kind tra gli elementi left e right:
 * un'uguaglianza (S_EQUAL), o l'appartenenza (S_HOLDS) del simbolo symbol
 * applicato a left e right. */
static Sentence *axiom_atom(SentenceKind kind, int symbol, Elem *left, Elem *right) {
    Sentence *s = sentence_new(kind, NULL, NULL, "");
    s->end = s->start;
    s->left = kind == S_HOLDS ? elem_new(symbol, 0, left, right) : left;
    s->right = kind == S_HOLDS ? NULL : right;
    return s;
}

/* 28q. Ritorna il connettivo kind tra a e b, senza semplificare nulla: la
 * forma è quella che il verificatore riconosce. */
static Sentence *axiom_join(SentenceKind kind, Sentence *a, Sentence *b) {
    Sentence *s = sentence_new(kind, a, b, "");
    s->end = s->start;
    return s;
}

/* 28q. Ritorna la variabile di posto slot, come elemento. */
static Elem *slot_elem(int slot) { return elem_new(-1, slot, NULL, NULL); }

/* 28q. Ritorna il simbolo di posto symbol applicato ai primi count elementi
 * di arg[] (count da 0 a 2). */
static Elem *map_apply(int symbol, Elem *const *arg, int count) {
    return elem_new(symbol, 0, count > 0 ? arg[0] : NULL, count > 1 ? arg[1] : NULL);
}

/* 28q. Ritorna l'insieme della componente i del lato k dell'equipotenza e. */
static int side_sort(const Sentence *e, int k, int i) { return slot_data[e->side_slot[k][i]].sort; }

/* 28q. Ritorna il nome interno della lettera greca word (greek_letters[],
 * 17o). */
static int greek_name(const char *word) {
    for (size_t i = 0; i < sizeof greek_letters / sizeof *greek_letters; i++)
        if (strcmp(greek_letters[i], word) == 0) return GREEK_NAMES + (int)i;
    return GREEK_NAMES;
}

/* 28q. Registra un'applicazione nuova, di nome la lettera greca word con il
 * primo pedice da 1 in su che nessun simbolo abbia, con arity argomenti
 * negli insiemi domain[] e il valore nell'insieme range; le dà il numero
 * d'ordine dei nomi (28f). Ritorna il suo posto in symbols[], o -1 se non c'è
 * più posto (e annota exhausted). */
static int map_symbol_new(const char *word, int arity, const int *domain, int range) {
    Symbol map = {greek_name(word), 1, arity, {arity > 0 ? domain[0] : 0, arity > 1 ? domain[1] : 0}, range, 0, 0};
    while (symbol_find(map.name, map.index) >= 0) {
        if (map.index == INT_MAX) { exhausted = 1; return -1; }
        map.index++;
    }
    int id = proof_symbol_append(map);
    if (id < 0) return -1;
    symbol_law[id] = 0;
    symbol_generation[id] = 0;
    name_serial[id] = ++names_given;
    name_known[id] = -1;
    return id;
}

/* 28q. Ritorna le identità D dell'equipotenza e (vedi la testa del
 * paragrafo) per le applicazioni di map[]: in map[0..n) le componenti di
 * quella da A a B, in map[n..n+m) quelle dell'inversa, con m e n le
 * componenti dei lati A e B. La forma, che il verificatore costruisce allo
 * stesso modo (ck_identities() in checker.c), è
 *
 *     (\forall x_{1} \forall x_{2}\ (\psi_{1}(\varphi(x)) = x_{1} \land \psi_{2}(\varphi(x)) = x_{2}))
 *     \land (\forall y_{1} ... )
 *
 * con le variabili del nodo, la più esterna per prima, e \varphi(x) scritto
 * come le n componenti \varphi_{j}(x_{1}, x_{2}). Con una componente sola
 * l'uguaglianza è una, senza congiunzione. */
static Sentence *equipotent_identities(const Sentence *e, const int *map) {
    Sentence *half[2];
    for (int k = 0; k < 2; k++) {
        /* Per k = 0: le variabili di A, e \psi dopo \varphi; per k = 1 quelle
         * di B, e \varphi dopo \psi. */
        int m = e->sides[k], n = e->sides[1 - k];
        const int *first = k ? map + e->sides[1] : map, *second = k ? map : map + e->sides[1];
        Elem *x[2], *inner[2];
        Sentence *body = NULL;
        for (int i = 0; i < m; i++) x[i] = slot_elem(e->side_slot[k][i]);
        for (int j = 0; j < n; j++) inner[j] = map_apply(first[j], x, m);
        for (int i = 0; i < m; i++) {
            Sentence *equal = axiom_atom(S_EQUAL, -1, map_apply(second[i], inner, n), x[i]);
            body = body ? axiom_join(S_AND, body, equal) : equal;
        }
        for (int i = m - 1; i >= 0; i--) body = axiom_bind(S_FORALL, e->side_slot[k][i], body);
        half[k] = body;
    }
    return axiom_join(S_AND, half[0], half[1]);
}

/* 28q. Gli insiemi della componente j delle applicazioni delle identità di
 * e, nell'ordine di map[] in equipotent_identities(): mette quelli degli
 * argomenti in domain[] e ne ritorna quanti sono, quello del valore in
 * *range. */
static int identity_map_sorts(const Sentence *e, int j, int *domain, int *range) {
    int forward = j < e->sides[1], from = forward ? 0 : 1;
    *range = forward ? side_sort(e, 1, j) : side_sort(e, 0, j - e->sides[1]);
    for (int a = 0; a < e->sides[from]; a++) domain[a] = side_sort(e, from, a);
    return e->sides[from];
}

/* 28q-1. Dalla condizione nota di posto i, l'equipotenza vera A \sim B, dà
 * un nome alla biiezione da A a B, \varphi, e alla sua inversa, \psi (una
 * applicazione per componente), e aggiunge le loro identità. */
static void bijection_name(int i) {
    const Sentence *e = now->known[i].source;
    int map[4];
    int count = e->sides[0] + e->sides[1];
    for (int j = 0; j < count; j++) {
        int domain[2], range, arity = identity_map_sorts(e, j, domain, &range);
        map[j] = map_symbol_new(j < e->sides[1] ? "varphi" : "psi", arity, domain, range);
        if (map[j] < 0) return;
    }
    int named = known_add(equipotent_identities(e, map), 0, now->known[i].value, K_BIJECTION, i);
    if (named < 0) return;
    if (!known_parts(named, map, count)) return;
    for (int j = 0; j < count; j++) name_known[map[j]] = named;
}

/* Guarda per la prima volta la condizione nota di posto i, e ne trae ciò
 * che non richiede scelte: un fatto entra tra le uguaglianze o tra i
 * "diversi"; di una congiunzione si aggiungono le due parti (28-1); un
 * "esiste" riceve un nome (28-2); una disgiunzione e un "per ogni" restano
 * in attesa. */
static void known_open(int i) {
    Known *k = &now->known[i];
    const Sentence *s = k->source;
    Parts p;
    k->stage = K_DONE;
    switch (s->kind) {
    case S_TRUE: case S_NOT:
        return;
    case S_EQUAL: case S_HOLDS:
        k->left = (short)elem_ground(s->left, k->value, G_CREATE);
        k->right = (short)(s->kind == S_EQUAL ? elem_ground(s->right, k->value, G_CREATE) : 0);
        if (k->left < 0 || k->right < 0) { k->left = k->right = -1; exhausted = 1; return; }
        if (k->negated && now->differents < MAX_DIFFERENT) now->different[now->differents++] = (short)i;
        else if (k->negated) exhausted = 1;
        else if (now->rep[k->left] != now->rep[k->right]) classes_join(k->left, k->right, i);
        return;
    case S_AND: case S_OR: case S_IMPLIES: case S_IFF:
        if (sentence_parts(s, k->negated, &p) && p.conjunction) {
            known_add(p.x, p.nx, k->value, K_PART, i);
            known_add(p.y, p.ny, k->value, K_PART, i);
            return;
        }
        sentence_ground(s, k->value);
        k->stage = K_WAITING;
        return;
    case S_FORALL_PART: case S_EXISTS_PART:
        /* 28j. Un "per ogni parte" aspetta le sue parti (28k); un "esiste
         * una parte" dà un nome. */
        if ((s->kind == S_FORALL_PART) != k->negated) k->stage = K_RULE;
        else part_name(i);
        return;
    case S_EQUIPOTENT:
        /* 28q. Vera, una biiezione con un nome (28q-1); falsa, è un "per
         * ogni" su due applicazioni, che aspetta il suo testimone (28q-2). */
        if (k->negated) k->stage = K_RULE;
        else bijection_name(i);
        return;
    case S_FORALL: case S_EXISTS:
        break;
    case S_MEMBER: case S_INCLUDED: case S_SAME: case S_UNIQUE:
        /* Non arrivano qui: lo svolgimento (17q) li toglie. */
        return;
    }
    if ((s->kind == S_FORALL) != k->negated) { k->stage = K_RULE; return; }

    /* 28-2. Un nome nuovo: la lettera della variabile, con il primo pedice
     * che non sia già di un altro simbolo. */
    Symbol name = {slot_data[s->slot].letter, 0, 0, {0, 0}, slot_data[s->slot].sort, 0, 0};
    SlotValues value = SLOT_VALUES_EMPTY;
    while (symbol_find(name.name, name.index) >= 0) {
        if (name.index == INT_MAX) { exhausted = 1; return; }
        name.index++;
    }
    int id = proof_symbol_append(name);
    if (id < 0) return;
    symbol_law[id] = known_law(i) != LAW_NONE;
    symbol_generation[id] = (unsigned char)known_generation(k);
    name_serial[id] = ++names_given;
    name_known[id] = -1;
    value = slot_values_copy(k->value);
    if (work_allocation_failed) { exhausted = 1; return; }
    value.data[s->slot] = (short)ground_lookup(id, -1, -1, G_CREATE);
    if (slot_values_get(value, s->slot) >= 0) name_known[id] = known_add(s->a, k->negated, value, K_NAMED, i);
}

/* 28-1. Riguarda la disgiunzione in attesa di posto i alla luce di ciò che
 * si sa adesso. Se una parte è vera non c'è altro da trarne; se una è
 * falsa, vale l'altra, che entra in elenco; se lo sono tutte e due il ramo
 * si chiude, e clash_choice lo annota. Un "se e solo se" si tratta allo
 * stesso modo: saputa una parte, l'altra è decisa. Ritorna 1 se ha
 * aggiunto qualcosa o chiuso il ramo. */
static int known_decide(int i) {
    Known *k = &now->known[i];
    const Sentence *s = k->source;
    Parts p;
    if (s->kind == S_IFF) {
        int a = truth(s->a, 0, k->value), b = truth(s->b, 0, k->value);
        if (a < 0 && b < 0) return 0;
        k->stage = K_DONE;
        if (a >= 0 && b >= 0) {
            if ((a == b) != k->negated) return 0;
            clash_choice = i;
        } else if (a >= 0) {
            known_add(s->b, a ? k->negated : !k->negated, k->value, K_PART, i);
        } else {
            known_add(s->a, b ? k->negated : !k->negated, k->value, K_PART, i);
        }
        return 1;
    }
    sentence_parts(s, k->negated, &p);
    int x = truth(p.x, p.nx, k->value), y = truth(p.y, p.ny, k->value);
    if (x != 0 && y != 0 && x != 1 && y != 1) return 0;
    k->stage = K_DONE;
    if (x == 1 || y == 1) return 0;
    if (x == 0 && y == 0) clash_choice = i;
    else if (x == 0) known_add(p.y, p.ny, k->value, K_PART, i);
    else known_add(p.x, p.nx, k->value, K_PART, i);
    return 1;
}

/* Trae da ciò che si sa tutto ciò che non richiede istanze né scelte:
 * apre le condizioni nuove, chiude per congruenza, riguarda le disgiunzioni
 * in attesa, finché nulla cambia. Ritorna 1 se il ramo si è chiuso con una
 * contraddizione, annotata in clash_fact o clash_choice. */
static int settle(void) {
    clash_fact = clash_choice = -1;
    for (int changed = 1; changed && !exhausted; ) {
        changed = 0;
        for (int i = 0; i < now->knowns && !exhausted; i++) {
            if (now->known[i].stage != K_NEW) continue;
            known_open(i);
            changed = 1;

            /* Il falso, una disgiunzione senza parti (lo svolgimento lo
             * lascia, per esempio, per un'immagine dell'insieme vuoto): il
             * ramo è chiuso. */
            if (now->known[i].source->kind == S_TRUE && now->known[i].negated) { clash_choice = i; return 1; }
        }
        closure();

        /* Una contraddizione: due elementi che si sanno diversi sono finiti
         * nella stessa classe. */
        for (int i = 0; i < now->differents; i++) {
            const Known *k = &now->known[now->different[i]];
            if (now->rep[k->left] == now->rep[k->right]) { clash_fact = now->different[i]; return 1; }
        }
        for (int i = 0; i < now->knowns && !exhausted; i++) {
            if (now->known[i].stage != K_WAITING || !known_decide(i)) continue;
            if (clash_choice >= 0) return 1;
            changed = 1;
        }
    }
    return 0;
}

/* Un "per ogni" noto, pronto per le sue istanze (28-3): le variabili dei
 * "per ogni" consecutivi con cui la condizione comincia, e ciò che li
 * segue. */
typedef struct {
    int known;             /* il suo posto in known[] */
    const int *slot;       /* variabili dalla piu esterna, prestito dal chiamante */
    int slots;             /* numero di variabili nel vettore slot */
    SlotSet all;     /* le stesse, come bit: il bit i è la variabile di posto i */
    const Sentence *body;  /* la condizione che segue i "per ogni" */
    int negated;           /* il segno con cui è vera */
} Rule;

/* Aggiunge all'elenco l'istanza di rule con gli elementi di value[] al
 * posto delle sue variabili, se non c'è già: due istanze su elementi uguali
 * per ciò che si sa sono la stessa. Ritorna 1 se l'ha aggiunta. */
static int instance_add(const Rule *rule, SlotValues value) {
    if (work_allocation_failed) return 0;
    for (int j = 0; j < rule->slots; j++)
        if (slot_values_get(value, rule->slot[j]) < 0) return 0;
    for (int i = rule->known + 1; i < now->knowns; i++) {
        const Known *k = &now->known[i];
        int same = k->parent == rule->known && k->origin == K_INSTANCE;
        for (int j = 0; j < rule->slots && same; j++) {
            int a = slot_values_get(k->value, rule->slot[j]), b = slot_values_get(value, rule->slot[j]);
            same = a >= 0 && now->rep[a] == now->rep[b];
        }
        if (same) return 0;
    }
    return known_add(rule->body, rule->negated, value, K_INSTANCE, rule->known) >= 0;
}

/* Ritorna le variabili che compaiono nell'elemento e, come bit. */
static SlotSet elem_slots(const Elem *e) {
    if (!e) return SLOT_EMPTY;
    if (e->symbol < 0) return slot_set_single(e->slot);
    return slot_set_union(elem_slots(e->arg[0]), elem_slots(e->arg[1]));
}

/* Confronto di uno schema con gli elementi presenti. Cerca ogni modo di
 * dare un elemento alle variabili ancora libere in value[] così che ogni
 * schema pattern[i], per i < count, diventi uguale, per ciò che si sa,
 * all'elemento target[i]; per ogni modo trovato aggiunge l'istanza di rule,
 * e ritorna quante ne ha aggiunte. I due elenchi hanno MAX_PATTERN posti e
 * vengono usati come pila: uno schema così annidato da riempirla non viene
 * confrontato.
 *
 * Una variabile libera prende l'elemento che ha di fronte; una già fissata
 * deve essergli uguale. Un simbolo applicato deve trovare, nella classe di
 * ciò che ha di fronte, un elemento con lo stesso simbolo: ce ne possono
 * essere più d'uno, e si provano tutti. È così che (x \perp y) \perp z
 * trova e \perp c quando si sa che e = b \perp a: x = b, y = a, z = c. */
static int instance_match(const Rule *rule, const Elem **pattern, short *target, int count, SlotValues value) {
    if (count == 0) return instance_add(rule, value);
    const Elem *p = pattern[count - 1];
    int facing = target[count - 1], made = 0;
    if (p->symbol < 0) {
        int fixed = slot_values_get(value, p->slot);
        if (fixed >= 0) return now->rep[fixed] == now->rep[facing] ? instance_match(rule, pattern, target, count - 1, value) : 0;
        value.data[p->slot] = (short)facing;
        made = instance_match(rule, pattern, target, count - 1, value);
        value.data[p->slot] = -1;
        return made;
    }
    for (int id = 1; id < now->grounds && !exhausted && count < MAX_PATTERN; id++) {
        if (now->rep[id] != now->rep[facing] || ground[id].symbol != p->symbol) continue;
        int next = count - 1;
        for (int i = 0; i < 2 && p->arg[i]; i++) { pattern[next] = p->arg[i]; target[next++] = ground[id].arg[i]; }
        made += instance_match(rule, pattern, target, next, value);
    }
    pattern[count - 1] = p;
    target[count - 1] = (short)facing;
    return made;
}

/* 28-3, le istanze che riscrivono un elemento presente. Per ogni elemento
 * scritto nella condizione s (fuori dai quantificatori più interni) che sia
 * un simbolo applicato e contenga tutte le variabili di rule, cerca gli
 * elementi presenti che gli corrispondono e aggiunge quelle istanze.
 * Ritorna quante ne ha aggiunte. */
static int instance_rewrite_elem(const Rule *rule, const Elem *e) {
    const Elem *pattern[MAX_PATTERN];
    short target[MAX_PATTERN];
    SlotValues value = SLOT_VALUES_EMPTY;
    int made = 0;
    if (e->symbol < 0) return 0;
    for (int i = 0; i < 2 && e->arg[i]; i++) made += instance_rewrite_elem(rule, e->arg[i]);
    if (!e->arg[0] || symbols[e->symbol].range == TRUTH || !slot_set_includes(elem_slots(e), rule->all)) return made;
    value = slot_values_copy(now->known[rule->known].value);
    if (work_allocation_failed) return 0;
    for (int id = 1, last = now->grounds; id < last && !exhausted; id++) {
        if (ground[id].symbol != e->symbol) continue;
        int count = 0;
        slot_values_load(value, now->known[rule->known].value);
        for (int i = 0; i < 2 && e->arg[i]; i++) { pattern[count] = e->arg[i]; target[count++] = ground[id].arg[i]; }
        made += instance_match(rule, pattern, target, count, value);
    }
    return made;
}

/* Come instance_rewrite_elem(), per tutti gli elementi dei confronti di s. */
static int instance_rewrite(const Rule *rule, const Sentence *s) {
    if (s->kind == S_FORALL || s->kind == S_EXISTS || part_quantifier(s) || s->kind == S_TRUE || s->kind == S_EQUIPOTENT) return 0;
    if (s->kind == S_EQUAL || s->kind == S_HOLDS) return instance_rewrite_elem(rule, s->left) + (s->right ? instance_rewrite_elem(rule, s->right) : 0);
    return instance_rewrite(rule, s->a) + (s->b ? instance_rewrite(rule, s->b) : 0);
}

/* Esamina, senza aggiungere nulla, l'elemento e di un'istanza che si pensa
 * di fare, con gli elementi di value[] al posto delle variabili. Ritorna il
 * posto di un elemento uguale a lui per ciò che si sa, o un numero negativo
 * se non c'è; annota in *missing se l'istanza introdurrebbe un elemento
 * nuovo. Un elemento con un nome c'è sempre: l'enunciato lo dà. */
static int instance_elem(const Elem *e, SlotValues value, int *missing) {
    int arg[2] = {-1, -1};
    if (e->symbol < 0) return slot_values_get(value, e->slot) >= 0 ? slot_values_get(value, e->slot) : -2;
    for (int i = 0; i < 2 && e->arg[i]; i++) {
        arg[i] = instance_elem(e->arg[i], value, missing);
        if (arg[i] < 0) return arg[i];
    }
    int found = ground_lookup(e->symbol, arg[0], arg[1], arg[0] < 0 ? G_CREATE : G_CLASS);
    if (found < 0 && symbols[e->symbol].range != TRUTH) *missing = 1;
    return found;
}

/* Come instance_elem(), per tutti i confronti della condizione s che non
 * stanno sotto un quantificatore; annota in più in *decided se di uno di
 * quei confronti si sa già se è vero o falso. */
static void instance_survey(const Sentence *s, SlotValues value, int *missing, int *decided) {
    if (s->kind == S_FORALL || s->kind == S_EXISTS || part_quantifier(s) || s->kind == S_TRUE || s->kind == S_EQUIPOTENT) return;
    if (s->kind == S_EQUAL || s->kind == S_HOLDS) {
        int a = instance_elem(s->left, value, missing), b = s->kind == S_EQUAL ? instance_elem(s->right, value, missing) : 0;
        if (a >= 0 && b >= 0 && (now->rep[a] == now->rep[b] || different_fact(a, b) >= 0)) *decided = 1;
        return;
    }
    instance_survey(s->a, value, missing, decided);
    if (s->b) instance_survey(s->b, value, missing, decided);
}

/* 28o. Con split_lookahead (le prove di ripiego) le istanze sugli elementi
 * con un nome di un "per ogni" di due o più variabili, P_1 \implies P_2
 * \implies ... \implies C, sono tante quante le coppie di nomi, e quasi
 * tutte non servono. Si tengono quelle in cui nessuna premessa P_i si sa
 * falsa (allora l'istanza è vera senza dire nulla) e al più una non si sa:
 * le altre aspettano che se ne sappia di più. Ritorna 1 se l'istanza di
 * rule con gli elementi di value[] è da tenere. */
static int split_lookahead;
static int instance_guarded(const Rule *rule, SlotValues value) {
    int unknown = 0;
    if (rule->negated) return 1;
    for (const Sentence *s = rule->body; s->kind == S_IMPLIES; s = s->b) {
        int known = truth(s->a, 0, value);
        if (known == 0) return 0;
        unknown += known < 0;
    }
    return unknown <= 1;
}

/* 28-3, le istanze per scelta degli elementi. Prova ogni scelta di un
 * elemento per ciascuna variabile di rule, uno per classe: con named = 1
 * tra i soli elementi con un nome, e le prende tutte; con named = 0 tra
 * tutti, e prende quelle che non introducono elementi nuovi e contengono un
 * confronto già deciso. Se le scelte sono troppe non ne prova nessuna.
 * Ritorna quante istanze ha aggiunto. */
static int instance_choices(const Rule *rule, int named) {
    /* Depositi sullo heap riusati fra i giri; nessun Known ne conserva un
     * indirizzo. La routine non richiama ricorsivamente questa ricerca. */
    static short *candidate;
    static int *index;
    static size_t candidate_capacity, index_capacity;
    size_t sorts = (size_t)sort_count;
    if (!work_reserve((void **)&candidate, &candidate_capacity, (size_t)now->grounds, sizeof *candidate) ||
        !work_reserve((void **)&index, &index_capacity, 2 * sorts + (size_t)rule->slots, sizeof *index)) {
        exhausted = 1; return 0;
    }
    int *first = index, *candidates = index + sorts, *pick = index + 2 * sorts;
    int made = 0, law = known_law(rule->known), used = 0;
    for (int sort = 0; sort < sort_count; sort++) first[sort] = -1;
    for (int j = 0; j < rule->slots; j++) first[slot_data[rule->slot[j]].sort] = 0;

    /* Le variabili dello stesso insieme condividono gli stessi candidati.
     * Ogni elemento entra in una sola lista: la memoria non e il prodotto
     * del numero di quantificatori per quello degli elementi presenti. */
    for (int sort = 0; sort < sort_count; sort++) {
        if (first[sort] < 0) continue;
        first[sort] = used; candidates[sort] = 0;
        for (int id = 1; id < now->grounds; id++) {
            if (symbols[ground[id].symbol].range != sort || (named && ground[id].arg[0] >= 0)) continue;
            if (law == LAW_COMPREHENSION && symbol_law[ground[id].symbol]) continue;
            int fresh = 1;
            for (int c = first[sort]; c < used && fresh; c++) fresh = now->rep[candidate[c]] != now->rep[id];
            if (fresh) { candidate[used++] = (short)id; candidates[sort]++; }
        }
    }
    long long choices = 1;
    for (int j = 0; j < rule->slots && choices <= MAX_TUPLES; j++) {
        pick[j] = 0;
        choices *= candidates[slot_data[rule->slot[j]].sort];
    }
    if (choices == 0 || choices > (named ? MAX_FREE_TUPLES : MAX_TUPLES)) return 0;

    SlotValues value;
    value = slot_values_copy(now->known[rule->known].value);
    if (work_allocation_failed) return 0;

    /* Ogni scelta, come un contachilometri. */
    for (int more = 1; more && !exhausted; ) {
        int missing = 0, decided = 0;
        slot_values_load(value, now->known[rule->known].value);
        for (int j = 0; j < rule->slots; j++) {
            int sort = slot_data[rule->slot[j]].sort;
            value.data[rule->slot[j]] = candidate[first[sort] + pick[j]];
        }
        if (!named) instance_survey(rule->body, value, &missing, &decided);
        int kept = !split_lookahead || rule->slots < 2 || instance_guarded(rule, value);
        if (kept && (named || (!missing && decided))) made += instance_add(rule, value);
        more = 0;
        for (int j = 0; j < rule->slots && !more; j++) {
            if (++pick[j] < candidates[slot_data[rule->slot[j]].sort]) more = 1; else pick[j] = 0;
        }
    }
    return made;
}

/* 28l. LE DIMOSTRAZIONI PIÙ LUNGHE: ISTANZE SUGGERITE, CASI CHE SI
 * CHIUDONO SUBITO
 *
 * (Sta qui, dentro 28d, perché le istanze servono a instantiate(); i casi
 * sono più avanti, con cheap_split(), prima di refute(). La lettera è venuta
 * dopo le altre.)
 *
 * Le dimostrazioni con le immagini e le controimmagini svolte sono più
 * lunghe delle altre del capitolo, e chiedono due cose che 28-3 e 28-5 da
 * sole non fanno.
 *
 * Le istanze suggerite da un'uguaglianza.
 * "f(X) \subseteq f(Y)" svolto è "per ogni t di T, se esiste u in X con
 * f(u) = t, allora esiste v in Y con f(v) = t". Chi lo usa sa che x sta in X
 * e prende t = f(x): "f(x) sta in f(X), quindi in f(Y)". Nessuna delle istanze
 * di 28-3 lo fa: f(x) non ha un nome, e nel corpo, fuori dai quantificatori
 * interni, non c'è un confronto che l'istanza decida. Ma il corpo dice quali
 * valori di t contano: t è il valore di f, f(u) = t. Per un "per ogni" su una
 * sola variabile t, ogni uguaglianza del corpo, anche sotto i quantificatori
 * interni, tra t e un simbolo applicato P suggerisce t := G per ogni elemento
 * presente G scritto come P (stessi simboli; al posto delle variabili di P,
 * qualsiasi cosa). Le istanze sono vere comunque (28-3); la regola dice solo
 * quali provare, al più MAX_FREE_TUPLES per giro, e non introduce elementi:
 * G c'è già.
 *
 * I casi che si chiudono subito. Un'istanza come "t \in f(X \cap Y) se e
 * solo se t \in f(X) \cap f(Y)" su un t che non c'entra è una disgiunzione
 * in attesa come quella che serve; distinguendo i casi della prima (28-5),
 * le distinzioni una dentro l'altra (MAX_SPLITS) finiscono su quelle che
 * non c'entrano. Spesso però uno dei due casi di una disgiunzione si chiude
 * con i soli giri di istanze: allora vale l'altro, ed è un passo che non
 * apre davvero due strade. cheap_split() cerca, tra le prime MAX_PROBES
 * disgiunzioni in attesa, una così, ne chiude il caso (la sua dimostrazione
 * scritta è quella di un caso, ricontrollata come le altre) e continua
 * nell'altro senza contarla tra le distinzioni. Se nessuna ha un caso così,
 * si torna a 28-5. La profondità dei rami resta limitata da MAX_BRANCHES. */

/* Ritorna 1 se l'elemento presente id è scritto come lo schema p: gli stessi
 * simboli negli stessi posti, e qualsiasi cosa al posto delle variabili. */
static int ground_fits(int id, const Elem *p) {
    if (p->symbol < 0) return 1;
    const Ground *g = &ground[id];
    if (g->symbol != p->symbol) return 0;
    for (int i = 0; i < 2 && p->arg[i]; i++)
        if (g->arg[i] < 0 || !ground_fits(g->arg[i], p->arg[i])) return 0;
    return 1;
}

/* Aggiunge le istanze del "per ogni" rule, su una sola variabile, suggerite
 * dalle uguaglianze della condizione s tra la variabile e un simbolo
 * applicato (vedi sopra). Ritorna quante ne ha aggiunte; *budget è quante
 * ne può ancora aggiungere. */
static int instance_trigger(const Rule *rule, const Sentence *s, int *budget) {
    if (!s) return 0;
    int made = instance_trigger(rule, s->a, budget) + instance_trigger(rule, s->b, budget), slot = rule->slot[0];
    if (s->kind != S_EQUAL) return made;
    for (int side = 0; side < 2; side++) {
        const Elem *bare = side ? s->right : s->left, *pattern = side ? s->left : s->right;
        if (bare->symbol >= 0 || bare->slot != slot || pattern->symbol < 0 || slot_set_intersects(elem_slots(pattern), rule->all)) continue;
        SlotValues value = slot_values_copy(now->known[rule->known].value);
        if (work_allocation_failed) return made;
        for (int id = 1, last = now->grounds; id < last && *budget > 0 && !exhausted; id++) {
            if (!ground_fits(id, pattern)) continue;
            slot_values_load(value, now->known[rule->known].value);
            value.data[slot] = (short)id;
            if (instance_add(rule, value)) { made++; --*budget; }
        }
    }
    return made;
}

/* 28j. Le istanze della definizione di una parte D (rule, la sua condizione
 * K_DEFINED, "per ogni x, x \in D se e solo se c(x)"): una per ogni elemento
 * e di cui si parla come membro di D, cioè con D(e) presente. È come si usa
 * una definizione a mano, dove serve: provarla su tutti gli elementi con un
 * nome riempirebbe il ramo di equivalenze "s \in D se e solo se s = a" su
 * elementi che non c'entrano, che la distinzione dei casi (28-5) prenderebbe
 * per prime. Ritorna quante istanze ha aggiunto. */
static int instance_definition(const Rule *rule) {
    int part = now->known[rule->known].part[0], made = 0;
    SlotValues value;
    value = slot_values_copy(now->known[rule->known].value);
    if (work_allocation_failed) return 0;
    for (int id = 1, last = now->grounds; id < last && !exhausted; id++) {
        if (ground[id].symbol != part) continue;
        slot_values_load(value, now->known[rule->known].value);
        value.data[rule->slot[0]] = ground[id].arg[0];
        made += instance_add(rule, value);
    }
    return made;
}

/* 28q. LA GRAMMATICA DEI TESTIMONI
 *
 * (La seconda metà di 28q: sta qui, accanto alle istanze, perché il
 * testimone di 28q-2 è un'istanza.)
 *
 * Un testimone di A \sim B si costruisce con ciò che c'è: le biiezioni con un
 * nome tra due insiemi (28q-1) e la forma degli insiemi. Un termine della
 * grammatica è una biiezione da un insieme U a un insieme V:
 *
 *   w1. l'identità, se U = V;
 *   w2. un passo da U a un insieme W, seguito da un termine da W a V. Il
 *       passo è una biiezione con un nome, \varphi_{k} da U o \psi_{k}
 *       all'indietro, oppure uno di w3 e w4;
 *   w3. U = \mathcal{P}(U'), W = \mathcal{P}(W'), e un termine \beta da U' a
 *       W': l'immagine X \mapsto \beta(X), definita con d2 come y \in \gamma(X)
 *       \iff \beta^{-1}(y) \in X, e l'inversa Y \mapsto \beta^{-1}(Y), y \in
 *       \delta(Y) \iff \beta(y) \in Y;
 *   w4. U = U_{2}^{U_{1}}, W = W_{2}^{W_{1}}, e due termini, \alpha da U_{1} a
 *       W_{1} e \beta da U_{2} a W_{2}: f \mapsto \beta \circ f \circ
 *       \alpha^{-1}, definita con d3 come \gamma(f)(y) = \beta(f(\alpha^{-1}(y))),
 *       e l'inversa F \mapsto \beta^{-1} \circ F \circ \alpha.
 *
 * I lati. Con una componente, un termine da A a B. Con due, da A_{1} \times
 * A_{2} a B_{1} \times B_{2}, o componente per componente, (x_{1}, x_{2})
 * \mapsto (\beta_{1}(x_{1}), \beta_{2}(x_{2})), o scambiando, (x_{1}, x_{2})
 * \mapsto (\beta_{1}(x_{2}), \beta_{2}(x_{1})), e l'inversa allo stesso modo:
 * le componenti sono applicazioni di due argomenti, definite con d1. Un
 * termine fatto di un solo passo è già una coppia di applicazioni; ogni
 * altro si scrive con d1, \gamma(x) = \beta(x).
 *
 * Perché i termini sono pochi. Un passo w2 non torna mai su un insieme già
 * toccato, quindi una composizione ha al più tanti passi quanti sono gli
 * insiemi, e w3 e w4 scendono negli insiemi su cui U è costruito, che
 * vengono prima di lui (sort_derived() in parser.c). I termini sono quindi
 * in numero finito; se ne tengono al più MAX_WITNESSES, dai più corti (il
 * numero dei passi, compresi quelli dentro w3 e w4), e la ricerca li prova
 * in quest'ordine, uno per tentativo (claim_attempts()). Il certificato porta
 * quello che ha funzionato, con le sue definizioni.
 *
 * La grammatica non conosce l'enunciato: solo gli insiemi e le biiezioni con
 * un nome nel ramo. Che cosa non costruisce: una biiezione che non è fatta
 * così, come \mathcal{P}(S) \sim \{0, 1\}^{S} o S \times (T \times V) \sim (S
 * \times T) \times V, e i passi con una biiezione con un nome tra prodotti,
 * da un'ipotesi S \times T \sim V. Lì l'enunciato resta NON DIMOSTRATO. */

/* 28q. Un termine della grammatica: una biiezione da from a to, scritta con
 * una delle regole w1-w4. Un passo w2 porta in next il termine che lo
 * segue. I termini vivono in bij[], rifatto per ogni testimone. */
typedef enum { BIJ_SAME, BIJ_NAMED, BIJ_PARTS, BIJ_MAPS } BijKind;
typedef struct {
    BijKind kind;           /* w1, w2 con un nome, w3, w4 */
    int from, to;           /* gli insiemi di partenza e di arrivo */
    int forward, backward;  /* BIJ_NAMED: la biiezione con un nome e la sua inversa, scambiate per un passo
                               all'indietro; BIJ_PARTS, BIJ_MAPS: le applicazioni definite, -1 finché il termine
                               non è scritto (bij_write()). Posti in symbols[] */
    int inner[2];           /* BIJ_PARTS: il termine tra le basi; BIJ_MAPS: quello tra gli insiemi di partenza,
                               poi quello tra gli insiemi d'arrivo. Posti in bij[]; -1 dove non servono */
    int next;               /* il termine da to in poi (w2), o -1 */
    int size;               /* i passi, compresi quelli dentro w3 e w4 */
} Bij;
static Bij bij[MAX_BIJ];
static int bij_count;

/* 28q. Le variabili delle definizioni: due per insieme, nate una volta per
 * enunciato da bijection_prepare(); bij_ready è 0 se non ci sono. */
static int (*bij_slot)[2],bij_ready;
static size_t bij_slot_capacity;

/* 28q. Quale testimone provare, dal più corto (0), e quanti se ne sono
 * trovati al più in un ramo: li usa claim_attempts(). */
static int witness_choice, witness_options;

/* 28q. Ritorna il posto in bij[] di una copia di b, o -1 se non c'è posto. */
static int bij_new(Bij b) {
    if (bij_count == MAX_BIJ) return -1;
    bij[bij_count] = b;
    return bij_count++;
}

/* 28q. Mette il termine t nella lista list[0..*count), ordinata dal più
 * corto, se ci sta tra i primi max; a parità di passi dopo quelli che ci
 * sono già. */
static void bij_keep(int *list, int *count, int max, int t) {
    if (t < 0) return;
    int at = *count;
    while (at > 0 && bij[list[at - 1]].size > bij[t].size) at--;
    if (at >= max) return;
    if (*count < max) ++*count;
    for (int i = *count - 1; i > at; i--) list[i] = list[i - 1];
    list[at] = t;
}

static int bij_terms(int from, int to, SlotSet visited, int *list, int max);

/* 28q. Mette in list[] i passi da from all'insieme step (w2 con un nome, w3,
 * w4), al più max, dai più corti. */
static void bij_steps(int from, int step, int *list, int *count, int max) {
    /* w2: le biiezioni con un nome tra due insiemi, nei due versi. */
    for (int i = 0; i < now->knowns; i++) {
        const Known *k = &now->known[i];
        if (k->origin != K_BIJECTION || k->negated) continue;
        const Sentence *e = now->known[k->parent].source;
        if (e->sides[0] != 1 || e->sides[1] != 1) continue;
        int a = side_sort(e, 0, 0), b = side_sort(e, 1, 0);
        if (a == from && b == step) bij_keep(list, count, max, bij_new((Bij){BIJ_NAMED, from, step, k->part[0], k->part[1], {-1, -1}, -1, 1}));
        if (b == from && a == step) bij_keep(list, count, max, bij_new((Bij){BIJ_NAMED, from, step, k->part[1], k->part[0], {-1, -1}, -1, 1}));
    }

    /* w3 e w4: termini tra gli insiemi su cui sono costruiti. */
    int a[MAX_WITNESSES], b[MAX_WITNESSES], na = 0, nb = 1;
    if (sort_data[from].kind != sort_data[step].kind || (sort_data[from].kind != SORT_PARTS && sort_data[from].kind != SORT_MAPS)) return;
    na = bij_terms(sort_data[from].base, sort_data[step].base, SLOT_EMPTY, a, max);
    if (sort_data[from].kind == SORT_MAPS) nb = bij_terms(sort_data[from].target, sort_data[step].target, SLOT_EMPTY, b, max);
    for (int i = 0; i < na; i++)
        for (int j = 0; j < nb; j++) {
            Bij made = {BIJ_PARTS, from, step, -1, -1, {a[i], -1}, -1, 1 + bij[a[i]].size};
            if (sort_data[from].kind == SORT_MAPS) { made.kind = BIJ_MAPS; made.inner[1] = b[j]; made.size += bij[b[j]].size; }
            bij_keep(list, count, max, bij_new(made));
        }
}

/* 28q. Mette in list[] i termini da from a to che non passano per gli
 * insiemi di visited (indice i: l'insieme di posto i), al più max, dai più
 * corti, e ritorna quanti sono. */
static int bij_terms(int from, int to, SlotSet visited, int *list, int max) {
    int count = 0;
    if (from == to) bij_keep(list, &count, max, bij_new((Bij){BIJ_SAME, from, to, -1, -1, {-1, -1}, -1, 0}));
    visited=slot_set_with(visited,from);
    for (int step = 0; step < sort_count; step++) {
        int first[MAX_WITNESSES], rest[MAX_WITNESSES], steps = 0, rests;
        if (slot_set_contains(visited,step)) continue;
        bij_steps(from, step, first, &steps, max);
        if (!steps) continue;
        rests = bij_terms(step, to, visited, rest, max);
        for (int i = 0; i < steps; i++)
            for (int j = 0; j < rests; j++) {
                Bij made = bij[first[i]];
                if (bij[rest[j]].kind != BIJ_SAME) { made.next = rest[j]; made.size += bij[rest[j]].size; }
                bij_keep(list, &count, max, bij_new(made));
            }
    }
    return count;
}

/* 28q. Ritorna l'elemento x mandato dal termine t, o dal suo inverso se
 * back: la scrittura come termine, con le applicazioni di ogni passo al loro
 * posto. Il termine deve essere scritto (bij_write()). L'inverso di una
 * composizione fa i passi dall'ultimo, ognuno all'indietro. */
static Elem *bij_apply(int t, Elem *x, int back) {
    if (t < 0) return x;
    const Bij *b = &bij[t];
    if (!back) return bij_apply(b->next, b->kind == BIJ_SAME ? x : elem_new(b->forward, 0, x, NULL), 0);
    Elem *rest = bij_apply(b->next, x, 1);
    return b->kind == BIJ_SAME ? rest : elem_new(b->backward, 0, rest, NULL);
}

/* 28q. Aggiunge al ramo la definizione spec dell'applicazione nuova map
 * (K_MAPDEF), e ritorna 0 se non c'è posto. */
static int mapdef_add(Sentence *spec, int map) {
    SlotValues nothing = SLOT_VALUES_EMPTY;

    int i = known_add(spec, 0, nothing, K_MAPDEF, -1);
    if (i < 0) return 0;
    int chosen = map;
    if (!known_parts(i, &chosen, 1)) return 0;
    name_known[map] = i;
    return 1;
}

/* 28q. Dà le loro applicazioni, con le definizioni, ai passi w3 e w4 del
 * termine t e di quelli dentro e dopo di lui, dai più interni (vedi la
 * testa del paragrafo per le forme). Ritorna 0 se non c'è stato posto. */
static int bij_write(int t) {
    if (t < 0) return 1;
    Bij *b = &bij[t];
    int defined = b->kind == BIJ_PARTS || b->kind == BIJ_MAPS;
    if (defined && b->forward >= 0) return 1;  /* già scritto */
    if (!bij_write(b->inner[0]) || !bij_write(b->inner[1]) || !bij_write(b->next)) return 0;
    if (!defined) return 1;
    int forward = map_symbol_new("gamma", 1, &b->from, b->to), backward = map_symbol_new("delta", 1, &b->to, b->from);
    if (forward < 0 || backward < 0) return 0;
    b->forward = forward;
    b->backward = backward;
    for (int side = 0; side < 2; side++) {
        /* side 0: \gamma da from a to; side 1: \delta da to a from. */
        int map = side ? backward : forward, arg = side ? b->to : b->from, value = side ? b->from : b->to, base = sort_data[value].base;
        Elem *object = slot_elem(bij_slot[arg][0]), *y = slot_elem(bij_slot[base][0]), *image = elem_new(map, 0, object, NULL);
        Sentence *spec;
        if (b->kind == BIJ_PARTS) {
            /* d2: y \in \gamma(X) \iff \beta^{-1}(y) \in X; y \in \delta(Y) \iff \beta(y) \in Y. */
            spec = axiom_join(S_IFF, axiom_atom(S_HOLDS, sort_data[value].symbol, y, image), axiom_atom(S_HOLDS, sort_data[arg].symbol, bij_apply(b->inner[0], y, !side), object));
        } else {
            /* d3: \gamma(f)(y) = \beta(f(\alpha^{-1}(y))); \delta(F)(y) = \beta^{-1}(F(\alpha(y))). */
            Elem *inside = elem_new(sort_data[arg].symbol, 0, object, bij_apply(b->inner[0], y, !side));
            spec = axiom_atom(S_EQUAL, -1, elem_new(sort_data[value].symbol, 0, image, y), bij_apply(b->inner[1], inside, side));
        }
        if (!mapdef_add(axiom_bind(S_FORALL, bij_slot[arg][0], axiom_bind(S_FORALL, bij_slot[base][0], spec)), map)) return 0;
    }
    return 1;
}

/* 28q. Un testimone di un'equipotenza, prima di essere scritto con le sue
 * definizioni: per ogni componente j del lato B il termine term[j] (un posto
 * in bij[]; -1 per la seconda di un lato con una sola componente), che parte
 * dalla componente swap ? 1 - j : j del lato A; size è la somma dei passi,
 * che dà l'ordine in cui i testimoni si provano. */
typedef struct {
    int term[2], swap, size;
} Witness;

/* 28q-2. L'istanza della condizione nota di posto r, l'equipotenza falsa A
 * \sim B: costruisce con la grammatica i testimoni, prende quello di numero
 * witness_choice (dal più corto), ne scrive le definizioni e aggiunge
 * \lnot D(\gamma, \delta). Una sola volta per ramo. Ritorna 1 se l'ha
 * aggiunta. */
static int bijection_witness(int r) {
    const Sentence *e = now->known[r].source;
    Witness found[2 * MAX_WITNESSES * MAX_WITNESSES], chosen;
    int count = 0, m = e->sides[0], n = e->sides[1];
    for (int i = r + 1; i < now->knowns; i++)
        if (now->known[i].parent == r && now->known[i].origin == K_BIJECTION) return 0;
    if (!bij_ready || m != n) return 0;

    /* I testimoni: per ogni modo di accoppiare le componenti, un termine per
     * componente; in ordine di passi, a parità prima senza scambio. */
    bij_count = 0;
    for (int swap = 0; swap < m; swap++) {
        int list[2][MAX_WITNESSES], length[2];
        for (int j = 0; j < n; j++) length[j] = bij_terms(side_sort(e, 0, swap ? 1 - j : j), side_sort(e, 1, j), SLOT_EMPTY, list[j], MAX_WITNESSES);
        for (int a = 0; a < length[0]; a++)
            for (int b = 0; b < (n == 2 ? length[1] : 1); b++) {
                Witness w = {{list[0][a], n == 2 ? list[1][b] : -1}, swap, bij[list[0][a]].size + (n == 2 ? bij[list[1][b]].size : 0)};
                int at = count++;
                while (at > 0 && found[at - 1].size > w.size) { found[at] = found[at - 1]; at--; }
                found[at] = w;
            }
    }
    if (count > MAX_WITNESSES) count = MAX_WITNESSES;
    if (count > witness_options) witness_options = count;
    if (witness_choice >= count) return 0;
    chosen = found[witness_choice];

    /* Le applicazioni: quelle di un solo passo con un nome, w3 o w4 se il
     * lato ha una componente; altrimenti nuove, definite con d1. */
    int map[4];
    for (int j = 0; j < n; j++)
        if (!bij_write(chosen.term[j])) return 0;
    const Bij *only = &bij[chosen.term[0]];
    if (m == 1 && only->kind != BIJ_SAME && only->next < 0) {
        map[0] = only->forward;
        map[1] = only->backward;
    } else {
        int domain[2], range;
        for (int j = 0; j < n + m; j++) {
            int arity = identity_map_sorts(e, j, domain, &range);
            if ((map[j] = map_symbol_new(j < n ? "gamma" : "delta", arity, domain, range)) < 0) return 0;
        }
        for (int j = 0; j < n + m; j++) {
            /* \gamma_{j}(x) = \beta_{j}(x_{i}), con i la componente da cui parte
             * \beta_{j}; \delta_{i}(y) = \beta_{j}^{-1}(y_{j}). */
            int forward = j < n, at = forward ? j : j - n, from = forward ? 0 : 1, count_args = e->sides[from];
            int term = forward ? j : (chosen.swap ? 1 - at : at), source = forward ? (chosen.swap ? 1 - j : j) : term;
            Elem *x[2];
            for (int a = 0; a < count_args; a++) x[a] = slot_elem(bij_slot[side_sort(e, from, a)][a]);
            Sentence *spec = axiom_atom(S_EQUAL, -1, map_apply(map[j], x, count_args), bij_apply(chosen.term[term], x[source], !forward));
            for (int a = count_args - 1; a >= 0; a--) spec = axiom_bind(S_FORALL, bij_slot[side_sort(e, from, a)][a], spec);
            if (!mapdef_add(spec, map[j])) return 0;
        }
    }
    int instance = known_add(equipotent_identities(e, map), 1, now->known[r].value, K_BIJECTION, r);
    if (instance < 0) return 0;
    return known_parts(instance, map, n + m);
}

/* 28q. Le istanze della definizione di un'applicazione (rule, una
 * condizione K_MAPDEF): una per ogni elemento presente scritto come la sua
 * forma, \gamma(x), y \in \gamma(X) o \gamma(f)(y), con al posto delle variabili
 * ciò che vi compare. Come per le parti di 28j, la definizione si usa dove
 * l'applicazione compare. Ritorna quante istanze ha aggiunto. */
static int instance_mapdef(const Rule *rule) {
    const Elem *shape = rule->body->kind == S_IFF ? rule->body->a->left : rule->body->left, *pattern[MAX_PATTERN];
    short target[MAX_PATTERN];
    SlotValues value = SLOT_VALUES_EMPTY;
    int made = 0;
    value = slot_values_copy(now->known[rule->known].value);
    if (work_allocation_failed) return 0;
    for (int id = 1, last = now->grounds; id < last && !exhausted; id++) {
        if (ground[id].symbol != shape->symbol) continue;
        int count = 0;
        slot_values_load(value, now->known[rule->known].value);
        for (int i = 0; i < 2 && shape->arg[i]; i++) { pattern[count] = shape->arg[i]; target[count++] = ground[id].arg[i]; }
        made += instance_match(rule, pattern, target, count, value);
    }
    return made;
}

/* 28q. Ritorna 1 se nella condizione s c'è un'equipotenza. */
static int sentence_has_equipotence(const Sentence *s) {
    return s && (s->kind == S_EQUIPOTENT || sentence_has_equipotence(s->a) || sentence_has_equipotence(s->b));
}

/* 28q. Prepara le variabili delle definizioni, due per insieme, se
 * l'enunciato root ha un'equipotenza. Un errore di risorse interrompe la
 * preparazione; una rinuncia lessicale non contamina la prova successiva. */
static void bijection_prepare(const Sentence *root) {
    const char *before = syntax_error;
    bij_ready = 0;
    if (!sentence_has_equipotence(root)) return;
    if (!work_reserve((void **)&bij_slot,&bij_slot_capacity,(size_t)sort_count,sizeof *bij_slot)) return;
    for (int i=0;i<sort_count && syntax_error==before && !work_allocation_failed;i++)
        for (int j=0;j<2 && syntax_error==before && !work_allocation_failed;j++) bij_slot[i][j]=unfold_slot(i);
    bij_ready=syntax_error==before && !work_allocation_failed;
    syntax_error = before;
}

/* 28r. LE ISTANZE SCELTE DA UN MODELLO CANDIDATO
 *
 * (Sta qui, dentro 28d, accanto alle altre istanze; la lettera è venuta dopo
 * le altre.)
 *
 * A che cosa serve. Le istanze di 28-3 si scelgono dalla forma: tutte sui
 * nomi, quelle che riscrivono un elemento presente, quelle che decidono un
 * confronto. Nelle dimostrazioni sulle famiglie di parti (una partizione
 * comune, la controimmagine di una partizione) e sugli ordini tra parti o
 * tra applicazioni le scelte per forma sono migliaia, e quella giusta
 * arriva quando le tabelle sono già piene, oppure non arriva mai: per "ogni
 * elemento a di S sta in un pezzo di F*" serve l'ipotesi "ogni t di T sta in
 * un pezzo di F" con t = f(a), un elemento di cui nessuno parla ancora. Qui
 * le istanze si scelgono dal significato, con un modello.
 *
 * Il modello candidato di un ramo. Gli elementi di ogni insieme sono le
 * classi degli elementi presenti (gli uguali per ciò che si sa sono uno
 * solo); un simbolo applicato vale l'elemento presente scritto così, se c'è,
 * altrimenti un valore "altro", diverso da tutti gli elementi presenti e
 * uguale solo a se stesso; due classi diverse sono elementi diversi; una
 * parte o una relazione vale solo dove si sa che vale. È il modello più
 * piccolo che le uguaglianze e le appartenenze note permettono, e i
 * quantificatori vi si calcolano provando gli elementi presenti: un conto
 * finito. È la tecnica dei dimostratori SMT detta MBQI, "model-based
 * quantifier instantiation" (Ge e de Moura, 2009).
 *
 * La regola. Un "per ogni" noto che nel modello candidato è falso in
 * qualche elemento a dice che il modello non va: l'istanza su a è vera
 * (28-3, come ogni istanza) e nel modello è falsa, quindi aggiungerla
 * costringe il ramo a cambiare. Porta una contraddizione, o un fatto nuovo
 * (il modello cresce), o un "esiste" a cui dare un nome (nasce un elemento),
 * o una disgiunzione da distinguere. Le istanze vere nel modello non dicono
 * nulla di nuovo su di lui, e si lasciano. Così "ogni t di T sta in un pezzo
 * di F", su t = f(a), nel modello è falsa perché i pezzi presenti sono
 * nessuno: l'istanza dà un pezzo nuovo, quello che serve. Per ogni "per ogni"
 * si prende, a ogni giro, la prima istanza falsa sugli elementi in ordine
 * di età: una sola, come fanno i dimostratori SMT, perché ognuna cambia il
 * modello e le altre vanno ricalcolate su quello nuovo.
 *
 * Tre aggiunte, ognuna con il suo perché.
 *
 *   28r-1. Un insieme senza elementi presenti, in cui un'applicazione
 *          dichiarata manda un elemento presente a: si aggiunge f(a). Il
 *          modello deve dare un valore a f(a), e un valore è un elemento:
 *          senza, i "per ogni" su quell'insieme non avrebbero dove provarsi.
 *          f(a) c'è: f è un'applicazione e a un elemento del suo dominio.
 *   28r-2. L'estensionalità di 28n resta come in 28n, provata solo dove un
 *          confronto è già deciso. Nel modello candidato due parti con gli
 *          stessi elementi presenti sembrano uguali in tutto ciò che si
 *          prova, e l'estensionalità sembrerebbe falsa su quasi tutte le
 *          coppie: le sue istanze, che servono solo a distinguere i casi,
 *          riempirebbero i rami.
 *   28r-3. La generazione. Un elemento nato da un "esiste" dentro
 *          un'istanza ha generazione 1 più la più alta degli elementi
 *          dell'istanza; quelli dichiarati e quelli a cui dà un nome
 *          l'enunciato stesso, senza istanze, hanno generazione 0. Il modello
 *          candidato prova solo gli elementi fino a una generazione data.
 *          Senza, un'ipotesi come "ogni x è in relazione con qualche a"
 *          darebbe un elemento nuovo da ogni elemento, e quello un altro, in
 *          una catena senza fine. Le generazioni ammesse crescono come in
 *          una ricerca ad approfondimento progressivo: prima 2, poi 4
 *          (model_generations[]).
 *
 * Quando. Sono le ultime prove di claim_attempts(), dopo quelle di sempre e
 * di 28o: le affermazioni che quelle dimostrano non cambiano, né nella
 * dimostrazione scritta né nel certificato. Il modello cambia solo quali
 * istanze si provano: ognuna è un'istanza di 28-3, scritta, ricontrollata
 * da 28e e portata nel certificato (28f) come le altre, e il verificatore la
 * rilegge senza sapere da dove viene. Le distinzioni di casi, le scelte di
 * parti (28k) e i casi che si chiudono subito (28l) restano quelli di
 * refute(). Il modello candidato non decide mai nulla da solo: non è un
 * controesempio (non tiene conto delle disgiunzioni in attesa, e i suoi
 * insiemi sono solo gli elementi nominati), e non trovarvi istanze false
 * vuol dire solo che la ricerca si ferma. */

/* 1 durante le prove di questo paragrafo: instantiate() sceglie le istanze
 * con il modello candidato. */
static int model_guided;

/* Il valore, nel modello candidato, di un simbolo applicato che non è
 * presente: "altro", diverso da ogni posto di ground[]. */
#define CANDIDATE_ELSE (-3)

/* Le generazioni ammesse nelle prove successive (28r-3), e quella ammessa
 * nella prova in corso. */
static const int model_generations[] = {2, 4};
static int generation_limit;

/* Il modello candidato del ramo in corso: per ogni insieme, un elemento
 * presente per ogni classe (il più vecchio, posto in ground[]), in ordine di
 * età, e quanti sono. Lo rifà candidate_prepare(). candidate_steps conta i
 * passi del calcolo, fino a MAX_CANDIDATE_STEPS per giro di istanze. */
static short (*candidate_domain)[MAX_GROUND];
static int *candidate_size;
static size_t candidate_domain_capacity,candidate_size_capacity;
static long long candidate_steps;

/* Ritorna il valore dell'elemento e nel modello candidato, con le variabili
 * agli elementi di value[]: il rappresentante della sua classe, oppure
 * CANDIDATE_ELSE se e è un simbolo applicato che non è presente (anche
 * perché non lo è un suo argomento). Una parte o una relazione applicata
 * vale la classe di "vero" quando si sa che vale. Va chiamata dopo
 * closure(), come ground_lookup() con G_CLASS. */
static int candidate_term(const Elem *e, SlotValues value) {
    int arg[2] = {-1, -1};
    if (e->symbol < 0) return slot_values_get(value, e->slot) >= 0 ? now->rep[slot_values_get(value, e->slot)] : CANDIDATE_ELSE;
    for (int i = 0; i < 2 && e->arg[i]; i++) {
        arg[i] = candidate_term(e->arg[i], value);
        if (arg[i] == CANDIDATE_ELSE) return CANDIDATE_ELSE;
    }
    int found = ground_lookup(e->symbol, arg[0], arg[1], arg[0] < 0 ? G_EXACT : G_CLASS);
    return found >= 0 ? now->rep[found] : CANDIDATE_ELSE;
}

/* Ritorna il valore della condizione s nel modello candidato, con le
 * variabili libere agli elementi di value[]: 1 vera, 0 falsa, -1 se non si
 * calcola. Non si calcolano i quantificatori su parti di 17u (le loro parti
 * le sceglie 28k), né nulla oltre MAX_CANDIDATE_STEPS passi; un connettivo
 * con una parte che non si calcola vale -1, a meno che l'altra lo decida.
 * value[] viene usato anche per le variabili che s lega, e rimesso com'era. */
static int candidate_holds(const Sentence *s, SlotValues value) {
    int a, b = -1;
    if (++candidate_steps > MAX_CANDIDATE_STEPS) return -1;
    switch (s->kind) {
    case S_TRUE:
        return 1;
    case S_NOT:
        a = candidate_holds(s->a, value);
        return a < 0 ? a : !a;
    case S_EQUAL:
        /* Due "altro" sono lo stesso valore, e nessuno dei due è un
         * elemento presente. */
        return candidate_term(s->left, value) == candidate_term(s->right, value);
    case S_HOLDS:
        return candidate_term(s->left, value) == now->rep[0];
    case S_AND:
        if ((a = candidate_holds(s->a, value)) == 0 || (b = candidate_holds(s->b, value)) == 0) return 0;
        return a == 1 && b == 1 ? 1 : -1;
    case S_OR: case S_IMPLIES:
        a = candidate_holds(s->a, value);
        if (s->kind == S_IMPLIES && a >= 0) a = !a;
        if (a == 1 || (b = candidate_holds(s->b, value)) == 1) return 1;
        return a == 0 && b == 0 ? 0 : -1;
    case S_IFF:
        a = candidate_holds(s->a, value);
        b = candidate_holds(s->b, value);
        return a < 0 || b < 0 ? -1 : a == b;
    case S_FORALL: case S_EXISTS: {
        /* Ogni elemento del modello, finché uno decide. */
        int sort = slot_data[s->slot].sort, every = s->kind == S_FORALL, result = every;
        short saved = slot_values_get(value, s->slot);
        for (int i = 0; i < candidate_size[sort] && result != !every; i++) {
            value.data[s->slot] = candidate_domain[sort][i];
            int v = candidate_holds(s->a, value);
            if (v < 0) result = -1;
            else if (v != every) result = !every;
        }
        value.data[s->slot] = saved;
        return result;
    }
    case S_FORALL_PART: case S_EXISTS_PART: case S_EQUIPOTENT:
        /* Le parti di 17u le sceglie 28k, le biiezioni di un'equipotenza 28q. */
    case S_MEMBER: case S_INCLUDED: case S_SAME: case S_UNIQUE:  /* questi non arrivano qui (17q) */
        break;
    }
    return -1;
}

/* Rifà il modello candidato del ramo in corso (candidate_domain[]): per ogni
 * insieme, il più vecchio degli elementi presenti di ogni classe la cui
 * generazione non supera generation_limit (28r-3). */
static void candidate_prepare(void) {
    for (int i = 0; i < sort_count; i++) candidate_size[i] = 0;
    for (int id = 1; id < now->grounds; id++) {
        int sort = symbols[ground[id].symbol].range, fresh = 1;
        if (sort == TRUTH || ground_generation(id) > generation_limit) continue;
        for (int c = 0; c < candidate_size[sort] && fresh; c++) fresh = now->rep[candidate_domain[sort][c]] != now->rep[id];
        if (fresh) candidate_domain[sort][candidate_size[sort]++] = (short)id;
    }
}

/* 28r-1. Aggiunge f(a) per ogni applicazione dichiarata f, di un
 * argomento, che va in un insieme senza elementi nel modello candidato, con
 * a il primo elemento del modello nel suo dominio. Ritorna quanti elementi
 * ha aggiunto; se qualcuno, rifà la chiusura e il modello. */
static int candidate_complete(void) {
    int made = 0;
    for (int f = 0; f < declared_symbols; f++) {
        const Symbol *map = &symbols[f];
        if (map->arity != 1 || map->range == TRUTH || symbol_bound[f] || symbol_structure(f) >= 0) continue;
        if (candidate_size[map->range] > 0 || candidate_size[map->domain[0]] == 0) continue;
        made += ground_lookup(f, candidate_domain[map->domain[0]][0], -1, G_CREATE) >= 0;
    }
    if (made) {
        closure();
        candidate_prepare();
    }
    return made;
}

/* Aggiunge la prima istanza del "per ogni" rule che è falsa nel modello
 * candidato, provando le scelte degli elementi del modello come un
 * contachilometri; se le scelte sono più di MAX_TUPLES non ne prova
 * nessuna. Ritorna 1 se l'ha aggiunta. Un'istanza falsa che c'è già (una
 * disgiunzione in attesa) non conta, e si passa alla scelta successiva. */
static int instance_model(const Rule *rule) {
    static int *pick;
    static size_t capacity;
    if (!work_reserve((void **)&pick, &capacity, (size_t)rule->slots, sizeof *pick)) { exhausted = 1; return 0; }
    long long tuples = 1;
    SlotValues value = SLOT_VALUES_EMPTY;
    /* Un prodotto interrotto al budget evita overflow con molte variabili.
     * Un dominio vuoto, anche dopo il prefisso gia grande, da zero istanze. */
    for (int j = 0; j < rule->slots; j++) {
        int size = candidate_size[slot_data[rule->slot[j]].sort];
        if (!size) return 0;
        if (tuples <= MAX_TUPLES) tuples *= size;
        pick[j] = 0;
    }
    if (!tuples || tuples > MAX_TUPLES) return 0;
    value = slot_values_copy(now->known[rule->known].value);
    if (work_allocation_failed) return 0;
    for (int more = 1; more && !exhausted && candidate_steps <= MAX_CANDIDATE_STEPS; ) {
        for (int j = 0; j < rule->slots; j++) value.data[rule->slot[j]] = candidate_domain[slot_data[rule->slot[j]].sort][pick[j]];

        /* Falsa: il valore opposto al segno con cui il corpo è noto. */
        if (candidate_holds(rule->body, value) == rule->negated && instance_add(rule, value)) return 1;
        more = 0;
        for (int j = 0; j < rule->slots && !more; j++) {
            if (++pick[j] < candidate_size[slot_data[rule->slot[j]].sort]) more = 1; else pick[j] = 0;
        }
    }
    return 0;
}

/* 28-3. Aggiunge le istanze dei "per ogni" noti che vale la pena provare,
 * come descritto in testa al capitolo ("Quali istanze"), e ritorna quante
 * ne ha aggiunte. Va chiamata dopo settle(), con le classi aggiornate: le
 * istanze aggiunte non vengono aperte qui, quindi le classi non cambiano
 * mentre si cerca. Le definizioni di 28j hanno le loro (instance_definition()),
 * più quelle che decidono un confronto. Con model_guided le istanze sono
 * quelle di 28r, scelte con il modello candidato. */
static int instantiate(void) {
    int made = 0, before = now->knowns;
    int *slot = NULL; size_t capacity = 0;

    /* 28r. Il modello candidato, con gli elementi che gli mancano (28r-1). */
    if (model_guided) {
        candidate_steps = 0;
        candidate_prepare();
        made += candidate_complete();
    }
    for (int r = 0; r < before && !exhausted; r++) {
        /* Un "per ogni parte" ha le sue istanze in 28k; un'equipotenza
         * falsa il suo testimone (28q-2). */
        if (now->known[r].stage != K_RULE || part_quantifier(now->known[r].source)) continue;
        if (now->known[r].source->kind == S_EQUIPOTENT) { made += bijection_witness(r); continue; }
        Rule rule = {.known=r, .all=SLOT_EMPTY, .body=now->known[r].source, .negated=now->known[r].negated};
        for (const Sentence *q = rule.body; (q->kind == S_FORALL || q->kind == S_EXISTS) && (q->kind == S_FORALL) != rule.negated; q = q->a)
            rule.slots++;
        if (!work_reserve((void **)&slot, &capacity, (size_t)rule.slots, sizeof *slot)) { exhausted = 1; break; }
        rule.slot = slot;
        int at = 0;
        while ((rule.body->kind == S_FORALL || rule.body->kind == S_EXISTS) &&
               (rule.body->kind == S_FORALL) != rule.negated) {
            rule.all = slot_set_with(rule.all, rule.body->slot);
            slot[at++] = rule.body->slot;
            rule.body = rule.body->a;
        }

        /* 28r. Una definizione di 28j o di 28q anche dove la sua parte o la
         * sua applicazione compare, l'estensionalità come in 28n (28r-2), il
         * resto dal modello. */
        if (model_guided) {
            if (now->known[r].origin == K_DEFINED) made += instance_definition(&rule);
            if (now->known[r].origin == K_MAPDEF) made += instance_mapdef(&rule);
            made += known_law(r) == LAW_EXTENSIONALITY ? instance_choices(&rule, 0) : instance_model(&rule);
            continue;
        }
        if (now->known[r].origin == K_DEFINED) {
            made += instance_definition(&rule) + instance_choices(&rule, 0);
            continue;
        }
        if (now->known[r].origin == K_MAPDEF) {
            made += instance_mapdef(&rule);
            continue;
        }

        /* 28n. L'estensionalità solo dove un confronto è già deciso (X \neq
         * Y noto), la comprensione solo sui nomi con cui si comincia: vedi
         * "Quali istanze delle leggi" in testa a 28n. */
        int law = known_law(r), budget = MAX_FREE_TUPLES;
        if (law != LAW_EXTENSIONALITY) made += instance_choices(&rule, 1);
        if (!law) made += instance_rewrite(&rule, rule.body);
        if (law != LAW_COMPREHENSION) made += instance_choices(&rule, 0);
        if (!law && rule.slots == 1) made += instance_trigger(&rule, rule.body, &budget);
    }
    free(slot);
    return made;
}

/* 28e. LA DIMOSTRAZIONE SCRITTA, E IL SUO CONTROLLO */

/* Perché un confronto tra due elementi ha un certo valore: è vero per una
 * catena di uguaglianze tra i due, oppure è falso perché due catene li
 * portano ai due elementi di un fatto "diversi". */
typedef struct {
    int value;       /* 1 vero, 0 falso, -1 non si sa */
    Chain chain[2];  /* vero: chain[0] va da un elemento all'altro. Falso: le
                        due catene, dai due elementi a quelli di `against` */
    int against;     /* falso: il fatto "diversi", posto in known[] */
} Reason;

/* Ricostruisce in *reason ciò che si sapeva del confronto s, con gli
 * elementi di value[] al posto delle variabili, usando solo i fatti con
 * numero d'ordine minore di stamp. Ogni catena trovata è già stata
 * ricontrollata anello per anello (chain_between()). */
static void literal_reason(const Sentence *s, SlotValues value, int stamp, Reason *reason) {
    int a = elem_ground(s->left, value, G_EXACT), b = s->kind == S_EQUAL ? elem_ground(s->right, value, G_EXACT) : 0;
    reason->value = -1;
    if (a < 0 || b < 0) return;
    if (chain_between(&reason->chain[0], a, b, stamp)) { reason->value = 1; return; }
    for (int i = 0; i < now->differents; i++) {
        const Known *d = &now->known[now->different[i]];
        if (d->stamp >= stamp) continue;
        for (int swap = 0; swap < 2; swap++) {
            if (!chain_between(&reason->chain[0], a, swap ? d->right : d->left, stamp) ||
                !chain_between(&reason->chain[1], b, swap ? d->left : d->right, stamp)) continue;
            reason->value = 0;
            reason->against = now->different[i];
            return;
        }
    }
}

/* Un passo 28-1 riletto per essere scritto e ricontrollato: le condizioni
 * elementari della premessa, con il valore di quelle che servono, e i fatti
 * su cui quei valori poggiano. Una condizione elementare è ciò che i
 * connettivi collegano: un confronto, un quantificatore, una dichiarazione. */
typedef struct {
    const Sentence *atom[MAX_PROP_ATOMS];
    int value[MAX_PROP_ATOMS];  /* 1, 0, oppure -1: non serve o non si sa */
    int atoms;
    short used[(2 * MAX_CHAIN + 1) * MAX_PROP_ATOMS];
    int uses;
} Deduction;

/* Elenca in d le condizioni elementari di s. Ritorna 0 se sono troppe. */
static int deduction_atoms(const Sentence *s, Deduction *d) {
    if (s->kind == S_NOT) return deduction_atoms(s->a, d);
    if (s->kind == S_AND || s->kind == S_OR || s->kind == S_IMPLIES || s->kind == S_IFF) return deduction_atoms(s->a, d) && deduction_atoms(s->b, d);
    if (d->atoms == MAX_PROP_ATOMS) return 0;
    d->atom[d->atoms++] = s;
    return 1;
}

/* Ritorna il valore di s quando la condizione elementare di posto i vale
 * vero se il bit i di bits è 1, falso altrimenti. */
static int deduction_value(const Sentence *s, const Deduction *d, unsigned bits) {
    switch (s->kind) {
    case S_NOT: return !deduction_value(s->a, d, bits);
    case S_AND: return deduction_value(s->a, d, bits) && deduction_value(s->b, d, bits);
    case S_OR: return deduction_value(s->a, d, bits) || deduction_value(s->b, d, bits);
    case S_IMPLIES: return !deduction_value(s->a, d, bits) || deduction_value(s->b, d, bits);
    case S_IFF: return deduction_value(s->a, d, bits) == deduction_value(s->b, d, bits);
    default: break;
    }
    for (int i = 0; i < d->atoms; i++)
        if (d->atom[i] == s) return bits >> i & 1;
    return 0;
}

/* Controllo di un passo con la tabella di verità: ritorna 1 se, in ogni
 * modo di dare vero o falso alle condizioni elementari che rispetta i
 * valori noti di d, quando premise è vera lo è anche conclusion (negata se
 * negated). Con conclusion NULL chiede che premise non sia mai vera: è una
 * contraddizione. Le condizioni di cui non si sa nulla sono lasciate
 * libere, quindi il passo è valido qualunque cosa valgano. */
static int deduction_follows(const Known *premise, const Sentence *conclusion, int negated, const Deduction *d) {
    for (unsigned bits = 0; bits < 1u << d->atoms; bits++) {
        int respects = 1;
        for (int i = 0; i < d->atoms && respects; i++) respects = d->value[i] < 0 || (int)(bits >> i & 1) == d->value[i];
        if (!respects || deduction_value(premise->source, d, bits) == premise->negated) continue;
        if (!conclusion || deduction_value(conclusion, d, bits) == negated) return 0;
    }
    return 1;
}

/* Rilegge il passo che dalla condizione nota di posto premise trae
 * conclusion (negata se negated; NULL per una contraddizione), fatto quando
 * il numero d'ordine era stamp. Riempie *d con le sole condizioni
 * elementari che servono e con i fatti su cui poggiano, e ritorna 1 se il
 * passo supera il controllo della tabella di verità. Se non lo supera è un
 * errore del programma, che unjustified_steps registra; se le condizioni
 * elementari sono troppe per la tabella il passo non si può controllare, e
 * la risposta è 0 senza che sia un errore.
 *
 * "Che servono": si parte da tutte quelle di cui si sapeva il valore, e si
 * prova a dimenticarle una per volta; quelle senza cui il passo regge
 * ancora non vengono scritte. */
static int deduction_read(int premise, const Sentence *conclusion, int negated, int stamp, Deduction *d) {
    const Known *p = &now->known[premise];
    Reason reason;
    d->atoms = d->uses = 0;
    if (!deduction_atoms(p->source, d)) return 0;
    for (int i = 0; i < d->atoms; i++) {
        d->value[i] = d->atom[i]->kind == S_TRUE ? 1 : -1;
        if (d->atom[i]->kind != S_EQUAL && d->atom[i]->kind != S_HOLDS) continue;
        literal_reason(d->atom[i], p->value, stamp, &reason);
        d->value[i] = reason.value;
    }
    if (!deduction_follows(p, conclusion, negated, d)) { unjustified_steps++; return 0; }
    for (int i = 0; i < d->atoms; i++) {
        int kept = d->value[i];
        if (kept < 0 || d->atom[i]->kind == S_TRUE) continue;
        d->value[i] = -1;
        if (!deduction_follows(p, conclusion, negated, d)) d->value[i] = kept;
    }

    /* I fatti usati dalle condizioni rimaste. */
    for (int i = 0; i < d->atoms; i++) {
        if (d->value[i] < 0 || d->atom[i]->kind == S_TRUE) continue;
        literal_reason(d->atom[i], p->value, stamp, &reason);
        for (int c = 0; c < (reason.value ? 1 : 2); c++)
            for (int j = 0; j < reason.chain[c].links; j++) d->used[d->uses++] = reason.chain[c].fact[j];
        if (!reason.value) d->used[d->uses++] = (short)reason.against;
    }
    return 1;
}

/* Le condizioni note che servono alla contraddizione del ramo, e il numero
 * con cui ognuna è citata nella dimostrazione scritta. */
static char needed[MAX_KNOWN];
static short label[MAX_KNOWN];

/* Scrive il riferimento alla condizione nota di posto i: (H3) per la terza
 * ipotesi, che è la condizione di posto 2, e il suo numero per le altre. */
static void put_label(int i) {
    if (now->known[i].origin == K_GIVEN) proof_add("(H%d)", i + 1); else proof_add("(%d)", label[i]);
}

/* Scrive ", by (3), (5)" con i riferimenti ai fatti delle catene di reason
 * e, se il confronto è falso, al fatto "diversi". Ogni fatto una volta. */
static void put_reason_labels(const Reason *reason) {
    short seen[2 * MAX_CHAIN + 1];
    int count = 0;
    for (int c = 0; c < (reason->value ? 1 : 2); c++)
        for (int j = 0; j < reason->chain[c].links; j++) seen[count++] = reason->chain[c].fact[j];
    if (!reason->value) seen[count++] = (short)reason->against;
    for (int i = 0, written = 0; i < count; i++) {
        int repeated = 0;
        for (int j = 0; j < i; j++) repeated = repeated || seen[j] == seen[i];
        if (repeated) continue;
        proof_add(written++ ? ", " : " by ");
        put_label(seen[i]);
    }
}

/* Scrive perché il confronto s ha il valore che reason dice: la catena di
 * uguaglianze, se è un'uguaglianza vera con più di un anello, altrimenti
 * il confronto stesso; poi i fatti usati. */
static void put_reason(const Sentence *s, SlotValues value, const Reason *reason) {
    const Chain *c = &reason->chain[0];
    proof_add("$");
    if (reason->value && s->kind == S_EQUAL && c->links > 1) {
        for (int i = 0; i <= c->links; i++) { if (i) proof_add(" = "); put_ground(c->term[i], 0); }
    } else {
        put_sentence(s, !reason->value, value, 0);
    }
    proof_add("$");
    put_reason_labels(reason);
}

/* Ritorna 1 se la condizione nota k è proprio `written`, letta con il
 * segno negated: le negazioni in testa a written passano nel segno, come
 * fa known_add(). */
static int known_is(const Known *k, const Sentence *written, int negated) {
    while (written->kind == S_NOT) { written = written->a; negated = !negated; }
    return k->source == written && k->negated == negated;
}

/* 28j. Ritorna 1 se l'elemento e non ha variabili libere fuori da bound (il
 * bit i per la variabile di posto i). Il bitset cresce anche per le
 * variabili nuove introdotte dalle definizioni di 28q. */
static int elem_closed(const Elem *e, SlotSet bound) {
    if (!e) return 1;
    if (e->symbol < 0) return slot_set_contains(bound, e->slot);
    return elem_closed(e->arg[0], bound) && elem_closed(e->arg[1], bound);
}

/* 28j. Ritorna 1 se la condizione s non ha variabili libere fuori da bound. */
static int sentence_closed(const Sentence *s, SlotSet bound) {
    if (!s) return 1;
    if (s->kind == S_FORALL || s->kind == S_EXISTS) bound = slot_set_with(bound, s->slot);
    return elem_closed(s->left, bound) && elem_closed(s->right, bound) && sentence_closed(s->a, bound) && sentence_closed(s->b, bound);
}

/* 28j. Controlla la definizione di posto i: è "per ogni x di S, x \in D se
 * e solo se c", chiusa, con D una parte di S nuova, che c non nomina e
 * nessuna condizione nota prima di questa nomina. Ritorna 1 se regge. */
static int definition_derived(int i) {
    const Known *k = &now->known[i];
    const Sentence *s = k->source;
    if (k->parts != 1) return 0;
    int part = k->part[0];
    if (k->negated || s->kind != S_FORALL || s->a->kind != S_IFF || s->a->a->kind != S_HOLDS || !sentence_closed(s, SLOT_EMPTY)) return 0;
    const Elem *member = s->a->a->left;
    if (member->symbol != part || part < declared_symbols || !part_of(part, slot_data[s->slot].sort) || member->arg[0]->symbol >= 0 ||
        member->arg[0]->slot != s->slot || sentence_mentions(s->a->b, part))
        return 0;
    for (int j = 0; j < i; j++)
        if (sentence_mentions(now->known[j].source, part)) return 0;
    return 1;
}

/* 28q. Ritorna 1 se nell'elemento presente id compare il simbolo symbol. */
static int ground_mentions(int id, int symbol) {
    if (id < 0) return 0;
    const Ground *g = &ground[id];
    return g->symbol == symbol || ground_mentions(g->arg[0], symbol) || ground_mentions(g->arg[1], symbol);
}

/* 28q. Ritorna 1 se il simbolo symbol compare in una delle condizioni note
 * prima di quella di posto i: nella condizione, o negli elementi al posto
 * delle sue variabili. */
static int mentioned_before(int i, int symbol) {
    for (int j = 0; j < i; j++) {
        const Known *k = &now->known[j];
        if (sentence_mentions(k->source, symbol)) return 1;
        for (int v = 0; v < k->value.count; v++)
            if (slot_values_get(k->value, v) > 0 && ground_mentions(slot_values_get(k->value, v), symbol)) return 1;
    }
    return 0;
}

/* 28q. Ritorna 1 se t è la variabile di posto slot. */
static int is_variable(const Elem *t, int slot) { return t && t->symbol < 0 && t->slot == slot; }

/* 28q. Ritorna 1 se l'elemento e sta nell'insieme sort (TRUTH per una parte
 * o una relazione applicata), con ogni simbolo applicato a tanti argomenti
 * quanti ne chiede, ognuno nel suo insieme. Il lettore lo controlla per ciò
 * che legge (elem_expect()); le identità e le definizioni di 28q le
 * costruisce il motore, e questo è il loro controllo. */
static int elem_typed(const Elem *e, int sort) {
    if (!e) return 0;
    if (e->symbol < 0) return slot_data[e->slot].sort == sort;
    const Symbol *s = &symbols[e->symbol];
    if (s->range != sort) return 0;
    for (int a = 0; a < 2; a++)
        if ((a < s->arity) != (e->arg[a] != NULL) || (a < s->arity && !elem_typed(e->arg[a], s->domain[a]))) return 0;
    return 1;
}

/* 28q. Come elem_typed(), per ogni confronto della condizione s: i due
 * membri di un'uguaglianza nello stesso insieme, un'appartenenza che vale
 * vero o falso. */
static int sentence_typed(const Sentence *s) {
    if (!s) return 1;
    if (s->kind == S_EQUAL) return elem_typed(s->left, elem_sort(s->left)) && elem_typed(s->right, elem_sort(s->left));
    if (s->kind == S_HOLDS) return elem_typed(s->left, TRUTH);
    return sentence_typed(s->a) && sentence_typed(s->b);
}

/* 28q. Controlla, leggendo l'albero, che s sia scritta come le identità D
 * dell'equipotenza e per le applicazioni di map[] (la forma è in testa a
 * equipotent_identities()): per ogni lato i "per ogni" sulle sue variabili,
 * poi un'uguaglianza per componente, ognuna con l'applicazione giusta
 * applicata alle altre e alle variabili nel loro ordine. Ritorna 1 se
 * regge. */
static int identities_written(const Sentence *s, const Sentence *e, const int *map) {
    if (s->kind != S_AND) return 0;
    for (int k = 0; k < 2; k++) {
        const Sentence *q = k ? s->b : s->a;
        int m = e->sides[k], n = e->sides[1 - k];
        const int *first = k ? map + e->sides[1] : map, *second = k ? map : map + e->sides[1];
        for (int i = 0; i < m; i++, q = q->a)
            if (q->kind != S_FORALL || q->slot != e->side_slot[k][i]) return 0;
        if (m == 2 && q->kind != S_AND) return 0;
        for (int i = 0; i < m; i++) {
            const Sentence *equal = m == 2 ? (i ? q->b : q->a) : q;
            if (equal->kind != S_EQUAL || !is_variable(equal->right, e->side_slot[k][i]) || equal->left->symbol != second[i]) return 0;
            for (int j = 0; j < 2; j++) {
                const Elem *inner = equal->left->arg[j];
                if ((j < n) != (inner != NULL)) return 0;
                if (j >= n) continue;
                if (inner->symbol != first[j]) return 0;
                for (int a = 0; a < 2; a++)
                    if ((a < m) != (inner->arg[a] != NULL) || (a < m && !is_variable(inner->arg[a], e->side_slot[k][a]))) return 0;
            }
        }
    }
    return 1;
}

/* 28q. Controlla la condizione nota di posto i, che viene dall'equipotenza
 * parent (K_BIJECTION): ha il suo segno, ed è D per le applicazioni di
 * k->part[], ognuna con gli insiemi giusti. Da un'equipotenza vera (28q-1)
 * le applicazioni sono nuove: nate dopo l'enunciato, tutte diverse, e mai
 * nominate prima. Da una falsa (28q-2) devono esserci già: dichiarate, o con
 * il loro nome o la loro definizione prima di questa condizione. Ritorna 1
 * se regge. */
static int bijection_derived(int i) {
    const Known *k = &now->known[i], *p = &now->known[k->parent];
    const Sentence *e = p->source;
    if (e->kind != S_EQUIPOTENT || k->negated != p->negated) return 0;
    if (k->parts != e->sides[0] + e->sides[1]) return 0;
    for (int j = 0; j < k->parts; j++) {
        int map = k->part[j], domain[2], range, arity = identity_map_sorts(e, j, domain, &range);
        if (map < 0 || map >= symbol_count) return 0;
        const Symbol *s = &symbols[map];
        if (s->arity != arity || s->range != range || s->family || symbol_bound[map] || symbol_structure(map) >= 0) return 0;
        for (int a = 0; a < arity; a++)
            if (s->domain[a] != domain[a]) return 0;
        for (int other = 0; other < j && !p->negated; other++)
            if (k->part[other] == map) return 0;
        if (!p->negated && (map < declared_symbols || mentioned_before(i, map))) return 0;
        if (p->negated && map >= declared_symbols && (name_known[map] < 0 || name_known[map] >= i)) return 0;
    }
    return identities_written(k->source, e, k->part) && sentence_typed(k->source);
}

/* 28q. Ritorna 1 se spec, sotto i "per ogni" sulle variabili di bound, è
 * una forma d1-d3 (testa di 28q) che definisce l'oggetto value dell'insieme
 * sort, senza nominare map in ciò che gli dà il valore. La variabile di d2 e
 * d3 è nuova: non è tra quelle di bound. */
static int spec_defines(const Sentence *spec, Elem *value, int sort, int map, SlotSet bound) {
    if (spec->kind == S_EQUAL) return elem_renamed(spec->left, value, NULL, NULL, 0) && !elem_mentions(spec->right, map);
    if (spec->kind != S_FORALL || slot_set_contains(bound, spec->slot) || (sort_data[sort].kind != SORT_PARTS && sort_data[sort].kind != SORT_MAPS) ||
        slot_data[spec->slot].sort != sort_data[sort].base)
        return 0;
    Elem *y = slot_elem(spec->slot);
    const Sentence *body = spec->a;
    bound = slot_set_with(bound, spec->slot);
    if (sort_data[sort].kind == SORT_MAPS) return spec_defines(body, elem_new(sort_data[sort].symbol, 0, value, y), sort_data[sort].target, map, bound);
    return body->kind == S_IFF && body->a->kind == S_HOLDS && elem_renamed(body->a->left, elem_new(sort_data[sort].symbol, 0, y, value), NULL, NULL, 0) &&
           !sentence_mentions(body->b, map);
}

/* 28q. Controlla la definizione di posto i (K_MAPDEF): chiusa, per
 * un'applicazione nuova k->part[0] mai nominata prima, con i "per ogni" sui
 * suoi argomenti, ognuno nel suo insieme, e poi una forma d1-d3. Ritorna 1
 * se regge. */
static int mapdef_derived(int i) {
    const Known *k = &now->known[i];
    const Sentence *s = k->source;
    if (k->parts != 1) return 0;
    int map = k->part[0];
    if (k->negated || map < declared_symbols || map >= symbol_count || !sentence_closed(s, SLOT_EMPTY) || !sentence_typed(s) || mentioned_before(i, map)) return 0;
    const Symbol *f = &symbols[map];
    if (f->range == TRUTH || f->family || symbol_bound[map] || f->arity < 1) return 0;
    Elem *arg[2];
    SlotSet bound = SLOT_EMPTY;
    for (int a = 0; a < f->arity; a++, s = s->a) {
        if (s->kind != S_FORALL || slot_data[s->slot].sort != f->domain[a] || slot_set_contains(bound, s->slot)) return 0;
        bound = slot_set_with(bound, s->slot);
        arg[a] = slot_elem(s->slot);
    }
    return spec_defines(s, map_apply(map, arg, f->arity), f->range, map, bound);
}

/* 28j. Controlla che la condizione nota k venga dal "per ogni parte" p con
 * le parti di k->part[] al posto delle parti legate in testa a p: ognuna una
 * parte del suo insieme con un nome, e k il corpo di p con loro al posto
 * delle legate, riletto da sentence_renamed(). Ritorna 1 se regge. */
static int part_instance_derived(const Known *k, const Known *p) {
    const Sentence *body = p->source;
    int count = 0, negated = p->negated, valid = 1;
    for (const Sentence *q = body; part_quantifier(q) && (q->kind == S_FORALL_PART) != p->negated; q = q->a) count++;
    if (!count || count != k->parts) return 0;
    int *from = NULL; size_t capacity = 0;
    if (!work_reserve((void **)&from, &capacity, (size_t)count, sizeof *from)) return 0;
    for (int j = 0; j < count; j++, body = body->a) {
        valid &= part_of(k->part[j], symbols[body->part].domain[0]);
        from[j] = body->part;
    }
    while (body->kind == S_NOT) { body = body->a; negated = !negated; }
    valid = valid && k->negated == negated && sentence_renamed(k->source, body, from, k->part, count);
    free(from);
    return valid;
}

/* 28j. Controlla che la condizione nota di posto i venga dall'"esiste una
 * parte" (o dal "non per ogni parte") p, con al posto della parte legata
 * una parte nuova, k->part[0], che nessuna condizione nota prima di questa
 * nomina. Ritorna 1 se regge. */
static int part_name_derived(int i, const Known *p) {
    const Known *k = &now->known[i];
    const Sentence *body = p->source->a;
    if (k->parts != 1) return 0;
    int from = p->source->part, to = k->part[0];
    int negated = p->negated;
    if ((p->source->kind == S_EXISTS_PART) == p->negated || to < declared_symbols || !part_of(to, symbols[from].domain[0])) return 0;
    for (int j = 0; j < i; j++)
        if (sentence_mentions(now->known[j].source, to)) return 0;
    while (body->kind == S_NOT) { body = body->a; negated = !negated; }
    return k->negated == negated && sentence_renamed(k->source, body, &from, &to, 1);
}

/* 28r. Ritorna 1 se l'elemento presente id è scritto bene: ogni argomento
 * sta nell'insieme che il suo simbolo chiede, fino in fondo. Il controllo di
 * un'istanza lo vuole per ogni elemento che sostituisce: chi ha costruito
 * l'elemento, compresi gli f(a) aggiunti dal modello candidato (28r-1), non
 * conta. */
static int ground_sorted(int id) {
    const Ground *g = &ground[id];
    const Symbol *s = &symbols[g->symbol];
    for (int i = 0; i < 2; i++) {
        if ((i < s->arity) != (g->arg[i] >= 0)) return 0;
        if (i < s->arity && (g->arg[i] < 1 || symbols[ground[g->arg[i]].symbol].range != s->domain[i] || !ground_sorted(g->arg[i]))) return 0;
    }
    return 1;
}

/* Controlla che la condizione nota di posto i, che non è un passo 28-1,
 * venga davvero da parent nel modo che origin dice: è un controllo sulla
 * forma, fatto rileggendo l'albero dell'enunciato. Ritorna 1 se regge. */
static int known_derived(int i) {
    const Known *k = &now->known[i], *p = &now->known[k->parent];
    const Sentence *body = p->source;
    Parts parts;
    switch (k->origin) {
    case K_INSTANCE:
        if (part_quantifier(body)) return part_instance_derived(k, p);

        /* Il corpo dei "per ogni" con cui parent comincia, con un elemento
         * del suo insieme al posto di ogni variabile. */
        while ((body->kind == S_FORALL || body->kind == S_EXISTS) && (body->kind == S_FORALL) != p->negated) {
            int id = slot_values_get(k->value, body->slot);
            if (id < 1 || symbols[ground[id].symbol].range != slot_data[body->slot].sort || !ground_sorted(id)) return 0;
            body = body->a;
        }
        return body != p->source && known_is(k, body, p->negated);
    case K_NAMED:
        /* parent è un "esiste", e il nome è nuovo: nessuna condizione nota
         * prima di questa lo usa. */
        if (part_quantifier(body)) return part_name_derived(i, p);
        if ((body->kind != S_FORALL && body->kind != S_EXISTS) || (body->kind == S_EXISTS) == p->negated) return 0;
        if (slot_values_get(k->value, body->slot) < 1 || ground[slot_values_get(k->value, body->slot)].arg[0] >= 0) return 0;
        for (int j = 0; j < i; j++)
            for (int v = 0; v < slot_count; v++)
                if (slot_values_get(now->known[j].value, v) == slot_values_get(k->value, body->slot)) return 0;
        return known_is(k, body->a, p->negated);
    case K_CASE:
        /* Uno dei due casi di una disgiunzione. Per un "se e solo se" il
         * caso è una scelta per il primo lato, e per il secondo il valore
         * che ne segue: lo stesso se l'equivalenza è vera, l'opposto se è
         * negata. Il primo lato è la condizione nota subito prima. */
        if (body->kind == S_IFF) {
            const Known *first = &now->known[i > 0 ? i - 1 : 0];
            if (known_is(k, body->a, 0) || known_is(k, body->a, 1)) return 1;
            return i > 0 && first->parent == k->parent && first->origin == K_CASE &&
                   (known_is(first, body->a, 0) || known_is(first, body->a, 1)) &&
                   known_is(k, body->b, known_is(first, body->a, 1) != p->negated);
        }
        return sentence_parts(body, p->negated, &parts) && !parts.conjunction &&
               (known_is(k, parts.x, parts.nx) || known_is(k, parts.y, parts.ny));
    case K_BIJECTION:
        return bijection_derived(i);
    default:
        return 1;
    }
}

/* 28j. Segna in needed[] le condizioni che hanno dato un nome (28-2) o una
 * definizione (K_DEFINED) ai simboli che l'elemento e nomina: chi legge la
 * dimostrazione deve averli visti nascere. */
static void need_names_elem(const Elem *e) {
    if (!e) return;
    if (e->symbol >= declared_symbols && name_known[e->symbol] >= 0) needed[name_known[e->symbol]] = 1;
    need_names_elem(e->arg[0]);
    need_names_elem(e->arg[1]);
}

/* 28j. Come need_names_elem(), per tutti gli elementi della condizione s. */
static void need_names(const Sentence *s) {
    if (!s) return;
    need_names_elem(s->left);
    need_names_elem(s->right);
    need_names(s->a);
    need_names(s->b);
}

/* 28j. Come need_names_elem(), per i nomi dentro l'elemento presente id: un
 * elemento con un nome usato in un'istanza va presentato anche se nessun
 * fatto su di lui serve, e con lui la catena da cui è nato. */
static void need_ground_names(int id) {
    const Ground *g = &ground[id];
    if (g->symbol >= declared_symbols && name_known[g->symbol] >= 0) needed[name_known[g->symbol]] = 1;
    for (int i = 0; i < 2 && g->arg[i] >= 0; i++) need_ground_names(g->arg[i]);
}

/* 28p. I CASI SCRITTI SONO TUTTI
 *
 * (Sta qui, accanto a leaf_write() che scrive i casi; la lettera è venuta
 * dopo le altre.)
 *
 * Ogni passo scritto si ricontrolla da solo (28e): una catena di
 * uguaglianze anello per anello, una deduzione con la sua tabella di verità,
 * un caso con la disgiunzione da cui viene. Ma "per ogni passo" non basta a
 * dire che la dimostrazione è completa: una distinzione di casi in cui un
 * caso non è scritto ha tutti i passi giusti e non dimostra nulla. Il
 * certificato non se ne accorge sempre, perché il verificatore ritrova da
 * sé i casi che non chiedono istanze (11e di checker.c): l'esperimento di
 * un motore bugiardo che non scriveva il caso già chiuso di 28o è passato
 * senza che nessun test lo vedesse. Per questo, a dimostrazione finita, si
 * controlla anche la forma dei casi.
 *
 * Di ogni ramo chiuso e scritto (una foglia) si annota il cammino: la
 * successione dei casi in cui sta, ognuno come la disgiunzione da cui viene
 * (il suo posto tra le cose note, uguale in tutti i rami che la ereditano) e
 * la parte scelta. Le foglie coprono tutto se, partendo dal cammino vuoto,
 * in ogni punto o c'è una foglia che si ferma lì (il ramo è chiuso senza
 * altri casi), oppure tutte le foglie che proseguono distinguono la stessa
 * disgiunzione, con le sue due parti, e da ognuna le foglie coprono tutto a
 * loro volta. È la regola della dimostrazione per casi: da "A oppure B", da
 * A una contraddizione e da B una contraddizione, segue la contraddizione;
 * la disgiunzione è tra le righe del caso (la sua riga "there are two
 * cases" la cita), ed è ricontrollata come le altre. Se la copertura manca
 * il programma ha sbagliato: unjustified_steps lo conta, e l'affermazione
 * non è dimostrata. */

/* Un passo del cammino di una foglia: la disgiunzione di posto parent tra
 * le cose note, e la parte scelta, come il primo caso che ne viene (source
 * con il segno negated; per un "se e solo se" il primo lato). */
typedef struct {
    short parent;
    const Sentence *source;
    signed char negated;
} CaseStep;

/* Il cammino di una foglia scritta: i suoi casi, dal più esterno. */
typedef struct {
    CaseStep step[MAX_CASE_STEPS];
    int steps;
} CasePath;

/* I cammini delle foglie scritte per l'affermazione in corso; 1 in
 * case_overflow se una non ci stava, e allora la copertura non si può dire. */
static CasePath case_path[MAX_CASE_LEAVES];
static int case_paths, case_overflow;

/* Annota il cammino del ramo corrente, appena chiuso e scritto. */
static void case_path_record(void) {
    if (case_paths == MAX_CASE_LEAVES) { case_overflow = 1; return; }
    CasePath *p = &case_path[case_paths++];
    p->steps = 0;
    for (int i = 0; i < now->knowns; i++) {
        const Known *k = &now->known[i];
        int first = k->origin == K_CASE;
        for (int j = 0; j < p->steps && first; j++) first = p->step[j].parent != k->parent;
        if (!first) continue;
        if (p->steps == MAX_CASE_STEPS) { case_overflow = 1; return; }
        p->step[p->steps++] = (CaseStep){k->parent, k->source, k->negated};
    }
}

/* Ritorna 1 se due passi scelgono la stessa parte della stessa
 * disgiunzione. */
static int case_step_same(const CaseStep *a, const CaseStep *b) {
    return a->parent == b->parent && a->source == b->source && a->negated == b->negated;
}

/* Ritorna 1 se le foglie di posto leaf[0..count), che hanno i primi depth
 * passi uguali, coprono tutti i casi da lì in giù (vedi la testa del
 * paragrafo). */
static int case_paths_cover(const CasePath *paths, const int *leaf, int count, int depth) {
    int side[MAX_CASE_LEAVES], sides = 0, other[MAX_CASE_LEAVES], others = 0;
    if (count == 0) return 0;
    for (int i = 0; i < count; i++)
        if (paths[leaf[i]].steps == depth) return 1;

    /* Tutte proseguono: la stessa disgiunzione, divisa nelle sue due parti. */
    const CaseStep *first = &paths[leaf[0]].step[depth];
    for (int i = 0; i < count; i++) {
        const CaseStep *s = &paths[leaf[i]].step[depth];
        if (s->parent != first->parent) return 0;
        if (case_step_same(s, first)) side[sides++] = leaf[i];
        else if (!others || case_step_same(s, &paths[other[0]].step[depth])) other[others++] = leaf[i];
        else return 0;
    }
    return others > 0 && case_paths_cover(paths, side, sides, depth + 1) && case_paths_cover(paths, other, others, depth + 1);
}

/* Ritorna 1 se le foglie scritte per l'affermazione in corso coprono tutti
 * i loro casi. */
static int case_paths_complete(void) {
    int leaf[MAX_CASE_LEAVES];
    for (int i = 0; i < case_paths; i++) leaf[i] = i;
    return !case_overflow && case_paths_cover(case_path, leaf, case_paths, 0);
}

/* Scrive la dimostrazione del ramo che si è appena chiuso: le sole
 * condizioni note che servono alla contraddizione, una per riga, e la
 * contraddizione. `leaf` è il numero del caso, 0 se non ci sono casi.
 * Ritorna 1 se ogni passo scritto ha superato il suo controllo; se ritorna
 * 0 il testo scritto va cancellato da chi chiama. Annota il cammino dei
 * casi della foglia (28p). */
static int leaf_write(int leaf) {
    static Deduction d;
    static Reason reason;
    memset(needed, 0, sizeof needed);

    /* Da dove nasce la contraddizione: un fatto "diversi" tra due elementi
     * uguali, o una disgiunzione senza parti vere. */
    if (clash_fact >= 0) {
        const Known *f = &now->known[clash_fact];
        if (!chain_between(&reason.chain[0], f->left, f->right, INT_MAX)) return 0;
        needed[clash_fact] = 1;
        for (int j = 0; j < reason.chain[0].links; j++) needed[reason.chain[0].fact[j]] = 1;
    } else {
        if (!deduction_read(clash_choice, NULL, 0, INT_MAX, &d)) return 0;
        needed[clash_choice] = 1;
        for (int j = 0; j < d.uses; j++) needed[d.used[j]] = 1;
    }

    /* All'indietro: ciò che serve a ciò che serve. Una condizione viene
     * sempre dopo quelle da cui dipende, quindi basta un passaggio. Ogni
     * passo viene ricontrollato qui, prima di scrivere qualcosa. */
    for (int i = now->knowns - 1; i >= 0; i--) {
        const Known *k = &now->known[i];
        if (!needed[i]) continue;

        /* 28j. Le parti scelte, e i nomi che la condizione nomina (in una
         * copia o in una definizione), vanno presentati prima di usarli. */
        need_names(k->source);
        for (int v = 0; v < slot_count; v++)
            if (slot_values_get(k->value, v) > 0) need_ground_names(slot_values_get(k->value, v));
        for (int j = 0; j < k->parts; j++)
            if (k->part[j] >= declared_symbols && name_known[k->part[j]] >= 0) needed[name_known[k->part[j]]] = 1;
        if ((k->origin == K_DEFINED && !definition_derived(i)) || (k->origin == K_MAPDEF && !mapdef_derived(i))) {
            if (!work_allocation_failed) unjustified_steps++;
            return 0;
        }
        if (k->parent < 0) continue;
        needed[k->parent] = 1;
        if (k->origin != K_PART) {
            if (!known_derived(i)) {
                /* Un controllo interrotto per memoria non e una deduzione
                 * falsa: il fallimento persistente scarta comunque la prova. */
                if (!work_allocation_failed) unjustified_steps++;
                return 0;
            }
            continue;
        }
        if (!deduction_read(k->parent, k->source, k->negated, k->stamp, &d)) return 0;
        for (int j = 0; j < d.uses; j++) needed[d.used[j]] = 1;
    }

    /* Le righe. */
    int number = 0;
    if (leaf) proof_add("\\item \\emph{Case %d.}\n\\begin{enumerate}\n", leaf);
    else proof_add("\\item \\emph{Suppose not.}\n\\begin{enumerate}\n");
    for (int i = 0; i < now->knowns; i++) {
        const Known *k = &now->known[i];
        if (!needed[i] || k->origin == K_GIVEN) continue;
        label[i] = (short)++number;
        proof_add("\\item ");
        if (k->origin == K_DENIED) {
            proof_add("Suppose that the claim fails");
        } else if (k->origin == K_INSTANCE) {
            proof_add("By ");
            put_label(k->parent);
            proof_add(" with");
            const Known *p = &now->known[k->parent];
            int written = 0;
            for (const Sentence *q = p->source; (q->kind == S_FORALL || q->kind == S_EXISTS) && (q->kind == S_FORALL) != p->negated; q = q->a) {
                proof_add("%s $", written++ ? "," : "");
                put_slot(q->slot);
                proof_add(" := ");
                put_ground(slot_values_get(k->value, q->slot), 0);
                proof_add("$");
            }

            /* 28j. Le parti scelte per le parti legate. */
            const Sentence *q = p->source;
            for (int j = 0; j < k->parts && part_quantifier(q); j++, q = q->a) {
                proof_add("%s $", written++ ? "," : "");
                put_symbol(q->part);
                proof_add(" := ");
                put_symbol(k->part[j]);
                proof_add("$");
            }
        } else if (k->origin == K_NAMED) {
            /* Un "esiste" vero dà l'elemento; un "per ogni" falso dà un
             * elemento per cui non vale. Lo stesso per una parte (28j). */
            const Sentence *q = now->known[k->parent].source;
            int some = q->kind == S_EXISTS || q->kind == S_EXISTS_PART, part = part_quantifier(q);
            proof_add("By ");
            put_label(k->parent);
            if (some) proof_add(" there is such %s of $", part ? "a part" : "an element");
            else proof_add(" some %s of $", part ? "part" : "element");
            put_sort(part ? symbols[q->part].domain[0] : slot_data[q->slot].sort);
            proof_add(some ? "$; call it $" : "$ makes it fail; call it $");
            if (part) put_symbol(k->part[0]); else put_ground(slot_values_get(k->value, q->slot), 0);
            proof_add("$. For it");
        } else if (k->origin == K_DEFINED) {
            /* 28j. La parte nuova, con la sua regola. */
            const Sentence *definition = k->source;
            SlotValues nothing = SLOT_VALUES_EMPTY;

            proof_add("Consider the part $");
            put_symbol(k->part[0]);
            proof_add(" = \\{");
            put_slot(definition->slot);
            proof_add(" \\in ");
            put_sort(slot_data[definition->slot].sort);
            proof_add(" \\mid ");
            put_sentence(definition->a->b, 0, nothing, 0);
            proof_add("\\}$ of $");
            put_sort(slot_data[definition->slot].sort);
            proof_add("$");
        } else if (k->origin == K_BIJECTION) {
            /* 28q-1: la biiezione con un nome; 28q-2: il testimone. */
            const Sentence *e = now->known[k->parent].source;
            int n = e->sides[1], m = e->sides[0];
            proof_add("By ");
            put_label(k->parent);
            proof_add(k->negated ? ", no map from $" : " there is a bijection from $");
            put_equipotent_side(e, 0);
            proof_add("$ to $");
            put_equipotent_side(e, 1);
            proof_add(k->negated ? "$ has an inverse; in particular not $" : "$; call it $");
            for (int j = 0; j < n; j++) { if (j) proof_add(", "); put_symbol(k->part[j]); }
            proof_add(k->negated ? "$, with $" : "$, and its inverse $");
            for (int j = 0; j < m; j++) { if (j) proof_add(", "); put_symbol(k->part[n + j]); }
            proof_add(k->negated ? "$ as inverse" : "$. For them");
        } else if (k->origin == K_MAPDEF) {
            /* 28q: un'applicazione nuova, con la sua definizione. */
            const Symbol *f = &symbols[k->part[0]];
            proof_add("Consider the map $");
            put_symbol(k->part[0]);
            proof_add(" \\colon ");
            for (int a = 0; a < f->arity; a++) { if (a) proof_add(" \\times "); put_sort(f->domain[a]); }
            proof_add(" \\to ");
            put_sort(f->range);
            proof_add("$ defined by");
        } else if (k->origin == K_CASE) {
            proof_add("By ");
            put_label(k->parent);
            proof_add(" there are two cases. In this one");
        } else {
            /* 28-1: la premessa, e ciò che di lei si sa già. */
            deduction_read(k->parent, k->source, k->negated, k->stamp, &d);
            proof_add("From ");
            put_label(k->parent);
            for (int a = 0, written = 0; a < d.atoms; a++) {
                if (d.value[a] < 0 || d.atom[a]->kind == S_TRUE) continue;
                literal_reason(d.atom[a], now->known[k->parent].value, k->stamp, &reason);
                proof_add(written++ ? " and " : ", since ");
                put_reason(d.atom[a], now->known[k->parent].value, &reason);
            }
        }
        proof_add(": $");
        put_sentence(k->source, k->negated, k->value, 0);
        proof_add("$.\n");
    }

    /* La contraddizione. */
    proof_add("\\item This is a contradiction: ");
    if (clash_fact >= 0) {
        const Known *f = &now->known[clash_fact];
        reason.value = 1;
        chain_between(&reason.chain[0], f->left, f->right, INT_MAX);
        put_reason(f->source, f->value, &reason);
        proof_add(", against ");
        put_label(clash_fact);
    } else {
        deduction_read(clash_choice, NULL, 0, INT_MAX, &d);
        put_label(clash_choice);
        proof_add(" cannot hold");
        for (int a = 0, written = 0; a < d.atoms; a++) {
            if (d.value[a] < 0 || d.atom[a]->kind == S_TRUE) continue;
            literal_reason(d.atom[a], now->known[clash_choice].value, INT_MAX, &reason);
            proof_add(written++ ? " and " : ", since ");
            put_reason(d.atom[a], now->known[clash_choice].value, &reason);
        }
    }
    proof_add(".\n\\end{enumerate}\n");
    if (!exhausted) case_path_record();
    return !exhausted;
}

/* 28f. IL CERTIFICATO
 *
 * Il controllo di 28e è del programma su se stesso: legge le tabelle della
 * ricerca. Il certificato porta la dimostrazione a checker.c, che non usa
 * nulla di questo file (capitolo 11 di checker.c). Per un modello trovato da
 * 28a porta gli insiemi, con i loro elementi, e la tabella di ogni simbolo:
 * il verificatore vi calcola l'enunciato da capo. Per una dimostrazione
 * porta, per ogni affermazione della tesi, un caso "case (not C)" con i soli
 * dati che la ricerca ha trovato: i nomi dati (28-2, voce witness) e le
 * istanze (28-3, voce instance) che servono alle contraddizioni dei rami. Il
 * resto, le parti (28-1), le uguaglianze (28-4) e i casi (28-5), il
 * verificatore lo ritrova da sé, provando tutti i valori delle condizioni
 * elementari, e così controlla anche che la dimostrazione valga quando un
 * insieme è vuoto.
 *
 * I nomi del certificato. Un nome dato da 28-2 si scrive con la lettera e il
 * suo numero d'ordine, x_3: due rami diversi possono dare due nomi diversi
 * allo stesso posto di symbols[], e nel certificato, dove i rami di
 * un'affermazione stanno insieme, devono restare distinti. I simboli
 * dichiarati si scrivono senza _ (R_{1} diventa R1), e le variabili legate
 * con la loro lettera, quindi non si confondono con i nomi. */

/* name_written[n] è 1 se la voce witness del nome di numero d'ordine n è
 * già nel certificato dell'affermazione in corso. */
static unsigned char name_written[MAX_NAMES_GIVEN + 1];

/* Scrive un'etichetta univoca dell'insieme. I nomi arbitrari conservano
 * lettera e pedice; quelli derivati hanno un prefisso con underscore e
 * l'indice del tipo, distinto dai nomi arbitrari. Concatenare gli alberi
 * non basta: mappe parti(P)->S e P->parti(S) darebbero entrambe MPPS.
 * Il significato resta nei dati parts/maps, mai nell'etichetta. */
static void cert_sort(int sort) {
    if (sort_data[sort].kind == SORT_PLAIN) {
        cert_add("%c", sort_data[sort].name);
        if (sort_data[sort].index) cert_add("%d", sort_data[sort].index);  /* 17w */
        return;
    }
    if (sort_data[sort].kind == SORT_NUMBERS) { cert_add("Num"); return; }
    cert_add("%c_%d",sort_data[sort].kind==SORT_PARTS?'P':'M',sort);
}

/* Scrive nel certificato il nome del simbolo di posto symbol. Un simbolo
 * di struttura (17v) si chiama in o ap seguito dal nome del suo insieme. */
static void cert_symbol(int symbol) {
    const Symbol *s = &symbols[symbol];
    if (symbol_structure(symbol) >= 0) {
        cert_add(sort_data[symbol_structure(symbol)].kind == SORT_PARTS ? "in" : "ap");
        cert_sort(symbol_structure(symbol));
        return;
    }
    /* 17v. Un numero scritto come elemento si chiama num seguito dal numero.
     * Si chiamava n1, come nel certificato si scrive la variabile n_{1}: con
     * \forall n_{1} in vista, "n1" nella condizione diventava la variabile,
     * e il certificato parlava di un altro enunciato. Nessun altro nome
     * comincia per "num": una lettera sola, o un comando (lettere greche,
     * operazioni, relazioni), poi un pedice.
     * Warning: se aggiungi un comando che si chiama num, cambia questo nome. */
    if (s->name >= NUMERAL_NAMES) { cert_add("num%d", s->name - NUMERAL_NAMES); return; }
    if (symbol >= declared_symbols && s->name >= GREEK_NAMES) { cert_add("%s_%d", greek_letters[s->name - GREEK_NAMES], name_serial[symbol]); return; }  /* 28q */
    if (symbol >= declared_symbols) { cert_add("%c_%d", s->name, name_serial[symbol]); return; }
    if (s->name >= RELATION_NAMES) cert_add("%s", relation_commands[s->name - RELATION_NAMES]);
    else if (s->name >= GREEK_NAMES) cert_add("%s", greek_letters[s->name - GREEK_NAMES]);
    else if (s->name >= OPERATION_NAMES) cert_add("%s", operation_symbols[s->name - OPERATION_NAMES]);
    else cert_add("%c", s->name);
    if (s->index <= LETTER_INDEX) cert_add("%c", LETTER_INDEX - s->index);
    else if (s->index) cert_add("%d", index_digits(s->index));
}

/* Scrive nel certificato l'elemento di posto id: (f a), o il nome. */
static void cert_ground(int id) {
    const Ground *g = &ground[id];
    if (g->symbol < 0) { certificate_broken = 1; return; }
    if (g->arg[0] >= 0) cert_add("(");
    cert_symbol(g->symbol);
    for (int i = 0; i < 2 && g->arg[i] >= 0; i++) { cert_add(" "); cert_ground(g->arg[i]); }
    if (g->arg[0] >= 0) cert_add(")");
}

/* Scrive nel certificato il nome della variabile di posto slot: la
 * lettera, seguita dal pedice se c'è (x_{1} diventa x1). Non si confonde con
 * un simbolo: il lettore (17o, 17p) non lega mai una lettera che è il nome di
 * un simbolo in vista, e i nomi dati da 28-2 hanno il trattino basso. */
static void cert_slot(int slot) {
    cert_add("%c", slot_data[slot].letter);
    if (slot_data[slot].index) cert_add("%d", index_digits(slot_data[slot].index));
}

/* Scrive nel certificato l'elemento e, con gli elementi di value[] al posto
 * delle variabili sostituite. Una parte o una relazione applicata, (X a),
 * è nella notazione del verificatore anche la condizione che valga. */
static void cert_elem(const Elem *e, SlotValues value) {
    if (e->symbol < 0) {
        if (slot_values_get(value, e->slot) >= 0) cert_ground(slot_values_get(value, e->slot)); else cert_slot(e->slot);
        return;
    }
    if (e->arg[0]) cert_add("(");
    cert_symbol(e->symbol);
    for (int i = 0; i < 2 && e->arg[i]; i++) { cert_add(" "); cert_elem(e->arg[i], value); }
    if (e->arg[0]) cert_add(")");
}

/* Scrive nel certificato la condizione s, con gli elementi di value[] al
 * posto delle variabili sostituite. Una dichiarazione è "true": i simboli
 * dichiarati sono nelle voci symbol. */
static void cert_sentence(const Sentence *s, SlotValues value) {
    static const char *const word[] = {[S_NOT] = "not", [S_AND] = "and", [S_OR] = "or", [S_IMPLIES] = "implies", [S_IFF] = "iff"};
    switch (s->kind) {
    case S_TRUE:
        cert_add("true");
        return;
    case S_EQUIPOTENT:
        /* 17w. (equipotent A B), con un lato prodotto tra parentesi: (S T). */
        cert_add("(equipotent");
        for (int k = 0; k < 2; k++) {
            cert_add(s->sides[k] == 2 ? " (" : " ");
            for (int i = 0; i < s->sides[k]; i++) { if (i) cert_add(" "); cert_sort(slot_data[s->side_slot[k][i]].sort); }
            if (s->sides[k] == 2) cert_add(")");
        }
        cert_add(")");
        return;
    case S_EQUAL:
        cert_add("(= ");
        cert_elem(s->left, value);
        cert_add(" ");
        cert_elem(s->right, value);
        cert_add(")");
        return;
    case S_HOLDS:
        cert_elem(s->left, value);
        return;
    case S_FORALL: case S_EXISTS:
        cert_add("(%s ", s->kind == S_FORALL ? "forall" : "exists");
        cert_slot(s->slot);
        cert_add(" ");
        cert_sort(slot_data[s->slot].sort);
        cert_add(" ");
        cert_sentence(s->a, value);
        cert_add(")");
        return;
    case S_FORALL_PART: case S_EXISTS_PART:
        /* 28j. La parte legata si scrive con il suo nome, come una variabile
         * (11g di checker.c). */
        cert_add("(%s ", s->kind == S_FORALL_PART ? "forallpart" : "existspart");
        cert_symbol(s->part);
        cert_add(" ");
        cert_sort(symbols[s->part].domain[0]);
        cert_add(" ");
        cert_sentence(s->a, value);
        cert_add(")");
        return;
    case S_MEMBER: case S_INCLUDED: case S_SAME: case S_UNIQUE:
        /* Non arrivano qui (17q); se arrivassero, il certificato non le sa
         * dire. */
        certificate_broken = 1;
        return;
    default:
        cert_add("(%s ", word[s->kind]);
        cert_sentence(s->a, value);
        if (s->b) { cert_add(" "); cert_sentence(s->b, value); }
        cert_add(")");
        return;
    }
}

/* Scrive l'inizio del certificato dell'enunciato root: il tipo, gli
 * insiemi (con il numero di elementi del modello m, se c'è), i simboli
 * dichiarati, l'enunciato. */
static void cert_abstract_head(const char *kind, const Sentence *root, const Model *m) {
    SlotValues nothing = SLOT_VALUES_EMPTY;

    certificate_length = 0;
    certificate_broken = 0;
    cert_add("certificate %s\n", kind);
    for (int i = 0; i < sort_count; i++) {
        /* 17v. Un insieme di parti o di applicazioni dice di che cosa è
         * fatto, e il nome del suo simbolo di struttura: la grandezza e la
         * tabella il verificatore le calcola da sé. */
        cert_add("sort ");
        cert_sort(i);
        if (sort_data[i].kind == SORT_NUMBERS) {
            /* 17v. I numeri scritti, nel loro ordine (numeral_position()). */
            cert_add(" numbers");
            for (int s = 0; s < declared_symbols; s++)
                if (symbols[s].name >= NUMERAL_NAMES && symbols[s].range == i) { cert_add(" "); cert_symbol(s); }
        } else if (sort_data[i].kind != SORT_PLAIN) {
            cert_add(sort_data[i].kind == SORT_PARTS ? " parts " : " maps ");
            cert_sort(sort_data[i].base);
            if (sort_data[i].kind == SORT_MAPS) { cert_add(" "); cert_sort(sort_data[i].target); }
            cert_add(" ");
            cert_symbol(sort_data[i].symbol);
        } else if (m) {
            cert_add(" %zu", m->dimension[i].size);
        }
        cert_add("\n");
    }
    /* Warning: se cambia l'ordine delle dichiarazioni implicite o esplicite,
     * aggiorna anche la numerazione della clausificazione in sp_prepare(). */
    for (int s = 0; s < declared_symbols; s++) {
        if (symbol_fixed(s) || symbol_bound[s]) continue;  /* fissato da 17v, o una parte legata (17u): non è dichiarato */
        cert_add("symbol ");
        cert_symbol(s);
        for (int i = 0; i < symbols[s].arity; i++) { cert_add(" "); cert_sort(symbols[s].domain[i]); }
        if (symbols[s].range == TRUTH) cert_add(" bool");
        else { cert_add(" "); cert_sort(symbols[s].range); }
        cert_add("\n");
    }
    cert_add("statement ");
    cert_sentence(root, nothing);
    cert_add("\n");
}

static void cert_witness(int symbol);

/* Scrive, se non ci sono già, le voci witness dei nomi che compaiono
 * nell'elemento di posto id. */
static void cert_names_in(int id) {
    const Ground *g = &ground[id];
    if (g->symbol >= declared_symbols) cert_witness(g->symbol);
    for (int i = 0; i < 2 && g->arg[i] >= 0; i++) cert_names_in(g->arg[i]);
}

/* 28j. Come cert_names_in(), per i nomi che compaiono nell'elemento e: i
 * suoi simboli (una copia o una definizione ne hanno di dati dalla
 * dimostrazione) e gli elementi di value[] al posto delle sue variabili. */
static void cert_names_in_elem(const Elem *e, SlotValues value) {
    if (!e) return;
    if (e->symbol < 0) {
        if (slot_values_get(value, e->slot) >= 0) cert_names_in(slot_values_get(value, e->slot));
        return;
    }
    if (e->symbol >= declared_symbols) cert_witness(e->symbol);
    cert_names_in_elem(e->arg[0], value);
    cert_names_in_elem(e->arg[1], value);
}

/* 28j. Come cert_names_in_elem(), per tutti gli elementi della condizione s. */
static void cert_names_in_sentence(const Sentence *s, SlotValues value) {
    if (!s) return;
    cert_names_in_elem(s->left, value);
    cert_names_in_elem(s->right, value);
    cert_names_in_sentence(s->a, value);
    cert_names_in_sentence(s->b, value);
}

/* Scrive la voce del nome di posto symbol, se non c'è già, preceduta dalle
 * voci dei nomi che usa. Per un nome dato da 28-2 è la voce witness: la
 * condizione "esiste" (o "per ogni", negata) da cui è nato. Per una parte
 * definita (28j) è la voce part: "part D x S c", la parte degli x di S per
 * cui vale c. */
static void cert_witness(int symbol) {
    int serial = name_serial[symbol];
    if (serial > MAX_NAMES_GIVEN || name_known[symbol] < 0) { certificate_broken = 1; return; }
    if (name_written[serial]) return;
    name_written[serial] = 1;
    const Known *named = &now->known[name_known[symbol]];
    if (named->origin == K_MAPDEF) {
        /* 28q. "define NOME A1 [A2] B C": l'applicazione con i suoi insiemi e
         * la sua definizione, dopo le voci dei nomi che usa. */
        const Symbol *f = &symbols[symbol];
        cert_names_in_sentence(named->source, named->value);
        cert_add("define ");
        cert_symbol(symbol);
        for (int a = 0; a < f->arity; a++) { cert_add(" "); cert_sort(f->domain[a]); }
        cert_add(" ");
        cert_sort(f->range);
        cert_add(" ");
        cert_sentence(named->source, named->value);
        cert_add("\n");
        return;
    }
    if (named->origin == K_BIJECTION) {
        /* 28q-1. "witness (equipotent A B) phi... psi...": i nomi di tutte le
         * applicazioni della biiezione, in una voce. */
        const Sentence *e = now->known[named->parent].source;
        cert_add("witness ");
        cert_sentence(e, named->value);
        for (int j = 0; j < e->sides[0] + e->sides[1]; j++) {
            if (name_serial[named->part[j]] <= MAX_NAMES_GIVEN) name_written[name_serial[named->part[j]]] = 1;
            cert_add(" ");
            cert_symbol(named->part[j]);
        }
        cert_add("\n");
        return;
    }
    if (named->origin == K_DEFINED) {
        const Sentence *definition = named->source;
        cert_names_in_sentence(definition->a->b, named->value);
        cert_add("part ");
        cert_symbol(symbol);
        cert_add(" ");
        cert_slot(definition->slot);
        cert_add(" ");
        cert_sort(slot_data[definition->slot].sort);
        cert_add(" ");
        cert_sentence(definition->a->b, named->value);
        cert_add("\n");
        return;
    }
    const Known *p = &now->known[named->parent];
    for (int v = 0; v < slot_count; v++)
        if (slot_values_get(p->value, v) >= 0) cert_names_in(slot_values_get(p->value, v));
    cert_names_in_sentence(p->source, p->value);
    cert_add("witness ");
    cert_sentence(p->source, p->value);
    cert_add(" ");
    cert_symbol(symbol);
    cert_add("\n");
}

/* Scrive nel certificato le voci del ramo appena chiuso: i nomi e le
 * istanze tra le condizioni che servono alla sua contraddizione (needed[],
 * riempito da leaf_write()), nell'ordine in cui sono nate. Un'istanza
 * nomina la condizione da cui viene e un elemento per ognuno dei
 * quantificatori che ha tolto. */
static void cert_leaf(void) {
    for (int i = 0; i < now->knowns; i++) {
        const Known *k = &now->known[i];
        if (!needed[i] || (k->origin != K_INSTANCE && k->origin != K_NAMED && k->origin != K_DEFINED && k->origin != K_MAPDEF && k->origin != K_BIJECTION))
            continue;
        if (k->origin == K_DEFINED || k->origin == K_MAPDEF || (k->origin == K_BIJECTION && !k->negated)) { cert_witness(k->part[0]); continue; }
        if (k->origin == K_BIJECTION) {
            /* 28q-2. "instance (equipotent A B) gamma... delta...", dopo le
             * definizioni delle applicazioni. */
            const Sentence *e = now->known[k->parent].source;
            int count = e->sides[0] + e->sides[1];
            for (int j = 0; j < count; j++)
                if (k->part[j] >= declared_symbols) cert_witness(k->part[j]);
            cert_add("instance ");
            cert_sentence(e, k->value);
            for (int j = 0; j < count; j++) { cert_add(" "); cert_symbol(k->part[j]); }
            cert_add("\n");
            continue;
        }
        const Known *p = &now->known[k->parent];
        if (k->origin == K_NAMED) {
            cert_witness(part_quantifier(p->source) ? k->part[0] : ground[slot_values_get(k->value, p->source->slot)].symbol);
            continue;
        }
        for (int v = 0; v < slot_count; v++)
            if (slot_values_get(k->value, v) >= 0) cert_names_in(slot_values_get(k->value, v));
        cert_names_in_sentence(p->source, p->value);
        for (int j = 0; j < k->parts; j++)
            if (k->part[j] >= declared_symbols) cert_witness(k->part[j]);
        cert_add("instance ");
        cert_sentence(p->source, p->value);
        for (const Sentence *q = p->source; (q->kind == S_FORALL || q->kind == S_EXISTS) && slot_values_get(k->value, q->slot) >= 0; q = q->a) {
            cert_add(" ");
            cert_ground(slot_values_get(k->value, q->slot));
        }

        /* 28j. Per un "per ogni parte", i nomi delle parti scelte. */
        const Sentence *q = p->source;
        for (int j = 0; j < k->parts && part_quantifier(q); j++, q = q->a) {
            cert_add(" ");
            cert_symbol(k->part[j]);
        }
        cert_add("\n");
    }
}

/* Dà al verificatore il certificato appena scritto, e ne riporta la
 * risposta in verdict. Accettato: il verdetto porta il certificato.
 * Respinto: è un errore del programma, unjustified_steps lo conta.
 * Respinto, non controllabile o incompleto: il verdetto diventa sempre
 * NON DIMOSTRATO. Questo linguaggio copre l'enunciato: esaurire le risorse
 * del verificatore non equivale ad averne ottenuto l'accettazione. */
static Verdict abstract_certified(Verdict verdict) {
    const char *text = certificate_text, *why = "è più lungo di quanto il programma sappia scrivere";
    CkAnswer answer = certificate_broken ? CK_UNSUPPORTED : ck_check(&text, &why);
    if (answer == CK_ACCEPTED) {
        verdict.certificate = certificate_text;
        return verdict;
    }
    snprintf(certificate_problem, sizeof certificate_problem, "il verificatore indipendente %s il certificato: %s",
             answer == CK_REJECTED ? "ha respinto" : "non sa controllare", why);
    verdict.reason = certificate_problem;
    if (answer == CK_REJECTED) unjustified_steps++;
    verdict.outcome = NOT_PROVED;
    verdict.proof = verdict.detail = verdict.certificate = NULL;
    return verdict;
}

/* 28n. LE LEGGI DELLE PARTI E DELLE APPLICAZIONI
 *
 * Un enunciato che prende \mathcal{P}(S) o T^{S} come insieme di oggetti
 * (17v) usa ciò che una parte e un'applicazione sono, e che le ipotesi non
 * dicono: due parti con gli stessi elementi sono la stessa parte, e ogni
 * condizione dà la parte degli elementi che la soddisfano. Le dimostrazioni
 * dei libri lo usano senza dirlo ("sia Y = S \setminus \{x\}"); qui sono
 * delle condizioni in più, gli assiomi, scritte come ogni altra e aggiunte
 * alle ipotesi. Sono vere per le parti e le applicazioni vere, e sono le
 * uniche cose che le distinguono da un insieme qualsiasi:
 *
 *   28n-1. Estensionalità delle parti. \forall X, Y \in \mathcal{P}(S)\
 *          ((\forall t \in S\ (t \in X \iff t \in Y)) \implies X = Y): una
 *          parte è l'insieme dei suoi elementi, e niente altro.
 *   28n-2. Estensionalità delle applicazioni. \forall f, g \in T^{S}\
 *          ((\forall x \in S\ (f(x) = g(x))) \implies f = g): un'applicazione
 *          è la tabella dei suoi valori.
 *   28n-3. Comprensione. Per una condizione P(t), con t in S e dei
 *          parametri: per ogni scelta dei parametri esiste Z \in
 *          \mathcal{P}(S) con \forall t \in S\ (t \in Z \iff P(t)). È la
 *          parte \{t \in S \mid P(t)\}, che esiste per qualunque P: è un
 *          sottoinsieme di S, e \mathcal{P}(S) li contiene tutti.
 *
 * Quali comprensioni. Le condizioni P sono infinite, e la ricerca ne prova
 * poche: la parte vuota (P falsa), tutto S (P vera) e le parti di un solo
 * elemento, \{a\} (P è t = a, con a parametro). Sono le parti di cui
 * parlano le dimostrazioni a mano di questi enunciati: "S stesso non è
 * un'immagine", "\{a\} e S contengono tutti e due a". Non è una ricerca
 * completa, e non deve esserlo: come per le istanze (28-3), non trovare una
 * dimostrazione vuol dire NON DIMOSTRATO. Per le applicazioni c'è una legge
 * in più, che dà quelle con due valori (28s).
 *
 * Il verificatore non si fida: riceve gli assiomi nel certificato, una voce
 * axiom per ognuno, e controlla da sé che ognuno abbia la forma di 28n-1,
 * 28n-2, 28n-3 o 28s-1, su un insieme di parti o di applicazioni dichiarato
 * (11h e 11k in checker.c). Un assioma di forma diversa è respinto: non si può far
 * passare un'ipotesi in più per una legge. I modelli finiti (28a, 28m)
 * hanno le parti e le applicazioni vere, dove gli assiomi valgono: un
 * controesempio trovato lì è un controesempio vero. */

/* Gli assiomi dell'enunciato in corso, aggiunti alle sue ipotesi, e la
 * legge di cui ognuno è un caso. */
static const Sentence *axioms[MAX_AXIOMS];
static Law axiom_law[MAX_AXIOMS];
static int axiom_count;

/* Ritorna la legge da cui viene la condizione nota di posto i: quella
 * dell'assioma, se è un assioma o una sua istanza; LAW_NONE altrimenti. */
static int known_law(int i) {
    const Known *k = &now->known[i];
    if (k->origin == K_INSTANCE || k->origin == K_PART) return known_law(k->parent);
    if (k->origin != K_GIVEN) return LAW_NONE;
    for (int a = 0; a < axiom_count; a++)
        if (axioms[a] == k->source) return axiom_law[a];
    return LAW_NONE;
}

/* Ritorna una variabile nuova dell'insieme sort, come elemento, e mette il
 * suo posto in *slot. */
static Elem *axiom_variable(int sort, int *slot) {
    *slot = unfold_slot(sort);
    return elem_new(-1, *slot, NULL, NULL);
}

/* Aggiunge l'assioma a, caso della legge law, se c'è posto; altrimenti lo
 * lascia fuori, e la ricerca ha una legge in meno. */
static void axiom_add(const Sentence *a, Law law) {
    if (axiom_count == MAX_AXIOMS || syntax_error) return;
    axiom_law[axiom_count] = law;
    axioms[axiom_count++] = a;
}

/* 28n-1 e 28n-2. L'estensionalità dell'insieme di posto sort, di parti o
 * di applicazioni. */
static void axiom_extensionality(int sort) {
    int x, y, t, symbol = sort_data[sort].symbol;
    Elem *a = axiom_variable(sort, &x), *b = axiom_variable(sort, &y), *point = axiom_variable(sort_data[sort].base, &t);
    Sentence *same = sort_data[sort].kind == SORT_PARTS
                         ? axiom_join(S_IFF, axiom_atom(S_HOLDS, symbol, point, a), axiom_atom(S_HOLDS, symbol, point, b))
                         : axiom_atom(S_EQUAL, -1, elem_new(symbol, 0, a, point), elem_new(symbol, 0, b, point));
    Sentence *law = axiom_join(S_IMPLIES, axiom_bind(S_FORALL, t, same), axiom_atom(S_EQUAL, -1, a, b));
    axiom_add(axiom_bind(S_FORALL, x, axiom_bind(S_FORALL, y, law)), LAW_EXTENSIONALITY);
}

/* 28n-3. La comprensione della parte \{t \in S \mid P(t)\} di
 * \mathcal{P}(S), insieme di posto sort: kind 0 per la parte vuota (P
 * falsa), 1 per tutto S (P vera), 2 per \{a\} (P è t = a, con a
 * parametro). */
static void axiom_part(int sort, int kind) {
    int z, t, a = -1, symbol = sort_data[sort].symbol;
    Elem *part = axiom_variable(sort, &z), *point = axiom_variable(sort_data[sort].base, &t);
    Sentence *condition = axiom_join(S_TRUE, NULL, NULL);
    if (kind == 0) condition = axiom_join(S_NOT, condition, NULL);
    if (kind == 2) condition = axiom_atom(S_EQUAL, -1, point, axiom_variable(sort_data[sort].base, &a));
    Sentence *law = axiom_bind(S_EXISTS, z, axiom_bind(S_FORALL, t, axiom_join(S_IFF, axiom_atom(S_HOLDS, symbol, point, part), condition)));
    axiom_add(kind == 2 ? axiom_bind(S_FORALL, a, law) : law, LAW_COMPREHENSION);
}

static void sentence_free(const Sentence *s, SlotSet bound, SlotSet *free);

/* Aggiunge a *free, come bit, le variabili dell'elemento e che non sono in
 * bound, cioè non legate dentro l'insieme di cui e fa parte. */
static void elem_free(const Elem *e, SlotSet bound, SlotSet *free) {
    if (!e) return;
    if (e->symbol < 0) { if (!slot_set_contains(bound, e->slot)) *free = slot_set_with(*free, e->slot); return; }
    elem_free(e->arg[0], bound, free);
    elem_free(e->arg[1], bound, free);
}

/* Come elem_free(), per un insieme scritto come nei libri: le lettere di
 * una regola, l'indice di un'unione e la parte di una descrizione sono
 * legate dentro di lui. */
static void set_term_free(const SetTerm *t, SlotSet bound, SlotSet *free) {
    if (!t) return;
    for (int i = 0; i < t->bounds; i++) bound = slot_set_with(bound, t->bound[i]);
    for (int i = 0; i < t->items; i++) elem_free(t->item[i], bound, free);
    set_term_free(t->a, bound, free);
    set_term_free(t->b, bound, free);
    if (t->condition) sentence_free(t->condition, bound, free);
}

/* Come elem_free(), per una condizione. */
static void sentence_free(const Sentence *s, SlotSet bound, SlotSet *free) {
    if (!s) return;
    if (s->kind == S_FORALL || s->kind == S_EXISTS || s->kind == S_UNIQUE) bound = slot_set_with(bound, s->slot);
    elem_free(s->left, bound, free);
    elem_free(s->right, bound, free);
    for (int i = 0; i < s->items; i++) elem_free(s->item[i], bound, free);
    set_term_free(s->set, bound, free);
    set_term_free(s->other, bound, free);
    sentence_free(s->a, bound, free);
    sentence_free(s->b, bound, free);
}

/* 28n-3. La comprensione dell'insieme e, che l'enunciato scrive come una
 * parte (part_template[] in 17v): per ogni valore delle sue lettere libere,
 * esiste la parte Z con \forall t\ (t \in Z \iff t \in e). La condizione
 * t \in e è svolta come in 17q, con lettere nuove al posto di quelle
 * libere, così l'assioma non condivide variabili con l'enunciato. */
static void axiom_template(const SetTerm *e) {
    int sort = sort_derived_find(SORT_PARTS, e->sort[0], -1), z, t, count = 0, original_slots = slot_count;
    SlotSet free = SLOT_EMPTY;
    if (sort < 0) return;
    set_term_free(e, SLOT_EMPTY, &free);
    int *slot = work_arena_array((size_t)original_slots, sizeof *slot);
    if (work_allocation_failed) return;
    for (int v = 0; v < original_slots; v++)
        if (slot_set_contains(free, v)) {
            /* Creare la variabile puo riallocare unfold_to; prima il valore,
             * poi si cerca la cella di destinazione. */
            Elem *replacement = axiom_variable(slot_data[v].sort, &slot[count]);
            unfold_to[v] = replacement;
            count++;
        }
    Elem *part = axiom_variable(sort, &z), *point = axiom_variable(e->sort[0], &t);
    Sentence *from = axiom_join(S_TRUE, NULL, NULL);
    unfold_copying++;
    Sentence *condition = unfold_member(&point, e, from);
    unfold_copying--;
    if (unfold_capacity) memset(unfold_to, 0, unfold_capacity * sizeof *unfold_to);
    Sentence *law = axiom_bind(S_EXISTS, z, axiom_bind(S_FORALL, t, axiom_join(S_IFF, axiom_atom(S_HOLDS, sort_data[sort].symbol, point, part), condition)));
    while (count > 0) law = axiom_bind(S_FORALL, slot[--count], law);
    axiom_add(law, LAW_COMPREHENSION);
}

/* 28s. LE APPLICAZIONI CON DUE VALORI
 *
 * (Sta qui, accanto alle leggi di 28n di cui è una in più; la lettera è
 * venuta dopo le altre.)
 *
 * Le comprensioni di 28n danno delle parti: la vuota, tutto S, \{a\}. Per le
 * applicazioni come oggetti, T^{S}, non ce n'era nessuna, e una
 * dimostrazione che chiede di costruire un'applicazione non si trovava:
 * "se l'ordine punto per punto su S^{S} è totale, S ha un solo elemento" si
 * dimostra a mano prendendo, per a \neq b, le applicazioni che mandano a in
 * a e il resto in b, e a in b e il resto in a, e guardando che non sono
 * confrontabili. La legge che le dà è
 *
 *   28s-1. Per ogni p di S e ogni u, v di T esiste h in T^{S} con h(x) = u
 *          se x = p e h(x) = v altrimenti.
 *
 * È vera: la regola dà a ogni x di S un valore solo, in T, quindi
 * un'applicazione da S a T, e T^{S} le contiene tutte; se S è vuoto non c'è
 * nessun p, se T lo è nessun u, e la legge non dice nulla. Con u = v dà le
 * applicazioni costanti. Perché questa e non altre: sono le applicazioni che
 * si scrivono con i soli elementi che hanno un nome, come \{a\} per le parti,
 * ed è un passo solo; le applicazioni date da una formula qualsiasi sarebbero
 * infinite, come le parti, e la legge diventerebbe una ricerca. Entra tra le
 * comprensioni (LAW_COMPREHENSION), che le prove usano solo quando le altre
 * non bastano (claim_attempts()), e il verificatore la riconosce dalla sua
 * forma, lettera per lettera (11k in checker.c). */

/* 28s-1. Aggiunge agli assiomi la legge delle applicazioni con due valori
 * dell'insieme di posto sort, di applicazioni da S a T, nella forma che il
 * verificatore riconosce: \forall p \in S\ \forall u, v \in T\ \exists h \in
 * T^{S}\ \forall x \in S\ ((x = p \implies h(x) = u) \land (x \neq p
 * \implies h(x) = v)). */
static void axiom_map_point(int sort) {
    int p, u, v, h, x, symbol = sort_data[sort].symbol;
    Elem *point = axiom_variable(sort_data[sort].base, &p), *first = axiom_variable(sort_data[sort].target, &u), *other = axiom_variable(sort_data[sort].target, &v);
    Elem *map = axiom_variable(sort, &h), *at = axiom_variable(sort_data[sort].base, &x);
    Sentence *here = axiom_atom(S_EQUAL, -1, at, point);
    Sentence *body = axiom_join(S_AND, axiom_join(S_IMPLIES, here, axiom_atom(S_EQUAL, -1, elem_new(symbol, 0, map, at), first)),
                                axiom_join(S_IMPLIES, axiom_join(S_NOT, here, NULL), axiom_atom(S_EQUAL, -1, elem_new(symbol, 0, map, at), other)));
    Sentence *law = axiom_bind(S_EXISTS, h, axiom_bind(S_FORALL, x, body));
    axiom_add(axiom_bind(S_FORALL, p, axiom_bind(S_FORALL, u, axiom_bind(S_FORALL, v, law))), LAW_COMPREHENSION);
}

/* Prepara gli assiomi dell'enunciato in corso: per ogni insieme di parti
 * l'estensionalità e le comprensioni descritte in testa al paragrafo, per
 * ogni insieme di applicazioni l'estensionalità e la legge di 28s; poi le
 * comprensioni degli insiemi che l'enunciato scrive come parti, tranne
 * quelli che le prime già danno (\emptyset, tutto S). Usa posti nuovi per
 * le variabili, dopo quelli dello svolgimento. */
static void axioms_prepare(void) {
    axiom_count = 0;
    for (int i = 0; i < sort_count; i++)
        /* I numeri elencati non sono insiemi di oggetti con un simbolo
         * di struttura: non hanno un'appartenenza o un'applicazione da
         * rendere estensionale. Trattarli come mappe userebbe sort_symbol=-1. */
        if (sort_data[i].kind == SORT_PARTS || sort_data[i].kind == SORT_MAPS) axiom_extensionality(i);
    for (int i = 0; i < sort_count; i++)
        for (int kind = 0; kind < 3 && sort_data[i].kind == SORT_PARTS; kind++) axiom_part(i, kind);
    for (int i = 0; i < sort_count; i++)
        if (sort_data[i].kind == SORT_MAPS) axiom_map_point(i);
    for (int i = 0; i < part_template_count; i++)
        if (part_template[i]->kind != ST_EMPTY && part_template[i]->kind != ST_SORT) axiom_template(part_template[i]);
}

/* Quanti dei primi assiomi sono estensionalità: axioms_prepare() le mette
 * prima delle comprensioni. */
static int axioms_extensional(void) {
    int count = 0;
    while (count < axiom_count && axiom_law[count] == LAW_EXTENSIONALITY) count++;
    return count;
}

/* Scrive nel certificato una voce axiom per ogni assioma (28f, 11h in
 * checker.c). */
static void cert_axioms(void) {
    SlotValues nothing = SLOT_VALUES_EMPTY;

    for (int i = 0; i < axiom_count; i++) {
        cert_add("axiom ");
        cert_sentence(axioms[i], nothing);
        cert_add("\n");
    }
}

/* 28g. I RAMI, LE AFFERMAZIONI, IL VERDETTO */

/* Quanti rami sono stati chiusi finora nella dimostrazione in corso: serve
 * a numerare i casi. */
static int leaves_closed;

/* Quanti giri di istanze (28-3) un ramo fa prima di distinguere dei casi
 * (28-5): MAX_ROUNDS, o di meno nelle prove di 28n. */
static int rounds_before_split = MAX_ROUNDS;

/* Copia nel ramo di profondità depth + 1 quello di profondità depth, con
 * i suoi elementi e i suoi nomi, e ci si sposta. Delle tabelle si copia
 * solo la parte in uso: il resto non vale nulla. */
static void branch_copy(int depth) {
    const Branch *from = &branch[depth];
    Branch *to = &branch[depth + 1];
    branch[depth].symbols = symbol_count;
    memcpy(to->known, from->known, sizeof *from->known * (size_t)from->knowns);
    memcpy(to->rep, from->rep, sizeof *from->rep * (size_t)from->grounds);
    memcpy(to->up, from->up, sizeof *from->up * (size_t)from->grounds);
    memcpy(to->why, from->why, sizeof *from->why * (size_t)from->grounds);
    memcpy(to->different, from->different, sizeof *from->different * (size_t)from->differents);
    to->knowns = from->knowns;
    to->differents = from->differents;
    to->grounds = from->grounds;
    to->symbols = from->symbols;
    to->clock = from->clock;
    now = to;
    ground_reindex();
}

/* 28k. QUALI PARTI PROVARE
 *
 * Le parti di S sono infinite quando S lo è, e anche quando è finito sono
 * troppe per provarle tutte: come per gli elementi (28-3, "Quali istanze"),
 * le regole dicono che cosa è lecito, non che cosa conviene. Si fa come a
 * mano: per smentire "f è iniettiva" con l'ipotesi "per ogni X, Y,
 * f(X) \subseteq f(Y) implica X \subseteq Y" si prendono X = \{a\} e Y =
 * \{b\}, con a e b gli elementi che f manda nello stesso punto; per avere
 * f(X) = Z si prende X = f^{-1}(Z). Le parti provate per una parte legata
 * di S sono quelle che si scrivono con un solo passo da ciò che il ramo ha
 * già:
 *
 *   - le parti di S che hanno un nome (dichiarate, o nate da 28-2);
 *   - \{a\}, per ogni elemento a di S con un nome (dichiarato, o nato da
 *     28-2), uno per classe di elementi uguali;
 *   - \emptyset e S;
 *   - f^{-1}(\{c\}) e f^{-1}(P), per ogni applicazione f da S a T, ogni c di T
 *     con un nome e ogni parte P di T con un nome;
 *   - f(P), per ogni applicazione f a valori in S e ogni parte P con un nome
 *     del suo dominio;
 *   - S \setminus P, per ogni parte P di S con un nome.
 *
 * Perché questo limite: sono le costruzioni che si fanno partendo dagli
 * oggetti dell'enunciato senza inventarne di nuovi, e un passo solo, perché
 * le parti costruite da parti costruite crescerebbero senza fine (f(f^{-1}(f(
 * ...)))). Le dimostrazioni dei libri sulle immagini e le controimmagini
 * stanno quasi tutte qui dentro.
 *
 * Come si provano. Aggiungere tutte le istanze insieme, come per gli
 * elementi, non funziona: un'istanza come "f(X) \subseteq f(Y) implica X
 * \subseteq Y" è un'implicazione tra due "per ogni", che si usa solo
 * distinguendo i casi (28-5), e i casi di trenta istanze inutili
 * esaurirebbero la profondità prima di arrivare a quella giusta. Si prova
 * invece una scelta per volta, come chi cerca l'esempio giusto: per un
 * "per ogni parte" del ramo e una scelta delle sue parti, una copia del ramo
 * con le definizioni delle parti e l'istanza; se la copia si chiude, il ramo
 * è chiuso, altrimenti si butta la copia, con ciò che ha scritto, e si prova
 * la scelta successiva. Non è una distinzione di casi: basta che una scelta
 * riesca, perché ciò che si aggiunge è vero comunque.
 *
 * Le scelte vengono prima dei casi, così un'istanza vale in tutti i casi che
 * seguono; se nessuna basta si distinguono i casi, e in ognuno si può
 * scegliere di nuovo, perché casi diversi possono volere parti diverse. Una
 * scelta dentro l'altra al più MAX_PART_CHOICES volte in un ramo, e al più
 * MAX_PART_ATTEMPTS scelte per un'affermazione: oltre, NON DIMOSTRATO. Non
 * trovare la scelta giusta non vuol dire mai FALSO. */

/* Una parte da provare per una parte legata (vedi sopra), prima di
 * averla: come si scrive con ciò che c'è. */
typedef enum {
    P_SYMBOL,          /* una parte con un nome: part */
    P_SINGLE,          /* \{element\} */
    P_EMPTY,           /* \emptyset */
    P_WHOLE,           /* l'insieme sort, tutto */
    P_POINT_PREIMAGE,  /* map^{-1}(\{element\}) */
    P_PREIMAGE,        /* map^{-1}(part) */
    P_IMAGE,           /* map(part) */
    P_COMPLEMENT       /* sort \setminus part */
} PartKind;

/* Una parte dell'insieme sort da provare (PartKind dice quale). I
 * simboli sono posti in symbols[]: element un elemento con un nome, map
 * un'applicazione di un argomento, part una parte con un nome; -1 dove non
 * servono. */
typedef struct {
    PartKind kind;
    int sort, part, map, element;
} PartCandidate;

/* Le variabili delle definizioni (28j): per ogni insieme, la x di "\{x \in
 * S \mid ...\}" e la u di un'immagine, "esiste u con f(u) = x". Si creano la
 * prima volta che servono, con una lettera che l'enunciato non usa; -1
 * finché mancano. Tutte le definizioni le condividono: ognuna è una
 * condizione chiusa, che le lega. */
static int (*definition_slot)[2];
static size_t definition_slot_capacity;

/* Dimensiona i depositi della sola ricerca legacy per istanze. Sono
 * separati dai modelli e da Sp, che non devono pagarne le cache. */
static int instance_sorts_reserve(void) {
    size_t need=(size_t)sort_count;
    return work_reserve((void **)&candidate_domain,&candidate_domain_capacity,need,sizeof *candidate_domain) &&
           work_reserve((void **)&candidate_size,&candidate_size_capacity,need,sizeof *candidate_size) &&
           work_reserve((void **)&definition_slot,&definition_slot_capacity,need,sizeof *definition_slot);
}

/* Ritorna la variabile which (0 per x, 1 per u) delle definizioni di parti
 * di sort, o -1 (annotando exhausted) se le variabili o le lettere sono
 * finite. */
static int definition_variable(int sort, int which) {
    if (definition_slot[sort][which] < 0) {
        int slot = slot_new(fresh_letter(), 0, sort);
        if (slot < 0 || syntax_error) { syntax_error = NULL; exhausted = 1; return -1; }
        definition_slot[sort][which] = slot;
    }
    return definition_slot[sort][which];
}

/* Ritorna 1 se il simbolo symbol è un nome dato da 28-2 (o dichiarato) e non
 * una parte definita: solo da questi si costruiscono altre parti. */
static int part_named(int symbol) {
    return symbol < declared_symbols || (name_known[symbol] >= 0 && now->known[name_known[symbol]].origin == K_NAMED);
}

/* Mette in element[] gli elementi di sort con un nome nel ramo corrente,
 * uno per classe di elementi uguali, e ritorna quanti sono. */
static int named_elements(int sort, int *element) {
    static int *rep; static size_t capacity;
    size_t need = (size_t)(symbol_count < now->grounds ? symbol_count : now->grounds);
    if (!work_reserve((void **)&rep, &capacity, need, sizeof *rep)) { exhausted = 1; return 0; }
    int count = 0;
    for (int s = 0; s < symbol_count; s++) {
        int id = symbols[s].arity == 0 && symbols[s].range == sort ? ground_lookup(s, -1, -1, G_EXACT) : -1, fresh = id >= 0;
        for (int i = 0; i < count && fresh; i++) fresh = rep[i] != now->rep[id];
        if (!fresh) continue;
        rep[count] = now->rep[id];
        element[count++] = s;
    }
    return count;
}

/* Mette in out[] le parti di sort da provare, nell'ordine della testa del
 * paragrafo, al più MAX_PART_CANDIDATES, e ritorna quante sono. */
static int part_candidates(int sort, PartCandidate *out) {
    static int *element; static size_t capacity;
    size_t need = (size_t)(symbol_count < now->grounds ? symbol_count : now->grounds);
    if (!work_reserve((void **)&element, &capacity, need, sizeof *element)) { exhausted = 1; return 0; }
    int count = 0, elements;
#define CANDIDATE(...) do { if (count < MAX_PART_CANDIDATES) out[count++] = (PartCandidate){__VA_ARGS__}; } while (0)
    for (int s = 0; s < symbol_count; s++)
        if (part_of(s, sort) && part_named(s)) CANDIDATE(P_SYMBOL, sort, s, -1, -1);
    elements = named_elements(sort, element);
    for (int i = 0; i < elements; i++) CANDIDATE(P_SINGLE, sort, -1, -1, element[i]);
    CANDIDATE(P_EMPTY, sort, -1, -1, -1);
    CANDIDATE(P_WHOLE, sort, -1, -1, -1);

    /* Un passo da ciò che ha un nome: controimmagini, immagini,
     * complementari. Le applicazioni sono quelle dichiarate, di un
     * argomento. */
    for (int f = 0; f < declared_symbols; f++) {
        const Symbol *map = &symbols[f];
        if (map->arity != 1 || map->range == TRUTH || symbol_bound[f]) continue;
        if (map->domain[0] == sort) {
            elements = named_elements(map->range, element);
            for (int i = 0; i < elements; i++) CANDIDATE(P_POINT_PREIMAGE, sort, -1, f, element[i]);
            for (int s = 0; s < symbol_count; s++)
                if (part_of(s, map->range) && part_named(s)) CANDIDATE(P_PREIMAGE, sort, s, f, -1);
        }
        if (map->range == sort)
            for (int s = 0; s < symbol_count; s++)
                if (part_of(s, map->domain[0]) && part_named(s)) CANDIDATE(P_IMAGE, sort, s, f, -1);
    }
    for (int s = 0; s < symbol_count; s++)
        if (part_of(s, sort) && part_named(s)) CANDIDATE(P_COMPLEMENT, sort, s, -1, -1);
#undef CANDIDATE
    return count;
}

/* Ritorna la regola della parte candidate, la condizione c di "\{x \in S
 * \mid c\}", con la variabile x di posto x; NULL se mancano le variabili. */
static Sentence *candidate_rule(const PartCandidate *c, int x) {
    Elem *element = elem_new(-1, x, NULL, NULL), *named = c->element >= 0 ? elem_new(c->element, 0, NULL, NULL) : NULL;
    Sentence *s, *member;
    switch (c->kind) {
    case P_SINGLE:
        s = sentence_new(S_EQUAL, NULL, NULL, NULL);
        s->left = element;
        s->right = named;
        return s;
    case P_EMPTY:
        return sentence_new(S_NOT, sentence_new(S_TRUE, NULL, NULL, NULL), NULL, NULL);
    case P_POINT_PREIMAGE:
        s = sentence_new(S_EQUAL, NULL, NULL, NULL);
        s->left = elem_new(c->map, 0, element, NULL);
        s->right = named;
        return s;
    case P_PREIMAGE:
        s = sentence_new(S_HOLDS, NULL, NULL, NULL);
        s->left = elem_new(c->part, 0, elem_new(c->map, 0, element, NULL), NULL);
        return s;
    case P_IMAGE: {
        /* Esiste u nel dominio, in part, con map(u) = x. */
        int u = definition_variable(symbols[c->map].domain[0], 1);
        if (u < 0) return NULL;
        Elem *argument = elem_new(-1, u, NULL, NULL);
        member = sentence_new(S_HOLDS, NULL, NULL, NULL);
        member->left = elem_new(c->part, 0, argument, NULL);
        s = sentence_new(S_EQUAL, NULL, NULL, NULL);
        s->left = elem_new(c->map, 0, argument, NULL);
        s->right = element;
        s = sentence_new(S_EXISTS, sentence_new(S_AND, member, s, NULL), NULL, NULL);
        s->slot = u;
        return s;
    }
    case P_COMPLEMENT:
        member = sentence_new(S_HOLDS, NULL, NULL, NULL);
        member->left = elem_new(c->part, 0, element, NULL);
        return sentence_new(S_NOT, member, NULL, NULL);
    default:
        return sentence_new(S_TRUE, NULL, NULL, NULL);
    }
}

/* Dà nel ramo corrente un nome alla parte candidate, che non è P_SYMBOL: se
 * una parte con la stessa regola è già definita la riusa, altrimenti
 * registra una parte nuova, con la lettera letter e un pedice, e la sua
 * definizione "per ogni x di S, x sta nella parte se e solo se c(x)"
 * (K_DEFINED, 28j). Ritorna il simbolo, o -1. */
static int part_define(const PartCandidate *candidate, int letter) {
    SlotValues nothing = SLOT_VALUES_EMPTY;
    int x = definition_variable(candidate->sort, 0);
    Sentence *rule = x >= 0 ? candidate_rule(candidate, x) : NULL;
    if (!rule || exhausted) return -1;

    /* La stessa regola sulla stessa variabile, quindi parte dello stesso
     * insieme: \emptyset di S e \emptyset di T hanno la stessa regola, ma
     * sono parti diverse (un errore di questo genere è stato trovato così). */
    for (int i = 0; i < now->knowns; i++)
        if (now->known[i].origin == K_DEFINED && now->known[i].source->slot == x && sentence_renamed(now->known[i].source->a->b, rule, NULL, NULL, 0))
            return now->known[i].part[0];
    int part = part_symbol_new(letter, candidate->sort, 1);
    if (part < 0) return -1;
    Sentence *member = sentence_new(S_HOLDS, NULL, NULL, NULL);
    member->left = elem_new(part, 0, elem_new(-1, x, NULL, NULL), NULL);
    Sentence *definition = sentence_new(S_FORALL, sentence_new(S_IFF, member, rule, NULL), NULL, NULL);
    definition->slot = x;

    int at = known_add(definition, 0, nothing, K_DEFINED, -1);
    if (at < 0) return -1;
    int chosen = part;
    if (!known_parts(at, &chosen, 1)) return -1;
    name_known[part] = at;
    return part;
}

static int refute(int depth, int splits, int choices);

/* Le scelte provate finora per l'affermazione in corso, e 1 se una scelta,
 * o una prova di 28l, si è fermata a un limite del programma (exhausted):
 * allora non aver trovato la dimostrazione non dice nulla. */
static int part_attempts, part_interrupted;

/* Quante scelte di parti una dentro l'altra sono ammesse in un ramo nella
 * ricerca in corso: da 1 a MAX_PART_CHOICES (vedi abstract_claim()). */
static int part_limit;

/* Il punto a cui torna un tentativo non riuscito (una scelta di parti, 28k,
 * o una prova di 28l): quanto erano lunghi la dimostrazione scritta e il
 * certificato, la memoria usata, i rami chiusi, i nomi dati e le loro voci
 * già scritte, i simboli. */
typedef struct {
    size_t proof, certificate, arena;
    int leaves, names, broken, symbols, cases;  /* cases (28p): i cammini delle foglie scritte */
    unsigned char written[MAX_NAMES_GIVEN + 1];
} SearchMark;

/* Annota in *mark il punto in cui si trova la ricerca. */
static void search_mark(SearchMark *mark) {
    *mark = (SearchMark){proof_length, certificate_length, arena_used, leaves_closed, names_given, certificate_broken, symbol_count, case_paths, {0}};
    memcpy(mark->written, name_written, sizeof name_written);
}

/* Riporta la ricerca al punto mark, sul ramo di profondità depth: ciò che il
 * tentativo ha scritto e dato si dimentica. Un tentativo fermato a un limite
 * lo annota in part_interrupted, e non ferma gli altri. */
static void search_back(const SearchMark *mark, int depth) {
    proof_cut(mark->proof);
    certificate_length = mark->certificate;
    certificate_text[mark->certificate] = 0;
    certificate_broken = mark->broken;
    arena_used = mark->arena;
    leaves_closed = mark->leaves;
    names_given = mark->names;
    case_paths = mark->cases;
    memcpy(name_written, mark->written, sizeof name_written);
    symbol_count = mark->symbols;
    now = &branch[depth];
    ground_reindex();
    if (exhausted) { part_interrupted = 1; exhausted = 0; }
}

/* Prova a chiudere il ramo di profondità depth con una scelta di parti per
 * uno dei suoi "per ogni parte" (vedi la testa del paragrafo); splits e
 * choices sono le distinzioni di casi e le scelte già fatte sopra di lui.
 * Ritorna 1 se una scelta chiude il ramo, con la dimostrazione e le voci del
 * certificato di quella sola; 0 se nessuna, e allora non lascia nulla:
 * testo, certificato, nomi, memoria e il ramo tornano come erano. */
static int part_choose(int depth, int splits, int choices) {
    PartCandidate *candidate = NULL;
    int *names = NULL;
    int *index = NULL, closed = 0;
    size_t candidate_capacity = 0, name_capacity = 0, index_capacity = 0;
    Branch *here = &branch[depth];
    for (int r = 0; r < here->knowns; r++) {
        const Known *rule = &here->known[r];
        if (rule->stage != K_RULE || !part_quantifier(rule->source)) continue;

        /* Le parti legate in testa alla regola, e le parti da provare per
         * ognuna. I temporanei appartengono a questa chiamata: una scelta
         * ricorsiva puo crescere senza spostare i vettori del suo genitore. */
        const Sentence *body = rule->source;
        int parts = 0, more = 1;
        for (const Sentence *q = body; part_quantifier(q) && (q->kind == S_FORALL_PART) != rule->negated; q = q->a) parts++;
        if (!work_reserve((void **)&candidate, &candidate_capacity, (size_t)parts * MAX_PART_CANDIDATES, sizeof *candidate) ||
            !work_reserve((void **)&names, &name_capacity, 2 * (size_t)parts, sizeof *names) ||
            !work_reserve((void **)&index, &index_capacity, 2 * (size_t)parts, sizeof *index)) {
            exhausted = 1; goto done;
        }
        int *bound = names, *chosen = names + parts;
        int *candidates = index, *pick = index + parts;
        for (int j = 0; j < parts; j++, body = body->a) {
            bound[j] = body->part;
            candidates[j] = part_candidates(symbols[body->part].domain[0], candidate + (size_t)j * MAX_PART_CANDIDATES);
            pick[j] = 0;
            more = more && candidates[j] > 0;
        }

        /* Ogni scelta, come un contachilometri. */
        for (; more; ) {
            SearchMark mark;
            if (part_attempts++ >= MAX_PART_ATTEMPTS || failure) goto done;
            search_mark(&mark);

            /* La copia del ramo, con le definizioni delle parti scelte e
             * l'istanza, se non c'è già. */
            int fresh = 1;
            branch_copy(depth);
            for (int j = 0; j < parts && fresh; j++) {
                const PartCandidate *c = &candidate[(size_t)j * MAX_PART_CANDIDATES + (size_t)pick[j]];
                chosen[j] = c->kind == P_SYMBOL ? c->part : part_define(c, symbols[bound[j]].name);
                fresh = chosen[j] >= 0;
            }
            for (int i = r + 1; i < now->knowns && fresh; i++)
                fresh = now->known[i].parent != r || now->known[i].parts != parts ||
                        memcmp(now->known[i].part, chosen, sizeof *chosen * (size_t)parts) != 0;
            if (fresh) {
                const Sentence *instance = body;
                for (int j = 0; j < parts; j++) instance = sentence_rename(instance, bound[j], chosen[j]);
                int at = known_add(instance, rule->negated, rule->value, K_INSTANCE, r);
                if (at >= 0 && known_parts(at, chosen, parts)) {
                    if (!exhausted && refute(depth + 1, splits, choices + 1)) { closed = 1; goto done; }
                }
            }

            /* Non è bastata: si torna com'era, e alla scelta successiva. */
            search_back(&mark, depth);
            more = 0;
            for (int j = 0; j < parts && !more; j++) {
                if (++pick[j] < candidates[j]) more = 1; else pick[j] = 0;
            }
        }
    }
done:
    free(candidate); free(names); free(index);
    return closed;
}

/* 28-5. Aggiunge alle cose note del ramo in corso il caso side della
 * disgiunzione in attesa di posto open, che non resta più in attesa. */
static void case_continue(int open, int side) {
    Known *k = &now->known[open];
    Parts parts;
    k->stage = K_DONE;
    if (k->source->kind == S_IFF) {
        /* "A se e solo se B": o tutte e due vere, o tutte e due false; se è
         * negato, una vera e l'altra falsa. Il caso fissa A, e con lei B. */
        known_add(k->source->a, side, k->value, K_CASE, open);
        known_add(k->source->b, side != k->negated, k->value, K_CASE, open);
    } else if (sentence_parts(k->source, k->negated, &parts)) {
        known_add(side ? parts.y : parts.x, side ? parts.ny : parts.nx, k->value, K_CASE, open);
    }
}

/* 28-5. Apre il caso side della disgiunzione in attesa di posto open: una
 * copia del ramo di profondità depth (branch_copy()), con quel caso in più
 * tra le cose note. */
static void case_open(int depth, int open, int side) {
    branch_copy(depth);
    case_continue(open, side);
}

/* 28o. LA SCELTA DEL CASO
 *
 * (Sta qui, accanto a 28-5 che serve; la lettera è venuta dopo le altre.)
 *
 * 28-5 distingue i casi della prima disgiunzione in attesa, dopo
 * MAX_ROUNDS giri di istanze. Con le parti e le applicazioni come oggetti
 * le istanze crescono in fretta (un elemento dà una parte che lo contiene,
 * la parte un elemento che contiene, e così via), e le tabelle si riempiono
 * prima della fine dei giri; e le disgiunzioni in attesa sono decine, con la
 * prima che spesso non serve. Con split_lookahead acceso, dopo ogni giro si
 * guarda avanti: per le disgiunzioni in attesa più recenti (al più
 * MAX_LOOKAHEAD) si apre ognuno dei due casi e si vede se si chiude da solo,
 * con ciò che segue senza istanze (settle()). Se una ha un caso che si
 * chiude, si distinguono subito i suoi casi, preferendo quella con tutti e
 * due chiusi; altrimenti si va avanti come prima. È la regola del
 * "letterale che fallisce" dei dimostratori: un caso che si chiude subito
 * costa una riga, e l'altro sa una cosa in più. Le prove non lasciano nulla:
 * i casi aperti sono copie, e i nomi dati lì si tolgono. Cambia solo
 * l'ordine della ricerca, non ciò che una dimostrazione trovata dice: ogni
 * suo passo è ricontrollato come sempre (28e). Le stesse prove scelgono le
 * istanze con più cura (instance_guarded(), in 28-3, dove split_lookahead è
 * dichiarata). */

/* Ritorna la disgiunzione in attesa del ramo di profondità depth con un
 * caso che si chiude da solo, scelta come in testa al paragrafo, o -1; in
 * *closing mette quale caso si chiude, 0 o 1, oppure 2 se si chiudono tutti
 * e due. */
static int split_choice(int depth, int *closing) {
    int best = -1, probes = 0, saved = exhausted;
    for (int i = branch[depth].knowns - 1; i >= 0 && probes < MAX_LOOKAHEAD; i--) {
        if (branch[depth].known[i].stage != K_WAITING) continue;
        int closed[2];
        probes++;
        for (int side = 0; side < 2; side++) {
            case_open(depth, i, side);
            closed[side] = settle() && !exhausted;
            exhausted = saved;
            symbol_count = branch[depth].symbols;
        }
        if (closed[0] && closed[1]) { best = i; *closing = 2; break; }
        if ((closed[0] || closed[1]) && best < 0) { best = i; *closing = closed[1]; }
    }
    now = &branch[depth];
    ground_reindex();
    return best;
}

/* 28l. Il valore di splits con cui refute() fa solo i suoi giri di istanze,
 * senza casi né scelte: è la prova di un caso. */
#define PROBE (MAX_SPLITS + 1)

/* 28l. Cerca, tra le prime MAX_PROBES disgiunzioni in attesa del ramo di
 * profondità depth, una con un caso che si chiude con i soli giri di
 * istanze; se la trova, chiude quel caso e poi l'altro, con le stesse
 * distinzioni di casi (splits) e scelte (choices) che restano al ramo.
 * Ritorna 1 se il ramo si è chiuso così; 0 se nessuna disgiunzione ha un
 * caso così, e allora non lascia nulla; -1 se ce n'era una ma l'altro caso
 * non si è chiuso: allora nemmeno il ramo si chiuderebbe (l'altro caso sa
 * tutto ciò che sa il ramo, e una cosa in più), e non lascia nulla. */
static int cheap_split(int depth, int splits, int choices) {
    static SearchMark mark[MAX_BRANCHES];
    Branch *here = &branch[depth];
    for (int open = 0, probes = 0; open < here->knowns && probes < MAX_PROBES && !failure; open++) {
        if (here->known[open].stage != K_WAITING) continue;
        probes++;
        for (int side = 0; side < 2; side++) {
            search_mark(&mark[depth]);
            case_open(depth, open, side);
            if (!refute(depth + 1, PROBE, choices)) { search_back(&mark[depth], depth); continue; }
            now = here;
            symbol_count = here->symbols;
            case_open(depth, open, !side);
            if (refute(depth + 1, splits, choices)) return 1;
            search_back(&mark[depth], depth);
            return -1;
        }
    }
    return 0;
}

/* Cerca una contraddizione in ogni continuazione del ramo di profondità
 * depth, e scrive la dimostrazione di ogni ramo che chiude. Ritorna 1 se li
 * chiude tutti, e allora ciò che il ramo suppone è impossibile. splits e
 * choices sono le distinzioni di casi e le scelte di parti (28k) fatte
 * sopra di lui; con splits uguale a PROBE fa solo i giri di istanze (28l).
 *
 * Prima ciò che segue senza scelte e le istanze, per un numero fisso di
 * giri (rounds_before_split). Se non basta, una disgiunzione con un caso che
 * si chiude subito (28l), che non conta tra le distinzioni di casi; poi una
 * scelta di parti (28k); poi 28-5: la prima disgiunzione in attesa dà due
 * casi, ognuno una copia del ramo con una parte in più tra le cose note, e
 * devono chiudersi tutti e due.
 *
 * 28o. Con split_lookahead, dopo ogni giro: se una disgiunzione ha i due
 * casi che si chiudono con ciò che segue senza istanze, si distinguono, e
 * il ramo è chiuso senza contarla tra le distinzioni; se ne ha uno, quello
 * si scrive subito, chiuso, e il ramo va avanti con l'altro caso tra le
 * cose note, senza scendere di profondità. */
static int refute(int depth, int splits, int choices) {
    int open = -1, closing = 0;
    now = &branch[depth];
    for (int round = 0; !exhausted; round++) {
        if (settle()) {
            /* Il ramo è chiuso: la sua dimostrazione scritta, e le sue voci
             * del certificato. */
            if (!leaf_write(splits || leaves_closed ? ++leaves_closed : 0)) return 0;
            cert_leaf();
            return 1;
        }

        /* 28o. Un caso che si chiude da solo vale più di altre istanze. */
        if (split_lookahead && splits != PROBE && depth + 1 < MAX_BRANCHES && (open = split_choice(depth, &closing)) >= 0) {
            if (closing == 2) break;
            case_open(depth, open, closing);
            if (!settle() || !leaf_write(++leaves_closed)) return 0;
            cert_leaf();
            now = &branch[depth];
            symbol_count = now->symbols;
            ground_reindex();
            case_continue(open, !closing);
            open = -1;
            round--;
            continue;
        }
        if (round == rounds_before_split || !instantiate()) break;
    }
    if (exhausted || splits == PROBE || depth + 1 == MAX_BRANCHES) return 0;
    if (open < 0) {
        int cheap = cheap_split(depth, splits, choices);
        if (cheap) return cheap > 0;
        if (choices < part_limit && part_choose(depth, splits, choices)) return 1;
    }
    for (int i = 0; i < now->knowns && open < 0; i++)
        if (now->known[i].stage == K_WAITING) open = i;
    if (exhausted || open < 0 || (splits == MAX_SPLITS && closing != 2)) return 0;
    for (int side = 0; side < 2; side++) {
        /* Il caso: una copia del ramo, con i suoi elementi e i suoi nomi. */
        case_open(depth, open, side);
        if (!refute(depth + 1, splits + (closing != 2), choices)) return 0;
        now = &branch[depth];
        symbol_count = now->symbols;
    }
    return 1;
}

/* Ritorna 1 se dalle ipotesi, le condizioni di hypothesis[0..hypotheses),
 * segue claim: lo dimostra per assurdo, e scrive la dimostrazione. Se
 * ritorna 0 non lascia testo.
 *
 * 28k. La ricerca si fa con al più una scelta di parti per ramo, poi, se non
 * basta e qualche scelta c'è stata, da capo con due: così una scelta in più
 * non viene provata prima di una distinzione di casi che basterebbe, e la
 * dimostrazione non si porta dietro parti che non servono. */
static int abstract_claim(const Sentence **hypothesis, int hypotheses, const Sentence *claim) {
    SlotValues nothing = SLOT_VALUES_EMPTY;
    size_t start = proof_length, certificate_start = certificate_length, arena_start = arena_used;
    int declared = symbol_count, proved = 0, certificate_was_broken = certificate_broken;

    for (part_limit = 1; part_limit <= MAX_PART_CHOICES && !proved && !exhausted; part_limit++) {
        proof_cut(start);
        certificate_length = certificate_start;
        certificate_text[certificate_start] = 0;
        arena_used = arena_start;
        symbol_count = declared;

        /* Il ramo di partenza: "vero" al posto 0, gli elementi con un nome
         * che l'enunciato dichiara, le ipotesi, la tesi negata.
         *
         * Perché gli elementi dichiarati subito. Un elemento entra nella
         * tabella quando lo nomina un fatto; ma u, dichiarato con u \in S,
         * può comparire solo sotto un quantificatore, come in f(u) \in
         * f(\{u\}), e allora nessuna istanza lo proverebbe. Metterlo in
         * tabella è lecito: u è un elemento di S, e un'istanza su u è
         * un'istanza su un termine chiuso fatto di simboli dichiarati, che il
         * verificatore accetta (11d, 11f di checker.c). */
        now = &branch[0];
        now->knowns = now->differents = now->clock = 0;
        now->grounds = 0;
        memset(exact, -1, sizeof exact);
        ground_lookup(-1, -1, -1, G_CREATE);
        for (int s = 0; s < declared; s++)
            if (symbols[s].arity == 0) ground_lookup(s, -1, -1, G_CREATE);
        for (int i = 0; i < hypotheses; i++) known_add(hypothesis[i], 0, nothing, K_GIVEN, -1);
        known_add(claim, 1, nothing, K_DENIED, -1);

        proof_add("\\item \\emph{Claim:} $");
        put_sentence(claim, 0, nothing, 0);
        proof_add("$.\n\\begin{itemize}\n");
        leaves_closed = 0;

        /* Nel certificato, un caso per l'affermazione: la si suppone falsa.
         * I nomi ripartono da capo, come nel verificatore. */
        cert_add("case (not ");
        cert_sentence(claim, nothing);
        cert_add(")\n");
        names_given = 0;
        memset(name_written, 0, sizeof name_written);
        part_attempts = 0;
        case_paths = case_overflow = 0;
        proved = refute(0, 0, 0);
        proof_add("\\end{itemize}\n");

        /* 28p. I casi scritti devono coprire tutto: se non lo fanno, il
         * programma ha sbagliato, e l'affermazione non è dimostrata. */
        if (proved && !case_paths_complete()) {
            unjustified_steps++;
            proved = 0;
            break;
        }
        if (!part_attempts) break;
    }

    /* I nomi dati durante la dimostrazione valgono solo per lei. Se non
     * riesce, il suo caso esce anche dal certificato (28n: la si può
     * riprovare con più leggi). */
    symbol_count = declared;
    if (!proved) {
        proof_cut(start);
        certificate_length = certificate_start;
        certificate_text[certificate_start] = 0;
        certificate_broken = certificate_was_broken;
    }
    return proved;
}

/* Ritorna 1 se l'affermazione claim segue dalle ipotesi hypothesis[]: le
 * prime first_pass sono le ipotesi dell'enunciato e le estensionalità
 * (28n), le altre, fino a hypotheses, le comprensioni. Prova come
 * abstract_claim(), con le sole prime; poi (28o) guardando avanti e
 * distinguendo i casi dopo LOOKAHEAD_ROUNDS giri, prima che le istanze
 * riempiano le tabelle; poi, se ci sono, anche con le comprensioni. */
static int claim_passes(const Sentence **hypothesis, int hypotheses, int first_pass, const Sentence *claim) {
    int first = first_pass < hypotheses ? first_pass : hypotheses;
    int proved = abstract_claim(hypothesis, first, claim);
    for (int pass = 1; !proved && pass < 3; pass++) {
        if (pass == 2 && first_pass >= hypotheses) break;
        exhausted = 0;
        split_lookahead = 1;
        rounds_before_split = LOOKAHEAD_ROUNDS;
        proved = abstract_claim(hypothesis, pass == 1 ? first : hypotheses, claim);
        split_lookahead = 0;
        rounds_before_split = MAX_ROUNDS;
    }
    return proved;
}

/* 28r. Come claim_passes(), con le istanze scelte dal modello candidato: per
 * ogni generazione di model_generations[], prima senza e poi con le
 * comprensioni, e MODEL_ROUNDS giri prima di distinguere i casi, perché ogni
 * giro aggiunge una sola istanza per "per ogni", e una catena di istanze che
 * dipendono l'una dall'altra chiede un giro per anello. */
static int model_passes(const Sentence **hypothesis, int hypotheses, int first_pass, const Sentence *claim) {
    int first = first_pass < hypotheses ? first_pass : hypotheses, proved = 0;
    for (size_t g = 0; !proved && g < sizeof model_generations / sizeof *model_generations; g++)
        for (int all = 0; all < 2 && !proved && (!all || first < hypotheses); all++) {
            exhausted = 0;
            model_guided = 1;
            generation_limit = model_generations[g];
            rounds_before_split = MODEL_ROUNDS;
            proved = abstract_claim(hypothesis, all ? hypotheses : first, claim);
            model_guided = 0;
            rounds_before_split = MAX_ROUNDS;
        }
    return proved;
}

/* Come claim_passes(), e (28q) con un testimone per volta per le
 * equipotenze da dimostrare: dal più corto, finché la dimostrazione riesce o
 * i testimoni finiscono. Senza equipotenze witness_options resta 0, e il
 * giro è uno solo. Infine (28r) model_passes(), con il primo testimone: le
 * istanze scelte dal modello vengono dopo tutte le altre prove, così ciò che
 * quelle dimostrano non cambia. */
static int claim_attempts(const Sentence **hypothesis, int hypotheses, int first_pass, const Sentence *claim) {
    int proved = 0;
    witness_options = 0;
    for (witness_choice = 0; !proved && (witness_choice == 0 || witness_choice < witness_options); witness_choice++) {
        if (witness_choice) exhausted = 0;
        proved = claim_passes(hypothesis, hypotheses, first_pass, claim);
    }

    /* Un testimone che ha dentro un passo w3 o w4 sotto un'altra applicazione
     * (un prodotto, una composizione) chiede le identità di quel passo a metà
     * della dimostrazione, con l'estensionalità, e quindi più giri di istanze
     * prima di distinguere i casi: un ultimo tentativo con il doppio, per
     * ogni testimone. */
    for (witness_choice = 0; !proved && witness_choice < witness_options; witness_choice++) {
        exhausted = 0;
        rounds_before_split = 2 * MAX_ROUNDS;
        proved = abstract_claim(hypothesis, first_pass < hypotheses ? first_pass : hypotheses, claim);
        rounds_before_split = MAX_ROUNDS;
    }
    witness_choice = 0;
    if (!proved) proved = model_passes(hypothesis, hypotheses, first_pass, claim);
    return proved;
}
/* 28o. Un'affermazione che non si dimostra tutta insieme si prova a pezzi,
 * ognuno come un'affermazione a sé: un'equivalenza A \iff B nei due versi,
 * A \implies B e B \implies A; A \implies (B \land C) come A \implies B e A
 * \implies C. L'affermazione segue dai pezzi per le sole leggi della logica,
 * e il verificatore, che ritrova i connettivi da sé (11e in checker.c), lo
 * ricontrolla. Ritorna 1 se ogni pezzo è dimostrato; un pezzo che non si
 * dimostra si divide ancora, se si può. */
static int claim_halves(const Sentence **hypothesis, int hypotheses, int first_pass, const Sentence *claim) {
    const Sentence *x, *y;
    if (claim->kind == S_IFF) {
        x = axiom_join(S_IMPLIES, claim->a, claim->b);
        y = axiom_join(S_IMPLIES, claim->b, claim->a);
    } else if (claim->kind == S_IMPLIES && claim->b->kind == S_AND) {
        x = axiom_join(S_IMPLIES, claim->a, claim->b->a);
        y = axiom_join(S_IMPLIES, claim->a, claim->b->b);
    } else {
        return 0;
    }
    return (claim_attempts(hypothesis, hypotheses, first_pass, x) || claim_halves(hypothesis, hypotheses, first_pass, x)) &&
           (claim_attempts(hypothesis, hypotheses, first_pass, y) || claim_halves(hypothesis, hypotheses, first_pass, y));
}

/* Aggiunge a list[], dal posto count, le condizioni di cui s è la
 * congiunzione, saltando le dichiarazioni; ritorna il nuovo numero, al più
 * max. */
static int conjuncts(const Sentence *s, const Sentence **list, int count, int max) {
    if (s->kind == S_AND) return conjuncts(s->b, list, conjuncts(s->a, list, count, max), max);
    if (s->kind != S_TRUE && count < max) list[count++] = s;
    return count;
}

/* Il testo di un modello, per il verdetto in una riga: una copia posseduta
 * qui, riusata tra gli enunciati e valida fino al modello successivo. */
static char *model_text;
static size_t model_text_capacity;  /* Byte posseduti in model_text. */

/* Consegna un modello gia trovato: ricalcola ipotesi, tesi e notazione
 * scritta, poi scrive il documento e il certificato indipendente. La stessa
 * uscita serve alle due quote di ricerca; una ricerca precedente puo aver
 * lasciato una dimostrazione incompleta, che qui viene svuotata. */
static Verdict abstract_model_result(Verdict verdict, const Sentence *written, const Sentence *root,
                                     const Model *model, long long compared) {
    size_t *value = model_variables();
    if (work_allocation_failed) { verdict.outcome = NOT_PROVED; verdict.reason = OUT_OF_MEMORY; return verdict; }
    proof_reset();

    /* Il modello trovato viene ricalcolato pezzo per pezzo: ipotesi
     * vere e tesi falsa, e non solo "l'implicazione è falsa". Con la
     * notazione dei libri, anche l'enunciato com'è scritto (28h). */
    model_steps = 0;
    int confirmed = abstract_example ? model_holds(model, root, value)
                  : root->kind == S_IMPLIES ? model_holds(model, root->a, value) && !model_holds(model, root->b, value)
                  : !model_holds(model, root, value);
    if (written != root) confirmed = confirmed && book_holds(model, written, value) == abstract_example;

    /* Un conto interrotto non conferma nulla, nemmeno quando il suo valore
     * è quello atteso: per un controesempio "non vale" è anche ciò che
     * ritorna un quantificatore fermato a metà. */
    if (!model_steps_complete()) {
        verdict.outcome = NOT_PROVED;
        verdict.reason = "il modello trovato non si è potuto ricalcolare entro il budget dei passi (--model-steps)";
        return verdict;
    }
    if (!confirmed) {
        unjustified_steps++;
        verdict.outcome = NOT_PROVED;
        verdict.reason = "la verifica indipendente non conferma il modello trovato";
        return verdict;
    }
    proof_add(abstract_example ? "\\textbf{Proof.} An example: " : "\\textbf{The statement is false.} A counterexample: ");
    proof_growable = 1;
    size_t from = proof_length;
    put_model(model);
    if (proof_broken) { verdict.outcome = NOT_PROVED; verdict.reason = "memoria esaurita scrivendo il modello"; return verdict; }
    /* Una copia intera: il testo di un modello cresce con i suoi insiemi,
     * e troncato a metà di una formula non si legge più (con 130 insiemi la
     * riga del verdetto finiva in "$S_{120} = \{"). La dimostrazione scritta
     * continua a crescere e può spostarsi: non si può puntare lì dentro. */
    size_t model_length = proof_length - from;
    if (!work_reserve((void **)&model_text, &model_text_capacity, model_length + 1, 1)) {
        verdict.outcome = NOT_PROVED; verdict.reason = OUT_OF_MEMORY; return verdict;
    }
    memcpy(model_text, proof_text + from, model_length);
    model_text[model_length] = 0;
    proof_add(abstract_example ? ". Computing with these tables, the condition holds." : ". Computing with these tables, the hypotheses hold and the conclusion fails.");
    put_unfolding_note(compared);
    if (abstract_example) proof_add(" $\\Box$");
    verdict.outcome = abstract_example ? PROVED : REFUTED;
    verdict.method = "con un esempio";
    verdict.detail = abstract_example ? NULL : model_text;
    verdict.proof = proof_text;

    /* Il certificato: il modello, in cui il verificatore ricalcola
     * l'enunciato con il suo valutatore. Se non lo sa ricalcolare (un
     * modello troppo grande per lui) il modello resta senza conferma, e
     * il verdetto non c'è: required = 1. */
    cert_abstract_head(abstract_example ? "example" : "counterexample", root, model);
    for (int s = 0; s < symbol_count; s++) {
        size_t cells;
        if (symbol_fixed(s) || symbol_bound[s]) continue;  /* fissato (28m), o una parte legata (28i): non ha tabella */
        model_cells(model, s, &cells);
        cert_add("table ");
        cert_symbol(s);
        for (size_t c = 0; c < cells; c++) cert_add(" %zu", model->table[s][c]);
        cert_add("\n");
    }
    cert_add("end\n");
    return abstract_certified(verdict);

}

/* Una quota di lavoro del model finding. Il limite di cardinalita resta
 * assente: cambiare quota modifica soltanto quanta ricerca si esegue prima
 * di dare tempo alla dimostrazione. Il programma ha uno stato singolo. */
static int model_sat_slice(const Sentence *root, int wanted, Model *model, long long *tried, int bound,
                           unsigned long long allowance) {
    if (!allowance) return 0;
    unsigned long long saved = model_work_limit;
    model_work_limit = allowance;
    int found = model_sat_search(root, wanted, model, tried, bound);
    model_work_limit = saved;
    return found;
}

/* 28u. SATURAZIONE: CLAUSOLE DA FARE E CLAUSOLE GIA ELABORATE
 *
 * Si nega l'enunciato e lo si traduce nel primo ordine non tipato, con un
 * predicato per ogni dominio: gli insiemi possono essere vuoti. Skolem
 * conserva le dipendenze dagli universali e i nomi di Tseitin conservano
 * tutte le variabili libere. Il checker ricostruisce la traduzione con un
 * lettore e strutture indipendenti; nessuna sua funzione cerca per noi.
 *
 * Una clausola scelta dalla coda viene combinata con quelle elaborate:
 * risoluzione, risoluzione dell'uguaglianza, fattorizzazione e superposizione.
 * I genitori hanno sempre variabili distinte prima dell'unificazione.
 * L'occurs-check impedisce sostituzioni cicliche: x=f(x) non ha un
 * unificatore tra termini finiti. Ogni deduzione conserva genitori,
 * posizioni e sostituzione simultanea completamente risolta.
 *
 * KBO con tutti i pesi uguali a uno orienta le riscritture; una clausola
 * sussunta e ridondante. La scelta alterna peso ed eta: ogni quinto turno
 * prende la piu vecchia, quindi una clausola persistente non resta esclusa
 * perche continuano a nascerne di leggere. Esaurire risorse o saturare senza
 * il vuoto non prova la tesi. Solo il vuoto ricontrollato la dimostra.
 *
 * SInE sceglie prima le clausole attivate dai simboli meno comuni della
 * tesi, poi allarga la tolleranza. Il portafoglio limita questi tentativi
 * per lavoro e tempo CPU; l'ultimo riattiva tutte le clausole. Le clausole
 * sospese conservano indice e contenuto: il checker ricostruisce sempre
 * l'enunciato originale, non una tesi riscritta dal selettore. Riprendere
 * dopo una quota richiede di rimettere in coda anche le clausole elaborate:
 * l'ultima inferenza puo essere stata interrotta a meta.
 *
 * AVATAR separa componenti a variabili disgiunte e introduce nomi per le
 * loro chiusure universali. Il SAT sceglie quali richiedere; le assunzioni
 * restano guardie nelle clausole complete. Una contraddizione condizionale
 * diventa un vincolo booleano che esclude il ramo. Prima di cambiare ramo
 * si rilegge il modello contro tutte le clausole SAT. Una risposta UNSAT
 * richiede un replay RUP: propagazione sotto le assunzioni opposte alla
 * clausola appresa, poi risoluzione all'indietro delle ragioni del conflitto.
 * Il checker riceve solo definizioni, partizioni e risoluzioni esplicite.
 * SAT, replay e clausole condividono i budget di lavoro e memoria; una
 * quota locale lascia al ciclo ordinario le trasformazioni gia valide.
 *
 * I principi universali su parti vengono istanziati con comprensioni
 * {x in S | L(x)}, da proprieta letterali ricavate dai controesempi ground.
 * Questo permette di usare principi induttivi forniti come ipotesi: non
 * attribuisce a un insieme arbitrario la semantica standard dei naturali.
 * Le istanze hanno contesti copiati, nomi freschi e gruppi di clausole
 * ricostruiti dal checker. Una clausificazione direzionale della NNF e
 * l'eliminazione booleana dei nomi tecnici limitano i passaggi ausiliari;
 * tutte le semplificazioni conservano risoluzioni esplicite. Non si assume
 * mai vera la proprieta scelta per la comprensione.
 *
 * Riferimenti: Kovacs e Voronkov, First-Order Theorem Proving and Vampire
 * (2013); Sternagel e Thiemann, Formalizing Knuth-Bendix Orders and
 * Knuth-Bendix Completion (2013); Hoder e Voronkov, Sine Qua Non for Large
 * Theory Reasoning (2011), selezione applicata qui alle clausole e ai soli
 * simboli originali, non ai nomi tecnici della traduzione; Voronkov,
 * AVATAR (2014); Plaisted e Greenbaum, A Structure-Preserving Clause Form
 * Translation (1986); Reger e Voronkov, Induction in Saturation-Based
 * Proof Search (2019). Si implementano
 * le regole, senza codice o risolutori esterni.
 */

/* Un blocco stabile di memoria della ricerca. next concatena i blocchi,
 * used/capacity contano byte del payload allineato. Nessun blocco si sposta.
 * I temporanei si riusano fra inferenze; le deduzioni vivono fino al termine. */
typedef struct SpBlock SpBlock;
struct SpBlock {
    SpBlock *next;
    size_t used, capacity;
    _Alignas(16) unsigned char data[];
};

/* Un'arena possiede tutti i blocchi a partire da first; current e quello
 * da cui continuare. Solo l'arena dei temporanei viene azzerata. */
typedef struct { SpBlock *first, *current; } SpArena;

/* Un simbolo della traduzione: arity conta gli argomenti; predicate
 * distingue un atomo da una funzione. component vale indice AVATAR piu
 * uno, zero negli altri casi. Il numero e quello nel certificato. */
typedef struct { int arity, predicate, component; } SpSymbol;

/* Un termine condiviso, con argomenti contigui in argument. weight e il
 * numero di occorrenze di simboli e variabili, per KBO e la scelta in coda.
 * Un riferimento positivo indica un termine; -1-v la variabile v; zero
 * l'assenza di un termine, usata per i predicati e le costanti logiche. */
typedef struct { int symbol, first, count; unsigned long long weight; } SpTerm;

/* Un atomo eventualmente negato. right!=0 indica un'uguaglianza; altrimenti
 * left e un predicato, oppure zero per vero. negative appartiene a {0,1}. */
typedef struct { int left, right, negative; } SpLiteral;

/* Una sostituzione esplicita nel certificato: variable e il nome prima
 * della normalizzazione, term la sua immagine gia completamente risolta. */
typedef struct { int variable, term; } SpBinding;

/* Regole del calcolo: INPUT viene ricostruita dal checker; COMPONENT e
 * COMPLEMENT sono definizioni conservative, SPLIT astrae una partizione,
 * COMPREHEND ricostruisce un'istanza universale su parti.
 * Le altre sono le inferenze esplicite del primo ordine.
 * Warning: una nuova regola richiede l'aggiornamento di sp_write(). */
typedef enum { SP_INPUT, SP_RESOLVE, SP_REFLEX, SP_FACTOR, SP_SUPER, SP_EQUAL_FACTOR,
               SP_COMPONENT, SP_COMPLEMENT, SP_SPLIT, SP_COMPREHEND } SpRule;

/* Un gruppo dello split: component identifica la chiusura universale,
 * negative il complemento ground. literal ha count indici nel genitore;
 * dopo sp_keep e posseduto dall'arena persistente della deduzione. */
typedef struct { int component, negative, count; const int *literal; } SpGroup;

/* Dati sufficienti a ricontrollare una deduzione. p/q e lp/lq identificano
 * genitori e letterali; flip/otherflip scelgono i versi delle uguaglianze;
 * side/position individuano il sotto-termine in visita preorder. binding
 * ha bindings immagini simultanee, possedute dall'arena della clausola.
 * groups/group descrivono soltanto SPLIT; per le due definizioni p e
 * invece l'indice della componente e non un genitore. Per COMPREHEND p
 * identifica l'istanza, senza genitori fra le clausole della ricerca. */
typedef struct {
    SpRule rule;
    int p, lp, q, lq, flip, otherflip, side, position;
    int bindings;
    const SpBinding *binding;
    int groups;
    const SpGroup *group;
} SpStep;

/* Stato di una clausola nella ricerca. Cancellarla dalla ricerca conserva
 * la deduzione nel deposito, perche puo essere genitore di una prova.
 * HELD sospende un'ipotesi di SInE, LOCKED una clausola le cui guardie
 * non sono attive nel modello SAT. BOOLEAN e affidata alla ricerca SAT. */
typedef enum { SP_PENDING, SP_ACTIVE, SP_DELETED, SP_HELD, SP_LOCKED, SP_BOOLEAN } SpStage;

/* Indice sparso di SInE, posseduto dall'arena persistente della ricerca.
 * first[i..i+1] delimita in symbol i simboli originali distinti della
 * clausola iniziale i; reverse[j..j+1] delimita in clause le clausole che
 * contengono il simbolo j. frequency conta clausole, non occorrenze di un
 * termine; minimum[i] e la frequenza minima nei simboli della clausola,
 * zero se non ne ha. Entrambi gli indici occupano spazio lineare nei dati. */
typedef struct {
    size_t *first, *reverse, *frequency, *minimum;
    int *symbol, *clause;
} SpSine;

/* Una clausola immutabile quanto a letterali e deduzione. count e il numero
 * di letterali, variables quello dei nomi normalizzati; literal e posseduto
 * dall'arena. signature filtra solo confronti impossibili di sussunzione,
 * weight ordina la coda. stage e l'unico campo modificato dalla ricerca. */
typedef struct {
    int count, variables;
    const SpLiteral *literal;
    SpStep step;
    SpStage stage;
    unsigned long long signature, weight;
} SpClause;

/* Una componente universalmente chiusa e il suo nome proposizionale.
 * key possiede letterali nell'arena persistente; symbol e fresco e senza
 * argomenti, atom il riferimento al suo termine condiviso (zero durante
 * una costruzione interrotta). forward/reverse sono clausole di definizione, -1 se una quota
 * ne ha interrotto la costruzione. value conserva il modello SAT fra due
 * chiamate CDCL: non dipende dalle assegnazioni temporanee del risolutore. */
typedef struct { SpClause key; int symbol, atom, forward, reverse, value; } SpComponent;

/* Una parte definita nel contesto di lettura: literal ha il solo parametro
 * v0 e definisce {x in sort | literal(x)}. left=0 indica un posto non legato
 * a una comprensione. I termini sono condivisi nel deposito della ricerca. */
typedef struct { SpLiteral literal; int sort; } SpProperty;

/* Una formula con quantificatore su parti, rinviata fino alle istanze.
 * source appartiene all'albero del parser; name e il suo nome nella NNF,
 * positive la polarita e every l'ammissibilita delle istanze universali.
 * binding ha slot_count celle, property declared_symbols celle; universals
 * ha universal parametri. Le copie appartengono all'arena persistente. */
typedef struct {
    const Sentence *source;
    SpLiteral name;
    int positive, every, universal;
    const int *binding, *universals;
    const SpProperty *property;
} SpSchema;

/* Un'istanza universale eseguita nella ricerca: schema identifica la
 * formula, property la comprensione canonica. first..past delimita tutte
 * le clausole ricostruite da quel comando nel certificato, incluse quelle
 * ridondanti. complete distingue il comando intero da un prefisso terminale;
 * symbol_first..symbol_past delimita i simboli freschi introdotti dal corpo.
 * Il deposito della ricerca possiede la voce e i suoi termini. */
typedef struct {
    int schema, first, past, complete;
    int symbol_first, symbol_past;
    SpLiteral property;
} SpExpansion;

/* Un comando che introduce simboli dopo la clausificazione iniziale.
 * kind e COMPONENT o COMPREHEND; index individua la voce corrispondente.
 * L'ordine posseduto dal vettore e quello della firma del certificato. */
typedef struct { SpRule kind; int index; } SpIntroduction;

/* Una coppia di termini ancora da unificare o confrontare. Gli elementi
 * della pila sono valori: una crescita non lascia puntatori pendenti. */
typedef struct { int a, b; } SpPair;

/* Un bilancio delle occorrenze per la condizione sulle variabili di KBO:
 * variable e un nome, balance e occorrenze nel primo meno nel secondo. */
typedef struct { int variable; long long balance; } SpBalance;

/* Stato posseduto da una ricerca. I suffissi _cap sono capacita sullo heap;
 * i contatori delimitano le celle valide. term/argument/hash condividono i
 * termini, symbol i simboli, clause le deduzioni; heap sceglie il peso e
 * age scorre gli indici per eta. input_symbol/original_symbol traducono i
 * simboli del parser nell'ordine dell'intestazione e viceversa; inputs conta
 * le dichiarazioni effettivamente emesse. binding e universals servono al parsing
 * dell'albero, non a interpretare un modello finito.
 * variables numera gli universali introdotti, universal conta quelli attivi;
 * initial delimita le clausole iniziali, empty e il posto del vuoto o -1.
 * unsupported segnala un nodo fuori dal primo ordine. rounds conta le scelte.
 *
 * sub e la sostituzione dell'unificazione; match e quella del confronto a
 * senso unico. todo/occurs sono pile iterative, trail permette di tornare
 * indietro nella sussunzione. path/path_count descrivono il cammino al punto
 * di superposizione. sub_count/match_count delimitano le mappe; trails,
 * todos, occurrences e balances contano le rispettive celle valide.
 * balance serve solo a KBO. storage possiede
 * clausole e certificati, scratch i temporanei riusati. bytes/work contano
 * memoria reale e visite; limited significa soltanto ricerca incompleta. */
typedef struct {
    int terms, args, symbols, clauses, variables, universal, heap_count, age;
    int initial, empty, limited, unsupported, inputs;
    unsigned long long work, rounds;
    size_t bytes;
    SpTerm *term;
    int *argument, *hash, *binding, *universals, *heap;
    int *input_symbol, *original_symbol;
    SpSymbol *symbol;
    SpClause *clause;
    int *sub, *match, *trail, *occurs, *path;
    int path_count;
    SpPair *todo;
    SpBalance *balance;
    size_t term_cap, argument_cap, hash_cap, binding_cap, universal_cap, heap_cap;
    size_t input_cap, original_cap;
    size_t symbol_cap, clause_cap, sub_cap, match_cap, trail_cap, occurs_cap, todo_cap, balance_cap, path_cap;
    int sub_count, match_count, trails, todos, occurrences, balances;
    SpSine sine;                 /* incidenze immutabili delle clausole iniziali */
    unsigned long long quota;    /* fine della quota di lavoro, zero per il budget globale */
    clock_t started, cpu_quota;  /* inizio e durata massima CPU del tentativo; zero senza timer */
    int resumable;              /* limited dipende dalla quota locale, non da memoria o budget globale */
    unsigned age_interval;      /* una scelta per eta ogni age_interval turni; zero mantiene cinque */
    int strategy;               /* zero diretto, 1/2 SInE, 3 AVATAR, 4 tutte le ipotesi */
    SpComponent *component;     /* componenti possedute, identificate anche nei simboli */
    int components;
    size_t component_cap;
    SatState sat;              /* SAT delle componenti, con budget condivisi */
    int avatar;                /* abilita la gestione dei rami SAT in questo tentativo */
    int avatar_dirty;          /* nuove componenti o clausole booleane richiedono un nuovo modello */
    int split_cursor, sat_cursor;/* primi indici di clausole ancora da suddividere o inviare al SAT */
    int replaying;             /* conserva i passi RUP senza euristiche o reinvio al SAT */
    unsigned sat_models;       /* modelli SAT effettivamente controllati, per la diagnostica */
    int *sat_proof;            /* clausola FO piu uno per ciascuna clausola SAT; zero richiede replay */
    size_t sat_proof_cap;
    signed char *rup_value;    /* assegnazioni temporanee del replay, indicizzate per componente */
    int *rup_reason, *rup_trail;/* ragioni FO piu uno e ordine delle propagazioni; zero e un'assunzione */
    size_t rup_value_cap, rup_reason_cap, rup_trail_cap;
    SpProperty *property;       /* parti definite, indicizzate per simbolo originale del parser */
    size_t property_cap;
    SpSchema *schema;           /* formule quantificate astratte, possedute dalla ricerca */
    SpExpansion *expansion;     /* gruppi di clausole delle istanze, in ordine cronologico */
    int schemas, expansions;
    size_t schema_cap, expansion_cap;
    SpIntroduction *introduction;/* ordine comune dei nomi SAT e delle istanze */
    int introductions;
    size_t introduction_cap;
    int comprehension;          /* abilita le istanze nei tentativi AVATAR e ordinario finale */
    int forward;                /* clausificazione direzionale in forma normale negativa */
    int emitting;               /* espansione piu uno durante la sua clausificazione, zero altrimenti */
    int seed_schema;            /* prossima formula a cui proporre le parti vuota e intera */
    int eliminate_expansion;    /* prossima istanza da semplificare per eliminazione booleana */
    int eliminate_symbol;       /* prossimo simbolo nell'intervallo dell'istanza corrente */
    int *unit;                  /* clausole unitarie disponibili, anche universalmente quantificate */
    int units, unit_cursor;     /* numero di unitarie e prossimo indice da semplificare */
    size_t unit_cap;
    SpArena storage, scratch;
} SpState;

/* Byte ancora disponibili a entrambi i motori. La sottrazione separata
 * evita overflow anche quando un limite viene ridotto fra due tentativi. */
static size_t sp_memory_left(const SpState *s) {
    if (s->bytes > saturation_memory_limit || s->sat.bytes > saturation_memory_limit - s->bytes) return 0;
    return saturation_memory_limit - s->bytes - s->sat.bytes;
}

/* Registra lavoro effettivo prima di visitare un nodo o tentare un passo.
 * Le quote locali interrompono con le stesse cautele di quelle globali,
 * ma il portafoglio puo riprendere lo stato. Il tempo CPU guida soltanto
 * la ricerca: non decide alcuna proposizione matematica. */
static int sp_visit(SpState *s) {
    if (s->limited || s->unsupported) return 0;
    if (s->work >= saturation_work_limit) { s->limited = 1; return 0; }
    if (s->quota && s->work >= s->quota) { s->limited = s->resumable = 1; return 0; }
    if (s->cpu_quota && s->work % 1024 == 0) {
        clock_t current = clock();
        if (s->started != (clock_t)-1 && current != (clock_t)-1 && current >= s->started && current - s->started >= s->cpu_quota) {
            s->limited = s->resumable = 1; return 0;
        }
    }
    s->work++;
    return 1;
}

/* Cresce un deposito, senza perdere i vecchi dati e contabilizzando i byte
 * effettivamente allocati. Non usa il fallimento globale delle altre
 * strategie: una ricerca interrotta puo lasciare spazio a un'altra. */
static int sp_reserve(SpState *s, void **data, size_t *capacity, size_t need, size_t unit) {
    if (s->limited || s->unsupported) return 0;
    if (need <= *capacity) return 1;
    size_t count = *capacity ? *capacity : 16;
    while (count < need) {
        if (count > (size_t)-1 / 2) { count = need; break; }
        count *= 2;
    }
    if (count > (size_t)-1 / unit || (count - *capacity) * unit > sp_memory_left(s)) { s->limited = 1; return 0; }
    void *next = realloc(*data, count * unit);
    if (!next) { s->limited = 1; return 0; }
    memset((unsigned char *)next + *capacity * unit, 0, (count - *capacity) * unit);
    s->bytes += (count - *capacity) * unit;
    *data = next; *capacity = count;
    return 1;
}

/* Prende memoria stabile, allineata, da un'arena della ricerca. Il budget
 * comprende i blocchi interi e i loro metadati, anche se non ancora pieni. */
static void *sp_allocate(SpState *s, SpArena *a, size_t count, size_t unit) {
    if (!count || s->limited || s->unsupported) return NULL;
    if (count > ((size_t)-1 - 15) / unit) { s->limited = 1; return NULL; }
    size_t need = (count * unit + 15) & ~(size_t)15;
    SpBlock *b = a->current;
    while (b && need > b->capacity - b->used) b = b->next;
    if (!b) {
        size_t capacity = need > 16384 ? need : 16384;
        if (capacity > (size_t)-1 - sizeof *b || sizeof *b + capacity > sp_memory_left(s)) { s->limited = 1; return NULL; }
        b = malloc(sizeof *b + capacity);
        if (!b) { s->limited = 1; return NULL; }
        *b = (SpBlock){.capacity=capacity};
        if (!a->first) a->first = b;
        else {
            SpBlock *last = a->current ? a->current : a->first;
            while (last->next) last = last->next;
            last->next = b;
        }
        s->bytes += sizeof *b + capacity;
    }
    a->current = b;
    void *data = b->data + b->used; b->used += need;
    return data;
}

/* Ricomincia i temporanei tra due inferenze. Nessun termine o clausola
 * conservato puo possedere un puntatore a quest'arena. */
static void sp_scratch_reset(SpState *s) {
    for (SpBlock *b = s->scratch.first; b; b = b->next) b->used = 0;
    s->scratch.current = s->scratch.first;
}

/* Libera tutto lo stato, anche dopo un'allocazione incompleta. */
static void sp_clear(SpState *s) {
    free(s->term); free(s->argument); free(s->hash); free(s->binding); free(s->universals);
    free(s->input_symbol); free(s->original_symbol);
    free(s->heap); free(s->symbol); free(s->clause); free(s->sub); free(s->match);
    free(s->trail); free(s->occurs); free(s->todo); free(s->balance); free(s->path);
    free(s->component); free(s->sat_proof); free(s->rup_value); free(s->rup_reason); free(s->rup_trail);
    free(s->property); free(s->schema); free(s->expansion);
    free(s->introduction);
    free(s->unit);
    sat_clear(&s->sat);
    SpArena *arenas[2] = {&s->storage, &s->scratch};
    for (int i = 0; i < 2; i++) for (SpBlock *b = arenas[i]->first; b;) {
        SpBlock *next = b->next; free(b); b = next;
    }
    memset(s, 0, sizeof *s);
}

/* Introduce un simbolo nel medesimo ordine dichiarativo del protocollo. */
static int sp_symbol(SpState *s, int arity, int predicate) {
    if (s->symbols == INT_MAX || !sp_reserve(s, (void **)&s->symbol, &s->symbol_cap, (size_t)s->symbols + 1, sizeof *s->symbol)) {
        s->limited = 1; return 0;
    }
    int id = s->symbols++;
    s->symbol[id] = (SpSymbol){.arity=arity, .predicate=predicate};
    return id;
}

/* Hash dei figli gia condivisi. Una collisione richiede comunque il
 * confronto esatto del simbolo e dell'intero vettore degli argomenti. */
static unsigned long long sp_term_hash(int symbol, const int *args, int count) {
    unsigned long long h = 1469598103934665603ULL ^ (unsigned)symbol;
    for (int i = 0; i < count; i++) h = (h ^ (unsigned)args[i]) * 1099511628211ULL;
    return h;
}

/* Peso di un riferimento: le variabili pesano uno, zero non e un termine. */
static unsigned long long sp_term_weight(const SpState *s, int t) {
    return t < 0 ? 1 : t ? s->term[t].weight : 0;
}

/* Condivide una costruzione finita. Il vettore input non deve puntare
 * dentro argument, che puo spostarsi; i chiamanti usano frame o scratch. */
static int sp_term(SpState *s, int symbol, const int *args) {
    if (!sp_visit(s)) return 0;
    int count = s->symbol[symbol].arity;
    if (!s->hash_cap || (size_t)s->terms + 1 >= s->hash_cap / 2) {
        size_t old = s->hash_cap;
        if (old > (size_t)-1 / 2 || !sp_reserve(s, (void **)&s->hash, &s->hash_cap, old ? 2 * old : 32, sizeof *s->hash)) {
            s->limited = 1; return 0;
        }
        memset(s->hash, 0, s->hash_cap * sizeof *s->hash);
        for (int id = 1; id <= s->terms; id++) {
            SpTerm t = s->term[id];
            size_t k = sp_term_hash(t.symbol, t.count ? s->argument + t.first : NULL, t.count) % s->hash_cap;
            while (s->hash[k]) k = (k + 1) % s->hash_cap;
            s->hash[k] = id;
        }
    }
    size_t h = sp_term_hash(symbol, args, count) % s->hash_cap;
    for (; s->hash[h]; h = (h + 1) % s->hash_cap) {
        if (!sp_visit(s)) return 0;
        int id = s->hash[h]; SpTerm t = s->term[id];
        if (t.symbol == symbol && (!count || memcmp(s->argument + t.first, args, (size_t)count * sizeof *args) == 0)) return id;
    }
    if (s->terms == INT_MAX || count > INT_MAX - s->args) { s->limited = 1; return 0; }
    if (!sp_reserve(s, (void **)&s->term, &s->term_cap, (size_t)s->terms + 2, sizeof *s->term) ||
        !sp_reserve(s, (void **)&s->argument, &s->argument_cap, (size_t)s->args + (size_t)count, sizeof *s->argument)) return 0;
    unsigned long long weight = 1;
    for (int i = 0; i < count; i++) {
        unsigned long long w = sp_term_weight(s, args[i]);
        if (w > ULLONG_MAX - weight) { s->limited = 1; return 0; }
        weight += w;
    }
    int id = ++s->terms;
    s->term[id] = (SpTerm){symbol, s->args, count, weight};
    if (count) memcpy(s->argument + s->args, args, (size_t)count * sizeof *args);
    s->args += count; s->hash[h] = id;
    return id;
}

/* Segue le sostituzioni dell'unificazione, che l'occurs-check tiene acicliche. */
static int sp_deref(const SpState *s, int t) {
    while (t < 0 && -1 - t < s->sub_count && s->sub[-1 - t]) t = s->sub[-1 - t];
    return t;
}

/* Aggiunge un confronto alla pila iterativa condivisa dalle operazioni di
 * unificazione e matching; il chiamante azzera todos prima di usarla. */
static int sp_pair_push(SpState *s, int a, int b) {
    if (s->todos == INT_MAX || !sp_reserve(s, (void **)&s->todo, &s->todo_cap, (size_t)s->todos + 1, sizeof *s->todo)) {
        s->limited = 1; return 0;
    }
    s->todo[s->todos++] = (SpPair){a, b};
    return 1;
}

/* Cerca una variabile in un termine dereferenziato, senza usare la pila C.
 * Se x compare in t, x=t richiederebbe un termine infinito e va rifiutata. */
static int sp_occurs(SpState *s, int variable, int term) {
    s->occurrences = 0;
    if (!sp_reserve(s, (void **)&s->occurs, &s->occurs_cap, 1, sizeof *s->occurs)) return 1;
    s->occurs[s->occurrences++] = term;
    while (s->occurrences && sp_visit(s)) {
        int t = sp_deref(s, s->occurs[--s->occurrences]);
        if (t == variable) return 1;
        if (t <= 0) continue;
        SpTerm n = s->term[t];
        if (n.count > INT_MAX - s->occurrences ||
            !sp_reserve(s, (void **)&s->occurs, &s->occurs_cap, (size_t)s->occurrences + (size_t)n.count, sizeof *s->occurs)) {
            s->limited = 1; return 1;
        }
        for (int i = 0; i < n.count; i++) s->occurs[s->occurrences++] = s->argument[n.first + i];
    }
    return s->limited;
}

/* Unificazione di Robinson con occurs-check. Il contesto sub gia presente
 * si estende; un fallimento lo lascia sporco, e il chiamante lo reinizializza
 * prima di un altro tentativo. Nessuna equazione sui reali entra qui. */
static int sp_unify(SpState *s, int left, int right) {
    s->todos = 0;
    sp_pair_push(s, left, right);
    while (s->todos && sp_visit(s)) {
        SpPair pair = s->todo[--s->todos];
        int a = sp_deref(s, pair.a), b = sp_deref(s, pair.b);
        if (a == b) continue;
        if (a < 0 || b < 0) {
            if (a >= 0) { int t = a; a = b; b = t; }
            if (-1 - a >= s->sub_count || sp_occurs(s, a, b)) return 0;
            s->sub[-1 - a] = b;
        } else {
            if (!a || !b || s->term[a].symbol != s->term[b].symbol) return 0;
            SpTerm x = s->term[a], y = s->term[b];
            for (int i = 0; i < x.count; i++) sp_pair_push(s, s->argument[x.first + i], s->argument[y.first + i]);
        }
    }
    return !s->limited && !s->unsupported;
}

/* Inizia un'unificazione con i nomi dei due genitori gia separati. */
static int sp_unify_start(SpState *s, int count) {
    s->sub_count = count;
    if (!sp_reserve(s, (void **)&s->sub, &s->sub_cap, (size_t)count, sizeof *s->sub)) return 0;
    if (count) memset(s->sub, 0, (size_t)count * sizeof *s->sub);
    return 1;
}

/* Applica una sostituzione risolta ai termini del genitore traslato di
 * offset. Gli zeri della mappa lasciano i nomi liberi; le immagini di sub
 * sono dereferenziate ricorsivamente solo quando recursive vale uno. */
static int sp_apply(SpState *s, int t, int offset, const int *sub, int count, int recursive) {
    if (!t || !sp_visit(s)) return 0;
    if (t < 0) {
        long long v = -1LL - t + offset;
        if (v >= INT_MAX) { s->limited = 1; return 0; }
        if (v < count && sub[v]) return recursive ? sp_apply(s, sub[v], 0, sub, count, 1) : sub[v];
        return -(int)v - 1;
    }
    SpTerm n = s->term[t];
    int *args = sp_allocate(s, &s->scratch, (size_t)n.count, sizeof *args);
    if (n.count && !args) return 0;
    for (int i = 0; i < n.count; i++) args[i] = sp_apply(s, s->argument[n.first + i], offset, sub, count, recursive);
    return sp_term(s, n.symbol, args);
}

/* Confronto a senso unico: solo le variabili dello schema possono cambiare.
 * I nomi del termine bersaglio sono traslati e quindi non possono essere
 * scambiati con quelli dello schema. trail conserva i nuovi legami. */
static int sp_match(SpState *s, int pattern, int target) {
    s->todos = 0;
    sp_pair_push(s, pattern, target);
    while (s->todos && sp_visit(s)) {
        SpPair p = s->todo[--s->todos];
        if (p.a == p.b) continue;
        if (p.a < 0) {
            int v = -p.a - 1;
            if (v >= s->match_count) return 0;
            if (s->match[v]) { if (s->match[v] != p.b) return 0; }
            else {
                if (!sp_reserve(s, (void **)&s->trail, &s->trail_cap, (size_t)s->trails + 1, sizeof *s->trail)) return 0;
                s->match[v] = p.b; s->trail[s->trails++] = v;
            }
        } else {
            if (!p.a || p.b <= 0 || s->term[p.a].symbol != s->term[p.b].symbol) return 0;
            SpTerm a = s->term[p.a], b = s->term[p.b];
            for (int i = 0; i < a.count; i++) sp_pair_push(s, s->argument[a.first + i], s->argument[b.first + i]);
        }
    }
    return !s->limited;
}

/* Ricomincia un confronto di schemi, oppure torna al punto segnato prima
 * di provare un diverso abbinamento di letterali. */
static int sp_match_start(SpState *s, int count) {
    s->match_count = count; s->trails = 0;
    if (!sp_reserve(s, (void **)&s->match, &s->match_cap, (size_t)count, sizeof *s->match)) return 0;
    if (count) memset(s->match, 0, (size_t)count * sizeof *s->match);
    return 1;
}

/* Cancella soltanto i legami aggiunti dopo mark. */
static void sp_match_back(SpState *s, int mark) {
    while (s->trails > mark) s->match[s->trail[--s->trails]] = 0;
}

/* Accumula il multinsieme delle variabili di t col segno dato. La visita
 * conta occorrenze, non soli nodi del DAG: f(x,x) contiene x due volte. */
static void sp_balance(SpState *s, int t, int sign) {
    if (!t || !sp_visit(s)) return;
    if (t < 0) {
        int i = 0;
        while (i < s->balances && s->balance[i].variable != t) i++;
        if (i == s->balances) {
            if (!sp_reserve(s, (void **)&s->balance, &s->balance_cap, (size_t)i + 1, sizeof *s->balance)) return;
            s->balance[s->balances++] = (SpBalance){t, 0};
        }
        if ((sign > 0 && s->balance[i].balance == LLONG_MAX) ||
            (sign < 0 && s->balance[i].balance == LLONG_MIN)) { s->limited = 1; return; }
        s->balance[i].balance += sign;
        return;
    }
    SpTerm n = s->term[t];
    for (int i = 0; i < n.count; i++) sp_balance(s, s->argument[n.first + i], sign);
}

/* KBO stretto, con peso uno per ogni simbolo e variabile e precedenza
 * crescente dei simboli. Prima si impone occ_s(x)>=occ_t(x) per ogni x;
 * poi decide il peso, a parita la precedenza o il primo figlio diverso.
 * I pesi positivi e la condizione sulle variabili rendono l'ordine ben
 * fondato e stabile per sostituzioni: riscrivere nel verso maggiore->minore
 * non puo creare un ciclo. Termini aperti possono restare incomparabili. */
static int sp_greater(SpState *s, int a, int b) {
    if (a == b || !a || !b || !sp_visit(s)) return 0;
    s->balances = 0; sp_balance(s, a, 1); sp_balance(s, b, -1);
    for (int i = 0; i < s->balances; i++) if (s->balance[i].balance < 0) return 0;
    unsigned long long x = sp_term_weight(s, a), y = sp_term_weight(s, b);
    if (x != y) return x > y;
    if (a < 0 || b < 0) return 0;
    SpTerm u = s->term[a], v = s->term[b];
    if (u.symbol != v.symbol) return u.symbol > v.symbol;
    for (int i = 0; i < u.count; i++) {
        int l = s->argument[u.first + i], r = s->argument[v.first + i];
        if (l != r) return sp_greater(s, l, r);
    }
    return 0;
}

/* Mappa temporanea della normalizzazione: old e il riferimento negativo
 * originale, fresh quello assegnato per prima occorrenza. Le celle sono
 * nello scratch e nessuna clausola conservata ne possiede il puntatore. */
typedef struct { int old, fresh; } SpName;

/* Un contesto di rinomina, condiviso solo dalla ricorsione corrente.
 * count/capacity delimitano i nomi, name puo cambiare indirizzo crescendo. */
typedef struct { int count; size_t capacity; SpName *name; } SpNames;

/* Rinomina le variabili per prima occorrenza, condividendo nuovamente i
 * termini costruiti. Non usa il valore numerico dei nomi come capacita. */
static int sp_rename(SpState *s, int t, SpNames *names) {
    if (!t || !sp_visit(s)) return 0;
    if (t < 0) {
        for (int i = 0; i < names->count; i++) if (names->name[i].old == t) return names->name[i].fresh;
        if ((size_t)names->count == names->capacity) {
            size_t cap = names->capacity ? 2 * names->capacity : 16;
            SpName *next = sp_allocate(s, &s->scratch, cap, sizeof *next);
            if (!next) return 0;
            if (names->count) memcpy(next, names->name, (size_t)names->count * sizeof *next);
            names->name = next; names->capacity = cap;
        }
        if (names->count == INT_MAX) { s->limited = 1; return 0; }
        int fresh = -1 - names->count;
        names->name[names->count++] = (SpName){t, fresh};
        return fresh;
    }
    SpTerm n = s->term[t];
    int *args = sp_allocate(s, &s->scratch, (size_t)n.count, sizeof *args);
    if (n.count && !args) return 0;
    for (int i = 0; i < n.count; i++) args[i] = sp_rename(s, s->argument[n.first + i], names);
    return sp_term(s, n.symbol, args);
}

/* Stesso atomo, ammettendo la simmetria dell'uguaglianza. Il segno viene
 * confrontato dal chiamante, cosi si riconoscono anche i complementari. */
static int sp_same_atom(SpLiteral a, SpLiteral b) {
    return (a.left == b.left && a.right == b.right) ||
           (a.right && b.right && a.left == b.right && a.right == b.left);
}

/* Copia e normalizza: falso si elimina, i duplicati identici si contraggono.
 * L'ordine dei letterali e il verso delle uguaglianze restano quelli della
 * regola, perche sono dati del certificato. La firma usa solo simboli che
 * una sostituzione non puo cambiare, quindi non scarta una sussunzione vera. */
static SpClause sp_normal(SpState *s, const SpLiteral *literal, int count) {
    SpClause c = {0}; SpNames names = {0};
    SpLiteral *out = sp_allocate(s, &s->scratch, (size_t)count, sizeof *out);
    if (count && !out) return c;
    for (int i = 0; i < count && sp_visit(s); i++) {
        SpLiteral l = literal[i];
        if (!l.left && l.negative) continue;
        l.left = sp_rename(s, l.left, &names); l.right = sp_rename(s, l.right, &names);
        /* Una quota puo fermare soltanto il secondo membro di t=t:
         * quel prefisso non e un predicato e non va indicizzato come tale. */
        if (s->limited || s->unsupported) break;
        int repeated = 0;
        for (int j = 0; j < c.count; j++)
            repeated |= out[j].left == l.left && out[j].right == l.right && out[j].negative == l.negative;
        if (repeated) continue;
        out[c.count++] = l;
        unsigned key = !l.left ? 0 : l.right ? 2u + (unsigned)l.negative
                       : 4u + 2u * (unsigned)s->term[l.left].symbol + (unsigned)l.negative;
        c.signature |= 1ULL << (key % 64);
        unsigned long long weight = sp_term_weight(s, l.left), right = sp_term_weight(s, l.right);
        if (right > ULLONG_MAX - weight) { s->limited = 1; return c; }
        weight += right;
        if (weight == ULLONG_MAX || weight + 1 > ULLONG_MAX - c.weight) { s->limited = 1; return c; }
        c.weight += weight + 1;
    }
    c.literal = out; c.variables = names.count;
    return c;
}

/* Una tautologia e vera per ogni interpretazione: vero, t=t, oppure due
 * atomi identici con segni opposti. Non basta che siano unificabili. */
static int sp_tautology(const SpClause *c) {
    for (int i = 0; i < c->count; i++) {
        SpLiteral l = c->literal[i];
        if ((!l.left || (l.right && l.left == l.right)) && !l.negative) return 1;
        for (int j = 0; j < i; j++)
            if (l.negative != c->literal[j].negative && sp_same_atom(l, c->literal[j])) return 1;
    }
    return 0;
}

/* Trasla e istanzia i letterali di una clausola, senza modificarla. Le
 * immagini devono gia essere simultanee, come quelle scritte al checker. */
static SpLiteral *sp_instance(SpState *s, SpClause c, int offset, const int *sub, int count, int recursive) {
    SpLiteral *literal = sp_allocate(s, &s->scratch, (size_t)c.count, sizeof *literal);
    if (c.count && !literal) return NULL;
    for (int i = 0; i < c.count; i++) {
        literal[i] = c.literal[i];
        literal[i].left = sp_apply(s, literal[i].left, offset, sub, count, recursive);
        literal[i].right = sp_apply(s, literal[i].right, offset, sub, count, recursive);
    }
    return literal;
}

/* Un livello del confronto fra clausole: choice e il prossimo letterale e
 * verso da provare, mark delimita i legami presenti prima di quel livello. */
typedef struct { size_t choice; int mark; } SpMatchFrame;

/* C sussume D se esiste una sostituzione theta con C theta contenuta in D.
 * I nomi di D restano fissi e distinti da quelli di C. Un successo rende D
 * ridondante: ogni interpretazione che soddisfa C soddisfa anche D. Il
 * backtracking e iterativo e il budget conta ogni abbinamento tentato. */
static int sp_subsumes(SpState *s, SpClause c, SpClause d) {
    if (c.signature & ~d.signature) return 0;
    if (!c.count) return 1;
    if (!d.count || !sp_match_start(s, c.variables)) return 0;
    int offset = c.variables > 64 ? c.variables : 64;
    SpLiteral *target = sp_instance(s, d, offset, NULL, 0, 0);
    SpMatchFrame *frame = sp_allocate(s, &s->scratch, (size_t)c.count, sizeof *frame);
    if (!target || !frame) return 0;
    int level = 0; frame[0] = (SpMatchFrame){0};
    while (level >= 0 && sp_visit(s)) {
        SpMatchFrame *f = &frame[level];
        sp_match_back(s, f->mark);
        if (f->choice == 2 * (size_t)d.count) { level--; continue; }
        size_t choice = f->choice++;
        SpLiteral a = c.literal[level], b = target[choice / 2];
        int flip = (int)(choice % 2);
        if (a.negative != b.negative || !!a.right != !!b.right || (flip && !a.right)) continue;
        int x = flip ? b.right : b.left, y = flip ? b.left : b.right;
        if (!sp_match(s, a.left, x) || (a.right && !sp_match(s, a.right, y))) continue;
        if (++level == c.count) return 1;
        frame[level] = (SpMatchFrame){.mark=s->trails};
    }
    return 0;
}

/* Ordine della coda per peso, con eta come spareggio deterministico. */
static int sp_before(const SpState *s, int a, int b) {
    return s->clause[a].weight < s->clause[b].weight ||
           (s->clause[a].weight == s->clause[b].weight && a < b);
}

/* Aggiunge una clausola alla coda a priorita. Le voci cancellate vengono
 * scartate quando arrivano in testa, senza spostare le altre clausole. */
static void sp_enqueue(SpState *s, int id) {
    if (!sp_reserve(s, (void **)&s->heap, &s->heap_cap, (size_t)s->heap_count + 1, sizeof *s->heap)) return;
    size_t at = (size_t)s->heap_count++;
    while (at && sp_before(s, id, s->heap[(at - 1) / 2])) {
        s->heap[at] = s->heap[(at - 1) / 2]; at = (at - 1) / 2;
    }
    s->heap[at] = id;
}

/* Toglie il minimo dall'heap, anche se gia elaborato per eta o cancellato. */
static int sp_pop(SpState *s) {
    if (!s->heap_count) return -1;
    int result = s->heap[0], last = s->heap[--s->heap_count];
    size_t at = 0, count = (size_t)s->heap_count;
    while (2 * at + 1 < count) {
        size_t child = 2 * at + 1;
        if (child + 1 < count && sp_before(s, s->heap[child + 1], s->heap[child])) child++;
        if (!sp_before(s, s->heap[child], last)) break;
        s->heap[at] = s->heap[child]; at = child;
    }
    if (count) s->heap[at] = last;
    return result;
}

/* Una scelta per eta ogni age_interval turni, cinque di default. Con
 * risorse illimitate ogni clausola persistente viene prima o poi scelta. */
static int sp_select(SpState *s) {
    unsigned interval = s->age_interval ? s->age_interval : 5;
    if (s->rounds++ % interval == interval - 1) {
        while (s->age < s->clauses && s->clause[s->age].stage != SP_PENDING && sp_visit(s)) s->age++;
        if (s->age < s->clauses) return s->age++;
    }
    for (int id; (id = sp_pop(s)) >= 0 && sp_visit(s);)
        if (s->clause[id].stage == SP_PENDING) return id;
    return -1;
}

/* Restituisce componente piu uno per una guardia, zero per un letterale
 * ordinario. Il ruolo resta esplicito anche fra simboli di nuove istanze. */
static int sp_guard(const SpState *s, SpLiteral l) {
    if (l.right || l.left <= 0) return 0;
    int symbol = s->term[l.left].symbol;
    return s->symbol[symbol].component;
}

/* Le guardie sono disgiunti della clausola completa: la parte FO e
 * richiesta soltanto quando tutte sono false. Le clausole solo booleane
 * vanno al SAT, anche se il modello corrente gia le soddisfa. */
static SpStage sp_available(const SpState *s, SpClause c) {
    if (!s->avatar || !c.count) return SP_PENDING;
    int ordinary = 0, active = 1;
    for (int i = 0; i < c.count; i++) {
        int guard = sp_guard(s, c.literal[i]);
        if (!guard) ordinary = 1;
        else if (s->component[guard - 1].value * (c.literal[i].negative ? -1 : 1) >= 0) active = 0;
    }
    return !ordinary ? SP_BOOLEAN : active ? SP_PENDING : SP_LOCKED;
}

/* Salva una clausola e, se derivata, la sua sostituzione. I temporanei sono
 * copiati prima di tornare al chiamante. Le clausole iniziali conservano
 * sempre il proprio indice, comprese quelle ridondanti; il checker le
 * ricostruisce senza conoscere le euristiche della ricerca. replaced e il
 * bersaglio di una riscrittura, oppure -1: non puo sussumere la propria
 * sostituta per poi essere cancellato senza conservarne nessuna.
 * Le definizioni mantengono anch'esse un indice; il replay conserva ogni
 * risolvente. Gruppi, posizioni e sostituzioni vengono copiati nell'arena. */
static int sp_keep(SpState *s, const SpLiteral *literal, int count, SpStep step, int replaced) {
    SpClause c = sp_normal(s, literal, count);
    if (s->limited || s->unsupported) return -1;
    int trivial = sp_tautology(&c), retained = step.rule == SP_INPUT || step.rule == SP_COMPONENT || step.rule == SP_COMPLEMENT || step.rule == SP_COMPREHEND;
    if (!retained && trivial) return -1;
    if (!retained && !s->replaying) for (int i = 0; i < s->clauses && sp_visit(s); i++)
        if (i != replaced && s->clause[i].stage != SP_DELETED && s->clause[i].stage != SP_HELD &&
            s->clause[i].stage != SP_LOCKED && sp_subsumes(s, s->clause[i], c)) return -1;
    if (s->clauses == INT_MAX) { s->limited = 1; return -1; }
    if (!sp_reserve(s, (void **)&s->clause, &s->clause_cap, (size_t)s->clauses + 1, sizeof *s->clause)) return -1;
    SpLiteral *saved = sp_allocate(s, &s->storage, (size_t)c.count, sizeof *saved);
    SpBinding *bindings = sp_allocate(s, &s->storage, (size_t)step.bindings, sizeof *bindings);
    if ((c.count && !saved) || (step.bindings && !bindings) || s->limited) return -1;
    if (c.count) memcpy(saved, c.literal, (size_t)c.count * sizeof *saved);
    if (step.bindings) memcpy(bindings, step.binding, (size_t)step.bindings * sizeof *bindings);
    SpGroup *groups = sp_allocate(s, &s->storage, (size_t)step.groups, sizeof *groups);
    if (step.groups && !groups) return -1;
    for (int i = 0; i < step.groups; i++) {
        groups[i] = step.group[i];
        int *indices = sp_allocate(s, &s->storage, (size_t)groups[i].count, sizeof *indices);
        if (!indices) return -1;
        memcpy(indices, groups[i].literal, (size_t)groups[i].count * sizeof *indices);
        groups[i].literal = indices;
    }
    c.literal = saved; c.step = step; c.step.binding = bindings;
    c.step.group = groups;
    c.stage = trivial ? SP_DELETED : sp_available(s, c);
    int id = s->clauses++;
    s->clause[id] = c;
    if (!c.count) s->empty = id;
    if (c.stage == SP_PENDING) sp_enqueue(s, id);
    if (s->avatar && c.stage == SP_BOOLEAN && !s->replaying) s->avatar_dirty = 1;
    if (!retained && !s->replaying && c.count) for (int i = 0; i < id && sp_visit(s); i++)
        if (s->clause[i].stage != SP_DELETED && sp_subsumes(s, c, s->clause[i])) s->clause[i].stage = SP_DELETED;
    return s->limited ? -1 : id;
}

/* Scrive una delle clausole di Tseitin, di al piu tre letterali. */
static void sp_emit(SpState *s, SpLiteral a, SpLiteral b, SpLiteral c, int count) {
    SpLiteral literal[3] = {a, b, c};
    SpStep step = {.rule=s->emitting ? SP_COMPREHEND : SP_INPUT, .p=s->emitting ? s->emitting - 1 : 0};
    sp_keep(s, literal, count, step, -1);
}

/* Il complemento di un letterale conserva il suo atomo. */
static SpLiteral sp_not(SpLiteral l) { l.negative = !l.negative; return l; }

/* Raccoglie nomi distinti in un vettore sparso nello scratch. Anche indici
 * lontani non richiedono memoria per tutte le posizioni intermedie. */
static void sp_free_variables(SpState *s, int t, SpNames *names) {
    if (!t || !sp_visit(s)) return;
    if (t < 0) { sp_rename(s, t, names); return; }
    SpTerm n = s->term[t];
    for (int i = 0; i < n.count; i++) sp_free_variables(s, s->argument[n.first + i], names);
}

/* Ordine dei nomi liberi, indipendente dall'ordine in cui sono stati letti. */
static int sp_name_order(const void *a, const void *b) {
    int x = ((const SpName *)a)->old, y = ((const SpName *)b)->old;
    return (y > x) - (y < x);
}

/* La riflessivita rende t=t vero per ogni interpretazione. Ridurre questo
 * atomo prima di nominare una sottoformula evita nomi per costanti logiche. */
static SpLiteral sp_constant_literal(SpLiteral l) {
    return l.right && l.left == l.right ? (SpLiteral){0, 0, l.negative} : l;
}

/* Introduce q(vars) equivalente ad a AND b, oppure a OR b. Le tre
 * implicazioni garantiscono entrambi i versi, anche sotto una negazione.
 * Con forward basta q=>F: i nomi interni della NNF compaiono positivamente.
 * Ogni modello di F si estende assegnando q=F, mentre q vero impone F.
 * E la trasformazione di Plaisted e Greenbaum; i membri di comprensioni
 * usati sotto negazione mantengono invece entrambi i versi.
 * I parametri sono tutte e sole le variabili libere, in ordine crescente. */
static SpLiteral sp_connect(SpState *s, SpLiteral a, SpLiteral b, int conjunction) {
    if (s->forward) { a = sp_constant_literal(a); b = sp_constant_literal(b); }
    if (!a.left) return a.negative == conjunction ? a : b;
    if (!b.left) return b.negative == conjunction ? b : a;
    SpNames names = {0};
    sp_free_variables(s, a.left, &names); sp_free_variables(s, a.right, &names);
    sp_free_variables(s, b.left, &names); sp_free_variables(s, b.right, &names);
    if (names.count) qsort(names.name, (size_t)names.count, sizeof *names.name, sp_name_order);
    int *args = sp_allocate(s, &s->scratch, (size_t)names.count, sizeof *args);
    if (names.count && !args) return (SpLiteral){0};
    for (int i = 0; i < names.count; i++) args[i] = names.name[i].old;
    SpLiteral q = {sp_term(s, sp_symbol(s, names.count, 1), args), 0, 0};
    if (conjunction) {
        sp_emit(s, sp_not(q), a, a, 2); sp_emit(s, sp_not(q), b, b, 2);
        if (!s->forward) sp_emit(s, q, sp_not(a), sp_not(b), 3);
    } else {
        if (!s->forward) { sp_emit(s, q, sp_not(a), a, 2); sp_emit(s, q, sp_not(b), b, 2); }
        sp_emit(s, sp_not(q), a, b, 3);
    }
    return q;
}

/* Legge un termine dell'albero originale nell'ambiente dei quantificatori.
 * Gli elementi legati sono slot, non nomi testuali: non puo esserci cattura. */
static int sp_input_term(SpState *s, const Elem *e) {
    if (!sp_visit(s)) return 0;
    if (e->symbol < 0) {
        if (e->slot < 0 || e->slot >= slot_count || !s->binding[e->slot]) { s->unsupported = 1; return 0; }
        return s->binding[e->slot];
    }
    if (e->symbol >= declared_symbols || s->input_symbol[e->symbol] < 0) { s->unsupported = 1; return 0; }
    int args[2];
    for (int i = 0; i < symbols[e->symbol].arity; i++) args[i] = sp_input_term(s, e->arg[i]);
    return sp_term(s, s->input_symbol[e->symbol], args);
}

/* Sostituisce tutte le occorrenze strutturali di from con to. L'immagine
 * non viene attraversata: si usa sia per astrarre un termine ground in
 * v0, sia per applicare la proprieta a un argomento senza cattura. */
static int sp_replace_term(SpState *s, int term, int from, int to) {
    if (!term || !sp_visit(s)) return 0;
    if (term == from) return to;
    if (term < 0) return term;
    SpTerm n = s->term[term];
    int *args = sp_allocate(s, &s->scratch, (size_t)n.count, sizeof *args);
    if (n.count && !args) return 0;
    for (int i = 0; i < n.count; i++) args[i] = sp_replace_term(s, s->argument[n.first + i], from, to);
    return sp_term(s, n.symbol, args);
}

/* Rinomina una formula quantificata su parti conservandone l'ambiente.
 * Il nome denota la formula nella polarita della NNF. Lasciarlo inizialmente
 * libero indebolisce i vincoli; le istanze universali verranno aggiunte
 * durante la ricerca. Le parti non diventano elementi del dominio comune. */
static SpLiteral sp_schema(SpState *s, const Sentence *n, int positive) {
    SpLiteral none = {0, 0, 1};
    if (s->schemas == INT_MAX || !sp_reserve(s, (void **)&s->schema, &s->schema_cap,
            (size_t)s->schemas + 1, sizeof *s->schema)) { s->limited = 1; return none; }
    int *binding = sp_allocate(s, &s->storage, (size_t)slot_count, sizeof *binding);
    int *universals = sp_allocate(s, &s->storage, (size_t)s->universal, sizeof *universals);
    SpProperty *property = sp_allocate(s, &s->storage, (size_t)declared_symbols, sizeof *property);
    if (s->limited) return none;
    if (slot_count) memcpy(binding, s->binding, (size_t)slot_count * sizeof *binding);
    if (s->universal) memcpy(universals, s->universals, (size_t)s->universal * sizeof *universals);
    if (declared_symbols) memcpy(property, s->property, (size_t)declared_symbols * sizeof *property);
    int symbol = sp_symbol(s, s->universal, 1);
    SpLiteral name = {sp_term(s, symbol, universals), 0, 0};
    if (!s->limited) s->schema[s->schemas++] = (SpSchema){.source=n, .name=name,
        .positive=positive, .every=(n->kind == S_FORALL_PART) == positive, .universal=s->universal,
        .binding=binding, .universals=universals, .property=property};
    return name;
}

/* L'appartenenza a una parte definita da L e D_S(t) AND L(t). Il parametro
 * v0 viene sostituito una sola volta; gli altri termini restano chiusi. */
static SpLiteral sp_property_member(SpState *s, const Elem *e) {
    SpLiteral none = {0, 0, 1};
    if (e->symbol < 0 || e->symbol >= declared_symbols || !s->property[e->symbol].literal.left) {
        s->unsupported = 1; return none;
    }
    SpProperty p = s->property[e->symbol];
    int value = sp_input_term(s, e->arg[0]);
    SpLiteral l = p.literal;
    l.left = sp_replace_term(s, l.left, -1, value); l.right = sp_replace_term(s, l.right, -1, value);
    SpLiteral domain = {sp_term(s, s->inputs + p.sort, &value), 0, 0};
    if (s->forward) l = sp_constant_literal(l);
    int forward = s->forward; s->forward = 0;
    SpLiteral member = sp_connect(s, domain, l, 1);
    s->forward = forward;
    return member;
}

/* NNF, Skolem e Tseitin sull'albero. positive indica la polarita richiesta.
 * Un quantificatore su S diventa un quantificatore del dominio comune con
 * il vincolo D_S: lo Skolem di un esiste non impone mai D_S incondizionatamente.
 * Le parti quantificate ricevono un'astrazione e successive istanze di
 * comprensione; l'equipotenza conserva le proprie strategie. */
static SpLiteral sp_formula(SpState *s, const Sentence *n, int positive) {
    SpLiteral constant = {0, 0, !positive}, a, b;
    if (!sp_visit(s)) return constant;
    switch (n->kind) {
    case S_TRUE: return constant;
    case S_EQUAL: case S_HOLDS:
        if (n->kind == S_HOLDS && n->left->symbol >= 0 && n->left->symbol < declared_symbols && symbol_bound[n->left->symbol]) {
            a = sp_property_member(s, n->left); return positive ? a : sp_not(a);
        }
        return (SpLiteral){sp_input_term(s, n->left), n->right ? sp_input_term(s, n->right) : 0, !positive};
    case S_NOT: return sp_formula(s, n->a, !positive);
    case S_AND: case S_OR: case S_IMPLIES:
        a = sp_formula(s, n->a, n->kind == S_IMPLIES ? !positive : positive);
        if (s->forward) {
            a = sp_constant_literal(a);
            if (!a.left && a.negative == ((n->kind == S_AND) == positive)) return a;
        }
        b = sp_formula(s, n->b, positive);
        return sp_connect(s, a, b, (n->kind == S_AND) == positive);
    case S_IFF:
        a = sp_formula(s, n->a, 0); b = sp_formula(s, n->b, positive);
        a = sp_connect(s, a, b, 0);
        b = sp_formula(s, n->a, 1);
        return sp_connect(s, a, sp_connect(s, b, sp_formula(s, n->b, !positive), 0), 1);
    case S_FORALL: case S_EXISTS: {
        int every = (n->kind == S_FORALL) == positive;
        if (s->variables == INT_MAX || !sp_reserve(s, (void **)&s->universals, &s->universal_cap, (size_t)s->universal + 1, sizeof *s->universals)) {
            s->limited = 1; return constant;
        }
        int value = every ? -1 - s->variables++ : sp_term(s, sp_symbol(s, s->universal, 0), s->universals);
        int saved = s->binding[n->slot]; s->binding[n->slot] = value;
        if (every) s->universals[s->universal++] = value;
        a = (SpLiteral){sp_term(s, s->inputs + slot_data[n->slot].sort, &value), 0, every};
        b = sp_formula(s, n->a, positive);
        if (every) s->universal--;
        s->binding[n->slot] = saved;
        return sp_connect(s, a, b, !every);
    }
    case S_FORALL_PART: case S_EXISTS_PART: return sp_schema(s, n, positive);
    default: s->unsupported = 1; return constant;
    }
}

/* Introduce un simbolo originale nella numerazione del certificato.
 * input_symbol traduce i posti del parser; original_symbol e la mappa
 * inversa, usata nelle clausole di chiusura e nel testo della prova. */
static void sp_input_symbol(SpState *s, int original) {
    if (original < 0 || original >= declared_symbols) { s->unsupported = 1; return; }
    if (s->input_symbol[original] >= 0) return;
    if (!sp_reserve(s, (void **)&s->original_symbol, &s->original_cap, (size_t)s->inputs + 1, sizeof *s->original_symbol)) return;
    int id = sp_symbol(s, symbols[original].arity, symbols[original].range == TRUTH);
    if (s->limited) return;
    s->input_symbol[original] = id; s->original_symbol[s->inputs++] = original;
}

/* Clausifica la negazione dell'enunciato e le leggi fornite. Le sole
 * funzioni dichiarate ricevono clausole di chiusura sui domini; per
 * predicati e simboli di Skolem non si inventano vincoli ulteriori. */
static int sp_prepare(SpState *s, const Sentence *root, const Sentence *const *laws, int count) {
    s->empty = -1;
    for (int i = 0; i < declared_symbols; i++) if (symbol_bound[i]) s->forward = 1;
    if (!sp_reserve(s, (void **)&s->binding, &s->binding_cap, (size_t)slot_count, sizeof *s->binding)) return 0;
    if (!sp_reserve(s, (void **)&s->property, &s->property_cap, (size_t)declared_symbols, sizeof *s->property)) return 0;
    if (!sp_reserve(s, (void **)&s->input_symbol, &s->input_cap, (size_t)declared_symbols, sizeof *s->input_symbol)) return 0;
    for (int i = 0; i < declared_symbols; i++) s->input_symbol[i] = -1;
    /* Warning: questo ordine e quello scritto da cert_abstract_head: prima
     * i simboli impliciti nelle sort, poi le dichiarazioni esplicite. Il
     * parser puo aver incontrato una funzione prima di un insieme di parti. */
    for (int i = 0; i < sort_count; i++) {
        if (sort_data[i].kind == SORT_NUMBERS) {
            for (int f = 0; f < declared_symbols; f++)
                if (symbols[f].name >= NUMERAL_NAMES && symbols[f].range == i) sp_input_symbol(s, f);
        } else if (sort_data[i].kind != SORT_PLAIN) sp_input_symbol(s, sort_data[i].symbol);
    }
    for (int i = 0; i < declared_symbols; i++)
        if (!symbol_fixed(i) && !symbol_bound[i]) sp_input_symbol(s, i);
    for (int i = 0; i < sort_count; i++) sp_symbol(s, 1, 1);
    for (int i = 0; i < s->inputs && sp_visit(s); i++) {
        const Symbol *f = &symbols[s->original_symbol[i]];
        if (f->range == TRUTH) continue;
        int vars[2] = {-1, -2}, value = sp_term(s, i, vars);
        SpLiteral c[3];
        c[0] = (SpLiteral){sp_term(s, s->inputs + f->range, &value), 0, 0};
        for (int j = 0; j < f->arity; j++) c[j + 1] = (SpLiteral){sp_term(s, s->inputs + f->domain[j], &vars[j]), 0, 1};
        sp_keep(s, c, f->arity + 1, (SpStep){.rule=SP_INPUT}, -1);
    }
    SpLiteral l = sp_formula(s, root, 0); sp_emit(s, l, l, l, 1);
    for (int i = 0; i < count && sp_visit(s); i++) { l = sp_formula(s, laws[i], 1); sp_emit(s, l, l, l, 1); }
    s->initial = s->clauses;
    return !s->limited && !s->unsupported;
}

/* Confronta chiavi canoniche senza permutare i letterali: lo stesso ordine
 * verra scritto nel certificato e ricostruito indipendentemente. */
static int sp_component_equal(SpState *s, SpClause a, SpClause b) {
    if (a.count != b.count) return 0;
    for (int i = 0; i < a.count && sp_visit(s); i++)
        if (a.literal[i].left != b.literal[i].left || a.literal[i].right != b.literal[i].right || a.literal[i].negative != b.literal[i].negative) return 0;
    return !s->limited;
}

/* Condivide una chiusura universale e conserva le sue definizioni.
 * Solo un singolo letterale ground puo usare il complemento della stessa
 * proposizione. Una quota puo lasciare una definizione incompleta, ma non
 * permette di cancellare il genitore dello split che la richiedeva. */
static int sp_component(SpState *s, SpClause key) {
    for (int i = 0; i < s->components && sp_visit(s); i++)
        if (sp_component_equal(s, key, s->component[i].key)) return i;
    if (s->limited) return -1;
    if (s->components == INT_MAX || key.count == INT_MAX ||
        !sp_reserve(s, (void **)&s->component, &s->component_cap, (size_t)s->components + 1, sizeof *s->component)) {
        s->limited = 1; return -1;
    }
    if (s->introductions == INT_MAX || !sp_reserve(s, (void **)&s->introduction, &s->introduction_cap,
            (size_t)s->introductions + 1, sizeof *s->introduction)) { s->limited = 1; return -1; }
    SpLiteral *copy = sp_allocate(s, &s->storage, (size_t)key.count, sizeof *copy);
    if (!copy) return -1;
    memcpy(copy, key.literal, (size_t)key.count * sizeof *copy); key.literal = copy;
    int symbol = sp_symbol(s, 0, 1);
    if (s->limited) return -1;
    int id = s->components++;
    s->component[id] = (SpComponent){.key=key, .symbol=symbol, .forward=-1, .reverse=-1};
    s->symbol[symbol].component = id + 1;
    s->introduction[s->introductions++] = (SpIntroduction){SP_COMPONENT, id};
    int atom = sp_term(s, symbol, NULL);
    s->component[id].atom = atom; s->avatar_dirty = 1;
    SpLiteral *definition = sp_allocate(s, &s->scratch, (size_t)key.count + 1, sizeof *definition);
    if (!definition || s->limited) return -1;
    memcpy(definition, copy, (size_t)key.count * sizeof *definition);
    definition[key.count] = (SpLiteral){atom, 0, 1};
    s->component[id].forward = sp_keep(s, definition, key.count + 1, (SpStep){.rule=SP_COMPONENT, .p=id}, -1);
    if (!key.variables && key.count == 1 && !s->limited) {
        SpLiteral opposite[] = {sp_not(copy[0]), {atom, 0, 0}};
        s->component[id].reverse = sp_keep(s, opposite, 2, (SpStep){.rule=SP_COMPLEMENT, .p=id}, -1);
    }
    return s->limited ? -1 : id;
}

/* Radice di una classe di letterali connessi da variabili condivise.
 * La compressione dei cammini non cambia la partizione matematica. */
static int sp_group_root(SpState *s, int *parent, int i) {
    int root = i;
    while (parent[root] != root && sp_visit(s)) root = parent[root];
    while (parent[i] != i && sp_visit(s)) { int next = parent[i]; parent[i] = root; i = next; }
    return root;
}

/* Collega due letterali quando vi compare la stessa variabile. owner ha
 * una cella per nome normalizzato e vale -1 prima della prima occorrenza. */
static void sp_group_variables(SpState *s, int term, int literal, int *parent, int *owner) {
    if (!term || !sp_visit(s)) return;
    if (term < 0) {
        int v = -term - 1;
        if (owner[v] < 0) owner[v] = literal;
        else {
            int a = sp_group_root(s, parent, literal), b = sp_group_root(s, parent, owner[v]);
            parent[b] = a;
        }
        return;
    }
    SpTerm n = s->term[term];
    for (int i = 0; i < n.count; i++) sp_group_variables(s, s->argument[n.first + i], literal, parent, owner);
}

/* Trova le componenti connesse dei letterali ordinari e scrive uno split
 * controllabile. I letterali ground sono componenti singole; le guardie
 * gia presenti non partecipano alla connessione e restano nel risultato.
 * Le definizioni non vengono suddivise di nuovo. Ritorna senza cambiare
 * il genitore quando rimane una sola componente con variabili. */
static void sp_split(SpState *s, int p) {
    SpClause a = s->clause[p];
    if (!a.count || a.stage == SP_DELETED || a.stage == SP_HELD || a.stage == SP_BOOLEAN ||
        a.step.rule == SP_COMPONENT || a.step.rule == SP_COMPLEMENT) return;
    /* La strategia con istanze propaga direttamente i fatti unitari:
     * astrarli di nuovo li nasconderebbe dietro guardie senza offrire una
     * scelta fra rami. Le disgiunzioni restano affidate allo split. */
    if (s->comprehension && a.count == 1) return;
    sp_scratch_reset(s);
    int *parent = sp_allocate(s, &s->scratch, (size_t)a.count, sizeof *parent);
    int *owner = sp_allocate(s, &s->scratch, (size_t)a.variables, sizeof *owner);
    int *which = sp_allocate(s, &s->scratch, (size_t)a.count, sizeof *which);
    if (!parent || !which || (a.variables && !owner)) return;
    for (int i = 0; i < a.count; i++) { parent[i] = i; which[i] = -1; }
    for (int i = 0; i < a.variables; i++) owner[i] = -1;
    for (int i = 0; i < a.count && sp_visit(s); i++) if (!sp_guard(s, a.literal[i])) {
        sp_group_variables(s, a.literal[i].left, i, parent, owner);
        sp_group_variables(s, a.literal[i].right, i, parent, owner);
    }
    int groups = 0;
    for (int i = 0; i < a.count && sp_visit(s); i++) if (!sp_guard(s, a.literal[i])) {
        int root = sp_group_root(s, parent, i);
        parent[i] = root;
        if (which[root] < 0) which[root] = groups++;
    }
    if (s->limited || !groups || (groups == 1 && a.variables)) return;
    SpGroup *part = sp_allocate(s, &s->scratch, (size_t)groups, sizeof *part);
    int *used = sp_allocate(s, &s->scratch, (size_t)groups, sizeof *used);
    SpLiteral *out = sp_allocate(s, &s->scratch, (size_t)a.count, sizeof *out);
    if (!part || !used || !out) return;
    memset(part, 0, (size_t)groups * sizeof *part); memset(used, 0, (size_t)groups * sizeof *used);
    /* Le radici sono gia definitive. Una nuova visita con quota durante
     * il conteggio potrebbe fermarsi su un nodo interno, privo di gruppo:
     * usare soltanto le radici congelate evita un indice -1. */
    for (int i = 0; i < a.count; i++) if (!sp_guard(s, a.literal[i])) part[which[parent[i]]].count++;
    for (int i = 0; i < groups; i++) {
        part[i].literal = sp_allocate(s, &s->scratch, (size_t)part[i].count, sizeof *part[i].literal);
        if (!part[i].literal) return;
    }
    for (int i = 0; i < a.count; i++) if (!sp_guard(s, a.literal[i])) {
        int group = which[parent[i]];
        ((int *)part[group].literal)[used[group]++] = i;
    }
    for (int i = 0; i < groups && sp_visit(s); i++) {
        SpLiteral *literal = sp_allocate(s, &s->scratch, (size_t)part[i].count, sizeof *literal);
        if (!literal) return;
        for (int j = 0; j < part[i].count; j++) literal[j] = a.literal[part[i].literal[j]];
        SpClause key = sp_normal(s, literal, part[i].count);
        /* Anche in una clausola con variabili, un singolo gruppo ground
         * condivide la chiave positiva con il suo letterale opposto. */
        if (!key.variables && key.count == 1 && key.literal[0].negative) {
            part[i].negative = 1; literal[0].negative = 0; key = sp_normal(s, literal, 1);
        }
        int id = sp_component(s, key);
        if (id < 0) return;
        part[i].component = id;
        out[i] = (SpLiteral){s->component[id].atom, 0, part[i].negative};
    }
    int count = groups;
    for (int i = 0; i < a.count; i++) if (sp_guard(s, a.literal[i])) out[count++] = a.literal[i];
    if (s->limited) return;
    sp_keep(s, out, count, (SpStep){.rule=SP_SPLIT, .p=p, .groups=groups, .group=part}, -1);
    if (!s->limited) s->clause[p].stage = SP_DELETED;
}

/* Istanzia una formula universale su parti con una proprieta letterale.
 * Tutte le clausole emesse restano indicizzate, perche il checker ricrea
 * l'intero gruppo. Nessuna verita della proprieta viene assunta. L'istanza
 * puo introdurre altre formule quantificate, con le proprie copie di contesto.
 * Una quota interrompe onestamente il tentativo finale: un gruppo parziale
 * non viene esportato. Ritorna uno anche per un'istanza gia presente. */
static int sp_comprehend(SpState *s, int id, SpLiteral literal) {
    if (!sp_visit(s)) return 0;
    if (s->emitting || id < 0 || id >= s->schemas || !s->schema[id].every) {
        s->unsupported = 1; return 0;
    }
    SpClause property = sp_normal(s, &literal, 1);
    if (s->limited) return 0;
    if (property.count != 1 || property.variables > 1 || !property.literal[0].left) { s->unsupported = 1; return 0; }
    literal = property.literal[0];
    for (int i = 0; i < s->expansions && sp_visit(s); i++) {
        SpExpansion old = s->expansion[i];
        if (old.schema == id && old.property.left == literal.left && old.property.right == literal.right && old.property.negative == literal.negative) {
            if (!old.complete) { s->limited = 1; s->resumable = 0; return 0; }
            return 1;
        }
    }
    if (s->limited) return 0;
    if (s->expansions == INT_MAX || !sp_reserve(s, (void **)&s->expansion, &s->expansion_cap,
            (size_t)s->expansions + 1, sizeof *s->expansion)) { s->limited = 1; return 0; }
    if (s->introductions == INT_MAX || !sp_reserve(s, (void **)&s->introduction, &s->introduction_cap,
            (size_t)s->introductions + 1, sizeof *s->introduction)) { s->limited = 1; return 0; }
    SpSchema schema = s->schema[id];
    if (!sp_reserve(s, (void **)&s->universals, &s->universal_cap, (size_t)schema.universal, sizeof *s->universals)) return 0;
    if (slot_count) memcpy(s->binding, schema.binding, (size_t)slot_count * sizeof *s->binding);
    if (declared_symbols) memcpy(s->property, schema.property, (size_t)declared_symbols * sizeof *s->property);
    if (schema.universal) memcpy(s->universals, schema.universals, (size_t)schema.universal * sizeof *s->universals);
    s->universal = schema.universal;
    int part = schema.source->part;
    s->property[part] = (SpProperty){literal, symbols[part].domain[0]};
    int expansion = s->expansions++;
    s->expansion[expansion] = (SpExpansion){.schema=id, .first=s->clauses, .past=s->clauses, .symbol_first=s->symbols, .property=literal};
    s->introduction[s->introductions++] = (SpIntroduction){SP_COMPREHEND, expansion};
    s->emitting = expansion + 1;
    /* Una quota locale puo fermare la strategia, ma non lascia un comando
     * a meta. Il budget globale e la memoria restano sempre vincolanti. */
    unsigned long long quota = s->quota; clock_t cpu_quota = s->cpu_quota;
    s->quota = 0; s->cpu_quota = 0;
    SpLiteral result = sp_formula(s, schema.source->a, schema.positive);
    sp_emit(s, sp_not(schema.name), result, result, 2);
    s->quota = quota; s->cpu_quota = cpu_quota;
    s->emitting = 0;
    s->expansion[expansion].past = s->clauses;
    s->expansion[expansion].symbol_past = s->symbols;
    s->expansion[expansion].complete = !s->limited && !s->unsupported;
    if (!s->expansion[expansion].complete) s->resumable = 0;
    s->universal = 0;
    if (slot_count) memset(s->binding, 0, (size_t)slot_count * sizeof *s->binding);
    if (declared_symbols) memset(s->property, 0, (size_t)declared_symbols * sizeof *s->property);
    return !s->limited && !s->unsupported;
}

/* Le parti vuota e intera sono comprensioni valide anche senza elementi
 * nominati. Si propone una sola formula per turno; le formule annidate
 * entrano nella stessa agenda dinamica, senza un limite di profondita.
 * Le proprieta x=x e x!=x sono dati generali, non casi di un esercizio. */
static void sp_seed_comprehensions(SpState *s) {
    while (s->seed_schema < s->schemas && sp_visit(s)) {
        int id = s->seed_schema++;
        if (!s->schema[id].every) continue;
        sp_scratch_reset(s);
        if (sp_comprehend(s, id, (SpLiteral){-1, -1, 0})) sp_comprehend(s, id, (SpLiteral){-1, -1, 1});
        return;
    }
}

/* Una proprieta proposta deve avere solo il parametro da astrarre.
 * Qui il controllo di groundness e sintattico, senza assegnazioni a caso. */
static int sp_ground_term(SpState *s, int term) {
    if (!term) return 1;
    if (!sp_visit(s) || term < 0) return 0;
    SpTerm n = s->term[term];
    for (int i = 0; i < n.count; i++) if (!sp_ground_term(s, s->argument[n.first + i])) return 0;
    return 1;
}

/* Una proprieta gia proposta copre i suoi casi particolari. Il matching
 * separa i due parametri: P(s(x)) non richiede un'altra istanza induttiva
 * quando P(x) e gia nell'agenda. E solo una selezione della ricerca, non
 * una prova di P(x); il checker riceve sempre le istanze effettive. */
static int sp_property_covered(SpState *s, int schema, SpLiteral property) {
    for (int i = 0; i < s->expansions && sp_visit(s); i++) {
        SpExpansion e = s->expansion[i]; SpLiteral old = e.property;
        if (e.schema != schema || old.negative != property.negative || !!old.right != !!property.right) continue;
        for (int flip = 0; flip < (old.right ? 2 : 1) && sp_visit(s); flip++) {
            sp_scratch_reset(s);
            if (!sp_match_start(s, 1)) return 0;
            /* Ogni proprieta ha al piu v0: v1 separa il candidato dalla
             * variabile sostituibile della proprieta gia proposta. */
            int left = sp_apply(s, flip ? property.right : property.left, 1, NULL, 0, 0);
            int right = sp_apply(s, flip ? property.left : property.right, 1, NULL, 0, 0);
            if (sp_match(s, old.left, left) && (!old.right || sp_match(s, old.right, right))) return 1;
        }
    }
    return 0;
}

/* Dalla clausola selezionata L[t] si propone la proprieta complementare
 * NOT L[x]. Le sottoespressioni piu piccole vengono prima: per f(a)!=a
 * la scelta a produce f(x)=x. Si applica la stessa operazione strutturale
 * alle costanti del letterale, senza riconoscere un teorema o un costruttore.
 * Questa e la selezione leggera su unita ground di Reger e Voronkov:
 * applicare subito tutte le proprieta di ogni clausola moltiplicherebbe
 * i corpi prima di poter lavorare sull'obiettivo induttivo corrente. */
static void sp_propose_term(SpState *s, SpLiteral literal, int term) {
    if (term <= 0 || !sp_visit(s)) return;
    SpTerm n = s->term[term];
    for (int i = 0; i < n.count && !s->limited; i++) sp_propose_term(s, literal, s->argument[n.first + i]);
    if (n.count || s->symbol[n.symbol].predicate || s->limited || s->unsupported) return;
    sp_scratch_reset(s);
    SpLiteral property = sp_not(literal);
    property.left = sp_replace_term(s, property.left, term, -1);
    property.right = sp_replace_term(s, property.right, term, -1);
    int schemas = s->schemas;
    for (int i = 0; i < schemas && sp_visit(s); i++) if (s->schema[i].every) {
        if (sp_property_covered(s, i, property)) continue;
        if (!sp_comprehend(s, i, property)) return;
    }
}

/* I predicati tecnici di domini e Tseitin guidano la saturazione, ma non
 * sono nuovi obiettivi induttivi. Si considerano uguaglianze e predicati
 * originali ground; il budget globale limita i tentativi, non un tetto
 * compilato al numero di proprieta o istanze. */
static void sp_propose_comprehensions(SpState *s, int id) {
    if (!s->schemas) return;
    SpClause c = s->clause[id];
    int ordinary = 0;
    for (int i = 0; i < c.count; i++) ordinary += !sp_guard(s, c.literal[i]);
    if (ordinary != 1) return;
    for (int i = 0; i < c.count && sp_visit(s); i++) {
        SpLiteral l = c.literal[i];
        if (sp_guard(s, l)) continue;
        /* Nel ramo SAT si anticipano i controesempi negativi: dai fatti
         * gia veri non si generano subito proprieta complementari. Il
         * tentativo ordinario finale considera entrambi i segni. */
        if (s->avatar && !l.negative) continue;
        if (!l.left || (!l.right && (l.left < 0 || s->term[l.left].symbol >= s->inputs))) continue;
        if (!sp_ground_term(s, l.left) || !sp_ground_term(s, l.right)) continue;
        sp_propose_term(s, l, l.left); sp_propose_term(s, l, l.right);
    }
}

/* Congela le immagini di una sostituzione. Risolvere qui tutte le catene
 * permette al checker di applicarla una sola volta, simultaneamente. */
static SpStep sp_snapshot(SpState *s, SpStep step, const int *sub, int count, int recursive) {
    int bindings = 0;
    for (int v = 0; v < count; v++) bindings += sub[v] != 0;
    SpBinding *saved = sp_allocate(s, &s->scratch, (size_t)bindings, sizeof *saved);
    if (bindings && !saved) return step;
    step.binding = saved; step.bindings = 0;
    for (int v = 0; v < count && sp_visit(s); v++) if (sub[v]) {
        int term = sp_apply(s, sub[v], 0, sub, count, recursive);
        if (term != -v - 1) saved[step.bindings++] = (SpBinding){v, term};
    }
    return step;
}

/* Dimensiona il contesto dei genitori separati. Il prefisso storico 64
 * mantiene leggibili i primi certificati, senza essere un limite. */
static int sp_context(SpState *s, int p, int q, int *offset) {
    *offset = s->clause[p].variables > 64 ? s->clause[p].variables : 64;
    if (s->clause[q].variables > INT_MAX - *offset) { s->limited = 1; return 0; }
    return *offset + s->clause[q].variables;
}

/* Conserva il risultato di una risoluzione o fattorizzazione. omit_a e
 * omit_b sono i letterali cancellati, -1 se nessuno; b puo essere vuota.
 * extra aggiunge, se richiesto, l'ineguaglianza della fattorizzazione equazionale. */
static void sp_combination(SpState *s, SpStep step, SpClause a, int omit_a,
                           SpClause b, int omit_b, int offset, const SpLiteral *extra) {
    if (b.count > INT_MAX - a.count - 1) { s->limited = 1; return; }
    int capacity = a.count + b.count + 1, used = 0;
    SpLiteral *out = sp_allocate(s, &s->scratch, (size_t)capacity, sizeof *out);
    SpLiteral *x = sp_instance(s, a, 0, s->sub, s->sub_count, 1);
    SpLiteral *y = sp_instance(s, b, offset, s->sub, s->sub_count, 1);
    if (!out || (a.count && !x) || (b.count && !y)) return;
    for (int i = 0; i < a.count; i++) if (i != omit_a) out[used++] = x[i];
    for (int i = 0; i < b.count; i++) if (i != omit_b) out[used++] = y[i];
    if (extra) out[used++] = *extra;
    step = sp_snapshot(s, step, s->sub, s->sub_count, 1);
    sp_keep(s, out, used, step, -1);
}

/* La selezione vale 1 se sono presenti letterali negativi ordinari, 2
 * per una clausola composta soltanto da domini, zero negli altri casi.
 * Le guardie AVATAR non partecipano alla scelta dei letterali FO. */
static int sp_resolution_selection(const SpState *s, SpClause c) {
    int negative = 0, domains = s->inputs != 0;
    for (int i = 0; i < c.count; i++) {
        SpLiteral l = c.literal[i];
        if (s->avatar && sp_guard(s, l)) continue;
        negative |= l.negative;
        if (l.right || l.left <= 0) domains = 0;
        else {
            int symbol = s->term[l.left].symbol;
            domains &= symbol >= s->inputs && symbol < s->inputs + sort_count;
        }
    }
    return domains ? 2 : negative;
}

/* Si privilegiano i negativi, ma le clausole dei domini usano il massimo
 * KBO. In D(f(x)) OR NOT D(x) il massimo e D(f(x)): si risponde cosi a
 * richieste su un termine gia presente, invece di generare D(f^n(a)) per
 * tutti i termini possibili. Nessun vincolo di dominio viene cancellato.
 * La selezione decide soltanto quali risoluzioni valide tentare. */
static int sp_resolution_literal(SpState *s, SpClause c, int index, int selection) {
    SpLiteral l = c.literal[index];
    if (s->avatar && sp_guard(s, l)) return 0;
    if (selection != 2) return !selection || l.negative;
    for (int i = 0; i < c.count && sp_visit(s); i++)
        if ((!s->avatar || !sp_guard(s, c.literal[i])) && sp_greater(s, c.literal[i].left, l.left)) return 0;
    return !s->limited;
}

/* Risoluzione binaria: da C o A e D o non B, se A e B si unificano,
 * segue (C o D) sigma. Per le uguaglianze si provano entrambi i versi.
 * Non si identificano le variabili dei genitori prima dell'unificazione. */
static void sp_resolve(SpState *s, int p, int q) {
    SpClause a = s->clause[p], b = s->clause[q];
    int selection_a = sp_resolution_selection(s, a), selection_b = sp_resolution_selection(s, b);
    int offset, count = sp_context(s, p, q, &offset);
    for (int i = 0; i < a.count && s->empty < 0 && sp_visit(s); i++)
        for (int j = 0; j < b.count && s->empty < 0 && sp_visit(s); j++) {
            SpLiteral x = a.literal[i], y = b.literal[j];
            if (!sp_resolution_literal(s, a, i, selection_a) || !sp_resolution_literal(s, b, j, selection_b)) continue;
            if (x.negative == y.negative || !!x.right != !!y.right || !x.left || !y.left) continue;
            for (int flip = 0; flip < (x.right ? 2 : 1) && s->empty < 0 && sp_visit(s); flip++) {
                sp_scratch_reset(s);
                if (!sp_unify_start(s, count)) return;
                int left = sp_apply(s, flip ? y.right : y.left, offset, NULL, 0, 0);
                int right = sp_apply(s, flip ? y.left : y.right, offset, NULL, 0, 0);
                if (!sp_unify(s, x.left, left) || (x.right && !sp_unify(s, x.right, right))) continue;
                sp_combination(s, (SpStep){.rule=SP_RESOLVE, .p=p, .lp=i, .q=q, .lq=j}, a, i, b, j, offset, NULL);
            }
        }
}

/* Trova un letterale proposizionale esatto, oppure restituisce -1.
 * I duplicati sono gia contratti dalla normalizzazione delle clausole. */
static int sp_proposition(SpClause c, int atom, int negative) {
    for (int i = 0; i < c.count; i++)
        if (!c.literal[i].right && c.literal[i].left == atom && c.literal[i].negative == negative) return i;
    return -1;
}

/* Elimina un nome tecnico senza argomenti con Davis-Putnam: da tutte le
 * coppie C OR q, D OR NOT q conserva C OR D, poi ritira le clausole con q.
 * Ogni risolvente ha una risoluzione esplicita, ricontrollabile dal checker.
 * Teacher: un modello dei risolventi si estende scegliendo q vero se un C
 * e falso, falso se un D e falso; entrambe le richieste non possono esserci
 * insieme, perche falsificherebbero C OR D. L'argomento vale anche quando
 * C e D sono universalmente quantificate, separandone prima le variabili.
 * Se una quota interrompe le coppie, i genitori restano nella ricerca.
 * Non si eliminano nomi di parti o componenti, che altre istanze possono
 * riutilizzare. Nessun predicato con argomenti viene trattato da Booleano. */
static void sp_eliminate_comprehensions(SpState *s) {
    while (s->eliminate_expansion < s->expansions && s->empty < 0 && sp_visit(s)) {
        SpExpansion e = s->expansion[s->eliminate_expansion];
        if (s->eliminate_symbol < e.symbol_first) s->eliminate_symbol = e.symbol_first;
        if (s->eliminate_symbol >= e.symbol_past) {
            s->eliminate_expansion++; s->eliminate_symbol = 0; continue;
        }
        int symbol = s->eliminate_symbol, protected = 0;
        if (!s->symbol[symbol].predicate || s->symbol[symbol].arity || s->symbol[symbol].component) {
            s->eliminate_symbol++; continue;
        }
        int atom = sp_term(s, symbol, NULL);
        for (int i = 0; i < s->schemas && sp_visit(s); i++) protected |= s->schema[i].name.left == atom;
        for (int i = 0; i < s->components && sp_visit(s); i++)
            protected |= sp_proposition(s->component[i].key, atom, 0) >= 0 || sp_proposition(s->component[i].key, atom, 1) >= 0;
        if (s->limited) return;
        if (protected) { s->eliminate_symbol++; continue; }
        int last = s->clauses;
        for (int p = 0; p < last && s->empty < 0 && sp_visit(s); p++) {
            if (s->clause[p].stage == SP_DELETED) continue;
            SpClause a = s->clause[p]; int x = sp_proposition(a, atom, 0);
            if (x < 0) continue;
            for (int q = 0; q < last && s->empty < 0 && sp_visit(s); q++) {
                if (s->clause[q].stage == SP_DELETED) continue;
                SpClause b = s->clause[q]; int y = sp_proposition(b, atom, 1);
                if (y < 0) continue;
                sp_scratch_reset(s);
                int offset, count = sp_context(s, p, q, &offset);
                if (!sp_unify_start(s, count)) return;
                sp_combination(s, (SpStep){.rule=SP_RESOLVE, .p=p, .lp=x, .q=q, .lq=y}, a, x, b, y, offset, NULL);
            }
        }
        if (s->limited) return;
        for (int i = 0; i < last && sp_visit(s); i++)
            if (sp_proposition(s->clause[i], atom, 0) >= 0 || sp_proposition(s->clause[i], atom, 1) >= 0) s->clause[i].stage = SP_DELETED;
        if (s->limited) return;
        s->eliminate_symbol++;
    }
}

/* Inferenze a un genitore. l!=r si cancella quando l e r si unificano.
 * Due atomi dello stesso segno si contraggono con un unificatore comune.
 * Dalle uguaglianze l=r o u=v, con l sigma=u sigma, segue invece
 * (resto o u=v o r!=v) sigma: e la fattorizzazione equazionale. */
static void sp_unary(SpState *s, int p) {
    SpClause a = s->clause[p], none = {0};
    for (int i = 0; i < a.count && s->empty < 0 && sp_visit(s); i++) {
        SpLiteral x = a.literal[i];
        if (s->avatar && sp_guard(s, x)) continue;
        if (x.negative && x.right) {
            sp_scratch_reset(s);
            if (sp_unify_start(s, a.variables) && sp_unify(s, x.left, x.right))
                sp_combination(s, (SpStep){.rule=SP_REFLEX, .p=p, .lp=i}, a, i, none, -1, 0, NULL);
        }
        for (int j = 0; j < a.count && s->empty < 0 && sp_visit(s); j++) {
            if (j == i) continue;
            SpLiteral y = a.literal[j];
            if (s->avatar && sp_guard(s, y)) continue;
            if (j > i && x.negative == y.negative && !!x.right == !!y.right) {
                for (int flip = 0; flip < (x.right ? 2 : 1) && s->empty < 0 && sp_visit(s); flip++) {
                    sp_scratch_reset(s);
                    if (!sp_unify_start(s, a.variables)) return;
                    if (!sp_unify(s, x.left, flip ? y.right : y.left) ||
                        (x.right && !sp_unify(s, x.right, flip ? y.left : y.right))) continue;
                    sp_combination(s, (SpStep){.rule=SP_FACTOR, .p=p, .lp=i, .lq=j}, a, i, none, -1, 0, NULL);
                }
            }
            /* Per la fattorizzazione equazionale si conserva ciascuna
             * delle due uguaglianze a turno: i residui non sono lo stesso
             * insieme sintattico di letterali, a differenza della fattorizzazione. */
            if (!x.negative && !y.negative && x.right && y.right)
                for (int flip = 0; flip < 2 && s->empty < 0 && sp_visit(s); flip++)
                    for (int other = 0; other < 2 && s->empty < 0 && sp_visit(s); other++) {
                        sp_scratch_reset(s);
                        if (!sp_unify_start(s, a.variables) ||
                            !sp_unify(s, flip ? x.right : x.left, other ? y.right : y.left)) continue;
                        SpLiteral extra = {sp_apply(s, flip ? x.left : x.right, 0, s->sub, s->sub_count, 1),
                                           sp_apply(s, other ? y.left : y.right, 0, s->sub, s->sub_count, 1), 1};
                        sp_combination(s, (SpStep){.rule=SP_EQUAL_FACTOR, .p=p, .lp=i, .lq=j, .flip=flip, .otherflip=other},
                                       a, i, none, -1, 0, &extra);
                    }
        }
    }
}

/* Trova una posizione preorder del termine originale e ne conserva il
 * cammino di figli in path. I pesi esatti consentono di saltare sottoalberi
 * senza visitarli; il cammino resta valido anche se si unificano variabili. */
static int sp_path(SpState *s, int term, unsigned long long position) {
    s->path_count = 0;
    while (position && term > 0 && sp_visit(s)) {
        SpTerm n = s->term[term]; position--;
        int found = 0;
        for (int i = 0; i < n.count; i++) {
            int child = s->argument[n.first + i]; unsigned long long weight = sp_term_weight(s, child);
            if (position >= weight) { position -= weight; continue; }
            if (!sp_reserve(s, (void **)&s->path, &s->path_cap, (size_t)s->path_count + 1, sizeof *s->path)) return 0;
            s->path[s->path_count++] = i; term = child; found = 1; break;
        }
        if (!found) return 0;
    }
    return position ? 0 : term;
}

/* Sostituisce sul cammino scelto e calcola la posizione DOPO sigma. Le
 * immagini delle variabili che precedono il punto possono avere piu nodi:
 * usare la vecchia posizione sarebbe un certificato sbagliato. */
static int sp_rewrite(SpState *s, int term, int depth, int offset, const int *sub, int count, int recursive,
                      int replacement, unsigned long long before, int *position) {
    if (!sp_visit(s)) return 0;
    if (depth == s->path_count) {
        if (before >= INT_MAX) { s->limited = 1; return 0; }
        *position = (int)before;
        return replacement;
    }
    if (term <= 0) { s->limited = 1; return 0; }
    SpTerm n = s->term[term];
    int *args = sp_allocate(s, &s->scratch, (size_t)n.count, sizeof *args);
    if (n.count && !args) return 0;
    before++;
    for (int i = 0; i < n.count; i++) {
        int child = s->argument[n.first + i];
        if (i == s->path[depth]) args[i] = sp_rewrite(s, child, depth + 1, offset, sub, count, recursive, replacement, before, position);
        else args[i] = sp_apply(s, child, offset, sub, count, recursive);
        if (i < s->path[depth]) {
            unsigned long long weight = sp_term_weight(s, args[i]);
            if (weight > ULLONG_MAX - before) { s->limited = 1; return 0; }
            before += weight;
        }
    }
    return sp_term(s, n.symbol, args);
}

/* Costruisce una superposizione valida dopo matching o unificazione. La
 * posizione originale e descritta da path, la sostituzione dal chiamante.
 * Il punto non e mai una variabile ne la radice di un predicato. */
static void sp_super_result(SpState *s, SpStep step, int offset, const int *sub, int count, int recursive) {
    SpClause a = s->clause[step.p], b = s->clause[step.q];
    SpLiteral source = a.literal[step.lp], target = b.literal[step.lq];
    int lhs = sp_apply(s, step.flip ? source.right : source.left, 0, sub, count, recursive);
    int rhs = sp_apply(s, step.flip ? source.left : source.right, 0, sub, count, recursive);
    if (lhs == rhs || sp_greater(s, rhs, lhs)) return;
    int raw = step.side ? target.right : target.left;
    int other = step.side ? target.left : target.right;
    int entire = sp_apply(s, raw, offset, sub, count, recursive);
    if (target.right && sp_greater(s, sp_apply(s, other, offset, sub, count, recursive), entire)) return;
    int result = sp_rewrite(s, raw, 0, offset, sub, count, recursive, rhs, 0, &step.position);
    SpLiteral *x = sp_instance(s, a, 0, sub, count, recursive), *y = sp_instance(s, b, offset, sub, count, recursive);
    if ((a.count && !x) || (b.count && !y) || s->limited) return;
    if (step.side) y[step.lq].right = result; else y[step.lq].left = result;
    if (b.count > INT_MAX - a.count) { s->limited = 1; return; }
    SpLiteral *out = sp_allocate(s, &s->scratch, (size_t)(a.count + b.count), sizeof *out);
    if (!out) return;
    int used = 0;
    for (int i = 0; i < a.count; i++) if (i != step.lp) out[used++] = x[i];
    for (int i = 0; i < b.count; i++) out[used++] = y[i];
    step = sp_snapshot(s, step, sub, count, recursive);
    sp_keep(s, out, used, step, -1);
}

/* Superposizioni fra due clausole, comprese quelle di una clausola con una
 * propria copia rinominata. Si esclude il verso strettamente crescente
 * dopo sigma, ma si conservano i termini incomparabili e tutti i letterali:
 * il calcolo contiene quindi le inferenze della superposizione ordinata. */
static void sp_superpose(SpState *s, int p, int q) {
    SpClause a = s->clause[p], b = s->clause[q];
    int offset, count = sp_context(s, p, q, &offset);
    for (int i = 0; i < a.count && s->empty < 0 && sp_visit(s); i++) {
        SpLiteral source = a.literal[i];
        if (source.negative || !source.right) continue;
        for (int flip = 0; flip < 2 && s->empty < 0 && sp_visit(s); flip++) {
            int lhs = flip ? source.right : source.left;
            if (lhs < 0) continue;
            for (int j = 0; j < b.count && s->empty < 0 && sp_visit(s); j++)
                for (int side = 0; side < (b.literal[j].right ? 2 : 1) && s->empty < 0 && sp_visit(s); side++) {
                    int raw = side ? b.literal[j].right : b.literal[j].left;
                    unsigned long long size = sp_term_weight(s, raw), first = b.literal[j].right ? 0 : 1;
                    for (unsigned long long pos = first; pos < size && s->empty < 0 && sp_visit(s); pos++) {
                        sp_scratch_reset(s);
                        int at = sp_path(s, raw, pos);
                        if (at <= 0 || !sp_unify_start(s, count)) continue;
                        int target = sp_apply(s, at, offset, NULL, 0, 0);
                        if (!sp_unify(s, lhs, target)) continue;
                        sp_super_result(s, (SpStep){.rule=SP_SUPER, .p=p, .lp=i, .q=q, .lq=j, .flip=flip, .side=side},
                                        offset, s->sub, s->sub_count, 1);
                    }
                }
        }
    }
}

/* Riscrive una clausola con una singola uguaglianza universale orientata.
 * Si usa matching: la clausola bersaglio non viene istanziata. La nuova
 * clausola e equivalente alla precedente in presenza dell'uguaglianza;
 * anche se gia sussunta, rende ridondante il vecchio bersaglio. */
static int sp_demodulate(SpState *s, int p, int q) {
    SpClause a = s->clause[p], b = s->clause[q];
    if (p == q || a.count != 1 || a.literal[0].negative || !a.literal[0].right) return 0;
    SpLiteral l = a.literal[0];
    int flip;
    if (sp_greater(s, l.left, l.right)) flip = 0;
    else if (sp_greater(s, l.right, l.left)) flip = 1;
    else return 0;
    int lhs = flip ? l.right : l.left, offset, count = sp_context(s, p, q, &offset);
    (void)count;
    for (int j = 0; j < b.count && sp_visit(s); j++)
        for (int side = 0; side < (b.literal[j].right ? 2 : 1) && sp_visit(s); side++) {
            int raw = side ? b.literal[j].right : b.literal[j].left;
            unsigned long long size = sp_term_weight(s, raw), first = b.literal[j].right ? 0 : 1;
            for (unsigned long long pos = first; pos < size && sp_visit(s); pos++) {
                sp_scratch_reset(s);
                int at = sp_path(s, raw, pos);
                if (at <= 0 || !sp_match_start(s, a.variables)) continue;
                if (!sp_match(s, lhs, sp_apply(s, at, offset, NULL, 0, 0))) continue;
                /* La demodulazione puo agire anche nel membro minore di
                 * un'uguaglianza: e una riscrittura, non una restrizione
                 * necessaria al calcolo della superposizione. */
                SpClause original = s->clause[q];
                SpLiteral *target = sp_instance(s, original, offset, s->match, s->match_count, 0);
                int rhs = sp_apply(s, flip ? l.left : l.right, 0, s->match, s->match_count, 0), position;
                int rewritten = sp_rewrite(s, raw, 0, offset, s->match, s->match_count, 0, rhs, 0, &position);
                if (!target || s->limited) return 0;
                if (side) target[j].right = rewritten; else target[j].left = rewritten;
                SpStep step = {.rule=SP_SUPER, .p=p, .lp=0, .q=q, .lq=j, .flip=flip, .side=side, .position=position};
                step = sp_snapshot(s, step, s->match, s->match_count, 0);
                sp_keep(s, target, original.count, step, q);
                if (s->limited) return 0;
                s->clause[q].stage = SP_DELETED;
                return 1;
            }
        }
    return 0;
}

/* Ricomincia la coda con le clausole scelte e ogni deduzione conservata.
 * Non si rianima una clausola eliminata per tautologia o sussunzione.
 * Anche gli ACTIVE tornano PENDING: una quota puo avere fermato le loro
 * inferenze prima di esaurirle. L'eta riparte da zero senza perdere equita.
 * selected=NULL riattiva tutte le ipotesi. keep_active e ammesso solo
 * quando il modello SAT precedente viene esteso senza cambiarne i valori;
 * conserva allora anche l'eta e l'agenda unitaria. Ritorna quante sono sospese;
 * con limited la coda e incompleta e il chiamante non deve usarla. */
static int sp_requeue_mode(SpState *s, const unsigned char *selected, int keep_active) {
    int held = 0;
    s->heap_count = 0;
    if (!keep_active) {
        s->age = 0; s->rounds = 0;
        s->units = s->unit_cursor = 0;
    }
    for (int i = 0; i < s->clauses && sp_visit(s); i++) {
        if (s->clause[i].stage == SP_DELETED) continue;
        int keep = i >= s->initial || !selected || selected[i];
        SpStage stage = keep ? sp_available(s, s->clause[i]) : SP_HELD;
        if (keep_active && stage == SP_PENDING && s->clause[i].stage == SP_ACTIVE) stage = SP_ACTIVE;
        s->clause[i].stage = stage;
        if (s->clause[i].stage == SP_PENDING) sp_enqueue(s, i);
        if (!keep) held++;
    }
    return held;
}

/* Una strategia nuova riprende anche le inferenze eventualmente interrotte
 * dal tentativo precedente. Nessuna clausola elaborata resta esclusa. */
static int sp_requeue(SpState *s, const unsigned char *selected) {
    return sp_requeue_mode(s, selected, 0);
}

/* Converte una guardia nel letterale del SAT. La variabile SAT uno e la
 * costante vera; le componenti occupano consecutivamente i posti da due. */
static SatLiteral sp_boolean(const SpState *s, SpLiteral l) {
    SatLiteral v = (SatLiteral)sp_guard(s, l) + 1;
    return l.negative ? -v : v;
}

/* Risoluzione proposizionale esplicita per il replay. Il pivot e l'indice
 * della componente, non una decisione del SAT. Entrambi i genitori sono
 * clausole complete gia giustificate; nessuna unificazione e necessaria. */
static int sp_boolean_resolve(SpState *s, int p, int q, int pivot) {
    SpClause a = s->clause[p], b = s->clause[q];
    int x = -1, y = -1;
    for (int i = 0; i < a.count; i++) if (sp_guard(s, a.literal[i]) == pivot + 1) x = i;
    for (int i = 0; i < b.count; i++) if (sp_guard(s, b.literal[i]) == pivot + 1) y = i;
    if (x < 0 || y < 0 || a.literal[x].negative == b.literal[y].negative || b.count > INT_MAX - a.count) return -1;
    sp_scratch_reset(s);
    SpLiteral *out = sp_allocate(s, &s->scratch, (size_t)a.count + (size_t)b.count, sizeof *out);
    if (!out) return -1;
    int count = 0;
    for (int i = 0; i < a.count; i++) if (i != x) out[count++] = a.literal[i];
    for (int i = 0; i < b.count; i++) if (i != y) out[count++] = b.literal[i];
    return sp_keep(s, out, count, (SpStep){.rule=SP_RESOLVE, .p=p, .lp=x, .q=q, .lq=y}, -1);
}

/* Ricostruisce una clausola appresa con RUP: si assumono falsi i suoi
 * letterali e si propagano soltanto clausole precedenti, gia giustificate.
 * Un conflitto si risolve all'indietro con le ragioni delle propagazioni;
 * restano soltanto negazioni delle assunzioni. La sottoclausola risultante
 * e quindi una conseguenza per risoluzione, anche se piu forte del target.
 * target vuoto richiede una contraddizione senza assunzioni.
 * Ritorna la clausola FO ricostruita, -1 se non riesce: UNSAT non basta. */
static int sp_rup(SpState *s, const SatLiteral *target, size_t count, size_t before) {
    memset(s->rup_value, 0, (size_t)s->components * sizeof *s->rup_value);
    memset(s->rup_reason, 0, (size_t)s->components * sizeof *s->rup_reason);
    for (size_t i = 0; i < count && sp_visit(s); i++) {
        size_t v = sat_index(target[i]);
        if (v < 2 || v - 2 >= (size_t)s->components) return -1;
        int value = target[i] < 0 ? 1 : -1;
        if (s->rup_value[v - 2] && s->rup_value[v - 2] != value) return -1;
        s->rup_value[v - 2] = (signed char)value;
    }
    int assigned = 0, conflict = -1, changed = 1;
    while (changed && conflict < 0 && !s->limited) {
        changed = 0;
        for (size_t j = 0; j < before && conflict < 0 && sp_visit(s); j++) {
            if (!s->sat_proof[j]) return -1;
            int id = s->sat_proof[j] - 1;
            SpClause c = s->clause[id];
            int unknown = 0, unit = -1, value = 0, satisfied = 0;
            for (int i = 0; i < c.count && sp_visit(s); i++) {
                int v = sp_guard(s, c.literal[i]) - 1;
                if (v < 0) return -1;
                int truth = s->rup_value[v] * (c.literal[i].negative ? -1 : 1);
                if (truth > 0) { satisfied = 1; break; }
                if (!truth) { unknown++; unit = v; value = c.literal[i].negative ? -1 : 1; }
            }
            if (satisfied) continue;
            if (!unknown) conflict = id;
            else if (unknown == 1) {
                s->rup_value[unit] = (signed char)value; s->rup_reason[unit] = id + 1;
                s->rup_trail[assigned++] = unit; changed = 1;
            }
        }
    }
    if (conflict < 0 || s->limited) return -1;
    while (assigned && sp_visit(s)) {
        int v = s->rup_trail[--assigned], used = 0;
        SpClause c = s->clause[conflict];
        for (int i = 0; i < c.count; i++) used |= sp_guard(s, c.literal[i]) == v + 1;
        if (used) {
            conflict = sp_boolean_resolve(s, conflict, s->rup_reason[v] - 1, v);
            if (conflict < 0) return -1;
        }
    }
    /* Il controllo finale impedisce che un replay incompleto venga usato
     * come ragione della clausola appresa o della clausola vuota. */
    SpClause result = s->clause[conflict];
    for (int i = 0; i < result.count && sp_visit(s); i++) {
        int present = 0;
        for (size_t j = 0; j < count && sp_visit(s); j++) present |= sp_boolean(s, result.literal[i]) == target[j];
        if (!present) return -1;
    }
    return s->limited ? -1 : conflict;
}

/* Traduce tutte le clausole apprese del CDCL in risoluzioni esplicite,
 * rispettandone l'ordine, poi ricostruisce il conflitto finale. Il replay
 * conserva esattamente i propri risultati, senza sussunzioni euristiche
 * e senza inviarli di nuovo al SAT. Una mancata ricostruzione e UNKNOWN. */
static int sp_avatar_replay(SpState *s) {
    size_t n = (size_t)s->components;
    if (!n) return 0;
    if (!sp_reserve(s, (void **)&s->rup_value, &s->rup_value_cap, n, sizeof *s->rup_value) ||
        !sp_reserve(s, (void **)&s->rup_reason, &s->rup_reason_cap, n, sizeof *s->rup_reason) ||
        !sp_reserve(s, (void **)&s->rup_trail, &s->rup_trail_cap, n, sizeof *s->rup_trail)) return 0;
    s->replaying = 1;
    int ok = 1;
    for (size_t i = 0; i < s->sat.clauses && ok && s->empty < 0 && sp_visit(s); i++) if (!s->sat_proof[i]) {
        SatClause c = s->sat.clause[i];
        int id = sp_rup(s, s->sat.literal + c.first, c.count, i);
        if (id < 0) ok = 0; else s->sat_proof[i] = id + 1;
    }
    if (ok && s->empty < 0 && !s->limited) ok = sp_rup(s, NULL, 0, s->sat.clauses) >= 0;
    s->replaying = 0;
    return ok && s->empty >= 0 && !s->limited;
}

/* Prima di ogni operazione SAT assegna il lavoro e la memoria ancora
 * disponibili a entrambi i motori. before permette di addebitare soltanto
 * il lavoro nuovo; nessun contatore viene azzerato fra due modelli SAT. */
static int sp_sat_begin(SpState *s, unsigned long long *before) {
    if (!sp_visit(s)) return 0;
    unsigned long long end = saturation_work_limit;
    if (s->quota && s->quota < end) end = s->quota;
    if (s->work >= end) { sp_visit(s); return 0; }
    if (!sp_memory_left(s) || end - s->work > ULLONG_MAX - s->sat.work) { s->limited = 1; return 0; }
    s->sat.memory_limit = s->sat.bytes + sp_memory_left(s);
    s->sat.budget = s->sat.work + end - s->work;
    *before = s->sat.work;
    return 1;
}

/* Registra il costo dell'operazione e traduce il limite locale del SAT
 * in una quota riprendibile soltanto quando non manca memoria e il budget
 * globale consente ancora la strategia successiva. */
static int sp_sat_end(SpState *s, unsigned long long before) {
    s->work += s->sat.work - before;
    if (s->sat.broken) {
        s->limited = 1;
        s->resumable = !s->sat.memory_limited && s->work < saturation_work_limit && s->quota && s->quota < saturation_work_limit;
    }
    return !s->limited;
}

/* Aggiunge nuove componenti e vincoli al livello zero, poi chiede un
 * modello SAT. Il vecchio modello FO resta copiato nelle componenti mentre
 * il CDCL cancella decisioni e propaga. Un modello viene riletto contro
 * tutte le clausole SAT prima di attivare le clausole FO del nuovo ramo.
 * UNSAT richiede invece il replay delle risoluzioni fino al vuoto. */
static int sp_avatar_update(SpState *s) {
    int last = s->clauses;
    while (s->split_cursor < last && sp_visit(s)) {
        sp_split(s, s->split_cursor);
        if (s->limited) return 0;
        s->split_cursor++;
    }
    if (s->limited || !s->avatar_dirty) return !s->limited;
    unsigned long long before;
    if (!sp_sat_begin(s, &before)) return 0;
    SatState *b = &s->sat;
    b->inconsistent = 0;
    for (size_t v = 1; v <= b->variables && sat_spend(b, 1); v++) { b->var[v].value = 0; b->var[v].seen = 0; }
    b->assigned = b->qhead = b->level = 0;
    while (b->variables < (size_t)s->components + 1 && !b->broken) sat_variable(b);
    if (!b->broken) sat_assign(b, 1, 0);
    for (size_t i = 0; i < b->clauses && sat_spend(b, 1); i++) {
        SatClause c = b->clause[i];
        if (c.count == 1 && !sat_assign(b, b->literal[c.first], i + 1)) b->inconsistent = 1;
    }
    if (!sp_sat_end(s, before)) return 0;
    last = s->clauses;
    for (; s->sat_cursor < last && sp_visit(s); s->sat_cursor++) {
        int id = s->sat_cursor; SpClause c = s->clause[id];
        if (c.stage == SP_DELETED || sp_available(s, c) != SP_BOOLEAN) continue;
        sp_scratch_reset(s);
        SatLiteral *literal = sp_allocate(s, &s->scratch, (size_t)c.count, sizeof *literal);
        if (!literal) return 0;
        for (int i = 0; i < c.count; i++) literal[i] = sp_boolean(s, c.literal[i]);
        if (!sp_sat_begin(s, &before)) return 0;
        size_t added = sat_clause(b, literal, (size_t)c.count);
        if (!sp_sat_end(s, before)) return 0;
        if (!sp_reserve(s, (void **)&s->sat_proof, &s->sat_proof_cap, b->clauses, sizeof *s->sat_proof)) return 0;
        if (added) s->sat_proof[added - 1] = id + 1;
    }
    if (!sp_sat_begin(s, &before)) return 0;
    int result = sat_solve(b);
    if (!sp_sat_end(s, before)) return 0;
    if (!sp_reserve(s, (void **)&s->sat_proof, &s->sat_proof_cap, b->clauses, sizeof *s->sat_proof)) return 0;
    if (result < 0) return sp_avatar_replay(s);
    if (!result) return 0;
    for (size_t i = 0; i < b->clauses && sp_visit(s); i++) {
        SatClause c = b->clause[i]; int satisfied = 0;
        for (size_t j = 0; j < c.count && sp_visit(s); j++) satisfied |= sat_value(b, b->literal[c.first + j]) > 0;
        if (!satisfied) return 0;
    }
    if (s->limited) return 0;
    int changed = 0;
    for (int i = 0; i < s->components; i++) {
        int value = b->var[(size_t)i + 2].value;
        if (!value) return 0;
        changed |= s->component[i].value && s->component[i].value != value;
        s->component[i].value = value;
    }
    s->sat_models++; s->avatar_dirty = 0;
    /* Un'estensione del medesimo modello non cambia le inferenze gia
     * esaurite. Riattivarle a ogni nuovo nome darebbe sempre precedenza
     * ai fatti vecchi e affamerebbe le clausole delle istanze. Il ciclo
     * marca invece PENDING la singola clausola interrotta da un vincolo.
     * Se cambia una decisione esistente si riesamina l'intero ramo. */
    int age = s->age; unsigned long long rounds = s->rounds;
    sp_requeue_mode(s, NULL, !changed);
    s->age = age; s->rounds = rounds;
    /* Un contenuto FO unitario del ramo puo avere guardie nel testo della
     * clausola. Proporlo subito evita che la coda dei nomi tecnici rinvii
     * l'obiettivo induttivo; la proprieta resta solo un candidato, non un
     * fatto del ramo. I corpi nuovi verranno suddivisi al giro successivo. */
    if (s->comprehension && !s->limited) {
        int clauses = s->clauses, expansions = s->expansions;
        for (int i = 0; i < clauses && sp_visit(s); i++) if (s->clause[i].stage == SP_PENDING)
            sp_propose_comprehensions(s, i);
        if (s->expansions != expansions) s->avatar_dirty = 1;
    }
    return !s->limited;
}

/* Individua l'unico letterale FO di una clausola, oppure restituisce -1.
 * In AVATAR le altre posizioni possono essere guardie ground; fuori da
 * AVATAR occorre una clausola unitaria nel senso ordinario. */
static int sp_unit_literal(const SpState *s, SpClause c) {
    int at = -1;
    for (int i = 0; i < c.count; i++) if (!s->avatar || !sp_guard(s, c.literal[i])) {
        if (at >= 0) return -1;
        at = i;
    }
    return at;
}

/* Cancella un letterale complementare a un'istanza di una clausola unitaria.
 * Il matching istanzia soltanto l'unita; il bersaglio resta universale sulle
 * sue variabili, rinominate a parte. Risoluzione e sostituzione esplicite
 * giustificano la riduzione. Le guardie dell'unita restano nel risultato:
 * il bersaglio si elimina soltanto se gia le contiene tutte, altrimenti
 * il risolvente vale sotto ipotesi piu forti e non puo sostituirlo. */
static int sp_unit_resolve(SpState *s, int target, int unit) {
    SpClause c = s->clause[target], a = s->clause[unit];
    int at = sp_unit_literal(s, a);
    if (at < 0) return 0;
    SpLiteral u = a.literal[at];
    int redundant = 1;
    for (int i = 0; i < a.count; i++) if (i != at) {
        int present = 0;
        for (int j = 0; j < c.count; j++)
            present |= a.literal[i].negative == c.literal[j].negative && sp_same_atom(a.literal[i], c.literal[j]);
        redundant &= present;
    }
    int offset;
    sp_context(s, unit, target, &offset);
    for (int i = 0; i < c.count && sp_visit(s); i++) {
        SpLiteral l = c.literal[i];
        if (u.negative == l.negative || !!u.right != !!l.right) continue;
        for (int flip = 0; flip < (u.right ? 2 : 1) && sp_visit(s); flip++) {
            sp_scratch_reset(s);
            if (!sp_match_start(s, s->clause[unit].variables)) return 0;
            int left = sp_apply(s, flip ? l.right : l.left, offset, NULL, 0, 0);
            int right = sp_apply(s, flip ? l.left : l.right, offset, NULL, 0, 0);
            if (!sp_match(s, u.left, left) || (u.right && !sp_match(s, u.right, right))) continue;
            SpLiteral *instance = sp_instance(s, c, offset, s->match, s->match_count, 0);
            SpLiteral *source = sp_instance(s, a, 0, s->match, s->match_count, 0);
            if (a.count > INT_MAX - c.count) { s->limited = 1; return 0; }
            SpLiteral *out = sp_allocate(s, &s->scratch, (size_t)a.count + (size_t)c.count, sizeof *out);
            if (!instance || !source || !out) return 0;
            int count = 0;
            for (int j = 0; j < a.count; j++) if (j != at) out[count++] = source[j];
            for (int j = 0; j < c.count; j++) if (j != i) out[count++] = instance[j];
            SpStep step = {.rule=SP_RESOLVE, .p=unit, .lp=at, .q=target, .lq=i};
            step = sp_snapshot(s, step, s->match, s->match_count, 0);
            sp_keep(s, out, count, step, -1);
            if (s->limited) return 0;
            if (redundant) s->clause[target].stage = SP_DELETED;
            return redundant;
        }
    }
    return 0;
}

/* Propagazione unitaria per le clausole nuove delle istanze. Si conserva
 * la prova di ogni riduzione, inclusi i nomi di Tseitin: altrimenti i corpi
 * delle comprensioni si moltiplicherebbero prima di usare base e passo.
 * L'agenda visita ogni clausola nuova; una nuova unita raggiunge anche le
 * clausole precedenti. Un turno visita soltanto il prefisso presente al
 * suo inizio: D(a), D(x)=>D(f(x)) genererebbero altrimenti D(f^n(a)) senza
 * mai lasciare lavorare il ciclo given-clause. Le nuove unita restano
 * nell'agenda del turno successivo, senza un tetto al numero di istanze.
 * Fuori da AVATAR le guardie sono disgiunti ordinari. */
static void sp_unit_propagate(SpState *s) {
    int last = s->clauses;
    while (s->unit_cursor < last && s->empty < 0 && sp_visit(s)) {
        int id = s->unit_cursor++;
        SpClause c = s->clause[id];
        if (c.stage == SP_DELETED || c.stage == SP_HELD || c.stage == SP_LOCKED) continue;
        if (c.stage == SP_BOOLEAN) continue;
        int at = sp_unit_literal(s, c);
        if (at >= 0) {
            int duplicate = 0;
            for (int i = 0; i < s->units && sp_visit(s); i++) {
                SpClause old = s->clause[s->unit[i]];
                if (old.count != c.count || old.variables != c.variables) continue;
                int same = 1;
                for (int j = 0; j < c.count; j++) {
                    int present = 0;
                    for (int k = 0; k < old.count; k++)
                        present |= old.literal[k].negative == c.literal[j].negative && sp_same_atom(old.literal[k], c.literal[j]);
                    same &= present;
                }
                duplicate |= same;
            }
            if (duplicate) { s->clause[id].stage = SP_DELETED; continue; }
            if (s->units == INT_MAX || !sp_reserve(s, (void **)&s->unit, &s->unit_cap, (size_t)s->units + 1, sizeof *s->unit)) {
                s->limited = 1; return;
            }
            s->unit[s->units++] = id;
            for (int i = 0; i < id && s->empty < 0 && sp_visit(s); i++)
                if (s->clause[i].stage != SP_DELETED && s->clause[i].stage != SP_HELD && s->clause[i].stage != SP_LOCKED) sp_unit_resolve(s, i, id);
        } else for (int i = 0; i < s->units && s->empty < 0 && sp_visit(s); i++)
            if (sp_unit_resolve(s, id, s->unit[i])) break;
    }
}

/* Il ciclo given-clause. Le semplificazioni conservano le loro deduzioni;
 * i genitori elaborati restano indirizzabili anche quando diventano
 * ridondanti. Una coda vuota senza contraddizione restituisce sconosciuto. */
static int sp_search(SpState *s) {
    if (s->expansions && !s->expansion[s->expansions - 1].complete) { s->limited = 1; s->resumable = 0; return 0; }
    while (s->empty < 0 && sp_visit(s)) {
        if (s->comprehension) {
            sp_seed_comprehensions(s);
            if (s->empty >= 0 || s->limited) break;
            sp_eliminate_comprehensions(s);
            if (s->empty >= 0 || s->limited) break;
            sp_unit_propagate(s);
            if (s->empty >= 0 || s->limited) break;
        }
        if (s->avatar && (!sp_avatar_update(s) || s->empty >= 0)) break;
        if (s->avatar && s->avatar_dirty) continue;
        int given = sp_select(s);
        if (s->limited) break;
        if (given < 0) {
            if (s->comprehension && s->seed_schema < s->schemas) continue;
            break;
        }
        int last = s->clauses, redundant = 0;
        sp_scratch_reset(s);
        for (int i = 0; i < last && !redundant && sp_visit(s); i++)
            if (s->clause[i].stage == SP_ACTIVE && sp_subsumes(s, s->clause[i], s->clause[given])) redundant = 1;
        if (redundant) { s->clause[given].stage = SP_DELETED; continue; }
        for (int i = 0; i < last && !redundant && sp_visit(s); i++)
            if (s->clause[i].stage == SP_ACTIVE) redundant = sp_demodulate(s, i, given);
        if (redundant) continue;
        s->clause[given].stage = SP_ACTIVE;
        if (s->comprehension) sp_propose_comprehensions(s, given);
        sp_unary(s, given);
        if (s->avatar && s->avatar_dirty) {
            if (s->clause[given].stage == SP_ACTIVE) s->clause[given].stage = SP_PENDING;
            continue;
        }
        for (int i = 0; i < last && s->empty < 0 && s->clause[given].stage == SP_ACTIVE && sp_visit(s); i++) {
            if (s->clause[i].stage != SP_ACTIVE) continue;
            sp_resolve(s, given, i);
            if (s->avatar && s->avatar_dirty) break;
            if (s->empty < 0) sp_superpose(s, given, i);
            if (s->avatar && s->avatar_dirty) break;
            if (i != given && s->empty < 0) sp_superpose(s, i, given);
            if (s->avatar && s->avatar_dirty) break;
        }
        /* Una nuova regola unitaria riscrive anche clausole gia in coda o
         * elaborate: le versioni nuove torneranno nella coda equa. */
        for (int i = 0; i < last && s->empty < 0 && (!s->avatar || !s->avatar_dirty) && sp_visit(s); i++)
            if (i != given && s->clause[i].stage != SP_DELETED &&
                s->clause[i].stage != SP_HELD && s->clause[i].stage != SP_LOCKED) sp_demodulate(s, given, i);
        if (s->avatar && s->avatar_dirty && s->clause[given].stage == SP_ACTIVE) s->clause[given].stage = SP_PENDING;
    }
    return s->empty >= 0 && !s->limited && !s->unsupported;
}

/* Conta o raccoglie i simboli originali distinti di un termine. stamp e
 * l'indice della clausola piu uno, seen evita di contare ripetizioni.
 * frequency e list possono essere NULL: i due passaggi condividono la
 * stessa visita, ma il primo conta e il secondo scrive lo spazio esatto. */
static void sp_sine_term(SpState *s, int term, int stamp, int *seen,
                          size_t *frequency, int *list, size_t *used) {
    if (term <= 0 || !sp_visit(s)) return;
    SpTerm t = s->term[term];
    if (t.symbol < s->inputs && seen[t.symbol] != stamp) {
        seen[t.symbol] = stamp;
        if (*used == (size_t)-1) { s->limited = 1; return; }
        if (frequency) frequency[t.symbol]++;
        if (list) list[*used] = t.symbol;
        (*used)++;
    }
    for (int i = 0; i < t.count; i++) sp_sine_term(s, s->argument[t.first + i], stamp, seen, frequency, list, used);
}

/* Costruisce le incidenze in due passaggi. Ogni simbolo e contato una sola
 * volta per clausola, anche in f(f(x)); Skolem, domini e Tseitin non
 * collegano ipotesi altrimenti distinte soltanto perche sono nomi tecnici.
 * Nessuna clausola viene cambiata, omessa dal deposito o rinumerata.
 * Richiede una clausificazione completa; ritorna uno per l'indice completo,
 * zero se le risorse non sono bastate a costruirlo. */
static int sp_sine_prepare(SpState *s) {
    if (s->limited || s->unsupported) return 0;
    SpSine *g = &s->sine;
    g->first = sp_allocate(s, &s->storage, (size_t)s->initial + 1, sizeof *g->first);
    g->reverse = sp_allocate(s, &s->storage, (size_t)s->inputs + 1, sizeof *g->reverse);
    g->frequency = sp_allocate(s, &s->storage, (size_t)s->inputs, sizeof *g->frequency);
    g->minimum = sp_allocate(s, &s->storage, (size_t)s->initial, sizeof *g->minimum);
    int *seen = sp_allocate(s, &s->scratch, (size_t)s->inputs, sizeof *seen);
    if (s->limited) return 0;
    if (s->inputs) { memset(seen, 0, (size_t)s->inputs * sizeof *seen); memset(g->frequency, 0, (size_t)s->inputs * sizeof *g->frequency); }
    g->first[0] = 0;
    for (int i = 0; i < s->initial && sp_visit(s); i++) {
        size_t used = 0;
        SpClause c = s->clause[i];
        for (int j = 0; j < c.count; j++) {
            sp_sine_term(s, c.literal[j].left, i + 1, seen, g->frequency, NULL, &used);
            sp_sine_term(s, c.literal[j].right, i + 1, seen, g->frequency, NULL, &used);
        }
        if (used > (size_t)-1 - g->first[i]) { s->limited = 1; return 0; }
        g->first[i + 1] = g->first[i] + used;
    }
    if (s->limited) return 0;
    size_t edges = g->first[s->initial];
    g->symbol = sp_allocate(s, &s->storage, edges, sizeof *g->symbol);
    g->clause = sp_allocate(s, &s->storage, edges, sizeof *g->clause);
    size_t *next = sp_allocate(s, &s->scratch, (size_t)s->inputs, sizeof *next);
    if (s->limited) return 0;
    g->reverse[0] = 0;
    for (int i = 0; i < s->inputs; i++) { g->reverse[i + 1] = g->reverse[i] + g->frequency[i]; next[i] = g->reverse[i]; seen[i] = 0; }
    for (int i = 0; i < s->initial && sp_visit(s); i++) {
        size_t used = 0, minimum = (size_t)-1;
        SpClause c = s->clause[i];
        int *list = edges ? g->symbol + g->first[i] : NULL;
        for (int j = 0; j < c.count; j++) {
            sp_sine_term(s, c.literal[j].left, i + 1, seen, NULL, list, &used);
            sp_sine_term(s, c.literal[j].right, i + 1, seen, NULL, list, &used);
        }
        for (size_t j = 0; j < used && sp_visit(s); j++) {
            int symbol = list[j];
            if (g->frequency[symbol] < minimum) minimum = g->frequency[symbol];
            g->clause[next[symbol]++] = i;
        }
        g->minimum[i] = used ? minimum : 0;
    }
    return !s->limited;
}

/* Segna i simboli originali di un elemento della tesi, traducendo i posti
 * del parser nell'ordine del certificato. Le variabili non sono simboli. */
static void sp_sine_goal_term(SpState *s, const Elem *e, unsigned char *goal) {
    if (!e || !sp_visit(s)) return;
    if (e->symbol >= 0 && e->symbol < declared_symbols && s->input_symbol[e->symbol] >= 0)
        goal[s->input_symbol[e->symbol]] = 1;
    sp_sine_goal_term(s, e->arg[0], goal); sp_sine_goal_term(s, e->arg[1], goal);
}

/* La tesi fornisce i simboli inizialmente rilevanti; le ipotesi non li
 * diventano soltanto perche sono scritte nell'enunciato da dimostrare. */
static void sp_sine_goal(SpState *s, const Sentence *n, unsigned char *goal) {
    if (!n || !sp_visit(s)) return;
    sp_sine_goal_term(s, n->left, goal); sp_sine_goal_term(s, n->right, goal);
    sp_sine_goal(s, n->a, goal); sp_sine_goal(s, n->b, goal);
}

/* Chiusura dei trigger di SInE. Un simbolo rilevante s attiva C se la sua
 * frequenza non supera tolerance volte il minimo di C; C rende rilevanti
 * tutti i suoi simboli. Le clausole senza simboli originali sono tenute.
 * Si visitano liste inverse, non tutte le clausole per ogni nuovo simbolo.
 * Richiede sp_sine_prepare riuscita. selected ha initial celle e viene
 * riempito; tolerance deve essere >0. Ritorna uno se la chiusura e completa,
 * zero con limited se le risorse non sono bastate. */
static int sp_sine_select(SpState *s, const unsigned char *goal, unsigned tolerance, unsigned char *selected) {
    if (s->limited || s->unsupported) return 0;
    const SpSine *g = &s->sine;
    int *queue = sp_allocate(s, &s->scratch, (size_t)s->inputs, sizeof *queue);
    unsigned char *relevant = sp_allocate(s, &s->scratch, (size_t)s->inputs, 1);
    if (s->limited) return 0;
    int count = 0;
    for (int i = 0; i < s->inputs; i++) { relevant[i] = goal[i]; if (goal[i]) queue[count++] = i; }
    for (int i = 0; i < s->initial; i++) selected[i] = g->minimum[i] == 0;
    for (int at = 0; at < count && sp_visit(s); at++) {
        int symbol = queue[at];
        for (size_t j = g->reverse[symbol]; j < g->reverse[symbol + 1] && sp_visit(s); j++) {
            int clause = g->clause[j]; size_t minimum = g->minimum[clause];
            if (selected[clause] || (minimum <= (size_t)-1 / tolerance && g->frequency[symbol] > tolerance * minimum)) continue;
            selected[clause] = 1;
            for (size_t k = g->first[clause]; k < g->first[clause + 1] && sp_visit(s); k++) {
                int next = g->symbol[k];
                if (!relevant[next]) { relevant[next] = 1; queue[count++] = next; }
            }
        }
    }
    return !s->limited;
}

/* Portafoglio in ordine: SInE stretto, SInE con tolleranza due e maggiore
 * frequenza delle scelte per eta, AVATAR, infine il ciclo ordinario con
 * tutte le ipotesi. AVATAR ha meta del lavoro rimasto e un secondo CPU;
 * le sue definizioni e clausole conservano validita nella ripartenza.
 * Ogni tentativo filtrato ha al piu un ottavo del lavoro rimasto e un
 * quarto di secondo CPU; con formule su parti usa un trentaduesimo,
 * perche i filtri FO non ne generano ancora le istanze. L'ultimo usa
 * il budget globale. Una firma vuota o un insieme gia
 * ristretto al massimo non richiedono ricerche filtrate ridondanti.
 * s contiene la clausificazione completa di root. Ritorna uno soltanto
 * per una refutazione, zero per una ricerca incompleta; tutti i passi
 * continuano a riferirsi alle clausole originali. */
static int sp_portfolio(SpState *s, const Sentence *root) {
    if (s->limited || s->unsupported) return 0;
    if (s->empty >= 0 || !s->inputs) { s->comprehension = s->schemas != 0; return sp_search(s); }
    sp_scratch_reset(s);
    if (!sp_sine_prepare(s)) return 0;
    unsigned char *goal = sp_allocate(s, &s->storage, (size_t)s->inputs, 1);
    if (!goal) return 0;
    memset(goal, 0, (size_t)s->inputs);
    sp_sine_goal(s, root->kind == S_IMPLIES ? root->b : root, goal);
    if (s->limited) return 0;
    for (int phase = 1; phase <= 4; phase++) {
        s->strategy = phase;
        s->quota = 0; s->cpu_quota = 0;
        s->avatar = phase == 3;
        s->comprehension = phase >= 3 && s->schemas != 0;
        if (phase == 3) s->avatar_dirty = 1;
        if (phase == 4) sat_clear(&s->sat);
        sp_scratch_reset(s);
        unsigned char *selected = NULL;
        if (phase < 3) {
            selected = sp_allocate(s, &s->scratch, (size_t)s->initial, 1);
            if (s->initial && !selected) return 0;
            if (!sp_sine_select(s, goal, (unsigned)phase, selected)) return 0;
        }
        int held = sp_requeue(s, selected);
        if (s->limited) return 0;
        if (phase < 3) {
            unsigned long long share = (saturation_work_limit - s->work) / (s->schemas ? 32 : 8);
            if (!held || !share) continue;
            s->quota = s->work + share;
            s->started = clock(); s->cpu_quota = CLOCKS_PER_SEC / 4 ? CLOCKS_PER_SEC / 4 : 1;
        } else if (phase == 3) {
            unsigned long long share = (saturation_work_limit - s->work) / 2;
            if (!share) continue;
            s->quota = s->work + share;
            s->started = clock(); s->cpu_quota = CLOCKS_PER_SEC;
        }
        s->age_interval = phase == 2 ? 2 : 5;
        if (sp_search(s)) { s->quota = 0; s->cpu_quota = 0; return 1; }
        if (s->limited && !s->resumable) return 0;
        s->limited = s->resumable = 0;
    }
    s->quota = 0; s->cpu_quota = 0;
    return 0;
}

/* Scrive un termine nel protocollo indipendente. I simboli sono numeri
 * della traduzione, non posti nella tabella di termini del motore. */
static void sp_cert_term(const SpState *s, int t) {
    if (t < 0) { cert_add("(v %d)", -t - 1); return; }
    SpTerm n = s->term[t];
    cert_add("(f %d", n.symbol);
    for (int i = 0; i < n.count; i++) { cert_add(" "); sp_cert_term(s, s->argument[n.first + i]); }
    cert_add(")");
}

/* Scrive la clausola normalizzata che il checker deve ritrovare esattamente. */
static void sp_cert_clause(const SpState *s, SpClause c) {
    cert_add("(clause");
    for (int i = 0; i < c.count; i++) {
        SpLiteral l = c.literal[i];
        if (!l.left) cert_add(l.negative ? " (false)" : " (true)");
        else {
            cert_add(" (%s ", l.right ? l.negative ? "ne" : "eq" : l.negative ? "neg" : "pos");
            sp_cert_term(s, l.left);
            if (l.right) { cert_add(" "); sp_cert_term(s, l.right); }
            cert_add(")");
        }
    }
    cert_add(")");
}

/* Nomi matematici dei simboli introdotti: D per i domini, k per Skolem,
 * P per le sottoformule. I simboli dichiarati conservano la loro scrittura. */
static void sp_put_term(const SpState *s, int t) {
    if (t < 0) { proof_add("x_{%d}", -t - 1); return; }
    SpTerm n = s->term[t];
    if (n.symbol < s->inputs) put_symbol(s->original_symbol[n.symbol]);
    else if (s->symbol[n.symbol].component) proof_add("b_{%d}", s->symbol[n.symbol].component - 1);
    else if (n.symbol < s->inputs + sort_count) proof_add("D_{%d}", n.symbol - s->inputs);
    else proof_add("%s_{%d}", s->symbol[n.symbol].predicate ? "P" : "k", n.symbol);
    if (n.count) proof_add("(");
    for (int i = 0; i < n.count; i++) { if (i) proof_add(","); sp_put_term(s, s->argument[n.first + i]); }
    if (n.count) proof_add(")");
}

/* Rende una disgiunzione come formula; la clausola vuota e il falso. */
static void sp_put_clause(const SpState *s, SpClause c) {
    if (!c.count) { proof_add("\\bot"); return; }
    for (int i = 0; i < c.count; i++) {
        SpLiteral l = c.literal[i];
        if (i) proof_add(" \\lor ");
        if (!l.left) proof_add(l.negative ? "\\bot" : "\\top");
        else {
            if (!l.right && l.negative) proof_add("\\lnot ");
            sp_put_term(s, l.left);
            if (l.right) { proof_add(l.negative ? " \\ne " : " = "); sp_put_term(s, l.right); }
        }
    }
}

/* Scrive gli antenati del vuoto e tutti i comandi che introducono nomi.
 * I comandi mantengono la firma e gli indici anche quando la loro prima
 * clausola non e fra gli antenati. Le clausole iniziali mantengono
 * i loro indici; gli altri passi vengono rinumerati dopo quelle iniziali,
 * cosi omettere ricerche inutilizzate non cambia un riferimento del checker. */
static void sp_write(SpState *s, const Sentence *root, const Sentence *const *laws, int law_count, long long compared) {
    if (s->empty < 0 || (s->expansions && !s->expansion[s->expansions - 1].complete)) { s->limited = 1; return; }
    sp_scratch_reset(s);
    unsigned char *needed = sp_allocate(s, &s->scratch, (size_t)s->clauses, 1);
    int *number = sp_allocate(s, &s->scratch, (size_t)s->clauses, sizeof *number);
    if (!needed || !number) return;
    memset(needed, 0, (size_t)s->clauses);
    needed[s->empty] = 1;
    for (int i = s->empty; i >= s->initial; i--) if (needed[i]) {
        SpStep step = s->clause[i].step;
        if (step.rule == SP_COMPONENT || step.rule == SP_COMPLEMENT || step.rule == SP_COMPREHEND) continue;
        needed[step.p] = 1;
        if (step.rule == SP_RESOLVE || step.rule == SP_SUPER) needed[step.q] = 1;
    }
    int count = s->initial;
    for (int i = 0; i < s->clauses; i++) number[i] = i < s->initial ? i : -1;
    /* I comandi non dipendono da genitori FO: le proprieta sono formule,
     * non fatti assunti. Si possono anticipare ai passi conservando il
     * loro ordine comune, necessario per simboli e formule annidate. */
    for (int i = 0; i < s->introductions; i++) {
        SpIntroduction event = s->introduction[i];
        if (event.kind == SP_COMPONENT) {
            SpComponent c = s->component[event.index];
            if (count > INT_MAX - 2) { s->limited = 1; return; }
            if (c.forward >= 0) number[c.forward] = count;
            count++;
            if (!c.key.variables && c.key.count == 1) {
                if (c.reverse >= 0) number[c.reverse] = count;
                count++;
            }
        } else {
            SpExpansion e = s->expansion[event.index];
            if (!e.complete || e.past - e.first > INT_MAX - count) { s->limited = 1; return; }
            for (int j = e.first; j < e.past; j++) number[j] = count++;
        }
    }
    for (int i = s->initial; i < s->clauses; i++) if (needed[i] && s->clause[i].step.rule != SP_COMPONENT &&
            s->clause[i].step.rule != SP_COMPLEMENT && s->clause[i].step.rule != SP_COMPREHEND) {
        if (count == INT_MAX) { s->limited = 1; return; }
        number[i] = count++;
    }
    cert_abstract_head("saturation", root, NULL);
    for (int i = 0; i < law_count; i++) { cert_add("axiom "); cert_sentence(laws[i], SLOT_VALUES_EMPTY); cert_add("\n"); }
    cert_add(s->forward ? "clausify forward\n" : "clausify\n");
    proof_reset(); proof_growable = 1;
    proof_add("\\textbf{Proof.} By contradiction and saturation. Each domain predicate $D_i$ denotes membership in its set. "
              "Negation normal form, Skolem functions with their universal parameters, and predicates for subformulas give clauses; "
              "all free variables of each clause are universal and are renamed apart before an inference. "
              "The initial clauses used below and every derived step are:\n\\begin{itemize}\n");
    for (int i = 0; i < s->introductions; i++) {
        SpIntroduction event = s->introduction[i];
        if (event.kind == SP_COMPONENT) {
            SpComponent c = s->component[event.index];
            cert_add("component "); sp_cert_clause(s, c.key); cert_add("\n");
            if (!c.key.variables && c.key.count == 1) cert_add("complement %d\n", event.index);
            proof_add("\\item Define $b_{%d}\\iff ", event.index);
            for (int j = 0; j < c.key.variables; j++) proof_add("\\forall x_{%d}\\ ", j);
            proof_add("("); sp_put_clause(s, c.key); proof_add(")$.\n");
        } else {
            SpExpansion e = s->expansion[event.index];
            SpClause property = {.count=1, .literal=&e.property};
            cert_add("comprehend %d ", e.schema); sp_cert_clause(s, property); cert_add("\n");
            proof_add("\\item Instantiate the universal part formula $ ");
            SpSchema schema = s->schema[e.schema];
            put_sentence(schema.source, !schema.positive, SLOT_VALUES_EMPTY, 0);
            proof_add("$ with $\\{x_0\\in "); put_sort(symbols[schema.source->part].domain[0]);
            proof_add("\\mid "); sp_put_clause(s, property); proof_add("\\}$.\n");
        }
    }
    static const char *const rule[] = {"input", "resolve", "reflex", "factor", "super", "equalfactor", "component", "complement", "split", "comprehend"};
    static const char *const description[] = {"clausification", "resolution", "equality resolution", "factoring", "superposition", "equality factoring", "component definition", "ground complement", "variable-disjoint splitting", "comprehension instantiation"};
    for (int i = 0; i < s->clauses; i++) {
        SpClause c = s->clause[i]; SpStep step = c.step;
        if (!needed[i]) continue;
        proof_add("\\item $(C_{%d})\\quad ", number[i]); sp_put_clause(s, c); proof_add("$.");
        if (i < s->initial) { proof_add(" By clausification.\n"); continue; }
        if (step.rule == SP_COMPONENT || step.rule == SP_COMPLEMENT) { proof_add(" By %s.\n", description[step.rule]); continue; }
        if (step.rule == SP_COMPREHEND) { proof_add(" By comprehension and clausification.\n"); continue; }
        proof_add(" By %s from $(C_{%d})$", description[step.rule], number[step.p]);
        if (step.rule == SP_RESOLVE || step.rule == SP_SUPER) proof_add(" and $(C_{%d})$", number[step.q]);
        if (step.bindings) {
            proof_add(", with $");
            for (int j = 0; j < step.bindings; j++) {
                if (j) proof_add(",\\ ");
                proof_add("x_{%d}\\mapsto ", step.binding[j].variable); sp_put_term(s, step.binding[j].term);
            }
            proof_add("$");
        }
        proof_add(".\n");
        if (step.rule == SP_SPLIT) {
            cert_add("step split %d (groups", number[step.p]);
            for (int j = 0; j < step.groups; j++) {
                SpGroup g = step.group[j];
                cert_add(" (%d %d", g.component, g.negative);
                for (int k = 0; k < g.count; k++) cert_add(" %d", g.literal[k]);
                cert_add(")");
            }
            cert_add(") "); sp_cert_clause(s, c); cert_add("\n");
            continue;
        }
        cert_add("step %s %d %d", rule[step.rule], number[step.p], step.lp);
        if (step.rule == SP_RESOLVE) cert_add(" %d %d", number[step.q], step.lq);
        else if (step.rule == SP_SUPER) cert_add(" %d %d %d %d %d", step.flip, number[step.q], step.lq, step.side, step.position);
        else if (step.rule == SP_FACTOR) cert_add(" %d", step.lq);
        else if (step.rule == SP_EQUAL_FACTOR) cert_add(" %d %d %d", step.flip, step.lq, step.otherflip);
        cert_add(" (subst");
        for (int j = 0; j < step.bindings; j++) {
            cert_add(" (%d ", step.binding[j].variable); sp_cert_term(s, step.binding[j].term); cert_add(")");
        }
        cert_add(") "); sp_cert_clause(s, c); cert_add("\n");
    }
    cert_add("end\n");
    proof_add("\\end{itemize}\nThe empty clause is a contradiction. Every inference and the initial clausification "
              "are checked independently by the certificate verifier.");
    put_unfolding_note(compared); proof_add(" $\\Box$");
}

/* Nodi trattati dalla saturazione: primo ordine e astrazioni dei
 * quantificatori su parti con istanze di comprensione. Una parte non viene
 * confusa con un elemento; l'equipotenza conserva la propria strategia. */
static int sp_supported_formula(const Sentence *root) {
    switch (root->kind) {
    case S_TRUE: case S_EQUAL: case S_HOLDS: return 1;
    case S_NOT: case S_FORALL: case S_EXISTS: case S_FORALL_PART: case S_EXISTS_PART: return sp_supported_formula(root->a);
    case S_AND: case S_OR: case S_IMPLIES: case S_IFF: return sp_supported_formula(root->a) && sp_supported_formula(root->b);
    default: return 0;
    }
}

/* Cerca una refutazione e la consegna soltanto attraverso ck_check.
 * Ritorna uno se e arrivata al controllo di un certificato, compreso un
 * eventuale rifiuto che deve restare visibile come errore del motore.
 * Zero significa ricerca incompleta: le altre strategie possono proseguire. */
static int saturation_attempt(const Sentence *root, const Sentence *const *laws, int law_count,
                               long long compared, Verdict *verdict) {
    if (!sp_supported_formula(root)) return 0;
    SpState state = {0};
    if (!sp_prepare(&state, root, laws, law_count) || !sp_portfolio(&state, root)) { sp_clear(&state); return 0; }
    /* Se il vuoto e gia nella negazione della tesi, non servono leggi
     * aggiuntive dopo di esso: si riscrive la sola refutazione della tesi. */
    if (state.empty < state.initial && state.empty + 1 < state.initial) {
        sp_clear(&state);
        if (!sp_prepare(&state, root, NULL, 0) || !sp_portfolio(&state, root)) { sp_clear(&state); return 0; }
        law_count = 0;
    }
    sp_write(&state, root, laws, law_count, compared);
    if (state.limited || proof_broken) { sp_clear(&state); return 0; }
    verdict->outcome = PROVED;
    verdict->method = "per saturazione di clausole";
    verdict->proof = proof_text;
    *verdict = abstract_certified(*verdict);
    sp_clear(&state);
    return 1;
}

/* Decide l'enunciato su insiemi qualsiasi scritto in formula e ne ritorna
 * il verdetto, come descritto in testa al capitolo: prima i modelli finiti,
 * che possono smentirlo (o, se chiede un esempio, dimostrarlo); poi la
 * dimostrazione per assurdo di ogni affermazione della tesi. In tutti e due
 * i casi il verdetto vale solo con il certificato accettato (28f).
 *
 * Svuota l'arena: i risultati di chiamate precedenti non sono più validi. */
static Verdict prove_abstract(const char *formula) {
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, "con istanze delle ipotesi e uguali al posto di uguali", NULL, NULL};
    static Model model;
    const Sentence *hypothesis[MAX_KNOWN / 8], *claim[MAX_KNOWN / 8];
    SlotValues nothing = SLOT_VALUES_EMPTY;
    long long tried;
    int bound;

    /* Ripartenza da zero e parsing. Il modello precedente non serve piu. */
    model_clear(&model);
    model_unconfirmed = NULL;
    proof_reset();
    arena_used = arena_keep;
    failure = NULL;
    syntax_error = NULL;
    cursor = formula;
    next_token();
    const Sentence *written = abstract_statement();
    if (syntax_error || failure) { verdict.reason = syntax_error ? syntax_error : failure; return verdict; }

    declared_symbols = symbol_count;
    if (!proof_symbols_reserve((size_t)symbol_count)) { verdict.reason = OUT_OF_MEMORY; return verdict; }
    if (symbol_count) memset(symbol_generation, 0, (size_t)symbol_count * sizeof *symbol_generation);
    if (symbol_count) memset(symbol_law, 0, (size_t)symbol_count * sizeof *symbol_law);

    /* 17q, 28h. La notazione dei libri, se c'è, si svolge; e lo svolgimento
     * si ricontrolla sui modelli finiti prima di ragionare sull'enunciato
     * svolto. Se non è d'accordo con l'enunciato scritto è un errore del
     * programma: nessun verdetto. */
    const Sentence *root = written;
    long long compared = 0;
    if (sentence_has_book_notation(written)) {
        root = abstract_unfold(written);

        /* Anche l'arena piena: lo svolgimento raddoppia l'enunciato a ogni
         * \exists!, e con 22 uno dentro l'altro la riempie. L'albero
         * incompleto non va calcolato sui modelli. */
        if (syntax_error || failure) { verdict.reason = syntax_error ? syntax_error : failure; return verdict; }
        compared = book_check(written, root);
        if (compared < 0) {
            unjustified_steps++;
            verdict.outcome = NOT_PROVED;
            verdict.reason = "lo svolgimento della notazione degli insiemi, ricalcolato sui modelli finiti, non dà lo stesso enunciato";
            return verdict;
        }
        if (compared == 0) {
            verdict.outcome = NOT_PROVED;
            verdict.reason = "lo svolgimento della notazione degli insiemi non si è potuto ricontrollare: l'enunciato è troppo lungo da calcolare anche sul modello più piccolo";
            return verdict;
        }
    }

    /* 28a. I modelli finiti. Per chi chiede un esempio, uno in cui la
     * condizione vale; per gli altri, uno in cui non vale. */
    int model_symbols = symbol_count;
    int found = model_search(root, abstract_example, &model, &tried, &bound);
    /* Prima una quota breve, poi la dimostrazione, infine il budget
     * rimasto. Un universale vero non consuma tutto il model finding prima
     * che le sue ipotesi siano usate. Le richieste di esempio usano subito
     * il budget intero, perche li la ricerca e tutto il procedimento. */
    unsigned long long first_work = abstract_example ? model_work_limit : model_work_limit / 16;
    if (!first_work) first_work = 1;
    unsigned long long remaining_work = model_work_limit - first_work;
    if (!found) found = model_sat_slice(root, abstract_example, &model, &tried, bound, first_work);
    if (found) return abstract_model_result(verdict, written, root, &model, compared);
    verdict.outcome = NOT_PROVED;

    /* 17v, 28m. Un enunciato che parla solo dei numeri che scrive, con
     * relazioni date dall'elenco delle loro coppie, non ha nulla da scegliere:
     * i suoi insiemi sono quei numeri, tutti diversi, e ogni simbolo ha la
     * sua tabella. Ha un solo modello, e quello che vi si calcola è il suo
     * valore. Un conto finito e completo: se il modello non lo smentisce
     * (sopra), l'enunciato vale. Il verificatore rifà il conto sullo stesso
     * modello (11b e 11i in checker.c). */
    int concrete = !plain_sorts() && !abstract_example;
    for (int s = 0; s < symbol_count && concrete; s++) concrete = symbol_fixed(s);
    if (concrete && model_search(root, 1, &model, &tried, &bound)) {
        size_t *value = model_variables();
        if (work_allocation_failed) { verdict.reason = OUT_OF_MEMORY; return verdict; }
        model_steps = 0;
        int holds = model_holds(&model, root, value) && (written == root || book_holds(&model, written, value));
        if (!model_steps_complete()) {
            verdict.reason = "il conto sui numeri dell'enunciato supera il budget dei passi (--model-steps)";
            return verdict;
        }
        if (!holds) {
            unjustified_steps++;
            verdict.reason = "la verifica indipendente non conferma il conto sui numeri dell'enunciato";
            return verdict;
        }
        proof_add("\\textbf{Proof.} The statement speaks only of the numbers it writes, which are distinct and are all its elements, "
                  "and every set in it is given by the list of its members: there is nothing to choose, and computing with them "
                  "the statement holds.");
        put_unfolding_note(compared);
        proof_add(" $\\Box$");
        verdict.outcome = PROVED;
        verdict.method = "con un conto sui numeri dell'enunciato";
        verdict.proof = proof_text;
        cert_abstract_head("example", root, &model);
        cert_add("end\n");
        return abstract_certified(verdict);
    }
    if (abstract_example) {
        verdict.reason = model_unconfirmed ? model_unconfirmed : "nessun esempio trovato entro il budget di ricerca dei modelli: può essercene uno";
        return verdict;
    }

    /* 28u. La prova per clausole e controllata senza un campione finito:
     * puo quindi precedere la cautela che resta per la ricerca per istanze. */
    /* 28n. Le leggi delle parti e delle applicazioni, dopo le ipotesi:
     * anche loro sono condizioni vere, e il certificato le porta. Se le
     * lettere per scriverle non bastano, la ricerca va avanti senza. */
    const char *before_axioms = syntax_error;
    axioms_prepare();
    if (syntax_error != before_axioms) { axiom_count = 0; syntax_error = before_axioms; }
    bijection_prepare(root);
    if (saturation_attempt(root, axioms, axiom_count, compared, &verdict)) return verdict;
    proof_reset();

    /* Senza il controllo indipendente non si dimostra: se nemmeno i modelli
     * con un elemento per insieme sono stati provati tutti, ci si ferma. */
    if (bound < 1) {
        symbol_count = model_symbols;
        if (model_sat_slice(root, 0, &model, &tried, bound, remaining_work))
            return abstract_model_result(verdict, written, root, &model, compared);
        verdict.reason = model_unconfirmed ? model_unconfirmed : "i modelli con pochi elementi sono troppi per provarli: manca il controllo indipendente";
        return verdict;
    }

    /* 28b-28g. La dimostrazione: ipotesi e tesi, un'affermazione per
     * volta. */
    const Sentence *thesis = root->kind == S_IMPLIES ? root->b : root;
    int hypotheses = root->kind == S_IMPLIES ? conjuncts(root->a, hypothesis, 0, MAX_KNOWN / 8) : 0;
    int claims = conjuncts(thesis, claim, 0, MAX_KNOWN / 8), proved = 1;
    exhausted = part_interrupted = 0;
    if (!instance_sorts_reserve()) { verdict.reason=OUT_OF_MEMORY;return verdict; }
    memset(definition_slot,-1,(size_t)sort_count*sizeof *definition_slot);
    cert_abstract_head("structure", root, NULL);

    int given = hypotheses;
    for (int i = 0; i < axiom_count && hypotheses < MAX_KNOWN / 8; i++) hypothesis[hypotheses++] = axioms[i];
    cert_axioms();
    proof_add("\\textbf{Proof.} By contradiction: we suppose that the hypotheses hold and that a claim fails.");
    for (int i = 0; i < hypotheses; i++) {
        if (i == given) proof_add("%s Since every set of parts or of maps here is the set of all of them, these hold too:", given ? "." : "");
        proof_add("%s (H%d) $", i == given ? "" : i ? "," : " The hypotheses:", i + 1);
        put_sentence(hypothesis[i], 0, nothing, 0);
        proof_add("$");
    }
    proof_add("%s\n\\begin{itemize}\n", hypotheses ? "." : "");
    /* 28n. Ogni affermazione prima con le sole estensionalità, che non
     * fanno nascere elementi, poi, se non basta, con le comprensioni: le
     * parti in più servono a poche dimostrazioni e rallentano le altre. Gli
     * assiomi sono in coda alle ipotesi, le estensionalità per prime, quindi
     * la prima prova usa un pezzo iniziale dell'elenco, con gli stessi
     * numeri (H1), (H2), ... */
    int first_pass = given + axioms_extensional();
    for (int i = 0; i < claims && proved && !failure; i++)
        proved = claim_attempts(hypothesis, hypotheses, first_pass, claim[i]) || claim_halves(hypothesis, hypotheses, first_pass, claim[i]);
    /* Nessuna dimostrazione trovata: la quota residua riprende il model
     * finding prima di emettere un esito sconosciuto. Anche dopo una ricerca
     * interrotta, un modello completo resta controllabile da solo. */
    if (!proved || failure) {
        symbol_count = model_symbols;
        if (model_sat_slice(root, 0, &model, &tried, bound, remaining_work))
            return abstract_model_result(verdict, written, root, &model, compared);
    }
    if (failure) {
        /* La memoria è finita durante la ricerca (le copie di 28j): ciò che
         * è stato scritto dopo non vale nulla. */
        verdict.reason = failure;
        return verdict;
    }
    if (!proved) {
        verdict.reason = model_unconfirmed ? model_unconfirmed
                       : exhausted || part_interrupted ? "la ricerca è stata interrotta: troppi elementi o troppe istanze senza arrivare a una dimostrazione"
                                   : "nessun controesempio trovato entro il budget dei modelli; le istanze provate non bastano a dimostrarlo";
        return verdict;
    }
    proof_add("\\end{itemize}\nIndependent check: no choice of nonempty sets with at most $%d$ element%s each, and of tables for what is declared, "
              "contradicts the statement (%lld were tried).", bound, bound == 1 ? "" : "s", tried);
    put_unfolding_note(compared);
    proof_add(" $\\Box$");

    /* Una dimostrazione troncata non è scritta: proof_add() si ferma a
     * PROOF_BYTES, e ciò che manca può essere un caso intero. Le
     * dimostrazioni di 28r sono le più lunghe del capitolo, e l'hanno
     * mostrato. */
    if (proof_length >= PROOF_BYTES - 1) {
        verdict.reason = "la dimostrazione trovata è più lunga di quanto il programma sappia scrivere";
        return verdict;
    }
    verdict.outcome = PROVED;
    verdict.proof = proof_text;

    /* Il certificato: i casi scritti da abstract_claim(), con i nomi e le
     * istanze dei rami (28f). */
    cert_add("end\n");
    return abstract_certified(verdict);
}

/* =============================================================================
 * 29. LIMITI
 * ============================================================================
 *
 * A che cosa serve. "Il limite di (1 - cos x)/x^2 per x che tende a 0 è
 * 1/2": l'enunciato arriva nella notazione di parse_limit_statement() (9i),
 * come affermazione da controllare, \lim_{x \to a} f = L, oppure come
 * richiesta, \lim_{x \to a} f, a cui si risponde RISOLTO con il valore. Il
 * metodo è uno solo, quello delle serie troncate con coefficienti esatti:
 * non c'è una formula per i limiti notevoli, una per de l'Hôpital, una per
 * le forme 1^\infty. Sono tutti casi della stessa aritmetica.
 *
 * 29a. IL PUNTO, I LATI, LA LETTERA t
 *
 * Ogni limite si porta a una lettera t > 0 che tende a 0: da destra di a si
 * scrive x = a + t, da sinistra x = a - t, a +\infty x = 1/t, a -\infty
 * x = -1/t. Un limite senza lato in un punto finito è fatto dei due limiti
 * da destra e da sinistra: esiste se tutti e due esistono e sono uguali, e
 * non esiste, dimostratamente, se sono diversi. Il limite è preso dentro il
 * campo di esistenza (29h): se da un lato la funzione non ha valori, conta
 * solo l'altro; se non ne ha da nessuno dei due, il punto non è di
 * accumulazione e il limite non ha senso.
 *
 * 29b. LE SERIE TRONCATE
 *
 * Una serie è una somma finita di termini c t^{k/D}, con c esatto, più un
 * resto O(t^{p/D}): una funzione che, per t piccolo, è al più una costante
 * per t^{p/D}. D, il denominatore comune degli esponenti, è 1 per i
 * polinomi e cresce con le radici (sqrt(t) = t^{1/2}: le serie di Puiseux).
 * Gli esponenti possono essere negativi: a +\infty x = t^{-1}. Il teorema
 * su cui tutto si regge è quello di Taylor con il resto di Peano: una
 * funzione con n derivate continue in u0 vale
 *
 *     g(u0 + w) = g(u0) + g'(u0) w + ... + g^{(n)}(u0) w^n / n! + o(w^n),
 *
 * e se w = O(t^v) con v > 0 il resto è O(t^{(n+1) v}). Somma e prodotto di
 * due serie sono una serie, con il resto che si calcola: (A + O(t^p))(B +
 * O(t^q)) = AB + O(t^{min(p + val B, q + val A)}), dove val è l'esponente
 * più basso. Il resto può anche non tendere a zero: O(t^0) è una funzione
 * limitata. Così sin(1/x) vicino a 0 è O(1), e x sin(1/x) è O(t): tende a
 * 0 anche se sin(1/x) non ha limite. Una serie esatta non ha resto. Quando
 * i coefficienti contengono la lettera L di 29d il resto vale a meno di una
 * potenza di L: O(t^{E}) vuol dire al più C t^{E} L^{m} (lim_logs).
 *
 * 29c. IL TERMINE PRINCIPALE E IL QUOZIENTE
 *
 * Il termine principale di una serie è il primo coefficiente diverso da
 * zero: se è c t^e, la funzione è c t^e (1 + o(1)), ha il segno di c, e
 * tende a +\infty o -\infty se e < 0, a c se e = 0, a 0 se e > 0. Decidere
 * che un coefficiente è zero è un conto esatto (il test di annullamento,
 * capitolo 12); che non lo è, e il suo segno, li dicono gli intervalli del
 * capitolo 24, e solo quando sono certi. Un coefficiente di cui non si sa
 * nulla ferma il conto: NON DIMOSTRATO. Se tutti i coefficienti noti sono
 * zero e il resto non tende a zero, si ricomincia con più termini: è ciò
 * che si fa a mano quando uno sviluppo al primo ordine "si cancella".
 * Dividere per una serie vuol dire 1/(c t^e (1 + u)) = c^{-1} t^{-e}
 * (1 - u + u^2 - ...), con u = O(t^{1/D}): l'ordine si sposta di -e. Il
 * limite di un quoziente è quindi il quoziente dei termini principali:
 * l'idea di de l'Hôpital, senza derivate.
 *
 * 29d. LA SCALA DEI LOGARITMI
 *
 * ln(c t^e (1 + u)) = ln c - e L + ln(1 + u), con L = ln(1/t), che tende a
 * +\infty più lentamente di ogni potenza di 1/t. I coefficienti possono
 * contenere la lettera L, anche al denominatore: x ln x da destra di 0 è
 * -L t, e tende a 0 perché t L tende a 0. Il termine principale di un
 * coefficiente c(L) è la sua potenza più alta in L: c(L) ~ k L^d. Un
 * esponenziale con L nel termine costante, e^{a + b L}, è e^a t^{-b} se b è
 * razionale: così x^x = e^{x ln x} e x^{1/x} = e^{(ln x)/x} hanno una serie.
 *
 * 29e. LE FUNZIONI
 *
 * Ogni funzione elementare entra con la sua serie di Taylor nel punto u0 a
 * cui tende l'argomento, con coefficienti esatti:
 *
 *     e^{u0 + w} = e^{u0} (1 + w + w^2/2 + ...),
 *     ln(c t^e (1 + w)) come in 29d, con ln(1 + w) = w - w^2/2 + ...,
 *     sin(u0 + w) = sin u0 cos w + cos u0 sin w, e il coseno allo stesso modo,
 *     arctan(u0 + w) = arctan u0 + arctan(w / (1 + u0 (u0 + w))),
 *     (c t^e (1 + w))^q = c^q t^{e q} (1 + q w + q (q - 1)/2 w^2 + ...);
 *
 * tangente e cotangente sono quozienti; le funzioni iperboliche arrivano
 * già scritte con queste (9h), e arcoseno e arcocoseno si riscrivono qui
 * con l'arcotangente (arcsin_by_arctan()). Quando l'argomento non
 * tende a un numero valgono regole a parte: e^{u} con u che tende a
 * -\infty è più piccolo di ogni potenza di t (una funzione "piatta": la
 * serie è 0 + O(t^n) per ogni n); arctan u con u che tende a +\infty o
 * -\infty è \pm \pi/2 - arctan(1/u); seno e coseno di qualunque cosa sono
 * O(1).
 *
 * 29f. LE FORME ESPONENZIALI
 *
 * f^g, con la variabile nell'esponente, vuol dire e^{g ln f}, ed è definita
 * solo dove f > 0: è il campo di esistenza dei libri, e lo stesso che usa
 * la tabella dei segni. Con un esponente numerico intero la potenza è un
 * prodotto, e la base può essere negativa; con uno razionale non intero la
 * base deve essere positiva, tranne che per le radici di indice dispari,
 * scritte con \sqrt[n]{}.
 *
 * 29g. L'ALGEBRA DEI LIMITI
 *
 * Quando una funzione non ha una serie (e^{1/x} da destra di 0 cresce più
 * di ogni potenza) resta il suo limite, e si va avanti con le regole dei
 * limiti sui numeri reali estesi: +\infty + c = +\infty, c / (0^{+}) =
 * \pm\infty con il segno di c, e^{+\infty} = +\infty, e^{-\infty} = 0^{+},
 * una funzione continua g in un numero L dà g(f) -> g(L). Una forma
 * indeterminata (\infty - \infty, 0 \cdot \infty, \infty / \infty) qui non
 * si scioglie: il verdetto è NON DIMOSTRATO.
 *
 * 29h. IL CAMPO DI ESISTENZA VICINO AL PUNTO
 *
 * Ogni operazione che ha una condizione la controlla sul termine
 * principale: un divisore con termine principale c t^e non nullo non si
 * annulla per t piccolo; un radicando, l'argomento di un logaritmo, la base
 * di f^g devono avere c > 0. Se c < 0 la funzione non ha valori da quel
 * lato, per nessun t piccolo: è un fatto, e lo si usa (29a). Un divisore
 * identicamente nullo dà lo stesso. In ogni altro caso dubbio il conto si
 * ferma.
 *
 * 29i. IL CONTROLLO CON I NUMERI
 *
 * Il risultato viene ricontrollato per un'altra strada: la funzione,
 * calcolata direttamente dall'albero con gli intervalli del capitolo 24
 * (node_range(), che non sa nulla di serie), nei punti x = a \pm 2^{-k}, o
 * x = \pm 2^{k} all'infinito. Da ogni lato il conto ha dato più del limite:
 * f - L ~ g(t), oppure f ~ g(t) per un limite infinito, con
 * g = c t^e L^d e^{G} il termine principale (29k: il fattore e^{G} è esatto,
 * e lo si calcola per intero con gli intervalli, L compresa). In quei punti
 * t = 2^{-k} e L = k ln 2; dopo la sostituzione di 29l t = 1/(k ln 2) e
 * L = ln(k ln 2), e i punti arrivano fino a k = 1000 perché L cresce
 * piano. Nei punti in cui l'intervallo è abbastanza stretto, il rapporto
 * (f - L)/g deve stare tra 1/16 e 16 (tende a 1); un punto in cui f o g
 * escono dai numeri della macchina (e^{x} per x = 2^{10}) non si usa. E g
 * deve andare dove va il limite: |g| deve scendere tra due valori lontani
 * di L (10^6 e 10^{12}, o 64 ln 2 e 256 ln 2 con un fattore e^{G}, che lì
 * resta tra i numeri della macchina) se il limite è finito, salire se è
 * infinito; lo si calcola dalla formula di g, in logaritmi, senza f. Che
 * cosa garantisce: un valore L sbagliato, un segno o un ordine sbagliati
 * fanno andare il rapporto a 0 o all'infinito, e lo si vede appena t è
 * abbastanza piccolo da lasciare indietro i termini successivi; due punti
 * consecutivi fuori dall'intervallo sono una contraddizione, il passo si
 * conta tra quelli non giustificati e il verdetto è NON DIMOSTRATO. Così
 * anche una g che va nella direzione sbagliata: è la regola che dal termine
 * principale ricava il limite (29c, 29k) a essere smentita, che il
 * rapporto da solo non vedrebbe (f ~ g anche se si sbaglia dove va g).
 * Che cosa non garantisce: nulla, da solo, perché un numero finito di
 * valori non decide un limite; e un errore più piccolo di un fattore 16 nel
 * coefficiente principale, o nascosto da una convergenza lentissima, passa.
 * Per questo il controllo conferma e non dimostra: senza almeno un punto
 * che confermi il verdetto è NON DIMOSTRATO. Quando di f - L non si conosce
 * un termine principale ma solo il resto, O(t^{E}), o il fatto che è più
 * piccolo di ogni potenza (una funzione piatta, un fattore e^{G} che va a
 * zero), si chiede |f - L| <= 16 (1 + |L|) t^{B} nell'ultimo punto
 * abbastanza preciso, con B = min(E, 1), o B = 4 se è piatta. Quando il
 * limite viene dall'algebra dei limiti (29g) non c'è nemmeno quello, e si
 * chiede solo che nell'ultimo punto utile f stia vicino a L, o abbia il
 * segno dell'infinito. Lo stesso controllo vale per il campo di esistenza:
 * un lato dichiarato senza valori deve risultare senza valori nei punti più
 * vicini al punto, e viceversa.
 *
 * 29j. IL VERDETTO E LA RISPOSTA RILETTA
 *
 * \lim f = L è DIMOSTRATO se il limite calcolato è L, esattamente; FALSO
 * solo se il limite è stato calcolato (o la sua non esistenza dimostrata,
 * con due limiti da destra e da sinistra diversi) ed è certamente diverso
 * da L; altrimenti NON DIMOSTRATO. Il valore scritto, nella dimostrazione e
 * nella risposta a una richiesta, viene riletto dal testo con il lettore
 * del capitolo 9 e confrontato con quello calcolato, come le soluzioni
 * della tabella dei segni.
 *
 * Il limite di una successione, \lim_{n \to +\infty} a_n, si calcola come
 * quello della funzione con n reale: se questo esiste la successione ha lo
 * stesso limite (teorema ponte), ma se non esiste non si può dire nulla.
 *
 * 29k. LA SCALA DELLE CRESCITE
 *
 * e^{x} / x^{5} a +\infty è \infty / \infty per l'algebra dei limiti, e
 * e^{1/t} non ha una serie in t. Lo si scrive allora con un fattore in più:
 * una funzione è e^{G} S, con S una serie come in 29b e G un esponente
 * esatto, una somma finita di termini g_i(L) t^{-k_i} con k_i > 0 e i
 * coefficienti g_i frazioni di polinomi nelle costanti e in L. e^{x} è
 * e^{t^{-1}} 1, x^{x} 2^{-x} = e^{x ln x - x ln 2} è e^{(L - ln 2) t^{-1}} 1,
 * e^{1/x} da destra di 0 è e^{t^{-1}} 1. È la scala delle crescite dei libri,
 * c x^{a} (\ln x)^{b} e^{P(x)}, con il confronto fattore per fattore: un
 * pezzo ristretto del metodo di Gruntz (D. Gruntz, "On computing limits in a
 * symbolic manipulation system", tesi, ETH Zurigo 1996), che a sua volta
 * viene dai campi di Hardy (G. H. Hardy, "Orders of infinity", 1910). I
 * fatti su cui si regge, con t -> 0^{+} e L = ln(1/t):
 *
 *   (a) L cresce meno di ogni potenza: t^{eps} L^{d} -> 0 per ogni eps > 0
 *       e ogni d (con s = L, t^{eps} L^{d} = e^{-eps s} s^{d}, e
 *       l'esponenziale batte ogni potenza di s);
 *   (b) se H = lambda(L) t^{-k} (1 + o(1)) con k > 0 e lambda(L) ~ c L^{j},
 *       c != 0, allora H / L -> +\infty o -\infty con il segno di c, perché
 *       t^{-k} L^{j - 1} -> +\infty per (a). Quindi per ogni e e d
 *
 *           e^{H} t^{e} L^{d} = exp(H - e L + d ln L) -> +\infty oppure 0,
 *
 *       perché H - e L + d ln L = H (1 + o(1)): e^{H} sta sopra o sotto ogni
 *       potenza di t e di L. È il confronto "gli esponenziali battono le
 *       potenze, che battono i logaritmi" dei libri;
 *   (c) somma: se G1 - G2 = H come in (b) con c > 0, allora
 *       e^{G1} S1 + e^{G2} S2 = e^{G1} (S1 + e^{-H} S2), ed e^{-H} S2 è più
 *       piccola di ogni potenza di t (b): è una funzione piatta (29e). Se
 *       G1 - G2 è esattamente zero (test di annullamento) le serie si
 *       sommano; se non si sa che segno ha, il conto si ferma;
 *   (d) prodotto e quoziente: e^{G1} S1 e^{G2} S2 = e^{G1 + G2} S1 S2, e
 *       1 / (e^{G} S) = e^{-G} / S;
 *   (e) potenze e logaritmi: (e^{G} S)^q = e^{q G} S^q e
 *       ln(e^{G} S) = G + ln S, perché e^{G} > 0;
 *   (f) l'esponenziale: se v = N + c(L) + P, con N i termini di esponente
 *       negativo (esatti, perché il resto di v tende a zero), c(L) il
 *       termine costante e P -> 0, allora e^{v} = e^{N} e^{c(L)} e^{P}:
 *       e^{N} è il fattore nuovo, gli altri due li sa già scrivere 29d. Se
 *       v ha già un fattore e^{G}, e^{v} sale di un piano (e^{e^{x}}) e si
 *       sa solo il suo limite, come in 29g.
 *
 * Il limite di e^{G} S: G ha un termine principale c t^{-k}; se c > 0 la
 * funzione tende all'infinito con il segno del termine principale di S, se
 * c < 0 tende a 0. Le funzioni che non sanno trattare il fattore (seno,
 * coseno, arcotangente) lo ricevono come lo vedeva l'algebra dei limiti:
 * un infinito, o una funzione piatta (value_plain()).
 *
 * 29l. SALIRE DI UN PIANO: x = e^{1/t}
 *
 * ln x / ln ln x a +\infty chiederebbe il logaritmo di L, che i coefficienti
 * non hanno. È il "moving up" di Gruntz: con x = e^{1/t} ogni ln x diventa
 * 1/t e ogni ln ln x diventa L, e i logaritmi scendono di un piano. La
 * sostituzione è lecita perché t -> e^{1/t} è una biiezione crescente da
 * (0, +\infty) a (1, +\infty), e t -> 0^{+} se e solo se x -> +\infty:
 * allora lim_{x -> +\infty} f(x) = lim_{t -> 0^{+}} f(e^{1/t}), nei due versi.
 * Allo stesso modo x = e^{-1/t} da destra di 0, x = -e^{1/t} a -\infty,
 * x = -e^{-1/t} da sinistra di 0; in un punto a diverso da zero x - a non
 * avrebbe una forma sola, e la sostituzione non si fa. La si prova solo
 * quando quella di 29a non arriva a un limite: con x = e^{1/t} un polinomio
 * come (x + 1)^2 - x^2 perde i termini piccoli (c), e non si scioglie più.
 *
 * Che cosa manca. Le stime (8 + sin^2 x \ge 8) per divergenze con
 * oscillazioni; due successioni per dimostrare che un limite in +\infty non
 * esiste; i parametri; le funzioni definite a pezzi; un esponenziale di un
 * esponenziale come fattore (e^{e^{x}} - e^{e^{x} - x}); i logaritmi annidati
 * più di una volta (ln ln ln x), che chiederebbero di salire di due piani.
 *
 * 29n. IL CERTIFICATO
 *
 * Il verdetto va a checker.c come certificato: l'enunciato, la sostituzione
 * e la precisione di ogni lato. Il verificatore rifà gli sviluppi con la sua
 * aritmetica e le sue regole (il suo capitolo 14), e il verdetto vuole che
 * lo accetti; vedi limit_certify().
 */

/* Il nome interno della lettera L = ln(1/t) (29d): non è un carattere. */
#define VAR_LOG_SCALE 5000

/* L'esponente "infinito" (29b): il resto di una serie esatta, o di una
 * funzione piatta, è O(t^{SERIES_FLAT}). Le somme di esponenti si fermano lì
 * (series_plus()), così non traboccano. */
#define SERIES_FLAT 1000000

#define MAX_SERIES_TERMS 48  /* coefficienti noti, al più, in una serie */
#define MAX_SERIES_DEN 24    /* denominatore massimo degli esponenti di una serie */
#define MAX_TAYLOR 20        /* termini di una serie di Taylor: 1/20! sta ancora nei razionali */
#define LIMIT_SAMPLES 60     /* punti del controllo con i numeri, t = 2^{-k} con k fino a 60 */
#define MOVED_SAMPLES 1000   /* lo stesso dopo la sostituzione di 29l: k fino a 1000, di 4 in 4 */

/* Le precisioni provate una dopo l'altra (29c): si sviluppa fino a t^4, poi
 * fino a t^8, poi fino a t^16, finché il termine principale non si trova. */
static const int series_goals[] = {4, 8, 16};

/* Una serie troncata (29b): la somma dei count coefficienti coef[i] per
 * t^{(low + i)/den}, più un resto O(t^{end/den}). Gli esponenti tra
 * low + count ed end hanno coefficiente zero.
 *
 * Invarianti: den >= 1; low + count <= end; se exact è 1 il resto non c'è ed
 * end vale SERIES_FLAT. Una funzione piatta ha count = 0, end = SERIES_FLAT
 * ed exact = 0; una funzione solo limitata ha count = 0 ed end = 0. I
 * coefficienti sono frazioni di polinomi nelle costanti (pi, e, logaritmi
 * di primi, radici) e nella lettera L; stanno nell'arena, come i Rat. */
typedef struct {
    int den;      /* D: gli esponenti sono multipli di 1/D */
    int low;      /* esponente, in unità 1/D, di coef[0] */
    int count;    /* coefficienti noti */
    int end;      /* esponente del resto, in unità 1/D */
    int exact;    /* 1 se la serie è una somma finita, senza resto */
    Rat *coef;
} Series;

/* Che cosa dice di un coefficiente c(L) il suo termine principale (29d). */
typedef struct {
    int known;      /* 1 se si sa se è zero e, se non lo è, il segno */
    int zero;       /* 1 se c(L) è zero */
    int side;       /* il segno di c(L) per L grande: +1 o -1 */
    Frac degree;    /* c(L) ~ value L^degree */
    Rat value;      /* il coefficiente della potenza più alta, senza L */
} Lead;

/* Ciò che il conto sa di una funzione vicino al punto, da un lato (29a):
 *   V_SERIES     la sua serie troncata;
 *   V_LIMIT      solo il suo limite (29g): +\infty, -\infty o un numero;
 *   V_UNDEFINED  che non ha valori in tutto un intorno da quel lato (29h);
 *   V_UNKNOWN    niente: il conto non sa andare avanti, e why dice perché. */
typedef enum { V_SERIES, V_LIMIT, V_UNDEFINED, V_UNKNOWN } ValueKind;

/* Una funzione vicino al punto, con ciò che se ne sa (vedi ValueKind). Per
 * V_SERIES la funzione è e^{G} S (29k), con S = series e G = growth; senza
 * fattore growth ha count = 0.
 * Invariante: growth è esatta, con i soli esponenti negativi; se ha dei
 * termini, series non è esattamente zero (value_grown()). */
typedef struct {
    ValueKind kind;
    Series series;    /* V_SERIES: S */
    int infinite;     /* V_LIMIT: +1 per +\infty, -1 per -\infty, 0 per un numero */
    Rat value;        /* V_LIMIT finito: il numero, senza la lettera L */
    int approach;     /* V_LIMIT finito: +1 se la funzione sta sopra il numero, -1 sotto, 0 se non si sa */
    int positive;     /* 1 se la funzione è certamente positiva vicino al punto */
    const char *why;  /* V_UNDEFINED, V_UNKNOWN: perché, in italiano */
    Series growth;    /* V_SERIES: l'esponente G del fattore e^{G} (29k) */
} Value;

/* Il motivo con cui un conto chiede più termini (29c): ha un nome perché
 * limit_side() lo riconosce e ricomincia con una precisione più alta. */
static const char *const NEEDS_PRECISION = "lo sviluppo, anche con più termini, non mostra un termine principale";

/* Il limite in corso: la variabile, il punto (finito, o +1 / -1 per
 * +\infty e -\infty), il lato, la precisione cercata (un esponente intero
 * di t), l'atomo della lettera L, se una potenza f^g è stata letta come
 * e^{g ln f} (lo dice la dimostrazione), e se la variabile è scritta con la
 * sostituzione di 29l, x = \pm e^{\pm 1/t}. */
static int lim_x, lim_infinity, lim_side, lim_goal, lim_ell, lim_exponential, lim_moved;
static Rat lim_point;

/* 1 se il conto in corso ha scritto la lettera L in un coefficiente (lo fa
 * solo value_ln()). Da quel momento un resto "O(t^{E})" vale a meno di una
 * potenza di L: un O(1) moltiplicato per -L, come \sin\frac{1}{x} \ln x, è
 * scritto O(t^{0}) ma non è limitato. Per i limiti non importa (t^{E} L^{m}
 * tende a zero per ogni E > 0), per e^{O(1)} sì: vedi value_exp(). */
static int lim_logs;

/* Il valore di L durante il controllo con i numeri (29i), per gli intervalli
 * dei coefficienti che la contengono; "non so" in ogni altro momento, perché
 * L è una lettera e non un numero. */
static Range lim_ell_range = {1, -1};

/* Somma di due esponenti: SERIES_FLAT se uno dei due lo è. Due esponenti
 * veri non devono mai arrivare vicino a SERIES_FLAT, che vuol dire "più di
 * ogni potenza": t^{2 SERIES_FLAT} preso per piatto, moltiplicato per
 * t^{-2 SERIES_FLAT}, darebbe 0 invece di 1. Oltre MAX_EXPONENT il conto
 * fallisce. */
#define MAX_EXPONENT (SERIES_FLAT / 16)
static int series_plus(int a, int b) {
    if (a >= SERIES_FLAT || b >= SERIES_FLAT) return SERIES_FLAT;
    long long sum = (long long)a + b;
    if (sum > MAX_EXPONENT || sum < -MAX_EXPONENT) { fail("esponenti troppo grandi in uno sviluppo"); return 0; }
    return (int)sum;
}

/* Ritorna una serie con den, low, count, end ed exact dati e i coefficienti
 * tutti zero. */
static Series series_make(int den, int low, int count, int end, int exact) {
    Series s = {den, low, count, end, exact, NULL};
    Rat zero = {poly_const(num_int(0)), poly_const(num_int(1))};
    if (count > 0) s.coef = arena_alloc((size_t)count * sizeof(Rat));
    if (!s.coef) s.count = 0;
    for (int i = 0; i < s.count; i++) s.coef[i] = zero;
    return s;
}

/* Ritorna la costante c come serie esatta. */
static Series series_const(Rat c) {
    Series s = series_make(1, 0, c.num.count ? 1 : 0, SERIES_FLAT, 1);
    if (s.count) s.coef[0] = c;
    return s;
}

/* Ritorna la funzione O(1), limitata e niente di più (29b). */
static Series series_bounded(void) { return series_make(1, 0, 0, 0, 0); }

/* Ritorna 1 se il Rat r contiene la lettera L. Solo come fattore di un
 * monomio: il capitolo non crea atomi con L dentro (vedi constant_ln()). */
static int rat_has_ell(Rat r) {
    for (int side = 0; side < 2; side++) {
        Poly p = side ? r.den : r.num;
        for (int i = 0; i < p.count; i++)
            if (mono_exponent(&p.term[i].mono, lim_ell).num != 0) return 1;
    }
    return 0;
}

/* Toglie da s i coefficienti iniziali scritti senza termini, e da una serie
 * esatta anche quelli finali: non cambia la funzione. */
static Series series_trim(Series s) {
    while (s.count > 0 && s.coef[0].num.count == 0) { s.coef++; s.count--; s.low++; }
    while (s.exact && s.count > 0 && s.coef[s.count - 1].num.count == 0) s.count--;
    if (s.count == 0) s.low = s.exact ? 0 : s.end;
    return s;
}

/* Ritorna s con il resto spostato a O(t^{end/den}), se end è più basso: ciò
 * che sta oltre si dimentica, e una serie esatta smette di esserlo.
 * Dimenticare è sempre lecito. */
static Series series_cut(Series s, int end) {
    if (end >= s.end) return s;
    s.exact = 0;
    s.end = end;
    if (s.low + s.count > end) s.count = end > s.low ? end - s.low : 0;
    if (s.count == 0) s.low = end;
    return s;
}

/* Ritorna s scritta con il denominatore den, multiplo del suo. */
static Series series_rescale(Series s, int den) {
    int k = den / s.den;
    if (k == 1) return s;
    int count = s.count ? (s.count - 1) * k + 1 : 0;
    Series r = series_make(den, s.low < SERIES_FLAT ? series_plus(s.low * k, 0) : SERIES_FLAT, count,
                           s.end < SERIES_FLAT ? series_plus(s.end * k, 0) : SERIES_FLAT, s.exact);
    for (int i = 0; i < s.count && r.count; i++) r.coef[i * k] = s.coef[i];
    return r;
}

/* Porta a e b allo stesso denominatore. Ritorna 0 se sarebbe troppo grande. */
static int series_common(Series *a, Series *b) {
    long long den = lcm_small(a->den, b->den);
    if (den > MAX_SERIES_DEN) return 0;
    *a = series_rescale(*a, (int)den);
    *b = series_rescale(*b, (int)den);
    return 1;
}

/* Ritorna s moltiplicata per la costante c. */
static Series series_scale(Series s, Rat c) {
    if (c.num.count == 0) return series_const(c);
    Series r = series_make(s.den, s.low, s.count, s.end, s.exact);
    for (int i = 0; i < r.count; i++) r.coef[i] = rat_mul(s.coef[i], c);
    return series_trim(r);
}

/* Ritorna s moltiplicata per t^{shift/den}. */
static Series series_shift(Series s, int shift) {
    s.low = series_plus(s.low, shift);
    s.end = series_plus(s.end, shift);
    return s;
}

/* Ritorna a + b, oppure a - b se subtract è diverso da zero; *ok diventa 0
 * se i denominatori non si possono mettere insieme. */
static Series series_add(Series a, Series b, int subtract, int *ok) {
    *ok = series_common(&a, &b);
    if (!*ok) return a;
    int end = a.end < b.end ? a.end : b.end, exact = a.exact && b.exact, low = SERIES_FLAT, top = -SERIES_FLAT;
    if (a.count) { low = a.low; top = a.low + a.count; }
    if (b.count && b.low < low) low = b.low;
    if (b.count && b.low + b.count > top) top = b.low + b.count;
    if (top > end) top = end;
    if (low >= top) low = top = end;
    if (top - low > MAX_SERIES_TERMS) { top = low + MAX_SERIES_TERMS; end = top; exact = 0; }
    Series r = series_make(a.den, low, top - low, end, exact);
    for (int i = 0; i < r.count; i++) {
        int e = low + i, ia = e - a.low, ib = e - b.low;
        Rat sum = ia >= 0 && ia < a.count ? a.coef[ia] : r.coef[i];
        if (ib >= 0 && ib < b.count) sum = rat_add(sum, b.coef[ib], subtract);
        r.coef[i] = sum;
    }
    return series_trim(r);
}

/* Ritorna a b (29b); *ok come per series_add(). */
static Series series_mul(Series a, Series b, int *ok) {
    *ok = series_common(&a, &b);
    if (!*ok) return a;
    if ((a.exact && a.count == 0) || (b.exact && b.count == 0)) return series_const(rat_int(0));

    /* Le valutazioni, o il resto dove non si conosce nulla, e il resto del
     * prodotto. */
    int va = a.count ? a.low : a.end, vb = b.count ? b.low : b.end;
    int end = series_plus(va, b.end), other = series_plus(vb, a.end), exact = a.exact && b.exact;
    if (other < end) end = other;
    int low = series_plus(va, vb), top = a.count && b.count ? a.low + a.count - 1 + b.low + b.count : low;
    if (top > end) top = end;
    if (low > top) low = top;
    if (top - low > MAX_SERIES_TERMS) { top = low + MAX_SERIES_TERMS; end = top; exact = 0; }
    Series r = series_make(a.den, low, top - low, end, exact);
    for (int i = 0; i < a.count; i++) {
        if (a.coef[i].num.count == 0) continue;
        for (int j = 0; j < b.count; j++) {
            int k = a.low + i + b.low + j - low;
            if (k >= r.count) break;
            if (b.coef[j].num.count) r.coef[k] = rat_add(r.coef[k], rat_mul(a.coef[i], b.coef[j]), 0);
        }
    }
    return series_trim(r);
}

/* LE COSTANTI
 *
 * I coefficienti delle serie sono numeri esatti scritti come frazioni di
 * polinomi negli atomi del capitolo 4: pi, la lettera e (qui sempre il
 * numero di Nepero), i primi con un esponente razionale (le radici), i
 * logaritmi, le arcotangenti, gli esponenziali complessi e^{i theta} con cui
 * il capitolo 11 scrive seni e coseni. Servono due cose: il segno di un
 * coefficiente, che dà un intervallo, e i valori delle funzioni nei punti
 * costanti, scritti in modo che lo stesso numero arrivi sempre alla stessa
 * forma: e^{1/2} è un monomio con la lettera e elevata a 1/2, ln e è 1,
 * e^{q ln p} è p^q. Due scritture diverse dello stesso numero non sono un
 * errore (il test di annullamento direbbe "non so"), solo un limite in meno
 * dimostrato. */

/* Un numero complesso noto a meno di un errore: le due parti, ognuna un
 * intervallo del capitolo 24. Serve per i coefficienti che contengono
 * e^{i theta}, che sono numeri reali scritti con numeri complessi. */
typedef struct {
    Range re, im;
} Pair;

/* Prodotto di due numeri complessi: (a + b i)(c + d i). */
static Pair pair_mul(Pair a, Pair b) {
    return (Pair){range_sub(range_mul(a.re, b.re), range_mul(a.im, b.im)), range_add(range_mul(a.re, b.im), range_mul(a.im, b.re))};
}

/* Il numero reale r come numero complesso. */
static Pair pair_real(Range r) { return (Pair){r, {0, 0}}; }

/* Ritorna il quadrato di r, che non è negativo anche quando r contiene lo
 * zero (il prodotto di intervalli lo farebbe scendere sotto). */
static Range range_square(Range r) {
    if (!range_known(r)) return r;
    if (r.low >= 0 || r.high <= 0) return range_mul(r, r);
    double top = -r.low > r.high ? -r.low : r.high;
    return range_wide(0, top * top);
}

/* Ritorna il modulo del numero complesso a. */
static Range pair_modulus(Pair a) {
    if (range_known(a.im) && a.im.low == 0 && a.im.high == 0) return range_known(a.re) && a.re.low >= 0 ? a.re : range_known(a.re) && a.re.high <= 0 ? range_neg(a.re) : range_sqrt(range_square(a.re));
    return range_sqrt(range_add(range_square(a.re), range_square(a.im)));
}

/* Ritorna la parte reale di a, che deve essere un numero reale scritto con
 * numeri complessi: "non so" se la parte immaginaria non può essere zero. */
static Range pair_real_part(Pair a) {
    return range_known(a.im) && a.im.low <= 0 && a.im.high >= 0 ? a.re : range_none();
}

/* Prototipi in avanti inevitabili: un atomo può avere per base un polinomio
 * o per esponente un monomio, fatti di atomi. poly_pair() ritorna il valore
 * del polinomio p di costanti; mono_real_range() un intervallo per il valore
 * reale del monomio m, di soli atomi reali (l'esponente di un atomo e^{i M}). */
static Pair poly_pair(Poly p);
static Range mono_real_range(const Mono *m);

/* Ritorna il valore dell'atomo elevato a e, come numero complesso, o "non
 * so". La lettera L ha un valore solo durante il controllo con i numeri
 * (lim_ell_range); altrimenti il suo intervallo è "non so". */
static Pair atom_pair(int atom, Frac e) {
    const Atom *a = &atoms[atom];
    Pair none = {range_none(), range_none()};
    Range base, power = range_ratio(e.num, e.den);

    /* e^{i M} elevato a e: l'angolo e M, il punto (cos, sin). */
    if (a->kind == ATOM_POW && a->base == BASE_EI) {
        Range sine, cosine;
        range_sin_cos(range_mul(power, mono_real_range(&a->exponent)), &sine, &cosine);
        return (Pair){cosine, sine};
    }
    switch (a->kind) {
    case ATOM_VAR:
        if (a->id == VAR_PI) base = range_pi();
        else if (a->id == 'e') base = range_exp_at(1);
        else if (a->id == VAR_LOG_SCALE && range_known(lim_ell_range)) base = lim_ell_range;
        else return none;
        break;
    case ATOM_POW:
        base = a->base == BASE_PRIME ? range_ratio(a->id, 1)
             : a->base == BASE_ATOM ? pair_real_part(atom_pair((int)a->id, frac_int(1)))
             : pair_real_part(poly_pair(base_polys[a->id]));
        if (a->exponent.count) power = range_mul(power, mono_real_range(&a->exponent));
        if (a->exponent.count || e.den != 1) return pair_real(range_exp(range_mul(power, range_ln(base))));
        break;
    case ATOM_LN:
        base = range_ln(a->base == BASE_PRIME ? range_ratio(a->id, 1)
                        : a->base == BASE_ATOM ? pair_modulus(atom_pair((int)a->id, frac_int(1)))
                        : pair_modulus(poly_pair(base_polys[a->id])));
        break;
    case ATOM_ATAN:
        base = range_atan(range_div(pair_real_part(poly_pair(atan_args[a->id].num)), pair_real_part(poly_pair(atan_args[a->id].den))));
        break;
    default:
        return none;
    }
    if (e.den == 1) return pair_real(range_power(base, e.num));
    return pair_real(range_exp(range_mul(power, range_ln(base))));
}

static Range mono_real_range(const Mono *m) {
    Pair product = pair_real((Range){1, 1});
    for (int i = 0; i < m->count; i++) product = pair_mul(product, atom_pair(m->factor[i].atom, m->factor[i].exp));
    return range_known(product.im) && product.im.low <= 0 && product.im.high >= 0 ? product.re : range_none();
}

/* Ritorna il valore del polinomio p di costanti, come numero complesso. */
static Pair poly_pair(Poly p) {
    Pair sum = pair_real((Range){0, 0});
    for (int t = 0; t < p.count; t++) {
        const Term *term = &p.term[t];
        Pair product = {range_ratio(term->coef.re.num, term->coef.re.den), range_ratio(term->coef.im.num, term->coef.im.den)};
        for (int f = 0; f < term->mono.count; f++) product = pair_mul(product, atom_pair(term->mono.factor[f].atom, term->mono.factor[f].exp));
        sum = (Pair){range_add(sum.re, product.re), range_add(sum.im, product.im)};
    }
    return sum;
}

/* Ritorna un intervallo che contiene la costante reale c, o "non so". Il
 * quoziente di due numeri complessi è n conj(d) / |d|^2; la parte
 * immaginaria deve poter essere zero, perché c è reale: se non può, il
 * numero non è quello che si crede, e la risposta è "non so". */
static Range constant_range(Rat c) {
    Pair n = poly_pair(c.num), d = poly_pair(c.den);
    Range size = range_add(range_square(d.re), range_square(d.im));
    Range re = range_div(range_add(range_mul(n.re, d.re), range_mul(n.im, d.im)), size);
    Range im = range_div(range_sub(range_mul(n.im, d.re), range_mul(n.re, d.im)), size);
    if (!range_known(im) || im.low > 0 || im.high < 0) return range_none();
    return re;
}

/* Il segno della costante c, senza la lettera L. Ritorna 0 se c è zero (il
 * test di annullamento, esatto), 1 se il segno è certo e lo mette in *side,
 * -1 se non si sa. Un errore di calcolo durante il test vale "non so". */
static int constant_sign(Rat c, int *side) {
    const char *saved = failure;
    int zero = c.num.count == 0 || poly_vanishes(c.num);
    if (failure != saved) { failure = saved; return -1; }
    if (zero) return 0;
    return range_side(constant_range(c), side) ? 1 : -1;
}

/* Della parte di p con la potenza più alta della lettera L mette in *degree
 * l'esponente, in *lead il coefficiente senza L e in *side il suo segno. Le
 * potenze più alte il cui coefficiente è zero (test esatto) si saltano.
 * Ritorna 1 se ci riesce, 0 se p è zero, -1 se un segno non si sa. */
static int poly_top(Poly p, Frac *degree, Poly *lead, int *side) {
    while (p.count > 0) {
        Frac top = mono_exponent(&p.term[0].mono, lim_ell);
        for (int i = 1; i < p.count; i++) {
            Frac e = mono_exponent(&p.term[i].mono, lim_ell);
            if (frac_cmp(e, top) > 0) top = e;
        }
        Term *high = terms_alloc(p.count), *low = terms_alloc(p.count);
        if (!high || !low) return -1;
        int highs = 0, lows = 0;
        for (int i = 0; i < p.count; i++) {
            Term t = p.term[i];
            if (frac_cmp(mono_exponent(&t.mono, lim_ell), top) != 0) { low[lows++] = t; continue; }
            t.mono = mono_with_exponent(&t.mono, lim_ell, frac_int(0));
            high[highs++] = t;
        }
        Poly group = poly_finish(high, p.count, highs);
        int known = constant_sign((Rat){group, poly_const(num_int(1))}, side);
        if (known < 0) return -1;
        if (known > 0) { *degree = top; *lead = group; return 1; }
        p = poly_finish(low, p.count, lows);
    }
    return 0;
}

/* Il termine principale del coefficiente c (29d), in *out. */
static Lead coefficient_lead(Rat c) {
    Lead out = {0, 0, 0, {0, 1}, {{0, NULL}, {0, NULL}}};
    Frac above, below;
    Poly top, bottom;
    int up, down;
    int found = poly_top(c.num, &above, &top, &up);
    if (found == 0) { out.known = out.zero = 1; return out; }
    if (found < 0 || poly_top(c.den, &below, &bottom, &down) <= 0) return out;
    out.known = 1;
    out.side = up * down;
    out.degree = frac_add(above, frac_neg(below));
    out.value = rat_make(top, bottom);
    return out;
}

/* Toglie da *s i coefficienti iniziali che sono zero (test esatto) e mette
 * in *lead il termine principale del primo che resta. Ritorna 1 se quel
 * coefficiente c'è e non è zero, 0 se non si sa se lo sia, -1 se non resta
 * nessun coefficiente noto. */
static int series_settle(Series *s, Lead *lead) {
    for (;;) {
        *s = series_trim(*s);
        if (s->count == 0) return -1;
        *lead = coefficient_lead(s->coef[0]);
        if (!lead->known) return 0;
        if (!lead->zero) return 1;
        s->coef[0] = (Rat){poly_const(num_int(0)), poly_const(num_int(1))};
    }
}

/* Ritorna 1 se l'atomo è certamente positivo: pi, e, un primo con un
 * esponente, il logaritmo di un primo, la lettera L (che è ln(1/t), con
 * t < 1), oppure un atomo il cui intervallo è positivo. */
static int atom_positive(int atom) {
    const Atom *a = &atoms[atom];
    int side;
    if (a->kind == ATOM_VAR) return a->id == VAR_PI || a->id == 'e' || a->id == VAR_LOG_SCALE;
    if ((a->kind == ATOM_POW || a->kind == ATOM_LN) && a->base == BASE_PRIME) return 1;
    return range_side(atom_pair(atom, frac_int(1)).re, &side) && side > 0 && atom_pair(atom, frac_int(1)).im.low == 0;
}

/* Il logaritmo naturale di |t|, per un solo termine t senza unità
 * immaginaria: ln|r| + somma di e_i ln|a_i| per il coefficiente r e gli
 * atomi a_i^{e_i}. Le regole che lo tengono in forma unica: ln e = 1,
 * |e^{i theta}| = 1, ln(e^{M}) = M, e ln|u^q| = q ln|u|. Ritorna 0 se t non
 * ha questa forma. */
static int term_log(Term t, Rat *out) {
    if (t.coef.im.num != 0 || t.coef.re.num == 0) return 0;
    Frac size = t.coef.re.num < 0 ? frac_neg(t.coef.re) : t.coef.re;
    Rat total = logarithm(rat_frac(size));
    for (int i = 0; i < t.mono.count; i++) {
        int atom = t.mono.factor[i].atom;
        const Atom *a = &atoms[atom];
        Rat piece;
        if (a->kind == ATOM_VAR && a->id == 'e') piece = rat_int(1);
        else if (a->kind == ATOM_POW && a->base == BASE_EI) continue;
        else if (a->kind == ATOM_POW && a->exponent.count == 0) piece = rat_atom(atom_ln(a->base, a->id));
        else if (a->kind == ATOM_POW && a->base == BASE_ATOM && atoms[a->id].kind == ATOM_VAR && atoms[a->id].id == 'e')
            piece = (Rat){poly_term((Term){num_int(1), a->exponent}), poly_const(num_int(1))};
        else piece = rat_atom(atom_ln(BASE_ATOM, atom));
        total = rat_add(total, rat_mul(rat_frac(t.mono.factor[i].exp), piece), 0);
    }
    *out = total;
    return !failure;
}

/* Il logaritmo naturale della costante c, che chi chiama sa positiva e
 * senza L. Numeratore e denominatore di un solo termine con term_log();
 * una somma con logarithm() del capitolo 11, che la scompone. Ritorna 0 se
 * non sa scriverlo. */
static int constant_ln(Rat c, Rat *out) {
    Rat side[2];
    for (int s = 0; s < 2; s++) {
        Poly p = s ? c.den : c.num;
        if (p.count == 1) { if (!term_log(p.term[0], &side[s])) return 0; continue; }
        if (!poly_is_real(p)) return 0;
        side[s] = logarithm((Rat){p, poly_const(num_int(1))});
    }
    *out = rat_add(side[0], side[1], 1);
    return !failure;
}

/* e elevato alla costante c, senza L e senza denominatore. Un termine alla
 * volta, perché e^{u + v} = e^u e^v: un razionale r dà e^r, q ln p dà p^q,
 * q M con M un monomio di altre costanti dà (e^M)^q. Ritorna 0 se non sa
 * scriverlo. */
static int constant_exp(Rat c, Rat *out) {
    if (!poly_is_one(c.den)) return 0;
    Rat total = rat_int(1);
    int e = atom_var('e');
    for (int i = 0; i < c.num.count; i++) {
        Term t = c.num.term[i], power = {num_int(1), {0}};
        Frac q = t.coef.re;
        if (t.coef.im.num != 0) return 0;
        const Atom *a = t.mono.count == 1 ? &atoms[t.mono.factor[0].atom] : NULL;
        int one = t.mono.count == 1 && frac_cmp(t.mono.factor[0].exp, frac_int(1)) == 0;
        if (t.mono.count == 0) {
            term_times(&power, e, q);
        } else if (one && a->kind == ATOM_LN && a->base == BASE_PRIME) {
            total = rat_mul(total, q.den == 1 ? rat_pow_int(rat_int(a->id), q.num) : fractional_power(rat_int(a->id), q, 0));
            continue;
        } else if (one && a->kind == ATOM_LN) {
            return 0;
        } else {
            term_times(&power, atom_pow(BASE_ATOM, e, &t.mono), q);
        }
        total = rat_mul(total, (Rat){poly_term(power), poly_const(num_int(1))});
    }
    *out = total;
    return !failure;
}

/* La costante c, positiva, elevata al razionale q non intero. Un termine
 * solo con atomi positivi si eleva fattore per fattore, (r a^k)^q =
 * r^q a^{k q}, che vale per basi positive; anche L lo è. Una somma senza L
 * passa da fractional_power() del capitolo 11. Ritorna 0 se non sa
 * scriverla. */
static int constant_power(Rat c, Frac q, Rat *out) {
    Poly part[2] = {c.num, c.den};
    Rat result[2];

    /* Numeratore e denominatore positivi, cambiando il segno a tutti e due
     * se serve. */
    int side = 1;
    if (part[1].count == 1 && part[1].term[0].mono.count == 0) side = part[1].term[0].coef.re.num > 0 ? 1 : -1;
    else if (constant_sign((Rat){part[1], poly_const(num_int(1))}, &side) != 1) return 0;
    for (int s = 0; s < 2 && side < 0; s++) part[s] = poly_add(poly_const(num_int(0)), part[s], 1);

    for (int s = 0; s < 2; s++) {
        Poly p = part[s];
        if (p.count == 1) {
            Term t = p.term[0], rest = {num_int(1), {0}};
            if (t.coef.im.num != 0 || t.coef.re.num <= 0) return 0;
            for (int i = 0; i < t.mono.count; i++) {
                if (!atom_positive(t.mono.factor[i].atom)) return 0;
                term_times(&rest, t.mono.factor[i].atom, frac_mul(t.mono.factor[i].exp, q));
            }
            result[s] = rat_mul(fractional_power(rat_frac(t.coef.re), q, 0), (Rat){poly_term(rest), poly_const(num_int(1))});
            continue;
        }
        Rat whole = {p, poly_const(num_int(1))};
        if (rat_has_ell(whole) || !poly_is_real(p)) return 0;
        result[s] = fractional_power(whole, q, 0);
    }
    *out = rat_make(poly_mul(result[0].num, result[1].den), poly_mul(result[0].den, result[1].num));
    return !failure;
}

/* Seno e coseno della costante c, senza L e senza denominatore: con le
 * formule di Eulero, come nel capitolo 11. Ritorna 0 se non si può. */
static int constant_sin_cos(Rat c, Rat *sine, Rat *cosine) {
    if (!poly_is_one(c.den) || !poly_is_real(c.num)) return 0;
    Rat forward = exp_i(c, 1), backward = exp_i(c, -1);
    Rat minus_half_i = {poly_const((Num){frac_int(0), (Frac){-1, 2}}), poly_const(num_int(1))};
    *cosine = rat_mul(rat_add(forward, backward, 0), rat_frac((Frac){1, 2}));
    *sine = rat_mul(rat_add(forward, backward, 1), minus_half_i);
    return !failure;
}

/* I VALORI E L'ALGEBRA DEI LIMITI (29g) */

/* L'esponente nullo: nessun fattore e^{G} (29k). */
#define NO_GROWTH ((Series){1, 0, 0, SERIES_FLAT, 1, NULL})

/* I quattro modi di costruire un Value: una serie (positive dice se la
 * funzione è certamente positiva vicino al punto), un limite finito con il
 * lato da cui ci si arriva, un limite infinito con il suo segno, un fallimento
 * (V_UNDEFINED o V_UNKNOWN) con il perché. */
static Value value_series(Series s, int positive) {
    Value v = {V_SERIES, s, 0, {{0, NULL}, {0, NULL}}, 0, positive, NULL, NO_GROWTH};
    return v;
}
static Value value_finite(Rat number, int approach) {
    Value v = {V_LIMIT, {1, 0, 0, 0, 0, NULL}, 0, number, approach, 0, NULL, NO_GROWTH};
    return v;
}
static Value value_infinite(int sign) {
    Value v = {V_LIMIT, {1, 0, 0, 0, 0, NULL}, sign, {{0, NULL}, {0, NULL}}, 0, sign > 0, NULL, NO_GROWTH};
    return v;
}
static Value value_failed(ValueKind kind, const char *why) {
    Value v = {kind, {1, 0, 0, 0, 0, NULL}, 0, {{0, NULL}, {0, NULL}}, 0, 0, why, NO_GROWTH};
    return v;
}

/* IL FATTORE e^{G} (29k) */

/* La funzione piatta: più piccola di ogni potenza di t (29e). */
static Series series_flat(void) { return series_make(1, SERIES_FLAT, 0, SERIES_FLAT, 0); }

/* Ritorna 1 se v ha un fattore e^{G}. */
static int value_grows(Value v) { return v.kind == V_SERIES && v.growth.count > 0; }

/* Dove va l'esponente g (29k-b): ritorna 1 e mette in *dir +1 se tende a
 * +\infty, -1 se tende a -\infty; ritorna 0 se g è zero (test esatto), -1
 * se il segno del suo termine principale non si sa. */
static int growth_direction(Series g, int *dir) {
    Lead lead;
    int found = series_settle(&g, &lead);
    if (found < 0) return 0;
    if (found == 0) return -1;
    *dir = lead.side;
    return 1;
}

/* Ritorna e^{g} s. Un esponente zero (test esatto) si toglie, e così quello
 * di una serie esattamente zero; un esponente che non è più esatto, perché
 * una somma lo ha troncato, non dice più quanto vale il fattore: allora la
 * risposta è "non so". */
static Value value_grown(Series s, Series g, int positive) {
    int dir;
    if (!g.exact) return value_failed(V_UNKNOWN, "un esponente con troppi termini");
    int known = growth_direction(g, &dir);
    if (known == 0 || (s.exact && series_trim(s).count == 0)) return value_series(s, positive);
    if (known < 0) return value_failed(V_UNKNOWN, "un esponenziale di cui non si sa se cresce o decresce");
    Value v = value_series(s, positive);
    v.growth = series_trim(g);
    return v;
}

/* Ritorna v come lo vedeva l'algebra dei limiti prima della scala (29k),
 * per le funzioni che il fattore e^{G} non lo sanno trattare: se G tende a
 * -\infty una funzione piatta, se tende a +\infty l'infinito con il segno
 * del termine principale di S. Un v senza fattore resta com'è. */
static Value value_plain(Value v) {
    if (!value_grows(v)) return v;
    int dir = 0;
    Series s = v.series;
    Lead lead;
    int found = series_settle(&s, &lead);

    /* La direzione di G è nota: value_grown() non costruisce un fattore
     * senza. */
    if (growth_direction(v.growth, &dir) != 1) return value_failed(V_UNKNOWN, "un esponenziale di cui non si sa se cresce o decresce");
    if (dir < 0) return value_series(series_flat(), found == 1 && lead.side > 0);
    if (found == 1) return value_infinite(lead.side);
    if (found < 0 && !s.exact && s.end < SERIES_FLAT) return value_failed(V_UNKNOWN, NEEDS_PRECISION);
    if (found < 0) return value_failed(V_UNKNOWN, "accanto a un esponenziale che cresce resta solo un termine più piccolo di ogni potenza, "
                                                  "di cui non si conosce l'ordine");
    return value_failed(V_UNKNOWN, "un coefficiente dello sviluppo ha un segno che gli intervalli non sanno stabilire");
}

/* Divide la serie s nei termini di esponente negativo, *negative (esatti:
 * chi chiama sa che il resto di s tende a zero), e in tutti gli altri con il
 * resto, *rest (29k-f). */
static void series_split_growth(Series s, Series *negative, Series *rest) {
    int count = s.low < 0 ? -s.low : 0;
    if (count > s.count) count = s.count;
    *negative = series_make(s.den, s.low, count, SERIES_FLAT, 1);
    for (int i = 0; i < negative->count; i++) negative->coef[i] = s.coef[i];
    *negative = series_trim(*negative);
    *rest = s;
    if (s.low < 0) {
        rest->coef += count;
        rest->count -= count;
        rest->low = 0;
        if (rest->count == 0) rest->coef = NULL;
    }
    *rest = series_trim(*rest);
}

/* Il limite della serie s (29c): un V_LIMIT, oppure V_UNKNOWN con il
 * motivo; NEEDS_PRECISION se i coefficienti noti sono tutti zero e il resto
 * non tende a zero. positive dice che la funzione è positiva: allora un
 * limite 0 è 0^{+}. */
static Value series_limit(Series s, int positive) {
    Lead lead;
    int found = series_settle(&s, &lead);
    if (found < 0) {
        if (s.exact || s.end > 0) return value_finite(rat_int(0), positive);
        return value_failed(V_UNKNOWN, NEEDS_PRECISION);
    }
    if (found == 0) return value_failed(V_UNKNOWN, "un coefficiente dello sviluppo ha un segno che gli intervalli non sanno stabilire");
    int top = lead.degree.num > 0, bottom = lead.degree.num < 0;
    if (s.low < 0 || (s.low == 0 && top)) return value_infinite(lead.side);
    if (s.low > 0 || bottom) return value_finite(rat_int(0), lead.side);

    /* Esponente 0 e nessuna potenza di L: il limite è il coefficiente, e
     * da che parte ci si arriva lo dice il termine dopo. */
    Rat number = rat_has_ell(s.coef[0]) ? lead.value : s.coef[0];
    Series rest = s;
    Lead next;
    rest.coef++;
    rest.count--;
    rest.low++;
    int approach = !rat_has_ell(s.coef[0]) && series_settle(&rest, &next) == 1 ? next.side : 0;
    return value_finite(number, approach);
}

/* Ritorna il limite di v: v stesso se non è una serie, altrimenti
 * series_limit(). Con il fattore e^{G} (29k) il limite è 0 se G tende a
 * -\infty, dal lato del segno di S; altrimenti l'infinito di value_plain(). */
static Value value_limit(Value v) {
    if (value_grows(v)) {
        Value plain = value_plain(v);
        if (plain.kind != V_SERIES) return plain;
        Series s = v.series;
        Lead lead;
        return value_finite(rat_int(0), series_settle(&s, &lead) == 1 ? lead.side : 0);
    }
    return v.kind == V_SERIES ? series_limit(v.series, v.positive) : v;
}

/* Il segno del limite finito l, se certo: +1, -1, oppure 0 se il numero è
 * zero; ritorna 0 se non si sa, 1 altrimenti. */
static int limit_sign(Value l, int *side) {
    int known = constant_sign(l.value, side);
    if (known == 0) *side = 0;
    return known >= 0;
}

/* -l, per un limite. */
static Value limit_neg(Value l) {
    if (l.kind != V_LIMIT) return l;
    if (l.infinite) return value_infinite(-l.infinite);
    return value_finite(rat_add(rat_int(0), l.value, 1), -l.approach);
}

/* a + b sui numeri reali estesi. */
static Value limit_add(Value a, Value b) {
    if (a.infinite && b.infinite) return a.infinite == b.infinite ? a : value_failed(V_UNKNOWN, "forma indeterminata: +\\infty - \\infty");
    if (a.infinite) return a;
    if (b.infinite) return b;
    return value_finite(rat_add(a.value, b.value, 0), a.approach == b.approach ? a.approach : 0);
}

/* a b sui numeri reali estesi: 0 per infinito non si scioglie. */
static Value limit_mul(Value a, Value b) {
    int sa = 0, sb = 0;
    if (!a.infinite && !limit_sign(a, &sa)) return value_failed(V_UNKNOWN, "un limite ha un segno che gli intervalli non sanno stabilire");
    if (!b.infinite && !limit_sign(b, &sb)) return value_failed(V_UNKNOWN, "un limite ha un segno che gli intervalli non sanno stabilire");
    if (a.infinite && b.infinite) return value_infinite(a.infinite * b.infinite);
    if (a.infinite || b.infinite) {
        int finite = a.infinite ? sb : sa, sign = a.infinite ? a.infinite : b.infinite;
        return finite ? value_infinite(finite * sign) : value_failed(V_UNKNOWN, "forma indeterminata: 0 \\cdot \\infty");
    }
    int approach = sa == 0 && sb ? a.approach * sb : sb == 0 && sa ? b.approach * sa : 0;
    return value_finite(rat_mul(a.value, b.value), approach);
}

/* 1 / l sui numeri reali estesi: 1/(0^{+}) = +\infty, 1/\infty = 0. Un
 * limite 0 senza segno non si inverte. */
static Value limit_inverse(Value l) {
    int side = 0;
    if (l.infinite) return value_finite(rat_int(0), l.infinite);
    if (!limit_sign(l, &side)) return value_failed(V_UNKNOWN, "un limite ha un segno che gli intervalli non sanno stabilire");
    if (side) return value_finite(rat_div(rat_int(1), l.value), -l.approach);
    if (l.approach) return value_infinite(l.approach);
    return value_failed(V_UNKNOWN, "un divisore tende a 0 senza un segno noto");
}

/* LE SERIE DELLE FUNZIONI (29e) */

/* I coefficienti delle serie di Taylor in 0 che servono, come dati: */
typedef enum {
    TAYLOR_EXP,        /* e^w = somma di w^k / k! */
    TAYLOR_LOG,        /* ln(1 + w) = somma di (-1)^{k+1} w^k / k, da k = 1 */
    TAYLOR_SIN,        /* sin w = somma di (-1)^j w^{2j+1} / (2j+1)! */
    TAYLOR_COS,        /* cos w = somma di (-1)^j w^{2j} / (2j)! */
    TAYLOR_ATAN,       /* arctan w = somma di (-1)^j w^{2j+1} / (2j+1) */
    TAYLOR_BINOMIAL    /* (1 + w)^q = somma di q (q - 1) ... (q - k + 1) / k! w^k */
} TaylorKind;

/* Mette in a[k] il coefficiente di w^k della serie kind (con l'esponente q
 * per TAYLOR_BINOMIAL), per k da 0, e ritorna quanti ne ha messi: al più
 * MAX_TAYLOR, meno se i numeri escono dai razionali. Uscire non è un
 * errore: la serie si tronca prima, e il resto lo dice (series_taylor()). */
static int taylor_coefficients(TaylorKind kind, Frac q, Frac *a) {
    const char *saved = failure;
    Frac factorial = frac_int(1), binomial = frac_int(1);
    int count = 0;
    for (int k = 0; k < MAX_TAYLOR; k++) {
        if (k > 0) {
            factorial = frac_mul(factorial, frac_int(k));
            binomial = frac_div(frac_mul(binomial, frac_add(q, frac_int(1 - k))), frac_int(k));
        }
        Frac sign = frac_int((k / 2) % 2 ? -1 : 1), c = frac_int(0);
        switch (kind) {
        case TAYLOR_EXP: c = frac_div(frac_int(1), factorial); break;
        case TAYLOR_LOG: if (k) c = frac_make(k % 2 ? 1 : -1, k); break;
        case TAYLOR_SIN: if (k % 2) c = frac_div(sign, factorial); break;
        case TAYLOR_COS: if (k % 2 == 0) c = frac_div(sign, factorial); break;
        case TAYLOR_ATAN: if (k % 2) c = frac_make(sign.num, k); break;
        case TAYLOR_BINOMIAL: c = binomial; break;
        }
        if (failure != saved) { failure = saved; break; }
        a[count++] = c;
    }
    return count;
}

/* Ritorna la somma dei a[k] w^k (29b), con w che tende a 0: i suoi
 * esponenti sono positivi. Se w è esatta lo sviluppo si ferma all'esponente
 * target (in unità 1/D di w); altrimenti al resto di w. Il resto della serie
 * troncata a K termini è O(w^K) = O(t^{K v}), con v l'esponente più basso
 * di w, e lo si aggiunge. */
static Series series_taylor(Series w, TaylorKind kind, Frac q, int target) {
    Frac a[MAX_TAYLOR];
    int terms = taylor_coefficients(kind, q, a), ok = 1;

    /* Il risultato ha il denominatore degli esponenti di w: chi chiama lo
     * sposta in quelle unità. Una costante andava riscritta, e senza farlo
     * 1/(2 t^{-5/2}) diventava t^5 / 2 (il controllo con i numeri lo ha
     * visto: tests/limits/false_limits.tex). */
    if (w.exact && w.count == 0) return series_rescale(series_const(rat_frac(a[0])), w.den);
    int v = w.count ? w.low : w.end, end = w.exact ? target : w.end;
    if (v < 1) { fail("uno sviluppo di Taylor con un argomento che non tende a 0"); return series_bounded(); }
    if (end < v) end = v;
    int used = (end + v - 1) / v;
    if (used > terms) used = terms;
    if (used < 1) used = 1;

    /* Horner: a[0] + w (a[1] + w (a[2] + ...)). */
    Series sum = series_rescale(series_const(rat_frac(a[used - 1])), w.den);
    for (int k = used - 2; k >= 0 && ok; k--) {
        sum = series_cut(series_mul(w, sum, &ok), end);
        sum = series_add(sum, series_const(rat_frac(a[k])), 0, &ok);
    }
    if (!ok) fail("denominatori degli esponenti troppo grandi in uno sviluppo");

    /* Il resto della serie troncata; e quello di w, se w non è esatta,
     * anche quando è piatta e il suo resto non ha un esponente. */
    sum = series_cut(sum, used >= SERIES_FLAT / v ? SERIES_FLAT : used * v);
    if (!w.exact) sum.exact = 0;
    return sum;
}

/* Il primo termine di s, che deve essere noto e diverso da zero, tolto da s:
 * s = c t^{low} (1 + u). Mette u in *u e ritorna c. */
static Rat series_unit(Series s, Series *u) {
    Rat c = s.coef[0], inverse = rat_div(rat_int(1), c);
    *u = series_make(s.den, 1, s.count - 1, series_plus(s.end, -s.low), s.exact);
    for (int i = 1; i < s.count && i - 1 < u->count; i++) u->coef[i - 1] = rat_mul(s.coef[i], inverse);
    *u = series_trim(*u);
    return c;
}

/* 1 / s (29c). Ritorna 1 e mette il risultato in *out se il termine
 * principale di s è noto e non nullo; -1 se s è esattamente zero (allora
 * 1/s non ha valori); 0 se non si sa. */
static int series_inverse(Series s, Series *out) {
    Lead lead;
    int found = series_settle(&s, &lead);
    if (found < 0) return s.exact ? -1 : 0;
    if (found == 0) return 0;
    Series u;
    Rat c = series_unit(s, &u);
    Series sum = series_taylor(u, TAYLOR_BINOMIAL, frac_int(-1), lim_goal * s.den + s.low);
    *out = series_shift(series_scale(sum, rat_div(rat_int(1), c)), -s.low);
    return !failure;
}

/* s^n per n intero (29b): moltiplicazioni ripetute, per quadrati. Con n < 0
 * si inverte prima. Ritorna come series_inverse(). */
static int series_power_int(Series s, long long n, Series *out) {
    int ok = 1;
    if (n < 0) {
        int inverted = series_inverse(s, &s);
        if (inverted <= 0) return inverted;
        n = -n;
    }
    Series result = series_const(rat_int(1)), square = s;
    for (; n > 0 && ok; n /= 2) {
        if (n % 2) result = series_mul(result, square, &ok);
        if (n > 1) square = series_mul(square, square, &ok);
    }
    *out = result;
    return ok && !failure;
}

/* s^q per q razionale non intero (29e, 29f): s = c t^{e} (1 + u) dà
 * c^q t^{e q} (1 + u)^q. La base deve essere positiva; con odd diverso da
 * zero (una radice di indice dispari) può essere negativa, e
 * (-b)^q = -(b^q). Ritorna 1 se riesce, -1 se la base è negativa vicino al
 * punto (la potenza non ha valori), 0 se non si sa. */
static int series_power(Series s, Frac q, int odd, Series *out) {
    Lead lead;
    int found = series_settle(&s, &lead);
    if (found < 0 && s.exact) { *out = s; return q.num > 0 ? 1 : -1; }
    if (found <= 0) return 0;
    if (lead.side < 0 && !odd) return -1;
    Series u;
    Rat c = series_unit(s, &u), cq;
    if (lead.side < 0) c = rat_add(rat_int(0), c, 1);
    if (!constant_power(c, q, &cq)) return 0;
    if (lead.side < 0) cq = rat_add(rat_int(0), cq, 1);

    /* L'esponente e q, con il denominatore che serve. */
    Frac shift = frac_make((__int128)s.low * q.num, (__int128)s.den * q.den);
    long long den = lcm_small(s.den, shift.den);
    if (den > MAX_SERIES_DEN || shift.num > MAX_EXPONENT / MAX_SERIES_DEN || shift.num < -MAX_EXPONENT / MAX_SERIES_DEN) return 0;
    Series sum = series_taylor(u, TAYLOR_BINOMIAL, q, lim_goal * s.den);
    sum = series_rescale(sum, (int)den);
    *out = series_shift(series_scale(sum, cq), (int)(shift.num * (den / shift.den)));
    return !failure;
}

/* Divide la serie s in *constant, il coefficiente di t^0 (zero se manca),
 * e *rest, i termini con esponente positivo e il resto. Ritorna 1 se s
 * tende a quel numero, cioè se dopo aver tolto gli zeri iniziali non restano
 * esponenti negativi, il resto tende a zero e il termine costante non
 * contiene L. Il segno del termine costante non serve. */
static int series_split(Series s, Rat *constant, Series *rest) {
    Lead lead;
    series_settle(&s, &lead);
    *constant = rat_int(0);
    if (s.end <= 0 || s.low < 0) return 0;
    *rest = s;
    if (s.count && s.low == 0) {
        *constant = s.coef[0];
        rest->coef++;
        rest->count--;
        rest->low++;
        *rest = series_trim(*rest);
    }
    return !rat_has_ell(*constant);
}

/* Le funzioni sui valori. Ognuna prova la serie (29e) e, se non c'è, il
 * limite (29g); un valore V_UNDEFINED o V_UNKNOWN passa com'è. */

/* e^v. */
static Value value_exp(Value v) {
    if (v.kind == V_UNDEFINED || v.kind == V_UNKNOWN) return v;

    /* Un esponente che ha già un fattore e^{G}: e^{e^{G} S} si sa solo come
     * limite, o come funzione piatta (29k-f). */
    v = value_plain(v);
    if (v.kind == V_UNKNOWN) return v;
    Value l = value_limit(v);
    if (v.kind == V_SERIES) {
        Series s = v.series, rest, negative;
        Rat constant, base;
        Lead lead;

        /* Limitata: e^{O(1)} è O(1), e positiva. Solo se l'O(1) è davvero
         * limitato, cioè se nessun coefficiente contiene L (lim_logs):
         * x \cdot x^{\sin(1/x)} = t e^{-L \sin(1/x)} risultava O(t), e il
         * limite 0 DIMOSTRATO, mentre in x = 1/(3\pi/2 + 2k\pi) la funzione
         * vale 1 (special_cases[] in tests/limits/test_limits.c). */
        if (series_settle(&s, &lead) < 0 && s.end == 0 && !lim_logs) return value_series(series_bounded(), 1);

        /* 29k-f. Se il resto tende a zero i termini di esponente negativo
         * sono noti tutti: sono il fattore e^{N}, e il resto si scrive con
         * il termine costante e una serie di Taylor. Il termine costante può
         * avere L al primo grado con un coefficiente razionale b:
         * e^{a + b L} = e^a t^{-b} (29d). Il coefficiente di t^0 non serve
         * con il segno: anche se gli intervalli non lo sanno dire, e^a si
         * scrive. */
        if (s.end > 0) {
            series_split_growth(s, &negative, &rest);
            s = rest;
            constant = rat_int(0);
            if (s.count && s.low == 0) {
                constant = s.coef[0];
                rest.coef++;
                rest.count--;
                rest.low++;
                rest = series_trim(rest);
            }
            Frac b = frac_int(0);
            int linear = !rat_has_ell(constant);
            if (!linear && poly_is_one(constant.den)) {
                Poly without = poly_const(num_int(0));
                linear = 1;
                for (int i = 0; i < constant.num.count; i++) {
                    Term t = constant.num.term[i];
                    Frac e = mono_exponent(&t.mono, lim_ell);
                    if (e.num == 0) without = poly_add(without, poly_term(t), 0);
                    else if (frac_cmp(e, frac_int(1)) == 0 && t.mono.count == 1 && t.coef.im.num == 0) b = frac_add(b, t.coef.re);
                    else linear = 0;
                }
                constant = (Rat){without, poly_const(num_int(1))};
            }
            long long den = lcm_small(rest.den, b.den);
            if (b.num > MAX_EXPONENT / MAX_SERIES_DEN || b.num < -MAX_EXPONENT / MAX_SERIES_DEN) linear = 0;
            if (linear && den <= MAX_SERIES_DEN && constant_exp(constant, &base)) {
                Series sum = series_scale(series_taylor(rest, TAYLOR_EXP, frac_int(0), lim_goal * rest.den), base);
                sum = series_rescale(sum, (int)den);
                return value_grown(series_shift(sum, (int)(-b.num * (den / b.den))), negative, 1);
            }
        }
    }

    /* Senza uno sviluppo: e^{+\infty} = +\infty, e e^{-\infty} è più
     * piccola di ogni potenza di t, una funzione piatta e positiva. */
    if (l.kind == V_LIMIT && l.infinite > 0) return value_infinite(1);
    if (l.kind == V_LIMIT && l.infinite < 0) return value_series(series_flat(), 1);

    /* e^L per un limite finito L. */
    Rat value;
    if (l.kind == V_LIMIT && !l.infinite && constant_exp(l.value, &value)) {
        Value r = value_finite(value, l.approach);
        r.positive = 1;
        return r;
    }
    return l.kind == V_UNKNOWN ? l : value_failed(V_UNKNOWN, "un esponenziale di cui non si sa scrivere né lo sviluppo né il limite");
}

/* ln v (29d). */
static Value value_ln(Value v) {
    if (v.kind == V_UNDEFINED || v.kind == V_UNKNOWN) return v;

    /* 29k-e. ln(e^{G} S) = G + ln S. */
    if (value_grows(v)) {
        Series s = v.series;
        Lead lead;
        int found = series_settle(&s, &lead), ok = 0;
        if (found == 1 && lead.side < 0) return value_failed(V_UNDEFINED, "il logaritmo di un numero negativo");
        if (found == 1) {
            Value rest = value_ln(value_series(v.series, 1));
            Series sum;
            if (rest.kind == V_SERIES && !value_grows(rest)) sum = series_add(v.growth, rest.series, 0, &ok);
            if (ok && !failure) return value_series(sum, 0);
        }
        v = value_plain(v);
        if (v.kind == V_UNKNOWN) return v;
    }
    if (v.kind == V_SERIES) {
        Series s = v.series, u;
        Lead lead;
        int found = series_settle(&s, &lead);
        if (found == 1 && lead.side < 0) return value_failed(V_UNDEFINED, "il logaritmo di un numero negativo");
        Rat c, logarithm_c;
        if (found == 1 && !rat_has_ell(s.coef[0])) {
            c = series_unit(s, &u);
            if (constant_ln(c, &logarithm_c)) {
                /* ln c - (low/D) L, più ln(1 + u). */
                Rat ell = rat_mul(rat_frac(frac_make(-s.low, s.den)), rat_atom(lim_ell));
                int ok;
                if (s.low) lim_logs = 1;
                Series sum = series_add(series_taylor(u, TAYLOR_LOG, frac_int(0), lim_goal * u.den), series_const(rat_add(logarithm_c, ell, 0)), 0, &ok);
                if (ok) return value_series(sum, 0);
            }
        }
    }
    Value l = value_limit(v);
    if (l.kind != V_LIMIT) return l;
    if (l.infinite) return l.infinite > 0 ? value_infinite(1) : value_failed(V_UNDEFINED, "il logaritmo di un numero negativo");
    int side;
    Rat value;
    if (!limit_sign(l, &side)) return value_failed(V_UNKNOWN, "un limite ha un segno che gli intervalli non sanno stabilire");
    if (side < 0 || (side == 0 && l.approach < 0)) return value_failed(V_UNDEFINED, "il logaritmo di un numero negativo");
    if (side == 0) return l.approach > 0 ? value_infinite(-1) : value_failed(V_UNKNOWN, "l'argomento di un logaritmo tende a 0 senza un segno noto");
    if (!constant_ln(l.value, &value)) return value_failed(V_UNKNOWN, "un logaritmo di una costante che il programma non sa scrivere");
    return value_finite(value, 0);
}

/* sin v, cos v, tan v, cot v: fn dice quale. Seno e coseno di ciò che non
 * tende a un numero sono comunque O(1) (29e). */
static Value value_trig(Value v, Function fn) {
    v = value_plain(v);
    if (v.kind == V_UNDEFINED || v.kind == V_UNKNOWN) return v;
    int quotient = fn == FN_TAN || fn == FN_COT, ok = 1;
    Value bounded = quotient ? value_failed(V_UNKNOWN, "la tangente di qualcosa che non tende a un numero") : value_series(series_bounded(), 0);
    Rat u0, sine, cosine;
    Series s, c, w;
    if (v.kind == V_SERIES) {
        if (!series_split(v.series, &u0, &w)) return bounded;
        if (!constant_sin_cos(u0, &sine, &cosine)) return quotient ? value_failed(V_UNKNOWN, "seno e coseno di una costante") : bounded;
        Series ws = series_taylor(w, TAYLOR_SIN, frac_int(0), lim_goal * w.den), wc = series_taylor(w, TAYLOR_COS, frac_int(0), lim_goal * w.den);
        s = series_add(series_scale(wc, sine), series_scale(ws, cosine), 0, &ok);
        c = series_add(series_scale(wc, cosine), series_scale(ws, sine), 1, &ok);
        if (!ok) return value_failed(V_UNKNOWN, "denominatori degli esponenti troppo grandi");
        if (fn == FN_SIN) return value_series(s, 0);
        if (fn == FN_COS) return value_series(c, 0);
        Series inverse, result;
        int inverted = series_inverse(fn == FN_TAN ? c : s, &inverse);
        if (inverted < 0) return value_failed(V_UNDEFINED, "una tangente dove il coseno vale zero");
        if (inverted > 0) result = series_mul(fn == FN_TAN ? s : c, inverse, &ok);
        if (inverted > 0 && ok) return value_series(result, 0);
        return value_failed(V_UNKNOWN, "il denominatore di una tangente ha uno sviluppo di cui non si trova il termine principale");
    }
    if (v.infinite) return bounded;
    if (!constant_sin_cos(v.value, &sine, &cosine)) return value_failed(V_UNKNOWN, "seno e coseno di una costante");
    if (fn == FN_SIN) return value_finite(sine, 0);
    if (fn == FN_COS) return value_finite(cosine, 0);
    int side;
    Rat below = fn == FN_TAN ? cosine : sine;
    if (constant_sign(below, &side) != 1) return value_failed(V_UNKNOWN, "una tangente in un punto in cui non si sa se il coseno è zero");
    return value_finite(rat_div(fn == FN_TAN ? sine : cosine, below), 0);
}

/* arctan v (29e). */
static Value value_arctan(Value v) {
    v = value_plain(v);
    if (v.kind == V_UNDEFINED || v.kind == V_UNKNOWN) return v;
    Rat half_pi = rat_div(rat_atom(atom_var(VAR_PI)), rat_int(2)), u0;
    int ok = 1;
    if (v.kind == V_SERIES) {
        Series s = v.series, w, inverse;
        Lead lead;
        int found = series_settle(&s, &lead);

        /* Verso +\infty o -\infty: \pm pi/2 - arctan(1/v). */
        if (found == 1 && s.low < 0 && series_inverse(s, &inverse) == 1) {
            Series sum = series_taylor(inverse, TAYLOR_ATAN, frac_int(0), lim_goal * inverse.den);
            sum = series_add(series_const(lead.side > 0 ? half_pi : rat_add(rat_int(0), half_pi, 1)), sum, 1, &ok);
            if (ok) return value_series(sum, 0);
        }

        /* Verso un numero u0: arctan u0 + arctan(w / (1 + u0 v)). È la
         * formula di sottrazione, arctan a - arctan b = arctan((a - b) /
         * (1 + a b)), che vale quando a b > -1: qui a b = u0 v tende a
         * u0^2, e 1 + u0 v resta lontano da zero. */
        if (series_split(s, &u0, &w) && poly_is_real(u0.num) && poly_is_real(u0.den)) {
            Series below = series_add(series_const(rat_int(1)), series_scale(s, u0), 0, &ok), z;
            if (ok && series_inverse(below, &z) == 1) {
                z = series_mul(w, z, &ok);
                Series sum = series_add(series_const(arctangent(u0)), series_taylor(z, TAYLOR_ATAN, frac_int(0), lim_goal * z.den), 0, &ok);
                if (ok && !failure) return value_series(sum, 0);
            }
        }
        return value_series(series_bounded(), 0);
    }
    Value l = value_limit(v);
    if (l.kind != V_LIMIT) return value_series(series_bounded(), 0);
    if (l.infinite) return value_finite(l.infinite > 0 ? half_pi : rat_add(rat_int(0), half_pi, 1), -l.infinite);
    if (!poly_is_real(l.value.num) || !poly_is_real(l.value.den)) return value_series(series_bounded(), 0);
    return value_finite(arctangent(l.value), 0);
}

/* v^n, per n intero. */
static Value value_power_int(Value v, long long n) {
    if (v.kind == V_UNDEFINED || v.kind == V_UNKNOWN) return v;
    if (n == 0) return value_series(series_const(rat_int(1)), 1);
    if (n > MAX_POWER || n < -MAX_POWER) return value_failed(V_UNKNOWN, "un esponente intero troppo grande");
    Series result;
    if (v.kind == V_SERIES) {
        /* 29k-e: (e^{G} S)^n = e^{n G} S^n. */
        int done = series_power_int(v.series, n, &result);
        if (done < 0) return value_failed(V_UNDEFINED, "una potenza negativa di una funzione che vale zero");
        if (done > 0) return value_grown(result, series_scale(v.growth, rat_int(n)), v.positive);
        v = value_plain(v);
        if (v.kind == V_UNKNOWN) return v;
    }
    Value l = value_limit(v), r = value_finite(rat_int(1), 0);
    if (l.kind != V_LIMIT) return l;
    if (n < 0) { l = limit_inverse(l); n = -n; }
    for (long long i = 0; i < n && r.kind == V_LIMIT; i++) r = limit_mul(r, l);
    return r;
}

/* v^q per q razionale non intero; odd come per series_power(). */
static Value value_power(Value v, Frac q, int odd) {
    if (v.kind == V_UNDEFINED || v.kind == V_UNKNOWN) return v;
    const char *negative = odd ? "" : "una potenza a esponente non intero, o una radice di indice pari, di un numero negativo";
    Series result;
    if (v.kind == V_SERIES) {
        /* 29k-e: (e^{G} S)^q = e^{q G} S^q, perché e^{G} > 0; con una
         * radice di indice dispari e S < 0, -(e^{q G} |S|^q). */
        int done = series_power(v.series, q, odd, &result);
        if (done < 0) return value_failed(V_UNDEFINED, q.num < 0 && v.series.exact ? "una potenza negativa di zero" : negative);
        if (done > 0) return value_grown(result, series_scale(v.growth, rat_frac(q)), 0);
        v = value_plain(v);
        if (v.kind == V_UNKNOWN) return v;
    }
    Value l = value_limit(v);
    int side;
    Rat value;
    if (l.kind != V_LIMIT) return l;
    if (l.infinite) {
        if (l.infinite < 0 && !odd) return value_failed(V_UNDEFINED, negative);
        return q.num > 0 ? value_infinite(l.infinite) : value_finite(rat_int(0), l.infinite);
    }
    if (!limit_sign(l, &side)) return value_failed(V_UNKNOWN, "un limite ha un segno che gli intervalli non sanno stabilire");
    if ((side < 0 || (side == 0 && l.approach < 0)) && !odd) return value_failed(V_UNDEFINED, negative);
    if (side == 0 && !l.approach) return value_failed(V_UNKNOWN, "la base di una potenza tende a 0 senza un segno noto");
    if (side == 0) return q.num > 0 ? value_finite(rat_int(0), l.approach) : value_infinite(l.approach);
    Rat base = side < 0 ? rat_add(rat_int(0), l.value, 1) : l.value;
    if (!constant_power(base, q, &value)) return value_failed(V_UNKNOWN, "una potenza di una costante che il programma non sa scrivere");
    return value_finite(side < 0 ? rat_add(rat_int(0), value, 1) : value, 0);
}

/* |v|. */
static Value value_abs(Value v) {
    if (v.kind == V_UNDEFINED || v.kind == V_UNKNOWN) return v;
    if (v.kind == V_SERIES) {
        /* |e^{G} S| = e^{G} |S|. */
        Series s = v.series;
        Lead lead;
        int found = series_settle(&s, &lead);
        if (found == 1) return value_grown(lead.side < 0 ? series_scale(s, rat_int(-1)) : s, v.growth, 1);
        if (found < 0) return value_grown(s, v.growth, 0);
        v = value_plain(v);
        if (v.kind == V_UNKNOWN) return v;
    }
    Value l = value_limit(v);
    int side;
    if (l.kind != V_LIMIT) return l;
    if (l.infinite) return value_infinite(1);
    if (!limit_sign(l, &side)) return value_failed(V_UNKNOWN, "un limite ha un segno che gli intervalli non sanno stabilire");
    return value_finite(side < 0 ? rat_add(rat_int(0), l.value, 1) : l.value, side ? 0 : l.approach ? 1 : 0);
}

/* 29k-c, 29k-d. a + b, a - b, a b, a / b con un fattore e^{G} in almeno
 * uno dei due, tutti e due serie. Ritorna V_UNKNOWN se il conto non si fa:
 * allora chi chiama ricomincia con value_plain(). */
static Value growth_binary(NodeKind op, Value a, Value b, int positive) {
    int ok = 1, dir;
    if (op == N_MUL || op == N_DIV) {
        Series factor = b.series;
        if (op == N_DIV) {
            int inverted = series_inverse(b.series, &factor);
            if (inverted < 0) return value_failed(V_UNDEFINED, "una divisione per una funzione che vale zero");
            if (inverted == 0) return value_failed(V_UNKNOWN, "un divisore con un esponenziale di cui non si trova il termine principale");
        }
        Series s = series_mul(a.series, factor, &ok), g = ok ? series_add(a.growth, b.growth, op == N_DIV, &ok) : NO_GROWTH;
        if (!ok || failure) return value_failed(V_UNKNOWN, "denominatori degli esponenti troppo grandi");
        return value_grown(s, g, positive);
    }

    /* Una somma con uno zero esatto è l'altro addendo, esatto com'è: lo zero
     * non ha esponente, ma non per questo "cresce di più" di e^{-1/t}. Per
     * l'invariante di Value uno zero esatto non ha fattore. */
    if (a.series.exact && series_trim(a.series).count == 0) return op == N_SUB ? value_grown(series_scale(b.series, rat_int(-1)), b.growth, 0) : b;
    if (b.series.exact && series_trim(b.series).count == 0) return a;

    /* Una somma: chi cresce di più, con la differenza degli esponenti. */
    Series delta = series_add(a.growth, b.growth, 1, &ok);
    int known = ok && delta.exact ? growth_direction(delta, &dir) : -1;
    if (known < 0) return value_failed(V_UNKNOWN, "non si sa quale dei due esponenziali cresce di più");
    if (known == 0) {
        Series s = series_add(a.series, b.series, op == N_SUB, &ok);
        return ok ? value_grown(s, a.growth, positive) : value_failed(V_UNKNOWN, "denominatori degli esponenti troppo grandi");
    }

    /* Quello che cresce di meno diventa una funzione piatta accanto
     * all'altro (29k-c). */
    Value big = dir > 0 ? a : b;
    Series s = dir < 0 && op == N_SUB ? series_scale(big.series, rat_int(-1)) : big.series;
    s = series_add(s, series_flat(), 0, &ok);
    return ok ? value_grown(s, big.growth, positive) : value_failed(V_UNKNOWN, "denominatori degli esponenti troppo grandi");
}

/* a + b, a - b, a b, a / b: op è N_ADD, N_SUB, N_MUL o N_DIV. */
static Value value_binary(NodeKind op, Value a, Value b) {
    if (a.kind == V_UNDEFINED) return a;
    if (b.kind == V_UNDEFINED) return b;
    if (a.kind == V_UNKNOWN) return a;
    if (b.kind == V_UNKNOWN) return b;
    int ok = 0, positive = a.positive && b.positive && op != N_SUB;
    Series result, inverse;

    /* Con il fattore e^{G} (29k); se il conto non si fa, l'algebra dei
     * limiti come prima della scala. */
    if (value_grows(a) || value_grows(b)) {
        if (a.kind == V_SERIES && b.kind == V_SERIES) {
            Value r = growth_binary(op, a, b, positive);
            if (r.kind != V_UNKNOWN) return r;
            failure = NULL;
        }
        a = value_plain(a);
        b = value_plain(b);
        if (a.kind == V_UNKNOWN) return a;
        if (b.kind == V_UNKNOWN) return b;
    }
    if (a.kind == V_SERIES && b.kind == V_SERIES) {
        if (op == N_ADD || op == N_SUB) result = series_add(a.series, b.series, op == N_SUB, &ok);
        if (op == N_MUL) result = series_mul(a.series, b.series, &ok);
        if (op == N_DIV) {
            int inverted = series_inverse(b.series, &inverse);
            if (inverted < 0) return value_failed(V_UNDEFINED, "una divisione per una funzione che vale zero");
            if (inverted > 0) result = series_mul(a.series, inverse, &ok);
        }
        if (ok && !failure) return value_series(result, positive);
    }
    Value la = value_limit(a), lb = value_limit(b), r;
    if (la.kind != V_LIMIT) return la;
    if (lb.kind != V_LIMIT) return lb;
    if (op == N_ADD) r = limit_add(la, lb);
    else if (op == N_SUB) r = limit_add(la, limit_neg(lb));
    else if (op == N_MUL) r = limit_mul(la, lb);
    else if (la.infinite && lb.infinite) r = value_failed(V_UNKNOWN, "forma indeterminata: \\infty / \\infty");
    else if (!la.infinite && !lb.infinite && la.value.num.count == 0 && lb.value.num.count == 0) r = value_failed(V_UNKNOWN, "forma indeterminata: 0 / 0");
    else r = (lb = limit_inverse(lb)).kind == V_LIMIT ? limit_mul(la, lb) : lb;
    if (r.kind == V_LIMIT) r.positive = positive;
    return r;
}

/* Se v è una costante esatta (una serie esatta con il solo termine t^0, o
 * zero) la mette in *c e ritorna 1. */
static int value_constant(Value v, Rat *c) {
    if (v.kind != V_SERIES || value_grows(v) || !v.series.exact || v.series.count > 1 || (v.series.count == 1 && v.series.low != 0)) return 0;
    *c = v.series.count ? v.series.coef[0] : rat_int(0);
    return 1;
}

/* Se il conto r non è riuscito e uno dei suoi operandi a, b è una serie di
 * cui non si conosce nessun coefficiente, ritorna NEEDS_PRECISION: con più
 * termini il termine principale di quell'operando può comparire (29c).
 * Altrimenti ritorna r. */
static Value precision_or(Value r, Value a, Value b) {
    Value operand[2] = {a, b};
    if (r.kind != V_UNKNOWN) return r;
    for (int i = 0; i < 2; i++) {
        Series s = operand[i].series;
        Lead lead;
        if (operand[i].kind == V_SERIES && series_settle(&s, &lead) < 0 && !s.exact && s.end < SERIES_FLAT)
            return value_failed(V_UNKNOWN, NEEDS_PRECISION);
    }
    return r;
}

/* Prototipo in avanti inevitabile: una funzione ha argomenti, che sono
 * espressioni, e il logaritmo e la radice hanno anche una base e un indice. */
static Value limit_eval(const Node *node);

/* Ritorna arcsin u, o arccos u se cosine è 1, scritto con l'arcotangente e
 * la radice quadrata, le funzioni che lo sviluppo in serie conosce:
 *
 *     \arcsin u = 2 \arctan(u / (1 + \sqrt{1 - u^2})),     \arccos u = \pi/2 - \arcsin u.
 *
 * È la bisezione dell'angolo: se a = \arcsin u, con a tra -\pi/2 e \pi/2,
 * allora tan(a/2) = sin a / (1 + cos a) = u / (1 + \sqrt{1 - u^2}), perché
 * cos a = \sqrt{1 - u^2} non è negativo; e a/2 sta tra -\pi/4 e \pi/4, dove
 * l'arcotangente inverte la tangente. Vale anche in u = 1 e u = -1, e non
 * altrove, perché fuori da [-1, 1] la radice non c'è: il campo di esistenza
 * è lo stesso. L'albero ritornato sta nell'arena e condivide u. */
static Node *arcsin_by_arctan(Node *u, int cosine) {
    Node *root = node_call(FN_ROOT, node_new(N_SUB, node_num(1), node_new(N_POW, u, node_num(2))), node_num(2));
    Node *value = node_new(N_MUL, node_num(2), node_call(FN_ARCTAN, node_new(N_DIV, u, node_new(N_ADD, node_num(1), root)), NULL));
    if (!cosine) return value;
    Node *pi = node_new(N_VAR, NULL, NULL);
    pi->name = VAR_PI;
    return node_new(N_SUB, node_new(N_DIV, pi, node_num(2)), value);
}

/* Il valore della chiamata di funzione node, con l'argomento che vale a. */
static Value limit_call(const Node *node, Value a) {
    Rat c;
    Num index;
    switch ((Function)node->op) {
    case FN_SIN: case FN_COS: case FN_TAN: case FN_COT:
        return value_trig(a, (Function)node->op);
    case FN_ARCTAN:
        return value_arctan(a);
    case FN_ARCSIN: case FN_ARCCOS:
        /* L'argomento si ricalcola dentro la riscrittura: a non serve. */
        return limit_eval(arcsin_by_arctan(node->a, node->op == FN_ARCCOS));
    case FN_LN:
        return value_ln(a);
    case FN_LOG:
        return value_binary(N_DIV, value_ln(a), value_ln(limit_eval(node->b)));
    case FN_ABS:
        return value_abs(a);
    case FN_ROOT:
        if (!value_constant(limit_eval(node->b), &c) || !rat_number(c, &index) || index.im.num != 0 || index.re.den != 1 || index.re.num < 2)
            return value_failed(V_UNKNOWN, "una radice con un indice che non è un intero da 2 in su");
        return value_power(a, (Frac){1, index.re.num}, index.re.num % 2);
    default:
        return value_failed(V_UNKNOWN, "una funzione che il capitolo dei limiti non tratta");
    }
}

/* Il valore dell'espressione node vicino al punto, dal lato in corso. Le
 * lettere ammesse sono la variabile, e e pi (lo controlla prove_limit()). */
static Value limit_eval(const Node *node) {
    Value a, b;
    Rat c;
    Num number;
    if (failure) return value_failed(V_UNKNOWN, failure);
    switch (node->kind) {
    case N_NUM:
        return value_series(series_const(rat_int(node->value)), node->value > 0);
    case N_VAR:
        if (node->name == VAR_PI || node->name == 'e') return value_series(series_const(rat_atom(atom_var(node->name))), 1);
        if (node->name != lim_x) return value_failed(V_UNKNOWN, "una lettera diversa dalla variabile del limite");
        if (lim_moved) {
            /* 29l: x = \pm e^{1/t} all'infinito, x = \pm e^{-1/t} vicino a 0. */
            Series g = series_make(1, -1, 1, SERIES_FLAT, 1);
            int sign = lim_infinity ? lim_infinity : lim_side;
            if (!g.count) return value_failed(V_UNKNOWN, OUT_OF_MEMORY);
            g.coef[0] = rat_int(lim_infinity ? 1 : -1);
            return value_grown(series_const(rat_int(sign)), g, sign > 0);
        }
        if (lim_infinity) {
            /* x = 1/t oppure x = -1/t. */
            Series s = series_make(1, -1, 1, SERIES_FLAT, 1);
            if (!s.count) return value_failed(V_UNKNOWN, OUT_OF_MEMORY);
            s.coef[0] = rat_int(lim_infinity);
            return value_series(s, lim_infinity > 0);
        } else {
            /* x = a + t oppure x = a - t. */
            Series s = series_make(1, 0, 2, SERIES_FLAT, 1);
            if (!s.count) return value_failed(V_UNKNOWN, OUT_OF_MEMORY);
            s.coef[0] = lim_point;
            s.coef[1] = rat_int(lim_side);
            return value_series(series_trim(s), 0);
        }
    case N_NEG:
        a = limit_eval(node->a);
        return precision_or(value_binary(N_SUB, value_series(series_const(rat_int(0)), 0), a), a, a);
    case N_ADD: case N_SUB: case N_MUL: case N_DIV:
        a = limit_eval(node->a);
        b = limit_eval(node->b);
        return precision_or(value_binary(node->kind, a, b), a, b);
    case N_POW:
        b = limit_eval(node->b);
        a = limit_eval(node->a);
        if (b.kind == V_UNDEFINED || b.kind == V_UNKNOWN) return b;

        /* Un esponente costante razionale: una potenza (29f). */
        if (value_constant(b, &c) && rat_number(c, &number) && number.im.num == 0)
            return precision_or(number.re.den == 1 ? value_power_int(a, number.re.num) : value_power(a, number.re, 0), a, a);

        /* f^g = e^{g ln f}, definita dove f > 0. La dimostrazione lo dice
         * quando conta, cioè quando la base dipende dalla variabile. */
        lim_exponential |= node_has_variable(node->b, lim_x) && node_has_variable(node->a, lim_x);
        return precision_or(value_exp(value_binary(N_MUL, b, value_ln(a))), a, b);
    case N_CALL:
        a = limit_eval(node->a);
        return precision_or(limit_call(node, a), a, a);
    default:
        return value_failed(V_UNKNOWN, "somme, prodotti e successioni con l'indice non sono trattati nei limiti");
    }
}

/* UN LATO ALLA VOLTA (29a) */

/* Gli esiti del controllo con i numeri di un lato (29i). */
typedef enum { CHECK_UNCONFIRMED, CHECK_CONFIRMED, CHECK_CONTRADICTED } CheckResult;

/* Il limite da un lato: ciò che il conto ha dato e ciò che i numeri ne
 * dicono. */
typedef struct {
    int side;          /* +1 da destra, -1 da sinistra, 0 per un punto all'infinito */
    Value value;       /* la funzione vicino al punto */
    Value limit;       /* il suo limite: V_LIMIT, V_UNDEFINED o V_UNKNOWN */
    int quotient;      /* 1 se la funzione è un quoziente: allora parts[] sono i suoi termini */
    Value parts[2];
    CheckResult check; /* il controllo con i numeri */
    int first, last;   /* i k dei punti x = a \pm 2^{-k} o x = \pm 2^{k} che il controllo ha usato */
    int moved;         /* 1 se il conto è fatto con la sostituzione di 29l */
    int goal;          /* la precisione del conto ritornato, lim_goal: l'ordine del certificato (29n) */
} SideResult;

/* Calcola in *r il limite di f dal lato side (29a), con precisioni via via
 * più alte finché il termine principale non si trova (29c). Se così non si
 * arriva a un limite, e il punto è 0 o un infinito, si riprova salendo di un
 * piano (29l): r->moved lo dice, e lim_moved resta quello del conto
 * ritornato. La memoria dell'ultimo tentativo resta: la usa la
 * dimostrazione scritta. */
static void limit_side(const Node *f, int side, SideResult *r) {
    int goals = (int)(sizeof series_goals / sizeof *series_goals);
    int moves = lim_infinity || lim_point.num.count == 0 ? 2 : 1;
    const char *first = NULL;
    memset(r, 0, sizeof *r);
    r->side = side;
    for (int moved = 0; moved < moves; moved++) {
        /* Se anche il secondo piano non arriva a un limite, il motivo da
         * dire è quello del primo, il conto dei libri. */
        if (moved) first = r->limit.why;
        for (int g = 0; g < goals; g++) {
            Scratch mark = scratch_mark();
            failure = NULL;
            lim_goal = r->goal = series_goals[g];
            lim_side = side;
            lim_moved = r->moved = moved;
            lim_logs = 0;
            lim_ell = atom_var(VAR_LOG_SCALE);
            r->quotient = f->kind == N_DIV;
            if (r->quotient) {
                r->parts[0] = limit_eval(f->a);
                r->parts[1] = limit_eval(f->b);
                r->value = precision_or(value_binary(N_DIV, r->parts[0], r->parts[1]), r->parts[0], r->parts[1]);
            } else {
                r->value = limit_eval(f);
            }
            r->limit = value_limit(r->value);
            if (failure) r->limit = value_failed(V_UNKNOWN, failure);
            failure = NULL;
            if (r->limit.kind != V_UNKNOWN) return;
            if (r->limit.why != NEEDS_PRECISION || g + 1 == goals) {
                if (moved + 1 == moves) {
                    if (first) r->limit.why = first;
                    return;
                }
                scratch_drop(mark);
                break;
            }
            scratch_drop(mark);
        }
    }
}

/* Ritorna l'intervallo di x nel punto k-esimo del lato di r: a \pm 2^{-k},
 * oppure \pm 2^{k} all'infinito. */
static Range sample_point(const SideResult *r, int k, Range point) {
    double t = 1;
    for (int i = 0; i < k; i++) t /= 2;
    if (lim_infinity) return (Range){lim_infinity / t, lim_infinity / t};
    return range_add(point, (Range){r->side * t, r->side * t});
}

/* Ritorna l'intervallo di L = ln(1/t) nel punto k-esimo: k ln 2, perché
 * t = 2^{-k}; con la sostituzione di 29l ln(k ln 2), perché lì
 * 1/t = |ln |x - a|| = k ln 2. */
static Range ell_at(const SideResult *r, int k) {
    Range ell = range_mul(range_ratio(k, 1), range_ln2());
    return r->moved ? range_ln(ell) : ell;
}

/* Ritorna l'intervallo di c t^e L^d, con t^e = e^{-e L}. */
static Range leading_at(Range c, Frac e, Frac d, Range ell) {
    Range power = range_exp(range_mul(range_ratio(-e.num, e.den), ell));
    Range logs = d.den == 1 ? range_power(ell, d.num) : range_exp(range_mul(range_ratio(d.num, d.den), range_ln(ell)));
    return range_mul(c, range_mul(power, logs));
}

/* Ritorna l'intervallo del fattore e^{G} (29k) dove L vale ell: G è esatto,
 * e si calcola termine per termine, con L nei coefficienti. */
static Range growth_at(Series g, Range ell) {
    Range sum = {0, 0};
    lim_ell_range = ell;
    for (int i = 0; i < g.count; i++) {
        if (g.coef[i].num.count == 0) continue;
        Range power = range_exp(range_mul(range_ratio(-(g.low + i), g.den), ell));
        sum = range_add(sum, range_mul(constant_range(g.coef[i]), power));
    }
    lim_ell_range = range_none();
    return range_exp(sum);
}

/* Ritorna un intervallo per ln|g(far)| - ln|g(near)|, con g = c t^e L^d
 * e^{G} e L che vale near e far nei due punti: -e (far - near) +
 * d (ln far - ln near) + G(far) - G(near), senza calcolare g, che uscirebbe
 * dai numeri della macchina. Il coefficiente c si cancella. */
static Range leading_climb(Frac e, Frac d, Series g, Range near, Range far) {
    Range climb = range_add(range_mul(range_ratio(-e.num, e.den), range_sub(far, near)),
                            range_mul(range_ratio(d.num, d.den), range_sub(range_ln(far), range_ln(near))));
    for (int i = 0; i < g.count; i++) {
        if (g.coef[i].num.count == 0) continue;
        Range rate = range_ratio(-(g.low + i), g.den), at[2];
        for (int k = 0; k < 2; k++) {
            lim_ell_range = k ? far : near;
            at[k] = range_mul(constant_range(g.coef[i]), range_exp(range_mul(rate, lim_ell_range)));
        }
        lim_ell_range = range_none();
        climb = range_add(climb, range_sub(at[1], at[0]));
    }
    return climb;
}

/* La stima del resto del controllo con i numeri, 16 (1 + |L|) t^{B} con
 * t^{B} = e^{-B ell}, come numero sicuramente non più grande del vero; -1
 * se non si calcola. number contiene il limite L. */
static double remainder_limit(Range number, Frac bound, Range ell) {
    Range power = range_exp(range_mul(range_ratio(-bound.num, bound.den), ell));
    return range_known(power) ? 16 * (1 + (number.high > -number.low ? number.high : -number.low)) * power.low : -1;
}

/* 29i. Il controllo con i numeri del lato r: la funzione f calcolata con gli
 * intervalli (node_range(), capitolo 24) nei punti t = 2^{-k}, contro ciò che
 * il conto ha dato. Vedi la testa del capitolo per il criterio e per ciò che
 * garantisce. Mette l'esito in r->check, e in r->first, r->last i k usati. */
static void limit_check(const Node *f, SideResult *r) {
    Range point = lim_infinity ? range_none() : constant_range(lim_point), number = range_none(), c = range_none();
    Frac e = {0, 1}, d = {0, 1};
    Series growth = NO_GROWTH;
    int expected = 0, finite = r->limit.kind == V_LIMIT && !r->limit.infinite, defined[2] = {0, 0}, count = 0;
    r->check = CHECK_UNCONFIRMED;
    if (!lim_infinity && !range_known(point)) return;

    /* Il termine principale atteso, di f - L o di f, se il conto l'ha dato
     * con una serie. Con il fattore e^{G} il limite finito è 0, e f - 0 è
     * e^{G} S: il termine principale è quello di S, per e^{G}. */
    /* Senza termine principale, ma con un resto noto per f - L, il resto dà
     * una stima: |f - L| <= C t^{E} se f - L = O(t^{E}), e |f - L| è più
     * piccolo di ogni potenza se è piatta o ha un fattore e^{G} con
     * G -> -\infty. Il controllo chiede allora |f - L| <= 16 (1 + |L|) t^{B}
     * nell'ultimo punto, con B = min(E, 1), e B = 4 per una funzione piatta:
     * un L sbagliato lascia |f - L| vicino a un numero fisso, e non passa
     * (vedi la testa del capitolo). B = 4 perché a volte i soli punti che
     * si sanno calcolare hanno t ancora grande, come e^{1/x^2} che esce dai
     * numeri della macchina già in x = 1/32, o dopo la sostituzione di 29l,
     * dove t = 1/(k ln 2). */
    int bounded = 0;
    Frac bound = {4, 1};
    if (finite) number = constant_range(r->limit.value);
    if (r->limit.kind == V_LIMIT && r->value.kind == V_SERIES) {
        int ok = 1, grows = value_grows(r->value);
        Series s = finite && !grows ? series_add(r->value.series, series_const(r->limit.value), 1, &ok) : r->value.series;
        Lead lead;
        int found = ok ? series_settle(&s, &lead) : 0;
        if (found == 1) {
            expected = 1;
            c = constant_range(lead.value);
            e = frac_make(s.low, s.den);
            d = lead.degree;
            if (grows) growth = r->value.growth;
        } else if (found < 0 && finite && !s.exact && s.end > 0) {
            bounded = 1;
            if (!grows && s.end < SERIES_FLAT) bound = s.end < s.den ? frac_make(s.end, s.den) : frac_int(1);
        }
        failure = NULL;
    }

    /* I punti, finché stanno dalla parte giusta del punto. Dopo la
     * sostituzione di 29l L cresce come ln k: i punti vanno più lontano. Con
     * un fattore e^{G} la funzione esce presto dai numeri della macchina
     * ((1 + e^{1/x^3})^{\sin x} già in x = 1/16): si parte allora da k = 1,
     * e conta l'ultimo punto che si sa calcolare. */
    Range kept[2] = {range_none(), range_none()};
    int kept_count = 0, step = r->moved ? 4 : 1, top = r->moved ? MOVED_SAMPLES : LIMIT_SAMPLES;
    for (int k = growth.count ? 1 : 4; k <= top; k += step) {
        Range x = sample_point(r, k, point);
        if (!range_known(x) || (!lim_infinity && (r->side > 0 ? x.low <= point.high : x.high >= point.low))) break;
        int nowhere = 0;
        Range value = node_range(f, lim_x, x, &nowhere);
        defined[count % 2] = nowhere ? -1 : range_known(value) ? 1 : 0;  /* gli ultimi due punti */
        count++;
        if (nowhere || !range_known(value) || r->limit.kind != V_LIMIT) continue;

        /* Il rapporto con il termine principale, oppure f - L, oppure f. Un
         * punto serve se l'intervallo è abbastanza stretto da dire qualcosa:
         * la larghezza decide solo quali punti guardare, non che cosa è
         * vero, che lo dicono poi i confronti certi tra intervalli. */
        Range q;
        double width;
        if (expected) {
            Range ell = ell_at(r, k);
            q = range_div(finite ? range_sub(value, number) : value, range_mul(leading_at(c, e, d, ell), growth_at(growth, ell)));
            width = 0.5;
        } else if (finite) {
            q = range_sub(value, number);
            width = (1 + (number.high > -number.low ? number.high : -number.low)) / 8;

            /* Con la stima del resto, un punto serve se l'intervallo è
             * stretto rispetto alla stima in quel punto. */
            double tight = bounded ? remainder_limit(number, bound, ell_at(r, k)) / 4 : -1;
            if (tight >= 0 && tight < width) width = tight;
        } else {
            q = range_mul(value, range_ratio(r->limit.infinite, 1));
            width = (q.low + q.high) / 2;
            width = (width < 0 ? -width : width) / 2;
        }
        if (!range_known(q) || q.high - q.low > width) continue;
        if (!r->first) r->first = k;
        r->last = k;
        kept[0] = kept[1];
        kept[1] = q;
        kept_count++;
    }

    /* Il campo di esistenza: negli ultimi due punti la funzione deve non
     * avere valori se il conto dice così, e averne altrimenti. */
    int last_two = count >= 2;
    if (r->limit.kind == V_UNDEFINED) {
        if (last_two && defined[0] < 0 && defined[1] < 0) r->check = CHECK_CONFIRMED;
        if (last_two && defined[0] > 0 && defined[1] > 0) r->check = CHECK_CONTRADICTED;
        return;
    }
    if (last_two && defined[0] < 0 && defined[1] < 0) { r->check = CHECK_CONTRADICTED; return; }
    if (r->limit.kind != V_LIMIT || kept_count == 0) return;

    /* Il valore. Con il termine principale g, anche la sua direzione: g
     * deve scendere tra due punti lontani se il limite è finito (f - L ~ g
     * va a zero), salire se è infinito. Così la regola che dal termine
     * principale ricava il limite (29c, 29k) è ricontrollata anche lei con i
     * numeri: un segno sbagliato di G la fa uscire, anche se f ~ g. */
    Range last = kept[1], before = kept[0];
    if (expected) {
        int out_last = last.high < 1.0 / 16 || last.low > 16, out_before = kept_count >= 2 && (before.high < 1.0 / 16 || before.low > 16);
        /* I due punti lontani, come valori di L = ln(1/t): è la formula di g
         * che si guarda, non f, e L può essere grande quanto si vuole. Con
         * un fattore e^{G} non troppo, perché G(t) resti tra i numeri della
         * macchina (G vi domina comunque il resto); senza, lontanissimi,
         * perché t^{e} batta L^{d} anche con d grande, come in
         * (\ln x)^{100} / x. */
        int side;
        Range near = growth.count ? range_mul(range_ratio(64, 1), range_ln2()) : range_ratio(1000000, 1);
        Range far = growth.count ? range_mul(range_ratio(256, 1), range_ln2()) : range_ratio(1000000000000, 1);
        Range climb = leading_climb(e, d, growth, near, far);

        /* Con un esponenziale, nel termine principale o in un termine
         * piatto accanto, i soli punti che si sanno calcolare possono stare
         * dove il termine principale non domina ancora: e^{\sqrt{1/t}}
         * supera t^{-7} solo da t = 2^{-12}, ma e^{2/t} esce dai numeri
         * della macchina già da t = 2^{-9}, e e^{-3/t} da t = 2^{-8}, anche
         * se trascurabile. Lì un rapporto lontano da 1 non conferma, ma non
         * smentisce: smentisce solo con un fattore e^{G} assente e punti
         * fino a t = 2^{-20}, come il limite infinito più sotto. */
        if (out_last && out_before) r->check = growth.count || r->last < 20 ? CHECK_UNCONFIRMED : CHECK_CONTRADICTED;
        else if (range_side(climb, &side) && side != (finite ? -1 : 1)) r->check = CHECK_CONTRADICTED;
        else if (last.low >= 1.0 / 16 && last.high <= 16) r->check = CHECK_CONFIRMED;
    } else if (finite && bounded) {
        double limit = remainder_limit(number, bound, ell_at(r, r->last));
        if (limit >= 0 && last.low >= -limit && last.high <= limit) r->check = CHECK_CONFIRMED;
    } else if (finite) {
        double size = (1 + (number.high > -number.low ? number.high : -number.low)) / 2;
        if (last.low >= -size && last.high <= size) r->check = CHECK_CONFIRMED;
    } else {
        if (kept_count >= 2 && r->last >= 20 && last.high < 0 && before.high < 0) r->check = CHECK_CONTRADICTED;
        else if (last.low >= 1) r->check = CHECK_CONFIRMED;
    }
}

/* LA DIMOSTRAZIONE SCRITTA */

/* Scrive il polinomio p, che contiene la lettera L, come somma di potenze
 * di L con i loro coefficienti tra parentesi. */
static void put_ell_poly(Poly p) {
    int written = 0;
    while (p.count > 0) {
        Frac top = mono_exponent(&p.term[0].mono, lim_ell);
        for (int i = 1; i < p.count; i++)
            if (frac_cmp(mono_exponent(&p.term[i].mono, lim_ell), top) > 0) top = mono_exponent(&p.term[i].mono, lim_ell);
        Term *high = terms_alloc(p.count), *low = terms_alloc(p.count);
        if (!high || !low) { unwritable = 1; return; }
        int highs = 0, lows = 0;
        for (int i = 0; i < p.count; i++) {
            Term t = p.term[i];
            if (frac_cmp(mono_exponent(&t.mono, lim_ell), top) != 0) { low[lows++] = t; continue; }
            t.mono = mono_with_exponent(&t.mono, lim_ell, frac_int(0));
            high[highs++] = t;
        }
        /* Un coefficiente razionale si scrive com'è, 1 e -1 davanti a L
         * si tacciono; gli altri vanno tra parentesi. */
        Poly group = poly_finish(high, p.count, highs);
        Num number;
        if (rat_number((Rat){group, poly_const(num_int(1))}, &number) && number.im.num == 0) {
            Frac size = number.re.num < 0 ? frac_neg(number.re) : number.re;
            proof_add("%s", number.re.num < 0 ? (written ? " - " : "-") : (written ? " + " : ""));
            if (size.num != 1 || size.den != 1 || !top.num) put_frac(size);
        } else {
            proof_add("%s\\left(", written ? " + " : "");
            put_terms(group);
            proof_add("\\right)");
        }
        written++;
        if (top.num) { proof_add(" L"); if (top.num != 1 || top.den != 1) { proof_add("^{"); put_frac(top); proof_add("}"); } }
        p = poly_finish(low, p.count, lows);
    }
}

/* Scrive il coefficiente c, anche con la lettera L. */
static void put_coefficient(Rat c) {
    if (!rat_has_ell(c)) { put_rat(c); return; }
    if (poly_is_one(c.den)) { put_ell_poly(c.num); return; }
    proof_add("\\frac{");
    put_ell_poly(c.num);
    proof_add("}{");
    put_ell_poly(c.den);
    proof_add("}");
}

/* Scrive t^{e}: niente per e = 0, t per e = 1. */
static void put_t_power(Frac e) {
    if (e.num == 0) return;
    proof_add("t");
    if (e.num != 1 || e.den != 1) { proof_add("^{"); put_frac(e); proof_add("}"); }
}

/* Scrive la serie s, al più shown termini con un coefficiente scritto
 * diverso da zero, e il resto. Ritorna 0, senza scrivere nulla, se un
 * coefficiente non si sa scrivere (contiene seni e coseni di costanti).
 *
 * Il resto scritto deve contenere tutto ciò che non si scrive. Se restano
 * termini non nulli oltre i primi shown, il resto parte dal primo di loro:
 * per t -> 0^+ i termini seguenti, con esponenti più alti, e il resto
 * calcolato O(t^{end}) sono tutti O(t^{e}), con e l'esponente del primo
 * omesso. Scrivere O(t^{end}) dopo aver tolto dei termini sarebbe falso: era
 * l'errore per cui 1/(1 + t) diventava "1 - t + O(t^{4})", dove manca
 * t^{2} - t^{3}. Una serie esatta (una somma finita) scrive invece i
 * puntini, che non dicono nulla di falso. */
static int put_series(Series s, int shown) {
    size_t start = proof_length;
    int written = 0, omitted = -1;
    unwritable = 0;
    s = series_trim(s);
    for (int i = 0; i < s.count; i++) {
        Rat c = s.coef[i];
        Num number;
        Frac e = frac_make(s.low + i, s.den);
        if (c.num.count == 0) continue;
        if (written == shown) { omitted = i; break; }
        if (rat_number(c, &number) && number.im.num == 0) {
            Frac size = number.re.num < 0 ? frac_neg(number.re) : number.re;
            int unit = size.num == 1 && size.den == 1 && e.num != 0;
            proof_add("%s", number.re.num < 0 ? (written ? " - " : "-") : (written ? " + " : ""));
            if (!unit) put_frac(size);
            if (!unit && e.num) proof_add("\\,");
        } else {
            if (written) proof_add(" + ");
            proof_add("\\left(");
            put_coefficient(c);
            proof_add("\\right)");
            if (e.num) proof_add("\\,");
        }
        put_t_power(e);
        written++;
    }
    /* Il resto: dal primo termine omesso, se c'è (vedi sopra). */
    if (s.exact && omitted >= 0) proof_add(" + \\dots");
    if (!s.exact && omitted < 0 && s.end >= SERIES_FLAT) proof_add("%so\\left(t^{k}\\right) \\text{ for every } k", written ? " + " : "");
    else if (!s.exact) {
        Frac e = frac_make(omitted >= 0 ? s.low + omitted : s.end, s.den);
        proof_add("%sO\\left(", written ? " + " : "");
        if (e.num == 0) proof_add("1"); else put_t_power(e);
        proof_add("\\right)");
    }
    if (s.exact && !written) proof_add("0");
    if (!unwritable && !failure) return 1;
    proof_cut(start);
    unwritable = 0;
    failure = NULL;
    return 0;
}

/* Scrive il limite l (V_LIMIT): +\infty, -\infty o il numero, e ne ritorna
 * il pezzo in *span. Ritorna 0, senza scrivere nulla, se il numero non si sa
 * scrivere. */
static int put_limit(Value l, Span *span) {
    span->from = proof_length;
    if (l.infinite) proof_add(l.infinite > 0 ? "+\\infty" : "-\\infty");
    else if (!put_value("", l.value, span)) return 0;
    span->to = proof_length;
    return 1;
}

/* Ritorna 1 se le lettere di node sono solo x (se non è 0), e e pi, e non
 * ci sono somme, successioni o applicazioni. */
static int limit_letters(const Node *node, int x) {
    if (!node) return 1;
    if (node->kind == N_VAR) return node->name == x || node->name == 'e' || node->name == VAR_PI;
    if (node->kind == N_SEQ || node->kind == N_BIGOP || node->kind == N_APPLY) return 0;
    return limit_letters(node->a, x) && limit_letters(node->b, x) && limit_letters(node->c, x);
}

/* Ritorna 1 se il testo text, un valore scritto (+\infty, -\infty o
 * un'espressione senza la variabile), riletto con il lettore del capitolo 9
 * e calcolato da capo, è il limite l (29j). */
static int limit_reread(const char *text, Value l) {
    int infinite = infinity_text(text, text + strlen(text));
    if (infinite) return infinite == l.infinite;
    if (l.infinite) return 0;
    Node *tree = parse_expression(text);
    Rat value;
    int side;
    if (syntax_error || !limit_letters(tree, 0) || !value_constant(limit_eval(tree), &value) || failure) {
        syntax_error = NULL;
        failure = NULL;
        return 0;
    }
    return constant_sign(rat_add(value, l.value, 1), &side) == 0;
}

/* Copia il pezzo span della dimostrazione in text, lungo al più size. */
static void span_copy(Span span, char *text, size_t size) {
    snprintf(text, size, "%.*s", (int)(span.to - span.from), proof_text + span.from);
}

/* Scrive la funzione v, una serie con il suo eventuale fattore e^{G}
 * (29k), al più shown termini della serie; ritorna 0, senza scrivere
 * nulla, come put_series(). L'esponente G è esatto e si scrive per intero. */
static int put_value_series(Value v, int shown) {
    size_t start = proof_length;
    if (!value_grows(v)) return put_series(v.series, shown);
    proof_add("e^{");
    int ok = put_series(v.growth, MAX_SERIES_TERMS);
    proof_add("} \\left(");
    ok = ok && put_series(v.series, shown);
    proof_add("\\right)");
    if (!ok) proof_cut(start);
    return ok;
}

/* Scrive il pezzo della dimostrazione che riguarda il lato r dell'enunciato
 * st, e ritorna 1 se il valore scritto, riletto, è quello calcolato. */
static int put_side_proof(const LimitStatement *st, const SideResult *r) {
    static const char *const names[] = {"From the left", "At $+\\infty$", "From the right"};
    const char *name = lim_infinity ? (lim_infinity > 0 ? "At $+\\infty$" : "At $-\\infty$") : names[r->side + 1];
    proof_add("\\item \\emph{%s}, with $x = ", name);
    if (r->moved) proof_add("%se^{%s\\frac{1}{t}}", (lim_infinity ? lim_infinity : r->side) < 0 ? "-" : "", lim_infinity ? "" : "-");
    else if (lim_infinity) proof_add(lim_infinity > 0 ? "\\frac{1}{t}" : "-\\frac{1}{t}");
    else if (st->point->kind == N_NUM && st->point->value == 0) proof_add(r->side > 0 ? "t" : "-t");
    else { put_node(st->point, 1); proof_add(r->side > 0 ? " + t" : " - t"); }
    proof_add("$ and $t \\to 0^{+}$%s: ", r->moved ? " (an increasing change of variable, which keeps the limit: the substitution with "
                                                     "$x$ a power of $t$ does not reach a limit here)" : "");
    if (r->limit.kind == V_UNDEFINED) {
        proof_add("the function has no value for any small $t$ (%s).\n", r->limit.why);
        return 1;
    }
    if (r->quotient && r->parts[0].kind == V_SERIES && r->parts[1].kind == V_SERIES) {
        size_t start = proof_length;
        proof_add("the numerator is $");
        int ok = put_value_series(r->parts[0], 3);
        proof_add("$ and the denominator is $");
        ok = ok && put_value_series(r->parts[1], 3);
        proof_add("$, so the function is $");
        ok = ok && put_value_series(r->value, 2);
        proof_add("$");
        if (!ok) { proof_cut(start); proof_add("the expansions of numerator and denominator have coefficients that are not written here"); }
    } else if (r->value.kind == V_SERIES) {
        size_t start = proof_length;
        proof_add("the function is $");
        if (put_value_series(r->value, 3)) proof_add("$");
        else { proof_cut(start); proof_add("the expansion of the function has coefficients that are not written here"); }
    } else {
        proof_add("the function has no expansion in powers of $t$, and the rules of the algebra of limits give its limit");
    }
    Span span;
    proof_add("; so the limit is $");
    if (!put_limit(r->limit, &span)) { proof_cut(proof_length - 1); proof_add("a number that is not written here.\n"); return 1; }
    proof_add("$.\n");
    char text[MAX_FORMULA];
    span_copy(span, text, sizeof text);
    return limit_reread(text, r->limit);
}

/* Scrive la riga del controllo con i numeri (29i) per il lato r. */
static void put_check(const SideResult *r) {
    const char *where = lim_infinity ? "" : r->side > 0 ? " on the right" : " on the left";
    if (r->limit.kind == V_UNDEFINED)
        proof_add("The function has no value%s at the points $t = 2^{-k}$ closest to $0$. ", where);
    else if (r->limit.kind == V_LIMIT && r->moved)
        proof_add("%s the values%s at $x = %s2^{%sk}$ for $k = %d, %d, \\dots, %d$, computed with interval arithmetic, agree with the result. ",
                  r->side < 0 ? "And" : "Directly from the function,", where, (lim_infinity ? lim_infinity : r->side) < 0 ? "-" : "",
                  lim_infinity ? "" : "-", r->first, r->first + 4, r->last);
    else if (r->limit.kind == V_LIMIT)
        proof_add("%s the values%s at $t = 2^{-k}$ for $k = %d, \\dots, %d$, computed with interval arithmetic, agree with the result. ",
                  r->side < 0 ? "And" : "Directly from the function,", where, r->first, r->last);
}

/* Ritorna 1 se i due limiti a e b (V_LIMIT) sono uguali, 0 se sono
 * certamente diversi, -1 se non si sa. */
static int limits_equal(Value a, Value b) {
    int side;
    if (a.infinite || b.infinite) return a.infinite == b.infinite;
    int known = constant_sign(rat_add(a.value, b.value, 1), &side);
    return known < 0 ? -1 : known == 0;
}

/* Il principio di ogni conto su un limite scritto in formula: ripartenza da
 * zero (l'arena, la tabella degli atomi; il testo della dimostrazione no,
 * perché limit_leading() non scrive e non deve cancellare), la lettura in
 * *st, le lettere ammesse, il punto in lim_point e il valore
 * dell'enunciato, se c'è, in *claimed. Ritorna NULL se riesce, altrimenti
 * il perché. */
static const char *limit_start(const char *formula, LimitStatement *st, Rat *claimed) {
    arena_used = arena_keep;
    atom_count = base_poly_count = atan_count = 0;
    failure = NULL;
    env_count = 0;
    conditions_on = 0;
    lim_exponential = lim_moved = lim_logs = 0;
    lim_point = *claimed = rat_int(0);
    if (!parse_limit_statement(formula, st)) return syntax_error;
    if (st->variable == 'e' || !limit_letters(st->function, st->variable) || !limit_letters(st->point, 0) || !limit_letters(st->value, 0))
        return "in un limite le lettere ammesse sono la variabile, e (il numero di Nepero) e \\pi";
    lim_x = st->variable;
    lim_infinity = st->infinity;
    lim_ell = atom_var(VAR_LOG_SCALE);
    lim_goal = series_goals[0];

    /* Il punto e il valore dell'enunciato: due costanti. */
    if ((st->point && !value_constant(limit_eval(st->point), &lim_point)) || (st->value && !value_constant(limit_eval(st->value), claimed)) || failure) {
        failure = NULL;
        return "il punto, o il valore dell'enunciato, non è un numero che il programma sa calcolare";
    }
    return NULL;
}

/* 29n. IL CERTIFICATO
 *
 * Il conto di ogni lato diventa un certificato per checker.c (il suo
 * capitolo 14), che rifà gli sviluppi da sé, con la sua aritmetica: la
 * funzione, il punto, ciò che si afferma con la sua verità, e per ogni lato
 * la sostituzione (29a, o 29l se il conto è salito di un piano) con la
 * precisione lim_goal a cui il conto è riuscito. Del conto del motore il
 * verificatore non riceve nient'altro: ricalcola il termine principale, e da
 * quello il limite.
 *
 * Che cosa si afferma: per DIMOSTRATO l'enunciato, vero; per FALSO
 * l'enunciato, falso; per RISOLTO la risposta riletta dal testo scritto
 * (29j), vera. Per una successione il certificato parla della funzione con
 * n reale: se questa ha limite la successione ha lo stesso (teorema ponte).
 * Un "non esiste" a +\infty non è mai vero per il verificatore, perché lì
 * c'è un lato solo: e nemmeno per il motore, che lo dichiara falso.
 *
 * Le risposte, come per la tabella dei segni (18p-15). Accettato: il
 * verdetto porta il certificato. Respinto: il motore e il verificatore non
 * sono d'accordo, quindi nel dubbio non è dimostrato, e il passo conta tra
 * quelli che non hanno superato il controllo. Non controllabile, o una
 * funzione che la notazione non sa dire (l'arcocotangente): il verdetto resta
 * e dice perché il certificato manca.
 *
 * La funzione si scrive con limit_cert_node(), non con cert_node() del
 * capitolo 13: qui la lettera e è il numero di Nepero, non un parametro, e
 * le funzioni elementari hanno le loro parole. */

/* Scrive l'albero n nella notazione dei limiti di checker.c (i suoi capitoli
 * 6 e 14), con x la variabile: (exp 1) per e, (exp u) per e^{u}, (pi), le
 * funzioni con le loro parole, \log_{b} a come (/ (ln a) (ln b)), come lo
 * calcola limit_call(). Ciò che la notazione non ha rende certificate_broken
 * uguale a 1.
 *
 * Warning: se limit_call() impara una funzione nuova, aggiungila qui e nel
 * capitolo 14 di checker.c. */
static void limit_cert_node(const Node *n, int x) {
    static const char *const binary[] = {[N_ADD] = "+", [N_SUB] = "-", [N_MUL] = "*", [N_DIV] = "/", [N_POW] = "^"};
    static const struct { Function fn; const char *word; } calls[] = {
        {FN_SIN, "sin"}, {FN_COS, "cos"}, {FN_TAN, "tan"}, {FN_COT, "cot"}, {FN_ARCTAN, "atan"},
        {FN_ARCSIN, "arcsin"}, {FN_ARCCOS, "arccos"}, {FN_LN, "ln"}, {FN_ABS, "abs"},
    };
    switch (n->kind) {
    case N_NUM:
        cert_add("%lld", n->value);
        return;
    case N_VAR:
        if (n->name == x) cert_letter(x);
        else if (n->name == 'e') cert_add("(exp 1)");
        else if (n->name == VAR_PI) cert_add("(pi)");
        else certificate_broken = 1;
        return;
    case N_NEG:
        cert_add("(neg ");
        limit_cert_node(n->a, x);
        cert_add(")");
        return;
    case N_ADD: case N_SUB: case N_MUL: case N_DIV: case N_POW:
        if (n->kind == N_POW && n->a->kind == N_VAR && n->a->name == 'e') {
            cert_add("(exp ");
            limit_cert_node(n->b, x);
            cert_add(")");
            return;
        }
        cert_add("(%s ", binary[n->kind]);
        limit_cert_node(n->a, x);
        cert_add(" ");
        limit_cert_node(n->b, x);
        cert_add(")");
        return;
    case N_CALL:
        if (n->op == FN_LOG && n->b) {
            cert_add("(/ (ln ");
            limit_cert_node(n->a, x);
            cert_add(") (ln ");
            limit_cert_node(n->b, x);
            cert_add("))");
            return;
        }
        if (n->op == FN_ROOT) {
            /* (root m a): l'indice prima, come nel capitolo 6 di checker.c. */
            cert_add("(root ");
            limit_cert_node(n->b, x);
            cert_add(" ");
            limit_cert_node(n->a, x);
            cert_add(")");
            return;
        }
        for (size_t i = 0; i < sizeof calls / sizeof *calls; i++)
            if (calls[i].fn == (Function)n->op) {
                cert_add("(%s ", calls[i].word);
                limit_cert_node(n->a, x);
                cert_add(")");
                return;
            }
        certificate_broken = 1;
        return;
    default:
        certificate_broken = 1;
    }
}

/* Scrive in certificate_text il certificato del limite st, calcolato nei
 * lati sides[0..count-1], che afferma claim (con il valore value se è
 * LIMIT_VALUE) con la verità truth. */
static void limit_certificate(const LimitStatement *st, const SideResult *sides, int count, LimitClaim claim, const Node *value, int truth) {
    static const char *const claims[] = {[LIMIT_ASKED] = "", [LIMIT_VALUE] = "value", [LIMIT_PLUS] = "plus", [LIMIT_MINUS] = "minus",
                                         [LIMIT_UNSIGNED] = "unsigned", [LIMIT_NONE] = "none"};
    certificate_length = 0;
    certificate_broken = claim == LIMIT_ASKED;
    cert_add("certificate limit\nvariable ");
    cert_letter(st->variable);
    cert_add("\npoint ");
    if (st->infinity) {
        cert_add(st->infinity > 0 ? "+infinity" : "-infinity");
    } else {
        limit_cert_node(st->point, st->variable);
        if (st->side) cert_add(st->side > 0 ? " right" : " left");
    }
    cert_add("\nfunction ");
    limit_cert_node(st->function, st->variable);
    cert_add("\nclaim %s ", claims[claim]);
    if (claim == LIMIT_VALUE) {
        limit_cert_node(value, st->variable);
        cert_add(" ");
    }
    cert_add(truth ? "true" : "false");

    /* I lati, nell'ordine di prove_limit(): da destra, poi da sinistra. */
    for (int i = 0; i < count; i++) {
        const SideResult *r = &sides[i];
        int toward = st->infinity ? st->infinity : r->side;
        const char *substitution = st->infinity ? (r->moved ? (toward > 0 ? "e^(1/t)" : "-e^(1/t)") : (toward > 0 ? "1/t" : "-1/t"))
                                                : (r->moved ? (toward > 0 ? "e^(-1/t)" : "-e^(-1/t)") : (toward > 0 ? "a+t" : "a-t"));
        cert_add("\nside %s %s %d", st->infinity ? "infinity" : toward > 0 ? "right" : "left", substitution, r->goal);
    }
    cert_add("\nend\n");
}

/* 29n. Fa controllare a checker.c il verdetto *verdict sul limite st, con i
 * lati sides[0..count-1], e lo aggiorna con la risposta (vedi "Le risposte"
 * in testa a 29n). claim, value e truth sono ciò che il certificato
 * afferma. */
static void limit_certify(const LimitStatement *st, const SideResult *sides, int count, LimitClaim claim, const Node *value, int truth, Verdict *verdict) {
    static char problem[512];
    const char *why = "la funzione usa qualcosa che la notazione dei certificati non ha", *text = certificate_text;
    limit_certificate(st, sides, count, claim, value, truth);
    if (!certificate_broken) {
        CkAnswer answer = ck_check(&text, &why);
        if (answer == CK_ACCEPTED) {
            verdict->certificate = certificate_text;
            verdict->reason = NULL;
            return;
        }
        if (answer == CK_REJECTED) {
            unjustified_steps++;
            snprintf(problem, sizeof problem, "il verificatore indipendente ha respinto il certificato del limite: %s", why);
            *verdict = (Verdict){NOT_PROVED, 0, 0, 0, problem, NULL, NULL, NULL, NULL, NULL};
            return;
        }
        snprintf(problem, sizeof problem, "il verificatore non sa controllarlo, %s", why);
    } else {
        snprintf(problem, sizeof problem, "%s", why);
    }

    /* Il motivo sta nella riga del verdetto, e per una richiesta prima del
     * ": " dopo il quale viene la risposta (vedi sign_certify()). */
    for (char *colon = problem; (colon = strchr(colon, ':')) != NULL;) *colon = ',';
    verdict->reason = problem;
}

/* 29j. Prova a dimostrare, smentire o risolvere l'enunciato sul limite
 * scritto in formula (vedi la testa del capitolo). Svuota l'arena e la
 * tabella degli atomi: i risultati di chiamate precedenti non sono più
 * validi. */
static Verdict prove_limit(const char *formula) {
    static char answer[MAX_FORMULA];
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    LimitStatement st;
    SideResult sides[2];
    Rat claimed;
    proof_reset();
    if ((verdict.reason = limit_start(formula, &st, &claimed))) return verdict;

    /* I lati, e per ognuno il controllo con i numeri. */
    int count = st.infinity || st.side ? 1 : 2;
    for (int i = 0; i < count; i++) {
        limit_side(st.function, count == 1 ? (st.infinity ? 0 : st.side) : 1 - 2 * i, &sides[i]);
        limit_check(st.function, &sides[i]);
    }

    /* Ogni lato deve essere calcolato e confermato dai numeri. */
    verdict.outcome = NOT_PROVED;
    for (int i = 0; i < count; i++) {
        if (sides[i].limit.kind == V_UNKNOWN) { verdict.reason = sides[i].limit.why; return verdict; }
        if (sides[i].check == CHECK_CONTRADICTED) {
            unjustified_steps++;
            verdict.reason = "il controllo con i numeri contraddice il limite calcolato";
            return verdict;
        }
        if (sides[i].check != CHECK_CONFIRMED) { verdict.reason = "il controllo con i numeri non conferma il limite calcolato"; return verdict; }
    }

    /* Il limite: da un lato solo, o dai due. Un lato senza valori non conta
     * (29a); se nessuno ne ha, il punto non è di accumulazione. */
    int undefined = (sides[0].limit.kind == V_UNDEFINED) + (count == 2 && sides[1].limit.kind == V_UNDEFINED);
    if (undefined == count) {
        verdict.reason = "vicino al punto la funzione non ha valori: il limite non ha senso";
        return verdict;
    }
    int exists = 1;
    Value l = sides[0].limit.kind == V_LIMIT ? sides[0].limit : sides[1].limit;
    if (count == 2 && !undefined) {
        int same = limits_equal(sides[0].limit, sides[1].limit);
        if (same < 0) { verdict.reason = "non si sa se i limiti da destra e da sinistra sono uguali"; return verdict; }
        exists = same;
    }

    /* La dimostrazione: un lato alla volta, poi il controllo, poi la
     * conclusione. Ogni valore scritto viene riletto. */
    int sound = 1, logs = 0, grows = 0;
    for (int i = 0; i < count; i++) {
        const Value *shown[3] = {&sides[i].value, &sides[i].parts[0], &sides[i].parts[1]};
        for (int j = 0; j < 3; j++) {
            if (shown[j]->kind != V_SERIES) continue;
            for (int k = 0; k < shown[j]->series.count; k++) logs |= rat_has_ell(shown[j]->series.coef[k]);
            for (int k = 0; k < shown[j]->growth.count; k++) logs |= rat_has_ell(shown[j]->growth.coef[k]);
            grows |= value_grows(*shown[j]);
        }
    }
    proof_add("\\textbf{Proof.} ");
    if (lim_exponential) proof_add("A power $f^{g}$ with the variable in the exponent means $e^{g \\ln f}$, defined where $f > 0$. ");
    if (grows)
        proof_add("A factor $e^{G}$, with $G$ a finite sum of negative powers of $t$, is larger or smaller than every power of $t$ and of "
                  "$\\ln\\frac{1}{t}$, according to the sign of the leading term of $G$ (the scale of growth: exponentials beat powers, "
                  "which beat logarithms); in a sum the smaller factor becomes a remainder smaller than every power of $t$. ");
    proof_add("Each one-sided limit is computed with expansions in powers of a variable $t \\to 0^{+}$, with exact coefficients "
              "(Taylor's theorem with Peano's remainder)%s; the limit is given by the leading term.\n\\begin{itemize}\n",
              logs ? ", where $L = \\ln\\frac{1}{t}$" : "");
    for (int i = 0; i < count; i++) sound = put_side_proof(&st, &sides[i]) && sound;
    proof_add("\\item \\emph{Check with numbers.} ");
    for (int i = 0; i < count; i++) put_check(&sides[i]);
    proof_add("\n\\end{itemize}\n");
    if (count == 2 && undefined) proof_add("Only one side of the point is in the domain, so the limit is the one from that side. ");
    else if (count == 2 && exists) proof_add("The two one-sided limits are equal, so they are the limit. ");
    else if (count == 2) proof_add("The two one-sided limits are different, so the limit does not exist. ");

    /* Il verdetto, confrontando il limite con ciò che l'enunciato dice. */
    int side = 0, holds = 0;
    switch (st.claim) {
    case LIMIT_ASKED: holds = 1; break;
    case LIMIT_NONE: holds = !exists; break;
    case LIMIT_PLUS: holds = exists && l.infinite > 0; break;
    case LIMIT_MINUS: holds = exists && l.infinite < 0; break;
    case LIMIT_UNSIGNED: holds = exists ? l.infinite != 0 : sides[0].limit.infinite && sides[1].limit.infinite; break;
    case LIMIT_VALUE:
        if (!exists || l.infinite) break;
        int known = constant_sign(rat_add(l.value, claimed, 1), &side);
        if (known < 0) { verdict.reason = "non si sa se il limite calcolato è il valore dell'enunciato"; return verdict; }
        holds = known == 0;
        break;
    }
    /* Ciò che il certificato afferma (29n): l'enunciato, oppure la risposta
     * riletta. */
    LimitStatement reread = st;
    int truth = holds;
    if (st.claim == LIMIT_ASKED) {
        /* La risposta: l'enunciato con il valore, scritto e riletto. Deve
         * rileggersi come un enunciato sul limite, e il valore come quello
         * calcolato. */
        const char *from = st.from, *to = st.to;
        char value[MAX_FORMULA];
        while (to > from && isspace((unsigned char)to[-1])) to--;
        if (!exists) {
            snprintf(answer, sizeof answer, "\\nexists %.*s", (int)(to - from), from);
            verdict.note = "i limiti da destra e da sinistra sono diversi";
        } else {
            Span span;
            proof_add("The limit is $");
            if (!put_limit(l, &span)) { verdict.reason = "il limite è un numero che il programma non sa scrivere"; return verdict; }
            proof_add("$. ");
            span_copy(span, value, sizeof value);
            snprintf(answer, sizeof answer, "%.*s = %s", (int)(to - from), from, value);
        }
        int read = parse_limit_statement(answer, &reread);
        syntax_error = NULL;
        sound = sound && read && (exists ? reread.claim != LIMIT_NONE && reread.claim != LIMIT_ASKED && limit_reread(value, l) : reread.claim == LIMIT_NONE);
        verdict.outcome = SOLVED;
        verdict.method = "con le serie troncate";
        verdict.detail = answer;
    } else if (holds) {
        proof_add("This is what the statement says.");
        verdict.outcome = PROVED;
        verdict.method = "con le serie troncate";
    } else {
        proof_add("The statement says otherwise, so it is false.");
        verdict.outcome = REFUTED;
        verdict.note = exists ? "il limite calcolato è un altro" : "il limite non esiste: i limiti da destra e da sinistra sono diversi";
    }
    proof_add(" $\\Box$");
    if (!sound) {
        unjustified_steps++;
        verdict.outcome = NOT_PROVED;
        verdict.reason = "un valore scritto nella dimostrazione, riletto dal testo, non è quello calcolato";
        return verdict;
    }
    verdict.proof = proof_text;
    if (st.claim == LIMIT_ASKED) truth = 1;
    limit_certify(&st, sides, count, reread.claim, reread.value, truth, &verdict);
    return verdict;
}

/* 29m. IL TERMINE PRINCIPALE, PER CHI LO CHIEDE
 *
 * Il confronto degli integrali impropri (30l) vuole sapere come una funzione
 * va a zero, o all'infinito, vicino a un estremo: il suo termine principale
 * c t^{e} L^{d} e^{G}, cioè f = c t^{e} L^{d} e^{G} (1 + o(1)). È lo stesso
 * conto di un limite (29b-29h, 29k), con lo stesso controllo con i numeri
 * (29i), che deve confermarlo; del coefficiente c servono solo il segno e
 * che non sia zero, che il conto decide in modo esatto (29c). */

/* Il termine principale di una funzione vicino a un punto, da un lato, nelle
 * lettere t e L di 29a; oppure, se della serie non si conosce nessun
 * coefficiente, solo il suo resto: f = O(t^{e}), cioè |f| <= C t^{e} per t
 * piccolo (29b), come x^{-2} \sin x all'infinito. */
typedef struct {
    int found;     /* 1 se il termine principale, o il resto, è noto */
    int bound;     /* 1 se si conosce solo il resto: f = O(t^{e}), e sign non conta */
    int sign;      /* il segno del coefficiente c: +1 o -1 */
    Frac e, d;     /* gli esponenti di t e di L */
    int growth;    /* 0 senza fattore e^{G}; +1 o -1 se G tende a +\infty o a -\infty */
} LeadingTerm;

/* Il termine principale della funzione della richiesta formula,
 * "\lim_{x \to a^{\pm}} f" o "\lim_{x \to \pm\infty} f", se il controllo con
 * i numeri conferma il conto. Non lo dà se il conto è riuscito solo salendo
 * di un piano (29l): lì t non è più |x - a| o 1/|x|. Svuota l'arena e la
 * tabella degli atomi come prove_limit(). */
static LeadingTerm limit_leading(const char *formula) {
    LeadingTerm out = {0, 0, 0, {0, 1}, {0, 1}, 0};
    LimitStatement st;
    SideResult r;
    Rat claimed;
    Lead lead;
    if (limit_start(formula, &st, &claimed) || st.claim != LIMIT_ASKED || (!st.infinity && !st.side)) return out;
    limit_side(st.function, st.infinity ? 0 : st.side, &r);
    limit_check(st.function, &r);
    if (r.check == CHECK_CONTRADICTED) unjustified_steps++;
    Series s = r.value.series;
    int dir = 0, found = r.value.kind == V_SERIES ? series_settle(&s, &lead) : 0;
    failure = NULL;
    if (r.check != CHECK_CONFIRMED || r.limit.kind != V_LIMIT || r.moved || r.value.kind != V_SERIES || found == 0) return out;
    if (value_grows(r.value) && growth_direction(r.value.growth, &dir) != 1) return out;

    /* Nessun coefficiente noto: una funzione piatta, o zero, è più piccola
     * di ogni potenza, come con G -> -\infty; altrimenti resta il resto. */
    if (found < 0) {
        if (dir > 0) return out;
        if (dir < 0 || s.exact || s.end >= SERIES_FLAT) return (LeadingTerm){1, 0, 0, {0, 1}, {0, 1}, -1};
        return (LeadingTerm){1, 1, 0, frac_make(s.end, s.den), {0, 1}, 0};
    }
    return (LeadingTerm){1, 0, lead.side, frac_make(s.low, s.den), lead.degree, dir};
}

/* =============================================================================
 * 30. INTEGRALI: PRIMITIVE, INTEGRALI DEFINITI E IMPROPRI
 * ============================================================================
 *
 * A che cosa serve. Le domande dei libri sugli integrali, nella notazione
 * del paragrafo 9j di parser.c:
 *
 *     \int f \, dx = F + c        è giusta questa primitiva?
 *     \int f \, dx                trovane una (la risposta è RISOLTO: F + c);
 *     \int_{a}^{b} f \, dx = V    è giusto questo valore? Senza "= V": quanto vale?
 *     \int_{1}^{+\infty} f \, dx = +\infty, \in \mathbb{R}, \notin \mathbb{R}
 *                                 un integrale improprio diverge? converge?
 *
 * VERIFICARE UNA PRIMITIVA (30a, 30b)
 *
 * Una primitiva di f su un intervallo aperto I è una funzione F derivabile in
 * I con F' = f. Due primitive sullo stesso intervallo differiscono per una
 * costante: se F' = G' in I la derivata di G - F è zero, e per il teorema di
 * Lagrange G - F è costante su I. Quindi "\int f \, dx = F + c" dice che su
 * ogni intervallo aperto in cui F e f sono definite le primitive di f sono
 * le F + c, ed è vero se e solo se lì F' = f. Su intervalli diversi la
 * costante può cambiare (1/x ha ln|x| + c_1 per x < 0 e ln|x| + c_2 per
 * x > 0): i libri le chiamano tutte c, e qui non si confrontano le F scritte
 * ma solo le loro derivate.
 *
 * È il controllo del capitolo 27 ribaltato. derive() calcola F' con le
 * regole di derivazione (27c-27g) e il test di annullamento (capitolo 12)
 * decide se F' - f è zero, con i conti esatti, dove i due membri sono
 * definiti: lì può usare i fatti del dominio (12d), come x >= 0 quando
 * compare \sqrt{x}; poi, per una strada che non
 * usa quelle regole, la serie di Taylor di F nei punti di prova, calcolata
 * con gli intervalli (27h), dà F'(x0) con l'errore garantito e la si
 * confronta con f(x0). DIMOSTRATO vuole lo zero esatto e almeno un punto in
 * cui i numeri confermano; FALSO vuole un punto x0 in cui F e f sono
 * definite e F'(x0) è di sicuro diverso da f(x0), sia per la serie di
 * Taylor sia per le regole, che lì devono concordare tra loro. Una regola
 * smentita dalla serie è un errore del programma (unjustified_steps).
 *
 * TROVARE UNA PRIMITIVA (30c-30h)
 *
 * La ricerca può essere euristica, il verdetto no: ogni primitiva trovata
 * viene scritta in LaTeX, riletta dal lettore del programma come se l'avesse
 * scritta l'utente, e verificata come sopra. I metodi sono quelli generali
 * dei libri, ognuno con il suo teorema scritto dove è il codice:
 *
 *   30c. la linearità, e l'ordine in cui si provano i metodi;
 *   30d. le funzioni razionali, per intero: divisione, Hermite-Ostrogradsky
 *        per i fattori ripetuti, fattori del denominatore su Q (radici
 *        razionali e fattori di secondo grado), fratti semplici con un
 *        sistema lineare esatto, logaritmi e arcotangenti; e x^m = s quando
 *        la funzione è x^{m-1} R(x^m);
 *   30e. i polinomi per esponenziali, P(x) e^{(a + i b) x}: seni e coseni
 *        sono esponenziali complessi (capitolo 11), quindi le potenze di
 *        seni e coseni, i loro prodotti (Werner), x^n sin x, e^x sin x (il
 *        caso "ciclico" dell'integrazione per parti) sono un caso solo;
 *   30f. per parti, con la regola di scelta: si deriva il logaritmo o
 *        l'arcotangente, si integra il resto;
 *   30g. per sostituzione: t = h(x) quando la funzione è g(h(x)) h'(x), a
 *        meno di una costante; e le sostituzioni che rendono la funzione
 *        razionale, t = (a x + b)^{1/n} e t = b^{g x};
 *   30h. le funzioni razionali di seno e coseno, con t = tan(x/2), o
 *        t = tan x quando la funzione non cambia sommando pi a x.
 *
 * GLI INTEGRALI DEFINITI (30i, 30j)
 *
 * Teorema fondamentale del calcolo integrale: se f è continua su [a, b] e F
 * è derivabile in un intervallo aperto che contiene [a, b] con F' = f, allora
 * l'integrale di f da a a b vale F(b) - F(a). Le ipotesi si controllano con
 * gli intervalli del capitolo 24, su una suddivisione di [a, b] (vedi 30i);
 * F(b) - F(a) si calcola con i conti esatti, con i valori esatti di seni,
 * coseni e arcotangenti negli angoli multipli di pi/12 (30i-1), e si
 * confronta con il valore scritto con il test di annullamento. Un valore
 * assoluto si toglie dividendo [a, b] nei punti in cui il suo argomento si
 * annulla (30i-2). Il controllo indipendente è una somma di Riemann con gli
 * intervalli, che chiude il valore vero tra due numeri senza usare F: il
 * valore esatto deve starci dentro. La stessa somma basta per dire FALSO,
 * quando il valore scritto ne sta di sicuro fuori.
 *
 * GLI INTEGRALI IMPROPRI (30k, 30l)
 *
 * Un estremo infinito, o una funzione non limitata vicino a un estremo o a
 * un punto interno: l'integrale è un limite di integrali su intervalli
 * compatti. Con una primitiva F (30k) è il limite di F agli estremi, che
 * calcola il capitolo 29 con la scala delle crescite (29k), dopo che la
 * tabella dei segni ha mostrato le funzioni definite sull'intervallo aperto
 * e diviso l'intervallo nei punti in cui non lo sono. Senza primitiva (30l)
 * la convergenza si decide per confronto con t^{e} (\ln\frac{1}{t})^{d}, dal
 * termine principale della funzione (29m). Anche un integrale definito che
 * 30i non vede continuo su [a, b], come \sqrt[5]{x} su [-1, 0], passa da qui.
 *
 * IL CERTIFICATO (30cert)
 *
 * Una primitiva verificata, o trovata, e un integrale definito portano un
 * certificato per checker.c (capitolo 13), scritto con le funzioni di 27m:
 * il verificatore deriva la primitiva da sé e controlla che la sua derivata
 * sia la funzione integranda; per un integrale anche che la funzione e la
 * primitiva siano definite su tutto [a, b], con Sturm, e che il valore sia
 * F(b) - F(a). Un rifiuto rende il verdetto NON DIMOSTRATO. Gli integrali
 * impropri (30k, 30l) restano senza certificato: il verificatore non sa
 * calcolare limiti di primitive.
 *
 * COSA NON C'È ANCORA
 *
 *   - Le aree, e negli integrali impropri le oscillazioni
 *     (\int_0^{+\infty} \cos x \, dx non converge, ma il motore non lo sa
 *     dire), i domini che la tabella dei segni non sa decidere
 *     (\frac{1}{e^{\sqrt{x}} - 1} su (0, 1)), le funzioni la cui primitiva non
 *     si trova e la cui convergenza vuole stime più fini del termine
 *     principale.
 *   - Le funzioni che derive() non tratta ancora: il valore assoluto fuori
 *     da un logaritmo (in una primitiva; in un integrale definito lo toglie
 *     30i-2), arcoseno e arcocoseno, seno e coseno iperbolici. Le primitive
 *     che le contengono restano non decise; il lettore e le regole di
 *     derivazione sono del capitolo 27.
 *   - Le radici di polinomi di secondo grado, \sqrt{a x^2 + b x + c}: le
 *     sostituzioni di Eulero e quelle iperboliche. Si verificano le primitive
 *     scritte, ma non si cercano; né si cerca quella di x^3 \sqrt{2 - x^2},
 *     che chiederebbe t = \sqrt{2 - x^2} con x^2 = 2 - t^2.
 *   - ln(e) = 1 nei conti esatti: un estremo come e^{3/2} non si calcola.
 *   - Lettere oltre alla variabile, a e pi greco (i parametri).
 *   - Il certificato (30cert, con le funzioni di 27m) di un integrale diviso
 *     in parti da un valore assoluto (30i-2), e di uno con una condizione di
 *     esistenza che non è un polinomio in x (una tangente, un denominatore
 *     con e^x), o con un estremo diverso da c_0 + c_1 pi + c_2 e: checker.c
 *     li dice non controllabili, e il verdetto dice perché il certificato
 *     manca.
 */

/* 30a. Ritorna una copia di tree in cui ogni logaritmo di un valore assoluto,
 * ln|u| o log_b|u|, è il logaritmo di u: è l'albero da dare a derive(), che
 * il valore assoluto non lo deriva.
 *
 * Perché si può. Dove u > 0 si ha |u| = u, e le due funzioni coincidono.
 * Dove u < 0 si ha ln|u| = ln(-u), con derivata (-u')/(-u) = u'/u: la stessa
 * formula che le regole danno per ln u. Quindi ln|u| e ln u hanno la stessa
 * derivata, u'/u, in ogni punto in cui ln|u| è derivabile: differiscono in
 * dove sono definite, non in come si derivano. Dove F è definita lo decidono
 * qui i conti con i numeri sull'albero com'è scritto (30b), mai questa
 * copia.
 *
 * Lo stesso vale per un valore assoluto che è un fattore dell'argomento,
 * come in \ln\frac{\sqrt{x^2 + 1}}{|x|}: la derivata di ln|g| è g'/g, e per
 * g = A |B|^k / C la derivata logaritmica g'/g = A'/A + k B'/B - C'/C non
 * cambia togliendo il valore assoluto, perché |B|'/|B| = B'/B dove B non è
 * zero. Per questo strip_factor_abs() toglie i valori assoluti che
 * dall'argomento si raggiungono scendendo per prodotti, quozienti, segni e
 * potenze, e solo quelli. */
static Node *strip_log_abs(const Node *tree);
static Node *strip_factor_abs(const Node *tree) {
    if (tree->kind == N_CALL && tree->op == FN_ABS) return strip_factor_abs(tree->a);
    if (tree->kind == N_MUL || tree->kind == N_DIV) return node_new(tree->kind, strip_factor_abs(tree->a), strip_factor_abs(tree->b));
    if (tree->kind == N_NEG) return node_new(N_NEG, strip_factor_abs(tree->a), NULL);
    if (tree->kind == N_POW && tree->b->kind == N_NUM) return node_new(N_POW, strip_factor_abs(tree->a), tree->b);
    return strip_log_abs(tree);
}

static Node *strip_log_abs(const Node *tree) {
    if (!tree) return NULL;
    if (tree->kind == N_CALL && (tree->op == FN_LN || tree->op == FN_LOG)) return node_call((Function)tree->op, strip_factor_abs(tree->a), tree->b);
    Node *copy = node_new(tree->kind, strip_log_abs(tree->a), strip_log_abs(tree->b));
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    copy->c = strip_log_abs(tree->c);
    return copy;
}

/* I punti in cui le primitive vengono controllate con i numeri (30b). Sono
 * sparsi perché le funzioni degli esercizi hanno domini diversi: x > 0,
 * x > ln 2, x >= 4, -2 < x < 2, x diverso da 0. */
static const Frac primitive_points[] = {{3, 10}, {7, 5}, {-9, 10}, {5, 2}, {-13, 5}, {9, 2}, {1, 7}, {-1, 3}, {11, 3}, {6, 1}, {-6, 1}, {17, 10}};
enum { PRIMITIVE_POINTS = sizeof primitive_points / sizeof *primitive_points };

/* L'esito della verifica di una primitiva F di f (30a e 30b). */
typedef struct {
    Outcome outcome;     /* PROVED, REFUTED, NOT_PROVED oppure UNSUPPORTED */
    const char *reason;  /* NOT_PROVED, UNSUPPORTED: perché, in italiano */
    Frac point;          /* REFUTED: il punto x0 in cui F'(x0) è di sicuro diverso
                            da f(x0); PROVED: il primo punto in cui i numeri confermano */
    int outside;         /* 1 se in un punto di prova f è definita e F no */
    Frac where;          /* quel punto, se outside */
    Node *derivative;    /* F' secondo le regole di derivazione; NULL se non si calcola */
} PrimitiveCheck;

/* 30a, 30b. Verifica che F sia una primitiva di f nella variabile x: vedi la
 * testa del capitolo. Gli alberi non devono contenere altre lettere che x, e
 * e pi greco. Lascia `failure` a NULL. */
static PrimitiveCheck primitive_check(const Node *f, const Node *F, int x) {
    PrimitiveCheck check = {NOT_PROVED, NULL, {0, 1}, 0, {0, 1}, NULL};

    /* 30a. F' con le regole, e F' - f con i conti esatti, dove i due membri
     * sono definiti (12d): è lì che F' = f deve valere. */
    Node *derivative = derive(strip_log_abs(F), x);
    if (failure) { check.outcome = UNSUPPORTED; check.reason = failure; failure = NULL; return check; }
    check.derivative = derivative;
    Statement claim = {derivative, (Node *)f, REL_EQ};
    int vanishes = vanishes_where_defined(&claim, F, rat_int(0));
    const char *trouble = failure;
    failure = NULL;

    /* 30b. In ogni punto di prova in cui f è definita: la derivata letta
     * dalla serie di Taylor di F, quella delle regole, e f. */
    Node *primitive = sample_tree(F, x, 0, 0), *rules = sample_tree(derivative, x, 0, 0), *integrand = sample_tree(f, x, 0, 0);
    int confirmed = 0, doubt = 0;
    for (int p = 0; p < PRIMITIVE_POINTS && !failure; p++) {
        Range at = range_ratio(primitive_points[p].num, primitive_points[p].den);
        Range value = sample_value(integrand, x, at);
        if (!range_known(value)) continue;
        Jet series = jet_eval(primitive, x, at, 1);
        if (!range_known(series.c[0])) {
            if (!check.outside) { check.outside = 1; check.where = primitive_points[p]; }
            continue;
        }
        Range by_rules = sample_value(rules, x, at);
        int agreement = numbers_agree(by_rules, series.c[1]);
        if (agreement < 0) {
            unjustified_steps++;
            check.reason = "la derivata calcolata con le regole di derivazione è smentita dalla serie di Taylor della primitiva";
            return check;
        }
        if (agreement == 0) continue;

        /* Le regole e la serie concordano: in questo punto si può dire FALSO
         * se f ne è di sicuro lontana per tutti e due i conti. */
        int side, by_series_differs = range_side(range_sub(series.c[1], value), &side);
        int by_rules_differs = range_side(range_sub(by_rules, value), &side);
        if (by_series_differs && by_rules_differs) {
            if (vanishes) {
                unjustified_steps++;
                check.reason = "il test di annullamento dice F' = f, ma i numeri dicono di no";
                return check;
            }
            check.outcome = REFUTED;
            check.point = primitive_points[p];
            return check;
        }
        if (by_series_differs || by_rules_differs) doubt = 1;
        else if (numbers_agree(series.c[1], value) > 0) {
            if (!confirmed) check.point = primitive_points[p];
            confirmed = 1;
        }
    }
    failure = NULL;
    if (!vanishes) check.reason = trouble ? trouble : "la derivata della primitiva, calcolata con le regole, non si riduce alla funzione integranda";
    else if (doubt) check.reason = "in un punto di prova la derivata della primitiva e la funzione integranda non concordano abbastanza per decidere";
    else if (!confirmed) check.reason = "non riesco a confermare con i numeri la derivata della primitiva, in nessuno dei punti di prova";
    else check.outcome = PROVED;
    return check;
}

/* 30c. LA RICERCA DI UNA PRIMITIVA
 *
 * Ogni metodo dei paragrafi seguenti riceve l'albero di f nella variabile x
 * e scrive in un testo una primitiva, in LaTeX; ritorna 0 se non si applica
 * o non riesce. La ricerca li prova in un ordine fisso, dal più completo al
 * più specifico (vedi primitive_methods[] e primitive_text()):
 *
 *   30c-1. f non contiene x: F = f x;
 *   30d.   funzioni razionali, che hanno sempre una primitiva elementare e
 *          un algoritmo completo per trovarla;
 *   30e.   polinomi per esponenziali, anche questi con una formula
 *          generale;
 *   30c-2. linearità: un fattore costante, o un segno, si porta fuori;
 *   30f.   per parti, con un logaritmo o un'arcotangente;
 *   30g.   per sostituzione, e le sostituzioni che rendono la funzione
 *          razionale (una radice, un esponenziale);
 *   30h.   seni e coseni con t = tan(theta/2);
 *   30c-8. linearità: una somma si integra un termine alla volta.
 *
 * Un metodo può chiamare la ricerca su un'altra funzione (per parti la
 * derivata del logaritmo per la primitiva del resto, per sostituzione la
 * funzione nella nuova variabile): la profondità è limitata da
 * MAX_PRIMITIVE_DEPTH, così la ricerca finisce sempre.
 *
 * Perché il risultato è un testo. È ciò che si consegna, e ciò che si
 * verifica: la primitiva trovata viene riletta dal parser del capitolo 9, e
 * un errore nel modo di scriverla (un segno, una parentesi) cambia ciò che si
 * rilegge e non passa la verifica. */

/* Il metodo che ha trovato l'ultima primitiva, per il verdetto. */
static const char *primitive_method;

/* Aggiunge a text, di size byte, il razionale v in LaTeX: 3, -\frac{5}{2}. */
static void frac_latex(Frac v, char *text, size_t size) {
    if (v.den == 1) text_add(text, size, "%lld", v.num);
    else text_add(text, size, "%s\\frac{%lld}{%lld}", v.num < 0 ? "-" : "", v.num < 0 ? -v.num : v.num, v.den);
}

/* Aggiunge alla somma scritta in text il termine coef body: col segno davanti
 * se non è il primo, senza il coefficiente se vale 1 o -1. Un body vuoto è
 * il numero coef; un coefficiente nullo non scrive nulla. */
static void term_latex(Frac coef, const char *body, char *text, size_t size) {
    if (coef.num == 0) return;
    int first = text[0] == 0, negative = coef.num < 0;
    Frac magnitude = negative ? frac_neg(coef) : coef;
    text_add(text, size, first ? (negative ? "-" : "") : (negative ? " - " : " + "));
    if (!body[0]) { frac_latex(magnitude, text, size); return; }
    if (magnitude.num != 1 || magnitude.den != 1) {
        frac_latex(magnitude, text, size);
        if (isdigit((unsigned char)body[0])) text_add(text, size, " \\cdot ");
    }
    text_add(text, size, "%s", body);
}

/* Mette in text, di size byte, l'albero node scritto da put_node() (capitolo
 * 13), che lo scrive in modo che si rilegga uguale. Ritorna 0 se non ci
 * sta. Il testo della dimostrazione in corso non cambia. */
static int node_latex(const Node *node, char *text, size_t size) {
    size_t start = proof_length;
    put_node(node, 0);
    size_t length = proof_length - start;
    int fits = proof_length < PROOF_BYTES - 1 && length < size;
    if (fits) {
        memcpy(text, proof_text + start, length);
        text[length] = 0;
    }
    proof_cut(start);
    return fits;
}

/* Ritorna l'albero dell'espressione scritta in text, o NULL se non si legge.
 * Il lettore dei token resta da reimpostare. */
static Node *text_tree(const char *text) {
    Node *tree = parse_expression(text);
    if (syntax_error || failure) { syntax_error = NULL; return NULL; }
    return tree;
}

/* Ritorna una lettera che non compare in tree, per la nuova variabile di una
 * sostituzione; 0 se sono tutte prese. */
static int fresh_variable(const Node *tree) {
    static const char letters[] = "tuwvszyqrpm";
    for (const char *l = letters; *l; l++)
        if (!node_has_variable(tree, *l)) return *l;
    return 0;
}

/* Ritorna una copia di tree con quattro semplificazioni che non cambiano una
 * primitiva, utili dopo una sostituzione (la primitiva semplificata è poi
 * verificata come ogni altra):
 *
 *   - (\sqrt[n]{B})^k = \sqrt[n/g]{B}^{k/g}, con g = mcd(n, k): vale dove la
 *     radice è definita, cioè per B >= 0. \sqrt[6]{x}^{3} diventa \sqrt{x};
 *   - \arctan(\tan A) = A - k pi, con k intero costante su ogni intervallo in
 *     cui tan A è definita: le due funzioni differiscono per una costante, e
 *     come primitive sono la stessa;
 *   - e^{c \ln A} = A^c, per c un numero, dove ln A è definito: la nuova
 *     primitiva è definita in più punti, ma la verifica la confronta con f
 *     solo dove sono definite tutte e due, e f, che conteneva ln A, lo è
 *     solo dove lo è ln A;
 *   - \ln e^{A} = \ln|e^{A}| = A, per ogni A. */
static Node *tidy(const Node *tree) {
    if (!tree) return NULL;
    Node *a = tidy(tree->a), *b = tidy(tree->b);
    if (tree->kind == N_CALL && tree->op == FN_ARCTAN && a->kind == N_CALL && a->op == FN_TAN) return a->a;
    if (tree->kind == N_POW && a->kind == N_VAR && a->name == 'e') {
        /* e^{\pm \ln A} ed e^{\pm c \ln A}: per A > 0 vale A^{\pm c}. */
        const Node *exponent = b->kind == N_NEG ? b->a : b;
        Node *c = NULL, *argument = NULL;
        if (exponent->kind == N_CALL && exponent->op == FN_LN) c = node_num(1), argument = exponent->a;
        else if (exponent->kind == N_MUL && exponent->b->kind == N_CALL && exponent->b->op == FN_LN) c = exponent->a, argument = exponent->b->a;
        if (c && b->kind == N_NEG) c = node_new(N_NEG, c, NULL);
        if (c) return c->kind == N_NUM && c->value == 1 ? argument : node_new(N_POW, argument, c);
    }
    const Node *inside = tree->kind == N_CALL && tree->op == FN_LN && a->kind == N_CALL && a->op == FN_ABS ? a->a : a;
    if (tree->kind == N_CALL && tree->op == FN_LN && inside->kind == N_POW && inside->a->kind == N_VAR && inside->a->name == 'e') return inside->b;
    if (tree->kind == N_POW && a->kind == N_CALL && a->op == FN_ROOT && a->b->kind == N_NUM && b->kind == N_NUM && b->value > 0) {
        long long g = (long long)gcd128(a->b->value, b->value), n = a->b->value / g, k = b->value / g;
        Node *base = n == 1 ? a->a : node_call(FN_ROOT, a->a, node_num(n));
        return k == 1 ? base : node_new(N_POW, base, node_num(k));
    }
    Node *copy = node_new(tree->kind, a, b);
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    copy->c = tree->c;
    return copy;
}

/* Scrive in text, di size byte, la primitiva G(t) scritta in inner con t
 * sostituita da h: è il ritorno alla variabile di partenza dopo una
 * sostituzione t = h(x), con le semplificazioni di tidy(). Ritorna 0 se non
 * riesce. */
static int substitute_back(const char *inner, int t, const Node *h, char *text, size_t size) {
    Node *g = text_tree(inner);
    return g && node_latex(tidy(node_replace(g, t, (Node *)h)), text, size);
}

static int primitive_text(const Node *f, int x, int depth, char *text, size_t size);

/* 30d. LE FUNZIONI RAZIONALI
 *
 * Teorema. Ogni funzione razionale N(x)/D(x) a coefficienti reali ha una
 * primitiva elementare: un polinomio, più una funzione razionale, più una
 * combinazione di logaritmi e di arcotangenti. L'algoritmo la trova, ed è
 * completo appena si sa scomporre il denominatore (Bernoulli, Leibniz; nei
 * libri: L. Torresani, "Integrazione delle funzioni razionali", pp. 1-3).
 *
 *   30d-1. Divisione: N = Q D + R con il grado di R minore di quello di D. Q
 *          si integra termine per termine.
 *
 *   30d-2. Fattori ripetuti (Hermite-Ostrogradsky). Sia D1 = mcd(D, D') e
 *          D2 = D / D1: D2 ha gli stessi fattori di D, ognuno una volta, e
 *          D1 quelli ripetuti, ognuno una volta in meno. Allora esistono, e
 *          sono unici, P di grado minore di D1 e S di grado minore di D2 con
 *
 *              R/D = (P/D1)' + S/D2,
 *
 *          cioè, moltiplicando per D = D1 D2,
 *
 *              R = P' D2 - P H + S D1,   con H = D1' D2 / D1,
 *
 *          che è un polinomio perché ogni fattore di D1 compare anche in D2.
 *          I coefficienti di P e di S sono incognite, quelli dei due membri
 *          devono coincidere: un sistema lineare con tante equazioni quante
 *          incognite, il grado di D, che si risolve con i razionali esatti.
 *          Così ciò che resta, S/D2, ha il denominatore senza fattori
 *          ripetuti (M. V. Ostrogradsky, 1845).
 *
 *   30d-3. I fattori di D2 su Q: le radici razionali, con il teorema delle
 *          radici razionali (rational_roots(), 11m); ciò che resta, se ha
 *          grado 2, è un fattore di secondo grado senza radici razionali; se
 *          ha grado 3 è irriducibile (un polinomio di terzo grado riducibile
 *          ha un fattore di primo grado); da 4 in su si cercano i fattori di
 *          secondo grado con il metodo di Kronecker (uni_quadratic_factor(),
 *          18p-6). Un fattore irriducibile di grado 3 o più ferma il metodo:
 *          le sue radici non si scrivono, e i libri non lo chiedono.
 *
 *   30d-4. Fratti semplici: S/D2 = somma di A_i / (x - r_i) e di
 *          (B_j x + C_j) / q_j(x), con un altro sistema lineare esatto.
 *
 *   30d-5. Le primitive dei fratti: A ln|x - r|; per q = x^2 + p x + s,
 *          (B x + C)/q = (B/2) q'/q + (C - B p/2)/q, e con il trinomio
 *          a x^2 + b x + c a coefficienti interi e Delta = b^2 - 4 a c:
 *
 *              \int dx / (a x^2 + b x + c) = 2 / sqrt(-Delta) arctan((2 a x + b) / sqrt(-Delta))   se Delta < 0,
 *                                          = 1 / sqrt(Delta) ln|(2 a x + b - sqrt(Delta)) / (2 a x + b + sqrt(Delta))|   se Delta > 0.
 *
 *          (Delta = 0 non capita: il trinomio avrebbe una radice razionale.)
 *
 *   30d-6. Quando un fattore resta irriducibile: se N(x)/D(x) = x^{m-1}
 *          R(x^m), con s = x^m si ha ds = m x^{m-1} dx e la primitiva è
 *          quella di R(s)/m, calcolata in s: x/(1 + x^4) diventa
 *          1/(2 (1 + s^2)).
 *
 * I conti sono tra razionali esatti a 64 bit: se escono dai limiti il
 * metodo rinuncia (fail()), non approssima. */

/* Un polinomio in una variabile a coefficienti razionali: c[0] + c[1] x +
 * ... + c[degree] x^degree. Invariante: c[degree] non è zero, i coefficienti
 * oltre degree sono zero; il polinomio nullo ha degree -1. */
typedef struct {
    int degree;
    Frac c[MAX_QPOLY + 1];
} QPoly;

/* Ritorna il polinomio nullo. */
static QPoly qpoly_zero(void) {
    QPoly p;
    p.degree = -1;
    for (int i = 0; i <= MAX_QPOLY; i++) p.c[i] = frac_int(0);
    return p;
}

/* Ristabilisce l'invariante dopo un conto che può aver annullato i
 * coefficienti più alti. */
static void qpoly_trim(QPoly *p) {
    while (p->degree >= 0 && p->c[p->degree].num == 0) p->degree--;
}

/* Ritorna a + scale b. */
static QPoly qpoly_add(QPoly a, QPoly b, Frac scale) {
    int top = a.degree > b.degree ? a.degree : b.degree;
    for (int i = 0; i <= b.degree; i++) a.c[i] = frac_add(a.c[i], frac_mul(scale, b.c[i]));
    a.degree = top;
    qpoly_trim(&a);
    return a;
}

/* Ritorna scale p. */
static QPoly qpoly_scale(QPoly p, Frac scale) { return qpoly_add(qpoly_zero(), p, scale); }

/* Ritorna a b; fallisce se il grado supera MAX_QPOLY. */
static QPoly qpoly_mul(QPoly a, QPoly b) {
    QPoly r = qpoly_zero();
    if (a.degree < 0 || b.degree < 0) return r;
    if (a.degree + b.degree > MAX_QPOLY) { fail("funzione razionale di grado troppo alto"); return r; }
    for (int i = 0; i <= a.degree; i++)
        for (int j = 0; j <= b.degree; j++) r.c[i + j] = frac_add(r.c[i + j], frac_mul(a.c[i], b.c[j]));
    r.degree = a.degree + b.degree;
    qpoly_trim(&r);
    return r;
}

/* Ritorna x^k. */
static QPoly qpoly_power_of_x(int k) {
    QPoly p = qpoly_zero();
    p.c[k] = frac_int(1);
    p.degree = k;
    return p;
}

/* Divide a per b, non nullo: mette quoziente e resto in *quotient e *rest. */
static void qpoly_divide(QPoly a, QPoly b, QPoly *quotient, QPoly *rest) {
    *quotient = qpoly_zero();
    *rest = a;
    while (rest->degree >= b.degree && !failure) {
        int shift = rest->degree - b.degree;
        Frac lead = frac_div(rest->c[rest->degree], b.c[b.degree]);
        quotient->c[shift] = lead;
        if (shift > quotient->degree) quotient->degree = shift;
        for (int j = 0; j < b.degree; j++) rest->c[j + shift] = frac_add(rest->c[j + shift], frac_neg(frac_mul(lead, b.c[j])));
        /* Il coefficiente più alto si annulla per costruzione: lo si azzera
         * a mano, così il ciclo avanza anche dopo un errore di aritmetica. */
        rest->c[rest->degree] = frac_int(0);
        qpoly_trim(rest);
    }
}

/* Ritorna la derivata di p. */
static QPoly qpoly_derivative(QPoly p) {
    QPoly d = qpoly_zero();
    for (int i = 1; i <= p.degree; i++) d.c[i - 1] = frac_mul(p.c[i], frac_int(i));
    d.degree = p.degree - 1;
    qpoly_trim(&d);
    return d;
}

/* Ritorna p diviso per il suo coefficiente più alto (p non nullo). */
static QPoly qpoly_monic(QPoly p) { return qpoly_scale(p, frac_div(frac_int(1), p.c[p.degree])); }

/* Ritorna il massimo comun divisore monico di a e b, non tutti e due nulli:
 * algoritmo di Euclide, mcd(a, b) = mcd(b, resto della divisione). */
static QPoly qpoly_gcd(QPoly a, QPoly b) {
    while (b.degree >= 0 && !failure) {
        QPoly q, r;
        qpoly_divide(a, b, &q, &r);
        a = b;
        b = r;
    }
    return qpoly_monic(a);
}

/* Ritorna p scritto a coefficienti interi senza divisori comuni e con il
 * coefficiente più alto positivo, e mette in *content il razionale per cui
 * va moltiplicato per tornare p. Fallisce se i numeri escono dai limiti. */
static QPoly qpoly_primitive(QPoly p, Frac *content) {
    __int128 g = 0, l = 1;
    for (int i = 0; i <= p.degree; i++) {
        g = gcd128(g, p.c[i].num);
        l = l / gcd128(l, p.c[i].den) * p.c[i].den;
        if (l >= COEF_LIMIT) { fail("numeri troppo grandi per il calcolo esatto"); *content = frac_int(1); return p; }
    }
    *content = p.degree < 0 ? frac_int(1) : frac_make(p.c[p.degree].num < 0 ? -g : g, l);
    return p.degree < 0 ? p : qpoly_scale(p, frac_div(frac_int(1), *content));
}

/* Legge p, un polinomio negli atomi, come polinomio nella sola variabile di
 * atomo x. Ritorna 0 se compare un altro atomo, un esponente negativo o non
 * intero, un coefficiente non reale, o se il grado supera MAX_QPOLY. */
static int qpoly_from(Poly p, int x, QPoly *out) {
    *out = qpoly_zero();
    for (int i = 0; i < p.count; i++) {
        const Term *t = &p.term[i];
        long long e = 0;
        if (t->mono.count > 1 || t->coef.im.num != 0) return 0;
        if (t->mono.count == 1) {
            if (t->mono.factor[0].atom != x || t->mono.factor[0].exp.den != 1) return 0;
            e = t->mono.factor[0].exp.num;
        }
        if (e < 0 || e > MAX_QPOLY) return 0;
        out->c[e] = t->coef.re;
        if (e > out->degree) out->degree = (int)e;
    }
    return 1;
}

/* Aggiunge a text, di size byte, il polinomio p nella variabile di nome
 * letter: 3x^{2} - \frac{1}{2}x + 5. Il polinomio nullo è 0. */
static void qpoly_latex(QPoly p, int letter, char *text, size_t size) {
    char sum[ANSWER_BYTES] = "", body[16];
    for (int i = p.degree; i >= 0; i--) {
        if (i == 0) body[0] = 0;
        else if (i == 1) snprintf(body, sizeof body, "%c", letter);
        else snprintf(body, sizeof body, "%c^{%d}", letter, i);
        term_latex(p.c[i], body, sum, sizeof sum);
    }
    text_add(text, size, "%s", sum[0] ? sum : "0");
}

/* Risolve il sistema lineare di n equazioni in n incognite
 * m[i][0] y_0 + ... + m[i][n-1] y_{n-1} = m[i][n], con l'eliminazione di
 * Gauss sui razionali esatti. Ritorna 1 e mette la soluzione in y[]; ritorna
 * 0 se la matrice è singolare o i numeri escono dai limiti. m viene
 * modificata. */
static int solve_linear(int n, Frac m[][MAX_QPOLY + 2], Frac *y) {
    for (int col = 0; col < n; col++) {
        /* Una riga con il pivot diverso da zero, portata al posto col. */
        int pivot = col;
        while (pivot < n && m[pivot][col].num == 0) pivot++;
        if (pivot == n) return 0;
        for (int k = 0; k <= n && pivot != col; k++) {
            Frac swap = m[col][k];
            m[col][k] = m[pivot][k];
            m[pivot][k] = swap;
        }
        /* La colonna si azzera in tutte le altre righe. */
        for (int row = 0; row < n; row++) {
            if (row == col || m[row][col].num == 0) continue;
            Frac factor = frac_div(m[row][col], m[col][col]);
            for (int k = col; k <= n; k++) m[row][k] = frac_add(m[row][k], frac_neg(frac_mul(factor, m[col][k])));
        }
        if (failure) return 0;
    }
    for (int i = 0; i < n; i++) y[i] = frac_div(m[i][n], m[i][i]);
    return !failure;
}

/* Mette in *square e *kernel i due interi con m = square^2 kernel e kernel senza
 * fattori quadrati, per m positivo fino a 10^12: sqrt(m) = square sqrt(kernel).
 * Ritorna 0 se m è troppo grande. */
static int square_part(long long m, long long *square, long long *kernel) {
    if (m <= 0 || m > 1000000000000LL) return 0;
    *square = 1;
    *kernel = 1;
    long long value = m, prime, times;
    while (pop_prime(&value, &prime, &times)) {
        for (long long k = 0; k < times / 2; k++) *square *= prime;
        if (times % 2) *kernel *= prime;
    }
    return 1;
}

/* 30d-5. Aggiunge a text la primitiva di coef / q, con q = a x^2 + b x + c a
 * coefficienti interi, a > 0, senza radici razionali: vedi la formula in
 * testa al paragrafo. letter è il nome della variabile. */
static void trinomial_latex(Frac coef, long long a, long long b, long long c, int letter, char *text, size_t size) {
    char linear[96] = "", root[48] = "", body[256];
    __int128 delta = (__int128)b * b - (__int128)4 * a * c;
    long long square, kernel;
    if (delta > (__int128)1000000000000LL || delta < -(__int128)1000000000000LL || !square_part(delta < 0 ? (long long)-delta : (long long)delta, &square, &kernel)) {
        fail("numeri troppo grandi per il calcolo esatto");
        return;
    }
    /* 2 a x + b e la radice si dividono per il loro divisore comune: il
     * rapporto non cambia, e x^2 + 1 dà arctan(x), non arctan(2x/2). */
    long long common = (long long)gcd128(gcd128(2 * a, b), square), reduced = square / common;
    QPoly line = qpoly_zero();
    line.c[1] = frac_int(2 * a / common);
    line.c[0] = frac_int(b / common);
    line.degree = 1;
    qpoly_latex(line, letter, linear, sizeof linear);

    /* sqrt(|Delta|) = square sqrt(kernel): il coefficiente diventa razionale
     * portando sqrt(kernel) al numeratore, 1/sqrt(kernel) = sqrt(kernel)/kernel. */
    if (reduced != 1) snprintf(root, sizeof root, "%lld", reduced);
    if (kernel != 1) text_add(root, sizeof root, "\\sqrt{%lld}", kernel);
    const char *outside = "";
    char radical[32] = "";
    if (kernel != 1) { snprintf(radical, sizeof radical, "\\sqrt{%lld}", kernel); outside = radical; }
    if (delta < 0) {
        coef = frac_div(frac_mul(coef, frac_int(2)), frac_int(square * kernel));
        if (root[0]) snprintf(body, sizeof body, "%s\\arctan\\left(\\frac{%s}{%s}\\right)", outside, linear, root);
        else snprintf(body, sizeof body, "%s\\arctan\\left(%s\\right)", outside, linear);
    } else {
        coef = frac_div(coef, frac_int(square * kernel));
        snprintf(body, sizeof body, "%s\\ln\\left|\\frac{%s - %s}{%s + %s}\\right|", outside, linear, root, linear, root);
    }
    term_latex(coef, body, text, size);
}

static int rational_any(QPoly num, QPoly den, int letter, char *text, size_t size, int depth);

/* 30d-6. Se num/den è x^{m-1} R(x^m) per un m >= 2 (il più grande),
 * scrive in text la primitiva, calcolata nella variabile s = x^m e riportata
 * in x. Ritorna 0 se non c'è un tale m. */
static int power_substitution(QPoly num, QPoly den, int letter, char *text, size_t size, int depth) {
    for (int m = den.degree; m >= 2; m--) {
        int fits = 1;
        for (int i = 0; i <= den.degree && fits; i++) fits = den.c[i].num == 0 || i % m == 0;
        for (int i = 0; i <= num.degree && fits; i++) fits = num.c[i].num == 0 || i % m == m - 1;
        if (!fits) continue;

        /* R(s) = Ñ(s) / D̃(s), con s^k al posto di x^{k m}; e 1/m da ds. */
        QPoly inner_num = qpoly_zero(), inner_den = qpoly_zero();
        for (int i = 0; i <= den.degree; i += m) inner_den.c[i / m] = den.c[i];
        for (int i = m - 1; i <= num.degree; i += m) inner_num.c[i / m] = frac_div(num.c[i], frac_int(m));
        inner_den.degree = den.degree / m;
        inner_num.degree = num.degree / m;
        qpoly_trim(&inner_num);
        qpoly_trim(&inner_den);

        /* La nuova variabile: una lettera diversa da quella di partenza. */
        int s = letter == 's' ? 'u' : 's';
        char inner[ANSWER_BYTES] = "";
        if (!rational_any(inner_num, inner_den, s, inner, sizeof inner, depth + 1)) return 0;
        Node *power = node_new(N_POW, node_new(N_VAR, NULL, NULL), node_num(m));
        power->a->name = letter;
        return substitute_back(inner, s, power, text, size);
    }
    return 0;
}

/* 30d. Scrive in text, di size byte, una primitiva di num/den (den non
 * nullo) nella variabile di nome letter, con l'algoritmo in testa al
 * paragrafo. Ritorna 1 se ci riesce, 0 se un fattore di den resta
 * irriducibile o i numeri escono dai limiti. */
static int rational_primitive(QPoly num, QPoly den, int letter, char *text, size_t size, int depth) {
    /* La matrice dei due sistemi lineari: statica perché è grande (10 KB)
     * per la pila di una ricerca ricorsiva. Non è mai in uso durante una
     * chiamata ricorsiva: ogni sistema si risolve prima di andare avanti. */
    static Frac m[MAX_QPOLY + 1][MAX_QPOLY + 2];
    Frac y[MAX_QPOLY + 1];
    char power_text[16];
    text[0] = 0;
    if (depth > MAX_PRIMITIVE_DEPTH) return 0;

    /* La frazione ai minimi termini: i fattori comuni darebbero una
     * primitiva giusta ma scritta male, come t^2 / t^3. Toglierli cambia la
     * funzione solo nei punti in cui non era definita. */
    if (num.degree >= 0) {
        QPoly common = qpoly_gcd(num, den), unused_rest;
        qpoly_divide(num, common, &num, &unused_rest);
        qpoly_divide(den, common, &den, &unused_rest);
    }

    /* Il denominatore monico; poi 30d-1, la divisione. */
    Frac lead = frac_div(frac_int(1), den.c[den.degree]);
    num = qpoly_scale(num, lead);
    den = qpoly_scale(den, lead);
    QPoly quotient, rest, unused;
    qpoly_divide(num, den, &quotient, &rest);
    for (int k = quotient.degree; k >= 0; k--) {
        if (k == 0) snprintf(power_text, sizeof power_text, "%c", letter);
        else snprintf(power_text, sizeof power_text, "%c^{%d}", letter, k + 1);
        term_latex(frac_div(quotient.c[k], frac_int(k + 1)), power_text, text, size);
    }
    if (rest.degree < 0) return !failure;

    /* 30d-2. Hermite-Ostrogradsky, se den ha fattori ripetuti. */
    QPoly d1 = qpoly_gcd(den, qpoly_derivative(den)), d2, s = rest;
    qpoly_divide(den, d1, &d2, &unused);
    if (d1.degree > 0 && !failure) {
        QPoly h;
        qpoly_divide(qpoly_mul(qpoly_derivative(d1), d2), d1, &h, &unused);
        int n = den.degree, unknowns_p = d1.degree;
        for (int j = 0; j < n && !failure; j++) {
            /* La colonna dell'incognita j: un coefficiente di P o di S. */
            QPoly column;
            if (j < unknowns_p) {
                QPoly power = qpoly_power_of_x(j);
                column = qpoly_add(qpoly_mul(qpoly_derivative(power), d2), qpoly_mul(power, h), frac_int(-1));
            } else {
                column = qpoly_mul(qpoly_power_of_x(j - unknowns_p), d1);
            }
            for (int i = 0; i < n; i++) m[i][j] = column.c[i];
        }
        for (int i = 0; i < n; i++) m[i][n] = rest.c[i];
        if (failure || !solve_linear(n, m, y)) return 0;

        /* P/D1, scritta con coefficienti interi sopra e sotto. */
        QPoly p = qpoly_zero();
        s = qpoly_zero();
        for (int j = 0; j < unknowns_p; j++) p.c[j] = y[j];
        for (int j = unknowns_p; j < n; j++) s.c[j - unknowns_p] = y[j];
        p.degree = unknowns_p - 1;
        s.degree = d2.degree - 1;
        qpoly_trim(&p);
        qpoly_trim(&s);
        if (p.degree >= 0) {
            /* Ai minimi termini, a coefficienti interi, con la costante
             * dentro la frazione: -\frac{4}{x - 2}, \frac{9}{4x^{4}}. */
            Frac top, bottom;
            QPoly common = qpoly_gcd(p, d1), reduced_p, reduced_d1;
            qpoly_divide(p, common, &reduced_p, &unused);
            qpoly_divide(d1, common, &reduced_d1, &unused);
            QPoly p_int = qpoly_primitive(reduced_p, &top), d1_int = qpoly_primitive(reduced_d1, &bottom);
            Frac scale = frac_div(top, bottom);
            p_int = qpoly_scale(p_int, frac_int(scale.num < 0 ? -scale.num : scale.num));
            d1_int = qpoly_scale(d1_int, frac_int(scale.den));
            char fraction[ANSWER_BYTES] = "\\frac{";
            qpoly_latex(p_int, letter, fraction, sizeof fraction);
            text_add(fraction, sizeof fraction, "}{");
            qpoly_latex(d1_int, letter, fraction, sizeof fraction);
            text_add(fraction, sizeof fraction, "}");
            term_latex(frac_int(scale.num < 0 ? -1 : 1), fraction, text, size);
        }
        if (s.degree < 0) return !failure;
    }
    if (failure) return 0;

    /* 30d-3. I fattori di d2: prima le radici razionali. */
    Frac root[MAX_QPOLY + 2];
    QPoly quadratic[MAX_QPOLY / 2 + 1], left = d2;
    int roots = 0, quadratics = 0;
    {
        Frac content;
        QPoly whole = qpoly_primitive(d2, &content);
        long long c[MAX_UNIVARIATE + 1];
        if (whole.degree > MAX_UNIVARIATE) return 0;
        for (int i = 0; i <= whole.degree; i++) {
            if (whole.c[i].num > LLONG_MAX / 4 || whole.c[i].num < -(LLONG_MAX / 4)) return 0;
            c[i] = whole.c[i].num;
        }
        roots = rational_roots(c, whole.degree, root);
        if (roots < 0) return 0;
        for (int i = 0; i < roots && !failure; i++) {
            QPoly linear = qpoly_zero(), q, r;
            linear.c[1] = frac_int(1);
            linear.c[0] = frac_neg(root[i]);
            linear.degree = 1;
            qpoly_divide(left, linear, &q, &r);
            left = q;
        }
    }

    /* Poi i fattori di secondo grado: ciò che resta, o i fattori di
     * Kronecker; un fattore irriducibile di grado 3 o più ferma tutto, e
     * resta da provare 30d-6. */
    if (left.degree >= 4 && !failure) {
        Frac content;
        QPoly whole = qpoly_primitive(left, &content);
        Uni u = {whole.degree, {0}}, factor, quotient_uni;
        for (int i = 0; i <= whole.degree; i++) u.c[i] = whole.c[i].num;
        while (u.degree >= 4 && !failure && uni_quadratic_factor(&u, &factor, &quotient_uni)) {
            QPoly q = qpoly_zero();
            for (int i = 0; i <= 2; i++) q.c[i] = frac_make(factor.c[i], 1);
            q.degree = 2;
            quadratic[quadratics++] = qpoly_monic(q);
            u = quotient_uni;
        }
        left = qpoly_zero();
        for (int i = 0; i <= u.degree; i++) left.c[i] = frac_make(u.c[i], 1);
        left.degree = u.degree;
        qpoly_trim(&left);
    }
    if (left.degree == 2) quadratic[quadratics++] = qpoly_monic(left);
    else if (left.degree >= 3 || failure) return 0;

    /* 30d-4. Fratti semplici: le colonne d2/(x - r_i), x d2/q_j e d2/q_j. */
    int n = d2.degree, column = 0;
    for (int i = 0; i < roots && !failure; i++, column++) {
        QPoly linear = qpoly_zero(), q, r;
        linear.c[1] = frac_int(1);
        linear.c[0] = frac_neg(root[i]);
        linear.degree = 1;
        qpoly_divide(d2, linear, &q, &r);
        for (int k = 0; k < n; k++) m[k][column] = q.c[k];
    }
    for (int j = 0; j < quadratics && !failure; j++) {
        QPoly q, r;
        qpoly_divide(d2, quadratic[j], &q, &r);
        QPoly shifted = qpoly_mul(q, qpoly_power_of_x(1));
        for (int k = 0; k < n; k++) {
            m[k][column] = shifted.c[k];
            m[k][column + 1] = q.c[k];
        }
        column += 2;
    }
    if (failure || column != n) return 0;
    for (int k = 0; k < n; k++) m[k][n] = s.c[k];
    if (!solve_linear(n, m, y)) return 0;

    /* 30d-5. Le primitive dei fratti. Un fattore x - u/v si scrive v x - u:
     * cambia il logaritmo di una costante, che si perde nella c. */
    for (int i = 0; i < roots && !failure; i++) {
        char body[128] = "\\ln\\left|";
        QPoly linear = qpoly_zero();
        linear.c[1] = frac_int(root[i].den);
        linear.c[0] = frac_int(-root[i].num);
        linear.degree = 1;
        qpoly_latex(linear, letter, body, sizeof body);
        text_add(body, sizeof body, "\\right|");
        term_latex(y[i], body, text, size);
    }
    for (int j = 0; j < quadratics && !failure; j++) {
        /* q_j = x^2 + p x + q, e il trinomio intero a x^2 + b x + c. */
        Frac b_coef = y[roots + 2 * j], c_coef = y[roots + 2 * j + 1], content;
        QPoly whole = qpoly_primitive(quadratic[j], &content);
        long long a = whole.c[2].num, b = whole.c[1].num, c = whole.c[0].num;
        char body[256] = "";
        __int128 delta = (__int128)b * b - (__int128)4 * a * c;

        /* (B/2) ln q: per Delta < 0 il trinomio è sempre positivo. */
        snprintf(body, sizeof body, delta < 0 ? "\\ln\\left(" : "\\ln\\left|");
        qpoly_latex(whole, letter, body, sizeof body);
        text_add(body, sizeof body, delta < 0 ? "\\right)" : "\\right|");
        term_latex(frac_div(b_coef, frac_int(2)), body, text, size);

        /* (C - B p/2) / q = a (C - B p/2) / (a x^2 + b x + c). */
        Frac rest_coef = frac_add(c_coef, frac_neg(frac_mul(b_coef, frac_div(quadratic[j].c[1], frac_int(2)))));
        trinomial_latex(frac_mul(rest_coef, frac_int(a)), a, b, c, letter, text, size);
    }
    return !failure;
}

/* 30d. La primitiva di num/den: con rational_primitive(), e se un fattore
 * del denominatore resta irriducibile con la sostituzione s = x^m (30d-6).
 * Ritorna 1 se una delle due riesce. */
static int rational_any(QPoly num, QPoly den, int letter, char *text, size_t size, int depth) {
    if (rational_primitive(num, den, letter, text, size, depth)) return 1;
    failure = NULL;
    text[0] = 0;
    if (power_substitution(num, den, letter, text, size, depth)) return 1;
    failure = NULL;
    return 0;
}

/* 30d. Il metodo per la ricerca: se f, calcolata con i conti esatti, è una
 * funzione razionale di x a coefficienti razionali, ne scrive in text una
 * primitiva. */
static int rational_method(const Node *f, int x, int depth, char *text, size_t size) {
    env_count = 0;
    Rat value = eval(f);
    Poly num, den;
    QPoly n, d;
    if (failure || !rat_polynomials(value, &num, &den) || !qpoly_from(num, atom_var(x), &n) || !qpoly_from(den, atom_var(x), &d) || d.degree < 0) {
        failure = NULL;
        return 0;
    }
    int found = rational_any(n, d, x, text, size, depth);
    failure = NULL;
    if (found) primitive_method = "con i fratti semplici";
    return found;
}

/* 30e. I POLINOMI PER ESPONENZIALI
 *
 * Teorema. Per n naturale e lambda complesso diverso da zero
 *
 *     \int x^n e^{lambda x} dx = e^{lambda x} \sum_{k=0}^{n} (-1)^k n!/(n-k)! x^{n-k} / lambda^{k+1}.
 *
 * È ciò che danno n integrazioni per parti, e si controlla derivando: con
 * c_k = (-1)^k n!/((n-k)! lambda^{k+1}), la derivata di e^{lambda x} c_k
 * x^{n-k} è e^{lambda x} (lambda c_k x^{n-k} + (n-k) c_k x^{n-k-1}), e
 * lambda c_k = -(n-k+1) c_{k-1}: le due parti si cancellano a catena, e
 * resta lambda c_0 x^n e^{lambda x} = x^n e^{lambda x}. Per lambda = 0 è
 * x^{n+1}/(n+1).
 *
 * Che cosa ci entra. Il valore di f calcolato con i conti esatti è un
 * polinomio negli atomi; seni e coseni vi sono già esponenziali complessi,
 * sin(b x) = (e^{i b x} - e^{-i b x}) / (2 i) (capitolo 11), e i prodotti e
 * le potenze sono già sviluppati. Se ogni termine è c x^n e^{a x} e^{i b x},
 * con n naturale, a e b razionali e c un numero (eventualmente moltiplicato
 * per costanti come e o \sqrt{2}), la formula si applica termine per
 * termine. Ci entrano così, con lo stesso conto, le potenze di seni e
 * coseni (le formule di bisezione), i prodotti di seni e coseni di angoli
 * diversi (le formule di Werner), x^n sin(b x) e x^n e^{a x} (per parti, più
 * volte), e^{a x} sin(b x) (il caso "ciclico" dei libri, dove l'integrale
 * torna uguale a se stesso dopo due passi).
 *
 * Il ritorno ai numeri reali. La primitiva ha termini d e^{i b x} e d'
 * e^{-i b x}; se la funzione è reale lo è anche lei, e la coppia vale
 * (d + d') cos(b x) + i (d - d') sin(b x), con due coefficienti reali. Se
 * non lo sono la funzione non era reale, e il metodo rinuncia. */

/* Un termine della primitiva: coef x^power e^{(a + i b) x} constant. */
typedef struct {
    int power;       /* l'esponente di x, da 0 in su */
    Frac a, b;       /* l'esponenziale e^{(a + i b) x} */
    Mono constant;   /* il prodotto degli atomi che non dipendono da x */
    Num coef;        /* il coefficiente, complesso */
} ExpTerm;

static ExpTerm exp_term[MAX_EXP_TERMS];
static int exp_terms;

/* Aggiunge alla primitiva il termine coef x^power e^{(a + i b) x}
 * constant, sommandolo a quello con gli stessi esponenti se c'è già. */
static void exp_term_add(int power, Frac a, Frac b, const Mono *constant, Num coef) {
    for (int i = 0; i < exp_terms; i++) {
        ExpTerm *t = &exp_term[i];
        if (t->power == power && frac_cmp(t->a, a) == 0 && frac_cmp(t->b, b) == 0 && mono_cmp(&t->constant, constant) == 0) {
            t->coef = num_add(t->coef, coef);
            return;
        }
    }
    if (exp_terms == MAX_EXP_TERMS) { fail("primitiva con troppi termini"); return; }
    exp_term[exp_terms++] = (ExpTerm){power, a, b, *constant, coef};
}

/* Prototipo in avanti necessario: la base di un atomo è un polinomio, fatto
 * di atomi. */
static int poly_involves(Poly p, int x);

/* Ritorna 1 se l'atomo dipende dall'atomo x, a qualunque livello: è x, o
 * x compare nella sua base, nel suo esponente o nel suo argomento. Per
 * prudenza le somme e le successioni ne dipendono sempre. */
static int atom_involves(int atom, int x) {
    const Atom *a = &atoms[atom];
    if (atom == x) return 1;
    switch (a->kind) {
    case ATOM_VAR: return 0;
    case ATOM_ATAN: return poly_involves(atan_args[a->id].num, x) || poly_involves(atan_args[a->id].den, x);
    case ATOM_POW: case ATOM_LN:
        for (int i = 0; a->kind == ATOM_POW && i < a->exponent.count; i++)
            if (atom_involves(a->exponent.factor[i].atom, x)) return 1;
        if (a->base == BASE_ATOM) return atom_involves((int)a->id, x);
        return a->base == BASE_POLY && poly_involves(base_polys[a->id], x);
    default: return 1;
    }
}

static int poly_involves(Poly p, int x) {
    for (int i = 0; i < p.count; i++)
        for (int f = 0; f < p.term[i].mono.count; f++)
            if (atom_involves(p.term[i].mono.factor[f].atom, x)) return 1;
    return 0;
}

/* Mette in text, di size byte, il monomio m scritto da put_mono() (capitolo
 * 13); ritorna 0 se non ci sta o se contiene qualcosa che non si scrive. */
static int mono_latex(const Mono *m, char *text, size_t size) {
    size_t start = proof_length;
    unwritable = 0;
    if (m->count) put_mono(m);
    size_t length = proof_length - start;
    int fits = !unwritable && proof_length < PROOF_BYTES - 1 && length < size;
    if (fits) {
        memcpy(text, proof_text + start, length);
        text[length] = 0;
    }
    proof_cut(start);
    return fits;
}

/* 30e. Il metodo per la ricerca: vedi la testa del paragrafo. */
static int exponential_method(const Node *f, int x, int depth, char *text, size_t size) {
    (void)depth;
    env_count = 0;
    Rat value = eval(f);
    int xa = atom_var(x), e = atom_var('e');
    exp_terms = 0;
    if (failure || !poly_is_one(value.den)) { failure = NULL; return 0; }

    /* Ogni termine: c x^n e^{a x} e^{i b x} per le costanti; si integra
     * subito con la formula. */
    for (int i = 0; i < value.num.count && !failure; i++) {
        const Term *t = &value.num.term[i];
        int n = 0;
        Frac a = frac_int(0), b = frac_int(0);
        Mono constant;
        constant.count = 0;
        for (int k = 0; k < t->mono.count; k++) {
            const Factor *factor = &t->mono.factor[k];
            const Atom *atom = &atoms[factor->atom];
            int linear = atom->kind == ATOM_POW && atom->exponent.count == 1 && atom->exponent.factor[0].atom == xa &&
                         frac_cmp(atom->exponent.factor[0].exp, frac_int(1)) == 0;
            /* Un atomo 1^M vale 1: nasce da power(), che calcola e^{u} come
             * il quoziente delle potenze di numeratore e denominatore di e,
             * e il denominatore è 1. */
            if (atom->kind == ATOM_POW && atom->base == BASE_POLY && poly_is_one(base_polys[atom->id])) continue;
            if (factor->atom == xa && factor->exp.den == 1 && factor->exp.num >= 0) n = (int)factor->exp.num;
            else if (linear && atom->base == BASE_EI) b = frac_add(b, factor->exp);
            else if (linear && atom->base == BASE_ATOM && atom->id == e) a = frac_add(a, factor->exp);
            else if (!atom_involves(factor->atom, xa)) { Mono single = mono_atom(factor->atom, factor->exp); constant = mono_mul(&constant, &single); }
            else return 0;
        }
        if (n > MAX_POWER) return 0;
        if (a.num == 0 && b.num == 0) {
            exp_term_add(n + 1, a, b, &constant, num_mul(t->coef, num_frac((Frac){1, n + 1})));
            continue;
        }
        /* lambda = a + i b, e i termini c_k della formula. */
        Num inverse = num_inv((Num){a, b}), step = num_mul(t->coef, inverse);
        for (int k = 0; k <= n && !failure; k++) {
            exp_term_add(n - k, a, b, &constant, step);
            step = num_mul(num_mul(step, inverse), num_int(-(n - k)));
        }
    }
    if (failure) { failure = NULL; return 0; }

    /* Il ritorno ai reali: per ogni termine con b >= 0 il suo compagno con
     * -b, e i due coefficienti reali del coseno e del seno. */
    text[0] = 0;
    for (int i = 0; i < exp_terms && !failure; i++) {
        ExpTerm *t = &exp_term[i];
        if (t->b.num < 0 && t->power >= 0) {
            /* Senza un compagno con +b: lo si crea, con coefficiente zero. */
            Frac plus = frac_neg(t->b);
            exp_term_add(t->power, t->a, plus, &t->constant, num_int(0));
        }
    }
    for (int i = 0; i < exp_terms && !failure; i++) {
        ExpTerm *t = &exp_term[i];
        if (t->b.num < 0) continue;
        Num partner = num_int(0);
        for (int j = 0; j < exp_terms; j++) {
            const ExpTerm *u = &exp_term[j];
            if (t->b.num != 0 && u->power == t->power && frac_cmp(u->a, t->a) == 0 && frac_cmp(u->b, frac_neg(t->b)) == 0 &&
                mono_cmp(&u->constant, &t->constant) == 0)
                partner = u->coef;
        }
        Num cosine = t->b.num ? num_add(t->coef, partner) : t->coef;
        Num difference_ = num_add(t->coef, num_neg(partner));
        Num sine = {frac_neg(difference_.im), difference_.re};
        if (cosine.im.num != 0 || (t->b.num != 0 && sine.im.num != 0)) { failure = NULL; return 0; }

        /* Il corpo comune: costanti, x^m, e^{a x}; poi cos e sin di b x. */
        char body[512] = "", piece[160] = "";
        if (!mono_latex(&t->constant, body, sizeof body)) return 0;
        /* Una costante puo finire con un comando senza graffe, come \pi:
         * accostarle x o e scriverebbe \pix o \pie, comandi diversi. Il
         * prodotto esplicito conserva i fattori anche quando si rileggono. */
        if (body[0] && (t->power > 0 || t->a.num != 0)) text_add(body, sizeof body, " \\cdot ");
        if (t->power == 1) text_add(body, sizeof body, "%c", x);
        else if (t->power > 1) text_add(body, sizeof body, "%c^{%d}", x, t->power);
        if (t->a.num != 0) {
            char letter[2] = {(char)x, 0};
            term_latex(t->a, letter, piece, sizeof piece);
            text_add(body, sizeof body, "e^{%s}", piece);
        }
        if (t->b.num == 0) { term_latex(cosine.re, body, text, size); continue; }
        char angle[96] = "", trig[768];
        char letter[2] = {(char)x, 0};
        term_latex(t->b, letter, angle, sizeof angle);
        snprintf(trig, sizeof trig, "%s\\cos\\left(%s\\right)", body, angle);
        term_latex(cosine.re, trig, text, size);
        snprintf(trig, sizeof trig, "%s\\sin\\left(%s\\right)", body, angle);
        term_latex(sine.re, trig, text, size);
    }
    if (failure) { failure = NULL; return 0; }
    if (!text[0]) snprintf(text, size, "0");
    primitive_method = "con i polinomi per esponenziali";
    return 1;
}

/* 30f. PER PARTI
 *
 * Teorema. Se u e v sono derivabili su un intervallo,
 *
 *     \int u v' dx = u v - \int u' v dx,
 *
 * perché (u v)' = u' v + u v'. La regola di scelta dei libri: u è il
 * fattore che derivando si semplifica, v' quello che si sa integrare. Qui u
 * è un logaritmo o un'arcotangente L (anche una sua potenza L^k), la cui
 * derivata è razionale nell'argomento, e v' è tutto il resto P: ci si
 * aspetta che V = \int P dx non contenga più logaritmi né arcotangenti (un
 * polinomio, una funzione razionale), e allora resta \int V (L^k)' dx, che
 * ha L^{k-1} al posto di L^k. x^2 ln x, ln(1 + x^2), x arctan(1 + 16 x),
 * arctan(x)/x^2, ln^2 x si fanno così.
 *
 * I prodotti con un esponenziale, un seno o un coseno (x^3 e^x, e^x sin x)
 * non passano di qui: sono il paragrafo 30e, che li fa tutti con una
 * formula. */

/* Ritorna 1 se il nodo è un logaritmo o un'arcotangente di un argomento con
 * x, o una sua potenza a esponente intero positivo scritto come numero. */
static int is_log_like(const Node *node, int x) {
    if (node->kind == N_POW && node->b->kind == N_NUM && node->b->value >= 1) node = node->a;
    return node->kind == N_CALL && (node->op == FN_LN || node->op == FN_LOG || node->op == FN_ARCTAN) && node_has_variable(node->a, x);
}

/* Ritorna 1 se in tree compare un logaritmo o un'arcotangente di x. */
static int has_log_like(const Node *tree, int x) {
    if (!tree) return 0;
    if (is_log_like(tree, x)) return 1;
    return has_log_like(tree->a, x) || has_log_like(tree->b, x) || has_log_like(tree->c, x);
}

/* Cerca tra i fattori di tree (prodotti, numeratori, segni meno) quelli che
 * is_log_like() accetta: li conta in *count e mette l'ultimo in *found. */
static void log_factors(const Node *tree, int x, const Node **found, int *count) {
    if (is_log_like(tree, x)) { *found = tree; (*count)++; return; }
    if (tree->kind == N_MUL) { log_factors(tree->a, x, found, count); log_factors(tree->b, x, found, count); }
    else if (tree->kind == N_DIV || tree->kind == N_NEG) log_factors(tree->a, x, found, count);
}

/* Ritorna una copia di tree, in cui target è un fattore (come per
 * node_is_factor(), 9j), con target sostituito da 1. */
static Node *drop_factor(Node *tree, const Node *target) {
    if (tree == target) return node_num(1);
    if (tree->kind == N_MUL && tree->a == target) return tree->b;
    if (tree->kind == N_MUL && tree->b == target) return tree->a;
    if (tree->kind == N_MUL) return node_is_factor(tree->a, target) ? node_new(N_MUL, drop_factor(tree->a, target), tree->b)
                                                                   : node_new(N_MUL, tree->a, drop_factor(tree->b, target));
    if (tree->kind == N_DIV || tree->kind == N_NEG) return node_new(tree->kind, drop_factor(tree->a, target), tree->b);
    return tree;
}

/* 30f. Il metodo per la ricerca: vedi la testa del paragrafo. */
static int parts_method(const Node *f, int x, int depth, char *text, size_t size) {
    const Node *log = NULL;
    int count = 0;
    Node *folded = node_fold(f, &(int){1});
    log_factors(folded, x, &log, &count);
    if (count != 1) return 0;
    Node *rest = drop_factor(folded, log);
    if (has_log_like(rest, x)) return 0;

    /* V = \int P, che non deve avere logaritmi; poi \int V L'. */
    char inner[ANSWER_BYTES], tail[ANSWER_BYTES];
    if (!primitive_text(rest, x, depth + 1, inner, sizeof inner)) return 0;
    Node *v = text_tree(inner);
    if (!v || has_log_like(v, x)) return 0;
    Node *slope = derive(strip_log_abs(log), x);
    if (failure) { failure = NULL; return 0; }
    if (!primitive_text(node_new(N_MUL, v, slope), x, depth + 1, tail, sizeof tail)) return 0;
    Node *g = text_tree(tail);
    if (!g || !node_latex(node_new(N_SUB, node_new(N_MUL, v, (Node *)log), g), text, size)) return 0;
    primitive_method = "per parti";
    return 1;
}

/* 30g. PER SOSTITUZIONE
 *
 * Teorema. Se G è una primitiva di g e h è derivabile, allora
 *
 *     \int g(h(x)) h'(x) dx = G(h(x)) + c,
 *
 * perché (G(h(x)))' = g(h(x)) h'(x) per la regola della catena.
 *
 * Come si riconosce h (la "derivata che divide"). Per ogni funzione interna
 * h dell'integranda f (l'argomento di una funzione, la base o l'esponente di
 * una potenza, una funzione intera come ln x o sin x) si calcola q = f / h'
 * e, nel suo albero, si scrive t al posto di ogni h. Se ciò che resta non
 * dipende più da x, cioè la sua derivata rispetto a x si riduce a zero con
 * i conti esatti, allora q = g(h(x)) con g(t) quel che resta, e la primitiva
 * è G(h(x)), con G cercata nella variabile t. È il caso di x e^{2x^2 - 1}
 * (h = 2x^2 - 1), di 1/(x sqrt(ln x)) (h = ln x), di R(cos x) sin x
 * (h = cos x).
 *
 * Le sostituzioni che rendono la funzione razionale. Quando ogni radice
 * dell'integranda ha lo stesso radicando a x + b, con t = (a x + b)^{1/n}
 * (n il minimo comune multiplo degli indici) le radici diventano potenze di
 * t, x = (t^n - b)/a e dx = (n/a) t^{n-1} dt. Quando ogni potenza con x
 * all'esponente ha la stessa base B e un esponente lineare, con
 * t = B^{g x} (g il massimo comun divisore dei coefficienti) le potenze
 * diventano potenze di t e dx = dt / (g ln(B) t). In tutti e due i casi
 * la funzione nella nuova variabile è spesso razionale (30d), o ha una
 * radice di un polinomio di primo grado in t, e si ricomincia. */

/* Ritorna una copia di tree in cui ogni sotto-albero scritto come h è la
 * lettera t. */
static Node *replace_subtree(const Node *tree, const Node *h, Node *t) {
    if (!tree) return NULL;
    if (node_equal(tree, h)) return t;
    Node *copy = node_new(tree->kind, replace_subtree(tree->a, h, t), replace_subtree(tree->b, h, t));
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    copy->c = replace_subtree(tree->c, h, t);
    return copy;
}

/* Aggiunge a list[] (di *count posti, al più MAX_INNER) le funzioni
 * interne di tree che contengono x: le chiamate di funzione, le potenze con
 * x, i loro argomenti, basi ed esponenti. x stessa e i doppioni no. */
static void collect_candidates(const Node *tree, int x, const Node **list, int *count) {
    if (!tree || !node_has_variable(tree, x)) return;
    const Node *own[3] = {NULL, NULL, NULL};
    if (tree->kind == N_CALL || tree->kind == N_POW) { own[0] = tree; own[1] = tree->a; own[2] = tree->kind == N_POW ? tree->b : NULL; }
    for (int i = 0; i < 3; i++) {
        const Node *h = own[i];
        if (!h || !node_has_variable(h, x) || (h->kind == N_VAR && h->name == x)) continue;
        int seen = 0;
        for (int j = 0; j < *count && !seen; j++) seen = node_equal(list[j], h);
        if (!seen && *count < MAX_INNER) list[(*count)++] = h;
    }
    collect_candidates(tree->a, x, list, count);
    collect_candidates(tree->b, x, list, count);
}

/* Ritorna l'albero del razionale v. */
static Node *frac_node(Frac v) {
    Node *n = node_num(v.num < 0 ? -v.num : v.num);
    if (v.den != 1) n = node_new(N_DIV, n, node_num(v.den));
    return v.num < 0 ? node_new(N_NEG, n, NULL) : n;
}

/* Ritorna l'albero della lettera name. */
static Node *letter_node(int name) {
    Node *n = node_new(N_VAR, NULL, NULL);
    n->name = name;
    return n;
}

/* Ritorna 1 se tree, calcolato con i conti esatti, vale zero dove è
 * definito; 0 se non lo si dimostra. */
static int tree_vanishes(const Node *tree) {
    env_count = 0;
    Rat value = eval(tree);
    int zero = !failure && poly_vanishes(value.num);
    failure = NULL;
    return zero;
}

/* Ritorna il fattore di tree (come per node_is_factor(), 9j) scritto come
 * target, o NULL se non c'è. */
static const Node *find_factor(const Node *tree, const Node *target) {
    if (node_equal(tree, target)) return tree;
    if (tree->kind == N_MUL) {
        const Node *found = find_factor(tree->a, target);
        return found ? found : find_factor(tree->b, target);
    }
    return tree->kind == N_DIV || tree->kind == N_NEG ? find_factor(tree->a, target) : NULL;
}

/* Scrive la derivata slope come c g, con c senza x: scende per i segni, i
 * prodotti per un fattore senza x e i quozienti per una costante. Mette in
 * *core il nucleo g (x^1 diventa x) e ritorna l'albero di c. */
static Node *slope_constant(const Node *slope, int x, const Node **core) {
    if (slope->kind == N_NEG) return node_new(N_NEG, slope_constant(slope->a, x, core), NULL);
    if (slope->kind == N_MUL && !node_has_variable(slope->a, x)) return node_new(N_MUL, slope->a, slope_constant(slope->b, x, core));
    if (slope->kind == N_MUL && !node_has_variable(slope->b, x)) return node_new(N_MUL, slope_constant(slope->a, x, core), slope->b);
    if (slope->kind == N_DIV && !node_has_variable(slope->b, x)) return node_new(N_DIV, slope_constant(slope->a, x, core), slope->b);
    *core = slope->kind == N_POW && slope->b->kind == N_NUM && slope->b->value == 1 ? slope->a : slope;
    return node_num(1);
}

/* 30g. La derivata che divide: vedi la testa del paragrafo. Se h' = c g e g
 * è scritta come un fattore di f, q è f senza quel fattore, diviso c (si
 * evita una divisione che resterebbe scritta, come sin(x)/sin(x)); se
 * h = ln x, la x che resta è e^t. */
static int substitution_method(const Node *f, int x, int depth, char *text, size_t size) {
    const Node *candidate[MAX_INNER];
    int count = 0, t = fresh_variable(f);
    collect_candidates(f, x, candidate, &count);
    for (int i = 0; i < count && t; i++) {
        const Node *h = candidate[i];
        Node *slope = derive(strip_log_abs(h), x);
        if (failure) { failure = NULL; continue; }
        const Node *core;
        Node *constant = slope_constant(node_fold(slope, &(int){1}), x, &core);
        const Node *factor = find_factor(f, core);
        Node *quotient = factor ? node_new(N_DIV, drop_factor((Node *)f, factor), constant) : node_new(N_DIV, (Node *)f, slope);
        Node *q = replace_subtree(quotient, h, letter_node(t));
        if (h->kind == N_CALL && h->op == FN_LN && h->a->kind == N_VAR && h->a->name == x)
            q = node_replace(q, x, node_new(N_POW, letter_node('e'), letter_node(t)));

        /* Se resta x, deve essere solo apparente: la derivata rispetto a x
         * si annulla, e allora si dà a x un valore qualsiasi in cui q si
         * calcola. */
        if (node_has_variable(q, x)) {
            Node *change = derive(strip_log_abs(q), x);
            if (failure) { failure = NULL; continue; }
            if (!tree_vanishes(change)) continue;
            Node *fixed = NULL;
            for (int p = 0; p < PRIMITIVE_POINTS && !fixed; p++) {
                Node *attempt = node_replace(q, x, frac_node(primitive_points[p]));
                env_count = 0;
                eval(attempt);
                if (!failure) fixed = attempt;
                failure = NULL;
            }
            if (!fixed) continue;
            q = fixed;
        }

        /* G nella variabile t, poi t = h. */
        char inner[ANSWER_BYTES];
        if (!primitive_text(q, t, depth + 1, inner, sizeof inner)) continue;
        if (!substitute_back(inner, t, h, text, size)) continue;
        primitive_method = "per sostituzione";
        return 1;
    }
    return 0;
}

/* I nodi radice raccolti da collect_roots(): \sqrt[k]{B} e B^{p/q}. */
typedef struct {
    const Node *node;  /* il nodo della radice, o della potenza */
    long long index;   /* l'indice k, o il denominatore q */
    long long power;   /* 1 per una radice, il numeratore p per una potenza */
} RootNode;

/* Aggiunge a list[] le radici di tree con x nel radicando: \sqrt[k]{B} con k
 * numero, e B^{e} con e un razionale non intero senza x. Ritorna 0 se ce ne
 * sono troppe. */
static int collect_roots(const Node *tree, int x, RootNode *list, int *count) {
    if (!tree || !node_has_variable(tree, x)) return 1;
    long long index = 0, power = 1;
    if (tree->kind == N_CALL && tree->op == FN_ROOT && node_has_variable(tree->a, x)) {
        if (tree->b->kind != N_NUM || tree->b->value < 2) return 0;
        index = tree->b->value;
    } else if (tree->kind == N_POW && node_has_variable(tree->a, x) && !node_has_variable(tree->b, x)) {
        env_count = 0;
        Num e;
        int numeric = rat_number(eval(tree->b), &e);
        failure = NULL;
        if (numeric && e.im.num == 0 && e.re.den != 1) { index = e.re.den; power = e.re.num; }
    }
    if (index) {
        if (*count == MAX_INNER) return 0;
        list[(*count)++] = (RootNode){tree, index, power};
    }
    return collect_roots(tree->a, x, list, count) && collect_roots(tree->b, x, list, count);
}

/* Ritorna una copia di tree con le radici di list[] scritte come potenze di
 * t (la radice di indice k è t^{n/k}) e x sostituita da value. */
static Node *rationalize(const Node *tree, int x, const RootNode *list, int count, long long n, Node *t, Node *value) {
    if (!tree) return NULL;
    for (int i = 0; i < count; i++)
        if (list[i].node == tree) return node_new(N_POW, t, frac_node(frac_make((__int128)n * list[i].power, list[i].index)));
    if (tree->kind == N_VAR && tree->name == x) return value;
    Node *copy = node_new(tree->kind, rationalize(tree->a, x, list, count, n, t, value), rationalize(tree->b, x, list, count, n, t, value));
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    copy->c = tree->c;
    return copy;
}

/* 30g. t = (a x + b)^{1/n}: vedi la testa del paragrafo. */
static int root_method(const Node *f, int x, int depth, char *text, size_t size) {
    RootNode root[MAX_INNER];
    int count = 0, t = fresh_variable(f);
    if (!t || !collect_roots(f, x, root, &count) || count == 0) return 0;

    /* Lo stesso radicando, di primo grado in x: B = a x + b. */
    env_count = 0;
    Rat base = eval(root[0].node->a);
    Poly num, den;
    QPoly linear;
    if (failure || !rat_polynomials(base, &num, &den) || !poly_is_one(den) || !qpoly_from(num, atom_var(x), &linear) || linear.degree != 1) { failure = NULL; return 0; }
    long long n = 1;
    for (int i = 0; i < count; i++) {
        env_count = 0;
        Rat other = eval(root[i].node->a);
        if (failure || !poly_vanishes(rat_add(other, base, 1).num)) { failure = NULL; return 0; }
        n = n / (long long)gcd128(n, root[i].index) * root[i].index;
        if (n > MAX_UNI) return 0;
    }

    /* x = (t^n - b)/a e dx = (n/a) t^{n-1} dt. */
    Frac a = linear.c[1], b = linear.c[0];
    Node *tn = node_new(N_POW, letter_node(t), node_num(n));
    Node *value = node_new(N_DIV, node_new(N_SUB, tn, frac_node(b)), frac_node(a));
    Node *inside = rationalize(f, x, root, count, n, letter_node(t), value);
    Node *g = node_new(N_MUL, frac_node(frac_div(frac_int(n), a)), node_new(N_MUL, inside, node_new(N_POW, letter_node(t), node_num(n - 1))));
    if (failure) { failure = NULL; return 0; }

    /* G(t), poi t = radice n-esima di a x + b. */
    char inner[ANSWER_BYTES];
    if (!primitive_text(g, t, depth + 1, inner, sizeof inner)) return 0;
    Node *back = node_call(FN_ROOT, (Node *)root[0].node->a, node_num(n));
    if (!substitute_back(inner, t, back, text, size)) return 0;
    primitive_method = "per sostituzione, con una radice";
    return 1;
}

/* Aggiunge a list[] le potenze di tree con x all'esponente e la base senza
 * x. Ritorna 0 se sono troppe. */
static int collect_exponentials(const Node *tree, int x, const Node **list, int *count) {
    if (!tree || !node_has_variable(tree, x)) return 1;
    if (tree->kind == N_POW && !node_has_variable(tree->a, x)) {
        if (*count == MAX_INNER) return 0;
        list[(*count)++] = tree;
        return 1;
    }
    return collect_exponentials(tree->a, x, list, count) && collect_exponentials(tree->b, x, list, count);
}

/* Ritorna una copia di tree con ogni potenza di list[] sostituita da
 * replacement[] nella stessa posizione. */
static Node *replace_listed(const Node *tree, const Node **list, Node **replacement, int count) {
    if (!tree) return NULL;
    for (int i = 0; i < count; i++)
        if (list[i] == tree) return replacement[i];
    Node *copy = node_new(tree->kind, replace_listed(tree->a, list, replacement, count), replace_listed(tree->b, list, replacement, count));
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    copy->c = tree->c;
    return copy;
}

/* 30g. t = B^{g x}: vedi la testa del paragrafo. */
static int exponential_substitution(const Node *f, int x, int depth, char *text, size_t size) {
    const Node *power[MAX_INNER];
    Node *replacement[MAX_INNER];
    Frac slope[MAX_INNER], shift[MAX_INNER];
    int count = 0, t = fresh_variable(f), xa = atom_var(x);
    if (!t || !collect_exponentials(f, x, power, &count) || count == 0) return 0;

    /* La stessa base, positiva (o e), ed esponenti a x + b con a e b
     * razionali; g è il massimo comun divisore degli a. */
    env_count = 0;
    Rat base = eval(power[0]->a);
    Num value;
    int euler = power[0]->a->kind == N_VAR && power[0]->a->name == 'e';
    if (failure || (!euler && (!rat_number(base, &value) || value.im.num != 0 || value.re.num <= 0 || frac_cmp(value.re, frac_int(1)) == 0))) { failure = NULL; return 0; }
    __int128 top = 0, bottom = 1;
    for (int i = 0; i < count; i++) {
        env_count = 0;
        Rat other = eval(power[i]->a), exponent = eval(power[i]->b);
        Poly num, den;
        QPoly line;
        if (failure || !poly_vanishes(rat_add(other, base, 1).num) || !rat_polynomials(exponent, &num, &den) || !poly_is_one(den) ||
            !qpoly_from(num, xa, &line) || line.degree != 1) { failure = NULL; return 0; }
        slope[i] = line.c[1];
        shift[i] = line.c[0];
        top = gcd128(top, slope[i].num);
        bottom = bottom / gcd128(bottom, slope[i].den) * slope[i].den;
        if (bottom > MAX_POWER) return 0;
    }
    Frac g = frac_make(top, bottom);

    /* B^{a x + b} = B^b t^{a/g}; x non deve restare. */
    for (int i = 0; i < count; i++) {
        Frac k = frac_div(slope[i], g);
        Node *piece = frac_cmp(k, frac_int(1)) == 0 ? letter_node(t) : node_new(N_POW, letter_node(t), frac_node(k));
        if (shift[i].num != 0) piece = node_new(N_MUL, node_new(N_POW, power[i]->a, frac_node(shift[i])), piece);
        replacement[i] = piece;
    }
    Node *inside = replace_listed(f, power, replacement, count);
    if (failure || node_has_variable(inside, x)) { failure = NULL; return 0; }

    /* dx = dt / (g ln(B) t): la costante davanti, perché la linearità la
     * porti fuori. */
    Node *logarithm_of_base = node_call(FN_LN, power[0]->a, NULL);
    if (frac_cmp(g, frac_int(1)) != 0) logarithm_of_base = node_new(N_MUL, frac_node(g), logarithm_of_base);
    Node *constant = euler ? frac_node(frac_div(frac_int(1), g)) : node_new(N_DIV, node_num(1), logarithm_of_base);
    Node *integrand = node_new(N_MUL, constant, node_new(N_DIV, inside, letter_node(t)));
    char inner[ANSWER_BYTES];
    if (!primitive_text(integrand, t, depth + 1, inner, sizeof inner)) return 0;
    Node *back = node_new(N_POW, power[0]->a, node_new(N_MUL, frac_node(g), letter_node(x)));
    if (frac_cmp(g, frac_int(1)) == 0) back->b = letter_node(x);
    if (!substitute_back(inner, t, back, text, size)) return 0;
    primitive_method = "per sostituzione, con un esponenziale";
    return 1;
}

/* 30h. SENO E COSENO: t = tan(x/2)
 *
 * Teorema. Se t = tan(theta/2) e theta non è un multiplo dispari di pi,
 *
 *     e^{i theta} = cos(theta) + i sin(theta) = (1 + i t) / (1 - i t),
 *
 * perché cos(theta) = (1 - t^2)/(1 + t^2) e sin(theta) = 2 t/(1 + t^2), e
 * (1 + i t)^2 = (1 - t^2) + 2 i t. Inoltre d theta = 2 dt / (1 + t^2). Una
 * funzione razionale di seno e coseno di theta, che nei conti esatti è una
 * frazione di polinomi negli esponenziali e^{i k theta} (capitolo 11),
 * diventa così una funzione razionale di t (a coefficienti complessi, ma il
 * suo valore è reale: la si moltiplica sopra e sotto per il coniugato del
 * denominatore), e si integra con 30d.
 *
 * L'angolo theta. Gli esponenti di e^{i x} che compaiono sono multipli
 * interi di un razionale g, il loro massimo comun divisore, e theta = g x.
 * Se inoltre, sopra e sotto, sono tutti pari o tutti dispari (in unità di
 * g), la funzione non cambia sommando pi/g a x, ed è una funzione di
 * e^{2 i g x}: allora theta = 2 g x, e t = tan(g x). È la regola di Bioche
 * per tan x, e dà primitive più corte: tan^2 x e 1/(sin^2 x cos^2 x) sono
 * razionali in tan x.
 *
 * La primitiva vale dove tan(theta/2) è definita: tra due multipli dispari
 * consecutivi di pi, ed è la verifica a dirlo, come sempre. */

/* Ritorna il polinomio (1 + i t)^p (1 - i t)^q nell'atomo t. */
static Poly cayley_factor(int t, int p, int q) {
    Term term;
    term.coef = num_int(1);
    term.mono = mono_atom(t, frac_int(1));
    Poly plus = poly_add(poly_const(num_int(1)), poly_mul(poly_const((Num){frac_int(0), frac_int(1)}), poly_term(term)), 0);
    Poly minus = poly_add(poly_const(num_int(1)), poly_mul(poly_const((Num){frac_int(0), frac_int(1)}), poly_term(term)), 1);
    Poly r = poly_const(num_int(1));
    for (int i = 0; i < p; i++) r = poly_mul(r, plus);
    for (int i = 0; i < q; i++) r = poly_mul(r, minus);
    return r;
}

/* Ritorna il coniugato di p: i coefficienti con la parte immaginaria
 * cambiata di segno (gli atomi sono lettere reali). */
static Poly poly_conjugate(Poly p) {
    Poly r = poly_add(poly_const(num_int(0)), p, 0);
    for (int i = 0; i < r.count; i++) r.term[i].coef.im = frac_neg(r.term[i].coef.im);
    return r;
}

/* Legge l'esponente di e^{i x} nel termine t, in *e: ritorna 0 se il termine
 * contiene qualcos'altro. ei è l'atomo e^{i x}. */
static int trig_exponent(const Term *t, int ei, Frac *e) {
    *e = frac_int(0);
    for (int k = 0; k < t->mono.count; k++) {
        if (t->mono.factor[k].atom != ei) return 0;
        *e = t->mono.factor[k].exp;
    }
    return 1;
}

/* L'intero k per cui il termine t, c e^{i e x}, è c w^k con w = e^{i theta}:
 * k = (e/g - odd)/2 con la regola di Bioche (bioche = 1), k = e/g senza.
 * ei è l'atomo e^{i x}. */
static long long trig_power(const Term *t, int ei, Frac g, int bioche, int odd) {
    Frac e;
    trig_exponent(t, ei, &e);
    long long k = frac_div(e, g).num;
    return bioche ? (k - odd) / 2 : k;
}

/* Riscrive la somma p di termini c w^k come polinomio nell'atomo t,
 * moltiplicata per (1 + i t)^M (1 - i t)^M: con w = (1 + i t)/(1 - i t),
 * w^k (1 + i t)^M (1 - i t)^M = (1 + i t)^{M+k} (1 - i t)^{M-k}, che per
 * |k| <= M è un polinomio. Gli altri argomenti come per trig_power(). */
static Poly cayley_poly(Poly p, int ei, Frac g, int bioche, int odd, long long big, int t) {
    Poly r = poly_const(num_int(0));
    for (int i = 0; i < p.count && !failure; i++) {
        long long k = trig_power(&p.term[i], ei, g, bioche, odd);
        r = poly_add(r, poly_mul(poly_const(p.term[i].coef), cayley_factor(t, (int)(big + k), (int)(big - k))), 0);
    }
    return r;
}

/* 30h. Il metodo per la ricerca: vedi la testa del paragrafo. */
static int trig_method(const Node *f, int x, int depth, char *text, size_t size) {
    env_count = 0;
    Rat value = eval(f);
    int t = fresh_variable(f);
    if (failure || !t) { failure = NULL; return 0; }
    Mono angle = mono_atom(atom_var(x), frac_int(1));
    int ei = atom_pow(BASE_EI, 0, &angle), ta = atom_var(t);

    /* Negli atomi solo e^{i x}; g è il massimo comun divisore degli
     * esponenti, e parity[side] la parità comune di e/g sopra (0) e sotto
     * (1), oppure 2 se non sono tutti uguali. */
    __int128 top = 0, bottom = 1;
    for (int side = 0; side < 2; side++) {
        Poly p = side ? value.den : value.num;
        for (int i = 0; i < p.count; i++) {
            Frac e;
            if (!trig_exponent(&p.term[i], ei, &e)) return 0;
            top = gcd128(top, e.num);
            bottom = bottom / gcd128(bottom, e.den) * e.den;
            if (bottom > MAX_POWER) return 0;
        }
    }
    if (top == 0) return 0;
    Frac g = frac_make(top, bottom);
    int parity[2] = {-1, -1};
    for (int side = 0; side < 2; side++) {
        Poly p = side ? value.den : value.num;
        for (int i = 0; i < p.count; i++) {
            int odd = (int)(trig_power(&p.term[i], ei, g, 0, 0) % 2 != 0);
            parity[side] = parity[side] < 0 || parity[side] == odd ? odd : 2;
        }
    }
    int bioche = parity[0] == parity[1] && parity[0] < 2, odd = bioche ? parity[0] : 0;
    Frac theta = bioche ? frac_mul(g, frac_int(2)) : g;

    /* M, il più grande |k|; poi i due polinomi in t. */
    long long big = 0;
    for (int side = 0; side < 2; side++) {
        Poly p = side ? value.den : value.num;
        for (int i = 0; i < p.count; i++) {
            long long k = trig_power(&p.term[i], ei, g, bioche, odd);
            if (k > big) big = k;
            if (-k > big) big = -k;
        }
    }
    if (big > MAX_QPOLY / 4 - 1) return 0;
    Poly above = cayley_poly(value.num, ei, g, bioche, odd, big, ta), below = cayley_poly(value.den, ei, g, bioche, odd, big, ta);

    /* Reali: sopra e sotto per il coniugato del denominatore. */
    Poly conjugate = poly_conjugate(below);
    above = poly_mul(above, conjugate);
    below = poly_mul(below, conjugate);
    QPoly n, d;
    if (failure || !qpoly_from(above, ta, &n) || !qpoly_from(below, ta, &d) || d.degree < 0) { failure = NULL; return 0; }

    /* dx = 2 dt / (theta (1 + t^2)), con theta il coefficiente di x. */
    QPoly unit_circle = qpoly_zero();
    unit_circle.c[0] = unit_circle.c[2] = frac_int(1);
    unit_circle.degree = 2;
    n = qpoly_scale(n, frac_int(2));
    d = qpoly_mul(qpoly_scale(d, theta), unit_circle);
    char inner[ANSWER_BYTES] = "";
    if (failure || !rational_any(n, d, t, inner, sizeof inner, depth + 1)) { failure = NULL; return 0; }

    /* t = tan(theta x / 2). */
    Frac half = frac_div(theta, frac_int(2));
    Node *argument = letter_node(x);
    if (half.num != 1) argument = node_new(N_MUL, node_num(half.num), argument);
    if (half.den != 1) argument = node_new(N_DIV, argument, node_num(half.den));
    static char label[128];
    char written[64];
    if (!substitute_back(inner, t, node_call(FN_TAN, argument, NULL), text, size) || !node_latex(argument, written, sizeof written)) return 0;
    snprintf(label, sizeof label, "con la sostituzione t = \\tan\\left(%s\\right)", written);
    primitive_method = label;
    return 1;
}

/* 30c-1. Una costante: la primitiva di c è c x. */
static int constant_method(const Node *f, int x, int depth, char *text, size_t size) {
    (void)depth;
    if (node_has_variable(f, x)) return 0;
    primitive_method = "per linearità";
    if (f->kind == N_NUM && f->value == 1) return node_latex(letter_node(x), text, size);
    return node_latex(node_new(N_MUL, (Node *)f, letter_node(x)), text, size);
}

/* 30c-2. Un segno o un fattore senza x si portano fuori dall'integrale. */
static int factor_method(const Node *f, int x, int depth, char *text, size_t size) {
    char inner[ANSWER_BYTES];
    const Node *inside = NULL, *constant = NULL;
    if (f->kind == N_NEG) inside = f->a, constant = node_num(-1);
    else if (f->kind == N_MUL && !node_has_variable(f->a, x)) inside = f->b, constant = f->a;
    else if (f->kind == N_MUL && !node_has_variable(f->b, x)) inside = f->a, constant = f->b;
    else if (f->kind == N_DIV && !node_has_variable(f->b, x)) inside = f->a, constant = node_new(N_DIV, node_num(1), f->b);
    Node *g;
    if (!inside || !primitive_text(inside, x, depth, inner, sizeof inner) || !(g = text_tree(inner))) return 0;
    const char *method = primitive_method;
    if (!node_latex(node_new(N_MUL, (Node *)constant, g), text, size)) return 0;
    primitive_method = method;
    return 1;
}

/* 30c-8. Una somma, un termine alla volta. */
static int sum_method(const Node *f, int x, int depth, char *text, size_t size) {
    char inner[ANSWER_BYTES], other[ANSWER_BYTES];
    Node *g, *h;
    if (f->kind != N_ADD && f->kind != N_SUB) return 0;
    if (!primitive_text(f->a, x, depth, inner, sizeof inner) || !(g = text_tree(inner))) return 0;
    if (!primitive_text(f->b, x, depth, other, sizeof other) || !(h = text_tree(other))) return 0;
    primitive_method = "per linearità";
    return node_latex(node_new(f->kind, g, h), text, size);
}

/* I metodi della ricerca, nell'ordine in cui si provano (vedi la testa di
 * 30c): le funzioni razionali e i polinomi per esponenziali vengono prima
 * della linearità, perché assorbono da sé i fattori numerici e danno
 * primitive più corte.
 *
 * Warning: se aggiungi un metodo, aggiungilo anche all'elenco in testa a 30c
 * e al commento di design del capitolo. */
static int (*const primitive_methods[])(const Node *, int, int, char *, size_t) = {
    constant_method, rational_method, exponential_method, factor_method, parts_method,
    substitution_method, root_method, exponential_substitution, trig_method, sum_method,
};

/* Quante chiamate a primitive_text() restano per l'enunciato in corso. Ogni
 * metodo può chiamarla su altre funzioni, e senza un tetto i tentativi
 * crescerebbero come una potenza della profondità: finito il conto, la
 * ricerca si arrende. */
static int primitive_budget;

/* 30c. Scrive in text, di size byte, una primitiva di f nella variabile x,
 * provando i metodi di primitive_methods[] uno dopo l'altro. Ritorna 1 se
 * uno riesce. Ciò che scrive non è ancora verificato.
 *
 * Ciò che un tentativo lascia nell'arena e nella tabella degli atomi si
 * toglie prima del successivo, e anche alla fine: il risultato è un testo,
 * che non dipende da nessuno dei due. Gli atomi sono al più MAX_ATOMS, e i
 * tentativi abbandonati li esaurirebbero. */
static int primitive_text(const Node *f, int x, int depth, char *text, size_t size) {
    text[0] = 0;
    if (depth > MAX_PRIMITIVE_DEPTH || failure || primitive_budget <= 0) return 0;
    primitive_budget--;
    Scratch mark = scratch_mark();
    int found = 0;
    for (size_t i = 0; i < sizeof primitive_methods / sizeof *primitive_methods && !found; i++) {
        found = primitive_methods[i](f, x, depth, text, size);
        if (!found) text[0] = 0;
        failure = NULL;
        scratch_drop(mark);
    }
    return found;
}

/* 30i. GLI INTEGRALI DEFINITI
 *
 * Le ipotesi del teorema fondamentale (in testa al capitolo) si controllano
 * con gli intervalli del capitolo 24. [a, b] si divide in RIEMANN_PIECES
 * parti uguali, e su ognuna, I, si calcola la serie di Taylor di f fino al
 * secondo ordine con gli intervalli (27h), su tutto I in una volta. Se il
 * calcolo riesce, ogni operazione è stata fatta dentro il suo dominio per
 * ogni x di I: nessun denominatore si annulla, ogni logaritmo ha l'argomento
 * positivo, ogni radice il radicando positivo. Le funzioni elementari sono
 * analitiche dove sono definite così, quindi f lo è in un intorno di ogni
 * punto di I. Dove il calcolo non riesce la parte si dimezza, fino a
 * RIEMANN_SPLITS volte. Lo stesso per F.
 *
 * Perché gli intervalli e non la tabella dei segni (18p). Il risultato è lo
 * stesso, "non si annulla su [a, b]", ma qui gli estremi sono spesso numeri
 * come pi/2, e le funzioni seni e coseni ristretti a un intervallo, che la
 * tabella tratta solo in casi particolari (18p-14). Con gli intervalli il
 * metodo è uno solo per ogni funzione, ed è completo per ciò che serve: se f
 * è continua su [a, b] con ogni sua parte lontana dai bordi del proprio
 * dominio, per compattezza ne è lontana di una quantità positiva, e
 * dimezzando abbastanza gli intervalli la vedono. Se il calcolo non riesce
 * (uno zero proprio in un estremo, un integrale improprio) l'integrale passa
 * a 30k, che lo tratta come improprio, mai un sì sbagliato: \sqrt{x} su
 * [0, 1] è continua, ma in 0 non è analitica, e qui non la si accetta; come
 * integrale improprio su (0, 1) sì, con lo stesso valore.
 *
 * L'INVOLUCRO DI RIEMANN, il controllo indipendente
 *
 * Su ogni parte I di ampiezza w, con punto medio m:
 *
 *   - l'integrale di f su I sta tra w min f e w max f, cioè in w f(I), e
 *     f(I) è chiuso nell'intervallo della serie al grado 0;
 *   - per la formula di Taylor con il resto di Lagrange,
 *     f(x) = f(m) + f'(m)(x - m) + f''(xi)/2 (x - m)^2 con xi in I; il
 *     termine di primo grado ha integrale zero su I, e (x - m)^2 ha
 *     integrale w^3/12. Quindi l'integrale sta in w f(m) + C w^3/12, con
 *     C l'intervallo del coefficiente di grado 2 della serie su I.
 *
 * Tutte e due le stime sono garantite (il valore vero sta di sicuro
 * dentro), quindi anche la loro intersezione; la somma sulle parti chiude
 * l'integrale. Se è troppo larga si ricomincia con quattro volte tante
 * parti. Non usa F, né le regole di derivazione, né i conti esatti: per
 * questo può controllare F(b) - F(a), e da sola basta a dire FALSO quando il
 * valore scritto ne è di sicuro fuori. */

/* L'esito dei conti con gli intervalli su [a, b]. */
typedef struct {
    int defined;     /* 1 se f, e F se data, sono analitiche su tutto [a, b] */
    int broken;      /* 1 se due stime garantite non si toccano: un errore del programma */
    Range integral;  /* contiene l'integrale di f da a a b, se defined */
} Enclosure;

/* Aggiunge a e->integral l'integrale di f sulla parte da p a q, di ampiezza
 * width (gli estremi e l'ampiezza sono intervalli che contengono i numeri
 * veri), dimezzandola fino a splits volte dove il calcolo non riesce. f e F
 * sono già passati da sample_tree(). */
static void enclose_piece(Enclosure *e, const Node *f, const Node *F, int x, Range p, Range q, Range width, int splits) {
    Range hull = {p.low, q.high}, two = range_ratio(2, 1);
    int undefined = 0;
    Range values = node_range(f, x, hull, &undefined);
    if (!range_known(values) || (F && !range_known(sample_value(F, x, hull)))) {
        Range middle = range_div(range_add(p, q), two), half = range_div(width, two);
        if (splits == 0 || !range_known(middle)) { e->defined = 0; return; }
        enclose_piece(e, f, F, x, p, middle, half, splits - 1);
        if (e->defined) enclose_piece(e, f, F, x, middle, q, half, splits - 1);
        return;
    }

    /* Le due stime, e la loro intersezione. La seconda vuole f due volte
     * derivabile su tutta la parte: c'è solo dove la serie si calcola. */
    Jet series = jet_eval(f, x, hull, 2);
    Range plain = range_mul(width, values);
    Range cube = range_div(range_mul(range_mul(width, width), width), range_ratio(12, 1));
    Range sharp = range_add(range_mul(width, sample_value(f, x, range_div(range_add(p, q), two))), range_mul(series.c[2], cube));
    Range piece = plain;
    if (range_known(sharp)) {
        piece.low = plain.low > sharp.low ? plain.low : sharp.low;
        piece.high = plain.high < sharp.high ? plain.high : sharp.high;
        if (piece.low > piece.high) { e->broken = 1; e->defined = 0; return; }
    }
    e->integral = range_add(e->integral, piece);
}

/* Ritorna l'involucro dell'integrale di f da a a b, con a < b, e controlla
 * che f e F (se non è NULL) siano analitiche su [a, b]: vedi la testa di
 * 30i. Le parti sono RIEMANN_PIECES, e quattro volte tante finché
 * l'involucro è più largo di 10^-9 volte (1 + |integrale|), fino a most. */
static Enclosure riemann_enclosure(const Node *f, const Node *F, int x, Range a, Range b, long long most) {
    Enclosure e = {1, 0, {0, 0}};
    for (long long pieces = RIEMANN_PIECES; pieces <= most; pieces *= 4) {
        Range span = range_sub(b, a), width = range_div(span, range_ratio(pieces, 1));
        e = (Enclosure){1, 0, {0, 0}};
        for (long long k = 0; k < pieces && e.defined; k++) {
            Range p = range_add(a, range_mul(span, range_ratio(k, pieces))), q = range_add(a, range_mul(span, range_ratio(k + 1, pieces)));
            enclose_piece(&e, f, F, x, p, q, width, RIEMANN_SPLITS);
        }
        if (!e.defined || !range_known(e.integral)) { e.defined = 0; return e; }
        double size = e.integral.high > -e.integral.low ? e.integral.high : -e.integral.low;
        if (e.integral.high - e.integral.low <= 1e-9 * (1 + size)) break;
    }
    return e;
}

/* 30i-1. I VALORI ESATTI NEGLI ESTREMI
 *
 * F(b) - F(a) si calcola con i conti esatti, legando x al valore esatto
 * dell'estremo; per gli angoli noti si scrivono prima i valori esatti di
 * seni, coseni e arcotangenti (exact_angles()). */

/* I valori esatti di seno e coseno negli angoli k pi/12, per k da 0 a 6
 * (da 0 a 90 gradi), che i libri ricavano dai triangoli con gli angoli di
 * 30, 45 e 60 gradi, e da quelli con le formule di bisezione:
 * cos(pi/12) = sqrt((1 + cos(pi/6))/2) = (sqrt(6) + sqrt(2))/4. */
static const char *const angle_sine[7] = {"0", "\\frac{\\sqrt{6} - \\sqrt{2}}{4}", "\\frac{1}{2}", "\\frac{\\sqrt{2}}{2}",
                                          "\\frac{\\sqrt{3}}{2}", "\\frac{\\sqrt{6} + \\sqrt{2}}{4}", "1"};

/* Ritorna l'albero del valore esatto di sin (cosine = 0) o di cos
 * (cosine = 1) nell'angolo k pi/12, per ogni intero k: con
 * sin(pi - u) = sin u, sin(u + pi) = -sin u e cos u = sin(pi/2 - u). */
static Node *angle_value(long long k, int cosine) {
    if (cosine) k = 6 - k;
    k %= 24;
    if (k < 0) k += 24;
    int negative = k >= 12;
    if (negative) k -= 12;
    if (k > 6) k = 12 - k;
    Node *v = text_tree(angle_sine[k]);
    return negative ? node_new(N_NEG, v, NULL) : v;
}

/* Le tangenti degli angoli k pi/12, per k da 1 a 5: tan(pi/12) = 2 - sqrt(3)
 * e tan(5 pi/12) = 2 + sqrt(3) vengono dalla formula di bisezione,
 * tan(u/2) = (1 - cos u)/sin u. */
static const char *const angle_tangent[6] = {"0", "2 - \\sqrt{3}", "\\frac{\\sqrt{3}}{3}", "1", "\\sqrt{3}", "2 + \\sqrt{3}"};

/* Ritorna una copia di tree in cui ogni seno, coseno, tangente o cotangente
 * il cui argomento, con x legata a value, vale k pi/12 con k intero, è
 * scritto con il suo valore esatto (angle_value()), e ogni arcotangente di
 * una delle tangenti di angle_tangent[] (o della sua opposta) è scritta come
 * l'angolo. Perché: nei conti esatti sin(pi/6) è una combinazione
 * dell'atomo e^{i pi/6}, che il test di annullamento non sa ridurre a 1/2
 * (gli mancano le relazioni tra le radici dell'unità), e arctan(sqrt(3)/3) è
 * un atomo che la sua regola 12c non sa confrontare con pi/6. */
static Node *exact_angles(const Node *tree, int x, Rat value) {
    if (!tree) return NULL;
    Node *copy = node_new(tree->kind, exact_angles(tree->a, x, value), exact_angles(tree->b, x, value));
    copy->value = tree->value;
    copy->name = tree->name;
    copy->op = tree->op;
    copy->c = tree->c;
    int trig = tree->kind == N_CALL && (tree->op == FN_SIN || tree->op == FN_COS || tree->op == FN_TAN || tree->op == FN_COT);
    if (!trig && !(tree->kind == N_CALL && tree->op == FN_ARCTAN)) return copy;
    env_count = 0;
    env_push(x, value);
    Rat angle = eval(tree->a);
    env_count = 0;
    if (failure) { failure = NULL; return copy; }

    /* L'arcotangente: l'argomento confrontato con le tangenti note. */
    if (!trig) {
        for (int k = 1; k <= 5; k++) {
            Rat tangent = eval(text_tree(angle_tangent[k]));
            Node *turn = node_new(N_DIV, node_new(N_MUL, node_num(k), letter_node(VAR_PI)), node_num(12));
            if (!failure && poly_vanishes(rat_add(angle, tangent, 1).num)) return turn;
            if (!failure && poly_vanishes(rat_add(angle, tangent, 0).num)) return node_new(N_NEG, turn, NULL);
            failure = NULL;
        }
        return copy;
    }

    /* L'argomento di seno e coseno deve essere q pi, con 12 q intero. */
    Num q;
    int pi = atom_var(VAR_PI);
    if (!poly_is_one(angle.den)) return copy;
    if (angle.num.count == 0) q = num_int(0);
    else if (angle.num.count != 1 || angle.num.term[0].mono.count != 1 || angle.num.term[0].mono.factor[0].atom != pi ||
             frac_cmp(angle.num.term[0].mono.factor[0].exp, frac_int(1)) != 0) return copy;
    else q = angle.num.term[0].coef;
    Frac k = frac_mul(q.re, frac_int(12));
    if (q.im.num != 0 || k.den != 1) return copy;
    Node *sine = angle_value(k.num, 0), *cosine = angle_value(k.num, 1);
    if (tree->op == FN_SIN) return sine;
    if (tree->op == FN_COS) return cosine;
    return tree->op == FN_TAN ? node_new(N_DIV, sine, cosine) : node_new(N_DIV, cosine, sine);
}

/* Ritorna il valore esatto di tree con x legata a value, con i seni e i
 * coseni degli angoli noti già scritti con i loro valori (exact_angles()). */
static Rat value_at(const Node *tree, int x, Rat value) {
    Node *known = exact_angles(tree, x, value);
    env_count = 0;
    env_push(x, value);
    Rat r = eval(known);
    env_count = 0;
    return r;
}

/* Ritorna p senza i fattori 1^M, che valgono 1: nascono da power() (vedi
 * exponential_method()) e scritti si leggerebbero \left(1\right)^{-10\,\pi}. */
static Poly poly_without_ones(Poly p) {
    Poly r = poly_const(num_int(0));
    for (int i = 0; i < p.count && !failure; i++) {
        Term t = p.term[i];
        Mono kept;
        kept.count = 0;
        for (int k = 0; k < t.mono.count; k++) {
            const Atom *a = &atoms[t.mono.factor[k].atom];
            if (a->kind != ATOM_POW || a->base != BASE_POLY || !poly_is_one(base_polys[a->id])) kept.factor[kept.count++] = t.mono.factor[k];
        }
        t.mono = kept;
        r = poly_add(r, poly_term(t), 0);
    }
    return r;
}

/* Mette in text, di size byte, il numero r scritto da put_rat() (capitolo
 * 13), senza i fattori 1^M; ritorna 0 se non ci sta o non si scrive. */
static int rat_latex(Rat r, char *text, size_t size) {
    r = (Rat){poly_without_ones(r.num), poly_without_ones(r.den)};
    size_t start = proof_length;
    unwritable = 0;
    put_rat(r);
    size_t length = proof_length - start;
    int fits = !unwritable && proof_length < PROOF_BYTES - 1 && length < size;
    if (fits) {
        memcpy(text, proof_text + start, length);
        text[length] = 0;
    }
    proof_cut(start);
    return fits;
}

/* Aggiunge alla dimostrazione l'intervallo r come [low, high], con abbastanza
 * cifre. */
static void put_range(Range r) { proof_add("\\left[%.16g, %.16g\\right]", r.low, r.high); }

/* 30i-2. I VALORI ASSOLUTI: SPEZZARE L'INTERVALLO
 *
 * |u| non è derivabile dove u si annulla, e una primitiva di |x - 1| non è
 * una formula sola. Ma tra due zeri consecutivi di u il segno di u è
 * costante (u è continua), e lì |u| = u oppure |u| = -u: l'integrale su
 * [a, b] è la somma degli integrali sulle parti, ognuno con una funzione
 * senza valore assoluto, a cui si applica il teorema fondamentale.
 *
 * Gli zeri di u si cercano dove si sa: la radice di u se è di primo grado
 * in x (anche con pi tra i coefficienti, come 6x - pi), le radici razionali
 * se è un polinomio, i multipli di pi/12 se contiene seni e coseni. La
 * ricerca è euristica; ciò che si usa no:
 *
 *   - ogni zero z è uno zero esatto: u(z) = 0 con il test di annullamento;
 *   - tra due punti consecutivi u non si annulla: vicino a uno zero z la
 *     serie di Taylor di u su [z, z + delta] (con gli intervalli) dà u' di
 *     segno certo, quindi u è monotona e si annulla solo in z; nel resto
 *     della parte gli intervalli danno a u un segno certo, lo stesso.
 *
 * Se uno zero sfugge alla ricerca il secondo controllo fallisce, e il
 * verdetto è NON DIMOSTRATO. */

/* Una parte [p, q] dell'intervallo di integrazione, con la funzione che
 * vi coincide con f: f stessa, o f con il valore assoluto tolto. */
typedef struct {
    Rat p, q;          /* gli estremi, esatti */
    Range low, high;   /* gli stessi, con gli intervalli */
    Node *f;           /* la funzione da integrare sulla parte */
} Stretch;

/* Raccoglie in list[] (al più MAX_INNER) i valori assoluti di tree che non
 * sono dentro un logaritmo: quelli lo derive() li attraversa (30a). */
static void collect_abs(const Node *tree, const Node **list, int *count) {
    if (!tree || (tree->kind == N_CALL && (tree->op == FN_LN || tree->op == FN_LOG))) return;
    if (tree->kind == N_CALL && tree->op == FN_ABS && *count < MAX_INNER) list[(*count)++] = tree;
    collect_abs(tree->a, list, count);
    collect_abs(tree->b, list, count);
}

/* Ritorna l'intervallo che contiene il numero r, o "non so". */
static Range rat_range(Rat r) { return range_div(poly_range(r.num), poly_range(r.den)); }

/* Ritorna 1 se in tree compare un seno, un coseno, una tangente o una
 * cotangente. */
static int has_trig(const Node *tree) {
    if (!tree) return 0;
    if (tree->kind == N_CALL && (tree->op == FN_SIN || tree->op == FN_COS || tree->op == FN_TAN || tree->op == FN_COT)) return 1;
    return has_trig(tree->a) || has_trig(tree->b) || has_trig(tree->c);
}

/* Mette in *sign il segno di u, certo e lo stesso, su tutta la parte da lo a
 * hi (intervalli che contengono gli estremi veri), dividendola fino a splits
 * volte. Ritorna 0 se non lo trova. */
static int range_sign(const Node *u, int x, Range lo, Range hi, int splits, int *sign) {
    int undefined = 0, side;
    Range value = node_range(u, x, (Range){lo.low, hi.high}, &undefined);
    if (range_side(value, &side)) {
        if (*sign == 0) *sign = side;
        return side == *sign;
    }
    if (splits == 0) return 0;
    Range middle = range_div(range_add(lo, hi), range_ratio(2, 1));
    return range_known(middle) && range_sign(u, x, lo, middle, splits - 1, sign) && range_sign(u, x, middle, hi, splits - 1, sign);
}

/* Mette in *sign il segno di u sulla parte aperta da lo a hi, dove u vale
 * zero in lo se zero_low, in hi se zero_high: vedi la testa di 30i-2.
 * Ritorna 0 se non si riesce a stabilirlo. */
static int piece_sign(const Node *u, int x, Range lo, Range hi, int zero_low, int zero_high, int *sign) {
    Range width = range_sub(hi, lo);
    *sign = 0;
    for (int end = 0; end < 2; end++) {
        if (!(end ? zero_high : zero_low)) continue;
        int found = 0;
        for (int k = 2; k <= 24 && !found; k++) {
            Range delta = range_div(width, range_ratio((__int128)1 << k, 1));
            Range near = end ? (Range){range_sub(hi, delta).low, hi.high} : (Range){lo.low, range_add(lo, delta).high};
            Jet series = jet_eval(u, x, near, 1);
            int slope;
            if (!range_side(series.c[1], &slope)) continue;
            /* Crescente da uno zero a sinistra: positiva dopo; da uno zero a
             * destra: negativa prima. */
            int here = end ? -slope : slope;
            if (*sign && *sign != here) return 0;
            *sign = here;
            if (end) hi = range_sub(hi, delta); else lo = range_add(lo, delta);
            found = 1;
        }
        if (!found) return 0;
    }
    return range_sign(u, x, lo, hi, RIEMANN_SPLITS, sign);
}

/* 30i-2. Divide [p, q] (esatti e con gli intervalli) nelle parti in cui il
 * valore assoluto di f ha un segno fisso, e le mette in piece[], con f senza
 * valore assoluto. Ritorna il numero di parti, 1 se f non ha valori
 * assoluti, 0 se non riesce. */
static int split_pieces(Node *f, int x, Rat p, Rat q, Range low, Range high, Stretch *piece) {
    const Node *bars[MAX_INNER];
    int count = 0;
    collect_abs(f, bars, &count);
    piece[0] = (Stretch){p, q, low, high, f};
    if (count == 0) return 1;
    for (int i = 1; i < count; i++)
        if (!node_equal(bars[i]->a, bars[0]->a)) return 0;
    const Node *u = sample_tree(bars[0]->a, x, 0, 0);

    /* I candidati zeri, poi solo quelli esatti e dentro (p, q). */
    Rat zero[MAX_PIECES];
    Range where[MAX_PIECES];
    int zeros = 0, candidates = 0, xa = atom_var(x);
    Rat candidate[MAX_INNER];
    env_count = 0;
    Rat value = eval(u);
    Poly num, den, part[2];
    if (!failure && rat_polynomials(value, &num, &den) && poly_split(num, xa, part, 1) == 1 && part[1].count)
        candidate[candidates++] = rat_div((Rat){poly_add(poly_const(num_int(0)), part[0], 1), poly_const(num_int(1))}, (Rat){part[1], poly_const(num_int(1))});
    failure = NULL;
    QPoly polynomial;
    if (rat_polynomials(value, &num, &den) && qpoly_from(num, xa, &polynomial) && polynomial.degree >= 2 && polynomial.degree <= MAX_UNIVARIATE) {
        Frac content, root[MAX_UNIVARIATE + 2];
        QPoly whole = qpoly_primitive(polynomial, &content);
        long long c[MAX_UNIVARIATE + 1];
        for (int i = 0; i <= whole.degree; i++) c[i] = whole.c[i].num;
        int roots = failure ? -1 : rational_roots(c, whole.degree, root);
        for (int i = 0; i < roots && candidates < MAX_INNER; i++) candidate[candidates++] = rat_frac(root[i]);
    }
    failure = NULL;
    if (has_trig(u)) {
        Range pi = range_pi();
        for (long long k = (long long)(low.low * 12 / pi.high) - 1; k <= (long long)(high.high * 12 / pi.low) + 1 && candidates < MAX_INNER; k++)
            candidate[candidates++] = rat_mul(rat_frac(frac_make(k, 12)), rat_atom(atom_var(VAR_PI)));
    }
    for (int i = 0; i < candidates; i++) {
        Range r = rat_range(candidate[i]);
        int left, right;
        if (!range_side(range_sub(r, low), &left) || left < 0 || !range_side(range_sub(high, r), &right) || right < 0) continue;
        Rat at = value_at(u, x, candidate[i]);
        if (failure || !poly_vanishes(at.num)) { failure = NULL; continue; }
        int seen = 0;
        for (int j = 0; j < zeros && !seen; j++) seen = poly_vanishes(rat_add(zero[j], candidate[i], 1).num);
        if (seen) continue;
        if (zeros == MAX_PIECES - 1) return 0;
        /* In ordine, inserendo: due zeri diversi hanno intervalli separati
         * (altrimenti non si sa quale viene prima, e si rinuncia). */
        int k = zeros;
        while (k > 0 && range_side(range_sub(where[k - 1], r), &left) && left > 0) { zero[k] = zero[k - 1]; where[k] = where[k - 1]; k--; }
        if (k > 0 && !(range_side(range_sub(r, where[k - 1]), &left) && left > 0)) return 0;
        zero[k] = candidate[i];
        where[k] = r;
        zeros++;
    }

    /* Le parti, il segno di u su ognuna, e f con |u| = u o -u. Anche gli
     * estremi a e b possono essere zeri di u, come 0 per sin x. */
    Rat at_start = value_at(u, x, p), at_end = value_at(u, x, q);
    int zero_start = !failure && poly_vanishes(at_start.num), zero_end = !failure && poly_vanishes(at_end.num);
    failure = NULL;
    Node *plus = (Node *)bars[0]->a, *minus = node_new(N_NEG, (Node *)bars[0]->a, NULL);
    for (int i = 0; i <= zeros; i++) {
        Rat from = i ? zero[i - 1] : p, to = i < zeros ? zero[i] : q;
        Range lo = i ? where[i - 1] : low, hi = i < zeros ? where[i] : high;
        int sign;
        if (!piece_sign(u, x, lo, hi, i > 0 || zero_start, i < zeros || zero_end, &sign)) return 0;
        Node *replacement[MAX_INNER];
        for (int j = 0; j < count; j++) replacement[j] = sign > 0 ? plus : minus;
        piece[i] = (Stretch){from, to, lo, hi, replace_listed(f, bars, replacement, count)};
    }
    return zeros + 1;
}

/* 30j. IL VERDETTO
 *
 * prove_integral() legge l'enunciato (9j), controlla che vi compaiano solo
 * la variabile, e e pi greco, e sceglie la strada: verificare una primitiva
 * (30a, 30b), cercarne una (30c-30h) e verificarla, o calcolare un integrale
 * definito (30i). Le dimostrazioni scritte sono in inglese, come le altre. */

/* Ritorna 1 se in tree compaiono solo la lettera x, e e pi greco (x = 0:
 * solo e e pi greco), e niente somme, successioni o applicazioni. */
static int only_letters(const Node *tree, int x) {
    if (!tree) return 1;
    if (tree->kind == N_VAR && tree->name != x && tree->name != 'e' && tree->name != VAR_PI) return 0;
    if (tree->kind == N_BIGOP || tree->kind == N_SEQ || tree->kind == N_APPLY) return 0;
    return only_letters(tree->a, x) && only_letters(tree->b, x) && only_letters(tree->c, x);
}

/* Scrive nella dimostrazione la verifica di F, già passata da
 * primitive_check(): la derivata con le regole, se non è troppo lunga, e i
 * punti in cui i numeri hanno confermato. Ritorna 0 se la derivata scritta,
 * riletta, non concorda con f nel punto di conferma: un errore nello
 * scriverla. */
static int put_primitive_check(const Node *f, const Node *F, int x, const PrimitiveCheck *check) {
    char written[ANSWER_BYTES];
    proof_add("By the rules of differentiation, ");
    int sound = 1;
    if (node_latex(check->derivative, written, sizeof written) && strlen(written) < 1500) {
        proof_add("$\\frac{d}{d%c}\\left(", x);
        put_node(F, 0);
        proof_add("\\right) = %s$, and the difference from the integrand reduces to $0$ by exact algebra", written);

        /* La derivata scritta, riletta, contro f nel punto di conferma. */
        Node *back = text_tree(written);
        Range at = range_ratio(check->point.num, check->point.den);
        sound = back && numbers_agree(sample_value(sample_tree(back, x, 0, 0), x, at), sample_value(sample_tree(f, x, 0, 0), x, at)) > 0;
    } else {
        proof_add("the derivative of the right side, too long to write here, minus the integrand reduces to $0$ by exact algebra");
    }
    proof_add(". So the derivative of $");
    put_node(F, 0);
    proof_add("$ is the integrand on every open interval where both are defined, and there every antiderivative is this function plus a "
              "constant (two antiderivatives on an interval differ by a constant, by the mean value theorem). \\emph{Check with numbers}: at $%c = "
              "\\frac{%lld}{%lld}$ the derivative read from the Taylor series of the antiderivative, computed with interval arithmetic, agrees "
              "with the integrand.", x, check->point.num, check->point.den);
    if (check->outside) proof_add(" The antiderivative is not defined everywhere the integrand is: for example at $%c = \\frac{%lld}{%lld}$.", x, check->where.num, check->where.den);
    proof_add("\n");
    return sound;
}

/* Il verdetto di una verifica, con il motivo e il punto. */
static Verdict primitive_verdict(const PrimitiveCheck *check, int x) {
    static char where[96];
    Verdict verdict = {check->outcome, 0, 0, 0, check->reason, NULL, NULL, NULL, NULL, NULL};
    if (check->outcome == REFUTED) {
        snprintf(where, sizeof where, "%c = %lld/%lld, dove la derivata della primitiva non è la funzione integranda", x, check->point.num, check->point.den);
        verdict.detail = where;
    }
    return verdict;
}

/* Cerca una primitiva di f in x, la scrive in text (di size byte), la
 * rilegge e la verifica: mette in *check l'esito e ritorna l'albero riletto,
 * o NULL se non la trova o non è verificata. Una primitiva trovata che la
 * verifica smentisce è un errore del programma: unjustified_steps sale. */
static Node *found_primitive(const Node *f, int x, char *text, size_t size, PrimitiveCheck *check) {
    primitive_method = NULL;
    primitive_budget = MAX_PRIMITIVE_CALLS;
    *check = (PrimitiveCheck){NOT_PROVED, "non trovo una primitiva con i metodi del programma", {0, 1}, 0, {0, 1}, NULL};
    if (!primitive_text(f, x, 0, text, size)) { failure = NULL; return NULL; }
    Node *F = text_tree(text);
    if (!F) { unjustified_steps++; check->reason = "la primitiva trovata non si rilegge"; return NULL; }
    *check = primitive_check(f, F, x);
    if (check->outcome == REFUTED) {
        unjustified_steps++;
        check->outcome = NOT_PROVED;
        check->reason = "la primitiva trovata è smentita dalla verifica: un errore del programma";
    }
    if (check->outcome != PROVED) {
        static char reason[256];
        snprintf(reason, sizeof reason, "la primitiva trovata non è verificata: %s", check->reason ? check->reason : "");
        check->reason = reason;
        check->outcome = NOT_PROVED;
        return NULL;
    }
    return F;
}

/* 30j. Il verdetto su un integrale definito di f da lower a upper: se claim
 * non è NULL, "l'integrale vale claim"; altrimenti la richiesta del suo
 * valore. *improper diventa 1 se gli intervalli non mostrano che f è
 * continua su tutto [a, b]: allora l'integrale va trattato come improprio
 * (30k), e il verdetto ritornato non conta. */
static Verdict prove_definite(const Node *f, const Node *lower, const Node *upper, const Node *claim, int x, int *improper) {
    static char answer[ANSWER_BYTES], detail[ANSWER_BYTES + 128];
    char primitive[ANSWER_BYTES];
    Verdict verdict = {NOT_PROVED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};

    /* Gli estremi, esatti e con gli intervalli, nell'ordine. */
    Node *fs = sample_tree(f, x, 0, 0);
    Range a = sample_value(sample_tree(lower, x, 0, 0), x, range_none()), b = sample_value(sample_tree(upper, x, 0, 0), x, range_none());
    int side;
    if (!range_side(range_sub(b, a), &side)) { verdict.reason = "non riesco a stabilire quale dei due estremi è il più piccolo"; return verdict; }
    int flip = side < 0;
    Range low = flip ? b : a, high = flip ? a : b;
    Range claimed = claim ? sample_value(sample_tree(claim, x, 0, 0), x, range_none()) : range_none();

    /* L'involucro di Riemann, senza F: basta per il FALSO. */
    Enclosure plain = riemann_enclosure(fs, NULL, x, low, high, 16 * RIEMANN_PIECES);
    if (plain.broken) { unjustified_steps++; verdict.reason = "due stime garantite dell'integrale non si toccano: un errore del programma"; return verdict; }
    if (!plain.defined) {
        verdict.reason = "non riesco a stabilire che la funzione integranda sia continua su tutto l'intervallo di integrazione";
        *improper = 1;
        return verdict;
    }
    Range integral = flip ? range_neg(plain.integral) : plain.integral;
    if (claim && range_known(claimed) && (claimed.high < integral.low || claimed.low > integral.high)) {
        snprintf(detail, sizeof detail, "il valore scritto è fuori da [%.16g, %.16g], che contiene l'integrale", integral.low, integral.high);
        proof_add("\\textbf{Proof that the statement is false.} The integrand is continuous on the interval of integration: interval arithmetic on "
                  "each of its pieces keeps every denominator away from zero and every logarithm and root inside its domain. Riemann sums with interval "
                  "arithmetic then enclose the integral in $");
        put_range(integral);
        proof_add("$, and the stated value lies outside, in $");
        put_range(claimed);
        proof_add("$.");
        verdict.outcome = REFUTED;
        verdict.detail = detail;
        verdict.proof = proof_text;
        return verdict;
    }

    /* Le parti (30i-2), ognuna con una primitiva verificata, e la somma dei
     * F(q) - F(p): con i conti esatti, e con gli intervalli per il
     * controllo. Gli estremi esatti vanno nell'ordine di low e high. */
    env_count = 0;
    Rat from = eval(flip ? upper : lower);
    Rat to = eval(flip ? lower : upper);
    if (failure) { verdict.reason = failure; failure = NULL; return verdict; }
    Stretch piece[MAX_PIECES];
    Node *F[MAX_PIECES];
    PrimitiveCheck check[MAX_PIECES];
    int pieces = split_pieces((Node *)f, x, from, to, low, high, piece);
    failure = NULL;
    if (pieces == 0) { verdict.reason = "non riesco a dividere l'intervallo nelle parti in cui un valore assoluto ha segno costante"; return verdict; }
    Rat exact = rat_int(0);
    Range by_primitive = {0, 0};
    for (int i = 0; i < pieces; i++) {
        F[i] = found_primitive(piece[i].f, x, primitive, sizeof primitive, &check[i]);
        if (!F[i]) { verdict.reason = check[i].reason; return verdict; }
        Node *Fs = sample_tree(F[i], x, 0, 0);
        if (!riemann_enclosure(sample_tree(piece[i].f, x, 0, 0), Fs, x, piece[i].low, piece[i].high, 16 * RIEMANN_PIECES).defined) {
            verdict.reason = "la primitiva trovata non è definita su tutto l'intervallo di integrazione";
            *improper = pieces == 1;
            return verdict;
        }
        Rat at_end = value_at(F[i], x, piece[i].q);
        Rat at_start = value_at(F[i], x, piece[i].p);
        exact = rat_add(exact, rat_add(at_end, at_start, 1), 0);
        by_primitive = range_add(by_primitive, range_sub(sample_value(Fs, x, piece[i].high), sample_value(Fs, x, piece[i].low)));
        if (failure) { verdict.reason = failure; failure = NULL; return verdict; }
    }
    if (flip) {
        exact = rat_add(rat_int(0), exact, 1);
        by_primitive = range_neg(by_primitive);
    }

    /* Il controllo indipendente: la somma dei F(q) - F(p), con gli
     * intervalli, dentro l'involucro di Riemann. */
    if (!range_known(by_primitive) || by_primitive.high < integral.low || by_primitive.low > integral.high) {
        unjustified_steps++;
        verdict.reason = "F(b) - F(a) non sta nell'involucro di Riemann dell'integrale: un errore del programma";
        return verdict;
    }
    double size = integral.high > -integral.low ? integral.high : -integral.low;
    if (integral.high - integral.low > 1e-3 * (1 + size)) { verdict.reason = "le somme di Riemann con gli intervalli non sono abbastanza precise per il controllo"; return verdict; }

    /* Il valore: da confrontare con quello scritto, o da scrivere. */
    const char *value_text = NULL;
    const Node *value = claim;
    if (claim) {
        env_count = 0;
        Rat gap = rat_add(exact, eval(claim), 1);
        if (failure || !poly_vanishes(gap.num)) {
            failure = NULL;
            verdict.reason = "F(b) - F(a) e il valore scritto non si riducono allo stesso numero con i conti esatti";
            return verdict;
        }
    } else {
        /* Il numero, scritto e riletto come ogni risultato: semplificato
         * dai conti esatti se si sa scrivere, altrimenti F(b) - F(a) così
         * com'è. */
        Node *back = NULL;
        if (rat_latex(exact, answer, sizeof answer)) back = text_tree(answer);
        if (!back && pieces == 1 && node_latex(node_new(N_SUB, node_replace(F[0], x, (Node *)upper), node_replace(F[0], x, (Node *)lower)), answer, sizeof answer))
            back = text_tree(answer);
        if (!back) { verdict.reason = "non riesco a scrivere il valore dell'integrale"; return verdict; }
        env_count = 0;
        Rat gap = rat_add(exact, eval(back), 1);
        Range reread = sample_value(sample_tree(back, x, 0, 0), x, range_none());
        if (failure || !poly_vanishes(gap.num) || !range_known(reread) || reread.high < integral.low || reread.low > integral.high) {
            failure = NULL;
            unjustified_steps++;
            verdict.reason = "il valore scritto, riletto, non è quello calcolato";
            return verdict;
        }
        value_text = answer;
        value = back;
    }

    /* La dimostrazione: le parti, se sono più d'una, poi ogni primitiva. */
    proof_add("\\textbf{Proof.} By the fundamental theorem of calculus: if $f$ is continuous on $[p, q]$ and $F' = f$ on an open interval "
              "containing $[p, q]$, the integral from $p$ to $q$ is $F(q) - F(p)$.");
    if (pieces > 1)
        proof_add(" The absolute value in the integrand vanishes at %d point%s of the interval: each is an exact zero, and between two consecutive ones "
                  "its argument has a constant sign (monotone near each zero, by its derivative computed with interval arithmetic, and of certain sign "
                  "elsewhere). On each piece the absolute value is its argument or its opposite, and the integral is the sum over the pieces.",
                  pieces - 1, pieces > 2 ? "s" : "");
    for (int i = 0; i < pieces; i++) {
        proof_add(pieces > 1 ? "\n\nOn the piece number %d, " : " ", i + 1);
        proof_add("$F = ");
        put_node(F[i], 0);
        proof_add("$, found by the search for an antiderivative. ");
        if (!put_primitive_check(piece[i].f, F[i], x, &check[i])) {
            unjustified_steps++;
            verdict.reason = "la derivata scritta nella dimostrazione, riletta, non è confermata";
            return verdict;
        }
    }
    proof_add("Interval arithmetic on each part of the interval of integration keeps every denominator of the integrand and of the antiderivative "
              "away from zero, and every logarithm and root inside its domain: the antiderivative is analytic on a neighbourhood of every point "
              "of it, and the integrand continuous. Hence the integral is the sum of the $F(q) - F(p)$");
    if (value_text) proof_add(", that is $%s$", value_text);
    proof_add(". \\emph{Check with numbers}: Riemann sums with interval arithmetic, which use neither the antiderivatives nor exact algebra, "
              "enclose the integral in $");
    put_range(integral);
    proof_add("$, and the sum lies there. $\\Box$");
    verdict.proof = proof_text;
    verdict.reason = NULL;
    if (value_text) {
        verdict.outcome = SOLVED;
        verdict.method = "con il teorema fondamentale del calcolo";
        verdict.detail = value_text;
    } else {
        verdict.outcome = PROVED;
        verdict.method = "con il teorema fondamentale del calcolo, e l'involucro di Riemann come controllo";
    }

    /* 30cert. Il certificato di un integrale ha una primitiva sola: con le
     * parti di un valore assoluto (30i-2) manca. Il verificatore ricontrolla
     * F' = f, che f e F siano definite su tutto l'intervallo, e il valore. */
    if (pieces == 1) calculus_certify(&verdict, calculus_certificate("integral", x, NULL, F[0], f, lower, upper, value), NULL, x);
    else verdict.reason = "il certificato di un integrale ha una primitiva sola, e qui un valore assoluto divide l'intervallo in parti";
    return verdict;
}

/* 30k. GLI INTEGRALI IMPROPRI
 *
 * A che cosa serve. "\int_{1}^{+\infty} \frac{dx}{x^{2}} = 1",
 * "\int_{0}^{\pi/2} \tan x \, dx = +\infty", "\int_{0}^{1} \frac{dx}{\sqrt{x}}",
 * "\int_{1}^{+\infty} \sin^{2}\frac{1}{x} \, dx \in \mathbb{R}": un estremo
 * infinito, o una funzione che vicino a un estremo non è limitata.
 *
 * LA DEFINIZIONE
 *
 * Sia f continua sull'intervallo aperto (a, b), con a un numero o -\infty e b
 * un numero o +\infty. Per un c in (a, b) si guardano i due limiti
 *
 *     lim_{q -> b^-} \int_c^q f      e      lim_{p -> a^+} \int_p^c f.
 *
 * Se esistono finiti, l'integrale improprio converge e vale la loro somma;
 * cambiare c sposta un pezzo finito da un limite all'altro, e la somma non
 * cambia. Se uno è +\infty e l'altro finito o +\infty, l'integrale vale
 * +\infty (diverge); lo stesso per -\infty. Altrimenti (un limite che non
 * esiste, o +\infty da una parte e -\infty dall'altra) l'integrale non
 * converge e non vale un infinito. Se f non è definita in un punto c
 * interno, (a, b) si divide in c, e l'integrale converge se converge su
 * ogni parte. Se f è continua anche negli estremi, che sono numeri, la
 * definizione dà l'integrale di sempre (la funzione integrale è continua):
 * la estende, non la cambia. Per questo un integrale definito che gli
 * intervalli non sanno dire continuo su tutto [a, b] (30i) viene trattato
 * qui.
 *
 * IL TEOREMA E IL METODO (30k-1 ... 30k-4)
 *
 * Se F è derivabile su (a, b) con F' = f, per ogni [p, q] dentro (a, b) il
 * teorema fondamentale dà \int_p^q f = F(q) - F(p), e quindi l'integrale
 * improprio è lim_{x -> b^-} F(x) - lim_{x -> a^+} F(x), sui numeri reali
 * estesi, con le regole della definizione. Si controllano, ognuno con il
 * suo metodo:
 *
 *   30k-1. che f sia continua su (a, b), e F derivabile: domain_conditions()
 *          raccoglie le condizioni di esistenza di f, di F e della derivata
 *          di F scritta dalle regole (divisori diversi da zero, argomenti dei
 *          logaritmi positivi, radicandi non negativi, coseni diversi da zero
 *          sotto una tangente), e la tabella dei segni (18p), con le sue
 *          verifiche, decide l'enunciato "per ogni x con a < x < b valgono".
 *          Una funzione elementare è continua dove è definita; e dove la
 *          formula della derivata ha un valore F è derivabile e quella è la
 *          sua derivata (capitolo 27, "Dove valgono le formule"). Se la
 *          tabella trova un punto c in cui una condizione non vale,
 *          l'intervallo si divide in c e si ricomincia, fino a
 *          MAX_IMPROPER_PIECES parti;
 *   30k-2. che F' = f: primitive_check(), come per le primitive (30a, 30b);
 *   30k-3. i limiti di F agli estremi di ogni parte: il capitolo 29, con la
 *          scala delle crescite (29k) e i suoi controlli (29i, 29j), come
 *          richieste \lim_{x \to b^{-}} F, scritte e rilette;
 *   30k-4. il controllo indipendente, con i numeri: su intervalli compatti
 *          [p_k, q_k] che si allargano verso gli estremi (q_k = b - 2^{-k}
 *          (b - c), oppure c + 2^{k-1} se b = +\infty), l'involucro di
 *          Riemann di 30i chiude \int_{p_k}^{q_k} f senza usare F, e
 *          F(q_k) - F(p_k), calcolato con gli intervalli, deve starci dentro.
 *          Gli intervalli si fermano dove non sanno più calcolare f (un
 *          esponenziale che esce dai numeri della macchina vicino a
 *          +\infty); ma se su uno di essi f non si chiude pur calcolandosi
 *          nei suoi due estremi, lì dentro c'è forse un punto in cui f non è
 *          definita, sfuggito a 30k-1, e il controllo smentisce.
 *          Che cosa garantisce: che F sia una primitiva su ogni compatto
 *          guardato, per una strada che non usa né le regole di derivazione
 *          né i conti esatti; un F sbagliato, o una divisione sfuggita al
 *          primo controllo, lo fa uscire. Che cosa no: i limiti agli estremi,
 *          che un numero finito di intervalli non vede; quelli li ricontrolla
 *          29i, e la convergenza la ricontrolla il confronto (30l) quando sa
 *          deciderla: se i due metodi non sono d'accordo il verdetto è NON
 *          DIMOSTRATO, e il passo si conta tra quelli non giustificati.
 *
 * Perché i capitoli si parlano con dei testi. La tabella dei segni e i
 * limiti ripartono da zero, e svuotano l'arena: si chiedono con enunciati
 * scritti in LaTeX (ask_method()), come farebbe un utente, e ciò che
 * rispondono (un controesempio, un limite) è un testo che si rilegge. Gli
 * alberi della funzione e della primitiva si rileggono dai loro testi
 * quando servono di nuovo. */

#define MAX_IMPROPER_PIECES 4  /* parti in cui un integrale improprio si divide nei punti interni (30k-1) */
#define IMPROPER_STEPS 12      /* intervalli compatti del controllo con i numeri (30k-4) */

/* Un estremo di una parte di un integrale improprio, o il valore di un
 * limite: un infinito, oppure un numero scritto in LaTeX. */
typedef struct {
    int infinite;              /* +1 per +\infty, -1 per -\infty, 0 per un numero */
    char text[ANSWER_BYTES];   /* il numero, se infinite è 0: si rilegge con il lettore */
} EndText;

/* Ciò che si sa di un integrale improprio, o di un suo estremo. */
typedef enum {
    IMPROPER_UNKNOWN,     /* non si sa */
    IMPROPER_FINITE,      /* converge */
    IMPROPER_PLUS,        /* vale +\infty */
    IMPROPER_MINUS,       /* vale -\infty */
    IMPROPER_NEITHER,     /* non converge, e non vale un infinito */
    IMPROPER_DIVERGENT    /* non converge; se valga un infinito non si sa */
} ImproperResult;

/* Gli estremi delle parti, da sinistra a destra: la parte i va da
 * improper_point[i] a improper_point[i + 1]. */
static EndText improper_point[MAX_IMPROPER_PIECES + 1];
static int improper_pieces;

/* Ripartenza da zero per un enunciato sugli integrali: l'arena, la tabella
 * degli atomi e le variabili dei conti; non il testo della dimostrazione. */
static void integral_reset(void) {
    arena_used = arena_keep;
    atom_count = base_poly_count = atan_count = 0;
    failure = NULL;
    env_count = point_count = 0;
    conditions_on = 0;
    induction_var = 0;
    default_base = domain_floor = 0;
}

/* LE CONDIZIONI DI ESISTENZA (30k-1) */

/* Ritorna 1 se c, che non contiene x, ha un valore, e mette in *value un
 * intervallo che lo contiene. */
static int constant_value(const Node *c, int x, Range *value) {
    *value = sample_value(sample_tree(c, x, 0, 0), x, range_none());
    return range_known(*value);
}

/* Ritorna 1 se c, che non contiene x, è un intero, e lo mette in *n. */
static int constant_integer(const Node *c, int x, long long *n) {
    if (node_has_variable(c, x)) return 0;
    const char *saved = failure;
    env_count = 0;
    Rat r = eval(c);
    Num v;
    int whole = !failure && rat_number(r, &v) && v.im.num == 0 && v.re.den == 1;
    failure = saved;
    if (whole) *n = v.re.num;
    return whole;
}

/* Aggiunge alla congiunzione text la condizione "\left(u\right) relation",
 * se non c'è già. Ritorna 0 se non ci sta. */
static int condition_add(const Node *u, const char *relation, char *text, size_t size) {
    char written[ANSWER_BYTES], piece[ANSWER_BYTES + 32];
    if (!node_latex(u, written, sizeof written)) return 0;
    snprintf(piece, sizeof piece, "\\left(%s\\right) %s", written, relation);
    if (strstr(text, piece)) return 1;
    if (strlen(text) + strlen(piece) + 8 >= size) return 0;
    text_add(text, size, "%s%s", text[0] ? " \\land " : "", piece);
    return 1;
}

/* La condizione u != 0, ridotta dove si sa: un prodotto è zero se lo è un
 * fattore, una potenza o una radice se lo è la base, c^v (con c > 0) e e^v
 * mai. Chi chiama ha già posto le condizioni di esistenza di u. Ritorna 0
 * come condition_add(), o se u è una costante che non si sa diversa da
 * zero. */
static int condition_nonzero(const Node *u, int x, char *text, size_t size) {
    Range value;
    long long n;
    int side;
    if (!node_has_variable(u, x)) return constant_value(u, x, &value) && range_side(value, &side);
    switch (u->kind) {
    case N_NEG:
        return condition_nonzero(u->a, x, text, size);
    case N_MUL:
        return condition_nonzero(u->a, x, text, size) && condition_nonzero(u->b, x, text, size);
    case N_DIV:
        return condition_nonzero(u->a, x, text, size);
    case N_POW:
        /* c^v e u^v = e^{v ln u} hanno la base positiva; u^0 = 1, e u^{-n}
         * ha già u != 0 tra le condizioni. */
        if (!node_has_variable(u->a, x) || node_has_variable(u->b, x)) return 1;
        if (constant_integer(u->b, x, &n) && n <= 0) return 1;
        return condition_nonzero(u->a, x, text, size);
    case N_CALL:
        if (u->op == FN_ROOT || u->op == FN_ABS) return condition_nonzero(u->a, x, text, size);
        break;
    default:
        break;
    }
    return condition_add(u, "\\ne 0", text, size);
}

/* La condizione u > 0, ridotta come in condition_nonzero(): |v| > 0 se
 * v != 0, e c^v > 0 sempre. */
static int condition_positive(const Node *u, int x, char *text, size_t size) {
    Range value;
    int side;
    if (!node_has_variable(u, x)) return constant_value(u, x, &value) && range_side(value, &side) && side > 0;
    if (u->kind == N_CALL && u->op == FN_ABS) return condition_nonzero(u->a, x, text, size);
    if (u->kind == N_POW && !node_has_variable(u->a, x)) return 1;
    return condition_add(u, "> 0", text, size);
}

/* La condizione u >= 0: vale da sé per |v|, c^v e le potenze pari. */
static int condition_nonnegative(const Node *u, int x, char *text, size_t size) {
    long long n;
    if (u->kind == N_CALL && u->op == FN_ABS) return 1;
    if (u->kind == N_POW && (!node_has_variable(u->a, x) || (constant_integer(u->b, x, &n) && n % 2 == 0))) return 1;
    return condition_add(u, "\\ge 0", text, size);
}

/* 30k-1. Aggiunge alla congiunzione text le condizioni perché tree, nella
 * variabile x, sia definita: divisori diversi da zero, argomenti dei
 * logaritmi e basi delle potenze con un esponente non intero (o con x
 * nell'esponente: u^v = e^{v ln u}) positivi, radicandi di indice pari non
 * negativi, coseni diversi da zero sotto una tangente (seni sotto una
 * cotangente), |u| <= 1 sotto un arcoseno. Una parte senza x deve avere un
 * valore. Sono le stesse convenzioni del resto del programma (29f, 29h).
 * Ritorna 0 se tree contiene ciò che qui non si tratta (fattoriali,
 * somme con \sum, applicazioni), o se il testo non ci sta. */
static int domain_conditions(const Node *tree, int x, char *text, size_t size) {
    Range value;
    long long n;
    int side;
    if (!node_has_variable(tree, x)) return constant_value(tree, x, &value);
    switch (tree->kind) {
    case N_VAR:
        return 1;
    case N_NEG:
        return domain_conditions(tree->a, x, text, size);
    case N_ADD: case N_SUB: case N_MUL:
        return domain_conditions(tree->a, x, text, size) && domain_conditions(tree->b, x, text, size);
    case N_DIV:
        return domain_conditions(tree->a, x, text, size) && domain_conditions(tree->b, x, text, size) && condition_nonzero(tree->b, x, text, size);
    case N_POW:
        if (!domain_conditions(tree->a, x, text, size) || !domain_conditions(tree->b, x, text, size)) return 0;
        if (tree->a->kind == N_VAR && tree->a->name == 'e') return 1;
        if (constant_integer(tree->b, x, &n)) return n >= 0 || condition_nonzero(tree->a, x, text, size);
        return condition_positive(tree->a, x, text, size);
    case N_CALL:
        if (!domain_conditions(tree->a, x, text, size)) return 0;
        switch ((Function)tree->op) {
        case FN_SIN: case FN_COS: case FN_ARCTAN: case FN_ARCCOT: case FN_ABS:
            return 1;
        case FN_TAN:
            return condition_nonzero(node_call(FN_COS, tree->a, NULL), x, text, size);
        case FN_COT:
            return condition_nonzero(node_call(FN_SIN, tree->a, NULL), x, text, size);
        case FN_LN:
            return condition_positive(tree->a, x, text, size);
        case FN_LOG:
            /* La base è un numero positivo diverso da 1. */
            if (!tree->b || node_has_variable(tree->b, x) || !constant_value(tree->b, x, &value) || !range_side(value, &side) || side < 0 ||
                !range_side(range_sub(value, range_ratio(1, 1)), &side))
                return 0;
            return condition_positive(tree->a, x, text, size);
        case FN_ROOT:
            if (!constant_integer(tree->b, x, &n) || n < 2) return 0;
            return n % 2 || condition_nonnegative(tree->a, x, text, size);
        case FN_ARCSIN: case FN_ARCCOS:
            return condition_add(tree->a, "^{2} \\le 1", text, size);
        default:
            return 0;
        }
    default:
        return 0;
    }
}

/* I TESTI DEGLI ESTREMI */

/* Scrive in text l'estremo e: +\infty, -\infty o il numero. */
static void end_latex(const EndText *e, char *text, size_t size) {
    snprintf(text, size, "%s", e->infinite > 0 ? "+\\infty" : e->infinite < 0 ? "-\\infty" : e->text);
}

/* Mette in *value l'intervallo del numero dell'estremo e (finito). Ritorna 0
 * se il testo non si rilegge o non ha un valore. Usa l'arena. */
static int end_range(const EndText *e, int x, Range *value) {
    Node *tree = text_tree(e->text);
    return tree && constant_value(tree, x, value);
}

/* Ritorna 1 se l'estremo c sta di sicuro tra p e q, che possono essere
 * infiniti. */
static int end_between(const EndText *p, const EndText *c, const EndText *q, int x) {
    Range low, middle, high;
    int side;
    if (c->infinite || !end_range(c, x, &middle)) return 0;
    if (!p->infinite && !(end_range(p, x, &low) && range_side(range_sub(middle, low), &side) && side > 0)) return 0;
    if (!q->infinite && !(end_range(q, x, &high) && range_side(range_sub(high, middle), &side) && side > 0)) return 0;
    return 1;
}

/* 30k-1. Chiede alla tabella dei segni se le condizioni conditions valgono
 * su ogni parte (improper_point[]), e divide una parte nel punto in cui la
 * tabella le smentisce. Ritorna 1 se alla fine valgono su ogni parte, 0 se
 * non si sa. La dimostrazione della tabella entra nel testo. */
static int improper_domain(const char *conditions, int x) {
    static char question[MAX_FORMULA], low[ANSWER_BYTES], high[ANSWER_BYTES];
    if (!conditions[0]) {
        proof_add("Every operation in the integrand is defined for every real number, so it is continuous everywhere.\n");
        return 1;
    }
    for (int i = 0; i < improper_pieces;) {
        const EndText *p = &improper_point[i], *q = &improper_point[i + 1];
        end_latex(p, low, sizeof low);
        end_latex(q, high, sizeof high);
        int wanted;
        if (p->infinite && q->infinite) wanted = snprintf(question, sizeof question, "\\forall %c \\in \\mathbb{R}\\ (%s)", x, conditions);
        else if (p->infinite) wanted = snprintf(question, sizeof question, "\\forall %c \\in \\mathbb{R}\\ (%c < %s \\implies %s)", x, x, high, conditions);
        else if (q->infinite) wanted = snprintf(question, sizeof question, "\\forall %c \\in \\mathbb{R}\\ (%s < %c \\implies %s)", x, low, x, conditions);
        else wanted = snprintf(question, sizeof question, "\\forall %c \\in \\mathbb{R}\\ (%s < %c \\land %c < %s \\implies %s)", x, low, x, x, high, conditions);
        if (wanted < 0 || (size_t)wanted >= sizeof question) return 0;
        /* Si scrive la domanda intera, con l'implicazione: la tabella che
         * segue ha righe anche fuori dall'intervallo, dove l'implicazione
         * vale perché la sua ipotesi è falsa. Con le sole condizioni, una riga
         * come "x = 0: la condizione vale" sembrava dire x \ne 0 in x = 0. */
        proof_add("\n\\emph{Where the functions are defined}, on $(%s, %s)$: the conditions $%s$ must hold there, that is $%s$; "
                  "outside the interval the implication holds because its hypothesis is false.\n", low, high, conditions, question);
        Verdict table = ask_method(prove_quantified, question, "The sign table, too long to be written here, shows that the conditions hold on every row.", 1);
        proof_add("\n");
        if (table.outcome == PROVED) { i++; continue; }

        /* Smentite in un punto c: si divide la parte in c. */
        const char *value = table.outcome == REFUTED && table.detail ? strstr(table.detail, "= ") : NULL;
        if (!value || improper_pieces == MAX_IMPROPER_PIECES) return 0;
        EndText c = {0, ""};
        snprintf(c.text, sizeof c.text, "%s", value + 2);
        if (!end_between(p, &c, q, x)) return 0;
        for (int k = improper_pieces; k > i; k--) improper_point[k + 1] = improper_point[k];
        improper_point[i + 1] = c;
        improper_pieces++;
        proof_add("\nThe sign table finds a point where a condition fails, $%c = %s$: the interval is split there, and each part is improper "
                  "at that end.\n", x, c.text);
    }
    return 1;
}

/* 30k-3. Il limite della funzione scritta in function quando x tende
 * all'estremo end, da destra se side è +1 e da sinistra se è -1 (per un
 * estremo infinito side non conta), chiesto al capitolo 29: mette in *out
 * l'infinito o il valore scritto, e ritorna 1 se il limite è calcolato. La
 * dimostrazione del limite entra nel testo, dopo intro. */
static int improper_limit(const char *function, int x, const EndText *end, int side, const char *intro, EndText *out) {
    static char question[MAX_FORMULA];
    int wanted = end->infinite ? snprintf(question, sizeof question, "\\lim_{%c \\to %s} %s", x, end->infinite > 0 ? "+\\infty" : "-\\infty", function)
                               : snprintf(question, sizeof question, "\\lim_{%c \\to %s^{%c}} %s", x, end->text, side > 0 ? '+' : '-', function);
    if (wanted < 0 || (size_t)wanted >= sizeof question) return 0;
    proof_add("%s", intro);
    Verdict limit = ask_method(prove_limit, question, "The limit, computed with the expansions of chapter 29, is the one written here.", 1);
    proof_add("\n");
    if (limit.outcome != SOLVED || !limit.detail) return 0;
    const char *value = NULL;
    for (const char *s = strstr(limit.detail, " = "); s; s = strstr(s + 1, " = ")) value = s + 3;
    if (!value) return 0;
    out->infinite = infinity_text(value, value + strlen(value));
    if (out->infinite == 2) return 0;
    snprintf(out->text, sizeof out->text, "%s", value);
    return 1;
}

/* 30l. IL CONFRONTO
 *
 * Quando non si trova una primitiva, la convergenza si decide dal
 * comportamento di f vicino a ogni estremo. Con t -> 0^{+} la lettera di 29a
 * (t = b - x vicino a un estremo b, t = 1/|x| all'infinito) e L = ln(1/t),
 * sia g = t^{e} L^{d}, positiva vicino all'estremo. I teoremi:
 *
 *   (C1) confronto asintotico: se f / g -> c con c != 0 finito, allora f ha
 *        il segno di c vicino all'estremo, |f| sta tra |c| g / 2 e 2 |c| g,
 *        e \int f converge se e solo se converge \int g; se \int g diverge,
 *        \int f vale \infty con il segno di c;
 *   (C2) se f / g -> 0 e \int g converge, allora |f| <= g vicino
 *        all'estremo, e \int f converge (assolutamente);
 *   (C3) se f / g -> \pm\infty e \int g diverge, allora f ha il segno
 *        dell'infinito e |f| >= g vicino all'estremo: \int f vale \infty con
 *        quel segno.
 *
 * E la scala di g (con s = ln(1/t), \int t^{e} L^{d} dt = \int e^{-(e + 1) s}
 * s^{d} ds verso s = +\infty, o con x = 1/t all'infinito):
 *
 *   - vicino a un estremo b che è un numero, \int (b - x)^{e} L^{d} dx
 *     converge se e solo se e > -1, oppure e = -1 e d < -1;
 *   - all'infinito, \int |x|^{-e} (\ln|x|)^{d} dx converge se e solo se
 *     e > 1, oppure e = 1 e d < -1.
 *
 * La g viene dal termine principale di f (29m, limit_leading()), che è un
 * conto del capitolo 29 confermato dal suo controllo con i numeri (29i):
 * f = c t^{e} L^{d} (1 + o(1)) con c != 0 dice proprio f / g -> c con
 * g = t^{e} L^{d}, ed è (C1). Se f ha un fattore e^{G} con G -> -\infty, f
 * è più piccola di ogni potenza (29k-b): f / g -> 0 con g = t^{-1/2} (o
 * x^{-2} all'infinito), ed è (C2); con G -> +\infty f / g -> \pm\infty con
 * g = t^{-1} (o 1), ed è (C3). Se della serie si conosce solo il resto,
 * f = O(t^{e}) (\frac{\sin x}{x^{2}} all'infinito è O(t^{2})), allora
 * |f| <= C g con g = t^{e}: è (C2), e decide solo quando \int g converge.
 * Del coefficiente c servono il segno e che non sia zero, che il conto
 * decide in modo esatto. I casi in cui f oscilla senza tendere a zero
 * abbastanza in fretta (\cos x all'infinito) restano non decisi. */

/* 30l. Il confronto all'estremo end di una parte (side +1 se è l'estremo
 * sinistro, a cui si arriva da destra, -1 se è il destro) per la funzione
 * scritta in function: ritorna IMPROPER_FINITE se l'integrale converge
 * vicino a end, IMPROPER_PLUS o IMPROPER_MINUS se vale un infinito,
 * IMPROPER_UNKNOWN se non si sa. Con proof scrive il ragionamento. */
static ImproperResult improper_compare(const char *function, int x, const EndText *end, int side, int proof) {
    static char question[MAX_FORMULA], t[ANSWER_BYTES], ell[ANSWER_BYTES], g[2 * ANSWER_BYTES];
    char e_text[64] = "", d_text[64] = "", where[ANSWER_BYTES];
    int wanted = end->infinite ? snprintf(question, sizeof question, "\\lim_{%c \\to %s} %s", x, end->infinite > 0 ? "+\\infty" : "-\\infty", function)
                               : snprintf(question, sizeof question, "\\lim_{%c \\to %s^{%c}} %s", x, end->text, side > 0 ? '+' : '-', function);
    if (wanted < 0 || (size_t)wanted >= sizeof question) return IMPROPER_UNKNOWN;
    LeadingTerm lead = limit_leading(question);
    if (!lead.found) return IMPROPER_UNKNOWN;

    /* La g: t^{e} L^{d} per (C1), oppure quella di (C2) o di (C3) con il
     * fattore e^{G}; e la scala, se il suo integrale converge. */
    int finite_end = !end->infinite;
    Frac e = lead.growth > 0 ? frac_int(finite_end ? -1 : 0) : lead.growth < 0 ? (finite_end ? (Frac){-1, 2} : frac_int(2)) : lead.e;
    Frac d = lead.growth ? frac_int(0) : lead.d;
    int g_converges = finite_end ? (frac_cmp(e, frac_int(-1)) > 0 || (frac_cmp(e, frac_int(-1)) == 0 && frac_cmp(d, frac_int(-1)) < 0))
                                 : (frac_cmp(e, frac_int(1)) > 0 || (frac_cmp(e, frac_int(1)) == 0 && frac_cmp(d, frac_int(-1)) < 0));
    ImproperResult result = lead.growth < 0 || (!lead.growth && g_converges) ? IMPROPER_FINITE : lead.sign > 0 ? IMPROPER_PLUS : IMPROPER_MINUS;

    /* Con il solo resto, |f| <= C g: dice che converge se converge \int g
     * (C2), e niente se diverge. */
    if (lead.bound && !g_converges) return IMPROPER_UNKNOWN;
    if (!proof) return result;

    /* La dimostrazione: t, positiva e che tende a 0, L = ln(1/t), la g, e
     * il teorema usato. */
    if (end->infinite) {
        snprintf(t, sizeof t, end->infinite > 0 ? "\\frac{1}{%c}" : "\\left(-\\frac{1}{%c}\\right)", x);
        snprintf(ell, sizeof ell, end->infinite > 0 ? "\\ln %c" : "\\ln(-%c)", x);
    } else {
        if (side < 0) snprintf(t, sizeof t, "\\left(%s - %c\\right)", end->text, x);
        else snprintf(t, sizeof t, "\\left(%c - \\left(%s\\right)\\right)", x, end->text);
        snprintf(ell, sizeof ell, "-\\ln%s", t);
    }
    frac_latex(e, e_text, sizeof e_text);
    frac_latex(d, d_text, sizeof d_text);
    g[0] = 0;
    if (e.num) text_add(g, sizeof g, "\\left(%s\\right)^{%s}", t, e_text);
    if (d.num) text_add(g, sizeof g, "%s\\left(%s\\right)^{%s}", g[0] ? " " : "", ell, d_text);
    if (!g[0]) text_add(g, sizeof g, "1");
    end_latex(end, where, sizeof where);
    if (failure) { failure = NULL; return IMPROPER_UNKNOWN; }
    proof_add("\n\\emph{Comparison as $%c \\to %s%s$}, with $g = %s$, positive near the end. The expansions of the limits (with their check with "
              "numbers) give %s. The integral of $g$ %s near this end (%s), so, by %s, the integral of the integrand %s there.\n", x, where,
              finite_end ? side > 0 ? "^{+}" : "^{-}" : "", g,
              lead.growth < 0 ? "an integrand smaller than every power, so $f / g \\to 0$"
              : lead.growth > 0 ? (lead.sign > 0 ? "an integrand larger than every power, so $f / g \\to +\\infty$"
                                                 : "an integrand larger than every power in absolute value, so $f / g \\to -\\infty$")
              : lead.bound ? "only a bound, $f = O(g)$, that is $|f| \\le C g$ near the end"
              : lead.sign > 0 ? "$f / g \\to c$ with $c > 0$" : "$f / g \\to c$ with $c < 0$",
              g_converges ? "converges" : "diverges",
              finite_end ? "$\\int (b - x)^{e} \\left(\\ln\\frac{1}{b - x}\\right)^{d} dx$ converges near $b$ if and only if $e > -1$, or $e = -1$ and $d < -1$"
                         : "$\\int |x|^{-e} \\left(\\ln |x|\\right)^{d} dx$ converges at infinity if and only if $e > 1$, or $e = 1$ and $d < -1$",
              lead.growth > 0 ? "comparison ($|f| \\ge g$ near the end, with the sign of $f$)"
              : lead.growth < 0 || lead.bound ? "comparison ($|f| \\le C g$ near the end: the integral converges absolutely)"
                                              : "asymptotic comparison",
              result == IMPROPER_FINITE ? "converges" : result == IMPROPER_PLUS ? "is $+\\infty$" : "is $-\\infty$");
    return result;
}

/* Ritorna ciò che dicono di un integrale improprio i risultati result[] dei
 * suoi count estremi (30l): converge se converge vicino a ogni estremo; un
 * infinito, se tutti quelli che divergono hanno lo stesso segno e degli
 * altri si sa che convergono; nessuno dei due, se due divergono con segni
 * opposti (+\infty - \infty non ha un valore). */
static ImproperResult improper_combine(const ImproperResult *result, int count) {
    int unknown = 0, plus = 0, minus = 0;
    for (int i = 0; i < count; i++) {
        unknown |= result[i] == IMPROPER_UNKNOWN;
        plus |= result[i] == IMPROPER_PLUS;
        minus |= result[i] == IMPROPER_MINUS;
    }
    if (plus && minus) return IMPROPER_NEITHER;
    if (unknown) return plus || minus ? IMPROPER_DIVERGENT : IMPROPER_UNKNOWN;
    return plus ? IMPROPER_PLUS : minus ? IMPROPER_MINUS : IMPROPER_FINITE;
}

/* 30k-3. I limiti di F (scritta in function) agli estremi di ogni parte, in
 * from[] (da destra dell'estremo sinistro) e to[] (da sinistra del destro).
 * Ritorna ciò che dicono dell'integrale vicino a ogni estremo, in result[]
 * (due per parte, come per il confronto), o 0 se un limite non si calcola. */
static int improper_limits(const char *function, int x, EndText *from, EndText *to, ImproperResult *result) {
    char where[ANSWER_BYTES], intro[2 * ANSWER_BYTES];
    for (int i = 0; i < improper_pieces; i++) {
        for (int end = 0; end < 2; end++) {
            const EndText *point = &improper_point[i + end];
            EndText *limit = end ? &to[i] : &from[i];
            end_latex(point, where, sizeof where);
            snprintf(intro, sizeof intro, "\n\\emph{The limit of $F$ as $%c \\to %s%s$}.\n", x, where, point->infinite ? "" : end ? "^{-}" : "^{+}");
            if (!improper_limit(function, x, point, end ? -1 : 1, intro, limit)) return 0;

            /* Vicino all'estremo destro l'integrale va come F, vicino al
             * sinistro come -F. */
            int sign = end ? limit->infinite : -limit->infinite;
            result[2 * i + end] = sign > 0 ? IMPROPER_PLUS : sign < 0 ? IMPROPER_MINUS : IMPROPER_FINITE;
        }
    }
    return 1;
}

/* 30k-4. Il controllo con i numeri sulla parte da p a q, con f e F già
 * passati da sample_tree(): vedi la testa di 30k. Mette in *steps quanti
 * intervalli [p_k, q_k] sono stati controllati, e dell'ultimo gli estremi in
 * *low e *high e l'involucro dell'integrale in *integral. Ritorna 1 se il controllo non trova errori; 0 se dice che il
 * programma ha sbagliato, F(q_k) - F(p_k) di sicuro fuori dall'involucro o
 * due stime garantite che non si toccano; -1 se trova un intervallo
 * compatto della parte su cui f non si chiude benché si calcoli nei suoi
 * estremi. */
static int improper_riemann(const Node *f, const Node *F, int x, const EndText *p, const EndText *q, int *steps, Range *low, Range *high,
                            Range *integral) {
    Range P = range_none(), Q = range_none(), one = range_ratio(1, 1), sum = {0, 0};
    *steps = 0;
    if ((!p->infinite && !end_range(p, x, &P)) || (!q->infinite && !end_range(q, x, &Q))) return 1;

    /* Il punto di partenza m, dentro la parte; poi gli intervalli verso gli
     * estremi, a metà della distanza che resta o raddoppiando. */
    Range m = p->infinite && q->infinite ? (Range){0, 0} : p->infinite ? range_sub(Q, one) : q->infinite ? range_add(P, one)
                                                                                                      : range_div(range_add(P, Q), range_ratio(2, 1));
    Range left = m, right = m;
    for (int k = 1; k <= IMPROPER_STEPS; k++) {
        Range half = range_ratio(1, (__int128)1 << k), far = range_ratio((__int128)1 << (k - 1), 1);
        Range next_left = p->infinite ? range_sub(m, far) : range_add(P, range_mul(range_sub(m, P), half));
        Range next_right = q->infinite ? range_add(m, far) : range_sub(Q, range_mul(range_sub(Q, m), half));
        /* Una sola suddivisione, senza raffinarla: qui l'involucro serve a
         * vedere un F sbagliato, non a dare il valore con tante cifre, e
         * le parti sono tante (due per passo e per parte). */
        Enclosure before = riemann_enclosure(f, F, x, next_left, left, RIEMANN_PIECES), after = riemann_enclosure(f, F, x, right, next_right, RIEMANN_PIECES);
        if (before.broken || after.broken) return 0;

        /* Un intervallo che gli intervalli non sanno chiudere ferma il
         * controllo. Può essere F a non chiudersi, per i conti (2/(3x^3 -
         * 45x^2 + 225x - 375) vicino a 5 perde tutte le cifre); ma se è f a
         * non chiudersi, e f si calcola in tutti e due i suoi estremi, il
         * motivo non è un numero troppo grande vicino a un estremo
         * dell'integrale, ma forse un punto dentro in cui f non è definita,
         * che le condizioni di esistenza (30k-1) non hanno visto: allora il
         * controllo smentisce. */
        for (int side = 0; side < 2; side++) {
            Range from = side ? right : next_left, to = side ? next_right : left;
            if ((side ? after : before).defined || !range_known(sample_value(f, x, from)) || !range_known(sample_value(f, x, to))) continue;
            if (!riemann_enclosure(f, NULL, x, from, to, RIEMANN_PIECES).defined) return -1;
        }
        if (!before.defined || !after.defined) break;
        sum = range_add(sum, range_add(before.integral, after.integral));
        Range difference = range_sub(sample_value(F, x, next_right), sample_value(F, x, next_left));
        if (!range_known(sum) || !range_known(difference)) break;
        if (difference.high < sum.low || difference.low > sum.high) return 0;
        left = next_left;
        right = next_right;
        *steps = k;
        *low = left;
        *high = right;
        *integral = sum;
    }
    return 1;
}

/* Il motivo di un NON DIMOSTRATO quando il confronto dice che l'integrale
 * converge, ma il valore manca. */
static const char *const CONVERGES_WITHOUT_VALUE = "l'integrale converge (per confronto), ma non trovo una primitiva per calcolarne il valore";

/* 30k. Il verdetto su un integrale improprio, letto da formula: vedi la
 * testa di 30k e di 30l. Svuota l'arena e la tabella degli atomi. */
static Verdict prove_improper(const char *formula) {
    static char f_text[ANSWER_BYTES], F_text[ANSWER_BYTES], f_conditions[ANSWER_BYTES], all_conditions[2 * ANSWER_BYTES], answer[ANSWER_BYTES];
    static EndText from[MAX_IMPROPER_PIECES], to[MAX_IMPROPER_PIECES];
    static ImproperResult ends[2 * MAX_IMPROPER_PIECES];
    Verdict verdict = {NOT_PROVED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    IntegralStatement st;
    PrimitiveCheck check;

    /* La lettura, i testi, e il verso: gli estremi da sinistra a destra. */
    proof_reset();
    integral_reset();
    if (!parse_integral_statement(formula, &st)) {
        verdict.outcome = UNSUPPORTED;
        verdict.reason = syntax_error;
        syntax_error = NULL;
        return verdict;
    }
    int x = st.variable, flip = 0;
    if (x == 'n') {
        verdict.outcome = UNSUPPORTED;
        verdict.reason = "un integrale improprio nella lettera n, che nei limiti è l'indice di una successione";
        return verdict;
    }
    EndText a = {st.lower_infinite, ""}, b = {st.upper_infinite, ""};
    if ((st.lower && !node_latex(st.lower, a.text, sizeof a.text)) || (st.upper && !node_latex(st.upper, b.text, sizeof b.text)) ||
        !node_latex(st.integrand, f_text, sizeof f_text)) {
        verdict.reason = "un estremo, o la funzione integranda, troppo lunghi da scrivere";
        return verdict;
    }
    if (a.infinite || b.infinite) {
        if (a.infinite == b.infinite) { verdict.reason = "i due estremi sono lo stesso infinito"; return verdict; }
        flip = a.infinite > 0 || b.infinite < 0;
    } else {
        Range low, high;
        int side;
        if (!end_range(&a, x, &low) || !end_range(&b, x, &high) || !range_side(range_sub(high, low), &side)) {
            verdict.reason = "non riesco a stabilire quale dei due estremi è il più piccolo";
            return verdict;
        }
        flip = side < 0;
    }
    improper_pieces = 1;
    improper_point[0] = flip ? b : a;
    improper_point[1] = flip ? a : b;

    /* Le condizioni di esistenza di f; la primitiva, e le sue. */
    f_conditions[0] = all_conditions[0] = 0;
    if (!domain_conditions(st.integrand, x, f_conditions, sizeof f_conditions)) {
        verdict.reason = "la funzione integranda contiene ciò di cui non so scrivere le condizioni di esistenza";
        return verdict;
    }
    Node *F = found_primitive(st.integrand, x, F_text, sizeof F_text, &check);
    failure = NULL;
    proof_add("\\textbf{Proof.} The integral is improper: by definition it is the limit of the integrals over the compact intervals inside "
              "the interval of integration, with the interval split at the points where the functions are not defined; it converges if "
              "the limit is finite on every part. ");
    size_t opening = proof_length;
    int with_F = 0;
    if (F) {
        snprintf(all_conditions, sizeof all_conditions, "%s", f_conditions);
        with_F = domain_conditions(F, x, all_conditions, sizeof all_conditions) && check.derivative &&
                 domain_conditions(check.derivative, x, all_conditions, sizeof all_conditions);
        if (with_F) {
            proof_add("Let $F = ");
            put_node(F, 0);
            proof_add("$, found by the search for an antiderivative. ");
            if (!put_primitive_check(st.integrand, F, x, &check)) {
                unjustified_steps++;
                verdict.reason = "la derivata scritta nella dimostrazione, riletta, non è confermata";
                return verdict;
            }
            proof_add("By the fundamental theorem of calculus, on every compact interval $[p, q]$ where $f$ is continuous and $F$ "
                      "differentiable, the integral is $F(q) - F(p)$: on each part, the improper integral is the limit of $F$ at its right end "
                      "minus the limit at its left end.\n\n");
        }
    }

    /* 30k-1, 30k-3: dove le funzioni sono definite, poi i limiti di F.
     * Se non si arriva in fondo, si ricomincia con il confronto (30l), senza
     * F e senza ciò che se n'è scritto. */
    ImproperResult result = IMPROPER_UNKNOWN;
    if (with_F && improper_domain(all_conditions, x) && improper_limits(F_text, x, from, to, ends)) result = improper_combine(ends, 2 * improper_pieces);
    if (result == IMPROPER_UNKNOWN) {
        proof_cut(opening);
        with_F = 0;
        improper_pieces = 1;
        improper_point[0] = flip ? b : a;
        improper_point[1] = flip ? a : b;
        if (!improper_domain(f_conditions, x)) {
            verdict.reason = "non riesco a stabilire che la funzione integranda sia continua sull'intervallo aperto di integrazione";
            return verdict;
        }
        for (int i = 0; i < 2 * improper_pieces; i++) ends[i] = improper_compare(f_text, x, &improper_point[(i + 1) / 2], i % 2 ? -1 : 1, 1);
        result = improper_combine(ends, 2 * improper_pieces);
    } else {
        /* Il secondo controllo della convergenza: il confronto, che non usa
         * F, dove sa decidere, deve dire lo stesso (30k-4). Del suo
         * ragionamento nel testo resta solo l'esito. */
        ImproperResult again[2 * MAX_IMPROPER_PIECES];
        size_t mark = proof_length;
        for (int i = 0; i < 2 * improper_pieces; i++) again[i] = improper_compare(f_text, x, &improper_point[(i + 1) / 2], i % 2 ? -1 : 1, 0);
        proof_cut(mark);
        for (int i = 0; i < 2 * improper_pieces; i++) {
            if (again[i] == IMPROPER_UNKNOWN || again[i] == ends[i]) continue;
            unjustified_steps++;
            verdict.reason = "il confronto e i limiti della primitiva non sono d'accordo sulla convergenza: un errore del programma";
            return verdict;
        }
        int compared = 0;
        for (int i = 0; i < 2 * improper_pieces; i++) compared += again[i] != IMPROPER_UNKNOWN;
        if (compared)
            proof_add("\n\\emph{Second check, by comparison} (which does not use $F$): at %d of the %d ends the behaviour of the integrand, "
                      "compared with a power of the distance from the end and of its logarithm, gives the same convergence or divergence.\n",
                      compared, 2 * improper_pieces);
    }
    if (flip) result = result == IMPROPER_PLUS ? IMPROPER_MINUS : result == IMPROPER_MINUS ? IMPROPER_PLUS : result;

    /* Da qui servono di nuovo gli alberi: si rileggono dai testi. */
    integral_reset();
    parse_integral_statement(formula, &st);
    syntax_error = NULL;

    /* 30k-4. Il controllo con i numeri, su ogni parte, con F. */
    if (with_F) {
        Node *fs = sample_tree(text_tree(f_text), x, 0, 0), *Fs = sample_tree(text_tree(F_text), x, 0, 0);
        proof_add("\n\\emph{Check with numbers}, with Riemann sums in interval arithmetic, which use neither $F$ nor exact algebra: ");
        for (int i = 0; i < improper_pieces; i++) {
            int steps;
            Range low, high, integral;
            int checked = improper_riemann(fs, Fs, x, &improper_point[i], &improper_point[i + 1], &steps, &low, &high, &integral);
            if (checked <= 0) {
                unjustified_steps++;
                verdict.reason = checked ? "su un intervallo compatto dentro una parte gli intervalli non sanno chiudere la funzione integranda, benché "
                                           "la calcolino nei suoi estremi: forse un punto in cui non è definita, che le condizioni di esistenza non hanno visto"
                                         : "F(q) - F(p) non sta nell'involucro di Riemann dell'integrale su [p, q]: un errore del programma";
                return verdict;
            }
            if (!steps) { verdict.reason = "le somme di Riemann con gli intervalli non si calcolano vicino agli estremi"; return verdict; }
            if (improper_pieces > 1) proof_add("%son part %d, ", i ? "; " : "", i + 1);
            proof_add("on %d intervals $[p_k, q_k]$ growing towards the ends they enclose the integral, and $F(q_k) - F(p_k)$ lies inside every "
                      "time; the last is $[p_k, q_k] \\subseteq ", steps);
            put_range((Range){low.low, high.high});
            proof_add("$, with the integral in $");
            put_range(integral);
            proof_add("$");
        }
        proof_add(".\n\n");
    }

    /* Il valore, per una parte alla volta, con i conti esatti. */
    Rat exact = rat_int(0);
    if (with_F && result == IMPROPER_FINITE) {
        for (int i = 0; i < improper_pieces && !failure; i++) {
            Node *above = text_tree(to[i].text), *below = text_tree(from[i].text);
            env_count = 0;
            if (!above || !below) { verdict.reason = "un limite scritto non si rilegge"; return verdict; }
            exact = rat_add(exact, rat_add(eval(above), eval(below), 1), 0);
        }
        if (flip) exact = rat_add(rat_int(0), exact, 1);
        if (failure) { verdict.reason = failure; failure = NULL; return verdict; }
    }

    /* Il verdetto: holds è 1 se l'enunciato è vero, 0 se è falso, -1 se non
     * si sa. */
    int holds = -1;
    const char *method = with_F ? "come integrale improprio, con la primitiva e i suoi limiti agli estremi" : "come integrale improprio, per confronto";
    int divergent = result == IMPROPER_PLUS || result == IMPROPER_MINUS || result == IMPROPER_NEITHER || result == IMPROPER_DIVERGENT;
    if (st.membership) holds = result == IMPROPER_FINITE ? st.membership > 0 : divergent ? st.membership < 0 : -1;
    else if (st.answer_infinite) holds = result == IMPROPER_PLUS ? st.answer_infinite > 0 : result == IMPROPER_MINUS ? st.answer_infinite < 0
                                        : result == IMPROPER_FINITE || result == IMPROPER_NEITHER ? 0 : -1;
    else if (st.answer && divergent) holds = 0;
    else if (st.answer && result == IMPROPER_FINITE && with_F) {
        env_count = 0;
        Rat gap = rat_add(exact, eval(st.answer), 1);
        int side;
        if (!failure && poly_vanishes(gap.num)) holds = 1;
        else if (!failure && range_side(constant_range(gap), &side)) holds = 0;
        failure = NULL;
    }

    /* La conclusione scritta. */
    if (result == IMPROPER_FINITE) proof_add("Hence the integral converges");
    else if (result == IMPROPER_PLUS || result == IMPROPER_MINUS) proof_add("Hence the integral is $%s\\infty$", result == IMPROPER_PLUS ? "+" : "-");
    else if (result == IMPROPER_NEITHER) proof_add("Hence the integral does not converge: on one part it is $+\\infty$ and on another $-\\infty$, and the sum has no value");
    else if (result == IMPROPER_DIVERGENT) proof_add("Hence the integral does not converge, because it diverges near one end");
    if (!st.answer && !st.answer_infinite && !st.membership) {
        /* Una richiesta: il valore, o l'infinito, scritto e riletto. */
        verdict.method = method;
        if (result == IMPROPER_PLUS || result == IMPROPER_MINUS) snprintf(answer, sizeof answer, "%s\\infty", result == IMPROPER_PLUS ? "+" : "-");
        else if (result == IMPROPER_FINITE && with_F) {
            Node *back = rat_latex(exact, answer, sizeof answer) ? text_tree(answer) : NULL;
            env_count = 0;
            Rat gap = back ? rat_add(exact, eval(back), 1) : rat_int(1);
            if (!back || failure || !poly_vanishes(gap.num)) {
                failure = NULL;
                unjustified_steps += back != NULL;
                verdict.reason = back ? "il valore scritto, riletto, non è quello calcolato" : "non riesco a scrivere il valore dell'integrale";
                return verdict;
            }
            proof_add(", and its value is $%s$", answer);
        } else {
            verdict.reason = result == IMPROPER_FINITE ? CONVERGES_WITHOUT_VALUE
                           : result == IMPROPER_NEITHER ? "l'integrale non converge, e non vale né +\\infty né -\\infty"
                           : result == IMPROPER_DIVERGENT ? "l'integrale non converge, ma non so se valga un infinito"
                           : "non so stabilire se l'integrale converge";
            return verdict;
        }
        proof_add(". $\\Box$");
        verdict.outcome = SOLVED;
        verdict.detail = answer;
        verdict.reason = "gli integrali non hanno una notazione nei certificati";
        verdict.proof = proof_text;
        return verdict;
    }
    if (holds < 0) {
        verdict.reason = result == IMPROPER_UNKNOWN ? "non so stabilire se l'integrale converge"
                       : result == IMPROPER_FINITE && !with_F ? CONVERGES_WITHOUT_VALUE
                       : result == IMPROPER_DIVERGENT ? "l'integrale non converge, ma non so se valga un infinito"
                       : "non so se il valore calcolato è quello scritto";
        return verdict;
    }
    if (result == IMPROPER_FINITE && with_F && rat_latex(exact, answer, sizeof answer)) proof_add(", and its value is $%s$", answer);
    proof_add(holds ? ". This is what the statement says. $\\Box$" : ". The statement says otherwise, so it is false. $\\Box$");
    verdict.outcome = holds ? PROVED : REFUTED;
    verdict.method = method;
    verdict.reason = "gli integrali non hanno una notazione nei certificati";
    verdict.proof = proof_text;
    return verdict;
}

/* Prova a dimostrare, o a risolvere, l'enunciato su un integrale scritto in
 * formula (vedi 9j e la testa del capitolo). Svuota l'arena e la tabella
 * degli atomi: i risultati di chiamate precedenti non sono più validi. */
static Verdict prove_integral(const char *formula) {
    static char answer[ANSWER_BYTES + 8];
    Verdict verdict = {UNSUPPORTED, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL};
    IntegralStatement statement;

    /* Ripartenza da zero; nessuna variabile di induzione. */
    proof_reset();
    integral_reset();
    if (!parse_integral_statement(formula, &statement)) {
        verdict.reason = syntax_error;
        syntax_error = NULL;
        return verdict;
    }
    int x = statement.variable;
    const Node *f = statement.integrand, *claim = statement.answer;
    if (x == 'e' || !only_letters(f, x) || !only_letters(claim, x) || !only_letters(statement.lower, 0) || !only_letters(statement.upper, 0)) {
        verdict.reason = "in un integrale le sole lettere ammesse sono la variabile, e e pi greco";
        return verdict;
    }

    /* Un integrale definito: improprio (30k) se ha un estremo infinito, se
     * dice di valere un infinito o di convergere, o se 30i non riesce a
     * vedere la funzione continua su tutto [a, b]. */
    if (statement.definite) {
        int improper = statement.lower_infinite || statement.upper_infinite || statement.answer_infinite || statement.membership;
        if (!improper) verdict = prove_definite(f, statement.lower, statement.upper, claim, x, &improper);
        return improper ? prove_improper(formula) : verdict;
    }

    /* Una primitiva da verificare. */
    if (claim) {
        PrimitiveCheck check = primitive_check(f, claim, x);
        verdict = primitive_verdict(&check, x);
        if (check.outcome != PROVED) return verdict;
        proof_add("\\textbf{Proof.} ");
        if (!put_primitive_check(f, claim, x, &check)) {
            unjustified_steps++;
            verdict.outcome = NOT_PROVED;
            verdict.reason = "la derivata scritta nella dimostrazione, riletta, non è confermata";
            return verdict;
        }
        proof_add("$\\Box$");
        verdict.method = check.outside ? "con le regole di derivazione, su ogni intervallo in cui primitiva e funzione integranda sono definite "
                                         "(la primitiva non lo è dappertutto dove lo è la funzione)"
                                       : "con le regole di derivazione, su ogni intervallo in cui primitiva e funzione integranda sono definite";
        verdict.reason = NULL;
        verdict.proof = proof_text;
        calculus_certify(&verdict, calculus_certificate("antiderivative", x, NULL, claim, f, NULL, NULL, NULL), claim, x);
        return verdict;
    }

    /* Una primitiva da trovare. */
    PrimitiveCheck check;
    char primitive[ANSWER_BYTES];
    Node *F = found_primitive(f, x, primitive, sizeof primitive, &check);
    verdict.outcome = NOT_PROVED;
    verdict.reason = check.reason;
    if (!F) return verdict;
    proof_add("\\textbf{Solution.} The search for an antiderivative gives $");
    put_node(F, 0);
    proof_add("$, which is checked as any stated antiderivative. ");
    if (!put_primitive_check(f, F, x, &check)) {
        unjustified_steps++;
        verdict.reason = "la derivata scritta nella dimostrazione, riletta, non è confermata";
        return verdict;
    }
    proof_add("$\\Box$");
    snprintf(answer, sizeof answer, "%s + c", primitive);
    verdict.outcome = SOLVED;
    verdict.reason = NULL;
    verdict.method = primitive_method ? primitive_method : "";
    verdict.detail = answer;
    verdict.note = check.outside ? "c costante su ogni intervallo; la primitiva non è definita dappertutto dove lo è la funzione" : "c costante su ogni intervallo";
    verdict.proof = proof_text;
    calculus_certify(&verdict, calculus_certificate("antiderivative", x, NULL, F, f, NULL, NULL, NULL), F, x);
    return verdict;
}

/* =============================================================================
 * 20. DIMOSTRARE UN ENUNCIATO
 * ============================================================================
 *
 * Il punto d'ingresso unico: sceglie il metodo guardando la notazione.
 *
 * Una notazione viene guardata subito, dopo il segno di integrale, perché
 * nessun metodo la tratta e il verdetto deve dirlo con il suo motivo: il
 * numero di elementi di un insieme, |S| (uses_cardinality()). Poi
 * l'equipotenza, A \sim B, che va al capitolo 28 (17w, 28q), tranne che con un
 * insieme di numeri (uses_equipotence()). Poi un enunciato che dichiara una relazione o
 * un'applicazione tra le parti di un insieme, con \mathcal{P}(S)^{2} o
 * \colon \mathcal{P}(S), va allo svolgimento di 17r e da lì al capitolo 15
 * (uses_parts_relations()); uno che scrive un insieme con una regola,
 * \{(x, y) \mid ...\}, parla di elementi (uses_elements()).
 *
 * Le convenzioni, nell'ordine in cui si applicano. Un enunciato che nomina un
 * insieme numerico, con \mathbb, va alle regole sui quantificatori: ogni sua
 * lettera deve essere quantificata su uno di quegli insiemi, quindi non c'è
 * modo di leggerlo in un altro senso. Tra gli altri, quello che parla di
 * elementi (dichiara qualcosa con \colon, quantifica una lettera minuscola,
 * dice x \in X) è un enunciato su insiemi qualsiasi, e va al capitolo 28.
 * Negli altri una lettera maiuscola senza pedice è un insieme: un enunciato
 * che ne contiene una, o che usa un simbolo proprio degli insiemi, va alla
 * decisione per regioni. Ogni altro va
 * all'induzione, dove le maiuscole compaiono solo con un pedice, come F_{k}:
 * a quella del capitolo 13 se è un'uguaglianza, a quella del capitolo 25 se
 * è una disuguaglianza. Prima però, se contiene \implies, è un enunciato su
 * una successione definita per ricorrenza, e va al capitolo 26: negli altri
 * enunciati senza \mathbb un'implicazione non ha posto. E prima ancora, se
 * comincia con il segno di derivata di Leibniz, va al capitolo 27; se
 * comincia con \lim, anche dopo \nexists, è un limite e va al capitolo 29.
 * Prima di tutto, un enunciato che comincia con \int è un integrale, e va al
 * capitolo 30, qualunque cosa contenga dopo.
 *
 * Guardare solo i simboli non basta, e ha già causato una dimostrazione falsa:
 * S \times T = T \times S non contiene né unioni né inclusioni, veniva letto
 * come prodotto di due numeri, e come tale risultava vero. Per i prodotti
 * cartesiani è falso. Il caso è ora nei test di antiregressione.
 */

/* Ritorna 1 se formula è un enunciato sugli insiemi, secondo la convenzione
 * descritta in testa al capitolo. Usa il lettore di token del parser, e lascia
 * il suo stato da reimpostare. */
static int uses_set_notation(const char *formula) {
    static const char *const commands[] = {"cup", "cap", "setminus", "subseteq", "supseteq", "emptyset",
                                            "varnothing", "mathcal", "triangle", "exists"};
    int found = 0;
    syntax_error = NULL;
    cursor = formula;
    next_token();
    while (token.kind != T_END && !found) {
        if (token.kind == T_LETTER && isupper(token.ch)) {
            /* Una maiuscola è un insieme se non è seguita da un pedice. */
            next_token();
            found = !is_char('_');
            continue;
        }
        for (size_t i = 0; token.kind == T_COMMAND && i < sizeof commands / sizeof *commands; i++)
            if (strcmp(token.name, commands[i]) == 0) found = 1;
        next_token();
    }
    syntax_error = NULL;
    return found;
}

/* Ritorna 1 se formula parla di elementi di insiemi qualsiasi, cioè è un
 * enunciato del linguaggio di 17o: dichiara qualcosa con \colon, oppure un
 * suo quantificatore lega una lettera minuscola, oppure dice di una lettera
 * minuscola, anche con pedice numerico, che appartiene a qualcosa, oppure
 * scrive un insieme con una regola, \{x \mid ...\} o \{(x, y) \mid ...\}
 * (17p). Gli enunciati sugli
 * insiemi del capitolo 14 quantificano solo lettere maiuscole, non
 * dichiarano nulla, non nominano elementi, e tra graffe conoscono solo
 * \emptyset. Usa il lettore di token del parser, e lascia il suo stato da
 * reimpostare. */
static int uses_elements(const char *formula) {
    int found = 0;
    syntax_error = NULL;
    cursor = formula;
    int named = 0;
    for (next_token(); token.kind != T_END && !found; ) {
        int quantifier = is_command("forall") || is_command("exists"), element = token.kind == T_LETTER && islower(token.ch);
        int braces = is_char(ESCAPED + '{'), family = named && is_command("subseteq");

        /* 17v. L'unione di una famiglia di parti, un'appartenenza negata, una
         * lettera contenuta in \mathcal{P}(S) (una famiglia di parti, F
         * \subseteq \mathcal{P}(S)): il capitolo 14 non ne ha, perché per lui
         * una lettera è un insieme di elementi e \mathcal{P}(S) no. named
         * dice se il token appena letto chiude un nome, F o F_{1}. */
        found = is_command("colon") || is_command("bigcup") || is_command("bigcap") || is_command("notin");
        named = token.kind == T_LETTER || is_char('}');
        /* Il nome va superato intero: in c_{12} \in S il token dopo c
         * e il pedice, ma quello dopo il nome e l'appartenenza. */
        if (element) { int index; abstract_name(&index); }
        else next_token();
        if (family && is_command("mathcal")) found = 1;
        if (quantifier && token.kind == T_LETTER && islower(token.ch)) found = 1;
        if (element && (is_command("in") || is_command("notin"))) found = 1;
        if (braces && (token.kind == T_OPEN || (token.kind == T_LETTER && islower(token.ch)))) found = 1;
    }
    syntax_error = NULL;
    return found;
}

/* Ritorna 1 se formula parla del numero di elementi di un insieme, |S|.
 * Nessun lettore conosce questa notazione, e nessuna regola la saprebbe
 * decidere: |\mathcal{P}(S)| = 2^n chiede di contare per induzione sul numero
 * degli elementi, e "un insieme infinito ha una parte numerabile" l'assioma
 * della scelta. Il verdetto deve dirlo, invece di riportare il simbolo su
 * cui un lettore si è fermato. L'equipotenza da sola, A \sim B, va al
 * capitolo 28 (17w, 28q).
 *
 * Una sbarra verticale è un numero di elementi quando la segue ciò che
 * indica un insieme: una graffa \{, \mathcal o \bigcup, e, se letters è 1,
 * una lettera maiuscola senza pedice (la convenzione di
 * uses_set_notation()). Il valore assoluto dei capitoli 9 e 18 ha dentro
 * un'espressione, che non comincia mai con le prime; in un enunciato con
 * \mathbb una maiuscola può essere un numero, e lì chi chiama passa
 * letters = 0. Usa il lettore di token del parser, e lascia il suo stato da
 * reimpostare. */
static int uses_cardinality(const char *formula, int letters) {
    int found = 0;
    syntax_error = NULL;
    cursor = formula;
    for (next_token(); token.kind != T_END && !found; ) {
        int bar = is_char('|') || token.kind == T_ABS_OPEN;
        next_token();
        if (!bar) continue;
        if (is_char(ESCAPED + '{') || is_command("mathcal") || is_command("bigcup") || is_command("bigcap")) found = 1;
        else if (letters && token.kind == T_LETTER && isupper(token.ch)) { next_token(); found = !is_char('_'); }
    }
    syntax_error = NULL;
    return found;
}

/* 17w. Ritorna 1 se formula scrive un'equipotenza, A \sim B. Usa il lettore
 * di token del parser, e lascia il suo stato da reimpostare. */
static int uses_equipotence(const char *formula) {
    int found = 0;
    syntax_error = NULL;
    cursor = formula;
    for (next_token(); token.kind != T_END && !found; next_token()) found = is_command("sim");
    syntax_error = NULL;
    return found;
}

/* Ritorna 1 se formula dichiara una relazione o un'applicazione tra le
 * parti di un insieme (17r): \colon \mathcal{P}(S), oppure \in
 * \mathcal{P}(S)^{2} o \in \mathcal{P}(S) \times \mathcal{P}(S), che si
 * scrivono solo nella regola di una relazione tra parti. \forall X \in
 * \mathcal{P}(S), senza il quadrato, è del capitolo 14 e non conta. Usa il
 * lettore di token del parser, e lascia il suo stato da reimpostare. */
static int uses_parts_relations(const char *formula) {
    int found = 0;
    syntax_error = NULL;
    cursor = formula;
    for (next_token(); token.kind != T_END && !found; ) {
        int colon = is_command("colon"), in = is_command("in");
        next_token();
        if (!is_command("mathcal") || (!colon && !in)) continue;
        if (colon) { found = 1; continue; }

        /* \in \mathcal{P}(L): dopo \mathcal, sette token, { P } ( L ); poi
         * il quadrato, o \times e un altro \mathcal. */
        for (int skip = 0; skip < 7 && token.kind != T_END; skip++) next_token();
        int square = is_char('^'), times = is_command("times");
        next_token();
        found = square || (times && is_command("mathcal"));
    }
    syntax_error = NULL;
    return found;
}

/* Ritorna 1 se in text c'è un segno di derivata di Leibniz, in un punto
 * qualsiasi (starts_with_derivative()). */
static int has_derivative_sign(const char *text) {
    for (const char *p = strchr(text, '\\'); p; p = strchr(p + 1, '\\'))
        if (starts_with_derivative(p)) return 1;
    return 0;
}

/* Prova a dimostrare l'enunciato scritto in formula.
 *
 * variable, has_base e base riguardano le dimostrazioni per induzione (vedi
 * prove_by_induction()) e sono ignorati per gli altri enunciati.
 *
 * I risultati di una chiamata precedente, comprese le stringhe del suo
 * verdetto, non sono più validi dopo questa. */
static Verdict prove_core(const char *formula, int variable, int has_base, long long base) {
    /* Il grafico dell'enunciato precedente non vale più. */
    if (figure) { pl_close(figure); figure = NULL; }

    /* Un enunciato lungo lo legge solo il linguaggio degli insiemi
     * qualsiasi (capitolo 28), che cresce con il problema e sorveglia la
     * pila (capitolo 2). Gli altri linguaggi contano su MAX_FORMULA, nei
     * loro depositi e nella profondità dei loro alberi: lo rifiutano, come
     * facevano quando era il lettore degli \item a fermarsi lì. Senza
     * questo rifiuto 6000 radici una dentro l'altra fermavano il programma. */
    const Verdict too_long = {UNSUPPORTED, variable, 0, 0, "enunciato troppo lungo", NULL, NULL, NULL, NULL, NULL};
    stack_guard = strlen(formula) >= MAX_FORMULA;

    /* \int in testa: un integrale (capitolo 30), qualunque cosa segua. */
    if (starts_with_integral(formula)) return stack_guard ? too_long : prove_integral(formula);

    /* Il numero di elementi di un insieme: nessun metodo del programma lo
     * tratta, e il verdetto lo dice (uses_cardinality()). L'equipotenza sì,
     * tra insiemi qualsiasi (17w, 28q); tra insiemi di numeri no. */
    if (uses_cardinality(formula, !strstr(formula, "\\mathbb")))
        return (Verdict){UNSUPPORTED, variable, 0, 0, "il numero di elementi di un insieme, |S|, non è trattato: contare chiede l'induzione sul numero "
                         "degli elementi, che il capitolo 28 non fa, e dire infinito un insieme chiede, per le sue parti numerabili, l'assioma della scelta",
                         NULL, NULL, NULL, NULL, NULL};
    if (uses_equipotence(formula)) {
        if (strstr(formula, "\\mathbb"))
            return (Verdict){UNSUPPORTED, variable, 0, 0, "l'equipotenza è trattata solo tra insiemi qualsiasi, non con un insieme di numeri", NULL, NULL, NULL, NULL, NULL};
        /* Un esponente che il lettore non sa leggere, S^{T \cup V}, è il
         * motivo vero anche quando il lettore si ferma prima. */
        int bad_exponent = equipotence_bad_exponent(formula);
        Verdict verdict = prove_abstract(formula);
        if (verdict.outcome == UNSUPPORTED && bad_exponent) verdict.reason = equipotence_exponent_reason;
        return verdict;
    }
    if (strstr(formula, "\\mathbb")) return stack_guard ? too_long : prove_quantified(formula);

    /* Un enunciato lungo, da qui in poi, è del capitolo 28 o di nessuno.
     * Uno sulle relazioni tra parti che il capitolo 28 non legge sarebbe
     * del capitolo 15 (17r), che gli enunciati lunghi non li legge: il
     * motivo è quello, non l'errore di un lettore a cui non era destinato. */
    if (stack_guard) {
        int parts = uses_parts_relations(formula);
        if (!parts && !uses_elements(formula)) return too_long;
        Verdict verdict = prove_abstract(formula);
        return parts && verdict.outcome == UNSUPPORTED ? too_long : verdict;
    }

    /* Il segno di derivata in testa: l'enunciato è del capitolo 27, anche
     * quando il capitolo 27 non lo sa leggere. Non prosegue come algebra,
     * perché come algebra \frac{d}{dx} sarebbe la frazione 1/x (vedi
     * starts_with_derivative()); il motivo detto è quello del lettore. */
    if (starts_with_derivative(formula)) {
        Verdict verdict = prove_derivative(formula, variable, has_base, base);
        if (verdict.reason == NOT_A_DERIVATIVE && syntax_error) verdict.reason = syntax_error;
        return verdict;
    }
    /* \lim in testa, anche dopo \nexists: un enunciato sui limiti, del
     * capitolo 29. */
    if (starts_with_limit(formula)) return prove_limit(formula);

    /* Un segno di derivata dentro un'espressione lo espandono (27j) solo
     * gli enunciati con quantificatori, sui numeri reali, e quelli del
     * capitolo 13 e del 25. Negli altri resta un segno che nessuno calcola,
     * e non va letto come altro. */
    if (has_derivative_sign(formula) && (uses_elements(formula) || uses_set_notation(formula) || strstr(formula, "\\implies")))
        return (Verdict){UNSUPPORTED, variable, 0, 0, "il segno di derivata non ha senso in un enunciato su insiemi o su una successione definita per ricorrenza", NULL, NULL, NULL, NULL, NULL};
    /* Una relazione tra parti che il capitolo 15 non sa decidere (troppi
     * insiemi, o una scrittura che 17r non legge) può ancora essere un
     * enunciato del capitolo 28, con \mathcal{P}(S) come insieme di oggetti
     * (17v): se lì non si legge nemmeno, il motivo resta quello di 17r. */
    if (uses_parts_relations(formula)) {
        Verdict verdict = prove_parts(formula);
        if (verdict.outcome != UNSUPPORTED) return verdict;
        Verdict objects = prove_abstract(formula);
        return objects.outcome != UNSUPPORTED ? objects : prove_parts(formula);
    }
    if (uses_elements(formula)) return prove_abstract(formula);
    if (uses_set_notation(formula)) return prove_sets(formula);
    if (strstr(formula, "\\implies")) return prove_sequence(formula, variable, has_base, base);

    /* Un'uguaglianza al capitolo 13; ciò che quello rifiuta perché non è
     * un'uguaglianza, al capitolo 25. */
    Verdict verdict = prove_by_induction(formula, variable, has_base, base);
    return verdict.reason == NOT_AN_EQUALITY ? prove_inequality(formula, variable, has_base, base) : verdict;
}

/* Scrive su out il verdetto in una riga, senza a capo. */
static void verdict_print(FILE *out, const Verdict *verdict) {
    switch (verdict->outcome) {
    case PROVED:
        if (verdict->variable) fprintf(out, "DIMOSTRATO per induzione su %c >= %lld", verdict->variable, verdict->base);
        else fprintf(out, "DIMOSTRATO %s", verdict->method);
        if (verdict->note) fprintf(out, " (%s)", verdict->note);

        /* Il certificato: c'è, oppure manca, e se si sa perché lo si dice. */
        if (!verdict->certificate) {
            fprintf(out, verdict->reason ? "; senza certificato (%s)" : "; senza certificato", verdict->reason);
            break;
        }

        /* Che cosa copre. Per un enunciato sugli insiemi tutto: il
         * verificatore lo ha deciso da capo. Per un'induzione l'uguaglianza
         * dove i due membri sono definiti, e con la voce "defined" anche il
         * fatto che lo siano per ogni n, nel punto che il certificato indica
         * se ci sono parametri. */
        const char *point = strstr(verdict->certificate, "\ndefined");
        if (!verdict->variable) fprintf(out, "; certificato verificato");
        else if (!point) fprintf(out, "; certificato verificato: uguali dove sono definiti");
        else if (point[8] == '\n') fprintf(out, "; certificato verificato: definiti e uguali per ogni %c", verdict->variable);
        else fprintf(out, "; certificato verificato: uguali dove sono definiti, e definiti per ogni %c con i parametri del certificato", verdict->variable);
        if (strstr(verdict->certificate, "\ngeneric ")) fprintf(out, ", con un'ipotesi in più sui parametri");
        break;
    case REFUTED:
        if (verdict->variable) fprintf(out, "FALSO: non vale per %c = %lld", verdict->variable, verdict->witness);
        else if (verdict->detail) fprintf(out, "FALSO: controesempio %s", verdict->detail);
        else fprintf(out, "FALSO: è dimostrata la sua negazione");
        if (verdict->note) fprintf(out, " (%s)", verdict->note);

        /* Il controesempio di un enunciato su insiemi qualsiasi è anche un
         * certificato (28f), che il verificatore ha ricalcolato; quello
         * della tabella dei segni lo è la tabella (18p-15), che può anche
         * mancare, e allora si dice perché. */
        if (verdict->certificate) fprintf(out, "; certificato verificato");
        else if (verdict->reason) fprintf(out, "; senza certificato (%s)", verdict->reason);
        break;
    case NOT_PROVED:
        fprintf(out, "NON DIMOSTRATO: %s", verdict->reason);
        break;
    case UNSUPPORTED:
        fprintf(out, "NON SUPPORTATO: %s", verdict->reason);
        break;
    case SOLVED:
        /* Il certificato prima dei due punti: dopo vengono le soluzioni, e
         * chi le rilegge (tools/fuzz/) le cerca subito dopo il primo ": ". */
        fprintf(out, "RISOLTO %s", verdict->method);
        if (verdict->certificate) fprintf(out, ", certificato verificato");
        else if (verdict->reason) fprintf(out, ", senza certificato (%s)", verdict->reason);
        fprintf(out, ": %s", verdict->detail);
        if (verdict->note) fprintf(out, " (%s)", verdict->note);
        break;
    }
}

/* Punto d'ingresso protetto: una pila o un vettore cresciuti solo in parte
 * rendono inutilizzabile tutto il tentativo, anche se una strada interna
 * ha cancellato failure per provarne un'altra. Ogni chiamata riparte dai
 * contatori inizializzati dai metodi; le capacita allocate si riusano. */
static Verdict prove(const char *formula, int variable, int has_base, long long base) {
    /* Anche il conto delle catene riparte: prima che il lettore lo azzeri
     * da sé, i primi token dell'enunciato sono già passati per la guardia,
     * e il conto dell'enunciato precedente lo faceva rifiutare. */
    work_allocation_failed = stack_exhausted = 0;
    stack_chain_levels = 0;
    Verdict verdict = prove_core(formula, variable, has_base, base);
    stack_guard = 0;

    /* La pila finita (capitolo 2) viene dopo la memoria: è la causa più
     * precisa, e i lettori fermati a metà possono aver detto altro. */
    if (work_allocation_failed || stack_exhausted) {
        verdict.outcome = NOT_PROVED;
        verdict.reason = stack_exhausted ? STACK_EXHAUSTED : OUT_OF_MEMORY;
        verdict.proof = verdict.certificate = verdict.detail = NULL;
    }
    return verdict;
}

/* Dimostra l'enunciato contenuto nel testo [item, end) di un \item. */
static Verdict prove_item(const char *item, const char *end) {
    Item statement;
    const char *problem = read_item(item, end, &statement);
    if (problem) return (Verdict){problem==OUT_OF_MEMORY?NOT_PROVED:UNSUPPORTED, 'n', 0, 0, problem, NULL, NULL, NULL, NULL, NULL};
    Verdict verdict = prove(statement.formula, statement.variable, statement.has_base, statement.base);

    /* Una condizione scritta dopo la formula restringe i casi di cui parla
     * l'enunciato: "per ogni n pari", "con 0 < x < 1". Se il programma non
     * l'ha letta, una dimostrazione resta valida, perché copre anche quei
     * casi; un controesempio invece potrebbe essere proprio uno dei casi
     * esclusi, quindi non basta a dire FALSO. Senza questa cautela la somma
     * dei (-1)^k "per ogni n pari" risultava falsa per n = 1. */
    if (statement.conditional && verdict.outcome == REFUTED) {
        const char *reason = "in generale non vale, ma dopo la formula c'è una condizione che il programma non sa leggere";
        return (Verdict){NOT_PROVED, verdict.variable, 0, 0, reason, NULL, NULL, NULL, NULL, NULL};
    }

    /* Un inciso letto come commento non ferma un FALSO, ma chi legge il
     * verdetto deve sapere che c'era e che non è stato considerato. */
    if (statement.remark && verdict.outcome == REFUTED) verdict.note = "ignorato un commento tra parentesi dopo la formula";
    return verdict;
}

/* Il capitolo 22, la scrittura del documento finale, sta in output.c: il
 * documento LaTeX con enunciati, dimostrazioni, soluzioni e grafici, e la sua
 * compilazione in PDF. Va incluso qui, dopo il verdetto che riporta e prima
 * di chi lo chiama. */
#include "output.c"

/* =============================================================================
 * 23. MAIN
 * ============================================================================
 *
 * Modi d'uso:
 *
 *     mathresearcher FILE.tex ...                  dimostra o risolve ogni enunciato dei file
 *     mathresearcher --proofs OUT.pdf FILE.tex ... scrive anche il documento con le
 *                                                  dimostrazioni, le soluzioni e i grafici:
 *                                                  in LaTeX (OUT.tex, con i grafici in
 *                                                  OUT-plots.pdf) e compilato in PDF
 *     mathresearcher --certificates OUT FILE.tex ...
 *                                                  scrive anche i certificati verificati,
 *                                                  da far ricontrollare a checker
 *     mathresearcher                               legge un enunciato da stdin
 *
 * --model-work N e --model-memory BYTES regolano i budget della ricerca SAT
 * (20.000.000 operazioni e 128 MiB di default), non un massimo di elementi.
 * --model-steps N regola gli elementi che i quantificatori provano
 * ricalcolando un enunciato sui modelli (40.000.000 di default): un modello
 * che non si riesce a ricalcolare non è un controesempio, e il verdetto lo dice.
 * --stack-budget BYTES regola la pila concessa agli alberi di un enunciato
 * lungo (4 MiB di default, per una pila di 8 MB): oltre, l'esito è "pila di
 * lavoro esaurita".
 * --verification-work N regola le visite del verificatore numerico
 * (20.000.000 di default): una verifica interrotta non conferma nulla.
 * --saturation-work N e --saturation-memory BYTES regolano le visite e la
 * memoria della ricerca per clausole (2.000.000 e 128 MiB di default).
 * Tutte le opzioni si possono dare insieme. Il codice di uscita è 0 se tutti
 * gli enunciati sono stati dimostrati o risolti, 1 altrimenti.
 */

/* Conteggio dei verdetti su un file. */
typedef struct {
    int total;        /* \item trovati */
    int proved;
    int certified;    /* tra i dimostrati, quelli con il certificato verificato */
    int refuted;
    int not_proved;
    int unsupported;
    int solved;       /* insiemi di soluzioni trovati */
} Report;

/* Dimostra tutti gli enunciati del file path. Riempie *report con i conteggi
 * e, se out non è NULL, vi scrive una riga per enunciato. Se document non è
 * NULL vi scrive, come elenco, ogni enunciato con la sua dimostrazione e il
 * suo grafico; se certificates non è NULL vi scrive i certificati
 * verificati, uno dopo l'altro. Ritorna 0 se il file non si può leggere, 1
 * altrimenti. */
static int prove_file(const char *path, Report *report, FILE *out, Document *document, FILE *certificates) {
    memset(report, 0, sizeof *report);
    char *text = read_file(path);
    if (!text) return 0;

    if (document) document_list(document, 1);
    const char *position = text, *item, *end;
    while (next_item(&position, &item, &end)) {
        Verdict verdict = prove_item(item, end);
        report->total++;
        switch (verdict.outcome) {
        case PROVED:      report->proved++; break;
        case REFUTED:     report->refuted++; break;
        case NOT_PROVED:  report->not_proved++; break;
        case UNSUPPORTED: report->unsupported++; break;
        case SOLVED:      report->solved++; break;
        }
        if (verdict.certificate) {
            if (verdict.outcome == PROVED) report->certified++;
            if (certificates) fprintf(certificates, "%s\n", verdict.certificate);
        }
        if (out) {
            fprintf(out, "%4d. ", report->total);
            verdict_print(out, &verdict);
            fputc('\n', out);
        }

        /* Nel documento l'enunciato va com'è scritto nel file: lo si rilegge
         * dal testo, perché prove_item() ne ritorna solo il verdetto. */
        if (document) {
            Item statement;
            const char *unreadable = read_item(item, end, &statement);
            document_item(document, unreadable ? NULL : statement.formula, &verdict, figure);
        }
    }
    if (document) document_list(document, 0);
    free(text);
    return 1;
}

/* Legge un budget decimale positivo senza conversioni con trabocco. */
static int read_model_budget(const char *text, unsigned long long *value) {
    unsigned long long n = 0;
    if (!*text) return 0;
    for (; *text; text++) {
        if (*text < '0' || *text > '9' || n > (ULLONG_MAX - (unsigned)(*text - '0')) / 10) return 0;
        n = 10 * n + (unsigned)(*text - '0');
    }
    *value = n;
    return n != 0;
}

/* Legge una riga completa da stream in memoria posseduta dal chiamante,
 * da liberare dopo l'uso. Non tronca l'input a un buffer numerico interno.
 * NULL indica EOF prima della riga oppure errore di risorse in failure. */
static char *read_input_line(FILE *stream) {
    char *line=NULL;size_t length=0,capacity=0;int ch;
    while ((ch=fgetc(stream))!=EOF && ch!='\n') {
        if (length>(size_t)-1-2 || !work_reserve((void **)&line,&capacity,length+2,1)) {
            free(line);fail(OUT_OF_MEMORY);return NULL;
        }
        line[length++]=(char)ch;
    }
    /* Un errore dello stream non e la fine di una formula: il prefisso gia
     * letto non deve diventare un enunciato diverso da quello ricevuto. */
    if (ferror(stream)) { free(line);fail("errore durante la lettura dell'enunciato");return NULL; }
    if (ch==EOF && !length) { free(line);return NULL; }
    if (!work_reserve((void **)&line,&capacity,length+1,1)) { free(line);return NULL; }
    line[length]=0;return line;
}

int main(int argc, char **argv) {
    engine_init();

    /* Senza argomenti: un solo enunciato da stdin, con la sua dimostrazione. */
    if (argc < 2) {
        printf("Enunciato in LaTeX: ");
        char *line=read_input_line(stdin);
        if (!line) { if (failure) fprintf(stderr,"ERRORE: %s\n",failure); return 1; }
        Verdict verdict = prove(line, 'n', 0, 0);
        verdict_print(stdout, &verdict);
        putchar('\n');
        if (verdict.proof) printf("\n%s\n", verdict.proof);
        free(line);
        return verdict.outcome == PROVED || verdict.outcome == SOLVED ? 0 : 1;
    }

    /* Le opzioni, prima dei file.
     *
     * --proofs: il documento finale (capitolo 22). Chiederlo è anche ciò che
     * fa costruire i grafici: senza un documento non servono.
     *
     * --certificates: il file in cui scrivere i certificati. */
    FILE *certificates = NULL;
    Document document;
    int first = 1, documented = 0;
    for (; first + 1 < argc && strncmp(argv[first], "--", 2) == 0; first += 2) {
        if (strcmp(argv[first], "--model-work") == 0 || strcmp(argv[first], "--model-memory") == 0 ||
            strcmp(argv[first], "--stack-budget") == 0 || strcmp(argv[first], "--model-steps") == 0 || strcmp(argv[first], "--verification-work") == 0 || strcmp(argv[first], "--saturation-work") == 0 ||
            strcmp(argv[first], "--saturation-memory") == 0) {
            unsigned long long budget;
            int stack = strcmp(argv[first], "--stack-budget") == 0;
            int memory = stack || strcmp(argv[first], "--model-memory") == 0 || strcmp(argv[first], "--saturation-memory") == 0;
            int steps = strcmp(argv[first], "--model-steps") == 0;
            if (!read_model_budget(argv[first + 1], &budget) || (memory && budget > (size_t)-1) || (steps && budget >= LLONG_MAX)) {
                printf("ERRORE: budget positivo non rappresentabile: %s\n", argv[first + 1]); return 1;
            }
            if (stack) stack_budget = (size_t)budget;
            else if (strcmp(argv[first], "--saturation-memory") == 0) saturation_memory_limit = (size_t)budget;
            else if (strcmp(argv[first], "--saturation-work") == 0) saturation_work_limit = budget;
            else if (memory) model_memory_limit = (size_t)budget;
            else if (steps) model_step_limit = (long long)budget;
            else if (strcmp(argv[first], "--verification-work") == 0) verification_work_limit = budget;
            else model_work_limit = budget;
            continue;
        }
        if (strcmp(argv[first], "--certificates") == 0 && !certificates) {
            certificates = fopen(argv[first + 1], "w");
            if (!certificates) { printf("ERRORE: impossibile scrivere %s\n", argv[first + 1]); return 1; }
            continue;
        }
        if (strcmp(argv[first], "--proofs") != 0 || documented) { printf("ERRORE: opzione sconosciuta o ripetuta: %s\n", argv[first]); return 1; }
        const char *problem = document_open(&document, argv[first + 1]);
        if (problem) { printf("ERRORE: %s: %s\n", problem, argv[first + 1]); return 1; }
        documented = figures_wanted = 1;
    }

    /* Un file per argomento. */
    int all_proved = 1;
    for (int i = first; i < argc; i++) {
        Report report;
        printf("%s\n", argv[i]);
        if (documented) document_section(&document, argv[i]);
        if (!prove_file(argv[i], &report, stdout, documented ? &document : NULL, certificates)) {
            printf("ERRORE: impossibile leggere il file\n");
            all_proved = 0;
            continue;
        }
        printf("Riepilogo: %d enunciati, %d dimostrati (%d con certificato verificato), %d falsi, %d non dimostrati, %d non supportati",
               report.total, report.proved, report.certified, report.refuted, report.not_proved, report.unsupported);

        /* Gli insiemi di soluzioni si contano solo se ce ne sono: così la
         * riga di un file di soli enunciati resta quella di sempre. */
        if (report.solved) printf(", %d risolti", report.solved);
        printf(".\n");
        if (report.proved + report.solved != report.total) all_proved = 0;
    }
    if (unjustified_steps)
        printf("ATTENZIONE: %d passi di dimostrazione (formule rilette, o certificati respinti dal verificatore) "
               "non hanno superato il controllo indipendente e sono stati scartati\n", unjustified_steps);
    if (certificates) fclose(certificates);
    if (documented) {
        const char *problem = document_close(&document);
        if (problem) printf("ERRORE: %s\n", problem);
    }
    if (figure) pl_close(figure);
    return all_proved ? 0 : 1;
}
